export const entries = [{"id":"a","latin":"ā","headword":"ā","letter":"a","pos":"preposition; interjection","posGroup":"preposition","english":"(prp. + abl.) from, of, since, by; from, away from; by (+ ablative); ah!","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ab","latin":"ab","headword":"ab","letter":"a","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) from, by","forms":["ab"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, prius quam eorum clandestina consilia efferantur, ut Caesar {{ab}} exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ab / a","latin":"ab / ā","headword":"ab / ā","letter":"a","pos":"preposition","posGroup":"preposition","english":"from, away from (+ abl.); from; by (with abl.)","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"abactus","latin":"abactus, abacta, abactum","headword":"abactus","letter":"a","pos":"adjective","posGroup":"adjective","english":"driven away/off/back; forced to resign (office); restrained by; passed (night)","forms":["abāctae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde, cum {{abāctae}} bovēs quaedam relictās dēsīderantēs mūgīrent, bovēs in spēluncā inclūsae vōcem reddidērunt, quā audītā Hercules revertit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abalienare","latin":"(abaliēnō) abaliēnāre","headword":"abaliēnāre","letter":"a","pos":"","posGroup":"other","english":"separate, alienate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abalieno","latin":"abalieno, abalienare, abalienavi, abalienatus","headword":"abalieno","letter":"a","pos":"verb","posGroup":"verb","english":"make alien; separate, abstract; alienate, estrange, make disaffected","forms":["abaliēnāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum Perseus omnium ab sē {{abaliēnāvit}} animōs: prō sē quisque transīre ad Rōmānōs, fugaeque cōnsilium capere rēgem sōlum prope relictum coēgērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abbas","latin":"abbas, abbatis","headword":"abbas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"abbot; head of an ecclesiastical community; father; any respected monk (early)","forms":["abbātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dīcēbant ergō Iūdaeī:\"S {{abbātum}} est: nōn licet tibi tollere grabātum tuum.\"Respondit iīs:\"Quī mē sānum fēcit, mihi dīxit: ' Tolle grabātum tuum et ambulā'.\"Proptereā persequēbantur IUdaeī Iēsum, quia haec faciēbat S abbātō, et quaerēbant eum ut interficerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abdere","latin":"(abdō) abdere, -didisse, -ditum","headword":"abdere","letter":"a","pos":"verb","posGroup":"verb","english":"hide; to hide, conceal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"abdico","latin":"abdico, abdicare, abdicavi, abdicatus","headword":"abdico","letter":"a","pos":"verb","posGroup":"verb","english":"resign, abdicate; abolish; disinherit; renounce, reject, expel, disapprove of","forms":["abdicātō","abdicāvit"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur, perlēctīs litterīs, cum prius omnēs signa sua cognōvissent, senātus dēcernit utī abdicātō magistrātū Lentulus itemque cēterī in līberīs cūstōdiīs habeantur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"abditum","latin":"abditum, abditi","headword":"abditum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"hidden/secret/out of the way place, lair, (in) secret","forms":["abditum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec ūlla deinde impudīca Lūcrētiae exemplō vīvet!' Cultrum, quem sub veste {{abditum}} habēbat, eum in corde dēfīgit, prōlāpsaque in vulnus moribunda cecidit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abditus","latin":"abditus, -a, -um","headword":"abditus","letter":"a","pos":"adjective","posGroup":"adjective","english":"hidden, remote","forms":["abdita","abditam","abditas","abditī","abditus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postero die equitatu ex castris educto, omnem eam planitiem quam in longitudinem tria milia passuum patere demonstravimus complent, pedestresque copias paulum ab eo loco {{abditas}} in locis superioribus constituunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abdo","latin":"abdo, abdere, abdidi, abditus","headword":"abdo","letter":"a","pos":"verb","posGroup":"verb","english":"remove, put away, set aside; depart, go away; hide, keep secret, conceal","forms":["abdere","abdiderat","abdiderunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in artiores silvas {{abdiderunt}}, copias omnes in loco edito atque aperto instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abducere","latin":"(abdūcō) abdūcere, abdūxisse, abductum","headword":"abdūcere","letter":"a","pos":"","posGroup":"other","english":"lead away, carry off","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"abduco","latin":"abduco, abducere, abduxi, abductus","headword":"abduco","letter":"a","pos":"verb","posGroup":"verb","english":"lead away, carry off; detach, attract away, entice, seduce, charm; withdraw","forms":["abdūcant","abdūcat","abdūcēbant","abdūcēbantur","abdūcere","abdūcerent","abdūceret","abdūcit","abdūcite","abductī","abductō","abductōs","abductus","abdūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Orbum mē līberīs fēcistis: Iōsēphus mortuus est; Simeon retentus est in Aegyptō; Beniamīnum vultis {{abdūcere}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abeo","latin":"abeo, abire, abivi(ii), abitus","headword":"abeo","letter":"a","pos":"verb","posGroup":"verb","english":"depart, go away; go off, go forth; pass away, die, disappear; be changed","forms":["abeam","abeās","abeō","abeunt","abeuntem","abeuntēs","abeuntibus","abeuntis","abī","abībis","abībit","abībō","abiēns","abīre","abīrent","abīs","abit","abite","abitū","abitum","abitūrōs","abitūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Proinde {{abite}}, dum est facultas, vosque ad legionem recipite.' Ita pugnans post paulum concidit ac suis saluti fuit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aberrare","latin":"(aberrō) aberrāre, aberrāvisse, aberrātum","headword":"aberrāre","letter":"a","pos":"","posGroup":"other","english":"wander away, stray","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"aberro","latin":"aberro, aberrare, aberravi, aberratus","headword":"aberro","letter":"a","pos":"verb","posGroup":"verb","english":"stray, wander, deviate; go/be/do wrong; be unfaithful; escape; disagree (with)","forms":["aberrant","aberrante","aberrantem","aberrāverat","aberrāvit","aberrent"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ex omnibus tabulīs haec mē maximē dēlectat, etiam magis quam tabulā dē fīliō Solīs, quī currum patris regere cōnātus item dē summō caelō cecidit, quod ab orbe sōlis stultē {{aberrāvit}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"abest","latin":"abest","headword":"abest","letter":"a","pos":"verb","posGroup":"verb","english":"be absent; is absent, is away; is away, is absent","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"abhorreo","latin":"abhorreo, abhorrere, abhorrui, -","headword":"abhorreo","letter":"a","pos":"verb","posGroup":"verb","english":"abhor, shrink back; be averse to, shudder at; differ from; be inconsistent","forms":["abhorreat","abhorrēbat","abhorret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haedum bālantem audīvit Tobiās, et, veritus nē fūrtō ablātus esset, dīxit uxōrī: “Vidē nē iste clam alicui ēreptus sit: redde illum dominō suō; nefās enim est nōbīs ex raptō vīvere.” Adeō vir iūstus ab omnī improbitāte {{abhorrēbat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abhorrere","latin":"(abhorreō) abhorrēre, -uisse","headword":"abhorrēre","letter":"a","pos":"","posGroup":"other","english":"be inconsistent with","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abicere","latin":"(abiciō) abicere, abiēcisse, abiectum","headword":"abicere","letter":"a","pos":"verb","posGroup":"verb","english":"throw away; to throw away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"abicio","latin":"abiciō, -ere, -iēcī, -iectum","headword":"abiciō","letter":"a","pos":"verb","posGroup":"verb","english":"throw down, throw aside","forms":["abicere","abiciam","abiciet","abicit","abiēcerat","abiēcerīs","abiēcērunt","abiēcisset","abiēcit","abiectis","abiectum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi neminem in aequum locum sese demittere sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, {{abiectis}} armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abiectus","latin":"abjectus, abjecta -um, abjectior -or -us, abjectissimus -a -um","headword":"abjectus","letter":"a","pos":"adjective","posGroup":"adjective","english":"downcast, dejected; humble, low, common, mean; subservient; base, sordid, vile","forms":["abiectus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Cethēgus, quī paulō ante aliquid tamen dē gladiīs ac sīcīs quae apud ipsum erant dēprehēnsae respondisset dīxissetque sē semper bonōrum ferrāmentōrum studiōsum fuisse, recitātīs litterīs dēbilitātus atque {{abiectus}} cōnscientiā repente conticuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"abiegnus","latin":"abiegnus, abiegna, abiegnum","headword":"abiegnus","letter":"a","pos":"adjective","posGroup":"adjective","english":"made of fir, deal; wooden","forms":["abiēgnīs","abiēgnus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{abiēgnus}} -ā -um (« abiēs) 7 ē lignō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"abies","latin":"abies, abietis","headword":"abies","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"fir tree/wood; white/silver fir, spruce; thing of fir, ship, spear; sea weed","forms":["abiēs","abietis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"abiēgnus -ā -um (« {{abiēs}}) 7 ē lignō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"abigere","latin":"(abigō) abigere, -ēgisse, -āctum (< agere)","headword":"abigere","letter":"a","pos":"","posGroup":"other","english":"drive away","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abigo","latin":"abigo, abigere, abegi, abactus","headword":"abigo","letter":"a","pos":"verb","posGroup":"verb","english":"drive/send away/off; expel, repel; steal, plunder (cattle), rustle; seduce","forms":["Abigam","abigās","abigere","abigeret"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vidēs Philerônem causidicum: sī nôn didicisset, hodiē famem â labrîs nôn {{abigeret}}; etiam adversus Norbânum sē extendit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"abire","latin":"abīre","headword":"abīre","letter":"a","pos":"verb","posGroup":"verb","english":"to go away","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"abit","latin":"abit, abeunt","headword":"abit","letter":"a","pos":"verb","posGroup":"verb","english":"go away; goes away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"abiungo","latin":"abjungo, abjungere, abjunxi, abjunctus","headword":"abjungo","letter":"a","pos":"verb","posGroup":"verb","english":"unyoke, remove, separate; unharness; remove part, split; cut off from, detach","forms":["abiuncto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam converteret, ut ne metu quidem necessario faciendum existimabat, cum infamia atque indignitas rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod {{abiuncto}} Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abiuro","latin":"abjuro, abjurare, abjuravi, abjuratus","headword":"abjuro","letter":"a","pos":"verb","posGroup":"verb","english":"repudiate (obligation or duty); deny on oath (falsely); abjure; perjure","forms":["abiūrāverat"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed ea saepe antehāc fidem prōdiderat, crēditum {{abiūrāverat}}, caedis cōnscia fuerat, luxuriā atque inopiā praeceps abierat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ablativus","latin":"ablātīvus, -ī (cāsus)","headword":"ablātīvus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ablative","forms":["ablātīvī","ablātīvō","ablātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: 'Nōminātīvus, genetīvus, dativus, accūsātīvus, vocātīvus, {{ablātīvus}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"abluo","latin":"abluo, abluere, ablui, ablutus","headword":"abluo","letter":"a","pos":"verb","posGroup":"verb","english":"wash away/off/out, blot out, purify, wash, cleanse; dispel (infection); quench","forms":["abluendōs","ablueret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mox fīlia pharaōnis venit ad flūmen, ut {{ablueret}} corpus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abnego","latin":"abnego, abnegare, abnegavi, abnegatus","headword":"abnego","letter":"a","pos":"verb","posGroup":"verb","english":"deny; decline (to), refuse, reject; refuse to give, withhold (what is due)","forms":["abnegārent"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Affirmābant autem ‘hanc fuisse summam vel culpae suae vel errōris, quod essent solitī statō diē ante lūcem convenīre, carmenque Christō quasi deō dīcere sēcum invicem sēque sacrāmentō nōn in scelus aliquod obstringere, sed nē fūrta, nē latrōcinia, nē adulteria committerent, nē fidem fallerent, nē dēpositum appellātī {{abnegārent}}’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"abnuo","latin":"abnuo, abnuere, abnui, abnuitus","headword":"abnuo","letter":"a","pos":"verb","posGroup":"verb","english":"refuse, decline; deny (guilt); refuse by a sign, shake head; reject; rule out","forms":["abnuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Līberābis populum tuum ā servitūte Madianitārum.” Nōlēbat prīmō Gedeōn tantum onus suscipere, sed duplicī mīrāculō cōnfirmātus nōn {{abnuit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aboleo","latin":"aboleo, abolere, abolevi, abolitus","headword":"aboleo","letter":"a","pos":"verb","posGroup":"verb","english":"destroy, efface, obliterate; kill; banish, dispel; put end to. abolish, rescind","forms":["abolendō","abolēre","abolēvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At Cupīdō paulātim Sychaeum ē memoriā Dīdōnis {{abolēre}} incipit et animum eius vīvō amōre accendere temptat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abolere","latin":"(aboleō) abolēre, -lēvisse, -litum","headword":"abolēre","letter":"a","pos":"","posGroup":"other","english":"efface, obliterate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abolescere","latin":"(abolēscō) abolēscere,","headword":"abolēscere","letter":"a","pos":"","posGroup":"other","english":"decay, be forgotten abolēvisse, abolitum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aborigines","latin":"Aborīginēs, -um","headword":"Aborīginēs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"the first inhabitants of Italy","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"abripere","latin":"(abripiō) abripere (< rapere)","headword":"abripere","letter":"a","pos":"","posGroup":"other","english":"drag away, carry off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abripio","latin":"abripio, abripere, abripui, abreptus","headword":"abripio","letter":"a","pos":"verb","posGroup":"verb","english":"drag/snatch/carry/remove away by force; wash/blow away (storm); abduct, kidnap","forms":["abreptās","abreptum","abripere","abripiuntur","abripuit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"rē-vellere -lisse -vulsum - {{abripere}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"abrogare","latin":"(abrogō) abrogāre","headword":"abrogāre","letter":"a","pos":"verb","posGroup":"verb","english":"repeal, cancel; to repeal, take away (by vote)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"abrogo","latin":"abrogo, abrogare, abrogavi, abrogatus","headword":"abrogo","letter":"a","pos":"verb","posGroup":"verb","english":"abolish; repeal wholly, annul; remove, take away","forms":["abrogāret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīs ātrociōribusque — crēdō — aliīs memorātīs, incēnsam multitūdinem perpulit ut imperium rēgī {{abrogāret}} exsulēsque esse iubēret L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abrumpere","latin":"(abrumpō) abrumpere (< rumpō)","headword":"abrumpere","letter":"a","pos":"","posGroup":"other","english":"break off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abrumpo","latin":"abrumpo, abrumpere, abrupi, abruptus","headword":"abrumpo","letter":"a","pos":"verb","posGroup":"verb","english":"break (bonds); break off; tear asunder; cut through, sever; remove, separate","forms":["abrumpere","abrumpit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dabis, improbe, poenās!' Hīs dictīs medium sermōnem {{abrumpit}} et aegra ex oculīs aufugit, linquēns eum cūnctantem et multa dīcere parantem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abs","latin":"abs","headword":"abs","letter":"a","pos":"preposition","posGroup":"preposition","english":"by (agent), from (departure, cause, remote origin (time); after (reference)","forms":["abs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dominus imperat ut colōnus accēdat, deinde interrogat: “Cūr nōndum solvistī mercēdem quam quater iam {{abs}} tē poposcī?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"abs = a","latin":"abs = ā, ab","headword":"abs = ā","letter":"a","pos":"","posGroup":"other","english":"(beforete)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"abscedere","latin":"(abscēdō) abscēdere (< cēdere)","headword":"abscēdere","letter":"a","pos":"","posGroup":"other","english":"go away, withdraw","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abscedo","latin":"abscedo, abscedere, abscessi, abscessus","headword":"abscedo","letter":"a","pos":"verb","posGroup":"verb","english":"withdraw, depart, retire; go/pass off/away; desist; recede (coasts); slough","forms":["abscēdant","abscēdēbat","abscēderent","abscēdite","abscēdunt"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"MERCVRIVS: Concēdite atque {{abscēdite}} omnēs, dē viā dēcēdite!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"abscindo","latin":"abscindo, abscindere, abscidi, abscissus","headword":"abscindo","letter":"a","pos":"verb","posGroup":"verb","english":"tear (away/off) (clothing); cut off/away/short; part, break, divide, separate","forms":["abscissa"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"flāventisque {{abscissa}} comās 'prō Iuppiter! ībit","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"abscisus","latin":"abscisus, abscisa -um, abscisior -or -us, abscisissimus -a -um","headword":"abscisus","letter":"a","pos":"adjective","posGroup":"adjective","english":"steep, sheer, precipitous; abrupt, curt, brusque; restricted; cut off, severed","forms":["abscisis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Itaque truncis arborum aut admodum firmis ramis {{abscisis}} atque horum delibratis ac praeacutis cacuminibus perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"absconditum","latin":"absconditum, absconditi","headword":"absconditum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"hidden/secret/concealed place/thing; secret","forms":["absconditum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et ipsī nihil intellēxērunt, ē t verbum istum {{absconditum}}","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"absconditus","latin":"absconditus, abscondita, absconditum","headword":"absconditus","letter":"a","pos":"adjective","posGroup":"adjective","english":"hidden, secret, concealed; covert, disguised; abstruse, recondite","forms":["absconditīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Prīncipiō, ut Catilīna paucīs ante diēbus ērūpit ex urbe, cum sceleris suī sociōs huiusce nefāriī bellī ācerrimōs ducēs Rōmae relīquisset, semper vigilāvī et prōvīdī, Quirītēs, quemadmodum in tantīs ac tam {{absconditīs}} īnsidiīs salvī esse possēmus.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"abscondo","latin":"abscondo, abscondere, abscondi, absconditus","headword":"abscondo","letter":"a","pos":"verb","posGroup":"verb","english":"hide, conceal, secrete, \"shelter\"; leave behind; bury, engulf, swallow up; keep","forms":["abscondere","abscondī","abscondit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Adāmus, fugiēns cōnspectum Deī, sē {{abscondit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"absens","latin":"absēns","headword":"absēns","letter":"a","pos":"adjective","posGroup":"adjective","english":"(gen. absentis) absent","forms":["absēns","absente","absentem","absentī","absentis","absentium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant {{absente}} imperatore ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"absisto","latin":"absisto, absistere, absistiti, -","headword":"absisto","letter":"a","pos":"verb","posGroup":"verb","english":"withdraw from; desist, cease; leave off; depart, go away from; stand back","forms":["absistit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nec prius {{absistit}}, quam septem ingentia victor","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"absit","latin":"absit","headword":"absit","letter":"a","pos":"interjection","posGroup":"interjection","english":"\"god forbid\", \"let it be far from the hearts of the faithful\"","forms":["absit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris {{absit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"absolvere","latin":"(absolvō) absolvere (< solvere)","headword":"absolvere","letter":"a","pos":"","posGroup":"other","english":"free, acquit","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"absolvo","latin":"absolvo, absolvere, absolvi, absolutus","headword":"absolvo","letter":"a","pos":"verb","posGroup":"verb","english":"free (bonds), release; acquit; vote for/secure acquittal; pay off; sum up","forms":["absolūtum","absolvam","absolvitō","absolvō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"AMPHITRYO: Quaesō, absolvitō hinc mē extemplō, quandō satis dēlūserīs!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"absterreo","latin":"absterreo, absterrere, absterrui, absterritus","headword":"absterreo","letter":"a","pos":"verb","posGroup":"verb","english":"frighten off/away; drive away; deter, discourage; keep away/withhold from, den","forms":["absterruēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ab urbe oppugnandā Poenum {{absterruēre}} cōnspecta moenia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"absterrere","latin":"(absterreō) absterrēre (< terrēre)","headword":"absterrēre","letter":"a","pos":"","posGroup":"other","english":"scare away","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abstinens","latin":"abstinēns, (gen. -entis)","headword":"abstinēns","letter":"a","pos":"adjective","posGroup":"adjective","english":"self-restrained","forms":["abstinēns","abstinentissimum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Per septem diēs Dāvīd in magnō lūctū fuit, cibō {{abstinēns}} et ōrāns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abstinentia","latin":"abstinentia, abstinentiae","headword":"abstinentia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"abstinence; fasting; moderation, self control, restraint; integrity; parsimony","forms":["abstinentiā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam prō pudōre, prō abstinentiā, prō virtūte audācia, largītiō, avāritia vigēbant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"abstineo","latin":"abstineo, abstinere, abstinui, abstentus","headword":"abstineo","letter":"a","pos":"verb","posGroup":"verb","english":"withhold, keep away/clear; abstain, fast; refrain (from); avoid; keep hands of","forms":["Abstinē","abstineās","abstineat","abstinēbant","abstinent","abstinēre","abstinerent","abstinēret","abstinuērunt","abstinuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Matres familiae de muro vestem argentumque iactabant, et pectore nudo prominentes passis manibus obtestabantur Romanos ut sibi parcerent neu, sicut Avarici fecissent, ne a mulieribus quidem atque infantibus {{abstinerent}}; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abstinere","latin":"(abstineō) abstinēre, abstinuisse, abstentum","headword":"abstinēre","letter":"a","pos":"","posGroup":"other","english":"keep off","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"abstractus","latin":"abstractus, abstracta, abstractum","headword":"abstractus","letter":"a","pos":"adjective","posGroup":"adjective","english":"abstract (as opposed to concrete)","forms":["abstracta","abstractus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita omnia in duās partēs {{abstracta}} sunt, rēs pūblica, quae media fuerat, dīlacerāta.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abstrahere","latin":"(abstrahō) abstrahere (< trahere)","headword":"abstrahere","letter":"a","pos":"","posGroup":"other","english":"remove, separate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abstraho","latin":"abstraho, abstrahere, abstraxi, abstractus","headword":"abstraho","letter":"a","pos":"verb","posGroup":"verb","english":"drag away from, remove forcibly, abort; carry off to execution; split","forms":["abstrahere","abstrahet","abstrahi","abstrahunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius aestimare, liberos, coniuges in servitutem {{abstrahi}}, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"absum","latin":"absum, abesse, āfuī, āfutūrum","headword":"absum","letter":"a","pos":"verb","posGroup":"verb","english":"be absent, be away","forms":["aberant","aberat","aberit","abesse","abessent","abesset","abest","absim","absum","absunt","afuerunt","āfuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id silentio noctis conati non magna iactura suorum sese effecturos sperabant, propterea quod neque longe ab oppido castra Vercingetorigis {{aberant}} et palus, quae perpetua intercedebat, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"absumere","latin":"(absūmō) absūmere (< sūmere)","headword":"absūmere","letter":"a","pos":"","posGroup":"other","english":"consume, waste, destroy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"absumo","latin":"absumo, absumere, absumpsi, absumptus","headword":"absumo","letter":"a","pos":"verb","posGroup":"verb","english":"spend, waste, squander, use up; take up (time); consume; exhaust, wear out","forms":["absūmās","absūmere","absūmī","absūmpsit","absūmpta","absūmptās","absūmptīs","absumptūrōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Omnia {{absūmpta}} sunt dīluviō; arca autem sublevātā aquīs fluitābat in altō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"absurdus","latin":"absurdus, absurda, absurdum","headword":"absurdus","letter":"a","pos":"adjective","posGroup":"adjective","english":"out of tune, discordant; absurd, nonsensical, out of place; awkward, uncouth","forms":["absurdum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Pulchrum est bene facere reī pūblicae, etiam bene dīcere haud {{absurdum}} est; vel pāce vel bellō clārum fierī licet; et quī fēcēre et quī facta aliōrum scrīpsēre, multī laudantur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"abundans","latin":"abundans, abundantis (gen.), abundantior -or -us, abundantissimus -a -um","headword":"abundans","letter":"a","pos":"adjective","posGroup":"adjective","english":"abundant; overflowing; abounding, copious, in large measure; overdone; rich","forms":["abundantī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In dē- mentô levātum in tribūnal excelsum Mercurius rapiēbat. cornū abundantī et très Parcae aurea pēnsa torquentēs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"abundantia","latin":"abundantia, -ae","headword":"abundantia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"overflow, abundance","forms":["abundantia","abundantiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iōsēphus autem patrem et frātrēs suōs collocāvit in optimā parte Aegyptī, eīsque omnium rērum {{abundantiam}} suppeditāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"abundare","latin":"(abundō) abundāre","headword":"abundāre","letter":"a","pos":"","posGroup":"other","english":"overflow, be rich (in) (+ abl.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abunde","latin":"abundē","headword":"abundē","letter":"a","pos":"adverb","posGroup":"adverb","english":"amply, more than needed","forms":["abundē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Plūra dīcerem, Quirītēs, sī timidīs virtūtem verba adderent — nam strēnuīs abundē dictum putō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"abundo","latin":"abundo, abundare, abundavi, abundatus","headword":"abundo","letter":"a","pos":"verb","posGroup":"verb","english":"abound (in), have in large measure; overdo, exceed; overflow; be rich/numerous","forms":["abundant","abundāre","abundat","abundent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Id esse facile, quod equitatu ipsi {{abundent}} et quod anni tempore subleventur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"abuti","latin":"(abūtor) abūtī, -ūsum (+ abl.)","headword":"abūtī","letter":"a","pos":"","posGroup":"other","english":"use up, take advantage of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"abutor","latin":"abutor, abuti, abusus sum","headword":"abutor","letter":"a","pos":"verb","posGroup":"verb","english":"waste, squander; abuse; misuse; use up; spend; exhaust; misapply (word); curse","forms":["abūtere","abūtī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ut enim multī, cōnstituimus, parātī, sī tuō commodō fierī potest, abūtī tēcum hōc ōtiō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ac","latin":"ac","headword":"ac","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"and, as, than","forms":["ac"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus {{ac}} remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"academia","latin":"Academia, Academiae","headword":"Academia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"academy, university; gymnasium where Plato taught; school built by Cicero","forms":["Acadēmiae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Cum vēnissem Athēnās, sex mēnsēs cum Antiochō, veteris {{Acadēmiae}} nōbilissimō et prūdentissimō philosophō, fuī studiumque philosophiae numquam intermissum ā prīmāque adulēscentiā cultum et semper auctum hōc rūrsus summō auctōre et doctōre renovāvī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"acanthus","latin":"acanthus, acanthi","headword":"acanthus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"bear's-foot, (black) hellbore (plant); gum arabic tree/wood","forms":["acanthō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et circumtextum croceō vēlāmen acanthō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"accedere","latin":"(accēdō) accēdere, accessisse,  accessum","headword":"accēdere","letter":"a","pos":"","posGroup":"other","english":"approach","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"accedo","latin":"accedo, accedere, accessi, accessus","headword":"accedo","letter":"a","pos":"verb","posGroup":"verb","english":"come near, approach; agree with; be added to (w/ad or in + ACC); constitute","forms":["accēdam","Accēdant","accēdat","accēde","accēdēbant","Accēdēbat","accēdēns","accēdentēs","accedere","accēderent","accēderet","accēdit","accēdite","accedunt","accessē","accesserat","Accessēre","accesserit","accessērunt","accessimus","accessissent","accessisset","accessit","accessūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio ascensus recta regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum clivum {{accesserat}}, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accelero","latin":"accelero, accelerare, acceleravi, acceleratus","headword":"accelero","letter":"a","pos":"verb","posGroup":"verb","english":"speed up, quicken, hurry; make haste, act quickly, hasten; accelerate","forms":["accelerāret","Accelerat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Accelerat}} Caesar, ut proelio intersit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accendere","latin":"(accendō) accendere, accendisse, accēnsum","headword":"accendere","letter":"a","pos":"verb","posGroup":"verb","english":"light, enflame; to light, kindle","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"accendo","latin":"accendō, -ere, -cendī, -cēnsum","headword":"accendō","letter":"a","pos":"verb","posGroup":"verb","english":"kindle, set on fire","forms":["Accende","accendēbant","accendēbat","accenderat","accendere","accenderit","accendet","Accendis","accendit","accendite","accenditur","accensa","accēnsae","accēnsās","accēnsī","accensis","accēnsō","accēnsōs","accēnsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Gedeōn trecentōs virōs in trēs partēs dīvīsit, deditque illīs tubās et lagoenās, in quibus erant lampadēs {{accēnsae}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"accensus","latin":"accensus, accensi","headword":"accensus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"attendant/orderly; supernumerary soldier (usu. pl.) [~ velatus => replacements]","forms":["accēnsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Apollō tantō amōre ergā puerum {{accēnsus}} erat, ut eum in omnibus certāminibus vincere sineret, nē trīstitia afficerētur, sī forte victus esset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"accepta","latin":"accepta, acceptae","headword":"accepta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"allotment, portion of land assigned to one person","forms":["accepta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praestare visum est tamen omnes difficultates perpeti quam tanta contumelia {{accepta}} omnium suorum voluntates alienare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accepto","latin":"accepto, acceptare, acceptavi, acceptatus","headword":"accepto","letter":"a","pos":"verb","posGroup":"verb","english":"receive regularly, take (payment/food); be given (name); submit to; grasp idea","forms":["accepto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et maxime, quod ipse animo non defecerat tanto {{accepto}} incommodo neque se in occultum abdiderat et conspectum multitudinis fugerat; plusque animo providere et praesentire existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"acceptum","latin":"acceptum, accepti","headword":"acceptum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"receipts (vs. expenditures); favors; receipt side of account; written receipt","forms":["acceptum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Iūnō, quae cōnsilium eius intellēxerat, hanc vaccam ā maritō poposcit, quī, ut amōrem suum cēlāret, nihil aliud facere nisi eam uxōri dōnāre poterat. lūnō tamen adhūc verēns nē dōnum nūper {{acceptum}} ā maritō surriperētur, hanc vaccam Argō, pastōri et servō suō ēgregiō, cūstōdiendam dedit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"acceptus","latin":"acceptus, -a, -um","headword":"acceptus","letter":"a","pos":"adjective","posGroup":"adjective","english":"well-liked, popular","forms":["acceptae","acceptam","acceptās","acceptī","acceptis","acceptissima","acceptissimus","acceptius","acceptus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vercingetorix, tot continuis incommodis Vellaunoduni, Cenabi, Novioduni {{acceptis}}, suos ad concilium convocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accersere","latin":"(accersō) accersere, -īvisse, -ītum","headword":"accersere","letter":"a","pos":"","posGroup":"other","english":"send for, fetch","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"accersitus","latin":"accersitus, accersita, accersitum","headword":"accersitus","letter":"a","pos":"adjective","posGroup":"adjective","english":"brought from elsewhere, foreign; extraneous; self-inflicted (death); sent for","forms":["accersītus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque hōrum omnium scelerum improbissimum māchinātōrem, Cimbrum Gabīnium, statim ad mē nihildum suspicantem vocāvī, deinde item {{accersītus}} est L.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"accerso","latin":"accerso, accersere, accersivi, accersitus","headword":"accerso","letter":"a","pos":"verb","posGroup":"verb","english":"send for, summon; indict/accuse; fetch, import; invite; invoke; bring on oneself","forms":["accersere","accersī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque quotiēnscumque dîcit “Carpe!” eôdem verbô et [Dê Fortûnätä, dê dîvitiîs T rimalchiônis, dē collîbertîs] Nôn potuî amplius quicquam gustāre, sed conversus ad eum, ut quam plūrima exciperem, longē {{accersere}} täbulās coepî scîscitäxîque ‘quae esset mulier illa quae hūc atque “Uxor” inquit “Trīma1chiônis, ‘Fortūnāta’ appellättlr; quae nummôs modiô mëtîtur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"accessio","latin":"accessiō, -ōnis ( f.)","headword":"accessiō","letter":"a","pos":"","posGroup":"other","english":"addition, accessory","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"accessus","latin":"accessus, accessus","headword":"accessus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"approach, arrival; entry, admittance, audience; hostile approach/attack; onset","forms":["accessus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{accessus}} -üs n (€ ac-cēdere) — aditus cūra sit: accessüs molliet","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"accidere","latin":"(accidō) accidere, accīdisse","headword":"accidere","letter":"a","pos":"verb","posGroup":"verb","english":"happen, occur; to happen","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"accidit","latin":"accidit","headword":"accidit","letter":"a","pos":"verb","posGroup":"verb","english":"happens","forms":["accidit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum {{accidit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accido","latin":"accidō, -ere, -cidī","headword":"accidō","letter":"a","pos":"verb","posGroup":"verb","english":"fall down; happen","forms":["accidat","acciderant","acciderat","accidere","acciderent","accideret","acciderit","accidērunt","accidet","accidisse","accidisset","accīsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius aestimare, liberos, coniuges in servitutem abstrahi, ipsos interfici; quae sit necesse {{accidere}} victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accingere","latin":"(accingō) accingere (< cingere)","headword":"accingere","letter":"a","pos":"","posGroup":"other","english":"gird","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"accingo","latin":"accingo, accingere, accinxi, accinctus","headword":"accingo","letter":"a","pos":"verb","posGroup":"verb","english":"gird on or about, surround; equip, provide (with); get ready, prepare (for)","forms":["accingeris","accingier","accingunt","accīnxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Saūl ipse sua iuvenī arma voluit accommodāre: galeam capitī eius imposuit, lōrīcā pectus circumtēxit, latus gladiō {{accīnxit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"accio","latin":"accio, accire, accivi, accitus","headword":"accio","letter":"a","pos":"verb","posGroup":"verb","english":"send for, summon (forth), fetch; invite; (w/mortum) commit suicide","forms":["accītīs","accītō","accītū","accītum","accīvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"\"Sē nōn rem novam petere, quia duo iam peregrīnī Rōmae rēgnāvissent: et Tatium nōn ex peregrīnō sōlum sed ex hoste rēgem factum, et Numam ignārum urbis, nōn petentem, in rēgnum {{accītum}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"accipio","latin":"accipiō, -ere, accēpī, acceptum","headword":"accipiō","letter":"a","pos":"verb","posGroup":"verb","english":"receive, accept","forms":["accēperam","accēperat","accēpēre","accēperim","acceperint","accēperit","accēpērunt","accēpī","accēpimus","Accēpisse","accēpissent","accēpissēs","accepisset","accēpistī","accēpistis","accēpit","acceptūrum","accipe","accipere","acciperent","acciperet","acciperetur","accipī","accipiam","accipiāmus","accipiant","accipiat","accipiātis","accipiēbās","accipiēbat","accipienda","accipiendīs","accipiēns","accipiēs","accipiet","accipimus","accipiō","accipis","accipit","accipite","accipitur","accipiunt","accipiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postremo in acie praestare interfici quam non veterem belli gloriam libertatemque quam a maioribus {{acceperint}} reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accipit","latin":"accipit, accipiunt","headword":"accipit","letter":"a","pos":"verb","posGroup":"verb","english":"receive; receives, gets; receives","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"accipiter","latin":"accipiter, accipitris","headword":"accipiter","letter":"a","pos":"noun","posGroup":"noun","english":"hawk (any of several species); flying gurnard (fish)","forms":["accipiter","accipitrem","Accipitrī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{accipiter}} -trīs zī, avis fera Ōdimus accipitrem, quia","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"accire","latin":"(acciō) accīre, -īvisse, -ītum","headword":"accīre","letter":"a","pos":"","posGroup":"other","english":"summon, send for","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"acclamare","latin":"(acclāmō) acclāmāre","headword":"acclāmāre","letter":"a","pos":"","posGroup":"other","english":"shout, proclaim","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"acclamo","latin":"acclamo, acclamare, acclamavi, acclamatus","headword":"acclamo","letter":"a","pos":"verb","posGroup":"verb","english":"shout (at), cry out against, protest; shout approval, applaud","forms":["acclāmantibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quōrum agmen imperātor secūtus — prōsequentibus cūnctīs 'servātōrem' 'līberātōrem'que {{acclāmantibus}} — eādem quā vēnerat viā Elatēam rediit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"acclivis","latin":"acclivis, acclivis, acclive","headword":"acclivis","letter":"a","pos":"adjective","posGroup":"adjective","english":"rising, sloping/inclining upward, ascending, up hill; steep","forms":["acclivis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Collis erat leniter ab infimo {{acclivis}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"accolere","latin":"(accolō) accolere (< colere)","headword":"accolere","letter":"a","pos":"","posGroup":"other","english":"live near","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"accolo","latin":"accolo, accolere, accolui, accultus","headword":"accolo","letter":"a","pos":"verb","posGroup":"verb","english":"dwell/live near; be a neighbor to","forms":["accolīt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec est ūllus hebetior sēnsus in vōbīs; sīcut, ubi Nīlus ad illa quae Catadūpa nōminantur praecipitat ex altissimīs montibus, ea gēns quae illum locum {{accolīt}} propter magnitūdinem sonitūs sēnsū audiendī caret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"accommodare","latin":"(accomodō) accommodāre","headword":"accommodāre","letter":"a","pos":"","posGroup":"other","english":"fit, adapt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"accommodo","latin":"accommodo, accommodare, accommodavi, accommodatus","headword":"accommodo","letter":"a","pos":"verb","posGroup":"verb","english":"adapt, adjust to, fit, suit; apply to, fasten on; apply/devote oneself to","forms":["accommodābō","accommodāre","accommodat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Saūl ipse sua iuvenī arma voluit {{accommodāre}}: galeam capitī eius imposuit, lōrīcā pectus circumtēxit, latus gladiō accīnxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"accubare","latin":"(accubō) accubāre","headword":"accubāre","letter":"a","pos":"verb","posGroup":"verb","english":"recline at the table; to lie at table","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"accubo","latin":"accubo, accubare, accubui, accubitus","headword":"accubo","letter":"a","pos":"verb","posGroup":"verb","english":"lie near or by; recline at table","forms":["accubet","accubuērunt","accubuī","Accubuistī","accubuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Postquam dī {{accubuērunt}}, ānus mēnsam apposuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"accumbere","latin":"(accumbō) accumbere, accubuisse","headword":"accumbere","letter":"a","pos":"verb","posGroup":"verb","english":"recline at the table; to recline at table; to recline (at table)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"accumbo","latin":"accumbo, accumbere, accumbui, accumbitus","headword":"accumbo","letter":"a","pos":"verb","posGroup":"verb","english":"take a place/recline at the table; lie on (bed), lie at/prone, lie beside","forms":["accumbēbat","accumbentēs","accumbere","accumbit","accumbunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīī, in trīclīnium flōribus ōmātum ingressī et in lectīs recipere vestibus pulcherrimīs strātīs {{accumbentēs}}, laetē apud Tantalum cēnābant, quī eīs cibōs optimōs appōnēbat pōtiōnēsque, quae eīs numquam satis esse vidēbantur, in pōcula fundēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"accurate","latin":"accūrātē","headword":"accūrātē","letter":"a","pos":"adverb","posGroup":"adverb","english":"carefully","forms":["accūrātissimē","accūrātius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quārē cum et bellum sit ita necessārium ut neglegī nōn possit, ita magnum ut accūrātissimē sit administrandum, et cum eī imperātōrem praeficere possītis in quō sit eximia bellī scientia, singulāris virtūs, clārissima auctōritās, ēgregia fortūna, dubitātis, Quirītēs, quīn hoc tantum bonī, quod vōbīs ā dīs immortālibus oblātum et datum est, in rem pūblicam cōnservandam atque amplificandam cōnferātis?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"accurrit","latin":"accurrit, -unt","headword":"accurrit","letter":"a","pos":"verb","posGroup":"verb","english":"come running; runs up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"accurro","latin":"accurro, accurrere, accucurri, accursus","headword":"accurro","letter":"a","pos":"verb","posGroup":"verb","english":"run/hasten to (help); come/rush up (inanim subj.); charge, rush to attack","forms":["accurrēns","accurrentēs","accurrerat","accurrere","accurrerent","accurrērunt","accurrit","accurrō","accurrunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum ovēs ā pāstōre numerantur, vir īrātus {{accurrit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"accusat","latin":"accūsat","headword":"accūsat","letter":"a","pos":"verb","posGroup":"verb","english":"accuse; accuses, blames","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"accusativus","latin":"accūsātīvus, -ī(cāsus)","headword":"accūsātīvus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"accusative","forms":["accūsātīvī","accūsātīvō","accūsātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: 'Nōminātīvus, genetīvus, dativus, {{accūsātīvus}}, vocātīvus, ablātīvus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"accusator","latin":"accusator, accusatoris","headword":"accusator","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"accuser, prosecutor at trial; plaintiff; informer","forms":["accūsātor","accūsātōrēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed ferae Daniell pepercērunt, rēxque, mīrāculō commōtus, ipsōs {{accūsātōrēs}} leōnibus dēvorandōs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"accuso","latin":"accūsō, -āre, accūsāvī","headword":"accūsō","letter":"a","pos":"verb","posGroup":"verb","english":"accuse, blame","forms":["accūsābantur","accūsābat","accūsābit","accūsāns","accūsant","accūsantēs","accūsāre","accūsat","accūsātus","accūsāvit","ACCVSATVR"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dāvus, quī probus est servus, tacet neque Mēdum {{accūsat}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"acer","latin":"ācer, -cris, -cre","headword":"ācer","letter":"a","pos":"adjective","posGroup":"adjective","english":"keen, active, fierce; keen, eager; harsh, hard, rough, bitter","forms":["acer","ācerrimae","acerrime","ācerrimī","ācerrimōs","ācre","ācrem","ācrēs","ācrī","ācribus","ācrior","ācriōrēs","ācriōribus","ācris","acrius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum {{acerrime}} comminus pugnaretur, hostes loco et numero, nostri virtute confiderent, subito sunt Aedui visi ab latere.nostris aperto, quos Caesar ab dextra parte alio ascensu manus distinendae causa miserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"acerbe","latin":"acerbe, acerbius, acerbissime","headword":"acerbe","letter":"a","pos":"adverb","posGroup":"adverb","english":"stridently, with harsh sound; cruelly, harshly; with pain/severity; premature","forms":["acerbē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Roboāmus aequālium cōnsiliō ūsus, populō acerbē respondit, eiusque postulātiōnem reiēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"acerbitas","latin":"acerbitas, acerbitatis","headword":"acerbitas","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"harshness, severity; bitterness, sourness, ill feeling; anguish, hardship","forms":["acerbitāte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Antiochus dolōris {{acerbitāte}} victus tandem ad sānam mentem rediit: sē mortālem esse agnōvit, et recordātus malōrum, quibus IŪdaeōs afrēcerat, apertē cōnfessus est sē suōrum scelerum poenās luere, ac dēmum prōmīsit sē Ilidaēōs flōrentēs beātōsque facrurum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"acerbo","latin":"acerbo, acerbare, acerbavi, acerbatus","headword":"acerbo","letter":"a","pos":"verb","posGroup":"verb","english":"embitter; aggravate; make disagreeable; make worse","forms":["acerbō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Alcyonē autem, cum prīmum hoc nōvit, acerbō dolōre affectā, lacrimās per genās effūdit tōtōque vultū palluit et, postquam ter frūstrā prae tristitiāā cōnāta est loquī, tum dēmum “Heu, mē miseram!” inquit, “Nōn iam mē amās, ō Cēyx?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"acerbum","latin":"acerbum, acerbi","headword":"acerbum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"calamity, misfortune","forms":["acerbum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At Paulā vīnum gustāns 'Hoc vīnum' inquit 'nimis {{acerbum}} est: os mihi contrahitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"acerbus","latin":"acerbus, -a, -um","headword":"acerbus","letter":"a","pos":"adjective","posGroup":"adjective","english":"bitter; bitter, sharp","forms":["acerba","acerbam","acerbissimum","acerbius","acerbus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Haec si gravia aut {{acerba}} videantur, multo illa gravius aestimare, liberos, coniuges in servitutem abstrahi, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"acervus","latin":"acervus, -ī","headword":"acervus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"heap, pile","forms":["acervus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ad fidem deinde tam laetārum rērum effundī in vestibulō cūriae iussit ānulōs aureōs, quī tantus {{acervus}} fuit ut metientibus dīmidium suprā trēs modiōs explēvisse sint quīdam auctōrēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"acestes","latin":"Acestes, Acestis","headword":"Acestes","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Acestes; (Sicilian king of Trojan descent, host of Aeneas)","forms":["Acestēn","Acestēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Seu vōs Hesperiam magnam Sāturniaque arva\nsīve Erycīs fīnīs rēgemque optātis {{Acestēn}},\n[vōs] auxiliō tūtōs dīmittam opibusque iuvābō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"acetum","latin":"acetum, aceti","headword":"acetum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"vinegar, sour wine; tang of vinegar; sourness of disposition; sharpness of wit","forms":["acētum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prōfer quae necessāria sunt: salem, oleum Hispānum ad lucernās, {{acētum}} ācre, vīnum album et nigrum, ligna sicca, carbōnēs, secūrim, vāsa, catīna, caccabum, ōllam...!” [Servus, postquam omnia extulit:] “Quid aliud vīs?” [Iūlius:] “Haec tantum, puer: Vāde ad Gāium et dīc eī: ‘Venī!’ Inde lavēmus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"achaemenis","latin":"achaemenis, achaemenidis","headword":"achaemenis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"plant alleged to have magical properties","forms":["Achaemenidēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dīxit {{Achaemenidēs}}: \"iterum Polyphēmon et illōs\nadspiciam fluidōs hūmānō sanguine rīctūs,\nhāc mihi sī cārior domus est Īthacāque carīna,\nsī minus Aenēān veneror genitōre, nec umquam\nesse satis poterō, nōn sī dederō omnia, grātus.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"achaicus","latin":"Achāicus, -a, -um","headword":"Achāicus","letter":"a","pos":"adjective","posGroup":"adjective","english":"Achaean, of the Achaean League","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"achates","latin":"achates, achatae","headword":"achates","letter":"a","pos":"noun","posGroup":"noun","english":"agate","forms":["Achātē","Achātēn","Achātēs","Achātī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aenēās rapidum ad nāvīs praemittit {{Achātēn}},\n[ut] Ascanīō ferat haec, ipsumque ad moenia dūcat;\nomnis in Ascanīō cārī stat cūra parentis.\n[eum] Mūnera praetereā Īliacīs ērepta ruīnīs\nferre iubet. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"achilleos","latin":"achilleos, achillei","headword":"achilleos","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"medicinal plant (said to be discovered by Achilles); milfoil, yarrow","forms":["Achillēōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nē facite! utque meum nōn sit sine honōre sepulcrum, placet {{Achillēōs}} mactāta Polyxena mānēs!”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"achilles","latin":"Achilles, Achillis","headword":"Achilles","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Achilles, Greek hero; (other Greeks)","forms":["Achille","Achillem","Achillēs","Achillī","Achillīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tacente Quīntō, Syrā pergit: 'An cupis audīre tabulam dē {{Achille}}, duce Graecōrum, quī Hectorem, ducem Troiānum, interfēcit atque corpus eius mortuum post currum suum trāxit circum moenia urbis Trōiae?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"acia","latin":"acia, aciae","headword":"acia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"thread, yarn","forms":["aciā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hic mihi dîxit etiam ea quae oblîtus eram: ab aciā et acū mī omnia exposuit, intestînâs meās -üs m cēnāveram!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"acide","latin":"acide, acidius, acidissime","headword":"acide","letter":"a","pos":"adverb","posGroup":"adverb","english":"unpleasantly","forms":["Ācide"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ibi Galatēa, nymphārum omnium pulcherrima, quae ūna cum sorōribus Siciliae undās incolēbat, ab Ācide pāstōre amābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"acidus","latin":"acidus, acida -um, acidior -or -us, acidissimus -a -um","headword":"acidus","letter":"a","pos":"adjective","posGroup":"adjective","english":"acid/sour/bitter/tart; sour-smelling; soaked in vinegar; shrill; sharp-tongued","forms":["acidior"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Interim puer Alexandrînus, quī caldam ministrābat, lusciniās coepit imitärî, clāmante Trimalchiône subinde: Ecce alius lūdus: servus quī ad pedēs Habinnae sēdë- bat, iussus, crëdô, ā dominô suô, prôclämävit subitô Nūllus sonus umquam {{acidior}} percussit aurēs meâs, tunc prîmum mē etiam Vergilius offenderit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"acies","latin":"aciēs, -ēī","headword":"aciēs","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"line of battle; battle-line; battle line; keenness","forms":["acie","acieī","aciem","acies"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postremo in {{acie}} praestare interfici quam non veterem belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"acquiescere","latin":"(acquiēscō) acquiēscere, -ēvisse, -ētum","headword":"acquiēscere","letter":"a","pos":"","posGroup":"other","english":"go to rest; die","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"acquiesco","latin":"acquiesco, acquiescere, acquievi, acquietus","headword":"acquiesco","letter":"a","pos":"verb","posGroup":"verb","english":"lie with (w/cum), rest/relax; repose (death); acquiesce/assent/submit; subside","forms":["acquiēvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sīc vir fortissimus, multīs variīsque perfūnctus labōribus, annō {{acquiēvit}} septuāgēsimō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"acquirere","latin":"(acquīrō) acquīrere, -īvisse, -ītum","headword":"acquīrere","letter":"a","pos":"","posGroup":"other","english":"acquire, procure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"acquiro","latin":"acquiro, acquirere, acquisivi, acquisitus","headword":"acquiro","letter":"a","pos":"verb","posGroup":"verb","english":"acquire (goods/money/adherents), obtain, gain, get; add to stock; accrue","forms":["acquīrant","acquīrit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"nàscītūr exiguus, sed opēs {{acquīrit}} eundō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"acriter","latin":"acriter, acrius, acerrime","headword":"acriter","letter":"a","pos":"adverb","posGroup":"adverb","english":"sharply, vigilantly, fiercely; severely, steadfastly; keenly, accurately","forms":["Ācriter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ācriter pugnātum est utrimque, sed, Deō favente, victōria penes Davidem fuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"acro","latin":"acro, acronis","headword":"acro","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"extremity; member of the body; stem of a plant","forms":["acro"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"inquit “ad parentālia mea in- Îbat rēs ad surnmam nauseam, cum Trimalchiô, ēbrie- tâte turpissirnä gravis, novum {{acro}}ânna, cornicinēs, in trī- clînium iussit addücî; fultusque cervîcälibus multîs ex- tendit sē suprā torum extrēmum, et “Fingite mē” inquit “mortuum esse!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"acta","latin":"ācta, -ōrum (n. pl.)","headword":"ācta","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"deeds, actions; deeds, records","forms":["ācta","āctam","actīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is enim nautās suōs tam validōs esse crēdit ut nūlla alia nāvīs rēmīs sōlīs ācta nāvem suam cōnsequī possit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"actaeon","latin":"Actaeon, Actaeonis","headword":"Actaeon","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Actaeon; (hunter transformed into stag by Diana)","forms":["Actaeōn","Actaeonis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Currēns enim hūc et illūc fīliārum corpora complectēbātur et manibus rāmōs, in quibus membra claudēbantur, rumpere et frangere cōnābātur: at inde sanguis IovisfiiCmīne percussūs, in flūmen Ēridanum dē caelō cadit {{Actaeōn}} in Cucō nymphās cōnspicit effundēbātur tamquam ex vulnere: “Parce, precor, māter!” clāmābant, “Parce!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"actio","latin":"āctiō, -ōnis ( f.) (< agere)","headword":"āctiō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"action, delivery","forms":["āctiōnibus","actiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Gracchus, quōrum maiōrēs Pūnicō atque aliīs bellīs multum reī pūblicae addiderant, vindicāre plēbem in lībertātem et paucōrum scelera patefacere coepēre, nōbilitās noxia atque eō perculsa Gracchōrum āctiōnibus obviam ierat, et prīmō Tiberium, dein paucōs post annōs eādem ingredientem Gāium, tribūnum alterum, alterum triumvirum colōniīs dēdūcendīs, cum M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"activum","latin":"āctīvum, -ī (verbum)","headword":"āctīvum","letter":"a","pos":"","posGroup":"other","english":"active","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"activus","latin":"āctīvus","headword":"āctīvus","letter":"a","pos":"adjective","posGroup":"adjective","english":"active","forms":["Āctīva","āctīvī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Genera verbōrum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: 'Āctīva, passīva, neutra, dēpōnentia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"actor","latin":"āctor, -ōris (m.)","headword":"āctor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"pleader, advocate","forms":["āctōrem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Quibus nōn contentus Rhodum vēnī mēque ad eundem quem Rōmae audīveram Molōnem applicāvī, cum āctōrem in vērīs causīs scrīptōremque praestantem, tum in notandīs animadvertendīsque vitiīs et in īnstituendō docendōque prūdentissimum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"actuarius","latin":"actuarius, actuari(i)","headword":"actuarius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"short-hand writer, clerk, account/book-keeper, secretary","forms":["āctuārius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et prôdîsset in medium, decēre gravitātem eius tam humilēs ineptiās! ’ [Âctuärius ācta praediôrum recitat] Et plānē interpellāvit saltätiônis libîdinem āctuārius, 53 quī tamquam urbis âcta recitāvit: VIĪ kalendās Sextîlês: in prae- diô Cūmānä, quod est Trimal- chiônis, nātī sunt puerÏXIOÇ pu- ellae XL; sublāta in horreum ex āreā trīticī mîlia modium quîn- genta; bovēs domitî quîngentï.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"actum","latin":"actum, acti","headword":"actum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"act, deed, transaction; acts (pl.), exploits; chronicles, (official) record","forms":["āctī","āctō","āctum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam id āctum est, tubae utrimque canunt contrā,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"actus","latin":"actus, actus","headword":"actus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"act, performance (of play), delivery; action, deed; series/sequence; progress","forms":["āctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et ipse āvulsus ē s t ab iīs quantum ē s t ī āctus lapidī s: et posifīs genibus, ōrābat dīcēns:\"Pater, sī vīs, trānsfer calicem istum ā mē; vērumtamen nōn mea voluntās, sed tua fīat.\"Et ecce sūdor eius, sīcut guttae sanguinis, dēcurrit in terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"actutum","latin":"actutum","headword":"actutum","letter":"a","pos":"adverb","posGroup":"adverb","english":"immediately, instantly; forthwith, without delay","forms":["āctūtum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Redībō āctūtum.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"acumen","latin":"acumen, acuminis","headword":"acumen","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"sharpened point, spur; sting; peak, promontory; sharpness/cunning/acumen; fraud","forms":["acūmen"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ubi est {{acūmen}} tuum?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"acuna","latin":"acuna, acunae","headword":"acuna","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"measure/piece of land (120 feet square), square actus","forms":["acūna"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"[Rīsus atque flētus] Í |{{acūna}} -ae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"acuo","latin":"acuo, acuere, acui, acutus","headword":"acuo","letter":"a","pos":"verb","posGroup":"verb","english":"whet, sharpen, cut to a point; spur on, provoke, incite; come to a head (PASS)","forms":["acuī","acuitur"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In versibus legendīs et aliae syllabae et syllaba vocābulī ultima acuī potest (ut il-lum, ge-mi-nī, se-nēx).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"acus","latin":"acus, acus","headword":"acus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"needle, pin; hair-pin; pipefish, needlefish; detail; husks/chaff (pl.)","forms":["acū"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Omnēs dē lēctābantur cum eam acū vestēs pingentem spectārent, eamque ūnō ōre laudābant dīcentēs ‘Minervam ipsam eius fuisse magistram’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"acute","latin":"acute, acutius, acutissime","headword":"acute","letter":"a","pos":"adverb","posGroup":"adverb","english":"acutely, with intellectual penetration; shrilly; clearly (seeing), distinctly","forms":["acūtē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cibus optimus est atque convīvīs placet, maximē vērō laudātur carō porcī, quam minister cultrō acūtē secat convīvīs spectantibus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"acutus","latin":"acūtus, -a, -um","headword":"acūtus","letter":"a","pos":"adjective","posGroup":"adjective","english":"sharp","forms":["acūtā","acūtae","acūtam","acūtissimam","acutissimis","acuto","acūtum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quini erant ordines coniuncti inter se atque implicati; quo qui intraverant, se ipsi {{acutissimis}} vallis induebant; hos cippos appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ad","latin":"ad","headword":"ad","letter":"a","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) to, toward, by, at, till; to, towards (with acc.); to, toward, near (+ accusative)","forms":["ad"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, in Italiam {{ad}} conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ad…versus","latin":"ad…versus","headword":"ad…versus","letter":"a","pos":"","posGroup":"other","english":"(prp. + acc.) toward","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"adaequo","latin":"adaequo, adaequare, adaequavi, adaequatus","headword":"adaequo","letter":"a","pos":"verb","posGroup":"verb","english":"equalize, make equal in height, come up to level; compare (to); be equal; raze","forms":["adaequabant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis {{adaequabant}} et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adam","latin":"Adam, undeclined","headword":"Adam","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Adam; (from the Hebrew); [NOM S => Adam, not Ada (otherwise 1 DECL Ad...)]","forms":["adam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sīs licet antīquō Niréus {{adam}}àátus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adamare","latin":"(adamō) adamāre","headword":"adamāre","letter":"a","pos":"","posGroup":"other","english":"fall in love with","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adamas","latin":"adamas, adamantis","headword":"adamas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"steel, hardest iron (early); anything hard, adamant; white sapphire; diamond","forms":["adamantā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Lacrimīs adamantā movébis:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adamo","latin":"adamo, adamare, adamavi, adamatus","headword":"adamo","letter":"a","pos":"verb","posGroup":"verb","english":"fall in love/lust with; love passionately/adulterously; admire greatly; covet","forms":["adamā","adamāvit","Adamō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ex ea fōrmāvit mulierem, quam dedit sociam Adamō, sīcque īnstituit mātrimōnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adamus","latin":"Adamus, Adami","headword":"Adamus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Adam, first man","forms":["Adame","Adamum","Adāmus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deus fīnxit corpus hominis ē līmō terrae; dēdit illī animam vīventem; fēcit illum ad similitūdinem suam, et nōmināvit illum {{Adamum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adaquo","latin":"adaquo, adaquare, adaquavi, adaquatus","headword":"adaquo","letter":"a","pos":"verb","posGroup":"verb","english":"water, supply with water, bring water to; obtain water; give to drink","forms":["adaquārī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nam ex eō puteō gregēs solēbant adaquārī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"addico","latin":"addico, addicere, addixi, addictus","headword":"addico","letter":"a","pos":"verb","posGroup":"verb","english":"be propitious; adjudge, sentence, doom; confiscate; award, assign; enslave","forms":["addīcās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tē ōrō atque obsecrō ut sinās puerum abīre, mēque prō eō {{addīcās}} in servitūtem; ego poenam, quā dignus est, mihi sūmō et exsolvam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"addo","latin":"addō, addere","headword":"addō","letter":"a","pos":"verb","posGroup":"verb","english":"add, join; add","forms":["addat","adde","addendum","addēns","addere","adderent","adderet","adderētur","addiderant","addiderat","addidistī","addidit","addit","Additae","additās","additī","additīs","addito","additū","additum","additur","additus","addō","addunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Addunt}} ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adducere","latin":"(addūcō) addūcere (< dūcere)","headword":"addūcere","letter":"a","pos":"verb","posGroup":"verb","english":"lead, bring (to); to bring to, draw to, influence","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"adduco","latin":"adduco, adducere, adduxi, adductus","headword":"adduco","letter":"a","pos":"verb","posGroup":"verb","english":"lead up/to/away; bring up/to; persuade, induce; lead, bring; contract, tighten","forms":["addūcam","addūcātur","addūcere","addūcerent","addūceret","adduci","addūcis","adducit","addūcite","addūcitur","addūcō","addūcor","adductum","adductūrum","adduxerat","addūxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter {{adduci}} iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adductus","latin":"adductus, adducta -um, adductior -or -us, adductissimus -a -um","headword":"adductus","letter":"a","pos":"adjective","posGroup":"adjective","english":"contracted, drawn together; frowning, grave; compressed, terse; strict, severe","forms":["adducta","adducti","adductos","adductus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia {{adducti}} fecerint, quod nihil nobis constat, non videtur pro certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adeo","latin":"adeō","headword":"adeō","letter":"a","pos":"verb","posGroup":"verb","english":"to such a degree, so, too; go to, approach","forms":["adeant","adeat","adeo","adeunda","adeundi","adeundum","adeunt","adī","adībam","adībant","adire","adīret","adīs","adit","aditūrōs","adīverit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hac coacta manu, quoscumque {{adit}} ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adeptus","latin":"adeptus, adeptus","headword":"adeptus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"attainment, an obtaining","forms":["adeptus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iacobus respondit rēgī: vīxī centum et trīgintā annōs, nec {{adeptus}} sum senectūtem beātam avōrum meōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adest","latin":"adest","headword":"adest","letter":"a","pos":"verb","posGroup":"verb","english":"be present; is present, is here; is present","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"adfatus","latin":"adfatus, adfatus","headword":"adfatus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"address, speech, converse with; pronouncement, utterance (of)","forms":["adfātū"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"audeat adfātū? quae prīma exōrdia sūmat?","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adfecto","latin":"adfecto, adfectare, adfectavi, adfectatus","headword":"adfecto","letter":"a","pos":"verb","posGroup":"verb","english":"aim at, desire, aspire, try, lay claim to; try to control; feign, pretend","forms":["adfecto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Summa difficultate rei frumentariae {{adfecto}} exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adfectus","latin":"adfectus, adfectus","headword":"adfectus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"affection, passion, love; friendly feeling (Cas); goodwill; loved ones (pl.)","forms":["adfectum","adfectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Esse non nullo se Caesaris beneficio {{adfectum}}, sic tamen ut iustissimam apud eum causam obtinuerit; sed plus communi libertati tribuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adfero","latin":"adferō, adferre, attulī, allātum","headword":"adferō","letter":"a","pos":"verb","posGroup":"verb","english":"bring to, cause","forms":["adferebantur","adferebat","adferre","adfert","adlātās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum {{adferebat}}: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adficio","latin":"adficio, adficere, adfeci, adfectus","headword":"adficio","letter":"a","pos":"verb","posGroup":"verb","english":"affect, make impression; move, influence; cause (hurt/death), afflict, weaken","forms":["adficiebat","adficiebatur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eo cum venisset, magna difficultate {{adficiebatur}}, qua ratione ad exercitum pervenire posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adfingo","latin":"adfingo, adfingere, adfinxi, adfictus","headword":"adfingo","letter":"a","pos":"verb","posGroup":"verb","english":"add to, attach; aggravate; embellish, counterfeit, forge; claim wrongly","forms":["adfingunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Addunt ipsi et {{adfingunt}} rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adfirmatio","latin":"adfirmatio, adfirmationis","headword":"adfirmatio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"affirmation, strengthening of belief; assertion, dogmatic/positive statement","forms":["adfirmatione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Simul in spem veniebant eius {{adfirmatione}} de reliquis adiungendis civitatibus; primumque eo tempore Galli castra munire instituerunt; et sic sunt animo consternati homines insueti laboris ut omnia quae imperarentur sibi patienda existimarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adflicto","latin":"adflicto, adflictare, adflictavi, adflictatus","headword":"adflicto","letter":"a","pos":"verb","posGroup":"verb","english":"shatter, damage, strike repeatedly, buffet, wreck; oppress, afflict; vex","forms":["adflīctāre"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad hōc mulierēs, quibus reī pūblicae magnitūdine bellī timor īnsolitus incesserat, {{adflīctāre}} sēsē, manūs supplicēs ad caelum tendere, miserārī parvōs līberōs, rogitāre, omnia pāvēre, superbiā atque dēliciīs omissīs sibi patriaeque diffidēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adflictus","latin":"adflictus, adflicta, adflictum","headword":"adflictus","letter":"a","pos":"adjective","posGroup":"adjective","english":"in a state of ruin (persons/countries/affairs), shattered","forms":["adflīctīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ausus, et {{adflīctīs}} melius cōnfīdere rēbus.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adfluo","latin":"adfluo, adfluere, adfluxi, adfluxus","headword":"adfluo","letter":"a","pos":"verb","posGroup":"verb","english":"flow on/to/towards/by; glide/drift quietly; flock together, throng; abound","forms":["adfluerent"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cui cum ad occāsum ab ortū sōlis omnia domita armīs parerent, domī ōtium atque dīvitiae, quae prīma mortālēs putant, {{adfluerent}}, fuēre tamen cīvēs quī sēque remque pūblicam obstinātīs animīs perditum īrent!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adfor","latin":"adfor, adfari, adfatus sum","headword":"adfor","letter":"a","pos":"verb","posGroup":"verb","english":"speak to, address; be spoked to/addressed (PASS), be decreed by fate","forms":["adfāre","adfāta","adfātur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ergō hīs āligerum dictīs {{adfātur}} Amōrem:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adgnosco","latin":"adgnosco, adgnoscere, adgnovi, adgnitus","headword":"adgnosco","letter":"a","pos":"verb","posGroup":"verb","english":"recognize, realize, discern; acknowledge, claim, admit to/responsibility","forms":["adgnōscit","adgnōvit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{adgnōvit}}, tālī fugientem est vōce secūtus:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adgredior","latin":"adgredior, adgredi, adgressus sum","headword":"adgredior","letter":"a","pos":"verb","posGroup":"verb","english":"approach, advance; attack, assail; undertake, seize (opportunity), attempt","forms":["adgrediar","adgressa"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīs licet īnfestus sociīs rēgīque mihique, dūre Philoctēte, licet exsecrēre meumque dēvoveās sine fīne caput cupiāsque dolentī mē tibi forte darī nostrumque haurīre cruōrem, tē tamen {{adgrediar}} mēcumque redūcere nītar tamque tuīs potiar (faveat Fortūna) sagittīs, quam sum Dardaniō, quem cēpī, vāte potītus, quam respōnsa deum Trōiānaque fāta retēxī, quam rapuī Phrygiae signum penetrāle Minervae hostibus ē mediīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"adhaereo","latin":"adhaereo, adhaerere, adhaesi, adhaesus","headword":"adhaereo","letter":"a","pos":"verb","posGroup":"verb","english":"adhere, stick, cling/cleave to; hang on; be attached/concerned/involved","forms":["adhaesit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus {{adhaesit}}, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adhibeo","latin":"adhibeo, adhibere, adhibui, adhibitus","headword":"adhibeo","letter":"a","pos":"verb","posGroup":"verb","english":"summon, invite, bring in; consult; put, add; use, employ, apply; hold out to","forms":["adhibēbat","adhibendos","adhibent","adhibēre","Adhibuī","Adhibuistī","adhibuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hic, summo in Arvernis ortus loco et magnae habitus auctoritatis, 'nihil', inquit, 'de eorum sententia dicturus sum, qui turpissimam servitutem deditionis nomine appellant, neque hos habendos civium loco neque ad concilium {{adhibendos}} censeo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adhinnio","latin":"adhinnio, adhinnire, adhinnivi, adhinnitus","headword":"adhinnio","letter":"a","pos":"verb","posGroup":"verb","english":"whinny to/at; express delight; strive after/long for with voluptuous desire","forms":["adhinnit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"280 fēmina cornipedī semper {{adhinnit}} equō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adhortari","latin":"(adhortor) adhortārī","headword":"adhortārī","letter":"a","pos":"","posGroup":"other","english":"encourage, urge on","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adhortator","latin":"adhortātor, -ōris (m.)","headword":"adhortātor","letter":"a","pos":"","posGroup":"other","english":"one who encourages","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adhortatus","latin":"adhortatus, adhortatus","headword":"adhortatus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"act of urging; encouragement, exhortation, persuasion","forms":["adhortatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"{{Adhortatus}} milites ne necessario tempore itineris labore permoveantur, cupidissimis omnibus progressus milia passuum XXV, agmen Aeduorum conspicatus, immisso equitatu iter eorum moratur atque impedit; interdicitque omnibus ne quemquam interficiant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adhortor","latin":"adhortor, adhortari, adhortatus sum","headword":"adhortor","letter":"a","pos":"verb","posGroup":"verb","english":"encourage, urge on; rally; exhort","forms":["adhortārentur","adhortari","adhortātur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos {{adhortari}} non destitit; quorum alteri, quod nullo studio agebant, non multum adiuvabant, alteri non magnis facultatibus, quod civitas erat exigua et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adhuc","latin":"adhūc","headword":"adhūc","letter":"a","pos":"adverb","posGroup":"adverb","english":"so far, till now, still; still, up to now; until now, up to this point","forms":["adhūc"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Sciō Diodōrum {{adhūc}} quattuor discipulōs habēre, quōrum duo sunt fīliī Iūliī; sed ante paucōs mēnsēs octō discipulōs habēbat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"adicere","latin":"(adiciō) adicere, adiēcisse, adiectum","headword":"adicere","letter":"a","pos":"verb","posGroup":"verb","english":"add; to add","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"adicio","latin":"adicio, adicere, adjeci, adjectus","headword":"adicio","letter":"a","pos":"verb","posGroup":"verb","english":"add, increase, raise; add to (DAT/ad+ACC); suggest; hurl (weapon); throw to/at","forms":["Adice","adicis","adicit","adiciunt","adiēcisset","adiecit","adiectā","adiectum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Huic loricam pinnasque {{adiecit}}, grandibus cervis eminentibus ad commissuras pluteorum atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adiectivum","latin":"adiectīvum (nomen)","headword":"adiectīvum","letter":"a","pos":"","posGroup":"other","english":"adjective","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"adigere","latin":"(adigō) adigere (< agere)","headword":"adigere","letter":"a","pos":"","posGroup":"other","english":"drive, compel (to)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adigo","latin":"adigo, adigere, adegi, adactus","headword":"adigo","letter":"a","pos":"verb","posGroup":"verb","english":"drive in/to (cattle), force, impel; cast, hurl; consign (curse); bind (oath)","forms":["adactis","adacto","adactum","adēgit","adigat","adigerentur","adigeret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis {{adacto}} extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adimere","latin":"(adimō) adimere (< emere)","headword":"adimere","letter":"a","pos":"","posGroup":"other","english":"take away (from), steal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adimo","latin":"adimo, adimere, ademi, ademptus","headword":"adimo","letter":"a","pos":"verb","posGroup":"verb","english":"withdraw, take away, carry off; castrate; deprive, steal, seize; annul; rescue","forms":["adēmerat","adēmit","ademptīs","adempto","ademptum","adimere","adimeret","adimerētur","adimit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prospectu tenebris {{adempto}} multa utrimque vulnera accipiuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adipisci","latin":"(adipīscor) adipīscī, adeptum","headword":"adipīscī","letter":"a","pos":"","posGroup":"other","english":"obtain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adipiscor","latin":"adipiscor, adipisci, adeptus sum","headword":"adipiscor","letter":"a","pos":"verb","posGroup":"verb","english":"gain, secure, win, obtain; arrive at, come up to/into; inherit; overtake","forms":["adeptī","adeptum","adipīscāmur","adipīscendī","adipīscī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posteā inter tot annōs, tot bella, bīna tantum spolia opīma capta sunt: adeō rāra fuit fortūna id decus adipīscendī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adit","latin":"adit, adeunt","headword":"adit","letter":"a","pos":"verb","posGroup":"verb","english":"go to, approach; approaches, goes to","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"aditus","latin":"aditus, -ūs","headword":"aditus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"approach, access; approach, entrance","forms":["aditu","aditum","aditus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum {{aditum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adiudico","latin":"adjudico, adjudicare, adjudicavi, adjudicatus","headword":"adjudico","letter":"a","pos":"verb","posGroup":"verb","english":"adjudge, impute, attribute, ascribe (to); award (as a judge), assign (to)","forms":["adiudicatum","adiūdicāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum {{adiudicatum}} a Caesare demonstravimus, sollicitatus ab Arvernis pecunia cum quibusdam adulescentibus colloquitur; quorum erat princeps Litaviccus atque eius fratres amplissima familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adiumentum","latin":"adiumentum, adiumenti","headword":"adiumentum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"help, assistance, support, means of aid","forms":["adiūmentō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hebraeī arcam foederis in pugnam dēferunt, et cum eā fīliī sacerdōtis prōcēdunt; sed quia Deus illīs erat offēnsus, arca dētrīmentō magis quam adiūmentō fuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adiunctum","latin":"adjunctum, adjuncti","headword":"adjunctum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"quality, characteristic, essential feature/attribute; collateral circumstance","forms":["adiūnctum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Lentulō esse sollicitātōs, eōsque in Galliam ad suōs cīvēs cum litterīs mandātīsque eōdemque itinere ad Catilīnam esse missōs, comitemque eīs {{adiūnctum}} esse T.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adiunctus","latin":"adjunctus, adjuncta -um, adjunctior -or -us, adjunctissimus -a -um","headword":"adjunctus","letter":"a","pos":"adjective","posGroup":"adjective","english":"bound/belonging to; composite, joined in compound (word); adjacent; relevant","forms":["adiūncta","adiūnctīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"\"lōra dare — līberum cursum dare tigribus {{adiūnctīs}} aurea","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adiungere","latin":"(adiungō) adiungere, adiūnxisse, adiūnctum","headword":"adiungere","letter":"a","pos":"verb","posGroup":"verb","english":"add to, join; to join, add","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"adiungo","latin":"adjungo, adjungere, adjunxi, adjunctus","headword":"adjungo","letter":"a","pos":"verb","posGroup":"verb","english":"add, attach, join to, add to, support; apply to; harness, yoke; direct; confer","forms":["adiuncturum","adiungās","adiungēbat","adiungendis","adiungere","adiungeret","adiungit","adiungunt","adiunguntur","adiūnxerat","adiūnxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Celeriter sibi Senones, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui Oceanum attingunt {{adiungit}}; omnium consensu ad: eum defertur imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adiutor","latin":"adjutor, adjutoris","headword":"adjutor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"assistant, deputy; accomplice; supporter; secretary; assistant schoolmaster","forms":["adiūtōrem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eō in proeliō Deus manirestum sē praebuit {{adiūtōrem}}; nam inter pugnandum appāruērunt quīnque virī equīs et virtūte servābant, in hostēs vērō tēla et fulmina iaciēbant: unde illī, oculīs et mente turbafī, ad viginfī quīnque mīlia interfecfī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adiutus","latin":"adjutus, adjutus","headword":"adjutus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"help, aid","forms":["adiūtus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi nūllō dolō {{adiūtus}}, tantum virtūte mīlitum rēx Rōmānus vīcit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adiuvans","latin":"adjuvans, (gen.), adjuvantis","headword":"adjuvans","letter":"a","pos":"adjective","posGroup":"adjective","english":"contributory (cause)","forms":["adiuvante"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Etsī nautae omnibus vīribus rēmigant, tamen illa nāvis, ventō secundō {{adiuvante}}, magis magisque appropinquat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"adiuvare","latin":"(adiuvō) adiuvāre, adiūvisse,  adiūtum","headword":"adiuvāre","letter":"a","pos":"","posGroup":"other","english":"help","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"adiuvo","latin":"adjuvo, adjuvare, adjuvi, adjutus","headword":"adjuvo","letter":"a","pos":"verb","posGroup":"verb","english":"help, aid, abet, encourage, favor; cherish, sustain; be of use, be profitable","forms":["adiuvā","adiuvabant","adiuvabat","adiuvandum","adiuvant","adiuvāre","adiuvārent","adiuvāret","adiuvās","adiuvat","adiūverint","adiuvēs","adiuvet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non multum {{adiuvabant}}, alteri non magnis facultatibus, quod civitas erat exigua et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adloquor","latin":"adloquor, adloqui, adlocutus sum","headword":"adloquor","letter":"a","pos":"verb","posGroup":"verb","english":"speak to (friendly); address, harangue, make a speech (to); call on; console","forms":["adloquere","adloquitur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum sīc rēgīnam {{adloquitur}}, cūnctīsque repente","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"admaturo","latin":"admaturo, admaturare, admaturavi, admaturatus","headword":"admaturo","letter":"a","pos":"verb","posGroup":"verb","english":"hasten (an occurrence); bring to maturity, mature, ripen","forms":["admaturari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Etsi multis iam rebus perfidiam Aeduorum perspectam habebat atque horum discessu {{admaturari}} defectionem civitatis existimabat, tamen eos retinendos non constituit, ne aut inferre iniuriam videretur aut daret timoris aliquam suspicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"administer","latin":"administer, -trī","headword":"administer","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"assistant, helper; assistant, accomplice","forms":["administer","administrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cēterum socius et {{administer}} omnium cōnsiliōrum assūmitur Scaurus, quī tametsī ā principiō ācerrimē rēgem impugnāverat, tamen magnitūdine pecūniae ā bonō honestōque in prāvum abstractus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"administra","latin":"administra, -ae","headword":"administra","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"assistant, helper","forms":["administrae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn enim bellandī virtūs sōlum in summō ac perfectō imperātōre quaerenda est, sed multae sunt artēs eximiae huius {{administrae}} comitēsque virtūtis.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"administrare","latin":"(administrō) administrāre","headword":"administrāre","letter":"a","pos":"","posGroup":"other","english":"conduct, administer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"administro","latin":"administro, administrare, administravi, administratus","headword":"administro","letter":"a","pos":"verb","posGroup":"verb","english":"administer, manage, direct; assist; operate, conduct; maneuver (ship); bestow","forms":["administrābat","administranda","administrandī","administrandis","administrandō","administrandum","administrantibus","administrare","administrarent","administrarentur","administraretur","administrari","administrāta","administrāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua {{administrarentur}}, centurionibus et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium procul visus est, qui agmen Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"admirabilis","latin":"admirabilis, admirabilis, admirabile","headword":"admirabilis","letter":"a","pos":"adjective","posGroup":"adjective","english":"admirable, wonderful; strange, astonishing, remarkable; paradoxical, contrary","forms":["admīrābilīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum iam in cōnspectū habēret terram ā Deō prōmissam, mortuus est vir sapientiā et cēterīs virtūtibus plānē {{admīrābilīs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"admirandus","latin":"admirandus, admiranda, admirandum","headword":"admirandus","letter":"a","pos":"adjective","posGroup":"adjective","english":"wonderful, admirable; astonishing, remarkable, extraordinary","forms":["admīrandum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Admīrandum}} sānē vērī ac sincērī ergā inimīcum amōris exemplum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"admirari","latin":"(admīror) admīrārī, admīrātum","headword":"admīrārī","letter":"a","pos":"","posGroup":"other","english":"wonder at","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"admiratio","latin":"admīrātiō, admīrātiōnis","headword":"admīrātiō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) wonder, admiration; admiration, wonder","forms":["admīrātiōne","admīrātiōnem"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Interiectiō quid est?' Discipulus: 'Pars ōrātiōnis significāns mentīs affectum vōce inconditā.' Magister: 'Significātiō interiectiōnis in quō est?' Discipulus: 'Aut laetitiam significāmus, ut euax!; aut dolōrem, ut heu!; aut {{admīrātiōnem}}, ut pāpae!; aut metum, ut attat!; et sī quā sunt similia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"admirator","latin":"admirator, admiratoris","headword":"admirator","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"admirer; one who venerates","forms":["admīrātor"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hīc litterārum quīdam studiō deditus, Simōnidis quī saepe versūs lēgerat eratque absentis {{admīrātor}} māximus, Simōnidem ipsum cognitum cupidissimē ad sē recēpit: veste, nummīs, familiā hominem exōrnāvit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"admiror","latin":"admiror, admirari, admiratus sum","headword":"admiror","letter":"a","pos":"verb","posGroup":"verb","english":"admire, respect; regard with wonder, wonder at; be surprised at, be astonished","forms":["admīrābantur","admīrāminī","admīrāns","admīrārentur","admīrārētur","admīrārī","admirāta","admīrātī","admīrātur","admīrātus","admīrēminī","admīror"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Admiratus}} quaerit ex perfugis causam, quorum magnus ad eum cotidie numerus confluebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"admiscere -miscuisse","latin":"(admisceō) admiscēre -miscuisse","headword":"admiscēre -miscuisse","letter":"a","pos":"","posGroup":"other","english":"mix (in), add","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"admissum","latin":"admissum, admissi","headword":"admissum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"crime, offense","forms":["admisso","admissum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"An dubitamus quin nefario facinore {{admisso}} Romani iam ad nos interficiendos concurrant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"admissus","latin":"admissus, admissus","headword":"admissus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"admission, letting in","forms":["Admissus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Admissus}} ergô ad Caesarem est cum suô mūnere. (Phialam porrēxit) Caesarî, deinde tēcit rēpor- valdius quam expāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"admittere","latin":"(admittō) admittere, admīsisse,  admissum","headword":"admittere","letter":"a","pos":"verb","posGroup":"verb","english":"let in; to let in, admit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"admitto","latin":"admitto, admittere, admisi, admissus","headword":"admitto","letter":"a","pos":"verb","posGroup":"verb","english":"urge on, put to a gallop; let in, admit, receive; grant, permit, let go","forms":["admīsit","admissās","admissōs","Admitte","admittere","admittēris","admittī","admittis","admittit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī Lepidus revenit, nōlī {{admittere}} eum!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"admodum","latin":"admodum","headword":"admodum","letter":"a","pos":"adverb","posGroup":"adverb","english":"very much, quite","forms":["admodum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postero die concilio convocato, consolatus cohortatusque est ne se {{admodum}} animo demitterent, ne perturbarentur incommodo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"admoneo","latin":"admoneo, admonere, admonui, admonitus","headword":"admoneo","letter":"a","pos":"verb","posGroup":"verb","english":"admonish, remind, prompt; suggest, advise, raise; persuade, urge; warn, caution","forms":["admoneāmur","admonēbat","admonente","admonentem","admoneō","admonēre","admonērent","admonēret","admonet","admonuī","admonuistī","admonuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iōsēphus vīxit annōs centum et decem; cumque esset mortī proximus, convocāvit frātrēs suōs, et illōs {{admonuit}} sē brevī moritūrum esse.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"admonere","latin":"(admoneō) admonēre (< monēre)","headword":"admonēre","letter":"a","pos":"","posGroup":"other","english":"remind, advise, urge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"admonitum","latin":"admonitum, admoniti","headword":"admonitum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"warning; reminder; reminding; advice; admonition","forms":["admonitum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sî nôn, tē iubëbô in decuriam Viätôrum conicî.” Et cocum quidem, potentiae {{admonitum}}, in culînam Trimalchiô autem mîtî ad nôs vultū respexit, et “Vî- num” inquit “sî nôn placet, mütäbô.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"admonitus","latin":"admonitus, -ūs","headword":"admonitus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"advice, prompting (only in abl.)","forms":["admonitū","admonitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Noēmus, {{admonitus}} ā Deō, exstrūxit ingentem arcam in modum nāvis; līnīvit eam bitūmine, et in eam indūxit pār ūnum omnium avium et animantium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"admoveo","latin":"admoveo, admovere, admovi, admotus","headword":"admoveo","letter":"a","pos":"verb","posGroup":"verb","english":"move up, bring up/near; lean on, conduct; draw near, approach; apply, add","forms":["admōtā","admōtae","admōtīs","admōtō","admōtum","admōtus","admovēret","admovērī","admōvērunt","admōvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iōnāthās ēdictī paternī nescius extendit virgam quam manū tenēbat, eamque in mel intīnctam ōrī {{admōvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"admovere","latin":"(admoveō) admovēre (< movēre)","headword":"admovēre","letter":"a","pos":"","posGroup":"other","english":"move near, put to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"admugio","latin":"admugio, admugire, -, -","headword":"admugio","letter":"a","pos":"verb","posGroup":"verb","english":"low (to); bellow (to); (like a bull)","forms":["admūgit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Mollibus in prátis {{admūgit}} fēmina taurō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"admurmuratio","latin":"admurmurātiō, -ōnis ( f.)","headword":"admurmurātiō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"murmur","forms":["admurmurātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vestra admurmurātiō facit, Quirītēs, ut agnōscere videāminī quī haec fēcerint — ego autem nōminō nēminem; quārē īrāscī mihi nēmō potest, nisi quī ante dē sē voluerit cōnfitērī!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adnectere","latin":"(adnectō) adnectere, -nexuisse,  -nexum","headword":"adnectere","letter":"a","pos":"","posGroup":"other","english":"bind, tie","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"adnecto","latin":"adnecto, adnectere, adnexui, adnexus","headword":"adnecto","letter":"a","pos":"verb","posGroup":"verb","english":"tie on/to, tie up (ship); bind to; fasten on; attach, connect, join, annex","forms":["adnectēns"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis {{adnectēns}} ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: 'Cōpulātīvās, disiūnctīvās, explētīvās, causālēs, ratiōnālēs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"adniti","latin":"(adnītor) adnītī, -īsum","headword":"adnītī","letter":"a","pos":"","posGroup":"other","english":"exert oneself, strive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adnitor","latin":"adnitor, adniti, adnisus sum","headword":"adnitor","letter":"a","pos":"verb","posGroup":"verb","english":"lean/rest upon, support oneself, (w/genibus) kneel; strive, work, exert, try","forms":["adnītiminī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quam ob rem vōs, quibus mīlitāris aetās est, adnītiminī mēcum!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adnixus","latin":"adnixus, adnixa, adnixum","headword":"adnixus","letter":"a","pos":"adjective","posGroup":"adjective","english":"vehement, strenuous","forms":["adnīxī","adnīxus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cȳmothoē simul et Trītōn {{adnīxus}} acūtō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adno","latin":"adno, adnare, adnavi, adnatus","headword":"adno","letter":"a","pos":"verb","posGroup":"verb","english":"swim to/towards, approach by swimming; sail to/towards; brought by sea (goods)","forms":["adnāre","adnāvimus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dispulit; hūc paucī vestrīs {{adnāvimus}} ōrīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adnotatiuncula","latin":"adnotātiuncula, -ae","headword":"adnotātiuncula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"short note","forms":["adnotātiunculīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed prōgressī longius sumus, cum fīnem prōposuerimus {{adnotātiunculīs}} istīs bellum Poenōrum secundum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adnoto","latin":"adnoto, adnotare, adnotavi, adnotatus","headword":"adnoto","letter":"a","pos":"verb","posGroup":"verb","english":"note/jot down, notice, become aware; mark, annotate; record, state; designate","forms":["adnotāvī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fuērunt aliī similis āmentiae, quōs, quia cīvēs Rōmānī erant, adnotāvī in Urbem remittendōs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"adnuo","latin":"adnuo, adnuere, adnui, adnutus","headword":"adnuo","letter":"a","pos":"verb","posGroup":"verb","english":"designate by a nod; indicate, declare; nod assent; smile on; agree to, grant","forms":["Adnuit"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Adnuit}}. ‘Est vērō’ inquam ‘nōtum quidem signum: imāgō avī tuī, clārissimī virī, quī amāvit ūnicē patriam et cīvēs suōs: quae quidem tē ā tantō scelere etiam mūta revocāre dēbuit!’ Leguntur eādem ratiōne ad senātum Allobrogum populumque litterae.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adoleo","latin":"adoleo, adolere, adolui, adolultus","headword":"adoleo","letter":"a","pos":"verb","posGroup":"verb","english":"worship, make/burn sacrifice/offerings; cremate; destroy/treat by fire/heat","forms":["adolēre"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cūra penum struere, et flammīs {{adolēre}} Penātīs;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adolescentior","latin":"adolescentior, adolescentiari, adolescentiatus sum","headword":"adolescentior","letter":"a","pos":"verb","posGroup":"verb","english":"behave in a youthful manner","forms":["adolēscentior"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et dīxit {{adolēscentior}} patrī: ' P āter, dā mihi portiōnem substantiae quae mē contingit. ' Et pater dīvīsit illī substantiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adolescere","latin":"(adolēscō) adolēscere, adolēvisse,","headword":"adolēscere","letter":"a","pos":"","posGroup":"other","english":"grow up adultum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adolesco","latin":"adolesco, adolescere, adolevi, adultus","headword":"adolesco","letter":"a","pos":"verb","posGroup":"verb","english":"grow up, mature, reach manhood/peak; become established/strong; grow, increase","forms":["adolēverit","adolēvērunt","adolēvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Isaacus {{adolēvit}}, deus tentāns fidem Abrahamī, dīxit illī: Abrahame, tolle fīlium tuum ūnicum quem amās, et immolā eum mihi in monte quem ostendam tibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adoni","latin":"Adoni, Adoniis","headword":"Adoni","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Adonis; (beautiful youth loved by Venus, killed by a boar)","forms":["Adōnī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"“Ō mī amātissimē Adōnī,” clamacum videat Adōnem morientem, magnō animī dolōre afficiēbātur inter lacrimās, “utinam mē audīvissēs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"adoptare","latin":"(adoptō) adoptāre","headword":"adoptāre","letter":"a","pos":"","posGroup":"other","english":"adopt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adoptatio","latin":"adoptātiō, -ōnis ( f.)","headword":"adoptātiō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"adoption","forms":["adoptātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi cum multa dē administrandō imperiō dissererent, Iugurtha inter aliās rēs iacit 'oportere quīnquenniī cōnsulta et dēcrēta omnia rescindī, nam per eōs annōs Micipsam parum animō valuisse.' Tum 'idem' Hiempsal 'placēre sibi' respondit, 'nam ipsum illum tribus proximīs annīs {{adoptātiōne}} in rēgnum pervēnisse!' Quod verbum in pectus Iugurthae altius quam quisquam rātus erat dēscendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adoptio","latin":"adoptiō, -ōnis ( f.)","headword":"adoptiō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"adoption","forms":["adoptiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam duōbus ē fīliīs (quōs, duōbus datīs in {{adoptiōnem}}, sōlōs nōminis, sacrōrum familiaeque hērēdēs retīnuerat domī) minor, duodecim fermē annōs nātus, quīnque diēbus ante triumphum, maior, quattuordecim annōrum, trīduō post triumphum dēcessit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adopto","latin":"adopto, adoptare, adoptavi, adoptatus","headword":"adopto","letter":"a","pos":"verb","posGroup":"verb","english":"adopt, select, secure, pick out; wish/name for oneself; adopt legally","forms":["Adoptat","adoptātum","adoptāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Itaque māter nūtrīvit puerum, et adultum reddidit fīliae pharaōnis, quae illum {{adoptāvit}}, et nōmināvit Moisem, id est ‘servātum ab aquīs’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ador","latin":"ador, adoris","headword":"ador","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"coarse grain; emmer wheat; spelt","forms":["ador"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"belé -es f, dea Phrygia quae {{ador}}à-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adorandus","latin":"adorandus, adoranda, adorandum","headword":"adorandus","letter":"a","pos":"adjective","posGroup":"adjective","english":"adorable, worthy of adoration/veneration","forms":["adōrandōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dēnique cum īrent omnēs ad vitulōs aureōs, quōs Ieroboāmus rēx Isrāēlis fēcerat, et populō {{adōrandōs}} prōposuerat, hīc sōlus fugiēbat societātem omnium; pergēbat autem ad templum Dominī, et ibi adōrābat Dominum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adorare","latin":"(adōrō) adōrāre, adōrāvisse, adōrātum","headword":"adōrāre","letter":"a","pos":"verb","posGroup":"verb","english":"adore, worship; to adore, worship","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"adorio","latin":"adorio, adorire, -, adoritus","headword":"adorio","letter":"a","pos":"verb","posGroup":"verb","english":"assail/assault/attack, rise against (military/political/plague); accost/address","forms":["adoriantur","adoriebantur","adoriebatur","adorīrentur","adorīrētur","adoriri","adoriuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque observabat dispersosque, cum longius necessario procederent, {{adoriebatur}} magnoque incommodo adficiebat, etsi quantum ratione provideri poterat ab nostris occurrebatur, ut incertis temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adorior","latin":"adorior, adoriri, adortus sum","headword":"adorior","letter":"a","pos":"verb","posGroup":"verb","english":"assail/assault/attack, rise against (military/political/plague); accost/address","forms":["adorti","adortus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hos continuo in itinere {{adorti}} omnibus impedimentis exuunt; repugnantes diem noctemque obsident; multis utrimque interfectis maiorem multitudinem ad arma concitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adoriri","latin":"(adorior) adorīrī (< orīrī)","headword":"adorīrī","letter":"a","pos":"","posGroup":"other","english":"attack","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adornare","latin":"(adōrnō) adōrnāre","headword":"adōrnāre","letter":"a","pos":"","posGroup":"other","english":"equip","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adorno","latin":"adorno, adornare, adornavi, adornatus","headword":"adorno","letter":"a","pos":"verb","posGroup":"verb","english":"equip, get ready, prepare; set off; adorn, array, embellish; honor, endow","forms":["adōrnārī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"IVPPITER: Iubē vērō vāsa pūra adōrnārī mihi,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"adoro","latin":"adoro, adorare, adoravi, adoratus","headword":"adoro","letter":"a","pos":"verb","posGroup":"verb","english":"honor, adore, worship, pay homage, reverence; beg, plead with, appeal to","forms":["adōrā","adōrābant","adōrābat","adōrāns","adōrant","adōrantēs","adōrārent","adorarī","adōrāta","adōrāvērunt","adōrāvissent","adōrāvit","adōret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; {{adōrābant}} sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, homicīdium; ūnō verbō, sē contāminābant omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adpareo","latin":"adpareo, adparere, adparui, adparitus","headword":"adpareo","letter":"a","pos":"verb","posGroup":"verb","english":"appear; be evident/visible/noticed/found; show up, occur; serve (w/DAT)","forms":["Adpārent"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Adpārent}} rārī nantēs in gurgite vastō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adpello","latin":"adpello, adpellere, adpuli, adpulsus","headword":"adpello","letter":"a","pos":"verb","posGroup":"verb","english":"drive to, move up, bring along, force towards; put ashore at, land (ship)","forms":["adpulit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"forte suā Libycīs tempestās {{adpulit}} ōrīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adpotus","latin":"adpotus, adpota, adpotum","headword":"adpotus","letter":"a","pos":"adjective","posGroup":"adjective","english":"drunk, intoxicated","forms":["adpōtum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Crēdō edepol equidem dormīre Sōlem—atque {{adpōtum}} probē!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"adquiro","latin":"adquiro, adquirere, adquisivi, adquisitus","headword":"adquiro","letter":"a","pos":"verb","posGroup":"verb","english":"acquire besides/in addition, obtain, gain, win, get; add to stock; accrue","forms":["adquireret","adquīrit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Labienus tanta rerum commutatione longe aliud sibi capiendum consilium atque antea senserat intellegebat, neque iam ut aliquid {{adquireret}} proelioque hostes lacesseret sed ut incolumem exercitum Agedincum reduceret cogitabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adrado","latin":"adrado, adradere, adrasi, adrasus","headword":"adrado","letter":"a","pos":"verb","posGroup":"verb","english":"shave/scrape/pare close; trim; fleece; [~ cacumen => lop off]","forms":["adrāsum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Palliô enim coccineô {{adrāsum}} exclūserat caput, circäque onerātās veste cer- vîcës lāticlāviam immîserat mappam ﬁmbriîs hinc atque illinc pendentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"adrideo","latin":"adrideo, adridere, adrisi, adrisus","headword":"adrideo","letter":"a","pos":"verb","posGroup":"verb","english":"smile at/upon; please, be pleasing/satisfactory (to); be/seem familiar (to)","forms":["adrīdē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sī rīserit, ad-ridé (: ridé ad illam) Rīserit: adrīdē! sī flēbit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adscendens","latin":"adscendens, (gen.), adscendentis","headword":"adscendens","letter":"a","pos":"adjective","posGroup":"adjective","english":"of/for climbing (machine); enabling one to climb","forms":["adscendentēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iacobus vīdit in somnīs scālam, quae innīxa terrae pertinēbat ad caelum, atque Angelōs Deī {{adscendentēs}} et dēscendentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adscisco","latin":"adscisco, adsciscere, adscivi, adscitus","headword":"adscisco","letter":"a","pos":"verb","posGroup":"verb","english":"adopt, assume; receive, admit, approve of, associate; take over, claim","forms":["adscītum","adscīvisse"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eā tempestāte plūrimōs cuiusque generis hominēs {{adscīvisse}} sibi dīcitur, mulierēs etiam aliquot, quae prīmō ingentēs sūmptūs stuprō corporis tolerāverant, post, ubi aetās tantummodo quaestuī neque luxuriae modum fēcerat, aes aliēnum grande cōnflāverant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adsector","latin":"adsector, adsectari, adsectatus sum","headword":"adsector","letter":"a","pos":"verb","posGroup":"verb","english":"accompany, attend, escort; support, be an adherent, follow; court (fame)","forms":["adsectārētur"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Accurrit quīdam nōtus mihi nōmine tantum, arreptāque manū: “Quid agis, dulcissimē rērum?” “Suāviter, ut nunc est,” inquam, “et cupiō omnia quae vīs.” Cum {{adsectārētur}}, “Numquid vīs?” occupō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"adsentio","latin":"adsentio, adsentire, adsensi, adsensus","headword":"adsentio","letter":"a","pos":"verb","posGroup":"verb","english":"assent, approve, agree in opinion; admit the truth of (w/DAT), agree (with)","forms":["adsentiant"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: Mihi quoque adsunt testēs quī illud quod ego dicam {{adsentiant}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"adsentior","latin":"adsentior, adsentiri, adsensus sum","headword":"adsentior","letter":"a","pos":"verb","posGroup":"verb","english":"assent to, agree, approve, comply with; admit the truth of (w/PREP)","forms":["adsentiēbantur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postquam Caesar dīcundī fīnem fēcit, cēterī verbō alius aliī variē {{adsentiēbantur}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adsentor","latin":"adsentor, adsentari, adsentatus sum","headword":"adsentor","letter":"a","pos":"verb","posGroup":"verb","english":"flatter, humor; agree, assent, confirm; agree to everything","forms":["adsentārī","adsentāris"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: Etiam tū quoque {{adsentāris}} huic?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"adsequor","latin":"adsequor, adsequi, adsecutus sum","headword":"adsequor","letter":"a","pos":"verb","posGroup":"verb","english":"follow on, pursue, go after; overtake; gain, achieve; equal, rival; understand","forms":["adsequerētur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sullae libīdō maxima invāserat reī pūblicae capiundae, neque id quibus modīs {{adsequerētur}}, dum sibi rēgnum parāret, quicquam pēnsī habēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adservo","latin":"adservo, adservare, adservavi, adservatus","headword":"adservo","letter":"a","pos":"verb","posGroup":"verb","english":"keep, guard, preserve; watch, observe; keep in custody; save life of, rescue","forms":["adservārem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ā quō nōn receptus etiam ad mē venīre ausus es, atque ut domī meae tē {{adservārem}} rogāstī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adsideo","latin":"adsideo, adsidere, adsedi, adsessus","headword":"adsideo","letter":"a","pos":"verb","posGroup":"verb","english":"sit by/in council/as assessor; watch over; camp near, besiege; resemble (w/DAT)","forms":["adsēdit","adsidet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"tumēre — tumidum (: turbidum) esse cum tumet, auxiliīs {{adsidet}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adsimulatus","latin":"adsimulatus, adsimulata, adsimulatum","headword":"adsimulatus","letter":"a","pos":"adjective","posGroup":"adjective","english":"similar, like, made similar; imitated, feigned, pretended. dissembled","forms":["adsimulātae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hāc ille tam varia multiplicīque nātūra cum omnēs omnibus ex terrīs hominēs improbōs audācēsque collēgerat, tum etiam multōs fortēs virōs et bonōs speciē quādam virtūtis {{adsimulātae}} tenēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"adsimulo","latin":"adsimulo, adsimulare, adsimulavi, adsimulatus","headword":"adsimulo","letter":"a","pos":"verb","posGroup":"verb","english":"make like; compare; counterfeit, simulate, imitate, pretend, feign, act a part","forms":["adsimulābō","adsimulāvit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Sed ita {{adsimulāvit}} sē quasi Amphitryō siet.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"adsisto","latin":"adsisto, adsistere, adstiti, adstatus","headword":"adsisto","letter":"a","pos":"verb","posGroup":"verb","english":"take a position/stand (near/by), attend; appear before; set/place near","forms":["adsistit","adsistō","adstiterit","adstitit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Angelus {{adstitit}} Gedeōnī: “Dominus tēcum” inquit “vir fortissimē.” Respondit Gedeōn: “Sī Deus nōbīscum est, cūr dūra premimur servitūte?” Ait angelus: “Mactē animō!","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adspecto","latin":"adspecto, adspectare, adspectavi, adspectatus","headword":"adspecto","letter":"a","pos":"verb","posGroup":"verb","english":"look/gaze at/upon; observe, watch; pay heed; face/look towards (place/person)","forms":["adspectat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"imminet, adversāsque {{adspectat}} dēsuper arcēs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adspicio","latin":"adspiciō, -ere, -spēxī, -spectum","headword":"adspiciō","letter":"a","pos":"verb","posGroup":"verb","english":"to catch sight of, look at; to catch sight of","forms":["adspexī","Adspice","adspiciam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Adspice}} caelum; dīnumerā stēllās, sī potes; tua prōgeniēs eās aequābit numerō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adspiro","latin":"adspiro, adspirare, adspiravi, adspiratus","headword":"adspiro","letter":"a","pos":"verb","posGroup":"verb","english":"breathe/blow (upon); aspirate; instill, infuse; be fragrant; influence; aspire","forms":["adspīrāns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"flōribus et dulcī {{adspīrāns}} complectitur umbrā.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adstare","latin":"(adstō) adstāre","headword":"adstāre","letter":"a","pos":"verb","posGroup":"verb","english":"stand by; to stand by (with dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"adsto","latin":"adsto, adstare, adstiti, -","headword":"adsto","letter":"a","pos":"verb","posGroup":"verb","english":"stand at/on/by/near; assist; stand up/upright/waiting/still/on one's feet","forms":["adstābat","adstāmus","adstante","adstantēs","adstāre","adstat","adstō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vidēbātur sibi {{adstāre}} Nīlō flūminī; et ecce ēmergēbant dē flūmine septem vaccae pinguēs, quae pāscēbantur in palūde.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adstrictus","latin":"adstrictus, adstricta -um, adstrictior -or -us, adstrictissimus -a -um","headword":"adstrictus","letter":"a","pos":"adjective","posGroup":"adjective","english":"bound (by rules), tied; terse, brief, restrained; constricted, dense, compact","forms":["adstricta","adstrictīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pectora, dum gaudent nec sunt {{adstricta}} dolōre,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adstringo","latin":"adstringo, adstringere, adstrinxi, adstrictus","headword":"adstringo","letter":"a","pos":"verb","posGroup":"verb","english":"tie up/down/back/on/together/tightly; bind, grasp, tighten, fix; form boundary","forms":["adstringitur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"īmaque pars cērīs {{adstringitur}} igne solūtīs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adstruo","latin":"adstruo, adstruere, adstruxi, adstructus","headword":"adstruo","letter":"a","pos":"verb","posGroup":"verb","english":"build on/additional structure; heap/pile (on); add to/on, contribute, provide","forms":["adstrue"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Iam mōlīre animum quī dūret et {{adstrue}} fōrmae:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adsuescere","latin":"(adsuēscō) adsuēscere, adsuētum","headword":"adsuēscere","letter":"a","pos":"","posGroup":"other","english":"get accustomed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adsuetudo","latin":"adsuetudo, adsuetudinis","headword":"adsuetudo","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"custom, habit; repeated practice/experience/association; intimacy, intercourse","forms":["adsuētūdō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"adsuétüdine (: quam adsuētūdō)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adsuetus","latin":"adsuetus, adsueta, adsuetum","headword":"adsuetus","letter":"a","pos":"adjective","posGroup":"adjective","english":"accustomed, customary, usual, to which one is accustomed/used","forms":["adsuētus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"in-{{adsuētus}} -ā -um («» solitus) 7 quī fertur inadsuēta subsecuisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adsum","latin":"adsum, adesse, adfuī, adfutūrum","headword":"adsum","letter":"a","pos":"verb","posGroup":"verb","english":"be present, be near","forms":["aderant","aderat","aderis","aderit","aderō","adērunt","ades","adesse","adessent","adesset","adest","adeste","adestis","adestō","adforet","adfuērunt","adfuit","adsīs","adsit","adsum","adsumus","adsunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum, collaudatis Carnutibus, dato iure iurando ab omnibus qui {{aderant}}, tempore eius rei constituto ab concilio disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adsurgo","latin":"adsurgo, adsurgere, adsurrexi, adsurrectus","headword":"adsurgo","letter":"a","pos":"verb","posGroup":"verb","english":"rise/stand up, rise to one's feet/from bed; climb, lift oneself; grow; soar","forms":["adsurgēns","adsurgunt"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cum subitō {{adsurgēns}} flūctū nimbōsus Ōrīōn","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"adulans","latin":"adulans, (gen.), adulantis","headword":"adulans","letter":"a","pos":"adjective","posGroup":"adjective","english":"flattering, adulatory","forms":["adūlantēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"quīn etiam laetās mōvēre per āera caudās\nnostraque {{adūlantēs}} comitantur vestīgia, dōnec\n[nōs] excipiunt famulae perque ātria marmore tēcta\nad dominam dūcunt: pulchrō sedet illa recessū\nsollemnī soliō, pallamque indūta nitentem\nīnsuper aurātō circumvelātur amictū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"adulatio","latin":"adulatio, adulationis","headword":"adulatio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"flattery, adulation; prostrating oneself; fawning (dogs), (pigeon) courtship","forms":["adūlatione"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"S ed IOiadā mortuō, aulicōrum {{adūlatione}} corruptus, ad vitia dēflexit, vēramque religiōnem dēseruit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adulescens","latin":"adulēscēns, adulēscentis","headword":"adulēscēns","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) young person; young man","forms":["adulescens","adulēscente","adulescentem","adulescentes","adulēscentī","adulescentibus","adulēscentis","adulescentium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae {{adulescens}}, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adulescentia","latin":"adulēscentia, -ae","headword":"adulēscentia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"youth; youth, young manhood","forms":["adulēscentiā","adulēscentiae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōrum Iugurtha acceptā ōrātiōne respondit: 'Sibi neque māius quicquam neque cārius auctōritāte senātūs esse; ab adulēscentiā ita sē enīsum ut ab optimō quōque probārētur; virtūte, nōn malitiā P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adulescentior","latin":"adulescentior, adulescentiari, adulescentiatus sum","headword":"adulescentior","letter":"a","pos":"verb","posGroup":"verb","english":"behave in a youthful manner","forms":["adulēscentior"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et dīxit {{adulēscentior}} ex illīs patrī: “Pater, dā mihi portiōnem substantiae quae mē contingit!” Et dīvīsit illīs substantiam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"adulescentulus","latin":"adulescentulus, adulescentuli","headword":"adulescentulus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"young man; mere youth","forms":["adulēscentulī","adulēscentulō","adulēscentulum","adulēscentulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Nōn poteris” inquit “{{adulēscentulus}} cum virō rōbustissimō pugnāre.” Respondit Dāvīd: “Nē timeās, ō rēx: cum pāscerem ovēs patris meī, leō invāsit gregem, ovemque corripuit: ego illum persecūtus occīdī, et ovem ē faucibus illīus ēripuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adulo","latin":"adulo, adulare, adulavi, adulatus","headword":"adulo","letter":"a","pos":"verb","posGroup":"verb","english":"fawn upon (as a dog); flatter (in a servile manner), court; make obeisance (to)","forms":["adūlēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ut ait Homērus; Hylās -ae m, {{adūlēs}}-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adulor","latin":"adulor, adulari, adulatus sum","headword":"adulor","letter":"a","pos":"verb","posGroup":"verb","english":"fawn upon (as a dog); flatter (in a servile manner), court; make obeisance (to)","forms":["adūlābātur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc canis, quī simul fuerat in viā, praecucurrit, et, quasi nūntius adveniēns, caudā suā erō {{adūlābātur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adulter","latin":"adulter, -erī","headword":"adulter","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"adulterer","forms":["adulter","adulterum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{adulter}} -erī m — vir quī aliénam uxó- Ille tuus nüllàs sentit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"adultera","latin":"adultera, -ae","headword":"adultera","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"adulteress","forms":["adultera"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Vidē iniūriam meam, {{adultera}}!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"adulterinus","latin":"adulterīnus, -a, -um","headword":"adulterīnus","letter":"a","pos":"adjective","posGroup":"adjective","english":"forged, false; false, counterfeit","forms":["adulterīnās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quem ille casū ministrum oblātum prōmissīs onerat impellitque utī tamquam suam vīsēns domum eat, portārum clāvēs {{adulterīnās}} paret — nam vērae ad Hiempsalem referēbantur; 'cēterum, ubi rēs postulāret, sē ipsum cum magnā manū ventūrum.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adulterium","latin":"adulterium, -ī","headword":"adulterium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"adultery","forms":["adulteria","adulteriī","adulteriō","adulterium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dum Mīnōs bellum gerit, opprobrium generis crēverat et {{adulterium}} foedum rēgīnae mōnstrō biformī patēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"adultero","latin":"adultero, adulterare, adulteravi, adulteratus","headword":"adultero","letter":"a","pos":"verb","posGroup":"verb","english":"commit adultery, defile (w/adultery); falsify, counterfeit, debase, corrupt","forms":["adulterābitis","adulterō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn occīdētis, nōn {{adulterābitis}}, nōn faciētis fūrtum; nōn dīcētis falsum testimōnium adversus proximum vestrum; nōn concupīscētis rem alterīus.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adultus","latin":"adultus, -a, -um (< adolēscere Cap. XLI)","headword":"adultus","letter":"a","pos":"adjective","posGroup":"adjective","english":"fullgrown, adult; grown up, mature","forms":["adultā","adultam","adultum","adultus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque māter nūtrīvit puerum, et {{adultum}} reddidit fīliae pharaōnis, quae illum adoptāvit, et nōmināvit Moisem, id est ‘servātum ab aquīs’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"adumbratus","latin":"adumbratus, adumbrata, adumbratum","headword":"adumbratus","letter":"a","pos":"adjective","posGroup":"adjective","english":"sketchy, shadowy, unsubstantial, obscure; outline; pretended, feigned, spurious","forms":["adumbrāta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Habuit enim ille, sīcuti meminisse vōs arbitror, permulta maximārum nōn expressa signa sed {{adumbrāta}} virtūtum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"aduncus","latin":"aduncus, -a, -um","headword":"aduncus","letter":"a","pos":"adjective","posGroup":"adjective","english":"hooked, curved","forms":["aduncō","aduncum","aduncus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"interit assiduā vōmer {{aduncus}} humō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aduro","latin":"aduro, adurere, adussi, adustus","headword":"aduro","letter":"a","pos":"verb","posGroup":"verb","english":"scorch, singe; burn; consume in fire","forms":["adūrēbat","adussit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Īrātus rēx eōs vesfītōs et catēnīs vīnctōs coniēcit in fomaeem ārdentem, sed flamma nihil illīs nocuit: nec corpus {{adussit}} ignis, nec vestēs quidem mūtāvit, at solvit tantummodo vincula, quibus eonstringēbantur, ita ut illaesī in mediā fomace ambulārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"advectus","latin":"advectus, advectus","headword":"advectus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"transportation, conveyance (to a place)","forms":["advectus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hae tibi erunt artēs: pācīque impōnere mōrem, parcere subiectīs et dēbellāre superbōs.' Cumīs profectus Aenēās prīmum portum Caiētae petīvit, deinde ventīs secundīs ad ōstium Tiberīnum {{advectus}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adveho","latin":"advehō, advehere","headword":"advehō","letter":"a","pos":"verb","posGroup":"verb","english":"carry to","forms":["advectī","advehēbātur","advehere","advehitur","advēxerit","advēxit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Multī nautae nunc in mare merguntur, dum rēs necessāriās ex terrīs aliēnīs in Italiam {{advehere}} cōnantur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"advena","latin":"advena, -ae","headword":"advena","letter":"a","pos":"noun; noun (m.)","posGroup":"noun","english":"immigrant, foreigner; stranger; newcomer, stranger","forms":["advena","advenae","advenam","advenārum","advenās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi sonum audīvērunt, Philēmōn iānuam aperuit, {{advenās}} intrāre et cōnsīdere iussit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"advenio","latin":"adveniō, -īre, -vēnī, -ventum","headword":"adveniō","letter":"a","pos":"verb","posGroup":"verb","english":"to come to, arrive","forms":["advēneram","advēnerat","advēneris","advēnerit","advēnerō","adveniās","adveniat","adveniēns","advenientem","advenientī","advēnimus","adveniō","advenīre","advenīs","advēnisse","advenit","adveniunt","adventūram","adventūrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlius et Aemilia ad vīllam suam {{adveniunt}} et ā Iūliā laetā salūtantur: “Salvēte, pater et māter!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"advenit","latin":"advenit, adveniunt","headword":"advenit","letter":"a","pos":"verb","posGroup":"verb","english":"arrive; arrives; arrives, comes to","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"adventare","latin":"(adventō) adventāre","headword":"adventāre","letter":"a","pos":"","posGroup":"other","english":"approach","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adventicius","latin":"adventīcius, -a, -um","headword":"adventīcius","letter":"a","pos":"adjective","posGroup":"adjective","english":"from without, foreign","forms":["adventīciīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mithridātēs autem et suam manum iam cōnfirmārat et magnīs {{adventīciīs}} auxiliīs multōrum rēgum et nātiōnum iuvābātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"advento","latin":"adventō, -āre","headword":"adventō","letter":"a","pos":"verb","posGroup":"verb","english":"arrive, approach","forms":["adventābant","adventābat","adventāre","adventat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Fēcerat haec [fāma] nōtum Graiās cum mīlite fortī {{adventāre}} ratēs neque inexspectātus in armīs hostis adest; prohibent aditūs lītusque tuentur Trōes, et magnō quid Achāica dextera posset sanguine sēnsērunt, et iam Phrygia rubēbant lītora, iam lētō prōlēs Neptūnia, Cygnus, mīlle virōs dederat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"adventus","latin":"adventus, -ūs","headword":"adventus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"arrival","forms":["adventu","adventum","adventus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eius {{adventu}} Bituriges ad Aeduos, quorum erant in fide, legatos mittunt subsidium rogatum, quo facilius hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adverbium","latin":"adverbium, -ī","headword":"adverbium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"adverb","forms":["adverbia","adverbiōrum","adverbium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister discipulum interrogat: 'Partēs ōrātiōnis quot sunt?' Discipulus respondet: 'Octō.' Magister: 'Quae?' Discipulus: 'Nōmen, prōnōmen, verbum, {{adverbium}}, participium, coniūnctiō, praepositiō, interiectiō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"adversa","latin":"adversa, adversae","headword":"adversa","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"enemy/adversary/opponent (female)","forms":["adversa"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fortūna {{adversa}} amīcīs fīdendum nōn est!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"adversari","latin":"(adversor) adversārī","headword":"adversārī","letter":"a","pos":"","posGroup":"other","english":"oppose, resist (+ dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adversarius","latin":"adversārius, -ī","headword":"adversārius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"opponent, adversary; opponent, enemy","forms":["adversāriōrum","adversarios","adversārius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis {{adversarios}} suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adverso","latin":"adverso, adversare, adversavi, adversatus","headword":"adverso","letter":"a","pos":"verb","posGroup":"verb","english":"apply (the mind), direct (the attention)","forms":["adverso"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quinque cohortes, quas minime firmas ad dimicandum esse existimabat, castris praesidio relinquit; quinque eiusdem legionis reliquas de media nocte cum omnibus impedimentis {{adverso}} flumine magno tumultu proficisci imperat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adversor","latin":"adversor, adversari, adversatus sum","headword":"adversor","letter":"a","pos":"verb","posGroup":"verb","english":"be against (w/DAT), oppose, withstand","forms":["adversante","adversārētur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō Āfricānus {{adversārētur}} fortisque ac validus prīdiē domum sē recēpisset, mortuus in cubiculō inventus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"adversum","latin":"adversum","headword":"adversum","letter":"a","pos":"preposition","posGroup":"preposition","english":"facing, opposite, against, towards; contrary to; face to face, in presence of","forms":["adversum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caelum nūbilum suspiciēns gubernātor optat ut ventus in {{adversum}} vertātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"adversus","latin":"adversus","headword":"adversus","letter":"a","pos":"adjective","posGroup":"adjective","english":"(prp. + acc.) toward; opposed, adverse; adverse, hostile; unfavourable","forms":["adversae","adversās","adversī","adversīs","adversōs","adversus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res {{adversae}} auctoritatem minuunt, sic huius ex contrario dignitas incommodo accepto in dies augebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"adversus/-um","latin":"adversus/-um","headword":"adversus/-um","letter":"a","pos":"","posGroup":"other","english":"(prp. +acc.) toward, against","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"advertere","latin":"(advertō) advertere (< vertere)","headword":"advertere","letter":"a","pos":"","posGroup":"other","english":"turn, direct (toward)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"adverto","latin":"adverto, advertere, adverti, adversus","headword":"adverto","letter":"a","pos":"verb","posGroup":"verb","english":"turn/face to/towards; direct/draw one's attention to; steer/pilot (ship)","forms":["adverte","advertēns","advertit","advertite"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nērēides nymphaeque simul, quae vellera mōtīs\nnūlla trahunt digitīs nec fīla sequentia dūcunt,\nherbās dispōnunt sparsōsque sine ōrdine flōrēs\nsēcernunt calathīs variāsque colōribus herbās;\nipsa, quod hae faciunt, opus exigit, ipsa, quis ūsus\nquōve sit in foliō, quae sit concordia mixtīs,\nnōvit et {{advertēns}} pensās examinat herbās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"advesperascit","latin":"advesperascit, advesperascere, advesperavit, -","headword":"advesperascit","letter":"a","pos":"verb","posGroup":"verb","english":"evening is coming on, it draws toward evening; it is growing dark","forms":["advesperāsceret"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Illī autem, quī omnia dē rē pūblicā praeclārā atque ēgregiā sentīrent, sine recūsātiōne ac sine ūllā morā negōtium suscēpērunt, et, cum {{advesperāsceret}}, occultē ad pontem Mulvium pervēnērunt atque ibi in proximīs villīs ita bipertītō fuērunt ut Tiberīs inter eōs et pōns interesset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"advocare","latin":"(advocō) advocāre","headword":"advocāre","letter":"a","pos":"","posGroup":"other","english":"call, summon","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"advocata","latin":"advocata, advocatae","headword":"advocata","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"helper (female), supporter, counselor","forms":["advocata"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postero die Caesar contione {{advocata}} temeritatem cupiditatemque militum reprehendit, quod sibi ipsi iudicavissent quo procedendum aut quid agendum videretur neque signo recipiendi dato constitissent neque ab tribunis militum legatisque retineri potuissent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"advocatus","latin":"advocatus, advocati","headword":"advocatus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"counselor, advocate, professional pleader; witness, supporter, mediator","forms":["advocātī","advocātōs","advocātus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"AMPHITRYO: Blepharō, quaesō ut {{advocātus}} mī adsīs nēve abeās!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"advoco","latin":"advoco, advocare, advocavi, advocatus","headword":"advoco","letter":"a","pos":"verb","posGroup":"verb","english":"call, summon, invite, convoke, call for; call in as counsel; invoke the Gods","forms":["advocābō","Advocāns","advocat","advocātīs","advocātō","advocātur","advocāverat","advocāvī","advocāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Venit rēx Assyriōrum, et prlmum quidem hostēs eius, qul sē {{advocāverat}}, profllgāvit, sed deinde ipslus etiam rēgnum vastāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"advolo","latin":"advolo, advolare, advolavi, advolatus","headword":"advolo","letter":"a","pos":"verb","posGroup":"verb","english":"fly to, dash to (w/DAT or ad + ACC), hasten towards","forms":["advolaret","advolāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus corona militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo {{advolaret}} aut interdiu tela in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"advolvo","latin":"advolvo, advolvere, advolvi, advolutus","headword":"advolvo","letter":"a","pos":"verb","posGroup":"verb","english":"roll to/towards; fall on knees (genibus advolvor), grovel, prostrate oneself","forms":["advolvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī mercātus est sindonem, et dēpōnēns eum ē cruce, involvit sindone et posuit in monumentō, et {{advolvit}} lapidem ad ōstium monumenfī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aedes","latin":"aedēs, -is ( f.)","headword":"aedēs","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"temple, pl. house; house; temple, shrine; temple","forms":["aede","aedem","aedēs","aedi","aedibus","aedium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic impius, extēnsa in templum dextrā, ausus est minarī sē Deī {{aedem}} solō aequātūrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aedicula","latin":"aedicula, aediculae","headword":"aedicula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"small room/house/building/shrine; chapel, tomb, sepulcher; niche, closet","forms":["aediculā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Praeter- eä grande armārium in angulô vîdî, in cuius aediculā erant Larēs argenteî positī Venerisque signum marmoreum et pyxis aurea nôn pusilla, in quā barbam ipsîus Interrogāre ego ātriēnsem coepī ‘quās in mediô pictūrās habērent?’ “Îliada et Odys- sîan”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"aedificans","latin":"aedificans, aedificantis","headword":"aedificans","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"builder","forms":["aedificantem","aedificantēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum igitur suōs civēs novum Lātōnae templum {{aedificantēs}} cerneret, iīs persuadēre cōnābātur nē id facerent, nēve dēbilem illam deam duōs tantum līberōs habentem tam magnī aestimārent, nēve eam nimis multum verērentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aedificare","latin":"(aedificō) aedificāre, aedificāvisse, aedificātum","headword":"aedificāre","letter":"a","pos":"verb","posGroup":"verb","english":"build; to build","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"aedificatio","latin":"aedificatio, aedificationis","headword":"aedificatio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"house; building, edifice, group of buildings, built-up area; act of building","forms":["aedificātiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque IUdaeī, dūce Zorobabele, Hierosolymam regressī sunt, et prlma novī templī:fundāmenta iēcērunt; sed aedificātiō diū intermissa est, quia illam impediēbant vīcīnae gentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aedificatus","latin":"aedificatus, aedificata, aedificatum","headword":"aedificatus","letter":"a","pos":"adjective","posGroup":"adjective","english":"built, erected, constructed, made; created; established; improved","forms":["aedificāta","aedificātae","aedificātam","aedificātus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum vērō Apollō et Neptūnus opus magnificē perfēcissent, ā Lāomedonte petīvērunt ut pecūniam, quam pollicitus erat, daret; at tyrannus ille superbus, etsī stupuit cum pulcherrima et validissima moenia tam brevī tempore {{aedificāta}} esse vīdisset, negāvit sē tantum pretium solūtūrum esse, eōsque indignīs verbīs reprehēnsōs dīmīsit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aedificium","latin":"aedificium, -ī","headword":"aedificium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"building","forms":["aedificia","aedificiī","aedificiis","aedificiorum","aedificium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Pabulum secari non posse; necessario dispersos hostes ex {{aedificiis}} petere; hos omnes cotidie ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aedifico","latin":"aedifico, aedificare, aedificavi, aedificatus","headword":"aedifico","letter":"a","pos":"verb","posGroup":"verb","english":"build, erect, construct, make; create; establish; improve; edify","forms":["aedificābant","aedificābat","aedificanda","aedificandī","aedificandīs","aedificandōs","aedificandum","aedificant","aedificāre","aedificārētur","aedificātum","aedificātur","aedificāverat","aedificāvērunt","aedificāvistī","aedificāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Salomōn templum immēnsī operis Hierosolymae {{aedificāvit}}: omnia aurō, argentō, gemmīsque in eō fulgēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aedilicius","latin":"aedīlicius, -ī (m.)","headword":"aedīlicius","letter":"a","pos":"adjective","posGroup":"adjective","english":"exaedile; of aedile rank","forms":["aedīliciōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cōnsūmpsērunt ultrā centum quīnquāgintā mīlia hominum, virōs cōnsulārēs quattuor et vīgintī, praetōriōs septem, {{aedīliciōs}} sexāgintā, senātōrēs ferē ducentōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aedilis","latin":"aedīlis, -is (m.)","headword":"aedīlis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"aedile (magistrate)","forms":["aedīlēs","aedīlis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Cum igitur essem in plūrimīs causīs et in prīncipibus patrōnīs quīnquennium ferē versātus, tum in patrōciniō Siculēnsī maximum in certāmen vēnī dēsignātus {{aedīlis}} cum dēsignātō cōnsule Hortēnsio.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aedilitas","latin":"aedīlitās, -ātis ( f.)","headword":"aedīlitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"aedileship","forms":["aedīlitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Scīpiō Aemiliānus, cum {{aedīlitātem}} peteret, cōnsul ā populō dictus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aedis","latin":"aedis, aedis","headword":"aedis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"temple, shrine; tomb; apartment, room; house (pl.), abode/dwelling; household","forms":["aedis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et mūrō lapideō, cuius operis exōrdium Sabīnō bellō turbātum erat, urbem cingere parat, et īnfima urbis loca circā forum aliāsque convallēs collibus interiectās cloācīs in Tiberim ductīs siccat, et {{aedis}} in Capitōliō Iovis, quam vōverat bellō Sabīnō, fundāmenta iacit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aeduus","latin":"Aeduus, Aedui","headword":"Aeduus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aedui (pl.); (also Haedui)","forms":["Aedui","Aeduis","Aeduorum","Aeduos","Aeduus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eius adventu Bituriges ad {{Aeduos}}, quorum erant in fide, legatos mittunt subsidium rogatum, quo facilius hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aeetes","latin":"Aeētēs, -ae","headword":"Aeētēs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aeetes (king of Colchis)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aeger","latin":"aeger, -gra, -grum","headword":"aeger","letter":"a","pos":"adjective","posGroup":"adjective","english":"sick, ill; ill, sick","forms":["aeger","aegerrimē","aegra","aegram","aegrī","aegrior","aegriōrēs","aegrīs","aegrius","aegrō","aegrōs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hōc modō pēs {{aeger}} nōn sānātur.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aegeus","latin":"Aegēus, -eī","headword":"Aegēus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aegeus, king of Athens","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aegides","latin":"Aegīdēs, -ae","headword":"Aegīdēs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"son of Aegeus, Theseus","forms":["Aegīdēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Aegīdēs}} Procrusten in eōdem lectō necāvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aegis","latin":"aegis, aegidis","headword":"aegis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"aegis (Minerva's shield); shield, defense; wood nearest pith, heartwood","forms":["Aegīdem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Aliī {{Aegīdem}} rogāvērunt ut auxilium daret, imprīmīs septem prīncipēs quī bellum contrā Thēbānōs gessērunt, quōrum rēx Creōn eōs vetuerat corpora interfectorum humāre.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aegre","latin":"aegrē","headword":"aegrē","letter":"a","pos":"adverb","posGroup":"adverb","english":"with pain, unwillingly","forms":["aegrē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dōna Abēlīs placuērunt deō, nōn autem dōna Caīnī; quod Caīnus aegrē tulit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aegritudo","latin":"aegritudo, aegritudinis","headword":"aegritudo","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"sickness, disease, grief, sorrow; affliction, anxiety; melancholy","forms":["aegritūdine"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pater eius autem, postquam puerum perdidit, animum dēspondit, eāque is {{aegritūdine}} paucīs diēbus post Tarentī ēmortuus est.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aegrotas","latin":"aegrotas, aegrotatis","headword":"aegrotas","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"illness, sickness","forms":["aegrōtās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Pater vērō, cubiculum ingressus, fīlium colōrem mūtāvisse animadvertit et “Quid pallēs, fīlī?” inquit “Utrum {{aegrōtās}} an territus es?” Fīlius autem id, quod Apollō dīxerat, patrī nārrāvit, eumque rogāvit, ut prō sē ad illud rēgnum dēscenderet, ubi umbrae mortuōrum versārī dīcuntur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aegrotat","latin":"aegrōtat, aegrōtāre","headword":"aegrōtat","letter":"a","pos":"verb","posGroup":"verb","english":"be ill; is ill, is sick","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aegroto","latin":"aegroto, aegrotare, aegrotavi, aegrotatus","headword":"aegroto","letter":"a","pos":"verb","posGroup":"verb","english":"be sick; be distressed/mentally/morally ill, be afflicted, languish, grieve","forms":["aegrōtāns","Aegrōtante","aegrōtantem","aegrōtantī","aegrōtārent","aegrōtat","aegrōtō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Medicus: “Pēs tantum {{aegrōtat}}.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aegrotus","latin":"aegrōtus, -a, -um","headword":"aegrōtus","letter":"a","pos":"adjective","posGroup":"adjective","english":"sick; sick, ill","forms":["aegrōtus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Puer {{aegrōtus}} iterum iterumque super lectum sē convertit nec dormīre potest, sīve in latere dextrō cubat sīve in latere sinistrō.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aegrum","latin":"aegrum, aegri","headword":"aegrum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"diseased part of the body; diseased state; grief, feeling of distress; pain","forms":["aegrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Aemilia abit ad fīlium suum {{aegrum}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aegyptius","latin":"Aegyptius, Aegyptii","headword":"Aegyptius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Egyptian, inhabitant of Egypt; Egyptian sage/prophet","forms":["Aegyptiī","Aegyptiīs","Aegyptiōrum","Aegyptiōs","Aegyptius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Putiphar {{Aegyptius}} emit Iōsēphum ā mercātōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aegyptus","latin":"Aegyptus, Aegypti","headword":"Aegyptus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Egypt","forms":["Aegyptī","Aegyptō","Aegyptum","Aegyptus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus: “Ubi est {{Aegyptus}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aemilius","latin":"Aemilius, Aemilia, Aemilium","headword":"Aemilius","letter":"a","pos":"adjective","posGroup":"adjective","english":"Aemilian; of Aemilius gens","forms":["Aemilia","Aemiliae","Aemiliam","Aemiliī","Aemiliō","Aemilium","Aemilius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dēlia: “Domina mea est {{Aemilia}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aemula","latin":"aemula, aemulae","headword":"aemula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"rival (female); woman who strives to equal/exceed; rival in love; rival city","forms":["aemula"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sub-esse — clam adesse et, sī nūlla subest {{aemula}},","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aemulus","latin":"aemulus, aemula, aemulum","headword":"aemulus","letter":"a","pos":"adjective","posGroup":"adjective","english":"envious, jealous, grudging, (things) comparable/equal (with/to)","forms":["aemulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Is, fratemae virtiitis {{aemulus}}, B acchidem plūribus proeliīs vīcit, illumque ad petendam pācem adēgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aena","latin":"aena, aenae","headword":"aena","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"card/comb used in treating of cloth/fibers","forms":["aēna"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"lītore {{aēna}} locant aliī, flammāsque ministrant.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"aeneas","latin":"Aeneas, Aeneae","headword":"Aeneas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aeneas; (Trojan hero, son of Venus and Anchises; founder of Roman race)","forms":["Aenēān","aēneās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Excipit {{Aenēān}} illīc animōque domōque\nnōn bene discidium Phrygiī lātūra marītī\nSīdōnis; inque pyram sacrī sub imāgine factā\nincubuit ferrō dēceptaque dēcipit omnēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aeneius","latin":"Aeneius, Aeneia, Aeneium","headword":"Aeneius","letter":"a","pos":"adjective","posGroup":"adjective","english":"Aeneian; of/relating to Aeneas","forms":["Aenēia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iamque deōs omnēs ipsamque {{Aenēia}} virtūs\nIūnōnem veterēs fīnīre coēgerat īrās,\ncum, bene fundātīs opibus crēscentis Iūlī,\ntempestīvus erat caelō Cythēreius hērōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aeneum","latin":"aeneum, aenei","headword":"aeneum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"vessel made of copper/bronze; brazen vessel; kettle, pot, cauldron","forms":["aēneum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"At ille sustulit phialam dē terrā: collîsa erat tamquam vāsum {{aēneum}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"aeneus","latin":"aēneus, -a, -um","headword":"aēneus","letter":"a","pos":"adjective","posGroup":"adjective","english":"of bronze/copper; brass, bronze, brazen; of bronze","forms":["aēneā","Aenēae","Aenēam","Aenēis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum ex galeā aēneā dentēs serpentis excēpit ut eōs in agrōs spargeret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aenum","latin":"aēnum, -ī","headword":"aēnum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"brass pot, cauldron","forms":["aēnīs","aēnō","aēnum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā aēnō in igne positō medicāmen validum fervet et albet spūmīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aeolus","latin":"Aeolus, -ī","headword":"Aeolus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aeolus, king of the winds","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aequabilis","latin":"aequābilis, -e","headword":"aequābilis","letter":"a","pos":"","posGroup":"other","english":"equal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aequabilitas","latin":"aequābilitās, -tātis ( f.)","headword":"aequābilitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"equality; evenness, equality","forms":["aequābilitās","aequābilitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed et in rēgnīs nimis expertēs sunt cēterī commūnis iūris et cōnsiliī; et in optimātium dominātū vix particeps lībertātis potest esse multitūdō, cum omnī cōnsiliō commūnī ac potestāte careat; et cum omnia per populum geruntur, quamvīs iūstum atque moderātum, tamen ipsa {{aequābilitās}} est inīqua, cum habet nūllōs gradūs dignitātis...'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aequabiliter","latin":"aequabiliter, aequabilitius, aequabilitissime","headword":"aequabiliter","letter":"a","pos":"adverb","posGroup":"adverb","english":"uniformly, equally; in equal proportions/a regular manner; smoothly; justly","forms":["aequābiliter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīc' inquam 'quis est quī complet aurēs meās tantus et tam dulcis sonus?' 'Hic est' inquit Āfricānus 'ille quī intervāllīs coniūnctus imparibus, sed tamen prō ratā parte ratiōne distīnctīs, impulsū et mōtū ipsōrum orbium efficitur, et acūta cum gravibus temperāns variōs {{aequābiliter}} concentūs efficit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aequalis","latin":"aequālis, -is (m./f.)","headword":"aequālis","letter":"a","pos":"adjective","posGroup":"adjective","english":"person of the same age","forms":["aequālia","aequalibus","aequālium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Roboāmus {{aequālium}} cōnsiliō ūsus, populō acerbē respondit, eiusque postulātiōnem reiēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aequaliter","latin":"aequaliter, aequalitius, aequalitissime","headword":"aequaliter","letter":"a","pos":"adverb","posGroup":"adverb","english":"evenly, alike, uniformly; equally, to an equal measure/extent; symmetrically","forms":["aequāliter"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Deinde, ut quisque voluntārius aut ex sociīs in castra vēnerat, {{aequāliter}} distribuerat, ac brevī spatiō legiōnēs numerō hominum explēverat, cum initiō nōn amplius duōbus mīlibus habuisset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"aequare","latin":"(aequō) aequāre","headword":"aequāre","letter":"a","pos":"","posGroup":"other","english":"make equal, equal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aeque","latin":"aequē","headword":"aequē","letter":"a","pos":"adverb","posGroup":"adverb","english":"equally","forms":["aequē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Expalluit aequē","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aequinoctium","latin":"aequinoctium, -ī","headword":"aequinoctium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"equinox","forms":["aequinoctium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ante diem octāvum kalendās Aprīlēs (id est diē octāvō ante kalendās Aprīlēs) nox atque diēs aequī sunt; is diēs \"{{aequinoctium}}\" dīcitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aequo","latin":"aequo, aequare, aequavi, aequatus","headword":"aequo","letter":"a","pos":"verb","posGroup":"verb","english":"level, make even/straight; equal; compare; reach as high or deep as","forms":["aequābant","aequābat","aequābit","aequārētur","aequātam","aequātīs","aequātum","aequātūrum","aequātus","aequāvit","aequet","aequō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Adspice caelum; dīnumerā stēllās, sī potes; tua prōgeniēs eās {{aequābit}} numerō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aequor","latin":"aequor, -ŏris (n.)","headword":"aequor","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"level surface, sea; level surface; the sea; sea, plain; sea, level surface","forms":["aequor","aequora","aequore","aequoris"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec poena dīlāta foret, nisi saevī ventī fēcissent {{aequora}} invia et tellūs Aulide puppēs tenuisset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aequoreus","latin":"aequoreus, aequorea, aequoreum","headword":"aequoreus","letter":"a","pos":"adjective","posGroup":"adjective","english":"of/connected with the sea, situated near/bordering on/surrounded by the sea","forms":["aequorea","aequoreās","aequoreīs","aequoreus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tunc tener {{aequorea}} mergitur","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aequum","latin":"aequum, aequi","headword":"aequum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"level ground; equal footing/terms; what is right/fair/equitable, equity","forms":["aequum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ubi neminem in {{aequum}} locum sese demittere sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aequus","latin":"aequus, -a, -um","headword":"aequus","letter":"a","pos":"adjective","posGroup":"adjective","english":"equal, calm; fair, just; equal","forms":["aequa","aequae","aequam","aequās","aequī","aequiore","aequiōrem","aequiōribus","aequīs","aequissimas","Aequōrum","Aequōs","aequus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Erat Romanis nec loco nec numero {{aequa}} contentio; simul et cursu et spatio pugnae defatigati non facile recentes atque integros sustinebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aer","latin":"āēr, āeris","headword":"āēr","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) air","forms":["āēr"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Aemilius: “Cum sōl lūcet, nimis calidus est āēr in hortō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aera","latin":"aera, aerae","headword":"aera","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"|parameter from which a calculation is made; item of account; era/epoch","forms":["āera"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nātūra nēminī dēdit sōlem, nec āera, nec aquam: dōna sunt omnibus commūnia.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aerarium","latin":"aerārium, -ī","headword":"aerārium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"state treasury; treasury","forms":["aerāriī","aerāriō","aerārium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aedēs Sāturnī est {{aerārium}} populī Rōmānī, id est locus ubi pecūnia pūblica dēpōnitur ac servātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aeratus","latin":"aerātus, -a, -um","headword":"aerātus","letter":"a","pos":"adjective","posGroup":"adjective","english":"fitted with bronze","forms":["aerātā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accipit aerātā iuvenem Collātia portā, condere iam vultūs sōle parante suōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aereus","latin":"aereus, -a, -um","headword":"aereus","letter":"a","pos":"adjective","posGroup":"adjective","english":"of bronze/copper","forms":["āerea","āereās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Lōrīcā induebātur; ocreās in crūribus āereās habēbat; cassis āerea caput eius operiēbat, et clipeus aureus tegēbat umerōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aerius","latin":"aerius, aeria, aerium","headword":"aerius","letter":"a","pos":"adjective","posGroup":"adjective","english":"of/produced in/existing in/flying in air, airborne/aerial; towering, airy; blue","forms":["āerius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec ego moneor |āerius -ā -um «āēr","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aerumna","latin":"aerumna, aerumnae","headword":"aerumna","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"toil, task, labor; hardship, trouble, affliction, distress, calamity","forms":["aerumnārum","aerumnās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sî factum nôn est, nihil est!” Haec aliaque cum efiîlsissimïs prôsequerëmur laudätiô- nibus, “Rogô” inquit, “Agamemnôn mihi cārissime, num- quid duodecim {{aerumnās}} Herculis tenēs, aut dē Ulixe täbulam quemadmodum illî Cyclôps pollicem extorsit?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"aes","latin":"aes, aeris (n.)","headword":"aes","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"copper, bronze, money","forms":["aere","aeri","āeris","aes"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quīntō diē, avēs quae volitant in {{aere}}, et piscēs quī natant in aquīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aesculetum","latin":"aesculētum, -ī","headword":"aesculētum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"oak forest","forms":["aesculētīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"quāle portentum neque mīlitāris / Daunias lātīs alit {{aesculētīs}} / nec Iubae tellūs generat, leōnum / ārida nūtrīx.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aeson","latin":"Aesōn, -onis","headword":"Aesōn","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aeson (father of Jason)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aesonides","latin":"Aesonīdēs, -ae","headword":"Aesonīdēs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Jason, son of Aeson","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aesopus","latin":"Aesopus, Aesopi","headword":"Aesopus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aesop (Greek author of fables); (Roman tragic actor contemporary with Cicero)","forms":["Aesōpī","Aesōpus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Aesōpus}} appellātur Graecus auctor fābulārum dē bēstiīs itemque dē hominum nātūrā et mōribus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aestas","latin":"aestās, aestātis","headword":"aestās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) summer","forms":["aestās","aestāte","aestātem","aestatis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat in magnis Caesari difficultatibus res, ne maiorem {{aestatis}} partem flumine impediretur, quod non fere ante autumnum Elaver vado transiri solet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aestimare","latin":"(aestimō) aestimāre, -āvisse, -ātum","headword":"aestimāre","letter":"a","pos":"","posGroup":"other","english":"value, estimate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"aestimat","latin":"aestimat","headword":"aestimat","letter":"a","pos":"verb","posGroup":"verb","english":"values, reckons","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aestimo","latin":"aestimo, aestimare, aestimavi, aestimatus","headword":"aestimo","letter":"a","pos":"verb","posGroup":"verb","english":"value, assess; estimate; reckon; consider, judge (situation); esteem","forms":["aestimābat","aestimāns","aestimant","aestimantur","aestimare","aestimārent","aestimāret","aestimārī","aestimās","aestimāvērunt","aestimāvit","aestimemus","aestimō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius {{aestimare}}, liberos, coniuges in servitutem abstrahi, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aestivus","latin":"aestīvus, -a, -um","headword":"aestīvus","letter":"a","pos":"adjective","posGroup":"adjective","english":"of summer","forms":["aestīvā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Pōne mē pigrīs ubi nūlla campīs / arbor aestīvā recreātur aurā, / quod latus mundī nebulae malusque / Iuppiter urget;","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aestuo","latin":"aestuo, aestuare, aestuavi, aestuatus","headword":"aestuo","letter":"a","pos":"verb","posGroup":"verb","english":"boil, seethe, foam; billow roll in waves; be agitated/hot; burn; waver","forms":["aestuābat"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tulliō Cicerōnī — namque anteā plēraque nōbilitās invidiā {{aestuābat}} et quasi polluī cōnsulātum crēdēbant, sī eum quamvīs ēgregius homō novus adeptus foret.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"aestuosus","latin":"aestuōsus, -a, -um","headword":"aestuōsus","letter":"a","pos":"adjective","posGroup":"adjective","english":"sweltering, seething","forms":["aestuōsās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sīve per Syrtēs iter {{aestuōsās}} / sīve factūrus per inhospitālem / Caucasum vel quae loca fābulōsus / lambit Hydaspēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aestus","latin":"aestus, aestus","headword":"aestus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"agitation, passion, seething; raging, boiling; heat/fire; sea tide/spray/swell","forms":["aestū","aestūs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aspicit accēnsum nec tantōs sustinet {{aestūs}}:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aetas","latin":"aetās, aetātis","headword":"aetās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) age; age, time of life","forms":["aetās","aetate","aetatem","aetātibus","aetātis","aetātum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sic et Cenabi caede et labore operis incitati non {{aetate}} confectis, non mulieribus, non infantibus pepercerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aeterno","latin":"aeternō","headword":"aeternō","letter":"a","pos":"adverb","posGroup":"adverb","english":"eternally, forever","forms":["aeternō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"\"Pendē aeternō,\" dīxit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aeternum","latin":"aeternum","headword":"aeternum","letter":"a","pos":"adverb","posGroup":"adverb","english":"forever","forms":["aeternum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pān dīxit: “{{Aeternum}} tē amābō.” Syringa autem dīxit: “Aeternum nympha Diānae erō.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aeternus","latin":"aeternus, -a, -um","headword":"aeternus","letter":"a","pos":"adjective","posGroup":"adjective","english":"eternal, everlasting","forms":["aeternā","Aeternae","aeternam","aeternās","aeternīs","aeternus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Romani vero quid petunt aliud aut quid volunt, nisi invidia adducti, quos fama nobiles potentesque bello cognoverunt, horum in agris civitatibusque considere atque his {{aeternam}} iniungere servitutem?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aether","latin":"aethēr, -eris (m.)","headword":"aethēr","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"heaven, upper air, ether","forms":["aether","aethera","aethere","aetheri"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ut vērō summō dēspexit ab {{aethere}} terrās īnfēlīx Phaethōn penitus penitusque iacentēs, palluit et subitō genua intremuēre timōre suntque oculīs tenebrae per tantum lūmen obortae, et iam māllet equōs numquam tetigisse paternōs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aetherius","latin":"aetherius, aetheria, aetherium","headword":"aetherius","letter":"a","pos":"adjective","posGroup":"adjective","english":"ethereal, heavenly, divine, celestial; of the upper atmosphere; aloft; lofty","forms":["aetheriā","aetheriās","aetheriīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Curribus in ōrās {{aetheriās}} exit: ibi ante Iovem capillīs passīs stetit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aethiopia","latin":"Aethiopia, Aethiopiae","headword":"Aethiopia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Ethiopia; present day Sudan; inland central Africa","forms":["Aethiopiam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Spectāte terrās in Āfricā: Maurītāniam, Numidiam, Libyam, {{Aethiopiam}}, Aegyptum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aethiops","latin":"Aethiops, Aethiopis","headword":"Aethiops","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Ethiopian, inhabitant of \"Ethiopia\"/Sudan; negro/black man; black slave","forms":["Aethiops","Aethiopum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eī dīcit in aurem aut ‘ut domī lectulī sternantur’, aut ‘ab avunculō rogētur {{Aethiops}}, quī ad balneās veniat’, aut ‘asturcōnī locus ante ōstium suum dētur’, aut aliquod fragile falsae chorāgium glōriae comparetur!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aethra","latin":"Aethra, -ae","headword":"Aethra","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Aethra, princess of Troezen","forms":["Aethra","Aethrae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Aethra}}, fīlia rēgis Troezēniī, erat māter eī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aevum","latin":"aevum, -ī","headword":"aevum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"lifetime, life; age, everlasting time","forms":["aevō","aevum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sustinet) et longō facite ut nārrēmur in aevō!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"afer","latin":"Afer, Afri","headword":"Afer","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"African; inhabitant of north coast of Africa (except Egypt); Carthaginian","forms":["Āfrī","Āfrīs","Āfrōrum","Āfrōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et contrā {{Afrōs}} bellum susceptum est prīmum Ap.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"affectare","latin":"(affectō) affectāre","headword":"affectāre","letter":"a","pos":"","posGroup":"other","english":"strive after, aspire to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"affecto","latin":"affecto, affectare, affectavi, affectatus","headword":"affecto","letter":"a","pos":"verb","posGroup":"verb","english":"aim at, desire, aspire, try, lay claim to; try to control; feign, pretend","forms":["affectandī","affectāre","affectāvit","affectō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Absalōn, fīlius Davidis, paternum rēgnum {{affectāvit}}: concitātā multitūdine imperītā, adversus patrem rebellāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"affectus","latin":"affectus, -ūs","headword":"affectus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) mood, feeling; feeling, emotion","forms":["affecta","affectam","affectī","affectōs","affectum","affectus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eurydicē, cum prīmum hoc animadvertit, tantō illīus virī metū {{affecta}} est, ut, omnia perīcula oblīta, per altās herbās et inter dūra saxa nūdīs pedibus celerrimē curreret, ut ab eō fugeret et ad Orphēum, marītum suum amārissimum, redīret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"affero","latin":"afferō, afferre, attulī, allātum","headword":"afferō","letter":"a","pos":"verb","posGroup":"verb","english":"bring to, bring","forms":["affer","afferant","afferat","afferēbāmus","afferēbantur","afferēbat","afferēns","afferent","afferō","afferre","afferrent","afferret","afferrī","affers","affert","Afferte","affertō","affertur","afferunt","afferuntur","allāta","allātae","allato","allātum","allātūrum","allātus","attulerant","attulerat","attuleris","attulerit","attulērunt","attulisset","attulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qui tum primum {{allato}} nuntio de oppugnatione Vellaunoduni, cum longius eam rem ductum iri existimarent, praesidium Cenabi tuendi causa quod eo mitterent comparabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"affert","latin":"affert, afferre","headword":"affert","letter":"a","pos":"","posGroup":"other","english":"bring (to, forward)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"afficere","latin":"(afficiō) afficere, affēcisse, affectum","headword":"afficere","letter":"a","pos":"","posGroup":"other","english":"affect, stir","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"afficio","latin":"afficio, afficere, affeci, affectus","headword":"afficio","letter":"a","pos":"verb","posGroup":"verb","english":"affect, make impression; move, influence; cause (hurt/death), afflict, weaken","forms":["affēcērunt","affēcissent","affēcit","afficere","afficerentur","afficeret","afficerētur","afficiam","afficiātur","afficiēbant","afficiēbātur","afficiendōs","afficiendum","afficiēris","afficiet","afficiētur","afficit","afficitur","afficiuntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dīxit etiam mulierī: {{afficiam}} tē multīs malīs; pariēs līberōs in dolōre, et eris in potestāte virī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"affigo","latin":"affīgō, -ere, affīxī, affīxum","headword":"affīgō","letter":"a","pos":"verb","posGroup":"verb","english":"fasten, pin to (+ dat.)","forms":["affīget","affigī","affīxam","affīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et {{affīget}} ad pālum, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"affingere","latin":"(affingō) affingere (< fingere)","headword":"affingere","letter":"a","pos":"","posGroup":"other","english":"add, fabricate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"affingo","latin":"affingo, affingere, affinxi, affictus","headword":"affingo","letter":"a","pos":"verb","posGroup":"verb","english":"add to, attach; aggravate; embellish, counterfeit, forge; claim wrongly","forms":["afficta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed dē Lūcullō dīcam aliō locō, et ita dīcam, Quirītēs, ut neque vēra laus eī dētrācta ōrātiōne meā neque falsa {{afficta}} esse videātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"affinis","latin":"affinis, affinis, affine","headword":"affinis","letter":"a","pos":"adjective","posGroup":"adjective","english":"neighboring, adjacent, next, bordering; related (marriage), akin, connected","forms":["affīnēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Māter nostra ūnā mēcum precātur ‘nē ego propinquōs et {{affīnēs}}, dēnique gentem nostram dēserere et prōdere quam līberāre mālim!’” Flāvus, īrātus: “Date arma et equum!” sed Stertinius accurrēns eum attinuit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"affirmare","latin":"(affirmō) affirmāre, affirmāvisse,  affirmātum","headword":"affirmāre","letter":"a","pos":"verb","posGroup":"verb","english":"assert, affirm; to affirm, assert","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"affirmo","latin":"affirmō, -āre","headword":"affirmō","letter":"a","pos":"verb","posGroup":"verb","english":"affirm, assert","forms":["Affirmābant","affirmabat","affirmandī","affirmāns","affirmāre","affirmat","affirmāvērunt","affirmāvisset","affirmāvit","affirmet","affirmō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quem Antiochus coepit illicere ut lēgem dēsereret, {{affirmāns}} eum dīvitem fore et beātum; sed adulēscēns nec minīs movēbātur, nec prōmissīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"afflicto","latin":"afflicto, afflictare, afflictavi, afflictatus","headword":"afflicto","letter":"a","pos":"verb","posGroup":"verb","english":"shatter, damage, strike repeatedly, buffet, wreck; oppress, afflict; vex","forms":["afflīctantur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ut saepe hominēs aegrī morbō gravī, cum aestū febrīque iactantur, sī aquam gelidam bibērunt, prīmō relevārī videntur, deinde multō gravius vehementiusque {{afflīctantur}}, sīc hic morbus quī est in rē pūblicā, relevātus istīus poenā, vehementius reliquīs vīvīs ingravēscet.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"afflictus","latin":"afflictus, afflicta, afflictum","headword":"afflictus","letter":"a","pos":"adjective","posGroup":"adjective","english":"in a state of ruin (persons/countries/affairs), shattered","forms":["afflīctae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam hōc ferē sīc fierī solēre accēpimus, ut rēgum {{afflīctae}} fortūnae facile multōrum opēs alliciant ad misericordiam, maximēque eōrum quī aut rēgēs sunt aut vīvunt in rēgnō, ut iīs nōmen rēgāle magnum et sānctum esse videātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"affligere","latin":"(afflīgō) afflīgere, -ixisse, -ictum","headword":"afflīgere","letter":"a","pos":"","posGroup":"other","english":"cast down, deject, afflict","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"affligo","latin":"affligo, affligere, afflixi, afflictus","headword":"affligo","letter":"a","pos":"verb","posGroup":"verb","english":"overthrow/throw down; afflict, damage, crush, break, ruin; humble, weaken, vex","forms":["afflīctum","afflīgerentur","afflīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum Hebraeī in potestāte essent Philistaeōrum, et ab illīs {{afflīgerentur}}, nātus est Samsōn, futūrus ultor hostium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"affluens","latin":"affluens, affluentis (gen.), affluentior -or -us, affluentissimus -a -um","headword":"affluens","letter":"a","pos":"adjective","posGroup":"adjective","english":"flowing/overflowing/abounding with; abundant, plentiful, sumptuous, copious","forms":["affluēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēgnābat Salomōn in summā pāce, opibus et dēliciīs {{affluēns}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"affluere","latin":"(affluō) affluere (< fluere)","headword":"affluere","letter":"a","pos":"","posGroup":"other","english":"flow near","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"affor","latin":"affor, affari, affatus sum","headword":"affor","letter":"a","pos":"verb","posGroup":"verb","english":"speak to, address; be spoked to/addressed (PASS), be decreed by fate","forms":["affēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iūdās respondit: fateor, rēs est manifēsta; nūllam possumus excūsātiōnem {{affēre}}, nec audēmus petere veniam aut spērāre; nōs omnēs erimus servī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"afranius","latin":"Afranius, Afrani","headword":"Afranius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Afranius; (Roman gens name)","forms":["Afrāniō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi Pompēī exercitūs validissimōs et fortissimōs cum tribus ducibus, Afrāniō, M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"africa","latin":"Āfrica, -ae","headword":"Āfrica","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Africa","forms":["Āfricā","Āfricae","Āfricam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlia: “Aegyptus in Āfricā est — sed Barabia est in Asiā.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"africanus","latin":"Africanus, Africana, Africanum","headword":"Africanus","letter":"a","pos":"adjective","posGroup":"adjective","english":"African; from/of Africa; plants/animals from Africa","forms":["Āfricāne","Āfricānī","Āfricānō","Āfricānum","Āfricānus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēlium Scīpiōnem prōtēxit fīlius, quī 'Āfricānī' posteā nōmen accēpit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"africus","latin":"Āfricus, -ī","headword":"Āfricus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"southwest wind; south-west wind","forms":["Āfricō","Āfricus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aeolus, ubi haec audīvit, cavum montem hastā impellit, ac ventī velut agmine factō ex antrō ruunt: Eurus Notusque et {{Africus}} terrās mariaque turbant et vastōs fluctūs ad lītora volvunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"agamemnon","latin":"Agamemnon, Agamemnonis","headword":"Agamemnon","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Agamemnon; (king of Mycenae, leader of Greeks at Troy)","forms":["Agamemnon","Agamemnonem","Agamemnonis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī Danai Iphigeniam {{Agamemnonis}} fīliam sacrificāverint, ventī ratēs movēbunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"agamemnonius","latin":"Agamemnonius, Agamemnonia, Agamemnonium","headword":"Agamemnonius","letter":"a","pos":"adjective","posGroup":"adjective","english":"Agamemnonian; of/relating to Agamemnon","forms":["Agamemnōniae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Chalcide Aulidem trāicit, trium mīlium spatiō distantem, portum inclūtum statiōne quondam mīlle nāvium {{Agamemnōniae}} classis, Diānaeque templum vīsit, ubi nāvibus cursum ad Troiam, fīliā victimā ārīs admōtā, rēx ille rēgum petiit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"agamus","latin":"agamus, agama, agamum","headword":"agamus","letter":"a","pos":"adjective","posGroup":"adjective","english":"unmarried","forms":["agāmus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quārē sī, ut ista nōn disserantur, līberārī mortis metū possumus, id {{agāmus}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"agathyrsus","latin":"Agathyrsus, Agathyrsi","headword":"Agathyrsus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Agathyrsian; (Scythian people who painted their bodies)","forms":["Agathyrsī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Crētēsque Dryopēsque fremunt pictīque Agathyrsī;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"age","latin":"age","headword":"age","letter":"a","pos":"interjection","posGroup":"interjection","english":"come!, go to!, well!, all right!; let come","forms":["age"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mēdus: “{{Age}}, discēde, Dāve — et tacē!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"age! / agite","latin":"age! / agite!","headword":"age! / agite","letter":"a","pos":"interjection","posGroup":"interjection","english":"come! come on!","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"agedum","latin":"agedum","headword":"agedum","letter":"a","pos":"interjection","posGroup":"interjection","english":"come!, go to!, well!, all right!","forms":["Agedum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: {{Agedum}}, exsolve cistulam!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"agenda","latin":"agenda, agendae","headword":"agenda","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"ritual; what must be done; agenda","forms":["agenda","agendae","agendam","agendum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caesar ex eo loco quintis castris Gergoviam pervenit equestrique eo die proelio levi facto, perspecto urbis situ, quae posita in altissimo monte omnes aditus difficiles habebat, de expugnatione desperavit; de obsessione non prius {{agendum}} constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"agens","latin":"agens, agentis","headword":"agens","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"advocate, pleader; secret police (pl.) (frumentarii/curiosi); land surveyors","forms":["agēns","agente","agentem","agentēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn sōlum nūllum ā mē maleficium patiēris, sed etiam rēgnābis mēcum apud Īnferōs, neque misera erit vīta tua: ego enim tē tam multum amō, ut tantum laetitia animum tuum afficere cupiam.” Hīs verbīs Plūtō perterritam virginem cōnsōlātus est; {{agēns}} deinde currum, equīs celeriter currentibus, ad locum pervēnit, ubi terrā, scēptrō percussa, sē aperuit ut iīs viam ad Īnferōs faceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ager","latin":"ager, agrī","headword":"ager","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"field","forms":["ager","agri","agris","agrō","agrōrum","agros","agrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per {{agros}} regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"agger","latin":"agger, -eris (m.)","headword":"agger","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"rampart","forms":["agger","aggere","aggerem","aggeres","aggeri","aggeris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut supra diximus, angustum habebat, {{aggerem}} apparare, vineas agere, turres duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aggero","latin":"aggero, aggerare, aggeravi, aggeratus","headword":"aggero","letter":"a","pos":"verb","posGroup":"verb","english":"heap/fill up, bring, carry; increase, add fuel; push/crowd/press together","forms":["aggerat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"incenditque animum dictīs atque {{aggerat}} īrās.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"aggredi","latin":"(aggredior) aggredī, aggressum","headword":"aggredī","letter":"a","pos":"","posGroup":"other","english":"attack, set about, try","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aggredior","latin":"aggredior, aggredi, aggressus sum","headword":"aggredior","letter":"a","pos":"verb","posGroup":"verb","english":"approach, advance; attack, assail; undertake, seize (opportunity), attempt","forms":["aggredī","aggrediantur","aggrediāris","aggrediminī","aggredimur","aggreditur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō {{aggrediāris}}?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aggressus","latin":"aggressus, aggressus","headword":"aggressus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"attack, assault","forms":["aggressus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iosue dīvīnō auxiliō frētus, nōn armīs aut vīribus urbem {{aggressus}} est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"agit/agunt","latin":"agit/agunt","headword":"agit/agunt","letter":"a","pos":"","posGroup":"other","english":"drive, do, perform","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"agitare","latin":"(agitō) agitāre","headword":"agitāre","letter":"a","pos":"","posGroup":"other","english":"move, stir, plan","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"agitatus","latin":"agitatus, agitata -um, agitatior -or -us, agitatissimus -a -um","headword":"agitatus","letter":"a","pos":"adjective","posGroup":"adjective","english":"agile, animated, brisk","forms":["agitātae","agitātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Multa praetereō cōnsultō; sed ea vōs coniectūrā perspicite: quantum illud bellum factum putētis quod coniungant rēgēs potentissimī, renovent {{agitātae}} nātiōnēs, suscipiant integrae gentēs, novus imperātor noster accipiat vetere exercitū pulsō!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"agite","latin":"agite","headword":"agite","letter":"a","pos":"interjection","posGroup":"interjection","english":"come!, go to!, well!, all right!","forms":["agite"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Agite}}, Syre et Lēander, lectīcam portāte!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"agito","latin":"agito, agitare, agitavi, agitatus","headword":"agito","letter":"a","pos":"verb","posGroup":"verb","english":"stir/drive/shake/move about; revolve; live; control, ride; consider, pursue","forms":["agitābant","agitābantur","agitābat","agitābātur","agitandō","agitantēs","agitantī","agitantur","agitāre","agitat","agitatis","agitātur","agitāvī","agitāvisse"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus {{agitatis}}, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"agmen","latin":"agmen, agminis","headword":"agmen","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(n.) army on the march, file; marching column","forms":["agmen","āgmina","agmine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, centurionibus et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium procul visus est, qui {{agmen}} Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"agna","latin":"agna, -ae","headword":"agna","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"ewe lamb","forms":["agna"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"agnus-Ipmy {{agna}}-ae/ € Ā -& utque fugit vīsōs agna","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"agnos","latin":"agnos, agni","headword":"agnos","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"chaste-tree (vitex agnus castus), tall plant resembling the willow","forms":["agnōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi cyclōps Polyphemus {{agnōs}} cūrat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"agnoscere","latin":"(agnōsco) agnōscere, -ōvisse","headword":"agnōscere","letter":"a","pos":"verb","posGroup":"verb","english":"recognize; to recognise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"agnosco","latin":"agnosco, agnoscere, agnovi, agnitus","headword":"agnosco","letter":"a","pos":"verb","posGroup":"verb","english":"recognize, realize, discern; acknowledge, claim, admit to/responsibility","forms":["agnōscās","agnōscātis","agnōscere","āgnōscit","agnoscō","agnōvī","agnōvisset","agnōvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rachel festīnāns id nūntiāvit patrī suō, quī {{agnōvit}} fīlium sorōris suae, deditque eī Rachēlem in mātrimōnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"agnus","latin":"agnus, -ī","headword":"agnus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"lamb","forms":["agnō","agnum","agnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Arethūsae vērō tunc tālis animus fuit, quālis est agnō, cum lupum audit in silvā ululantem.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ago","latin":"ago, agere, egi, actus","headword":"ago","letter":"a","pos":"verb","posGroup":"verb","english":"drive/urge/conduct/act; spend (time w/cum); thank (w/gratias); deliver (speech)","forms":["āctōs","āctūrum","agam","agant","agantur","agat","agātur","agēbam","agebant","agēbat","agēbātis","agendō","agendos","agendus","agere","agerent","agerentur","ageret","agerētis","agerētur","agēs","aget","agētis","agētur","agi","agimus","agis","agit","agitis","agitur","agō","agor","agundī","agunt","aguntur","ēgerat","ēgeris","ēgerit","ēgerunt","ēgī","ēgimus","ēgisse","ēgissent","ēgisset","ēgit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, in Italiam ad conventus {{agendos}} proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"agrarius","latin":"agrārius, -a, -um","headword":"agrārius","letter":"a","pos":"adjective","posGroup":"adjective","english":"agrarian","forms":["agrāriam","agrāriīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Semprōnius Gracchus tribūnus plēbis, cum lēgem {{agrāriam}} ferrēt adversus voluntātem senātūs et equestris ōrdinis — 'nē quis ex pūblicō agrō plūs quam mīlle iūgera possidēret' — in eum furōrem exārsit ut M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"agrestis","latin":"agrestis, -e","headword":"agrestis","letter":"a","pos":"adjective","posGroup":"adjective","english":"rustic, boorish, (m.) peasant","forms":["agrestēs","agrestī","agrestis","agrestium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accidit ut exercītus trāiceret silvam, in quā esset plūrimum mellis {{agrestis}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"agricola","latin":"agricola, -ae","headword":"agricola","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) farmer","forms":["agricola","agricolae","agricolam","agricolārum","agricolās","agricolīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Adamus habuit multōs līberōs, inter quōs Caīnus et Abel numerantur; hic fuit pāstor, ille {{agricola}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"agrippa","latin":"Agrippa, Agrippae","headword":"Agrippa","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Agrippa; (Roman cognomen); [Menenius A~ => fable of the belly and members]","forms":["Agrippā","Agrippae","Agrippam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Agrippā, duce illūstrī quī classī Augustī praefectus erat, itemque magnae balneae quae ab eōdem thermae Agrippae vocantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"agrippina","latin":"Agrippina, Agrippinae","headword":"Agrippina","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Agrippina (Roman woman's name); (mother of Nero); [Colonia ~ => Cologne]","forms":["Agrippīnā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Īdem Vespasiānus duo templa aedificāvit: templum Dīvī Claudiī in Caeliō monte (coeptum quidem ab Agrippīnā, Claudiī uxōre, sed ā Nerōne prope funditus dēstrūctum), et templum Pācis forō proximum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ah","latin":"ah","headword":"ah","letter":"a","pos":"interjection","posGroup":"interjection","english":"exclamation expressing surprise/irony","forms":["Āh"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: [ad Iovem] Āh, nōlī!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ahenum","latin":"ahenum, aheni","headword":"ahenum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"vessel made of copper/bronze; brazen vessel; kettle, pot, cauldron","forms":["ahēnum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cūrābō igitur ut Phrixus {{ahēnum}} moriātur; profectō enim hōc modō efficiam ut soror quoque, post eius mortem, miseram vītam habeat.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ai","latin":"ai","headword":"ai","letter":"a","pos":"interjection","posGroup":"interjection","english":"alas; exclamation expressing grief","forms":["AI"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Statim in iīs ‘{{AI}}’ litterae ad Apollinis clāmōrem commemorandum appāruērunt, quae adhūc in illīus flōris foliīs scrīpta cernuntur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ain","latin":"ain, undeclined","headword":"ain","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"ayin; (16th letter of Hebrew alphabet)","forms":["Ain"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sanniō: “{{Ain}}’ tū?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ain’ = ais ne","latin":"ain’ = ais ne?","headword":"ain’ = ais ne","letter":"a","pos":"","posGroup":"other","english":"you don’t say? really?","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"aio","latin":"aio, -, -","headword":"aio","letter":"a","pos":"verb","posGroup":"verb","english":"say (defective), assert; say yes/so, affirm, assent; prescribe/lay down (law)","forms":["aibās","aibat","aiēbam","aiēbant","aiēbās","aiēbat","aiō","ais","aiunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Diodōrus: “Quid {{ais}}?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ais","latin":"(āiō) ais, ait, āiunt","headword":"ais","letter":"a","pos":"","posGroup":"other","english":"say","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ait","latin":"ait, -, -","headword":"ait","letter":"a","pos":"verb","posGroup":"verb","english":"he says (ait), it is said; they say (aiunt)","forms":["ait"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cui Rebecca: bibe, {{ait}}, domine mī; et simul dēmīsit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ala","latin":"āla, -ae","headword":"āla","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"wing","forms":["ālā","ālae","ālam","ālās","ālīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra magnam avem quae suprā hortum volat digitō mōnstrat: “Ecce avis fera quae ā parvīs avibus timētur.” Avis magnīs ālīs sustinētur, neque Iūlia ālās movērī videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"alacer","latin":"alacer, -cris, -cre","headword":"alacer","letter":"a","pos":"adjective","posGroup":"adjective","english":"lively, eager, keen; eager, brisk","forms":["alacres","alacrior"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnes {{alacres}} et fiduciae pleni ad Alesiam proficiscuntur, neque erat omnium quisquam qui aspectum modo tantae multitudinis sustineri posse arbitraretur, praesertim ancipiti proelio, cum ex oppido eruptione pugnaretur, foris tantae copiae equitatus peditatusque cernerentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alatus","latin":"ālātus, -a, -um","headword":"ālātus","letter":"a","pos":"adjective","posGroup":"adjective","english":"winged","forms":["ālātum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Manē Bellerophōn, cum oculōs aperuisset, aureum illud frēnum, quod in somnīs dea eī dederat, cōnspexit; quō sūmptō, ē templō exiit, ut Pēgasum, equum illum ālātum, quaereret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"alba","latin":"alba, albae","headword":"alba","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"|white precious stone; pearl","forms":["albā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Coepērunt IUdaeī accūsāre Iēsum dīcentēs:\"Rūne invenīmus subvertentem gentem nostram, et dīcentem sē rēgem esse.\"Pīlātus, cum eum interrogāsset et cognōvisset eum Galilaeum esse, mīsit ad Hērōdem, quī sprēvit Iēsum, induit veste albā et remīsit ad Pīlātum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"albens","latin":"albens, (gen.), albentis","headword":"albens","letter":"a","pos":"adjective","posGroup":"adjective","english":"white, light, bleached; made/covered in white; pale, pallid; bright, clear","forms":["albēns","albentēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{albēns}} -entis adī — albus, cànus tempus et albentēs 1am","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"albeo","latin":"albeo, albere, -, -","headword":"albeo","letter":"a","pos":"verb","posGroup":"verb","english":"be/appear white/pale/light-colored/white with age","forms":["albet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Intereā aēnō in igne positō medicāmen validum fervet et {{albet}} spūmīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"albesco","latin":"albesco, albescere, -, -","headword":"albesco","letter":"a","pos":"verb","posGroup":"verb","english":"become white/pale/light-colored/white with age; become bright, gleam, glow","forms":["albēscere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"rēgīna ē speculīs ut prīmam {{albēscere}} lūcem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"albinus","latin":"albinus, albini","headword":"albinus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"plasterer, one who covers walls with stucco/plaster","forms":["Albīne","Albīnī","Albīnō","Albīnum","Albīnus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Certē {{Albīnus}}, quī tabernam habet prope forum Rōmānum, magnum pretium dabit tibi.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"albis","latin":"Albis, Albis","headword":"Albis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Elbe; (river in Germany)","forms":["albīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"inveniunt foliīs medium cingentibus {{albīs}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"albo","latin":"albo, albare, albavi, albatus","headword":"albo","letter":"a","pos":"verb","posGroup":"verb","english":"make white","forms":["albō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sī nāvis, Minotaurō necātō, reveniat, vēlō albō nāviget; iuvenibus necātīs, vēlō ātrō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"albugo","latin":"albugo, albuginis","headword":"albugo","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"white opaque spot on the eye; disorder of the scalp","forms":["albūgō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde Tobiās oculōs patris līnīvit felle piscis, et post dīmidiam fermē hōram coepit albūgō, quasi membrāna ōvī, ex oculīs eius ēgredī, quam apprehēnsam fīlius extrāxit, atque ille statim vīsum recēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"albulus","latin":"albulus, albula, albulum","headword":"albulus","letter":"a","pos":"adjective","posGroup":"adjective","english":"white, pale, whitish","forms":["Albula"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pāx ita convēnerat ut Etrūscīs Latīnīsque fluvius {{Albula}}, quem nunc Tiberim vocant, fīnis esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"album","latin":"album, albi","headword":"album","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"white (color); white tablet, official list, register","forms":["album"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Atque collum tuum {{album}} bene vidētur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"albus","latin":"albus, -a, -um","headword":"albus","letter":"a","pos":"adjective","posGroup":"adjective","english":"white","forms":["albae","albam","albārum","albās","albī","albōs","albus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce autem quattuor ovēs {{albae}} accurrunt!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"alcyon","latin":"alcyon, alcyonis","headword":"alcyon","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"halcyon; kingfisher; sea birds (pl.)","forms":["Alcyonēm","Alcyonēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum haec ex caelō spectāret, Iūnō, deōrum rēgīna, Īridem, suam nūntiam variīs colōribus exōrnātam, vocāvit et eī imperāvit ut somnium ad {{Alcyonēm}} mitteret, quō coniugis mors nūntiārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"alcyone","latin":"alcyone, alcyones","headword":"alcyone","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"halcyon; kingfisher; sea birds (pl.)","forms":["Alcyonē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Fuērunt ōlim duo coniugēs: virō Cēyx, uxōrī vērō Alcyonē nōmen fuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"alea","latin":"alea, aleae","headword":"alea","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"game of dice; die; dice-play; gambling, risking; chance, venture, risk, stake","forms":["ālea"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ālea -ae f — lūdus quō tesserīs iacī-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"alere","latin":"alere","headword":"alere","letter":"a","pos":"verb","posGroup":"verb","english":"feed, nourish","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ales","latin":"āles, -itis ( f.)","headword":"āles","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"large bird; bird","forms":["āles","ālitem"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sīve īnfāns valet sīve aegrōtat, māter ipsa eum cūrāre et alere dēbet — hoc est mātris officium!\" Iūlius: \"Tūne ipsa īnfantem tuum lacte tuō āles?\" Aemilia: \"Profectō īnfantem meum ipsa ālam.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"alexander","latin":"Alexander, Alexandri","headword":"Alexander","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Alexander; (common Greek name)","forms":["Alexander","Alexandrī","Alexandrō","Alexandrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Intereā Dēmētrium rēgem interrēcit {{Alexander}}, quī sē Antiochī fllium dictitābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alexandria","latin":"Alexandria, Alexandriae","headword":"Alexandria","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Alexandria; (City in Egypt and others)","forms":["Alexandrīa","Alexandrīae","Alexandrīam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eō annō etiam {{Alexandrīa}} ab Alexandrō Macedone condita est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"algens","latin":"algens, (gen.), algentis","headword":"algens","letter":"a","pos":"adjective","posGroup":"adjective","english":"cold (weather), chilly (insufficient clothing); cold (of things normally hot)","forms":["algentī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"algentī manus est calfacienda sinū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"algidus","latin":"algidus, algida, algidum","headword":"algidus","letter":"a","pos":"adjective","posGroup":"adjective","english":"cold","forms":["Algidō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sequentī annō, cum in Algidō monte ab urbe duodecimō fermē mīliāriō Rōmānus obsidērētur exercitus, L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"algor","latin":"algor, algoris","headword":"algor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"cold, coldness; chilliness; a fit of shivering; cold weather (pl.)","forms":["algōris"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Corpus patiēns inediae, {{algōris}}, vigiliae, suprā quam cuīquam crēdibile est.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"alia","latin":"alia","headword":"alia","letter":"a","pos":"adverb","posGroup":"adverb","english":"by another/different way/route","forms":["alia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Docet longe {{alia}} ratione esse bellum gerendum atque antea gestum sit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alias","latin":"aliās","headword":"aliās","letter":"a","pos":"adverb","posGroup":"adverb","english":"at another time, at another place","forms":["alias"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Depopulata Gallia Cimbri magnaque inlata calamitate finibus quidem nostris aliquando excesserunt atque {{alias}} terras petierunt; iura, leges, agros, libertatem nobis reliquerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alibi","latin":"alibī","headword":"alibī","letter":"a","pos":"adverb","posGroup":"adverb","english":"elsewhere","forms":["alibī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accītusque inde Carthāginem sextō ac trīcēsimō post annō quam puer inde profectus erat, fassus in cūriā est 'nōn proeliō modo sē, sed bellō victum, nec spem salūtis alibī quam in pāce impetrandā esse.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"alicula","latin":"alicula, aliculae","headword":"alicula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"light coat/cloak/hunting dress; child's coat","forms":["āliculā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cēterum ad scindendum aprum nôn ille Ca1pūs ac- cessit quī altilia lacerāverat, sed barbātus ingēns, fasciîs crürâlibus alligātus et āliculā sub- ômâtus polymitā, strictôque vënätôriô cultrô latus aprî vehementer percussit ēvolāvērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"alienigena","latin":"aliēnigena, -ae (m.)","headword":"aliēnigena","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"foreigner, stranger","forms":["aliēnigena","alienigenam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Paulō post rēgnum Iildae invāsit Hērōdēs {{aliēnigena}}: hunc prīmum Iiidaēī habuērunt rēgem ex aliā gente ortum, eōque rēgnante nātus est Chrīstus, ufī praedīxerant prophētae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alieno","latin":"alieno, alienare, alienavi, alienatus","headword":"alieno","letter":"a","pos":"verb","posGroup":"verb","english":"alienate, give up, lose possession, transfer by sale, estrange; become numb","forms":["alienare","aliēnō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praestare visum est tamen omnes difficultates perpeti quam tanta contumelia accepta omnium suorum voluntates {{alienare}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alienum","latin":"alienum, alieni","headword":"alienum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"another's property/land/possessions; foreign soil; other's affairs/views (pl.)","forms":["aliēnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Frātrēs Iōsēphī respondērunt dispēnsātōrī: istud sceleris longē ā nōbīs {{aliēnum}} est; nōs, ut tūtē scīs, retulimus bonā fide pecūniam repertam in saccīs; tantum abest ut fūrātī sīmus scyphum dominī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alienus","latin":"aliēnus, -a, -um","headword":"aliēnus","letter":"a","pos":"adjective","posGroup":"adjective","english":"belonging to another; another’s, foreign; another's, foreign; another’s, belonging to someone else","forms":["aliena","aliēnae","aliēnam","aliēnārum","aliēnās","aliēnī","aliēnīs","aliēnōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Multum ad terrendos nostros valet clamor, qui post tergum pugnantibus exstitit, quod suum periculum in {{aliena}} vident salute constare; omnia enim plerumque quae absunt vehementius hominum mentes perturbant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliger","latin":"aliger, aligera, aligerum","headword":"aliger","letter":"a","pos":"adjective","posGroup":"adjective","english":"winged, having wings; moving with the speed of flight","forms":["āligerum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ergō hīs āligerum dictīs adfātur Amōrem:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"alii","latin":"alii","headword":"alii","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"some ... others (alii ... alii)","forms":["alii"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc {{alii}} deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alio","latin":"aliō","headword":"aliō","letter":"a","pos":"adverb","posGroup":"adverb","english":"elsewhere","forms":["alio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis {{alio}} loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliqu","latin":"aliqu","headword":"aliqu","letter":"a","pos":"pronoun","posGroup":"pronoun","english":"anyone/anybody/anything; someone; some/few; some (particular) thing","forms":["alicui","alicuius","Aliquae","aliquās","aliquem","aliquis","aliquōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si {{alicuius}} indicio vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliqua","latin":"aliqua","headword":"aliqua","letter":"a","pos":"adverb","posGroup":"adverb","english":"somehow, in some way or another, by some means or other; to some extent","forms":["aliquā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aliquā diē tē persuādeam, ut ad vîllam veniās et videās casulās nostrâs?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"aliquam","latin":"aliquam","headword":"aliquam","letter":"a","pos":"adverb","posGroup":"adverb","english":"largely, to a large extent, a lot of; [~ multi/multum => fair number/amount]","forms":["aliquam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Etsi multis iam rebus perfidiam Aeduorum perspectam habebat atque horum discessu admaturari defectionem civitatis existimabat, tamen eos retinendos non constituit, ne aut inferre iniuriam videretur aut daret timoris {{aliquam}} suspicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliquamdiu","latin":"aliquamdiū","headword":"aliquamdiū","letter":"a","pos":"adverb","posGroup":"adverb","english":"for some time","forms":["aliquamdiū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Absalōn, profectō patre, ingressus est Hierosolymam, ibīque aliquamdiū morātus est, quae rēs salūtī fuit Davidī: nam interim Dāvīd collēgit cōpiās, sēque ad bellum comparāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aliquando","latin":"aliquandō","headword":"aliquandō","letter":"a","pos":"adverb","posGroup":"adverb","english":"some time or other, finally; at some time, once","forms":["aliquando"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Depopulata Gallia Cimbri magnaque inlata calamitate finibus quidem nostris {{aliquando}} excesserunt atque alias terras petierunt; iura, leges, agros, libertatem nobis reliquerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliquanto","latin":"aliquanto","headword":"aliquanto","letter":"a","pos":"adverb","posGroup":"adverb","english":"somewhat, to/by some (considerable) extent/amount; considerably","forms":["aliquantō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quī labor cum mīlitiae adderētur, minus tamen plēbs indignābātur sē templa deōrum aedificāre manibus suīs, quam postquam ad alia opera speciē minōra, sed labōris aliquantō maiōris traducēbātur, velut ad forōs in circō faciendōs cloācamque Maxumam sub terrā agendam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aliquantum","latin":"aliquantum","headword":"aliquantum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(adv.) to some extent; some, a certain amount","forms":["aliquantum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum cōram eō esset, Promēthēum ex Olympō aufūgisse sēcum {{aliquantum}} ignis auferentem nūntiāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aliqui","latin":"aliqui","headword":"aliqui","letter":"a","pos":"adverb","posGroup":"adverb","english":"in some way/extent","forms":["aliquī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"\"Haec verba locūtus Daedalus cum fīliō sūrsum ē labyrinthō ēvolāvit, neque quisquam fugam eōrum animadvertit nisi aliquī pāstor, quī forte suspiciēns eōs tamquam magnās avēs volantēs vīdit ac deōs esse arbitrātus est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aliquid","latin":"aliquid","headword":"aliquid","letter":"a","pos":"adverb","posGroup":"adverb","english":"to some degree/extent; somewhat","forms":["aliquid"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi {{aliquid}} ab eis iniri consili intellexissent, gladiis destrictis portas occupaverunt suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aliquis","latin":"aliquis, aliquid","headword":"aliquis","letter":"a","pos":"pronoun","posGroup":"pronoun","english":"someone, something; some, any","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aliquo","latin":"aliquo","headword":"aliquo","letter":"a","pos":"adverb","posGroup":"adverb","english":"to some place/person (or other); in some/any direction/quarter; some/anywhere","forms":["aliquō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Promētheus vērō, quī hominibus bene volēbat, aliquō beneficiō eōs afficiendōs esse statuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aliquod","latin":"aliquod, undeclined","headword":"aliquod","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"some/several/a few people; more than one; a number","forms":["aliquod"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deōrum quisque, Iove iubente, fōrmōsissimae virginī ita cōnfectae {{aliquod}} dēdit dōnum, ut illa hominēs allicere posset: Minerva enim pulcherrima ōmāmenta eī dōnāvit, Mercurius vēro cōnsilia, quibus hominum animōs falleret, aliī aliās rēs dedērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aliquot","latin":"aliquot","headword":"aliquot","letter":"a","pos":"pronoun","posGroup":"pronoun","english":"some, several","forms":["aliquot"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diē quōdam fēstō, cum domī lautum convīvium parāvisset, mīsit fīlium ut {{aliquot}} ē sociīs ad prandium invītāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aliter","latin":"aliter","headword":"aliter","letter":"a","pos":"adverb","posGroup":"adverb","english":"otherwise","forms":["aliter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Postquam vērō ille fīnem canendī fēcit, Plūtō sīc locūtus est: “Tū, Orpheū, cantū tuō animōs nostrōs vīcistī: redī igitur ad superōs, et tēcum Eurydicēn dūc, hāc tamen lege, nē respiciās nēve ūllō modō uxōrem intueāris, antequam ad vītam lūcemque redeās: quod sī {{aliter}} faciēs, numquam iterum coniugem tuam vidēbis!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"alium","latin":"alium, ali(i)","headword":"alium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"garlic, garlic plant","forms":["alium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mārcus {{alium}} nīdum videt, hunc nīdum reperīre nōn potest.” Iūlia et Syra cum cane ab arbore discēdunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aliunde","latin":"aliunde","headword":"aliunde","letter":"a","pos":"adverb","posGroup":"adverb","english":"from another place, person, thing","forms":["aliunde"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Nam quod semper movētur aeternum est; quod autem mōtum affert alicui quodque ipsum agitātur {{aliunde}}, quandō fīnem habet mōtūs, vīvendī fīnem habeat necesse est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"alius","latin":"alius, alia, aliud","headword":"alius","letter":"a","pos":"adjective; pronoun","posGroup":"adjective","english":"another, other; other, another; other; aliī ... aliī — some ... others","forms":["aliae","aliam","aliārum","aliis","aliōrum","alios","aliud","alius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant {{alios}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"allecto","latin":"allecto, allectare, allectavi, allectatus","headword":"allecto","letter":"a","pos":"verb","posGroup":"verb","english":"entice, allure, encourage, invite","forms":["allectā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Locī amoenitāte allectā, et corpus sūdōre ac terrā sordī dum lavandī cupidā, Arethūsā, veste positā, in fluviī aquās intrāvit ac prīmum pedēs et crūra, deinde ventrem, tum pectus, tōtum dēnique corpus usque ad collum mersit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"allicere","latin":"(alliciō) allicere, allēxisse, allectum","headword":"allicere","letter":"a","pos":"verb","posGroup":"verb","english":"attract; to attract, entice","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"allicio","latin":"allicio, allicere, allexi, allectus","headword":"allicio","letter":"a","pos":"verb","posGroup":"verb","english":"draw gently to, entice, lure, induce (sleep), attract, win over, encourage","forms":["allectae","allēctus","allexerat","allexit","allicere","allici","alliciant","alliciebat","alliciendus","allicit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec minus quam est pollicitus Vercingetorix animo laborabat ut reliquas civitates adiungeret, atque eas donis pollicitationibusque {{alliciebat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alligare","latin":"(alligō) alligāre","headword":"alligāre","letter":"a","pos":"","posGroup":"other","english":"tie, fasten to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"alligatus","latin":"alligatus, alligati","headword":"alligatus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"slaves (pl.) who are fettered","forms":["alligātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cēterum ad scindendum aprum nôn ille Ca1pūs ac- cessit quī altilia lacerāverat, sed barbātus ingēns, fasciîs crürâlibus {{alligātus}} et āliculā sub- ômâtus polymitā, strictôque vënätôriô cultrô latus aprî vehementer percussit ēvolāvērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"alligo","latin":"alligo, alligare, alligavi, alligatus","headword":"alligo","letter":"a","pos":"verb","posGroup":"verb","english":"bind/fetter (to); bandage; hinder, impede, detain; accuse; implicate/involve in","forms":["alligant","alligat","alligātīs","alligāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubī pervēnērunt ambō in locum dēsignātum, Abrahamus exstrūxit āram, disposuit ligna, {{alligāvit}} Isaacum super struem lignōrum, deinde arripuit gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"allium","latin":"allium, alli(i)","headword":"allium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"garlic, garlic plant","forms":["Allia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"' {{Allia}} -aē f, parvus fluvius Latiī; 'flē-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"allobrox","latin":"Allobrox, Allobrogis","headword":"Allobrox","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Allobroges (pl.); (tribe of Gaul - in Caesar's Gallic War)","forms":["Allobroges","Allobrogibus","Allobrogum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His praeficit fratrem Eporedorigis, bellumque inferri {{Allobrogibus}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alloqui","latin":"(alloquor) alloquī (< loquī)","headword":"alloquī","letter":"a","pos":"","posGroup":"other","english":"speak to, address","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"alloquor","latin":"alloquor, alloqui, allocutus sum","headword":"alloquor","letter":"a","pos":"verb","posGroup":"verb","english":"speak to (friendly); address, harangue, make a speech (to); call on; console","forms":["allocūta","allocūtus","alloquar","alloquendō","alloquī","alloquitur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sīc Davidem {{allocūtus}} est prophēta Nāthan: “Erant in eādem urbe duo hominēs: alter dīves multōs boum, caprārum atque ovium gregēs alēbat; alter vērō nihil habēbat praeter ovem ūnam, quam ipse ēmerat, et apud sē dīligenter nūtriēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"almus","latin":"almus, alma, almum","headword":"almus","letter":"a","pos":"adjective","posGroup":"adjective","english":"nourishing, kind, propitious; of a nurse/breast, providing nurture, fostering","forms":["alma","almus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{almus}} -ā -um - benignus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"alo","latin":"alō, alere","headword":"alō","letter":"a","pos":"verb","posGroup":"verb","english":"nourish, raise","forms":["ālātīs","alatur","alēbam","alēbat","alendī","alendum","alere","alet","alētur","ali","alit","ālite","alitur","aluērunt","aluī","aluissent","aluit","aluntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quod si diutius {{alatur}} controversia, fore uti pars cum parte civitatis confligat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alpha","latin":"alpha, undeclined","headword":"alpha","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"alpha, 1st letter of Greek alphabet; A; first/foremost (group/class); beginning","forms":["alpha"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Tlēpolemus: “Sciō nōmina litterārum: {i}{{alpha}}, bēta, gamma...{/i}”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"alpis","latin":"Alpis, Alpis","headword":"Alpis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Alps (usually pl.), mountains to the north of Italy","forms":["Alpe","Alpēs","Alpibus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Celsī sānē et arduī montēs Germāniam ab Italiā disiungunt, ac difficillimae sunt viae quae trāns {{Alpēs}} ferunt, sed tamen celer tabellārius idem iter quīndecim ferē diēbus cōnficere potest, ut tabellāriī pūblicī quibus ūtitur dux noster.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"altare","latin":"altare, altaris","headword":"altare","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"altar (usu. pl.), fitting for burnt offerings; burnt offering; high altar","forms":["altāre","altāria","altāribus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum ērēxit {{altāre}}, et obtulit sacrificium Dominō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"altaria","latin":"altāria, -ium (n. pl.)","headword":"altāria","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"altar; high altar","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"alte","latin":"alte, altius, altissime","headword":"alte","letter":"a","pos":"adverb","posGroup":"adverb","english":"high, on high, from above, loftily; deep, deeply; far, remotely; profoundly","forms":["altē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam vērō diū hoc modo inter sē magnō cum gaudiō lūsērunt, rēgis fīlia pilam ad ancillam tam altē iēcit, ut illa capere nōn posset; cecidit autem in mare flūctūsque eam ita sēcum trāxērunt, ut mergerētur: itaque puellae simul omnēs tam magnā vōce clāmāvērunt, ut Ulixēs, nōtissimus ille Graecōrum dux, quī in silvā prope lītus dormiēbat, subitō excitārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"alter","latin":"alter, -era, -erum","headword":"alter","letter":"a","pos":"pronoun; adjective","posGroup":"pronoun","english":"one, the other, second; the one, the other","forms":["alter","altera","alterae","alteram","alteri","alterīs","altero","alterōs","alterum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, {{altera}} Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alteras","latin":"alteras","headword":"alteras","letter":"a","pos":"adverb","posGroup":"adverb","english":"at another time; at one time ... at another","forms":["Alterās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Alterās}} fëcî mäiôrës et dîceret.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"altercatio","latin":"altercatio, altercationis","headword":"altercatio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"contention, dispute, wrangle, altercation; debate, argument (law), repartee","forms":["altercātiōne"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Orta inter duās mulierēs gravī {{altercātiōne}}, rēs ad Salomōnem dēlāta est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alterius","latin":"alterius","headword":"alterius","letter":"a","pos":"adverb","posGroup":"adverb","english":"of one another","forms":["alterīus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nōn occīdētis, nōn adulterābitis, nōn faciētis fūrtum; nōn dīcētis falsum testimōnium adversus proximum vestrum; nōn concupīscētis rem {{alterīus}}.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alternis","latin":"alternis","headword":"alternis","letter":"a","pos":"adverb","posGroup":"adverb","english":"alternately; one after the other in turn, by turns; every other day/year","forms":["alternis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, {{alternis}} trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alterno","latin":"alterno, alternare, alternavi, alternatus","headword":"alterno","letter":"a","pos":"verb","posGroup":"verb","english":"do by turns, vary; alternate, waver, ebb and flow; bear/crop in alternate years","forms":["alternantī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"haec alternantī potior sententia vīsa est:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"altilis","latin":"altilis, altilis, altile","headword":"altilis","letter":"a","pos":"adjective","posGroup":"adjective","english":"fattened, fat, raised/fed up for eating; rich (dowry); well-fed, pampered","forms":["altilia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quô factô, vidēmus înfrä {{altilia}} et -or1sm . summa lepōremque 1n medlō pmms subôrnätum, ut Pēgasus vidërëtm.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"altitudo","latin":"altitūdo, -inis ( f.)","headword":"altitūdo","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"height, depth","forms":["altitudine","altitudinem","altitudinis","altitudo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in {{altitudinem}} pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"alto","latin":"alto, altare, altavi, altatus","headword":"alto","letter":"a","pos":"verb","posGroup":"verb","english":"raise, make high, elevate","forms":["altō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Omnia absūmpta sunt dīluviō; arca autem sublevātā aquīs fluitābat in altō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"altum","latin":"altum, -ī","headword":"altum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"“the deep”: the open sea","forms":["altum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis imbribus tardarentur, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, {{altum}} pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"altus","latin":"altus, -a, -um","headword":"altus","letter":"a","pos":"adjective","posGroup":"adjective","english":"high, tall, deep; high, deep; tall, lofty, deep, high","forms":["alta","altae","altās","altī","altior","altiōrēs","altīs","altissima","altissimae","altissimārum","altissimīs","altissimo","altissimōs","altissimum","altissimus","altius","altōs","altus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, {{altissima}} nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aluta","latin":"aluta, alutae","headword":"aluta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"piece/kind of soft leather (prepared with alum); purse/pouch; shoe; beauty patch","forms":["alūtā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"parvāque sincérás vēlat alūtā genàs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"alveum","latin":"alveum, alvei","headword":"alveum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"bath, bath-tub","forms":["alveum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Appropinquante arca, aquae, quae superne dēfluēbant, stetērunt īnstar mūrī; quae autem īnfrā, dēscendērunt, et {{alveum}} siccum relīquērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alveus","latin":"alveus, alvei","headword":"alveus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"cavity, hollow; tub; trough, bowl, tray; gameboard; beehive; canoe","forms":["alveō","alveus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Flāvit etiam ventus vehemēns, quō exsiccātus est {{alveus}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"alvus","latin":"alvus, alvi","headword":"alvus","letter":"a","pos":"noun","posGroup":"noun","english":"belly/paunch/stomach; womb; bowel; bowel movement; hull (ship); beehive; cavity","forms":["alvō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille dedit, quod nōn animā haec Cyclōpis in ōra\nvēnit, et ut iam nunc lūmen vītāle relinquam,\naut tumulō aut certē nōn illā condar in alvō.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ama","latin":"ama, amae","headword":"ama","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"bucket; water bucket; (esp. fireman's bucket)","forms":["ama"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dé duce terribilī factus {{ama}}àtor erat;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amabilis","latin":"amabilis, amabile, amabilior -or -us, amabilissimus -a -um","headword":"amabilis","letter":"a","pos":"adjective","posGroup":"adjective","english":"worthy to be loved, lovable; amiable, pleasant; lovely, attractive, delightful","forms":["amābilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"[Ut amēris, {{amābilis}} estō!]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amando","latin":"amando, amandare, amandavi, amandatus","headword":"amando","letter":"a","pos":"verb","posGroup":"verb","english":"send away, dismiss, banish; regulate","forms":["amandā","āmandō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"superābat āmandō","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amans","latin":"amāns, amantis","headword":"amāns","letter":"a","pos":"noun","posGroup":"noun","english":"one who loves, a lover","forms":["amāns","amante","amantem","amantēs","amantī","amantibus","amantis","amantissimam","amantissime","amantissimōs","amantium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cornēlius: “Ego nōn minus gaudeō mē esse domī apud tē, uxōrem meam {{amantissimam}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amaracus","latin":"amaracus, amaraci","headword":"amaracus","letter":"a","pos":"noun","posGroup":"noun","english":"marjoram; feverfew (pyrethrum parthenium)","forms":["amāracus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Īdaliae lūcōs, ubi mollis {{amāracus}} illum","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"amare","latin":"amare, amarius, amarissime","headword":"amare","letter":"a","pos":"adverb","posGroup":"adverb","english":"with bitterness, acidly, spitefully, bitterly","forms":["amāre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Apollō, quī in silvīs et agrīs errābat, cum prīmum eam iīsdem in locīs laetē lūdentem cōnspexit, statim {{amāre}} coepit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amarum","latin":"amarum, amari","headword":"amarum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"bitterness; unpleasantness; (often pl.)","forms":["amārum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Corpus ut aspexit, lacrimīs aurīgā profūsīs restitit; hunc tālī corripit illa sonō: \"Vādis? an exspectās pretium pietātis {{amārum}}?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"amarus","latin":"amārus, -a, -um","headword":"amārus","letter":"a","pos":"adjective","posGroup":"adjective","english":"bitter","forms":["amārae","amāram","amārī","amāris","amārissimae","amārissimē","amārissimum","amārō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dōrippa: “Dīcō ‘nōn mē, sed ancillam ā tē amārī’.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amasia","latin":"amasia, amasiae","headword":"amasia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"female lover; (JFW guess from amasius = lover)","forms":["Amasīae","Amasīās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Athalia -ae f, Ochosīās -ae m, īOas -ae m, Iōiadas -ae m, {{Amasīās}}","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amasiuncula","latin":"amasiuncula, amasiunculae","headword":"amasiuncula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"loved one, darling, sweetheart; fond lover","forms":["amasiuncula"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Suädeô bonum tuum cōn- coquās, milva, et mē nôn faciās ringentem, {{amasiuncula}}!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"amat","latin":"amat","headword":"amat","letter":"a","pos":"verb","posGroup":"verb","english":"loves; loves, likes","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"amat/amant","latin":"amat/amant","headword":"amat/amant","letter":"a","pos":"","posGroup":"other","english":"love","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"amata","latin":"Amata, Amatae","headword":"Amata","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Amata; (queen of Latium, wife of Latinus, opposed Aeneas)","forms":["amāta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cum Athēnās redīret, Hippolytam rēgīnam eārum sēcum rettulit, quae maximē {{amāta}} fīlium Hippolytum peperit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"amator","latin":"amator, amatoris","headword":"amator","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"lover; friend, devotee; enthusiastic admirer/pursuer; one fond of women","forms":["amātor","amātōrī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nova arma! (: {{amātor}} mīlitāns!)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amatorius","latin":"amātōrius, -a, -um","headword":"amātōrius","letter":"a","pos":"adjective","posGroup":"adjective","english":"of love","forms":["AMĀTŌRIA"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ARS {{AMĀTŌRIA}} IĪ","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amatus","latin":"amatus, amata, amatum","headword":"amatus","letter":"a","pos":"adjective","posGroup":"adjective","english":"loved, beloved","forms":["amātās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum prīmum vērō Alphēus {{amātās}} aquās cognōvit, posita hominis fōrma, quam eō cōnsiliō sūmpserat, ut Arethūsam persequī posset, in flūmen iterum sē convertit, ut sē cum nymphā coniungeret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amazon","latin":"Amāzōn, -onis","headword":"Amāzōn","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Amazon, a female warrior","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"amb","latin":"amb","headword":"amb","letter":"a","pos":"numeral","posGroup":"numeral","english":"both; two of pair; two considered together, both parties; each of two","forms":["ambae","ambās","ambō","ambōbus","ambōrum","ambōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque ūna ambō abiērunt forās, et cum essent in agrō, Caīnus irruit in Abēlem, et interfēcit illum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ambages","latin":"ambages, ambagis","headword":"ambages","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"circuit; roundabout way; long story, details; riddle; ambiguity; lie; mystery","forms":["ambāgēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{ambāgēs}}; sed summa sequar fastīgia rērum.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ambiguus","latin":"ambiguus, ambigua, ambiguum","headword":"ambiguus","letter":"a","pos":"adjective","posGroup":"adjective","english":"changeable, doubtful, ambiguous, wavering, fickle; treacherous, unethical","forms":["ambiguō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nōn aliter Maeandrus in agrīs Phrygiīs lūdit et ambiguō lapsū fluit et refluit; occurrēns sibi, aquās incertās nunc ad fontēs, nunc ad mare apertum dūcit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ambio","latin":"ambio, ambire, ambivi, ambitus","headword":"ambio","letter":"a","pos":"verb","posGroup":"verb","english":"go round, visit in rotation, inspect; solicit, canvass; circle, embrace","forms":["ambīre"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"heu quid agat? quō nunc rēgīnam {{ambīre}} furentem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ambitio","latin":"ambitio, ambitionis","headword":"ambitio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"ambition; desire for/currying favor/popularity, flattery; vote canvassing; pomp","forms":["ambitiō","ambitiōne","ambitiōnem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae tametsī animus aspernābātur īnsolēns malārum artium, tamen inter tanta vitia imbēcilla aetās {{ambitiōne}} corrupta tenēbātur; ac mē, cum ab reliquōrum malīs mōribus dissentīrem, nihilō minus honōris cupīdō eadem quā cēterōs fāma atque invidia vexābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ambitus","latin":"ambitus, ambitus","headword":"ambitus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"circuit, edge, extent; orbit, cycle; canvass, bribery; circumlocution; show","forms":["ambitūs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sulla, dēsignātī cōnsulēs, lēgibus {{ambitūs}} interrogātī poenās dederant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ambo","latin":"ambō, -ae, -ō","headword":"ambō","letter":"a","pos":"pronoun","posGroup":"pronoun","english":"both, the two; both, two, together","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ambro","latin":"ambro, ambronis","headword":"ambro","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"glutton; spendthrift","forms":["Ambrōnibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caepiō ā Cimbrīs et Teutonibus et Tīgurīnīs et {{Ambrōnibus}}, quae erant Germānōrum et Gallōrum gentēs, victī sunt iuxtā flūmen Rhodanum ingentī interniciōne; etiam castra sua et magnam partem exercitūs perdidērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ambrosia","latin":"ambrosia, -ae","headword":"ambrosia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"ambrosia, food of the gods","forms":["ambrosiā"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quicquid in Aenēā fuerat mortāle, repurgat\net respersit aquīs; pars optima restitit illī,\nlūstrātum genetrīx dīvīnō corpus odōre\nunxit et ambrosiā cum dulcī nectare mixtā\ncontigit ōs fēcitque deum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ambubaia","latin":"ambubaia, ambubaiae","headword":"ambubaia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Syrian singing-girl and courtesan","forms":["Ambūbāiam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô puer quoque ofﬁciôsus urceolum ﬁîgidum ad mālam eius admôvit, super quem incumbēns Fortūnāta Contrā Trimalchiô “Quid enim?” inquit, “{{Ambūbāiam}} nôn meminit sē?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ambulare","latin":"ambulāre","headword":"ambulāre","letter":"a","pos":"verb","posGroup":"verb","english":"walk; to walk","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ambulat","latin":"ambulat, ambulant","headword":"ambulat","letter":"a","pos":"verb","posGroup":"verb","english":"walk; walks","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ambulator","latin":"ambulator, ambulatoris","headword":"ambulator","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"one who walks about (idly/for pleasure); itinerant trader, peddler","forms":["ambulātor"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vīlicus nē sit {{ambulātor}}, sōbrius sit semper, ad cēnam nē quō eat...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ambulatrix","latin":"ambulatrix, (gen.), ambulatricis","headword":"ambulatrix","letter":"a","pos":"adjective","posGroup":"adjective","english":"movable, which can be moved; transferable; liable to change","forms":["ambulātrīx"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ad cēnam nē quō eat, nēve {{ambulātrīx}} siet...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ambulo","latin":"ambulō, -āre","headword":"ambulō","letter":"a","pos":"verb","posGroup":"verb","english":"walk","forms":["ambulā","ambulābant","ambulābat","ambulandō","ambulandum","ambulāns","ambulant","ambulante","ambulantem","ambulantēs","ambulāre","ambulārem","ambulārent","ambulāret","ambulās","ambulat","Ambulāte","ambulātum","ambulāverat","ambulāvērunt","ambulāvit","ambulent"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Via Latīna est longa, sed Mēdus, quī viā Latīnā Tūsculō Rōmam {{ambulat}}, fessus nōn est, nam is ambulat ad Lȳdiam amīcam, quae Rōmae habitat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amens","latin":"āmēns (gen. āmēntis)","headword":"āmēns","letter":"a","pos":"adjective","posGroup":"adjective","english":"out of one’s mind, mad","forms":["āmēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Antiochus, ut cognōvit suōs ducēs ā IŪdā Machabaeō esse dēvictōs, āmēns furōre, in liidaeam citātō cursū contendit, excidiō gentis et urbis acceptam clādem ulrūrus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amentia","latin":"amentia, amentiae","headword":"amentia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"madness; extreme folly, infatuation, stupidity; frenzy, violent excitement","forms":["āmentiae","āmentiam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Laecae domum, convēnisse eōdem complūrēs eiusdem āmentiae scelerisque sociōs.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ames","latin":"ames, amitis","headword":"ames","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"pole/fork for supporting/spreading birdnets; fence rail, cross bar","forms":["ames"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mēdus: \"Nihil rogō, nisi ut mē {{ames}} ita ut mē amāre solēbās.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"amethystus","latin":"amethystus, amethysti","headword":"amethystus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"amethyst, violet-blue precious stone; vine yielding non-intoxicating wine?","forms":["amethystus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{amethystus}} -ī f, gemma pretiōsa","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amica","latin":"amīca, -ae","headword":"amīca","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"female friend; girlfriend, friend; girlfriend, (female) friend; friend (female)","forms":["amīca"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dōrippa, quae {{amīca}} Lȳdiae est, amīcam suam interrogat: “Quis est amīcus tuus?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amice","latin":"amice, amicius, amicissime","headword":"amice","letter":"a","pos":"adverb","posGroup":"adverb","english":"in a friendly manner/spirit; with goodwill","forms":["amīce"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lȳdia: “Ō {{amīce}}, salvē!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amicio","latin":"amicio, amicire, amicui, amictus","headword":"amicio","letter":"a","pos":"verb","posGroup":"verb","english":"clothe, cover, dress; wrap about; surround; veil; clothe with words","forms":["amictī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dissimulant, et nūbe cavā speculantur amictī,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"amicitia","latin":"amīcitia, -ae","headword":"amīcitia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"friendship","forms":["amicitia","amicitiae","amicitiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Huic rei idoneos homines deligebat quorum quisque aut oratione subdola aut {{amicitia}} facillime capere posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"amico","latin":"amico, amicare, -, -","headword":"amico","letter":"a","pos":"verb","posGroup":"verb","english":"propitiate, make friendly to oneself","forms":["amīcō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Accipe hās rosās ab amīcō tuō!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amictus","latin":"amictus, -ūs","headword":"amictus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"mantle, cloak; cloak, mantle","forms":["amictū","amictus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"quīn etiam laetās mōvēre per āera caudās\nnostraque adūlantēs comitantur vestīgia, dōnec\n[nōs] excipiunt famulae perque ātria marmore tēcta\nad dominam dūcunt: pulchrō sedet illa recessū\nsollemnī soliō, pallamque indūta nitentem\nīnsuper aurātō circumvelātur amictū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"amicus","latin":"amīcus, -ī","headword":"amīcus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"friend","forms":["amīcae","amīcam","amīcas","amīcī","amīcior","amicis","amīcissimē","amīcissimī","amīcissimōs","amīcissimum","amīcissimus","amīcōrum","amīcōs","amīcum","amicus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum {{amicis}} in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"amigrare","latin":"(āmigrō) āmigrāre","headword":"āmigrāre","letter":"a","pos":"","posGroup":"other","english":"go away, remove","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"amigro","latin":"amigro, amigrare, amigravi, amigratus","headword":"amigro","letter":"a","pos":"verb","posGroup":"verb","english":"go away, remove","forms":["amigrant"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sublātīs igitur rēbus suīs, {{amigrant}} Rōmam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"amittere","latin":"(āmittō) āmittere, āmīsisse, āmissum","headword":"āmittere","letter":"a","pos":"verb","posGroup":"verb","english":"lose; to lose","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"amitto","latin":"āmittō, -ere, āmīsī, āmissum","headword":"āmittō","letter":"a","pos":"verb","posGroup":"verb","english":"lose","forms":["āmīserat","āmīserim","āmīsērunt","āmīsī","āmīsimus","āmīsisse","āmīsissētis","āmīsistī","āmīsit","amissa","āmissae","āmissam","amissis","āmissō","āmissōs","Amissum","āmittant","āmittātis","āmittere","āmitterent","āmitteret","āmittit","āmittitur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eorum impetum Galli sustinere non potuerunt atque in fugam coniecti multis {{amissis}} se ad agmen receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"amnis","latin":"amnis, amnis","headword":"amnis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) river","forms":["amne","amnem","amnēs","amnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ut Hebraeī in terram prōmissam intrōdūcerentur, Iordānis erat trāiciendus, nec erat iīs nāvium cōpiā, nec vadum praebēbat {{amnis}} tunc plēnō alveō fluēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amo","latin":"amo, amare, amavi, amatus","headword":"amo","letter":"a","pos":"verb","posGroup":"verb","english":"love, like; fall in love with; be fond of; have a tendency to","forms":["amābam","amābant","amābar","amābāris","amābās","amābat","amābātur","amāberis","amābiminī","amābimur","amābis","amābit","amābitur","amābō","amābor","amābunt","amāmus","amandae","amandī","amandum","amant","amāret","amārētur","amās","amat","amātis","amātur","amāverant","amāverat","amāvī","amāvisse","amāvit","ĀME","amēmus","ament","amēris","amet","amētur","amō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lȳdia Mēdum {{amat}} et ab eō amātur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"amoenitas","latin":"amoenitās, -ātis ( f.)","headword":"amoenitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"pleasantness, beauty","forms":["amoenitāte"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Locī {{amoenitāte}} allectā, et corpus sūdōre ac terrā sordī dum lavandī cupidā, Arethūsā, veste positā, in fluviī aquās intrāvit ac prīmum pedēs et crūra, deinde ventrem, tum pectus, tōtum dēnique corpus usque ad collum mersit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amoeno","latin":"amoeno, amoenare, amoenavi, amoenatus","headword":"amoeno","letter":"a","pos":"verb","posGroup":"verb","english":"make pleasant (places); please, delight","forms":["amoenō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Dominus hve illūc in hortō suō amoenō ambulat, deinde exit in agrōs, quī hortum cingunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"amoenum","latin":"amoenum, amoeni","headword":"amoenum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"pleasant places (pl.)","forms":["amoenum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Apud lacum currēbat {{amoenum}}, quem pulcherrima silva cingēbat novīs foliīs modo vestīta; avēs canentēs vēr nūntiābant, et sōl clāra suā lūce omnia ita illūstrābat, ut nūllum perīculum puellīs lūdentibus impendēre vidērētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amoenus","latin":"amoenus, -a, -um","headword":"amoenus","letter":"a","pos":"adjective","posGroup":"adjective","english":"pleasant (of places); pleasant, lovely","forms":["amoena","amoenīs","amoenissima","amoenissimō","amoenissimōs","amoenissimum","amoenissimus","amoenius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Deus posuit Adamum et Ēvam in hortō amoenissimō, quī solet appellārī Paradīsus terrestris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amor","latin":"amor, amōris","headword":"amor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) love","forms":["amor","amōre","amōrem","amōrēs","amōrī","amōribus","amōris","amōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Longē alia fuit mēns fīliī eius Iōnāthae: virtūtem Davidis admīrāns, illum singulārī {{amōre}} complexus est, suōque balteō, arcū et gladiō dōnāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amoveo","latin":"amoveo, amovere, amovi, amotus","headword":"amoveo","letter":"a","pos":"verb","posGroup":"verb","english":"move/take/put away, remove, steal; banish, cause to go away; withdraw, retire","forms":["āmōtīs","āmovērī","Āmōvī","āmōvisse","āmōvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cōnfestim Iacobus vidēns cognātam suam, āmōvit lapidem ab ōre puteī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amphitheatrum","latin":"amphitheātrum, -ī","headword":"amphitheātrum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"amphitheater; amphitheatre","forms":["amphitheātrō","amphitheātrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aliquandō igitur velut pauperēs vestītī urbem magnam intrāvērunt ubi multae tabernae mercātōriae, multa templa, ingēns {{amphitheātrum}} erant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"amphora","latin":"amphora, -ae","headword":"amphora","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"amphora (jar)","forms":["amphorā","amphoram","amphorās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Quid?” inquit Trimalchiô, “Quandô mihi Pompëiänî “Annô priôre“ inquit āctuārius, “et ideô in ratiônem ratiônës meās înferrî vetuô.” @� vetuô : vetô [Petauristārius dēlāpsus bracchium dominî contundit] conïtuxādere -tūdisse -tūsum s1mūs cum scahs cōnst1t1t, puerumque iussit per gradūs et in summā parte trāns1l1rē et dent1bus {{amphoram}} sūs- ôdaria tinēre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ampla","latin":"ampla, amplae","headword":"ampla","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"opportunity","forms":["ampla"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā ad sociōs in lītore relictōs mūnera {{ampla}} mittit: vīgintī taurōs, centum suēs totidemque agnōs cum mātribus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"amplare","latin":"(amplō) amplāre","headword":"amplāre","letter":"a","pos":"","posGroup":"other","english":"extend, enlarge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"amplecti","latin":"(amplector) amplectī, -xum","headword":"amplectī","letter":"a","pos":"verb","posGroup":"verb","english":"embrace, cling to; to embrace, cling to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"amplector","latin":"amplector, -ī, -plexus sum","headword":"amplector","letter":"a","pos":"verb","posGroup":"verb","english":"to embrace","forms":["amplectente","amplectī","amplectimur","amplectitur","amplectuntur","amplexa","amplexae","amplexās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dardanidās mātrēs patriōrum signa deōrum dum licet {{amplexās}} succēnsaque templa tenentīs invidiōsa trahunt victōrēs praemia Graī; mittitur Astyanax illīs dē turribus, unde pugnantem prō sē prōavītaque rēgna tuentem saepe vidēre patrem mōnstrātum ā mātre solēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"amplexo","latin":"amplexo, amplexare, amplexavi, amplexatus","headword":"amplexo","letter":"a","pos":"verb","posGroup":"verb","english":"take and hold in arms, embrace, clasp; welcome, accept gladly; cling/attach to","forms":["amplexāminī","amplexārier","amplexātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Isaacus, {{amplexātus}} Iacobum, anteposuit eum frātrī, et tribuit illī omnia bona prīmōgenitī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"amplexus","latin":"amplexus, amplexus","headword":"amplexus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"clasp, embrace, surrounding; sexual embrace; coil (snake); circumference","forms":["amplexūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"vīlis ad {{amplexūs}} īnferiōris","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"amplificare","latin":"(amplificō) amplificāre","headword":"amplificāre","letter":"a","pos":"","posGroup":"other","english":"enlarge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"amplifico","latin":"amplifico, amplificare, amplificavi, amplificatus","headword":"amplifico","letter":"a","pos":"verb","posGroup":"verb","english":"enlarge, extend, increase; develop; magnify, amplify; praise loudly, exalt","forms":["amplificanda","amplificandam","amplificāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Egregiēque rēbus bellō gestīs, aedēs Iovis Ferētriī {{amplificāta}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"amplio","latin":"amplio, ampliare, ampliavi, ampliatus","headword":"amplio","letter":"a","pos":"verb","posGroup":"verb","english":"enlarge, augment, intensify, widen; ennoble, glorify; postpone, adjourn","forms":["ampliātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eumenis, quō iuvante Antiochus victus erat, rēgnum {{ampliātum}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"amplitudo","latin":"amplitūdō, -inis ( f.)","headword":"amplitūdō","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"size, extent, greatness; greatness, distinction","forms":["amplitudinem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in {{amplitudinem}} deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"amplius","latin":"amplius","headword":"amplius","letter":"a","pos":"adverb","posGroup":"adverb","english":"more","forms":["amplius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnium consensu hac sententia probata, uno die {{amplius}} XX urbes Biturigum incenduntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"amplus","latin":"amplus, -a, -um","headword":"amplus","letter":"a","pos":"adjective","posGroup":"adjective","english":"large, big","forms":["amplam","amplior","amplīs","amplissima","amplissimam","Amplissimē","amplissimīs","amplissimum","amplissimus","amplum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, sollicitatus ab Arvernis pecunia cum quibusdam adulescentibus colloquitur; quorum erat princeps Litaviccus atque eius fratres {{amplissima}} familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ampulla","latin":"ampulla, ampullae","headword":"ampulla","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"bottle, jar, flask for holding liquids; inflated expressions, bombast","forms":["ampullam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Iūlius, quī amīcōs invītāvit, ante cēnam cum Gāiō amīcō in balneum itūrus est, ut lavētur et exerceātur.] [Iūlius, ad servōs:] “Afferte sabana ad balneum, strigilem, {{ampullam}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"amputare","latin":"(amputō) amputāre","headword":"amputāre","letter":"a","pos":"","posGroup":"other","english":"cut off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"amputo","latin":"amputo, amputare, amputavi, amputatus","headword":"amputo","letter":"a","pos":"verb","posGroup":"verb","english":"lop/cut off, prune, shorten; amputate; eradicate, exclude, take away; castrate","forms":["amputandam","amputāre","amputarī","amputātīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quod illī indignē ferentēs volēbant ulcīscī iniūriam, et maledicī convīciātōris caput {{amputāre}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"an","latin":"an","headword":"an","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"or (mostly with ūter: ūter…an)","forms":["an"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, {{an}} perfidia adducti fecerint, quod nihil nobis constat, non videtur pro certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"analectris","latin":"analectris, analectridis","headword":"analectris","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"pad worn under the shoulder blades; shoulder pad (to improve the figure)","forms":["analectridēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Conveniunt tenuēs scapulīs {{analectridēs}} altīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"anapaestus","latin":"anapaestus, anapaesta, anapaestum","headword":"anapaestus","letter":"a","pos":"adjective","posGroup":"adjective","english":"anapaestic (consisting of two shorts followed by a long)","forms":["anapaestus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: iambus u —, trochaeus — u, {{anapaestus}} u u —, dactylus — u u, spondēus — —, tribrachys u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"anceps","latin":"anceps, -cipitis","headword":"anceps","letter":"a","pos":"adjective","posGroup":"adjective","english":"double, undecided","forms":["anceps","ancipitem","ancipiti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnes alacres et fiduciae pleni ad Alesiam proficiscuntur, neque erat omnium quisquam qui aspectum modo tantae multitudinis sustineri posse arbitraretur, praesertim {{ancipiti}} proelio, cum ex oppido eruptione pugnaretur, foris tantae copiae equitatus peditatusque cernerentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"anchises","latin":"Anchises, Anchisis","headword":"Anchises","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Anchises; (father of Aeneas, Trojan prince, lover of Venus)","forms":["Anchīsēn","Anchīsēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Miserī tē sī qua parentis\ntangere cūra potest, ōrō (fuit et tibi tālis\n{{Anchīsēs}} genitor), Daunī miserēre senectae,\net mē, seu corpus spoliātum lūmine māvīs,\nredde meīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ancile","latin":"ancīle, -is (n.)","headword":"ancīle","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(sacred) shield; sacred shield of Mars","forms":["ancīlia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Saliōs item duodecim Mārtī legit caelestiaque arma, quae \"{{ancīlia}}\" appellantur, ferre ac per urbem saltāre canentēs carmina iussit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ancilla","latin":"ancilla, -ae","headword":"ancilla","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"female slave, servant; maidservant","forms":["ancilla","ancillae","ancillam","ancillārum","ancillās","ancillīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēlia {{ancilla}} est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ancora","latin":"ancora, ancorae","headword":"ancora","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"anchor; grappling iron/hook; [in/ad ~is => at anchor]","forms":["ancora"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"hic {{ancora}} iacta nostràs ratēs hīc teneat nostrās ancora","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ancus","latin":"ancus, anci","headword":"ancus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"group of musical notes","forms":["Ancī","Ancō","Ancum","Ancus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī cum comitia habēret, {{Ancum}} Marcium rēgem populus creāvit; patrēs fuēre auctōrēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"andreas","latin":"Andreas, Andreae","headword":"Andreas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Andrew","forms":["Andreās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Brant autem {{Andreās}} et Iōannes.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"androgeosos","latin":"Androgeosos, Androgei","headword":"Androgeosos","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Androgeos (son of Minos and Pasiphae, whose death was avenged on Athens)","forms":["Androgeī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quō Mīnōs cēlāverat geminam fīgūram taurī iuvenisque, et bis mōnstrum sanguine Athēniēnsium pāstum erat mortis causā Androgeī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"androgeus","latin":"Androgeus, -eī","headword":"Androgeus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Androgeus, son of Minos","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"andromache","latin":"Andromache, Andromaches","headword":"Andromache","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Andromache; (wife of Hector, captive of Neoptolemus)","forms":["Andromachē","Andromachēn"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"645 omnibus Andromachē vīsa est spatiōsior aequō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"andromeda","latin":"Andromeda, Andromedae","headword":"Andromeda","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Andromeda; (Ethiopian princess, rescued by Perseus)","forms":["Andromeda","Andromedae","Andromedam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Fuit {{Andromeda}} pulcherrima virgō, fīlia Cassiopēae et Cēpheī, quī in Asiā rēgnābant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"anfractus","latin":"ānfrāctus, -ūs","headword":"ānfrāctus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"orbit (of the sun); lit. bending, recurving; winding, circuit","forms":["anfractus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio ascensus recta regione, si nullus {{anfractus}} intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum clivum accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"angelus","latin":"angelus, angeli","headword":"angelus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"angel; messenger","forms":["angelī","angelō","angelōrum","Angelōs","angelum","angelus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum ēiēcit Adamum et Ēvam ex hortō, ut ille coleret terram, et collocāvit {{Angelum}}, quī praeferēbat manū gladium igneum, ut cūstōdīret aditum Paradīsī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"angiportum","latin":"angiportum, angiporti","headword":"angiportum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"narrow street, alley; lane","forms":["angiportō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ait iste ‘eōs similitūdine locī dēceptōs angiportō tōtō deerrāsse; sē contrā valētūdinem suam ad noctem multam exspectāsse!’","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ango","latin":"ango, angere, anxi, anctus","headword":"ango","letter":"a","pos":"verb","posGroup":"verb","english":"choke, throttle, strangle; press tight; distress, cause pain, vex, trouble","forms":["angēbat","angī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Illud Iōsēphum {{angēbat}} quod Beniamīnus cum cēterīs nōn aderat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"anguis","latin":"anguis, -is (m./f.)","headword":"anguis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"snake, serpent","forms":["anguem","anguēs","Anguibus","anguīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam Apollō, quī deus arcū validissimus est, Pȳthōnem, {{anguem}} ingentem et tam terribilem, ut etiam dīī eum metuerent, mīlle sagittīs eius corpus percutiēns dēvīcit, ob magnam victōriam valdē gaudēbat atque glōriōsus per viās ībat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"angulus","latin":"angulus, -ī","headword":"angulus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"angle, corner","forms":["angulum","Angulus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Angulus}} mūrī erat in plāniōrem patentiorēmque vallem vergēns; adversus eum vīneās agere īnstituit, per quās ariēs moenibus admovērī posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"angusta","latin":"angusta, angustae","headword":"angusta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"small/confined/narrow space/place/passage, strait, channel; crisis, extremities","forms":["angusta"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Diodōrus: “Vīlla Iūliī sub illō monte sita est, nec vērō ab hōc locō cernī potest; sed ecce via {{angusta}} quae ad vīllam fert.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"angustia","latin":"angustia, angustiae","headword":"angustia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"narrow passage/place/space (pl.), defile; strait, pass; difficulties; meanness","forms":["angustiae","angustiās","angustiīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum {{angustiae}} multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"angustiae","latin":"angustiae, -ārum (pl.)","headword":"angustiae","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"narrowness, pass, defile; narrow pass, defile","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"angusto","latin":"angusto, angustare, angustavi, angustatus","headword":"angusto","letter":"a","pos":"verb","posGroup":"verb","english":"narrow, reduce width/size/amount, constrict, limit; choke, crowd together/hamper","forms":["angusto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ubi neminem in aequum locum sese demittere sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum {{angusto}} exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"angustum","latin":"angustum, angusti","headword":"angustum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"small/confined/narrow space/place/passage, strait, channel; crisis, extremities","forms":["angustum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut supra diximus, {{angustum}} habebat, aggerem apparare, vineas agere, turres duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"angustus","latin":"angustus, -a, -um","headword":"angustus","letter":"a","pos":"adjective","posGroup":"adjective","english":"narrow","forms":["angustam","angustiore","angustioribus","angustīs","angustōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praesidio legionum addito nostris animus augetur: hostes in fugam coiecti se ipsi multitudine impediunt atque {{angustioribus}} portis relictis coacervantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"anhelitus","latin":"anhelitus, anhelitus","headword":"anhelitus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"panting, puffing, gasping, shortness of breath; breath, exhalation; bad breath","forms":["anhēlitūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nec male odoráti sit trīstīs {{anhēlitūs}} Orīs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"anhelo","latin":"anhelo, anhelare, anhelavi, anhelatus","headword":"anhelo","letter":"a","pos":"verb","posGroup":"verb","english":"pant, gasp; breathe/gasp out, belch forth, exhale; utter breathlessly","forms":["anhēlāns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Invidus adstābat vehementī flāmine {{anhēlāns}} occiduus ventus, quī vērīs signa redūcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"anilis","latin":"anilis, anilis, anile","headword":"anilis","letter":"a","pos":"adjective","posGroup":"adjective","english":"old-womanish; of an old woman; inflicted by an old woman; old wives tale","forms":["anīlī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum haec dīxisset, Vertumnus, anīlī fōrmā vestīmentīsque dēpositīs, in iuvenem rediit, et tālis appāruit nymphae; quae, cum eius pulchritūdinem cōnspexisset, ipsa quoque statim amōre capta est et in animō vulnera sēnsit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"anima","latin":"anima, -ae","headword":"anima","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"breath, life, soul; breath, spirit; breath, spirit, soul; spirit, soul","forms":["anima","animae","animam","animās","animīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Deus fīnxit corpus hominis ē līmō terrae; dēdit illī {{animam}} vīventem; fēcit illum ad similitūdinem suam, et nōmināvit illum Adamum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"animadverto","latin":"animadvertō, animadvertere","headword":"animadvertō","letter":"a","pos":"verb","posGroup":"verb","english":"notice","forms":["animadversa","animadversum","animadvertēbant","animadvertebantur","animadvertēbat","animadvertēns","animadverterat","animadvertēre","animadverterent","animadverterētur","animadvertet","animadvertī","animadvertis","animadvertissem","animadvertisset","animadvertit","animadvertite"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante tertiam vigiliam est {{animadversum}} fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"animal","latin":"animal, animālis","headword":"animal","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(n.) animal, living being; animal","forms":["animal","animālia","animālibus","animālium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aquila enim bonōs oculōs habet et parva {{animālia}} procul vidēre potest.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"animans","latin":"animans, (gen.), animantis","headword":"animans","letter":"a","pos":"adjective","posGroup":"adjective","english":"living, having life","forms":["animantia","animantium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sextō diē fēcit omnia {{animantia}}, postrēmō hominem, et quiēvit diē septimō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"animare","latin":"(animō) animāre","headword":"animāre","letter":"a","pos":"","posGroup":"other","english":"give life to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"animatus","latin":"animatus, animata, animatum","headword":"animatus","letter":"a","pos":"adjective","posGroup":"adjective","english":"endowed with spirit, animated, spirited; inclined, minded; live, growing, fresh","forms":["animātae","animātī","animātūs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"dare illīs; sīn aliter sient animātī neque dent quae petat,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"animo","latin":"animo, animare, animavi, animatus","headword":"animo","letter":"a","pos":"verb","posGroup":"verb","english":"animate, give/bring life; revive, refresh; rouse, animate; inspire; blow","forms":["animo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque cohortatus Aeduos de supportando commeatu, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium impetum magno {{animo}} sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"animus","latin":"animus, -ī","headword":"animus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"mind, emotion, courage; soul, spirit, mind; (pl.) courage; mind, spirit, courage","forms":["animi","animōrum","animos","animum","animus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summam imperi se consulto nulli discedentem tradidisse, ne is multitudinis studio ad dimicandum impelleretur; cui rei propter {{animi}} mollitiem studere omnes videret, quod diutius laborem ferre non possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ann","latin":"ann., abb.","headword":"ann","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"year; abb. ann./a.; [regnavit ann(is). XLIIII => he reigned for 44 years]","forms":["ann"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"crēditur {{ann}}ósum pertimuisse senem:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"annalis","latin":"annālis, -e","headword":"annālis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"relating to a year","forms":["Annālem","Annālēs","annālī","annalibus","annālīs","Annālium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cassius quoque historicus in prīmō {{Annālium}} dē Homērō atque Hēsiodō trādit plūs annīs post bellum Trōiānum quam centum et sexāgintā, ante Rōmam autem conditam annīs circiter centum et sexāgintā.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"anne","latin":"anne","headword":"anne","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"can it be that (introducing a question expecting a negative answer)","forms":["anne"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"quid faciam? roger {{anne}} rogem? quid deinde rogābō? quod cupiō mēcum est...","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"annius","latin":"annius, annius","headword":"annius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"striving; exertion","forms":["Annium","Annius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tot indignitātibus commōtus graviter senātus, ante omnēs {{Annius}} cōnsulāris.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"anniversarium","latin":"anniversarium, anniversarii","headword":"anniversarium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"anniversary; birthday (Cal)","forms":["anniversārium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Claudiō Marcellō; āra Pācis, in quā sacerdōtēs virginēsque Vestālēs {{anniversārium}} sacrificium facere iussit; mausōlēum Augustī, id est monumentum in quō ossa prīncipis cremāta servantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"anniversarius","latin":"anniversārius, -a, -um","headword":"anniversārius","letter":"a","pos":"","posGroup":"other","english":"annual","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"anno","latin":"anno, annare, annavi, annatus","headword":"anno","letter":"a","pos":"verb","posGroup":"verb","english":"swim to/towards, approach by swimming; sail to/towards; brought by sea (goods)","forms":["Anna","anno"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo {{anno}} eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"annona","latin":"annona, annonae","headword":"annona","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"year's produce; provisions; allotment/rations; wheat/food; price of grain/food","forms":["annōnam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ex aliīs quoque regiōnibus conveniēbātur in Aegyptum ad emendam {{annōnam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"annulus","latin":"annulus, annuli","headword":"annulus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ring; (anulus variant); [~ Piscatoris => Pope's ring w/St. Peter casting net]","forms":["annulum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum dētrāxit ē manū suā {{annulum}}, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō torquem aureum circumdedit, eumque in currū suō secundum collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"annuo","latin":"annuo, annuere, annui, annutus","headword":"annuo","letter":"a","pos":"verb","posGroup":"verb","english":"designate w/nod, nod assent; indicate, declare; favor/smile on; agree to, grant","forms":["annuat","annuerent","annuērunt","annuī","annuit","annuō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Continuō Eliezer exposuit parentibus Rebeccae causam itineris susceptī, rogāvitque ut {{annuerent}} postulātiōnī suae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"annus","latin":"annus, -ī","headword":"annus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"year","forms":["anni","annis","annōrum","annōs","annum","annus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore {{anni}}, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"annuum","latin":"annuum, annui","headword":"annuum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"yearly payment (usu. pl.); annual stipend, pension, annuity (L+S)","forms":["annuum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et placuit nē imperium longius quam {{annuum}} habērent, nē per diuturnitātem potestātis īnsolentiōrēs redderentur, sed civīlēs semper essent, quī sē post annum scīrent futūrōs esse prīvātōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"annuus","latin":"annuus, annua, annuum","headword":"annuus","letter":"a","pos":"adjective","posGroup":"adjective","english":"for a year, lasting/appointed for a year; paid/performed yearly, annual","forms":["annua","annuōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Annua}} nōs illīc tenuit mora, multaque praesēns\ntempore tam longō vīdī, multa auribus hausī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"anomalus","latin":"anōmalus, -a, -um","headword":"anōmalus","letter":"a","pos":"adjective","posGroup":"adjective","english":"anomalous, irregular","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"anser","latin":"anser, anseris","headword":"anser","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"goose","forms":["Ānser","ānserem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nostrum ānserem occīdēmus et coctum appōnēmus.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ante","latin":"ante","headword":"ante","letter":"a","pos":"preposition","posGroup":"preposition","english":"in front of, before; before, in front of (with acc.)","forms":["ante"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam {{ante}} se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"antea","latin":"anteā","headword":"anteā","letter":"a","pos":"adverb","posGroup":"adverb","english":"before; beforehand","forms":["antea"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Docet longe alia ratione esse bellum gerendum atque {{antea}} gestum sit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"antecapere","latin":"(antecapiō) antecapere (< capere)","headword":"antecapere","letter":"a","pos":"","posGroup":"other","english":"anticipate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"antecapio","latin":"antecapio, antecapere, antecepi, anteceptus","headword":"antecapio","letter":"a","pos":"verb","posGroup":"verb","english":"take/seize beforehand, pre-occupy, forestall; anticipate","forms":["antecapere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur Iugurtha oppidum circumsēdit; vīneīs turribusque et māchinīs omnium generum expugnāre aggreditur, maximē festīnāns tempus lēgātōrum {{antecapere}} quōs ante proelium factum Rōmam ab Adherbale missōs audīverat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"antecedere","latin":"(antecēdō) antecēdere (< cēdere)","headword":"antecēdere","letter":"a","pos":"","posGroup":"other","english":"precede, surpass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"antecedo","latin":"antecedo, antecedere, antecessi, antecessus","headword":"antecedo","letter":"a","pos":"verb","posGroup":"verb","english":"precede, go before/ahead/in front of, attain before; excel, surpass, outstrip","forms":["antecēdat","antecēdēbat","antecedere","antecesserat","antecessisse","antecessit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, centurionibus et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium procul visus est, qui agmen Vercingetorigis {{antecesserat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"antecellere","latin":"(antecellō) antecellere","headword":"antecellere","letter":"a","pos":"","posGroup":"other","english":"surpass, excel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"anteeo","latin":"anteeo, anteire, anteivi(ii), anteitus","headword":"anteeo","letter":"a","pos":"verb","posGroup":"verb","english":"go/walk before/ahead, precede, antedate; surpass; anticipate; prevent","forms":["anteīret","anteit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"virtūs omnibus rēbus {{anteit}} profectō:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"antefero","latin":"antefero, anteferre, antetuli, antelatus","headword":"antefero","letter":"a","pos":"verb","posGroup":"verb","english":"carry before; place before/in front of; bring in advance, anticipate; prefer","forms":["anteferam","anteferēbat","anteferret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vīcit tamen in senātū pars illa quae vērō pretium aut grātiam {{anteferēbat}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"anteferre","latin":"(anteferō) anteferre (< ferre)","headword":"anteferre","letter":"a","pos":"","posGroup":"other","english":"prefer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"antehac","latin":"antehāc","headword":"antehāc","letter":"a","pos":"adverb","posGroup":"adverb","english":"before this; before now, formerly","forms":["antehāc"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus sē malum puerum fuisse fatētur ac simul prōmittit sē posthāc bonum puerum futūrum esse, semper sē parentibus paritūrum esse neque umquam in viā pugnātūrum neque in lūdō dormītūrum esse — id quod saepe {{antehāc}} prōmīsit!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"anteire","latin":"(anteeō) anteīre (< īre)","headword":"anteīre","letter":"a","pos":"","posGroup":"other","english":"precede, surpass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"antemna","latin":"antemna, antemnae","headword":"antemna","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"yard of a ship; yardarm; sail (poet.); antenna (Cal)","forms":["Antemnīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Multī mortālēs convēnēre studiō etiam videndae novae urbis, maximē ex oppidīs proximīs Caenīnā, Crustumeriō, {{Antemnīs}}; etiam Sabīnōrum omnis multitūdō cum līberīs ac coniugibus vēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"anteponere","latin":"(antepōnō) antepōnere (< pōnere)","headword":"antepōnere","letter":"a","pos":"","posGroup":"other","english":"place before, prefer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"antepono","latin":"antepono, anteponere, anteposui, antepositus","headword":"antepono","letter":"a","pos":"verb","posGroup":"verb","english":"set before (w/DAT), place/station before, serve (food); prefer, value above","forms":["antepōnerent","anteposuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Isaacus, amplexātus Iacobum, {{anteposuit}} eum frātrī, et tribuit illī omnia bona prīmōgenitī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"antequam","latin":"antequam","headword":"antequam","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"before; before, sooner than","forms":["antequam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam discēde, Lepide, {{antequam}} ille revenit!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"antesto","latin":"antesto, antestare, antesteti, antestatus","headword":"antesto","letter":"a","pos":"verb","posGroup":"verb","english":"surpass, excel, be superior to; stand before","forms":["antestārī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cāsū venit obvius illī adversārius, et “Quō tū, turpissimē?” magnā inclāmat vōce, et “Licet antestārī?” Ego vērō oppōnō auriculam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"antevenio","latin":"antevenio, antevenire, anteveni, anteventus","headword":"antevenio","letter":"a","pos":"verb","posGroup":"verb","english":"come/go/arrive/act before, get in front of; anticipate, forestall; surpass","forms":["antevenīre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed Marius explōrāre itinera rēgum, cōnsilia et īnsidiās eōrum {{antevenīre}}, nihil apud eōs tūtum patī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"antevenire","latin":"(anteveniō) antevenīre (< venīre)","headword":"antevenīre","letter":"a","pos":"","posGroup":"other","english":"forestall, anticipate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"anteverto","latin":"anteverto, antevertere, anteverti, anteversus","headword":"anteverto","letter":"a","pos":"verb","posGroup":"verb","english":"act first, get ahead; anticipate; forestall; give priority; take precedence","forms":["antevertendum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Qua re nuntiata, Caesar omnibus consiliis {{antevertendum}} existimavit, ut Narbonem proficisceretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"anthedon","latin":"anthedon, anthedonis","headword":"anthedon","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"species of medlar-tree, Greek medlar (Mespilus tanacet)","forms":["Anthēdonem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Piscātor quīdam, nōmine Glaucus, ōlim {{Anthēdonem}}, īnsulam Graecam, incolēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"antidhac","latin":"antidhac","headword":"antidhac","letter":"a","pos":"adverb","posGroup":"adverb","english":"before this time, up til now; before now/then; previously, earlier; in the past","forms":["antidhāc"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: Quia salūtāre advenientem mē solēbās {{antidhāc}},","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"antiquitas","latin":"antīquitās, -ātis ( f.)","headword":"antīquitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"antiquity, ancient times; antiquity, the past","forms":["antīquitātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Pompēius quī nōn modo eōrum hominum quī nunc sunt glōriam, sed etiam {{antīquitātis}} memoriam virtūte superārit, quae rēs est quae cuiusquam animum in hāc causā dubium facere possit?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"antiquo","latin":"antiquo, antiquare, antiquavi, antiquatus","headword":"antiquo","letter":"a","pos":"verb","posGroup":"verb","english":"reject (bill); vote for the rejection","forms":["antīquō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nam tempore antīquō Mārtius mēnsis prīmus erat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"antiquum","latin":"antiquum, antiqui","headword":"antiquum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"antiquity; things of olden times; old custom/habit","forms":["antīquum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In forō est templum {{antīquum}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"antiquus","latin":"antīquus, -a, -um","headword":"antīquus","letter":"a","pos":"adjective","posGroup":"adjective","english":"old, ancient, former; old, ancient","forms":["antīqua","antīquam","antīquās","antīquī","antīquiōrem","antīquīs","antiquissima","antīquissimam","Antīquissimīs","antīquissimō","antīquissimum","antīquissimus","antīquus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, {{antiquissima}} familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"antis","latin":"antis, antis","headword":"antis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"rows (pl.) (vines/plants); ranks (soldiers); files (cavalry)","forms":["antīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"petulāns -{{antīs}} adī 7 protervus, īrī-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"antistita","latin":"antistita, -ae","headword":"antistita","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"priestess","forms":["antistita"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"[Cassandra] tracta atque comīs {{antistita}} Phoebī nōn prōfectūrās tendēbat ad aethera palmās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"antonius","latin":"Antonius, Antonia, Antonium","headword":"Antonius","letter":"a","pos":"adjective","posGroup":"adjective","english":"Antony/Anthony; (Roman gens name)","forms":["Antōniī","Antōniō","Antōnium","Antōnius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Antōniī vīcisset, Iānum tertium claudī iussit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"antrum","latin":"antrum, -ī","headword":"antrum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"cave, cavern; cave, grotto","forms":["antrā","antrīs","antrō","antrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prō domō {{antrum}} aestāte frīgidum, hieme vērō calidum habeō.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"anulus","latin":"ānulus, -ī","headword":"ānulus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ring","forms":["ānulī","ānulīs","ānulō","ānulōrum","ānulōs","ānulum","ānulus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus dīcit ‘mātrem suam et gemmīs et margarītīs et ānulīs pulchrīs ōrnārī nec aliam fēminam tam fōrmōsam esse...’”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"anus","latin":"anus, -ūs","headword":"anus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) old woman","forms":["ānī","Ano","anuī","ānum","ānus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Minerva igitur, postquam tālia audīvit, sordidā veste indūta, cānōs sibi ipsa fēcit capillōs et baculō invalida membra ita sustinēbat, ut plānē anuī similis esset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"anxio","latin":"anxio, anxiare, anxiavi, anxiatus","headword":"anxio","letter":"a","pos":"verb","posGroup":"verb","english":"make uneasy/anxious/nervous; worry","forms":["anxiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Intereā Tobiās pater erat animō anxiō et sollicitō, quod suus fīlius in redeundō tardior esset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"anxius","latin":"ānxius, -a, -um","headword":"ānxius","letter":"a","pos":"adjective","posGroup":"adjective","english":"worried, worrying","forms":["Ānxia","anxiīs","anxius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ānxia, Procri, latēs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ap","latin":"Ap., abb.","headword":"Ap","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Appius (Roman praenomen); (esp, gens Claudia); Ap.Cl. Caecus built Appian Way","forms":["ap"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hēsiodus poēta nārrat *sibi Mūsās {{ap}}-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"apage","latin":"apage","headword":"apage","letter":"a","pos":"interjection","posGroup":"interjection","english":"be off!; nonsense!, get away with you!","forms":["Apage"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“{{Apage}} tē!” inquit, “Aedēs commodāvī, familiam dedī — argentum quoque vult?!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aper","latin":"aper, aprī","headword":"aper","letter":"a","pos":"noun","posGroup":"noun","english":"wild boar","forms":["aper","aprī","aprōs","aprum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum vērō iuvenis ille fortissimus per silvāsas et arduōs montēs errāre atque ferās, quae ibi latēbant, persequī solēret, Venus, quae timēbat nē bēstiae saevae eī aliquō modo nocērent, etiam atque etiam monēbat nē in lupōs, leonēs, ursōs aut {{aprōs}} impetum faceret, quī omnium perīculōsissimī esse vidēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aperio","latin":"aperio, aperire, aperui, apertus","headword":"aperio","letter":"a","pos":"verb","posGroup":"verb","english":"uncover, open, disclose; explain, recount; reveal; found; excavate; spread out","forms":["aperī","aperiam","aperienda","aperiendum","aperiēns","aperīre","aperīrem","aperīrentur","aperīret","aperīrī","aperit","aperīte","aperītur","aperiundum","aperiunt","aperiuntur","aperuērunt","aperuisse","aperuissent","aperuisset","aperuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mēdus ōstium {{aperit}} et intrat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aperire","latin":"aperīre, -iō, aperuī, apertum","headword":"aperīre","letter":"a","pos":"verb","posGroup":"verb","english":"to open","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"aperit","latin":"aperit, aperiunt","headword":"aperit","letter":"a","pos":"verb","posGroup":"verb","english":"open, disclose; opens","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aperte","latin":"aperte, apertius, apertissime","headword":"aperte","letter":"a","pos":"adverb","posGroup":"adverb","english":"openly, publicly; manifestly; w/o disguise/reserve; plainly, clearly, frankly","forms":["aperte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Bellovaci autem, defectione Aeduorum cognita, qui iam ante erant per se infideles, manus cogere atque {{aperte}} bellum parare coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aperto","latin":"aperto, apertare, apertavi, apertatus","headword":"aperto","letter":"a","pos":"verb","posGroup":"verb","english":"bare, expose, lay bare","forms":["aperto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in artiores silvas abdiderunt, copias omnes in loco edito atque {{aperto}} instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"apertum","latin":"apertum, aperti","headword":"apertum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"area free from obstacles, open/exposed space, the open (air); known facts (pl.)","forms":["apertum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum etiam atque etiam Narcissus vōcem audīvisset ad suās vōcēs respondentem, nēminem tamen vīdisset, per silvāsam ambulāre perrēxit; cum vērō ad {{apertum}} campum arboribus circumdatum pervēnisset, “Hūc coeāmus” dīxit magnā vōce.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"apertus","latin":"apertus, -a, -um","headword":"apertus","letter":"a","pos":"adjective","posGroup":"adjective","english":"open","forms":["aperta","apertae","apertam","apertās","apertī","apertis","apertos","apertus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et {{apertos}} cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"apes","latin":"apes, apis","headword":"apes","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"bee; swarm regarded as a portent","forms":["apēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Mūsae ex altō Olympō eum ōrantem audīvērunt, et {{apēs}} ad arcam mīsērunt, quae, in cubiculum per parvam rīmam ingressae, in arcam intrāvērunt et Comātam meile aluērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"apex","latin":"apex, apicis","headword":"apex","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"point, top, summit; cap, crown; conical priest cap; highest honor","forms":["apicem"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nūbila. iamque volāns {{apicem}} et latera ardua cernit","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"apis","latin":"apis, apis","headword":"apis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) bee","forms":["apis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quōdam diē, postquam multōs piscēs rētī cēperat, ē marī reversus, ita neglegenter prope ōram maritimam ambulābat, ut per ignōta loca errāret, ubi neque ūllae ovēs umquam herbam ēderant neque ūlla {{apis}} meī ē flōribus fēcerat neque agricolae, falce ūsī, frūmentum messuerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"apium","latin":"apium, api(i)","headword":"apium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"wild celery; parsley; (garlands); like plants","forms":["apium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"In mediā mēnsā vērō favum cum meile {{apium}} posuērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"apoculo","latin":"apoculo, apoculare, apoculavi, apoculatus","headword":"apoculo","letter":"a","pos":"verb","posGroup":"verb","english":"go away, remove oneself, leave","forms":["Apoculāmus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“{{Apoculāmus}} nôs circā gallicinia.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"apollo","latin":"Apollō, -inis","headword":"Apollō","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Apollo (god of music and medicine)","forms":["Apolline","Apollinem","Apollinī","Apollinis","Apollō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ita nātī sunt Apollō et Diāna, Lātōnae līberī, quōs ipsa valdē amābat; neque iam ab īnsulā discēdere volēbat: at inde quoque necesse fuit fugere: nam Iūnō eam persequēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"app","latin":"App., abb.","headword":"App","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Appius (Roman praenomen); (abb. App.)","forms":["app"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sed Hidās, quī potentiae dīvīnae magis quam numerō mīlitum cōnfīdēbat, istō terrificō bellī {{app}} aratīī nōn est commōtus; in eam castrōrum hosfilium partem irruit, ubi erat tabemaculum rēgī s, et, occīsīs quattuor hominum mīlibus, tantās opēs dissipāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"apparare","latin":"(apparō) apparāre","headword":"apparāre","letter":"a","pos":"","posGroup":"other","english":"prepare, arrange","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"apparatus","latin":"apparātus, -ūs","headword":"apparātus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"preparation, equipment","forms":["apparātū","apparātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi Deus dēdit iīs lēgem cum apparātū terrificō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"appareo","latin":"appareo, apparere, apparui, apparitus","headword":"appareo","letter":"a","pos":"verb","posGroup":"verb","english":"appear; be evident/visible/noticed/found; show up, occur; serve (w/DAT)","forms":["appāreat","appārēbant","appārēbat","appārēbit","Appārent","appārentur","appārēre","appārērent","appārēret","appāruērunt","apparuisset","appāruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum obdūxerō nūbēs caelō, arcus meus {{appārēbit}}, et recordābor foederis meī, nec unquam dīluvium erit ad perdendum orbem terrārum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"apparere","latin":"(appāreō) appārēre, appāruisse ({i}intr. + dat.{/i})","headword":"appārēre","letter":"a","pos":"","posGroup":"other","english":"appear","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"apparet","latin":"apparet, apparere","headword":"apparet","letter":"a","pos":"verb","posGroup":"verb","english":"it is apparent/evident/clear/certain/visible/noticeable/found; it appears","forms":["appāret"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum gubernātor loquitur, altera nāvis procul in marī {{appāret}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"apparo","latin":"apparo, apparare, apparavi, apparatus","headword":"apparo","letter":"a","pos":"verb","posGroup":"verb","english":"prepare, fit out, make ready, equip, provide; attempt; organize (project)","forms":["apparabant","apparandō","apparare","apparārī","apparātur","apparāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut supra diximus, angustum habebat, aggerem {{apparare}}, vineas agere, turres duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"appellare","latin":"appellāre","headword":"appellāre","letter":"a","pos":"verb","posGroup":"verb","english":"call, address by name","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"appellativum","latin":"appellātīvum, -ī","headword":"appellātīvum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(nōmen) common noun","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"appellativus","latin":"appellātīvus","headword":"appellātīvus","letter":"a","pos":"adjective","posGroup":"adjective","english":"common (of a noun)","forms":["Appellātīva","appellātīvum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Nōmen quid est?' Discipulus: 'Pars ōrātiōnis cum cāsū, corpus aut rem propriē significāns; aut enim ūnīus nōmen est et proprium dīcitur, aut multōrum et {{appellātīvum}}.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"appellatus","latin":"appellatus, appellati","headword":"appellatus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"appellee; one appealed against","forms":["appellatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Interim Teutomatus, Olloviconis filius, rex Nitiobrigum, cuius pater ab senatu nostro amicus erat {{appellatus}}, cum magno equitum suorum numero et quos ex Aquitania conduxerat ad eum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"appellere","latin":"(appellō) appellere (< pellere)","headword":"appellere","letter":"a","pos":"","posGroup":"other","english":"drive, bring (to)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"appello","latin":"appellō, appellāre","headword":"appellō","letter":"a","pos":"verb","posGroup":"verb","english":"call, address; call, name","forms":["appellā","appellabant","appellābat","appellābātur","appellābitur","appellābō","appellābuntur","appellandī","appellant","appellantem","appellantur","appellare","appellārent","appellārētur","appellārī","appellās","appellat","appellāta","appellātī","appellātis","appellātum","appellatur","appellāverint","appellāvērunt","appellāvisse","appellāvisset","appellāvit","appellem","appellent","appelletur","appelli","appellō","appulit","appulsa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Rex ab. suis {{appellatur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"appetens","latin":"appetens, appetentis (gen.), appetentior -or -us, appetentissimus -a -um","headword":"appetens","letter":"a","pos":"adjective","posGroup":"adjective","english":"eager/greedy/having appetite for (w/GEN), desirous; avaricious/greedy/covetous","forms":["appetēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hīs difficultātibus circumventus, ubi videt neque per vim neque īnsidiīs opprimī posse hominem tam acceptum populāribus, quod erat Iugurtha manū prōmptus et {{appetēns}} glōriae mīlitāris, statuit eum obiectāre perīculīs et eō modō fortūnam temptāre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"appetere","latin":"(appetō) appetere (< petere)","headword":"appetere","letter":"a","pos":"","posGroup":"other","english":"try to reach, seek, desire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"appeto","latin":"appeto, appetere, appetivi, appetitus","headword":"appeto","letter":"a","pos":"verb","posGroup":"verb","english":"seek/grasp after, desire; assail; strive eagerly/long for; approach, near","forms":["appetebat","appetere","appeteret","appetit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum {{appetebat}}, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"applicare","latin":"(applicō) applicāre","headword":"applicāre","letter":"a","pos":"","posGroup":"other","english":"attach","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"applico","latin":"applico, applicare, applicavi, applicatus","headword":"applico","letter":"a","pos":"verb","posGroup":"verb","english":"connect, place near, bring into contact; land (ship); adapt; apply/devote to","forms":["applicat","applicāvī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tunc südäriô manüs tergēns, quod in collô habēbat, {{applicat}} sē illî torô in quô Scintilla Habinnae discumbë- bat uxor, ôsculätaque plaudentem “Est tē” inquit “vidēre?” Ē6 deinde perventum est ut Fortūnāta annillās suās crassissimîs dētraheret lacertîs Scintillaeque mîrantî os- tenderet.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"apponere","latin":"appōnere","headword":"appōnere","letter":"a","pos":"verb","posGroup":"verb","english":"to serve, set before","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"apponit","latin":"appōnit, appōnere","headword":"appōnit","letter":"a","pos":"","posGroup":"other","english":"place (on), serve","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"appono","latin":"appono, apponere, apposui, appositus","headword":"appono","letter":"a","pos":"verb","posGroup":"verb","english":"place near, set before/on table, serve up; put/apply/add to; appoint/assign","forms":["appōnam","appōnēbant","appōnēbat","appōnēmus","appōnere","appōnerēmus","appōneret","Appōnēs","appōnet","appōnī","appōnit","appōnuntur","apposuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dein dēdūxit eum domum, eīque cibum {{apposuit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"apportare","latin":"(apportō) apportāre, -āvisse, -ātum","headword":"apportāre","letter":"a","pos":"","posGroup":"other","english":"carry to","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"apporto","latin":"apporto, apportare, apportavi, apportatus","headword":"apporto","letter":"a","pos":"verb","posGroup":"verb","english":"carry/convey/bring (to); import; present (play); bring (news); make one's way","forms":["apportāre","apportārī","apportat","apportō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum tē caream, nunc vītam parvī exīstimō!” Dum alia trīstissima verba dīcit et plangit, undās aliquid {{apportāre}} vīdit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"appositum","latin":"appositum, appositi","headword":"appositum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"adjective, epithet","forms":["appositum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Dum vērō cibum in mēnsā {{appositum}} sūmunt, Atalanta “Ō virī,” inquit, “usque ad hunc diem nūllum marītum habēre voluī, neque quisquam efficere potuit ut mē uxōrem dūceret nōlentem.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"appositus","latin":"appositus, apposita -um, appositior -or -us, appositissimus -a -um","headword":"appositus","letter":"a","pos":"adjective","posGroup":"adjective","english":"adjacent, near, accessible, akin; opposite; fit, appropriate, apt; based upon","forms":["apposita","appositās","appositō","appositōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Cum igitur plūra ēsse optārent, quīdam ex dīīs, impatiēns “Age, Tantale” inquit, “aliōs cibōs accipere volumus: iam prīdem eōs {{appositōs}} esse oportēbat!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"apprecor","latin":"apprecor, apprecari, apprecatus sum","headword":"apprecor","letter":"a","pos":"verb","posGroup":"verb","english":"address prayer to, pray to , invoke, beseech","forms":["apprecātus","apprecer"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum Isaacus iam senuisset, et factus esset caecus, vocāvit Esāüm: sūmitō, inquit pharetram, arcum et sagittās; affer mihi et parā dē vēnātiōne pulmentum, ut comedam et {{apprecer}} tibi fausta omnia, antequam moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"apprehendere","latin":"(apprehendō) apprehendere, apprehendisse, apprehēnsum","headword":"apprehendere","letter":"a","pos":"","posGroup":"other","english":"seize","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"apprehendo","latin":"apprehendo, apprehendere, apprehendi, apprehensus","headword":"apprehendo","letter":"a","pos":"verb","posGroup":"verb","english":"seize (upon), grasp, cling to, lay hold of; apprehend; embrace; overtake","forms":["Apprehende","apprehendendum","apprehendēns","apprehendit","apprehēnsam","apprehēnsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quādam diē mulier {{apprehendit}} ōram palliī eius; at Iōsēphus relīquit pallium in manibus eius, et fugit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"approbare","latin":"(approbō) approbāre","headword":"approbāre","letter":"a","pos":"","posGroup":"other","english":"approve","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"approbo","latin":"approbo, approbare, approbavi, approbatus","headword":"approbo","letter":"a","pos":"verb","posGroup":"verb","english":"approve, commend, endorse; prove; confirm; justify; allow; make good","forms":["approbant","approbāvissent","approbāvisset","approbō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Conclamat omnis multitudo et suo more armis concrepat, quod facere in eo consuerunt cuius orationem {{approbant}}: summum esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"appropinquare","latin":"(appropinquō) appropinquāre,  -āvisse  ({i}intr. + dat.{/i})","headword":"appropinquāre","letter":"a","pos":"","posGroup":"other","english":"approach","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"appropinquo","latin":"appropinquō, -āre, -āvī, -ātum","headword":"appropinquō","letter":"a","pos":"verb","posGroup":"verb","english":"approach","forms":["appropinquābant","appropinquābat","appropinquāns","appropinquant","appropinquante","appropinquantem","appropinquantēs","appropinquare","appropinquarent","appropinquāret","appropinquat","appropinquāvērunt","appropinquāvit","appropinquet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque {{appropinquare}} prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"appulsus","latin":"appulsus, appulsus","headword":"appulsus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"landing; approach; influence, impact; bringing/driving to (cattle) (/right to)","forms":["appulsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Alveus in līmō, silvīs {{appulsus}} opācīs, paulātim fluviō dēficiente sedet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aprico","latin":"aprico, apricare, apricavi, apricatus","headword":"aprico","letter":"a","pos":"verb","posGroup":"verb","english":"tan","forms":["apricō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dein, cum essent perpauca inter sē ūnō aut alterō spatiō collocūtī Scīpiōnīque eōrum adventus periūcundus et pergrātus fuisset, placitum est ut in apricō maximē prātulō locō, quod erat hībernum tempus annī, cōnsīderent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"apricus","latin":"aprīcus, -a, -um","headword":"aprīcus","letter":"a","pos":"","posGroup":"other","english":"sunny","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aprilis","latin":"Aprilis, Aprilis, Aprile","headword":"Aprilis","letter":"a","pos":"adjective","posGroup":"adjective","english":"April (month/mensis understood); abb. Apr.","forms":["Aprīlem","Aprīlēs","Aprīlis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; {{Aprīlis}}, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aprus","latin":"Aprus, Apra, Aprum","headword":"Aprus","letter":"a","pos":"adjective","posGroup":"adjective","english":"April (month/mensis understood); abb. Apr.","forms":["apr"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Solēbat sîc cēnāre quômodo rēx: {{apr}}ôs gausapätôs, opera pistôria `� (*) cocôs, pistôrës habet.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"apte","latin":"apte, aptius, aptissime","headword":"apte","letter":"a","pos":"adverb","posGroup":"adverb","english":"closely, snugly, so to fit tightly/exactly; neatly, aptly; suitably; fittingly","forms":["aptē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi eī in carpentō sedentī cum uxōre aquilā repente dēlāpsa pilleum aufert, superque carpentum volitāns rūrsus, velut dīvīnitus missa, capitī aptē repōnit; inde sublīmis abit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"apto","latin":"aptō (1)","headword":"aptō","letter":"a","pos":"verb","posGroup":"verb","english":"fit to, adapt to (+ dat.)","forms":["apta","aptāre","aptāret","aptat","aptātam","aptāvit","aptent","aptō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde induit Iacobum vestibus frātris; {{aptāvit}} pellem haedī manibus eius et collō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aptus","latin":"aptus, -a, -um","headword":"aptus","letter":"a","pos":"adjective","posGroup":"adjective","english":"fit, suitable, convenient","forms":["aptior","aptīs","aptissima","aptissimum","aptius","aptōs","aptum","aptus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Singulari militum nostrorum virtuti consilia cuiusque modi Gallorum occurrebant, ut est summae genus sollertiae atque ad omnia imitanda et efficienda quae ab quoque traduntur {{aptissimum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"apud","latin":"apud","headword":"apud","letter":"a","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) beside, near, by; at the house of, with (with acc.); among, at the house of","forms":["apud"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod {{apud}} eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aqua","latin":"aqua, -ae","headword":"aqua","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"water","forms":["aqua","aquae","aquam","aquārum","aquās","aquīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat e regione oppidi collis sub ipsis radicibus montis egregie munitus atque ex omni parte circumcisus; quem si tenerent nostri, et {{aquae}} magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aquae ductus","latin":"aquae ductus, -ūs","headword":"aquae ductus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"aqueduct","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"aquari","latin":"(aquor) aquārī","headword":"aquārī","letter":"a","pos":"","posGroup":"other","english":"fetch water","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aquator","latin":"aquātor, -ōris (m.)","headword":"aquātor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"one who fetches water","forms":["aquātōrēs","aquātōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aufidus amnis, utrīsque castrīs affluēns, aditum {{aquātōribus}} haud sine certāmine dabat; ex minōribus tamen castrīs, quae posita trāns Aufidum erant, līberius aquābantur Rōmānī, quia rīpa ulterior nūllum habēbat hostium praesidium.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aquila","latin":"aquila, -ae","headword":"aquila","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"eagle","forms":["aquila","aquilae","aquilam","aquilās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra: “Est {{aquila}}, quae cibum quaerit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aquilinus","latin":"aquilinus, aquilina, aquilinum","headword":"aquilinus","letter":"a","pos":"adjective","posGroup":"adjective","english":"eagle's, like that of an eagle","forms":["Aquīlīnum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Saturnīnus prōcōnsul per praecōnem dīcī iussit: “Spērātum, Nartzālum, Cittīnum, Veturium, Fēlīcem, {{Aquīlīnum}}, Laetantium, Iānuāriam, Generōsam, Vestiam, Dōnātam, Secundam dūcī iussī.” Ūniversī dīxērunt: “Deō grātiās!” Et statim dēcollātī sunt prō nōmine Christī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aquilius","latin":"Aquilius, Aquili","headword":"Aquilius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aquilius; (Roman gens name); of/named after Aquilius","forms":["Aquīliō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aquīliō Flōrō cōnsulibus, Scīpiō Corsicam et Sardiniam vāstāvit, multa mīlia inde captīvōrum abdūxit, triumphum ēgit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aquilo","latin":"Aquilō, -ōnis (m.)","headword":"Aquilō","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"north (northeast) wind; north wind","forms":["Aquilōne","Aquilōnēs","aquilōnī","aquilōnibus","aquilōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Namque tibi nūntiō sociōs tuōs salvōs esse classemque relātam et in tūtum locum āctam versīs {{Aquilōnibus}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aquitania","latin":"Aquitania, Aquitaniae","headword":"Aquitania","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Aquitania, one of the divisions of Gaul/France (southwest)","forms":["Aquitania"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Interim Teutomatus, Olloviconis filius, rex Nitiobrigum, cuius pater ab senatu nostro amicus erat appellatus, cum magno equitum suorum numero et quos ex {{Aquitania}} conduxerat ad eum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aquor","latin":"aquor, aquari, aquatus sum","headword":"aquor","letter":"a","pos":"verb","posGroup":"verb","english":"get/fetch/bring water; be watered","forms":["aquābantur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aufidus amnis, utrīsque castrīs affluēns, aditum aquātōribus haud sine certāmine dabat; ex minōribus tamen castrīs, quae posita trāns Aufidum erant, līberius {{aquābantur}} Rōmānī, quia rīpa ulterior nūllum habēbat hostium praesidium.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aquosus","latin":"aquosus, aquosa -um, aquosior -or -us, aquosissimus -a -um","headword":"aquosus","letter":"a","pos":"adjective","posGroup":"adjective","english":"abounding in water, well watered, wet; humid, rainy; clear as water, watery","forms":["aquōsus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dum pelagō dēsaevit hiems et {{aquōsus}} Ōrīōn,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ara","latin":"āra, -ae","headword":"āra","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"altar","forms":["ārā","ārae","āram","ārās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubī pervēnērunt ambō in locum dēsignātum, Abrahamus exstrūxit āram, disposuit ligna, alligāvit Isaacum super struem lignōrum, deinde arripuit gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arabia","latin":"Arabia, Arabiae","headword":"Arabia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Arabia; Aden; [~ Felix => Yemen]","forms":["Arabiā","Arabiam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In {i}Arabiā {/i} littera prīma est {i}a{/i}, nōn {i}b{/i}.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"arabs","latin":"Arabs, Arabis","headword":"Arabs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Arab, people of Arabia","forms":["Ārabēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Philistaeōs, Deō favente, domuit; Ārabēs devlcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arachne","latin":"Arachne, -ēs","headword":"Arachne","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Arachne (a maiden)","forms":["Arachnē","Arachnēn","Arachnēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Arachnē fēmina fuit, quae arte suā nōbilissima erat: saepe enim nymphae ipsae silvās et flūminis aquās relinquēbant, ut mīrābilia opera ab eā cōnfecta aspicerent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aranea","latin":"arānea, -ae","headword":"arānea","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"spider, cobweb; cobweb; spider","forms":["arānea","arāneam","aranearum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At Minerva eam inventam et in vītam reductam herbae cuiusdam sūcō aspersit; quō factum est ut tōtum eius corpus parvum fieret; in utrōque latere octo gracilia crūra appāruerunt; ex ventre verō iam ab illō tempore stāmen ēmittit: {{arānea}} enim facta, ut anteā, etiam nunc tēlās tēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"arare","latin":"(arō) arāre, arāvisse, arātum","headword":"arāre","letter":"a","pos":"","posGroup":"other","english":"plow","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"araris","latin":"Araris, Araris","headword":"Araris","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Arar/Saone; (river in Gaul, tributary of the Rhone)","forms":["Ararim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sulpicium Cabilloni et Matiscone in Aeduis ad {{Ararim}} rei frumentariae causa collocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arat","latin":"arat","headword":"arat","letter":"a","pos":"verb","posGroup":"verb","english":"ploughs","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aratius","latin":"aratius, aratia, aratium","headword":"aratius","letter":"a","pos":"adjective","posGroup":"adjective","english":"variety of fig","forms":["aratīī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sed Hidās, quī potentiae dīvīnae magis quam numerō mīlitum cōnfīdēbat, istō terrificō bellī app aratīī nōn est commōtus; in eam castrōrum hosfilium partem irruit, ubi erat tabemaculum rēgī s, et, occīsīs quattuor hominum mīlibus, tantās opēs dissipāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arator","latin":"arātor","headword":"arātor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ploughman","forms":["Arātor"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Arātor}} duōs validōs bovēs, quī arātrum trahunt, prae sē agit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aratro","latin":"aratro, aratrare, aratravi, aratratus","headword":"aratro","letter":"a","pos":"verb","posGroup":"verb","english":"plow in (young grain to improve the yield), plow (after sowing)","forms":["arātrō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quī serit nūllō īnstrūmentō ūtitur praeter manum: quī arat arātrō ūtitur, quī mētit falce ūtitur, quī serit manū suā ūtitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aratrum","latin":"arātrum, -ī","headword":"arātrum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"plow; plough","forms":["arātra","arātrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Agricola arāns post {{arātrum}} ambulat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"arbiter","latin":"arbiter, -trī (m.)","headword":"arbiter","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"eyewitness, arbitrator; judge, arbitrator","forms":["arbitrīs","arbitrōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tanaquil inter tumultum claudī rēgiam iubet, {{arbitrōs}} ēicit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"arbitrari","latin":"(arbitror) arbitrārī, arbitrātum","headword":"arbitrārī","letter":"a","pos":"verb","posGroup":"verb","english":"think, judge; to think, suppose","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"arbitratus","latin":"arbitrātus, -ūs (< arbitrārī Cap. XXII)","headword":"arbitrātus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"choice, decision","forms":["arbitrātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque Aegēus, {{arbitrātus}} mortem fīliī eō colōre significārī, sine morā dē saxō sē iēcit in mare, quod ā nōmine eius etiam nunc \"mare Aegaeum\" vocātur.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"arbitrium","latin":"arbitrium, -ī","headword":"arbitrium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"decision, wish; will, judgement","forms":["arbitrio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ex his Bellovaci suum numerum non compleverunt, quod se suo nomine atque {{arbitrio}} cum Romanis bellum gesturos dicebant, neque cuiusquam imperio obtemperaturos; rogati tamen ab Commio pro eius hospitio duo milia una miserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arbitro","latin":"arbitro, arbitrare, arbitravi, arbitratus","headword":"arbitro","letter":"a","pos":"verb","posGroup":"verb","english":"think, judge; consider; be settled/decided on (PASS)","forms":["arbitrō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō Aemiliānus, cum commūne hīs rēgnum pater relīquisset et dīvidere eōs arbitrō Scīpiōne iussisset, partēs administrandī rēgnī dīvīsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"arbitror","latin":"arbitror, -ārī, -ātus sum","headword":"arbitror","letter":"a","pos":"verb","posGroup":"verb","english":"think, judge","forms":["arbitrābar","arbitrābātur","arbitrāminī","arbitrantur","arbitrāre","arbitrārēmur","arbitrārentur","arbitraretur","arbitrārī","arbitrārier","arbitrāris","arbitrātū","arbitrātum","arbitrātur","arbitror"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum iam muro turres appropinquassent, ex captivis Caesar cognovit Vercingetorigem consumpto pabulo castra movisse propius Avaricum atque ipsum cum equitatu expeditisque qui inter equites proeliari consuessent insidiarum causa eo profectum quo nostros postero die pabulatum venturos {{arbitraretur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arbor","latin":"arbor, arboris","headword":"arbor","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) tree","forms":["arbor","arbore","arborem","arborēs","arborī","arboribus","arboris","arborum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque truncis {{arborum}} aut admodum firmis ramis abscisis atque horum delibratis ac praeacutis cacuminibus perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arboreus","latin":"arboreus, arborea, arboreum","headword":"arboreus","letter":"a","pos":"adjective","posGroup":"adjective","english":"tree-, of tree(s); resembling a tree, branching; wooden","forms":["arboreīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cornibus {{arboreīs}}, sternit, tum volgus, et omnem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"arbutus","latin":"arbutus, arbuti","headword":"arbutus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"arbutus, strawberry tree (Arbutus unedo)","forms":["arbutus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{arbutus}} À silva nemus nōn alta facit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"arca","latin":"arca, arcae","headword":"arca","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"box, chest; strong-box, coffer; wealth, money; coffin, bier; cell, cage; ark","forms":["arca","arcae","arcam","Arcas"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Noēmus, admonitus ā Deō, exstrūxit ingentem {{arcam}} in modum nāvis; līnīvit eam bitūmine, et in eam indūxit pār ūnum omnium avium et animantium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arcadia","latin":"Arcadia, -ae","headword":"Arcadia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Arcadia (a region of the Peloponnesus, dear to Jupiter)","forms":["Arcadiā","Arcadiam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Callistō optima omnium fēminārum in Arcadiā habitantium fuit, Arcasque, eius fīlius, pulcherrimus omnium puerōrum esse vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"arcanus","latin":"arcanus, arcana, arcanum","headword":"arcanus","letter":"a","pos":"adjective","posGroup":"adjective","english":"secret, private, hidden; intimate, personal; confidential; mysterious, esoteric","forms":["arcāna","arcānōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nīl opus est digitīs per quōs {{arcāna}} loquāris,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"arcas","latin":"Arcas, Arcadis","headword":"Arcas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Arcas (son of Callisto)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"arceo","latin":"arceo, arcere, arcui, -","headword":"arceo","letter":"a","pos":"verb","posGroup":"verb","english":"ward/keep off/away; keep close, confine; prevent, hinder; protect; separate","forms":["arceās","arcēbat","arcēbis","arcendam","arcēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id metuēns et memor veteris bellī quod ad Trōiam prō cārīs Argīs gesserat — nōndum oblīta erat causam īrae ac dolōris: iūdicium Paridis, quī Venerem deam pulcherrimam esse iūdicāverat — Trōiānōs per mare tōtum iactātōs longē ā Latiō {{arcēbat}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"arcere","latin":"(arceō) arcēre, arcuisse, arctum","headword":"arcēre","letter":"a","pos":"","posGroup":"other","english":"keep away","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"arcessit","latin":"arcessit, arcessere","headword":"arcessit","letter":"a","pos":"verb","posGroup":"verb","english":"send for, fetch; sends for, summons","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"arcessitus","latin":"arcessitus, arcessita, arcessitum","headword":"arcessitus","letter":"a","pos":"adjective","posGroup":"adjective","english":"brought from elsewhere, foreign; extraneous; self-inflicted (death); sent for","forms":["arcessītus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Arcessītus}} est Dāvīd huiusce artīs perītus, quī ob illud mūnus inter ministrōs rēgiōs habēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arcesso","latin":"arcesso, arcessere, arcessivi, arcessitus","headword":"arcesso","letter":"a","pos":"verb","posGroup":"verb","english":"send for, summon, indict; fetch, import; invite; invoke; bring on oneself","forms":["arcessam","arcessat","arcesse","arcessere","arcesseret","arcessī","arcessit","Arcessītē","arcessītis","arcessītō","arcessītum","arcessīvit","arcessunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam, si legiones in provinciam {{arcesseret}}, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arcisellium","latin":"arcisellium, arciselli(i)","headword":"arcisellium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"chair with rounded back","forms":["arcisellium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Puerum bäsiävî ﬁügälissimum, nôn propter fôr- mam, sed quia frügî est: decem partēs dîcit, librum ab oculô lēgit, thretium sibi dē diäriîs fēcit, {{arcisellium}} dē suô parāvit et duās trul- “Ita tibi vidētur, fulcipedia?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"arco","latin":"arco, arcere, arcui, -","headword":"arco","letter":"a","pos":"verb","posGroup":"verb","english":"keep away, protect","forms":["arc"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"(animum) | interiōra r: pl : {{arc}}àna","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"arcturus","latin":"Arcturus, Arcturi","headword":"Arcturus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Acturus, brightest star in Bootes; the whole constellation; arction plant","forms":["Arctūrum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Arctūrum}} pluviāsque Hyadas geminōsque Triōnēs;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"arcuatus","latin":"arcuātus, -a, -um","headword":"arcuātus","letter":"a","pos":"adjective","posGroup":"adjective","english":"arched","forms":["arcuātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ductus eius habet longitūdinem passuum ūndecim mīlium centum nōnāgintā (ex eō rīvus est subterrāneus passuum ūndecim mīlium centum trīgintā, suprā terram opus {{arcuātum}} passuum sexāgintā).","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"arcus","latin":"arcus, arcūs","headword":"arcus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"bow","forms":["arcū","arcubus","arcum","arcus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Deus dīxit illī: nōn dēlēbō deinceps genus hominum: pōnam {{arcum}} meum in nūbibus, et erit signum foederis quod faciō vōbīscum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ardea","latin":"ardea, ardeae","headword":"ardea","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"heron","forms":["Ardea"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Temptāta rēs est sī prīmō impetū capī {{Ardea}} posset; ubi id parum prōcessit, Rōmānī urbem obsidēre coepērunt, castrīs sub moenibus positīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ardens","latin":"ardens, ardentis (gen.), ardentior -or -us, ardentissimus -a -um","headword":"ardens","letter":"a","pos":"adjective","posGroup":"adjective","english":"burning, flaming, glowing, fiery; shining, brilliant; eager, ardent, passionate","forms":["ārdēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Esāüs ārdēns īra minābātur mortem Iacobō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ardeo","latin":"ardeō, -ēre, ārsī, ārsum","headword":"ardeō","letter":"a","pos":"verb","posGroup":"verb","english":"be on fire, burn with love, glow","forms":["Ardeam","ardēbant","ārdēbat","ārdēbunt","ārdent","ārdentem","ardentēs","ārdentī","ardentibus","ārdentis","ārdēre","ārderent","ārderet","ārdet","ārsisse","ārsit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ego aliquam domum ārdēre putō.” brevī tempore viae oppidī implentur hominibus, quī omnēs in eam partem currunt unde fūmus oritur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ardere","latin":"(ārdeō) ārdēre, arsisse, arsum","headword":"ārdēre","letter":"a","pos":"","posGroup":"other","english":"burn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ardor","latin":"ārdor, -ōris (m.)","headword":"ārdor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"burning, fire, ardor; burning, heat, eagerness","forms":["ardor","ardōre"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multās tamen fēminās {{ardor}} iungere sē vātī habēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"arduum","latin":"arduum, ardui","headword":"arduum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"steep/high place, heights, elevation; arduous/difficult/hard task; challenge","forms":["arduum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed elati spe celeris victoriae et hostium fuga et superiorum temporum secundis proeliis, nihil adeo {{arduum}} sibi esse existimaverunt quod non virtute consequi possent, neque finem prius sequendi fecerunt quam muro oppido portisque appropinquarunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arduus","latin":"arduus, -a, -um","headword":"arduus","letter":"a","pos":"adjective","posGroup":"adjective","english":"steep; steep, difficult; hard, difficult","forms":["ardua","arduae","arduās","arduī","arduōs","arduus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum vērō iuvenis ille fortissimus per silvāsas et {{arduōs}} montēs errāre atque ferās, quae ibi latēbant, persequī solēret, Venus, quae timēbat nē bēstiae saevae eī aliquō modo nocērent, etiam atque etiam monēbat nē in lupōs, leonēs, ursōs aut aprōs impetum faceret, quī omnium perīculōsissimī esse vidēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"area","latin":"ārea, -ae","headword":"ārea","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"open space, site; open space, arena","forms":["āreā","āream"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et prôdîsset in medium, decēre gravitātem eius tam humilēs ineptiās! ’ [Âctuärius ācta praediôrum recitat] Et plānē interpellāvit saltätiônis libîdinem āctuārius, 53 quī tamquam urbis âcta recitāvit: VIĪ kalendās Sextîlês: in prae- diô Cūmānä, quod est Trimal- chiônis, nātī sunt puerÏXIOÇ pu- ellae XL; sublāta in horreum ex āreā trīticī mîlia modium quîn- genta; bovēs domitî quîngentï.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"arens","latin":"arens, (gen.), arentis","headword":"arens","letter":"a","pos":"adjective","posGroup":"adjective","english":"dry parched, waterless; dried (herbs); parching (thirst)","forms":["ārentem","ārentī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hebraeī incēdēbant per ārentem alveum, dōnec rīpam oppositam attingerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"areo","latin":"areo, arere, arui, -","headword":"areo","letter":"a","pos":"verb","posGroup":"verb","english":"be dry/parched; be thirsty; be withered (plants/animals, from lack of water)","forms":["āre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"125 Ō, quotiēns illum doluit prōpēràāre Calypsō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"argenteus","latin":"argenteus, -a, -um","headword":"argenteus","letter":"a","pos":"adjective","posGroup":"adjective","english":"made of silver; silver","forms":["argentea","argenteae","argenteam","argenteās","argenteī","argenteīs","argenteum","argenteus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Eliezer dēprōmpsit vās aurea et {{argentea}}, vestēsque pretiōsās, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"argentum","latin":"argentum, -ī","headword":"argentum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"silver","forms":["argentī","argentō","argentum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Salomōn templum immēnsī operis Hierosolymae aedificāvit: omnia aurō, argentō, gemmīsque in eō fulgēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"argonautae","latin":"Argonautae, -ārum","headword":"Argonautae","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"the Argonauts (sailors on the Argo)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"argosos","latin":"Argosos, Argi","headword":"Argosos","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"Argos; (city in the Peloponnese, kingdom of Agamemnon)","forms":["Argī","Argīs","Argō","Argōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At Iūnō, quae cōnsilium eius intellēxerat, hanc vaccam ā maritō poposcit, quī, ut amōrem suum cēlāret, nihil aliud facere nisi eam uxōri dōnāre poterat. lūnō tamen adhūc verēns nē dōnum nūper acceptum ā maritō surriperētur, hanc vaccam Argō, pastōri et servō suō ēgregiō, cūstōdiendam dedit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"arguere","latin":"(arguō) arguere, -uisse, -ūtum","headword":"arguere","letter":"a","pos":"","posGroup":"other","english":"reveal, affirm, accuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"argumentum","latin":"argūmentum, -ī","headword":"argūmentum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"proof, argument","forms":["argūmenta","argūmentīs","argūmentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vîcit scîlicet, et Îphigenîam, ﬁliam suam, Achillî dedit uxô- rem. 0b eam rem Âiäx însänit et statim {{argūmentum}} Haec ut dîxit Trimalchiô, clämôrem Homēristae sustulērunt, intcrque familiam discurrentem vitulus in lance ducënâriä ēlixus allātus est, et quidem galeātus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"arguo","latin":"arguo, arguere, argui, argutus","headword":"arguo","letter":"a","pos":"verb","posGroup":"verb","english":"prove, argue, allege; disclose; accuse, complain of, charge, blame, convict","forms":["arguantur","Arguat","arguēbat","arguere","arguerent","arguerentur","arguet","arguit","arguitō","arguitur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Illī porrō metuēbant nē {{arguerentur}} dē pecūniā quam in saccīs repererant; quārē pūrgāvērunt sē apud dispēnsātōrem Iōsēphī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arguto","latin":"arguto, argutare, argutavi, argutatus","headword":"arguto","letter":"a","pos":"verb","posGroup":"verb","english":"babble, say childishly/foolishly","forms":["argūtat"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Dēdit gladiätôrës sëstertiâriôs iam dëcrepitôs, quôs sī suf- “Vidēris mihi, Agamemnôn, dîcere: “Quid iste {{argūtat}} molestus?” Quia tū, quī potes loquî, nôn loqueris.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"argutus","latin":"argutus, arguta -um, argutior -or -us, argutissimus -a -um","headword":"argutus","letter":"a","pos":"adjective","posGroup":"adjective","english":"melodious, clear (sounds), ringing; eloquent; wise, witty, cunning; talkative","forms":["argūtam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"stuprī, dēdecoris ā virō {{argūtam}} meō!—","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ariadna","latin":"Ariadna, -ae","headword":"Ariadna","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Ariadne, daughter of Minos","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ariadne","latin":"Ariadne, Ariadnes","headword":"Ariadne","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Ariadne; (daughter of Minos, helped Theseus, wed Bacchus)","forms":["Ariadnae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tum Thēseus, fīlum {{Ariadnae}} post sē trahēns, labyrinthum intrāvit ac sine morā Mīnōtaurum in mediā parte exspectantem petīvit, quem post brevem pugnam gladiō occīdit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"arida","latin":"arida, aridae","headword":"arida","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"dry land; dry place; dry surface; dryness","forms":["ārida"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"crēdita : sēmina sata (agrō crēdita) terraque caelestēs ārida","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aridus","latin":"āridus, -a, -um","headword":"āridus","letter":"a","pos":"adjective","posGroup":"adjective","english":"dry, barren","forms":["aridam","āridus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Alii faces atque {{aridam}} materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aries","latin":"ariēs, -ētis, (m.)","headword":"ariēs","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ram, battering ram; a ram","forms":["ariēs","ariete","arietem","arietibus","arietis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab {{ariete}} materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aris","latin":"aris, aridis","headword":"aris","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"plant resembling arum; dragon-root, green dragon (L+S)","forms":["ārīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīc dē mōre patriō cum Iovī sacra parāvissent, ut āra accēnsīs ignibus incanduit, Danai dracōnem in arbore vīdēre quae proxima ārīs sacrīs stābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"arista","latin":"arista, aristae","headword":"arista","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"awn, beard of an ear of grain; ear of grain; grain crop; harvest","forms":["aristae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Horruit, ut sterilēs agitat quàs ventus {{aristae}},","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"arma","latin":"arma, -ōrum","headword":"arma","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(n. pl.) arms; weapons, arms; arms, weapons","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"armare","latin":"(armō) armāre, armāvisse, armātum","headword":"armāre","letter":"a","pos":"verb","posGroup":"verb","english":"arm; to arm","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"armarium","latin":"armarium, armari(i)","headword":"armarium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"cabinet, closet, cupboard; chest, safe; book-case; sepulchral monument","forms":["armārium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Praeter- eä grande {{armārium}} in angulô vîdî, in cuius aediculā erant Larēs argenteî positī Venerisque signum marmoreum et pyxis aurea nôn pusilla, in quā barbam ipsîus Interrogāre ego ātriēnsem coepī ‘quās in mediô pictūrās habērent?’ “Îliada et Odys- sîan”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"armatura","latin":"armātūra, -ae","headword":"armātūra","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"armament, armed troops","forms":["armātūrā","armaturae","armātūram","armātūrārum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Caesar, quod hostes equitatu superiores esse intellegebat et interclusis omnibus itineribus nulla re ex provincia atque Italia sublevari poterat, trans Rhenum in Germaniam mittit ad eas civitates quas superioribus annis pacaverat equitesque ab his arcessit et levis {{armaturae}} pedites, qui inter eos proeliari consuerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"armatus","latin":"armātus, -a, -um","headword":"armātus","letter":"a","pos":"adjective","posGroup":"adjective","english":"armed","forms":["armātā","armātae","armātī","armātīs","armātō","armātōrum","armātōs","armātum","armātus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius virum {{armātum}} timet, quia ipse arma nōn fert; itaque mīlitem equum ascendere iubet: “Ascende!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"armenia","latin":"Armenia, Armeniae","headword":"Armenia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Armenia; (country lying north of Persia)","forms":["Armenia","Armēniae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Terrae in Āsiā sunt Āsia Minor, {{Armenia}}, Mesopotamia, Arabia, Syria, Phoenīcē.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"armenius","latin":"Armenius, Armenia, Armenium","headword":"Armenius","letter":"a","pos":"adjective","posGroup":"adjective","english":"Armenian; [~ prunum => apricot]","forms":["Armēnius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc in illō timōre et fugā Tigrānēs, rēx {{Armēnius}}, excēpit diffīdentemque rēbus suīs cōnfirmāvit et afflīctum ērēxit perditumque recreāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"armenta","latin":"armenta, armentae","headword":"armenta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"herd (of cattle); a head of cattle, individual bull/horse; cattle/horses (pl.)","forms":["armenta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"prōspicit errantīs; hōs tōta {{armenta}} sequuntur","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"armentum","latin":"armentum, -ī","headword":"armentum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(herd of ) cattle; herd of cattle","forms":["armentī","armentīs","armentum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"candidus — armentī glōria","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"armifer","latin":"armifer, armifera, armiferum","headword":"armifer","letter":"a","pos":"adjective","posGroup":"adjective","english":"bearing arms, armed; warlike, martial, of war/fighting; producing armed men","forms":["armiferīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"5 Tālis ab {{armiferīs}} Priamēius hospes Amȳclīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"armiger","latin":"armiger, armigeri","headword":"armiger","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"armor bearer; squire; [Iovis armiger => Jupiter's armor-bearer = the eagle]","forms":["armigerī","armigerō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sōlō armigerō comite, castra hostium ingressus est, et vīgintī ferē Philistaeīs interemptīs, ūniversum exercitum terrōre perculit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"armilla","latin":"armilla, -ae","headword":"armilla","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"bracelet; bracelet, armlet","forms":["armillam","armillās","armjllā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eliezer prōtulit inaurēs aureās et {{armillās}}, quās dēdit Rebeccae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"armo","latin":"armo, armare, armavi, armatus","headword":"armo","letter":"a","pos":"verb","posGroup":"verb","english":"equip, fit with armor; arm; strengthen; rouse, stir; incite war; rig (ship)","forms":["armandos","armārī","armat","armāverat","armāvit","arment"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui Avarico expugnato refugerant, {{armandos}} vestiendosque curat; simul, ut deminutae copiae redintegrarentur, imperat certum numerum militum civitatibus, quem et quam ante diem in castra adduci velit, sagittariosque omnes, quorum erat permagnus numerus in Gallia, conquiri et ad se mitti iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"armum","latin":"armum, armi","headword":"armum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"arms (pl.), weapons, armor, shield; close fighting weapons; equipment; force","forms":["arma","armis","armorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cognito eius consilio ad {{arma}} concurritur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aro","latin":"arō, -āre, -āvī, -ātum","headword":"arō","letter":"a","pos":"verb","posGroup":"verb","english":"plough","forms":["Arabās","arandum","arāns","arant","arantur","arāre","arārī","arat","arātōs","arātus","arāverit","ārent","āret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Illōrum narū maximus dēclārāvit sē suōsque frātrēs p {{arātōs}} esse morī, magis quam culpam committere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aroma","latin":"aroma, aromatis","headword":"aroma","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"spice, aromatic substance; sweet odors (Bee)","forms":["arōmata"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde cum cōnsēdissent ad sūmendum cibum, cōnspexērunt mercātōrēs quī petēbant Aegyptum cum camēlīs portantibus varia {{arōmata}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arrectus","latin":"arrectus, arrecta -um, arrectior -or -us, arrectissimus -a -um","headword":"arrectus","letter":"a","pos":"adjective","posGroup":"adjective","english":"erect, perpendicular, upright, standing; steep, precipitous; excited, eager","forms":["arrēctī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīs animum arrēctī dictīs et fortis Achātēs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"arrideo","latin":"arrideo, arridere, arrisi, arrisus","headword":"arrideo","letter":"a","pos":"verb","posGroup":"verb","english":"smile at/upon; please, be pleasing/satisfactory (to); be/seem familiar (to)","forms":["arrīdēns","arrīdēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"cum rīsī, {{arrīdēs}}; lacrimās quoque saepe notāvī mē lacrimante tuās!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"arridere","latin":"(arrīdeō) arrīdēre (< ridēre)","headword":"arrīdēre","letter":"a","pos":"","posGroup":"other","english":"smile at","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"arripere","latin":"(arripiō) arripere (< rapere)","headword":"arripere","letter":"a","pos":"","posGroup":"other","english":"grasp, take hold of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"arripio","latin":"arripio, arripere, arripui, arreptus","headword":"arripio","letter":"a","pos":"verb","posGroup":"verb","english":"take hold of; seize (hand/tooth/claw), snatch; arrest; assail; pick up, absorb","forms":["arrēptā","arripit","arripuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubī pervēnērunt ambō in locum dēsignātum, Abrahamus exstrūxit āram, disposuit ligna, alligāvit Isaacum super struem lignōrum, deinde {{arripuit}} gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arrogare","latin":"(arrogō) arrogāre","headword":"arrogāre","letter":"a","pos":"","posGroup":"other","english":"claim as one’s own; claim for someone else","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"arrogo","latin":"arrogo, arrogare, arrogavi, arrogatus","headword":"arrogo","letter":"a","pos":"verb","posGroup":"verb","english":"ask, question; arrogate to one's self, claim, make undue claim; confer (upon)","forms":["arrogāvisset","arrogāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Vix perāctō sacrificiō vēnit Samūēl, rēgemque graviter reprehendit, quod mūnus proprium sacerdōtum sibi temere {{arrogāvisset}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ars","latin":"ars, artis","headword":"ars","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) art, skill; art, skill, profession, conduct","forms":["ars","artem","artēs","arti","artibus","artīs","artium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Arcessītus est Dāvīd huiusce {{artīs}} perītus, quī ob illud mūnus inter ministrōs rēgiōs habēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"arte","latin":"arte, artius, artissime","headword":"arte","letter":"a","pos":"adverb","posGroup":"adverb","english":"closely/tightly (bound/filled/holding); briefly, in a confined space, compactly","forms":["arte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His collocatis et coagmentatis alius insuper ordo additur, ut idem illud intervallum servetur neque inter se contingant trabes, sed paribus intermissae spatiis singulae singulis saxis interiectis {{arte}} contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"artifex","latin":"artifex, -icis (m.)","headword":"artifex","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"craftsman, master, artist; artist, craftsman","forms":["artifex","artificem","artificēs","artificum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Artifex}} colōribus urnās pingit; format pictūrās dē deīs et dē herōe Graecō, Ulixe.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"artificium","latin":"artificium, -ī","headword":"artificium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"skill, art, cunning","forms":["artificio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Non virtute neque in acie vicisse Romanos, sed {{artificio}} quodam et scientia oppugnationis, cuius rei fuerint ipsi imperiti.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"artius","latin":"artius, artia, artium","headword":"artius","letter":"a","pos":"adjective","posGroup":"adjective","english":"sound in mind and body; complete, perfect; skilled in arts; artful, cunning","forms":["artius"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam utī plānitiēs erat inter sinistrōs montēs et ab dextrā rūpēs asperās, octo cohortēs in fronte cōnstituit, reliquārum signa in subsidiō {{artius}} collocat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"artus","latin":"artus, -a, -um","headword":"artus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"close, tight, deep; joint; (pl.) limbs","forms":["artā","Ārtior","artiores","artūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in {{artiores}} silvas abdiderunt, copias omnes in loco edito atque aperto instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arum","latin":"arum, ari","headword":"arum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"plants of genus arum","forms":["arum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Bāiae -{{arum}} f pl, oppidum Campa-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"arva","latin":"arva, arvae","headword":"arva","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"arable land, plowed field; soil, region; countryside; dry land; lowlands, plain","forms":["arva"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"oppida clāra hominum, rīdentiaque {{arva}} petēbat","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"arvernus","latin":"Arvernus, Arverni","headword":"Arvernus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Arverni (pl.); (tribe of SE Gaul - in Caesar's Gallic War)","forms":["Arverni","Arvernis","Arverno","Arvernorum","Arvernos","Arvernum","Arvernus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus {{Arvernorum}} audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"arvum","latin":"arvum, -ī","headword":"arvum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"(plowed) field; field, ploughed land; field, ploughland","forms":["arvīs","arvō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"... pavor occupat illum, ante oculōsque natant tenebrae retrōque ferentī āversōs passūs mediō lapis obstitit arvō; quem super impulsum resupīnō corpore Cygnum vī multā vertit terraeque affīxit Achillēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"arx","latin":"arx, arcis ( f.)","headword":"arx","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"hilltop, citadel; citadel; citadel, height","forms":["arce","arcem","arcēs","arcī","arcis","arx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vercingetorix ex {{arce}} Alesiae suos conspicatus ex oppido egreditur, crates, longurios, musculos, falces reliquaque quae eruptionis causa paraverat profert.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"as","latin":"as, assis","headword":"as","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) as (copper coin); an as (coin)","forms":["as","asse","assem","assēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Ē sther:\"Meam, ō rēx, meaeque gentis salūtem precor, nam crūdēlis iste Amān nōs dēvōvit necī.\"Quā rē permōtus est {{As}} suerus, audiēnsque crucem ab eō parātam esse Mardochaēō, Amanem ipsum eīdem crucī iussit affigī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"asa","latin":"asa, asae","headword":"asa","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"altar, structure for sacrifice, pyre; sanctuary; home; refuge, shelter","forms":["Asa","Asae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Roboamō patrī successit Abia, quī trēs tantum annōs rēgnāvit, soliumque relīquit {{Asae}} fīlī ō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ascanius","latin":"Ascanius, Ascanii","headword":"Ascanius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Ascanius/Iulus; (son of Aeneas)","forms":["Ascanīī","Ascanīō","Ascanium","Ascanius"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aenēās rapidum ad nāvīs praemittit Achātēn,\n[ut] Ascanīō ferat haec, ipsumque ad moenia dūcat;\nomnis in Ascanīō cārī stat cūra parentis.\n[eum] Mūnera praetereā Īliacīs ērepta ruīnīs\nferre iubet. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ascendens","latin":"ascendens, (gen.), ascendentis","headword":"ascendens","letter":"a","pos":"adjective","posGroup":"adjective","english":"of/for climbing (machine); enabling one to climb","forms":["ascendēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Tandem in eius tergum {{ascendēns}} cōnsīdit et “Ō amīcae, venīte, et mē spectāte!” inquit, “vidēte mē in taurī tergō sedentem!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ascendit","latin":"ascendit, ascendere","headword":"ascendit","letter":"a","pos":"verb","posGroup":"verb","english":"climb, go up, mount; climbs, goes up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ascendo","latin":"ascendō, -ere, -scendī, -scēnsum","headword":"ascendō","letter":"a","pos":"verb","posGroup":"verb","english":"mount, ascend, go up","forms":["ascendam","ascendās","Ascende","ascendēbant","ascendēbat","ascendente","ascendentem","ascendentēs","ascendentibus","ascenderant","ascendere","ascenderet","ascenderīs","ascendērunt","ascendimus","ascendissent","ascendisset","ascendit","Ascendite","ascendunt","ascensu","ascensum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus expositis signum dat et ab dextra parte alio {{ascensu}} eodem tempore Aeduos mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ascensus","latin":"ascensus, ascensus","headword":"ascensus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ascent; act of scaling (walls); approach; a stage/step in advancement; height","forms":["ascensus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio {{ascensus}} recta regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum clivum accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ascia","latin":"ascia, asciae","headword":"ascia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"carpenter's axe; mason's trowel; [sub ~ => under the trowel/construction]","forms":["asciam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Scîs tñ mē nôn mentîrî: Agathô unguentārius proximē sēdūxit mē et “Suädeô” inquit “nôn patiāris genus tuum interîre.” At ego, dum bōnātus agô et nôlô vidërî levis, ipse mihi {{asciam}} in crūs “Rēctē!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"asciscere","latin":"(ascīscō) ascīscere, -scīvisse, -scītum","headword":"ascīscere","letter":"a","pos":"verb","posGroup":"verb","english":"admit, adopt; to admit, adopt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"ascisco","latin":"ascisco, asciscere, ascivi, ascitus","headword":"ascisco","letter":"a","pos":"verb","posGroup":"verb","english":"adopt, assume; receive, admit, approve of, associate; take over, claim","forms":["ascīvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quō foedere et Sabīnōs in cīvitātem {{ascīvit}}, sacris commūnicātis, et rēgnum suum cum illōrum rēge sociāvit.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ascribo","latin":"ascribo, ascribere, ascripsi, ascriptus","headword":"ascribo","letter":"a","pos":"verb","posGroup":"verb","english":"add/state in writing, insert; appoint; enroll, enfranchise; reckon, number","forms":["ascrībere"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quam tangere ut nōn potuit, discēdēns ait: “Nōndum mātūra est, nōlō acerbam sūmere!” Quī facere quae nōn possunt verbīs ēlevant, {{ascrībere}} hoc dēbēbunt exemplum sibī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"asella","latin":"asella, asellae","headword":"asella","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"small/little she-ass","forms":["asella"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"290 utrūdīta scabrà turpis {{asella}} molā!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"asellus","latin":"asellus, aselli","headword":"asellus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(small/young) ass, donkey; fish of the cod family, hake?; Asses/stars in Cancer","forms":["asellī","asellum","asellus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mīdās damnātus in ūnā parte corporis aurēs asellī gerit, quamquam cēterae partēs sunt hominis.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"asia","latin":"Āsia, -ae","headword":"Āsia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Asia","forms":["Āsia","Asiae","Āsiam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlia: “Suria est in Asiā.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"asiaticus","latin":"Asiaticus, Asiatica, Asiaticum","headword":"Asiaticus","letter":"a","pos":"adjective","posGroup":"adjective","english":"Asiatic, of/connected with Asia/the East/Asia Minor; w/Asiatic/florid style","forms":["Asiāticus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēliō Scīpiōne — adiuvante Eumene, rēge Pergamī — pāx data est eā condiciōne 'ut omnibus prōvinciīs citrā Taurum montem cēderet.' Cornēlius Scīpiō, quī cum Antiochō dēbellāverat, eō cognōmine frātrī exaequātus '{{Asiāticus}}' appellātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"asina","latin":"asina, asinae","headword":"asina","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"she-ass","forms":["Asinā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēliō Asinā cōnsulibus, in marī dīmicāvērunt parātīs nāvibus rōstrātīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"asininus","latin":"asinīnus, -a, -um","headword":"asinīnus","letter":"a","pos":"adjective","posGroup":"adjective","english":"asinine; of a donkey","forms":["asinīnās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Deus Apollō effēcerat ut Midās aurēs {{asinīnās}} habēret...' Iūlius: 'Satis est!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"asinus","latin":"asinus, -ī","headword":"asinus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"ass, donkey","forms":["asinī","asinum","asinus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Trāditus Philistaeīs rūpit vincula, quibus constrīctus erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aspecto","latin":"aspecto, aspectare, aspectavi, aspectatus","headword":"aspecto","letter":"a","pos":"verb","posGroup":"verb","english":"look/gaze at/upon; observe, watch; pay heed; face/look towards (place/person)","forms":["aspectās","aspectat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Caelum {{aspectat}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"aspectus","latin":"aspectus, aspectus","headword":"aspectus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"appearance, aspect, mien; act of looking; sight, vision; glance, view; horizon","forms":["aspectū","aspectum","aspectūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Omnes alacres et fiduciae pleni ad Alesiam proficiscuntur, neque erat omnium quisquam qui {{aspectum}} modo tantae multitudinis sustineri posse arbitraretur, praesertim ancipiti proelio, cum ex oppido eruptione pugnaretur, foris tantae copiae equitatus peditatusque cernerentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"aspello","latin":"aspello, aspellere, -, -","headword":"aspello","letter":"a","pos":"verb","posGroup":"verb","english":"drive away; banish","forms":["aspellam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"[tēctum mōnstrāns] atque illāc sūrsum ēscenderō, inde optimē {{aspellam}} virum","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"asper","latin":"asper, -era, -erum","headword":"asper","letter":"a","pos":"adjective","posGroup":"adjective","english":"rough, harsh, grievous","forms":["asper","aspera","asperam","asperās","asperior","asperius","asperōs","asperrima"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"« {{asper}} -era -erum — ferus, sevērus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aspergere","latin":"(aspergō) aspergere, aspersisse, aspersum","headword":"aspergere","letter":"a","pos":"verb","posGroup":"verb","english":"sprinkle/strew on; to sprinkle on","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"aspergo","latin":"aspergo, aspergere, aspersi, aspersus","headword":"aspergo","letter":"a","pos":"verb","posGroup":"verb","english":"sprinkle/strew on, splatter, splash; defile, stain; cast (slur); inflict (harm)","forms":["aspergere","aspergit","aspersa","aspersissent","aspersit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Cadmus vērō, cum mīlitum suōrum ossa, cruōre {{aspersa}}, sub arbore iacentia vidēret, nūllō modō dēterritus est nē saevum dracōnem oppugnāret, at prōtinus magnā vōce clāmāvit: “Pereat istud mōnstrum, dignum pessimā morte!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"asperitas","latin":"asperitās, -ātis ( f.)","headword":"asperitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"roughness, ruggedness","forms":["asperitās","asperitāte"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{asperitās}} odium. saevāque","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aspernor","latin":"aspernor, aspernari, aspernatus sum","headword":"aspernor","letter":"a","pos":"verb","posGroup":"verb","english":"despise, scorn, disdain; spurn, push away, repel, reject; refuse, decline","forms":["aspernābātur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae tametsī animus {{aspernābātur}} īnsolēns malārum artium, tamen inter tanta vitia imbēcilla aetās ambitiōne corrupta tenēbātur; ac mē, cum ab reliquōrum malīs mōribus dissentīrem, nihilō minus honōris cupīdō eadem quā cēterōs fāma atque invidia vexābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"aspicio","latin":"aspicio, aspicere, aspexi, aspectus","headword":"aspicio","letter":"a","pos":"verb","posGroup":"verb","english":"look/gaze on/at, see, observe, behold, regard; face; consider, contemplate","forms":["aspexerit","aspexerō","aspexit","aspice","aspicere","aspicerent","aspiceret","aspiciam","aspiciēbant","aspiciēbat","aspicienda","aspiciendī","aspiciendus","aspiciēns","aspicimus","aspiciō","aspicis","aspicit","aspicite","aspicitur","aspiciunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aemilia: “{{Aspice}} rosās, Iūlī!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aspicit","latin":"aspicit, aspiciunt","headword":"aspicit","letter":"a","pos":"verb","posGroup":"verb","english":"look at, look; looks at, gazes at","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"assa","latin":"assa, assae","headword":"assa","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"dry-nurse, nurse, nanny","forms":["assā"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ūtāmur assā, et sīc dēscendāmus ad solium! [Dēscendit ipse.] Dēscende!” [Gāius, dēscendēns:] “Bene temperātum est solium.” [Iūlius:] “Exī iam!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"assensio","latin":"assensio, assensionis","headword":"assensio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"assent, agreement, belief; approval, approbation, applause","forms":["assēnsiō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed, nesciō quōmodo, dum legō, assentior — cum posuī librum et mēcum ipse dē immortālitāte animōrum coepī cōgitāre, assēnsiō illa omnis ēlābitur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"assensus","latin":"assēnsus, -ūs","headword":"assēnsus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"approval, assent","forms":["assēnsū"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum hōc Hasdrubale foedus renovāverat populus Rōmānus: 'ut fīnis utrīusque imperiī esset amnis Hibērus, Saguntīnīsque mediīs inter imperia duōrum populōrum lībertās servārētur.' In Hasdrubalis locum haud dubia rēs fuit quīnam successūrus esset, quia extemplō iuvenis Hannibal in praetōrium dēlātus imperātorque ingentī omnium clāmōre atque assēnsū appellātus erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assentio","latin":"assentio, assentire, assensi, assensus","headword":"assentio","letter":"a","pos":"verb","posGroup":"verb","english":"assent, approve, agree in opinion; admit the truth of (w/DAT), agree (with)","forms":["assenserint"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque nōn sum praedicātūrus quantās ille rēs domī mīlitiae, terrā marīque, quantāque fēlīcitāte gesserit, ut eius semper voluntātibus nōn modo cīvēs {{assenserint}}, sociī obtemperārint, hostēs oboedierint, sed etiam ventī tempestātēsque obsecundārint; hōc brevissimē dīcam: nēminem umquam tam impudentem fuisse quī ab dīs immortālibus tot et tantās rēs tacitē audēret optāre quot et quantās dī immortālēs ad Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assentior","latin":"assentior, assentiri, assensus sum","headword":"assentior","letter":"a","pos":"verb","posGroup":"verb","english":"assent to, agree, approve, comply with; admit the truth of (w/PREP)","forms":["assēnsa","assentior","assentīre","assentīrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iōsēphus autem nōlēbat assentīrī improbae mulierī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"assentire","latin":"(assentiō) assentīre (< sentīre)","headword":"assentīre","letter":"a","pos":"","posGroup":"other","english":"agree with, assent","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assentor","latin":"assentor, assentari, assentatus sum","headword":"assentor","letter":"a","pos":"verb","posGroup":"verb","english":"flatter, humor; agree, assent, confirm; agree to everything","forms":["Assentēmur"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego respiciēns ad Ascyltōn “Quid côgitäs?” inquam, “Ego enim, sî vîderô balneum, statim expîräbô!” “{{Assentēmur}}” ait ille, “et dum illî balneum petunt, nôs Cum haec placuissent, dücentē per porticum Gîtone ad excēpit ut Ascyltos etiam in piscînam cecīderit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"assequi","latin":"(assequor) assequī (< sequī)","headword":"assequī","letter":"a","pos":"","posGroup":"other","english":"attain to, achieve","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assequor","latin":"assequor, assequi, assecutus sum","headword":"assequor","letter":"a","pos":"verb","posGroup":"verb","english":"follow on, pursue, go after; overtake; gain, achieve; equal, rival; understand","forms":["assecūtus","assequeris","assequī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tunc Iōsēphus vocāvit dispēnsātōrem domūs suae, eīque dīxit: persequere virōs, et cum eōs {{assecūtus}} fuerīs, illīs dīcitō: quārē iniūriam prō beneficiō rependistis?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"asserere","latin":"(asserō) asserere, -uisse, -rtum","headword":"asserere","letter":"a","pos":"verb","posGroup":"verb","english":"claim; to claim, assert","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"assero","latin":"assero, asserere, asserui, assertus","headword":"assero","letter":"a","pos":"verb","posGroup":"verb","english":"lay hands on/grasp; assert/state/allege; free/release; claim; protect/preserve","forms":["asserere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iūliō Caesare et Marciō Philippō cōnsulibus sescentēsimō quīnquāgēsimō nōnō annō ab urbe conditā, cum prope alia omnia bella cessārent, in Ītaliā gravissimum bellum Picentēs, Marsī Paelīgnīque mōvērunt, quī, cum annīs numerōsīs iam populō Rōmānō oboedīrent, tum lībertātem sibi aequam {{asserere}} coepērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assideo","latin":"assideo, assidere, assedi, assessus","headword":"assideo","letter":"a","pos":"verb","posGroup":"verb","english":"sit by/in council/as assessor; watch over; camp near, besiege; resemble (w/DAT)","forms":["assēdistī","assēdit","assīdere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Rutilius vēnisset, eum quoque ut salūtāvit, propter Tubērōnem iussit {{assīdere}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assidere","latin":"(assīdō) assīdere (< sidere)","headword":"assīdere","letter":"a","pos":"","posGroup":"other","english":"sit down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assidue","latin":"assidue, assiduius, assiduissime","headword":"assidue","letter":"a","pos":"adverb","posGroup":"adverb","english":"continually, constantly, regularly","forms":["assiduē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Antōnium et Hortēnsium, quī tum arte ōrātōriā excellebant, assiduē audiēbat, ac simul apud doctōrēs Graecōs, Molōnem rhētorem et Diodōtum philosophum, discēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assiduitas","latin":"assiduitās, -ātis ( f.)","headword":"assiduitās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"perseverance","forms":["assiduitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam cum propter {{assiduitātem}} in causīs et industriam, tum propter exquīsītius et minimē vulgāre ōrātiōnis genus animōs hominum ad mē dīcendī novitāte converteram.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assiduo","latin":"assiduo","headword":"assiduo","letter":"a","pos":"adverb","posGroup":"adverb","english":"continually, constantly, regularly","forms":["assiduo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri defessis succederent nostrosque {{assiduo}} labore defatigarent, quibus propter magnitudinem castrorum perpetuo esset isdem in vallo permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"assiduus","latin":"assiduus, -a, -um","headword":"assiduus","letter":"a","pos":"adjective","posGroup":"adjective","english":"constantly present","forms":["assiduā","assiduae","assiduis","Assiduissimē","assiduum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et {{assiduis}} imbribus tardarentur, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"assignare","latin":"(assignō) assignāre","headword":"assignāre","letter":"a","pos":"","posGroup":"other","english":"assign, allocate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assigno","latin":"assigno, assignare, assignavi, assignatus","headword":"assigno","letter":"a","pos":"verb","posGroup":"verb","english":"assign, distribute, allot; award, bestow (rank/honors); impute; affix seal","forms":["assignātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē et tibi, Pūblī, et pīīs omnibus retinendus animus est in custōdiā corporis nec iniussū eius ā quō ille est vōbīs datus ex hominum vītā migrandum est, nē mūnus hūmānum {{assignātum}} ā deō dēfūgisse videāminī.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"assis","latin":"assis, assis","headword":"assis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"penny, copper coin; a pound; one, whole; circular flap/valve; round slice","forms":["assis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"omnes unius aestimemus {{assis}}!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"assuetus","latin":"assuetus, assueta -um, assuetior -or -us, assuetissimus -a -um","headword":"assuetus","letter":"a","pos":"adjective","posGroup":"adjective","english":"accustomed, customary, usual, to which one is accustomed/used","forms":["assuētus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dāvīd vērō iīs impedītus armīs, quibus nōn erat {{assuētus}}, vix poterat incēdere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"assum","latin":"assum, adesse, affui, affuturus","headword":"assum","letter":"a","pos":"verb","posGroup":"verb","english":"be near, be present, be in attendance, arrive, appear; aid (w/DAT)","forms":["affuerim","affuī","affuit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ipse enim saepe amīcīs meīs affuī, nēmō amīcus umquam frūstrā auxilium ā mē petīvit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"assumere","latin":"(assūmō) assūmere (< sumere)","headword":"assūmere","letter":"a","pos":"","posGroup":"other","english":"take, lay claim to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assuo","latin":"assuo, assuere, assui, assutus","headword":"assuo","letter":"a","pos":"verb","posGroup":"verb","english":"sew or patch on","forms":["Assuerō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Amān ulciscendī inimicī causā ūniversam IŪdaeōrum gentem perdere statuit, ēdictumque eā dē rē ab Assuerō impetrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"assurgere","latin":"(assurgō) assurgere (< surgere)","headword":"assurgere","letter":"a","pos":"","posGroup":"other","english":"rise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"assurgo","latin":"assurgo, assurgere, assurrexi, assurrectus","headword":"assurgo","letter":"a","pos":"verb","posGroup":"verb","english":"rise/stand up, rise to one's feet/from bed; climb, lift oneself; grow; soar","forms":["assurgere","assurgunt"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ego mäiestāte conterritus praetôrem putābam vēnisse; itaque temptävî {{assurgere}} et nüdôs pedēs in tcrram dēferre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"assus","latin":"assus, assa, assum","headword":"assus","letter":"a","pos":"adjective","posGroup":"adjective","english":"roasted, baked; dry (from sunbathing); w/unaccompanied voice","forms":["assam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dā carnem {{assam}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"assyrius","latin":"Assyrius, Assyrii","headword":"Assyrius","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Assyrian; inhabitant of Assur/Assyria","forms":["Assyriīs","Assyriōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē īrātus Deus illōs in potestātem hostium trādidit: dēvīctī sunt ā rēge {{Assyriōrum}}, quī decem tribūs captīvās fēcit, et in Assyriam dēportāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ast","latin":"ast","headword":"ast","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"but, on the other hand/contrary; but yet; at least; in that event; if further","forms":["ast"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Ast}} illī solvuntur frīgore membra,\nvītaque cum gemitū fūgit indignāta sub umbrās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"astrologus","latin":"astrologus, -ī","headword":"astrologus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"astronomer; astronomer, student of the stars","forms":["astrologus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iūlius Proculus auc- tiônemfaciet rêrum supervacuārum.” [T rimalchiô {{astrologus}} dē\" duodecim signīs] Interpellāvit tam dulcēs fābulās Trimalchiô; nam iam sublātum erat ferculum, hilarësque convîvae vînô ser- mônibusque püblicätîs operam coeperant dare.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"astrum","latin":"astrum, -ī","headword":"astrum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"star, constellation","forms":["astra","astrī","astrōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quotiēs nox terrās operit, quotiēs {{astra}} surgunt, imāgō patris Anchīsae in somnīs mē admonet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"astu","latin":"astu, undeclined","headword":"astu","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"city (esp. Athens), town (as opp. to rest of Attica/city-state)","forms":["astū"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hunc tamen ūtilitās populī frāterque datī summa movet sceptrī, laudem ut cum sanguine pēnset; mittor et ad mātrem, quae nōn hortanda, sed astū dēcipienda fuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"asturco","latin":"asturco, asturconis","headword":"asturco","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Nero's favorite horse; a horse from Asturia in Hispania Tarraconensis","forms":["asturcōnī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eī dīcit in aurem aut ‘ut domī lectulī sternantur’, aut ‘ab avunculō rogētur Aethiops, quī ad balneās veniat’, aut ‘asturcōnī locus ante ōstium suum dētur’, aut aliquod fragile falsae chorāgium glōriae comparetur!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"astus","latin":"astus, astus","headword":"astus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"craft, cunning, guile; cunning procedure/method, trick, stratagem","forms":["astus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fà{{astus}} -üs 7ī — superbia (fastūs : -um)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"astutia","latin":"astutia, astutiae","headword":"astutia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"cunning, cleverness, astuteness; cunning procedure/method, trick, stratagem","forms":["āstūtiae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Neque illī tamen ad cavendum dolus aut āstūtiae dēerant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"asylum","latin":"asȳlum, -ī","headword":"asȳlum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"refuge, asylum; place of refuge, sanctuary","forms":["asȳlum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde, nē vāna urbis magnitūdō esset, multitūdinem fīnitimōrum in urbem recēpit, cum sub monte Capitōlīnō inter duōs lūcōs {{asȳlum}} aperuisset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"at","latin":"at","headword":"at","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"but; but, yet, but meanwhile","forms":["at"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{At}} Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"atalanta","latin":"Atalanta, Atalantae","headword":"Atalanta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Atalanta; (huntress who raced her suitors; Calydonian boar huntress)","forms":["Atalanta","Atalantae","Atalantam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Fuit ōlim pulcherrima puella, nōmine {{Atalanta}}, cui plūrimī virī, quī eam ita amābant ut uxōrem dūcere vellent, multa et pretiōsissima dōna ex variīs orbīs terrārum partibus ferre solēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"atavus","latin":"ātavus, -ī","headword":"ātavus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"forefather, ancestor","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ater","latin":"āter, -tra, -trum","headword":"āter","letter":"a","pos":"adjective","posGroup":"adjective","english":"black, dark; dark, black","forms":["āter","ātra","ātrae","ātrās","atrī","ātrīs","ātrō","ātrōrum","ātrōs","ātrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam vērō caelum nūbibus ātrīs operītur, itaque obscūrum est ātrium.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"athenae","latin":"Athenae","headword":"Athenae","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Athens (pl.); inhabitants of Athens, Athenians","forms":["Athēnae","Athēnārum","Athēnās","Athēnīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī, iam antequam ex urbe {{Athēnīs}} in Crētam venit, complūrēs rēs mīrābilēs fēcerat.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"atheniensis","latin":"Atheniensis, Atheniensis","headword":"Atheniensis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Athenian, inhabitant of Athens","forms":["Athēniēnsēs","Athēniēnsī","Athēniēnsibus","Athēniēnsis","Athēniēnsium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Labyrinthus ille, in quō Mīnōtaurus inclūsus tenēbātur, ā Daedalō, virō Athēniēnsī, aedificātus erat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"athleta","latin":"āthlēta, -ae (m.)","headword":"āthlēta","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"athlete, prizefighter","forms":["athlētārum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam et artificum omnis generis quī lūdicram artem faciēbant ex tōtō orbe terrārum multitūdō et {{athlētārum}} et nōbilium equōrum convēnit et lēgātiōnēs cum victimīs, et quidquid aliud deōrum hominumque causā fierī magnīs lūdīs in Graeciā solet ita factum est ut nōn magnificentiam tantum sed prūdentiam in dandīs spectāculīs, ad quae rudēs tum Rōmānī erant, admīrārentur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"atlas","latin":"atlas, atlantis","headword":"atlas","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"atlas (of geography)","forms":["Atlantis","Atlās"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"personat aurātā, docuit quem maximus {{Atlās}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"atomus","latin":"atomus, atomi","headword":"atomus","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"atom, ultimate component of matter, particle incapable of being divided","forms":["atomī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Praetereā dīcit, ut ante eum Dēmocritus, ‘omnem rem, omnem māteriam efficī ex partibus minimīs, quae semper moventur.’ Eae particulae minimae, quae dīvidī nōn possunt, Graecē appellantur ‘atomī’.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"atque","latin":"atque","headword":"atque","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"and, and also","forms":["atque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius {{atque}} audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"atque/ac","latin":"atque/ac","headword":"atque/ac","letter":"a","pos":"","posGroup":"other","english":"and, as, than","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"atqui","latin":"atquī","headword":"atquī","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"but, and yet","forms":["Atquī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vīdit quīdam pendentem Absalōnem, nec ausus est illī manūs violentās īnferre, sed nūntiāvit Iōābō, quī eum increpāns: “Debuerās” inquit “iuvenem impium cōnfodere.” “Atquī” respondit ille “mē praesente, rēx praecēpit tibi, ut fīliō suō parcerēs.” “Ego vērō nōn parcam” ait Iōāb, et statim sūmpsit trēs lanceās, quās in pectus Absalōnis dēfīxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"atriensis","latin":"atriensis, atriensis","headword":"atriensis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"steward; servant in charge of household administration, major-domo; house-slave","forms":["ātriēnsem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Praeter- eä grande armārium in angulô vîdî, in cuius aediculā erant Larēs argenteî positī Venerisque signum marmoreum et pyxis aurea nôn pusilla, in quā barbam ipsîus Interrogāre ego ātriēnsem coepī ‘quās in mediô pictūrās habērent?’ “Îliada et Odys- sîan”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"atrium","latin":"ātrium, -ī","headword":"ātrium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"main room, hall; atrium, hall; atrium, entrance hall; atrium, entrance-hall; entrance hall, reception room","forms":["ātria","ātriīs","ātriō","ātrium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum Quīntus in lectō iacet in cubiculō suō, Medicus in ātriō Iūlium exspectat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"atrocitas","latin":"atrocitas, atrocitatis","headword":"atrocitas","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"fury; barbarity, cruelty; wickedness; severity, harshness; horror, dreadfulness","forms":["atrōcitāte"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nōnnūllī ficta et haec et multa praetereā existimābant ab eīs quī Cicerōnis invidiam, quae posteā orta est, lēnīrī crēdēbant {{atrōcitāte}} sceleris eōrum quī poenās dederant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"atrox","latin":"atrōx, -ōcis","headword":"atrōx","letter":"a","pos":"adjective","posGroup":"adjective","english":"dreadful, atrocious","forms":["ātrōcem","atrōcī","atrōcia","atrōcior","atrōcissima","atrōx"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Atrōx}} vīsum est id facinus patribus plēbīque.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"attamen","latin":"attamen","headword":"attamen","letter":"a","pos":"adverb","posGroup":"adverb","english":"but yet, but however, nevertheless","forms":["attamen"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Attamen}} pepercit Noēmō et līberīs eius, quī colēbant virtūtem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"attat","latin":"attat","headword":"attat","letter":"a","pos":"interjection","posGroup":"interjection","english":"exclamation of joy, pain, wonder, fright","forms":["attat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Interiectiō quid est?' Discipulus: 'Pars ōrātiōnis significāns mentīs affectum vōce inconditā.' Magister: 'Significātiō interiectiōnis in quō est?' Discipulus: 'Aut laetitiam significāmus, ut euax!; aut dolōrem, ut heu!; aut admīrātiōnem, ut pāpae!; aut metum, ut {{attat}}!; et sī quā sunt similia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"attendo","latin":"attendo, attendere, attendi, attentus","headword":"attendo","letter":"a","pos":"verb","posGroup":"verb","english":"turn/stretch towards; apply; attend/pay (close) attention to, listen carefully","forms":["attendere","attendis"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ecquid {{attendis}}, ecquid animadvertis hōrum silentium?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"attentus","latin":"attentus, -a, -um","headword":"attentus","letter":"a","pos":"adjective","posGroup":"adjective","english":"attentive","forms":["attentī","attentiōre","attentis","attentius","attentōs","attentum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cēterum in hāc rē is nōn peior fuerat cēterīs, nam omnēs puerī parum attentī fuerant.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"attenuare","latin":"(attenuō) attenuāre","headword":"attenuāre","letter":"a","pos":"","posGroup":"other","english":"make thin, reduce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"attenuo","latin":"attenuo, attenuare, attenuavi, attenuatus","headword":"attenuo","letter":"a","pos":"verb","posGroup":"verb","english":"thin (out); weaken, lessen, diminish, shrink, reduce in size; make plain","forms":["Attenuant"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"735 {{Attenuant}} iuvenum vigilātae corpora noctēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"atterere","latin":"(atterō) atterere (< terere)","headword":"atterere","letter":"a","pos":"","posGroup":"other","english":"wear (down), weaken","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"attero","latin":"attero, atterere, attrivi, attritus","headword":"attero","letter":"a","pos":"verb","posGroup":"verb","english":"rub, rub against; grind; chafe; wear out/down/away; diminish, impair; waste","forms":["attrīverat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Bellō Pūnicō secundō, quō dux Carthāginiēnsium Hannibal post magnitūdinem nōminis Rōmānī Ītaliae opēs maximē {{attrīverat}}, Masinissa, rēx Numidārum, in amīcitiam receptus ā P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"attestor","latin":"attestor, attestari, attestatus sum","headword":"attestor","letter":"a","pos":"verb","posGroup":"verb","english":"confirm, attest, bear witness to","forms":["attestātur"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hoc {{attestātur}} brevis Aesōpī fābula: Lupus arguēbat vulpem fūrtī crīmine.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"atticus","latin":"Atticus, Attica, Atticum","headword":"Atticus","letter":"a","pos":"adjective","posGroup":"adjective","english":"Attic, Athenian; classic, elegant","forms":["Attica","Atticus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Namque {{Atticus}} M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"attineo","latin":"attineo, attinere, attinui, attentus","headword":"attineo","letter":"a","pos":"verb","posGroup":"verb","english":"hold on/to/near/back/together/fast; restrain, keep (in custody), retain; delay","forms":["attinēre","attinet","attinuisset","attinuit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Quod ad mē {{attinet}}, iam paxmôs meôs comëdî, et sî persevērat haec armôna, casulâs meās vēndam.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"attinere","latin":"(attineō) attinēre (< tenēre)","headword":"attinēre","letter":"a","pos":"","posGroup":"other","english":"concern, relate to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"attingere","latin":"(attingō) attingere, -tigisse, -tactum","headword":"attingere","letter":"a","pos":"","posGroup":"other","english":"touch, reach, arrive at, adjoin","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"attingo","latin":"attingō, -ere, -tigī, -tāctum","headword":"attingō","letter":"a","pos":"verb","posGroup":"verb","english":"to touch, reach","forms":["attigerit","attigerunt","attigī","attigimus","attigissent","attigisset","attigit","attingat","attingere","attingerent","attingeret","attingimus","attingit","attingunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter sibi Senones, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui Oceanum {{attingunt}} adiungit; omnium consensu ad: eum defertur imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"attollo","latin":"attollo, attollere, -, -","headword":"attollo","letter":"a","pos":"verb","posGroup":"verb","english":"raise/lift up/towards/to a higher position; erect, build; exalt; extol, exalt","forms":["attollēns","attollet","attollit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"coniugis, ōra modīs {{attollēns}} pallida mīrīs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"attonitus","latin":"attonitus, -a, -um","headword":"attonitus","letter":"a","pos":"adjective","posGroup":"adjective","english":"stunned, stupefied; thunderstruck, astonished","forms":["attonitī","attonitum","attonitus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{attonitum}} fōrmā fac putet","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"attractus","latin":"attractus, attracta -um, attractior -or -us, attractissimus -a -um","headword":"attractus","letter":"a","pos":"adjective","posGroup":"adjective","english":"drawn together (brows), knit","forms":["attractus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ad cuius aspectum Tobiās perterritus exclāmāvit: “Domine, invādit mē.” Cui angelus: “Apprehende illum et trahe ad tē.” Piscis {{attractus}} in rīpam aliquamdiū palpitāvit et exspīrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"attrecto","latin":"attrecto, attrectare, attrectavi, attrectatus","headword":"attrecto","letter":"a","pos":"verb","posGroup":"verb","english":"touch; lay hands on; handle (roughly), assault (sexually), violate; deal with","forms":["attrectāverit","attrectem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Esāüs est pilōsus, ego sum lēnis; sī pater mē {{attrectāverit}}, succēnsēbit mihi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"attribuo","latin":"attribuo, attribuere, attribui, attributus","headword":"attribuo","letter":"a","pos":"verb","posGroup":"verb","english":"assign/allot/attribute/impute to; grant, pay; appoint, put under jurisdiction","forms":["attribuerat","attribuit","attribuuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque {{attribuerat}}, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"attributus","latin":"attributus, attributa, attributum","headword":"attributus","letter":"a","pos":"adjective","posGroup":"adjective","english":"ascribed, attributed; assigned, allotted","forms":["attribūtae","attribūtam","attributus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nostri, ut superioribus diebus, ut cuique erat locus {{attributus}}, ad munitiones accedunt; fun: dis librilibus sudibusque, quas in opere disposuerant, ac glandibus Gallos proterrent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"attritus","latin":"attritus, attrita -um, attritior -or -us, attritissimus -a -um","headword":"attritus","letter":"a","pos":"adjective","posGroup":"adjective","english":"worn, worn down by use; smoothed; hardened, brazen; thin (style), attenuated","forms":["attrīta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde exercitus ibi est locōrum sciēns, sed mēhercule magis strēnuus quam fēlīx; nam magna pars eius avāritiā aut temeritāte ducum {{attrīta}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"au","latin":"Au., abb.","headword":"Au","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aulus (Roman praenomen); (abb. A./Au.)","forms":["au"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"iūgīs aurēs timidàs memorī ōre {{au}}-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"auceps","latin":"auceps, aucupis","headword":"auceps","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"bird-catcher, fowler; bird seller, poulterer; spy, eavesdropper","forms":["aucupibus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{aucupibus}} nōtī fruticēs; quī sustinet hāmōs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"aucto","latin":"aucto, auctare, auctavi, auctatus","headword":"aucto","letter":"a","pos":"verb","posGroup":"verb","english":"increase/enlarge (much), grow; prosper/bless (with) (w/ABL)","forms":["auctō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prīncipēs Albānōrum in patrēs lēgit, ut ea quoque pars reī pūblicae crēsceret, et senātuī ita ab sē auctō cūriam aedificāvit, quae \"cūriā Hostīliā\" usque ad patrum nostrōrum aetātem appellāta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"auctor","latin":"auctor, -ōris (m.)","headword":"auctor","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"originator, founder, advocate, guarantor; author; founder, originator","forms":["auctor","auctōre","auctōrem","auctōrēs","auctōribus","auctōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tū dolor es facinusque meum.......ego sum tibi fūneris {{auctor}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"auctoritas","latin":"auctōritās, -ātis ( f.)","headword":"auctōritās","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"authorization, authority; authority, influence","forms":["auctōritās","auctoritate","auctoritatem","auctōritātī","auctoritatis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res adversae {{auctoritatem}} minuunt, sic huius ex contrario dignitas incommodo accepto in dies augebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"auctus","latin":"auctus, auctus","headword":"auctus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"growth, increase, enlargement, act of increasing; accession; prosperity; bulk","forms":["auctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In quattuor regiōnēs urbe dīvīsa, partēs eās \"tribūs\" appellāvit. (Posteā numerus tribuum {{auctus}} est ūnā et trīgintā tribubus rūsticīs additīs.)","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"aucupo","latin":"aucupo, aucupare, -, aucupatus","headword":"aucupo","letter":"a","pos":"verb","posGroup":"verb","english":"catch, take (swarm of bees); hunt after, seek, be on the lookout for","forms":["aucupēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Parätî {{aucupēs}} cum harun- dinibus fuērunt et eôs circâ trīclīnium volitantēs mômentô excëpënmt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"audacia","latin":"audācia, -ae","headword":"audācia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"boldness; boldness, daring","forms":["audācia","audaciae","audāciam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium Cadurcum, summae hominem {{audaciae}}, cum parte copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"audacter","latin":"audacter, audacius, audacissime","headword":"audacter","letter":"a","pos":"adverb","posGroup":"adverb","english":"boldly, audaciously, confidently, proudly, fearlessly; impudently, rashly","forms":["audācter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Sed rēctus, sed certus, amîcus amîcô, cum quô {{audācter}} singulôs tractābat!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"audax","latin":"audāx","headword":"audāx","letter":"a","pos":"adjective","posGroup":"adjective","english":"(gen.audācis) bold; bold, daring","forms":["audācem","audācēs","audācī","audācior","audācis","audācissimōs","audācissimum","audacius","audāx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque {{audacius}} de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"audens","latin":"audens, audentis (gen.), audentior -or -us, audentissimus -a -um","headword":"audens","letter":"a","pos":"adjective","posGroup":"adjective","english":"daring, bold, courageous; characterized by boldness/license of expression","forms":["audentem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"hinc pudor! {{audentem}} Forsque Venusque iuvat.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"audeo","latin":"audeo, audere, ausus sum","headword":"audeo","letter":"a","pos":"verb","posGroup":"verb","english":"intend, be prepared; dare/have courage (to go/do), act boldly, venture, risk","forms":["audeam","audeant","audeat","audēbant","audēbat","audēbunt","audēmus","audent","audeō","audēre","audēret","audēs","audet","audētis","ausae","ausōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id esse facile, quod neque legiones {{audeant}} absente imperatore ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"audet","latin":"audet, audēre","headword":"audet","letter":"a","pos":"","posGroup":"other","english":"dare, venture","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"audiens","latin":"audiens, audientis","headword":"audiens","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"auditor, one who hears; hearer of, obedient to (your command); public penitent","forms":["audiēns","audientem","audientēs","audientī","audientium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haec verba {{audiēns}} Iūlia plōrāre incipit atque mātrem vocat: “Uhuhū!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"audio","latin":"audio, audire, audivi, auditus","headword":"audio","letter":"a","pos":"verb","posGroup":"verb","english":"hear, listen, accept, agree with; obey; harken, pay attention; be able to hear","forms":["audi","audiam","audiāmus","audiant","audiās","audiat","audiātis","audiēbam","audiēbant","audiēbat","audiebatur","audienda","audiendī","audiendō","audiendum","audient","audiēs","audiet","audiētis","audīminī","audīmur","audīmus","audiō","audior","audīre","audīrent","audīret","audīrētur","audīrī","audīris","audis","audit","audīte","auditis","audītōs","audītū","audītum","audītur","audiunt","audiuntur","audīveram","audīverant","audīverat","audīvēre","audīverim","audīvērunt","audīvī","audivimus","audīvisse","audīvissem","audīvissēs","audīvisset","audīvistī","audīvistis","audīvit","AVDĪVIT"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iam Caesar a Gergovia discessisse {{audiebatur}}, iam de Aeduorum defectione et secundo Galliae motu rumores adferebantur, Gallique in colloquiis interclusum itinere et Ligere Caesarem inopia frumenti coactum in provinciam contendisse confirmabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"audire","latin":"audīre","headword":"audīre","letter":"a","pos":"verb","posGroup":"verb","english":"to hear","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"audit","latin":"audit","headword":"audit","letter":"a","pos":"verb","posGroup":"verb","english":"hear, listen; hears, listens to; hears","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"auditio","latin":"auditio, auditionis","headword":"auditio","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"hearing, act/sense of hearing; report, hearsay, rumor; lecture, recital","forms":["auditionem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Impellit alios avaritia, alios iracundia et temeritas quae maxime illi hominum generi est innata, ut levem {{auditionem}} habeant pro re comperta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"audito","latin":"audito, auditare, auditavi, auditatus","headword":"audito","letter":"a","pos":"verb","posGroup":"verb","english":"hear frequently","forms":["audita","audītās","audito"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum {{audita}} sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"auditus","latin":"auditus, auditus","headword":"auditus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"hearing; listening; act/sense of hearing; hearsay","forms":["audītus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"At, nōndum memorātis omnibus rēbus, horrendus sonus ē maris flūctibus {{audītus}} est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aufero","latin":"auferō, auferre, abstulī, ablatum","headword":"auferō","letter":"a","pos":"verb","posGroup":"verb","english":"carry away, carry off","forms":["ablātā","ablātōs","ablātum","ablātus","abstulerant","abstulerat","abstulerit","abstulimus","abstulisse","abstulistis","abstulit","aufer","auferēns","auferentem","Auferēre","auferet","auferor","auferre","auferrent","auferret","auferrētur","auferrī","aufert","Auferte","auferunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rēx indignāns respondit: “Inīquē fēcit quisquis ille est: prō ove ablātā quattuor ovēs reddet.” Tum prophēta apertē: “Tū” ait “tū es iste vir: tē Deus bonīs omnibus cumulāvit, tē rēgem fēcit, tē ab īrā Saūlis līberāvit, tibi rēgiam domum, rēgiās opēs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"auferre","latin":"(auferō) auferre, abstulisse, ablātum","headword":"auferre","letter":"a","pos":"verb","posGroup":"verb","english":"carry off; to carry off, steal","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aufugere","latin":"(aufugiō) aufugere, aufūgisse","headword":"aufugere","letter":"a","pos":"verb","posGroup":"verb","english":"run away, escape; to run away, escape","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"aufugio","latin":"aufugio, aufugere, aufugi, -","headword":"aufugio","letter":"a","pos":"verb","posGroup":"verb","english":"flee, flee from, shun; run/fly away, escape; disappear (things), vanish","forms":["aufūgerat","aufugere","aufūgisse","aufūgit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum cōram eō esset, Promēthēum ex Olympō {{aufūgisse}} sēcum aliquantum ignis auferentem nūntiāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"augeo","latin":"augeō, augēre","headword":"augeō","letter":"a","pos":"verb","posGroup":"verb","english":"increase; to increase, enlarge","forms":["auctā","auctī","auctīs","auctum","augeat","augebat","augebatur","augēbō","augendae","augēre","augeri","auget","augetur","auxerant","auxerat","auxerint","auxērunt","auxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res adversae auctoritatem minuunt, sic huius ex contrario dignitas incommodo accepto in dies {{augebatur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"augescere","latin":"(augēscō) augēscere","headword":"augēscere","letter":"a","pos":"","posGroup":"other","english":"begin to grow, increase","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"augesco","latin":"augesco, augescere, -, -","headword":"augesco","letter":"a","pos":"verb","posGroup":"verb","english":"grow, increase in size/amount/number; develop; prosper; rise/be swollen (river)","forms":["augēscunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita populus lūdibriō habitus ex contiōne discēdit, Iugurthae Bestiaeque et cēterīs quōs illa quaestiō exagitābat animī {{augēscunt}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"augur","latin":"augur, -is (m.)","headword":"augur","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"augur; augur, prophet; augur, reader of bird-signs","forms":["augur","augure","augurēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Augur}} “Vincēmus” ait “Pelasgī; gaudēte!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"augurium","latin":"augurium, -ī","headword":"augurium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"augury, omen; omen, augury","forms":["auguriō","augurium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accēpisse id {{augurium}} laeta dīcitur Tanaquil, mulier perīta caelestium prōdigiōrum, ut plērīque Etrūscī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"augus","latin":"Augus, Auga, Augum","headword":"Augus","letter":"a","pos":"adjective","posGroup":"adjective","english":"August (month/mensis understood); abb. Aug.; renamed from Sextilis in 8 BC","forms":["Aūg"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Aūg}}. annō 390 ā.C.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"augusta","latin":"Augusta, Augustae","headword":"Augusta","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Augusta; (title of Emperor's wife/occasionally other close female relatives)","forms":["augusta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iam continēns agmen migrantium implēverat viās, et cōnspectus aliōrum renovābat lacrimās, vōcēsque etiam miserābilēs exaudiēbantur, mulierum praecipuē, cum templa {{augusta}} ab armātīs occupāta praeterīrent ac velut captōs relinquerent deōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"augusto","latin":"augusto, augustare, augustavi, augustatus","headword":"augusto","letter":"a","pos":"verb","posGroup":"verb","english":"glorify; render venerable","forms":["Augustō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Exiit ēdictum ā Caesare Augustō ut dēscrīberētur ūniversus orbis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"augustus","latin":"augustus, -a, -um","headword":"augustus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"venerable, majestic","forms":["Augustās","Augustī","augustiōrem","augustum","augustus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; {{Augustus}}, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aula","latin":"aula, -ae","headword":"aula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"palace; palace, court","forms":["āulā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dāvīd, ut vīdit implācābilem esse Saūlis in sē animum, excessit āulā, et sōlitūdinem petīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aulaeum","latin":"aulaeum, aulaei","headword":"aulaeum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"canopy/covering; theater curtain; hangings/folds (pl.), tapestries/drapery","forms":["aulaeīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum venit, {{aulaeīs}} iam sē rēgīna superbīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"aulicus","latin":"aulicus, aulici","headword":"aulicus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"courtier (of the imperial/a prince's household)","forms":["aulicī","aulicīs","aulicōrum","aulicus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc aulicī eī suāsērunt ut aliquem arcesseret, quī citharam scīret pulsāre, ad dēlīniendum aegrum eius animum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aulid","latin":"Aulid, Aulidis","headword":"Aulid","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Aulis; (port in Boeotia where Greek fleet assembled for Troy)","forms":["Aulide","Aulidem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nec poena dīlāta foret, nisi saevī ventī fēcissent aequora invia et tellūs {{Aulide}} puppēs tenuisset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aulus","latin":"Aulus, Auli","headword":"Aulus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Aulus (Roman praenomen); (abb. A.)","forms":["Aulus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Alia praenōmina Latīna sunt '{{Aulus}}', 'Decimus', 'Gāius', 'Pūblius', 'Sextus', 'Titus'.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"aura","latin":"aura, -ae","headword":"aura","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"breeze, wind; breeze, air","forms":["aura","aurae","auram","aurās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōmen dulce sonāns Phoebō levis {{aura}} ferēbat:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aurata","latin":"aurata, auratae","headword":"aurata","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"kind of fish, gilthead, dorado","forms":["aurāta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{aurāta}} : veste aurāta vestīta","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"auratus","latin":"aurātus, -a, -um","headword":"aurātus","letter":"a","pos":"adjective","posGroup":"adjective","english":"gilded","forms":["aurātō","aurātum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Intereā dī domum eōrum in templum mūtāvērunt cuius tēctum {{aurātum}}, iānua gemmīs ōrnāta, columnae candidae erant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aurea","latin":"aurea, aureae","headword":"aurea","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"bridle of a horse","forms":["aurea"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Eliezer dēprōmpsit vās {{aurea}} et argentea, vestēsque pretiōsās, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aureolus","latin":"aureolus, aureola, aureolum","headword":"aureolus","letter":"a","pos":"adjective","posGroup":"adjective","english":"golden, made of gold, gold colored; beautiful, brilliant, excellent, splendid","forms":["aureolam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec melior Scintilla, quae dē cervîce suā capsellam dē- trāxit {{aureolam}}, quam ‘Fëlîciônem’ ap- pellābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"aureus","latin":"aureus, -a , -um","headword":"aureus","letter":"a","pos":"adjective","posGroup":"adjective","english":"golden","forms":["aureae","auream","aureās","aureī","aureīs","aureō","aureōs","aureum","aureus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nōlō flōrēs accipere ab illō virō volō.” Dōrippa Sanniōnī magnum ānulum {{aureum}} ostendit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"auricomus","latin":"auricomus, auricoma, auricomum","headword":"auricomus","letter":"a","pos":"adjective","posGroup":"adjective","english":"golden-haired, with golden hair; flaxen-haired; with golden foliage/leaves","forms":["auricomum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{auricomum}} sibi quī dīvum praepōnit amantī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"auricula","latin":"auricula, auriculae","headword":"auricula","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"ear (part of body/organ of hearing); sense of hearing","forms":["auriculam","auriculās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēmittō {{auriculās}}, ut inīquae mentis asellus, cum gravius dorsō subiit onus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"auriga","latin":"aurīga, -ae","headword":"aurīga","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(m.) charioteer, driver; charioteer","forms":["aurīgā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"ultima tandem viae pars, cum deorsum versa sit, perīculōsissima est atque ad eam tūtō percurrendam aurīgā opus est, quī bene equōs regere sciat!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"auris","latin":"auris, auris","headword":"auris","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) ear","forms":["aure","aurem","aurēs","auribus","aurīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa {{auribus}} desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"auro","latin":"auro, aurare, auravi, auratus","headword":"auro","letter":"a","pos":"verb","posGroup":"verb","english":"gild, overlay with gold","forms":["aurō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Albīnus: “Nōn ut aurum, sed ut ferrum tinnit iste ānulus: est ānulus ferreus aurō opertus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"aurora","latin":"aurōra, -ae","headword":"aurōra","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"dawn","forms":["aurōra","Aurōrae","aurōram"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"purpureās {{Aurōra}} forēs et plēna rosārum ātria: diffugiunt stēllae;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"aurum","latin":"aurum, -ī","headword":"aurum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"gold","forms":["aurī","aurum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Albīnus: “Nōn ut {{aurum}}, sed ut ferrum tinnit iste ānulus: est ānulus ferreus aurō opertus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ausonia","latin":"Ausonia, Ausoniae","headword":"Ausonia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"Ausonia; (ancient/poetic name for Italy)","forms":["Ausoniā","Ausoniam","Ausonium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ubi Trōiānae rēmīs avidamque Charybdin\nēvicēre ratēs, cum iam prope lītus adessent\n{{Ausonium}}, Libycās ventō referuntur ad ōrās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"auspex","latin":"auspex, auspicis","headword":"auspex","letter":"a","pos":"noun","posGroup":"noun","english":"diviner by birds, augur; soothsayer; patron, supporter; wedding functionary","forms":["auspicibus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dīs equidem {{auspicibus}} reor et Iūnōne secundā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"auspicari","latin":"(auspicor) auspicārī","headword":"auspicārī","letter":"a","pos":"","posGroup":"other","english":"take the auspices","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"auspicato","latin":"auspicātō","headword":"auspicātō","letter":"a","pos":"adverb","posGroup":"adverb","english":"after taking the auspices; with good omens dē integrō anew","forms":["auspicātō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rōmam arcessītus Numa, sīcut Rōmulus auspicātō post rēgnum adeptus est, dē sē quoque deōs cōnsulī iussit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"auspicium","latin":"auspicium, -ī","headword":"auspicium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"omen taken from birds; guidance, divination; auspices; bird-omen, auspices; omen (from birds), auspices","forms":["auspicia","auspiciīs","auspiciō","auspicium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita Thēseus factus est rēx, Aegeō mortuō, et sapiēns dux per multōs annōs populō Athēniēnsī {{auspicium}} fēlīx et iūra iūsta dedit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"auspicor","latin":"auspicor, auspicari, auspicatus sum","headword":"auspicor","letter":"a","pos":"verb","posGroup":"verb","english":"take auspices; seek omens; begin with auspices, make ceremonial start; portend","forms":["auspicārētur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ergō inter frātrēs convēnit ut Rōmulus in Palātiō, Remus in Aventīnō {{auspicārētur}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"auster","latin":"Auster, -trī","headword":"Auster","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"south wind","forms":["Auster","austrīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Trōiā profugī Hesperiam sīve Italiam, terram antīquam, petēbāmus, cum turbidus {{Auster}} nōs disiēcit atque paucōs nostrum hīc ad vestrās ōrās compulit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"australis","latin":"austrālis, -e","headword":"austrālis","letter":"a","pos":"adjective","posGroup":"adjective","english":"southern","forms":["austrālis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Duō sunt habitābilēs, quōrum {{austrālis}} ille, in quō quī īnsistunt adversa vōbīs urgent vestīgia, nihil ad vestrum genus; hic autem alter subiectus aquilōnī quem incolitis, cerne quam tenuī vōs parte contingat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ausum","latin":"ausum, ausi","headword":"ausum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"daring/bold deed, exploit, venture; attempt; presumptuous act, outrage; crime","forms":["ausa","ausi","ausim","ausit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire {{ausi}} domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ausus","latin":"ausus, ausus","headword":"ausus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"daring, initiative; ventures (pl.)","forms":["ausus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs {{ausus}} es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aut","latin":"aut","headword":"aut","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"or","forms":["aut"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis {{aut}} singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"autem","latin":"autem","headword":"autem","letter":"a","pos":"conjunction","posGroup":"conjunction","english":"but, however; however, but","forms":["autem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Totum {{autem}} murum ex omni parte turribus contabulaverant atque has coriis intexerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"automatum","latin":"automatum, automati","headword":"automatum","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"automaton, automatic/self-moving mechanism; automatic/puppet-like movements","forms":["automātum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec mora: ex plägîs ponderis inclînätiône crēscentibus tomācula cum rogāmus ut eum mittās (z im- sî piscem exinterāre praeter- ponderis ī.ē : quia pondus fēcit rē-porrigere : rogāvit ut [T rimalchiô dē\" āere Corinthiā‘, dē‘ vitrô, dê argentô] Plausum post hōc {{automātum}} familia dedit et “Gäiô féliciter!” conclāmāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"autumno","latin":"autumno, autumnare, autumnavi, autumnatus","headword":"autumno","letter":"a","pos":"verb","posGroup":"verb","english":"bring autumnal conditions","forms":["Autumnō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Autumnō folia dē arboribus cadunt et terram operiunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"autumnus","latin":"autumnus, -ī","headword":"autumnus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"autumn","forms":["autumnī","autumnum","autumnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat in magnis Caesari difficultatibus res, ne maiorem aestatis partem flumine impediretur, quod non fere ante {{autumnum}} Elaver vado transiri solet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"autumo","latin":"autumo, autumare, autumavi, autumatus","headword":"autumo","letter":"a","pos":"verb","posGroup":"verb","english":"say, assert; say yes; affirm; mention, speak of; name, call; reckon, judge","forms":["autumāre","autumat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"'Nescioquem loquī {{autumat}}—mihi certō nōmen Sōsia est!'","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"autus","latin":"autus, auti","headword":"autus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"increase, enlargement; growth","forms":["aūtō"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque tôtum circumspicere triclînium coepî, nē per parietem aūtō- matum aliquod exîret, utique postquam servus verberärî coepit quî bracchium dominî contūsum albā potius quam conchÿliātä involverat lānä.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"auxilia","latin":"auxilia","headword":"auxilia","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"auxiliary troops","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"auxilio","latin":"auxilio, auxiliare, auxiliavi, auxiliatus","headword":"auxilio","letter":"a","pos":"verb","posGroup":"verb","english":"help (w/DAT); give help/aid; assist; be helpful, be of use/avail; remedy, heal","forms":["auxilio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nolite hos vestro {{auxilio}} exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi imbecillitate omnem Galliam prosternere et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"auxilior","latin":"auxilior, auxiliari, auxiliatus sum","headword":"auxilior","letter":"a","pos":"verb","posGroup":"verb","english":"help (w/DAT); give help/aid; assist; be helpful, be of use/avail; remedy, heal","forms":["auxiliari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Conantibus {{auxiliari}} suis, 'Frustra', inquit, 'meae vitae subvenire conamini, quem iam sanguis viresque deficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"auxilium","latin":"auxilium, -ī","headword":"auxilium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"help, aid; help; (pl.) auxiliary troops; aid, help","forms":["auxili","auxilia","auxiliī","auxiliis","auxilium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quem simul atque oppidani conspexerunt atque in spem {{auxili}} venerunt, clamore sublato arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"avaritia","latin":"avāritia, -ae","headword":"avāritia","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"greed, avarice","forms":["avaritia","avāritiae","avāritiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Impellit alios {{avaritia}}, alios iracundia et temeritas quae maxime illi hominum generi est innata, ut levem auditionem habeant pro re comperta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"avarus","latin":"avārus, -a, -um","headword":"avārus","letter":"a","pos":"adjective","posGroup":"adjective","english":"greedy; greedy, miserly","forms":["avārī","avārior","avārum","avārus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Orontēs: 'Midās est nōmen rēgis, dē quō haec tabulā nārrat: in quādam urbe Asiae ōlim vīvēbat rēx quīdam {{avārus}}, nōmine Midās, quī nihil magis optābat dīvitiās...' Iūlius, quī tabulam audīre nōn vult, Orontem interpellat: 'Nōn Midās,' inquit, 'sed Mēdus est nōmen servī meī, quī heri...' Orontēs vērō, minimē turbātus, nārrāre pergit:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ave","latin":"ave","headword":"ave","letter":"a","pos":"interjection","posGroup":"interjection","english":"hail!, formal expression of greetings","forms":["avē"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Subiit igitur alia classis, et illî quidem exclânnävëre: “Valē, Gäî!” hî autem: “Avē, Gäî!” arbor eiusque lignum dūrum tîbiîs canendô et saltandô pō- pulum dēlectat; ambübäimn mâchina : mēnsā in vënäliciô dē quā vêneunt servī et an- cüräbô ut domita sit (domētur) gerit (ut mīles), audâx [?] interîre : exstinguî (quia For- [T rimalchiô uxôrî convīcium facit] Hinc prîmum hilaritās nostra turbāta est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"avehere","latin":"(āvehō) āvehere (< vehere)","headword":"āvehere","letter":"a","pos":"","posGroup":"other","english":"carry off, pass, go away","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"aveho","latin":"aveho, avehere, avexi, avectus","headword":"aveho","letter":"a","pos":"verb","posGroup":"verb","english":"carry away, carry; (passive) ride away/off, sail away, go away, depart","forms":["āvectōs","āvehī","avehuntur","āvexerat","avexerunt","āvēxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque interfectis Novioduni custodibus quique eo negotiandi causa convenerant, pecuniam atque equos inter se partiti sunt; obsides civitatum Bibracte ad magistratum deducendos curaverunt; oppidum, quod a se teneri non posse iudicabant, ne cui esset usui Romanis, incenderunt; frumenti quod subito potuerunt navibus {{avexerunt}}, reliquum flumine atque incendio corruperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"avellere","latin":"(āvellō) āvellere, āvelisse","headword":"āvellere","letter":"a","pos":"","posGroup":"other","english":"tear away","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"avello","latin":"avello, avellere, avulsi, avulsus","headword":"avello","letter":"a","pos":"verb","posGroup":"verb","english":"tear/pluck/wrench away/out/off; separate by force, part; take away, wrest","forms":["āvellī","āvulsum","āvulsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nīcānor ipse inter hostium cadāvera repertus est, cuius caput āvulsum Iildās Hierosolymam ferrī iussit, manumque nefāriam templō affīxam suspendī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"aveo","latin":"aveo, avere, -, -","headword":"aveo","letter":"a","pos":"verb","posGroup":"verb","english":"hail; fare/be well; (IMP/INF; greeting/leaving); [ ~ jubeo => I send greetings]","forms":["aveō","averet","Avēte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Revocātus praecō, cum ūnusquisque nōn audīre modo, sed vidēre lībertātis suae nūntium {{averet}}, iterum prōnūntiāvit eadem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"avere","latin":"(aveō) avēre","headword":"avēre","letter":"a","pos":"","posGroup":"other","english":"be eager, desire, long","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"averna","latin":"Averna, -ōrum","headword":"Averna","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"the region of Avernus, entrance to the underworld","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"avernus","latin":"Avernus, Averni","headword":"Avernus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"Avernus; (lake near Cumae, entrance to underworld); the underworld","forms":["Avernum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Orpheus gaudēns eam accipit sed cum hāc lēge Plūtōnis: nōn debet respicere Eurydicēn dōnec ingentem spēluncam {{Avernum}} exierit; aut dōnum erit vānum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"aversus","latin":"aversus, aversa -um, aversior -or -us, aversissimus -a -um","headword":"aversus","letter":"a","pos":"adjective","posGroup":"adjective","english":"turned/facing away, w/back turned; behind, in rear; distant; averse; hostile","forms":["āversa","Āversī","āversōs","āversus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"... pavor occupat illum, ante oculōsque natant tenebrae retrōque ferentī āversōs passūs mediō lapis obstitit arvō; quem super impulsum resupīnō corpore Cygnum vī multā vertit terraeque affīxit Achillēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"avertere","latin":"(āvertō) āvertere","headword":"āvertere","letter":"a","pos":"","posGroup":"other","english":"turn aside or away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"averto","latin":"averto, avertere, averti, aversus","headword":"averto","letter":"a","pos":"verb","posGroup":"verb","english":"turn away from/aside, divert, rout; disturb; withdraw; steal, misappropriate","forms":["āverte","avertebant","āvertendō","āvertēns","āvertere","āverterent","āverteret","āverteris","āvertī","āvertistī","āvertit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam et laqueis falces {{avertebant}}, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"avide","latin":"avide, avidius, avidissime","headword":"avide","letter":"a","pos":"adverb","posGroup":"adverb","english":"greedily, hungrily, avariciously; eagerly, impatiently","forms":["avidē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prānsus nōn avidē (quantum interpellet inānī ventre diem dūrāre), domesticus ōtior.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"aviditas","latin":"aviditas, aviditatis","headword":"aviditas","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"greed, covetousness; keen desire, lust/passion; appetite (food/drink), gluttony","forms":["aviditās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vērum dēcepta {{aviditās}} et quem tenēbat ōre dīmīsit cibum nec quem petēbat adeō potuit tangere!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"avidus","latin":"avidus, -a, -um","headword":"avidus","letter":"a","pos":"adjective","posGroup":"adjective","english":"greedy, eager (+ gen.); eager","forms":["avida","Avidae","avidī","avidīs","avidissimē","avidissimus","avidō","avidōs","avidus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mīdās cibum dente avidō tangere temptāvit, sed dentēs dūrum aurum tetigērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"avis","latin":"avis, avis","headword":"avis","letter":"a","pos":"noun (f.)","posGroup":"noun","english":"(f.) bird","forms":["avem","avēs","avibus","avis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce {{avis}} ante canem volat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"avitus","latin":"avītus, -a, -um","headword":"avītus","letter":"a","pos":"adjective","posGroup":"adjective","english":"of a grandfather","forms":["avītā","avītae","avītam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec deinceps ab avītā religiōne umquam dēscīvērunt, quamvīs ea dē causā ā plūribus rēgibus vexatī sint, ac praesertim ab Antiochō rēge Syriae; quae pars historiae Iūdaicae nunc nārranda venit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"avium","latin":"avium, avii","headword":"avium","letter":"a","pos":"noun (n.)","posGroup":"noun","english":"pathless region (pl.), wild waste, wilderness, desert; lonely/solitary places","forms":["avium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iūlius: “Pullī {{avium}} sunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"avolare","latin":"(āvolō) āvolāre","headword":"āvolāre","letter":"a","pos":"","posGroup":"other","english":"fly off, rush off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"avolo","latin":"avolo, avolare, avolavi, avolatus","headword":"avolo","letter":"a","pos":"verb","posGroup":"verb","english":"fly/rush away/off; hasten away, flee, vanish; fly away (missile)","forms":["āvolant","Āvolat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"7210 Āvolat, ut thyrsó concitā Bacchā, vīs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"avos","latin":"avos, avi","headword":"avos","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"grandfather; forefather, ancestor","forms":["avōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut medium campī passīs tetigēre capillīs, in terram positō prōcubuēre genū, et quasi sentīrent, blandō clāmōre nepōtēs tendēbant ad {{avōs}} bracchia parva suōs; quī poterat clāmābat \"avum\", tunc dēnique vīsum, et quī vix poterat posse coāctus erat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"avunculus","latin":"avunculus, -ī","headword":"avunculus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"(maternal) uncle","forms":["avunculō","avunculum","avunculus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quārē Rebecca māter, timēns dīlēctō fīliō suō: fuge, inquit, fīlī mī; abī ad Labānum {{avunculum}} tuum, et commorāre apud eum dōnec īra frātris tuī dēfervēscat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"avus","latin":"avus, -ī","headword":"avus","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"grandfather","forms":["āvī","avō","avōrum","avum","avus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cui Rebecca respondit: ego sum fīlia Bathuēlis: {{avus}} meus est frāter Abrahamī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"axis","latin":"axis, axis","headword":"axis","letter":"a","pos":"noun (m.)","posGroup":"noun","english":"axle, axis, pole; chariot; the sky, heaven; north pole; region, clime","forms":["axe","axem","Axis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Axis}} erat aureus, aureus erat tēmō, aureae rotae, at argenteī radiī: quae metalla ūna cum gemmīs, quibus tōtus currus ōrnābātur, Sōlis lūmen repercussum in omnēs caelī partēs spargēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"baca","latin":"baca, bacae","headword":"baca","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"berry, fruit of tree/shrub; olive; pearl; piece/bead of coral","forms":["bācās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"caerula quot {{bācās}} Palladis arbor habet,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"bacatus","latin":"bacatus, bacata, bacatum","headword":"bacatus","letter":"b","pos":"adjective","posGroup":"adjective","english":"set with pearls","forms":["bācātum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{bācātum}}, et duplicem gemmīs aurōque corōnam.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"baccha","latin":"Baccha, -ae","headword":"Baccha","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"a Bacchante (female worshipper of Bacchus)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"bacchans","latin":"bacchans, bacchantis","headword":"bacchans","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"votaries (pl.) of Bacchus, Bacchantes","forms":["Bacchantes","bacchantum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Miserrimus Orpheus tendēns manūs et ōrāns {{Bacchantes}} vōce movēre frūstrā temptāvit; īnsānissimae eum lacerāvērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"bacchor","latin":"bacchor, bacchari, bacchatus sum","headword":"bacchor","letter":"b","pos":"verb","posGroup":"verb","english":"celebrate rites of Bacchus; revel/rave/riot; run wild; be frenzied/raving mad","forms":["bacchābere","bacchātur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīc tū quā laetitiā perfruere, quibus gaudiīs exsultābis, quanta in voluptāte {{bacchābere}}, cum in tantō numerō tuōrum neque audiēs virum bonum quemquam neque vidēbis!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"bacchus","latin":"Bacchus, -ī","headword":"Bacchus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"Bacchus (god of wine)","forms":["Bacche","Bacchī","Bacchō","Bacchum","Bacchus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde multās aliās fābulās pīnxit; tum Phoebum, et {{Bacchum}}; dēnique extrēmam vestis partem pulcherrimīs flōribus ōrnāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"bacciballum","latin":"bacciballum, bacciballi","headword":"bacciballum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"piece; woman (slang), bit of stuff/fluff","forms":["bacciballum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ibi, quômodo diî volunt, amāre rentînarn, pulcherrimum {{bacciballum}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"baculum","latin":"baculum, -ī","headword":"baculum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"stick; stick, staff","forms":["bāculīs","baculō","baculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra dominum īrātum — et {{baculum}} eius — videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"baia","latin":"baia, baiae","headword":"baia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"palm branch; Baiae (pl.) posh Bay of Naples resort w/hot springs, the Palms","forms":["Bāiae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"CROLAN [{{Bāiae}}, locus celeberrimus]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"balans","latin":"balans, balantis","headword":"balans","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"bleater; sheep (pl.)","forms":["bālantem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Haedum {{bālantem}} audīvit Tobiās, et, veritus nē fūrtō ablātus esset, dīxit uxōrī: “Vidē nē iste clam alicui ēreptus sit: redde illum dominō suō; nefās enim est nōbīs ex raptō vīvere.” Adeō vir iūstus ab omnī improbitāte abhorrēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"balat","latin":"bālat, -ant","headword":"bālat","letter":"b","pos":"verb","posGroup":"verb","english":"bleat; bleats","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"balatus","latin":"balatus, balatus","headword":"balatus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"bleating (of sheep/goats)","forms":["balātus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Subitō in mediō aēnō {{balātus}} audītur et sine morā ēvenit agnus quī mātrem quaerit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"balbus","latin":"balbus, balba, balbum","headword":"balbus","letter":"b","pos":"adjective","posGroup":"adjective","english":"stammering, stuttering, lisping, suffering from a speech defect; fumbling","forms":["Balbum","Balbus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister epistulam prōmit atque “Hanc epistulam” inquit “volō tē ad Lūcium Iūlium {{Balbum}} ferre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"balnea","latin":"balnea, balneae","headword":"balnea","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"baths (pl.)","forms":["balnea","balneae","balneās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"cēlent fūrtīvōs {{balnea}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"balneae","latin":"balneae, -ārum (pl.)","headword":"balneae","letter":"b","pos":"","posGroup":"other","english":"public baths","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"balneator","latin":"balneator, balneatoris","headword":"balneator","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"bath-attendant; keeper of a bathhouse","forms":["balneātōrī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tamen temptō — sī possum.” [Iūlius cum Gāiō luctātur in cērōmate.] [Gāius:] “Leviter fatīgātus sum.” [Iūlius:] “Introcāmus in cellam prīmam tepidāriam.” [Iūlius introiēns, ad servum:] “Dā balneātōrī nummōs!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"balneum","latin":"balneum, -ī","headword":"balneum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"bath","forms":["balneīs","balneō","balneum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ex agrīs reversus Iūlius continuō {{balneum}} petit, atque aqua calida, tum frīgida lavātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"balo","latin":"balo, balare, balavi, balatus","headword":"balo","letter":"b","pos":"verb","posGroup":"verb","english":"bleat, baa (like a sheep); talk foolishly","forms":["bālant","bālat"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Ovis {{bālat}}: “Bābā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"balteus","latin":"balteus, -ī","headword":"balteus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"sword-belt, baldric","forms":["balteō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Longē alia fuit mēns fīliī eius Iōnāthae: virtūtem Davidis admīrāns, illum singulārī amōre complexus est, suōque balteō, arcū et gladiō dōnāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"barba","latin":"barba, -ae","headword":"barba","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"beard","forms":["barbā","barbam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At ego sciō quā dē causā mē fugiās: tibi neque capillī neque barbā meā placent, etsī capillī et barba virum decent: num tū pulchram sine frondibus arborem, pulchram sine pennīs avem, pulchram sine lānā ovem umquam vīdistī?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"barbara","latin":"barbara, barbarae","headword":"barbara","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"foreign/barbarian woman; kind of plaster; plaster applied to raw wounds (L+S)","forms":["barbara"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pater certē saevus, certē est mea terra {{barbara}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"barbaria","latin":"barbaria, barbariae","headword":"barbaria","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"strange/foreign land; uncivilized races, barbarity; brutality; barbarism","forms":["barbaria"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{barbaria}} -āe f — mōs barbarus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"barbarum","latin":"barbarum, barbari","headword":"barbarum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"barbarism; impropriety of speech; kind of plaster (applied to raw wounds L+S)","forms":["barbarum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Prīmum dīxit ‘mātrem meam turpem esse’, deinde mē ‘puerum {{barbarum}}’ appellāvit!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"barbarus","latin":"barbarus, -a, -um","headword":"barbarus","letter":"b","pos":"adjective","posGroup":"adjective","english":"foreign, barbarian; barbarian, foreign; rough, rude, foreign","forms":["barbarārum","barbarī","barbarīs","barbarō","barbarōrum","barbarōs","barbarus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dēfende mē ab hōc puerō barbarō!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"barbatus","latin":"barbatus, barbata, barbatum","headword":"barbatus","letter":"b","pos":"adjective","posGroup":"adjective","english":"bearded, having a beard; (like the men of antiquity); (as sign of) adult","forms":["barbātum","barbātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cēterum ad scindendum aprum nôn ille Ca1pūs ac- cessit quī altilia lacerāverat, sed {{barbātus}} ingēns, fasciîs crürâlibus alligātus et āliculā sub- ômâtus polymitā, strictôque vënätôriô cultrô latus aprî vehementer percussit ēvolāvērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"barcala","latin":"barcala, barcalae","headword":"barcala","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"fool, simpleton","forms":["barcalae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Notāvit haec Trimalchiô iussitque afferrî omnia, et “Vidëtîs” inquit “mulieris compedēs: sīc nôs {{barcalae}} dēspoliāmur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"barce","latin":"Barce, Barces","headword":"Barce","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"Barce; (city in Libya; also nurse of Sychaeus)","forms":["Barcēn"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tum breviter {{Barcēn}} nūtrīcem adfāta Sychaeī,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"bas","latin":"bas, baseos/is","headword":"bas","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"pedestal; base, point of attachment; foundation, support; chord (of an arc)","forms":["bas"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fretum trànsnà{{bas}} ut illa (Hērō) ānī- transnabàs, animum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"basilica","latin":"basilica, -ae","headword":"basilica","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"basilica; basilica, public hall","forms":["basilica","basilicae","basilicam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aedificia pūblica amplissima sunt duae {{basilicae}}, Aemilia et Iūlia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"basio","latin":"basio, basiare, basiavi, basiatus","headword":"basio","letter":"b","pos":"verb","posGroup":"verb","english":"kiss, give a kiss","forms":["bāsiet"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô, ut sciat mē posse mālum dare, nôlô mē mortuum {{bāsiet}}!”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"basium","latin":"bāsium, -ī","headword":"bāsium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"kiss","forms":["basia","basiorum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Da mi {{basia}} mille, deinde centum,","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"bassus","latin":"bassus, bassa, bassum","headword":"bassus","letter":"b","pos":"adjective","posGroup":"adjective","english":"low, base; base (Cal); [follis bassus => baseball]","forms":["Bassa","Bassam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Nec scilicet in te, sed in {{Bassam}} scriptum est hoc:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"bat","latin":"bat","headword":"bat","letter":"b","pos":"conjunction","posGroup":"conjunction","english":"but, while, however; (contemptuous parity of \"at\" - b-b-but)","forms":["bāt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"*crūdēlīs Théseu!\" clàmà{{bāt}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"baucis","latin":"Baucis, Baucidis","headword":"Baucis","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"Baucis","forms":["Baucidis","Baucis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Utinam nē nōs in viam pellant!” Hīs verbīs dictīs iānuam pulsāvērunt casae, in quā {{Baucis}} cum Philēmone habitābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"be","latin":"be","headword":"be","letter":"b","pos":"interjection","posGroup":"interjection","english":"baa (sound made by sheep)","forms":["be"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sit bene conveniēns et sine là{{be}} toga.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"beatum","latin":"beatum, beati","headword":"beatum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"happiness, blessedness; good fortune; good circumstances","forms":["beātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Quem Antiochus coepit illicere ut lēgem dēsereret, affirmāns eum dīvitem fore et {{beātum}}; sed adulēscēns nec minīs movēbātur, nec prōmissīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"beatus","latin":"beātus, -a, -um","headword":"beātus","letter":"b","pos":"adjective","posGroup":"adjective","english":"blessed, fortunate; happy, blessed","forms":["beātā","beātam","beātī","beātior","beātiōrēs","beātissimī","beātissimus","beātius","beātōs","beātus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Is sōlus {{beātus}} esse mihi vidētur cui nōn modo corpus sānum est, sed etiam mēns sāna in corpore sānō.” quam philosophōs nōn legō neque deōs vereor.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"bellare","latin":"(bellō) bellāre","headword":"bellāre","letter":"b","pos":"","posGroup":"other","english":"wage war, fight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"bellator","latin":"bellātor, -ōris (m.)","headword":"bellātor","letter":"b","pos":"","posGroup":"other","english":"warrior","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"bellatrix","latin":"bellatrix, (gen.), bellatricis","headword":"bellatrix","letter":"b","pos":"adjective","posGroup":"adjective","english":"warlike, martial; skilled/useful in war; of animals/things used in war","forms":["bellātrīx"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{bellātrīx}}, audetque virīs concurrere virgō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"belle","latin":"belle, bellius, bellissime","headword":"belle","letter":"b","pos":"adverb","posGroup":"adverb","english":"well, nicely; satisfactorily/agreeably, suitably/neatly; fortunately/favorably","forms":["bellē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Fuit Ēchō iūcundissimā nymphā, quae tam pulchrā vōce canere fābulāsque tam bellē nārrāre solēbat, ut ipsa Iūnō, deōrum rēgīna, saepe ex altō Olympō dēscenderet, ut eam canentem loquentemve studiōsē audīret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"bellicosus","latin":"bellicōsus, -a, -um","headword":"bellicōsus","letter":"b","pos":"adjective","posGroup":"adjective","english":"warlike","forms":["bellicōsa","bellicōsās","bellicōsō","bellicōsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Urbs antīqua fuit, Karthāgō, in ōrā Āfricae contrā Italiam sita, dīves atque {{bellicōsa}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"bellicus","latin":"bellicus, -a, -um","headword":"bellicus","letter":"b","pos":"adjective","posGroup":"adjective","english":"of war, military","forms":["bellicās","bellicīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praedās {{bellicās}} imperātōrēs cum paucīs diripiēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"bellis","latin":"bellis, bellis","headword":"bellis","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"flower (perh. daisy); (white daisy, ox-eye - L+S)","forms":["bellīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Pāruit Aenēās et formīdābilis Orcī\nvīdit opēs ātavōsque suōs umbramque senīlem\nmagnanimī Anchīsae; didicit quoque iūra locōrum,\nquaeque novīs essent adeunda perīcula {{bellīs}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"bello","latin":"bello, bellare, bellavi, bellatus","headword":"bello","letter":"b","pos":"verb","posGroup":"verb","english":"fight, wage war, struggle; take part in war/battle/fight (also animals/games)","forms":["bellandī","bellāns","bellantem","bellantēs","bellāre","bellātum","bello"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de {{bello}} consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bellovacus","latin":"Bellovacus, Bellovaci","headword":"Bellovacus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"Bellovaci, tribe of Gallia Belgica (near Rouen in Normandy) - Caesar","forms":["Bellovaci","Bellovacis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"{{Bellovaci}} autem, defectione Aeduorum cognita, qui iam ante erant per se infideles, manus cogere atque aperte bellum parare coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bellum","latin":"bellum, -ī","headword":"bellum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"war","forms":["bella","belli","bellōrum","bellum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui {{belli}} initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bellus","latin":"bellus, -a, -um","headword":"bellus","letter":"b","pos":"adjective","posGroup":"adjective","english":"lovely, pretty; pretty, fine","forms":["bellas","bellissimum","bellus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: \"Et viri veniunt ut {{bellas}} feminas spectent!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"belo","latin":"belo, belare, belavi, belatus","headword":"belo","letter":"b","pos":"verb","posGroup":"verb","english":"bleat, baa (like a sheep); talk foolishly","forms":["Bēlō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ā Bēlō solitī; tum facta silentia tēctīs:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"belua","latin":"bēlua, -ae","headword":"bēlua","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"beast, wild animal; wild beast","forms":["bēluae","bēluam","bēluās","bēluīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is vīderat {{bēluam}} ūnam cēterīs maiōrem, ac phalerīs rēgis circumtēctam; exīstimāns illa rēgem vehī, sē prō communī saliite dēvōvit: per mediōs hostēs ad bēluam properāvit, sub illīus ventrem subiit, repefifīs ictibus cōnfossam occīdit, et bēluae lābentis pondere oppressus ipse occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"bene","latin":"bene","headword":"bene","letter":"b","pos":"adverb","posGroup":"adverb","english":"well","forms":["bene"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Haec cogitanti accidere visa est facultas {{bene}} rei gerendae.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"benedico","latin":"benedico, benedicere, benedixi, benedictus","headword":"benedico","letter":"b","pos":"verb","posGroup":"verb","english":"bless; praise; speak well of; speak kindly of (classically 2 words)","forms":["benedīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cēnantibus autem iīs, accēpit pānem, {{benedīxit}} ac frēgit, dēditque discipulīs suīs et ait:\"Accipite et comedite: hoc est corpus meum.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"benefacio","latin":"benefacio, benefacere, benefeci, benefactus","headword":"benefacio","letter":"b","pos":"verb","posGroup":"verb","english":"do service/good to; make well/ably; benefit; bless; (usu. 2 words)","forms":["benefacite"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Vidēns Jēsus turbās, ascendit in montem et docēbat eās:\"Audīstis dictum esse ab antīquīs: ' dīligēs proximum tuum, et odiō habēbis inimīcum tuum. ' Ego autem dīcō vōbīs: dīligite inimīcōs vestrōs, et {{benefacite}} hīs quī ōdērunt vōs, et ōrātē prō persequentibus et calumniantibus vōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"beneficentia","latin":"beneficentia, beneficentiae","headword":"beneficentia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"beneficence, kindness; honorable treatment","forms":["beneficentia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Miserēre pauperum, ut Deus tuī misereātur: quantum potuerīs, estō beneficus et līberālis; sī tibi magnae opēs suppetant, multum tribue, sī parvae, parum, sed libenter; quoniam {{beneficentia}} hominem ab aeternā morte līberat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"beneficium","latin":"beneficium, -ī","headword":"beneficium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"good deed; kindness, good deed; kindness, favour; kindness, service","forms":["beneficia","beneficiī","beneficiīs","beneficio","beneficiōrum","beneficium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, '{{beneficia}} habetis, quem proditionis insimulatis; cuius opera sine vestro sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"beneficus","latin":"beneficus, benefica -um, beneficentior -or -us, beneficentissimus -a -um","headword":"beneficus","letter":"b","pos":"adjective","posGroup":"adjective","english":"beneficent, kind, generous, liberal, serviceable","forms":["beneficis","beneficus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tamen tanta universae Galliae consensio fuit libertatis vindicandae et pristinae belli laudis reciperandae, ut neque {{beneficis}} neque amicitiae memoria moverentur, omnesque et animo et opibus in id bellum incumberent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"benevolentia","latin":"benevolentia, benevolentiae","headword":"benevolentia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"benevolence, kindness, goodwill; favor; endearments","forms":["benevolentia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quae tametsi Caesar intellegebat, tamen quam mitissime potest legatos appellat: nihil se propter inscientiam levitatemque vulgi gravius de civitate iudicare neque de sua in Aeduos {{benevolentia}} deminuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"benigne","latin":"benigne, benignius, benignissime","headword":"benigne","letter":"b","pos":"adverb","posGroup":"adverb","english":"kindly, benevolently, obligingly; courteously, cheerfully; freely, generously","forms":["benignē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quam ob rem Iōsēphus benignē habitus est ab erō, quī praefēcit eum domuī suae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"benignus","latin":"benignus, -a, -um","headword":"benignus","letter":"b","pos":"adjective","posGroup":"adjective","english":"kind, benevolent; kind","forms":["benigna","benignae","benignī","benignīs","benignus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tantus populī favor invidiam Saūlis accendit, quī deinceps malevolō fuit in Davidem animō, nec iam eum {{benignīs}} oculīs aspiciēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"beo","latin":"beo, beare, beavi, beatus","headword":"beo","letter":"b","pos":"verb","posGroup":"verb","english":"bless, make happy, gladden, delight; enrich (with)","forms":["beat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{beat}} | quó cōnsule : quō annó (nam","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"bestia","latin":"bēstia, -ae","headword":"bēstia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"beast, animal","forms":["bēstia","bēstiae","bēstiam","bēstiārum","bēstiās","bēstiīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius id quod in herbā iacet manū tangit atque “Fui!” inquit horrēns, “Est parva {{bēstia}} nūda.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"bestiola","latin":"bestiola, bestiolae","headword":"bestiola","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"little creature, insect","forms":["bēstiolae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Cēra est māteria mollis quam apēs, {{bēstiolae}} industriae, faciunt.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"beta","latin":"beta, betae","headword":"beta","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"beet, beetroot","forms":["bēta","bētās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tlēpolemus: “Sciō nōmina litterārum: {i}alpha, {{bēta}}, gamma...{/i}”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"bibere","latin":"bibere","headword":"bibere","letter":"b","pos":"verb","posGroup":"verb","english":"to drink","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"bibit","latin":"bibit, -unt","headword":"bibit","letter":"b","pos":"verb","posGroup":"verb","english":"drink; drinks","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"bibliotheca","latin":"bibliothēca, -ae","headword":"bibliothēca","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"library","forms":["bibliothēcā","bibliothēcās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et nē mē putēs studia fastîdîtum, très {{bibliothēcās}} habeô, ūnam Graecam, altē- Cum dîxisset Agamemnôn: “Pauper et dîves inimîcî inquit Agamemnôn, et nesciô quam contrôversiam ex- Statim Trimalchiô “Hoc” inquit “sî factum est, contrô- versia nôn est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bibo","latin":"bibō, -ere, bibī, bibitum","headword":"bibō","letter":"b","pos":"verb","posGroup":"verb","english":"drink","forms":["bibam","bibāmus","bibant","bibās","bibat","bibe","bibēbant","bibēbat","bibendī","bibendum","bibentem","bibentēs","bibentī","bibentibus","bibentium","biberam","bibere","biberet","bibērunt","bibet","bibī","bibimus","bibis","bibisse","bibissent","bibisset","bibistī","bibistis","bibit","Bibitē","bibō","bibunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mīles laetus ē manū Mēdī {{bibit}} et ‘aquam bonam esse’ dīcit: “Aqua bona est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"bibrax","latin":"Bibrax, Bibractis","headword":"Bibrax","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"Bibrax, a town of the Remi in central Gaul","forms":["Bibracte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eo cum Eporedorix Viridomarusque venissent et de statu civitatis cognovissent, Litaviccum {{Bibracte}} ab Aeduis receptum, quod est oppidum apud eos maximae auctoritatis, Convictolitavem magistratum magnamque partem senatus ad eum convenisse, legatos ad Vercingetorigem de pace et amicitia concilianda publice missos, non praetermittendum tantum commodum existimaverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bibulus","latin":"bibulus, bibula, bibulum","headword":"bibulus","letter":"b","pos":"adjective","posGroup":"adjective","english":"fond of drinking, ever thirsty; soaking, sodden; spongy, absorbent, porous","forms":["Bibulō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Bibulō cōnsul est factus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"bidens","latin":"bidens, bidentis","headword":"bidens","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"heavy hoe, mattock with two iron teeth","forms":["bidentis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"exquīrunt; mactant lēctās dē mōre {{bidentis}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"biduum","latin":"bīduum, -ī","headword":"bīduum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"two days","forms":["biduo","biduum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar {{biduum}} in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"biennium","latin":"biennium, ī (n.)","headword":"biennium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"two years; period of two years","forms":["bienniō","biennium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post {{biennium}} rēx ipse habuit somnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"biformis","latin":"biformis, -e","headword":"biformis","letter":"b","pos":"adjective","posGroup":"adjective","english":"two-formed","forms":["biforme","biformēs","biformī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quod {{biforme}} mōnstrum, taurus cum capite hominis, nātus Pāsiphaae et taurī albī, sub rēgiā in labyrinthō habitābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"bifurcum","latin":"bifurcum, bifurci","headword":"bifurcum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"fork; point at which anything forks; fork of thighs, crotch","forms":["bifurcum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In lārvam inträvî, paene animam ébul- lîvî, sūdor mihi per {{bifurcum}} volābat, oculî mortuî, vix “Melissa mea mîrärî coepit quod tam sërô ambulārem, et “Sî ante”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bilis","latin":"bilis, bilis","headword":"bilis","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"gall, bile; wrath, anger, indignation; madness, melancholy, folly","forms":["bīlī","bīlis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{bīlis}}: ibi Rōmānī à Gallīs vīctī sunt","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"bimaris","latin":"bimaris, -e","headword":"bimaris","letter":"b","pos":"adjective","posGroup":"adjective","english":"lying between two seas","forms":["bimarem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iamque Thēseus aderat fīlius parentī ignārus, quī virtūte suā {{bimarem}} isthmum pācāverat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"bimatus","latin":"bimatus, bimatus","headword":"bimatus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"two years of age; (of animals)","forms":["bimatū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et imperāvit ut occīderentur omnēs Īnfantēs quī erant in cīvitāte Bēthlehem et in fīnibus, ā bimatū et Īnfrā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"bimus","latin":"bimus, bima, bimum","headword":"bimus","letter":"b","pos":"adjective","posGroup":"adjective","english":"two years old; for/lasting two years","forms":["bimus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sīve humilés propiōre fretō iactá{{bimus}} ālās,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"bini","latin":"bīnī, -ae, -a","headword":"bīnī","letter":"b","pos":"adjective","posGroup":"adjective","english":"two at a time; two each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"bipertito","latin":"bipertito","headword":"bipertito","letter":"b","pos":"adverb","posGroup":"adverb","english":"in two parts/divisions/ways; [esse ~ => to be divided]","forms":["bipertītō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Illī autem, quī omnia dē rē pūblicā praeclārā atque ēgregiā sentīrent, sine recūsātiōne ac sine ūllā morā negōtium suscēpērunt, et, cum advesperāsceret, occultē ad pontem Mulvium pervēnērunt atque ibi in proximīs villīs ita bipertītō fuērunt ut Tiberīs inter eōs et pōns interesset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"biremis","latin":"birēmis, -e","headword":"birēmis","letter":"b","pos":"adjective","posGroup":"adjective","english":"with two banks of oars","forms":["birēmis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ecce classis Graecōrum, {{birēmis}}, trirēmis; servī remōs dūcentēs; ducēs ventum secundum spērantēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"bis","latin":"bis","headword":"bis","letter":"b","pos":"adverb","posGroup":"adverb","english":"twice","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"bisaccium","latin":"bisaccium, bisacci(i)","headword":"bisaccium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"double bag; pair of saddle bags","forms":["bisacci"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cēterum in prômulsidän‘ asellus erat Corinthius cum {{bisacci}}ô positus, quī habēbat olîväs in alterā parte albās, in alterā nigrās.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bitias","latin":"Bitias, Bitiae","headword":"Bitias","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"Bitias; (Trojan warrior, companion of Aeneas)","forms":["Bitiae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tum {{Bitiae}} dedit increpitāns; ille impiger hausit","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"bitumen","latin":"bitumen, bituminis","headword":"bitumen","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"bitumen, pitch, asphalt (generic name for various hydrocarbons)","forms":["bitūmine"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Noēmus, admonitus ā Deō, exstrūxit ingentem arcam in modum nāvis; līnīvit eam {{bitūmine}}, et in eam indūxit pār ūnum omnium avium et animantium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"biturig","latin":"Biturig, Biturigis","headword":"Biturig","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"Bituriges (pl.), a people of SW Gaul, Aquitania - in Caesar's \"Gallic War\"","forms":["Bituriges","Biturigibus","Biturigum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium Cadurcum, summae hominem audaciae, cum parte copiarum in Rutenos mittit; ipse in {{Bituriges}} proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"blaesus","latin":"blaesus, blaesa, blaesum","headword":"blaesus","letter":"b","pos":"adjective","posGroup":"adjective","english":"lisping, stammering; indistinct; mispronouncing from speech defect/drunkenness","forms":["blaesā","blaesō","blaesus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"fac titubet blaesō subdola","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"blande","latin":"blande, blandius, blandissime","headword":"blande","letter":"b","pos":"adverb","posGroup":"adverb","english":"in coaxing/winning manner, charmingly, persuasively, seductively","forms":["blandē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Exceptī ab Tullō blandē ac benignē, libenter rēgis convīviō intersunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"blandiens","latin":"blandiens, blandientis","headword":"blandiens","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"flatterer; sweet talker","forms":["blandientem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fāma est etiam Hannibalem annōrum fermē novem, puerīliter {{blandientem}} patrī Hamilcarī ut dūcerētur in Hispāniam, cum — perfectō Āfricō bellō — exercitum eō trāiectūrus sacrificāret, ārīs admōtum tāctīsque sacrīs iūre iūrandō adactum ā patre esse 'sē, cum prīmum posset, hostem fore populō Rōmānō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"blandio","latin":"blandio, blandire, blandivi, blanditus","headword":"blandio","letter":"b","pos":"verb","posGroup":"verb","english":"flatter, delude; fawn; coax, urge, behave/speak ingratiatingly; allure; please","forms":["blandīre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Postibus et dūrae supplex {{blandīre}} puellae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"blandiri","latin":"(blandior) blandīrī","headword":"blandīrī","letter":"b","pos":"","posGroup":"other","english":"coax, urge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"blanditia","latin":"blanditia, blanditiae","headword":"blanditia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"flattery, caress, compliment; charm (pl.), flatteries, enticement, courtship","forms":["blanditiae","blanditiās","Blanditiīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{blanditiae}} -àrum f p/ 7 blanda verba [Cēra blanditiās ferat]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"blanditus","latin":"blanditus, blandita, blanditum","headword":"blanditus","letter":"b","pos":"adjective","posGroup":"adjective","english":"pleasant, agreeable, charming","forms":["blanditi"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Blanditi}}ás mollés auremque iuvantia verba","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"blando","latin":"blando","headword":"blando","letter":"b","pos":"adverb","posGroup":"adverb","english":"in coaxing/winning manner, charmingly, persuasively, seductively","forms":["blandō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut medium campī passīs tetigēre capillīs, in terram positō prōcubuēre genū, et quasi sentīrent, blandō clāmōre nepōtēs tendēbant ad avōs bracchia parva suōs; quī poterat clāmābat \"avum\", tunc dēnique vīsum, et quī vix poterat posse coāctus erat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"blandus","latin":"blandus, -a, -um","headword":"blandus","letter":"b","pos":"adjective","posGroup":"adjective","english":"charming, ingratiating","forms":["blanda","blandās","blandīs","blandus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[Dē puellā {{blandīs}} verbīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"blasphemo","latin":"blasphemo, blasphemare, blasphemavi, blasphematus","headword":"blasphemo","letter":"b","pos":"verb","posGroup":"verb","english":"blaspheme (against God); revile; reproach","forms":["blasphēmābat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dnus autem d ē hīs latrōnibus, quī pendēbant, {{blasphēmābat}} eum, dīcēns:\"Sī tū es Chrīstus, salvā tē ipsum et nōs.\"Et alter ihcrepābat eum dīcēns:\"Neque tū timēs Deum?\"Et dīxit illī Jēsus:\"Hodiē mēcum eris in paradīsō.\"Et obscūrātus est sōl, et vēlum temp lī scissum est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"blatio","latin":"blatio, blatire, -, -","headword":"blatio","letter":"b","pos":"verb","posGroup":"verb","english":"prate, babble; utter in a babbling way; (applied to sounds of certain animals)","forms":["blatīs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ita nūgās {{blatīs}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"blepharon","latin":"blepharon, blephari","headword":"blepharon","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"eyelid (? Greek); [Chariton blepharon => kind of coral?]","forms":["Blepharō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Postquam omnēs praeter {{Blepharō}}nem turbātī atque incertī discessērunt, Amphitryō amīcum suum cōnsulit, quid sibi faciendum esse cēnseat; nec vērō Blepharō dīiūdicāre quit, uter sit vērus Amphitryō atque Alcumēnae marītus.]","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"boa","latin":"boa, boae","headword":"boa","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"large Italian snake; water serpent; disease with pustules (measles/smallpox)","forms":["boum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sīc Davidem allocūtus est prophēta Nāthan: “Erant in eādem urbe duo hominēs: alter dīves multōs {{boum}}, caprārum atque ovium gregēs alēbat; alter vērō nihil habēbat praeter ovem ūnam, quam ipse ēmerat, et apud sē dīligenter nūtriēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"boarius","latin":"boarius, boaria, boarium","headword":"boarius","letter":"b","pos":"adjective","posGroup":"adjective","english":"of oxen/cattle; [forum boarium => cattle market at Rome]","forms":["Boāriō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vīcus Tuscus forum Rōmānum cum forō Boāriō iungit, id est forum celebre prope Tiberim flūmen, ubi bovēs aliaeque pecudēs vēneunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"boius","latin":"Boius, Boii","headword":"Boius","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"Boli (pl.), a people of Cisalpine Gaul - in Caesar's \"Gallic War\"","forms":["Boiorum","Boios"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, {{Boiorum}} oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bona","latin":"bona, -ōrum","headword":"bona","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"goods, property","forms":["bona"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Bona}} civium Romanorum diripiunt, caedes faciunt, in servitutem abstrahunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bonatus","latin":"bonatus, bonata, bonatum","headword":"bonatus","letter":"b","pos":"adjective","posGroup":"adjective","english":"good natured","forms":["bōnātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Scîs tñ mē nôn mentîrî: Agathô unguentārius proximē sēdūxit mē et “Suädeô” inquit “nôn patiāris genus tuum interîre.” At ego, dum {{bōnātus}} agô et nôlô vidërî levis, ipse mihi asciam in crūs “Rēctē!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bonum","latin":"bonum, -ī","headword":"bonum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"blessing, a good; good, blessing (pl. goods)","forms":["bonī","bonis","bonō","bonōrum","bonum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interim nuntio allato omnes eorum milites in potestate Caesaris teneri, concurrunt ad Aristium; nihil publico factum consilio demonstrant; quaestionem de {{bonis}} direptis decernunt, Litavicci fratrumque bona publicant, legatos ad Caesarem sui purgandi gratia mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bonus","latin":"bonus, -a, -um","headword":"bonus","letter":"b","pos":"adjective","posGroup":"adjective","english":"good","forms":["bonae","bonam","bonās","bone","bonōs","bonus","melior","meliōra","meliōre","meliōrem","meliōrēs","meliōribus","meliōris","meliōrum","melius","optimā","optimae","optimam","optime","optimī","optimīs","optimō","optimōs","optimum","optimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sua in illos merita proponit obtestaturque ut suae salutis rationem habeant, neu se {{optime}} de communi libertate meritum hostibus in cruciatum dedant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"boreas","latin":"Boreas, Boreae","headword":"Boreas","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"north wind; the_North; Boreas (god of the north wind)","forms":["Boreā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ut Boreā frondēs excutiente cadunt.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"bos","latin":"bōs, bovis","headword":"bōs","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"(m./f.) ox; ox, cow","forms":["bōs","bove","bovem","bovēs","bovis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Et invēnit in templō vēndentēs {{bovēs}}, et ovēs et columbās et ~ nummulāriōs sedentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"bracchium","latin":"bracchium, -ī","headword":"bracchium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"arm; arm, limb; arm, branch","forms":["bracchia","bracchiī","bracchiīs","bracchiō","bracchium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Nōn dormit” respondet Iūlius, “Quīntus dormīre nōn potest, quod iam nōn modo pēs eius dolet, sed etiam {{bracchium}}.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"brachium","latin":"brachium, brachi(i)","headword":"brachium","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"arm; lower arm, forearm; claw; branch, shoot; earthwork connecting forts","forms":["brāchiīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"“Ō Tarpēia” dīxērunt, “quamquam mala et improba fēmina nōbīs vidēris esse, dabimus tamen, ut pollicitī sumus, ea, quae in {{brāchiīs}} nostrīs sinistrīs gerimus!” Tarpēia laeta ad mīlitēs accessit; quī quidem rīdentēs in eam nōn armillās, sed gravissima sua scūta iēcērunt!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"brattea","latin":"brattea, bratteae","headword":"brattea","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"gold leaf/foil, thin sheet of metal (esp. gold)/other material; veneer; show","forms":["brattea"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"īnspice quam tenuis {{brattea}} ligna tegat!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"breve","latin":"breve, brevis","headword":"breve","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"shallow water, shallows; a short/brief space of time; short speech, a few words","forms":["breve"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Post {{breve}} tempus Eurōpam uxōrem dūxit et eam terram, ad quam simul cum eā pervēnerat, Eurōpam appellāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"brevi","latin":"brevī","headword":"brevī","letter":"b","pos":"adverb","posGroup":"adverb","english":"in a short time; soon, in a short time","forms":["brevī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tlēpolemus: “Sed erō meō prōmīsī ‘mē brevī tempore reditūrum esse.’ Neque enim aliōs habet servōs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"brevis","latin":"brevis, -e","headword":"brevis","letter":"b","pos":"adjective","posGroup":"adjective","english":"short","forms":["brevem","brevēs","brevia","brevibus","brevior","brevis","brevissimē","brevissimum","brevissimus","brevius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iūlius corpora bēstiārum rūrsus tangit et ālās {{brevēs}} sentit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"breviter","latin":"breviter","headword":"breviter","letter":"b","pos":"adverb","posGroup":"adverb","english":"briefly","forms":["breviter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Discedentibus his {{breviter}} sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"bria","latin":"bria, briae","headword":"bria","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"wine vessel","forms":["bria"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sed haec sô{{bria}}, ‘bonôrum cônsiliôrum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"britannia","latin":"Britannia, Britanniae","headword":"Britannia","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"Britain","forms":["Britannia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, fideli atque utili superioribus annis erat usus in {{Britannia}} Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, iura legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"britannicus","latin":"Britannicus, Britannica, Britannicum","headword":"Britannicus","letter":"b","pos":"adjective","posGroup":"adjective","english":"British","forms":["Britannicum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is prīmus vīcit Helvētiōs, deinde vincendō per bella gravissima usque ad Ōceanum {{Britannicum}} prōcessit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"brutum","latin":"brutum, bruti","headword":"brutum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"beast, animal; brute","forms":["Brutum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; {{Brutum}} adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"brutus","latin":"brūtus, -a, -um","headword":"brūtus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"brutish, stupid","forms":["Brūtī","Brūtō","Brutus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ille vērō, cum nōndum sacrāvisset novum templum, Rōmā expulsus est ā Iūniō Brūtō, atque prō rēge duō cōnsulēs populō Rōmānō praepositī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"bubo","latin":"bubo, bubonis","headword":"bubo","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"horned or eagle owl (esp. as bird of ill omen)","forms":["būbō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sōlaque culminibus fērālī carmine būbō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"bucca","latin":"bucca, buccae","headword":"bucca","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"jaw, mouth; mouthful; cheek (with blowing a trumpet); cavity (knee joint) (L+S)","forms":["buccam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn meherculēs hodiē {{buccam}} pānis invenîre potuî.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"buccina","latin":"buccina, buccinae","headword":"buccina","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"horn; bugle, watch-horn; (curved) trumpet, war trumpet; shell Triton blew","forms":["buccinae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Coepērunt exaudīrī tonitrua, micāre fulgura: nūbēs dēnsa operiēbat montem, et clangor {{buccinae}} vehementius perstrepēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"bucinus","latin":"bucinus, bucini","headword":"bucinus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"trumpeter; epithet for cock/rooster","forms":["būcinus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô ânulum trāiēcit in dexteram manum, et “Nôn sine causā” inquit “hic {{būcinus}} signum dedit; nam aut incendium oportet ﬁat, aut aliquis in vîcîniâ animam abiciet.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bul","latin":"bul, undeclined","headword":"bul","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"Bul (rain), Heshvan, Jewish month; (8th in ecclesiastic year)","forms":["bul"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quod autem in mediô caespitem vidētis et super caespitem terrā māter est in mediô quasi ôvum corrotundāta, et omnia bona in sē habet tamquam favus.” [F erculum secundum.' aper cum vënätiônis apparātū] “Sophôs!” üniversî clâmämus, et sublätîs manibus ad 40 cameram iürâmus ‘Hipparchum Arätumque comparandôs posuērunt in quibus rētia erant picta subsessôrësque cum vënä{{bul}}îs et tôtus vënätiônis apparātus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bulbus","latin":"bulbus, bulbi","headword":"bulbus","letter":"b","pos":"noun (m.)","posGroup":"noun","english":"bulb; onion, edible bulb","forms":["Bulbō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Atīliō Bulbō cōnsulibus dē Sardīs triumphātum est, et pāce omnibus locīs factā Rōmānī nūllum bellum habuērunt, quod iīs post Rōmam conditam semel tantum, Numā Pompīliō regnante, contigerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"bule","latin":"bule, bules","headword":"bule","letter":"b","pos":"noun (f.)","posGroup":"noun","english":"Greek council or senate","forms":["bulae","bulās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque quotiēnscumque dîcit “Carpe!” eôdem verbô et [Dê Fortûnätä, dê dîvitiîs T rimalchiônis, dē collîbertîs] Nôn potuî amplius quicquam gustāre, sed conversus ad eum, ut quam plūrima exciperem, longē accersere tä{{bulās}} coepî scîscitäxîque ‘quae esset mulier illa quae hūc atque “Uxor” inquit “Trīma1chiônis, ‘Fortūnāta’ appellättlr; quae nummôs modiô mëtîtur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"bus","latin":"bus, bus","headword":"bus","letter":"b","pos":"noun","posGroup":"noun","english":"ox, bull; cow; cattle (pl.); (odd form mostly in Varro)","forms":["bi","būbus","bus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nōn est hic, sed surrēxit.\"Paulō post appāruit Jēsus duo {{bus}} discipulīs euntibus ad castellum, nōmine Emmāus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"buthrotum","latin":"Buthrotum, Buthroti","headword":"Buthrotum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"Buthrotum; (city in Epirus where Helenus ruled)","forms":["Būthrōtī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum sociōs portum linquere iussit, ac nāvēs ab īnsulā Leucadiā praeter lītora Ēpīrī vectae prōtinus ad portum Būthrōtī urbis accessērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"buxeus","latin":"buxeus, buxea, buxeum","headword":"buxeus","letter":"b","pos":"adjective","posGroup":"adjective","english":"of/connected with box-tree; of boxwood; characteristic of boxwood (color)","forms":["buxeā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Lacerātus igitur ab illô doctissimô cocô quī paulô ante dē porcô avēs piscësque tēcerat, in caccabum est coniectus, dumque Daedalus pôtiônem ferventissimam haurit, Fortūnāta molā buxeā Sümptîs igitur matteîs, respiciēns ad familiam Trimal- chiô “Quid vôs” inquit “adhūc nôn cēnāstis?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"byssinum","latin":"byssinum, byssini","headword":"byssinum","letter":"b","pos":"noun (n.)","posGroup":"noun","english":"garment made of fine flax (byssus)","forms":["byssinā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum dētrāxit ē manū suā annulum, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō torquem aureum circumdedit, eumque in currū suō secundum collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"caccabus","latin":"caccabus, caccabi","headword":"caccabus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"pot (cooking/kitchen); pan (Cal)","forms":["caccabum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lacerātus igitur ab illô doctissimô cocô quī paulô ante dē porcô avēs piscësque tēcerat, in {{caccabum}} est coniectus, dumque Daedalus pôtiônem ferventissimam haurit, Fortūnāta molā buxeā Sümptîs igitur matteîs, respiciēns ad familiam Trimal- chiô “Quid vôs” inquit “adhūc nôn cēnāstis?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cachinno","latin":"cachinno, cachinnare, cachinnavi, cachinnatus","headword":"cachinno","letter":"c","pos":"verb","posGroup":"verb","english":"laugh aloud or boisterously, guffaw; laugh loudly at","forms":["cachinnō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Est quae perversō distorqueat ōrā cachinnō;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cachinnus","latin":"cachinnus, -ī","headword":"cachinnus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"laugh, guffaw","forms":["cachinnis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"et vino et sale et omnibus {{cachinnis}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"caco","latin":"caco, cacare, cacavi, cacatus","headword":"caco","letter":"c","pos":"verb","posGroup":"verb","english":"defecate; defecate upon; defile with excrement; (rude)","forms":["cacantī","cacātum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praepônam enim ūnum ex meum populus {{cacātum}} currat!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cacumen","latin":"cacumen, cacuminis","headword":"cacumen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"top, peak, summit; shoot, blade of grass, tip of tree/branch; zenith; limit","forms":["cacuminibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Itaque truncis arborum aut admodum firmis ramis abscisis atque horum delibratis ac praeacutis {{cacuminibus}} perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cacus","latin":"Cacus, Caci","headword":"Cacus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cacus, giant son of Vulcan; (lived on Mt Aventius); servant (L+S)","forms":["Cācus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi cum eum somnus oppressisset, pāstor quīdam nōmine {{Cācus}}, ferōx viribus, bovēs pulcherrimōs ē grege rapere et praedam in spēluncam suam abdere voluit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cadaver","latin":"cadaver, cadaveris","headword":"cadaver","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"corpse, cadaver, dead body; ruined city","forms":["cadāver","cadāvera","cadaveribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quid hominum milibus LXXX uno loco interfectis propinquis consanguineisque nostris animi fore existimatis, si paene in ipsis {{cadaveribus}} proelio decertare cogentur?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cadit","latin":"cadit, cadere","headword":"cadit","letter":"c","pos":"verb","posGroup":"verb","english":"fall; falls","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cadmus","latin":"Cadmus, Cadmi","headword":"Cadmus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cadmus; (founder of Thebes, sowed dragon teeth)","forms":["Cadmī","Cadmō","Cadmus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quibus verbīs audītīs, omnēs fīliī (inter quōs erat quīdam nōmine {{Cadmus}}) ē patris domō exiērunt et: “Nesciō,” inquit quīdam eōrum, “quid faciāmus: nōbīs enim per tōtum mare omnēsque terrās soror quaerenda erit; nec umquam inveniēmus, nisi diū quaesīverimus.” Statuērunt igitur Ut aliī aliās regiōnēs peterent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cado","latin":"cadō, -ere, cecidī, cāsum","headword":"cadō","letter":"c","pos":"verb","posGroup":"verb","english":"fall, fall down","forms":["cadant","cadat","cadēbant","cadēbat","cadēns","cadentem","cadentēs","cadentia","cadentis","cadere","caderent","caderet","cadet","cadīs","cadit","cadunt","ceciderant","cecīderat","cecidēre","cecīderit","cecidērunt","cecidī","cecidisse","cecidissent","cecidisset","cecidistī","cecidit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Equus perterritus currit, atque mīles ad terram {{cadit}}!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"caduceum","latin":"caduceum, caducei","headword":"caduceum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"herald's staff carried as token of peace/truce; wand of Mercury","forms":["cādūceum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Erat autem vë- nälicium cum titulîs pictum, et ipse Trimalchiô capillātus {{cādūceum}} tenēbat Minerväque dūcente Rômam intrābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caducifer","latin":"caducifer, caducifera, caduciferum","headword":"caducifer","letter":"c","pos":"adjective","posGroup":"adjective","english":"staff-bearer, i.e. Mercury","forms":["cadūcifer"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hūc Iuppiter vēnit et Mercurius {{cadūcifer}} cum patre suō quoque vēnit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"caducum","latin":"caducum, caduci","headword":"caducum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"property without/that cannot be taken by an heir; unowned/escheated estate","forms":["cadūcum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Infrā autem iam nihil est nisi mortāle et {{cadūcum}} — praeter animōs mūnere deōrum hominum generī datōs; supra Lūnam sunt aeterna omnia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caducus","latin":"cadūcus, -a, -um","headword":"cadūcus","letter":"c","pos":"adjective","posGroup":"adjective","english":"ready to fall, perishable; falling, perishable","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"cadurcum","latin":"cadurcum, cadurci","headword":"cadurcum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"coverlet (of Cadurcian/French linen); marriage bed","forms":["Cadurcum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium {{Cadurcum}}, summae hominem audaciae, cum parte copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cadus","latin":"cadus, cadi","headword":"cadus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"jar, large jar for wine/oil/liquids; urn, funeral urn; money jar (L+S)","forms":["Cadus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: {{Cadus}} erat vīnī, inde implēvī hirneam...","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"caecitas","latin":"caecitas, caecitatis","headword":"caecitas","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"blindness, darkness; mental/moral blindness, lack of discernment","forms":["caecitātem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nam Tobiās adeō patienter tulit {{caecitātem}}, ut neque illum querentem quisquam audīerit, neque ille eō minus cōnstanter Deum coluerit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"caeco","latin":"caeco, caecare, caecavi, caecatus","headword":"caeco","letter":"c","pos":"verb","posGroup":"verb","english":"blind; obscure, confuse, hide; morally blind; [stu ~ => throw dust, deceive]","forms":["caecō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caecus","latin":"caecus, -a, -um","headword":"caecus","letter":"c","pos":"adjective","posGroup":"adjective","english":"blind","forms":["caeca","caecae","caecī","caecōs","caecum","caecus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum Isaacus iam senuisset, et factus esset {{caecus}}, vocāvit Esāüm: sūmitō, inquit pharetram, arcum et sagittās; affer mihi et parā dē vēnātiōne pulmentum, ut comedam et apprecer tibi fausta omnia, antequam moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"caedere","latin":"(caedō) caedere, cecīdisse, caesum","headword":"caedere","letter":"c","pos":"verb","posGroup":"verb","english":"beat, fell, kill; to kill, cut down; to cut down, kill","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"caedes","latin":"caedēs, caedis","headword":"caedēs","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) slaughter","forms":["caede","caedem","caedes","caedī","caedibus","caedium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ibi cognoscit de Clodi {{caede}}, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"caedis","latin":"caedis, caedis","headword":"caedis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"murder/slaughter/massacre; assassination; feuding; slain/victims; blood/gore","forms":["caedis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Numitor, postquam iuvenēs caede factā pergere ad sē grātulantēs vīdit, extemplō advocātō conciliō scelera frātris, orīginem nepōtum, caedem deinde tyrannī et sē {{caedis}} auctōrem ostendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caedo","latin":"caedō","headword":"caedō","letter":"c","pos":"verb","posGroup":"verb","english":"to kill, cut down","forms":["caederentur","caederēs","caedit","caedunt","caesam","caesī","caesīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prīmō rem bene gessit: caesī sunt hostēs et eōrum rēx captus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cael","latin":"cael, undeclined","headword":"cael","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"heaven, sky; universe, world; space; air, weather; Jehovah; (shortened form)","forms":["cael"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec minus rē- liquî convîvae mîrantës ērēxēre vultūs, expectantēs quid novî dē {{cael}}ô nüntiärëmr.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caeles","latin":"caeles, caelitis","headword":"caeles","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"the_Gods (usu. pl.); divinity, dweller in heaven; saint (Ecc)","forms":["caelitēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad quem ut vēnī, complexus mē senex collacrimāvit aliquantōque post suspexit ad caelum et 'Grātēs' inquit 'tibi agō, summe Sōl, vōbīsque, reliquī {{caelitēs}}, quod, ante quam ex hāc vītā migrō, cōnspiciō in meō rēgnō et hīs tēctīs P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caelestis","latin":"caelestis, -e","headword":"caelestis","letter":"c","pos":"adjective","posGroup":"adjective","english":"celestial, (m. pl.) gods; heavenly, divine","forms":["caelestēs","caelestī","caelestia","caelestibus","caelestis","caelestium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Viam mediam tenē: iter fac in mediō āere inter caelum et terram; altius ēgressus {{caelestia}} tēcta cremābis,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caelia","latin":"caelia, caeliae","headword":"caelia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"kind of beer; (Spanish L+S)","forms":["Caelium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In hortīs Nerōnis, quī usque ad montem {{Caelium}} patēbant, stagnum arte factum erat aedificiīs circumdatum atque campīs silvīsque cum multitūdine omnis generis pecudum ac ferārum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caelites","latin":"caelitēs, -um (m. pl.)","headword":"caelitēs","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"gods; the gods of heaven","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"caelo","latin":"caelo, caelare, caelavi, caelatus","headword":"caelo","letter":"c","pos":"verb","posGroup":"verb","english":"carve, make raised work/relief; engrave, emboss; chase, finish; embroider","forms":["caelāverat","caelō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sōl lūcet in caelō sine nūbibus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"caelum","latin":"caelum, -ī","headword":"caelum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"sky, heaven; sky, heavens; sky, the heavens","forms":["caelī","caelīs","caelōrum","caelum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia eam rīdēre nōn videt, nam {{caelum}} aspicit neque iam aquilam videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"caelus","latin":"caelus, caeli","headword":"caelus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"heaven, sky, heavens; space; air, climate, weather; universe, world; Jehovah","forms":["caelus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nam mihi nihil novî potest afferrî, sîcut ille ferculus iam “{{Caelus}} hīc, in quô duodecim diî habitant, in totidem sē ﬁgüräs convertit, et modo ﬁt Ariēs; itaque quisquis nāscitur illô signô multa pecora habet, multum lānae, caput praetereâ dūrum, frontem expudôrätam, comū acūtum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caeparius","latin":"caeparius, caeparii","headword":"caeparius","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"grower of onions; trader in onions (L+S)","forms":["Caepāriō","Caepārium","Caepārius"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur, cōnfirmātō animō, vocārī ad sēsē iubet Lentulum, Cethēgum, Statilium, Gabīnium, itemque {{Caepārium}} Tarracīnēnsem, quī in Āpūliam ad concitanda servitia proficīscī parābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"caerimonia","latin":"caerimōnia, -ae","headword":"caerimōnia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"rite, ceremony; ceremony, rite","forms":["caerimonia","caerimōniās","caerimōniīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima {{caerimonia}} continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"caeruleus","latin":"caeruleus, caerulea, caeruleum","headword":"caeruleus","letter":"c","pos":"adjective","posGroup":"adjective","english":"blue, cerulean, dark; greenish-blue, azure; of river/sea deities; of sky/sea","forms":["caerulea","caeruleae","caeruleī","caeruleōs","caeruleus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tandem Pygmaliōn fōrmōsissimae puellae signum cōnfēcit, quae aureum capillum, {{caeruleōs}} oculōs, rubra labra habēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caerulus","latin":"caerulus, caerula, caerulum","headword":"caerulus","letter":"c","pos":"adjective","posGroup":"adjective","english":"blue, cerulean; deep/sky/greenish-blue, azure; of river/sea deities; of sky/sea","forms":["caerula","caerulus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{caerula}} quot bācās Palladis arbor habet,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"caesa","latin":"caesa, caesae","headword":"caesa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cut; (of a sword/knife/spear)","forms":["caesa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Certāmine commissō, Pyrrhus vulnerātus est, elephantī interfectī, vīgintī mīlia {{caesa}} hostium, et ex Rōmānīs tantum quīnque mīlia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caesar","latin":"Caesar, Caesaris","headword":"Caesar","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Caesar; (Julian gens cognomen); [C. Julius ~ => Emperor]","forms":["Caesar","Caesare","Caesarem","Caesari","Caesaris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quieta Gallia, {{Caesar}}, ut constituerat, in Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"caesaries","latin":"caesaries, caesariei","headword":"caesaries","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hair; long/flowing/luxuriant hair; dark/beautiful hair; plume (of a helmet)","forms":["caesariem"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{caesariem}} nātō genetrīx lūmenque iuventae","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"caeso","latin":"Caeso, Caesonis","headword":"Caeso","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Kaeso/Caeso (Roman praenomen); (abb. K.)","forms":["caesō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et dum Albānus exercitus inclāmat Curiātiīs utī opem ferant frātrī, iam Horātius caesō hoste victor secundam pugnam petēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caespes","latin":"caespes, caespitis","headword":"caespes","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"grassy ground, grass; earth; sod, turf; altar/rampart/mound of sod/turf/earth","forms":["caespes","caespite","caespitem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{caespes}} -itis m :","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"caesum","latin":"caesum, caesi","headword":"caesum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"comma; pause, stop","forms":["caesum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rōmulus eam rem minus aegrē quam dignum erat tulisse dīcitur, seu ob īnfīdam societātem rēgnī, seu quia haud iniūriā Tatium {{caesum}} crēdēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"caesus","latin":"caesus, caesus","headword":"caesus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cutting, cutting off","forms":["caesus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Magnus numerus eōrum aut {{caesus}} aut captus est ā nostrīs, reliquī ultrā flūmen in magnīs silvīs latent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"calamitas","latin":"calamitās, -ātis ( f.)","headword":"calamitās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"misfortune, calamity; disaster, misfortune; disaster, defeat","forms":["calamitās","calamitate","calamitatem","calamitātēs","calamitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Depopulata Gallia Cimbri magnaque inlata {{calamitate}} finibus quidem nostris aliquando excesserunt atque alias terras petierunt; iura, leges, agros, libertatem nobis reliquerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"calamitosus","latin":"calamitosus, calamitosa, calamitosum","headword":"calamitosus","letter":"c","pos":"adjective","posGroup":"adjective","english":"calamitous; ruinous, destructive; liable to damage/disaster; damaged/miserable","forms":["calamitōsum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Namque alia bellī facinora praedae magis quam dētrīmentō fore, incendium vērō crūdēle, immoderātum ac sibi maximē {{calamitōsum}} putābat, quippe cui omnēs cōpiae in ūsū cotīdiānō et cultū corporis erant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"calamus","latin":"calamus, -ī","headword":"calamus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"reed, reed pen; reed pen","forms":["calamō","calamum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister {{calamum}} et chartam prōmit et ipse scrībere incipit; is enim calamō in chartā scrībit, nōn stilō in cērā ut discipulī. (Charta ex papȳrō efficitur, id est ex altā herbā quae in Aegyptō apud Nīlum flūmen reperītur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"calathus","latin":"calathus, calathi","headword":"calathus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"wicker basket, flower basket; wine-cup; milk pail; cheese/curdled milk bowl","forms":["calathīs","calathōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ōlim Proserpina, Cereris fīliā virgō, cum aliīs puellīs in campīs Siciliae laeta errābat lūdēns et aut violās aut candida līlia carpēns, {{calathōs}} ac sinum eō cōnsiliō implēbat, ut cēterās amīcās flōrēs colligendō vinceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calcar","latin":"calcar, -cāris (n.)","headword":"calcar","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"spur; stimulus","forms":["calcāribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam egō hanc victimam Mānibus peremptōrum foedē cīvium dabō!' subditīsque {{calcāribus}} equō per cōnfertissimam hostium turbam impetum facit cōnsulemque lanceā trānsfīxit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"calceamentum","latin":"calceamentum, calceamenti","headword":"calceamentum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"shoe; instrument for stretching hides","forms":["calceāmenta"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dā mihi {{calceāmenta}}!” Iam calceātus sum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"calceatus","latin":"calceatus, calceatus","headword":"calceatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"shoe; footwear; sandal","forms":["calceātus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dā mihi calceāmenta!” Iam {{calceātus}} sum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"calceo","latin":"calceo, calceare, calceavi, calceatus","headword":"calceo","letter":"c","pos":"verb","posGroup":"verb","english":"put shoes on, furnish with shoes; shoe (horses); put feet in something","forms":["calceō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pythia, nam sīc appellāta est Delphīs sacerdōs, ēdiderat nūllum esse perīculum eō tempore, sed rēgem verērī dēbēre iuvenem ūnō calceō sōlum indūtum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"calceus","latin":"calceus, -ī","headword":"calceus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"shoe; shoe, sandal","forms":["calceī","calceīs","calceōs","calceus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mercurius vērō continuō, sine morā, patris imperiō pāruit: induit {{calceōs}} suōs aureōs et ālis ornatōs, quibus ventō celerius volāre potest sīve super mare sīve super terram, et, virgam manū gerēns, ad campōs, in quibus ignēs ab hominibus accēnsōs vīderat, volandō pervēnit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calco","latin":"calco, calcare, calcavi, calcatus","headword":"calco","letter":"c","pos":"verb","posGroup":"verb","english":"tread/trample upon/under foot, crush; tamp/ram down; spurn; copulate (cock)","forms":["calcātīs","calcem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"'Er y Vērque novum stābat cīnctum flōrente corōnā, stābat nūda Aestās et spīcea serta gerēbat, stābat et Autumnus {{calcātīs}} sordidus ūvīs et glaciālis Hiems cānōs hirsūta capillōs","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calculus","latin":"calculus, calculi","headword":"calculus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"pebble; (bladder) stone; piece for reckoning/voting/game; calculation","forms":["calculōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum vēro ōlim Arethūsa, postquam diū per silvāsas cucurrerat, domum sōia redīret, ad rapidum fluvium pervēnit, cuius frīgidae aquae, nūllō modō turbidae ac percussae radiīs sōlis, quī in mediō caelō sine nūbibus fulgēbat, ita illūstrābantur ut nympha ipsōs {{calculōs}} in īmō flūmine iacentēs cemere posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calda","latin":"calda, caldae","headword":"calda","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hot water; warm water","forms":["calda"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tamen {{calda}} pôtiô vestiārius est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caldicerebrius","latin":"caldicerebrius, caldicerebria, caldicerebrium","headword":"caldicerebrius","letter":"c","pos":"adjective","posGroup":"adjective","english":"hot-headed","forms":["caldicerebrius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et Titus noster magnum animum habet et est {{caldicerebrius}}: aut hoc aut illud, erit quid utique.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caldum","latin":"caldum, caldi","headword":"caldum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"drink of wine and hot water (w/spices); (usu. Roman winter drink); heat","forms":["caldum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sequēns ferculum fuit scriblîta frîgida, et suprā mel {{caldum}} înñsum excellente Hispānum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caldus","latin":"caldus, calda -um, caldior -or -us, caldissimus -a -um","headword":"caldus","letter":"c","pos":"adjective","posGroup":"adjective","english":"warm, hot; fiery, lusty; eager, rash, on the spot; having a warm climate/place","forms":["caldam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ille autem iam ēbrius uxôris suae umerîs imposuerat manūs, onerätusque aliquot corônîs, et unguentô per frontem in oculôs ﬂuente, praetôriô locô sē posuit, continuôque vînum et {{caldam}} poposcit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"calefacio","latin":"calefacio, calefacere, calefeci, calefactus","headword":"calefacio","letter":"c","pos":"verb","posGroup":"verb","english":"make warm/hot (exert/ferment); heat; excite/rouse; vex/trouble; pursue eagerly","forms":["calefacere"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Prīmum hominēs, rē novā perterritī, fugere volēbant; Promētheus vērō eōs retinuit atque mōnstrāvit quam ūtile illud mūnus eīs esset: “Igne corpora vestra nūda et frīgentia {{calefacere}} poteritis; ferōcissimae quoque bēstiae ab igne fugient, neque in vōs impetum facere audēbunt; praetereā igne vōbīs etiam ferrum mollīre et arma cōnficere licēbit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caleo","latin":"caleo, calere, calui, -","headword":"caleo","letter":"c","pos":"verb","posGroup":"verb","english":"be/feel/be kept warm; be hot with passion/inflamed/active/driven hotly/urged","forms":["calent","calet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"adiuvat et flammae, quà {{calet}} ipse, favet. —","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"calfacio","latin":"calfacio, calfacere, calfeci, calfactus","headword":"calfacio","letter":"c","pos":"verb","posGroup":"verb","english":"make warm/hot (exert/ferment); heat; excite/rouse; vex/trouble; pursue eagerly","forms":["calfacienda","calfactī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"algentī manus est {{calfacienda}} sinū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"calida","latin":"calida, calidae","headword":"calida","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hot water; warm water","forms":["calida"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Forte ex nīdō hirundinum stercora {{calida}} incidērunt in oculōs dormientīs, unde caecus factus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"calidum","latin":"calidum, calidi","headword":"calidum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"drink of wine and hot water (w/spices); (usu. Roman winter drink); heat","forms":["calidum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prō domō antrum aestāte frīgidum, hieme vērō {{calidum}} habeō.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calidus","latin":"calidus, -a, -um","headword":"calidus","letter":"c","pos":"adjective","posGroup":"adjective","english":"warm, hot, f. hot water; hot; hot, warm","forms":["calidae","calidam","calidārum","calidī","calidior","calidīs","calidissimī","calidissimus","calidō","calidus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aemilius: “Cum sōl lūcet, nimis {{calidus}} est āēr in hortō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"caliga","latin":"caliga, caligae","headword":"caliga","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"soldier's boot; boot; military service","forms":["caligās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Poposcī calceāmenta et {{caligās}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"caligo","latin":"caligo, caliginis","headword":"caligo","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"mist/fog; darkness/gloom/murkiness; moral/intellectual/mental dark; dizziness","forms":["cālīgō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ibi cālīgō nebulīs miscētur, nec ūllus sonus silentia rumpit: omnia, mūta, quiēscunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caligula","latin":"Caligula, Caligulae","headword":"Caligula","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Caligula (Gaius Claudius Caesar Germanicus, 37-41 AD); little soldier('s boot)","forms":["Caligula"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posteā Rōmānī nōbilissimī in Palātiō habitāvērunt, ibīque post Iūliī Caesaris aetātem Augustus, Tiberius, {{Caligula}} aliīque prīncipēs Rōmānī domōs magnificās sibi aedificāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"calix","latin":"calix, -icis","headword":"calix","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"drinking cup","forms":["calicem","calix"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et accipiēns {{calicem}}, grātiās ēgit, et dedit illīs, dīcēns:\"Bibitē ex hōc omnēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"callide","latin":"callide, callidius, callidissime","headword":"callide","letter":"c","pos":"adverb","posGroup":"adverb","english":"expertly, skillfully, cleverly; well, thoroughly; cunningly, artfully","forms":["callidē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At contrā paucī, quibus bonum et aequum dīvitiīs cārius erat, subveniendum Adherbalī et Hiempsalis mortem sevērē vindicandam cēnsēbant; sed ex omnibus maximē Aemilius Scaurus, homō nōbilis, impiger, factiōsus, avidus potentiae, honōris, dīvitiārum, cēterum vitia sua callidē occultāns.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"callidus","latin":"callidus, -a, -um","headword":"callidus","letter":"c","pos":"adjective","posGroup":"adjective","english":"clever, cunning","forms":["callidissimō","callidissimum","callidissimus","callidum","callidus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Serpēns, quī erat {{callidissimum}} omnium animantium, dīxit mulierī: cūr nōn comedis frūctum istīus arboris?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"callis","latin":"callis, -is ( f.)","headword":"callis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"track, path; mountain path","forms":["callēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Antiochum timor incessit nē quās per imminentia iuga {{callēs}} invenīret ad trānsitum Rōmānus; nam Lacedaemoniōs quondam ita ā Persīs circuitōs fāma erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"callisto","latin":"Callistō, -ūs","headword":"Callistō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Callisto (a nymph)","forms":["Callistō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Callistō optima omnium fēminārum in Arcadiā habitantium fuit, Arcasque, eius fīlius, pulcherrimus omnium puerōrum esse vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calo","latin":"calo, calonis","headword":"calo","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"camp/soldier's servant; type of awkwardness/stupidity; low servant/drudge (L+S)","forms":["cālōnibus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Mānlium in dextrā, Faesulānum quendam in sinistrā parte cūrāre iubet; ipse cum lībertīs et {{cālōnibus}} propter aquilam adsistit, quam bellō Cimbricō C.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"calor","latin":"calor, calōris","headword":"calor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) heat","forms":["calor","calōre","calōrem","calōribus","calōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum igitur sōl in caelō altissimus esset et Iō {{calōrem}} vix paterētur, dē caelō ad fluvium Iuppiter dēscendit et puellae appāruit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"calumnia","latin":"calumnia, calumniae","headword":"calumnia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"sophistry, sham; false accusation/claim/statement/pretenses/objection; quibble","forms":["calumniā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Metellus Crēticus in Āpūliam circumque ea loca missī (hī utrīque ad urbem imperātōrēs erant, impedītī nē triumphārent calumniā paucōrum quibus omnia honesta atque inhonesta vēndere mōs erat), sed praetōrēs Q.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"calumnior","latin":"calumnior, calumniari, calumniatus sum","headword":"calumnior","letter":"c","pos":"verb","posGroup":"verb","english":"accuse falsely; misrepresent, interpret wrongly; depreciate, find fault with","forms":["calumniantibus","Calumniārī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vidēns Jēsus turbās, ascendit in montem et docēbat eās:\"Audīstis dictum esse ab antīquīs: ' dīligēs proximum tuum, et odiō habēbis inimīcum tuum. ' Ego autem dīcō vōbīs: dīligite inimīcōs vestrōs, et benefacite hīs quī ōdērunt vōs, et ōrātē prō persequentibus et {{calumniantibus}} vōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"calvaria","latin":"calvaria, calvariae","headword":"calvaria","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"skull","forms":["Calvāria"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et postquam vēnērunt in locum quī vocātur ' {{Calvāria}}', crucifīxērunt eum, et latrōnēs duōs, alterum ā dextrīs et alterum ā sinistrīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"calvus","latin":"calvus, calva -um, calvior -or -us, calvissimus -a -um","headword":"calvus","letter":"c","pos":"adjective","posGroup":"adjective","english":"bald, bald-headed; having head shaved; smooth (nuts); bare/stripped (things)","forms":["calvae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Circā cicer et lupînum, {{calvae}} arbitrātū, et mäla singula nam sî aliquid mūneris meô vemulae nôn tulerô, habëbô “Bene mē admonet dominā meā: in prôspectü habū- īmus ursînae frustum, dē quô cum imprūdēns Scintilla gustāsset, paene intestîna suā Vomuit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"calydon","latin":"Calydōn, -ōnis","headword":"Calydōn","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Calydon, a city in Greece","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"camelus","latin":"camelus, cameli","headword":"camelus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"camel, dromedary","forms":["camēlīs","camēlō","camēlōrum","camēlōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Eliezer sūmpsit decem {{camēlōs}} dominī suī, et profectus est, portāns sēcum mūnera magnifica, quibus dōnāret puellam dēstinātam Isaacō et eius parentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"camera","latin":"camera, -ae","headword":"camera","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"chamber, room","forms":["camera","camerae","cameram"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tot sunt {{camerae}}, tot sunt viae ut Daedalus ipse vix ad līmen revertere possit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"camillus","latin":"camillus, camilli","headword":"camillus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"boy/noble youth attendant of a flamen/priest","forms":["Camillō","Camillus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dictātor contrā ipsōs missus est Furius {{Camillus}}, quī prīmum eōs vīcit aciē, mox etiam cīvitātem diū obsidēns cēpit, antīquissimam Italiae atque dītissimam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"campana","latin":"campana, campanae","headword":"campana","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"bell","forms":["Campāna","Campānīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Posterō diē senātus frequēns datus Hannibalī; ubi prīma eius ōrātiō perblanda ac benigna fuit, quā grātiās ēgit {{Campānīs}} 'quod amīcitiam suam Rōmānae societātī praeposuissent', et inter cētera magnifica prōmissa pollicitus est 'brevī caput Ītaliae omnis Capuam fore!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"campania","latin":"Campania, Campaniae","headword":"Campania","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Campania; (province of Italy south of Latinium noted for its fertility)","forms":["Campāniā","Campāniae","Campāniam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nē in Campāniā quidem plūrēs vīllae sunt, quamquam multī Rōmānī in ōra maritima eius regiōnis vīllās possident; nam plūrimī Rōmānī sub urbe Rōmā habitāre volunt in villīs suburbānīs.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"campanus","latin":"campanus, campana, campanum","headword":"campanus","letter":"c","pos":"adjective","posGroup":"adjective","english":"flat; level","forms":["Campānōrum","Campānum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Māgōnem regiōnis eius urbēs dēficientēs ab Rōmānīs accipere iubet, ipse per agrum {{Campānum}} mare Īnferum petit, oppugnātūrus Neāpolim, ut urbem maritimam habēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"campestris","latin":"campestris, campestris, campestre","headword":"campestris","letter":"c","pos":"adjective","posGroup":"adjective","english":"level, even, flat, of level field; on open plain/field; plain-dwelling","forms":["campestres","campestribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hoc intermisso spatio duas fossas quindecim pedes latas eadem altitudine perduxit, quarum interiorem {{campestribus}} ac demissis locis aqua ex flumine derivata complevit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"campidoctor","latin":"campidoctor, campidoctoris","headword":"campidoctor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"one who exercises/drills soldiers in Campus Martius; drill sergeant","forms":["campidoctōrēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At ille sīmius māior ait illī quī fallāx erat: “Quid sum ego?” Fallāx dīxit: “Tū es Imperātor!” Iterum interrogāvit: “Et istī quōs ante mē stāre vidēs, quid sunt?” Īdem fallāx respondit: “Hī comitēs sunt tuī, prīmicēriī, {{campidoctōrēs}}, et cēterī officiālēs.” Et prō hōc sīmius, quī mendāciter laudātus est cum turbā suā, ōsculātus est hominem fallācem et mūnera illī dedit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"campus","latin":"campus, -ī","headword":"campus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"plain; field, plain; field; plain, field; Campus Mārtius","forms":["campī","campīs","campō","campōs","campum","campus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat ex oppido Alesia despectus in {{campum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cancer","latin":"cancer, cancri","headword":"cancer","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"crab; Cancer (zodiac); the_South; summer heat; cancer, disease, tumor, canker","forms":["cancer"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nisi cavēris, Taurus īrātus cōmibus tē petet; via est perīculōrum plēna: hinc enim habēbis Sagittārium, quī arcū suō ēmittit sagittās, illinc saevī Leōnis os, apertum et ad tē mordendum parātum; bracchia sua ad tē apprehendendum Scorpiō ad dextram et {{Cancer}} ad sinistram extendent; neque facile erit tunc equōs timentēs metūque affectōs regere: vix mihi pārent, vix mē patiuntur!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"candelabrum","latin":"candēlābrum, -ī","headword":"candēlābrum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"candelabrum","forms":["candēlābrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In templō Pācis servantur rēs sacrae quās Titus Iūdaeīs victīs adēmit, in iīs {{candēlābrum}} aureum et mēnsa aurāta quae in templō Hierosolymōrum stābat tubaeque argenteae quibus Iūdaeī convocābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"candens","latin":"candens, candentis (gen.), candentior -or -us, candentissimus -a -um","headword":"candens","letter":"c","pos":"adjective","posGroup":"adjective","english":"shining/bright/clear (light); (approaching) white; boiling/red-hot, glowing","forms":["candentis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{candentis}} vaccae media inter cornua fundit,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"candida","latin":"candida, candidae","headword":"candida","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"games/play presented by a candidate for office","forms":["candidā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Tūne ante aciem Ilidaēōrum vīsus est eques veste candidā, armīs aureīs indūtus, hastam vibrāns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"candidum","latin":"candidum, candidi","headword":"candidum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"white (of an egg)","forms":["candidum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Stupuit Narcissus cum, humī iacēns, spectāvisset illōs oculōs, quae quasi lūcentia sīdera, ex aquā eum intuērī vidēbantur, et capillōs dignōs Bacchō, dignōs Apolline, pulcherrimāsque genās et {{candidum}} collum decusque","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"candidus","latin":"candidus, -a, -um","headword":"candidus","letter":"c","pos":"adjective","posGroup":"adjective","english":"white, bright","forms":["candidae","candidam","candidior","candidīs","candidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ut vērō amōris dolōrem, quō animus eius afficiēbātur, levāret, nōnnumquam in celsum saxum ascendēbat, unde, mare prōspiciēns, tībiīs ūsus hōc modō canēbat: “Ō fōrmōsa Galatēa, cāseō {{candidior}}, agnō suāvior, ūva mātūra dulcior, cūr mē amantem contemnis, sī dīligenter tē cūrō?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"candor","latin":"candor, -ōris (m.)","headword":"candor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"whiteness, brightness; brightness, whiteness","forms":["candōre","candōrem","candōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ōrīs et in niveō mixtum {{candōre}} rubōrem,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"canens","latin":"canens, (gen.), canentis","headword":"canens","letter":"c","pos":"adjective","posGroup":"adjective","english":"gray, grayish; white, hoary","forms":["canēns","canente","canentem","canentēs","canentīs","canentium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cotīdiē enim, gallō {{canente}}, ē lectīs surgēbant, mala ēdēbant et lac bibēbant, ac posteā ē casā in silvās et collēs currēbant, ubi parvās ovēs īnsequentēs vel flōrēs carpentēs lūdere per multās hōrās poterant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caneo","latin":"caneo, canere, canui, -","headword":"caneo","letter":"c","pos":"verb","posGroup":"verb","english":"be/become covered in white; be hoary, be white/gray (with age)","forms":["canendī","canendīs","canendō","canendum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Subitō autem novem pulcherrimās puellās vīdit, quās statim intellēxit novem Mūsās esse, deās artium canendī, scrībendī, saltandī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"canes","latin":"canes, canis","headword":"canes","letter":"c","pos":"noun","posGroup":"noun","english":"dog; hound; subordinate; \"jackal\"; dog-star/fish; lowest dice throw; clamp","forms":["canēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum autem ōlim dea summum Olympum currū suō petīvisset atque Adōnem sōlum in silvā relīquisset, puer, quī aprī vestīgia in terrā cōnspexerat, Veneris verba oblītus, {{canēs}} suōs hortātus est, ut ferōcem illam bēstiam quam celerrimē sequerentur: erat enim cupidissimus illīus ferae capiendae.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"canicula","latin":"canicula, caniculae","headword":"canicula","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"bitch (also people); dog-star; dog-fish, shark; dog-days; lowest throw at dice","forms":["Canīcula"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Canīcula}} -ae f, sīdus calōrem afferēns","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"canis","latin":"canis, canis","headword":"canis","letter":"c","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) dog","forms":["cane","canem","cani","canibus","canis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui {{cani}} iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono tubae, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"canistrum","latin":"canistrum, canistri","headword":"canistrum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"wicker basket (used for food/flowers and in sacrifices)","forms":["canistra","canistrīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alter quoque nārrāvit somnium suum Iōsēphō: gestābam in capite tria {{canistra}} in quibus erant cibī quōs pistōrēs solent cōnficere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"canit","latin":"canit, canere","headword":"canit","letter":"c","pos":"verb","posGroup":"verb","english":"sing (of), crow, play; sings; sings, crows; sings, plays (music)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"canities","latin":"canities, canitiei","headword":"canities","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"white/gray coloring/deposit; gray/white hair, grayness of hair; old age","forms":["cānitiem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Fémina {{cānitiem}} Germānīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"canna","latin":"canna, cannae","headword":"canna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"small reed/cane; panpipe/flute; small vessel/gondola; windpipe; cane-sugar","forms":["canna","Cannae","Cannās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ut levis in madidā {{canna}} palūde tremit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cano","latin":"cano, canere, cecini, cantus","headword":"cano","letter":"c","pos":"verb","posGroup":"verb","english":"sing, celebrate, chant; crow; recite; play (music)/sound (horn); foretell","forms":["cānam","canat","canēbant","canēbat","canere","canerem","Canimus","canit","canitis","canō","canunt","cecinisse","cecinit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlia laeta {{canit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"canor","latin":"canor, canoris","headword":"canor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"song, vocal music; tune, melody; birdsong; music of instruments; poetic strain","forms":["canor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Rēs est blanda {{canor}}: discant","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cantabundus","latin":"cantabundus, cantabunda, cantabundum","headword":"cantabundus","letter":"c","pos":"adjective","posGroup":"adjective","english":"singing; chanting","forms":["cantābundus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sedeô ego {{cantābundus}} et stēlās numerô.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cantare","latin":"cantāre","headword":"cantāre","letter":"c","pos":"verb","posGroup":"verb","english":"to sing, make music","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"cantat","latin":"cantat","headword":"cantat","letter":"c","pos":"verb","posGroup":"verb","english":"sing; sings","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"canticum","latin":"canticum, cantici","headword":"canticum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"song; passage in a comedy chanted or sung; sing-song voice","forms":["canticum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Menecratēs -1s m, ﬁchcen üsque ad cameram ôs ëbnum et coeplt Menecrāns cantlca ({{canticum}}ﬂacerärerfoedë lacerāre (sîcut 1llî d1cēbant qū1 lmguam elus mtellege- gingilighô [7] “Gin-gī-lī-phô!” ingentî clämôre exsonābant.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"canto","latin":"canto, cantare, cantavi, cantatus","headword":"canto","letter":"c","pos":"verb","posGroup":"verb","english":"sing; play (roles/music); recite; praise, celebrate; forewarn; enchant, bewitch","forms":["cantā","cantābant","cantābat","cantābit","cantandum","cantāns","cantante","cantāre","cantat","cantāvit","cantent","cantētur","cantō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ancilla {{cantat}}: “Lalla.” Quae est ancilla quae cantat?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"cantus","latin":"cantus, -ūs","headword":"cantus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) song","forms":["cantibus","cantū","cantum","cantus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Orpheus nōbilissimus fidicen atque poēta ēgregius fuit, quī inde ā puerō tam pulchrē canēbat, ut nōn sōlum bēstiae ferae ad eum accurrerent, vērum etiam rapida flūmina cōnsisterent, nē strepitū {{cantum}} eius turbārent, ac saxa ipsa arborēsque (mīrābile vīsū!) ad audiendum venīrent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"canum","latin":"canum, cani","headword":"canum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"wicker basket (used for food/flowers and in sacrifices)","forms":["canum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Silva tum excēpit ferum, in quā retentīs impedītus cornibus lacerārī coepit morsibus saevīs {{canum}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"canus","latin":"canus, cana, canum","headword":"canus","letter":"c","pos":"adjective","posGroup":"adjective","english":"white, gray; aged, old, wise; hoary; foamy, white-capped; white w/snow/frost","forms":["Cānā","cānōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Nūptiae factae sunt in Cānā Galilaeae: et erat māter Iēsu ibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"capax","latin":"capax, capacis (gen.), capacior -or -us, capacissimus -a -um","headword":"capax","letter":"c","pos":"adjective","posGroup":"adjective","english":"large, spacious, roomy, big; capable, fit, competent; has right to inherit","forms":["capācibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Tum aquam ex fonte {{capācibus}} urrīīs haustam in deae corpus effundunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"capella","latin":"capella, capellae","headword":"capella","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"she-goat; meteor type; star in constellation Auriga (rising in rainy season)","forms":["capellā","capellae","capellās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mercurius statim ālās, petasum, virgam sūmpsit; at cum prīmum in terram venit, vestēs pāstōris induit et aliquot {{capellās}} virgā per agrōs ēgit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caper","latin":"caper, capri","headword":"caper","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"he-goat, billy-goat; goatish/armpit smell; star in Auriga (L+S); grunting fish","forms":["caper","caprī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Postquam diū Pēgasus volāvit, tandem Bellerophōn, quī eius dorsō īnsīdēbat, ex altō āere dēspiciēns, Chimaeram, mōnstrum horrendum (cui duo erant capita, quōrum alterum leōnis, alterum vērō caprī; cauda autem dracōnis), cōnspexit, quod crūdēlissimum vidēbātur esse flammāsque ex ōre exspīrābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"capere","latin":"capere","headword":"capere","letter":"c","pos":"verb","posGroup":"verb","english":"to capture, take","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"capesso","latin":"capesso, capessere, capessivi, capessitus","headword":"capesso","letter":"c","pos":"verb","posGroup":"verb","english":"grasp, take, seize eagerly; undertake, manage; pursue w/zeal; carry out orders","forms":["capessere","capessite"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nunc pergam erī imperium exsequī et mē domum {{capessere}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"capetum","latin":"capetum, capeti","headword":"capetum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"fodder for cattle","forms":["Capetō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Latīnō Alba ortus est, Albā Atys, Atye Capys, Capye Capetus, Capetō Tiberīnus, quī in Albulā amne submersus celebre nōmen flūminī dedit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"capillatus","latin":"capillatus, capillata, capillatum","headword":"capillatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"having long hair (older generation/foreign peoples/boys); hairy; hair-like","forms":["capillātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Erat autem vë- nälicium cum titulîs pictum, et ipse Trimalchiô {{capillātus}} cādūceum tenēbat Minerväque dūcente Rômam intrābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"capillus","latin":"capillus, -ī","headword":"capillus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"hair","forms":["capillī","capillīs","capillō","capillōrum","capillōs","capillum","capillus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quorum cum magna multitudo convenisset, matres familiae, quae paulo ante Romanis de muro manus tendebant, suos obtestari et more Gallico passum {{capillum}} ostentare liberosque in conspectum proferre coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"capio","latin":"capio, capere, cepi, captus","headword":"capio","letter":"c","pos":"verb","posGroup":"verb","english":"take hold, seize; grasp; take bribe; arrest/capture; put on; occupy; captivate","forms":["cape","capere","caperent","caperentur","caperet","caperētur","caperis","capī","capiam","capiāmus","capiant","capiās","capiat","capiēbant","capiēbantur","capiēbat","capienda","capiendae","capiendam","capiendī","capiendis","capiendo","capiendōs","capiendum","capiēns","capientēs","capiēs","capimur","capiō","capior","capit","capitur","capiunda","capiundae","capiunt","capiuntur","ceperant","ceperat","cēperint","cēperīs","cēperō","ceperunt","cēpī","cēpimus","cēpisse","cēpissent","cēpisset","cēpit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma {{capiant}}, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"capis","latin":"capis, capidis","headword":"capis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cup/bowl with handle used mainly for ritual purposes","forms":["capidem","capis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"quam {{capis}}: es paulō quam potes esse minus!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"capit","latin":"capit, capere","headword":"capit","letter":"c","pos":"verb","posGroup":"verb","english":"take, catch, capture; catches, takes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"capitalis","latin":"capitalis, capitale, capitalior -or -us, capitalissimus -a -um","headword":"capitalis","letter":"c","pos":"adjective","posGroup":"adjective","english":"of/belonging to head/life; deadly, mortal; dangerous; excellent, first-rate","forms":["capitālium"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haec ubi Rōmae comperta sunt, senātus Catilīnam et Mānlium hostēs iūdicat, cēterae multitūdinī diem statuit ante quam licēret sine fraude ab armīs discēdere praeter rērum {{capitālium}} condemnātīs.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"capito","latin":"capito, (gen.), capitonis","headword":"capito","letter":"c","pos":"adjective","posGroup":"adjective","english":"big-headed, having a large head (masculine adj.); (cognommen); kind of mullet","forms":["Capitō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Gabīnius Capitō, C.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"capitolinus","latin":"Capitolinus, Capitolina, Capitolinum","headword":"Capitolinus","letter":"c","pos":"adjective","posGroup":"adjective","english":"Capitoline; (one of 7 hills of Rome); of the Capitol","forms":["Capitōlīnī","Capitōlīnō","Capitōlīnum","Capitōlīnus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ā colle Quirīnālī et ā monte Capitōlīnō usque ad Tiberim flūmen campus Mārtius patet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"capitolium","latin":"Capitolium, Capitolii","headword":"Capitolium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"Capitol; Capitoline Hill in Rome","forms":["Capitōlia","Capitōliī","Capitōliō","Capitōlium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In mediā urbe inter collēs {{Capitōlium}} et Palātium est forum Rōmānum, quō hominēs ex tōtā Italiā atque ex omnibus prōvinciīs Rōmānīs conveniunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"capitulum","latin":"capitulum, -ī","headword":"capitulum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"chapter","forms":["capitula","capitulī","capitulīs","capitulō","capitulum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In capitulō prīmō mīlle vocābula sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"capra","latin":"capra, -ae","headword":"capra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"goat","forms":["capra","caprae","caprārum","caprās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sīc Davidem allocūtus est prophēta Nāthan: “Erant in eādem urbe duo hominēs: alter dīves multōs boum, {{caprārum}} atque ovium gregēs alēbat; alter vērō nihil habēbat praeter ovem ūnam, quam ipse ēmerat, et apud sē dīligenter nūtriēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"capsa","latin":"capsa, capsae","headword":"capsa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cylindrical case (for books), bookcase; receptacle for things, box, satchel","forms":["capsā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Erat inter ingentēs sōlitūdinēs oppidum magnum atque valēns nōmine {{Capsa}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"capsella","latin":"capsella, capsellae","headword":"capsella","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"small box/casket; coffer","forms":["capsellam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec melior Scintilla, quae dē cervîce suā {{capsellam}} dē- trāxit aureolam, quam ‘Fëlîciônem’ ap- pellābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"capso","latin":"capso, capsere, -, -","headword":"capso","letter":"c","pos":"verb","posGroup":"verb","english":"seize (only PRES form which is FUT); take bribe; capture; occupy; captivate","forms":["Capsam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed ubi diēs coepit et Numidae nihil hostīle metuentēs multī oppidō ēgressī, repente omnem equitātum et cum iīs vēlōcissimōs peditēs cursu tendere ad {{Capsam}} et portās obsidēre iubet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"captiva","latin":"captiva, captivae","headword":"captiva","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"prisoner (female), captive","forms":["captīva"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"At sī quōs tamen ultima nostrī verba movent ōris (Prīamī vōs fīlia rēgis, nōn {{captīva}} rogat), genetricī corpus inemptum reddite, nēve aurō redimat iūs triste sepulcrī, sed lacrimīs! tunc, cum poterat, redimēbat et aurō.” Dīxerat, at populus lacrimās, quās illa tenēbat, nōn tenet; ipse etiam flēns invītusque sacerdōs virginis ferrum in pectore condit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"captivitas","latin":"captivitas, captivitatis","headword":"captivitas","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"captivity/bondage; capture/act of being captured; blindness; captives (Plater)","forms":["Captīvitās","captīvitātem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum in {{captīvitātem}} abductus esset, eandem in Deum pietātem semper retinuit: omnia bona, quae habēre poterat, cotīdiē exsiliī suī comitibus impertiēbat, eōsque monitīs salūtāribus ad colendum Deum hortābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"captivus","latin":"captīvus, -ī","headword":"captīvus","letter":"c","pos":"adjective","posGroup":"adjective","english":"prisoner of war","forms":["captīvās","captīvī","captivis","captīvōrum","captīvōs","captīvus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum iam muro turres appropinquassent, ex {{captivis}} Caesar cognovit Vercingetorigem consumpto pabulo castra movisse propius Avaricum atque ipsum cum equitatu expeditisque qui inter equites proeliari consuessent insidiarum causa eo profectum quo nostros postero die pabulatum venturos arbitraretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"capto","latin":"capto, captare, captavi, captatus","headword":"capto","letter":"c","pos":"verb","posGroup":"verb","english":"try/long/aim for, desire; entice; hunt legacy; try to catch/grasp/seize/reach","forms":["captā","captanda","captandae","captantēs","captāre","captārem","captās","captent","captō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tandem, ūnō librō captō, recēdit, ac vix vīvus intrā forēs lābitur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"captum","latin":"captum, capti","headword":"captum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"catch; (e.g. fish)","forms":["captum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Māne, sōle oriente, Comātās parvum haedum {{captum}} ē grege in templō super āram Mūsīs sacrificat eāsque ōrat ut illud sacrificium accipiant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"captus","latin":"captus, capta, captum","headword":"captus","letter":"c","pos":"adjective","posGroup":"adjective","english":"captured, captive","forms":["captae","captam","captārum","capti","captis","captōs","captus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec faciunt reciperandorum suorum causa; sed contaminati facinore et {{capti}} compendio ex direptis bonis, quod ea res ad multos pertinebat, timore poenae exterriti consilia clam de bello inire incipiunt civitatesque reliquas legationibus sollicitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"capua","latin":"Capua, Capuae","headword":"Capua","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Capua; chief city of Campania","forms":["Capua","Capuae","Capuam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Via Appia est inter Rōmam et Brundisium; via Latīna inter Rōmam et {{Capuam}}; via Flāminia inter Rōmam et Arīminum; via Aurēlia inter Rōmam et Genuam; via Aemilia inter Arīminum et Placentiam.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"caput","latin":"caput, capitis","headword":"caput","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) head; life","forms":["capita","capite","capitī","capitibus","capitis","caput"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui {{capitis}} periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"carbasum","latin":"carbasum, carbasi","headword":"carbasum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"plant with narcotic juice","forms":["carbasa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"337 Sed nōn cui dederās à lītore {{carbasa}} ventō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"carbasus","latin":"carbasus, carbasi","headword":"carbasus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"linen (cloth); fine linen, cambric; canvas; sail; linen garment/clothes; awning","forms":["carbasus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"undique convēnēre; vocat iam {{carbasus}} aurās,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"carbo","latin":"carbo, carbonis","headword":"carbo","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"charcoal; glowing coal; pencil/marker; worthless thing; charred remains; coal","forms":["carbō","Carbōne","carbōnēs","carbōnis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"carbō ib pulvis littera — {{carbō}}nis pulvere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"carcer","latin":"carcer, carceris","headword":"carcer","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) prison; prison, enclosure","forms":["Carcer","carcere","carcerem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mulier īrāta inclāmāvit servōs, et Iōsēphum accūsāvit apud virum, quī, nimium crēdulus, coniēcit Iōsēphum in {{carcerem}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cardo","latin":"cardō, cardinis","headword":"cardō","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) hinge","forms":["cardine","cardinēs","cardinibus","cardō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Foris duōs {{cardinēs}} habet, in quibus vertī potest; cum foris in cardinibus vertitur, iānua aperītur aut clauditur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"carduus","latin":"carduus, cardui","headword":"carduus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"thistle; prickly bur/seed-vessel; cardoon (artichoke-like vegetable)","forms":["carduōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde Deus dīxit Adamō: quia gessistī mōrem uxōrī tuae, habēbis terram īnfēstam; ea fundet tibi spīnās et {{carduōs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"care","latin":"care, carius, carissime","headword":"care","letter":"c","pos":"adverb","posGroup":"adverb","english":"dear, at high price; of high value; at great cost/sacrifice","forms":["cārē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"\"[cārē!\" clāmat, *ubī es? quōque sub axe volās?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"careo","latin":"careō, carēre","headword":"careō","letter":"c","pos":"verb","posGroup":"verb","english":"(+abl.) lack; to lack, be without (+ abl.)","forms":["caream","careant","careat","careātis","carēbant","carēbat","carēbis","carentēs","carēre","cārerent","carēret","caret","caruerint","caruisse","caruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites {{caruerint}} et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"carere","latin":"carēre","headword":"carēre","letter":"c","pos":"verb","posGroup":"verb","english":"lack, be without (+ abl.)","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"carica","latin":"carica, caricae","headword":"carica","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"kind of fig; (Caria a country in south-west Asia Minor)","forms":["cāricās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Accipiō pānem candidum, olīvās, cāseum, {{cāricās}}, nucēs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"carina","latin":"carīna, -ae","headword":"carīna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"keel, ship; keel; poetically, ship; ship","forms":["carīna","carīnae","carīnās","carīnīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accipiunt ventōs ā tergō mīlle {{carīnae}} multaque perpessae Phrygiā potiuntur harēnā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"caris","latin":"caris, caridis","headword":"caris","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"kind of crustacean; shrimp/prawn?; sea-crab (L+S)","forms":["cāris"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"lapillus -ī m 7 parvus lapis: gemma VŌs quoque nec {{cāris}} aurēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"caritas","latin":"cāritās, -ātis ( f.)","headword":"cāritās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"high price, love, esteem; affection, loyalty","forms":["caritāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi eō ventum est, Turnum ex somnō excitātum circumsistunt custōdēs; comprehensīsque servīs, quī {{caritāte}} dominī vim parābant, cum gladiī abditī ex omnibus locīs aedium prōtraherentur, ēnimvērō manifēsta rēs vīsa est, iniectaeque Turnō catēnae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"carmen","latin":"carmen, carminis","headword":"carmen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) song, poem; song; song, chant, incantation, charm","forms":["carmen","carmina","carmine","carminibus","carminis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In altō monte, cum gregem cūstōdīret, ut inter pāstōrēs fierī solet, pulchra {{carmina}}, etsī rūstica, tībiīs canere incipiēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"carnifex","latin":"carnifex, carnificis","headword":"carnifex","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"executioner, hangman; murderer, butcher, torturer; scoundrel, villain","forms":["carnifex"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Etiam clāmās, {{carnifex}}?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"carnis","latin":"carnis, carnis","headword":"carnis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"meat/flesh; the_body; pulp/flesh of plants, sapwood; soft part; low passions","forms":["carnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc iussit angelus fel piscis sēpōnī, utpote medicāmentum salūtāre; deinde partem {{carnis}} coxērunt comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"carnutes","latin":"Carnutes, Carnutis","headword":"Carnutes","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Carnutes, tribe of central Gaul, around Loire - Caesar","forms":["Carnutes","Carnutibus","Carnutum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His rebus agitatis, profitentur {{Carnutes}} se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"caro","latin":"carō, carnis","headword":"carō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) meat; flesh, meat; meat, flesh","forms":["carne","carnem","carnēs","carnī","carō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et affīget ad pālum, ubi avēs pāscentur {{carne}} tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"carpentum","latin":"carpentum, -ī","headword":"carpentum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"two-wheeled carriage","forms":["carpentō","carpentum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi eī in carpentō sedentī cum uxōre aquilā repente dēlāpsa pilleum aufert, superque carpentum volitāns rūrsus, velut dīvīnitus missa, capitī aptē repōnit; inde sublīmis abit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"carpere","latin":"carpere","headword":"carpere","letter":"c","pos":"verb","posGroup":"verb","english":"to pick, pluck","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"carpit","latin":"carpit","headword":"carpit","letter":"c","pos":"verb","posGroup":"verb","english":"picks, plucks","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"carpit/carpunt","latin":"carpit/carpunt","headword":"carpit/carpunt","letter":"c","pos":"","posGroup":"other","english":"gather, pick, crop","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"carpo","latin":"carpo, carpere, carpsi, carptus","headword":"carpo","letter":"c","pos":"verb","posGroup":"verb","english":"seize/pick/pluck/gather/browse/tear off; graze/crop; tease/pull out/card (wool)","forms":["carpat","carpe","carpēbant","carpēbat","carpendō","carpēns","carpentem","carpentēs","carpere","carperet","carpis","carpit","Carpite","carpitur","carpserat","carpsisse","carpsit","carpta","carptam","carptās","carptum","carptus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quae, dum cum aliīs puellīs in campō lūdit, currit, pilam iacit flōrēsque carpendō dēlectātur, subitō magnum et album taurum vīdit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"carrus","latin":"carrus, carri","headword":"carrus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"wagon; (Gallic type)","forms":["carros"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito {{carros}} impedimentaque sua in artiores silvas abdiderunt, copias omnes in loco edito atque aperto instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"carthaginiensis","latin":"Carthaginiensis, Carthaginiensis","headword":"Carthaginiensis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Carthaginian, inhabitant of Carthage; (also of New Carthage in Spain?)","forms":["Carthāginiēnsem","Carthāginiēnsēs","Carthāginiēnsī","Carthāginiēnsibus","Carthāginiēnsis","Carthāginiēnsium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Duīlius commissō proeliō {{Carthāginiēnsium}} ducem vīcit, trīgintā et ūnam nāvēs cēpit, quattuordecim mersit, septem mīlia hostium cēpit, tria mīlia occīdit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"carthago","latin":"Carthāgō, -inis","headword":"Carthāgō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Carthage","forms":["Carthāgine","Carthāginem","Carthāginis","Carthāgō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Carthāgō est in Āfricā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"carus","latin":"cārus, -a, -um","headword":"cārus","letter":"c","pos":"adjective","posGroup":"adjective","english":"dear; expensive; dear, beloved","forms":["cārā","cārae","cārī","cārior","cāriōra","cariorem","cāriōrēs","cārissima","cārissimae","cārissime","cārissimum","cārissimus","cārius","cārum","cārus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat {{cariorem}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"casa","latin":"casa, -ae","headword":"casa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cottage, hut; house, cottage","forms":["casā","casae","casam","casīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Īnō autem, cum prīmum in rēgiam īvit, neque puerum nōmine Phrixum neque puellam nōmine Hellēn amāvit eōsque ex rēgiā ad parvam {{casam}} quae in silvā sita erat, mīsit, ubi tamen Phrixus et Hellē laetī habitābant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caseum","latin":"caseum, casei","headword":"caseum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cheese; pressed curd; comic term of endearment (L+S)","forms":["cāseum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ibi in vāsīs prīmum holera et olīvās et {{cāseum}} et pānem, deinde prūna et nucēs et mala et ūvās et pōculum lactis plēnum hospitibus obtulērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"caseus","latin":"caseus, casei","headword":"caseus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cheese; pressed curd; comic term of endearment (L+S)","forms":["cāseī","cāseō","Cāseus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ut vērō amōris dolōrem, quō animus eius afficiēbātur, levāret, nōnnumquam in celsum saxum ascendēbat, unde, mare prōspiciēns, tībiīs ūsus hōc modō canēbat: “Ō fōrmōsa Galatēa, cāseō candidior, agnō suāvior, ūva mātūra dulcior, cūr mē amantem contemnis, sī dīligenter tē cūrō?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cassandra","latin":"Cassandra, Cassandrae","headword":"Cassandra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Cassandra; (Trojan prophetess, daughter of Priam, cursed by Apollo)","forms":["Cassandra"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[{{Cassandra}}] tracta atque comīs antistita Phoebī nōn prōfectūrās tendēbat ad aethera palmās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cassis","latin":"cassis, -idis","headword":"cassis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"helmet","forms":["cassidibus","cassis","Cassium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci deque his stramenta detrahi mulionesque cum {{cassidibus}} equitum specie ac simulatione collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cassius","latin":"Cassius, Cassi","headword":"Cassius","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cassius; (Roman gens name); (L. ~ Longinus defeated by Helvetii; Caesar killer)","forms":["Cassiō","Cassius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cassiō aliīsque senātōribus necātus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"castanea","latin":"castanea, castaneae","headword":"castanea","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"chestnut-tree, chestnut","forms":["castanea"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{castanea}} -ae f &g","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"castella","latin":"castella, castellae","headword":"castella","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Castile (Spain); (place of castles/castella)","forms":["castella"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Castra opportunis locis erant posita, ibique {{castella}} XXIII facta, quibus in castellis interdiu stationes ponebantur, ne qua subito: eruptio fieret; haec eadem noctu excubitoribus ac firmis praesidiis tenebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"castellum","latin":"castellum, -ī","headword":"castellum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"fort, stronghold","forms":["castellis","castello","castellum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castra opportunis locis erant posita, ibique castella XXIII facta, quibus in {{castellis}} interdiu stationes ponebantur, ne qua subito: eruptio fieret; haec eadem noctu excubitoribus ac firmis praesidiis tenebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"castigare","latin":"(castīgō) castīgāre","headword":"castīgāre","letter":"c","pos":"","posGroup":"other","english":"correct, reprove","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"castigator","latin":"castīgātor, -ōris (m.)","headword":"castīgātor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"one who reproves, corrects","forms":["castīgātor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Movet cum patris maestitia, tum Brūtus {{castīgātor}} lacrimārum atque inertium querēlārum auctorque 'quod virōs, quod Rōmānōs deceret!' arma capiendī 'adversus hostīlia ausōs!' Ferōcissimus quisque iuvenum cum armīs voluntārius adest; sequitur et cētera iuventūs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"castitas","latin":"castitās, -ātis ( f.)","headword":"castitās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"chastity; chastity, purity","forms":["castitās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tarquinium mala libīdō Lūcrētiae per vim stuprandae capit; cum fōrmā tum spectāta {{castitās}} incitat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"castor","latin":"Castor, Castoris","headword":"Castor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Castor; (twin to Pollux, brother to Helen); St Elmo's fire (pl.), corposant","forms":["Castor","Castore","Castorem","Castorī","Castoris"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Leucippī rēgis) à {{Castore}} et Pollūce","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"castra","latin":"castra, -ōrum","headword":"castra","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n. pl.) camp","forms":["castra","castris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quorum ille precibus permotus {{castra}} ex Biturigibus movet in Arvernos versus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"castrensis","latin":"castrensis, castrensis, castrense","headword":"castrensis","letter":"c","pos":"adjective","posGroup":"adjective","english":"of/connected with camp or active military service; characteristic of soldiers","forms":["castrēnse"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hunc ego hominem tam ācrem, tam audācem, tam parātum, tam callidum, tam in scelere vigilantem, tam in perditīs rēbus dīligentem, nisi ex domesticīs īnsidiīs in {{castrēnse}} latrōcinium compulissem — dīcam id quod sentiō, Quirītēs — nōn facile hanc tantam mōlem malī ā cervīcibus vestrīs dēpulissem.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"castrum","latin":"castrum, castri","headword":"castrum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"fort/fortress; camp (pl.), military camp/field; army; war service; day's march","forms":["castrorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum disparandos deducendosque ad suos curaret, quae cuique civitati pars {{castrorum}} ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"castus","latin":"castus, -a, -um","headword":"castus","letter":"c","pos":"adjective","posGroup":"adjective","english":"chaste; pure, innocent, holy","forms":["castās","castī","castissimum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"ī00 l[llelocus castī damna pudōris habet.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"casu","latin":"casu","headword":"casu","letter":"c","pos":"adverb","posGroup":"adverb","english":"by chance/accident; accidentally; casually; (ablative of casus)","forms":["casu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Romani si {{casu}} intervenerint, fortunae, si alicuius indicio vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"casula","latin":"casula, casulae","headword":"casula","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"little/small/humble cottage, hut","forms":["casulās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Aliquā diē tē persuādeam, ut ad vîllam veniās et videās {{casulās}} nostrâs?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"casus","latin":"cāsus, -ūs","headword":"cāsus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) fall, event, (grammatical) case; (m.) fall, case; case","forms":["cāsibus","cāsuī","casum","casus","cāsuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc {{casum}} ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cata","latin":"cata","headword":"cata","letter":"c","pos":"preposition","posGroup":"preposition","english":"by; (in distributed sense); [cata mane mane => morning by morning]","forms":["cata"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Pessimē mihi erat nē hîs precibus per rîdiculum aliquid {{cata}}- strophae quaererētur; nec enirn adhūc exciderat cocus ille quî oblîtus fuerat porcum exinterāre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"catadupum","latin":"catadupum, catadupi","headword":"catadupum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cataracts (pl.); (specifically Nile cataracts)","forms":["Catadūpa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec est ūllus hebetior sēnsus in vōbīs; sīcut, ubi Nīlus ad illa quae {{Catadūpa}} nōminantur praecipitat ex altissimīs montibus, ea gēns quae illum locum accolīt propter magnitūdinem sonitūs sēnsū audiendī caret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"catella","latin":"catella, catellae","headword":"catella","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"puppy (female), young/little bitch; lap dog; little/light/ornamental chain","forms":["catellam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Valdē tē rogô ut secundum pedēs stā- tuae meae {{catellam}} pônâs et corônäs et unguenta et Petra- itis omnēs pugnās, ut mihi contingat tuô beneﬁciô post mortem vīvere.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"catena","latin":"catēna, -ae","headword":"catēna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"chain","forms":["catēnā","catēnae","catēnam","catēnās","catēnīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Īrātus rēx eōs vesfītōs et {{catēnīs}} vīnctōs coniēcit in fomaeem ārdentem, sed flamma nihil illīs nocuit: nec corpus adussit ignis, nec vestēs quidem mūtāvit, at solvit tantummodo vincula, quibus eonstringēbantur, ita ut illaesī in mediā fomace ambulārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"caterva","latin":"caterva, -ae","headword":"caterva","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"band, troop, crowd; crowd, company","forms":["catervā","catervās","catervīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"chorus -ī 1 — canentium catervā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"catinum","latin":"catinum, catini","headword":"catinum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"large bowl/plate; main chamber in forepump; smelting crucible; hollow in rock","forms":["catīna","catīnum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prōfer quae necessāria sunt: salem, oleum Hispānum ad lucernās, acētum ācre, vīnum album et nigrum, ligna sicca, carbōnēs, secūrim, vāsa, {{catīna}}, caccabum, ōllam...!” [Servus, postquam omnia extulit:] “Quid aliud vīs?” [Iūlius:] “Haec tantum, puer: Vāde ad Gāium et dīc eī: ‘Venī!’ Inde lavēmus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cato","latin":"Cato, Catonis","headword":"Cato","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cato; (Roman cognomen); [M. Porcius Cato => Censor]","forms":["Catō","Catōne","Catōnem","Catōnī","Catōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Catō ōrātor in cīvitāte et Plautus poēta in scaenā flōruērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"catulus","latin":"catulus, catuli","headword":"catulus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"young dog, puppy, whelp; dog (any age); young of any animal, pup/cub; fetter","forms":["Catulī","catulīs","Catulō","Catulum","Catulus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"375 nec lea, cum {{catulīs}} lactentibus ūbera praebet,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"caucasus","latin":"Caucasus, Caucasi","headword":"Caucasus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Caucasus; (mountain range between Black and Caspian seas)","forms":["Caucasō","Caucasum","Caucasus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam vērō cōram deīs fuit, Iuppiter hanc sevērissimam gravissimamque poenam in eum statuit: ut in monte Caucasō catēnā ferreā vincīrētur; praetereā ut aquila cotīdiē eius iecur interdiū vorāret, quod nocte iterum nāscerētur, nē supplicium umquam fīnem habēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cauda","latin":"cauda, -ae","headword":"cauda","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"tail","forms":["caudā","caudam","caudās","caudīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Canis eam canere audit et {{caudam}} movet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"caudex","latin":"caudex, caudicis","headword":"caudex","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"trunk of tree; piece/hunk of wood; blockhead; (bound) book; note/account book","forms":["Caudex"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Annō deinde post Rōmam conditam quadringentēsimō fermē et nōnāgēsimō, cōnsulibus Appiō Claudiō — cui cognōmentum {{Caudex}} fuit — et Marcō Fulviō Flaccō, bellum adversum Poenōs prīmum coeptum est, neque diū post Callimachus, poēta Cȳrēnēnsis, Alexandrīae apud Ptolomaeum rēgem celebrātus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"causa","latin":"causa, -ae","headword":"causa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cause, reason; cause, sake, reason; case, cause, reason","forms":["causa","causae","causam","causārum","causās","causīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis {{causa}} recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"causalis","latin":"causālis","headword":"causālis","letter":"c","pos":"adjective","posGroup":"adjective","english":"(coniūnctiō) (f.) causal conjunction; causal","forms":["causālēs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis adnectēns ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: 'Cōpulātīvās, disiūnctīvās, explētīvās, {{causālēs}}, ratiōnālēs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"causidicus","latin":"causidicus, causidici","headword":"causidicus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"advocate, barrister; pleader of causes","forms":["causidicō","causidicum","causidicus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vidēs Philerônem {{causidicum}}: sī nôn didicisset, hodiē famem â labrîs nôn abigeret; etiam adversus Norbânum sē extendit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caute","latin":"caute, cautius, cautissime","headword":"caute","letter":"c","pos":"adverb","posGroup":"adverb","english":"cautiously; with security/precautions, without risk; circumspectly, carefully","forms":["cautē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tum Promētheus, postquam cautē circum sē aspexit num quis venīret, curruī appropinquāvit, ut inde ignis scintillam sūmeret, quam hominibus dōnāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cautes","latin":"cautes, cautis","headword":"cautes","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"rough pointed/detached rock, loose stone; rocks (pl.), cliff, crag; reef","forms":["cautibus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"perfide, sed dūrīs genuit tē {{cautibus}} horrēns","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cautis","latin":"cautis, cautis","headword":"cautis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"rough pointed/detached rock, loose stone; rocks (pl.), cliff, crag; reef","forms":["cautīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"crīmina sunt {{cautīs}} istā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cautum","latin":"cautum, cauti","headword":"cautum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"provisions (pl.) (of a law); concern (Ecc)","forms":["cautum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cavēre cávisse {{cautum}} Cāverit haec cūstōs, prō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cautus","latin":"cautus, -a, -um","headword":"cautus","letter":"c","pos":"adjective","posGroup":"adjective","english":"cautious; cautious, careful","forms":["cautus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Semper {{cautus}} estō!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cava","latin":"cava, cavae","headword":"cava","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hollow; cage (Ecc)","forms":["cavā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et cavā sub tenerum scamna","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cavatus","latin":"cavatus, cavata -um, cavatior -or -us, cavatissimus -a -um","headword":"cavatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"hollow, hollow in form; hollowed out, excavated; forming a cave","forms":["cavāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Classem in convexō nemorum sub rūpe {{cavāta}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cavea","latin":"cavea, -ae","headword":"cavea","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cage, coop","forms":["cavea"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Super līmen autem {{cavea}} pendēbat aurea, in quā pīca varia intrantēs salūtābat. cūrat premendô ac pulsandô veste circumdare, vestīre pīsum (: pīsa) pūrgāre : ē vārius : variīs colôribus litterā quadrātā: Ā B C D Ē... persequī oculîs : spectāre dëﬁciëns porticūs zextrëma p.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"caveo","latin":"caveo, cavere, cavi, cautus","headword":"caveo","letter":"c","pos":"verb","posGroup":"verb","english":"beware, avoid, take precautions/defensive action; give/get surety; stipulate","forms":["caveat","cavendum","cavēns","cavere","cavēris","Cāverit","cāvērunt","cavēte","cavētō","cāvisse","cāvissēs","cavit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus {{cavere}} inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cavere","latin":"(caveō) cavēre, cāvisse, cautum","headword":"cavēre","letter":"c","pos":"","posGroup":"other","english":"beware","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"cavo","latin":"cavo, cavare, cavavi, cavatus","headword":"cavo","letter":"c","pos":"verb","posGroup":"verb","english":"hollow out, make concave/hollow; excavate; cut/pierce through; carve in relief","forms":["cavantur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tamen dūra saxa mollī aquā {{cavantur}} dūra tamen mollī saxa","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cavum","latin":"cavum, cavi","headword":"cavum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"hole, cavity, depression, pit, opening; cave, burrow; enclosed space; aperture","forms":["cavum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sustinētur); {{cavum}} (: leve) scamnum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cavus","latin":"cavus, -a, -um","headword":"cavus","letter":"c","pos":"adjective","posGroup":"adjective","english":"hollow","forms":["cavē","cavus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tlēpolemus: “c-a ca, v-e vē: ca-vē, c-a ca, n-e-m nem: canem: cavē canem!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"cedens","latin":"cedens, (gen.), cedentis","headword":"cedens","letter":"c","pos":"adjective","posGroup":"adjective","english":"unresisting/deferring/conceding/surrendering/withdrawing; yielding to touch","forms":["cedentes","cedentibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Galli inter equites raros sagittarios expeditosque levis armaturae interiecerant, qui suis {{cedentibus}} auxilio succurrerent et nostrorum equitum impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cedere","latin":"(cēdō) cēdere, cēssisse,  cessum  ({i}intr. + dat.{/i})","headword":"cēdere","letter":"c","pos":"","posGroup":"other","english":"yield","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"cedo","latin":"cedo, cedere, cessi, cessus","headword":"cedo","letter":"c","pos":"verb","posGroup":"verb","english":"go/pass (from/away); withdraw/retire/leave; step aside/make way; take place of","forms":["cēdās","cēdat","cēde","cēdēbant","cēdendō","cedendum","cēdere","cēderet","cēdet","cēdimus","cēdit","Cedo","cēdunt","cesserīmus","cessisset","cessit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ne eo quidem tempore quisquam loco {{cessit}}, sed circumventi omnes interfectique sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"celare","latin":"(cēlō) cēlāre","headword":"cēlāre","letter":"c","pos":"","posGroup":"other","english":"conceal (from)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"celeber","latin":"celeber, -bris, -bre","headword":"celeber","letter":"c","pos":"adjective","posGroup":"adjective","english":"crowded, well-known; celebrated, famous","forms":["celeberrima","celeberrimum","celeberrimus","celebre","celebrior"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nūlla diēs fertur {{celebrior}} quam illa Athēnīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"celebrare","latin":"(celebrō) celebrāre","headword":"celebrāre","letter":"c","pos":"","posGroup":"other","english":"go to a place frequently or in great numbers, celebrate, extol","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"celebratus","latin":"celebrātus, -a, -um","headword":"celebrātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"crowded, celebrated, famous","forms":["celebrātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Annō deinde post Rōmam conditam quadringentēsimō fermē et nōnāgēsimō, cōnsulibus Appiō Claudiō — cui cognōmentum Caudex fuit — et Marcō Fulviō Flaccō, bellum adversum Poenōs prīmum coeptum est, neque diū post Callimachus, poēta Cȳrēnēnsis, Alexandrīae apud Ptolomaeum rēgem {{celebrātus}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"celebris","latin":"celebris, celebris, celebre","headword":"celebris","letter":"c","pos":"adjective","posGroup":"adjective","english":"famous, celebrated, renowned; honored, distinguished; famed; notorious","forms":["celebris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Via {{celebris}}, quae inter Cūriam et basilicam Aemiliam in forum exit, Argīlētum nōminātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"celebritas","latin":"celebritās, -tātis ( f.)","headword":"celebritās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"large assembly; renown","forms":["celebritātem","celebritātēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Idemque mercātūs, lūdōs omnēsque conveniundī causās et {{celebritātēs}} invēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"celebro","latin":"celebrō (1)","headword":"celebrō","letter":"c","pos":"verb","posGroup":"verb","english":"praise, honor, celebrate","forms":["celebrābat","celebrāret","celebrārētur","celebrārī","celebrāte","celebrātum","celebrāvērunt","celebrēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Diē quādam cum pūblicum convīvium {{celebrārētur}}, Samsōnem addūcī iubent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"celer","latin":"celer, celeris, celere","headword":"celer","letter":"c","pos":"adjective","posGroup":"adjective","english":"swift; swift, fast","forms":["celer","celerem","celerēs","celerior","celerius","celerrimē","Celerum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vix haec dīxerat, cum servī, quī sevērum atque superbum rēgem timēbant, quam celerrimē potuērunt imperāta fēcērunt: itaque ad stabulum cucurrērunt unde alterum taurum ad lītus dūxērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"celeritas","latin":"celeritās, -ātis ( f.)","headword":"celeritās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"speed, swiftness","forms":["celeritas","celeritate","celeritātem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, {{celeritate}} praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"celeriter","latin":"celeriter","headword":"celeriter","letter":"c","pos":"adverb","posGroup":"adverb","english":"quickly","forms":["celeriter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eae res in Galliam Transalpinam {{celeriter}} perferuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"celero","latin":"celero, celerare, celeravi, celeratus","headword":"celero","letter":"c","pos":"verb","posGroup":"verb","english":"quicken/accelerate; make haste, act quickly/be quick; hasten, hurry, do quickly","forms":["celerāns","celerāre"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum {{celerāre}} fugam patriāque excēdere suādet,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"celes","latin":"celes, celetis","headword":"celes","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"small/fast boat, yacht; (statue of) a race horse","forms":["cēlēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cave nē mē quidquam {{cēlēs}} eōrum quae audīstī.” Iubentī pāruit Samūēl, illīque ēnārrāvit omnia verba Dominī, cui Hēlī: “Dominus est” ait “faciat quod sibi libuerit.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cella","latin":"cella, -ae","headword":"cella","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"inner chamber (of a temple)","forms":["cellā","cellam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Interim, dum Mercurius vigilat, aediﬁcävî hanc dō- quattuor cënätiônës, cubicula vîgintî, porticūs marmorā- tôs duôs, süsum cellätiônem, cubiculum in quô ipse dormiô, vîperae huius sessôrium, ôstiäriî {{cellam}} per- bonam.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"celo","latin":"cēlō, -āre, -āvī, -ātum","headword":"cēlō","letter":"c","pos":"verb","posGroup":"verb","english":"hide, conceal","forms":["cēlābant","celābat","cēlanda","celāre","cēlāret","celari","cēlāris","celat","cēlātā","cēlātō","cēlāverat","cēlāvit","cēlent","celeris","cēlētur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed elati spe {{celeris}} victoriae et hostium fuga et superiorum temporum secundis proeliis, nihil adeo arduum sibi esse existimaverunt quod non virtute consequi possent, neque finem prius sequendi fecerunt quam muro oppido portisque appropinquarunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"celsus","latin":"celsus, -a, -um","headword":"celsus","letter":"c","pos":"adjective","posGroup":"adjective","english":"tall, high","forms":["celsā","celsās","Celsī","celsīs","celsum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ut vērō amōris dolōrem, quō animus eius afficiēbātur, levāret, nōnnumquam in {{celsum}} saxum ascendēbat, unde, mare prōspiciēns, tībiīs ūsus hōc modō canēbat: “Ō fōrmōsa Galatēa, cāseō candidior, agnō suāvior, ūva mātūra dulcior, cūr mē amantem contemnis, sī dīligenter tē cūrō?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cementum","latin":"cementum, cementi","headword":"cementum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"small stones, rubble (for concrete); quarry stones (for walls) (L+S); chips","forms":["cementīs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cum ergô Trimalchiô iūs inter lîtigantës dîceret, neuter sententiam tulit dë{{cementīs}}, sed alterîus amphoram fuste percussit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cena","latin":"cēna, -ae","headword":"cēna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"dinner; dinner, main meal; dinner, meal","forms":["cēna","cēnae","cēnam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vesperī vērō ē silvīs collibusque ad parvam casam redībant, ubi {{cēnam}} parābant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cenabum","latin":"Cenabum, Cenabi","headword":"Cenabum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"Cenabum; town in Gaul; Orleans","forms":["Cenabi","Cenabum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, {{Cenabum}} signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cenaculum","latin":"cenaculum, cenaculi","headword":"cenaculum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"attic, garret (often let as lodging); upstairs dining room; top/upper story","forms":["cēnāculō","cēnāculum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Inambulābat in cēnāculō maerēns, et in hās vōcēs identidem ērumpēns: “Fīlī mī Absalōn, Absalōn fīlī mī: utinam prō tē moriar, Absalōn fīlī mī, fīlī mī Absalōn.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cenare","latin":"(cēnō) cēnāre, -āvisse, -ātum","headword":"cēnāre","letter":"c","pos":"verb","posGroup":"verb","english":"dine; to dine","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"ceno","latin":"ceno, cenare, cenavi, cenatus","headword":"ceno","letter":"c","pos":"verb","posGroup":"verb","english":"dine, eat dinner/supper; have dinner with; dine on, make a meal of","forms":["cēnābant","cēnābat","cēnābimus","cenabis","cēnandum","cēnant","cēnantibus","cēnāre","cēnārent","cēnat","Cēnāte","cēnāveram","cēnāvī","cēnāvimus","cēnāvistī","cēnēmus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Cēnantibus}} autem iīs, accēpit pānem, benedīxit ac frēgit, dēditque discipulīs suīs et ait:\"Accipite et comedite: hoc est corpus meum.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"censeo","latin":"censeo, censere, censui, census","headword":"censeo","letter":"c","pos":"verb","posGroup":"verb","english":"think/suppose, judge; recommend; decree, vote, determine; count/reckon; assess","forms":["cēnseam","cēnseant","cēnseat","cēnsēbant","censebat","cēnsēbātur","cēnsēbis","censent","censeo","cēnsēre","cēnserem","cēnsērent","cēnsēret","cēnsēs","cēnset","cēnsuerant","censuerat","cēnsuēre","cēnsuerit","cēnsuērunt","cēnsuisset","censuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Statuunt ut X milia hominum delecta ex omnibus copiis in oppidum mittantur, nec solis Biturigibus communem salutem committendam {{censent}}, quod penes eos, si id oppidum retinuissent, summam victoriae constare intellegebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"censere","latin":"(cēnseō) cēnsēre, cēnsuisse, cēnsum","headword":"cēnsēre","letter":"c","pos":"","posGroup":"other","english":"think","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"censor","latin":"cēnsor, -ōris (m.)","headword":"cēnsor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"censor (magistrate)","forms":["cēnsor","cēnsōrēs","cēnsōribus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{cēnsor}} -óris m — vir cuius mūnus est","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"censum","latin":"censum, censi","headword":"censum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"estimate of property value by census/censor; ones property/wealth/fortune","forms":["cēnsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aggrediturque inde ad pācis longē maximum opus: ut enim īnstituit {{cēnsum}}, bellī pācisque mūnera nōn virītim, ut ante, sed prō habitū pecūniārum fierent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"censura","latin":"cēnsūra, -ae ( f.)","headword":"cēnsūra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"censorship","forms":["cēnsūra"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec mea vōs ūnī dōnat {{cēnsūra}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"census","latin":"cēnsus, -ūs","headword":"cēnsus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"assessment, registration; census, valuation","forms":["cēnsa","cēnsōs","cēnsū","cēnsuī","cēnsus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"quī furor est...! : quam furiōsum est...! quis furor est {{cēnsus}} corpore","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"centaurus","latin":"centaurus, centauri","headword":"centaurus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"centaur, a mythical creature, half man and half horse; name of constellation","forms":["Centaurī","Centaurōrum","Centaurōs","centaurus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Centaurī mīra mōnstra fuērunt, quibus vultūs, pectora et bracchia hominum erant, cētera vērō corporis membra equīna; nātūram vērō ferōcem et saevam habēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"centesimus","latin":"centēsimus, -a, -um","headword":"centēsimus","letter":"c","pos":"adjective","posGroup":"adjective","english":"hundredth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"centum","latin":"centum","headword":"centum","letter":"c","pos":"numeral","posGroup":"numeral","english":"(invariable) a hundred","forms":["centēsimō","centēsimum","centiēs","centum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter {{centum}} LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"centuria","latin":"centuria, -ae","headword":"centuria","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"century (unit of 100); company of a hundred; squadron","forms":["centuria","centuriae","centuriās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eōdem tempore et {{centuriae}} trēs equitum cōnscrīptae sunt: \"Ramnēnsēs\" ab Rōmulō, ab T.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"centuriatus","latin":"centuriātus, -a, -um","headword":"centuriātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"voting in centuries; office of century","forms":["centuriātūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quem enim possumus imperātōrem illō in numerō putāre cuius in exercitū {{centuriātūs}} vēneant atque vēnīerint? quid hunc hominem magnum aut amplum dē rē pūblicā cōgitāre, quī pecūniam ex aerāriō dēprōmptam ad bellum administrandum aut propter cupiditātem prōvinciae magistrātibus dīvīserit aut propter avāritiam Rōmae in quaestū relīquerit?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"centurio","latin":"centuriō, -ōnis (m.)","headword":"centuriō","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"centurion (officer)","forms":["centuriātīs","centurio","centuriōne","centuriōnem","centuriōnēs","centurionibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, {{centurionibus}} et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium procul visus est, qui agmen Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cephalo","latin":"cephalo, cephalonis","headword":"cephalo","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"palm tree","forms":["Cephalō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Gràta quiēs Cephalō: famulīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cera","latin":"cēra, -ae","headword":"cēra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"wax","forms":["cēra","cērae","cēram","cērīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Lapidēs (mīrābile dictū!) ut {{cēra}} molliuntur; postquam vērō mollēs fīunt, fōrmam accipere incipiunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cerasinus","latin":"cerasinus, cerasina, cerasinum","headword":"cerasinus","letter":"c","pos":"adjective","posGroup":"adjective","english":"cherry-colored","forms":["cerasina"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vënit ergô, galbinô succîncta cingillô, periscelis _ ita ut înfrä {{cerasina}} appārēret tunica et periscelidēs tortae phaecasiaeque inaurā- tae.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ceraunius","latin":"ceraunius, ceraunia, ceraunium","headword":"ceraunius","letter":"c","pos":"adjective","posGroup":"adjective","english":"connected with thunderbolts/thunder/lightning; (varieties of plant/minerals)","forms":["Ceraunia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eō diē Trōiānī iūxtā {{Ceraunia}} promunturium vectī sunt, unde cursus brevissimus est in Italiam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cerberus","latin":"Cerberus, -ī","headword":"Cerberus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cerberus, the three-headed dog of the underworld","forms":["Cerberum","Cerberus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Proserpinam et Plūtōnem tenentem rēgnum umbrārum adiit et sīc ait: \"Ō dī positī sub terrā, nōn hūc dēscendī quod Tartarum vidēre dēsīderābam nec canem {{Cerberum}}, mōnstrum ingēns, vincere.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cereale","latin":"Cereale, Cerealis","headword":"Cereale","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"festival of Ceres (pl.)","forms":["Cereālia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tūre datō flammīs vīnōque in tūra profūsō,\n. . . rēgia tēcta petunt, positīsque tapētibus altīs\nmūnera cum liquidō capiunt {{Cereālia}} Bacchō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cerebellum","latin":"cerebellum, cerebelli","headword":"cerebellum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"brain; seat of senses/intellect; little brain (L+S)","forms":["cerebellum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Cēterum, quemadmodum dî volunt, dominus in domô factus sum, et ecce cëpî ipsimî {{cerebellum}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cerebrum","latin":"cerebrum, -ī","headword":"cerebrum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"brain","forms":["cerebrī","cerebrō","cerebrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Post frontem est {{cerebrum}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ceres","latin":"Cerēs, Cereris","headword":"Cerēs","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Ceres (goddess of agriculture)","forms":["Cerere","Cererem","Cererī","Cereris","Cerēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Cerēs}} est dea frūmentī et frūgum omnium, quae in agrīs crēscunt et ab agricolīs metuntur, cum prīmum mātūrae videntur esse.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cerno","latin":"cernō, cernere","headword":"cernō","letter":"c","pos":"verb","posGroup":"verb","english":"discern, perceive","forms":["cernam","cērne","cernebantur","cernēbat","cernebatur","cernēns","cernentī","cernere","cernerentur","cernerēs","cerneret","cernerētur","cernēs","cerni","cernis","cernit","cernitis","cernitur","cernō","cernuntur","crētum","crēverant","creverat","crēvisse","crēvissent","crēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam cum in minora castra operis perspiciendi causa venisset, animadvertit collem, qui ab hostibus tenebatur, nudatum hominibus, qui superioribus diebus vix prae multitudine {{cerni}} poterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cero","latin":"cero, cerare, ceravi, ceratus","headword":"cero","letter":"c","pos":"verb","posGroup":"verb","english":"smear/coat with wax","forms":["ceret"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cum ergô auferrētur, ad caput eius symphôniacus cum minimîs tībiīs accessit et, tamquam in aurem alī- quid sëcrëtô dî{{ceret}}, tôtô itinere cantāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ceroma","latin":"ceroma, ceromatis","headword":"ceroma","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"layer of mud put down for wrestling; the_ring; wrestler; wax ointment (L+S)","forms":["cērōmate"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rape nōbīs pilam! [Ad Gāium:] Lūdāmus in sphaeristēriō!” [Amīcī in sphaeristēriō pilā lūdunt.] [Iūlius:] “Exercērī volō in {{cērōmate}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"certamen","latin":"certāmen, certāminis","headword":"certāmen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) contest, fight; contest; contest, struggle","forms":["certāmen","certāmine","certāminī","certāminibus","certāminis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum duae aciēs in cōnspectū essent, Philistaeus quīdam, nōmine Goliathus, vir mīrae magnitūdinis, prōgressus est ante ōrdinēs, et ūnum ex Hebraeīs saepe prōvocābat ad singulāre {{certāmen}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"certare","latin":"(certō) certāre, certāvisse, certātum","headword":"certāre","letter":"c","pos":"verb","posGroup":"verb","english":"contend, fight; to contend, fight","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"certe","latin":"certē","headword":"certē","letter":"c","pos":"adverb","posGroup":"adverb","english":"surely, certainly","forms":["certe"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas excidere conatus esset, a multitudine oppressus ac sibi desperans, multis iam vulneribus acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem {{certe}} vitae prospiciam, quos cupiditate gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"certiorem facere","latin":"certiōrem facere","headword":"certiōrem facere","letter":"c","pos":"","posGroup":"other","english":"inform","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"certo","latin":"certō","headword":"certō","letter":"c","pos":"verb","posGroup":"verb","english":"for certain; contend, vie with, struggle","forms":["certa","certābant","certābat","certāmus","certandī","certāns","certantēs","certāre","certārent","certātum","certātur","certāvērunt","certavisset","certent","certet","certo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia adducti fecerint, quod nihil nobis constat, non videtur pro {{certo}} esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"certum","latin":"certum, certi","headword":"certum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"that which is fixed/regular/definite/specified/certain/fact/reliable/settled","forms":["certum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, {{certum}} numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"certus","latin":"certus, -a, -um","headword":"certus","letter":"c","pos":"adjective","posGroup":"adjective","english":"certain, sure; sure, certain","forms":["certae","certam","certi","certior","certiōrā","certiorem","certīs","certissima","certissimam","certius","certos","certus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto {{certior}} factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cerva","latin":"cerva, -ae","headword":"cerva","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hind, deer","forms":["cervā","cervae","cervam","cervis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Huic loricam pinnasque adiecit, grandibus {{cervis}} eminentibus ad commissuras pluteorum atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cervix","latin":"cervix, cervicis","headword":"cervix","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"neck (sg/pl.), nape; severed neck/head; cervix, neck (bladder/uterus/jar/land)","forms":["cervīce","cervīcibus","cervīx"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hēlī, audītō tantae clādis nūntiō, ē sellā dēcidit, et frāctā {{cervīce}} mortuus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cervos","latin":"cervos, cervi","headword":"cervos","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"stag/deer; forked branches; chevaux-de-frise (spiked barricade against cavalry)","forms":["cervōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum ōlim īnfēlīx nympha per silvāsas errāret, subitō Narcissum, fōrmōsissimum adulēscentulum sēdecim annōrum, quī arcū et sagittīs armātus timidōs {{cervōs}} persequēbātur, cōnspexit; quem cum prīmum pulcherrimīs membrīs currentem cervīque vestīgia oculīs quaerentem vīdisset, statim amāvit nec iam sine eō sē vīvere posse putāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cervus","latin":"cervus, -ī","headword":"cervus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"stag, deer; stag","forms":["cervī","cervō","cervum","cervus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēlectābātur vērō ingentī quōdam cervō quī magna et lāta cornua in capite gerēbat, quae Nymphae aurō gemmīsque ita ōrnāverant ut etiam in obscūrā silvā lūcērent; ipse cervus, sine mētā, hominum domōs adīre solēbat, quī, manūs extendentēs, eius collum tergumque tangēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cessare","latin":"(cessō) cessāre, cessāvisse, cessātum","headword":"cessāre","letter":"c","pos":"verb","posGroup":"verb","english":"cease, stop; to stop, cease","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"cesso","latin":"cesso, cessare, cessavi, cessatus","headword":"cesso","letter":"c","pos":"verb","posGroup":"verb","english":"be remiss/inactive; hold back, leave off, delay, cease from; rest; be free of","forms":["cessābit","cessandum","cessāre","cessārent","cessat","cessātum","cessāvit","cessēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ut {{cessāvit}} loquī, dīxit Simonī:\"Due in altum, et laxātē rētia.\"Respondit Simōn:\"Praeceptor, tōtam noctem labōrāvimus, sed nihil cēpimus; tamen, sīcut dixisfī, laxābō rēte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cetera","latin":"cetera","headword":"cetera","letter":"c","pos":"adverb","posGroup":"adverb","english":"for the rest, otherwise; in other respects","forms":["cētera"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi sunt {{cētera}} ōrnāmenta tua?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ceteri","latin":"cēterī, -ae, -a","headword":"cēterī","letter":"c","pos":"adjective","posGroup":"adjective","english":"(pl.) the other(s), the rest; the rest, the others","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cetero","latin":"cetero","headword":"cetero","letter":"c","pos":"adverb","posGroup":"adverb","english":"for the rest(new details/theme), otherwise; in other respects; at other times","forms":["cēterō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Crēditur — quia nōn abhorret ā cēterō scelere — admonitū Tulliae id factum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ceterum","latin":"cēterum","headword":"cēterum","letter":"c","pos":"adverb","posGroup":"adverb","english":"besides, however","forms":["cēterum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Cēterum}} in hāc rē is nōn peior fuerat cēterīs, nam omnēs puerī parum attentī fuerant.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ceterus","latin":"cēterus, -a, -um","headword":"cēterus","letter":"c","pos":"adjective","posGroup":"adjective","english":"other, rest of","forms":["cēterae","Cēterārum","ceteras","cēterī","cēterīs","cēterōrum","cēterōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fabium discessu eorum duabus relictis portis obstruere {{ceteras}} pluteosque vallo addere et se in posterum diem similemque casum apparare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ceyx","latin":"ceyx, ceycis","headword":"ceyx","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"sea bird (tern?); son of Lucifer/husband of Alcyone; male kingfisher (L+S)","forms":["Cēycis","Cēyx"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Fuērunt ōlim duo coniugēs: virō {{Cēyx}}, uxōrī vērō Alcyonē nōmen fuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"chalcis","latin":"Chalcis, Chalcidos/is","headword":"Chalcis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Chalcis; (several towns in Greece/elsewhere, esp. chief city of Euboea)","forms":["Chalcide","Chalcidem","Chalcis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum quibus societāte iūnctā, Antiochus, Syriae rēx, cum bellum Graeciae intulisset, complūrēs urbēs occupāvit, inter quās {{Chalcidem}} et tōtam Euboeam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"chanaan","latin":"Chanaan, undeclined","headword":"Chanaan","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Canaan/Palestine","forms":["Chanaan"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī respondērunt: profectī sumus ē regiōne {{Chanaan}} ut emāmus frūmentum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"chaos","latin":"Chaos, Chai","headword":"Chaos","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"Chaos, pit of Hell, underworld; formless/shapeless primordial matter","forms":["chaos"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ināne {{chaos}} : chaos sine ōrdine","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"charta","latin":"charta, -ae","headword":"charta","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"paper; paper, map","forms":["chartā","chartae","chartam","chartās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister calamum et {{chartam}} prōmit et ipse scrībere incipit; is enim calamō in chartā scrībit, nōn stilō in cērā ut discipulī. (Charta ex papȳrō efficitur, id est ex altā herbā quae in Aegyptō apud Nīlum flūmen reperītur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"charybdis","latin":"Charybdis, -is","headword":"Charybdis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Charybdis (a dangerous whirlpool)","forms":["Charybdem","Charybdim","Charybdis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Brevī nāvigābimus per fretum Siculum, ubi ab utrāque parte magnum perīculum impendet nautīs: ab ōrā Italiae saxa perīculōsa, quibus Scyllā nōmen est, ab ōrā Siciliae vorāgō terribilis quae {{Charybdis}} vocātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"chia","latin":"chia, chiae","headword":"chia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Chian fig; (Chios/Chius island in Aegean off Ionia)","forms":["chīa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{chīa}} tibi sunt, saltà! (quī saltat","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"chilo","latin":"Chilo, Chilonis","headword":"Chilo","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Chilo; Big Lips (Roman cognomen); fellator, one who practices fellatio","forms":["Chīlōnem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annium {{Chīlōnem}}, quī ūna cum hōc Fūriō semper erat in hāc Allobrogum sollicitātiōne versātus, in P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"chirographum","latin":"chirographum, chirographi","headword":"chirographum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"own handwriting; handwritten document, manuscript; written bond/charter/promise","forms":["chīrographum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque angelus, sūmptīs camēlīs, properāvit Rāgē, suum Gābelō {{chīrographum}} reddidit, pecūniam illī crēditam recēpit, eumque ad nūptiās Tobiae addūxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"chius","latin":"Chius, Chia, Chium","headword":"Chius","letter":"c","pos":"adjective","posGroup":"adjective","english":"Chian, of Chios; of Chian wine; characteristic/suggestive of Chios, luxurious","forms":["Chios"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Crēta, Rhodus, Naxus, Samos, {{Chios}}, Lesbos, Lēmnos, Euboea sunt īnsulae Graecae.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"chlamys","latin":"chlamys, chlamydis","headword":"chlamys","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Greek cloak/cape frequently for military use; state mantle; cloak, mantle","forms":["chlamydem"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīdoniam pictō {{chlamydem}} circumdata limbō;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"choragium","latin":"choragium, choragii","headword":"choragium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"place where chorus practiced; preparing chorus; splendid preparation; a spring","forms":["chorāgium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eī dīcit in aurem aut ‘ut domī lectulī sternantur’, aut ‘ab avunculō rogētur Aethiops, quī ad balneās veniat’, aut ‘asturcōnī locus ante ōstium suum dētur’, aut aliquod fragile falsae {{chorāgium}} glōriae comparetur!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"chorda","latin":"chorda, chordae","headword":"chorda","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"tripe; catgut, musical instrument (string); rope/cord (binding slave) (L+S)","forms":["chordae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"plēctrum -ī 7, quō {{chordae}} pulsantur","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"chorus","latin":"chorus, chori","headword":"chorus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"chorus; choral passage in a play; dancing/singing performance/ers; school","forms":["chorī","chorōs","chorum","chorus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{chorus}} -ī 1 — canentium catervā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"christianus","latin":"Christianus, Christiani","headword":"Christianus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Christian/follower of Christ; Christian clergyman; Christianity (pl.) (Beesom)","forms":["Christiāna","Christiānī","Chrīstiānīs","Christiānō","Christiānōrum","Christiānōs","Christiānum","Christiānus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Orontēs: '...et cum {{Chrīstiānīs}} istīs, quī quendam hominem Iudaeum tamquam novum deum adōrant, deōs Rōmānōs dērīdent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"christus","latin":"Christus, Christi","headword":"Christus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Christ","forms":["Chrīste","Chrīstī","Chrīstō","Chrīstum","Chrīstus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Paulō post rēgnum Iildae invāsit Hērōdēs aliēnigena: hunc prīmum Iiidaēī habuērunt rēgem ex aliā gente ortum, eōque rēgnante nātus est {{Chrīstus}}, ufī praedīxerant prophētae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"chronicus","latin":"chronicus, -a, -um","headword":"chronicus","letter":"c","pos":"adjective","posGroup":"adjective","english":"written in the form of annals; annalistic; chronological; librī chronicī, chronicles","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"cibarium","latin":"cibarium, cibari(i)","headword":"cibarium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"ration/allowance of food (pl.); food, provisions; food for animals, feed/fodder","forms":["cibāria"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus iussit frātrum saccōs implērī trīticō, et pecūniam quam attulerant repōnī in ōre saccōrum; addidit īnsuper {{cibāria}} in viam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cibo","latin":"cibo, cibare, cibavi, cibatus","headword":"cibo","letter":"c","pos":"verb","posGroup":"verb","english":"feed, give food/fodder to animals/men; (also passive sense) eat, take food","forms":["cibo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi cum ad munitiones Romanorum accessissent, flentes omnibus precibus orabant ut se in servitutem receptos {{cibo}} iuvarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cibus","latin":"cibus, -ī","headword":"cibus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"food","forms":["cibī","cibīs","cibōs","cibum","cibus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra: “Est aquila, quae {{cibum}} quaerit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"cicatrix","latin":"cicātrīx, -īcis ( f.)","headword":"cicātrīx","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"scar","forms":["cicātrīcēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Nōn possum fideī causā imāginēs neque triumphōs aut cōnsulātūs maiōrum meōrum ostentāre — at, sī rēs postulet, hastās, vexillum, phalerās, alia mīlitāria dōna, praetereā {{cicātrīcēs}} adversō corpore!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cicer","latin":"cicer, ciceris","headword":"cicer","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"chick pea (Cicer aristinum); (as a common food); (rude) testicles, penis?","forms":["cicer","ciceris"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Circā {{cicer}} et lupînum, calvae arbitrātū, et mäla singula nam sî aliquid mūneris meô vemulae nôn tulerô, habëbô “Bene mē admonet dominā meā: in prôspectü habū- īmus ursînae frustum, dē quô cum imprūdēns Scintilla gustāsset, paene intestîna suā Vomuit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cicero","latin":"Cicero, Ciceronis","headword":"Cicero","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cicero; (gens Tullia cognomen; M. Tullius Cicero, Roman orator and statesman)","forms":["Cicerō","Cicerōne","Ciceronem","Cicerōnī","Cicerōnis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tullium {{Ciceronem}} et P.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cieo","latin":"cieo, ciere, civi, citus","headword":"cieo","letter":"c","pos":"verb","posGroup":"verb","english":"move, set in motion; excite/rouse/stir up; urge on; summon/muster/call up","forms":["ciēns","cient","ciēs","ciētur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{ciēs}} rotundā ...... vult)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ciere","latin":"(cieō) ciēre, cīvisse, citum","headword":"ciēre","letter":"c","pos":"","posGroup":"other","english":"set in motion, move","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cilicium","latin":"cilicium, cilicii","headword":"cilicium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"rug/blanket/small garment of goat's hair; (originating in Cilicia)","forms":["Ciliciā","cilicium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde scidit vestem, et induit {{cilicium}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cimber","latin":"Cimber, Cimbri","headword":"Cimber","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cimberi (pl.), a German tribe, invaded Gaul - in Caesar's \"Gallic War\"","forms":["Cimbri","Cimbrīs","Cimbrorum","Cimbrōs","Cimbrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Facere, quod nostri maiores nequaquam pari bello {{Cimbrorum}} Teutonumque fecerunt; qui in oppida compulsi ac simili inopia subacti eorum corporibus qui aetate ad bellum inutiles videbantur vitam toleraverunt neque se hostibus tradiderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cimbricus","latin":"Cimbricus, Cimbrica, Cimbricum","headword":"Cimbricus","letter":"c","pos":"adjective","posGroup":"adjective","english":"Cimbrian; of the Cimbri","forms":["Cimbricō","Cimbricum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tertiō quoque eī et quārtō dēlātus est cōnsulātus, quia bellum {{Cimbricum}} prōtrahēbātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cincinnatus","latin":"cincinnatus, cincinnata, cincinnatum","headword":"cincinnatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"with curled/curly hair; with hair in ringlets; (artificially)","forms":["Cincinnātō","Cincinnātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quīnctius {{Cincinnātus}} dictātor est factus, quī agrum quattuor iūgerum possidēns manibus suīs colēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cinctum","latin":"cinctum, cincti","headword":"cinctum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"girdle, method of girding clothes; crown/garland; belt","forms":["cīnctum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"'Er y Vērque novum stābat {{cīnctum}} flōrente corōnā, stābat nūda Aestās et spīcea serta gerēbat, stābat et Autumnus calcātīs sordidus ūvīs et glaciālis Hiems cānōs hirsūta capillōs","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cinctus","latin":"cinctus, cincta, cinctum","headword":"cinctus","letter":"c","pos":"adjective","posGroup":"adjective","english":"surrounded/encircled; surrounded (by friends/people/enemy); bordered, enclosed","forms":["cīnctus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum autem nūbe {{cīnctus}} sē occultāret, nēmō eum cernere poterat; ipse vērō, praesēns, omnia vidēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cingere","latin":"(cingō) cingere, cīnxīsse, cīnctum","headword":"cingere","letter":"c","pos":"","posGroup":"other","english":"bind round, surround","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"cingo","latin":"cingo, cingere, cinxi, cinctus","headword":"cingo","letter":"c","pos":"verb","posGroup":"verb","english":"surround/encircle/ring; enclose; beleaguer; accompany; gird, equip; ring (tree)","forms":["cingant","cingantur","cinge","cingebant","cingebat","cingentibus","cingere","cingeretur","cingeris","cingit","cingitur","cingō","cingunt","cīnxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ex omnibus fere partibus palus difficilis atque impedita {{cingebat}}, non latior pedibus quinquaginta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cingula","latin":"cingula, cingulae","headword":"cingula","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"belt; sword belt; sash, girdle; band; saddle-girth; collar (dog)","forms":["cingula"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dea, hīs precibus mōta, ita respondit: “Discēdite ā templō; vestibus capita vestra operīte et {{cingula}} solvite: deinde post terga iacitē ossa magnae mātris!” At Pyrrha id, quod dea imperābat, facere nōlēbat: “Ignōsce mihi, deārum optima: ego tamen dubitō an id facere audeam, quod iubēs; nōlo enim, iactātis ossibus, mātrem mortuam iniūria afficere!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cingulus","latin":"cingulus, -ī (also: cingulum, -ī)","headword":"cingulus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"belt; belt, zone","forms":["cingulīs","cingulō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam vērō per tōtum terrārum orbem frūstrā errāvit, in Siciliam rediit, ubi tandem, apud locum ubi terrā patuerat ut Plūtō et Proserpina ad Īnferōs dēscenderent, cingulō fīliae inventō, eam ab Īnferōrum rēge raptam esse intellēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cinis","latin":"cinis, -eris (m.)","headword":"cinis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"ashes; ashes, remains","forms":["cinere","cinerem","cinerēs","cinerī","cinis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubī ad aurēs Mardochaeī crūdēle ēdictum pervēnit, statim cōnscīssis vestibus saccum induit, cōnspersusque {{cinere}} perrēxit ad rēgiam, et illam implēvit questibus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cio","latin":"cio, cire, civi(ii), citus","headword":"cio","letter":"c","pos":"verb","posGroup":"verb","english":"move, set in motion; excite/rouse/stir up; urge on; summon/muster/call up","forms":["ci","cit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"nec tuā mordà{{ci}} pūmice","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cippus","latin":"cippus, cippi","headword":"cippus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"|stocks/fetter/prison; tree stump; bulwark of sharpened stakes (pl.) (L+S)","forms":["cippos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quini erant ordines coniuncti inter se atque implicati; quo qui intraverant, se ipsi acutissimis vallis induebant; hos {{cippos}} appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circa","latin":"circā","headword":"circā","letter":"c","pos":"preposition","posGroup":"preposition","english":"around","forms":["circā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Arcam circumferrī iussit circā mūrōs, sacerdōtēsque antecēdere, et tubā canere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circaea","latin":"circaea, circaeae","headword":"circaea","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"plant; (Vincetoxicum nigrum?)","forms":["Circaea"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"sors mē fīdumque Polītēn\nEurylochumque simul nimōque Elpēnora vīnō\nbīsque novem sociōs {{Circaea}} ad moenia mīsit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circaeum","latin":"circaeum, circaei","headword":"circaeum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"plant, mandrake; (alternative name for mandragoras)","forms":["Circaeō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nōs quoque Circaeō religātā in lītore nāve,\nAntiphatē memorem tum crūdēlisque Cyclōpis,\nīre negābāmus; sed tēcta ignōta subīre\nsorte sumus lēctī:","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circe","latin":"Circē, -ae","headword":"Circē","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Circe, the sorceress","forms":["Circae","Circē"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed Ulixēs effugit et pervenit ad īnsulam {{Circae}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circen","latin":"circen, circinis","headword":"circen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"circle; circular course; [w/solis => a year (poetic)]","forms":["Circēn"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"cumque eadem passīs (tantum medicāmina possunt!)\nclaudor hara, sōlumque suīs caruisse figūrā\nvīdimus Eurylochum: sōlus data pōcula fūgit;\nquae nisi vītāsset, pecoris pars ūna manērem\nnunc quoque saetigerī, nec tantae clādis ab illō\ncertior ad {{Circēn}} ultor vēnisset Ulixēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circensis","latin":"circēnsis, -e","headword":"circēnsis","letter":"c","pos":"adjective","posGroup":"adjective","english":"of the circus","forms":["circenses","circensibus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Malo cursus equorum spectare in circo.\" Cornelius: \"Ludi {{circenses}} me non minus iuvant quam gladiatorii: modo in amphitheatrum, modo in circum eo.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"circes","latin":"circes, circitis","headword":"circes","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"circle, ring; circuit, circumference of the circus","forms":["Circēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Amīssā sociōrum parte dolentēs\nmultaque conquestī terrās advēnimus illās,\nquās procul hinc spectās (procul est, mihi crēde, videnda\nīnsula vīsa mihi!) tūque ō iūstissime Trōum,\nnāte deā (neque enim fīnītō Marte vocandus\nhostis es, Aenēā), moneō, fuge lītora {{Circēs}}!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circiter","latin":"circiter","headword":"circiter","letter":"c","pos":"adverb","posGroup":"adverb","english":"(prp. + acc.) around, near (adv. approximately)","forms":["circiter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum {{circiter}} centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circo","latin":"circo, circare, circavi, circatus","headword":"circo","letter":"c","pos":"verb","posGroup":"verb","english":"traverse; go about (L+S); wander through","forms":["circo"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Malo cursus equorum spectare in {{circo}}.\" Cornelius: \"Ludi circenses me non minus iuvant quam gladiatorii: modo in amphitheatrum, modo in circum eo.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"circos","latin":"circos, circi","headword":"circos","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"precious stone","forms":["circōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Homines enim sunt hāc lēge generātī, quī tuērentur illum globum quem in hōc templō medium vidēs, quae \"terra\" dīcitur, iīsque animus datus est ex illīs sempiternīs ignibus quae \"sīdera\" et \"stellās\" vocātis, quae globōsae et rotundae, dīvīnīs animātae mentibus, {{circōs}} suōs orbēsque cōnficiunt celeritāte mīrābilī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circueo","latin":"circueo, circuire, circuivi(ii), circuitus","headword":"circueo","letter":"c","pos":"verb","posGroup":"verb","english":"encircle, surround; border; skirt; circulate/wander through; go/measure round","forms":["circuitōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Antiochum timor incessit nē quās per imminentia iuga callēs invenīret ad trānsitum Rōmānus; nam Lacedaemoniōs quondam ita ā Persīs {{circuitōs}} fāma erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circuitus","latin":"circuitus, -ūs","headword":"circuitus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"rotation, circumference; circuit, circumference","forms":["circuitu","circuitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Longo {{circuitu}} easdem omnes iubet petere regiones.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circulus","latin":"circulus, circuli","headword":"circulus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"circle; orbit, zone; ring, hoop; belt, collar; company; cycle; circumference","forms":["circulus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ecce autem dēductus lacūnā- ribus subitô {{circulus}} ingēns dēmittitur, cuius per tôtum orbem corônae aureae cum alabastrîs unguentî pendēbant.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"circum","latin":"circum","headword":"circum","letter":"c","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) around; around, about","forms":["circum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum aureum eius vellus ad Colchidis rēgem portāvit, quī: “Cūrābō” inquit, “ut hoc vellus aureum in rāmō altissimae quercus pōnātur, quae in silvā prope rēgiam est.” Dracō vērō saevus, quī in silvā vīvēbat, {{circum}} arboris truncum sē volvēns vellus per multōs annōs cūstōdīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"circumagere","latin":"(circumagō) circumagere (< agere)","headword":"circumagere","letter":"c","pos":"","posGroup":"other","english":"cause to turn around","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumago","latin":"circumago, circumagere, circumegi, circumactus","headword":"circumago","letter":"c","pos":"verb","posGroup":"verb","english":"drive/lead around; turn (around); wheel, revolve; upset; change opinions, sway","forms":["circumagerent","circumagī","circumagit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Trēs in saxa latentia abripiuntur, trēs ab altō in vada feruntur, ūnam ante ipsīus Aenēae oculōs ingēns flūctus in puppim ferit atque ter {{circumagit}}, tum rapidus vertex eam vorat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circumcisus","latin":"circumcisus, circumcisa, circumcisum","headword":"circumcisus","letter":"c","pos":"adjective","posGroup":"adjective","english":"sheer on all sides, cut off; limited; short, brief, pruned of excess, abridged","forms":["circumcisus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Erat e regione oppidi collis sub ipsis radicibus montis egregie munitus atque ex omni parte {{circumcisus}}; quem si tenerent nostri, et aquae magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumcludo","latin":"circumcludo, circumcludere, circumclusi, circumclusus","headword":"circumcludo","letter":"c","pos":"verb","posGroup":"verb","english":"surround; encircle/enclose/build round (w/structure); hedge/shut in, circumvent","forms":["circumclūsum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Num īnfitiārī potes tē illō ipsō diē meīs praesidiīs, meā dīligentiā {{circumclūsum}} commovēre tē contrā rem pūblicam nōn potuisse, cum tū, discessū cēterōrum, nostra tamen quī remānsissēmus caede contentum tē esse dīcēbās?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"circumdare","latin":"(circumdō) circumdare, circumdedisse, circumdatum","headword":"circumdare","letter":"c","pos":"verb","posGroup":"verb","english":"surround; to surround","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"circumdo","latin":"circumdo, circumdare, circumdedi, circumdatus","headword":"circumdo","letter":"c","pos":"verb","posGroup":"verb","english":"surround; envelop, post/put/place/build around; enclose; beset; pass around","forms":["circumdabunt","circumdant","circumdantēs","circumdantur","circumdare","circumdat","circumdata","circumdatam","circumdatō","circumdatum","circumdatur","circumdedēre","circumdedērunt","circumdedit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude {{circumdata}} unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumducere","latin":"(circumdūcō) circumdūcere (< dūcere)","headword":"circumdūcere","letter":"c","pos":"","posGroup":"other","english":"lead around","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumduco","latin":"circumduco, circumducere, circumduxi, circumductus","headword":"circumduco","letter":"c","pos":"verb","posGroup":"verb","english":"lead out of the way/round about; cheat, mislead, trick out of; take/go around","forms":["circumdūcī","circumdūcit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tullus equitem clārā increpāns vōce, ut hostēs exaudīrent, redīre in proelium iubet: nihil trepidātiōne opus esse; ut suō iussū circumdūcī Albānum exercitum, ut Fīdēnātium nūda terga invādat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circumeo","latin":"circumeo, circumire, circumivi(ii), circumitus","headword":"circumeo","letter":"c","pos":"verb","posGroup":"verb","english":"encircle, surround; border; skirt; circulate/wander through; go/measure round","forms":["circumeat","circumeunda","circumeundam","circumībat","circumiēns","circumire","circumirentur","circumit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qua re animadversa reliqui ne {{circumirentur}} veriti se fugae mandant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumfero","latin":"circumfero, circumferre, circumtuli, circumlatus","headword":"circumfero","letter":"c","pos":"verb","posGroup":"verb","english":"carry/hand/pass/spread/move/take/cast around (in circle); publicize; divulge","forms":["Circumferēbat","circumferrī","circumlāta","circumlātum","circumtulisse"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Arcam circumferrī iussit circā mūrōs, sacerdōtēsque antecēdere, et tubā canere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circumfulcio","latin":"circumfulcio, circumfulcire, circumfulsi, circumfultus","headword":"circumfulcio","letter":"c","pos":"verb","posGroup":"verb","english":"support/hold up around","forms":["circumfulsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Angelus Dominī stetit iuxtā illōs et clāritās magna {{circumfulsit}} illōs ita ut timērent valdē.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circumfundere","latin":"(circumfundō) circumfundere (< fundere)","headword":"circumfundere","letter":"c","pos":"","posGroup":"other","english":"pour, spread around; pour/spread around","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumfundo","latin":"circumfundo, circumfundere, circumfundi, circumfusus","headword":"circumfundo","letter":"c","pos":"verb","posGroup":"verb","english":"pour/drape/crowd around; cause (water) to go round/part; surround; distribute","forms":["circumfūdit","circumfundi","circumfūsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi neminem in aequum locum sese demittere sed toto undique muro {{circumfundi}} viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumfusus","latin":"circumfusus, circumfusa, circumfusum","headword":"circumfusus","letter":"c","pos":"adjective","posGroup":"adjective","english":"surrounded; draped around; distributed; extra, superfluous","forms":["circumfūsa","circumfūsās","circumfūsī","circumfūsō","circumfūsōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ambieratque Venus superōs collōque parentis\n{{circumfūsa}} suī, \"numquam mihi\" dīxerat, \"ullō\ntempore dūre pater, nunc sīs mītissimus, optō,\nAenēaeque meō, quī tē dē sanguine nostrō\nfēcit avum, quamvīs parvum dēs, optime, nūmen,\ndummodo dēs aliquod! . . .\" Tum pater \"estis\" ait,\n\"caelestī mūnere dignī, quaeque petis prō quōque petis:\ncape, nāta, quod optās!\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circumire","latin":"(circumeō) circumīre (< īre)","headword":"circumīre","letter":"c","pos":"","posGroup":"other","english":"go around/about, outflank; go around, outflank","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circummitto","latin":"circummitto, circummittere, circummisi, circummissus","headword":"circummitto","letter":"c","pos":"verb","posGroup":"verb","english":"send around/to different parts (embassies/missions); send round, flank","forms":["circummittuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Legationes in omnes partes {{circummittuntur}}; quantum gratia, auctoritate, pecunia valent ad sollicitandas civitates nituntur; nacti obsides quos Caesar apud eos deposuerat, horum supplicio dubitantes territant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumplecto","latin":"circumplecto, circumplectere, circumplexi, circumplexus","headword":"circumplecto","letter":"c","pos":"verb","posGroup":"verb","english":"encompass; embrace/clasp; surround/encircle; enclose (w/wall); cover roundabout","forms":["circumplecti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Erat a septentrionibus collis, quem propter magnitudinem circuitus opere {{circumplecti}} non potuerant nostri; necessario paene iniquo loco et leniter declivi castra fecerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumsedeo","latin":"circumsedeo, circumsedere, circumsedi, circumsessus","headword":"circumsedeo","letter":"c","pos":"verb","posGroup":"verb","english":"besiege/invest/blockade; surround, mob (person), beset; sit/live/settle round","forms":["circumsēdit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Igitur Iugurtha oppidum {{circumsēdit}}; vīneīs turribusque et māchinīs omnium generum expugnāre aggreditur, maximē festīnāns tempus lēgātōrum antecapere quōs ante proelium factum Rōmam ab Adherbale missōs audīverat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circumsedere","latin":"(circumsedeō) circumsedēre (< sedēre)","headword":"circumsedēre","letter":"c","pos":"","posGroup":"other","english":"besiege","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumsilio","latin":"circumsilio, circumsilire, -, -","headword":"circumsilio","letter":"c","pos":"verb","posGroup":"verb","english":"leap/spring/hop round","forms":["circumsiliens"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"sed {{circumsiliens}} modo huc modo illuc","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"circumsilire","latin":"(circumsiliō) circumsilīre, circumsiluisse","headword":"circumsilīre","letter":"c","pos":"","posGroup":"other","english":"hop about","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"circumsistere","latin":"(circumsistō) circumsistere, -stetisse","headword":"circumsistere","letter":"c","pos":"","posGroup":"other","english":"surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumsisto","latin":"circumsisto, circumsistere, circumstiti, circumstatus","headword":"circumsisto","letter":"c","pos":"verb","posGroup":"verb","english":"stand/gather/crowd/take a stand around; surround, beset; be on either side","forms":["circumsisterent","circumsisteretur","circumsistit","circumsistunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se {{circumsisterent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumspecto","latin":"circumspectō, -āre, -āvī, -ātum","headword":"circumspectō","letter":"c","pos":"verb","posGroup":"verb","english":"look about, cast a glance","forms":["circumspectat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Stat et oculīs superbīs {{circumspectat}}; fēminās Thēbārum vocat et clāmat: “Cūr Lātōnam ōrātis?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circumspicio","latin":"circumspicio, circumspicere, circumspexi, circumspectus","headword":"circumspicio","letter":"c","pos":"verb","posGroup":"verb","english":"look around/over/for, survey; inspect; search for/seek; examine/review; ponder","forms":["circumspice","circumspicere","Circumspiciēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"īnserere et patriās intus dēprēndere cūrās! dēnique quidquid habet dīves, {{circumspice}}, mundus","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"circumstans","latin":"circumstans, circumstantis","headword":"circumstans","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"by-stander (usu. pl.)","forms":["circumstantēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ecce manipulus meus surgēbat et stābat rēctus; vestrī autem manipulī {{circumstantēs}} venerābantur meum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circumstare","latin":"(circumstō) circumstāre,","headword":"circumstāre","letter":"c","pos":"","posGroup":"other","english":"stand around, surround circumstetisse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumsto","latin":"circumsto, circumstare, circumsteti, circumstatus","headword":"circumsto","letter":"c","pos":"verb","posGroup":"verb","english":"stand/gather/crowd around, surround, beset; be on either side","forms":["circumstant","circumstāre","circumstent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nec quae tē {{circumstent}} deinde perīcula cernis, dēmēns, nec Zephyrōs audīs spīrāre secundōs?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"circumtectus","latin":"circumtectus, circumtecta, circumtectum","headword":"circumtectus","letter":"c","pos":"adjective","posGroup":"adjective","english":"covered, clothed","forms":["circumtēctam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Is vīderat bēluam ūnam cēterīs maiōrem, ac phalerīs rēgis {{circumtēctam}}; exīstimāns illa rēgem vehī, sē prō communī saliite dēvōvit: per mediōs hostēs ad bēluam properāvit, sub illīus ventrem subiit, repefifīs ictibus cōnfossam occīdit, et bēluae lābentis pondere oppressus ipse occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circumtego","latin":"circumtego, circumtegere, circumtexi, circumtectus","headword":"circumtego","letter":"c","pos":"verb","posGroup":"verb","english":"cover round about","forms":["circumtēxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Saūl ipse sua iuvenī arma voluit accommodāre: galeam capitī eius imposuit, lōrīcā pectus {{circumtēxit}}, latus gladiō accīnxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circumtextum","latin":"circumtextum, circumtexti","headword":"circumtextum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"garment inwoven with purple","forms":["circumtextum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et {{circumtextum}} croceō vēlāmen acanthō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"circumvallare","latin":"(circumvāllō) circumvāllāre","headword":"circumvāllāre","letter":"c","pos":"","posGroup":"other","english":"beset, surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumvallo","latin":"circumvallo, circumvallare, circumvallavi, circumvallatus","headword":"circumvallo","letter":"c","pos":"verb","posGroup":"verb","english":"surround with wall/siegeworks; blockade; beset, surround with troops/barriers","forms":["circumvallare","circumvallavit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo {{circumvallavit}}; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumvehere","latin":"(circumvehō) circumvehere (< vehere)","headword":"circumvehere","letter":"c","pos":"","posGroup":"other","english":"go around, travel around","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumvehi","latin":"circumvehī","headword":"circumvehī","letter":"c","pos":"verb","posGroup":"verb","english":"to sail around (a place)","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"circumvehor","latin":"circumvehor, circumvehi, circumvectus sum","headword":"circumvehor","letter":"c","pos":"verb","posGroup":"verb","english":"make rounds of; travel/ride round/in succession/past; flow round (sea)","forms":["circumvectī","circumvectus","circumvehi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci deque his stramenta detrahi mulionesque cum cassidibus equitum specie ac simulatione collibus {{circumvehi}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumvelo","latin":"circumvelo, circumvelare, circumvelavi, circumvelatus","headword":"circumvelo","letter":"c","pos":"verb","posGroup":"verb","english":"cover around, envelop","forms":["circumvelātur"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"quīn etiam laetās mōvēre per āera caudās\nnostraque adūlantēs comitantur vestīgia, dōnec\n[nōs] excipiunt famulae perque ātria marmore tēcta\nad dominam dūcunt: pulchrō sedet illa recessū\nsollemnī soliō, pallamque indūta nitentem\nīnsuper aurātō {{circumvelātur}} amictū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"circumvenio","latin":"circumvenio, circumvenire, circumveni, circumventus","headword":"circumvenio","letter":"c","pos":"verb","posGroup":"verb","english":"encircle, surround; assail, beset; enclose; circumvent; defraud/trick; surpass","forms":["circumvenīre","circumvenirentur","circumvenīrī","circumventa","circumventi","circumventum","circumventus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Fabius centurio quique una murum ascenderant {{circumventi}} atque interfecti muro praecipitabantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"circumvenire","latin":"(circumveniō) circumvenīre","headword":"circumvenīre","letter":"c","pos":"","posGroup":"other","english":"surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"circumverto","latin":"circumverto, circumvertere, circumverti, circumversus","headword":"circumverto","letter":"c","pos":"verb","posGroup":"verb","english":"free (slave) by manumission; (PASS) turn (oneself) round, revolve (round)","forms":["circumversum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Focum pūrum {{circumversum}} cotīdiē, priusquam cubitum eat, habeat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"circumviso","latin":"circumviso, circumvisere, circumvisi, circumvisus","headword":"circumviso","letter":"c","pos":"verb","posGroup":"verb","english":"look round at; glare round upon","forms":["circumvīsere"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Sed anguēs oculīs omnēs {{circumvīsere}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"circumvolito","latin":"circumvolito, circumvolitare, circumvolitavi, circumvolitatus","headword":"circumvolito","letter":"c","pos":"verb","posGroup":"verb","english":"fly around/round about/over; (of horsemen/horses' hooves); frequent; flit","forms":["circumvolitābant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ecce autem avēs {{circumvolitābant}}, et cibōs illōs comedēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"circus","latin":"circus, -ī","headword":"circus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"circle, orbit, Circus Maximus; racecourse, circus; the circus, racecourse; racetrack, circus","forms":["circus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"[{{Circus}} et Amphitheātrum (Forum)]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cis","latin":"cis","headword":"cis","letter":"c","pos":"preposition","posGroup":"preposition","english":"(prp. +acc.) on this side of","forms":["cis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Dā praepositiōnēs cāsūs accūsātīvī!' Discipulus: 'Ad, apud, ante, adversum, {{cis}}, citra, circum, circā, contrā, ergā, extrā, inter, intrā, īnfrā, iuxtā, ob, per, prope, secundum, post, trāns, ultrā, praeter, propter, suprā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cissos","latin":"cissos, cissi","headword":"cissos","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"ivy","forms":["cissē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"in-ficere -iō -fécissē -fectum - tin-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cista","latin":"cista, cistae","headword":"cista","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"chest/box (usu. made of wicker); box for sacred ceremonial objects; ballot box","forms":["cistā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cistā (quā continentur medicāmina)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cisterna","latin":"cisterna, cisternae","headword":"cisterna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cistern; underground/sunken tank/reservoir for water; (or wine L+S); ditch/pit","forms":["cisternae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quid faciāmus hominēs miserrimî et novî generis laby- 73 _ iectîsque vestîmentîs, quae Gîtôn in aditū siccāre coepit, rär_1eus_ mē factus balneum intrāvimus, angustum scîlicet et {{cisternae}} frīgī- aquam frîgidam continet därīae simile, in quô Trimalchiô rēctus stâbat. _ _ _ _ efﬁlgere, nam ‘nihil melius esse’ dîcëbat ‘quam sine lcugn funfîcîruïgi pānis ﬁt turbā lavärî’ et ‘eô ipsô locô aliquandô pistrînum fuisse’.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cistula","latin":"cistula, cistulae","headword":"cistula","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"little/small box/chest; small basket (L+S)","forms":["cistulā","cistulam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Est in cistulā, Amphitryōnis obsignāta signō est.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"citatus","latin":"citātus, -a, -um","headword":"citātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"speeded up, swift","forms":["citāta"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn tigrīs catulīs {{citāta}} raptīs, nec sīc scorpiōs improbus timētur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cite","latin":"cite","headword":"cite","letter":"c","pos":"adverb","posGroup":"adverb","english":"quickly; rapidly","forms":["cite"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Dî{{cite}} aliquid bellî!” Cônsonuëre cornicinēs fünebrî strepitū. Ünus praecī- puê, servus libitînäriî illîus quī inter hôs honestissimus erat, tam valdē intonuit ut tôtam concitāret vîcîniam!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"citer","latin":"citer, citera -um, citerior -or -us, citimus -a -um","headword":"citer","letter":"c","pos":"adjective","posGroup":"adjective","english":"near/on this side; (COMP) nearer; sooner/earlier, urgent; (SUPER) next; least","forms":["citeriōre"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Catilīna pollicērī tabulās novās, prōscrīptiōnem locuplētium, magistrātūs, sacerdōtia, rapīnās, alia omnia quae bellum atque libīdō victōrum fert. ‘Praetereā esse in Hispāniā {{citeriōre}} Pīsōnem, in Maurētāniā cum exercitū P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"citerior","latin":"citerior, citerius","headword":"citerior","letter":"c","pos":"adjective","posGroup":"adjective","english":"nearer; nearer, on this side","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"cithaeron","latin":"Cithaeron, Cithaeronis","headword":"Cithaeron","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cithaeron; (mountain in Boeotia, sacred to Bacchus)","forms":["Cithaerōn"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"orgia nocturnusque vocat clāmōre {{Cithaerōn}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cithara","latin":"cithara, citharae","headword":"cithara","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cithara, lyre; lute, guitar (L+S)","forms":["citharā","citharam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tunc aulicī eī suāsērunt ut aliquem arcesseret, quī {{citharam}} scīret pulsāre, ad dēlīniendum aegrum eius animum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"citimus","latin":"citimus, -a, -um (sup. of citer)","headword":"citimus","letter":"c","pos":"adjective","posGroup":"adjective","english":"nearest","forms":["cītima"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erant autem eae stellae quās numquam ex hōc locō vīdimus, et eae magnitūdinēs omnium quās esse numquam suspicātī sumus — ex quibus erat ea minima quae ultima ā caelō, {{cītima}} ā terrīs, lūce lūcēbat aliēnā.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cito","latin":"citō","headword":"citō","letter":"c","pos":"verb","posGroup":"verb","english":"quickly","forms":["citās","Citātīs","citātō","citius","cito"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōmodo, ait Isaacus, potuistī invenīre tam {{cito}}?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"citra","latin":"citrā","headword":"citrā","letter":"c","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) on this side; on this side of (+ acc.)","forms":["citrā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nē hoc fīat, legiōnēs Rōmānae hīc sunt ac tamdiū remanēbunt dum hostis armātus seu citrā seu ultrā Dānuvium ūllus reliquus erit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"citro: ultro citroque","latin":"citrō: ultrō citrōque","headword":"citrō: ultrō citrōque","letter":"c","pos":"","posGroup":"other","english":"to and fro, on both sides","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"citus","latin":"citus, cita -um, citior -or -us, citissimus -a -um","headword":"citus","letter":"c","pos":"adjective","posGroup":"adjective","english":"quick, swift, rapid; moving/acting/passing/occurring quickly, speedy; early","forms":["citae","Citam","citī","citus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fufium {{Citam}}, honestum equitem Romanum, qui rei frumentariae iussu Caesaris praeerat, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"civile","latin":"civile, civilis","headword":"civile","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"courtesy; civility","forms":["cīvīle"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annō urbis conditae sescentēsimō sexāgēsimō secundō prīmum Rōmae bellum {{cīvīle}} commōtum est, eōdem annō etiam Mithridāticum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"civilis","latin":"cīvīlis, -e","headword":"cīvīlis","letter":"c","pos":"adjective","posGroup":"adjective","english":"civic, civil","forms":["civīlēs","cīvīlī","cīvīlia","cīvīlibus","cīvīlis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et bellum utrimque omnibus vīribus parābātur, cīvīlī bellō simillimum, prope inter parentēs nātōsque, cum Rōmānī ab Albā ortī essent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"civis","latin":"cīvis, cīvis","headword":"cīvis","letter":"c","pos":"noun","posGroup":"noun","english":"(m./f.) citizen","forms":["cīvem","cives","cīvī","cīvibus","cīvīs","civium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit {{cives}} Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"civitas","latin":"cīvitās, -ātis ( f.)","headword":"cīvitās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"state, city, citizenship; state, city; citizenship","forms":["civitas","civitate","civitatem","civitates","civitati","civitatibus","civitatis","civitatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Celeriter ad omnes Galliae {{civitates}} fama perfertur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clades","latin":"clādēs, -is ( f.)","headword":"clādēs","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"disaster, defeat; disaster, destruction; defeat, disaster","forms":["clāde","clādem","clādēs","clādī","clādibus","clādis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēlētus est ūniversus exercitus pharaōnis in mediīs flūctibus, nec ūnus quidem nūntius tantae {{clādis}} superfuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clam","latin":"clam","headword":"clam","letter":"c","pos":"adverb","posGroup":"adverb","english":"secretly","forms":["clam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos {{clam}} ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clamat","latin":"clāmat, clāmant","headword":"clāmat","letter":"c","pos":"verb","posGroup":"verb","english":"shout; shouts, calls out; shouts, cries out; shouts, calls; shouts, exclaims","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"clamitare","latin":"(clāmitō) clāmitāre","headword":"clāmitāre","letter":"c","pos":"","posGroup":"other","english":"shout loudly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"clamito","latin":"clamito, clamitare, clamitavi, clamitatus","headword":"clamito","letter":"c","pos":"verb","posGroup":"verb","english":"cry out, yell; shout repeatedly, clamor; proclaim; name/call repeatedly/loudly","forms":["clāmitābat","clāmitāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec procul iam ā portā Palātiī erat, {{clāmitāns}}: \"Vīcimus perfidōs hospitēs, imbellēs hostēs!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"clamo","latin":"clamo, clamare, clamavi, clamatus","headword":"clamo","letter":"c","pos":"verb","posGroup":"verb","english":"proclaim, declare; cry/shout out; shout/call name of; accompany with shouts","forms":["clāmābant","clāmābat","clāmāns","clāmant","clāmante","clāmantem","clāmantēs","clāmantibus","clāmantium","clāmāre","clāmāret","clāmās","clāmat","clāmāveritis","clāmāvērunt","clāmāvit","clament"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Flōra {{clāmat}}: “Ecce rosae!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"clamor","latin":"clāmor, clāmōris","headword":"clāmor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) shout, shouting; shout, cry; shout, clamour, noise","forms":["clamor","clamore","clāmōrem","clāmōrēs","clamōribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, {{clamore}} per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clanculum","latin":"clanculum","headword":"clanculum","letter":"c","pos":"adverb","posGroup":"adverb","english":"secretly, by stealth; sub rosa; privately (L+S)","forms":["clanculum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Hunc IOiadās pontifex in templō {{clanculum}} aluit atque ēducāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clandestinus","latin":"clandestīnus, -a, -um","headword":"clandestīnus","letter":"c","pos":"adjective","posGroup":"adjective","english":"secret, clandestine","forms":["clandestina","clandestinis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, prius quam eorum {{clandestina}} consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clango","latin":"clango, clangere, clangui, -","headword":"clango","letter":"c","pos":"verb","posGroup":"verb","english":"clang, make ringing noise; sound (horn); scream (eagle); speak w/ringing tone","forms":["clangentibus","clangere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hī, mediā nocte, ingressī castra hostium, coepērunt tubīs {{clangere}}, et collīdere inter sē lagoenās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clangor","latin":"clangor, clangoris","headword":"clangor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"clang, noise; blare/blast (trumpet); crying/clamor (bird); barking/baying (dog)","forms":["clangor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Coepērunt exaudīrī tonitrua, micāre fulgura: nūbēs dēnsa operiēbat montem, et {{clangor}} buccinae vehementius perstrepēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clare","latin":"clare, clarius, clarissime","headword":"clare","letter":"c","pos":"adverb","posGroup":"adverb","english":"aloud; brightly, clearly; lucidly; with distinction/honor, illustriously","forms":["clārē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Amphitryō ad ōstium versus properat, cum subitō ita clārē fulget ac tam validē tonat ut ille quasi mortuus ante forēs concīdat.]","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"claritas","latin":"claritas, claritatis","headword":"claritas","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"clarity/vividness; brightness; distinctness; loudness; celebrity, renown, fame","forms":["clāritās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Angelus Dominī stetit iuxtā illōs et {{clāritās}} magna circumfulsit illōs ita ut timērent valdē.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"claritudo","latin":"clāritūdo, -inis ( f.)","headword":"clāritūdo","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"fame, renown; renown, distinction","forms":["clāritūdinem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Scīpiōnis, quī tum Rōmānīs imperātor erat, et mōrem hostium cognōvit, multō labōre multāque cūrā, praetereā modestissimē pārendō et saepe obviam eundō perīculīs, in tantam {{clāritūdinem}} brevī pervēnit ut nostrīs vehementer cārus, Numantīnīs maximō terrōrī esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"claro","latin":"claro, clarare, claravi, claratus","headword":"claro","letter":"c","pos":"verb","posGroup":"verb","english":"make visible; brighten, light up; make clear, explain; make illustrious/famous","forms":["clārō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ipse rēx deōrum dē clārō Olympō mē dēmīsit, ipse haec mandāta ad tē ferre iussit: Quid struis?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"claros","latin":"claros, clari","headword":"claros","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"beetle infesting beehives; (regarded by Pliny as a disease)","forms":["clārōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Dea Lātōna quoque līberōs {{clārōs}} habēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"clarus","latin":"clārus, -a, -um","headword":"clārus","letter":"c","pos":"adjective","posGroup":"adjective","english":"bright, clear, loud; bright, clear; famous, illustrious, bright, shining, clear","forms":["clāra","clāram","clārī","clāriōra","clāriōre","clāriōribus","clārīs","clārissima","clārissimās","clārissimē","clārissimī","clārissimīs","clārissimō","clārissimōs","clārissimum","clārissimus","clārius","clārōrum","clārum","clārus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Medicus: “Est medicus Graecus {{clārissimus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"classiarii","latin":"classiārii, -ōrum (pl.)","headword":"classiārii","letter":"c","pos":"","posGroup":"other","english":"marines","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"classiarius","latin":"classiārius, -ī","headword":"classiārius","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"marine, sailor","forms":["classiāriōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hārum cum effēcisset magnam multitūdinem, diē ipsō quō factūrus erat nāvāle proelium, {{classiāriōs}} convocat iīsque praecipit 'omnēs ut in ūnam Eumenis rēgis concurrant nāvem; quem sī aut cēpissent aut interfēcissent, magnō iīs' pollicētur 'praemiō fore.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"classis","latin":"classis, classis","headword":"classis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) fleet","forms":["classe","classem","classēs","classī","classibus","classis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postrēmō, cum tam cārum esset frūmentum ac pānis ut multī inopia cibī necessāriī perīrent, populus Rōmānus ūnō ōre postulāvit ut ūniversa {{classis}} Rōmāna ad hostēs illōs audācissimōs mitterētur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"claudere","latin":"claudere, -ō, clausī, clausum","headword":"claudere","letter":"c","pos":"verb","posGroup":"verb","english":"to close, shut; to close","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"claudit","latin":"claudit, claudunt","headword":"claudit","letter":"c","pos":"verb","posGroup":"verb","english":"shut, close; closes, shuts","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"claudius","latin":"Claudius, Claudi","headword":"Claudius","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Claudius; (Roman gens name); Lame","forms":["Claudia","Claudiī","Claudiō","Claudium","Claudius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ōlim, dum per viās ambulant, vir malus at dīves, nōmine {{Claudius}}, quī magnam pecūniam multōsque servōs habēbat, eōs vīdit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"claudo","latin":"claudō, -ere, clausī, clausum","headword":"claudō","letter":"c","pos":"verb","posGroup":"verb","english":"to shut in, close","forms":["claudam","claudē","claudēbant","claudēbantur","claudēbat","claudēbātur","claudere","claudi","claudit","Claudite","clauditur","claudō","claudor","clauduntur","clausēre","clausērunt","clausissem","clausisset","clausit","clausūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quem simul atque oppidani conspexerunt atque in spem auxili venerunt, clamore sublato arma capere, portas {{claudere}}, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"claudus","latin":"claudus, -a, -um","headword":"claudus","letter":"c","pos":"adjective","posGroup":"adjective","english":"lame","forms":["claudōs","claudus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Bellerophōn autem, quamquam ex altō locō cecidit, nōn mortuus est, sed, {{claudus}} et caecus factus, reliquam vītam miserē ēgit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"clausa","latin":"clausa, clausae","headword":"clausa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cell","forms":["clausa"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Altera ē duābus fenestrīs est aperta, altera {{clausa}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"claustrum","latin":"claustrum, claustri","headword":"claustrum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"bolt (gate/door); key; bars (pl.), enclosure; barrier; door, gate, bulwark; dam","forms":["claustra"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"circum {{claustra}} fremunt; celsā sedet Aeolus arce","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"clausum","latin":"clausum, clausi","headword":"clausum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"enclosed space","forms":["clausum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iuppiter magnum illud vās Pandōrae dederat, eīque imperāverat nē umquam illud aperīret, sed {{clausum}} magnā cum cūrā cūstōdīret; nam in illō vāse Iuppiter, quī mortālēs pūnīre volēbat, omnia mala inclūserat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"clausus","latin":"clausus, -a, -um","headword":"clausus","letter":"c","pos":"adjective","posGroup":"adjective","english":"closed, shut; closed","forms":["clausae","clausam","clausās","clausīs","clausō","clausōs","clausus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sōla in cubiculō suō Dōrippa forem {{clausam}} aspicit, tum ad fenestram apertam accēdit, unde Tiberim flūmen spectat et pontem Fabricium, quī dūcit ad parvam īnsulam in mediō pōns pontis flūmine sitam.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"clava","latin":"clāva, -ae","headword":"clāva","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"club, cudgel; club","forms":["clāvā","clāvam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prīmō diē Thēseus prōlem clāviferentem Vulcānī superāvit; posteā {{clāvam}} illīus semper portābat, memoriam prīmae victōriae.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"claves","latin":"claves, clavis","headword":"claves","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"door-key; bar/key for turning a press, lever; hook for bowling a hoop","forms":["clāvēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quem ille casū ministrum oblātum prōmissīs onerat impellitque utī tamquam suam vīsēns domum eat, portārum {{clāvēs}} adulterīnās paret — nam vērae ad Hiempsalem referēbantur; 'cēterum, ubi rēs postulāret, sē ipsum cum magnā manū ventūrum.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"clavis","latin":"clāvis, clāvis","headword":"clāvis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) key","forms":["clāvem","clāvis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus continuō {{clāvem}} prōmit, forēs aperit et canem territum solvit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"clemens","latin":"clēmēns","headword":"clēmēns","letter":"c","pos":"adjective","posGroup":"adjective","english":"(gen.clēmentis) merciful; merciful, gentle","forms":["clēmēns","clēmentem","clēmentēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mercurius vērō, quī duōs hominēs probōs et iūstōs esse nōverat, Iovī suāsit ut {{clēmēns}} esset iīsque parceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"clementer","latin":"clementer, clementius, clementissime","headword":"clementer","letter":"c","pos":"adverb","posGroup":"adverb","english":"leniently, mercifully; mildly/softly; slowly/at an easy rate/gradually, gently","forms":["clēmenter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus eōs {{clēmenter}} salūtāvit, interrogāvitque: salvusne est senex ille quem vōs patrem habētis?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clementia","latin":"clēmentia, -ae","headword":"clēmentia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"clemency, mercy; mercy, clemency","forms":["clēmentia","clēmentiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nihil eā lēgātiōne perfectum est, Perseō rēgium nōmen omnī vī amplectente, Paulō 'ut sē suaque omnia in fidem et {{clēmentiam}} populī Rōmānī permitteret' tendente.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"clibanarius","latin":"clībanārius, -ī (m.)","headword":"clībanārius","letter":"c","pos":"","posGroup":"other","english":"cuirassier; heavily armored soldier","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cliens","latin":"cliens, clientis","headword":"cliens","letter":"c","pos":"noun","posGroup":"noun","english":"client, dependent (of a patron), vassal; client state/its citizens, allies","forms":["clientibus","clientium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis {{clientibus}} facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clientela","latin":"clientela, clientelae","headword":"clientela","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"clientship; vassalage; patronage; protection; clients; vassals; allies (pl.)","forms":["clientelas"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Civitatem esse omnem in armis; divisum senatum, divisum populum, suas cuiusque eorum {{clientelas}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clipeo","latin":"clipeo, clipeare, clipeavi, clipeatus","headword":"clipeo","letter":"c","pos":"verb","posGroup":"verb","english":"provide/arm with a shield (clipeus) or protection","forms":["clipeō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clipeum","latin":"clipeum, clipei","headword":"clipeum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"round/embossed shield (usu. bronze); disk of sun; vault of sky; meteorite","forms":["clipeum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In terram ēgressī Iovī sacrificāvērunt, atque Aenēās {{clipeum}}, quem cuidam hostī adēmerat, ad forēs templī fīxit et hunc versum īnscrīpsit: AENEAS HAEC DE DANAIS VICTORIBVS ARMA.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"clipeus","latin":"clipeus, -ī","headword":"clipeus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"round shield","forms":["Clipeōs","clipeus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Lōrīcā induebātur; ocreās in crūribus āereās habēbat; cassis āerea caput eius operiēbat, et {{clipeus}} aureus tegēbat umerōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"clivum","latin":"clivum, clivi","headword":"clivum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"slope (pl.), incline; sloping ground; inclined passage/surface; (street name)","forms":["clivum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio ascensus recta regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum {{clivum}} accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"clivus","latin":"clīvus, -ī","headword":"clīvus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"slope, sloping street; slope, steep street","forms":["clīvō","clīvus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multae viae ex omnibus urbis partibus in forum ferunt, ut Argīlētum, Sacra via, Nova via, vīcus Tuscus, vīcus Iūgārius, atque {{clīvus}} Capitōlīnus, quō imperātōrēs triumphantes in Capitōlium ascendunt. (\"Clīvus\" dīcitur via quae in clīvō montis facta est.) In summā Sacrā viā īnfrā clīvum Palātīnum est arcus Titī, dē quō mox dīcendum erit, et templum Iovis Stātōris.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cloaca","latin":"cloāca, -ae","headword":"cloāca","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"sewer","forms":["cloāca","cloācam","cloācīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In eā valle ōlim magna palūs erat, quae tum dēmum siccāta est cum aqua palūdis in flūmen dēdūcerētur per {{cloācam}} subterrāneam, quae appellātur \"cloāca Maxima\".","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cloanthusus","latin":"Cloanthusus, Cloanthi","headword":"Cloanthusus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cloanthus; (Trojan companion of Aeneas)","forms":["Cloanthum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fāta Lycī, fortemque Gyān, fortemque {{Cloanthum}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"clodus","latin":"clodus, cloda, clodum","headword":"clodus","letter":"c","pos":"adjective","posGroup":"adjective","english":"limping, lame; defective/crippled/imperfect; uneven/halting/wavering/uncertain","forms":["Clodi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ibi cognoscit de {{Clodi}} caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cludo","latin":"cludo, cludere, clusi, clusus","headword":"cludo","letter":"c","pos":"verb","posGroup":"verb","english":"close, shut, block up; conclude, finish; blockade, besiege; enclose; confine","forms":["clūdere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{clūdere}} -sīsse -sum - claudere, in-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cluens","latin":"cluens, cluentis","headword":"cluens","letter":"c","pos":"noun","posGroup":"noun","english":"client, dependent (of a patron), vassal; client state/its citizens, allies","forms":["Cluentium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pompeiō, maximē tamen ā Cornēliō Sullā, quī inter alia ēgregia ita {{Cluentium}}, hostium ducem, cum magnīs cōpiīs fūdit ut ex suīs ūnum amitteret!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"clueo","latin":"clueo, cluere, -, -","headword":"clueo","letter":"c","pos":"verb","posGroup":"verb","english":"be called, be named, be reputed/spoken of/said to be; be reckoned as existing","forms":["clueat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"datur mī, ut meus victor vir bellī {{clueat}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"clymenus","latin":"clymenus, clymeni","headword":"clymenus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"plant, scorpion's tail (Scorpiurus vermiculata)","forms":["Clymenē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Promētheus fuit fīlius Tītānī, nōmine Īapetī, et Nymphae, quae Clymenē appellābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cn","latin":"Cn., abb.","headword":"Cn","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Gnaeus (Roman praenomen); (abb. Cn.)","forms":["Cn"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"His rebus in Italiam Caesari nuntiatis, cum iam ille urbanas res virtute {{Cn}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coa","latin":"coa, coae","headword":"coa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"lustful woman; (wearing fine Coan silk?); fictitious nickname of Clodia (L+S)","forms":["Cōa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"pl, vestīmenta {{Cōa}}; *Cōā decēre'","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"coacervo","latin":"coacervo, coacervare, coacervavi, coacervatus","headword":"coacervo","letter":"c","pos":"verb","posGroup":"verb","english":"heap/pile up, gather/crowd together; amass, collect; make by heaping; add/total","forms":["coacervantur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Praesidio legionum addito nostris animus augetur: hostes in fugam coiecti se ipsi multitudine impediunt atque angustioribus portis relictis {{coacervantur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coacto","latin":"coacto, coactare, coactavi, coactatus","headword":"coacto","letter":"c","pos":"verb","posGroup":"verb","english":"compel; constrain; force","forms":["coacto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His suppliciis celeriter {{coacto}} exercitu, Lucterium Cadurcum, summae hominem audaciae, cum parte copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coactum","latin":"coactum, coacti","headword":"coactum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"thick/fulled covering; mattress","forms":["coactum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Iam Caesar a Gergovia discessisse audiebatur, iam de Aeduorum defectione et secundo Galliae motu rumores adferebantur, Gallique in colloquiis interclusum itinere et Ligere Caesarem inopia frumenti {{coactum}} in provinciam contendisse confirmabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coactus","latin":"coactus, coactus","headword":"coactus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"compulsion, constraint, force, coercion","forms":["coāctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē prōcūrātiōnem regnl {{coāctus}} est relinquere IOathae fīliō, qul rēctē imperium administrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"coaequo","latin":"coaequo, coaequare, coaequavi, coaequatus","headword":"coaequo","letter":"c","pos":"verb","posGroup":"verb","english":"make level/equal, equalize; regard/treat as equal, equate; adjust by weighing","forms":["coaequandīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Etenim quis mortālium, cui virīle ingenium est, tolerāre potest illīs dīvitiās superāre, quās profundant in exstruendō marī et montibus {{coaequandīs}} — nōbīs rem familiārem etiam ad necessāriā dēesse? illōs bīnās aut amplius domōs continuāre — nōbīs Larem familiārem nusquam ūllum esse?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"coagmento","latin":"coagmento, coagmentare, coagmentavi, coagmentatus","headword":"coagmento","letter":"c","pos":"verb","posGroup":"verb","english":"join/fasten together, connect; make by joining/construct; fit (words) together","forms":["coagmentatis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His collocatis et {{coagmentatis}} alius insuper ordo additur, ut idem illud intervallum servetur neque inter se contingant trabes, sed paribus intermissae spatiis singulae singulis saxis interiectis arte contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coalescere","latin":"(coalēscō) coalēscere, -uisse, -itum","headword":"coalēscere","letter":"c","pos":"verb","posGroup":"verb","english":"grow together, coalesce; to grow together, unite","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"coalesco","latin":"coalesco, coalescere, coalui, coalitus","headword":"coalesco","letter":"c","pos":"verb","posGroup":"verb","english":"join/grow together; coalesce; close (wound); become unified/strong/established","forms":["coalēscere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēbus dīvīnīs rīte factīs vocātāque ad concilium multitūdine, quae {{coalēscere}} in ūnum populum nōn poterat nisi lēgibus, Rōmulus iūra dedit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coangusto","latin":"coangusto, coangustare, coangustavi, coangustatus","headword":"coangusto","letter":"c","pos":"verb","posGroup":"verb","english":"confine to narrow space, cramp; make narrower; narrow/limit scope/application","forms":["coangustābunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et ut appropinquāvit Hierosolymae, vidēns cīvitātem, flēvit super illam, dīcēns:\"Veniet diēs quā circumdabunt tē inimicī tuī vāllō et {{coangustābunt}} tē undique.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"coarguo","latin":"coarguo, coarguere, coargui, -","headword":"coarguo","letter":"c","pos":"verb","posGroup":"verb","english":"refute; show, demonstrate; overwhelm w/proof; silence; convict; prove guilty","forms":["coarguunt"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eadem Gallī fatentur, ac Lentulum dissimulantem {{coarguunt}}, praeter litterās, sermōnibus quōs ille habēre solitus erat: ex lībrīs Sibyllīnīs rēgnum Rōmae tribūs Cornēliīs portendī: Cinnam atque Sullam anteā, sē tertium esse cui fātum foret urbis potīrī!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"coccinum","latin":"coccinum, coccini","headword":"coccinum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"scarlet-dyed/scarlet clothes/garments/coverings (pl.)","forms":["coccinā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hinc, involūtus coccinā gausapā, lectīcae impositus est, praecēdentibus phalerātis cursôribus quattuor et chîra- maxiô in quô dēliciae eius vehēbantur, puer vetulus, lippus, dominô Trimalchī- ône dëfôrmior.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"coccinus","latin":"coccinus, coccina, coccinum","headword":"coccinus","letter":"c","pos":"adjective","posGroup":"adjective","english":"dyed scarlet, scarlet-dyed; scarlet, of scarlet color","forms":["coccine"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Palliô enim {{coccine}}ô adrāsum exclūserat caput, circäque onerātās veste cer- vîcës lāticlāviam immîserat mappam ﬁmbriîs hinc atque illinc pendentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cochlear","latin":"cochlear, cochlearis","headword":"cochlear","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"spoon; (originally for extracting snails); spoonful","forms":["cochleāria"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Temptēmus tamen, Accipimus nôs {{cochleāria}} nôn minus sëlîbräs pertundimus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cochlos","latin":"cochlos, cochli","headword":"cochlos","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"kind of marine gastropod; (with spiral shell)","forms":["cochle"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cônstemätî nôs însolentiä ëbriôrum intentāvī- que ē gastñs lābentia, quae collēcta puer lance circum- Hās lautitiās aequāvit ingeniôsus cocus: in crätîculä enim argenteā {{cochle}}âs attulit et tremulā taeterrimāque Pudet referre quae secuntur: inaudîtô enim môre puerî capillätî attulērunt unguentum in argenteā pēlve pedësque recumbentium ūnxērunt, cum ante crūra tälôsque corônîs vînxissent.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cocles","latin":"Cocles, Coclitis","headword":"Cocles","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"one-eyed person; Horatius (who kept Etruscans from Subician bridge)","forms":["Cocles"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Equidem nōn ante recēdām quam pōns lāpsus erit.” Hic fortissimus mīles Horātius appellābātur, cognōmen vērō eius ‘{{Cocles}}’ erat, nam alterō oculō carēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"coco","latin":"coco, cocere, coxi, coctus","headword":"coco","letter":"c","pos":"verb","posGroup":"verb","english":"cook; boil, fry, bake; burn, parch (sun); stir up; ripen, mature (plot); digest","forms":["coc","cocō","coxērunt","coxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc iussit angelus fel piscis sēpōnī, utpote medicāmentum salūtāre; deinde partem carnis {{coxērunt}} comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"coctum","latin":"coctum, cocti","headword":"coctum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cooked food; smelted ore","forms":["coctum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Nostrum ānserem occīdēmus et {{coctum}} appōnēmus.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"coctus","latin":"coctus, cocta -um, coctior -or -us, coctissimus -a -um","headword":"coctus","letter":"c","pos":"adjective","posGroup":"adjective","english":"cooked; roasted, burnt; smelted; baked (bricks); ripened, ripe; softened, mild","forms":["coctās","coctus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nimis tardus nōbis vidēris esse.” Tantalus vērō, quī cibīs carēbat, fīlium parvum, nōmine Pelopem, quem domī ēducāverat, eō cōnsiliō vocāvit ut eum necāret eiusque carnēs {{coctās}} deīs in convīviō cubantibus appōneret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cocus","latin":"cocus, -ī","headword":"cocus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cook","forms":["cocum","cocus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"(Servus cuius negōtium est cibum coquere atque cōnficere in culīnā, {{cocus}} appellātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"coemo","latin":"coemo, coemere, coemi, coemptus","headword":"coemo","letter":"c","pos":"verb","posGroup":"verb","english":"buy; buy up","forms":["coemptum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huc Caesar omnes obsides Galliae, frumentum, pecuniam publicam, suorum atque exercitus impedimentorum magnam partem contulerat; huc magnum numerum equorum huius belli causa in Italia atque Hispania {{coemptum}} miserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coeo","latin":"coeo, coire, coivi(ii), coitus","headword":"coeo","letter":"c","pos":"verb","posGroup":"verb","english":"fit together; have sexual intercourse; collect/gather (fluid); meet; rally","forms":["coeāmus","Coeō","coeundī","coeunt","coeuntibus","Cōī","Cōīs","coit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum etiam atque etiam Narcissus vōcem audīvisset ad suās vōcēs respondentem, nēminem tamen vīdisset, per silvāsam ambulāre perrēxit; cum vērō ad apertum campum arboribus circumdatum pervēnisset, “Hūc {{coeāmus}}” dīxit magnā vōce.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"coepi","latin":"coepī, coepisse","headword":"coepī","letter":"c","pos":"verb","posGroup":"verb","english":"began (defective, no present system)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"coepio","latin":"coepio, coepere, coepi, coeptus","headword":"coepio","letter":"c","pos":"verb","posGroup":"verb","english":"begin, commence, initiate; set foot on; (usu. PERF PASS w/PASS INF; PRES early)","forms":["coeperam","coeperant","coeperat","coepēre","coeperunt","coepī","coepimus","coepisse","coepisset","coepistī","coepit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cenabenses paulo ante mediam noctem silentio ex oppido egressi flumen transire {{coeperunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coepisse","latin":"coepisse","headword":"coepisse","letter":"c","pos":"verb","posGroup":"verb","english":"to have begun (defective)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"coepta","latin":"coepta, -ōrum (pl.)","headword":"coepta","letter":"c","pos":"","posGroup":"other","english":"beginnings, undertakings","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"coepto","latin":"coepto, coeptare, coeptavi, coeptatus","headword":"coepto","letter":"c","pos":"verb","posGroup":"verb","english":"begin/commence (w/INF); set to work, undertake/attempt/try; venture/begin (ACC)","forms":["coeptō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Dà veniam coeptō, Iuppiter","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"coeptum","latin":"coeptum, coepti","headword":"coeptum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"undertaking (usu.pl.), enterprise, scheme; work begun/started/taken in hand","forms":["coepta","coeptī","coeptīs","coeptum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Auxilium ā tē petō!” Vix precēs dīxerat, cum subitō membra cōnstitērunt et corpus cortice operīrī {{coeptum}} est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"coeptus","latin":"coeptus, coepta, coeptum","headword":"coeptus","letter":"c","pos":"adjective","posGroup":"adjective","english":"begun, started, commenced; undertaken","forms":["coeptae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nōn {{coeptae}} adsurgunt turrēs, nōn arma iuventūs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"coerceo","latin":"coerceo, coercere, coercui, coercitus","headword":"coerceo","letter":"c","pos":"verb","posGroup":"verb","english":"enclose, confine; restrain, check, curb, repress; limit; preserve; punish","forms":["coercēre","coercērent","coercēret","Coercitī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Coercitī ab līctōre et iussī ōrdine loquī, tandem clāmāre dēsistunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coercere","latin":"(coerceō) coercēre, -cuisse, -citum","headword":"coercēre","letter":"c","pos":"","posGroup":"other","english":"keep in control, restrain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"coetus","latin":"coetus, -ūs (< coīre Cap. LI)","headword":"coetus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"gathering, society; gathering, assembly","forms":["coetū","coetum","coetus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"eōs auspiciō meō atque ductū prīmō coetū vīcimus.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"cogere","latin":"(cōgō) cōgere, coēgisse, coāctum","headword":"cōgere","letter":"c","pos":"verb","posGroup":"verb","english":"compel, force; to compel, gather","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"cogitare","latin":"cōgitāre","headword":"cōgitāre","letter":"c","pos":"verb","posGroup":"verb","english":"to think","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"cogitatio","latin":"cōgitātiō, -ōnis ( f.)","headword":"cōgitātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"thought, reflection","forms":["cōgitātiōne","cōgitātiōnēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Thēseus ad Graeciam redīret, aut commōtus {{cōgitātiōne}} laetitiae patris aut rēgis oblītus nāvem vēlō albō nōn ōrnāvit; Aegeus, quī vēlum ātrum ex arce vīdit, sē in mare iēcit et mortuus est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cogito","latin":"cōgitō, cōgitāre","headword":"cōgitō","letter":"c","pos":"verb","posGroup":"verb","english":"think","forms":["cōgitā","cōgitābam","cogitabat","cōgitābis","Cōgitāmus","cōgitandum","cogitans","cōgitant","cogitanti","cōgitāre","cōgitāret","cōgitārī","cōgitās","cōgitat","cōgitāvisse","cōgitāvit","cōgitent","cōgitēs","cōgitō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Haec {{cogitanti}} accidere visa est facultas bene rei gerendae.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cognatio","latin":"cognatio, cognationis","headword":"cognatio","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"blood relation/relationship; kinsmen/relatives, family; consanguinity; affinity","forms":["cognationis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae {{cognationis}}, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cognatus","latin":"cognātus, -a, -um","headword":"cognātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"related","forms":["cognātam","cognātī","cognātīs","cognātō","cognātōs","cognātum","cognātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā Abrahamus mīsit servum suum Eliezerem ad {{cognātōs}} suōs quī erant in Mesopotamiā, ut inde addūceret uxōrem fīliō suō Isaacō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cognitio","latin":"cognitiō, -ōnis ( f.)","headword":"cognitiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"getting to know, study","forms":["cōgnitiō","cognitiōne","Cognitiōnibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac mē hercule etiam tē ipsum, Laelī, omnēsque avidōs sapientiae cōgnitiō ipsa rērum cōnsīderātiōque dēlectat.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cognitus","latin":"cognitus, cognita, cognitum","headword":"cognitus","letter":"c","pos":"adjective","posGroup":"adjective","english":"known (from experience/carnally)), tried/proved; noted, acknowledged/recognized","forms":["cognita","cognitis","cognito","cognitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Cognito}} eius consilio ad arma concurritur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cognomen","latin":"cognōmen, -inis","headword":"cognōmen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) surname; surname, family name","forms":["cognōmen","cognōmine"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Equidem nōn ante recēdām quam pōns lāpsus erit.” Hic fortissimus mīles Horātius appellābātur, {{cognōmen}} vērō eius ‘Cocles’ erat, nam alterō oculō carēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cognomentum","latin":"cognōmentum, -ī","headword":"cognōmentum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"surname; surname, additional name","forms":["cognōmentō","cognōmentum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā Pythagorās Samius in Italiam vēnit, Tarquinī fīliō regnum obtinente, cui {{cognōmentum}} Superbus fuit; iīsdemque temporibus occīsus est Athēnīs ab Harmodiō et Aristogītōne Hipparchus, Pīsistratī fīlius, Hippiae tyrannī frāter.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cognomino","latin":"cognomino, cognominare, cognominavi, cognominatus","headword":"cognomino","letter":"c","pos":"verb","posGroup":"verb","english":"give surname/epithet/sobriquet to person; name, give specific name, call","forms":["cognōminābātur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Intrāvit autem Satanās in IŪdam, quī {{cognōminābātur}} Iscariōtēs, ūnum dē duodecim.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cognoscere","latin":"(cognōscō) cognōscere, -nōvisse, -nitum","headword":"cognōscere","letter":"c","pos":"verb","posGroup":"verb","english":"get to know, recognize; to recognise, get to know; to recognise, find out; to recognize, find out; to learn, find out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cognoscit","latin":"cognōscit","headword":"cognōscit","letter":"c","pos":"verb","posGroup":"verb","english":"recognises, gets to know","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cognosco","latin":"cognosco, cognoscere, cognovi, cognitus","headword":"cognosco","letter":"c","pos":"verb","posGroup":"verb","english":"become acquainted with/aware of; recognize; learn, find to be; inquire/examine","forms":["cognitum","cognōscam","cognōscant","cognōscat","cognoscebat","cognoscendum","cognoscere","cognōscerent","cognōsceret","cognōscerētur","cognōscēs","cognōscet","cognoscētis","cognōscī","cognōscis","cognoscit","cognoscite","cognōscitur","cognōscō","cognoscunt","cognōveram","cognōverant","cognōverat","cognōvēre","cognoverint","cognoverunt","cognōvī","cognōvisse","cognovissent","cognōvisset","cognovit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi {{cognoscit}} de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cogo","latin":"cōgō, -ere, coēgī, coāctum","headword":"cōgō","letter":"c","pos":"verb","posGroup":"verb","english":"force, compel, gather","forms":["coacta","coactae","coāctī","coactis","coēgerat","coēgēre","coēgērunt","coēgī","coēgistī","coegit","cogant","cogat","cogatur","cōgēbat","cogendi","cōgendum","cōgente","cogentur","cogere","cogerentur","cōgerēris","cōgeret","cogeretur","cōgī","cōgis","cogit","cōgitur","cogundī","cogunt","coguntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac {{coacta}} manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cohaerentia","latin":"cohaerentia, cohaerentiae","headword":"cohaerentia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cohesion, sticking/combining together; organic structure; being time contiguous","forms":["cohaerentia"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nōmen ipsum, sī flāgitiīs careat, an flāgitia {{cohaerentia}} nōminī pūniantur?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cohaereo","latin":"cohaereo, cohaerere, cohaesi, cohaesus","headword":"cohaereo","letter":"c","pos":"verb","posGroup":"verb","english":"stick/cling/hold/grow together, adhere; embrace; touch, adjoin, be in contact","forms":["cohaerent"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Dumque sīc {{cohaerent}}, Habinnās ﬁîrtim cônsurrëxit pedësque Fortü- nâtae correptôs super lectum immîsit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"coheres","latin":"coheres, coheredis","headword":"coheres","letter":"c","pos":"noun","posGroup":"noun","english":"co-heir; joint heir","forms":["cohērēdem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quid multa? {{cohērēdem}} mē Caesarî tëcit, et accëpî patrimônium lātī- “Nëminî tamen nihil satis est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cohibeo","latin":"cohibeō, -ēre, -uī, -itum","headword":"cohibeō","letter":"c","pos":"verb","posGroup":"verb","english":"to hold in, confine","forms":["cohibēbantur","cohibuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"At Dāvīd eōs {{cohibuit}}: “Sinite” inquit “istum mihi maledīcere; forsitan Deus, hīs quae patior malīs plācātus, meī miserēbitur, et meum dolōrem respiciet.” Incrēdibilem rēgis patientiam admīrātī, comitēs dictō aegrē pāruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cohorrescere","latin":"(cohorrēscō) cohorrēscere","headword":"cohorrēscere","letter":"c","pos":"verb","posGroup":"verb","english":"shudder; to shudder, be terrified","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"cohorresco","latin":"cohorresco, cohorrescere, cohorrui, -","headword":"cohorresco","letter":"c","pos":"verb","posGroup":"verb","english":"shudder; shiver/shake (from emotion/fear/cold/illness)","forms":["cohorruī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quem ubi agnōvī, equidem cohorruī; sed ille 'Ades' inquit 'animō et omitte timōrem, Scīpiō, et quae dīcam trade memoriae!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cohors","latin":"cohors, cohortis","headword":"cohors","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) cohort","forms":["cohors","cohortem","cohortes","cohortibus","cohortium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque, ne id accideret, silvestri loco castris positis e regione unius eorum pontium quos Vercingetorix rescindendos curaverat, postero die cum duabus legionibus in occulto restitit; reliquas copias cum omnibus impedimentis, ut consueverat, misit, apertis quibusdam {{cohortibus}}, uti numerus legionum constare videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cohortatio","latin":"cohortātiō, -ōnis ( f.)","headword":"cohortātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"exhortation","forms":["cohortātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tālī {{cohortātiōne}} mīlitum factā, classis ab utrīsque in proelium dēdūcitur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cohortor","latin":"cohortor, cohortari, cohortatus sum","headword":"cohortor","letter":"c","pos":"verb","posGroup":"verb","english":"encourage, cheer up; exhort, rouse, incite; admonish","forms":["cohortabatur","cohortārī","cohortatur","cohortatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Itaque {{cohortatus}} Aeduos de supportando commeatu, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium impetum magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coicio","latin":"coicio, coicere, cojeci, cojectus","headword":"coicio","letter":"c","pos":"verb","posGroup":"verb","english":"throw/put/pile together; conclude, infer, guess; assign, make go; classify, put","forms":["coicere","coiciunt","coiciuntur","coiecti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi septima legio constiterat, hostes pelluntur atque in fugam {{coiciuntur}}; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coire","latin":"(coēo) coīre (< īre)","headword":"coīre","letter":"c","pos":"","posGroup":"other","english":"come together, gather","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cola","latin":"cola, colae","headword":"cola","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"strainer","forms":["cōla"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dépexaeque iubae plausaque {{cōla}} — QQuadrupēdēs inter rapidī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"colchis","latin":"Colchis, -idis","headword":"Colchis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Colchis (a country on the Black Sea)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"colchos","latin":"Colchos, Colchi","headword":"Colchos","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Colchis; (land at east end of Black Sea, home of Medea)","forms":["Colchī","Colchīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Frāter diū flēvit; ipse tamen nōn cecidit, sed usque ad Asiae terram volāvit, quae {{Colchīs}} appellātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"colere","latin":"(colō) colere, coluisse, cultum","headword":"colere","letter":"c","pos":"verb","posGroup":"verb","english":"cultivate; to cultivate, farm; to till, cultivate, honour, worship","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"colis","latin":"colis, colis","headword":"colis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"stalk/stem; stem of a cabbage/lettuce/etc; cabbage/lettuce; quill; penis","forms":["colis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Iūlius frontem contrahit et 'Agricola' inquit 'ipse nōn sum, sed multīs agricolīs praesum ac dīligenter cūrō ut colōnī agrōs meōs bene cōlant.' Orontēs, quī vīta rūstica nōn fruitur, 'Prūdenter facis' inquit 'quod agrōs ipse nōn {{colis}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"colit","latin":"colit","headword":"colit","letter":"c","pos":"verb","posGroup":"verb","english":"cultivates, farms","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"collabi","latin":"(collābor) collābī (< lābī)","headword":"collābī","letter":"c","pos":"","posGroup":"other","english":"fall down, collapse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"collabor","latin":"collabor, collabi, collapsus sum","headword":"collabor","letter":"c","pos":"verb","posGroup":"verb","english":"collapse, fall down/in ruin; fall in swoon/exhaustion/death; slip/slink (meet)","forms":["collāpsam","collāpsās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aedēs Concordiae antīqua eō tempore aedificāta esse dīcitur cum post longam discordiam, quae populum Rōmānum dīvīserat in duās factiōnēs inter sē inimīcissimās, patriciōs et plēbēiōs, tandem concordia omnium {{collāpsam}} in meliōrem faciem restituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"collacrimare","latin":"(collācrimō) collācrimāre","headword":"collācrimāre","letter":"c","pos":"","posGroup":"other","english":"burst into tears","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"collacrimo","latin":"collacrimo, collacrimare, collacrimavi, collacrimatus","headword":"collacrimo","letter":"c","pos":"verb","posGroup":"verb","english":"weep together, weep in company of someone; weep over/for (w/ACC); bewail","forms":["collacrimāns","collacrimāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde cēterōs quoque frātrēs {{collacrimāns}} ōsculātus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"collaudare","latin":"(collaudō) collaudāre","headword":"collaudāre","letter":"c","pos":"","posGroup":"other","english":"commend, praise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"collaudo","latin":"collaudo, collaudare, collaudavi, collaudatus","headword":"collaudo","letter":"c","pos":"verb","posGroup":"verb","english":"praise/extol highly; commend; eulogize","forms":["collaudābant","collaudatis","collaudāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum, {{collaudatis}} Carnutibus, dato iure iurando ab omnibus qui aderant, tempore eius rei constituto ab concilio disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"collecta","latin":"collecta, collectae","headword":"collecta","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"contribution; collection; meeting/assemblage (L+S); Collect at Mass (eccl.)","forms":["collēctā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"lēctā (: collēctā) vēnit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"collectio","latin":"collēctiō, -ōnis ( f.)","headword":"collēctiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"collecting, gathering","forms":["collēctiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prīmum ex suō rēgnō sīc Mithridātēs profūgit ex eōdem Pontō, quō Medēa illa quondam profūgisse dīcitur, quam praedicant in fugā frātris suī membra in iīs locīs quā sē parēns persequerētur dissipāvisse, ut eōrum collēctiō dispersa maerorque paternus celeritātem persequendī retardāret!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"collectus","latin":"collectus, collecta -um, collectior -or -us, collectissimus -a -um","headword":"collectus","letter":"c","pos":"adjective","posGroup":"adjective","english":"compact (of style), concise; restricted; contracted, narrow; shut (Ecc)","forms":["collēctās","collēctī","collēctīs","collēctō","collēctōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Brevī rēgem paenituit, quod tot mīlia hominum dīmīsisset, et, collēctō ingentī exercitū, eōs persecūtus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"collega","latin":"collēga, -ae (m.)","headword":"collēga","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"colleague; colleague in office","forms":["collēgā","collēgae","collēgam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et {{collēgae}} quidem meî rîsërunt; ego autem, collëctô spī- rītū, nôn dëstitî tôtum parietem persequî.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"collegium","latin":"collegium, collegi(i)","headword":"collegium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"college/board (priests); corporation; brotherhood/guild/company/society/school","forms":["Collegio"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hae scaenae moventēs factae sunt ā discipulīs dē {{Collegio}} Highland Park; magistra eōrum, Cyril Miles et coniūnx Arnold, pictūram moventem fēcērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"collido","latin":"collido, collidere, collisi, collisus","headword":"collido","letter":"c","pos":"verb","posGroup":"verb","english":"strike/dash together; crush, batter, deform; set into conflict with each other","forms":["collīdere","collīditur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hī, mediā nocte, ingressī castra hostium, coepērunt tubīs clangere, et {{collīdere}} inter sē lagoenās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"colliga","latin":"colliga, colligae","headword":"colliga","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"place/cave for gathering natron (native sesquicarbonate of soda from dripping)","forms":["colliga"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"\"Līctor, {{colliga}} manūs!\" Accesserat līctor iniciēbatque laqueum collō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"colligare","latin":"(colligō) colligāre","headword":"colligāre","letter":"c","pos":"","posGroup":"other","english":"tie up, bind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"colligere","latin":"(colligō) colligere (< legere)","headword":"colligere","letter":"c","pos":"","posGroup":"other","english":"gather, collect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"colligo","latin":"colligo, colligere, collegi, collectus","headword":"colligo","letter":"c","pos":"verb","posGroup":"verb","english":"collect, assemble, bring/gather/hold/keep together; combine; harvest; pick up","forms":["collēgerat","collēgērunt","collēgisset","collēgit","colligāre","colligat","collige","colligendi","colligendō","colligere","colligī","colligit","Colligite","colligunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Item ex reliquis partibus nostri cedentes usque in castra insecuti sui {{colligendi}} facultatem non dederunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"collino","latin":"collino, collinere, collevi, collitus","headword":"collino","letter":"c","pos":"verb","posGroup":"verb","english":"besmear, smear over; soil, pollute, defile","forms":["Collīnam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rūrsus pugnam gravissimam habuit contrā Lampōnium et Carinātem, ducēs partis Mariānae, ad portam {{Collīnam}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"collis","latin":"collis, collis","headword":"collis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) hill","forms":["colle","collem","colles","collibus","collis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Collis}} erat leniter ab infimo acclivis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"collocare","latin":"(collocō) collocāre","headword":"collocāre","letter":"c","pos":"","posGroup":"other","english":"place","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"colloco","latin":"colloco, collocare, collocavi, collocatus","headword":"colloco","letter":"c","pos":"verb","posGroup":"verb","english":"place/put/set in order/proper position, arrange; station, post, position; apply","forms":["collocantur","collocārī","collocat","collocāta","collocatis","collocātum","collocātus","collocaverat","collocāvērunt","collocavit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar {{collocaverat}} Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"colloquium","latin":"colloquium, -ī","headword":"colloquium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"conversation","forms":["Colloquia","Colloquiī","colloquiis","colloquiō","colloquium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iam Caesar a Gergovia discessisse audiebatur, iam de Aeduorum defectione et secundo Galliae motu rumores adferebantur, Gallique in {{colloquiis}} interclusum itinere et Ligere Caesarem inopia frumenti coactum in provinciam contendisse confirmabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"colloquor","latin":"colloquor, colloquī","headword":"colloquor","letter":"c","pos":"verb","posGroup":"verb","english":"converse","forms":["collocuti","collocūtus","colloquēmur","colloquentem","colloquerentur","colloquī","colloquitur","colloquuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, sollicitatus ab Arvernis pecunia cum quibusdam adulescentibus {{colloquitur}}; quorum erat princeps Litaviccus atque eius fratres amplissima familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"colluceo","latin":"colluceo, collucere, colluxi, -","headword":"colluceo","letter":"c","pos":"verb","posGroup":"verb","english":"shine brightly, light up (with fire); reflect light, shine, be lit up; glitter","forms":["collūcent","collūcēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iam mare turbārī trabibus saevīsque vidēbis {{collūcēre}} facēs, iam fervēre lītora flammīs, sī tē hīs attigerit terrīs aurōra morantem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"colludo","latin":"colludo, colludere, collusi, collusus","headword":"colludo","letter":"c","pos":"verb","posGroup":"verb","english":"play/sport together/with; (also) make sport; act in collusion (with)","forms":["collūdunt"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Iam pistôribus {{collūdunt}}: “Servā mē, serväbô tē!” Itaque populus minūtus labôrat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"collum","latin":"collum, -ī","headword":"collum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"neck","forms":["colla","collī","collō","collum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faustīnus: “Et in collō ovis meae sunt vestīgia dentium canis tuī!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"colo","latin":"colo, colere, colui, cultus","headword":"colo","letter":"c","pos":"verb","posGroup":"verb","english":"live in (place), inhabit; till, cultivate, promote growth; foster, maintain","forms":["colam","cōlāmus","cōlant","cōlantur","cōlat","cole","colēbant","colēbat","colenda","colendī","colendīs","colendō","colendōs","colendum","colere","colerem","colerent","coleret","coleris","colit","colite","colitis","colitō","colitur","coluerat","coluēre","coluerīs","coluerit","coluērunt","coluimus","coluisse","coluit","colunt","coluntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum ēiēcit Adamum et Ēvam ex hortō, ut ille {{coleret}} terram, et collocāvit Angelum, quī praeferēbat manū gladium igneum, ut cūstōdīret aditum Paradīsī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"colonia","latin":"colōnia, -ae","headword":"colōnia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"settlement, colony; colony, settlement","forms":["colōniae","colōniam","colōniīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et continuātō in alterum annum tribūnātū, lēgibus agrāriīs lātīs effēcit ut complūrēs {{colōniae}} in Italiā dēdūcerentur et ūna in solō dīrutae Carthāginis, quō ipse triumvir creātus colōniam dēdūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"colonus","latin":"colōnus, -ī","headword":"colōnus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(tenant) farmer; tenant farmer","forms":["colōnī","colōnīs","colōnō","colōnōs","colōnum","colōnus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Agrī Iūliī nōn ā dominō ipsō coluntur, sed ā {{colōnīs}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"color","latin":"color, colōris","headword":"color","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) color; colour","forms":["color","colore","colōrem","colōribus","colōris","colōrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eius adventu ex {{colore}} vestitus cognito, quo insigni in proeliis uti consuerat, turmisque equitum et cohortibus visis quas se sequi iusserat, ut de locis superioribus haec declivia et devexa cernebantur, hostes proelium committunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"colossus","latin":"Colossus, Colossi","headword":"Colossus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Colossus of Rhodes (colossal statue in harbor); any large statue (Emperor)","forms":["Colossus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In vestibulō stābat ingēns statua tyrannī ex aere facta, quae {{Colossus}} appellābātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"columba","latin":"columba, -ae","headword":"columba","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"pigeon, dove","forms":["columba","columbae","columbam","columbās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde ēmīsit {{columbam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"columna","latin":"columna, -ae","headword":"columna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"column; column, pillar","forms":["columna","columnae","columnās","columnīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Sciō multās domōs Tūsculānās et māiōrēs et meliōrēs esse quam nostram atque {{columnīs}} et signīs pulchriōribus ōrnārī, nec tamen haec domus mihi vidētur minus pulchra esse. rēs pulchra (esse) Domūs hominum dīvitum signīs deārum magnificīs ōrnantur — domus mea fēminā ōrnātur optimā et pulcherrimā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"com","latin":"com","headword":"com","letter":"c","pos":"preposition","posGroup":"preposition","english":"with, together/jointly/along/simultaneous with, amid; supporting; attached","forms":["com"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{com}}-pōnēre — récté pōnēre","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"coma","latin":"coma, -ae","headword":"coma","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hair; hair of the head","forms":["coma","comae","comam","comās","Comāta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit {{comam}}, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis rōbore: obvium leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comatus","latin":"comatus, comata, comatum","headword":"comatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"long-haired, having (long) hair; leafy; [Gallia Comata => Transalpine Gaul]","forms":["Comātam","Comātās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Comātās}} servus fuit, quī in Graeciā habitābat, et cotīdiē caprās ovēsque dominī, quae in collibus et campīs pāscēbantur, cūstōdiēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"comburo","latin":"comburo, comburere, combusi, combustus","headword":"comburo","letter":"c","pos":"verb","posGroup":"verb","english":"burn up/away; (w/love); consume/destroy w/fire; reduce to ash, cremate; scald","forms":["comburī","combustae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ārās falsīs dīīs per ūniversam IŪdaeam exstrūxit; omnia templī Hierosolymitanī omāmenta dētrāxit; librōs sacrōs iussit comburī; reluctantēs inaudītīs suppliciīs afrecit; urbem innumerā caede vastāvit: ac nē Iudaeī tot malīs oppressī rebellārent, praesidium in arce collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comedo","latin":"comedo, comedere, comedi, comesus","headword":"comedo","letter":"c","pos":"verb","posGroup":"verb","english":"eat up/away, chew up; finish eating; fret, chafe; consume/devour; waste/squander","forms":["comedam","comedās","comede","comedēbant","comedendam","comedendō","comedere","comēderit","comedēs","comedis","comēdistī","comēdit","comedite","comēsse","comēst"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deus dīxit hominī: ūtere frūctibus omnium arborum Paradīsī, praeter frūctum arboris scientiae bonī et malī; nam sī {{comedās}} illum frūctum, moriēris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comes","latin":"comes, comitis","headword":"comes","letter":"c","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) companion; companion, sharer","forms":["comes","comite","comitem","comitēs","comitibus","comitum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Habēbat sēcum ūnam {{comitem}} sorōrem puerī, quam iussit stāre procul, ut ēventum reī explōrāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comicus","latin":"cōmicus, -a, -um","headword":"cōmicus","letter":"c","pos":"","posGroup":"other","english":"of comedy, comic","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"comis","latin":"cōmis, -e","headword":"cōmis","letter":"c","pos":"adjective","posGroup":"adjective","english":"kind, affable; courteous, kindly","forms":["cōmibus","comīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc igitur faciās: cum ē templō exierīs, vaccam pulchram vidēbis {{cōmibus}} paene aureīs, quae numquam rūrī labōrāvit; ea in latere plēnam lūnam gerere vidēbitur; tibi suādeō ut eam sequāris: nam ubi cōnstiterit, ibi urbis moenia tibi aedificanda erunt.” Apollō, haec verba locūtus, tacuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"comitari","latin":"(comitor) comitārī, comitātum","headword":"comitārī","letter":"c","pos":"verb","posGroup":"verb","english":"accompany; to accompany","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"comitatur","latin":"comitātur","headword":"comitātur","letter":"c","pos":"verb","posGroup":"verb","english":"accompanies","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"comitatus","latin":"comitātus, -ūs","headword":"comitātus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"escort, retinue","forms":["comitāta","comitātū","comitātum","comitātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quīntus: 'Nōnne Mēdus eum {{comitātus}} est?'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"comiter","latin":"comiter","headword":"comiter","letter":"c","pos":"adverb","posGroup":"adverb","english":"courteously, affably, obligingly, graciously, kindly","forms":["cōmiter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"illa blandàs precēs {{cōmiter}} excipiet excipiet blandās cōmiter","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"comitia","latin":"comitia, -ōrum (pl.)","headword":"comitia","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"assembly of the people","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"comitio","latin":"comitio, comitiare, comitiavi, comitiatus","headword":"comitio","letter":"c","pos":"verb","posGroup":"verb","english":"offer sacrifice after which comitia could be held; go to comitia (L+S)","forms":["Comitiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tullius Cicerō, ōrātor omnium quī Rōmae fuērunt illūstrissimus, ōrātiōnēs habuit, nam Rōstra antīqua, quae in ipsō Comitiō posita erant, simul cum cūriā antīquā ā Iūliō Caesare dēstrūcta sunt, cum nova cūria aedificārētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"comitium","latin":"comitium, comiti(i)","headword":"comitium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"place in Forum where comitia were held; comitia (pl.), assembly; elections","forms":["comitia","comitiis","comitiōrum","Comitium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tres nobilissimi Aedui capti ad Caesarem perducuntur: Cotus, praefectus equitum, qui controversiam cum Convictolitavi proximis {{comitiis}} habuerat, et Cavarillus, qui post defectionem Litavicci pedestribus copiis praefuerat, et Eporedorix, quo duce ante adventum Caesaris Aedui cum Sequanis bello contenderant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"comitor","latin":"comitor, comitari, comitatus sum","headword":"comitor","letter":"c","pos":"verb","posGroup":"verb","english":"join as an attendant, guard/escort; accompany, follow; attend (funeral)","forms":["comitābitur","comitābor","comitante","comitantibus","comitantur","comitārī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam Dāvus puerum ex ātriō dūxit, dominus 'Haec omnia' inquit 'facta sunt, quod Mēdus heri domō fugit nec hodiē Mārcum in lūdum euntem et illinc redeuntem comitārī potuit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"commeatus","latin":"commeātus, -ūs","headword":"commeātus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"supplies, provisions","forms":["commeatu","commeatus","commeātuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque cohortatus Aeduos de supportando {{commeatu}}, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium impetum magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commemini","latin":"commemini, commeminisse","headword":"commemini","letter":"c","pos":"verb","posGroup":"verb","english":"remember, recollect; remember (to do something w/INF); mention, cite, recall","forms":["commeminī","commeminit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"hoc adeō hoc commeminī magis, quia illō diē imprānsus fuī—","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"commemorare","latin":"(commemorō) commemorāre, -āvisse, -ātum","headword":"commemorāre","letter":"c","pos":"verb","posGroup":"verb","english":"mention; to mention, recall","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"commemoro","latin":"commemoro, commemorare, commemoravi, commemoratus","headword":"commemoro","letter":"c","pos":"verb","posGroup":"verb","english":"recall (to self/other); keep in mind, remember; mention/relate; place on record","forms":["commemorandō","commemorandum","commemorant","commemorāre","commemorāvimus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Statim in iīs ‘AI’ litterae ad Apollinis clāmōrem {{commemorandum}} appāruērunt, quae adhūc in illīus flōris foliīs scrīpta cernuntur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"commendare","latin":"(commendō) commendāre","headword":"commendāre","letter":"c","pos":"","posGroup":"other","english":"entrust, commit","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commendatio","latin":"commendātiō, -ōnis ( f.)","headword":"commendātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"recommendation, praise","forms":["commendātiōne","commendātiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rosciō dicta tantum {{commendātiōnis}} habuit ut nōn ūlla esset quae nōn dīgna nostrō patrōciniō vidērētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"commendatus","latin":"commendatus, commendata -um, commendatior -or -us, commendatissimus -a -um","headword":"commendatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"recommended (for attention/favor); entrusted; acceptable, agreeable, suitable","forms":["commendātus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum versūs scrībere coepisset, Horātius ā poētā Vergiliō Maecēnātī, virō Rōmānō dīvītissimō, {{commendātus}} est.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"commendo","latin":"commendo, commendare, commendavi, commendatus","headword":"commendo","letter":"c","pos":"verb","posGroup":"verb","english":"entrust, give in trust; commit; recommend, commend to; point out, designate","forms":["commendet","commendō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et clāmāns Iēsus vōce magnā ait:\"Pater, in mantīs tuās commendō spīritum meum.\"Et haec dīcēns, exspīrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"commentari","latin":"(commentor) commentārī","headword":"commentārī","letter":"c","pos":"","posGroup":"other","english":"think about, practice","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commentarius","latin":"commentārius, -ī","headword":"commentārius","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"notebook, record; notebook, commentary","forms":["commentāriō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Satis autem vīsum est in hōc commentāriō dē temporibus paucōrum hominum dīcere, ex quōrum aetātibus dē plūribus quoque, quōs nōn nōminārēmus, haud difficilis coniectūra fierī posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"commentor","latin":"commentor, commentari, commentatus sum","headword":"commentor","letter":"c","pos":"verb","posGroup":"verb","english":"think about; study beforehand, practice, prepare; discuss, argue over; imagine","forms":["Commentābar"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'{{Commentābar}} dēclāmitāns — sīc enim nunc loquimur — idque faciēbam multum etiam Latīnē, sed Graecē saepius, vel quod Graeca ōrātiō plūra ōrnāmenta suppeditāns cōnsuētūdinem similiter Latīnē dīcendī afferēbat, vel quod ā Graecīs summīs doctōribus, Graecē dīcerem, neque corrigī possem neque docērī.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"commentus","latin":"commentus, commenta, commentum","headword":"commentus","letter":"c","pos":"adjective","posGroup":"adjective","english":"feigned, pretended, fabricated, devised, fictitious, invented","forms":["commentus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ut abigās: quōvīs pactō fac {{commentus}} sīs!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"commeo","latin":"commeo, commeare, commeavi, commeatus","headword":"commeo","letter":"c","pos":"verb","posGroup":"verb","english":"go to, visit, travel; pass; resort to; go to and fro, come and go; communicate","forms":["commeare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem duodenum pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium incursu etiam singuli {{commeare}} possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commi","latin":"commi, undeclined","headword":"commi","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"gum, vicid secretion from trees","forms":["Commi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huius opera {{Commi}}, ut antea demonstravimus, fideli atque utili superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, iura legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commigrare","latin":"(commigrō) commigrāre","headword":"commigrāre","letter":"c","pos":"","posGroup":"other","english":"move, go and live","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commigro","latin":"commigro, commigrare, commigravi, commigratus","headword":"commigro","letter":"c","pos":"verb","posGroup":"verb","english":"migrate, go and live (elsewhere); move one's home with all effects; enter","forms":["commigrāvisse","commigrāvit","commigret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus Iōsēphus: īte, inquit, properātē ad patrem meum, eīque nūntiātē fīlium suum vīvere, et apud Pharaōnem plūrimum posse; persuādēte illī ut in Aegyptum cum omnī familiā {{commigret}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comminus","latin":"comminus","headword":"comminus","letter":"c","pos":"adverb","posGroup":"adverb","english":"hand to hand (fight), in close combat/quarters; close at hand; in presence of","forms":["comminus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum acerrime {{comminus}} pugnaretur, hostes loco et numero, nostri virtute confiderent, subito sunt Aedui visi ab latere.nostris aperto, quos Caesar ab dextra parte alio ascensu manus distinendae causa miserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commisceo","latin":"commisceo, commiscere, commiscui, commixtus","headword":"commisceo","letter":"c","pos":"verb","posGroup":"verb","english":"intermingle, mix together/up, combine (ingredients); unite/join sexually","forms":["commiscuit","commixtā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec mulier plānē admīrābilis, et sempitēmā memoriā digna, postquam fīliōs certantēs et aspectīī et verbīs adiiīverat, postquam morientēs magnō animō cōnspexerat, ipsa dīram mortem subiit, suumque sanguinem cum fīliōrum sanguine {{commiscuit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"commissum","latin":"commissum, commissi","headword":"commissum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"undertaking, enterprise; trust, secret; thing entrusted/confiscated; crime","forms":["commissa","commissis","commisso","commissum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam maiore {{commisso}} delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commissura","latin":"commissura, commissurae","headword":"commissura","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"joint, juncture, seam, gap; intersection, common point; boundary/dividing line","forms":["commissuras"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huic loricam pinnasque adiecit, grandibus cervis eminentibus ad {{commissuras}} pluteorum atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"committere proelium","latin":"committere proelium","headword":"committere proelium","letter":"c","pos":"phrase","posGroup":"other","english":"to join battle","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"committo","latin":"committo, committere, commisi, commissus","headword":"committo","letter":"c","pos":"verb","posGroup":"verb","english":"bring together, unite/join, connect/attach; put together, construct; entrust","forms":["commīserat","commīsisse","commīsisset","commīsit","commissōs","commissurum","committam","committe","committendam","committendum","committent","committere","committerent","committeret","committi","committit","committunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte {{committi}} videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commodo","latin":"commodo, commodare, commodavi, commodatus","headword":"commodo","letter":"c","pos":"verb","posGroup":"verb","english":"lend, hire; give, bestow, provide; put at disposal of, oblige; make fit, adapt","forms":["commodāre","commodāvī","commodāvit","commodō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Gābelō cuidam egentī decem talenta, quibus ā rēge dōnātus erat, perhūmāniter {{commodāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"commodum","latin":"commodum, -ī","headword":"commodum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"advantage, interest","forms":["commoda","commodis","commodum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea salutis causa rei familiaris {{commoda}} neglegenda: vicos atque aedificia incendi oportere hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commodus","latin":"commodus, commoda -um, commodior -or -us, commodissimus -a -um","headword":"commodus","letter":"c","pos":"adjective","posGroup":"adjective","english":"suitable, convenient, obliging; opportune/timely; favorable/lucky; advantageous","forms":["commodiorem","commodius","commodus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pompei {{commodiorem}} in statum pervenisse intellegeret, in Transalpinam Galliam profectus est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commorari","latin":"(commoror) commorārī","headword":"commorārī","letter":"c","pos":"","posGroup":"other","english":"stay, linger","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commoror","latin":"commoror, commorari, commoratus sum","headword":"commoror","letter":"c","pos":"verb","posGroup":"verb","english":"stop/stay/remain, abide; linger, delay; detain, be delayed (menses); dwell on","forms":["commorandum","commorāre","commorātum","commoratus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caesar Avarici complures dies {{commoratus}} summamque ibi copiam frumenti et reliqui commeatus nactus exercitum ex labore atque inopia reficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commoto","latin":"commoto, commotare, commotavi, commotatus","headword":"commoto","letter":"c","pos":"verb","posGroup":"verb","english":"move very violently; agitate","forms":["commōtō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Pāstor, quī in campō ovēs pāscēbat, cum haec omnia vīdisset, trīstis ac maerēns hoc carmen continuō compositum animō valdē commōtō cecinit:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"commotus","latin":"commōtus, -a, -um","headword":"commōtus","letter":"c","pos":"adjective","posGroup":"adjective","english":"nervous, unsettled, emotionally moved","forms":["commōta","commōtior","commōtīs","commōtus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et rūrsus: Deus sit tibi propitius, fīlī mī; et abiit festīnāns, quia {{commōtus}} erat animō, et lacrimae ērumpēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"commoveo","latin":"commoveō, -ēre, -mōvī, -mōtum","headword":"commoveō","letter":"c","pos":"verb","posGroup":"verb","english":"shake, move, disturb","forms":["commōtum","commoveāre","commovēbat","commovēbātur","commovēre","commōvit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"neque miser mē {{commovēre}} possum prae formīdine!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"commovere","latin":"(commoveō) commovēre (< movēre)","headword":"commovēre","letter":"c","pos":"","posGroup":"other","english":"move, excite, cause","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commune","latin":"commune, communis","headword":"commune","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"joint/common/public property/rights; public; public places/interests (pl.)","forms":["commūne"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Magister: 'Genera nōminum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: 'Masculīnum, ut hic magister; fēminīnum, ut haec fēmina; neutrum, ut hoc scamnum; {{commūne}}, ut hic et haec sacerdōs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"communicare","latin":"(commūnicō) commūnicāre","headword":"commūnicāre","letter":"c","pos":"verb","posGroup":"verb","english":"share; to share, make common","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"communico","latin":"communico, communicare, communicavi, communicatus","headword":"communico","letter":"c","pos":"verb","posGroup":"verb","english":"share; share/divide with/out; receive/take a share of; receive; join with","forms":["commūnicābō","communicat","commūnicātis","commūnicātō","commūnicāvisse","communicet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum his praemium {{communicat}} hortaturque eos ut se liberos et imperio natos meminerint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"communio","latin":"commūniō, -ōnis ( f.)","headword":"commūniō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"partnership, sharing; sharing, community","forms":["commūniōne","commūniōnem","commūniunt","commūnīvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[Ex Līviī librō XXII:] Cōnsulēs satis explōrātīs itineribus sequentēs Poenum, ventum ad Cannās est et in cōnspectū Poenum habēbant, bīna castra {{commūniunt}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"communire","latin":"(commūniō) commūnīre","headword":"commūnīre","letter":"c","pos":"","posGroup":"other","english":"fortify","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"communis","latin":"commūnis, -e","headword":"commūnis","letter":"c","pos":"adjective","posGroup":"adjective","english":"shared, common; common, shared; common (of gender)","forms":["communem","communes","communi","commūnia","commūnibus","communis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur {{communem}} Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"communiter","latin":"communiter","headword":"communiter","letter":"c","pos":"adverb","posGroup":"adverb","english":"in common, commonly; in joint action; indiscriminately; generally, ordinarily","forms":["commūniter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caenīnēnsēs Crustumīnīque et Antemnātēs, cum Tatium Sabīnōsque lentē agere exīstimārent, ipsī inter sē trēs populī {{commūniter}} bellum parant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"commutare","latin":"(commūtō) commūtāre","headword":"commūtāre","letter":"c","pos":"","posGroup":"other","english":"change (completely)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"commutatio","latin":"commūtātiō, -ōnis ( f.)","headword":"commūtātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"change; change, reversal","forms":["commūtātiō","commutatione","commutationem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum Labienus tanta rerum {{commutatione}} longe aliud sibi capiendum consilium atque antea senserat intellegebat, neque iam ut aliquid adquireret proelioque hostes lacesseret sed ut incolumem exercitum Agedincum reduceret cogitabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"commutatus","latin":"commutatus, commutatus","headword":"commutatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"change; alteration","forms":["commūtātus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Vestītum servīlem gerēns atque in fōrmam Sōsiae servī {{commūtātus}} nūllō modō deī similis est—nisi quod pinnulae, quās in petasō gerit, significant eum esse Mercurium.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"commuto","latin":"commuto, commutare, commutavi, commutatus","headword":"commuto","letter":"c","pos":"verb","posGroup":"verb","english":"change; alter wholly, rearrange, replace; transform; exchange, barter, sell","forms":["commūtāre","commūtārent","commutatis","commutato","commūtāverō","commūtāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam, ut {{commutato}} consilio iter in provinciam converteret, ut ne metu quidem necessario faciendum existimabat, cum infamia atque indignitas rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"como","latin":"como, comere, compsi, comptus","headword":"como","letter":"c","pos":"verb","posGroup":"verb","english":"arrange/do (hair); adorn, make beautiful; embellish; arrange in order, set out","forms":["cōmīt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ut prope perventum, {{cōmīt}}és in valle relinquit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"comoedia","latin":"cōmoedia, -ae","headword":"cōmoedia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"comedy; comedy, play","forms":["cōmoedia","cōmoediae","comoediam","comoediās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nuper spectavi {{comoediam}} Plauti de Amphitryone, duce Graecorum, cuius uxor Alcmena ab ipso Iove amabatur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"compages","latin":"compages, compagis","headword":"compages","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"action of binding together, fastening; bond, tie; joint; structure, framework","forms":["compāgibus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"vīcit hiems; laxīs laterum {{compāgibus}} omnēs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"comparare","latin":"(comparō) comparāre","headword":"comparāre","letter":"c","pos":"verb","posGroup":"verb","english":"prepare, provide; compare; to compare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"comparat","latin":"comparat","headword":"comparat","letter":"c","pos":"verb","posGroup":"verb","english":"compares","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"comparate","latin":"comparate","headword":"comparate","letter":"c","pos":"adverb","posGroup":"adverb","english":"comparatively; in/by comparison (L+S)","forms":["Comparāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Comparāte}} nunc, Quirītēs, cum illōrum superbiā mē, hominem novum!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"comparatio","latin":"comparātiō, comparātiōnis","headword":"comparātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) a comparison; preparation, provision, comparison; comparison; preparation, comparison","forms":["Comparātiō","comparātiōnem","comparātiōnis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Magister: '{{Comparātiōnis}} gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: 'Positīvus, ut doctus; comparātīvus, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat quālitātem aut quantitātem significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"comparativus","latin":"comparātīvus, -ī (gradus)","headword":"comparātīvus","letter":"c","pos":"adjective","posGroup":"adjective","english":"comparative","forms":["comparātīvī","comparātīvō","comparātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Comparātiōnis gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: 'Positīvus, ut doctus; {{comparātīvus}}, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat quālitātem aut quantitātem significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"compareo","latin":"compareo, comparere, comparui, -","headword":"compareo","letter":"c","pos":"verb","posGroup":"verb","english":"appear/come in sight; be visible/present/in evidence/clearly stated/forthcoming","forms":["comparuisset","compāruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vōs autem dēbitās Deō grātēs rependite.” Haec locūtus, ab illōrum cōnspectū ablātus est, nec ultrā {{compāruit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comparere","latin":"(compāreō) compārēre, -uisse","headword":"compārēre","letter":"c","pos":"","posGroup":"other","english":"appear","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"comparo","latin":"comparō, comparāre","headword":"comparō","letter":"c","pos":"verb","posGroup":"verb","english":"liken, compare; prepare, get ready","forms":["Comparā","comparabant","comparābat","comparandi","comparandō","comparandum","comparant","comparantur","comparāre","comparārent","comparārī","comparat","comparāta","comparatis","comparātō","comparāvit","compārēs","comparetur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus {{comparatis}}, represso iam Lucterio et remoto, quod intrare intra praesidia periculosum putabat, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"compavesco","latin":"compavesco, compavescere, -, -","headword":"compavesco","letter":"c","pos":"verb","posGroup":"verb","english":"become very afraid/full of fear/thoroughly terrified","forms":["compavēscit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hoc illa ubi audīvit, animus {{compavēscit}}, domō trepidāns ēgreditur, ad cēterās mātrōnās pergit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"compellere","latin":"(compellō) compellere (< pellere)","headword":"compellere","letter":"c","pos":"","posGroup":"other","english":"drive together, compel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"compello","latin":"compello, compellere, compuli, compulsus","headword":"compello","letter":"c","pos":"verb","posGroup":"verb","english":"drive together (cattle), round up; force, compel, impel, drive; squeeze; gnash","forms":["compellāns","compellat","compelle","compellēbātur","compelluntur","compulērunt","compulissem","compulit","compulsi","compulsos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, {{compulsos}} in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"compendio","latin":"compendio, compendiare, compendiavi, compendiatus","headword":"compendio","letter":"c","pos":"verb","posGroup":"verb","english":"shorten, abridge (sermon); shorten/cut short (life), kill","forms":["compendio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Haec faciunt reciperandorum suorum causa; sed contaminati facinore et capti {{compendio}} ex direptis bonis, quod ea res ad multos pertinebat, timore poenae exterriti consilia clam de bello inire incipiunt civitatesque reliquas legationibus sollicitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"comperio","latin":"comperio, comperire, comperi, compertus","headword":"comperio","letter":"c","pos":"verb","posGroup":"verb","english":"learn/discover/find (by investigation); verify/know for certain; find guilty","forms":["comperī","comperissent","comperisset","comperistī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quō cum quaereret Pyrrhus 'quālem Rōmam {{comperisset}}?' Cineās dīxit 'rēgum sē patriam vīdisse: scīlicet tālēs illīc ferē omnēs esse quālis ūnus Pyrrhus apud Ēpīrum et reliquam Graeciam putārētur!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"comperire","latin":"(comperio) comperīre, -erisse, -ertum","headword":"comperīre","letter":"c","pos":"","posGroup":"other","english":"find out, learn, discover","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"compertum","latin":"compertum, comperti","headword":"compertum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"ascertained/proved/verified fact, certainty; [pro ~o => as certain/for a fact]","forms":["comperta","compertum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Impellit alios avaritia, alios iracundia et temeritas quae maxime illi hominum generi est innata, ut levem auditionem habeant pro re {{comperta}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"compes","latin":"compes, compedis","headword":"compes","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"shackles (for feet) (usu. pl.), fetters; things impeding movement; chains","forms":["compedēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Notāvit haec Trimalchiô iussitque afferrî omnia, et “Vidëtîs” inquit “mulieris {{compedēs}}: sīc nôs barcalae dēspoliāmur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"compesco","latin":"compesco, compescere, compescui, -","headword":"compesco","letter":"c","pos":"verb","posGroup":"verb","english":"restrain, check; quench; curb, confine, imprison; hold in check; block, close","forms":["compescere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nōn potuit Mīnōs hominis {{compescere}} pinnās,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"competitor","latin":"competitor, competitoris","headword":"competitor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"rival, competitor; other candidate for office; rival claimant (to throne)","forms":["competītōrēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum proximīs comitiīs cōnsulāribus mē cōnsulem in Campō et {{competītōrēs}} tuōs interficere voluistī, compressī cōnātūs tuōs nefāriōs amīcōrum praesidiō et cōpiīs, nūllō tumultū pūblicē concitātō; dēnique, quotiēnscumque mē petīstī, per mē tibi obstitī, quamquam vidēbam perniciem meam cum magnā calamitāte reī pūblicae esse coniūnctam.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"complaceo","latin":"complaceo, complacere, complacui, complacitus","headword":"complaceo","letter":"c","pos":"verb","posGroup":"verb","english":"please, take fancy of, capture affections of, be acceptable/agreed to","forms":["complacitum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"quantusque amātor sit quod {{complacitum}} est semel:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"complecti","latin":"complectī","headword":"complectī","letter":"c","pos":"verb","posGroup":"verb","english":"to embrace","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"complectitur","latin":"complectitur, complectī","headword":"complectitur","letter":"c","pos":"","posGroup":"other","english":"embrace","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"complector","latin":"complector, complecti, complexus sum","headword":"complector","letter":"c","pos":"verb","posGroup":"verb","english":"embrace, hug; welcome; encircle, encompass; attain; include, bring in, involve","forms":["complectar","complectātur","complectēbātur","complectēns","complecterentur","complecterētur","complectī","complectitur","complectuntur","complexī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Lȳdia amīcam lacrimantem {{complectitur}} atque cōnsōlārī cōnātur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"compleo","latin":"compleo, complere, complevi, completus","headword":"compleo","letter":"c","pos":"verb","posGroup":"verb","english":"fill (up/in); be big enough to fill; occupy space, crowd; furnish/supply/man","forms":["compleat","complēbantur","complēbat","complēbātur","complent","complentur","complere","complērī","complet","complētum","complētur","compleverant","complēverit","compleverunt","complevit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quem simul atque oppidani conspexerunt atque in spem auxili venerunt, clamore sublato arma capere, portas claudere, murum {{complere}} coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"complere","latin":"(compleō) complēre, -plēvisse, -plētum","headword":"complēre","letter":"c","pos":"verb","posGroup":"verb","english":"fill up; to fill, man","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"complexo","latin":"complexo, complexare, complexavi, complexatus","headword":"complexo","letter":"c","pos":"verb","posGroup":"verb","english":"embrace closely; join, combine (Ecc)","forms":["complexa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Numquam omnēs hodiē moriēmur inultī!\" Sed coniūnx pedēs virī abeuntis {{complexa}} in līmine haerēbat parvumque fīlium patrī ostendēbat: \"Sī peritūrus abīs, et nōs rape in omnia tēcum!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"complexus","latin":"complexus, -ūs","headword":"complexus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"embrace","forms":["complexibus","complexū","complexus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium {{complexus}} nec facile totum opus corona militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo advolaret aut interdiu tela in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"complorare","latin":"(complōrō) complōrāre","headword":"complōrāre","letter":"c","pos":"verb","posGroup":"verb","english":"lament, bewail; to bewail, lament","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"comploratio","latin":"complōrātiō, -ōnis ( f.)","headword":"complōrātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"lamentation","forms":["complōrātiō","complōrātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Movet ferōcī iuvenī animum complōrātiō sorōris in victōriā suā tantōque gaudiō pūblicō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"comploratus","latin":"comploratus, comploratus","headword":"comploratus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"lamentation, (vocal) mourning; loud/violent complaint/bemoaning/bewailing (L+S)","forms":["complōrātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Viriāthus ā prōditōribus, cōnsiliō Servīliī Caepiōnis, interfectus est et ab exercitū suō multum {{complōrātus}} ac nōbiliter sepultus, vir duxque magnus et per quattuordecim annōs quibus cum Rōmānīs bellum gessit frequentius superior.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"complures","latin":"complūrēs, -e","headword":"complūrēs","letter":"c","pos":"","posGroup":"other","english":"very many","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"complus","latin":"complus, (gen.), compluris","headword":"complus","letter":"c","pos":"adjective","posGroup":"adjective","english":"many (pl.), several, a fair/good number; more than one (L+S)","forms":["complūra","complures","compluribus","complūrium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut {{complures}} dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"componere","latin":"(compōnō) compōnere (< pōnere)","headword":"compōnere","letter":"c","pos":"","posGroup":"other","english":"settle, arrange, compose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"compono","latin":"compono, componere, composui, compositus","headword":"compono","letter":"c","pos":"verb","posGroup":"verb","english":"compare; place/put/add/collect together, collate; match (up); store/hoard; calm","forms":["compōnat","compōnere","compōnerent","composuērunt","composuī","composuisse","composuissent","composuisset","composuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīī vērō Pelopis membra, ut fuerant, {{composuērunt}}, eīque iterum vītam dedērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"compos","latin":"compos (gen. compotis)","headword":"compos","letter":"c","pos":"adjective","posGroup":"adjective","english":"in possession of (+ gen.)","forms":["compos","compotem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{compos}} -potis adī - gen — possidēns,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"composite","latin":"composite, compositius, compositissime","headword":"composite","letter":"c","pos":"adverb","posGroup":"adverb","english":"in orderly/skillful/well arranged/composed way; deliberately/regularly/properly","forms":["compositē"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Plērīque eōrum quī ante mē sententiās dīxērunt compositē atque magnificē cāsum reī pūblicae miserātī sunt.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"composito","latin":"composito","headword":"composito","letter":"c","pos":"adverb","posGroup":"adverb","english":"by prearrangement; concertedly","forms":["compositō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deversī in patriam IUdaeī, compositō urbis stātiī, nōn iam egēs habuēre, sed imperium penes pontificēs fuit: tribūta tamen pēnsitārunt prīmum Persīs, deinde Graecīs, post dēvictum ab Alexandra Darīum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"compositum","latin":"compositum, compositi","headword":"compositum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"made-up/compound medicine; agreement/compact; [ex/de ~o => by pre-arrangement]","forms":["compositum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pāstor, quī in campō ovēs pāscēbat, cum haec omnia vīdisset, trīstis ac maerēns hoc carmen continuō {{compositum}} animō valdē commōtō cecinit:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"compositus","latin":"compositus, composita -um, compositior -or -us, compositissimus -a -um","headword":"compositus","letter":"c","pos":"adjective","posGroup":"adjective","english":"well-arranged/ordered, regular, matching; made up of several parts, compound","forms":["compositā","compositam","compositīs","compositōs","compositus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Multa deinceps bella Dāvīd prosperē gessit contrā Philistaeōs, rēbusque forīs et domī {{compositīs}}, reliquum vītae tempus in flōrentī pāce exēgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"comprehendere","latin":"(comprehendō) comprehendere, -disse, -nsum","headword":"comprehendere","letter":"c","pos":"","posGroup":"other","english":"seize, include","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"comprehendo","latin":"comprehendo, comprehendere, comprehendi, comprehensus","headword":"comprehendo","letter":"c","pos":"verb","posGroup":"verb","english":"catch/seize/grasp firmly; arrest; take hold/root/fire, ignite; conceive (baby)","forms":["comprehendere","comprehenderem","comprehenderent","Comprehendērunt","comprehendi","comprehenditur","comprehendunt","comprehensī","comprehēnsīs","comprehensos","comprehēnsum","comprehēnsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus profligatis, rursus oppidani perterriti {{comprehensos}} eos quorum opera plebem concitatam existimabant ad Caesarem perduxerunt seseque ei dediderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"comprehenso","latin":"comprehenso, comprehensare, comprehensavi, comprehensatus","headword":"comprehenso","letter":"c","pos":"verb","posGroup":"verb","english":"seize in an embrace; embrace, hug","forms":["comprehēnsa"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae quoniam in senātū illūstrāta, patefacta, comperta sunt per mē, vōbīs iam expōnam breviter, ut, et quanta et quam manifēsta et quā ratiōne investīgāta et {{comprehēnsa}} sint, vōs quī et ignōrātis et exspectātis scīre possītis.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"comprendo","latin":"comprendo, comprendere, comprendi, comprensus","headword":"comprendo","letter":"c","pos":"verb","posGroup":"verb","english":"catch/seize/grasp firmly; arrest; take hold/root/fire, ignite; conceive (baby)","forms":["comprēndere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ō quater et quotiēns numerō {{comprēndere}} nón est","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"compressus","latin":"compressus, compressa -um, compressior -or -us, compressissimus -a -um","headword":"compressus","letter":"c","pos":"adjective","posGroup":"adjective","english":"constricted/narrow/pressed together; bound/tight (bowels), constipated, binding","forms":["compressa","compressius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed Vestālis, vī {{compressa}}, geminōs fīliōs peperit, et Mārtem patrem esse affirmāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"comprimere","latin":"(comprimō) comprimere (< premere)","headword":"comprimere","letter":"c","pos":"","posGroup":"other","english":"compress, crush, suppress, rape","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"comprimo","latin":"comprimo, comprimere, compressi, compressus","headword":"comprimo","letter":"c","pos":"verb","posGroup":"verb","english":"press/squeeze together, fold, crush; hem/shut/keep/hold in; copulate (male)","forms":["compressī","compressū","comprimam","comprimendōs","comprimī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"et gravidam fēcit is eam compressū suō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"comprobare","latin":"(comprobō) comprobāre","headword":"comprobāre","letter":"c","pos":"","posGroup":"other","english":"approve, confirm","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"comprobo","latin":"comprobo, comprobare, comprobavi, comprobatus","headword":"comprobo","letter":"c","pos":"verb","posGroup":"verb","english":"approve, accept, sanction, ratify; prove, justify, confirm, attest, bear out","forms":["Comprobāmus","comprobātō","comprobātum","comprobāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ita rēs somnium {{comprobāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"compulso","latin":"compulso, compulsare, compulsavi, compulsatus","headword":"compulso","letter":"c","pos":"verb","posGroup":"verb","english":"batter, pound","forms":["compulsa","compulsō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis {{compulsa}}, viritim distribuit; frumentum parce et paulatim metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"compulsus","latin":"compulsus, compulsus","headword":"compulsus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"striking together (hostile)","forms":["compulsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eādem necessitāte {{compulsus}} Iacobus mīsit illūc fīliōs suōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"computare","latin":"computāre","headword":"computāre","letter":"c","pos":"verb","posGroup":"verb","english":"to compute, count; calculate, reckon","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"computo","latin":"computō, computāre","headword":"computō","letter":"c","pos":"verb","posGroup":"verb","english":"calculate, reckon; compute, count up","forms":["computā","computābam","computābant","computant","computāre","computās","computat"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus sorōrī respondet: “{{Computāre}} discimus.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"conari","latin":"cōnārī","headword":"cōnārī","letter":"c","pos":"verb","posGroup":"verb","english":"to try, attempt; to try; to attempt, try","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"conatum","latin":"conatum, conati","headword":"conatum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"effort; attempt/design/attempted action (in pejorative sense); (usu. pl.) (L+S)","forms":["cōnāta","conati"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Id silentio noctis {{conati}} non magna iactura suorum sese effecturos sperabant, propterea quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua intercedebat, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conatur","latin":"cōnātur, cōnārī","headword":"cōnātur","letter":"c","pos":"verb","posGroup":"verb","english":"attempt, try; tries, attempts","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"conatus","latin":"conatus, conatus","headword":"conatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"attempt, effort; exertion, struggle; impulse, tendency; endeavor, design","forms":["conatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas excidere {{conatus}} esset, a multitudine oppressus ac sibi desperans, multis iam vulneribus acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem certe vitae prospiciam, quos cupiditate gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concavus","latin":"concavus, concava, concavum","headword":"concavus","letter":"c","pos":"adjective","posGroup":"adjective","english":"hollow/hollowed out; concave/curving inward; arched; bent/curved; sunken (eyes)","forms":["concava"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"làcībūs nec semper {{concava}} puppis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"concedere","latin":"(concēdō) concēdere (< cēdere)","headword":"concēdere","letter":"c","pos":"","posGroup":"other","english":"go (away), yield, give up, concede, allow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concedo","latin":"concedo, concedere, concessi, concessus","headword":"concedo","letter":"c","pos":"verb","posGroup":"verb","english":"relinquish/give up/concede; depart; pardon; submit, allow/grant/permit/condone","forms":["concēdās","concēde","concēdendum","concedente","concēdere","concēderem","concēderēs","concēdit","Concēdite","concēdō","concesserat","concesserō","concessērunt","concessimus","concessit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Datur petentibus venia, dissuadente primo Vercingetorige, post {{concedente}} et precibus ipsorum et misericordia vulgi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concentus","latin":"concentus, -ūs","headword":"concentus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"harmony; harmony, concord","forms":["concentūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc' inquam 'quis est quī complet aurēs meās tantus et tam dulcis sonus?' 'Hic est' inquit Āfricānus 'ille quī intervāllīs coniūnctus imparibus, sed tamen prō ratā parte ratiōne distīnctīs, impulsū et mōtū ipsōrum orbium efficitur, et acūta cum gravibus temperāns variōs aequābiliter {{concentūs}} efficit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conceptum","latin":"conceptum, concepti","headword":"conceptum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"fetus, that which is conceived; concept/ideas; measurement of volume/capacity","forms":["concepta"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Convertit ad hanc scaenam Trimalchiô vultum, et “Amîcî!” ait, “Pävônīs ôva gallînae iussî suppônî, et mē- herculēs timeô nē iam {{concepta}} sint!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"concertare","latin":"(concertō) concertāre","headword":"concertāre","letter":"c","pos":"","posGroup":"other","english":"fight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concesso","latin":"concesso, concessare, concessavi, concessatus","headword":"concesso","letter":"c","pos":"verb","posGroup":"verb","english":"cease/desist temporarily, leave off; rest","forms":["concēssēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēgulī intereā in loca propinqua thēsaurīs alius aliō {{concēssēre}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"concessus","latin":"concessus, concessa, concessum","headword":"concessus","letter":"c","pos":"adjective","posGroup":"adjective","english":"permitted/allowable/allowed/granted; lawful; relinquished; permitting/conceding","forms":["concessa","concessae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn multō post Salomōn {{concessae}} sibi ā Deō sapientiae speciem ēdidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"concha","latin":"concha, conchae","headword":"concha","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"mollusk/murex/oyster/scallop; pearl/mollusk-shell; Triton horn; female genitalia","forms":["conchā","conchae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"lītore quot {{conchae}} — tot sunt in amōre dolōrēs;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"concidere","latin":"(concīdō) concīdere, -disse, -sum","headword":"concīdere","letter":"c","pos":"","posGroup":"other","english":"kill, beat; fall (down), collapse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concido","latin":"concido, concidere, concidi, -","headword":"concido","letter":"c","pos":"verb","posGroup":"verb","english":"fall down/faint/dead/victim/to earth/short, collapse; drop, subside; decline","forms":["concīdat","conciderant","concīdērunt","concidisse","concidissent","concidit","concidunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas glaebas in ignem e regione turris proiciebat; scorpione ab latere dextro traiectus exanimatusque {{concidit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concieo","latin":"concieo, conciere, concivi, concitus","headword":"concieo","letter":"c","pos":"verb","posGroup":"verb","english":"move, set in violent motion, stir up; muster; rouse, excite, incite, provoke","forms":["concīverat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tarquinius Gabiōs tamquam in suum regnum profectus ab ultōribus veterum simultātium, quās sibi ipse caedibus rapīnīsque {{concīverat}}, est interfectus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conciliare","latin":"(conciliō) conciliāre","headword":"conciliāre","letter":"c","pos":"","posGroup":"other","english":"win over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concilio","latin":"concilio, conciliare, conciliavi, conciliatus","headword":"concilio","letter":"c","pos":"verb","posGroup":"verb","english":"unite, bring together/about; cause; win over, attract; acquire, procure, buy","forms":["conciliābat","concilianda","conciliandīs","conciliandō","conciliandōs","conciliante","conciliāre","conciliāret","conciliās","conciliat","conciliātur","concilio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum, collaudatis Carnutibus, dato iure iurando ab omnibus qui aderant, tempore eius rei constituto ab {{concilio}} disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concilium","latin":"concilium, -ī","headword":"concilium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"assembly, league; union, joining; assembly, council; council, league","forms":["concilia","conciliis","concilium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indictis inter se principes Galliae {{conciliis}} silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concinens","latin":"concinens, concinentis (gen.), concinentior -or -us, concinentissimus -a -um","headword":"concinens","letter":"c","pos":"adjective","posGroup":"adjective","english":"harmonious, fitting; harmonious (L+S)","forms":["concinente"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Crēdite mihi: cordācem nëmô melius dūcit.” Atque ipse, ërëctîs suprā frontem manibus, Syrum histriônem ex- hībēbat, {{concinente}} tôtä familiā: Madēia perimadēia!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"concinere","latin":"concinere","headword":"concinere","letter":"c","pos":"verb","posGroup":"verb","english":"to sound in chorus","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"concinne","latin":"concinne, concinnius, concinnissime","headword":"concinne","letter":"c","pos":"adverb","posGroup":"adverb","english":"neatly, prettily, daintily, beautifully","forms":["concinnē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Servulus nōn inurbānus satis strēnuē et concinnē comparārat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"concinno","latin":"concinno, concinnare, concinnavi, concinnatus","headword":"concinno","letter":"c","pos":"verb","posGroup":"verb","english":"prepare/make ready; repair, put/set right/in order, touch up; arrange suitably","forms":["concinnās","concinnat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: [lacrimāns] Lacrimantem ex abitū {{concinnās}} tū tuam uxōrem.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"concino","latin":"concino, concinere, concinui, -","headword":"concino","letter":"c","pos":"verb","posGroup":"verb","english":"sing/chant/shout/sound together; celebrate in song; say same thing, agree","forms":["concinitur","concinunt"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nunc dēmum cornua {{concinunt}}, quae signum cursūs dant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"concipere","latin":"(concipiō) concipere (< capere)","headword":"concipere","letter":"c","pos":"","posGroup":"other","english":"receive, catch, conceive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concipio","latin":"concipio, concipere, concepi, conceptus","headword":"concipio","letter":"c","pos":"verb","posGroup":"verb","english":"take in/up, receive, catch; derive/draw (from); contain/hold; grasp; adopt; wed","forms":["concēperat","concēpit","concipit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Scīpiō Āfricānus, lēgātus ad Antiochum missus, Ephesī cum Hannibale, quī sē Antiochō adiūnxerat, collocūtus est, ut — sī fierī posset — metum eī, quem ex populō Rōmānō {{concēperat}}, eximeret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"concitare","latin":"(concitō) concitāre","headword":"concitāre","letter":"c","pos":"","posGroup":"other","english":"stir up, incite","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concitatus","latin":"concitātus, -a, -um","headword":"concitātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"fast, rapid","forms":["concitātā","concitātae","concitatam","concitātī","concitātior","concitātō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quibus profligatis, rursus oppidani perterriti comprehensos eos quorum opera plebem {{concitatam}} existimabant ad Caesarem perduxerunt seseque ei dediderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concito","latin":"concito, concitare, concitavi, concitatus","headword":"concito","letter":"c","pos":"verb","posGroup":"verb","english":"stir up, disturb; discharge/hurl (missile); flow rapidly/strong current; rush","forms":["concītā","concitābant","concitābantur","concitābat","concitanda","concitandum","concitant","concitāret","concitat","concitavimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hos continuo in itinere adorti omnibus impedimentis exuunt; repugnantes diem noctemque obsident; multis utrimque interfectis maiorem multitudinem ad arma {{concitant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conclamare","latin":"(conclāmō) conclāmāre","headword":"conclāmāre","letter":"c","pos":"","posGroup":"other","english":"shout, cry out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conclamo","latin":"conclamo, conclamare, conclamavi, conclamatus","headword":"conclamo","letter":"c","pos":"verb","posGroup":"verb","english":"cry/shout aloud/out; make resound w/shouts; give a signal; summon; bewail/mourn","forms":["conclamant","conclamare","conclāmat","conclāmāvisset","conclāmāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Conclamat}} omnis multitudo et suo more armis concrepat, quod facere in eo consuerunt cuius orationem approbant: summum esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conclave","latin":"conclave, conclavis","headword":"conclave","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"room, chamber; lockable enclosed space; coop/cage; public lavatory; dining hall","forms":["conclāve"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde Iōsēphus ingressus est in {{conclāve}}; ubi suī eum frātrēs exspectābant, quī eum venerātī sunt offerentēs mūnera.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"concludo","latin":"concludo, concludere, conclusi, conclusus","headword":"concludo","letter":"c","pos":"verb","posGroup":"verb","english":"shut up, confine; contain, limit; close; include (limit); conceal, keep secret","forms":["conclūdere","conclūsērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Et cum hoc fēcissent, {{conclūsērunt}} piscium multitiīdinem magnam, ita ut rumperētur rēte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conclusum","latin":"conclusum, conclusi","headword":"conclusum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"confined space; conclusion in a syllogism (L+S)","forms":["conclūsum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: [ad Sōsiam appropinquantem] Quō ambulās tū, quī Volcānum in cornū {{conclūsum}} geris?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"concordia","latin":"concordia, -ae","headword":"concordia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"concord","forms":["concordia","concordiae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huius discidiī occāsiōne, Pompēius, populī Rōmānī dux, in Iildaeam venit, speciē quidem restituendae inter frātrēs {{concordiae}}, sed rē vērā ut istam prōvinciam Rōmānō adiungeret imperī ō; et vērē IŪdaeam stīpendiāriam populī Rōmānī fēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"concors","latin":"concors, (gen. -rdis)","headword":"concors","letter":"c","pos":"adjective","posGroup":"adjective","english":"harmonious, concordant","forms":["concors"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inde nōn modo commūne, sed {{concors}} etiam rēgnum duōbus rēgibus fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"concrepo","latin":"concrepo, concrepare, concrepui, concrepitus","headword":"concrepo","letter":"c","pos":"verb","posGroup":"verb","english":"make noise (door), grate/creak; sound, crash/clash, rattle; snap (fingers)","forms":["concrepat","concrepuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Conclamat omnis multitudo et suo more armis {{concrepat}}, quod facere in eo consuerunt cuius orationem approbant: summum esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concubeo","latin":"concubeo, concubere, concubui, concubitus","headword":"concubeo","letter":"c","pos":"verb","posGroup":"verb","english":"lie with (sexual and not); have sexual intercourse with","forms":["concubuisse","concubuisset"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"nūllī : cum nüllà | ferunt : dīcunt et tnullī nōn sē {{concubuisse}}!'","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"concubina","latin":"concubīna, -ae","headword":"concubīna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"concubine","forms":["concubīnā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dein Micipsa fīlius rēgnum sōlus obtinuit, Mastanabalem et Hiempsalem ex sē genuit, Iugurthamque, fīlium Mastanabalis frātris — quem Masinissa, quod ortus ex concubīnā erat, prīvātum dērelīquerat — eōdem cultū quō līberōs suōs domī habuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"concubitus","latin":"concubitus, concubitus","headword":"concubitus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"lying together (sleeping/dining/sex); sexual intercourse, coitus; sexual act","forms":["concubitū","concubitūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"illīc : in concubitū )","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"concumbere","latin":"(concumbō) concumbere, -uisse, -itum","headword":"concumbere","letter":"c","pos":"","posGroup":"other","english":"sleep (with)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concupiscere","latin":"(concupīscō) concupīscere, -īvisse (< cupere)","headword":"concupīscere","letter":"c","pos":"verb","posGroup":"verb","english":"desire, covet; to desire greatly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"concupisco","latin":"concupisco, concupiscere, concupivi, concupitus","headword":"concupisco","letter":"c","pos":"verb","posGroup":"verb","english":"desire eagerly/ardently; covet, long for; aim at; conceive a strong desire for","forms":["concupīscētis","concupīverat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nōn occīdētis, nōn adulterābitis, nōn faciētis fūrtum; nōn dīcētis falsum testimōnium adversus proximum vestrum; nōn {{concupīscētis}} rem alterīus.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"concurrere","latin":"(concurrō) concurrere (< currere)","headword":"concurrere","letter":"c","pos":"","posGroup":"other","english":"hurry together, clash","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"concurro","latin":"concurrō, -ere, -currī, -cursum","headword":"concurrō","letter":"c","pos":"verb","posGroup":"verb","english":"meet, come up against (+ dat.); to run together, rush to battle","forms":["concurrant","concurrēbant","concurrendum","concurrere","concurreret","concurrērunt","concurrēt","concurrit","concurritur","concurrunt","concursu","concursum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum signo dato {{concurrunt}} civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"concursus","latin":"concursus, -ūs","headword":"concursus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"concourse, encounter; running together, riotous gathering","forms":["concursus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quā tū audācia, mē vīvō, vocāre ausus es patrēs aut sēde cōnsīdere mea?\" Cum ille ferōciter ad haec — \"sē patris suī tenēre sēdem: fīlium rēgis multō potiōrem rēgnī hērēdem esse quam servum; illum satis diū per licentiam illūsisse dominīs\" — clāmor ab utriusque fautōribus oritur et {{concursus}} populī fīēbat in cūriam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"concutio","latin":"concutiō, -ere, concussī, concussum","headword":"concutiō","letter":"c","pos":"verb","posGroup":"verb","english":"shake, brandish","forms":["concussā","concussam","concusserat","concussit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās {{concussit}}, et turba omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn inultus occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"condemnare","latin":"(condemnō) condemnāre","headword":"condemnāre","letter":"c","pos":"","posGroup":"other","english":"condemn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"condemno","latin":"condemno, condemnare, condemnavi, condemnatus","headword":"condemno","letter":"c","pos":"verb","posGroup":"verb","english":"condemn, doom, convict; find guilty; (pass) sentence; blame, censure, impugn","forms":["condemnabiminī","condemnāre","condemnari","condemnātīs","condemnāvērunt","condemnō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis {{condemnari}} debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"condere","latin":"(condō) condere, -didisse, -ditum","headword":"condere","letter":"c","pos":"verb","posGroup":"verb","english":"put, hide, found, close; to found (a city), hide","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"condicio","latin":"condiciō, condicōnis","headword":"condiciō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) agreement, contract, condition; condition, terms","forms":["condiciō","condicione","condicionem","condiciōnēs","condiciōnibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Neque enim ulla alia {{condicione}} bella gesserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"condignus","latin":"condignus, condigna, condignum","headword":"condignus","letter":"c","pos":"adjective","posGroup":"adjective","english":"appropriate, worthy, befitting; wholly deserving, very worthy (L+S)","forms":["condignum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ēcastor {{condignum}} dōnum, quāle'st quī dōnum dedit.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"condio","latin":"condio, condire, condivi, conditus","headword":"condio","letter":"c","pos":"verb","posGroup":"verb","english":"preserve/pickle; embalm/mummify; spice; season/flavor/render pleasant/give zest","forms":["condīrent"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde praecēpit medicī ut {{condīrent}} corpus; et ipse cum frātribus multīsque Aegyptiīs patrem dēportāvit in regiōnem Chanaan.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"condiscipulus","latin":"condiscipulus, condiscipuli","headword":"condiscipulus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"fellow pupil/student (male); schoolfellow, schoolmate; fellow disciple (Ecc)","forms":["condiscipulī","condiscipulō","condiscipulus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prīmum salūtō magistrum, quī mē resalūtāvit: “Avē, magister! — Avēte, condiscipulī!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"conditor","latin":"conditor, -ōris (m.)","headword":"conditor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"founder","forms":["conditor","conditōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Condita urbs {{conditōris}} nōmine appellāta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conditum","latin":"conditum, conditi","headword":"conditum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"aromatic/spiced wine; seasoned food (pl.) (OLD)","forms":["conditum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Corpus eius {{conditum}} est, et in feretrō positum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"condo","latin":"condō, -ere, condidī, conditum","headword":"condō","letter":"c","pos":"verb","posGroup":"verb","english":"hide, bury, plunge; to found; to bury, hide","forms":["condar","condās","Conde","condēbat","condendae","condendīs","condere","conderet","condidit","condit","condita","conditae","conditam","conditī","conditū","conditūram","condunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi sēnsit mortem sibi imminēre, arcessītō Iōsēphō dīxit: sī mē amās, iūra tē id factūrum esse quod ā tē petam, scīlicet ut nē mē sepeliās in Aegyptō, sed corpus meum trānsferās ex hāc regiōne, et {{condās}} in sepulcrō maiōrum meōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"condono","latin":"condono, condonare, condonavi, condonatus","headword":"condono","letter":"c","pos":"verb","posGroup":"verb","english":"give (away/up); present; make present of; forgive/pardon/absolve; sacrifice to","forms":["condōnābam","condōnāret","condōnat","condōnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Post mortem patris, timēbant frātrēs Iōsēphī nē ulcīscerētur iniūriam quam accēperat; mīsērunt igitur ad illum rogantēs nōmine patris ut eam oblīvīscerētur, sibique {{condōnāret}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conduco","latin":"conduco, conducere, conduxi, conductus","headword":"conduco","letter":"c","pos":"verb","posGroup":"verb","english":"draw/bring together, collect, assemble; unite/join; cause to curdle/coagulate","forms":["conduxerat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Interim Teutomatus, Olloviconis filius, rex Nitiobrigum, cuius pater ab senatu nostro amicus erat appellatus, cum magno equitum suorum numero et quos ex Aquitania {{conduxerat}} ad eum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conductum","latin":"conductum, conducti","headword":"conductum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"anything hired/leased; rented house/dwelling; lease/contract","forms":["conductā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Itaque cēnsuit pecūniās eōrum pūblicandās, ipsōs per mūnicipia in cūstōdiā habendōs, vidēlicet timēns nē, sī Rōmae sint, aut ā populāribus coniūrātiōnis aut ā multitūdine conductā per vim ēripiantur — quasi vērō malī atque scelestī tantummodo in urbe et nōn per tōtam Ītaliam sint, aut nōn ibi plūs possit audācia ubi ad dēfendundum opēs minōrēs sunt.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"conectere","latin":"(cōnectō) cōnectere, -uisse, -xum","headword":"cōnectere","letter":"c","pos":"","posGroup":"other","english":"join together","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conexum","latin":"conexum, conexi","headword":"conexum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"hypothetical proposition; necessary consequence, inevitable inference (L+S)","forms":["cōnexa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Novem tibi orbibus vel potius globīs {{cōnexa}} sunt omnia, quōrum ūnus est caelestis, extimus, quī reliquōs omnēs complectitur, summus ipse deus arcēns et continēns cēterōs; in quō sunt īnfīxī illī quī volvuntur stellārum cursūs sempiternī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confectus","latin":"confectus, confecta, confectum","headword":"confectus","letter":"c","pos":"adjective","posGroup":"adjective","english":"with her litter (w/sus of a sow); (offered with all her young for sacrifice)","forms":["confecta","cōnfectae","confectam","cōnfectī","confectis","confecto","confectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam {{confectam}} vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confero","latin":"cōnferō, cōnferre, contulī, collātum","headword":"cōnferō","letter":"c","pos":"verb","posGroup":"verb","english":"bring together, collect; sē cōnferre — take oneself to; bring together; change","forms":["collāta","collatis","collātum","cōnfer","cōnferam","cōnferantur","cōnferās","cōnferātis","cōnferātur","cōnferēbantur","cōnferendam","cōnferret","conferri","cōnfert","confertis","conferunt","contulerant","contulerat","contulērunt","contulī","contulisse","contulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, {{collatis}} militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confertus","latin":"cōnfertus, -a, -um","headword":"cōnfertus","letter":"c","pos":"adjective","posGroup":"adjective","english":"dense, compact","forms":["cōnfertissimam","cōnfertissimōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam egō hanc victimam Mānibus peremptōrum foedē cīvium dabō!' subditīsque calcāribus equō per {{cōnfertissimam}} hostium turbam impetum facit cōnsulemque lanceā trānsfīxit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confessio","latin":"cōnfessiō, -ōnis ( f.)","headword":"cōnfessiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"admission, confession","forms":["cōnfessiō","cōnfessiōnibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ea erat cōnfessiō caput rērum Rōmam esse, dē quō totiēns armīs certātum erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confessus","latin":"confessus, confessa, confessum","headword":"confessus","letter":"c","pos":"adjective","posGroup":"adjective","english":"admitted, acknowledged; generally admitted, manifest, obvious; confessed","forms":["cōnfessus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cūr virum innoxium tibi mīlitantem gladiō hostium interfēcistī?” Hīs prophētae verbīs mōtus Dāvīd culpam agnōvit et {{cōnfessus}} est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confestim","latin":"cōnfestim","headword":"cōnfestim","letter":"c","pos":"adverb","posGroup":"adverb","english":"at once, immediately","forms":["confestim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Non minus qui intra munitiones erant perturbantur Galli: veniri ad se {{confestim}} existimantes ad arma conclamant; non nulli perterriti in oppidum irrumpunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conficere","latin":"(cōnficiō) cōnficere, cōnfēcisse, confectum","headword":"cōnficere","letter":"c","pos":"","posGroup":"other","english":"make, accomplish","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"conficio","latin":"conficio, conficere, confeci, confectus","headword":"conficio","letter":"c","pos":"verb","posGroup":"verb","english":"make, construct; prepare, complete, accomplish; cause; perform; do thoroughly","forms":["cōnfēcerant","cōnfēcerat","cōnfēcēre","cōnfēcī","cōnfēcistī","cōnfēcit","cōnfectum","cōnficere","cōnficerent","conficeret","cōnficī","cōnficiam","cōnficiās","cōnficiēbat","cōnficienda","cōnficiendō","cōnficiēs","cōnficit","cōnficiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ea qui {{conficeret}}, C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conficit","latin":"cōnficit","headword":"cōnficit","letter":"c","pos":"verb","posGroup":"verb","english":"makes, completes","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"confidens","latin":"confidens, (gen.), confidentis","headword":"confidens","letter":"c","pos":"adjective","posGroup":"adjective","english":"assured/confident; bold/daring/undaunted; overconfident, presumptuous; trusting","forms":["cōnfīdēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cadmus vērō, quī deō parēre volēbat, cum prīmum exiit, illam pulchram vaccam cōnspexit, quae aurea cornua gerēbat; itaque, {{cōnfīdēns}} Apollinis verbīs, eam, etsī per longum tempus terrāsque multās ambulāvit, usque ad locum quendam ignōtum, pulcherrimum tamen, secūtus est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"confidenter","latin":"confidenter, confidentius, confidentissime","headword":"confidenter","letter":"c","pos":"adverb","posGroup":"adverb","english":"boldly, daringly, with assurance; audaciously, impudently, with effrontery","forms":["cōnfīdenter"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"[Animō receptō] Vērum certum est {{cōnfīdenter}} hominem contrā colloquī,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"confidentia","latin":"cōnfīdentia, -ae","headword":"cōnfīdentia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"self-confidence","forms":["cōnfīdentia","cōnfīdentiam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"AMPHITRYO: [{{cōnfīdentiam}} eius admīrāns] Satis audācter.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"confideo","latin":"confideo, confidere, confisus sum","headword":"confideo","letter":"c","pos":"verb","posGroup":"verb","english":"rely on, trust (to); believe, be confident/assured/sure; (Vulgate 4 Ezra 7:98)","forms":["cōnfīdendum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quoniam vēro ex interiōre templī parte eadem verba iterum iterumque repetēbantur, Deucaliōn uxōri suāsit ut deae sibique ipsī cōnfīderet: “Nōli timēre” inquit, “amātissima coniūnx: {{cōnfīdendum}} ā nōbīs est deae verbīs; neque enim umquam dea suādēbit ut scelera faciāmus.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"confidere","latin":"(cōnfīdō) cōnfīdere,  cōnfīsum ({i}+ dat.{/i})","headword":"cōnfīdere","letter":"c","pos":"verb","posGroup":"verb","english":"trust; to trust (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"confido","latin":"confido, confidere, confisus sum","headword":"confido","letter":"c","pos":"verb","posGroup":"verb","english":"have confidence in, rely on, trust (to); believe, be confident/assured; be sure","forms":["cōnfīdam","confidat","cōnfīde","confidebant","confidebat","cōnfīdere","confiderent","cōnfīderēs","cōnfīderet","cōnfīdit","cōnfīdō","cōnfīsī","cōnfīsum","cōnfīsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus rebus confectis Caesar ad oppidum Avaricum, quod erat maximum munitissimumque in finibus Biturigum atque agri fertilissima regione, profectus est, quod eo oppido recepto civitatem Biturigum se in potestatem redacturum {{confidebat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"configo","latin":"configo, configere, confixi, confixus","headword":"configo","letter":"c","pos":"verb","posGroup":"verb","english":"fasten/nail together, construct; set/cover with studs/points; drive in (nails)","forms":["cōnfīgeret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Praetereā, cum ab irrītā oppugnātiōne Carthāginis cōnsul — alter enim Rōmam ad comitia ierat — exercitum dūceret adversus Hasdrubalem, quī amplā manū saltum inīquum īnsēderat, suāsit prīmō cōnsulī nē tam inīquō locō {{cōnfīgeret}}; victus deinde plūrium, quī et prūdentiae et virtūtī eius invidēbant, sententiīs et ipse saltum ingressus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confinis","latin":"cōnfīnis, -e","headword":"cōnfīnis","letter":"c","pos":"adjective","posGroup":"adjective","english":"adjacent, neighboring","forms":["cōnfīnia","cōnfīnis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Arte superciliī {{cōnfīnia}} nūda replētis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"confirmanda","latin":"confirmanda, confirmandae","headword":"confirmanda","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"candidate for confirmation (female)","forms":["confirmandam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi a Viridomaro atque Eporedorige Aeduis appellatus discit cum omni equitatu Litaviccum ad solicitandos Aeduos profectum; opus esse ipsos antecedere ad {{confirmandam}} civitatem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confirmandus","latin":"confirmandus, confirmandi","headword":"confirmandus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"candidate for confirmation","forms":["confirmandi","confirmandos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Cum hoc idem postero die fecisset, satis ad Gallicam ostentationem minuendam militumque animos {{confirmandos}} factum existimans in Aeduos movit castra.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confirmare","latin":"(cōnfīrmō) cōnfīrmāre","headword":"cōnfīrmāre","letter":"c","pos":"","posGroup":"other","english":"assure, encourage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"confirmatus","latin":"confirmatus, confirmata -um, confirmatior -or -us, confirmatissimus -a -um","headword":"confirmatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"confident/assured; well established/firmly based; well attested/certain/proven","forms":["cōnfirmātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Līberābis populum tuum ā servitūte Madianitārum.” Nōlēbat prīmō Gedeōn tantum onus suscipere, sed duplicī mīrāculō {{cōnfirmātus}} nōn abnuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confirmo","latin":"confirmo, confirmare, confirmavi, confirmatus","headword":"confirmo","letter":"c","pos":"verb","posGroup":"verb","english":"strengthen, develop, build up (w/troops); make secure/firm; reassure; secure","forms":["confirmabant","confirmabat","cōnfirmāre","cōnfirmārent","confirmari","confirmat","confirmatis","cōnfirmātō","cōnfirmāvit","cōnfirmem","cōnfirment"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eo cum venisset, timentes {{confirmat}}, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confiteor","latin":"cōnfiteor, -ērī, -fessus sum","headword":"cōnfiteor","letter":"c","pos":"verb","posGroup":"verb","english":"confess, acknowledge","forms":["cōnfessī","cōnfessīs","cōnfessōs","cōnfitēberis","Cōnfitentēs","cōnfiteor","cōnfitērī","cōnfitētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum praefectus pincernārum dīxit rēgī: {{cōnfiteor}} peccātum meum; cum ego et praefectus pistōrum essēmus in carcere, uterque somniāvimus eādem nocte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confiteri","latin":"(cōnfiteor) cōnfitērī, cōnfessum","headword":"cōnfitērī","letter":"c","pos":"","posGroup":"other","english":"confess","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"confitetur","latin":"cōnfitētur","headword":"cōnfitētur","letter":"c","pos":"verb","posGroup":"verb","english":"confesses","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"conflagrare","latin":"(cōnflagrō) cōnflagrāre","headword":"cōnflagrāre","letter":"c","pos":"","posGroup":"other","english":"be burnt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conflagro","latin":"conflagro, conflagrare, conflagravi, conflagratus","headword":"conflagro","letter":"c","pos":"verb","posGroup":"verb","english":"be on fire/burn; be burnt down/consumed/utterly destroyed; be/become inflamed","forms":["cōnflagrātūrum","cōnflagrāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed rēx, cum sacrum Iovī nōn rīte fēcisset, fulmine ictus cum domō suā {{cōnflagrāvit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conflictare","latin":"(cōnflīctō) cōnflīctāre","headword":"cōnflīctāre","letter":"c","pos":"","posGroup":"other","english":"harass, distress","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conflicto","latin":"conflicto, conflictare, conflictavi, conflictatus","headword":"conflicto","letter":"c","pos":"verb","posGroup":"verb","english":"harm, assail, harass, distress, torment, vex; bring to ruin","forms":["cōnflīctābātur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hī, relicta urbe, nē vidērent mala, quibus ea {{cōnflīctābātur}}, sēcessērunt in solitiīdinem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confligere","latin":"(cōnflīgō) cōnflīgere, -xisse, -ctum","headword":"cōnflīgere","letter":"c","pos":"verb","posGroup":"verb","english":"clash, fight; to clash, do battle; to fight, engage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"confligo","latin":"confligo, confligere, conflixi, conflictus","headword":"confligo","letter":"c","pos":"verb","posGroup":"verb","english":"clash, collide; contend/fight/combat; be in conflict/at war; argue/disagree","forms":["confligat","cōnflīgere","cōnflīgunt","cōnflīxerat","cōnflīxērunt","cōnflīxisse","cōnflīxisset","cōnflīxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod si diutius alatur controversia, fore uti pars cum parte civitatis {{confligat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conflo","latin":"conflo, conflare, conflavi, conflatus","headword":"conflo","letter":"c","pos":"verb","posGroup":"verb","english":"kindle/ignite, blow on; arouse/stir up; melt (down); cast/weld; run up debt","forms":["cōnflāre","cōnflātam","cōnflātum","cōnflāverant"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eā tempestāte plūrimōs cuiusque generis hominēs adscīvisse sibi dīcitur, mulierēs etiam aliquot, quae prīmō ingentēs sūmptūs stuprō corporis tolerāverant, post, ubi aetās tantummodo quaestuī neque luxuriae modum fēcerat, aes aliēnum grande {{cōnflāverant}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"confluens","latin":"confluens, confluentis","headword":"confluens","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"confluence, meeting place/junction of rivers; name of town (pl.) (now Coblenz)","forms":["cōnfluentēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi Aniēnem fluvium trānsiit, ad {{cōnfluentēs}} collocat castra.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confluentes","latin":"cōnfluentēs, -ium (m. pl.)","headword":"cōnfluentēs","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"confluence; place where two rivers unite; river-junction","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"confluo","latin":"confluo, confluere, confluxi, confluxus","headword":"confluo","letter":"c","pos":"verb","posGroup":"verb","english":"flow/flock/come together/abundantly, meet/assemble; gather/collect; be brought","forms":["confluebat","cōnfluunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Admiratus quaerit ex perfugis causam, quorum magnus ad eum cotidie numerus {{confluebat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"confodio","latin":"confodio, confodere, confodi, confossus","headword":"confodio","letter":"c","pos":"verb","posGroup":"verb","english":"stab/run through, wound fatally; pierce, harm; dig up/turn over (land); trench","forms":["cōnfodere","cōnfoditur","cōnfossum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quārē lanceā {{cōnfodere}} cōnātus est, sed Dāvīd ictum lētālem dēclīnātiōne corporis effūgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confossus","latin":"confossus, confossa -um, confossior -or -us, confossissimus -a -um","headword":"confossus","letter":"c","pos":"adjective","posGroup":"adjective","english":"punctured, pierced; pierced through; full of holes","forms":["cōnfossam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Is vīderat bēluam ūnam cēterīs maiōrem, ac phalerīs rēgis circumtēctam; exīstimāns illa rēgem vehī, sē prō communī saliite dēvōvit: per mediōs hostēs ad bēluam properāvit, sub illīus ventrem subiit, repefifīs ictibus {{cōnfossam}} occīdit, et bēluae lābentis pondere oppressus ipse occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"confugere","latin":"(cōnfugiō) cōnfugere (< fugere)","headword":"cōnfugere","letter":"c","pos":"verb","posGroup":"verb","english":"flee for refuge; to flee for refuge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"confugio","latin":"confugio, confugere, confugi, confugitus","headword":"confugio","letter":"c","pos":"verb","posGroup":"verb","english":"flee (for refuge/safety/protection); take refuge; have recourse/appeal to","forms":["cōnfūgerant","cōnfugere","cōnfugiō","cōnfūgit","cōnfugiunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ergō Coriolānus, Rōma pulsūs, ad Volscōs {{cōnfūgit}}, quī ōlim hostēs eius fuerant, iīsque persuāsit, ut Rōmānōrum urbem oppugnārent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"confulgeo","latin":"confulgeo, confulgere, confulsi, -","headword":"confulgeo","letter":"c","pos":"verb","posGroup":"verb","english":"shine, gleam; be resplendent; shine brightly, glitter, glisten (L+S)","forms":["cōnfulgēbant"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ārdēre cēnsuī aedēs, ita tum {{cōnfulgēbant}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"confundere","latin":"(cōnfundō) cōnfundere (< fundere)","headword":"cōnfundere","letter":"c","pos":"","posGroup":"other","english":"mingle, upset, confuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"confundo","latin":"confundo, confundere, confudi, confusus","headword":"confundo","letter":"c","pos":"verb","posGroup":"verb","english":"pour/mix/mass/bring together; combine/unite/blend/merge; spread over, diffuse","forms":["cōnfūdēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Haec tantō dicta animō magis {{cōnfūdēre}} audientium animōs quam sī miserābiliter orbitātem suam dēflendō locūtus esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confusio","latin":"cōnfūsiō, -ōnis ( f.)","headword":"cōnfūsiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"mixture; disorder, confusion; confusion, disorder","forms":["cōnfūsiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec cōnstitūtiō prīmum habet aequābilitātem quandam magnam, quā carēre diūtius vix possunt līberī, deinde firmitūdinem — quod et illa prīma facile in contrāria vitia convertuntur, ut exsistat ex rēge dominus, ex optimātibus factiō, ex populō turba et cōnfūsiō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"confusus","latin":"confusus, confusa -um, confusior -or -us, confusissimus -a -um","headword":"confusus","letter":"c","pos":"adjective","posGroup":"adjective","english":"mixed together/jumbled/disordered; in disorder; indistinct; inarticulate","forms":["confusa","cōnfūsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dum haec apud Alesiam geruntur, Galli, concilio principum indicto, non omnes eos qui arma ferre possent, ut censuit Vercingetorix, convocandos statuunt sed certum numerum cuique ex civitate imperandum, ne tanta multitudine {{confusa}} nec moderari nec discernere suos nec frumentationem habere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"congelo","latin":"congelō, -āre, -āvī, -ātum","headword":"congelō","letter":"c","pos":"verb","posGroup":"verb","english":"freeze, stiffen, congeal","forms":["congelat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dum Nīobē lacrimat, in statuam {{congelat}}; etiam nunc lacrimae manant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"congemino","latin":"congemino, congeminare, congeminavi, congeminatus","headword":"congemino","letter":"c","pos":"verb","posGroup":"verb","english":"double; increase; combine to double size; redouble; employ in repeated action","forms":["congemināvimus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nunc sī patera pateram peperit, omnēs {{congemināvimus}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"congerere","latin":"(congerō) congerere (< gerere)","headword":"congerere","letter":"c","pos":"","posGroup":"other","english":"bring together, collect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"congeries","latin":"congeries, congeriei","headword":"congeries","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"heap, pile, mass; collection/accumulation (events/words); the ruins; chaos","forms":["congeriēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dīxit Hebraeīs: “Sī quandō vōs interrogāverint fīliī vestrī, quōrsum spectet ista lapidum {{congeriēs}}, respondēbitis: ‘Siccō pede trāiēcimus Iordānem istum: idcircō positī sunt lapidēs ad sempiternam factī memoriam, ut discant quanta sit Deī potentia.’”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"congero","latin":"congero, congerere, congessi, congestus","headword":"congero","letter":"c","pos":"verb","posGroup":"verb","english":"collect, bring/get together, amass; heap/pile up/on; build, construct; compile","forms":["congerit","congesserat","congessit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iōsēphus perlūstrāvit omnēs Aegyptī regiōnēs, et per septem annōs ūbertātis {{congessit}} maximam frūmentī cōpiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"congredi","latin":"(congredīor) congredī, -gressum","headword":"congredī","letter":"c","pos":"","posGroup":"other","english":"meet, join battle, fight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"congredior","latin":"congredior, congredi, congressus sum","headword":"congredior","letter":"c","pos":"verb","posGroup":"verb","english":"meet, approach, near; join in battle, come to grips; contend/engage (at law)","forms":["congrederētur","congressi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Helvii sua sponte cum finitimis proelio {{congressi}} pelluntur et C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"congregare","latin":"(congregō) congregāre","headword":"congregāre","letter":"c","pos":"","posGroup":"other","english":"bring together, gather","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"congregatus","latin":"congregatus, congregatus","headword":"congregatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"union, association","forms":["congregātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē, quoniam dē rē pūblicā quaerimus, hoc prīmum videāmus: quid sit id ipsum quod quaerimus.' Cum approbāvisset Laelius, 'Est igitur' inquit Āfricānus 'rēs pūblica \"rēs populī\", populus autem nōn omnis hominum coetus quōquō modō {{congregātus}}, sed coetus multitūdinis iūris cōnsēnsū et ūtilitātis commūniōne sociātus...'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"congrego","latin":"congrego, congregare, congregavi, congregatus","headword":"congrego","letter":"c","pos":"verb","posGroup":"verb","english":"collect/bring together/assemble/convene; flock, congregate; group; concentrate","forms":["congregātīs","congregātōs","congregentur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Propter quam iniūriam ab Arīminō, ubi mīlitēs {{congregātōs}} habēbat, adversum patriam cum exercitū vēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"congressus","latin":"congressus, congressus","headword":"congressus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"meeting, interview; assembly/conference; encounter; engagement, clash; contest","forms":["congressus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam quotiēscumque cum eō {{congressus}} est in Ītaliā, semper discessit superior.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conicere","latin":"(coniciō) conicere, -iēcisse, -iectum","headword":"conicere","letter":"c","pos":"","posGroup":"other","english":"throw, put; throw, put together","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conicio","latin":"cōniciō, -icere, -iēcī, -iectum","headword":"cōniciō","letter":"c","pos":"verb","posGroup":"verb","english":"throw, hurl; plunge","forms":["conic","conicerent","conicī","coniciāmus","coniciēbant","cōnicit","coniciunt","coniēcerat","coniēcērunt","coniēcisse","coniēcit","coniectā","coniectās","coniecti","coniectis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eorum impetum Galli sustinere non potuerunt atque in fugam {{coniecti}} multis amissis se ad agmen receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coniector","latin":"conjector, conjectoris","headword":"conjector","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"soothsayer; interpreter of dreams; diviner, seer","forms":["coniectōrem","coniectōrēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ubī illūxit, Pharaō perturbātus convocāvit omnēs {{coniectōrēs}} Aegyptī, et nārrāvit illīs somnium; at nēmō poterat illud interpretārī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"coniectura","latin":"coniectūra, -ae","headword":"coniectūra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"inferring, conjecture; conjecture, inference","forms":["coniectūra","coniecturam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His quam longissime possent egredi iussis, cum iam ex diei tempore {{coniecturam}} ceperat in castra perventum,: isdem sublicis, quarum pars inferior integra remanebat, pontem reficere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coniectus","latin":"conjectus, conjectus","headword":"conjectus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"throwing/crowding (together/into area), collection; joining battle (w/pugnae)","forms":["coniectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Agger ab universis in munitionem {{coniectus}} et ascensum dat Gallis et ea quae in terra occultaverant Romani contegit; nec iam arma nostris nec vires suppetunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coniugatio","latin":"coniugātiō, coniugātiōnis","headword":"coniugātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) conjugation","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"coniugium","latin":"coniugium, -ī","headword":"coniugium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"marriage; marriage, wedlock","forms":["coniugia","coniugiī","coniugio","coniugium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inde fidēs dextraeque datae thalamōque receptus\nconiugiī dōtem sociōrum corpora poscit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"coniunctio","latin":"coniūnctiō, coniūnctiōnis","headword":"coniūnctiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) conjunction; union, conjunction","forms":["coniūnctiō","coniūnctiōnem","coniūnctiōnum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister discipulum interrogat: 'Partēs ōrātiōnis quot sunt?' Discipulus respondet: 'Octō.' Magister: 'Quae?' Discipulus: 'Nōmen, prōnōmen, verbum, adverbium, participium, coniūnctiō, praepositiō, interiectiō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"coniunctivus","latin":"coniūnctīvus","headword":"coniūnctīvus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"subjunctive","forms":["coniūnctīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Modī verbōrum quī sunt?' Discipulus: 'Indicātīvus, ut lēgō; imperātīvus, ut lēge; optātīvus, ut utinam legerem; {{coniūnctīvus}}, ut cum legam; īnfīnītīvus, ut legere.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"coniunctum","latin":"conjunctum, conjuncti","headword":"conjunctum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"connected word/proposition; compound proposition; connection (L+S)","forms":["coniūnctum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Id ponte Subliciō, tum prīmum in Tiberī factō, urbī {{coniūnctum}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coniunctus","latin":"conjunctus, conjuncta, conjunctum","headword":"conjunctus","letter":"c","pos":"adjective","posGroup":"adjective","english":"adjoining/contiguous/linked; connected/contemporary (time), continuous; complex","forms":["coniūnctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīc' inquam 'quis est quī complet aurēs meās tantus et tam dulcis sonus?' 'Hic est' inquit Āfricānus 'ille quī intervāllīs {{coniūnctus}} imparibus, sed tamen prō ratā parte ratiōne distīnctīs, impulsū et mōtū ipsōrum orbium efficitur, et acūta cum gravibus temperāns variōs aequābiliter concentūs efficit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coniungo","latin":"coniungō, coniungere","headword":"coniungō","letter":"c","pos":"verb","posGroup":"verb","english":"connect, unite","forms":["coniūncta","coniūnctam","coniuncti","coniunctis","coniūnctō","coniūnctōs","coniungant","coniunge","coniungere","coniungeret","coniungī","coniungit","coniungitur","coniunguntur","coniūnxerat","coniunxerint","coniūnxeris","Coniūnxērunt","coniūnxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Conclamant Aedui et Litaviccum obsecrant ut sibi consulat. 'Quasi vero', inquit ille, 'consili sit res, ac non necesse sit nobis Gergoviam contendere et cum Arvernis nosmet {{coniungere}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coniunx","latin":"coniūnx, coniugis","headword":"coniūnx","letter":"c","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) spouse; spouse, husband / wife; husband or wife, spouse","forms":["coniuge","coniugem","coniuges","coniugī","coniugibus","coniugis","coniugum","coniūnx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius aestimare, liberos, {{coniuges}} in servitutem abstrahi, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coniurare","latin":"(coniūrō) coniūrāre","headword":"coniūrāre","letter":"c","pos":"","posGroup":"other","english":"swear together, conspire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"coniurati","latin":"coniūrātī, -ōrum (pl.)","headword":"coniūrātī","letter":"c","pos":"","posGroup":"other","english":"conspirators","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"coniuratio","latin":"coniūrātiō, -ōnis ( f.)","headword":"coniūrātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"conspiracy, plot; conspiracy","forms":["coniūrātiō","coniūrātiōne","coniūrātiōnem","coniūrātiōnī","coniūrātiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ea coniūrātiō industriā M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coniuratus","latin":"coniūrātus, -a, -um","headword":"coniūrātus","letter":"c","pos":"adjective","posGroup":"adjective","english":"sworn, joined by an oath","forms":["coniūrātae","coniūrātīs","coniūrātōrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mīlle ratēs et omnēs Pelasgae gentēs {{coniūrātae}} sequuntur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"coniuro","latin":"conjuro, conjurare, conjuravi, conjuratus","headword":"conjuro","letter":"c","pos":"verb","posGroup":"verb","english":"swear/act together, join in an oath/plot; conspire, plot; form alliance/league","forms":["coniurarent","coniūrāvēre","coniūrāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae {{coniurarent}}, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conlabor","latin":"conlabor, conlabi, conlapsus sum","headword":"conlabor","letter":"c","pos":"verb","posGroup":"verb","english":"collapse, fall down/in ruin; fall in swoon/exhaustion/death; slip/slink (meet)","forms":["conlāpsam"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{conlāpsam}} aspiciunt comitēs, ēnsemque cruōre","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"conluceo","latin":"conluceo, conlucere, conluxi, -","headword":"conluceo","letter":"c","pos":"verb","posGroup":"verb","english":"shine brightly, light up (with fire); reflect light, shine, be lit up; glitter","forms":["conlūcēre"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{conlūcēre}} facēs, iam fervere lītora flammīs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"conor","latin":"conor, conari, conatus sum","headword":"conor","letter":"c","pos":"verb","posGroup":"verb","english":"attempt/try/endeavor, make an effort; exert oneself; try to go/rise/speak","forms":["conabantur","conabatur","cōnābor","conamini","cōnantem","cōnantēs","Conantibus","conantur","cōnāre","cōnārētur","cōnārī","cōnāris","cōnātur","cōnor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Conantibus}} auxiliari suis, 'Frustra', inquit, 'meae vitae subvenire conamini, quem iam sanguis viresque deficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conqueror","latin":"conqueror, -ī, -questus sum","headword":"conqueror","letter":"c","pos":"verb","posGroup":"verb","english":"to complain, lament","forms":["Conquerar","conquestī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Amīssā sociōrum parte dolentēs\nmultaque conquestī terrās advēnimus illās,\nquās procul hinc spectās (procul est, mihi crēde, videnda\nīnsula vīsa mihi!) tūque ō iūstissime Trōum,\nnāte deā (neque enim fīnītō Marte vocandus\nhostis es, Aenēā), moneō, fuge lītora Circēs!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"conquiescere","latin":"(conquiēscō) conquiēscere","headword":"conquiēscere","letter":"c","pos":"","posGroup":"other","english":"rest","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conquiesco","latin":"conquiesco, conquiescere, conquievi, conquietus","headword":"conquiesco","letter":"c","pos":"verb","posGroup":"verb","english":"rest, take repose/be quiet, nap/go to sleep; have respite/pause from (w/ab/ex)","forms":["conquiēscere","conquieverat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie {{conquieverat}}, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conquirere","latin":"(conquīrō) conquīrere (< quaerere)","headword":"conquīrere","letter":"c","pos":"","posGroup":"other","english":"search out, investigate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conquiro","latin":"conquiro, conquirere, conquisivi, conquisitus","headword":"conquiro","letter":"c","pos":"verb","posGroup":"verb","english":"seek out; hunt/rake up; investigate; collect; search out/down/for diligently","forms":["Conquīrendī","conquīrere","conquirerent","conquiri","Conquirit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, centurionibus et paucis militibus intromissis qui arma iumentaque {{conquirerent}}, equitatus hostium procul visus est, qui agmen Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consalutare","latin":"(cōnsalūtō) cōnsalūtāre","headword":"cōnsalūtāre","letter":"c","pos":"","posGroup":"other","english":"greet, hail","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consaluto","latin":"consaluto, consalutare, consalutavi, consalutatus","headword":"consaluto","letter":"c","pos":"verb","posGroup":"verb","english":"hail/greet/salute (as); exchange greetings; greet/salute cordially (L+S)","forms":["cōnsalūtātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pompēius dē Mithridāte et Tigrāne, ductīs ante currum līberīs Mithridātis et Tigrāne Tigrānis fīliō, triumphāvit, Magnusque ā tōtā cōntiōne {{cōnsalūtātus}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consceleratus","latin":"consceleratus, conscelerata -um, consceleratior -or -us, consceleratissimus -a -um","headword":"consceleratus","letter":"c","pos":"adjective","posGroup":"adjective","english":"wicked, depraved; criminal; (person/actions)","forms":["cōnscelerātus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Neque umquam ex illō dēlendī huius imperī tam {{cōnscelerātus}} impetus exstitisset, nisi tot vitiōrum tanta immānitās quibusdam facilitātis et patientiae rādīcibus nīterētur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"conscendere","latin":"cōnscendere","headword":"cōnscendere","letter":"c","pos":"verb","posGroup":"verb","english":"to board, climb","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"conscendo","latin":"cōnscendō, cōnscendere","headword":"cōnscendō","letter":"c","pos":"verb","posGroup":"verb","english":"mount, board; go on board ship, embark","forms":["cōnscendentem","cōnscendentī","cōnscenderant","cōnscendērunt","cōnscendī","cōnscendimus","cōnscendit","cōnscendunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dāvīd, postquam solium {{cōnscendit}}, duplex scelus, et quidem gravissimum, commīsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conscia","latin":"conscia, consciae","headword":"conscia","letter":"c","pos":"noun","posGroup":"noun","english":"accomplice, accessory; partner; confidante; one privy to (crime/plot); witness","forms":["cōnscia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"(7 ac satis fīda), {{cōnscia}} tacitīs iocīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"conscientia","latin":"conscientia, conscientiae","headword":"conscientia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(joint) knowledge, complicity (of crime); conscience; sense of guilt, remorse","forms":["cōnscientiā","cōnscientiae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Agitābātur magis magisque in diēs animus ferōx inopia reī familiāris et cōnscientiā scelerum, quae utrāque iīs artibus auxerat quās suprā memorāvī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"conscindo","latin":"conscindo, conscindere, conscidi, conscissus","headword":"conscindo","letter":"c","pos":"verb","posGroup":"verb","english":"rend/tear to pieces, destroy by tearing; slaughter, cut to pieces","forms":["cōnscīssis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ubī ad aurēs Mardochaeī crūdēle ēdictum pervēnit, statim {{cōnscīssis}} vestibus saccum induit, cōnspersusque cinere perrēxit ad rēgiam, et illam implēvit questibus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"consciscere","latin":"(cōnscīscō) cōnscīscere, -īvisse, -ītum","headword":"cōnscīscere","letter":"c","pos":"","posGroup":"other","english":"decree, inflict (on)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conscisco","latin":"conscisco, consciscere, conscivi, conscitus","headword":"conscisco","letter":"c","pos":"verb","posGroup":"verb","english":"ordain/decree/determine/resolve; decide/inflict on; bring on oneself (w/sibi)","forms":["cōnscīvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quam iniūriam cum Arachnē aequō animō patī nōn posset, prīmum lacrimāns in locum fūgit, quō nēminem sē cōnsequī posse putābat; deinde laqueō mortem sibi ipsa {{cōnscīvit}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"conscius","latin":"cōnscius, -a, -um","headword":"cōnscius","letter":"c","pos":"adjective","posGroup":"adjective","english":"privy (to), accomplice (+ gen.)","forms":["cōnsciī","cōnsciīs","cōnscius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed spatiō temporis crīnis accīsus crēscere et cum crīne virtūs redīre coepit: iamque Samsōn, {{cōnscius}} receptī rōboris, iūstae ultiōnis tempus opperiēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conscribere","latin":"(cōnscrībō) cōnscrībere (< scrībere)","headword":"cōnscrībere","letter":"c","pos":"","posGroup":"other","english":"enroll, compose, write","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conscribo","latin":"conscribo, conscribere, conscripsi, conscriptus","headword":"conscribo","letter":"c","pos":"verb","posGroup":"verb","english":"enroll/enlist/raise (army); write on/down, commit to/cover with writing; compose","forms":["cōnscrīpserat","cōnscrīpsit","cōnscrīptae","cōnscrīptās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eōdem tempore et centuriae trēs equitum {{cōnscrīptae}} sunt: \"Ramnēnsēs\" ab Rōmulō, ab T.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conscriptus","latin":"conscriptus, conscripti","headword":"conscriptus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"senator/counselor; enrolling of the people for the purpose of bribery (L+S)","forms":["cōnscrīptī","cōnscrīptō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ancus, dēmandātā cūrā sacrōrum flāminibus sacerdōtibusque aliīs, exercitū novō cōnscrīptō profectus, Politorium, urbem Latīnōrum, vī cēpit; secūtusque mōrem rēgum priōrum, quī rem Rōmānam auxerant hostibus in cīvitātem accipiendīs, multitūdinem omnem Rōmam trādūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consecrare","latin":"(cōnsecrō) cōnsecrāre","headword":"cōnsecrāre","letter":"c","pos":"verb","posGroup":"verb","english":"consecrate; to consecrate, dedicate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"consecratus","latin":"consecratus, consecrata -um, consecratior -or -us, consecratissimus -a -um","headword":"consecratus","letter":"c","pos":"adjective","posGroup":"adjective","english":"consecrated, holy, sacred","forms":["cōnsecrāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aedēs Castoris {{cōnsecrāta}} est dīs Castorī et Pollūcī, Iovis fīliīs geminīs, quī saepius Rōmānīs in proeliīs auxiliō vēnērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consecro","latin":"consecro, consecrare, consecravi, consecratus","headword":"consecro","letter":"c","pos":"verb","posGroup":"verb","english":"consecrate/dedicate, set apart; hallow, sanctify; deify; curse; vow to a god","forms":["cōnsecrābant","cōnsecrātum","cōnsecrāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē admonitus ā Deō Samūēl annuit eōrum postulātiōnī, et Saūlem rēgem {{cōnsecrāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"consenescere","latin":"(cōnsenēscō) cōnsenēscere, -uisse","headword":"cōnsenēscere","letter":"c","pos":"","posGroup":"other","english":"grow old","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consenesco","latin":"consenesco, consenescere, consenui, -","headword":"consenesco","letter":"c","pos":"verb","posGroup":"verb","english":"grow old; grow old together; spend one's whole life/grow old in; decay, spoil","forms":["cōnsenuērunt","cōnsenuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tertiō annō post rēgēs exāctōs Tarquinius, cum suscipī nōn posset in rēgnum neque eī Porsenna, quī pācem cum Rōmānīs fēcerat, praestāret auxilium, Tusculum sē contulit, quae cīvitās nōn longē ab urbe est, atque ibi per quattuordecim annōs prīvātus cum uxōre {{cōnsenuit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consensio","latin":"consensio, consensionis","headword":"consensio","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"agreement (opinion), consent, accordance, harmony; unanimity; plot, conspiracy","forms":["consensio","cōnsēnsiōnem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tamen tanta universae Galliae {{consensio}} fuit libertatis vindicandae et pristinae belli laudis reciperandae, ut neque beneficis neque amicitiae memoria moverentur, omnesque et animo et opibus in id bellum incumberent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consensus","latin":"cōnsēnsus, -ūs","headword":"cōnsēnsus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"concord, agreement","forms":["consensu","consensui","cōnsēnsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Celeriter sibi Senones, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui Oceanum attingunt adiungit; omnium {{consensu}} ad: eum defertur imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consentio","latin":"consentio, consentire, consensi, consensus","headword":"consentio","letter":"c","pos":"verb","posGroup":"verb","english":"join/share in sensation/feeling; be in agreement/harmony; be of the same mind","forms":["cōnsēnsērunt","cōnsēnsit","cōnsentīre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haud difficileter persuāsit Latīnīs, quamquam in eō foedere superior Rōmāna rēs erat; cēterum et capita nōminis Latīnī {{cōnsentīre}} cum rēge vidēbant, et Turnī suppliciō terrēbantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consentire","latin":"(cōnsentiō) cōnsentīre (< sentīre)","headword":"cōnsentīre","letter":"c","pos":"","posGroup":"other","english":"agree (on)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consequi","latin":"(cōnsequor) cōnsequī, cōnsecūtum","headword":"cōnsequī","letter":"c","pos":"","posGroup":"other","english":"follow, overtake","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"consequor","latin":"consequor, consequi, consecutus sum","headword":"consequor","letter":"c","pos":"verb","posGroup":"verb","english":"follow, go/come after; attend on; pursue; catch up with, overtake; follow up","forms":["cōnsecūta","cōnsecūtī","consecutus","cōnsequar","cōnsequātur","cōnsequendī","cōnsequerētur","consequi","consequitur","cōnsequuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ille oppidum Biturigum positum in via Noviodunum oppugnare instituerat. (Quo ex oppido cum legati ad eum venissent oratum ut sibi ignosceret suaeque vitae consuleret, ut celeritate reliquas res conficeret, qua pleraque erat {{consecutus}}, arma conferri, equos produci, obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conserere","latin":"(cōnserō) cōnserere, -uisse, -tum","headword":"cōnserere","letter":"c","pos":"","posGroup":"other","english":"join, connect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consero","latin":"consero, conserere, conserui, consertus","headword":"consero","letter":"c","pos":"verb","posGroup":"verb","english":"connect/link, fasten/press/put together; construct/compose; join, engage (in)","forms":["cōnsererent","cōnseruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Porrō Samūēl ēdīxerat, ut sē per septem diēs exspectārent, nēve manum cum hoste prius {{cōnsererent}}, quam ipse, veniēns, Deō sacrificium faceret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conservare","latin":"(cōnservō) cōnservāre","headword":"cōnservāre","letter":"c","pos":"","posGroup":"other","english":"preserve, maintain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conservator","latin":"cōnservātor, -ōris (m.)","headword":"cōnservātor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"savior, guardian; preserver, guardian","forms":["cōnservātōrēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nihil est enim illī prīncipī deō quī omnem mundum regit (quod quidem in terrīs fīat) acceptius quam concilia coetūsque hominum iūre sociātī, quae \"cīvitātēs\" appellantur; hārum rēctōrēs et {{cōnservātōrēs}} hinc profectī hūc revertuntur.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conservo","latin":"conservō (1)","headword":"conservō","letter":"c","pos":"verb","posGroup":"verb","english":"keep, preserve","forms":["cōnservandam","cōnservandī","cōnservāre","cōnservāret","cōnservārī","cōnservāta","cōnservātam","cōnservātīs","conservatos","cōnservātūrus","cōnservāverint","cōnservāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caesar, nuntiis ad civitatem Aeduorum missis qui suo beneficio {{conservatos}} docerent quos iure belli interficere potuisset, tribusque horis noctis exercitui ad quietem datis, castra ad Gergoviam movit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conservus","latin":"conservus, conservi","headword":"conservus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"fellow-slave; companion in servitude (L+S)","forms":["cōnservum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nunc, cum esse crēdent servum et {{cōnservum}} suum,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"considerare","latin":"(cōnsīderō) cōnsīderāre","headword":"cōnsīderāre","letter":"c","pos":"","posGroup":"other","english":"observe, reflect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"considerate","latin":"considerate, consideratius, consideratissime","headword":"considerate","letter":"c","pos":"adverb","posGroup":"adverb","english":"carefully, cautiously, considerately; upon consideration","forms":["cōnsīderāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nunc quid agendum sit {{cōnsīderāte}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consideratio","latin":"cōnsīderātiō, -ōnis ( f.)","headword":"cōnsīderātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"consideration, reflection; consideration, contemplation","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"consideratus","latin":"consideratus, considerata -um, consideratior -or -us, consideratissimus -a -um","headword":"consideratus","letter":"c","pos":"adjective","posGroup":"adjective","english":"thought out, careful, considered (thing); cautious/deliberate/careful (person)","forms":["cōnsīderātā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque addūctus est ad Saūlem, quī, cōnsīderātā eius aetāte, diffīdēbat pugnae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"considero","latin":"considero, considerare, consideravi, consideratus","headword":"considero","letter":"c","pos":"verb","posGroup":"verb","english":"examine/look at/inspect; consider closely, reflect on/contemplate; investigate","forms":["cōnsīderābat","Cōnsīderāns","cōnsīderantis","cōnsīderāret","cōnsīderō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Frātrēs igitur invidēbant eī; at pater rem tacitus {{cōnsīderābat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"considit","latin":"cōnsīdit","headword":"cōnsīdit","letter":"c","pos":"verb","posGroup":"verb","english":"sits down","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"consido","latin":"cōnsīdō, cōnsīdere","headword":"cōnsīdō","letter":"c","pos":"verb","posGroup":"verb","english":"sit down","forms":["cōnsēderant","consederat","cōnsēdēre","cōnsēderis","cōnsēdērunt","cōnsēdissent","cōnsēdisset","consedit","cōnsīde","cōnsīdēbat","cōnsīdēns","cōnsīderās","considere","cōnsīderēmus","cōnsīderent","Cōnsīderēs","cōnsīderet","cōnsīdimus","cōnsīdis","cōnsīdit","cōnsīdite","cōnsīditis","cōnsīdō","considunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Is cum animadvertisset perpetuam esse paludem quae influeret in Sequanam atque illum omnem locum magnopere impediret, hic {{consedit}} nostrosque transitu prohibere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consilium","latin":"cōnsilium, -ī","headword":"cōnsilium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"plan; plan, advice; plan, purpose","forms":["consili","consilia","cōnsiliī","consiliis","consilio","cōnsiliōrum","consilium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello {{consilia}} inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consimile","latin":"consimile, consimilis","headword":"consimile","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"similar things (pl.); and the like (L+S)","forms":["cōnsimile"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"itidem habet petasum ac vestītum—tam {{cōnsimile}}'st atque ego:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"consimilis","latin":"consimilis, consimilis, consimile","headword":"consimilis","letter":"c","pos":"adjective","posGroup":"adjective","english":"like, very similar; similar in all respects (L+S)","forms":["cōnsimilis"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"I mōnstrāns] Tam similis est imāgō, tam {{cōnsimilis}} est quam fierī potest.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"consistens","latin":"Consistens, Consistentis","headword":"Consistens","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"class (pl.) of penitents in early Church","forms":["cōnsistēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"{{Cōnsistēns}} dēmum in herbā cōnsēdit ut rēte piscibus complētum siccāret atque piscēs captōs numerāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"consistit","latin":"cōnsistit, cōnsistunt","headword":"cōnsistit","letter":"c","pos":"verb","posGroup":"verb","english":"stop, halt; stops, halts; stops, halts, takes a stand","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"consisto","latin":"consisto, consistere, constiti, constitus","headword":"consisto","letter":"c","pos":"verb","posGroup":"verb","english":"stop/stand/halt/cease; pause, linger; stop spreading/flowing; take a position","forms":["cōnsistat","Cōnsiste","consistebat","consistendi","consistere","cōnsisterent","Cōnsistimus","cōnsistit","cōnsistunt","cōnstitissem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Unam esse Aeduorum civitatem quae certissimam Galliae victoriam distineat; eius auctoritate reliquas contineri; qua traducta, locum {{consistendi}} Romanis in Gallia non fore.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consobrinus","latin":"consobrinus, consobrini","headword":"consobrinus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"first cousin (male); (on mother's side); children of sisters (L+S); relation","forms":["consobrino"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Commio Atrebati, Viridomaro et Eporedorigi Aeduis, Vercassivellauno Arverno, {{consobrino}} Vercingetorigis, summa imperi traditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consociare","latin":"(cōnsociō) cōnsociāre","headword":"cōnsociāre","letter":"c","pos":"","posGroup":"other","english":"associate, share","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consociatus","latin":"consociatus, consociata -um, consociatior -or -us, consociatissimus -a -um","headword":"consociatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"closely linked/associated; united (L+S); agreeing, harmonious","forms":["cōnsociātōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eum cōnsēnsum deōsque {{cōnsociātōs}} laudābat Servius inter prīmōrēs Latīnōrum, cum quibus pūblicē prīvātimque hospitia amīcitiāsque iūnxerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consocio","latin":"consocio, consociare, consociavi, consociatus","headword":"consocio","letter":"c","pos":"verb","posGroup":"verb","english":"associate/join/unite (in), share; bring in close relation/alliance/partnership","forms":["cōnsociant","cōnsociāvērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēgnum {{cōnsociant}}; imperium omne cōnferunt Rōmam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consolari","latin":"cōnsōlārī","headword":"cōnsōlārī","letter":"c","pos":"verb","posGroup":"verb","english":"to comfort","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"consolatio","latin":"consolatio, consolationis","headword":"consolatio","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"consolation; comfort/encouragement (act/instance); consoling fact/circumstance","forms":["cōnsōlātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sed Iacobus nōluit accipere {{cōnsōlātiōnem}}, dīxitque: ego dēscendam moerēns cum fīliō meō in sepulcrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"consolatur","latin":"cōnsōlātur, cōnsōlārī","headword":"cōnsōlātur","letter":"c","pos":"","posGroup":"other","english":"comfort, console","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"consolor","latin":"cōnsōlor","headword":"cōnsōlor","letter":"c","pos":"verb","posGroup":"verb","english":"to comfort; comfort, encourage","forms":["cōnsōlābor","cōnsōlāns","cōnsolantēs","Cōnsōlantur","Cōnsōlāre","cōnsōlārer","cōnsōlārī","cōnsōlātur","consolatus","cōnsōler","cōnsōlor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sic milites {{consolatus}} eodem die reducit in castra reliquaque quae ad oppugnationem pertinebant oppidi administrare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consonans","latin":"cōnsonāns, cōnsonantis","headword":"cōnsonāns","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) consonant","forms":["Cōnsonāns","cōnsonantēs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Litterae sunt aut vōcālēs aut {{cōnsonantēs}}: vōcālēs sunt Ā, Ē, I, Ō, V, Y; cēterae sunt cōnsonantēs. (Etiam I et V cōnsonantēs sunt in vocābulīs IAM, VEL, vōs, QVAM, cet.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"consono","latin":"consono, consonare, consonui, -","headword":"consono","letter":"c","pos":"verb","posGroup":"verb","english":"sound/utter/make noise together, harmonize; resound/re-echo; agree","forms":["cōnsonat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{cōnsonat}} terra, clāmōrem utrimque efferunt.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"conspectus","latin":"cōnspectus, -ūs","headword":"cōnspectus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) sight, view; conspicuous, remarkable","forms":["cōnspecta","cōnspectō","conspectu","conspectum","cōnspectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indignantes milites Caesar, quod {{conspectum}} suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conspergo","latin":"conspergo, conspergere, conspersi, conspersus","headword":"conspergo","letter":"c","pos":"verb","posGroup":"verb","english":"sprinkle/strew/spatter, cover with small drops/particles; diversify/intersperse","forms":["cōnspersit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus haec locūtus frātrem suum Beniamīnum complexus est, eumque lacrimīs {{cōnspersit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conspicere","latin":"(cōnspiciō) cōnspicere, cōnspexisse, cōnspectum","headword":"cōnspicere","letter":"c","pos":"verb","posGroup":"verb","english":"catch sight of, see; to catch sight of, notice","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"conspiciens","latin":"conspiciens, (gen.), conspicientis","headword":"conspiciens","letter":"c","pos":"adjective","posGroup":"adjective","english":"intelligent, having understanding","forms":["cōnspiciēns"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Symmachus cruōrem in faciē puerī {{cōnspiciēns}} “Quid?” inquit, “unde est cruor ille?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"conspicio","latin":"conspicio, conspicere, conspexi, conspectus","headword":"conspicio","letter":"c","pos":"verb","posGroup":"verb","english":"observe/see/witness; notice; watch; gaze/stare on; catch/be in sight of; face","forms":["cōnspexerat","conspexerunt","cōnspexī","cōnspexissent","cōnspexisset","cōnspexit","cōnspicere","conspici","cōnspiciet","cōnspiciō","cōnspicis","cōnspicit","conspiciuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quem simul atque oppidani {{conspexerunt}} atque in spem auxili venerunt, clamore sublato arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conspicit","latin":"cōnspicit","headword":"cōnspicit","letter":"c","pos":"verb","posGroup":"verb","english":"catches sight of, notices","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"conspicor","latin":"conspicor, conspicari, conspicatus sum","headword":"conspicor","letter":"c","pos":"verb","posGroup":"verb","english":"catch sight of, see; observe, notice; perceive; be conspicuous; be regarded","forms":["cōnspicāta","cōnspicātī","cōnspicātur","conspicatus","cōnspicor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Adhortatus milites ne necessario tempore itineris labore permoveantur, cupidissimis omnibus progressus milia passuum XXV, agmen Aeduorum {{conspicatus}}, immisso equitatu iter eorum moratur atque impedit; interdicitque omnibus ne quemquam interficiant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conspicuus","latin":"conspicuus, -a, -um","headword":"conspicuus","letter":"c","pos":"adjective","posGroup":"adjective","english":"conspicuous, spectacular; conspicuous, notable","forms":["cōnspicuīs","cōnspicuum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"vīsite {{cōnspicuīs}} terna theātra locīs;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"conspiratio","latin":"cōnspīrātiō, -ōnis ( f.)","headword":"cōnspīrātiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"agreement, conspiracy","forms":["Cōnspīrātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cōnspīrātiō inter trēs cīvitātis prīncipēs facta est: Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conspuo","latin":"conspuo, conspuere, conspui, consputus","headword":"conspuo","letter":"c","pos":"verb","posGroup":"verb","english":"spit on, sputter over; besplatter with saliva; (contempt); spit; spit it out","forms":["cōnspuētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Assilmpsit autem Jēsus duodecim discipulōs et ait illīs:\"Ecce, ascendimus Hierosolymam et cōnsummābuntur omnia quae scrlpta sunt dē Fīliō hominis: trādētur enim gentibus, et illūdētur, et flagellābitur, et {{cōnspuētur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"constans","latin":"cōnstāns","headword":"cōnstāns","letter":"c","pos":"adjective","posGroup":"adjective","english":"(gen.cōnstantis) steady, firm","forms":["cōnstāns","Cōnstantēs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Statimque Iēsus locūtus est eīs dīcēns: \"{{Cōnstantēs}} ēstote!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"constanter","latin":"constanter, constantius, constantissime","headword":"constanter","letter":"c","pos":"adverb","posGroup":"adverb","english":"firmly, immovably; steadily, constantly, without change; resolutely; loyally","forms":["cōnstanter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nam Tobiās adeō patienter tulit caecitātem, ut neque illum querentem quisquam audīerit, neque ille eō minus {{cōnstanter}} Deum coluerit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"constantia","latin":"cōnstantia, -ae","headword":"cōnstantia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"steadiness, persistence; firmness, constancy","forms":["cōnstantia","cōnstantiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Īnsignis fuit Eleazarī senis {{cōnstantia}}: is apertō ōre compellēbātur camem suillam comedere, quā Hidaeis lēx interdīcēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"constat","latin":"cōnstat, cōnstant","headword":"cōnstat","letter":"c","pos":"verb","posGroup":"verb","english":"cost, stand firm; costs (with a price)","forms":["cōnstābant","constabat","cōnstant","constare","cōnstāret","constat","constiterant","constiterat","cōnstitēre","cōnstiterit","constiterunt","constitissent","cōnstitit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi {{constiterant}}, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consternatus","latin":"consternatus, consternata, consternatum","headword":"consternatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"dismayed, confused, confounded, in consternation","forms":["consternati"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Simul in spem veniebant eius adfirmatione de reliquis adiungendis civitatibus; primumque eo tempore Galli castra munire instituerunt; et sic sunt animo {{consternati}} homines insueti laboris ut omnia quae imperarentur sibi patienda existimarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"constituere","latin":"(cōnstituō) cōnstituere, cōnstituisse,  cōnstitūtum","headword":"cōnstituere","letter":"c","pos":"verb","posGroup":"verb","english":"decide, fix; to decide, resolve","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"constituo","latin":"cōnstituō, -ere, -uī, -ūtum","headword":"cōnstituō","letter":"c","pos":"verb","posGroup":"verb","english":"decide, determine","forms":["constituebantur","constituerat","constituere","constitueret","cōnstituērunt","constitui","cōnstituimus","cōnstituisset","Cōnstituistī","constituit","cōnstitūtā","cōnstitūtam","cōnstitūtās","cōnstitūtī","constitutis","constituto","constituunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut {{constituerat}}, in Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"constitutio","latin":"cōnstitūtiō, -ōnis ( f.)","headword":"cōnstitūtiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"constitution; order, arrangement; constitution, ordering","forms":["cōnstitūtiō","cōnstitūtiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec cōnstitūtiō prīmum habet aequābilitātem quandam magnam, quā carēre diūtius vix possunt līberī, deinde firmitūdinem — quod et illa prīma facile in contrāria vitia convertuntur, ut exsistat ex rēge dominus, ex optimātibus factiō, ex populō turba et cōnfūsiō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"constitutum","latin":"constitutum, constituti","headword":"constitutum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"agreed arrangement, appointment; agreement to pay a sum on a date, note, IOU","forms":["cōnstitūtum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ā quō etiam aquilam illam argenteam, quam tibi ac tuīs omnibus cōnfīdō perniciōsam ac fūnestam futūram, cui domī tuae sacrārium scelerātum {{cōnstitūtum}} fuit, sciam esse praemissam?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"constitutus","latin":"constitutus, constituti","headword":"constitutus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"meeting","forms":["cōnstitūtus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Flāminiī, quī eōdem tempore viam Flāmīniam mūnīvit; tertius circus trāns Tiberim in agrō Vāticānō {{cōnstitūtus}} ā prīncipe C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"constrictus","latin":"constrictus, constricta -um, constrictior -or -us, constrictissimus -a -um","headword":"constrictus","letter":"c","pos":"adjective","posGroup":"adjective","english":"small/limited in size; marked by contraction/tightening; compressed/contracted","forms":["Cōnstrictam","constrīctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Trāditus Philistaeīs rūpit vincula, quibus {{constrīctus}} erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"construo","latin":"cōnstruō, -ere, -strūxī, -strūctum","headword":"cōnstruō","letter":"c","pos":"verb","posGroup":"verb","english":"build, construct","forms":["cōnstrūxit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Daedalus, quī celeberrimus in arte aedificandī erat, hunc labyrinthum {{cōnstrūxit}} quī lūmina in errōrem variārum viārum multīs flexibus dūceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"consuescere","latin":"(cōnsuēscō) cōnsuēscere, -ēvisse, -ētum","headword":"cōnsuēscere","letter":"c","pos":"","posGroup":"other","english":"get used/accustomed to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consuesco","latin":"consuesco, consuescere, consuevi, consuetus","headword":"consuesco","letter":"c","pos":"verb","posGroup":"verb","english":"accustom oneself; become/be accustomed/used; inure, habituate; familiarize","forms":["cōnsuēscat","cōnsuētum","consueverat","cōnsuēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Itaque, ne id accideret, silvestri loco castris positis e regione unius eorum pontium quos Vercingetorix rescindendos curaverat, postero die cum duabus legionibus in occulto restitit; reliquas copias cum omnibus impedimentis, ut {{consueverat}}, misit, apertis quibusdam cohortibus, uti numerus legionum constare videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consuetudo","latin":"cōnsuētūdō, -inis ( f.)","headword":"cōnsuētūdō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"custom, habit","forms":["consuetudine","consuetudinem","cōnsuētūdō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus {{consuetudine}} excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante tertiam vigiliam est animadversum fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consul","latin":"cōnsul, -is (m.)","headword":"cōnsul","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"consul","forms":["cōnsul","cōnsule","cōnsulem","cōnsulēs","cōnsulī","cōnsulibus","cōnsulis","cōnsulum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Cōnsule}} dē gemmīs, dē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"consularis","latin":"cōnsulāris, -e","headword":"cōnsulāris","letter":"c","pos":"adjective","posGroup":"adjective","english":"consular; (m.) an exconsul","forms":["cōnsulāre","cōnsulārem","cōnsulārēs","cōnsulārī","cōnsulāribus","cōnsulāris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Annō trecentēsimō et alterō ab urbe conditā imperium {{cōnsulāre}} cessāvit et prō duōbus cōnsulibus decem factī sunt quī summam potestātem habērent, 'decemvirī' nōminātī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consulatus","latin":"cōnsulātus, -ūs","headword":"cōnsulātus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"consulate; consulship","forms":["cōnsulātū","cōnsulātum","cōnsulātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōnō annō post rēgēs exāctōs, cum gener Tarquinī ad iniūriam socerī vindicandam ingentem collēgisset exercitum, nova Rōmae dignitās est creāta, quae dictātūra appellātur, maior quam {{cōnsulātus}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consulere","latin":"(cōnsulō) cōnsulere, -suluisse, consult, take -sultum","headword":"cōnsulere","letter":"c","pos":"","posGroup":"other","english":"counsel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consulo","latin":"consulo, consulere, consului, consultus","headword":"consulo","letter":"c","pos":"verb","posGroup":"verb","english":"ask information/advice of; consult, take counsel; deliberate/consider; advise","forms":["cōnsulam","consulant","consulat","cōnsulātis","cōnsulēmus","cōnsulendī","cōnsulendum","cōnsulente","cōnsulere","cōnsulerem","cōnsulerent","consuleret","cōnsulit","consulite","cōnsulitur","cōnsultūrum","cōnsuluerint","cōnsuluī","cōnsulundō","consulunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis {{consulat}} neve ab hostibus diripiantur, praesertim cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consultare","latin":"(cōnsultō) cōnsultāre","headword":"cōnsultāre","letter":"c","pos":"","posGroup":"other","english":"deliberate, debate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consultatio","latin":"consultatio, consultationis","headword":"consultatio","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"full/mature deliberation/consideration/discussion; consultation; inquiry","forms":["cōnsultātiōne"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vīsa est enim mihi rēs digna {{cōnsultātiōne}}, maximē propter perīclitantium numerum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"consulto","latin":"cōnsultō","headword":"cōnsultō","letter":"c","pos":"verb","posGroup":"verb","english":"deliverately","forms":["cōnsulta","consultabant","cōnsultant","cōnsultantēs","cōnsultāre","cōnsultāta","consulto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque {{consulto}} certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consultor","latin":"cōnsultor, -ōris (m.)","headword":"cōnsultor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"adviser, counselor","forms":["cōnsultor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Egomet in agmine aut in proeliō {{cōnsultor}} īdem et socius perīculī vōbīscum aderō, mēque vōsque in omnibus rēbus iuxtā geram.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consultum","latin":"cōnsultum, -ī","headword":"cōnsultum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"resolution","forms":["cōnsultum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque ingentī cōnsēnsū fit senātūs {{cōnsultum}} ut Hannibalī quattuor mīlia Numidārum in supplementum mitterentur et quadrāgintā elephantī et argentī talenta quīngenta.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consultus","latin":"consultus, consulti","headword":"consultus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"lawyer, jurist; (also jurisconsultus, one or two words); expert","forms":["cōnsultus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Iugurtha, contrā spem nūntiō acceptō, fīlium et cum eō duōs familiārēs ad senātum lēgātōs mittit iīsque praecipit 'omnēs mortālēs pecūniā aggrediantur!' Quī postquam Rōmam adventābant, senātus ā Bestiā {{cōnsultus}} 'placeretne lēgātōs Iugurthae recipī moenibus?' iīque dēcrēvēre 'nisi rēgnum ipsumque dēditum vēnissent, utī in diēbus proximīs decem Ītaliā dēcēderent!' Ita infectīs rēbus illī domum discēdunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"consumere","latin":"(cōnsūmō) cōnsūmere,  cōnsūmpsisse, cōnsūmptum","headword":"cōnsūmere","letter":"c","pos":"verb","posGroup":"verb","english":"consume, spend; to use up, spend; to consume, destroy","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"consummo","latin":"consummo, consummare, consummavi, consummatus","headword":"consummo","letter":"c","pos":"verb","posGroup":"verb","english":"add/reckon/total/sum/make up; finish off, end; bring about, achieve/accomplish","forms":["cōnsummābuntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Assilmpsit autem Jēsus duodecim discipulōs et ait illīs:\"Ecce, ascendimus Hierosolymam et {{cōnsummābuntur}} omnia quae scrlpta sunt dē Fīliō hominis: trādētur enim gentibus, et illūdētur, et flagellābitur, et cōnspuētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"consumo","latin":"cōnsūmō, -ere, -sūmpsī, -sūmptum","headword":"cōnsūmō","letter":"c","pos":"verb","posGroup":"verb","english":"to consume, wear away","forms":["cōnsūmēbant","cōnsūmēbātur","cōnsūmere","cōnsūmet","cōnsūmit","cōnsūmitur","consumpserunt","cōnsūmpsī","cōnsūmpsit","cōnsūmptā","cōnsūmptī","Cōnsūmptīs","consumpto","consumptum","cōnsūmptus","CŌNSVMPTVM"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non multum adiuvabant, alteri non magnis facultatibus, quod civitas erat exigua et infirma, celeriter quod habuerunt {{consumpserunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consuo","latin":"consuo, consuere, consui, consutus","headword":"consuo","letter":"c","pos":"verb","posGroup":"verb","english":"sew together/up, stitch/join; make by sewing together; patch up; devise, plan","forms":["consuerant","consuerat","consuerunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Conclamat omnis multitudo et suo more armis concrepat, quod facere in eo {{consuerunt}} cuius orationem approbant: summum esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"consurgere","latin":"(cōnsurgō) cōnsurgere (<surgere)","headword":"cōnsurgere","letter":"c","pos":"","posGroup":"other","english":"stand up, rise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"consurgo","latin":"consurgo, consurgere, consurrexi, consurrectus","headword":"consurgo","letter":"c","pos":"verb","posGroup":"verb","english":"rise/stand up (body of people); rise (jury/from meal/to speak/from bed); ambush","forms":["cōnsurgēns","Consurrēxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cōnfestim pater, {{cōnsurgēns}}, coepit, offendēns pedibus, currere, et, datā manū servō, prōcessit obviam fīliō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"contabulo","latin":"contabulo, contabulare, contabulavi, contabulatus","headword":"contabulo","letter":"c","pos":"verb","posGroup":"verb","english":"board over, cover with boards; furnish with roof/floor/bridge; build; bridge","forms":["contabulaverant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Totum autem murum ex omni parte turribus {{contabulaverant}} atque has coriis intexerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contagio","latin":"contagio, contagionis","headword":"contagio","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"contact/touch (to contagion/infection); social contact/intercourse; influence","forms":["contāgiō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Neque cīvitātēs tantum, sed vīcōs etiam atque agrōs superstitiōnis istīus contāgiō pervagāta est.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"contaminatus","latin":"contaminatus, contaminata -um, contaminatior -or -us, contaminatissimus -a -um","headword":"contaminatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"contaminated, polluted, adulterated; used, second-hand, soiled by use; profane","forms":["contaminati"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Haec faciunt reciperandorum suorum causa; sed {{contaminati}} facinore et capti compendio ex direptis bonis, quod ea res ad multos pertinebat, timore poenae exterriti consilia clam de bello inire incipiunt civitatesque reliquas legationibus sollicitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contamino","latin":"contamino, contaminare, contaminavi, contaminatus","headword":"contamino","letter":"c","pos":"verb","posGroup":"verb","english":"corrupt, defile (w/filth/intercourse), stain, befoul spoil; ruin, dishonor","forms":["contāminābant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, homicīdium; ūnō verbō, sē {{contāminābant}} omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"contego","latin":"contego, contegere, contexi, contectus","headword":"contego","letter":"c","pos":"verb","posGroup":"verb","english":"cover up, conceal, hide; protect; clothe; roof over; bury/entomb; strew thickly","forms":["contegit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Agger ab universis in munitionem coniectus et ascensum dat Gallis et ea quae in terra occultaverant Romani {{contegit}}; nec iam arma nostris nec vires suppetunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contemnendus","latin":"contemnendus, contemnenda, contemnendum","headword":"contemnendus","letter":"c","pos":"adjective","posGroup":"adjective","english":"be despised/neglected; [w/negative => considerable, not negligible]","forms":["contemnendus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"nēre) — {{contemnendus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"contemnere","latin":"(contemnō) contemnere, contēmpsisse, contēmptum","headword":"contemnere","letter":"c","pos":"verb","posGroup":"verb","english":"think little of, scorn; to despise; to value little, disdain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"contemno","latin":"contemno, contemnere, contempsi, contemptus","headword":"contemno","letter":"c","pos":"verb","posGroup":"verb","english":"think little of; look down on, take poor view of; pay no heed/disregard/slight","forms":["contemnant","contemnar","contemnās","contemnēbant","contemnēbat","contemnēns","contemnentēs","contemnere","contemnerent","contemneret","contemnis","contemnit","contemnitis","contemnitō","contemnō","Contemnunt","contempserīs","contempsī","contempsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum extrēmum spīritum ageret, ad rēgem conversus:\"Tū quidem\"ait,\"hanc vltam nōbīs ēripis, sed āmissam nōbīs reddet Deus, prō cuius lēge linguam postulanfī prōtulit amputandam, manusque prōtendēns, dīxit:\"Haec membra, ā Deō acceptā, nunc propter Deum contemnō, quia spērō fore ut eā reciperem.\"Rēx et aliī circumstantēs admīrābantur animum adulēscentis, quī acerbissimum dolōrem prō nihilō dūcēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"contemplari","latin":"(contemplor) contemplārī","headword":"contemplārī","letter":"c","pos":"","posGroup":"other","english":"look at, observe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contemplatus","latin":"contemplatus, contemplatus","headword":"contemplatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"contemplation, pondering; consideration (L+S); observance; regard, respect","forms":["Contemplātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Contemplātus}} omnia quae nōscenda erant, quattuor simul locīs aggredī urbem cōnstituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"contemplo","latin":"contemplo, contemplare, contemplavi, contemplatus","headword":"contemplo","letter":"c","pos":"verb","posGroup":"verb","english":"observe/note/notice, gaze/look hard at, regard; contemplate/consider carefully","forms":["contemplāns","contemplantī","contemplārī","contemplō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"SOSIA: [Mercurium īnspiciēns] Certē edepol, cum illum contemplō et fōrmam cognōscō meam,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"contemptor","latin":"contemptor, -ōris","headword":"contemptor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"a despiser","forms":["contemptor"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ūna ē quibus, \"en,\" ait, \"en, hīc est {{contemptor}} nostrī,\" et hastam in ōra vātis Phoebī mīsit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"contemptus","latin":"contēmptus, -a, -um","headword":"contēmptus","letter":"c","pos":"adjective","posGroup":"adjective","english":"despicable","forms":["contempta","contemptior","contemptō","contemptus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Cyānē dolēns et deam raptam et iūra fontis suī {{contempta}} mente tācitā vulnus gerit et omnis in lacrimās convertitur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"contendo","latin":"contendo, contendere, contendi, contentus","headword":"contendo","letter":"c","pos":"verb","posGroup":"verb","english":"stretch, draw tight, make taut; draw/bend (bow/catapult); tune; stretch out","forms":["contendant","Contende","contendēbat","contenderant","contendere","contenderet","contenderunt","contendi","contendisse","contendit","contendite","contenditur","contendunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum {{contenderet}}, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contentio","latin":"contentiō, -ōnis ( f.)","headword":"contentiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"tension, exertion","forms":["contentio","contentione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His erat inter se de principatu {{contentio}}, et in illa magistratuum controversia alter pro Convictolitavi, alter pro Coto summis opibus pugnaverant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contentus","latin":"contentus, -a, -um","headword":"contentus","letter":"c","pos":"adjective","posGroup":"adjective","english":"stretched, content, satisfied; satisfied, content","forms":["contenta","contentam","contenti","contentō","contentus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam, quamquam multī et mortālēs et immortālēs eam amābant, omnēs virōs omnēsque deōs fugere solēbat, sōlīs suīs frūgibus pōmīsque {{contenta}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"contero","latin":"contero, conterere, contrivi, contritus","headword":"contero","letter":"c","pos":"verb","posGroup":"verb","english":"grind, crush, pound to pieces; bruise, crumble; rub/wipe away/out/off, expunge","forms":["conteret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Inimīcitiae erunt inter tē et mulierem; ipsa ōlim {{conteret}} caput tuum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conterritus","latin":"conterritus, conterrita, conterritum","headword":"conterritus","letter":"c","pos":"adjective","posGroup":"adjective","english":"frightened; terrorized","forms":["conterritus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ego mäiestāte {{conterritus}} praetôrem putābam vēnisse; itaque temptävî assurgere et nüdôs pedēs in tcrram dēferre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"contexo","latin":"contexo, contexere, contexui, contextus","headword":"contexo","letter":"c","pos":"verb","posGroup":"verb","english":"weave/entwine/braid/twist together; compose/connect/link/combine; make/join/form","forms":["contexitur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sic deinceps omne opus {{contexitur}}, dum iusta muri altitudo expleatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conticescere","latin":"(conticēscō) conticēscere,","headword":"conticēscere","letter":"c","pos":"","posGroup":"other","english":"fall silent conticuisse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conticesco","latin":"conticesco, conticescere, conticui, -","headword":"conticesco","letter":"c","pos":"verb","posGroup":"verb","english":"cease to talk, fall silent, lapse into silence; cease to function, become idle","forms":["cōnticuēre","cōnticuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum {{cōnticuēre}} omnēs intentīque ōra tenēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"contiguus","latin":"contiguus, contigua, contiguum","headword":"contiguus","letter":"c","pos":"adjective","posGroup":"adjective","english":"near, adjoining/adjacent/neighboring; bordering upon; within reach","forms":["contiguus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ennius é-meruit (7 meruit) {{contiguus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"continens","latin":"continēns, -entis","headword":"continēns","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"unbroken, adjacent; continent","forms":["continēns","continentem","continentēs","continenti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis imbribus tardarentur, tamen {{continenti}} labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"continentia","latin":"continentia, -ae","headword":"continentia","letter":"c","pos":"","posGroup":"other","english":"restraint, self-control","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contineo","latin":"contineō, -ēre, continuī, contentum","headword":"contineō","letter":"c","pos":"verb","posGroup":"verb","english":"hold together, keep, defend","forms":["contentum","continē","contineantur","contineat","continēbant","continebantur","continēbātur","continent","continentur","contineō","continēre","continērēmur","contineret","continērētur","contineri","continet","continetur","continuisse","continuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia {{continetur}}, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"continere","latin":"(contineō) continēre, continuisse,  contentum","headword":"continēre","letter":"c","pos":"","posGroup":"other","english":"contain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"contingere","latin":"(contingō) contingere, -tigisse,","headword":"contingere","letter":"c","pos":"","posGroup":"other","english":"touch, be close to, be granted,","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contingit","latin":"contingit, contingere, contigit, contactus est","headword":"contingit","letter":"c","pos":"verb","posGroup":"verb","english":"it happens, it turns out; (PERF) it came to pass","forms":["contingit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et dīxit adolēscentior patrī: ' P āter, dā mihi portiōnem substantiae quae mē {{contingit}}. ' Et pater dīvīsit illī substantiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"contingo","latin":"contingō, -ere, -tigī, -tāctum","headword":"contingō","letter":"c","pos":"verb","posGroup":"verb","english":"to touch; to fall to one's lot","forms":["contigerant","contigerat","contigerint","contigerit","contigissent","contigit","contingant","contingat","contingebat","contingent","contingere","contingeret","contingunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eo cum venisset, timentes confirmat, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum {{contingunt}}, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"continuare","latin":"(continuō) continuāre","headword":"continuāre","letter":"c","pos":"","posGroup":"other","english":"continue, prolong","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"continuatus","latin":"continuatus, continuata, continuatum","headword":"continuatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"uninterrupted/unbroken; consecutive; contiguous/adjacent to; permanent (Latham)","forms":["continuātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Per quattuor et vīgintī diēs, ita ut nūllum tempus vacuum dīmicātiōne esset, adversus quattuor ē partibus simul oppugnantem hostem nocturnus diurnō {{continuātus}} labor est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"continuo","latin":"continuō","headword":"continuō","letter":"c","pos":"adverb","posGroup":"adverb","english":"immediately; at once, immediately","forms":["continua","continuāre","continuās","continuātō","continuēre","continuo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hos {{continuo}} in itinere adorti omnibus impedimentis exuunt; repugnantes diem noctemque obsident; multis utrimque interfectis maiorem multitudinem ad arma concitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"continuum","latin":"continuum, continui","headword":"continuum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"continuum","forms":["continuum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hic fīnis bellī, cum quadriennium {{continuum}} bellātum esset, inter Rōmānōs ac Persea fuit, idemque fīnis inclūtī per Eurōpae plērumque atque Asiam omnem rēgnī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"continuus","latin":"continuus, -a, -um","headword":"continuus","letter":"c","pos":"adjective","posGroup":"adjective","english":"continuous, successive","forms":["continuae","continuis","continuus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vercingetorix, tot {{continuis}} incommodis Vellaunoduni, Cenabi, Novioduni acceptis, suos ad concilium convocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contio","latin":"cōntiō, -ōnis ( f.)","headword":"cōntiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"meeting, assembly; assembly, public meeting","forms":["contione","cōntiōnem","cōntiōnis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postero die Caesar {{contione}} advocata temeritatem cupiditatemque militum reprehendit, quod sibi ipsi iudicavissent quo procedendum aut quid agendum videretur neque signo recipiendi dato constitissent neque ab tribunis militum legatisque retineri potuissent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contionari","latin":"(cōntiōnor) cōntiōnārī","headword":"cōntiōnārī","letter":"c","pos":"","posGroup":"other","english":"address a meeting","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contionor","latin":"contionor, contionari, contionatus sum","headword":"contionor","letter":"c","pos":"verb","posGroup":"verb","english":"address assembly, deliver public speech; preach/harangue; attend public meeting","forms":["contiōnantem","contiōnātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Albānī, ut rēgem Rōmānum {{contiōnantem}} audīrent, proximī cōnstitēre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"contonat","latin":"contonat, contonare, contonavit, -","headword":"contonat","letter":"c","pos":"verb","posGroup":"verb","english":"it thunders violently/loudly/heavily","forms":["contonat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ibi continuō {{contonat}}","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"contra","latin":"contrā","headword":"contrā","letter":"c","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) against","forms":["contra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque deiecti in foro ac locis patentioribus cuneatim constiterunt, hoc animo ut, si qua ex parte obviam {{contra}} veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contracto","latin":"contracto, contractare, contractavi, contractatus","headword":"contracto","letter":"c","pos":"verb","posGroup":"verb","english":"handle, finger, touch repeatedly; feel; handle unlawfully (theft/embezzlement)","forms":["contractā","contrāctō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Gedeōn, contrāctō exercitū, profectus est cum duōbus et trīgintā mīlibus hominum, et castra castrīs hostium contulit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"contradicere","latin":"(contrādīcō) contrādīcere (< dīcere)","headword":"contrādīcere","letter":"c","pos":"","posGroup":"other","english":"speak against, oppose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contradico","latin":"contradico, contradicere, contradixi, contradictus","headword":"contradico","letter":"c","pos":"verb","posGroup":"verb","english":"gainsay/contradict; speak against/speak for adversary, oppose/object to/contest","forms":["contrādīcente","Contrādictum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vērum cum impatientiā Varrōnis cōnsulis — {{contrādīcente}} alterō cōnsule — apud vīcum quī Cannae appellātur in Āpūliā pugnātum esset, ambō cōnsulēs ab Hannibale vincuntur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"contrahere","latin":"(contrahō) contrahere, -trāxisse, -tractum","headword":"contrahere","letter":"c","pos":"","posGroup":"other","english":"contract","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"contraho","latin":"contraho, contrahere, contraxi, contractus","headword":"contraho","letter":"c","pos":"verb","posGroup":"verb","english":"enter into/upon relationship/agreement/business/marriage/loan/battle, deal with","forms":["contrahenda","contraheret","contrahī","contrahit","contrahitur","contrahuntur","contrāxerat","contrāxistis","contrāxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati praecipue indulserat, nulla interposita dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad {{contrahenda}} castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contrarius","latin":"contrārius, -a, -um","headword":"contrārius","letter":"c","pos":"adjective","posGroup":"adjective","english":"opposite, contrary","forms":["contrāria","contrāriae","contrāriam","contrāriās","contrāriīs","contrario","contrārius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res adversae auctoritatem minuunt, sic huius ex {{contrario}} dignitas incommodo accepto in dies augebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contremescere","latin":"(contremēscō) contremēscere, -muisse","headword":"contremēscere","letter":"c","pos":"verb","posGroup":"verb","english":"tremble, quake; to tremble greatly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"contremesco","latin":"contremesco, contremescere, contremui, -","headword":"contremesco","letter":"c","pos":"verb","posGroup":"verb","english":"tremble all over; shake (violently), quake; tremble at/with fear, be afraid of","forms":["contremuērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc sēnsit Polyphēmus, sed cum eōs capere nōn posset, clāmōrem horribilem sustulit, quō mare et terrae {{contremuērunt}} atque penitus resonuit mōns cavus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"controversia","latin":"controversia, controversiae","headword":"controversia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"controversy/dispute; debate; moot case debated in school, forensic exercise","forms":["controversia","controversiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quod si diutius alatur {{controversia}}, fore uti pars cum parte civitatis confligat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contueor","latin":"contueor, contueri, contuitus sum","headword":"contueor","letter":"c","pos":"verb","posGroup":"verb","english":"look at/gaze on/behold; see to; be in sight of, have view of; contemplate/weigh","forms":["contuērī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Igitur altē spectāre sī volēs atque hanc sēdem et aeternam domum contuērī, neque tē sermōnibus vulgī dederis, nec in praemiīs hūmānīs spem posueris rērum tuārum!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"contueri","latin":"(contueor) contuērī (< tuērī)","headword":"contuērī","letter":"c","pos":"","posGroup":"other","english":"look at, contemplate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"contumelia","latin":"contumēlia, -ae","headword":"contumēlia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"insult, affront; insult, abuse","forms":["contumelia","contumēliam","contumēliīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praestare visum est tamen omnes difficultates perpeti quam tanta {{contumelia}} accepta omnium suorum voluntates alienare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"contumeliosus","latin":"contumēliōsus, -a, -um","headword":"contumēliōsus","letter":"c","pos":"adjective","posGroup":"adjective","english":"insulting, outrageous; insulting, abusive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"contundo","latin":"contundo, contundere, contudi, contusus","headword":"contundo","letter":"c","pos":"verb","posGroup":"verb","english":"quell/crush/outdo/subdue utterly; bruise/beat; pound to pieces/powder/pulp","forms":["contudit","contundit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Philistaeōs mulfis proelils {{contudit}}, IŪdaeōsque ā tribufīs, quae pendēbant Assyriīs, līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"conturbare","latin":"(conturbō) conturbāre, conturbāvisse, conturbātum","headword":"conturbāre","letter":"c","pos":"","posGroup":"other","english":"mix up, confound","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"conturbo","latin":"conturbo, conturbare, conturbavi, conturbatus","headword":"conturbo","letter":"c","pos":"verb","posGroup":"verb","english":"confuse, disquiet/confound/derange/dismay, upset/mix up; go bankrupt, default","forms":["conturbabimus","conturbāre","conturbātur"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{conturbabimus}} illa, ne sciamus,","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"contusum","latin":"contusum, contusi","headword":"contusum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"bruise, contusion","forms":["contūsum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque tôtum circumspicere triclînium coepî, nē per parietem aūtō- matum aliquod exîret, utique postquam servus verberärî coepit quî bracchium dominî {{contūsum}} albā potius quam conchÿliātä involverat lānä.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"conubium","latin":"cōnūbium, -ī","headword":"cōnūbium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"marriage, intermarriage; marriage, union; marriage, right of intermarriage","forms":["cōnūbia","cōnūbiī","cōnūbiīs","cōnūbiō","cōnūbium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Egō per hās lacrimās, per dextram tuam, per {{cōnūbium}} nostrum tē ōrō: sī quid bene dē tē meruī, aut sī tibi dulce fuit quidquam meum, miserēre meī et mūtā iam mentem!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conus","latin":"conus, coni","headword":"conus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cone, conical figure/shape; apex of helmet; form of sundial; pine cone; tenpin","forms":["cōnī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dīxerit cōnī perf : fortasse dīcet Dīxerit ē multīs aliquis:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"convalescere","latin":"(convalēscō) convalēscere (< valēre)","headword":"convalēscere","letter":"c","pos":"","posGroup":"other","english":"grow strong, recover","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"convalesco","latin":"convalesco, convalescere, convalui, convalitus","headword":"convalesco","letter":"c","pos":"verb","posGroup":"verb","english":"grow strong/thrive/gain power; regain health/strength, recover, get well/better","forms":["convalēscere","convalēscit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fīdēnātēs, cum nimis vīcīnam urbem prope sē {{convalēscere}} vidērent, priusquam tam valida esset quam futūra esse vidēbātur, properant bellum facere.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"convallis","latin":"convallis, convallis","headword":"convallis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"valley (much shut in), ravine, deep/narrow/enclosed valley, glen; (also pl.)","forms":["convallēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et mūrō lapideō, cuius operis exōrdium Sabīnō bellō turbātum erat, urbem cingere parat, et īnfima urbis loca circā forum aliāsque {{convallēs}} collibus interiectās cloācīs in Tiberim ductīs siccat, et aedis in Capitōliō Iovis, quam vōverat bellō Sabīnō, fundāmenta iacit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"convehere","latin":"(convehō) convehere (< vehere)","headword":"convehere","letter":"c","pos":"","posGroup":"other","english":"carry, gather","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"conveho","latin":"conveho, convehere, convexi, convectus","headword":"conveho","letter":"c","pos":"verb","posGroup":"verb","english":"bring/carry/bear together/to one place; collect, gather; get in (harvest) (L+S)","forms":["convectum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His rebus perfectis, regiones secutus quam potuit aequissimas pro loci natura, XIIII milia passuum complexus pares eiusdem generis munitiones, diversas ab his, contra exteriorem hostem perfecit, ut ne magna quidem multitudine, si ita accidat, eius discessu munitionum praesidia circumfundi possent; ne autem cum periculo ex castris egredi cogatur, dierum XXX pabulum frumentumque habere omnes {{convectum}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conveniens","latin":"conveniens, convenientis (gen.), convenientior -or -us, convenientissimus -a -um","headword":"conveniens","letter":"c","pos":"adjective","posGroup":"adjective","english":"fitting; appropriate; comfortable; internally consistent, harmonious","forms":["conveniēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sit bene {{conveniēns}} et sine làbe toga.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"convenio","latin":"conveniō, convenīre","headword":"conveniō","letter":"c","pos":"verb","posGroup":"verb","english":"come together, fit together; fit; meet, assemble","forms":["convenerant","convēnerat","convēnēre","convēnerit","convenerunt","conveniant","conveniat","conveniēbant","conveniēbātur","conveniēmus","convenienda","convenient","conveniet","convenire","convenīrem","convenīrent","convenīret","convenisse","convēnissent","convenisset","convēnistī","convenit","conveniundī","conveniunt","conventū"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Eo cum venisset, timentes confirmat, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, {{convenire}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"convenire","latin":"convenīre","headword":"convenīre","letter":"c","pos":"verb","posGroup":"verb","english":"to come together, meet","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"convenit","latin":"convenit, conveniunt","headword":"convenit","letter":"c","pos":"verb","posGroup":"verb","english":"come together, meet, suit; fits, suits","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"conventum","latin":"conventum, conventi","headword":"conventum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"agreement, compact, covenant; convention, accord (L+S)","forms":["conventum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postquam omnium animōs alacrēs videt, cohortātus ut petītiōnem suam cūrae habērent, {{conventum}} dīmīsit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"conventus","latin":"conventus, -ūs","headword":"conventus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"assembly","forms":["conventus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, in Italiam ad {{conventus}} agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"conversa","latin":"conversa, conversae","headword":"conversa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"convert; she who has changed","forms":["conversā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Māter prīmum ad haec verba, quasi in saxum conversā, stupuit; tum “Mī Iuppiter” inquit, “tua quoque fīlia Proserpina est; ecce, tandem, postquam diū quae sīvī, eam repperī: sī ‘reperīre’ vocās, ‘scīre ubi sit’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"conversio","latin":"conversiō, -ōnis ( f.)","headword":"conversiō","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"rotation, revolution; turning, revolution","forms":["conversiō","conversiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob causam summus ille caelī stellifer cursus, cuius conversiō est concitātior, acūtō et excitātō movētur sonō, gravissimō autem hic lūnāris atque īnfimus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"conversus","latin":"conversus, conversa, conversum","headword":"conversus","letter":"c","pos":"adjective","posGroup":"adjective","english":"upside down; inverted; turned backward; recurved; facing in specified direction","forms":["conversus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum extrēmum spīritum ageret, ad rēgem {{conversus}}:\"Tū quidem\"ait,\"hanc vltam nōbīs ēripis, sed āmissam nōbīs reddet Deus, prō cuius lēge linguam postulanfī prōtulit amputandam, manusque prōtendēns, dīxit:\"Haec membra, ā Deō acceptā, nunc propter Deum contemnō, quia spērō fore ut eā reciperem.\"Rēx et aliī circumstantēs admīrābantur animum adulēscentis, quī acerbissimum dolōrem prō nihilō dūcēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"convertere","latin":"(convertō) convertere, convertisse,  conversum","headword":"convertere","letter":"c","pos":"","posGroup":"other","english":"turn","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"converto","latin":"convertō, -ere, -vertī, -versum","headword":"convertō","letter":"c","pos":"verb","posGroup":"verb","english":"turn around, alter, change","forms":["conversae","conversam","conversī","conversum","convertat","Converte","convertēbat","converteram","converteret","convērtērunt","convertī","convertissent","convertit","convertitur","convertunt","convertuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam {{converteret}}, ut ne metu quidem necessario faciendum existimabat, cum infamia atque indignitas rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"convexo","latin":"convexo, convexare, convexavi, convexatus","headword":"convexo","letter":"c","pos":"verb","posGroup":"verb","english":"jostle, push against; press/squeeze together (L+S)","forms":["convexō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Classem in convexō nemorum sub rūpe cavāta","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"convexum","latin":"convexum, convexi","headword":"convexum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"arch, vault; dome; dome of the sky; concavity (L+S); (usu. pl.)","forms":["convexa"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"lūstrābunt {{convexa}}, polus dum sīdera pāscet,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"conviciator","latin":"conviciator, conviciatoris","headword":"conviciator","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"one who utters abuse, reviler","forms":["convīciātōris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quod illī indignē ferentēs volēbant ulcīscī iniūriam, et maledicī {{convīciātōris}} caput amputāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"convicium","latin":"convicium, convici(i)","headword":"convicium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"noise (angry), chatter/outcry/clamor/bawling; noise source; noisy importuning","forms":["convīcium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Subiit igitur alia classis, et illî quidem exclânnävëre: “Valē, Gäî!” hî autem: “Avē, Gäî!” arbor eiusque lignum dūrum tîbiîs canendô et saltandô pō- pulum dēlectat; ambübäimn mâchina : mēnsā in vënäliciô dē quā vêneunt servī et an- cüräbô ut domita sit (domētur) gerit (ut mīles), audâx [?] interîre : exstinguî (quia For- [T rimalchiô uxôrî {{convīcium}} facit] Hinc prîmum hilaritās nostra turbāta est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"convictus","latin":"convictus, convictus","headword":"convictus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"intimacy; association; living together; close friends; banquet, dinner party","forms":["convictus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Manlius Rōmae, quī Gallōs in obsidiōne Capitōliī obrēpentēs per ardua dēpulerat, {{convictus}} est cōnsilium dē regnō occupandō iniisse damnātusque capitis ē saxō Tarpēiō, ut M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"convincere","latin":"(convincō) convincere (< vincere)","headword":"convincere","letter":"c","pos":"verb","posGroup":"verb","english":"find guilty, convict; to convict, prove guilty","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"convinco","latin":"convinco, convincere, convici, convictus","headword":"convinco","letter":"c","pos":"verb","posGroup":"verb","english":"conquer, establish; convince; overcome, demonstrate, prove clearly; grant","forms":["convictī","convictōs","Convincam","convincere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Convincam}}, sī negās; videō enim esse hīc in senātū quōsdam quī tēcum ūna fuērunt!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"conviva","latin":"convīva, -ae","headword":"convīva","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m./f.) dinner guest; guest at dinner; guest at a banquet","forms":["convīva","convīvae","convīvam","convīvārum","convīvās","convīvīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnēs igitur {{convīvae}} ūnō ōre exclāmāvērunt: “Pereat Tantalus, pater crūdēlissimus et iniūstissimus, nē nōmine quidem patris dignus!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"convivium","latin":"convīvium, -ī","headword":"convīvium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"dinner party; dinner party, banquet; banquet, party","forms":["convīvia","convīviī","convīviīs","convīviō","convīvium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Eliezer dēprōmpsit vās aurea et argentea, vestēsque pretiōsās, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt {{convīvium}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"convocare","latin":"(convocō) convocāre, -āvisse, -ātum","headword":"convocāre","letter":"c","pos":"verb","posGroup":"verb","english":"call together; to call together","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"convoco","latin":"convocō, -āre, -āvī, -ātum","headword":"convocō","letter":"c","pos":"verb","posGroup":"verb","english":"call together, summon","forms":["convocābantur","convocandos","convocat","convocātī","convocatis","convocato","convocāverīs","convocāvit","Convocēmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, {{convocatis}} suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"convolsus","latin":"convolsus, convolsa, convolsum","headword":"convolsus","letter":"c","pos":"adjective","posGroup":"adjective","english":"suffering from wrenching/dislocation of a limb","forms":["convolsae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"vix septem {{convolsae}} undīs Eurōque supersunt.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"coopertus","latin":"coopertus, cooperta, coopertum","headword":"coopertus","letter":"c","pos":"adjective","posGroup":"adjective","english":"overwhelmed, buried deep (in crime/misfortune/etc.)","forms":["coopertus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Curius, nātus haud obscūrō locō, flāgitiīs atque facinoribus {{coopertus}}, quem cēnsōrēs senātū probrī grātiā mōverant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"cooptare","latin":"(cooptō) cooptāre","headword":"cooptāre","letter":"c","pos":"","posGroup":"other","english":"choose (as colleague)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"coopto","latin":"coopto, cooptare, cooptavi, cooptatus","headword":"coopto","letter":"c","pos":"verb","posGroup":"verb","english":"choose (colleague in office), elect; co-opt, admit","forms":["cooptāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et ipse — quod prīncipium reī pūblicae fuit — urbem condidit auspicātō, et, omnibus pūblicīs rēbus īnstituendīs quī sibi essent in auspiciīs, ex singulīs tribubus singulōs {{cooptāvit}} augurēs.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"coorior","latin":"coorior, cooriri, coortus sum","headword":"coorior","letter":"c","pos":"verb","posGroup":"verb","english":"appear, originate; arise, break out (bad); be born; spring forth/to attack","forms":["coorta","coortum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eo cum esset ventum, exploratores hostium, ut omni fluminis parte erant dispositi, inopinantes, quod magna subito erat {{coorta}} tempestas, ab nostris opprimuntur; exercitus equitatusque equitibus Romanis administrantibus quos ei negotio praefecerat celeriter transmittitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cooriri","latin":"(coorior) coorīrī (< orīrī)","headword":"coorīrī","letter":"c","pos":"","posGroup":"other","english":"break out, arise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cophinus","latin":"cophinus, cophini","headword":"cophinus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"basket, hamper","forms":["cophinī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Posteā collēgērunt fragmenta, et superfuērunt duodecim cophinī","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"copia","latin":"cōpia, -ae","headword":"cōpia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"abundance; opportunity; troops","forms":["copia","copiae","copiam","copiarum","copias","copiis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis {{copiis}} adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"copiae","latin":"cōpiae, -ārum (pl.)","headword":"cōpiae","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"resources, troops; troops, forces; supplies; forces, troops","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"copiose","latin":"copiose, copiosius, copiosissime","headword":"copiose","letter":"c","pos":"adverb","posGroup":"adverb","english":"eloquently/fully/at length; w/abundant provisions, sumptuously/copiously/richly","forms":["cōpiōsē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Māter plōrāns ad Cēpheum “Quōmodo” clāmābat, “hoc facere potuistī, mī vir?” Quī, inter lacrimās, quās ipse quoque cōpiōsē effundēbat, “Quaeris ā mē, ō uxor,” inquit, “cūr tam saevus fuerim, ut fīliam ad certam mortem mīserim.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"copiosus","latin":"copiosus, copiosa -um, copiosior -or -us, copiosissimus -a -um","headword":"copiosus","letter":"c","pos":"adjective","posGroup":"adjective","english":"plentiful/copious/abundant; well supplied/equipped, w/ample resources; prolific","forms":["cōpiōsa"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Jēsus Ībat in cīvitātem quae vocātur N aim, et Ībant cum eō discipulī eius et turba {{cōpiōsa}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"copulare","latin":"(cōpulō) cōpulāre, -āvisse, -ātum","headword":"cōpulāre","letter":"c","pos":"verb","posGroup":"verb","english":"join, connect; to join, link","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"copulativa","latin":"cōpulātīva","headword":"cōpulātīva","letter":"c","pos":"","posGroup":"other","english":"(coniūnctiō) (f.) copulative conjunction","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"copulativus","latin":"cōpulātīvus","headword":"cōpulātīvus","letter":"c","pos":"adjective","posGroup":"adjective","english":"copulative","forms":["cōpulātīvās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis adnectēns ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: '{{Cōpulātīvās}}, disiūnctīvās, explētīvās, causālēs, ratiōnālēs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"copulo","latin":"copulo, copulare, copulavi, copulatus","headword":"copulo","letter":"c","pos":"verb","posGroup":"verb","english":"connect, join physically, couple; bind/tie together, associate, unite, ally","forms":["cōpulātīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Mediā nocte in castra nūntiātum est magnum hostium numerum nāviculīs ratibusque {{cōpulātīs}} flūmen trānsīsse celeriterque secundum flūmen adversus castra nostra prōgredī.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"coque","latin":"coque","headword":"coque","letter":"c","pos":"adverb","posGroup":"adverb","english":"likewise; no less; besides, as well, also/too; not only; even/indeed, actually","forms":["coque"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēscendat hūc! [Ad cocum quī dēscendit] Tolle, {{coque}} dīligenter pulmentāria! [Ad servum] Affer clāvem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"coquere","latin":"(coquō) coquere, coxisse, coctum","headword":"coquere","letter":"c","pos":"verb","posGroup":"verb","english":"cook; to cook","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"coquo","latin":"coquo, coquere, coxi, coctus","headword":"coquo","letter":"c","pos":"verb","posGroup":"verb","english":"cook; boil, fry, bake; burn, parch (sun); stir up; ripen, mature (plot); digest","forms":["coquās","coquere","coquitur"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hic Aemilia 'Necesse est' inquit 'paulisper famem sitimque ferre, dum cibus {{coquitur}} et trīclīnium exōrnātur.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cor","latin":"cor, cordis","headword":"cor","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) heart","forms":["cor","corde","cordī","cordibus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Medicus: “Sanguis ā {{corde}} per vēnās fluit in tōtum corpus hūmānum, ut dīcit Hippocratēs...” Hippocratēs -is","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"coram","latin":"cōram (also{i} adv.{/i})","headword":"cōram","letter":"c","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.)in the presence of, face to face (with); in the presence of (+ abl.)","forms":["cōram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iōsēphus adiit Pharaōnem, eīque nūntiāvit patrem suum advēnisse; cōnstituit etiam quīnque ē frātribus suīs {{cōram}} rēge.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"corbis","latin":"corbis, corbis","headword":"corbis","letter":"c","pos":"noun","posGroup":"noun","english":"basket; (esp. one used for gathering grain/fruit; basketful (quantity)","forms":["corbe"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Permittitis tamen ﬁnîrî lūsum?” Sequēbātur puer cum tabulā terebinthinā et crystallinîs tesserîs, notävîque rem om- nium dēlicātissimam: prô calculîs enim albîs ac nigrîs aureôs argenteôsque habēbat tesserae Interim, �Ē$ gustantibus adhūc nôbîs, repositôrium al- lātum est cum {{corbe}} in quô gallîna erat lignea patentibus in orbem älîs, quālēs esse solent quae _ incubant ôva.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corcillum","latin":"corcillum, corcilli","headword":"corcillum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"heart (as the seat of intelligence); brains; savoir-faire; little heart (L+S)","forms":["Corcillum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Corcillum}} est quod hominēs facit, cētera quisquilia omnia!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corda","latin":"corda, cordae","headword":"corda","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"tripe; catgut, musical instrument string; rope/cord (binding a slave) (L+S)","forms":["corda"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"iam prīdem residēs animōs dēsuētaque {{corda}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cordax","latin":"cordax, cordacis","headword":"cordax","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"trochaic meter; cordax (indecent/extravagant dance of Greek comedy L+S)","forms":["cordācem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Crēdite mihi: {{cordācem}} nëmô melius dūcit.” Atque ipse, ërëctîs suprā frontem manibus, Syrum histriônem ex- hībēbat, concinente tôtä familiā: Madēia perimadēia!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corintheus","latin":"Corintheus, Corinthea, Corintheum","headword":"Corintheus","letter":"c","pos":"adjective","posGroup":"adjective","english":"of/from/pertaining to Corinth, Corinthian; of Corinthian bronze/order","forms":["Corintheā","Corintheum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quam cum Agamemnôn propius cônsîderäret, ait Trimalchiô: “Sô1us sum quī vēra Corintheā habeam.” Expectābam ut prô reliquä însolentiä dîceret ‘sibi vāsa Corinthô affenî’, sed ille melius “Et forsitan” inquit “quaeris, quārē sôlus Corintheā vēra possideam?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corinthium","latin":"Corinthium, Corinthii","headword":"Corinthium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"Corinthian bronze vessels (pl.); buildings of the Corinthian order/style","forms":["Corinthiā","Corinthiī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aesōnidēs in mātrimōnium fīliam rēgis Corinthiī dūcere spērāvit ut (ita dīxit) prō Medeā et fīliīs duōbus suīs domum tūtam faceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"corinthius","latin":"Corinthius, Corinthia, Corinthium","headword":"Corinthius","letter":"c","pos":"adjective","posGroup":"adjective","english":"of/from/pertaining to Corinth, Corinthian; of Corinthian bronze/order","forms":["Corinthiōs","Corinthius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum in prômulsidän‘ asellus erat {{Corinthius}} cum bisacciô positus, quī habēbat olîväs in alterā parte albās, in alterā nigrās.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corinthos","latin":"Corinthos, Corinthi","headword":"Corinthos","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Corinth","forms":["Corinthon","Corinthos"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī, omnī Achāiā in dēditiōnem acceptā, {{Corinthon}} ex senātūs cōnsultō dīruit, quia ibi lēgātī Rōmānī violātī erant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"corinthus","latin":"Corinthus, Corinthi","headword":"Corinthus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Corinth","forms":["Corinthī","Corinthō","Corinthum","Corinthus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prope Isthmum sita est {{Corinthus}}, urbs pulcherrima, nec procul absunt Athēnae, patria nostra.\"\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"corium","latin":"corium, cori(i)","headword":"corium","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"skin/leather/hide; peel/rind/shell/outer cover; layer/coating; thong/strap/whip","forms":["coriis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Totum autem murum ex omni parte turribus contabulaverant atque has {{coriis}} intexerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cornicen","latin":"cornicen, -inis (m.)","headword":"cornicen","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"horn-blower, bugler","forms":["cornicinēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"inquit “ad parentālia mea in- Îbat rēs ad surnmam nauseam, cum Trimalchiô, ēbrie- tâte turpissirnä gravis, novum acroânna, {{cornicinēs}}, in trī- clînium iussit addücî; fultusque cervîcälibus multîs ex- tendit sē suprā torum extrēmum, et “Fingite mē” inquit “mortuum esse!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corniculum","latin":"corniculum, corniculi","headword":"corniculum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"little/small horn; (used as funnel); a horn-shaped decoration for soldiers","forms":["Corniculum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Corniculum}}, Fīculea, Crustumerium, Medullia, Nōmentum — haec oppida dē Latīnīs aut dē sociīs Latīnōrum capta sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cornipes","latin":"cornipes, cornipedis","headword":"cornipes","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"hoofed animal; (horse)","forms":["cornipedī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"280 fēmina cornipedī semper adhinnit equō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cornu","latin":"cornū, cornūs","headword":"cornū","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) horn; horn, end, tip","forms":["cornibus","CORNIBVS","cornu","cornua"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Primo concursu ab dextro {{cornu}}, ubi septima legio constiterat, hostes pelluntur atque in fugam coiciuntur; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"corona","latin":"corōna, -ae","headword":"corōna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"wreath; crown","forms":["corona","corōnae","corōnam","corōnās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus {{corona}} militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo advolaret aut interdiu tela in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"coronare","latin":"corōnāre","headword":"corōnāre","letter":"c","pos":"verb","posGroup":"verb","english":"to crown","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"coronis","latin":"coronis, coronidis","headword":"coronis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"colophon, device for marking the end of a book; curved line/flourish at end","forms":["Corōnidem","Corōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Corōnis}} pulchra fuit puella quae in Graeciā habitābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"corono","latin":"corono, coronare, coronavi, coronatus","headword":"corono","letter":"c","pos":"verb","posGroup":"verb","english":"wreathe, crown, deck with garlands; award prize; surround/encircle, ring round","forms":["corōnant","corōnantur","corōnat","corōnātur"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Atalanta victor {{corōnātur}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"corporaliter","latin":"corporaliter","headword":"corporaliter","letter":"c","pos":"adverb","posGroup":"adverb","english":"in respect of material things; carnally; corporally, bodily (L+S)","forms":["corporāliter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sed ego nôn mē- herculēs {{corporāliter}} illam aut propter rēs veneriās cûrävî, sed magis quod benemôria fuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corpus","latin":"corpus, corporis","headword":"corpus","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) body","forms":["corpora","corpore","corporī","corporibus","corporis","corporum","corpus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie conquieverat, superiore {{corporis}} parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"correptus","latin":"correptus, correpta, correptum","headword":"correptus","letter":"c","pos":"adjective","posGroup":"adjective","english":"short; (of a syllable)","forms":["correptus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cumque ā pontifice admonitus nōn pāruisset, turpl morbō, quem ' lepram' vocant, {{correptus}} est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"corrigit","latin":"corrigit","headword":"corrigit","letter":"c","pos":"verb","posGroup":"verb","english":"corrects","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"corrigo","latin":"corrigō, corrigere","headword":"corrigō","letter":"c","pos":"verb","posGroup":"verb","english":"correct","forms":["corrēxit","corrigās","corrige","corrigī","corrigit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nāte, cave, dum rēsque sinit tua {{corrige}} vōta!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"corripere","latin":"(corripiō) corripere (< rapere)","headword":"corripere","letter":"c","pos":"verb","posGroup":"verb","english":"seize, rebuke; to seize, snatch up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"corripio","latin":"corripiō, -ere, corripuī, correptum","headword":"corripiō","letter":"c","pos":"verb","posGroup":"verb","english":"seize, snatch","forms":["correpta","correptī","correptīs","correptum","corripiēbat","corripit","corripiunt","Corripuēre","corripuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hebraeī, cum vīdissent ex ūnā parte sē marī interclūsōs esse, ex alterā parte īnstāre pharaōnem cum omnibus cōpiīs, magnō timōre correptī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"corroboro","latin":"corroboro, corroborare, corroboravi, corroboratus","headword":"corroboro","letter":"c","pos":"verb","posGroup":"verb","english":"strengthen, harden, reinforce; corroborate; mature; make powerful, fortify","forms":["corrōborāvērunt"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quamquam nōnnūllī sunt in hōc ōrdine quī aut ea quae imminent nōn videant aut ea quae vident dissimulent; quī spem Catilīnae mollibus sententiīs aluērunt coniūrātiōnemque nāscentem nōn crēdendō {{corrōborāvērunt}}; quōrum auctōritāte multī, nōn sōlum improbī, vērum etiam imperītī, sī in hunc animadvertissem, ‘crūdēliter et rēgiē factum esse’ dīcerent.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"corrotundo","latin":"corrotundo, corrotundare, corrotundavi, corrotundatus","headword":"corrotundo","letter":"c","pos":"verb","posGroup":"verb","english":"make round; round off; amass/make up a round sum of money","forms":["corrotundāta"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quod autem in mediô caespitem vidētis et super caespitem terrā māter est in mediô quasi ôvum {{corrotundāta}}, et omnia bona in sē habet tamquam favus.” [F erculum secundum.' aper cum vënätiônis apparātū] “Sophôs!” üniversî clâmämus, et sublätîs manibus ad 40 cameram iürâmus ‘Hipparchum Arätumque comparandôs posuērunt in quibus rētia erant picta subsessôrësque cum vënäbulîs et tôtus vënätiônis apparātus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"corrumpere","latin":"(corrumpō) corrumpere (< rumpere)","headword":"corrumpere","letter":"c","pos":"","posGroup":"other","english":"spoil, corrupt, bribe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"corrumpo","latin":"corrumpo, corrumpere, corrupi, corruptus","headword":"corrumpo","letter":"c","pos":"verb","posGroup":"verb","english":"spoil/rot; taint/contaminate; damage/ruin, undo; destroy/deface; digest; infect","forms":["corrumpam","corrumpe","corrumpendum","corrumpere","corrumpis","corrumpit","corruperunt","corrūpit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Itaque interfectis Novioduni custodibus quique eo negotiandi causa convenerant, pecuniam atque equos inter se partiti sunt; obsides civitatum Bibracte ad magistratum deducendos curaverunt; oppidum, quod a se teneri non posse iudicabant, ne cui esset usui Romanis, incenderunt; frumenti quod subito potuerunt navibus avexerunt, reliquum flumine atque incendio {{corruperunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"corruo","latin":"corruo, corruere, corrui, corrutus","headword":"corruo","letter":"c","pos":"verb","posGroup":"verb","english":"fall/break down, fall to ground/from height, collapse; be ruined, come to grief","forms":["corruērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum arca septiēs circumlāta esset, mūrī et turrēs īlicō {{corruērunt}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"corruptela","latin":"corruptela, corruptelae","headword":"corruptela","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"corruption/bribery/suborning; corrupting/perverting influence; seducer/misleader","forms":["corruptēlārum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cui tū adulēscentulō, quem {{corruptēlārum}} illecebrīs irrētīssēs, nōn aut ad audāciam ferrum aut ad libīdinem facem praetulistī?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"corruptum","latin":"corruptum, corrupti","headword":"corruptum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"corrupted parts (pl.) (of the body)","forms":["corruptum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō Āfricānus Numantiam obsēdit, et {{corruptum}} licentiā luxuriāque exercitum ad sevērissimam mīlitiae disciplīnam revocāvit: omnia dēliciārum īnstrūmenta recīdit, duo mīlia scortōrum ē castrīs ēiēcit, mīlitem cotīdiē in opere habuit et trīgintā diērum frūmentum ac septēnōs vallōs ferre cōgēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"corruptus","latin":"corruptus, corrupta -um, corruptior -or -us, corruptissimus -a -um","headword":"corruptus","letter":"c","pos":"adjective","posGroup":"adjective","english":"rotten/decayed; infected (wounds), corrupt; degenerate/decadent; depraved/venal","forms":["corrupta","corruptam","corruptī","corruptus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"S ed IOiadā mortuō, aulicōrum adūlatione {{corruptus}}, ad vitia dēflexit, vēramque religiōnem dēseruit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"corsica","latin":"Corsica, Corsicae","headword":"Corsica","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Corsica; (island)","forms":["Corsica","Corsicam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Corsica}} īnsula est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cortex","latin":"cortex, corticis","headword":"cortex","letter":"c","pos":"noun","posGroup":"noun","english":"bark; cork; skin, rind, husk, hull; outer covering, shell, carapace, chrysalis","forms":["cortice"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Auxilium ā tē petō!” Vix precēs dīxerat, cum subitō membra cōnstitērunt et corpus {{cortice}} operīrī coeptum est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cortina","latin":"cortina, cortinae","headword":"cortina","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cauldron, (of Delphi oracle), kettle; water-organ; vault/arch; curtain (L+S)","forms":["cortīnīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Moysēs ā Deō monitus cōnficī iussit tabernāculum ex pellibus et {{cortīnīs}} pretiōsissimīs, īnsuper arcam foederis aurō pūrō vestītam, in quā reposuit tabulās lēgis dīvīnae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"coruscus","latin":"coruscus, corusca, coruscum","headword":"coruscus","letter":"c","pos":"adjective","posGroup":"adjective","english":"vibrating/waving/tremulous/shaking; flashing, twinkling; brilliant (L+S)","forms":["coruscē","coruscīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"corvinus","latin":"corvinus, corvina, corvinum","headword":"corvinus","letter":"c","pos":"adjective","posGroup":"adjective","english":"raven-, of/belonging/pertaining to a raven","forms":["Corvīnus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Corvus nōn sōlum victōriam eī, sed etiam nōmen dedit, nam posteā īdem '{{Corvīnus}}' est dictus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"corvus","latin":"corvus, -ī","headword":"corvus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"raven; also a boarding-hook","forms":["corve","corvī","CORVO","corvum","corvus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tandem mēnse ūndecimō postquam dīluvium coeperat, Noēmus aperuit fenestram arcae, et ēmīsit {{corvum}}, quī nōn est reversus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cos","latin":"cos, cotis","headword":"cos","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"flint-stone; whetstone, hone, grinding stone; rocks (pl.); any hard stone (L+S)","forms":["cŌs","Cotum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum {{Cotum}}, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"costa","latin":"costa, costae","headword":"costa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"rib; side/flank/back; rib with meat; ribs/frame of ship; sides (pl.) of pot","forms":["costīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde immīsit sopōrem in Adamum et dētrāxit ūnam ē {{costīs}} eius dormientīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cothurnus","latin":"cothurnus, cothurni","headword":"cothurnus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"high boot/buskin (worn by Greek tragic actors to increase their height)","forms":["cothurnō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"purpureōque altē sūrās vincīre cothurnō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cotidiano","latin":"cotidiano","headword":"cotidiano","letter":"c","pos":"adverb","posGroup":"adverb","english":"every day, daily","forms":["cotīdiānō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tertius et quārtus ex fīliīs, postquam operī cotīdiānō fīnem imposuerant, in palaestram īverant, ut validiōra corpons membra facerent: cum vērō iam alter alterum luctandō complecterētur, ūnā sagittā eōs ita iūnctōs trānsfīxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cotidianus","latin":"cotidianus, cotidiana, cotidianum","headword":"cotidianus","letter":"c","pos":"adjective","posGroup":"adjective","english":"daily, everyday; usual/habitual, normal/regular; ordinary/common/unremarkable","forms":["cotīdiānī","cotidianus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has {{cotidianus}} agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cotidie","latin":"cotīdiē","headword":"cotīdiē","letter":"c","pos":"adverb","posGroup":"adverb","english":"daily; every day; daily, every day","forms":["cotidie"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Pabulum secari non posse; necessario dispersos hostes ex aedificiis petere; hos omnes {{cotidie}} ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cotta","latin":"Cotta, Cottae","headword":"Cotta","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cotta; (Roman cognomen)","forms":["Cotta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duo tum excellebant ōrātōrēs, quī mē imitandī cupiditāte incitārent, {{Cotta}} et Hortēnsius, quōrum alter remissus et lēnis, alter ōrnātus, ācer et verbōrum et actiōnis genere commōtior.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cous","latin":"Cous, Coa, Coum","headword":"Cous","letter":"c","pos":"adjective","posGroup":"adjective","english":"of/from/belonging to Cos (island in Aegean, now Stanchio); (its wine/fine silk)","forms":["Coos","Cōus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Cōus}} -ā -um (« Coos -ī f; īnsula); n","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cras","latin":"crās","headword":"crās","letter":"c","pos":"adverb","posGroup":"adverb","english":"tomorrow","forms":["crās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tibi respōnsum nōn dabitur hodiē, {{crās}} magistrō dabitur ā Mārcō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"crassitudo","latin":"crassitudo, crassitudinis","headword":"crassitudo","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"thickness (measure); density/consistency (liquid); richness (soil); sediment","forms":["crassitudine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huc teretes stipites feminis {{crassitudine}} ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"crasso","latin":"crasso, crassare, crassavi, crassatus","headword":"crasso","letter":"c","pos":"verb","posGroup":"verb","english":"thicken, condense, make thick","forms":["crassō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Syra (parvā vōce ad Aemiliam): “Is nōn est tam crassus quam ipse medicus!” Sed ea verba ā crassō medicō nōn audiuntur. cui color faciēī ruber est, nimis multum sanguinis habet...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"crassus","latin":"crassus, -a, -um","headword":"crassus","letter":"c","pos":"adjective","posGroup":"adjective","english":"thick, fat; fat, thick; fat, stout","forms":["crassā","crassam","crassiōrem","Crassius","crassum","crassus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia et Syra in hortō ambulant cum Margarītā, cane Iūliae parvā et crassā.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"crater","latin":"crātēr, crātēris","headword":"crātēr","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"bowl; large mixing bowl","forms":["crātēr","crātēre","crātēribus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Vīnum et cibus etiam erant in {{crātēribus}}!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cratera","latin":"cratera, craterae","headword":"cratera","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"mixing bowl; depression, volcano crater, basin of fountain; Cup (constellation)","forms":["crātērās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde {{crātērās}} vīnī lactisque addit et rogat rēgem umbrārum cum coniuge raptā nē mortem senis rēgis properent.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cratis","latin":"crātis, -is ( f.)","headword":"crātis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"hurdle (of wickerwork)","forms":["crāte","crates","cratibus","cratium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Labienus primo vineas agere, {{cratibus}} atque aggere paludem explere atque iter munire conabatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"creare","latin":"(creō) creāre","headword":"creāre","letter":"c","pos":"","posGroup":"other","english":"create, appoint","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"creator","latin":"creator, creatoris","headword":"creator","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"creator (of world); maker, author; founder (city); father; one who appoints","forms":["creātōris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Oblītī sunt Deī {{creātōris}}; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, homicīdium; ūnō verbō, sē contāminābant omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"creatum","latin":"creatum, creati","headword":"creatum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"things made (pl.)","forms":["creātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Plēbs autem querēbātur \"centum prō ūnō dominōs factōs\" et rēgem ā sē {{creātum}} postulābat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"creatus","latin":"creatus, creati","headword":"creatus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"child, offspring","forms":["creāta","creātī","creātōs","creatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset {{creatus}}, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"creber","latin":"crēber, -ris, -re (-bra, -brum)","headword":"crēber","letter":"c","pos":"adjective","posGroup":"adjective","english":"frequent, numerous","forms":["crēbrī","crebris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum {{crebris}} diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"crebra","latin":"crebra","headword":"crebra","letter":"c","pos":"adverb","posGroup":"adverb","english":"repeatedly","forms":["crēbra"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Subitō nūbēs ātrae caelum occultant atque {{crēbra}} fulgura cum tonitrū in tenebrīs micant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"crebro","latin":"crebro, crebrius, creberrime","headword":"crebro","letter":"c","pos":"adverb","posGroup":"adverb","english":"frequently/repeatedly/often, one after another, time after time; thickly/densely","forms":["crebro"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum {{crebro}} integri defessis succederent nostrosque assiduo labore defatigarent, quibus propter magnitudinem castrorum perpetuo esset isdem in vallo permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"credens","latin":"credens, credentis","headword":"credens","letter":"c","pos":"noun","posGroup":"noun","english":"believer; the_faithful (pl.)","forms":["crēdēns","crēdentem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Minervae verbīs parēns, Cadmus tergum cuiusdam ex illīs mīlitibus ē terrā natis hasta percussit: quī, {{crēdēns}} sē ab aliō mīlite pulsātum esse, eum gladiō trānsfīxit; ita iī ferī hominēs ex agrō ortī suīs armīs inter sē occīdēbant; post longam autem pugnam eōrum trēs tantum mānsērunt; quōs Minerva Cadmō suāsit ut amīcōs sociōsque acciperet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"credere","latin":"(crēdō) crēdere, -didisse,  -ditum ({i}intr. + dat.{/i})","headword":"crēdere","letter":"c","pos":"verb","posGroup":"verb","english":"believe, trust, entrust; to believe, trust (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"credibilis","latin":"credibilis, credibilis, credibile","headword":"credibilis","letter":"c","pos":"adjective","posGroup":"adjective","english":"credible/trustworthy/believable/plausible/convincing/likely/probable","forms":["crēdibile","crēdibilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sit tibi {{crēdibilis}} sermō consuétaque verba,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"credit","latin":"crēdit","headword":"crēdit","letter":"c","pos":"verb","posGroup":"verb","english":"believes, trusts","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"creditum","latin":"creditum, crediti","headword":"creditum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"loan, debt, what is lent; [in ~ accipere => to receive a loan]","forms":["crēdita","crēditum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"sī semel {{crēdita}} est","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"creditus","latin":"creditus, credita, creditum","headword":"creditus","letter":"c","pos":"adjective","posGroup":"adjective","english":"loan","forms":["crēditam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque angelus, sūmptīs camēlīs, properāvit Rāgē, suum Gābelō chīrographum reddidit, pecūniam illī {{crēditam}} recēpit, eumque ad nūptiās Tobiae addūxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"credo","latin":"credo, credere, credidi, creditus","headword":"credo","letter":"c","pos":"verb","posGroup":"verb","english":"trust, entrust; commit/consign; believe, trust in, rely on, confide; suppose","forms":["crēdam","crēdant","crēdās","crēdat","crēde","crēdēbam","crēdēbant","crēdēbat","crēdēmus","crēdenda","crēdendō","crēdent","crēdere","crēderem","crēderent","crēderet","crēdet","crēdī","crēdiderant","crēdiderim","crēdiderīs","crēdidērunt","crēdidī","crēdidisse","crēdidit","crēdis","crēdit","crēdite","Crēditis","crēditur","crēdō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed neque Iūlius, pater Mārcī, neque Cornēlius, pater Sextī, fīliō suō {{crēdet}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"credulus","latin":"credulus, credula, credulum","headword":"credulus","letter":"c","pos":"adjective","posGroup":"adjective","english":"credulous, trusting, gullible; prone to believe/trust; full of confidence (L+S)","forms":["crēdulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulier īrāta inclāmāvit servōs, et Iōsēphum accūsāvit apud virum, quī, nimium {{crēdulus}}, coniēcit Iōsēphum in carcerem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cremare","latin":"(cremō) cremāre","headword":"cremāre","letter":"c","pos":"","posGroup":"other","english":"burn, cremate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cremo","latin":"cremo, cremare, cremavi, crematus","headword":"cremo","letter":"c","pos":"verb","posGroup":"verb","english":"burn (to ash)/cremate; consume/destroy (fire); burn alive; make burnt offering","forms":["cremābis","cremātā","cremātum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Viam mediam tenē: iter fac in mediō āere inter caelum et terram; altius ēgressus caelestia tēcta {{cremābis}},","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"creo","latin":"creo, creare, creavi, creatus","headword":"creo","letter":"c","pos":"verb","posGroup":"verb","english":"create/bring into being/make; procreate; beget/sire; give birth to","forms":["creābantur","creābit","creandō","creandōs","creant","creantēs","creāre","creāret","creārētur","creari","creat","creāte","creātīs","creāveritis","creāvērunt","creāvisset","creāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus {{creari}} vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"crepitus","latin":"crepitus, crepitus","headword":"crepitus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"rattling, rustling, crash (thunder); chattering (teeth); snap (fingers); fart","forms":["crepitus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"—strepitus, {{crepitus}}, sonitus, tonitrus!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"crepo","latin":"crepo, crepare, crepui, crepitus","headword":"crepo","letter":"c","pos":"verb","posGroup":"verb","english":"rattle/rustle/clatter; jingle/tinkle; snap (fingers); harp on, grumble at; fart","forms":["crepitū","crepuit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{crepuit}}, ad quod signum matellam spadô lüdentî subiēcit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"crepusculum","latin":"crepusculum, crepusculi","headword":"crepusculum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"twilight, dusk; darkness (L+S)","forms":["crepusculō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quantō est facilius mihi sub tēctō vīvere et ōtiōsum largō satiārī cibō!” [Canis:] “Venī ergō mēcum!” Dum prōcēdunt, lupus ā catēnā collum dētrītum canī aspicit. [Lupus:] “Unde hoc, amīce?” [Canis:] “Nīl est.” [Lupus:] “Dīc, sōdēs, tamen!” [Canis:] “Quia videor ācer, alligant mē interdiū, lūce ut quiēscam, ut vigilem nox cum vēnerit: crepusculō solūtus quā vīsum est vāgor.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"crescere","latin":"(crēscō) crēscere, crēvisse","headword":"crēscere","letter":"c","pos":"","posGroup":"other","english":"grow","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"cresco","latin":"crēscō, -ere, crēvī, crētum","headword":"crēscō","letter":"c","pos":"verb","posGroup":"verb","english":"increase, grow","forms":["crēscam","crēscēbant","crēscēbat","crēscēns","crēscentem","crēscentēs","crēscentibus","crēscentis","crēscere","crēsceret","crēscit","crēscunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Intereā posterī Iacobī, seu Hebraeī, numerō auctī sunt mīrum in modum, et eōrum multitūdō {{crēscēns}} in diēs metum incutiēbat Aegyptiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cresso","latin":"cresso, cressare, cressavi, cressatus","headword":"cresso","letter":"c","pos":"verb","posGroup":"verb","english":"increase (size/number/honor), multiply; thrive","forms":["Cressa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"saepe reget dubiam {{Cressa}} Corōna ratem.\"","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"creta","latin":"Crēta, -ae","headword":"Crēta","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Crete","forms":["crētā","Crētae","Crētam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus: “Estne {{Crēta}} oppidum Graecum?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"creusa","latin":"Creusa, Creusae","headword":"Creusa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Creusa; (wife of Aeneas, lost during the fall of Troy)","forms":["Creūsa","Creūsae","Creūsam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"altera nūpta: {{Creūsa}}, nova uxor","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"crimen","latin":"crīmen, -inis (n.)","headword":"crīmen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"charge, accusation; sin, crime, fault; charge, crime","forms":["crīmen","crīmina","crīmine","crīminibus","crīminis","crīminum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rōmānī tamen hunc tyrannum diū perferre nōn potuērunt; itaque Tarquinius, multōrum {{crīminum}} accūsātus, ex urbe expulsus est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"criminari","latin":"(crīminor) crīminārī","headword":"crīminārī","letter":"c","pos":"","posGroup":"other","english":"accuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"criminor","latin":"criminor, criminari, criminatus sum","headword":"criminor","letter":"c","pos":"verb","posGroup":"verb","english":"accuse, denounce; charge (with); allege with accusation; make accusations","forms":["crīminandō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Minucius, magister equitum, ferōx et temerārius, crīminandō dictātōrem tamquam sēgnem et timidum effēcit populī iussū aequārētur eī cum dictātōre imperium; dīvīsōque exercitū, cum inīquō locō cōnflīxisset et in magnō discrīmine legiōnēs eius essent, superveniente cum exercitū Fabiō Maximō discrīmine līberātus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"crinis","latin":"crīnis, -is (m.)","headword":"crīnis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"hair","forms":["crīne","crīnem","crīnēs","crīnibus","crīnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed spatiō temporis {{crīnis}} accīsus crēscere et cum crīne virtūs redīre coepit: iamque Samsōn, cōnscius receptī rōboris, iūstae ultiōnis tempus opperiēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"crinitus","latin":"crinitus, crinita, crinitum","headword":"crinitus","letter":"c","pos":"adjective","posGroup":"adjective","english":"hairy; having long locks, long haired; hair-like; [stella crinita => comet]","forms":["crīnīta","crīnītus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quae male {{crīnīta}} est, cūstōdem in līmine pōnat","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"crispans","latin":"crispans, (gen.), crispantis","headword":"crispans","letter":"c","pos":"adjective","posGroup":"adjective","english":"curled; uneven, wrinkled; trembling (of an earthquake)","forms":["crispāns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"bīna manū lātō {{crispāns}} hastīlia ferrō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"crispus","latin":"crispus, crispa, crispum","headword":"crispus","letter":"c","pos":"adjective","posGroup":"adjective","english":"curled/curly; trembling/vibrating; uneven/wrinkled/twisted; elegant (style)","forms":["crīspus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"facere | {{crīspus}} -ā -um","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cristatus","latin":"cristatus, cristata, cristatum","headword":"cristatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"tufted, crested; having a comb/tuft on head; plumed; [~ ales => cock]","forms":["cristātus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"hāc Phrygēs, īnstāret currū {{cristātus}} Achillēs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"croceus","latin":"croceus, crocea, croceum","headword":"croceus","letter":"c","pos":"adjective","posGroup":"adjective","english":"yellow, golden; saffron-colored; of saffron/its oil, saffron-; scarlet (Ecc)","forms":["croceō","croceum","croceus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nusquam corpus erat; {{croceum}} prō corpore flōrem","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"croco","latin":"croco, crocare, crocavi, crocatus","headword":"croco","letter":"c","pos":"verb","posGroup":"verb","english":"dye saffron-yellow","forms":["crocō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"vel prope té natō, lūcide Cydne, crocō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"crocum","latin":"crocum, croci","headword":"crocum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"saffron color/dye/oil/perfume (theater); crocus/saffron (Crocus sativus)","forms":["crocum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ille {{crocum}} simulat (croceō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"crocus","latin":"crocus, croci","headword":"crocus","letter":"c","pos":"noun","posGroup":"noun","english":"crocus/saffron (Crocus sativus); its oil; saffron-color (L+S); yellow stamens","forms":["crōcē","crocus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nūda pedem, crōcēàs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"crotale","latin":"crotale, crotalis","headword":"crotale","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"ear-rings (pl.); ear pendants of several loosely hanging/rattling pearls","forms":["crotalia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Inde duo {{crotalia}} prôtulit et °r°t3|ī33 '5' Fortūnātae in vicem cônsîderanda dedit, et “Dominî” inquit “meî beneﬁciô nëmô “Quid?” inquit Habinnās, “excatarissästî mē, ut tibi emerem fabam vitream.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"cruciare","latin":"(cruciō) cruciāre, cruciāvisse, cruciātum","headword":"cruciāre","letter":"c","pos":"verb","posGroup":"verb","english":"torture; to torture","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cruciatus","latin":"cruciātus, -ūs","headword":"cruciātus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"torture","forms":["cruciātibus","cruciātū","cruciatum","cruciātūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sua in illos merita proponit obtestaturque ut suae salutis rationem habeant, neu se optime de communi libertate meritum hostibus in {{cruciatum}} dedant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"crucifigo","latin":"crucifigo, crucifigere, crucifixi, crucifixus","headword":"crucifigo","letter":"c","pos":"verb","posGroup":"verb","english":"crucify; attach to a cross","forms":["crucifīxērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et postquam vēnērunt in locum quī vocātur ' Calvāria', {{crucifīxērunt}} eum, et latrōnēs duōs, alterum ā dextrīs et alterum ā sinistrīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"crucio","latin":"crucio, cruciare, cruciavi, cruciatus","headword":"crucio","letter":"c","pos":"verb","posGroup":"verb","english":"torment, torture; cause grief/anguish; crucify; suffer torture/agony; grieve","forms":["cruciābō","cruciāre","cruciāret","cruciāverō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Profectō Promēthēum omnibus modīs cruciābō, cum prīmum eum cēperō!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"crudele","latin":"crudele, crudelius, crudelissime","headword":"crudele","letter":"c","pos":"adverb","posGroup":"adverb","english":"cruelly, harshly, severely, unmercifully, savagely, fiercely","forms":["crūdēle"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubī ad aurēs Mardochaeī {{crūdēle}} ēdictum pervēnit, statim cōnscīssis vestibus saccum induit, cōnspersusque cinere perrēxit ad rēgiam, et illam implēvit questibus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"crudelis","latin":"crūdēlis, -e","headword":"crūdēlis","letter":"c","pos":"adjective","posGroup":"adjective","english":"cruel; cruel, bloody; cruel, harsh","forms":["crūdēlem","crūdēlēs","crūdēlī","crūdēlia","crūdēlibus","crūdēlis","crūdēlissimae","crūdēlissimē","crūdēlissimī","crūdēlissimīs","crūdēlissimō","crūdēlissimum","crūdēlissimus","crūdēlius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tunc coepērunt inter sē dīcere: meritō haec patimur; {{crūdēlēs}} fuimus in frātrem nostrum; nunc poenam huius sceleris luimus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"crudelitas","latin":"crūdēlitās, -ātis ( f.)","headword":"crūdēlitās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cruelty","forms":["crūdēlitās","crūdēlitāte","crudelitatem","crūdēlitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac variis dictis sententiis, quarum pars deditionem, pars, dum vires suppeterent, eruptionem censebat, non praetereunda oratio Critognati videtur propter eius singularem et nefariam {{crudelitatem}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"crudeliter","latin":"crudeliter, crudelius, crudelissime","headword":"crudeliter","letter":"c","pos":"adverb","posGroup":"adverb","english":"cruelly, savagely, relentlessly; with cruel effect","forms":["crudeliter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos {{crudeliter}} excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cruento","latin":"cruento, cruentare, cruentavi, cruentatus","headword":"cruento","letter":"c","pos":"verb","posGroup":"verb","english":"stain/spot/mark with blood; cause to bleed, wound; pollute with blood-guilt","forms":["cruentō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōlō tē fatīgāre nārrandō dē bellō cruentō, cum brevī pācem fore spērem.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cruentus","latin":"cruentus, -a, -um","headword":"cruentus","letter":"c","pos":"adjective","posGroup":"adjective","english":"bloody, gory; bloody, bloodstained; bloody; bloodstained, bloody","forms":["cruentā","cruentam","cruentās","cruentōs","cruentum","cruentus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cum vērō amīcī, quī apud eum stābant, ferrum ēdūxērunt, ūna cum sagittā cruentā pars pulmōnis est extracta.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cruor","latin":"cruor, cruōris","headword":"cruor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) gore, blood; blood, gore; blood","forms":["cruor","cruōre","cruōrem"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōlī per imbrem frīgidum ambulāre!” sōlum ūmida, sed etiam sordida sunt vestīmenta eius, atque faciēs {{cruōre}} et sordibus operītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"crus","latin":"crūs, crūris","headword":"crūs","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"(n.) leg; leg, shin","forms":["crūra","crūre","crūribus","crūris","crūs","CRVRA"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sextus sē locō movēre nōn potest, quod duo puerī super corpus eius sedent alter bracchia, alter {{crūra}} tenēns.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"crux","latin":"crux, crucis","headword":"crux","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) cross","forms":["cruce","crucem","crucī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Ē sther:\"Meam, ō rēx, meaeque gentis salūtem precor, nam crūdēlis iste Amān nōs dēvōvit necī.\"Quā rē permōtus est As suerus, audiēnsque {{crucem}} ab eō parātam esse Mardochaēō, Amanem ipsum eīdem crucī iussit affigī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cubans","latin":"cubans, (gen.), cubantis","headword":"cubans","letter":"c","pos":"adjective","posGroup":"adjective","english":"lying, resting on the ground; low lying; sagging, sloping, liable to subside","forms":["cubāns","cubantem","cubantēs","cubantibus","cubantis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Iacobus iter persecūtus pervenit in Mesopotamiam; vīdit trēs pecorum gregēs propter puteum {{cubantēs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cubare","latin":"cubāre, -ō, cubuī, cubitum","headword":"cubāre","letter":"c","pos":"verb","posGroup":"verb","english":"to lie (in bed); to lie, recline","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cubat","latin":"cubat, cubāre","headword":"cubat","letter":"c","pos":"verb","posGroup":"verb","english":"lie (in bed); lies, is lying down","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cubiculum","latin":"cubiculum, -ī","headword":"cubiculum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"bedroom; bedroom, room; room, bedroom","forms":["cubicula","cubiculī","cubiculīs","cubiculō","cubiculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum Quīntus in lectō iacet in cubiculō suō, Medicus in ātriō Iūlium exspectat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"cubile","latin":"cubīle, -is (n.)","headword":"cubīle","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"bed, couch","forms":["cubīle"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tīthōnī croceum linquēns Aurōra {{cubīle}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"cubitum","latin":"cubitum, cubiti","headword":"cubitum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"elbow; forearm; ulna; cubit (length - 17.4 inches); elbow bend/pipe","forms":["cubitīs","cubitum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aqua operuit ūniversam terram, ita ut superāret quīndecim {{cubitīs}} altissimōs montēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cubitus","latin":"cubitus, cubitus","headword":"cubitus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"state/action of reclining/lying down/taking rest; bed, couch","forms":["cubitibus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Is 'sē' dīxit cum Alcumēnā clam cōnsuētum {{cubitibus}},","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"cubo","latin":"cubo, cubare, cubui, cubitus","headword":"cubo","letter":"c","pos":"verb","posGroup":"verb","english":"lie (down/asleep); recline, incline; lie/be in bed, rest/sleep; be sick/dead","forms":["cubābant","cubābat","cubābit","cubāre","cubās","cubat","cubet","cubitū","cubō","cubuistī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nocte vērō in silvīs humī {{cubābat}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cucumis","latin":"cucumis, cucumeris","headword":"cucumis","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cucumber (plant/fruit); kind of marine animal (sea cucumber?)","forms":["cucumerēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pōne oxygarum et lactūcās et {{cucumerēs}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cucurbita","latin":"cucurbita, cucurbitae","headword":"cucurbita","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"gourd (plant/fruit) (Cucurbitaceae); dolt/pumpkin-head; cup, cupping-glass","forms":["cucurbitās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Affertur gustātiō: ōva, holera, piscēs...] [Iūlius, ad singulōs ministrōs:] “Dā nōbīs prīmum bētās aut {{cucurbitās}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cucurru","latin":"cucurru","headword":"cucurru","letter":"c","pos":"interjection","posGroup":"interjection","english":"cock-a-doodle-doo!","forms":["Cucurru"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Ecce gallus canit: '{{Cucurru}}!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cucus","latin":"cucus, cuci","headword":"cucus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"daw, jackdaw (Corvus monedula?); (might be used of a fool/sluggard/slut)","forms":["Cucō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Currēns enim hūc et illūc fīliārum corpora complectēbātur et manibus rāmōs, in quibus membra claudēbantur, rumpere et frangere cōnābātur: at inde sanguis IovisfiiCmīne percussūs, in flūmen Ēridanum dē caelō cadit Actaeōn in Cucō nymphās cōnspicit effundēbātur tamquam ex vulnere: “Parce, precor, māter!” clāmābant, “Parce!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cui","latin":"cui?","headword":"cui","letter":"c","pos":"pronoun","posGroup":"pronoun","english":"to whom?","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cuius","latin":"cuius?","headword":"cuius","letter":"c","pos":"pronoun","posGroup":"pronoun","english":"(gen. sing.) whose; whose?","forms":["cuia","cuius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, {{cuius}} pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"culina","latin":"culīna, -ae","headword":"culīna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"kitchen","forms":["culīnā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sīc Tantalus, quī etiam cognōscere volēbat utrum dīī omnia animadverterent, carnēs miserī fīliī inhūmānē interfectī ē culīnā in trīclīnium portāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"culmen","latin":"culmen, -inis (n.)","headword":"culmen","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"summit, top, peak, roof; summit, roof-top","forms":["culmen","culmina","culmine","culminī","culminibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ruit altō ā {{culmine}} Trōia.\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"culmus","latin":"culmus, culmi","headword":"culmus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"stalk, stem (of cereal grass/others); hay; straw; thatch","forms":["culmō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Septem spīcae plēnae ēnāscēbantur in ūnō culmō, aliaeque totidem exīlēs succrēscēbant, ēspīcās plēnās cōnsūmēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"culo","latin":"culo, culare, culavi, culatus","headword":"culo","letter":"c","pos":"verb","posGroup":"verb","english":"drive, thrust, shove; (perh. slang); push (one) by/in the culus (Sex rude)","forms":["culā","cūlās","culere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"oc-{{culere}} -uissē -tum - occultāre","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"culpa","latin":"culpa, -ae","headword":"culpa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"blame, fault, guilt; guilt, blame, fault; fault, blame","forms":["culpa","culpae","culpam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc Iūdās, ūnus ē fīliīs Iacobī, dīxit patrī: committe mihi puerum; ego illum recipiō in fidem meam; ego servābō, ego redūcam illum ad tē; nisi fēcerō, huius reī {{culpa}} in mē residēbit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"culpare","latin":"culpāre","headword":"culpāre","letter":"c","pos":"verb","posGroup":"verb","english":"to blame","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"culpo","latin":"culpo, culpare, culpavi, culpatus","headword":"culpo","letter":"c","pos":"verb","posGroup":"verb","english":"blame, find fault with, censure, reproach, reprove, disapprove; accuse, condemn","forms":["culpāvī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sēderat quoque Hippomenēs spectātor cursūs; damnāverat procōs: \"Petīturne coniūnx per tanta perīcula?\" Sed ubi vīdit fōrmam corpusque puellae, dīxit: \"Mihī ignōscite, quōs culpāvī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"culter","latin":"culter, cultrī","headword":"culter","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"knife","forms":["cultrī","cultrō","cultrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: “Sūme {{cultrum}} ac vēnam aperī tuam!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"cultor","latin":"cultor, cultoris","headword":"cultor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"inhabitant; husbandman/planter/grower; supporter; worshiper; who has interest","forms":["cultor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mortuō patre, IOsaphātus rēgnāre coepit, fuitque religiōsus Deī {{cultor}}: quāpropter Deus illum glōria et dīvitiīs auxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cultum","latin":"cultum, culti","headword":"cultum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cultivated/tilled/farmed lands (pl.); gardens; plantations; standing crops","forms":["cultum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad eōs Deus saepe mīsit prophētās, quī eōs admonērent, et ad vērum {{cultum}} revocārent; sed illī prophētārum monitīs nōn pāruērunt, immō eōs contumēliīs, poenīs, morte affēcērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cultura","latin":"cultūra, -ae","headword":"cultūra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cultivation, care","forms":["cultūrā"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Fīlius agricolae ipse agricola sēdulus, dum in praediō suō morātur, scrīpsit librum ‘Dē agrī cultūrā’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cultus","latin":"cultus, -ūs","headword":"cultus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"cultivation, care, mode of life, worship","forms":["culta","cultās","cultīs","cultissima","cultō","cultōs","cultū","cultuī","cultūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is, relictō vērō D eī cultū, falsa nūmina adōrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"culus","latin":"culus, culi","headword":"culus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"buttocks; posterior; anus; (rude)","forms":["cūlīs","culum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"[Servitium et mīlitia amōris] umbrá{{culum}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cum","latin":"cum","headword":"cum","letter":"c","pos":"preposition; conjunction","posGroup":"preposition","english":"(prp. + abl.) with; when; when, since","forms":["cum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium Cadurcum, summae hominem audaciae, {{cum}} parte copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cum…tum","latin":"cum…tum","headword":"cum…tum","letter":"c","pos":"","posGroup":"other","english":"not only…but also","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cuma","latin":"cuma, cumae","headword":"cuma","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"spring shoots of cabbage/similar; hollow sphere (L+S); spherical layer, stratum","forms":["cuma","Cūmārum","Cumās","Cumīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[Aenēās] . . . loca fēta palustribus undīs,\nlītora {{Cūmārum}} vīvācisque antrā Sibyllae\nintrat, et [ut] ad mānēs veniat per Averna paternōs\nōrat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cumatilis","latin":"cumatilis, cumatilis, cumatile","headword":"cumatilis","letter":"c","pos":"adjective","posGroup":"adjective","english":"wave/sea colored; water-colored, blue (L+S); of the waves; [deus ~ => Neptune]","forms":["cūmātilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ab undīs: {{cūmātilis}} -ē (« Gr cuma","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cumque","latin":"cumque","headword":"cumque","letter":"c","pos":"adverb","posGroup":"adverb","english":"at any time; -ever, -soever; appended to give generalized/indefinite force","forms":["cumque"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iōsēphus vīxit annōs centum et decem; {{cumque}} esset mortī proximus, convocāvit frātrēs suōs, et illōs admonuit sē brevī moritūrum esse.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cumulatus","latin":"cumulatus, cumulata -um, cumulatior -or -us, cumulatissimus -a -um","headword":"cumulatus","letter":"c","pos":"adjective","posGroup":"adjective","english":"heaped (up), abounding in; great/abundant/vast; increased/augmented (L+S); full","forms":["cumulātae","cumulātam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deus fēcit foedus cum illō hīs verbīs: exī ē domō paternā, dēsere patriam, et pete regiōnem quam datūrus sum posterīs tuīs: augēbō tē prōle numerōsā; eris pater multārum gentium, ac per tē omnēs orbis nātiōnēs erunt bonīs {{cumulātae}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cumulo","latin":"cumulo, cumulare, cumulavi, cumulatus","headword":"cumulo","letter":"c","pos":"verb","posGroup":"verb","english":"heap/pile up/high, gather into a pile/heap; accumulate, amass; load/fill full","forms":["cumulāvistī","cumulāvit","cumulō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rēx indignāns respondit: “Inīquē fēcit quisquis ille est: prō ove ablātā quattuor ovēs reddet.” Tum prophēta apertē: “Tū” ait “tū es iste vir: tē Deus bonīs omnibus {{cumulāvit}}, tē rēgem fēcit, tē ab īrā Saūlis līberāvit, tibi rēgiam domum, rēgiās opēs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cumulus","latin":"cumulus, -ī","headword":"cumulus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"heap, pile","forms":["cumulum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dum tamen hanc sperat, dum praecorrumpere dōnīs\nmē cupit, \"ēlige\" ait \"virgō Cūmaea, quid optēs:\noptātīs potiēre tuīs.\" Ego pulveris haustī\nostendī {{cumulum}}: quot habēret corpora pulvis,\ntot mihi nātālēs contingere vāna rogāvī;\nexcidit, ut peterem iuvenēs quoque prōtinus annōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cuna","latin":"cuna, cunae","headword":"cuna","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cradle (usu. pl.); nest for young birds; one's earliest years","forms":["cūnae","cūnās","cūnīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Parvulus īnfāns in {{cūnīs}} cubāre solet.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cunabula","latin":"cūnābula, -ōrum (n. pl.)","headword":"cūnābula","letter":"c","pos":"","posGroup":"other","english":"cradle","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cunabulum","latin":"cunabulum, cunabuli","headword":"cunabulum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cradle (pl.); earliest home/years/childhood; hereditary station; nest/hive","forms":["cūnābula"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Cūnae sunt {{cūnābula}} īnfantīs.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cunae","latin":"cūnae, -ārum","headword":"cūnae","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"crib; cradle (plural)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"cuncta","latin":"cuncta, cunctae","headword":"cuncta","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"all (pl.) (F); all with a stated/implied exception","forms":["cuncta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis {{cuncta}} Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cunctans","latin":"cunctans, cunctantis (gen.), cunctantior -or -us, cunctantissimus -a -um","headword":"cunctans","letter":"c","pos":"adjective","posGroup":"adjective","english":"hesitant/delaying/slow to act, tardy; clinging; stubborn, resistant to movement","forms":["cūnctantem","cūnctantēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dabis, improbe, poenās!' Hīs dictīs medium sermōnem abrumpit et aegra ex oculīs aufugit, linquēns eum {{cūnctantem}} et multa dīcere parantem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cunctari","latin":"(cūnctōr) cūnctārī","headword":"cūnctārī","letter":"c","pos":"","posGroup":"other","english":"hesitate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"cunctatio","latin":"cunctatio, cunctationis","headword":"cunctatio","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"delay, hesitation; tardiness, inactivity; hesitating about/delaying of (w/GEN)","forms":["cūnctātiōnem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quis enim potest melius vel {{cūnctātiōnem}} meam regere vel ignōrantiam īnstruere?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cunctor","latin":"cunctor, cunctari, cunctatus sum","headword":"cunctor","letter":"c","pos":"verb","posGroup":"verb","english":"delay, impede, hold up; hesitate, tarry, linger; be slow to act; dawdle; doubt","forms":["cūnctāminī","cūnctandō","cunctandum","cūnctantur","cūnctārī","cūnctentur","cūnctētur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"dūbītàrē imf — cūnctārī, cessāre","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cunctus","latin":"cūnctus, -a, -um","headword":"cūnctus","letter":"c","pos":"adjective","posGroup":"adjective","english":"all; all, whole","forms":["cūnctam","cūnctās","cuncti","cūnctīs","cūnctōs","cūnctus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin {{cuncti}} caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cuneatim","latin":"cuneatim","headword":"cuneatim","letter":"c","pos":"adverb","posGroup":"adverb","english":"in a closely packed/wedge formation; in the form of a wedge, wedge-shaped","forms":["cuneatim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque deiecti in foro ac locis patentioribus {{cuneatim}} constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cuneus","latin":"cuneus, -ī","headword":"cuneus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"wedge","forms":["cuneum","cuneus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tandem Rōmānī impulēre hostium {{cuneum}} ā cēterā prōminentem aciē.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cuniculus","latin":"cuniculus, cuniculi","headword":"cuniculus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"rabbit; underground tunnel/burrow/hole; mine/excavation; channel; secret device","forms":["cuniculis","cuniculo","cuniculorum","cuniculos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem {{cuniculis}} subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cupa","latin":"cupa, cupae","headword":"cupa","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"barrel, cask, vat, tun; (esp. for wine); niche in a columbarium (for ashes)","forms":["cupis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tacente Quīntō, Syrā pergit: 'An {{cupis}} audīre tabulam dē Achille, duce Graecōrum, quī Hectorem, ducem Troiānum, interfēcit atque corpus eius mortuum post currum suum trāxit circum moenia urbis Trōiae?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"cupere","latin":"(cupiō) cupere, cupīvisse, cupitum","headword":"cupere","letter":"c","pos":"verb","posGroup":"verb","english":"want, desire; to desire, want","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"cupide","latin":"cupidē","headword":"cupidē","letter":"c","pos":"adverb","posGroup":"adverb","english":"eagerly","forms":["cupidē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Postquam omnēs adfuērunt, servī vīnum in pōcula fūdērunt, quod virī, quī parātī erant ad audiendum, cupidē bibērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cupiditas","latin":"cupiditās, cupiditātis","headword":"cupiditās","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"(f.) desire","forms":["cupiditas","cupiditate","cupiditātem","cupiditātibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas excidere conatus esset, a multitudine oppressus ac sibi desperans, multis iam vulneribus acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem certe vitae prospiciam, quos {{cupiditate}} gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cupido","latin":"cupīdō, -inis ( f.)","headword":"cupīdō","letter":"c","pos":"noun (m.); noun (f.)","posGroup":"noun","english":"desire, passion; Cupid, Eros, Amor","forms":["cupīdine","cupīdinem","Cupīdinis","cupīdō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neque vēro omnia dīxī, nam mala memoria mihi est.” Hic Cupīdō, deus quī, quamquam iuvenis esse vidētur, senex tamen est, simul atque pōculum suum funditus exhausit, exclāmāvit: “Num ideō tantam iniūriam nōn esse pūniendam cēnsēs?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cupidus","latin":"cupidus, -a, -um","headword":"cupidus","letter":"c","pos":"adjective","posGroup":"adjective","english":"desirous; eager, desirous (+ gen.); eager, desiring (+ gen.); eager, greedy (+ gen.)","forms":["cupidā","cupidae","cupidam","cupidās","cupidī","cupidior","cupidīs","cupidissima","cupidissimē","cupidissimī","cupidissimis","cupidissimus","cupidōs","cupidum","cupidus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Adhortatus milites ne necessario tempore itineris labore permoveantur, {{cupidissimis}} omnibus progressus milia passuum XXV, agmen Aeduorum conspicatus, immisso equitatu iter eorum moratur atque impedit; interdicitque omnibus ne quemquam interficiant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cupiens","latin":"cupiens, cupientis (gen.), cupientior -or -us, cupientissimus -a -um","headword":"cupiens","letter":"c","pos":"adjective","posGroup":"adjective","english":"desirous, eager for, longing; anxious","forms":["cupiēns","cupientem","cupientī","cupientium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Deus tamen, quī hoc plānē ignōrābat, laetābātur quod tālia verba ex fōrmōsissimā virgine audiēbat, atque, Corōnidem vidēre {{cupiēns}}, cotīdiē dē summō Olympō dēscendere solēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cupio","latin":"cupio, cupere, cupivi, cupitus","headword":"cupio","letter":"c","pos":"verb","posGroup":"verb","english":"wish/long/be eager for; desire/want, covet; desire as a lover; favor, wish well","forms":["cupere","Cuperem","cuperēs","cuperet","cupiam","cupiās","cupiat","cupiēbant","cupiēbat","cupient","cupiēre","cupiō","cupit","cupitis","cupiunt","cupīverīs","cupīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hōc indiciō cognōvit Eliezer quod scīre {{cupiēbat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cupressus","latin":"cupressus, cupressi","headword":"cupressus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cypress-tree; cypress oil/wood, cypress-wood casket, spear of cypress-wood","forms":["cupressī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Apollō igitur, trīstis ad arborem accēdēns, “Ego” inquit, “semper tē flēbō, amīce; tū vērō aliōs flēbis et dolentibus hominibus omnī tempore aderis!” Hoc est cūr arborem, quae ex illō puerō Graecē ‘cyparissī’, La tīne vērō ‘cupressī’ nōmen habet, prope amīcōrum nostrōrum sepulcra pōnāmus.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cur","latin":"cūr?","headword":"cūr","letter":"c","pos":"adverb","posGroup":"adverb","english":"why?; why","forms":["cūr"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Cur}} enim potius Aedui de suo iure et de legibus ad Caesarem disceptatorem quam Romani ad Aeduos veniant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cura","latin":"cūra, -ae","headword":"cūra","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"care, concern","forms":["cura","cūrae","cūram","cūrārum","cūrās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Allobroges crebris ad Rhodanum dispositis praesidiis magna cum {{cura}} et diligentia suos fines tuentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"curare","latin":"cūrāre","headword":"cūrāre","letter":"c","pos":"verb","posGroup":"verb","english":"care for, look after; to care for; see to it that","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"curate","latin":"curate, curatius, curatissime","headword":"curate","letter":"c","pos":"adverb","posGroup":"adverb","english":"carefully, with care; diligently; elaborately","forms":["cūrātē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fāma dē adventū frātrum Iōsēphī ad aurēs rēgis pervēnit; quī dēdit eīs mūnera perferenda ad patrem cum hīs mandātīs: addūcite hūc patrem vestrum et omnem eius familiam, nec multum cūrātē supellectilem vestram, quia omnia quae opus erunt vōbīs praebitūrus sum, et omnēs opēs Aegyptī vestrae erunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cures","latin":"cures, curis","headword":"cures","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"spear; (Sabine word)","forms":["cūrēs","Curī","Curibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Alcēstis, quae Admētum tōtam rem nārrantem, parentēsque ‘sē nōlle prō eō morī’ dīcentēs exaudīverat, “Ō Ad mete, dīlēctissime coniūnx,” inquit “tē plūs quam vītam meam amō; sine morā parātissimā sum ad moriendum; Plūtōnis rēgnum prō tē petam, unde negant redīre quemquam; hoc ūnum tamen tē rogō, ut līberōs nostrōs etiam post mortem meam bene {{cūrēs}} et doceās; ōrō quoque nē meī, quae tantum tē amāvī, oblīvīscāris.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"curia","latin":"cūria, -ae","headword":"cūria","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"curia (division of the people, Senate-House); senate house, council; senate-house","forms":["cūria","cūriae","cūriam","cūriās","cūriīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi {{cūria}} Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) nefandās, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"curiatius","latin":"curiatius, curiatia, curiatium","headword":"curiatius","letter":"c","pos":"adjective","posGroup":"adjective","english":"of curiae; (w/Comitia) (pl.) assembly in which people voted according to curia","forms":["Curiātiī","Curiātiīs","Curiātiōrum","Curiātiōs","Curiātium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iam aliquantum spatiī ex eō locō ubi pugnātum est aufūgerat, cum respiciēns videt {{Curiātiōs}} magnīs intervāllīs sequentēs, ūnum haud procul ab sēsē abesse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"curio","latin":"curio, curionis","headword":"curio","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"priest presiding over a curia; crier/herald; [~ maximus => chief of this sect]","forms":["Curiō","Curiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scrībōnius Curiō, quī Dardanōs vīcit et ūsque ad Danuvium penetrāvit triumphumque meruit et intrā triennium bellō fīnem dedit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"curiosus","latin":"cūriōsus, -a, -um","headword":"cūriōsus","letter":"c","pos":"adjective","posGroup":"adjective","english":"curious, inquisitive","forms":["cūriōsior","cūriōsīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed saccus ventōrum ā nautīs {{cūriōsīs}} aperītur et ventī effugiunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"curis","latin":"curis, curis","headword":"curis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"spear; (Sabine word)","forms":["cūrīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ita loquitur, et maximīs {{cūrīs}} aeger vultū spem simulat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"curius","latin":"curius, curia, curium","headword":"curius","letter":"c","pos":"adjective","posGroup":"adjective","english":"grievous; full of sorrow","forms":["Curius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Curius}} Dentātus, ambō cōnsulēs, contrā Samnītās missī ingentibus proeliīs eōs cōnfēcēre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"curo","latin":"cūrō, cūrāre","headword":"cūrō","letter":"c","pos":"verb","posGroup":"verb","english":"care for","forms":["cūrābant","cūrābat","cūrābimus","cūrābō","cūranda","cūrandam","cūrandās","cūrandum","cūrant","cūrāre","cūrārent","curaret","cūrārētur","curat","cūrāta","cūrātō","cūrātōs","curaverat","curaverunt","cūrāvit","cūrem","cūret","cūrō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum disparandos deducendosque ad suos {{curaret}}, quae cuique civitati pars castrorum ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"currens","latin":"currens, (gen.), currentis","headword":"currens","letter":"c","pos":"adjective","posGroup":"adjective","english":"current","forms":["currēns","currentem","currentēs","currentī","currentibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Incolae perterritī, quamquam fūnibus et hastīs ūtēbantur, taurum hūc et illūc {{currentem}} capere nōn poterant; nec ē tālī perīculō līberātī sunt, dōnec Herculēs, quī in Crētam vēnerat, illam saevissimam bēstiam tandem cēpit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"currere","latin":"currere","headword":"currere","letter":"c","pos":"verb","posGroup":"verb","english":"to run","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"currit","latin":"currit, currunt","headword":"currit","letter":"c","pos":"verb","posGroup":"verb","english":"run; runs","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"curro","latin":"curro, currere, cucurri, cursus","headword":"curro","letter":"c","pos":"verb","posGroup":"verb","english":"run/trot/gallop, hurry/hasten/speed, move/travel/proceed/flow swiftly/quickly","forms":["cucurrerat","cucurrērunt","cucurrī","cucurrit","currat","curre","currēbant","currēbat","currendī","currendō","currendum","current","currere","curreret","curreretur","curris","currit","currite","currō","currunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum {{curreretur}} aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"currus","latin":"currus, -ūs","headword":"currus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) chariot","forms":["Curribus","currū","curruī","currum","currus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum dētrāxit ē manū suā annulum, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō torquem aureum circumdedit, eumque in currū suō secundum collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cursor","latin":"cursor, -ōris","headword":"cursor","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"runner","forms":["Cursor","cursōrēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duo {{cursōrēs}} trāns summum cursum volāre videntur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cursus","latin":"cursus, -ūs","headword":"cursus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"(m.) running, forward movement; course; running, course","forms":["cursu","cursum","cursūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat Romanis nec loco nec numero aequa contentio; simul et {{cursu}} et spatio pugnae defatigati non facile recentes atque integros sustinebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"curtus","latin":"curtus, curta, curtum","headword":"curtus","letter":"c","pos":"adjective","posGroup":"adjective","english":"mutilated; incomplete, missing a part; circumcised; castrated, gelded; docked","forms":["curtīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hodiē trīcēsima sabbata: vīn’ tū {{curtīs}} Iūdaeīs oppēdere?” “Nūlla mihi” inquam “religiō est.” [Fuscus:] “At mī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"curvo","latin":"curvō (1)","headword":"curvō","letter":"c","pos":"verb","posGroup":"verb","english":"curve, bend, arch","forms":["curvāre","curvātō","curvāvit","curvō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde ille occīdit Sinem magnīs vīribus male ūsum, quī tam validus erat ut pīnūs ad terram {{curvāre}} posset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"curvum","latin":"curvum, curvi","headword":"curvum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"curve; curved object or line; that which is crooked/wrong (L+S); (morally)","forms":["curvum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"curváre — {{curvum}} facere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"curvus","latin":"curvus, -a, -um","headword":"curvus","letter":"c","pos":"adjective","posGroup":"adjective","english":"curved, crooked, bent; curved, bending","forms":["curvā","curvīs","curvus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dum in hortīs cultīs errat, pōmum poenīceum dē arbore curvā carpserat et in ōre suō septem grāna presserat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cuspis","latin":"cuspis, cuspidis","headword":"cuspis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"point/tip (spear), pointed end; spit/stake; blade; javelin/spear/lance; sting","forms":["cuspide"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec ubi dicta, cavum conversā {{cuspide}} montem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"custodia","latin":"cūstōdia, -ae","headword":"cūstōdia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"guard, custody, post; guard, custody","forms":["cūstōdia","custōdiam","custodiis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar dispositis in vallo {{custodiis}} recipi prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"custodio","latin":"custodio, custodire, custodivi, custoditus","headword":"custodio","letter":"c","pos":"verb","posGroup":"verb","english":"guard/protect/preserve, watch over, keep safe; take heed/care, observe; restrain","forms":["cūstōdiēbantur","cūstōdiēbat","cūstōdiendam","cūstōdiendum","cūstōdient","cūstōdientēs","cūstōdīre","cūstōdīret","cūstōdīrī","cūstōdit","custōdiunt","cūstōdīvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Symmachus: “Nōnne iānitor {{cūstōdit}} domum tuam?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"custodire","latin":"(cūstōdiō) cūstōdīre, cūstōdīvisse,  cūstōdītum","headword":"cūstōdīre","letter":"c","pos":"verb","posGroup":"verb","english":"guard; to guard","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"custos","latin":"cūstōs, -ōdis (m./f.)","headword":"cūstōs","letter":"c","pos":"noun; noun (m.)","posGroup":"noun","english":"guardian, guard; guardian, keeper; guard, watchman","forms":["cūstōde","cūstōdem","custōdēs","cūstōdī","custodibus","cūstōdīs","cūstōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque interfectis Novioduni {{custodibus}} quique eo negotiandi causa convenerant, pecuniam atque equos inter se partiti sunt; obsides civitatum Bibracte ad magistratum deducendos curaverunt; oppidum, quod a se teneri non posse iudicabant, ne cui esset usui Romanis, incenderunt; frumenti quod subito potuerunt navibus avexerunt, reliquum flumine atque incendio corruperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"cutis","latin":"cutis, cutis","headword":"cutis","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"skin; external appearance, surface; person, body; leather/hide; rind; membrane","forms":["cutem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, linguam amputarī, {{cutem}} capitis detrahī, summās mantīs ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"cyanus","latin":"cyanus, cyani","headword":"cyanus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"precious stone (like lapis-lazuli); blue cornflower/blue-bottle Centaurea cyanus","forms":["Cyānē"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"In mediō stāgnō nympha Cyānē, ā cuius nōmine stāgnum dictum est, celeberrima inter nymphās Siciliānās exstitit recōgnōvitque deam.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cyathus","latin":"cyathus, cyathi","headword":"cyathus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"1/12 sextarius/pint; shot (liquid measure); 10 drachmae (dry measure)","forms":["cyathō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cēna ministrātur puerīs tribus, et lapis albus pōcula cum cyathō duo sustinet; adstat echīnus vīlis, cum paterā gūtus, Campāna supellex.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"cyclops","latin":"Cyclōps, -is","headword":"Cyclōps","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cyclops, the one-eyed giant","forms":["Cyclōpis","cyclōps"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Polyphēmus fuit {{Cyclōps}} quī ōlim in īnsulā Sicilia habitābat ibique vīta rūstica fruēbātur (Cyclōps est mōnstrum homine altius atque fortius, quod vērō ūnum oculum in mediā fronte habet).","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cycnus","latin":"cycnus, cycni","headword":"cycnus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"swan; (favorable omen)","forms":["cycnīs","cycnōrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Haud procul lacus est ubi carmina {{cycnōrum}} audiuntur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cydonia","latin":"Cydonia, Cydoniae","headword":"Cydonia","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Cydonia, city in Crete; (now Canea L+S))","forms":["Cydōnia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"« Cnōsōs, {{Cydōnia}}, urbēs Crētae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cygnus","latin":"cygnus, cygni","headword":"cygnus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"swan; (favorable omen)","forms":["Cygnō","Cygnum","Cygnus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Fēcerat haec [fāma] nōtum Graiās cum mīlite fortī adventāre ratēs neque inexspectātus in armīs hostis adest; prohibent aditūs lītusque tuentur Trōes, et magnō quid Achāica dextera posset sanguine sēnsērunt, et iam Phrygia rubēbant lītora, iam lētō prōlēs Neptūnia, {{Cygnus}}, mīlle virōs dederat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cyllenius","latin":"Cyllenius, Cyllenia, Cyllenium","headword":"Cyllenius","letter":"c","pos":"adjective","posGroup":"adjective","english":"Cyllenian; of Mt. Cyllene; (epithet of Mercury)","forms":["Cyllēnia","Cyllēnius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"725 ecce redit Cephalus silvīs, {{Cyllēnia}} prōlēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cymbalum","latin":"cymbalum, cymbali","headword":"cymbalum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"cymbal; (term for tedious/stupid speaker); cymbals (usu. pl.); valve","forms":["cymbala"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{cymbala}} -ōrum n pl","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cynthus","latin":"Cynthus, Cynthi","headword":"Cynthus","letter":"c","pos":"noun (m.)","posGroup":"noun","english":"Cynthus; (mountain on Delos, birthplace of Apollo and Diana)","forms":["Cynthī","Cynthus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cynthius -1, Apollō («€ {{Cynthus}} -ī nī,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"cyparissus","latin":"cyparissus, cyparissi","headword":"cyparissus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"cypress-tree; cypress oil/wood, cypress-wood casket, spear of cypress-wood","forms":["cyparissī","Cyparissus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Cyparissus}} fōrmōsissimus adulēscēns fuit, quī ab Apolline dīligēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"cyprius","latin":"Cyprius, Cypria, Cyprium","headword":"Cyprius","letter":"c","pos":"adjective","posGroup":"adjective","english":"Cyprian, of/belonging to Cyprus; (island); of Cyprian copper","forms":["Cyprium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ex tantō tumultū cum sē domum reciperet pervēnissetque ad summum {{Cyprium}} vīcum, restitit pavidus is quī iūmenta agēbat iacentemque dominae Servium trucīdātum ostendit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"cyprum","latin":"cyprum, cypri","headword":"cyprum","letter":"c","pos":"noun (n.)","posGroup":"noun","english":"Cyprian copper","forms":["Cyprum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Spectāte īnsulās: Siciliam, Sardiniam, Corsicam, Crētam, {{Cyprum}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cyprus","latin":"Cyprus, -ī","headword":"Cyprus","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Cyprus (island sacred to Venus)","forms":["Cyprī","Cyprus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Est ager in parte optimā īnsulae Cyprī, quae est sacra deae Venerī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"cytherea","latin":"Cytherea, Cythereae","headword":"Cytherea","letter":"c","pos":"noun (f.)","posGroup":"noun","english":"Cytherea; (epithet of Venus, from island Cythera)","forms":["Cythērea"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At {{Cythērea}} novās artēs, nova pectore versat\ncōnsilia, ut faciem mūtātus et ōra Cupīdō\nprō dulcī Ascanīō veniat, dōnīsque furēntem\nincendat rēgīnam atque ossibus implicet ignem.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dactylus","latin":"dactylus, -ī","headword":"dactylus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dactyl","forms":["dactylus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: iambus u —, trochaeus — u, anapaestus u u —, {{dactylus}} — u u, spondēus — —, tribrachys u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"daedalus","latin":"Daedalus","headword":"Daedalus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Daedalus, the craftsman","forms":["Daedalī","Daedalō","Daedalum","Daedalus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Labyrinthus ille, in quō Mīnōtaurus inclūsus tenēbātur, ā Daedalō, virō Athēniēnsī, aedificātus erat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"dama","latin":"dama, damae","headword":"dama","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"fallow/red-deer; small member of deer family; gazelle/antelope; doe; slave name","forms":["Dāma"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"@�> (palma) caryôta, thébaica: duo genera palmārum (ﬁﬁctuum) ūberibus im-minēre : nūtrīrī vivîs sêcum ferendus datur al-ligâre: fasciîs alligātus : cui fasciae ligâtae erant ad numerum : ad symphôniam laecasïn (ÂatKâÇstv), verbum pectus pulsāre (ob lūctum), [Sermô convîvärum: {{Dāma}} dëﬁîgore, Seleucus dêfünere] Ab hôc ferculô Trimalchiô ad lasanum surrēxit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"damnare","latin":"(damnō) damnāre","headword":"damnāre","letter":"d","pos":"verb","posGroup":"verb","english":"condemn, sentence; to condemn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"damnatus","latin":"damnatus, damnata -um, damnatior -or -us, damnatissimus -a -um","headword":"damnatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"condemned; found guilty; reprobate (L+S); criminal; hateful, wretched; damned","forms":["damnātī","damnātus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mīdās {{damnātus}} in ūnā parte corporis aurēs asellī gerit, quamquam cēterae partēs sunt hominis.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"damno","latin":"damno, damnare, damnavi, damnatus","headword":"damno","letter":"d","pos":"verb","posGroup":"verb","english":"pass/pronounce judgment, find guilty; deliver/condemn/sentence; harm/damn/doom","forms":["damnātīs","damnāverat","damnavit","damnent","damnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"IOsaphātus tamen cum Achabō Isrāēlītārum rēge impiō amīcitiam iūnxit, quae rēs illī magnō damnō fuit: nam, coniuncfīs cōpiīs, pugnārunt adversus rēgem Syriae: in proeliō Achabus interfectus est, parumque āfuit quīn perīret et ipse IOsaphātus, nec sine auxiliō dīvīnō incolumīs ēvāsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"damnosus","latin":"damnōsus, -a, -um","headword":"damnōsus","letter":"d","pos":"adjective","posGroup":"adjective","english":"ruinous","forms":["damnōsā","damnōsī","damnōsum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Manibus ad caelum tentīs, hōc modō ōrat: \"Dā veniam, pater benignē, peccāvimus, sed remitte {{damnōsum}} dōnum.\" Bacchus benignus inquit: \"Ī ad flūmen vīcīnum Sardibus et carpe viam in montēs Lydiae ūsque ad ortum flūminis.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"damnum","latin":"damnum, -ī","headword":"damnum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"loss","forms":["damna","damnī","damnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita indignātiō patris et {{damnum}} mihi ēvenient prō eius benevolentia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"daniel","latin":"Daniel, Danielis","headword":"Daniel","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Daniel; prophet Daniel; book of Old Testament","forms":["Daniēl"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Inter capfīvōs, quī B abylōnem abducfī erant, delecfī sunt puerī eximia rorma: {{Daniēl}}, Ananīās, Misael et Azāriās: hī cum aliīs mulfīs in ipsā rēgiā ēducābantur, ut posteā ad mēnsam rēgis cōnsisterent, eīque accumbenfī ministrārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dapes","latin":"dapēs, -um (f. pl.)","headword":"dapēs","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"feast, meal, food; feast, rich food","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"daphne","latin":"Daphnē, -ēs","headword":"Daphnē","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"Daphne (a nymph)","forms":["Daphnē","Daphnēs","Daphnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Daphnē, fīlia Pēnēī, quī deus cuiusdam flūminis erat, prīmus amor fuit Apollinis; quī tamen, etiam sī puellae cupiditāte ferē cōnsūmēbātur, ab eā ut amārētur efficere nōn poterat: namque puella eum ōderat atque fugiēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"daps","latin":"daps, dapis","headword":"daps","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"sacrificial feast/meal; feast, banquet; food composing it; food/meal of animals","forms":["dapēs","dapibus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nēve domī praesūme {{dapēs}}, sed dēsine citrā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"dardanius","latin":"Dardanius, Dardania, Dardanium","headword":"Dardanius","letter":"d","pos":"adjective","posGroup":"adjective","english":"Dardanian, Trojan; of/pertaining to Dardanus (ancestor of Trojans)","forms":["Dardaniā","Dardaniae","Dardaniō","Dardaniōs","Dardanium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīs licet īnfestus sociīs rēgīque mihique, dūre Philoctēte, licet exsecrēre meumque dēvoveās sine fīne caput cupiāsque dolentī mē tibi forte darī nostrumque haurīre cruōrem, tē tamen adgrediar mēcumque redūcere nītar tamque tuīs potiar (faveat Fortūna) sagittīs, quam sum Dardaniō, quem cēpī, vāte potītus, quam respōnsa deum Trōiānaque fāta retēxī, quam rapuī Phrygiae signum penetrāle Minervae hostibus ē mediīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dardanus","latin":"Dardanus, Dardani","headword":"Dardanus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Dardanus; (ancestor of Trojans, son of Jupiter and Electra)","forms":["Dardanōs","Dardanus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quōs cum flentēs cerneret, et ipse illacrimāsse dīcitur sortī hūmānae, quod quī paulō ante nōn contentus rēgnō Macedoniae {{Dardanōs}} Illyriōsque oppugnāsset, is tum āmissō exercitū, extorris rēgnō, in parvam īnsulam compulsus, supplex, fānī religiōne, nōn vīribus suīs tūtus esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dares","latin":"Dares, Daris","headword":"Dares","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Dares; (Trojan boxer, defeated by Entellus)","forms":["darēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Vīdī, puduitque vidēre, cum tū terga {{darēs}} inhonestaque vēla parārēs; nec mora “quid facitis?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dat","latin":"dat, dant","headword":"dat","letter":"d","pos":"verb","posGroup":"verb","english":"give; gives","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"dativus","latin":"datīvus, -ī (cāsus)","headword":"datīvus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dative","forms":["dativus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: 'Nōminātīvus, genetīvus, {{dativus}}, accūsātīvus, vocātīvus, ablātīvus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"dato","latin":"dato, datare, datavi, datatus","headword":"dato","letter":"d","pos":"verb","posGroup":"verb","english":"be in habit of giving; make a practice of giving; give away, administer (L+S)","forms":["datās","dato"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum, collaudatis Carnutibus, {{dato}} iure iurando ab omnibus qui aderant, tempore eius rei constituto ab concilio disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dator","latin":"dator, datoris","headword":"dator","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"giver, donor, patron; slave who hands the ball to the player (L+S)","forms":["dator"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Adsit laetitiae Bacchus {{dator}}, et bona Iūnō;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"datum","latin":"datum, dati","headword":"datum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"present/gift; that which is given; debit; [~ dandis => w/all supplied]","forms":["data","datī","datum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aristium, tribunum militum, iter ad legionem facientem fide {{data}} ex oppido Cabillono educunt; idem facere cogunt eos qui negotiandi causa ibi constiterant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"datus","latin":"datus, datus","headword":"datus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"act of giving","forms":["datus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posteā, cum pater eī, Fabius Maximus, lēgātus {{datus}} fuisset, et Samnītās vīcit et plūrima ipsōrum oppida cēpit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"david","latin":"David, undeclined","headword":"David","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"David","forms":["Dāvīd","Davidem","Davidī","Davidis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quam ob causam reiectus est ā Deō, et in eius locum {{Dāvīd}}, adhūc iuvenis, ē tribū Iūdae ēlēctus est, et ā Samūēle ūnctus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"de","latin":"dē","headword":"dē","letter":"d","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) (down) from, of, about; about, concerning; down from (+ ablative)","forms":["de"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ibi cognoscit {{de}} Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"de/ex improviso","latin":"dē/ex imprōvīsō","headword":"dē/ex imprōvīsō","letter":"d","pos":"","posGroup":"other","english":"unexpectedly, suddenly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dea","latin":"dea, -ae","headword":"dea","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"goddess","forms":["dea","deābus","deae","deam","deārum","deās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Sciō multās domōs Tūsculānās et māiōrēs et meliōrēs esse quam nostram atque columnīs et signīs pulchriōribus ōrnārī, nec tamen haec domus mihi vidētur minus pulchra esse. rēs pulchra (esse) Domūs hominum dīvitum signīs {{deārum}} magnificīs ōrnantur — domus mea fēminā ōrnātur optimā et pulcherrimā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"deambulo","latin":"deambulo, deambulare, deambulavi, deambulatus","headword":"deambulo","letter":"d","pos":"verb","posGroup":"verb","english":"take a walk, go for a walk; walk abroad (L+S); walk much; promenade","forms":["dēambulābat","dēambulantem","deambulāre","dēambulātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Caīnus nōn pāruit Deō monentī; dissimulāns īram, dīxit frātrī suō: Age, eāmus {{dēambulātum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"debellare","latin":"(dēbellō) dēbellāre","headword":"dēbellāre","letter":"d","pos":"","posGroup":"other","english":"finish the war, subdue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"debello","latin":"debello, debellare, debellavi, debellatus","headword":"debello","letter":"d","pos":"verb","posGroup":"verb","english":"fight out/to a finish; bring a battle/war to an end; vanquish, subdue","forms":["dēbellāre","dēbellāverat","dēbellāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hae tibi erunt artēs: pācīque impōnere mōrem, parcere subiectīs et {{dēbellāre}} superbōs.' Cumīs profectus Aenēās prīmum portum Caiētae petīvit, deinde ventīs secundīs ad ōstium Tiberīnum advectus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"debeo","latin":"dēbeō, dēbēre","headword":"dēbeō","letter":"d","pos":"verb","posGroup":"verb","english":"owe, ought; ought, owe, should","forms":["dēbeat","dēbeātur","dēbēbant","dēbēbat","dēbēbimus","debēbit","dēbēbunt","dēbēmus","dēbent","dēbentur","dēbeō","debere","dēbērent","dēbēs","dēbet","debētis","dēbētur","dēbita","dēbitam","dēbitās","dēbuerant","Debuerās","dēbuistī","dēbuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari {{debere}}, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"debere","latin":"(dēbeō) dēbēre, dēbuisse, dēbitum","headword":"dēbēre","letter":"d","pos":"verb","posGroup":"verb","english":"owe, ought; to owe; ought","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"debet","latin":"dēbet","headword":"dēbet","letter":"d","pos":"verb","posGroup":"verb","english":"owes","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"debilis","latin":"dēbilis, -e","headword":"dēbilis","letter":"d","pos":"adjective","posGroup":"adjective","english":"weak; weak, feeble","forms":["dēbilem","dēbilēs","dēbili","dēbilis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At quamquam iī ad horrendam necem missī erant, Hippomenēs sine timōre mortis in cōnspectum puellae venit et “Cūr” inquit “facilem glōriam quaeris vincendō {{dēbilēs}} virōs?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"debilitare","latin":"(dēbilitō) dēbilitāre","headword":"dēbilitāre","letter":"d","pos":"","posGroup":"other","english":"weaken","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"debilito","latin":"debilito, debilitare, debilitavi, debilitatus","headword":"debilito","letter":"d","pos":"verb","posGroup":"verb","english":"weaken/disable/incapacitate/impair/maim/lame/cripple; deprive of power (to act)","forms":["dēbilitātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod nisi domī cīvium suōrum invidiā {{dēbilitātus}} esset, Rōmānōs vidētur superāre potuisse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"debitum","latin":"debitum, debiti","headword":"debitum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"debt/what is owed; (his) due; duty; that due/ought to occur; [w/voli => by vow]","forms":["dēbitum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ananīās, Misael et Azāriās morī māluērunt, quam honōrem, soll Deō {{dēbitum}}, statuae dēferre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decedo","latin":"decedo, decedere, decessi, decessus","headword":"decedo","letter":"d","pos":"verb","posGroup":"verb","english":"withdraw/retire, go off/away, depart, leave; relinquish/cease; desert/abandon","forms":["dēcēdēns","dēcēdere","dēcēderent","dēcēdite","dēcesserat","dēcessēre","dēcesserō","dēcessisse","dēcessisset","dēcessit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum ex hāc vītā dēcesserō, sepelī corpus meum; mātrem tuam colitō, memor malōrum quae passa est, cum tē in uterō gestāret, et cum ipsā suprēmum diem obierit, eam pōnitō mēcum in eōdem sepulcrō.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decem","latin":"decem","headword":"decem","letter":"d","pos":"numeral","posGroup":"numeral","english":"ten","forms":["decem","deciēs","decimae","dēnās","Dēnī","dēnīs","dēnōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Placuit ut Litaviccus {{decem}} illis milibus quae Caesari ad bellum mitterentur praeficeretur atque ea ducenda curaret, fratresque eius ad Caesarem praecurrerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"december","latin":"December, Decembris","headword":"December","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"December; (the 10th month of the old calender, 12th/last month after Caesar)","forms":["December","Decembrēs","Decembrī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; {{December}}, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"decemvir","latin":"decemvir, decemviri","headword":"decemvir","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"decemvir, one of ten men; (commission of ten, board with consular powers)","forms":["decemvirī","decemvirīs","decemvirō","decemvirōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Annō trecentēsimō et alterō ab urbe conditā imperium cōnsulāre cessāvit et prō duōbus cōnsulibus decem factī sunt quī summam potestātem habērent, 'decemvirī' nōminātī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"decens","latin":"decens, decentis (gen.), decentior -or -us, decentissimus -a -um","headword":"decens","letter":"d","pos":"adjective","posGroup":"adjective","english":"appropriate, decent/seemly/becoming, in approved standard; pleasing/graceful","forms":["decēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{decēns}} -entis adī (part «€ decēre):","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decenter","latin":"decenter, decentius, decentissime","headword":"decenter","letter":"d","pos":"adverb","posGroup":"adverb","english":"appropriately/decently, with good taste; becomingly, pleasingly, gracefully","forms":["decenter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"puellae discunt lacrimàre {{decenter}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"deceptus","latin":"deceptus, deceptus","headword":"deceptus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"deception","forms":["dēceptūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Pāsīphae et taurus {{dēceptūs}}]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decernere","latin":"(dēcernō) dēcernere (< cernere)","headword":"dēcernere","letter":"d","pos":"","posGroup":"other","english":"decide, settle, fight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"decerno","latin":"decerno, decernere, decrevi, decretus","headword":"decerno","letter":"d","pos":"verb","posGroup":"verb","english":"decide/settle/determine/resolve; decree/declare/ordain; judge; vote for/contend","forms":["dēcernēbat","dēcernere","dēcernī","dēcernit","dēcernitur","dēcernō","decernunt","dēcernuntur","dēcrētae","dēcrētūrī","dēcrētus","DECRETVS","dēcrēverat","dēcrēvēre","dēcrēverit","dēcrēvērunt","dēcrēvistis","dēcrēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Interim nuntio allato omnes eorum milites in potestate Caesaris teneri, concurrunt ad Aristium; nihil publico factum consilio demonstrant; quaestionem de bonis direptis {{decernunt}}, Litavicci fratrumque bona publicant, legatos ad Caesarem sui purgandi gratia mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"decerpo","latin":"decerpo, decerpere, decerpsi, decerptus","headword":"decerpo","letter":"d","pos":"verb","posGroup":"verb","english":"pluck, pull/tear/snip off, pick; cull; reap/procure/gather; catch/snatch; remove","forms":["dēcerpsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulier, dēcepta hīs verbīs, {{dēcerpsit}} frūctum et comēdit; deinde obtulit virō, quī pariter comēdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decerto","latin":"decerto, decertare, decertavi, decertatus","headword":"decerto","letter":"d","pos":"verb","posGroup":"verb","english":"fight (issue out/to the finish); contend/dispute/argue; struggle/compete over","forms":["decertare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quid hominum milibus LXXX uno loco interfectis propinquis consanguineisque nostris animi fore existimatis, si paene in ipsis cadaveribus proelio {{decertare}} cogentur?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"decet","latin":"decet, decēre","headword":"decet","letter":"d","pos":"verb","posGroup":"verb","english":"(impersonal) be fitting, proper","forms":["deceat","decēbant","decēbat","decēbit","decent","decēre","deceret","decet","decuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At Dōrippa “Dōnum vēndere” inquit “nōn {{decet}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"decido","latin":"decido, decidere, decidi, decisus","headword":"decido","letter":"d","pos":"verb","posGroup":"verb","english":"detach, cut off/out/down; fell; cut/notch/carve to delineate; flog thoroughly","forms":["dēcidēbant","dēciderit","dēcidit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hēlī, audītō tantae clādis nūntiō, ē sellā {{dēcidit}}, et frāctā cervīce mortuus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decies","latin":"deciēs","headword":"deciēs","letter":"d","pos":"","posGroup":"other","english":"ten times","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"decima","latin":"decima, decimae","headword":"decima","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"tithe; tenth part; (offering/tax/largesse); tax/right to collect 10%; 10th hour","forms":["decima"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed intolerantius Gallos insequentes legio {{decima}} tardavit, quae pro subsidio paulo aequiore loco constiterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"decimo","latin":"decimo, decimare, decimavi, decimatus","headword":"decimo","letter":"d","pos":"verb","posGroup":"verb","english":"choose by lot every tenth man (for punishment); make tithe offering (to a god)","forms":["decimō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dīē quīntō decimō post lūnam novam lūna plēna est et fōrmam habet litterae Ō.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"decimum","latin":"decimum","headword":"decimum","letter":"d","pos":"adverb","posGroup":"adverb","english":"for the tenth time","forms":["decimum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum vērō ad sextum et {{decimum}} annum Andromeda pervēnisset, eius māter, interrogāta quid dē tam pulchra fīlia sentīret, sine morā respondit sē certō scīre nē Nereidās quidem tantā pulchritūdine ōrnātās esse.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"decimus","latin":"decimus, -a, -um","headword":"decimus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"tenth","forms":["decimus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Exit Sextus. duo-{{decimus}} -a -um","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"decipere","latin":"(dēcipō) dēcipere (< capere)","headword":"dēcipere","letter":"d","pos":"","posGroup":"other","english":"deceive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"decipio","latin":"dēcipiō, -ere, -cēpī, -ceptum","headword":"dēcipiō","letter":"d","pos":"verb","posGroup":"verb","english":"deceive; deceive, trick; to deceive, cheat","forms":["dēcēperat","dēcēpēre","dēcēpisse","dēcēpistī","dēcēpit","dēcepta","dēceptae","dēceptam","DECEPTO","dēceptōs","dēceptum","dēcipiam","dēcipiat","dēcipienda","dēcipit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mulier, {{dēcepta}} hīs verbīs, dēcerpsit frūctum et comēdit; deinde obtulit virō, quī pariter comēdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"declamitare","latin":"(dēclāmitō) dēclāmitāre","headword":"dēclāmitāre","letter":"d","pos":"verb","posGroup":"verb","english":"make practice speeches; to practise declamation","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"declamito","latin":"declamito, declamitare, declamitavi, declamitatus","headword":"declamito","letter":"d","pos":"verb","posGroup":"verb","english":"declaim (oratoric exercise) continually/habitually; practice rhetoric; bluster","forms":["dēclāmitāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Commentābar {{dēclāmitāns}} — sīc enim nunc loquimur — idque faciēbam multum etiam Latīnē, sed Graecē saepius, vel quod Graeca ōrātiō plūra ōrnāmenta suppeditāns cōnsuētūdinem similiter Latīnē dīcendī afferēbat, vel quod ā Graecīs summīs doctōribus, Graecē dīcerem, neque corrigī possem neque docērī.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"declamo","latin":"declamo, declamare, declamavi, declamatus","headword":"declamo","letter":"d","pos":"verb","posGroup":"verb","english":"declaim, make speeches (usu. as an oratorical exercise); bluster/bawl (L+S)","forms":["dēclāmat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"465 Quis, nisi mentis inops, tenerae {{dēclāmat}} amīcae?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"declarare","latin":"(dēclārō) dēclārāre","headword":"dēclārāre","letter":"d","pos":"","posGroup":"other","english":"show, declare, express","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"declaro","latin":"declaro, declarare, declaravi, declaratus","headword":"declaro","letter":"d","pos":"verb","posGroup":"verb","english":"declare/announce/make known; indicate, reveal, testify, show/prove; mean (word)","forms":["dēclārant","dēclārantur","dēclārat","dēclārātī","dēclārātus","dēclārāvisse","dēclārāvit","dēclārēs","dēclārētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illōrum narū maximus {{dēclārāvit}} sē suōsque frātrēs p arātōs esse morī, magis quam culpam committere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"declinare","latin":"dēclīnāre","headword":"dēclīnāre","letter":"d","pos":"verb","posGroup":"verb","english":"to decline, inflect","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"declinat","latin":"dēclīnat, -ant","headword":"dēclīnat","letter":"d","pos":"","posGroup":"other","english":"decline, inflect","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"declinatio","latin":"dēclīnātiō, dēclīnātiōnis","headword":"dēclīnātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"(f.) declension","forms":["dēclīnātiōne","dēclīnātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quārē lanceā cōnfodere cōnātus est, sed Dāvīd ictum lētālem {{dēclīnātiōne}} corporis effūgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"declino","latin":"declino, declinare, declinavi, declinatus","headword":"declino","letter":"d","pos":"verb","posGroup":"verb","english":"deflect/divert/turnaside/swerve/change direction/deviate/dodge; digress/diverge","forms":["declinandī","dēclīnantur","dēclīnat","Dēclīnāvī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ex IŪdaeīs multī patriam dēseruērunt, declinandī periculī causā; multī mortem oppefīvērunt, potius quam ā lēge dīvīnā discēderent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"declive","latin":"declive, declivis","headword":"declive","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"slope, declivity; surface sloping downwards; [per decline => downwards]","forms":["declivi","declivia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Erat a septentrionibus collis, quem propter magnitudinem circuitus opere circumplecti non potuerant nostri; necessario paene iniquo loco et leniter {{declivi}} castra fecerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"declivitas","latin":"declivitas, declivitatis","headword":"declivitas","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"declivity, slope, descent; tendency to slope down; falling gradient","forms":["declivitatem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Iniquum loci ad {{declivitatem}} fastigium magnum habet momentum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"decollo","latin":"decollo, decollare, decollavi, decollatus","headword":"decollo","letter":"d","pos":"verb","posGroup":"verb","english":"behead, cause to be beheaded; remove from the neck (according to Nonius); rob","forms":["dēcollātī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Saturnīnus prōcōnsul per praecōnem dīcī iussit: “Spērātum, Nartzālum, Cittīnum, Veturium, Fēlīcem, Aquīlīnum, Laetantium, Iānuāriam, Generōsam, Vestiam, Dōnātam, Secundam dūcī iussī.” Ūniversī dīxērunt: “Deō grātiās!” Et statim dēcollātī sunt prō nōmine Christī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"decolor","latin":"decolor, (gen.), decoloris","headword":"decolor","letter":"d","pos":"adjective","posGroup":"adjective","english":"discolored; not normal color; (dark people); stained/faded; degenerate/depraved","forms":["dēcōlor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dolor -orisadī- mütitócolore, — QuŌs lēgit in viridī {{dēcōlor}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decor","latin":"dēcor, -ōris (m.)","headword":"dēcor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"beauty, grace","forms":["decor","decōrem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"(Mīrābātur Achillēs enim.) “Nec haec cassis quam vidēs neque scūtum, onus sinistrae, auxiliō mihi sunt; {{decor}} est quaesītus ab istīs; Mars quoque ob hoc capere arma solet! [Sī] removēbitur huius tegminis officium, tamen indestrictus abībō; est aliquid nōn esse nātum Nērēide, sed quī Nēreaque et nātās et tōtum temperat aequor.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"decorare","latin":"(decorō) decorāre","headword":"decorāre","letter":"d","pos":"verb","posGroup":"verb","english":"adorn, glorify; to adorn, decorate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"decore","latin":"decore","headword":"decore","letter":"d","pos":"adverb","posGroup":"adverb","english":"beautifully, in a pleasing manner; properly/suitably, in correct/seemly manner","forms":["decōre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"in ferrum flammāsque ruit positōque {{decōre}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decoris","latin":"decoris, decoris, decore","headword":"decoris","letter":"d","pos":"adjective","posGroup":"adjective","english":"beautiful; pleasing to the senses","forms":["decōris"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"litàs tantum {{decōris}} habet","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decoro","latin":"decoro, decorare, decoravi, decoratus","headword":"decoro","letter":"d","pos":"verb","posGroup":"verb","english":"adorn/grace, embellish/add beauty to; glorify, honor/add honor to; do credit to","forms":["decorat","decorātam","decorātum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sinistrā manū lyram gemmīs atque dentibus Indīs {{decorātam}}, dextrā manū plectrum tenuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"decorum","latin":"decorum, decori","headword":"decorum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"decorum, that which is suitable/seemly, propriety","forms":["decōrum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"terque quaterque manū pectus percussa {{decōrum}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"decorus","latin":"decōrus, -a, -um","headword":"decōrus","letter":"d","pos":"adjective","posGroup":"adjective","english":"becoming, fitting; handsome, comely","forms":["decōram"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ōs umerōsque deō similis; namque ipsa {{decōram}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"decresco","latin":"decresco, decrescere, decrevi, decretus","headword":"decresco","letter":"d","pos":"verb","posGroup":"verb","english":"decrease; abate; diminish, dwindle, shrink; (in number/amount); be subtracted","forms":["dēcrēscere","dēcrēscunt"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Simul atque grātus nūntius dē eā rē Rōmam pervēnit, pretium frūmentī {{dēcrēscere}} coeptum est; victīs enim praedōnibus, nautae sine metū per maria, quae omnium gentium commūnia sunt, nāvigābant.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"decretum","latin":"dēcrētum, -ī (< cernere)","headword":"dēcrētum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"resolution, decree","forms":["dēcrēta","dēcrētī","dēcrētīs","dēcrētō","dēcrētum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec longē aberrāvit suspîciô mea: in vicem enim poenae vënit {{dēcrētum}} Trimalchiônis quô puerum iussit lîberum esse, ‘né quis posset dîcere tantum virum esse ā servô vulnerātum! ’ Comprobāmus nôs factum, et ‘quam in praecipitî rēs 55 hūmānae essent’ variô sermône gan-îmus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"decuma","latin":"decuma, -ae","headword":"decuma","letter":"d","pos":"","posGroup":"other","english":"tithe, tenth part","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"decuria","latin":"decuria, decuriae","headword":"decuria","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"group/division of ten; class, social club; gang; cavalry squad; ten judges/feet","forms":["decuriā","decuriam","decuriās","DECVRĪĪS"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Continuôque cocum vocârî iussit et, nôn expectātā ëlëctiône nostIā, mäximum nātū iussit occîdî; et clārä vôce: “Ex quotā decuriā es?” Cum ille ‘sē ex quadrägësimâ’ respqndisset, “Ëmptî- cius an” inquit “domī nātus?” “Neutrum” inquit cocus, “sed testâmentô Pānsae tibi “Vidé ergô” ait “ut dîligenter pônäs!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"decurio","latin":"decurio, decurionis","headword":"decurio","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"decurion, officer commanding a decuria (calavry squad); (also naval); foreman","forms":["decuriō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et cum factum esset sfaō, venit IOseph ab Arimathaea, nōbilis decuriō, ad Pīlātum et pefīvit corpus Iēsu.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decuris","latin":"decuris, decuris","headword":"decuris","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"member of municipal senate/governing committee of decuria; councillor","forms":["decuri"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"monumentîs înscrîbitur né tribūnal: cum sēde magisträ- tūs (praetôris, aedîlis, cét.) cicarô : servulus dîlêctus licet sculpere (: volô té s.) quod sibi assûmpsit Trimal- cum posset : etsî poterat {{decuri}}îs: magistrâtuum mī- nistrî lïbertînî in decuriās ex parvô : ex parvīs rébus sēstertium Irecentiês centêna et tū (quī haec Iegis) valē’!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"decurrere","latin":"(dēcurrō) dēcurrere (< currere)","headword":"dēcurrere","letter":"d","pos":"","posGroup":"other","english":"run down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"decurro","latin":"decurro, decurrere, decucurri, decursus","headword":"decurro","letter":"d","pos":"verb","posGroup":"verb","english":"run/hurry/rush/flow/slope down; hasten; travel downstream; come to land/end","forms":["dēcucurrērunt","dēcurrēns","dēcurrerat","dēcurrēre","dēcurrī","dēcurrit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Et ipse āvulsus ē s t ab iīs quantum ē s t ī āctus lapidī s: et posifīs genibus, ōrābat dīcēns:\"Pater, sī vīs, trānsfer calicem istum ā mē; vērumtamen nōn mea voluntās, sed tua fīat.\"Et ecce sūdor eius, sīcut guttae sanguinis, {{dēcurrit}} in terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decus","latin":"decus, -oris (n.)","headword":"decus","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"honor, ornament; honour, glory, ornament","forms":["dēc","decora","decōrī","decus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"— nec dūbītó quīn sē, stultā, {{dēc}}érē putet!\"","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"decusso","latin":"decusso, decussare, decussavi, decussatus","headword":"decusso","letter":"d","pos":"verb","posGroup":"verb","english":"arrange crosswise; mark with a cross; divide crosswise (in form of X) (L+S)","forms":["decussāns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At Iacobus {{decussāns}} manūs dextram imposuit Ephraīmō, sinistram autem Manassī, et utrīque simul bene precātus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"decutere","latin":"(dēcutiō) dēcutere, -ssisse, -ssum","headword":"dēcutere","letter":"d","pos":"verb","posGroup":"verb","english":"knock off, shake off; to strike off, knock down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"decutio","latin":"decutio, decutere, decussi, decussus","headword":"decutio","letter":"d","pos":"verb","posGroup":"verb","english":"shake/strike/knock/force down/off/aside (from upright); dislodge; overturn","forms":["dēcussisse"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi inambulāns tacitus summa papāverum capita dīcitur baculō {{dēcussisse}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dedecus","latin":"dēdecus, -oris (n.)","headword":"dēdecus","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"disgrace, dishonor; disgrace, shame","forms":["dēdecōre","dēdecoris","dēdecus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae vōs dēmentia” dīxī “concitat, ō sociī, captam dīmittere Trōiam, quidque domum fertis decimō, nisi {{dēdecus}}, annō?”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dedere","latin":"(dēdō) dēdere (< dare)","headword":"dēdere","letter":"d","pos":"","posGroup":"other","english":"give up, devote","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dedicare","latin":"(dēdicō) dēdicāre","headword":"dēdicāre","letter":"d","pos":"","posGroup":"other","english":"dedicate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dedicatio","latin":"dedicatio, dedicationis","headword":"dedicatio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dedication, consecration, ceremonial opening; act/rite conferring sanctity","forms":["dēdicātiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iildās omnia pūrgāvit, portās refēcit, novum altāre ērēxit, cuius dēdicātiō magna tofius populī frequentiā, clangentibus tubīs, facta est; dēcrētumque, ad memoriam reī sempitēmam, quotannīs diem sollemnem celebrātum In.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dedicatus","latin":"dedicatus, dedicata -um, dedicatior -or -us, dedicatissimus -a -um","headword":"dedicatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"devoted; dedicated","forms":["dēdicāta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"mūnera (ut theātrum) {{dēdicāta}} erant","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"dedico","latin":"dedico, dedicare, dedicavi, dedicatus","headword":"dedico","letter":"d","pos":"verb","posGroup":"verb","english":"declare/proclaim; census return; dedicate/consecrate; devote/apply/commit (to)","forms":["dēdicātum","dēdicāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Magnum quidem opus fuit, neque brevī tempore perfectum est, nam quadrāgintā dēnique annīs post Caesar Octāviānus Augustus, quō cognōmine tum appellābātur, magnificum illud monumentum victōriae suae Martī {{dēdicāvit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dedignor","latin":"dedignor, dedignari, dedignatus sum","headword":"dedignor","letter":"d","pos":"verb","posGroup":"verb","english":"disdain; refuse (scornfully), reject with scorn, spurn; feel contempt for","forms":["dēdignāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quōs ego sim totiēns iam {{dēdignāta}} marītōs?","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"dedisco","latin":"dedisco, dediscere, dedidici, -","headword":"dedisco","letter":"d","pos":"verb","posGroup":"verb","english":"unlearn, forget, put out of one's mind; lose the habit of, forget (how to)","forms":["dēdiscit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"quī quod didicit id {{dēdiscit}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"deditio","latin":"dēditiō, -ōnis ( f.)","headword":"dēditiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"surrender, capitulation","forms":["deditione","deditionem","deditionis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de {{deditione}}, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deditus","latin":"deditus, dedita -um, deditior -or -us, deditissimus -a -um","headword":"deditus","letter":"d","pos":"adjective","posGroup":"adjective","english":"devoted/attached to, fond of; devoted/directed/given over (to) (activity)","forms":["dēdita","dēditam","dēditī","dēditus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cui successit IOsiās, vir sānctus et religiōsus, quī ā puerō virtūfi {{dēditus}}, populum ad lēgitimum cultum revocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dedo","latin":"dedo, dedere, dedidi, deditus","headword":"dedo","letter":"d","pos":"verb","posGroup":"verb","english":"give up/in, surrender; abandon/consign/devote (to); yield, hand/deliver over","forms":["dedant","dēde","dēdentēs","dēdere","dederent","dēderet","dēderētis","dēderētur","dediderunt","dēdidisset","dēditum","deditur","dēduntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus profligatis, rursus oppidani perterriti comprehensos eos quorum opera plebem concitatam existimabant ad Caesarem perduxerunt seseque ei {{dediderunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deducere","latin":"(dēdūcō) dēdūcere (< dūcere)","headword":"dēdūcere","letter":"d","pos":"verb","posGroup":"verb","english":"lead/bring down, launch; to lead down, draw off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"deduco","latin":"deduco, deducere, deduxi, deductus","headword":"deduco","letter":"d","pos":"verb","posGroup":"verb","english":"lead/draw//pull/bring/stretch down/away/out/off; escort; eject/evict (claimant)","forms":["dēdūcam","dēdūcendīs","deducendos","deducere","dēdūcerent","dēdūcerentur","dēdūcerētur","dēdūcet","deducit","dēdūcitur","dēdūcunt","dēdūcuntur","deduxerat","deduxi","deduxisset","dēdūxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum {{deducere}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deductus","latin":"deductus, deducta -um, deductior -or -us, deductissimus -a -um","headword":"deductus","letter":"d","pos":"adjective","posGroup":"adjective","english":"drawn down; bent in; attenuated/slender, weak, soft (voice); fine-spun (style)","forms":["deducta","deductas","dēductī","deductis","deductos","dēductus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio {{deductis}}, cum se vel principes eius consili fore profiterentur, ratio perficiendi quaerebatur, quod civitatem temere ad suscipiendum bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deerro","latin":"deerro, deerrare, deerravi, deerratus","headword":"deerro","letter":"d","pos":"verb","posGroup":"verb","english":"go astray, wander off; miss, stray from target/goal; err/make a mistake/go wrong","forms":["deerrāre"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"I Cum patre ut abiī Tarentum ad mercātum; posteā inter hominēs mē {{deerrāre}} ā patre atque inde āvehī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"deesse","latin":"deesse","headword":"deesse","letter":"d","pos":"verb","posGroup":"verb","english":"to fail, be lacking (+ dat.); to be absent, be lacking, be missing","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"defatigo","latin":"defatigo, defatigare, defatigavi, defatigatus","headword":"defatigo","letter":"d","pos":"verb","posGroup":"verb","english":"tire (out), exhaust; break force of; (PASS) lose heart, weary, be discouraged","forms":["defatigarent","defatigati","defatigatis","dēfātīgātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri defessis succederent nostrosque assiduo labore {{defatigarent}}, quibus propter magnitudinem castrorum perpetuo esset isdem in vallo permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defectio","latin":"defectio, defectionis","headword":"defectio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"desertion/revolt/defection; failure/deficiency; ellipsis (grammar); eclipse","forms":["defectione","defectionem","defectionis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ipse maiorem Galliae motum exspectans, ne ab omnibus civitatibus circumsisteretur, consilia inibat quem ad modum ab Gergovia discederet ac rursus omnem exercitum contraheret, ne profectio nata ab timore {{defectionis}} similis fugae videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defendere","latin":"(dēfēndō) dēfendere, -isse, -ēnsum","headword":"dēfendere","letter":"d","pos":"verb","posGroup":"verb","english":"defend, maintain; to defend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"defendit","latin":"dēfendit, dēfendere","headword":"dēfendit","letter":"d","pos":"verb","posGroup":"verb","english":"defend; defends","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"defendo","latin":"dēfendō","headword":"dēfendō","letter":"d","pos":"verb","posGroup":"verb","english":"to defend","forms":["dēfendam","dēfendant","dēfende","dēfendēbant","dēfendēbantur","dēfendenda","dēfendendam","defendendum","dēfendentī","dēfendere","dēfenderēmus","dēfenderent","dēfenderet","dēfenderētur","dēfenderit","dēfendet","defendi","dēfendisset","dēfendistis","defendit","dēfendite","dēfenditur","dēfendō","dēfendundum","dēfendunt","defensuros"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deliberatur de Avarico in communi concilio, incendi placeret an {{defendi}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defensa","latin":"defensa, defensae","headword":"defensa","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"defense","forms":["dēfēnsa"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Postquam bellum in Urbem nūntiātum est, Rōmānī exercitum parāvērunt ut Urbs, quae mūris et flūmine iam satis {{dēfēnsa}} eīs vidēbātur, etiam armīs dēfenderētur; via tamen hostibus patēbat, nam pōns super flūmen positus erat, per quem facile Rōmam intrāre poterant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"defensio","latin":"defensio, defensionis","headword":"defensio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"defense/protection; act of defending; argument/justification in defense, excuse","forms":["defensionem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et {{defensionem}} urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defensor","latin":"dēfēnsor, -ōris (m.)","headword":"dēfēnsor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"defender","forms":["dēfēnsor","dēfensōrem","dēfensōrēs","dēfēnsōribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Defensores}} oppido idonei deliguntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defensum","latin":"defensum, defensi","headword":"defensum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"defense; enclosure","forms":["dēfēnsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hinc invictus patriam {{dēfēnsum}} revocātus bellum gessit adversus P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"defero","latin":"defero, deferre, detuli, delatus","headword":"defero","letter":"d","pos":"verb","posGroup":"verb","english":"carry/bring/sink/fall down/off; convey/deliver/transfer; reduce/slope (down to)","forms":["dēfer","dēferantur","dēferēbantur","dēferre","dēferrem","deferrentur","dēferrētur","dēferrī","defert","Dēferte","defertur","dēferunt","dēferuntur","dēlāta","dēlātae","delati","dēlātum","dēlātus","dētulērunt","dētulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter sibi Senones, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui Oceanum attingunt adiungit; omnium consensu ad: eum {{defertur}} imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deferre","latin":"(dēferō) dēferre (< ferre)","headword":"dēferre","letter":"d","pos":"verb","posGroup":"verb","english":"carry, bring, report, confer, denounce; to carry down, drive off course","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"defervescere","latin":"(dēfervēscō) dēfervēscere","headword":"dēfervēscere","letter":"d","pos":"","posGroup":"other","english":"calm down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defervesco","latin":"defervesco, defervescere, deferbui, -","headword":"defervesco","letter":"d","pos":"verb","posGroup":"verb","english":"come to full boil; cease boiling, cool off (fermentation); calm down, subside","forms":["dēfervērat","dēfervēscat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē Rebecca māter, timēns dīlēctō fīliō suō: fuge, inquit, fīlī mī; abī ad Labānum avunculum tuum, et commorāre apud eum dōnec īra frātris tuī {{dēfervēscat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"defessus","latin":"dēfessus, -a, -um","headword":"dēfessus","letter":"d","pos":"adjective","posGroup":"adjective","english":"worn out, tired; tired, worn out, weary","forms":["defessi","defessis","dēfessum","dēfessus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri {{defessis}} succederent nostrosque assiduo labore defatigarent, quibus propter magnitudinem castrorum perpetuo esset isdem in vallo permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deficere","latin":"(dēficiō) dēficere (< facere)","headword":"dēficere","letter":"d","pos":"","posGroup":"other","english":"fail, sink, wane, defect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deficio","latin":"deficio, deficere, defeci, defectus","headword":"deficio","letter":"d","pos":"verb","posGroup":"verb","english":"fail/falter; run short/out; grow weak/faint; come to end; revolt/rebel, defect","forms":["defecerat","dēfēcerit","dēfēcērunt","dēfēcisse","dēfēcit","deficere","deficeret","dēficiēbant","dēficient","dēficiente","dēficientēs","deficiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia {{deficeret}}, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"defigere","latin":"(dēfīgō) dēfīgere (< fīgere)","headword":"dēfīgere","letter":"d","pos":"","posGroup":"other","english":"fix, thrust, paralyze","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defigo","latin":"defigo, defigere, defixi, defixus","headword":"defigo","letter":"d","pos":"verb","posGroup":"verb","english":"sink/bury/stick/thrust (weapon); fasten, fix, plant, embed; attach/affix","forms":["dēfīgere","dēfīgit","dēfīximus","dēfīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vīdit quīdam pendentem Absalōnem, nec ausus est illī manūs violentās īnferre, sed nūntiāvit Iōābō, quī eum increpāns: “Debuerās” inquit “iuvenem impium cōnfodere.” “Atquī” respondit ille “mē praesente, rēx praecēpit tibi, ut fīliō suō parcerēs.” “Ego vērō nōn parcam” ait Iōāb, et statim sūmpsit trēs lanceās, quās in pectus Absalōnis {{dēfīxit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"definio","latin":"definio, definire, definivi, definitus","headword":"definio","letter":"d","pos":"verb","posGroup":"verb","english":"define/bound/fix/limit/mark; restrict/confine; assign, ordain; lay down (rule)","forms":["dēfīnītum","definiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cognitis per exploratores regionibus, duces hostium LX milia ex omni numero deligunt earum civitatum quae maximam virtutis opinionem habebant, quid quoque pacto agi placeat occulte inter se constituunt, adeundi tempus {{definiunt}}, cum meridies esse videatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"definire","latin":"(dēfīniō) dēfīnīre (< finīre)","headword":"dēfīnīre","letter":"d","pos":"","posGroup":"other","english":"delimit","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defixus","latin":"defixus, defixa, defixum","headword":"defixus","letter":"d","pos":"adjective","posGroup":"adjective","english":"motionless, still","forms":["dēfīxa","dēfīxus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quam cum magis intuērer, 'Quaesō' inquit Āfricānus 'quōusque humī {{dēfīxa}} tua mēns erit?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deflecto","latin":"deflecto, deflectere, deflexi, deflexus","headword":"deflecto","letter":"d","pos":"verb","posGroup":"verb","english":"bend downwards; bend (bow); turn (aside), change course/direction of; deflect","forms":["dēflexit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"S ed IOiadā mortuō, aulicōrum adūlatione corruptus, ad vitia {{dēflexit}}, vēramque religiōnem dēseruit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"defleo","latin":"defleo, deflere, deflevi, defletus","headword":"defleo","letter":"d","pos":"verb","posGroup":"verb","english":"weep (abundantly) for; mourn loss of; express/feel sorrow about; lament/bewail","forms":["dēflendō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Haec tantō dicta animō magis cōnfūdēre audientium animōs quam sī miserābiliter orbitātem suam dēflendō locūtus esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deflere","latin":"(dēfleō) dēflēre (< flēre)","headword":"dēflēre","letter":"d","pos":"","posGroup":"other","english":"weep for","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defluo","latin":"defluo, defluere, defluxi, defluxus","headword":"defluo","letter":"d","pos":"verb","posGroup":"verb","english":"flow/glide/run down; descend/fall; flow/stream away; float/swim/row downstream","forms":["dēfluēbant","dēflūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Appropinquante arca, aquae, quae superne {{dēfluēbant}}, stetērunt īnstar mūrī; quae autem īnfrā, dēscendērunt, et alveum siccum relīquērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deforme","latin":"deforme, deformis","headword":"deforme","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"disgrace; shameful thing/deed","forms":["deforme"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus {{deforme}} non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deformis","latin":"dēfōrmis, -e","headword":"dēfōrmis","letter":"d","pos":"","posGroup":"other","english":"ugly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deformitas","latin":"dēfōrmitās, -tātis ( f.)","headword":"dēfōrmitās","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"deformity","forms":["dēfōrmitās","dēfōrmitāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neque hāc {{dēfōrmitāte}} reditūs mel tam Scīpiō exsultābit atque efferet sē quam Hannō, quī domum nostram, quandō aliā rē nōn potuit, ruīnā Carthāginis oppressit!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"defugere","latin":"(dēfugiō) dēfugere (< fugere)","headword":"dēfugere","letter":"d","pos":"","posGroup":"other","english":"escape, avoid","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defugio","latin":"defugio, defugere, defugi, -","headword":"defugio","letter":"d","pos":"verb","posGroup":"verb","english":"flee, escape, run/move away (from), make one's escape from; avoid (strongly)","forms":["dēfūgisse"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē et tibi, Pūblī, et pīīs omnibus retinendus animus est in custōdiā corporis nec iniussū eius ā quō ille est vōbīs datus ex hominum vītā migrandum est, nē mūnus hūmānum assignātum ā deō {{dēfūgisse}} videāminī.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"defunctus","latin":"defunctus, defuncti","headword":"defunctus","letter":"d","pos":"noun","posGroup":"noun","english":"dead person; (usu. male); the dead (pl.) (L+S)","forms":["dēfūnctam","dēfūnctī","Dēfūnctō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hinc Rōmānī, dēfūnctī nequīquam proeliō ūnō, omissīs Gallīs Hispānīsque, quōrum terga cecīderant, adversus Āfrōs integram pugnam ineunt, nōn inīquā tantum eō inīquā quod indūsī adversus circumfūsōs, sed etiam quod fessī cum recentibus pugnābant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"defungi","latin":"(dēfungor) dēfungī, dēfunctum","headword":"dēfungī","letter":"d","pos":"","posGroup":"other","english":"complete","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"defungor","latin":"defungor, defungi, defunctus sum","headword":"defungor","letter":"d","pos":"verb","posGroup":"verb","english":"have done with (ABL), finish, bring/come to end, be quit/done/rid of; discharge","forms":["dēfungī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et ille dēfungī proeliō festīnat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"degenero","latin":"degenero, degenerare, degeneravi, degeneratus","headword":"degenero","letter":"d","pos":"verb","posGroup":"verb","english":"be inferior to ancestors/unworthy; deteriorate/decline; lower oneself","forms":["dēgenerāre","dēgenerāvit","dēgenerēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iōsaphatō patrī successit Iōramus, quī ā patēmā pietāte {{dēgenerāvit}}: namque Athaliam impiī Achabī fīliam dūxit uxōrem, fuitque socerō quam patrī similior.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"degravo","latin":"degravo, degravare, -, degravatus","headword":"degravo","letter":"d","pos":"verb","posGroup":"verb","english":"weigh/press/drag down; rest heavily on; overpower, overwhelm; burden","forms":["dēgravātī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quīdam cūriōsior: “Simōnidē, tū ex opibus nīl sūmis tuīs?” “Mēcum” inquit “mea sunt cūncta.” Tum paucī ēnatant, quia plūrēs onere dēgravātī perierant.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"degredior","latin":"degredior, degredi, degressus sum","headword":"degredior","letter":"d","pos":"verb","posGroup":"verb","english":"march/go/come/flow down, descend; dismount; move off/depart; turn aside/deviate","forms":["dēgredientium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde variōs vultūs {{dēgredientium}} ā nūntiīs cernerēs, ut cuique laeta aut trīstia nūntiābantur, grātulantēsque aut cōnsolantēs redeuntibus domōs circumfūsōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"degusto","latin":"degusto, degustare, degustavi, degustatus","headword":"degusto","letter":"d","pos":"verb","posGroup":"verb","english":"taste; taste/try/eat/drink a little of; glance at; graze; sip; test; judge","forms":["dēgustāvissent"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Fuēre eā tempestāte quī dīcerent Catilīnam, ōrātiōne habitā, cum ad iūs iūrandum populārēs sceleris suī adigeret, hūmānī corporis sanguinem vīnō permixtum in paterīs circumtulisse; inde cum post exsecrātiōnem omnēs {{dēgustāvissent}}, sīcuti in sollemnibus sacrīs fierī cōnsuēvit, aperuisse cōnsilium suum, atque eō ita fēcisse, quō inter sē fīdī magis forent, alius aliī tantī facinoris cōnsciī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"dehinc","latin":"dehinc","headword":"dehinc","letter":"d","pos":"adverb","posGroup":"adverb","english":"next, then","forms":["dehinc"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Bellum scrīptūrus sum quod populus Rōmānus cum Iugurthā, rēge Numidārum, gessit, prīmum quia magnum et ātrox variāque victōriā fuit, {{dehinc}} quia tunc prīmum superbiae nōbilitātis obviam ītum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dehisco","latin":"dehisco, dehiscere, dehivi, -","headword":"dehisco","letter":"d","pos":"verb","posGroup":"verb","english":"gape/yawn/split open; part/divide, develop/leave a gap/leak; be/become apart","forms":["dēhīscat","dēhīscēns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hī summō in flūctū pendent; hīs unda {{dēhīscēns}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"dehortor","latin":"dehortor, dehortari, dehortatus sum","headword":"dehortor","letter":"d","pos":"verb","posGroup":"verb","english":"dissuade; advise (person) against an action; deter, have restraining influence","forms":["dēhortābantur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Suī illum amīcī ab hōc officiō {{dēhortābantur}}; at Tobiās, magis Deum quam rēgem timēns, id facere nōn dēstitit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deicere","latin":"(dēiciō) dēicere (< icere)","headword":"dēicere","letter":"d","pos":"","posGroup":"other","english":"throw/bring down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deicio","latin":"deicio, deicere, dejeci, dejectus","headword":"deicio","letter":"d","pos":"verb","posGroup":"verb","english":"throw/pour/jump/send/put/push/force/knock/bring down; cause to fall/drop; hang","forms":["dēicerent","dēiēcerit","dēiēcimus","dēiēcit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum Aegyptiī prōgrederentur in mediō marī, Dominus subvertit eōrum currūs et {{dēiēcit}} equitēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deiecto","latin":"dejecto, dejectare, dejectavi, dejectatus","headword":"dejecto","letter":"d","pos":"verb","posGroup":"verb","english":"hurl down violently; (intensive verb)","forms":["deiecto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, {{deiecto}} praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem duodenum pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium incursu etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deiectus","latin":"dejectus, dejecta, dejectum","headword":"dejectus","letter":"d","pos":"adjective","posGroup":"adjective","english":"downcast/dismayed/subdued/dejected; drooping/hanging/sunk/cast down; low lying","forms":["dēiectae","deiecti","dēiectīs","deiectos","dēiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque {{deiecti}} in foro ac locis patentioribus cuneatim constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dein","latin":"dein","headword":"dein","letter":"d","pos":"adverb","posGroup":"adverb","english":"afterward, then","forms":["dein"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Dein}} dēdūxit eum domum, eīque cibum apposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deinceps","latin":"deinceps","headword":"deinceps","letter":"d","pos":"adverb","posGroup":"adverb","english":"in succession, next","forms":["deinceps"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii {{deinceps}} excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deinde","latin":"deinde","headword":"deinde","letter":"d","pos":"adverb","posGroup":"adverb","english":"then, next; then","forms":["deinde"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Hāc lūce” inquit Iūlius “nihil vidērī potest”, ac {{deinde}}: “Nōn ūna, sed quattuor parvae bēstiae hīc iacent.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"deinde/dein","latin":"deinde/dein","headword":"deinde/dein","letter":"d","pos":"","posGroup":"other","english":"afterward, then","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"deiurare","latin":"(dēiūrō) dēiūrāre","headword":"dēiūrāre","letter":"d","pos":"verb","posGroup":"verb","english":"swear; to swear by","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"deiuro","latin":"dejuro, dejurare, dejuravi, dejuratus","headword":"dejuro","letter":"d","pos":"verb","posGroup":"verb","english":"swear, take an oath","forms":["dēiūrant"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In veteribus scrīptīs neque mulierēs Rōmānae per Herculem {{dēiūrant}} neque virī per Castorem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"delabi","latin":"(dēlābōr) dēlābī (< lābī)","headword":"dēlābī","letter":"d","pos":"","posGroup":"other","english":"slip down, descend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"delabor","latin":"delabor, delabi, delapsus sum","headword":"delabor","letter":"d","pos":"verb","posGroup":"verb","english":"slip/fall/glide/fly/flow down; fall freely/out of control/prostrate; slip into","forms":["dēlāpsa","dēlāpsae","dēlāpsīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hellē autem dēspiciēns magnōs flūctūs Īnfrā sē vīdit; puella perterrita dē arietis dorsō {{dēlāpsa}} est; dum vērō cadit, “Ō frāter,” clāmāvit, “ōrō tē ut auxilium mihi ferās!” Deinde, quatiēns bracchia et crūra dē summō caelō in mare cecidit ac mersa est, neque frāter eam servāre potuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"delapsus","latin":"delapsus, delapsus","headword":"delapsus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"outfall (for drainage); flowing off, discharge (L+S); falling off, decent","forms":["dēlāpsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Saūl ipse ex equō {{dēlāpsus}}, nē vīvus in potestātem hostium venīret, ūnī comitum latus trānsfodiendum praebuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"delectamentum","latin":"dēlectāmentum, -ī","headword":"dēlectāmentum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"delight","forms":["dēlectāmenta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"“Certē Iūnō mē hīc nōn vidēbit,” dīxit, “aut sī videt, sunt {{dēlectāmenta}} pretiōsa sed dīgna pretiī.” Statim Iuppiter fōrmam Diānae simulāvit et ita ad nympham sēcrētō appropinquāvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"delectantur","latin":"dēlectantur","headword":"dēlectantur","letter":"d","pos":"verb","posGroup":"verb","english":"are delighted (with)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"delectat","latin":"dēlectat","headword":"dēlectat","letter":"d","pos":"verb","posGroup":"verb","english":"delights, pleases","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"delectat/delectant","latin":"dēlectat/dēlectant","headword":"dēlectat/dēlectant","letter":"d","pos":"","posGroup":"other","english":"delight, please","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"delectatio","latin":"dēlectātiō, -ōnis (m.)","headword":"dēlectātiō","letter":"d","pos":"","posGroup":"other","english":"delight, pleasure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"delecto","latin":"delecto, delectare, delectavi, delectatus","headword":"delecto","letter":"d","pos":"verb","posGroup":"verb","english":"delight, please, amuse, fascinate; charm, lure, entice; be a source of delight","forms":["dēlectābantur","dēlectābat","dēlectābātur","dēlectābimur","dēlectandī","dēlectant","dēlectantur","dēlectāre","dēlectārentur","dēlectārētur","dēlectāris","dēlectat","dēlectātī","delectatis","dēlectātur","dēlectātus","dēlectent","dēlectētur","delecto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter effecto opere legionibusque traductis et loco castris idoneo {{delecto}}, reliquas copias revocavit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"delector","latin":"delector, delectari, delectatus sum","headword":"delector","letter":"d","pos":"verb","posGroup":"verb","english":"delight, please, amuse, fascinate; charm, lure, entice; be a source of delight","forms":["dēlector"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Ego tē discipulum improbum nōn cōnsōlor, quod tergum tibi dolet, at {{dēlector}} lacrimīs tuīs!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"deleo","latin":"dēleō, dēlēre","headword":"dēleō","letter":"d","pos":"verb","posGroup":"verb","english":"blot out, efface, destroy","forms":["Dēlē","dēleātur","dēlēbitur","dēlēbō","dēlendam","dēlendī","dēleō","dēlēre","dēlēret","deleri","dēlet","dēlēta","dēlētae","dēlētam","dēlētās","dēlētīs","dēlētum","dēlēveris","dēlēvissem","dēlēvisset","dēlēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quod nisi crebris subsidiis ac totius diei labore milites essent defessi, omnes hostium copiae {{deleri}} potuissent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"delet","latin":"dēlet","headword":"dēlet","letter":"d","pos":"verb","posGroup":"verb","english":"erases, deletes","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"deletus","latin":"deletus, deletus","headword":"deletus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"annihilation","forms":["dēlētus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Dēlētus}} est ūniversus exercitus pharaōnis in mediīs flūctibus, nec ūnus quidem nūntius tantae clādis superfuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deliberare","latin":"(dēlīberō) dēlīberāre","headword":"dēlīberāre","letter":"d","pos":"","posGroup":"other","english":"deliberate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deliberatio","latin":"dēlīberātiō, -ōnis ( f.)","headword":"dēlīberātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"deliberation; deliberation, debate","forms":["dēlīberātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Utinam, Quirītēs, virōrum fortium atque innocentium cōpiam tantam habērētis ut haec vōbīs dēlīberātiō difficilis esset, quemnam potissimum tantīs rēbus ac tantō bellō praeficiendum putārētis!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"delibero","latin":"delibero, deliberare, deliberavi, deliberatus","headword":"delibero","letter":"d","pos":"verb","posGroup":"verb","english":"weigh/consider/deliberate/consult (oracle); ponder/think over; resolve/decide on","forms":["dēlīberandum","dēlīberāns","Deliberatur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Deliberatur}} de Avarico in communi concilio, incendi placeret an defendi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"delibro","latin":"delibro, delibrare, delibravi, delibratus","headword":"delibro","letter":"d","pos":"verb","posGroup":"verb","english":"peel, remove/strip the bark (from); strip/take off (bark); (rind L+S)","forms":["delibratis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Itaque truncis arborum aut admodum firmis ramis abscisis atque horum {{delibratis}} ac praeacutis cacuminibus perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"delicatus","latin":"delicatus, delicata -um, delicatior -or -us, delicatissimus -a -um","headword":"delicatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"luxurious/sumptuous, addicted to pleasure; self-indulgent/comfortable; pampered","forms":["dēlicātissimam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Permittitis tamen ﬁnîrî lūsum?” Sequēbātur puer cum tabulā terebinthinā et crystallinîs tesserîs, notävîque rem om- nium {{dēlicātissimam}}: prô calculîs enim albîs ac nigrîs aureôs argenteôsque habēbat tesserae Interim, �Ē$ gustantibus adhūc nôbîs, repositôrium al- lātum est cum corbe in quô gallîna erat lignea patentibus in orbem älîs, quālēs esse solent quae _ incubant ôva.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"delicia","latin":"delicia, deliciae","headword":"delicia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"|||favorite/pet/darling/beloved; man w/fine taste/gourmet; voluptuary","forms":["deliciae","dēliciārum","dēliciās","dēliciīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Rēgnābat Salomōn in summā pāce, opibus et {{dēliciīs}} affluēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deliciae","latin":"dēliciae, -ārum","headword":"dēliciae","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"(f.pl.) delight, pet; darling, pet; darling, pet, delight","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"delictum","latin":"dēlictum, -ī","headword":"dēlictum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"misdeed, offense; fault, crime","forms":["dēlicta","dēlictī","delicto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam maiore commisso {{delicto}} igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deligare","latin":"(dēligō) dēligāre","headword":"dēligāre","letter":"d","pos":"","posGroup":"other","english":"tie up, fasten","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deligere","latin":"(dēligō) dēligere (< legere)","headword":"dēligere","letter":"d","pos":"","posGroup":"other","english":"pick out, choose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deligo","latin":"dēligō, -ere, -lēgī, -lēctum","headword":"dēligō","letter":"d","pos":"verb","posGroup":"verb","english":"pick, choose, select","forms":["delecta","delecti","dēlēctīs","dēlēctōs","dēlēgistī","dēlēgit","dēligāta","deligebat","dēligendō","dēligendum","dēligēre","dēligeret","deligi","deligit","deligunt","deliguntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pabulum secari non posse; necessario dispersos hostes ex aedificiis petere; hos omnes cotidie ab equitibus {{deligi}} posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"delinio","latin":"delinio, delinire, delinivi, delinitus","headword":"delinio","letter":"d","pos":"verb","posGroup":"verb","english":"mitigate, mollify, smooth down, soothe; soften, cajole; bewitch, charm, entice","forms":["dēlīniendum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc aulicī eī suāsērunt ut aliquem arcesseret, quī citharam scīret pulsāre, ad {{dēlīniendum}} aegrum eius animum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"delinquere","latin":"(dēlinquō) dēlinquere","headword":"dēlinquere","letter":"d","pos":"","posGroup":"other","english":"misbehave, do wrong","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"delinquo","latin":"delinquo, delinquere, deliqui, delictus","headword":"delinquo","letter":"d","pos":"verb","posGroup":"verb","english":"fail (duty), be wanting/lacking, fall short; offend/do wrong/err/commit offense","forms":["dēlīquerīs","dēlīquērunt","dēlīquī","dēlīquit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"AMPHITRYO: Tūtē ēdictās facta tua—ex mē quaeris quid {{dēlīquerīs}}?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"deliquo","latin":"deliquo, deliquare, deliquavi, deliquatus","headword":"deliquo","letter":"d","pos":"verb","posGroup":"verb","english":"strain (liquid to clear); strain off (solid matter); make clear; clarify/explain","forms":["dēlīquēre"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Misereāminī, cēnseō — {{dēlīquēre}} hominēs adulēscentulī per ambitiōnem! — atque etiam armātōs dīmittātis!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"deliramentum","latin":"deliramentum, deliramenti","headword":"deliramentum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"delusion, nonsense; product of a deranged mind; absurdity (L+S)","forms":["dēlīrāmenta"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: [ad Sōsiam] Haec quidem {{dēlīrāmenta}} loquitur!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"delirare","latin":"(dēlīrō) dēlīrāre","headword":"dēlīrāre","letter":"d","pos":"","posGroup":"other","english":"be mad","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deliro","latin":"deliro, delirare, deliravi, deliratus","headword":"deliro","letter":"d","pos":"verb","posGroup":"verb","english":"be mad/crazy/deranged/silly; speak deliriously, rave; deviate from balks (plow)","forms":["dēlīrantēs","dēlīrāre","Dēlīrat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"AMPHITRYO: {{Dēlīrat}} uxor.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"delitescere","latin":"(dēlitēscō) dēlitēscere, -uisse","headword":"dēlitēscere","letter":"d","pos":"","posGroup":"other","english":"hide oneself","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"delitisco","latin":"delitisco, delitiscere, delitui, -","headword":"delitisco","letter":"d","pos":"verb","posGroup":"verb","english":"hide, go in hiding/seclusion; withdraw; vanish/be concealed; take refuge/shelter","forms":["dēlituisse","dēlituistis","dēlituit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Tobiās cum uxōre et fīliō {{dēlituit}}, sīcque rēgis īram effūgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"delos","latin":"Delos, Deli","headword":"Delos","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"Delos; (island birthplace of Apollo and Diana)","forms":["Dēlī","Dēlō","Dēlos","Dēlum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Samos, Naxos, Paros, {{Dēlos}}, Lebin-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"delphinus","latin":"delphīnus, -ī","headword":"delphīnus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dolphin","forms":["delphīnī","delphīnis","delphīnō","delphīnum","delphīnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Neptūnus, eius precibus permōtus, parvam īnsulam ex Ōceanī fundō extulit; tum {{delphīnum}} ex altō marī ad Lātōnam mīsit, quī eam in dorsō suō sedentem ā lītore maris usque ad parvae illīus īnsulae ōram vēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"delphis","latin":"delphis, delphinos/is","headword":"delphis","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dolphin; ornament shaped like a dolphin; (part of water organ); constellation","forms":["Delphis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quōdam diē Cēyx templum Apollinis {{Delphis}} situm vī sērē cōnstituit, ut deum cōnsuleret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"delubrum","latin":"dēlūbrum, -ī","headword":"dēlūbrum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"temple, shrine","forms":["dēlūbra","dēlūbrīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Collātīnīs hīs verbīs dēditī sunt, eaque dēditiōnis fōrmula est: Rēx interrogāvit: \"Estisne vōs lēgātī ōrātōrēsque ut missī ā populō Collātīnō, vōs populumque Collātīnum dēderētis?\" \"Sumus.\" \"Estne populus Collātīnus in suā potestāte?\" \"Est.\" \"Dēditisne vōs populumque Collātīnum, urbem, agrōs, aquam, terminōs, {{dēlūbra}}, dīvīna hūmānaque omnia in meam populumque Rōmānum diciōnem?\" \"Dedimus.\" \"At ego recipiō.\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deludo","latin":"deludo, deludere, delusi, delusus","headword":"deludo","letter":"d","pos":"verb","posGroup":"verb","english":"deceive/dupe; play false/mock/make sport; play through, complete a performance","forms":["Dēlūdam","dēlūdētur","dēlūdī","dēlūsa","dēlūsam","dēlūserīs","dēlūsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Malō animō id faciēbat rēx invidus: spērābat scīlicet iuvenem audācem facile peritūrum; at sua eum spēs {{dēlūsit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dem","latin":"dem, demos/is","headword":"dem","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"community, a people; administrative district (in Attica); tract of land (L+S)","forms":["dem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Dem}} | Fēmina aspera","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"demandare","latin":"(dēmandō) dēmandāre","headword":"dēmandāre","letter":"d","pos":"","posGroup":"other","english":"entrust, hand over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"demando","latin":"demando, demandare, demandavi, demandatus","headword":"demando","letter":"d","pos":"verb","posGroup":"verb","english":"entrust, hand over (to), commit; lay (duty on a person), charge (that)","forms":["dēmandātā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ancus, dēmandātā cūrā sacrōrum flāminibus sacerdōtibusque aliīs, exercitū novō cōnscrīptō profectus, Politorium, urbem Latīnōrum, vī cēpit; secūtusque mōrem rēgum priōrum, quī rem Rōmānam auxerant hostibus in cīvitātem accipiendīs, multitūdinem omnem Rōmam trādūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"demens","latin":"dēmens (gen. dēmēntis)","headword":"dēmens","letter":"d","pos":"adjective","posGroup":"adjective","english":"out of one’s mind, mad; mad, out of one's mind","forms":["dēmēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Saepe tamen {{dēmēns}} 'stultē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"dementia","latin":"dēmentia, -ae","headword":"dēmentia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"madness, folly","forms":["dēmentia","dēmentiam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae vōs {{dēmentia}}” dīxī “concitat, ō sociī, captam dīmittere Trōiam, quidque domum fertis decimō, nisi dēdecus, annō?”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"demere","latin":"(dēmō) dēmere, dēmpsisse, dēmptum","headword":"dēmere","letter":"d","pos":"verb","posGroup":"verb","english":"take away; to take away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"demergere","latin":"(dēmergō) dēmergere, -merisse, -mersum","headword":"dēmergere","letter":"d","pos":"","posGroup":"other","english":"sink, plunge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"demergo","latin":"demergo, demergere, demersi, demersus","headword":"demergo","letter":"d","pos":"verb","posGroup":"verb","english":"submerge/sink; plunge/dip/immerse; set; retract; conceal; bury; overwhelm/engulf","forms":["dēmergātur","dēmersit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī quis autem scandalizāverit ūnum dē parvulīs isfīs, expedit eī ut suspendiitur mola collō eius et {{dēmergātur}} in profundum mare.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"demersus","latin":"demersus, demersa -um, demersior -or -us, demersissimus -a -um","headword":"demersus","letter":"d","pos":"adjective","posGroup":"adjective","english":"depressed","forms":["dēmersae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam ex ducentīs et vīgintī nāvibus cum trīgintā fūgit, nōnāgintā cum pugnātōribus captae sunt, {{dēmersae}} cēterae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deminuo","latin":"deminuo, deminuere, deminui, deminutus","headword":"deminuo","letter":"d","pos":"verb","posGroup":"verb","english":"make smaller; cut up small; lessen/diminish/reduce (size/number/amount/scope)","forms":["deminuere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quae tametsi Caesar intellegebat, tamen quam mitissime potest legatos appellat: nihil se propter inscientiam levitatemque vulgi gravius de civitate iudicare neque de sua in Aeduos benevolentia {{deminuere}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deminutus","latin":"deminutus, deminuta, deminutum","headword":"deminutus","letter":"d","pos":"adjective","posGroup":"adjective","english":"diminished; small, diminutive","forms":["deminutae","deminutis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Qui Avarico expugnato refugerant, armandos vestiendosque curat; simul, ut {{deminutae}} copiae redintegrarentur, imperat certum numerum militum civitatibus, quem et quam ante diem in castra adduci velit, sagittariosque omnes, quorum erat permagnus numerus in Gallia, conquiri et ad se mitti iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"demiror","latin":"demiror, demirari, demiratus sum","headword":"demiror","letter":"d","pos":"verb","posGroup":"verb","english":"wonder (I wonder how/why); be amazed/utterly astonished at, at loss to imagine","forms":["dēmīror"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: Manē, māne, obsecrō tē! [Ad Sōsiam] Nimis {{dēmīror}}, Sōsia,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"demissus","latin":"demissus, demissa -um, demissior -or -us, demississimus -a -um","headword":"demissus","letter":"d","pos":"adjective","posGroup":"adjective","english":"low/low-lying; of low altitude; keeping low (people); slanting/hanging/let down","forms":["dēmissus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In eum locum postquam {{dēmissus}} est Lentulus, vindicēs rērum capitālium, quibus praeceptum erat, laqueō gulam frēgēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"demittere","latin":"(dēmittō) dēmittere (< mittere)","headword":"dēmittere","letter":"d","pos":"","posGroup":"other","english":"let fall, drop, lower","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"demitto","latin":"dēmittō, -ere, -mīsī, -missum","headword":"dēmittō","letter":"d","pos":"verb","posGroup":"verb","english":"send away, send down","forms":["dēmīsit","dēmissa","demissae","demissi","demissis","dēmissō","dēmissum","demittebantur","demittere","demitterent","dēmitteret","dēmittit","dēmittite","dēmittitur","Dēmittō","dēmittunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi neminem in aequum locum sese {{demittere}} sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"demo","latin":"demo, demere, dempsi, demptus","headword":"demo","letter":"d","pos":"verb","posGroup":"verb","english":"take/cut away/off, remove, withdraw; subtract; take away from","forms":["dēme","dēmere","dēmpta","dēmptās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Magister: 'Āctīva quae sunt?' Discipulus: 'Quae in -ō dēsinunt et acceptā -r litterā faciunt ex sē passīva, ut lēgō: legor.' Magister: 'Passīva quae sunt?' Discipulus: 'Quae in -r dēsinunt et ea {{dēmpta}} redeunt in āctīvā, ut legor: lēgō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"demonstrare","latin":"dēmōnstrāre","headword":"dēmōnstrāre","letter":"d","pos":"verb","posGroup":"verb","english":"to show, prove","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"demonstrativum","latin":"dēmōnstrātīvum","headword":"dēmōnstrātīvum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"demonstrative","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"demonstro","latin":"dēmōnstrō, dēmōnstrāre","headword":"dēmōnstrō","letter":"d","pos":"verb","posGroup":"verb","english":"point out, show","forms":["dēmōnstrandī","demonstrant","dēmōnstrāre","dēmōnstrārī","demonstrat","demonstratur","dēmōnstrāverim","demonstravimus","dēmōnstrāvit","dēmōnstrēs","dēmōnstret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere {{demonstrant}}; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"demum","latin":"dēmum","headword":"dēmum","letter":"d","pos":"adverb","posGroup":"adverb","english":"finally; at last, finally","forms":["dēmum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum {{dēmum}} illī cum eō fīdenter locūtī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"demus","latin":"demus","headword":"demus","letter":"d","pos":"adverb","posGroup":"adverb","english":"at last, finally; at length, in the end, eventually; [tum demum => only then]","forms":["Dēmus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Dēmus}} causidicō honōrārium et advocātīs et iūris perītō, ut studiōsius dēfendant nōs.” [Servus, nummulārium cōnspiciēns:] “Iste est.” [Lūcius:] “Accipe ab eō nummōs, et sequere!” [Nummīs acceptīs, servus Lūcium ad forum sequitur.] [Lūcius:] “Sīcut cōnstituimus adest Gāius.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"denarium","latin":"denarium, denarii","headword":"denarium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"denarius (silver coin=10/16/18 asses); (~ aureus=25 silver ~); drachma weight","forms":["dēnārium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ecce pecūnia.” Magister servō suō {{dēnārium}} dat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"denarius","latin":"dēnārius, -ī","headword":"dēnārius","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"denarius (silver coin)","forms":["dēnāriī","dēnāriōs","dēnārius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Posterā diē prōtulit duōs {{dēnāriōs}}, et dēdit stabulāriō, et ait: ' Cūram illīus habē: et quodcumque superērogāverīs, ego, cum redierō, reddam tibi '.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"denarro","latin":"denarro, denarrare, denarravi, denarratus","headword":"denarro","letter":"d","pos":"verb","posGroup":"verb","english":"tell/relate fully/in full; give a full account of; recount, narrate (L+S)","forms":["dēnārrat"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Puer Papīrius in medium Cūriae prōgressus, quid māter audīre īnstitisset, quid ipse mātrī dīxisset, rem sīcut fuerat {{dēnārrat}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"denego","latin":"dēnegō, -āre, dēnegāvī","headword":"dēnegō","letter":"d","pos":"verb","posGroup":"verb","english":"refuse, deny","forms":["dēnegāre","dēnegat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Dēnegat}} hoc genitor dīvīsque īrāscitur ipsīs atque in rēge tamen pater est; ego mīte parentis ingenium verbīs ad pūblica commoda vertī: difficilem tenuī sub inīquō iūdice causam.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"deni","latin":"dēnī, -ae, -a","headword":"dēnī","letter":"d","pos":"adjective","posGroup":"adjective","english":"ten at a time; ten each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"denique","latin":"dēnique","headword":"dēnique","letter":"d","pos":"adverb","posGroup":"adverb","english":"finally; and then, finally","forms":["dēnique"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Denique}} ex omni numero, qui fuit circiter milium XL, vix DCCC, qui primo clamore audito se ex oppido eiecerunt, incolumes ad Vercingetorigem pervenerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dens","latin":"dēns, dentis","headword":"dēns","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"(m.) tooth","forms":["dēns","dente","dentem","dentēs","dentibus","dentium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Post eās venit parvus canis īrātus, quī ūnam ovem {{dentibus}} petit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"denso","latin":"denso, densare, densavi, densatus","headword":"denso","letter":"d","pos":"verb","posGroup":"verb","english":"thicken/condense/concentrate/compress/coagulate; press/pack/crowd together","forms":["dēnsō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"densus","latin":"dēnsus, -a, -um","headword":"dēnsus","letter":"d","pos":"adjective","posGroup":"adjective","english":"thick, dense","forms":["dēnsa","dēnsam","dēnsās","dēnsī","dēnsior","dēnsissima","densissimis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"A medio fere colle in longitudinem, ut natura montis ferebat, ex grandibus saxis sex pedum murum, qui nostrum impetum tardaret praeduxerant Galli atque inferiore omni spatio vacuo relicto superiorem partem collis usque ad murum oppidi {{densissimis}} castris compleverant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dentatus","latin":"dentatus, dentata, dentatum","headword":"dentatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"toothed; w/(prominent/displayed) teeth; w/spikes/teeth/gears; polished w/tooth","forms":["Dentātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Curius {{Dentātus}}, ambō cōnsulēs, contrā Samnītās missī ingentibus proeliīs eōs cōnfēcēre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"denuntiare","latin":"(dēnuntiō) dēnuntiāre","headword":"dēnuntiāre","letter":"d","pos":"","posGroup":"other","english":"denounce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"denuntio","latin":"denuntio, denuntiare, denuntiavi, denuntiatus","headword":"denuntio","letter":"d","pos":"verb","posGroup":"verb","english":"give notice, warn/foretell; threaten/enjoin/declare intent to injure; intimate","forms":["dēnūntiāns","dēnūntiārent","dēnūntiāret","dēnūntiāta","Dēnūntiāvī","dēnūntiāvisset","dēnūntiāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At Deus ad Davidem mīsit prophētam, quī illum admonēret, eīque poenam sceleris {{dēnūntiāret}} subeundam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"denuo","latin":"dēnuō","headword":"dēnuō","letter":"d","pos":"adverb","posGroup":"adverb","english":"anew, again; again, anew","forms":["dēnuō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque ē lectō surgere cōnātur, sed pēs dēnuō dolēre incipit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"deorsum","latin":"deorsum","headword":"deorsum","letter":"d","pos":"adverb","posGroup":"adverb","english":"down; downwards","forms":["deorsum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam singulī nautae singulōs rēmōs sūrsum {{deorsum}} movēbant et nāvis ē portū proficiscēbatur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"depellere","latin":"(dēpellō) dēpellere (< pellere)","headword":"dēpellere","letter":"d","pos":"verb","posGroup":"verb","english":"drive down/off, avert; to drive off, repel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"depello","latin":"depello, depellere, depuli, depulsus","headword":"depello","letter":"d","pos":"verb","posGroup":"verb","english":"drive/push out//off/away/aside, repel; expel; remove, wean; banish utterly","forms":["depellunt","dēpulerat","dēpulissem","depulsos","dēpulsum","dēpulsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sextium legatum, quem minoribus castris praesidio reliquerat, misit, ut cohortes ex castris celeriter educeret et sub infimo colle ab dextro latere hostium constitueret, ut, si nostros loco {{depulsos}} vidisset, quo minus libere hostes insequerentur terreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dependo","latin":"dependo, dependere, dependi, depensus","headword":"dependo","letter":"d","pos":"verb","posGroup":"verb","english":"pay over/down; pay (penalty); expend (time/labor); spend, lay out; bestow","forms":["dēpendēbant","dēpendent"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Secūtum est hôs repositôrium in quô positus erat prīmae magnitūdinis aper ..., ē cuius dentibus sportellae {{dēpendēbant}} duae palmulîs textae, alterā caryôtîs alterā thëbaicîs rē- plēta.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"depereo","latin":"depereo, deperire, deperivi(ii), deperitus","headword":"depereo","letter":"d","pos":"verb","posGroup":"verb","english":"perish/die; be lost/totally destroyed; be much in love with/love to distraction","forms":["dēperit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"sīc efflīctim amāre proinde ut hic tē efflīctim {{dēperit}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"deponens","latin":"dēpōnēns","headword":"dēpōnēns","letter":"d","pos":"adjective","posGroup":"adjective","english":"(gen.depōnentis) deponent (verb)","forms":["dēpōnēns","dēpōnentia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quī mercātus est sindonem, et {{dēpōnēns}} eum ē cruce, involvit sindone et posuit in monumentō, et advolvit lapidem ad ōstium monumenfī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deponere","latin":"(dēpōnō) dēpōnere (< pōnere)","headword":"dēpōnere","letter":"d","pos":"","posGroup":"other","english":"put/lay down, deposit","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"depono","latin":"depono, deponere, deposui, depostus","headword":"depono","letter":"d","pos":"verb","posGroup":"verb","english":"put/lay down/aside/away; let drop/fall; give up; resign; deposit/entrust/commit","forms":["dēpōne","dēpōnendam","deponere","dēpōneret","dēpōnitur","dēpōnunt","deposuerat","dēposuerit","dēposuērunt","Dēposuī","dēposuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium {{deponere}} coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"depopulari","latin":"(dēpopulor) dēpopulārī","headword":"dēpopulārī","letter":"d","pos":"","posGroup":"other","english":"sack","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"depopulatio","latin":"dēpopulātiō, -ōnis ( f.)","headword":"dēpopulātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"plundering","forms":["dēpopulātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac prīmum agrōs quōs bellō Rōmulus cēperat dīvīsit virītim cīvibus docuitque sine {{dēpopulātiōne}} atque praedā posse eōs colendīs agrīs abundāre commodīs omnibus, amōremque iīs ōtiī et pācis iniēcit, quibus facillimē iūstitia et fidēs convalēscit et quōrum patrōciniō maximē cultus agrōrum perceptiōque frūgum dēfenditur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"depopulor","latin":"depopulor, depopulari, depopulatus sum","headword":"depopulor","letter":"d","pos":"verb","posGroup":"verb","english":"sack/plunder/pillage/rob/despoil; ravage/devastate/destroy/lay waste; overgraze","forms":["depopulandos","Depopulata","dēpopulātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Altera ex parte Gabalos proximosque pagos Arvernorum in Helvios, item Rutenos Cadurcosque ad fines Volcarum Arecomicorum {{depopulandos}} mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deportare","latin":"(dēportō) dēportāre","headword":"dēportāre","letter":"d","pos":"","posGroup":"other","english":"convey, bring back","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deporto","latin":"deporto, deportare, deportavi, deportatus","headword":"deporto","letter":"d","pos":"verb","posGroup":"verb","english":"bring, convey (to); carry along/down (current); transport; take/bring home","forms":["dēportāre","dēportātō","dēportāvit","dēportētis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde praecēpit medicī ut condīrent corpus; et ipse cum frātribus multīsque Aegyptiīs patrem {{dēportāvit}} in regiōnem Chanaan.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deposcere","latin":"(dēposcō) dēposcere (< poscere)","headword":"dēposcere","letter":"d","pos":"","posGroup":"other","english":"demand","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deposco","latin":"deposco, deposcere, depoposci, -","headword":"deposco","letter":"d","pos":"verb","posGroup":"verb","english":"demand peremptorily; ask for earnestly; require; request earnestly; challenge","forms":["dēpoposcerat","dēpoposcit","dēposcī","deposcunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis {{deposcunt}} qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"depositum","latin":"depositum, depositi","headword":"depositum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"deposit, trust; money placed on deposit/safe keeping; contract on trust money","forms":["dēposita","dēpositīs","dēpositō","dēpositum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc, lūctū dēpositō, iussit sibi appōnī cibōs, mīrantibusque aulicīs dīxit: “Aegrōtante puerulō ieiūnus ōrābam, spērāns scīlicet Deum plācārī posse; nunc autem, cum mortuus sit, cūr frūstrā lūgeam?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"depravare","latin":"(dēprāvō) dēprāvāre","headword":"dēprāvāre","letter":"d","pos":"","posGroup":"other","english":"pervert, distort","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"depravo","latin":"depravo, depravare, depravavi, depravatus","headword":"depravo","letter":"d","pos":"verb","posGroup":"verb","english":"distort/deform/twist, make crooked; mislead/pervert; deprave, corrupt","forms":["dēprāvāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fautōrēs lēgātōrum, praetereā senātūs magna pars, grātiā {{dēprāvāta}}, Adherbalis dicta contemnere, Iugurthae virtūtem extollere laudibus; grātiā, voce, dēnique omnibus modīs prō aliēnō scelere et flagitiō sua quasi prō glōriā nītēbantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deprecari","latin":"(dēprecōr) dēprecārī","headword":"dēprecārī","letter":"d","pos":"","posGroup":"other","english":"beg, entreat","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deprecatio","latin":"dēprecātiō, -ōnis ( f.)","headword":"dēprecātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"entreaty, plea","forms":["dēprecātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rōmānōs saepe vīcit, usque ad quīntum mīliārium urbis accessit, oppugnātūrus etiam patriam suam (lēgātīs quī pācem petēbant repudiātīs), nisi ad eum māter Veturia et uxor Volumnia ex urbe vēnissent, quārum flētū et {{dēprecātiōne}} superātus remōvit exercitum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deprecor","latin":"deprecor, deprecari, deprecatus sum","headword":"deprecor","letter":"d","pos":"verb","posGroup":"verb","english":"avert by prayer; entreat/pray/beg; intercede/beg pardon/mercy/relief/exemption","forms":["deprecari","dēprecātūra","dēprecer","dēprecor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His cognitis et Litavicci fraude perspecta Aedui manus tendere et deditionem significare et proiectis armis mortem {{deprecari}} incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deprehendo","latin":"deprehendo, deprehendere, deprehendi, deprehensus","headword":"deprehendo","letter":"d","pos":"verb","posGroup":"verb","english":"seize/catch; catch napping/redhanded; surprise/pounce on; arrest; intercept","forms":["dēprehendant","dēprehendat","dēprehenderentur","dēprehenderētur","dēprehendisse","dēprehendit","dēprehēnsae","dēprehēnsī","dēprehēnsīs","dēprehēnsum","dēprehēnsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Apud quem fūrtum {{dēprehēnsum}} fuerit, is morte mulctētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deprendo","latin":"deprendo, deprendere, deprendi, deprensus","headword":"deprendo","letter":"d","pos":"verb","posGroup":"verb","english":"seize/catch; catch napping/redhanded; surprise/pounce on; arrest; intercept","forms":["dēprēndere","dēprēndī","dēprēndit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Bracchia mersit aquīs nec sē {{dēprēndit}} in illīs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"deprensa","latin":"deprensa, deprensae","headword":"deprensa","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"species of military punishment; (more than castigatio, less than ignominia)","forms":["dēprēnsa","dēprēnsīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Deprensis}} navibus circiter quinquaginta celeriterque coniunctis atque eo militibus iniectis et rei novitate perterritis oppidanis, quorum magna pars erat ad bellum evocata, sine contentione oppido potitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"depressus","latin":"depressus, depressa -um, depressior -or -us, depressissimus -a -um","headword":"depressus","letter":"d","pos":"adjective","posGroup":"adjective","english":"low/low-lying, deep down; at/having low elevation; low-pitched/subdued (sound)","forms":["dēpressus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Est in Carcere locus, quod Tulliānum appellātur, ubi paululum ascenderīs ad laevam, circiter duodecim pedēs humī {{dēpressus}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"deprimere","latin":"(dēprimō) dēprimere (< premere)","headword":"dēprimere","letter":"d","pos":"","posGroup":"other","english":"press down, sink","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"depromere","latin":"(dēprōmō) dēprōmere (< prōmere)","headword":"dēprōmere","letter":"d","pos":"","posGroup":"other","english":"take out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"depromo","latin":"depromo, depromere, deprompsi, depromptus","headword":"depromo","letter":"d","pos":"verb","posGroup":"verb","english":"bring/draw out, fetch, produce (from container/store); bring/utter (info)","forms":["dēprōmpsit","dēprōmptam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum Eliezer {{dēprōmpsit}} vās aurea et argentea, vestēsque pretiōsās, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"depugno","latin":"depugno, depugnare, depugnavi, depugnatus","headword":"depugno","letter":"d","pos":"verb","posGroup":"verb","english":"fight hard/it out, do battle; fight against and kill (in arena); stop fighting","forms":["depugnarent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque deiecti in foro ac locis patentioribus cuneatim constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa {{depugnarent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"depulsio","latin":"dēpulsiō, -ōnis ( f.)","headword":"dēpulsiō","letter":"d","pos":"","posGroup":"other","english":"rebuttal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deque","latin":"deque","headword":"deque","letter":"d","pos":"adverb","posGroup":"adverb","english":"downwards","forms":["deque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci {{deque}} his stramenta detrahi mulionesque cum cassidibus equitum specie ac simulatione collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"derectus","latin":"derectus, derecta -um, derectior -or -us, derectissimus -a -um","headword":"derectus","letter":"d","pos":"adjective","posGroup":"adjective","english":"straight/not curved; moving straight forward/in straight line; direct/absolute","forms":["derectis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Fossam pedum XX {{derectis}} lateribus duxit, ut eius fossae solum tantundem pateret quantum summae fossae labra distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"derelictum","latin":"derelictum, derelicti","headword":"derelictum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"that which has been given up/abandoned; (legal)","forms":["dērelictīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nactus es ex perditis atque ab omnī nōn modo fortūnā vērum etiam spē {{dērelictīs}} cōnflātam improbōrum manum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"derelinquere","latin":"(dērelinquō) dērelinquere (< relinquere)","headword":"dērelinquere","letter":"d","pos":"","posGroup":"other","english":"leave behind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"derelinquo","latin":"derelinquo, derelinquere, dereliqui, derelictus","headword":"derelinquo","letter":"d","pos":"verb","posGroup":"verb","english":"leave behind/abandon/discard; forsake/desert; neglect; leave derelict; bequeath","forms":["dērelīquerat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dein Micipsa fīlius rēgnum sōlus obtinuit, Mastanabalem et Hiempsalem ex sē genuit, Iugurthamque, fīlium Mastanabalis frātris — quem Masinissa, quod ortus ex concubīnā erat, prīvātum {{dērelīquerat}} — eōdem cultū quō līberōs suōs domī habuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"derideo","latin":"derideo, deridere, derisi, derisus","headword":"derideo","letter":"d","pos":"verb","posGroup":"verb","english":"mock/deride/laugh at/make fun of; be able to laugh, escape, get off scot free","forms":["dērīdēbant","dērīdēbat","dērīdēns","dērīdent","deridentur","dērīdēs","dērīdet","dērīsī","dērīsit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dōrippa: “Mē {{dērīdēs}}!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"deridere","latin":"(dērīdeō) dērīdēre, dērīsisse, dērīsum","headword":"dērīdēre","letter":"d","pos":"verb","posGroup":"verb","english":"laugh at; to mock, laugh at","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"deridiculum","latin":"deridiculum, deridiculi","headword":"deridiculum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"laughing-stock; absurdity, ridiculous thing; ridiculousness; ridicule (L+S)","forms":["dērīdiculī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: Obsecrō, ēcastor, quid tū mē dērīdiculī grātia","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"derigesco","latin":"derigesco, derigescere, derigui, -","headword":"derigesco","letter":"d","pos":"verb","posGroup":"verb","english":"freeze, become/grow stiff/rigid (through fear); grow quite/very still","forms":["dēriguēre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{dēriguēre}} oculī, calidusque ē corpore sanguis,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"deripio","latin":"deripio, deripere, deripui, dereptus","headword":"deripio","letter":"d","pos":"verb","posGroup":"verb","english":"seize/grab/snatch/take away; tear/pull off/down; remove (violently)","forms":["dēripiunt"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tergora {{dēripiunt}} costīs et vīscera nūdant;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"derisus","latin":"derisus, derisus","headword":"derisus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"mockery; scorn, derision","forms":["dērīsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nisi gēns nostra in Deum peccāvisset, numquam in hās miseriās incīdissēmus; sed mox Deus, meō frātrumque meōrum sanguine plācātus, genfī nostrae reconciliābitur, et nōs post mortem patienter tolerātam aetēma vlta dōnābit.\"Tum Antiochus indignē ferēns sē {{dērīsum}} esse, in illum exquīsītō suppliciō necāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"derivo","latin":"derivo, derivare, derivavi, derivatus","headword":"derivo","letter":"d","pos":"verb","posGroup":"verb","english":"draw/lead off (river/fluid), divert/turn aside; derive/draw on; form derivative","forms":["derivata"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hoc intermisso spatio duas fossas quindecim pedes latas eadem altitudine perduxit, quarum interiorem campestribus ac demissis locis aqua ex flumine {{derivata}} complevit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"des","latin":"des","headword":"des","letter":"d","pos":"numeral","posGroup":"numeral","english":"two thirds; [bes alter => one and two thirds]","forms":["dēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ambieratque Venus superōs collōque parentis\ncircumfūsa suī, \"numquam mihi\" dīxerat, \"ullō\ntempore dūre pater, nunc sīs mītissimus, optō,\nAenēaeque meō, quī tē dē sanguine nostrō\nfēcit avum, quamvīs parvum {{dēs}}, optime, nūmen,\ndummodo dēs aliquod! . . .\" Tum pater \"estis\" ait,\n\"caelestī mūnere dignī, quaeque petis prō quōque petis:\ncape, nāta, quod optās!\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"desaevio","latin":"desaevio, desaevire, desaevivi, desaevitus","headword":"desaevio","letter":"d","pos":"verb","posGroup":"verb","english":"rage, rave furiously; work off/vent one's rage","forms":["dēsaevit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dum pelagō {{dēsaevit}} hiems et aquōsus Ōrīōn,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"descendens","latin":"descendens, descendentis","headword":"descendens","letter":"d","pos":"noun","posGroup":"noun","english":"descendant; (pl.) posterity, descendants","forms":["dēscendēns","dēscendentēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iacobus vīdit in somnīs scālam, quae innīxa terrae pertinēbat ad caelum, atque Angelōs Deī adscendentēs et {{dēscendentēs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"descendere","latin":"(dēscendō) dēscendere, dēscendisse, dēscēnsum","headword":"dēscendere","letter":"d","pos":"","posGroup":"other","english":"descend","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"descendo","latin":"descendo, descendere, descendi, descensus","headword":"descendo","letter":"d","pos":"verb","posGroup":"verb","english":"descend, climb/march/come/go/flow/run/hang down; dismount; penetrate/sink","forms":["dēscendam","dēscendāmus","descendant","dēscendās","dēscendat","Dēscende","Dēscendēbat","dēscendere","dēscenderent","descenderet","dēscendērunt","dēscendī","dēscendisse","dēscendisset","dēscendit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum Vercingetorix nihilo minus in aequum locum {{descenderet}}, levi facto equestri proelio atque secundo in castra exercitum reduxit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"descensus","latin":"descensus, descensus","headword":"descensus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"decent, climbing/getting down; action/means/way of descent; lying down (rude)","forms":["dēscēnsus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur, ubi iter eius ex perfugīs cognōvit, castra properē mōvit ac sub ipsīs rādīcibus montium cōnsēdit, quā illī {{dēscēnsus}} erat in Galliam properantī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"desciscere","latin":"(dēscīscō) dēscīscere, -īvisse, -ītum","headword":"dēscīscere","letter":"d","pos":"verb","posGroup":"verb","english":"defect, withdraw; to desert, revolt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"descisco","latin":"descisco, desciscere, descivi, descitus","headword":"descisco","letter":"d","pos":"verb","posGroup":"verb","english":"desert/defect/revolt; deviate/abandon standard/principle; degenerate; fall away","forms":["dēscīscerent","dēscīvērunt","dēscīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At cum senuisset, et fīliī eius ā mōribus paternīs {{dēscīscerent}}, populus, novitātis amāns, ab illō rēgem petīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"describere","latin":"(dēscrībō) dēscrībere (< scrībere)","headword":"dēscrībere","letter":"d","pos":"","posGroup":"other","english":"draw, describe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"describo","latin":"describo, describere, descripsi, descriptus","headword":"describo","letter":"d","pos":"verb","posGroup":"verb","english":"describe/draw, mark/trace out; copy/transcribe/write; establish (law/right)","forms":["dēscrībere","dēscrīberētur","dēscrībitur","Dēscrībō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Exiit ēdictum ā Caesare Augustō ut {{dēscrīberētur}} ūniversus orbis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"descriptum","latin":"descriptum, descripti","headword":"descriptum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"diary, journal; things (pl.) recorded, writings","forms":["dēscrīptum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Lentulō sē habēre ad Catilīnam mandāta et litterās: ut servōrum praesidiō ūterētur, ut ad urbem quam prīmum cum exercitū accēderet! — id autem eō cōnsiliō, ut, cum urbem ex omnibus partibus, quemadmodum {{dēscrīptum}} distribūtumque erat, incendissent caedemque īnfīnītam cīvium fēcissent, praestō esset ille, quī et fugientēs exciperet et sē cum hīs urbānīs ducibus coniungeret!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"deseco","latin":"deseco, desecare, desecui, desectus","headword":"deseco","letter":"d","pos":"verb","posGroup":"verb","english":"sever; cut off (limb/boundary); cut/carve from/out/away; cut/reap/mow (crop)","forms":["desectis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus {{desectis}} aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deserere","latin":"(dēserō) dēserere, dēseruisse, dēsertum","headword":"dēserere","letter":"d","pos":"verb","posGroup":"verb","english":"leave, desert; to abandon, desert","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"deserit","latin":"dēserit","headword":"dēserit","letter":"d","pos":"verb","posGroup":"verb","english":"abandons, deserts","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"desero","latin":"desero, deserere, deserui, desertus","headword":"desero","letter":"d","pos":"verb","posGroup":"verb","english":"leave/depart/quit/desert; forsake/abandon/give up; withdraw support, let down","forms":["deserantur","dēserās","dēsere","deserendum","deserere","dēsererent","dēsererentur","dēsereret","dēseret","dēseris","dēserit","dēseritur","dēseruerat","dēseruēre","dēseruērunt","dēseruisset","dēseruit","dēserunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis {{deserantur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deserta","latin":"deserta, desertae","headword":"deserta","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"abandoned/deserted wife","forms":["dēsertā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"désertà nocte iacébis : nocte dēsertā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"desertus","latin":"dēsertus, -a, -um","headword":"dēsertus","letter":"d","pos":"adjective","posGroup":"adjective","english":"deserted","forms":["dēsertae","dēsertam","dēsertās","dēsertīs","dēsertō","dēsertus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Erat in dēsertō spēluncā vastō recessū patēns: ibi Dāvīd cum suīs comitibus in interiōre parte latēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"desiderans","latin":"desiderans, desiderantis (gen.), desiderantior -or -us, desiderantissimus -a -um","headword":"desiderans","letter":"d","pos":"adjective","posGroup":"adjective","english":"greatly desired or missed; (SUPER of absent/dead persons)","forms":["dēsīderantem","dēsīderantēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Charōn eum frūstrā ōrantem et flūmen Stygem iterum trānsīre {{dēsīderantem}} prohibuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"desiderare","latin":"(dēsīderō) dēsīderāre, -āvisse, -ātum","headword":"dēsīderāre","letter":"d","pos":"verb","posGroup":"verb","english":"long for, miss; to long for, miss","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"desiderat","latin":"dēsīderat","headword":"dēsīderat","letter":"d","pos":"verb","posGroup":"verb","english":"desires, longs for","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"desideratus","latin":"desideratus, desiderata -um, desideratior -or -us, desideratissimus -a -um","headword":"desideratus","letter":"d","pos":"adjective","posGroup":"adjective","english":"desired, longed for, sought after; missed (the dead), regretted","forms":["desiderati"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eo die milites sunt paulo minus septingenti {{desiderati}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"desiderium","latin":"dēsīderium, -ī","headword":"dēsīderium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"desire, longing; longing, desire","forms":["dēsīderiō","dēsīderium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum vērō iam procul sōlis lūcem aspiceret, neque ūllum sonum post sē audīret, dubitāns an Eurydicē sē sequerētur, tantō metū captus est, ut iam {{dēsīderium}} uxōris rūrsus videndī, quō ārdēbat, retinēre nōn posset: cōnstitit igitur nōn iam patiēns morae, et ferē sub ipsā lūce, amōre victus, rēs pexit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"desidero","latin":"desidero, desiderare, desideravi, desideratus","headword":"desidero","letter":"d","pos":"verb","posGroup":"verb","english":"desire/want, long/wish for, request, require/need; miss, lack; lose","forms":["dēsīderābam","dēsīderābat","dēsīderāmus","dēsīderant","dēsīderās","dēsīderat","desideratis","dēsīderātum","dēsīderāverat","dēsīderāvit","dēsidērem","dēsīderēs","dēsīderō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero {{desideratis}} quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"desidia","latin":"desidia, desidiae","headword":"desidia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"idleness, slackness; inactivity; remaining in place; leisure; indolence, sloth","forms":["dēsidiā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed postquam luxū atque dēsidiā cīvitās corrupta est, rūrsus rēs pūblica magnitūdine suā imperātōrum atque magistrātuum vitia sustentābat ac, sīcuti esset effēta pariendō, multīs tempestātibus haud sānē quisquam Rōmae virtūte magnus fuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"designare","latin":"(dēsignō) dēsignāre","headword":"dēsignāre","letter":"d","pos":"","posGroup":"other","english":"mark out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"designatus","latin":"designatus, designata, designatum","headword":"designatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"designate/elect; appointed (but not yet installed magistrate); expected (baby)","forms":["dēsignātī","dēsignātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum prīmum circō quī nunc Maximus dīcitur {{dēsignātus}} locus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"designo","latin":"designo, designare, designavi, designatus","headword":"designo","letter":"d","pos":"verb","posGroup":"verb","english":"mark; point/mark/trace out, outline/describe; indicate/designate/denote","forms":["dēsignat","dēsignātō","dēsignātum","dēsignāverat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ubī pervēnērunt ambō in locum {{dēsignātum}}, Abrahamus exstrūxit āram, disposuit ligna, alligāvit Isaacum super struem lignōrum, deinde arripuit gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"desilio","latin":"desilio, desilire, desilui, desultus","headword":"desilio","letter":"d","pos":"verb","posGroup":"verb","english":"leap/jump down, dismount, alight; (chariot); jump headlong, venture heedlessly","forms":["dēsilīret","dēsiliunt","dēsiluit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Simul Rebecca, cōnspicāta virum dēambulantem, {{dēsiluit}} ē camēlō, et interrogāvit Eliezerem: quis est ille vir?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"desilire","latin":"(dēsiliō) dēsilīre, dēsiluisse","headword":"dēsilīre","letter":"d","pos":"verb","posGroup":"verb","english":"jump down; to leap down","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"desilit","latin":"dēsilit","headword":"dēsilit","letter":"d","pos":"verb","posGroup":"verb","english":"jumps down","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"desinit","latin":"dēsinit","headword":"dēsinit","letter":"d","pos":"verb","posGroup":"verb","english":"stops, ceases","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"desino","latin":"dēsinō, dēsinere","headword":"dēsinō","letter":"d","pos":"verb","posGroup":"verb","english":"finish, stop, end","forms":["dēsinam","dēsinant","dēsine","dēsinēbat","dēsinere","dēsinit","dēsinitō","dēsinunt","dēsitūrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Aemilia: “{{Dēsine}} plōrāre, Iūlia!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"desipere","latin":"(dēsipiō) dēsipere, -uisse","headword":"dēsipere","letter":"d","pos":"","posGroup":"other","english":"be out of one’s mind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"desipio","latin":"desipio, desipere, desipui, -","headword":"desipio","letter":"d","pos":"verb","posGroup":"verb","english":"act/be foolish; be out of one's mind/lose one's reason/lack rational thought","forms":["dēsiperet"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēx, quasi anus aetāte {{dēsiperet}}, dērīsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"desistere","latin":"(dēsistō) dēsistere, dēstitisse","headword":"dēsistere","letter":"d","pos":"verb","posGroup":"verb","english":"leave off, cease; to stop, cease","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"desisto","latin":"dēsistō, -ere, -stitī, -stitum","headword":"dēsistō","letter":"d","pos":"verb","posGroup":"verb","english":"desist, stop, leave off","forms":["dēsistam","dēsiste","dēsistēbāmus","dēsistere","dēsisterem","dēsistis","dēsistunt","dēstiterit","destiterunt","dēstitī","destitit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non {{destitit}} tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"desolatus","latin":"desolatus, desolata, desolatum","headword":"desolatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"desolate; empty","forms":["dēsōlāta"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae vidētur sistī et corrigī posse: certē satis cōnstat prope iam {{dēsōlāta}} templa coepisse celebrārī, et sacra sollemnia diū intermissa repetī, passimque vēnīre carnem victimārum, cuius adhūc rārissimus ēmptor inveniēbātur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"despectus","latin":"despectus, despectus","headword":"despectus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"view down/from above; prospect/panorama; spectacle; (object of) contempt/scorn","forms":["despectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec procul ex oppido videbantur, ut erat a Gergovia {{despectus}} in castra, neque tanto spatio certi quid esset explorari poterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"desperare","latin":"(dēspērō) dēspērāre, -āvisse, -ātum","headword":"dēspērāre","letter":"d","pos":"verb","posGroup":"verb","english":"lose hope; to despair","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"desperatio","latin":"dēspērātiō, -tiōnis ( f.)","headword":"dēspērātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"desperation","forms":["dēspērātiō","dēspērātiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Utrimque in pugnam prōcursum est; hinc spēs, hinc dēspērātiō animōs irrītābat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"desperatus","latin":"desperatus, desperata -um, desperatior -or -us, desperatissimus -a -um","headword":"desperatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"desperate/hopeless; despairing/lacking hope; desperately ill/situated; reckless","forms":["desperata"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At ei qui ab Alesia processerant maesti prope victoria {{desperata}} se in oppidum receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"despero","latin":"despero, desperare, desperavi, desperatus","headword":"despero","letter":"d","pos":"verb","posGroup":"verb","english":"despair (of); have no/give up hope (of/that); give up as hopeless (of cure)","forms":["dēspērābat","desperans","desperant","dēspērantis","dēspērāre","dēspērāret","desperatis","dēspērāverīs","desperavit","dēspērēmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, {{desperatis}} hominibus, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"despicere","latin":"(dēspiciō) dēspicere, dēspexisse, dēspectum","headword":"dēspicere","letter":"d","pos":"verb","posGroup":"verb","english":"look down (at); to look down on","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"despicio","latin":"dēspiciō","headword":"dēspiciō","letter":"d","pos":"verb","posGroup":"verb","english":"to despise, look down on","forms":["dēspecta","dēspectī","dēspexeram","dēspexit","despicere","dēspiciēbam","dēspiciēbat","dēspiciēns","dēspiciunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius indicio vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem {{despicere}} potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"despicit","latin":"dēspicit","headword":"dēspicit","letter":"d","pos":"verb","posGroup":"verb","english":"looks down on","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"despolio","latin":"despolio, despoliare, despoliavi, despoliatus","headword":"despolio","letter":"d","pos":"verb","posGroup":"verb","english":"rob/plunder; despoil (of); strip, deprive of clothing/covering; (for flogging)","forms":["dēspoliāmur","dēspoliātur"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn ﬁt mora: {{dēspoliātur}} cocus, atque inter duôs tortôrës maestus cônsistit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"despondeo","latin":"despondeo, despondere, despondi, desponsus","headword":"despondeo","letter":"d","pos":"verb","posGroup":"verb","english":"betroth, promise (woman) in marriage; pledge, promise; despair/yield/give up","forms":["dēspondit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec, cum quaererētur gener Tarquiniō, quisquam ē iuventūte Rōmānā ūllā arte cum Serviō cōnferrī potuit, fīliamque eī suam rēx {{dēspondit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"despondere","latin":"(dēspondeō) dēspondēre (< spondēre)","headword":"dēspondēre","letter":"d","pos":"","posGroup":"other","english":"betroth, engage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"desponso","latin":"desponso, desponsare, desponsavi, desponsatus","headword":"desponso","letter":"d","pos":"verb","posGroup":"verb","english":"betroth, promise in marriage","forms":["dēspōnsa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cui soror virgō, quae {{dēspōnsa}} ūnī ex Curiātiīs fuerat, obvia ante portam Capēnam fuit, cognitōque super umerōs frātris palūdāmentō spōnsī, quod ipsa cōnfēcerat, solvit crīnēs et flēbiliter nōmine spōnsum mortuum appellat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"destinare","latin":"(dēstinō) dēstināre","headword":"dēstināre","letter":"d","pos":"","posGroup":"other","english":"designate, establish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"destinata","latin":"destinata, destinatae","headword":"destinata","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"betrothed female; bride","forms":["dēstinātā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iosue, dēvictīs omnibus Palestīnae populīs, Hebraeōs in sēde dēstinātā collocāvit, agrōs et oppida captā singulīs tribubus dīvīsit, et mortuus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"destinatus","latin":"destinatus, destinata, destinatum","headword":"destinatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"stubborn/obstinate; determined/resolved/resolute/firm; destined (L+S); fixed","forms":["dēstinātam","destinatos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus corona militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo advolaret aut interdiu tela in nostros operi {{destinatos}} coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"destino","latin":"destino, destinare, destinavi, destinatus","headword":"destino","letter":"d","pos":"verb","posGroup":"verb","english":"fix/bind/fasten down; fix (in mind), make up mind; aim/fix on target, mark out","forms":["dēstinantēs","dēstinās","dēstinat","destinaverant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum {{destinaverant}} tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"destitutus","latin":"destitutus, destituta, destitutum","headword":"destitutus","letter":"d","pos":"adjective","posGroup":"adjective","english":"destitute, devoid of; childless","forms":["dēstitūtī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Varia deinceps fuit Hebraeōrum fortūna prō variīs eōrum mōribus: iī saepe in Deum peccāvērunt; tunc dīvīnō praesidiō dēstitūtī ab hostibus superābantur; quotiēs ad Deum conversī eius auxilium implōrāvērunt, plācātus Deus eōs līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"destrictus","latin":"destrictus, destricta -um, destrictior -or -us, destrictissimus -a -um","headword":"destrictus","letter":"d","pos":"adjective","posGroup":"adjective","english":"strict, severe; uncompromising; unreserved; rigid (L+S); censorious","forms":["destrictis","dēstrictōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi aliquid ab eis iniri consili intellexissent, gladiis {{destrictis}} portas occupaverunt suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"destringo","latin":"destringo, destringere, destrinxi, destrictus","headword":"destringo","letter":"d","pos":"verb","posGroup":"verb","english":"strip off, remove by cutting; strip (clothes); scrape/rub down (w/strigil)","forms":["dēstrīnxit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Celeriter arcum sagittāsque manū corripuit, quae tēla gerēbat fīdus Achātēs, et prīmum ipsōs ducēs gregis {{dēstrīnxit}}, quam septem ingentia corpora humī iacēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"destruere","latin":"(dēstruō) dēstruere (< struere)","headword":"dēstruere","letter":"d","pos":"","posGroup":"other","english":"demolish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"destruo","latin":"destruo, destruere, destruxi, destructus","headword":"destruo","letter":"d","pos":"verb","posGroup":"verb","english":"demolish, pull/tear down; destroy, ruin; demolish/refute (arguments/evidence)","forms":["dēstruat","dēstrūcta","dēstrūctīs","dēstrūctum","dēstrūēbant","dēstrūxerimus","dēstrūxit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nisi pontem {{dēstrūxerimus}}, domus et templa tūta nōn erunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"desum","latin":"dēsum, deesse","headword":"dēsum","letter":"d","pos":"verb","posGroup":"verb","english":"fall short, be lacking","forms":["dēerant","Dēerat","dēerō","dēesse","deest","dēfuerat","dēfuerit","dēfuī","dēfuisse","dēfuit","dēfutūrum","dentīā","derint","dēsint","dēsit","dēsumus","dēsunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Vestīmenta eius sordida sunt, sanguis dē nāsō fluit, {{deest}} ūnus ē dentibus priōribus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"desuper","latin":"desuper","headword":"desuper","letter":"d","pos":"adverb","posGroup":"adverb","english":"from above, from overhead; up above","forms":["dēsuper"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aut hōc inclūsī lignō occultantur Achīvī,\naut haec in nostrōs fābricāta est māchina mūrōs\nīnspectūra domōs ventūraque {{dēsuper}} urbī,\naut aliquis latet error: equō nē crēdite, Teucrī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"detegere","latin":"(dētegō) dētegere (< tegō)","headword":"dētegere","letter":"d","pos":"","posGroup":"other","english":"uncover, disclose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"detego","latin":"detego, detegere, detexi, detectus","headword":"detego","letter":"d","pos":"verb","posGroup":"verb","english":"uncover/disclose/reveal; expose, lay bare; fleece; unsheathe; remove; unroof","forms":["dētēctam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Affectō deinde eō, cum prope ad ultimum fīnem vītae esset, {{dētēctam}} tandem sibi orīginem suam.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"detentus","latin":"detentus, detentus","headword":"detentus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"holding/keeping back; retention; detention","forms":["dētentus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat ibi in grabātō vir quīdam magnā {{dētentus}} Īnfirmitāte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"detergeo","latin":"detergeo, detergere, detersi, detersus","headword":"detergeo","letter":"d","pos":"verb","posGroup":"verb","english":"wipe/clean off/away; strip/trim/sheer/break/sweep off, rub/wipe clean; cancel","forms":["dētergēns","dēterget","dētersō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Servus caput mīlitis manū sustinet et, dum sanguinem {{dēterget}}, interrogat eum: “Quid est, amīce?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"deterget","latin":"dēterget, dētergēre","headword":"dēterget","letter":"d","pos":"verb","posGroup":"verb","english":"wipe off; wipes off, cleans","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"deterior","latin":"dēterior, -ius","headword":"dēterior","letter":"d","pos":"adjective","posGroup":"adjective","english":"worse; worse, lower","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"detero","latin":"detero, deterere, detrivi, detritus","headword":"detero","letter":"d","pos":"verb","posGroup":"verb","english":"rub/wear/file away/down; remove, rub off/out; wear down to smooth surface","forms":["dētrītum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quantō est facilius mihi sub tēctō vīvere et ōtiōsum largō satiārī cibō!” [Canis:] “Venī ergō mēcum!” Dum prōcēdunt, lupus ā catēnā collum {{dētrītum}} canī aspicit. [Lupus:] “Unde hoc, amīce?” [Canis:] “Nīl est.” [Lupus:] “Dīc, sōdēs, tamen!” [Canis:] “Quia videor ācer, alligant mē interdiū, lūce ut quiēscam, ut vigilem nox cum vēnerit: crepusculō solūtus quā vīsum est vāgor.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"deterreo","latin":"deterreo, deterrere, deterrui, deterritus","headword":"deterreo","letter":"d","pos":"verb","posGroup":"verb","english":"deter; frighten away; discourage (from), put/keep off, avert; frighten/terrify","forms":["dēterreantur","dēterrēbantur","dēterrēbat","dēterrēbātur","dēterrentur","dēterrēre","dēterret","dēterritā","deterritī","dēterritus","dēterruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Poena dīluviī nōn {{dēterruit}} hominēs ā vitiīs, sed brevī factī sunt peiōrēs quam prius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deterrere","latin":"(dēterreō) dēterrēre, dēterruisse, dēterritum","headword":"dēterrēre","letter":"d","pos":"verb","posGroup":"verb","english":"deter; to deter, frighten off","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"deterritus","latin":"dēterritus, -a, -um","headword":"dēterritus","letter":"d","pos":"adjective","posGroup":"adjective","english":"deterred","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"detestor","latin":"detestor, detestari, detestatus sum","headword":"detestor","letter":"d","pos":"verb","posGroup":"verb","english":"call down solemn curse on, execrate; detest/loathe; avert, ward off by entreaty","forms":["dētester"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nunc, ut ā mē, patrēs cōnscrīptī, quandam prope iūstam patriae querimōniam {{dētester}} ac dēprecer, percipite, quaesō, dīligenter quae dīcam, et ea penitus animīs vestrīs mentibusque mandāte!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"detineo","latin":"detineo, detinere, detinui, detentus","headword":"detineo","letter":"d","pos":"verb","posGroup":"verb","english":"detain, hold; hold off, keep away (from); hold prisoner; retain; occupy","forms":["dētinet","dētinuēre","dētinuērunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":".— sīcut, docet Epicūrus (-ī m) {{dētinet}}: innocué","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"detorqueo","latin":"detorqueo, detorquere, detorsi, detortus","headword":"detorqueo","letter":"d","pos":"verb","posGroup":"verb","english":"turn/twist/bend/pull away/aside; deflect; deviate (path); divert; sway","forms":["dētorquet"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"prōtinus ad rēgem cursus {{dētorquet}} Iarbān","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"detracto","latin":"detracto, detractare, detractavi, detractatus","headword":"detracto","letter":"d","pos":"verb","posGroup":"verb","english":"refuse (to undertake/undergo), decline, reject, evade, recoil from","forms":["dētrācta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed dē Lūcullō dīcam aliō locō, et ita dīcam, Quirītēs, ut neque vēra laus eī {{dētrācta}} ōrātiōne meā neque falsa afficta esse videātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"detrahere","latin":"(dētrahō) dētrahere, dētrāxisse, dētractum","headword":"dētrahere","letter":"d","pos":"","posGroup":"other","english":"pull off; pull off, remove","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"detraho","latin":"detraho, detrahere, detraxi, detractus","headword":"detraho","letter":"d","pos":"verb","posGroup":"verb","english":"drag/pull/strip/take down/away/off; remove; exclude, omit, cut out; subtract","forms":["dētractam","dētrahēbat","dētraheret","detrahi","dētrahit","dētrāxerat","dētrāxērunt","dētrāxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci deque his stramenta {{detrahi}} mulionesque cum cassidibus equitum specie ac simulatione collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"detrecto","latin":"detrecto, detrectare, detrectavi, detrectatus","headword":"detrecto","letter":"d","pos":"verb","posGroup":"verb","english":"refuse (to undertake/undergo), decline, reject, evade, recoil from","forms":["detrectandam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo tuta, neu suis sint ad {{detrectandam}} militiam receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"detrimentum","latin":"dētrīmentum, -ī","headword":"dētrīmentum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"harm, loss; loss, damage","forms":["dētrīmentī","detrimento"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto {{detrimento}} et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"detrudo","latin":"detrudo, detrudere, detrusi, detrusus","headword":"detrudo","letter":"d","pos":"verb","posGroup":"verb","english":"push/thrust/drive/force off/away/aside/from/down; expel; dispossess; postpone","forms":["dētrūdunt","dētrūsērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubī Iōsēphus pervēnit ad frātrēs suōs, dētrāxērunt eī togam quā indūtus erat, et {{dētrūsērunt}} eum in foveam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deturbo","latin":"deturbo, deturbare, deturbavi, deturbatus","headword":"deturbo","letter":"d","pos":"verb","posGroup":"verb","english":"upset/topple, bring tumbling down; dislodge; strike/beat to ground","forms":["deturbant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Multitudine telorum ex turribus propugnantes {{deturbant}}, aggere et cratibus fossas explent, falcibus vallum ac loricam rescindunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"deucalion","latin":"Deucalion, Deucalionis","headword":"Deucalion","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Deucalion; (survivor of the great flood with wife Pyrrha)","forms":["Deucaliōn","Deucaliōnem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Iuppiter igitur postquam {{Deucaliōnem}} eiusque uxōrem, Pyrrham nōmine, quōs Mercurius praeter cēterōs servandōs esse cēnsēbat, in rate quādam posuit, ventōs omnēs līberāvit, nūbibusque ātrīs tōtum caelum operuit; deinde ingentēs imbrēs dē caelō mīsit, et aquās tōtīus orbis ita auxit, ut omnēs terrae mergerentur: omnia mare erant, et lītora quoque marī dēerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"deurere","latin":"(deūrō) deūrere (< ūrere)","headword":"deūrere","letter":"d","pos":"","posGroup":"other","english":"burn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deuro","latin":"deuro, deurere, deussi, deustus","headword":"deuro","letter":"d","pos":"verb","posGroup":"verb","english":"burn down/up/thoroughly, consume; destroy/wither/blast (of cold/serpent breath)","forms":["deūrit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum illa foculum cōram cum ignī appōnit, trēs librōs ex novem {{deūrit}}, et 'ecquid reliquōs sex eōdem pretiō emere vellet?' rēgem interrogāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"deus","latin":"deus, -ī","headword":"deus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"god (pl. deī/diī/dī, voc.deus)","forms":["dee","deī","deīs","deō","deōrum","deōs","deum","deus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quot oculī sunt deō Iānō?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"devehere","latin":"(dēvehō) dēvehere (< vehere)","headword":"dēvehere","letter":"d","pos":"","posGroup":"other","english":"carry, convey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deveho","latin":"deveho, devehere, devexi, devectus","headword":"deveho","letter":"d","pos":"verb","posGroup":"verb","english":"carry/convey/transport/take/remove; carry away/downstream/by sea; sail (off w/)","forms":["dēveheret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Oroandem dēnique Crētēnsem, cui nōta Thrāciae ōra erat quia mercātūrās in eā regiōne fēcerat, appellat, 'ut sē sublātum in lembum ad Cotym {{dēveheret}}.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"devenio","latin":"devenio, devenire, deveni, deventus","headword":"devenio","letter":"d","pos":"verb","posGroup":"verb","english":"come to, arrive/turn up (at); go (to see/stay); reach; land; turn to; extend to","forms":["Dēvēnēre","dēvēnērunt","dēvēnit","dēveniunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"IOae morte rēgnum ad Amasfam fīlium {{dēvēnit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"devenire","latin":"(dēveniō) dēvenīre (< venīre)","headword":"dēvenīre","letter":"d","pos":"","posGroup":"other","english":"come, arrive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"deversor","latin":"deversor, deversari, deversatus sum","headword":"deversor","letter":"d","pos":"verb","posGroup":"verb","english":"lodge, stay, have lodgings; put up at an inn","forms":["dēversēmur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ut appropinquāvērunt urbī, quae vocābātur Ecbatāna, dīxit Tobiās angelō: “Apud quem vīs ut {{dēversēmur}} in hāc urbe?” Cui angelus: “Est hic” inquit “vir quīdam cognātus tuus, nōmine Rāgūēl: is nōs hospitiō excipiet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"deverto","latin":"deverto, devertere, deverti, deversus","headword":"deverto","letter":"d","pos":"verb","posGroup":"verb","english":"divert, turn away/aside/in/off; detour/digress/branch off; lodge/put up","forms":["Deversī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deversī in patriam IUdaeī, compositō urbis stātiī, nōn iam egēs habuēre, sed imperium penes pontificēs fuit: tribūta tamen pēnsitārunt prīmum Persīs, deinde Graecīs, post dēvictum ab Alexandra Darīum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"devexus","latin":"devexus, devexa, devexum","headword":"devexus","letter":"d","pos":"adjective","posGroup":"adjective","english":"sloping/inclining downwards/downhill/away; steep; shelving; declining/sinking","forms":["devexa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eius adventu ex colore vestitus cognito, quo insigni in proeliis uti consuerat, turmisque equitum et cohortibus visis quas se sequi iusserat, ut de locis superioribus haec declivia et {{devexa}} cernebantur, hostes proelium committunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"devincere","latin":"(dēvincō) dēvincere (< vincere)","headword":"dēvincere","letter":"d","pos":"","posGroup":"other","english":"defeat completely","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"devincio","latin":"devincio, devincire, devinxi, devinctus","headword":"devincio","letter":"d","pos":"verb","posGroup":"verb","english":"tie/bind up, hold/fix fast; subjugate; obligate/oblige/constrain; unite closely","forms":["dēvīnxit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Atque hōrum trium generum quodvīs, sī teneat illud vinculum quod prīmum hominēs inter sē reī pūblicae societāte {{dēvīnxit}}, nōn perfectum illud quidem neque meā sententiā optimum est, sed tolerābile tamen.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"devincire","latin":"(dēvinciō) dēvincīre (< vincīre)","headword":"dēvincīre","letter":"d","pos":"","posGroup":"other","english":"bind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"devinco","latin":"devinco, devincere, devici, devictus","headword":"devinco","letter":"d","pos":"verb","posGroup":"verb","english":"subdue; defeat decisively, conquer/overcome entirely","forms":["dēvīcerat","dēvīcit","dēvīctī","dēvictīs","dēvictō","dēvictōs","dēvictum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iosue, {{dēvictīs}} omnibus Palestīnae populīs, Hebraeōs in sēde dēstinātā collocāvit, agrōs et oppida captā singulīs tribubus dīvīsit, et mortuus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"devocare","latin":"(dēvocō) dēvocāre","headword":"dēvocāre","letter":"d","pos":"","posGroup":"other","english":"call away, divert","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"devolo","latin":"devolo, devolare, devolavi, devolatus","headword":"devolo","letter":"d","pos":"verb","posGroup":"verb","english":"fly/swoop/drop down (on to); hurry/rush/hasten/fly down/away (to)","forms":["dēvolant"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{dēvolant}} anguēs iubātī deorsum in impluvium duo","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"devolvo","latin":"devolvo, devolvere, devolvi, devolutus","headword":"devolvo","letter":"d","pos":"verb","posGroup":"verb","english":"roll/fall/tumble down; roll off; fall/sink back; fall into","forms":["dēvolvere"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Saepe vī magnā surgere et magnōs montēs corpore {{dēvolvere}} temptat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"devorare","latin":"(dēvorō) dēvorāre, dēvorāvisse, dēvorātum","headword":"dēvorāre","letter":"d","pos":"verb","posGroup":"verb","english":"swallow up, devour; to devour","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"devoro","latin":"dēvorō (1)","headword":"dēvorō","letter":"d","pos":"verb","posGroup":"verb","english":"consume, devour; devour, swallow","forms":["dēvorābat","dēvorandōs","dēvorāre","dēvorat","dēvorāte","devoratis","dēvorātūrus","dēvorāvit","dēvoret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Occīdāmus illum et prōiiciāmus in puteum; dīcēmus patrī: fera {{dēvorāvit}} Iōsēphum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"devoveo","latin":"dēvoveō, -ēre, -vōvī, -vōtum","headword":"dēvoveō","letter":"d","pos":"verb","posGroup":"verb","english":"devote","forms":["dēvōta","dēvoveās","dēvovēbō","dēvōvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Ē sther:\"Meam, ō rēx, meaeque gentis salūtem precor, nam crūdēlis iste Amān nōs {{dēvōvit}} necī.\"Quā rē permōtus est As suerus, audiēnsque crucem ab eō parātam esse Mardochaēō, Amanem ipsum eīdem crucī iussit affigī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dexter","latin":"dexter, -tra, -trum","headword":"dexter","letter":"d","pos":"adjective","posGroup":"adjective","english":"right, f. the right (hand); right (hand); right, on the right; right, skilful","forms":["dexter","dexteram","dexterās","dexterius","dextro"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas glaebas in ignem e regione turris proiciebat; scorpione ab latere {{dextro}} traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dextera","latin":"dextera, dexterae","headword":"dextera","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"right hand; weapon/greeting/shaking hand; right side; soldier","forms":["dextera"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fēcerat haec [fāma] nōtum Graiās cum mīlite fortī adventāre ratēs neque inexspectātus in armīs hostis adest; prohibent aditūs lītusque tuentur Trōes, et magnō quid Achāica {{dextera}} posset sanguine sēnsērunt, et iam Phrygia rubēbant lītora, iam lētō prōlēs Neptūnia, Cygnus, mīlle virōs dederat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dextra","latin":"dextra, -ae","headword":"dextra","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"right hand","forms":["dextra","dextrae","dextram","dextrās","dextris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus expositis signum dat et ab {{dextra}} parte alio ascensu eodem tempore Aeduos mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dextrum","latin":"dextrum, dextri","headword":"dextrum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"right hand; right-hand side","forms":["dextrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ego putō bracchium eius {{dextrum}} tam dolēre quam tergum meum!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dia","latin":"dia, diae","headword":"dia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"goddess","forms":["Dīa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"quà brevis aequoreīs {{Dīa}} ferītur aquīs;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"diadema","latin":"diadema, diadematis","headword":"diadema","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"diadem/crown; ornamental headband; (sign of sovereignty); dominion; preeminence","forms":["diadēma"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hic, prīmus omnium post capfīvitātem, rēgium nōmen sūmpsit, capifique {{diadēma}} imposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dialectica","latin":"dialectica, dialecticae","headword":"dialectica","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dialectics, logic; art of logic/reasoning","forms":["dialecticīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"An tū {{dialecticīs}} nōn imbūtus quidem es?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"dialis","latin":"Dialis, Dialis, Diale","headword":"Dialis","letter":"d","pos":"adjective","posGroup":"adjective","english":"of Jupiter; of flamen Dialis; heavenly/aerial; [flamen ~ => Roman chief priest]","forms":["diāle","Diālis"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scissa lautum noven- {{diāle}} servô suô misellô faciêbat, quem mortuum manū rnîserat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"diana","latin":"Diāna, -ae","headword":"Diāna","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"Diana (goddess of the moon and the hunt)","forms":["Diāna","Diānae","Diānam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ita nātī sunt Apollō et {{Diāna}}, Lātōnae līberī, quōs ipsa valdē amābat; neque iam ab īnsulā discēdere volēbat: at inde quoque necesse fuit fugere: nam Iūnō eam persequēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dicare","latin":"(dicō) dicāre","headword":"dicāre","letter":"d","pos":"","posGroup":"other","english":"dedicate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dicio","latin":"diciō, -ōnis ( f.)","headword":"diciō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dominion, power","forms":["diciōne","diciōnem","diciōnis"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"in {{diciōnem}} atque in arbitrātum cūnctī Thēbānō poplō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"dicis","latin":"dicis, dicis","headword":"dicis","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"form; [~ causa/gratia (only) => for the sake of appearance or judicial form]","forms":["dīcis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lepidus: “Quid {{dīcis}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dicit","latin":"dīcit, dīcere","headword":"dīcit","letter":"d","pos":"","posGroup":"other","english":"say, call, speak","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"dicitare","latin":"(dicitō) dicitāre","headword":"dicitāre","letter":"d","pos":"","posGroup":"other","english":"dictate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dico","latin":"dīcō, -ere, dīxī, dictum","headword":"dīcō","letter":"d","pos":"verb","posGroup":"verb","english":"say, speak, tell","forms":["dīc","dicābō","dīcam","dīcāmus","dīcant","dicantur","dīcar","dicāre","dicās","dīcat","dicātum","dīcātur","dicāvit","dīcē","dīcēbam","dicebant","dīcēbantur","dīcēbās","dīcēbat","dīcēbātur","dīcēmus","dīcenda","dīcendī","dīcendō","dīcendum","dīcēns","dīcente","dīcentem","dīcentēs","dīcentium","dīcere","dīcerem","dīcerent","dicerentur","dīcerēs","dīceret","dīcerētur","dīceris","dīcēs","dīcet","dīcētis","dici","dīcimus","dīcit","dīcite","dīcitis","dīcitō","dīcitur","dīcō","Dictae","dictū","dictūrī","dictūrōs","dictūrum","dicturus","dīcundī","dicunt","dīcuntur","dīxeram","dīxerās","dīxerat","dīxerim","dīxerīs","dīxerit","dīxerītis","dīxerō","dīxērunt","dīxī","diximus","dixisse","dīxissem","dīxissent","dīxisset","dīxistī","dīxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In primis rationem esse habendam {{dicunt}}, prius quam eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dictare","latin":"dictāre","headword":"dictāre","letter":"d","pos":"verb","posGroup":"verb","english":"to dictate","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"dictator","latin":"dictātor, -ōris (m.)","headword":"dictātor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dictator; dictator, commander with royal power","forms":["dictātor","dictātōre","dictātōrem","dictātōrī","dictātōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Albānī Mettium Fūfētium {{dictātōrem}} creant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dictatum","latin":"dictatum, dictati","headword":"dictatum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"things dictated (pl.); dictated lessons or exercises; lessons; precepts/rules","forms":["dictātum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et ego in prīmā classe {{dictātum}} accēpī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"dictatura","latin":"dictātūra, -ae","headword":"dictātūra","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dictatorship","forms":["dictātūra"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōnō annō post rēgēs exāctōs, cum gener Tarquinī ad iniūriam socerī vindicandam ingentem collēgisset exercitum, nova Rōmae dignitās est creāta, quae {{dictātūra}} appellātur, maior quam cōnsulātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dictitare","latin":"dictitāre","headword":"dictitāre","letter":"d","pos":"verb","posGroup":"verb","english":"to say repeatedly, keep saying","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"dictito","latin":"dictito, dictitare, dictitavi, dictitatus","headword":"dictito","letter":"d","pos":"verb","posGroup":"verb","english":"repeat; persist in saying, keep on saying/speaking of; say/plead/call often","forms":["dictitābat","dictitāns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Intereā Dēmētrium rēgem interrēcit Alexander, quī sē Antiochī fllium {{dictitābat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dicto","latin":"dictō, dictāre","headword":"dictō","letter":"d","pos":"verb","posGroup":"verb","english":"dictate","forms":["dicta","dictat","Dictāvit","dictō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Vix haec verba {{dicta}} erant, cum Tlēpolemus per forēs apertās currit, dominum iacentem tollit eumque extrā forēs portat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dictum","latin":"dictum, -ī","headword":"dictum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"saying","forms":["dictis","dictum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ac variis {{dictis}} sententiis, quarum pars deditionem, pars, dum vires suppeterent, eruptionem censebat, non praetereunda oratio Critognati videtur propter eius singularem et nefariam crudelitatem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dictus","latin":"dictus, dictus","headword":"dictus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"speech; speaking, saying (action); word (Ecc); command","forms":["dictus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Intereā Mathathīās mortuus est, moriēnsque exercituī prae:Iēcit Iiidam fīlium, quī {{dictus}} est Machabaeus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dido","latin":"dido, didere, dididi, diditus","headword":"dido","letter":"d","pos":"verb","posGroup":"verb","english":"distribute, deal out, disseminate; spread, diffuse; spread abroad (L+S)","forms":["dīdit","Dīdō","Dīdōne","Dīdōnī","Dīdōnis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In Āfricā Dīdō, rēgīna Phoenissa, habitat et regnat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dies","latin":"diēs, -ēī","headword":"diēs","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"(m.) day, date; day","forms":["die","diebus","diei","diem","dierum","dies","dīī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ubi ea {{dies}} venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"differo","latin":"differo, differre, distuli, dilatus","headword":"differo","letter":"d","pos":"verb","posGroup":"verb","english":"postpone/delay/differ; put off, keep waiting; give respite to; differ, disagree","forms":["differ","differant","differendō","differt","distulērunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem {{differt}}, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"differre","latin":"(differo) differre (< ferre)","headword":"differre","letter":"d","pos":"","posGroup":"other","english":"postpone, defer, differ","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"difficile","latin":"difficile","headword":"difficile","letter":"d","pos":"adverb","posGroup":"adverb","english":"with difficulty","forms":["difficile"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iūlia, quae lacrimās tenēre vix potest, “Sed nimis {{difficile}} est” inquit “id quod interrogor ā tē, Mārce; quamquam multum cōgitō, nōn possum rēctē respondēre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"difficilis","latin":"difficilis, -e","headword":"difficilis","letter":"d","pos":"adjective","posGroup":"adjective","english":"(sup.difficillimus) difficult, hard; difficult","forms":["difficilem","difficiles","difficilis","difficilius","difficillimae","difficillimō","difficillimum","difficillimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex omnibus fere partibus palus {{difficilis}} atque impedita cingebat, non latior pedibus quinquaginta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"difficultas","latin":"difficultās, -ātis ( f.)","headword":"difficultās","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"difficulty","forms":["difficultas","difficultate","difficultatem","difficultates","difficultatibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eo cum venisset, magna {{difficultate}} adficiebatur, qua ratione ad exercitum pervenire posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"difficulter","latin":"difficulter","headword":"difficulter","letter":"d","pos":"adverb","posGroup":"adverb","english":"with difficulty","forms":["difficulter"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed maximē adulēscentium familiāritātēs appetēbat: eōrum animī mollēs etiam et flūxī dolīs haud {{difficulter}} capiēbantur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"diffidens","latin":"diffidens, diffidentis (gen.), diffidentior -or -us, diffidentissimus -a -um","headword":"diffidens","letter":"d","pos":"adjective","posGroup":"adjective","english":"distrustful; lacking in confidence; without self-confidence (L+S); anxious","forms":["diffīdēns"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Volturcius prīmō cohortātus cēterōs gladiō sē ā multitūdine dēfendit; deinde, ubi ā lēgātīs dēsertus est, multa prius dē salūte suā Pomptīnum obtestātus, quod eī nōtus erat, postrēmō timidus ac vītae {{diffīdēns}} velut hostibus sēsē praetōribus dedit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"diffidere","latin":"(diffīdō) diffīdere, -īsum","headword":"diffīdere","letter":"d","pos":"","posGroup":"other","english":"distrust, despair of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diffido","latin":"diffido, diffidere, diffisus sum","headword":"diffido","letter":"d","pos":"verb","posGroup":"verb","english":"distrust; despair; (w/DAT) lack confidence (in), despair (of); expect not","forms":["Diffīde","diffīdēbat","diffidēre","diffīderent","diffīdet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Itaque addūctus est ad Saūlem, quī, cōnsīderātā eius aetāte, {{diffīdēbat}} pugnae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diffluere","latin":"(diffluō) diffluere","headword":"diffluere","letter":"d","pos":"","posGroup":"other","english":"overflow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diffluo","latin":"diffluo, diffluere, diffluxi, diffluctus","headword":"diffluo","letter":"d","pos":"verb","posGroup":"verb","english":"flow away; waste/wear/melt away; dissolve/disappear; pass out; ramble (speaker)","forms":["diffluentēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is dedit operam — sī modo id cōnsequī potuit — ut nimis redundantēs nōs et superfluentēs iuvenīlī quādam dīcendī impūnitāte et licentiā reprimeret et quasi extrā rīpās {{diffluentēs}} coercēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"diffugio","latin":"diffugio, diffugere, diffugi, diffugitus","headword":"diffugio","letter":"d","pos":"verb","posGroup":"verb","english":"scatter, disperse, dispel; flee/run away in different/several directions","forms":["diffugiunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"purpureās Aurōra forēs et plēna rosārum ātria: {{diffugiunt}} stēllae;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"diffundo","latin":"diffundo, diffundere, diffundi, diffusus","headword":"diffundo","letter":"d","pos":"verb","posGroup":"verb","english":"diffuse; spread/pour out/widely; bottle/draw off; squander, distribute lavishly","forms":["diffundente","diffundere","diffundit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Parcite paucārum {{diffundere}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"digero","latin":"dīgerō, -ere, dīgessī, dīgestum","headword":"dīgerō","letter":"d","pos":"verb","posGroup":"verb","english":"arrange, interpret","forms":["dīgerit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Trōia cadet sī nōs moram longam bellī ferre poterimus.” Novem volucrēs in novem annōs bellī {{dīgerit}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"digitus","latin":"digitus, -ī","headword":"digitus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"finger","forms":["digitī","digitis","digitō","digitōs","digitum","digitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Huc teretes stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius {{digitis}} quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dignitas","latin":"dignitās, -ātis ( f.)","headword":"dignitās","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"worthiness, dignity, rank","forms":["dignitas","dignitate","dignitatem","dignitātēs","dignitātī","dignitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res adversae auctoritatem minuunt, sic huius ex contrario {{dignitas}} incommodo accepto in dies augebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"digno","latin":"digno, dignare, dignavi, dignatus","headword":"digno","letter":"d","pos":"verb","posGroup":"verb","english":"deem/consider/think worthy/becoming/deserving/fit (to); deign, condescend","forms":["dignāre","dignētur","dignō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quī dē dominae suae morte nārrāvērunt; “Nescīs tū” inquiunt “mala quae sunt in hāc domō: dominus enim noster nihil tibi dīxit, nē animum tuum turbāret: coniūnx Admētī periit; quī tamen, nē cōgerēris aliam domum invenīre, tē excēpit, atque nōbīs imperāvit, ut tibi, hospitī omnī honōre dignō, cibōs appōnerēmus.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dignor","latin":"dignor, dignari, dignatus sum","headword":"dignor","letter":"d","pos":"verb","posGroup":"verb","english":"deem/consider/think worthy/becoming/deserving/fit (to); deign, condescend","forms":["dignor"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Venus: 'Haud equidem tālī mē {{dignor}} honōre;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"dignum","latin":"dignum, digni","headword":"dignum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"appropriate/suitable thing; worthy act; worth","forms":["dignum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cadmus vērō, cum mīlitum suōrum ossa, cruōre aspersa, sub arbore iacentia vidēret, nūllō modō dēterritus est nē saevum dracōnem oppugnāret, at prōtinus magnā vōce clāmāvit: “Pereat istud mōnstrum, {{dignum}} pessimā morte!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dignus","latin":"dignus, -a, -um","headword":"dignus","letter":"d","pos":"adjective","posGroup":"adjective","english":"(+ abl.) worthy of; worthy, worth (+ abl. or gen.); worthy (of) (+ abl.)","forms":["digna","dignam","dignās","dignī","dignīs","dignissima","dignissimum","dignōs","dignus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tē ōrō atque obsecrō ut sinās puerum abīre, mēque prō eō addīcās in servitūtem; ego poenam, quā {{dignus}} est, mihi sūmō et exsolvam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"digredi","latin":"(digredior) digredī, digressum","headword":"digredī","letter":"d","pos":"","posGroup":"other","english":"depart","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"digredior","latin":"digredior, digredi, digressus sum","headword":"digredior","letter":"d","pos":"verb","posGroup":"verb","english":"depart; come/go away; part/separate/deviate; divorce; G:digress/leave (topic)","forms":["dīgrederentur","dīgrediuntur","dīgressam","digressī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam mediā nocte digressī sunt cēterī, ea sōla in domō vacuā maeret lectōque Aenēae relictō incumbit: illum absentem et audit et videt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"digressus","latin":"digressus, digressus","headword":"digressus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"departure, parting; separation; G:digression; deviation (L+S); (going) aside","forms":["dīgressus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hāctenus ea, quae ad rēgnum Isrāēlīticum spectābant, breviter attigī, nunc revertor ad rēgēs Iūdae, ā quibus {{dīgressus}} sum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diiudico","latin":"dijudico, dijudicare, dijudicavi, dijudicatus","headword":"dijudico","letter":"d","pos":"verb","posGroup":"verb","english":"decide, settle (conflict); adjudicate/judge; distinguish (between), discern","forms":["dīiūdicāre","dīiūdicat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"quam omnium Thēbīs vir ūnam esse optimam {{dīiūdicat}},","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"dilabi","latin":"(dīlābor) dīlābī (< lābī)","headword":"dīlābī","letter":"d","pos":"","posGroup":"other","english":"fall apart, perish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dilabor","latin":"dilabor, dilabi, dilapsus sum","headword":"dilabor","letter":"d","pos":"verb","posGroup":"verb","english":"run/flow/slip away, spread (liquids); dissolve/melt away, disperse (clouds)","forms":["dīlāberētur","dīlābuntur","dīlāpsī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Madianītae, audītō tubārum sonitū et vīsīs lampadibus, turbātī sunt, et turpī fugā, quō quisque potuit, dīlāpsī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dilacerare","latin":"(dīlacerō) dīlacerāre","headword":"dīlacerāre","letter":"d","pos":"verb","posGroup":"verb","english":"tear to pieces; to tear apart, rip to pieces","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"dilacero","latin":"dilacero, dilacerare, dilaceravi, dilaceratus","headword":"dilacero","letter":"d","pos":"verb","posGroup":"verb","english":"tear to pieces, tear in pieces; tear apart","forms":["dīlacerāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita omnia in duās partēs abstracta sunt, rēs pūblica, quae media fuerat, {{dīlacerāta}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dilatare","latin":"(dīlātō) dīlātāre","headword":"dīlātāre","letter":"d","pos":"","posGroup":"other","english":"spread, expand","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dilato","latin":"dilato, dilatare, dilatavi, dilatatus","headword":"dilato","letter":"d","pos":"verb","posGroup":"verb","english":"widen/broaden, expand/enlarge/extend/spread/dilate; prolong; flatten/roll out","forms":["dīlāta","dīlātārī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec poena {{dīlāta}} foret, nisi saevī ventī fēcissent aequora invia et tellūs Aulide puppēs tenuisset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dilectus","latin":"dīlēctus, -a, -um","headword":"dīlēctus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"beloved, dear; recruitment; choice; levy, recruiting; levy, recruitment","forms":["dīlēcta","dīlēctibus","dīlēctissima","dīlēctissimae","dīlēctissime","dīlēctō","dilectum","dīlēctūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, {{dilectum}} tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"diligens","latin":"dīligēns","headword":"dīligēns","letter":"d","pos":"adjective","posGroup":"adjective","english":"(gen. dīligentis) careful, accurate; diligent, careful","forms":["dīligēns","dīligentem","dīligentior","dīligentissimum","dīligentius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Īdibus Maiīs dēmum ex itinere Rōmam revertī, unde hodiē veniō.' Iūlius: 'Ergō vōs mihi aliquid dē rēbus urbānīs novissimīs nūntiābitis.' Cornēlius: 'Et tū nōs docēbis dē rēbus rūsticīs, ut agricola studiōsus et {{dīligēns}}.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"diligenter","latin":"diligenter, diligentius, diligentissime","headword":"diligenter","letter":"d","pos":"adverb","posGroup":"adverb","english":"carefully; attentively; diligently; scrupulously; thoroughly/completely/well","forms":["diligenter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sub vesperum consilio convocato, cohortatus ut ea quae imperasset {{diligenter}} industrieque administrarent, naves quas Metiosedo deduxerat singulas equitibus Romanis attribuit et prima confecta vigilia IIII milia passuum secundo flumine silentio progredi ibique se exspectari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"diligentia","latin":"dīligentia, -ae","headword":"dīligentia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"carefulness","forms":["diligentia","diligentiae","dīligentiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summae {{diligentiae}} summam imperi severitatem addit; magnitudine supplici dubitantes cogit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"diligere","latin":"dīligere","headword":"dīligere","letter":"d","pos":"verb","posGroup":"verb","english":"love, cherish; to love, be fond of","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"diligo","latin":"dīligō, dīligere","headword":"dīligō","letter":"d","pos":"verb","posGroup":"verb","english":"love, cherish; to love, esteem","forms":["dīlēxerint","dīlēxisse","dīlēxit","dīligam","dīligēbat","dīligēbātur","dīligeret","dīligēs","dīligis","dīligit","dīligite","dīligō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cūr tū philosophōs Graecōs ita {{dīligis}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dilucescere","latin":"(dīlūcēscō) dīlūcēscere, -lūxisse","headword":"dīlūcēscere","letter":"d","pos":"","posGroup":"other","english":"dawn, become light","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dilucesco","latin":"dilucesco, dilucescere, diluxi, -","headword":"dilucesco","letter":"d","pos":"verb","posGroup":"verb","english":"dawn, become/grow light; begin to shine (L+S); shine (PERF)","forms":["dīlūcēscēbat","dīlūcēsceret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iam {{dīlūcēscēbat}}, cum signum cōnsul dedit — et sine ūllō certāmine scālīs integrōs mūrōs trānscendēre!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"diluculo","latin":"diluculo","headword":"diluculo","letter":"d","pos":"adverb","posGroup":"adverb","english":"at dawn/daybreak/first light; early","forms":["dīlūculō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Et veniēbant valdē dīlūculō mulierēs portantēs, quae parāverant, arōmata, ut ungerent corpus Iēsu.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diluvio","latin":"diluvio, diluvionis","headword":"diluvio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"flood, inundation; deluge (L+S); destruction (by water)","forms":["dīluviō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē offēnsus Deus statuit perdere hominum genus dīluviō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diluvium","latin":"diluvium, diluvi(i)","headword":"diluvium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"flood, inundation; deluge (L+S); destruction (by water)","forms":["dīluviī","dīluvium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tandem mēnse ūndecimō postquam {{dīluvium}} coeperat, Noēmus aperuit fenestram arcae, et ēmīsit corvum, quī nōn est reversus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dimicare","latin":"(dīmicō) dīmicāre","headword":"dīmicāre","letter":"d","pos":"","posGroup":"other","english":"fight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dimicatio","latin":"dīmicātiō, -ōnis ( f.)","headword":"dīmicātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"fight; fight, struggle","forms":["dīmicātiō","dīmicātiōne","dimicationum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipse adit reliquos, cohortatur ne labori succumbant; omnium superiorum {{dimicationum}} fructum in eo die atque hora docet consistere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dimico","latin":"dimico, dimicare, dimicavi, dimicatus","headword":"dimico","letter":"d","pos":"verb","posGroup":"verb","english":"fight, battle; struggle/contend/strive; brandish weapons; be in conflict/peril","forms":["dimicandum","dīmicāns","dimicare","dīmicārent","dimicaret","dīmicātum","dimicaturas","dīmicāvērunt","dīmicāvit","dīmicent","dīmicet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio {{dimicaturas}} intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dimidia","latin":"dimidia, dimidiae","headword":"dimidia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"half","forms":["dīmidia"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Sex mēnsēs sunt {{dīmidia}} pars annī, trēs mēnsēs quārta pars annī.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"dimidium","latin":"dīmidium, -ī","headword":"dīmidium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"half","forms":["dīmidium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob rem etiam nunc per {{dīmidium}} annum frūgēs et flōrēs habēmus, cēterīs vērō mēnsibus frīgora sunt, imbrēs et nivēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dimidius","latin":"dīmidius, -a, -um","headword":"dīmidius","letter":"d","pos":"adjective","posGroup":"adjective","english":"half","forms":["dīmidiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Deinde Tobiās oculōs patris līnīvit felle piscis, et post {{dīmidiam}} fermē hōram coepit albūgō, quasi membrāna ōvī, ex oculīs eius ēgredī, quam apprehēnsam fīlius extrāxit, atque ille statim vīsum recēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dimissus","latin":"dimissus, dimissi","headword":"dimissus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"surrender; handing over; demise","forms":["dīmissus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iacobus, {{dīmissus}} ā patre et mātre, profectus est in Mesopotamiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dimittere","latin":"(dīmittō) dīmittere, dīmīsisse, dīmissum","headword":"dīmittere","letter":"d","pos":"","posGroup":"other","english":"send in different directions","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"dimitto","latin":"dīmittō, -ere, -mīsī, -missum","headword":"dīmittō","letter":"d","pos":"verb","posGroup":"verb","english":"send away, let go, abandon","forms":["dīmīserat","dīmīsēre","dīmīserit","Dīmīsērunt","dīmīsissent","dīmīsisset","dīmīsistī","dimisit","dīmissa","dīmissī","dīmissīs","dīmissō","dīmittam","dīmittātis","dīmitte","dīmittendī","dīmittendōs","dimittere","dimitterent","dīmitteret","dīmittī","dimittit","dīmittite","dīmittō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Dimittit}} quoque versus legationes; obtestatur ut in fide maneant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dimoveo","latin":"dimoveo, dimovere, dimovi, dimotus","headword":"dimoveo","letter":"d","pos":"verb","posGroup":"verb","english":"put/set aside, dismiss, divert; displace/remove; exercise, move about","forms":["dimōverat","dīmovēre","dīmōvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Samūēl prīmō rem dissuāsit, Hebraeōsque ab istō cōnsiliō {{dīmovēre}} cōnātus est; sed illī in sententiā perstitērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dine","latin":"dine, dines","headword":"dine","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"whirlwind; vortex","forms":["dine"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"adsuétü{{dine}} (: quam adsuētūdō)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"dinumero","latin":"dinumero, dinumerare, dinumeravi, dinumeratus","headword":"dinumero","letter":"d","pos":"verb","posGroup":"verb","english":"count, calculate (number of); enumerate; reckon; count/pay out (money)","forms":["dīnumerā","dīnumerāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Adspice caelum; dīnumerā stēllās, sī potes; tua prōgeniēs eās aequābit numerō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diomedes","latin":"Diomedes, Diomedis","headword":"Diomedes","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Diomedes; (Greek hero at Troy, later settled in Italy)","forms":["Diomēdēs","Diomēdis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tīs equīs (Ulixēs et {{Diomēdēs}} equōs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"dionysius","latin":"Dionysius, Dionysi(i)","headword":"Dionysius","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Dionysius (long y); (of Syracuse); Dennis (Ecc); St Dennis of Paris","forms":["Dionȳsium","Dionȳsius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iam deinde, tribūnīs mīlitum cōnsulārī imperiō rem pūblicam Rōmae regentibus, ad annum ferē conditae urbis trecentēsimum quadrāgēsimum septimum, trīgintā illī tyrannī praepositī sunt ā Lacedaemoniīs Athēniēnsibus, et in Siciliā {{Dionȳsius}} superior tyrannidem tenuit; paucīsque annīs post Sōcratēs Athēnīs capitis damnātus est et in carcere venēnō necātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dionysus","latin":"Dionysus, Dionysi","headword":"Dionysus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Dionysus (Greek long y); Bacchus (Roman); god of wine","forms":["Dīonȳsī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Aut forte aut voluntāte deōrum Ariadna facta est coniūnx et sacerdōs Dīonȳsī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dipthongus","latin":"dipthongus, -ī","headword":"dipthongus","letter":"d","pos":"","posGroup":"other","english":"dipthong","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"dira","latin":"dira, dirae","headword":"dira","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"curses, imprecations (pl.); bad omens, presages of evil; The Furies; Harpies","forms":["dīra"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae simul ārentī sitientēs hausimus ōre,\net tetigit summōs virgā dea {{dīra}} capillōs,\n(et pudet et referam) saetīs horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\nmurmur et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla tumēre torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dirigere","latin":"(dīrigō) dīrigere (< regere)","headword":"dīrigere","letter":"d","pos":"","posGroup":"other","english":"arrange, direct","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dirigo","latin":"dīrigō, -ere, dīrēxī, dīrēctum","headword":"dīrigō","letter":"d","pos":"verb","posGroup":"verb","english":"direct, guide","forms":["directae","dīrēxit","dīrige","dīrigit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Trabes {{directae}} perpetuae in longitudinem paribus intervallis distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dirimere","latin":"(dirimō) dirimere (< emere)","headword":"dirimere","letter":"d","pos":"","posGroup":"other","english":"divide, interrupt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dirimo","latin":"dirimo, dirimere, diremi, diremptus","headword":"dirimo","letter":"d","pos":"verb","posGroup":"verb","english":"pull/break/take apart; cleave; sort (votes); break up/dissolve (joint activity)","forms":["dirēmit","dīrimit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"sed proelium id tandem {{dirēmit}} nox interventū suō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"diripere","latin":"(dīripio) dīripere (< rapere)","headword":"dīripere","letter":"d","pos":"","posGroup":"other","english":"plunder, loot, rob","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diripio","latin":"dīripiō, -ere, -ripuī, -reptum","headword":"dīripiō","letter":"d","pos":"verb","posGroup":"verb","english":"snatch apart, tear away","forms":["dīrepta","dīreptās","direptis","dīreptōs","diripiantur","diripiēbant","dīripiendās","dīripiendī","diripit","diripiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fufium Citam, honestum equitem Romanum, qui rei frumentariae iussu Caesaris praeerat, interficiunt bonaque eorum {{diripiunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"diruere","latin":"(dīruō) dīruere, dīruisse,","headword":"dīruere","letter":"d","pos":"","posGroup":"other","english":"demolish dīrutum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diruo","latin":"diruo, diruere, dirui, dirutus","headword":"diruo","letter":"d","pos":"verb","posGroup":"verb","english":"demolish/wreck/destroy, pull down, raze to ground; overthrow; bankrupt (L+S)","forms":["dīruēbantur","dīruendam","dīruit","dīrutae","dīruunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum Sedeciās rebellāsset, Nabuchodonosor, reversus, urbem {{dīruit}}, templum incendit, et Sedeciam, effossīs prius oculīs, in carcerem mīsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dirus","latin":"dīrus, -a, -um","headword":"dīrus","letter":"d","pos":"adjective","posGroup":"adjective","english":"dreadful; dreadful, cruel","forms":["dīrae","dīram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Haec mulier plānē admīrābilis, et sempitēmā memoriā digna, postquam fīliōs certantēs et aspectīī et verbīs adiiīverat, postquam morientēs magnō animō cōnspexerat, ipsa {{dīram}} mortem subiit, suumque sanguinem cum fīliōrum sanguine commiscuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dis","latin":"dis, ditis (gen.), ditior -or -us, ditissimus -a -um","headword":"dis","letter":"d","pos":"adjective","posGroup":"adjective","english":"rich/wealthy; richly adorned; fertile/productive (land); profitable; sumptuous","forms":["dis","Dītī","dītior","dītissimam","dītissimus","ditum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nostri, ut superioribus diebus, ut cuique erat locus attributus, ad munitiones accedunt; fun: {{dis}} librilibus sudibusque, quas in opere disposuerant, ac glandibus Gallos proterrent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"discedit","latin":"discēdit","headword":"discēdit","letter":"d","pos":"verb","posGroup":"verb","english":"go away, depart; leaves, departs; departs, goes away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"discedo","latin":"discēdō, -ere, -cessī, -cessum","headword":"discēdō","letter":"d","pos":"verb","posGroup":"verb","english":"depart, go away","forms":["discēdam","discēde","discēdendī","discēdendum","discēdēns","discedentem","Discedentibus","discēdere","discēderent","discederet","discēdēs","discēdet","discēdis","discedit","discēdite","discēditis","disceditur","discedunt","discesserat","discessērunt","discessī","discessimus","discessisse","discessit","discessu","discessum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum, collaudatis Carnutibus, dato iure iurando ab omnibus qui aderant, tempore eius rei constituto ab concilio {{disceditur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"disceptare","latin":"(disceptō) disceptāre","headword":"disceptāre","letter":"d","pos":"","posGroup":"other","english":"decide, debate, discuss","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disceptator","latin":"disceptator, disceptatoris","headword":"disceptator","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"arbitrator","forms":["disceptatorem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Cur enim potius Aedui de suo iure et de legibus ad Caesarem {{disceptatorem}} quam Romani ad Aeduos veniant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"discepto","latin":"discepto, disceptare, disceptavi, disceptatus","headword":"discepto","letter":"d","pos":"verb","posGroup":"verb","english":"dispute; debate; arbitrate","forms":["disceptārent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Postquam illī mōre rēgiō iūsta magnificē fēcerant, rēgulī in ūnum convēnērunt, ut inter sē dē cūnctīs negōtiīs {{disceptārent}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"discere","latin":"discere","headword":"discere","letter":"d","pos":"verb","posGroup":"verb","english":"to learn; learn","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"discernere","latin":"(discernō) discernere","headword":"discernere","letter":"d","pos":"verb","posGroup":"verb","english":"distinguish; to distinguish, discern","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"discerno","latin":"discerno, discernere, discrevi, discretus","headword":"discerno","letter":"d","pos":"verb","posGroup":"verb","english":"see, discern; distinguish, separate","forms":["discernere","discernerēs","discrēverat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum haec apud Alesiam geruntur, Galli, concilio principum indicto, non omnes eos qui arma ferre possent, ut censuit Vercingetorix, convocandos statuunt sed certum numerum cuique ex civitate imperandum, ne tanta multitudine confusa nec moderari nec {{discernere}} suos nec frumentationem habere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"discessus","latin":"discessus, -ūs","headword":"discessus","letter":"d","pos":"","posGroup":"other","english":"departure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"discidium","latin":"discidium, discidi(i)","headword":"discidium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"separation, divorce, discord; disagreement, quarrel; tearing apart","forms":["discidiī","discidium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Huius discidiī occāsiōne, Pompēius, populī Rōmānī dux, in Iildaeam venit, speciē quidem restituendae inter frātrēs concordiae, sed rē vērā ut istam prōvinciam Rōmānō adiungeret imperī ō; et vērē IŪdaeam stīpendiāriam populī Rōmānī fēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"discinctus","latin":"discinctus, discincta, discinctum","headword":"discinctus","letter":"d","pos":"adjective","posGroup":"adjective","english":"wearing loose clothes; easy-going","forms":["discīnctus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Īnstitor ad dominam veniet {{discīnctus}} emàcem,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"disciplina","latin":"disciplīna, -ae","headword":"disciplīna","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"instruction, discipline","forms":["disciplīnā","disciplīnam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inde Lacedaemonem adit, nōn operum magnificentia, sed disciplīnā īnstitūtīsque memorābilem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"discipuli","latin":"discipulī, -ōrum","headword":"discipulī","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"students, pupils","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"discipulus","latin":"discipulus, -ī","headword":"discipulus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"pupil, disciple; pupil, student","forms":["discipule","discipulī","discipulīs","discipulō","discipulōrum","discipulōs","discipulum","discipulus","DISCIPVLVS"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus: “Quia mē malum {{discipulum}} esse putat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"discit","latin":"discit","headword":"discit","letter":"d","pos":"verb","posGroup":"verb","english":"learns","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"discludo","latin":"discludo, discludere, disclusi, disclusus","headword":"discludo","letter":"d","pos":"verb","posGroup":"verb","english":"divide, separate, keep apart; shut off","forms":["discludit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis {{discludit}}, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"disco","latin":"discō, discere","headword":"discō","letter":"d","pos":"verb","posGroup":"verb","english":"learn","forms":["didicerant","didicerint","didicērunt","didicī","didicisse","didicisset","didicistī","didicit","discant","discās","disce","discēbam","discēbant","discēbat","discendum","discere","discerēmus","disceret","discēs","discet","discī","discimus","discīs","discit","discite","discitis","discō","discunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ibi a Viridomaro atque Eporedorige Aeduis appellatus {{discit}} cum omni equitatu Litaviccum ad solicitandos Aeduos profectum; opus esse ipsos antecedere ad confirmandam civitatem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"discordia","latin":"discordia, -ae","headword":"discordia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"disagreement, discord","forms":["discordia","discordiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aedēs Concordiae antīqua eō tempore aedificāta esse dīcitur cum post longam {{discordiam}}, quae populum Rōmānum dīvīserat in duās factiōnēs inter sē inimīcissimās, patriciōs et plēbēiōs, tandem concordia omnium collāpsam in meliōrem faciem restituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"discors","latin":"discors, -cordis","headword":"discors","letter":"d","pos":"adjective","posGroup":"adjective","english":"inharmonious, discordant","forms":["discordem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Neptūnus, quī rēgem pūnīre voluit, fēcit ut Pāsiphaē, coniūnx eius, taurum amāret; adultera lignō taurum saevum dēcēperat ut fētum {{discordem}} uterō ferret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"discribere","latin":"(discrībō) discrībere (< scībere)","headword":"discrībere","letter":"d","pos":"","posGroup":"other","english":"divide up, distribute","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"discribo","latin":"discribo, discribere, discripsi, discriptus","headword":"discribo","letter":"d","pos":"verb","posGroup":"verb","english":"divide, assign, distribute","forms":["dīscrīpsistī","dīscrīpsit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque omnium prīmum ad cursūs lūnae in duodecim mēnsēs {{dīscrīpsit}} annum, additīs Iānuāriō et Februāriō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"discrimen","latin":"discrīmen, -inis (n.)","headword":"discrīmen","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"distinction, grave danger; crisis, danger; distinction; difference; crisis","forms":["discrīmen","discrīmina","discrīmine"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Urbem quam statuō, vestra est; subdūcite nāvīs;\nTrōs Tyriusque mihī nūllō {{discrīmine}} agētur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"discriptio","latin":"discrīptiō, -ōnis ( f.)","headword":"discrīptiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"distribution","forms":["dīscrīptiōne","dīscrīptiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sīc enim dēcernō, sīc sentiō, sīc affirmō: nūllam omnium rērum pūblicārum aut cōnstitūtiōne aut {{dīscrīptiōne}} aut disciplīnā cōnferendam esse cum eā quam patrēs nostrī nōbīs acceptam iam inde ā māiōribus relīquērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"discumbere","latin":"(discumbō) discumbere, -cubuisse, -cubitum","headword":"discumbere","letter":"d","pos":"","posGroup":"other","english":"take one’s place at table","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"discumbo","latin":"discumbo, discumbere, discubui, discubitus","headword":"discumbo","letter":"d","pos":"verb","posGroup":"verb","english":"sit (to eat), recline at table; lie down; go to bed","forms":["discubuerant","discumbāmus","discumbant","discumbe","discumbēbat","discumbere","discumbitur","discumbunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vespere autem factō, {{discumbēbat}} Iēsus cum duodecim discipulīs suīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"discurrere","latin":"(discurrō) discurrere (< currere)","headword":"discurrere","letter":"d","pos":"","posGroup":"other","english":"run in several directions","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"discurro","latin":"discurro, discurrere, discurri, discursus","headword":"discurro","letter":"d","pos":"verb","posGroup":"verb","english":"run off in different directions; run/dash around/about; wander; roam","forms":["discurrentem","discurrere","discurrit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Necdum sciëbä- mūs quô mitterēmus suspiciônës nostrās, cum extrā triclî- nium clāmor sublātus est ingēns, et ecce canēs Lacônicî etiam circā mēnsam {{discurrere}} coepērunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"discus","latin":"discus, disci","headword":"discus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"disk/disc; discus; disk-shaped object; dish; gong; form of sundial; dial; CD","forms":["discum","discus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ōlim igitur, cum, positīs vestīmentīs, oleō membra aspersissent, in lātissimō campō herbīs opertō discīs iactandīs certābant; Hyacinthus, quī certandī studiōsissimus erat, prior {{discum}} in āera omnibus lacertōrum vīribus ēmīsit; quī, sē celerrimē vertēns, usque ad caelum ascendit, atque, cum nūbēs scidisset, rūrsus ad terram dēscendit, ceciditque procul ā locō unde puer et deus intuēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"discutio","latin":"discutio, discutere, discussi, discussus","headword":"discutio","letter":"d","pos":"verb","posGroup":"verb","english":"strike down; shatter, shake violently; dissipate, bring to naught; plead case","forms":["discussa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen {{discussa}} nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"diserte","latin":"diserte","headword":"diserte","letter":"d","pos":"adverb","posGroup":"adverb","english":"eloquently; expressly; distinctly, clearly","forms":["disertē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Satin' hoc plānē, satīn' disertē,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"disertus","latin":"disertus, -a, -um","headword":"disertus","letter":"d","pos":"adjective","posGroup":"adjective","english":"eloquent","forms":["disertī","disertum","disertus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tālibus atque aliīs, in quae dolor ipse {{disertum}} fēcerat, āversōs profugā dē classe redūxī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"disicere","latin":"(disiciō) disicere, disiēcisse,","headword":"disicere","letter":"d","pos":"","posGroup":"other","english":"scatter, break up disiectum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disicio","latin":"disicio, disicere, disjeci, disjectus","headword":"disicio","letter":"d","pos":"verb","posGroup":"verb","english":"break up; scatter; drive apart; separate into two halves, halve, divide","forms":["disicere","disiceret","disiēcerat","disiēcērunt","disiēcit","disiectam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōnne Minerva classem Graecōrum ventīs {{disicere}} atque submergere potuit ob ūnīus Aiācis scelus?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"disiicio","latin":"disjicio, disjicere, disjeci, disjectus","headword":"disjicio","letter":"d","pos":"verb","posGroup":"verb","english":"break up; scatter; drive apart; separate into two halves, halve, divide","forms":["disiice"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aut age dīversōs et {{disiice}} corpora pontō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"disiunctiva","latin":"disiūnctīva","headword":"disiūnctīva","letter":"d","pos":"","posGroup":"other","english":"(coniūnctiō) (f.) disjunctive conjunction","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"disiunctivus","latin":"disiūnctīvus","headword":"disiūnctīvus","letter":"d","pos":"adjective","posGroup":"adjective","english":"disjunctive","forms":["disiūnctīvās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis adnectēns ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: 'Cōpulātīvās, {{disiūnctīvās}}, explētīvās, causālēs, ratiōnālēs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"disiunctus","latin":"disiūnctus, -a, -um","headword":"disiūnctus","letter":"d","pos":"","posGroup":"other","english":"distant","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disiungere","latin":"(disiungō) disiungere, disiūnxisse,  disiūnctum","headword":"disiungere","letter":"d","pos":"","posGroup":"other","english":"unyoke, separate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"disiungo","latin":"disjungo, disjungere, disjunxi, disjunctus","headword":"disjungo","letter":"d","pos":"verb","posGroup":"verb","english":"unyoke; disunite, sever, divide, separate, part, estrange; put asunder (Ecc)","forms":["disiungitur","disiungunt"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Mēdus et Lȳdia ventō secundō per mare Īnferum nāvigāre pergunt ad fretum Siculum (id est fretum quō Sicilia ab Italiā {{disiungitur}}).","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"dispalari","latin":"(dispālōr) dispālārī","headword":"dispālārī","letter":"d","pos":"","posGroup":"other","english":"wander about","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dispar","latin":"dispār, -paris","headword":"dispār","letter":"d","pos":"adjective","posGroup":"adjective","english":"unequal, different","forms":["disparēs","dispari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, pari aetate et gratia sed genere {{dispari}}, quem Caesar ab Diviciaco sibi traditum ex humili loco ad summam dignitatem perduxerat, in equitum numero convenerant nominatim ab eo evocati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"disparo","latin":"disparo, disparare, disparavi, disparatus","headword":"disparo","letter":"d","pos":"verb","posGroup":"verb","english":"separate, divide","forms":["disparandos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum {{disparandos}} deducendosque ad suos curaret, quae cuique civitati pars castrorum ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dispellere","latin":"(dispellō) dispellere (< pellere)","headword":"dispellere","letter":"d","pos":"","posGroup":"other","english":"drive apart","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dispello","latin":"dispello, dispellere, dispuli, dispulsus","headword":"dispello","letter":"d","pos":"verb","posGroup":"verb","english":"drive apart or away; disperse","forms":["dispulerat","dispulit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīc ait, et dictō citius aequor tumidum sēdāvit, nūbēs collēctās {{dispulit}} solemque redūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dispensator","latin":"dispensator, dispensatoris","headword":"dispensator","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"steward; attendant; treasurer; dispenser","forms":["dispēnsātor","dispēnsātōrem","dispēnsātōrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Illī porrō metuēbant nē arguerentur dē pecūniā quam in saccīs repererant; quārē pūrgāvērunt sē apud {{dispēnsātōrem}} Iōsēphī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dispereo","latin":"dispereo, disperire, disperivi(ii), disperitus","headword":"dispereo","letter":"d","pos":"verb","posGroup":"verb","english":"perish/die; be destroyed; be ruined/lost/undone (completely) (L+S); disappear","forms":["dispeream"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Habērēs magnum adiūtōrem, posset quī ferre secundās, hunc hominem vellēs sī trādere — {{dispeream}}, nī summōssēs omnēs!” [Ego:] “Nōn istō vīvimus illīc quō tū rēre modō, domus hāc nec pūrior ūlla est nec magis hīs aliēna malīs: nīl mī officit” inquam “dītior hic aut est quia doctior.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"dispergere","latin":"(dispergō) dispergere, -sisse, -sum","headword":"dispergere","letter":"d","pos":"","posGroup":"other","english":"scatter, disperse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dispergo","latin":"dispergo, dispergere, dispersi, dispersus","headword":"dispergo","letter":"d","pos":"verb","posGroup":"verb","english":"scatter (about), disperse","forms":["dispersa","dispersos","dispersum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pabulum secari non posse; necessario {{dispersos}} hostes ex aedificiis petere; hos omnes cotidie ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dispertio","latin":"dispertio, dispertire, dispertivi, dispertitus","headword":"dispertio","letter":"d","pos":"verb","posGroup":"verb","english":"divide (up); distribute; assign; separate into lots/groups","forms":["dispertītī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"dispertītī virī, dispertītī ōrdinēs:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"displiceo","latin":"displiceo, displicere, displicui, displicitus","headword":"displiceo","letter":"d","pos":"verb","posGroup":"verb","english":"displease","forms":["displiceat","displicērent","displicet","displicuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Illī prīmum sē pūrgāre cōnantur: sē invītōs aliquid quod {{displiceat}} Tullō dictūrōs esse; rēs repetītum sē vēnisse; nisi reddantur, bellum indīcere iussōs esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"displicere","latin":"(displiceō) displicēre, -uisse, -itum","headword":"displicēre","letter":"d","pos":"","posGroup":"other","english":"displease, offend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disponere","latin":"(dispōnō) dispōnere (< pōnere)","headword":"dispōnere","letter":"d","pos":"","posGroup":"other","english":"arrange, station","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dispono","latin":"dispono, disponere, disposui, dispositus","headword":"dispono","letter":"d","pos":"verb","posGroup":"verb","english":"dispose, place here and there, distribute; set/lay out; administer/manage/order","forms":["disponere","dispōnerent","dispōnit","dispōnite","dispōnunt","disposita","dispositi","dispositis","disposito","disposuerant","disposuerat","dispōsuisse","disposuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via {{dispositis}} familiaribus suis principibusque civitatum disparandos deducendosque ad suos curaret, quae cuique civitati pars castrorum ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"disputare","latin":"(disputō) disputāre","headword":"disputāre","letter":"d","pos":"","posGroup":"other","english":"argue, discuss","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disputatio","latin":"disputātiō, -ōnis ( f.)","headword":"disputātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"an arguing, discussion; discussion, argument","forms":["disputātiō","disputātiōnem","disputātiōnēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum deinde Philus et Scīpiō et Tubērō parumper dē rēbus caelestibus disputāvissent — velut dē certīs et ratīs astrōrum mōtibus, quōs Archimēdēs Syrācūsiānus in globō sīve sphaerā aēneā arte mīrābilī effectā dēclārāvisse dīcitur — Laelius, quī eius modī {{disputātiōnēs}} tamquam inūtilēs contemnēbat, 'alia quaedam maiōra quaerenda esse' dīxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"disputo","latin":"disputo, disputare, disputavi, disputatus","headword":"disputo","letter":"d","pos":"verb","posGroup":"verb","english":"discuss, debate, argue","forms":["disputābam","disputābitur","disputāre","disputātum","disputāvissent","disputāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed possumus audīre aliquid, an sērius vēnimus?' [Philus:] 'Nihil est adhūc {{disputātum}}, et, quoniam disputāre integrum est, libenter tibi, Laelī, dē eō dissertāre concesserō.' [Laelius:] 'Immō vērō tē audiāmus.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dissensio","latin":"dissēnsiō, -ōnis ( f.) (< sentīre)","headword":"dissēnsiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"disagreement","forms":["dissēnsiō","dissēnsiōne","dissēnsiōnem","dissensionibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis {{dissensionibus}} ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dissentio","latin":"dissentio, dissentire, dissensi, dissensus","headword":"dissentio","letter":"d","pos":"verb","posGroup":"verb","english":"dissent, disagree; differ","forms":["dissentio","dissentīrem","dissentirent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam quae ab reliquis Gallis civitates {{dissentirent}}, has sua diligentia adiuncturum atque unum consilium totius Galliae effecturum, cuius consensui ne orbis quidem terrarum possit obsistere; idque se prope iam effectum habere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dissentire","latin":"(dissentiō) dissentīre (< sentīre)","headword":"dissentīre","letter":"d","pos":"","posGroup":"other","english":"disagree","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disserere","latin":"(disserō) disserere (< serere)","headword":"disserere","letter":"d","pos":"","posGroup":"other","english":"discuss, argue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dissero","latin":"dissero, disserere, disserui, disseritus","headword":"dissero","letter":"d","pos":"verb","posGroup":"verb","english":"plant/sow at intervals; scatter/distribute, plant here/there; separate/part","forms":["disserantur","disserebantur","disserendī","disserendīs","disserentium","disserere","dissererent","disserit","disseruisse","disseruit","dissērunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis hamis infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis {{disserebantur}}; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"disserto","latin":"disserto, dissertare, dissertavi, dissertatus","headword":"disserto","letter":"d","pos":"verb","posGroup":"verb","english":"discuss","forms":["dissertāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed possumus audīre aliquid, an sērius vēnimus?' [Philus:] 'Nihil est adhūc disputātum, et, quoniam disputāre integrum est, libenter tibi, Laelī, dē eō {{dissertāre}} concesserō.' [Laelius:] 'Immō vērō tē audiāmus.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dissideo","latin":"dissideo, dissidere, dissedi, dissessus","headword":"dissideo","letter":"d","pos":"verb","posGroup":"verb","english":"disagree, be at variance; be separated","forms":["Dissidēbat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Dissidēbat}} ab eō Pergamēnus rēx Eumenēs, Rōmānīs amīcissimus, bellumque inter eōs gerēbātur et marī et terrā; sed utrobīque Eumenēs plūs valēbat propter Rōmānōrum societātem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dissidere","latin":"(dissideō) dissidēre (< sedēre)","headword":"dissidēre","letter":"d","pos":"","posGroup":"other","english":"disagree, differ","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dissilio","latin":"dissilio, dissilire, dissilui, -","headword":"dissilio","letter":"d","pos":"verb","posGroup":"verb","english":"fly/leap/burst apart; break up; be broken up; burst; split","forms":["dissili"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"F ëlîcitäte {{dissili}}ô!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"dissimilis","latin":"dissimilis, -e","headword":"dissimilis","letter":"d","pos":"adjective","posGroup":"adjective","english":"unlike, different","forms":["Dissimilī","dissimilis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam {{dissimilis}} fuit haec Niobē ab illa quae paulō ante, superba, cīvibus dissuāserat nē Lātōnam colerent!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dissimulare","latin":"(dissimulō) dissimulāre","headword":"dissimulāre","letter":"d","pos":"","posGroup":"other","english":"conceal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dissimulator","latin":"dissimulator, dissimulatoris","headword":"dissimulator","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dissembler","forms":["dissimulātor"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Animus audāx, subdolus, varius, cuius reī libet simulātor aut {{dissimulātor}}; aliēnī appetēns, suī profūsus; ārdēns in cupiditātibus; satis ēloquentiae, sapientiae parum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"dissimulo","latin":"dissimulo, dissimulare, dissimulavi, dissimulatus","headword":"dissimulo","letter":"d","pos":"verb","posGroup":"verb","english":"conceal, dissemble, disguise, hide; ignore","forms":["dissimulābat","dissimulanda","dissimulandī","dissimulāns","Dissimulant","dissimulantem","dissimulāre","dissimulat","dissimulāta","dissimulent","dissimulō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Caīnus nōn pāruit Deō monentī; {{dissimulāns}} īram, dīxit frātrī suō: Age, eāmus dēambulātum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dissipare","latin":"(dissipō) dissipāre","headword":"dissipāre","letter":"d","pos":"","posGroup":"other","english":"scatter, spread","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dissipo","latin":"dissipo, dissipare, dissipavi, dissipatus","headword":"dissipo","letter":"d","pos":"verb","posGroup":"verb","english":"scatter, disperse, dissipate, squander; destroy completely; circulate","forms":["dissipābitur","dissipārī","dissipāvisse","dissipāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed Hidās, quī potentiae dīvīnae magis quam numerō mīlitum cōnfīdēbat, istō terrificō bellī app aratīī nōn est commōtus; in eam castrōrum hosfilium partem irruit, ubi erat tabemaculum rēgī s, et, occīsīs quattuor hominum mīlibus, tantās opēs {{dissipāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dissolvo","latin":"dissolvo, dissolvere, dissolvi, dissolutus","headword":"dissolvo","letter":"d","pos":"verb","posGroup":"verb","english":"unloose; dissolve, destroy; melt; pay; refute; annul","forms":["dissolūtum","dissolvēre","dissolvit"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cupiō, patrēs cōnscrīptī, mē esse clēmentem, cupiō in tantīs reī pūblicae perīculīs mē nōn {{dissolūtum}} vidērī; sed iam mē ipse inertiae nēquitiaeque condemnō.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"dissuadeo","latin":"dissuadeo, dissuadere, dissuasi, dissuasus","headword":"dissuadeo","letter":"d","pos":"verb","posGroup":"verb","english":"dissuade, advise against","forms":["dissuādēbant","dissuadente","dissuādēre","dissuāserat","dissuāsit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Datur petentibus venia, {{dissuadente}} primo Vercingetorige, post concedente et precibus ipsorum et misericordia vulgi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dissuadere","latin":"(dissuādeō) dissuādēre, dissuāsisse","headword":"dissuādēre","letter":"d","pos":"verb","posGroup":"verb","english":"dissuade; to dissuade (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"distans","latin":"distans, (gen.), distantis","headword":"distans","letter":"d","pos":"adjective","posGroup":"adjective","english":"distant; separate","forms":["distāns","distantem","distantes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Trabes directae perpetuae in longitudinem paribus intervallis {{distantes}} inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"distare","latin":"(distō) distāre","headword":"distāre","letter":"d","pos":"","posGroup":"other","english":"be distant","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"distentus","latin":"distentus, distenta, distentum","headword":"distentus","letter":"d","pos":"adjective","posGroup":"adjective","english":"full, filled up; distended; occupied, busy","forms":["distenta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"209 Ipse tenē {{distenta}} suīs umbrācula virgīs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"distinctus","latin":"distinctus, distincta, distinctum","headword":"distinctus","letter":"d","pos":"adjective","posGroup":"adjective","english":"separate, distinct; definite, lucid","forms":["distīnctam","distīnctīs","distīnctōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[Exciderunt duae pāginae.] [Scīpiō:] 'Hī coetūs igitur sēdem prīmum certō locō domiciliōrum causā cōnstituērunt; quam cum locīs manūque saepsissent, eius modī coniūnctiōnem tēctōrum \"oppidum\" vel \"urbem\" appellāvērunt dēlūbrīs {{distīnctam}} spatiīsque commūnibus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"distineo","latin":"distineo, distinere, distinui, distentus","headword":"distineo","letter":"d","pos":"verb","posGroup":"verb","english":"keep apart, separate; prevent, hold up; distract","forms":["distineat","distinebat","distinendae","distinetur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Unam esse Aeduorum civitatem quae certissimam Galliae victoriam {{distineat}}; eius auctoritate reliquas contineri; qua traducta, locum consistendi Romanis in Gallia non fore.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"distinguere","latin":"(distinguō) distinguere, -xisse, -ctum","headword":"distinguere","letter":"d","pos":"","posGroup":"other","english":"distinguish, mark, characterize","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"disto","latin":"disto, distare, -, -","headword":"disto","letter":"d","pos":"verb","posGroup":"verb","english":"stand apart, be distant; be different","forms":["distabant","distarent","distat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Fossam pedum XX derectis lateribus duxit, ut eius fossae solum tantundem pateret quantum summae fossae labra {{distarent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"distorqueo","latin":"distorqueo, distorquere, distorsi, distortus","headword":"distorqueo","letter":"d","pos":"verb","posGroup":"verb","english":"twist this way and that","forms":["distorqueat","distorquēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Est quae perversō {{distorqueat}} ōrā cachinnō;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"distrahere","latin":"(distrahō) distrahere (< trahere)","headword":"distrahere","letter":"d","pos":"","posGroup":"other","english":"pull apart, break up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"distraho","latin":"distraho, distrahere, distraxi, distractus","headword":"distraho","letter":"d","pos":"verb","posGroup":"verb","english":"draw/pull/tear apart, wrench, separate, (sub)divide; sell in parcels; distract","forms":["distractum","distrahendum","distrahi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque {{distrahi}} potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"distribuere","latin":"(distribuō) distribuere, -buisse, -būtum","headword":"distribuere","letter":"d","pos":"","posGroup":"other","english":"divide, distribute, share","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"distribuo","latin":"distribuo, distribuere, distribui, distributus","headword":"distribuo","letter":"d","pos":"verb","posGroup":"verb","english":"divide, distribute, assign","forms":["distribuendam","distribuerat","distribuerentur","distribuerunt","distribuistī","distribuit","distribūtī","distributo","distribuuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus rebus auditis, quod existimabant tribus locis transire legiones atque omnes perturbatos defectione Aeduorum fugam parare, suas quoque copias in tres partes {{distribuerunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"districtus","latin":"districtus, -a, -um","headword":"districtus","letter":"d","pos":"adjective","posGroup":"adjective","english":"busy","forms":["distrīctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Atque hic tantus vir tantīsque bellīs {{distrīctus}} nōnnihil temporis tribuit litterīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ditare","latin":"(dītō) dītāre","headword":"dītāre","letter":"d","pos":"","posGroup":"other","english":"enrich","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ditio","latin":"ditio, ditionis","headword":"ditio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"power; sovereignty, dominion, authority","forms":["ditiōnī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Num subiiciēmur ditiōnī tuae?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dito","latin":"dito, ditare, ditavi, ditatus","headword":"dito","letter":"d","pos":"verb","posGroup":"verb","english":"enrich","forms":["dītā","dītārī","dītāvit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"dītā (: sēmina) cum faenore reddunt","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"diu","latin":"diū","headword":"diū","letter":"d","pos":"adverb","posGroup":"adverb","english":"for a long time","forms":["diū","diutius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summam imperi se consulto nulli discedentem tradidisse, ne is multitudinis studio ad dimicandum impelleretur; cui rei propter animi mollitiem studere omnes videret, quod {{diutius}} laborem ferre non possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dium","latin":"dium, dii","headword":"dium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"open sky; [sub dio => in the open air]]:","forms":["dīīs","Diō","Diom"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ārās falsīs {{dīīs}} per ūniversam IŪdaeam exstrūxit; omnia templī Hierosolymitanī omāmenta dētrāxit; librōs sacrōs iussit comburī; reluctantēs inaudītīs suppliciīs afrecit; urbem innumerā caede vastāvit: ac nē Iudaeī tot malīs oppressī rebellārent, praesidium in arce collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"diurnitas","latin":"diūrnitās, -ātis ( f.)","headword":"diūrnitās","letter":"d","pos":"","posGroup":"other","english":"long duration","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diurnus","latin":"diurnus, -a, -um","headword":"diurnus","letter":"d","pos":"adjective","posGroup":"adjective","english":"of the day, daily","forms":["diurnis","diurno"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque {{diurno}} neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dius","latin":"dius, dia, dium","headword":"dius","letter":"d","pos":"adjective","posGroup":"adjective","english":"divine; w/supernatural radiance; divinely inspired; blessed, saint (Latham)","forms":["dīae","Diam","dīus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ariadnā raptā, Aegīdēs prōtinus ad īnsulam {{Diam}} vēla dedit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"diutinus","latin":"diūtinus, -a, -um","headword":"diūtinus","letter":"d","pos":"","posGroup":"other","english":"long, prolonged","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"diutius","latin":"diūtius","headword":"diūtius","letter":"d","pos":"adverb","posGroup":"adverb","english":"longer (comp. of diū)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"diuturnitas","latin":"diuturnitās, -ātis","headword":"diuturnitās","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"long duration","forms":["diuturnitātem","diuturnitātī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et placuit nē imperium longius quam annuum habērent, nē per {{diuturnitātem}} potestātis īnsolentiōrēs redderentur, sed civīlēs semper essent, quī sē post annum scīrent futūrōs esse prīvātōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"diuturnus","latin":"diūturnus, -a, -um","headword":"diūturnus","letter":"d","pos":"adjective","posGroup":"adjective","english":"long, prolonged","forms":["diūturnā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dum Latīnus in Italiā in pāce diūturnā rēgnat, Trōia seu Īlium, clārissima Asiae urbs, post bellum decem annōrum tandem ā Graecīs capta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"diva","latin":"diva, divae","headword":"diva","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"goddess","forms":["dīva"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{dīva}} solō fīxōs oculōs āversa tenēbat.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"divello","latin":"divello, divellere, divelli, divulsus","headword":"divello","letter":"d","pos":"verb","posGroup":"verb","english":"alienate/estrange; compel (persons) to part company, force away; separate from","forms":["dīvellere","dīvellī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīxit et aurō\nfulgentem rāmum silvā Iūnōnis Avernae\nmōnstrāvit iussitque suō {{dīvellere}} truncō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"diverso","latin":"diverso, diversare, diversavi, diversatus","headword":"diverso","letter":"d","pos":"verb","posGroup":"verb","english":"turn around; diversify","forms":["dīversō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"conchā (: margarīta) ē dīversō litēre — Jectāque dīversō lītore","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"diversorium","latin":"diversorium, diversori(i)","headword":"diversorium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"inn, lodging house, stopping place; public/private accommodation; quarters","forms":["dīversōrium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In {{dīversōrium}} dērīsī cōnferunt sēsē.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"diversus","latin":"dīversus, -a, -um","headword":"dīversus","letter":"d","pos":"adjective","posGroup":"adjective","english":"opposite, different; scattered, spread out, turned in different directions","forms":["dīversa","dīversae","diversas","dīversē","dīversī","dīversīs","dīversōs","dīversum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His rebus perfectis, regiones secutus quam potuit aequissimas pro loci natura, XIIII milia passuum complexus pares eiusdem generis munitiones, {{diversas}} ab his, contra exteriorem hostem perfecit, ut ne magna quidem multitudine, si ita accidat, eius discessu munitionum praesidia circumfundi possent; ne autem cum periculo ex castris egredi cogatur, dierum XXX pabulum frumentumque habere omnes convectum iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dives","latin":"dīves","headword":"dīves","letter":"d","pos":"adjective","posGroup":"adjective","english":"(gen. dīvitis) rich","forms":["dīves","dīvitem","dīvitēs","dīvitī","divitibus","dīvitissimī","dīvitissimō","dīvītissimum","dīvitissimus","dīvitum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Sciō multās domōs Tūsculānās et māiōrēs et meliōrēs esse quam nostram atque columnīs et signīs pulchriōribus ōrnārī, nec tamen haec domus mihi vidētur minus pulchra esse. rēs pulchra (esse) Domūs hominum {{dīvitum}} signīs deārum magnificīs ōrnantur — domus mea fēminā ōrnātur optimā et pulcherrimā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"diviciacus","latin":"Diviciacus, Diviciaci","headword":"Diviciacus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Diviciacus; an Aeduan Gaul chief in Caesar; a Suessiones king","forms":["Diviciaco"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, pari aetate et gratia sed genere dispari, quem Caesar ab {{Diviciaco}} sibi traditum ex humili loco ad summam dignitatem perduxerat, in equitum numero convenerant nominatim ab eo evocati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dividendus","latin":"dividendus, dividenda, dividendum","headword":"dividendus","letter":"d","pos":"adjective","posGroup":"adjective","english":"dividing (math.)","forms":["dīvidendō","dīvidendum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Gracchum frātrem et Appium Claudium socerum triumvirōs ad {{dīvidendum}} agrum creāret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dividit","latin":"dīvidit, dīvidere","headword":"dīvidit","letter":"d","pos":"","posGroup":"other","english":"divide","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"divido","latin":"divido, dividere, divisi, divisus","headword":"divido","letter":"d","pos":"verb","posGroup":"verb","english":"divide; separate, break up; share, distribute; distinguish","forms":["Dīvidātur","dīvidē","dīvidēbant","dīvidēbat","dīvidere","dīviderent","dīvideret","dīviderētur","dīvidī","dividit","dīviditur","dīvidunt","dīviduntur","dīvīsa","dīvīsae","dīvīserat","dīvīserit","dīvīsērunt","dīvīsisse","dīvīsisset","dīvīsit","dīvīsō","divisum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis {{dividit}}, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dividuus","latin":"dividuus, dividua, dividuum","headword":"dividuus","letter":"d","pos":"adjective","posGroup":"adjective","english":"divisible; divided, separated; half; parted","forms":["dīviduōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"per loca {{dīviduōs}} amne sequuntur equōs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"divinitus","latin":"dīvīnitus","headword":"dīvīnitus","letter":"d","pos":"adverb","posGroup":"adverb","english":"by divine will","forms":["dīvīnitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Utrīque obvenit {{dīvīnitus}} somnium eādem nocte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"divino","latin":"divino, divinare, divinavi, divinatus","headword":"divino","letter":"d","pos":"verb","posGroup":"verb","english":"divine; prophesy; guess","forms":["dīvīnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iosue dīvīnō auxiliō frētus, nōn armīs aut vīribus urbem aggressus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"divinus","latin":"dīvīnus, -a, -um","headword":"dīvīnus","letter":"d","pos":"adjective","posGroup":"adjective","english":"divine","forms":["dīvīnā","dīvīnae","dīvīnam","dīvīnās","dīvīnē","divinī","dīvīnīs","dīvīnum","dīvīnus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Moysēs ā Deō monitus cōnficī iussit tabernāculum ex pellibus et cortīnīs pretiōsissimīs, īnsuper arcam foederis aurō pūrō vestītam, in quā reposuit tabulās lēgis {{dīvīnae}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"divisio","latin":"dīvīsiō, -ōnis ( f.)","headword":"dīvīsiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"division; division, distribution","forms":["dīvīsiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In {{dīvīsiōne}}, quae pars Numidiae Mauretaniam attingit, agrō virīsque opulentior, Iugurthae trāditur; illam alteram, quae portuōsior et aedificiīs magis exōrnāta erat, Adherbal possēdit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"divitia","latin":"divitia, divitiae","headword":"divitia","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"riches (pl.), wealth","forms":["dīvitiae","dīvitiārum","dīvitiās","dīvitiīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae rēs ita Deō placuit, ut illī plūs tribuerit quam rogātus erat; nam Salomōnī eximiam sapientiam imperīvit, et īnsuper {{dīvitiās}} et glōriam, quās nōn petīverat, addidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"divitiae","latin":"dīvitiae, -ārum","headword":"dīvitiae","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"riches; riches, wealth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"divortium","latin":"dīvortium, -ī","headword":"dīvortium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"divorce","forms":["dīvortium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Carvīlius Rūga prīmus Rōmae dē amīcōrum sententiā {{dīvortium}} cum uxōre fēcit, quod matrimōniō sterilis esset iūrāssetque apud cēnsōrēs 'uxōrem sē līberum quaerundōrum causā habēre'; eōdemque annō Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"divulgare","latin":"(dīvulgō) dīvulgāre","headword":"dīvulgāre","letter":"d","pos":"","posGroup":"other","english":"make public, divulge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"divulgo","latin":"divulgo, divulgare, divulgavi, divulgatus","headword":"divulgo","letter":"d","pos":"verb","posGroup":"verb","english":"publish, disseminate news of","forms":["dīvulgātur","dīvulgāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum fāma tantī facinoris per omnem Āfricam brevī {{dīvulgātur}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"divum","latin":"dīvum, -ī","headword":"dīvum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"the open sky","forms":["dīvum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"auricomum sibi quī {{dīvum}} praepōnit amantī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"divus","latin":"dīvus, -a, -um","headword":"dīvus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"divine, (m.) god","forms":["dīvae","dīvī","divis","dīvō","dīvom","dīvōrum","dīvus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēscendēbat Apollō altō dē vertice Olympī aurātāsque domōs, {{dīvōrum}} tēcta, relinquēns,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dixit","latin":"dīxit","headword":"dīxit","letter":"d","pos":"verb","posGroup":"verb","english":"he/she/it said","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"do","latin":"do, dare, dedi, datus","headword":"do","letter":"d","pos":"verb","posGroup":"verb","english":"give; dedicate; sell; pay; grant/bestow/impart/offer/lend; devote; allow; make","forms":["dā","dabam","dabant","dabās","dabat","dabātur","dabimus","dabis","dabit","dabitis","dabitur","dabō","Dabor","dabunt","dabuntur","danda","dandīs","dandō","dandum","dāns","dant","dantem","Dantur","dare","Darem","darent","daret","darētur","dari","dās","dat","datae","datam","date","datis","datōs","datur","datūra","daturum","datūrus","dederant","dederās","dederat","dēdēris","dederit","dederō","dederunt","dedī","dedimus","dedisse","dedissem","dedisset","dedistī","dedit","dent","der","dere","det","dētis","dētur","dō","dor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; {{daturum}} se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"doceo","latin":"doceō, docēre","headword":"doceō","letter":"d","pos":"verb","posGroup":"verb","english":"teach, instruct; teach","forms":["docē","doceam","doceant","doceās","doceat","docēbant","docēbantur","docēbar","docēbat","docēbis","docēbō","docenda","docendōs","docēns","docent","docentem","docentis","docentur","doceō","docēre","docerent","docērētur","docērī","docēs","docet","docētur","docuerat","docuī","docuisse","docuissem","docuistī","docuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque cohortatus Aeduos de supportando commeatu, praemittit ad Boios qui de suo adventu {{doceant}} hortenturque ut in fide maneant atque hostium impetum magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"docere","latin":"docēre","headword":"docēre","letter":"d","pos":"verb","posGroup":"verb","english":"to teach","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"docet","latin":"docet","headword":"docet","letter":"d","pos":"verb","posGroup":"verb","english":"teaches","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"docilis","latin":"docilis, docilis, docile","headword":"docilis","letter":"d","pos":"adjective","posGroup":"adjective","english":"easily taught, teachable, responsive; docile","forms":["docilēs","docilī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Quisquis ubīque, virī, {{docilēs}} advertite mentés,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"doctor","latin":"doctor, -ōris (m.)","headword":"doctor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"teacher, learned man; teacher","forms":["doctōre","doctōrēs","doctōrī","doctoribus","doctōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post trīduum invēnērunt illum in templō sedentem in media {{doctōrum}}, audientem et interrogantem illōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"doctrina","latin":"doctrīna, -ae ( f.)","headword":"doctrīna","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"teaching instruction","forms":["doctrīnā","doctrīnae","doctrīnārum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In librō quem Caesare dictātōre scrīpsit ad Brūtum 'Dē clārīs ōrātōribus', Cicerō inter alia haec dē doctrīnā suā iuvenīlī nārrat: 'At vērō ego hōc tempore omnēs noctēs et diēs in omnium {{doctrīnā}}rum meditātiōne versābar.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"doctus","latin":"doctus, -a, -um","headword":"doctus","letter":"d","pos":"adjective","posGroup":"adjective","english":"learned, skilled; learned","forms":["docta","doctae","doctē","doctī","doctior","doctīs","doctissimē","doctissimō","doctissimus","doctius","doctō","doctōs","doctus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōnne {{doctus}} est magister tuus?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"documentum","latin":"documentum, -ī","headword":"documentum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"example, proof","forms":["documento","documentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis {{documento}} et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dolabella","latin":"Dolabella, Dolabellae","headword":"Dolabella","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Dolabella; (cognomen of gens Cornelia)","forms":["Dolābella"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēliō {{Dolābella}} cōnsule dēlētae sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"doleo","latin":"doleō, -ēre, doluī","headword":"doleō","letter":"d","pos":"verb","posGroup":"verb","english":"suffer pain, grieve; to grieve, suffer pain","forms":["doleam","doleat","dolēbat","dolēbis","dolendo","dolēns","dolent","dolentem","dolentēs","dolentī","dolentibus","doleō","dolēre","dolerent","dolēret","dolet","doluerit","doluērunt","doluistī","doluit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos {{dolerent}} liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dolere","latin":"dolēre, -eō, dolūī","headword":"dolēre","letter":"d","pos":"verb","posGroup":"verb","english":"to hurt, ache","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"dolet","latin":"dolet, dolēre","headword":"dolet","letter":"d","pos":"verb","posGroup":"verb","english":"hurt, feel pain, grieve; hurts, gives pain; hurts, causes pain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"dolium","latin":"dolium, dolii","headword":"dolium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"large earthenware vessel (~60 gal. wine/grain); hogshead (Cas); tun/cask","forms":["dōlia"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum tempestātēs pluviae fuerint, ‘quae opera per imbrem fierī potuerint: {{dōlia}} lavārī, vīllam pūrgārī, frūmentum trānsferrī, stercus forās efferrī, sterculīnum fierī, sēmen pūrgārī, tīmēs sarcīrī, novōs fierī’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"dolo","latin":"dolo, dolare, dolavi, dolatus","headword":"dolo","letter":"d","pos":"verb","posGroup":"verb","english":"hew/chop into shape, fashion/devise; inflict blows, batter/cudgel soundly, drub","forms":["dolō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quod Ēchō Iūnōnī, rēgīnae deōrum, dolō nocuerat, nympha Iūnōnī nōn grāta erat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dolor","latin":"dolor, dolōris","headword":"dolor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"(m.) pain, grief; grief, pain","forms":["dolor","dolore","dolorem","dolōrēs","dolōribus","dolōris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum {{dolore}} omnes ferebant, tamen hoc sibi solaci proponebant, quod se prope explorata victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dolosus","latin":"dolōsus, -a, -um","headword":"dolōsus","letter":"d","pos":"adjective","posGroup":"adjective","english":"crafty, treacherous","forms":["dolōsa","dolōsum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cōnsilium Ulixis erat {{dolōsum}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dolus","latin":"dolus, -ī","headword":"dolus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"guile, deceit, cunning; trick, stratagem","forms":["dolī","dolīs","dolōs","dolum","dolus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Crēditis āvectōs hostēs, aut ūlla putātis\ndōna carēre {{dolīs}} Danaum? sīc nōtus Ulixēs?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"domare","latin":"(domō) domāre, -uisse, -itum","headword":"domāre","letter":"d","pos":"","posGroup":"other","english":"tame, subdue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"domesticus","latin":"domesticus, -a, -um","headword":"domesticus","letter":"d","pos":"adjective","posGroup":"adjective","english":"domestic, household","forms":["domesticae","domesticam","domesticārum","domesticīs","domesticō","domesticōrum","domesticus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnēs autem eius līberī et nepōtēs {{domesticam}} virtūtem sunt imitātī, Deōque pariter et hominibus grātī et acceptī fuērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"domi","latin":"domī","headword":"domī","letter":"d","pos":"","posGroup":"other","english":"at home (locative)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"domicilium","latin":"domicilium, -ī","headword":"domicilium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"dwelling, residence","forms":["domiciliōrum","domicilium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[Exciderunt duae pāginae.] [Scīpiō:] 'Hī coetūs igitur sēdem prīmum certō locō {{domiciliōrum}} causā cōnstituērunt; quam cum locīs manūque saepsissent, eius modī coniūnctiōnem tēctōrum \"oppidum\" vel \"urbem\" appellāvērunt dēlūbrīs distīnctam spatiīsque commūnibus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"domina","latin":"domina, -ae","headword":"domina","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"mistress; mistress, lady; lady, mistress of the household","forms":["domina","dominae","dominam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Libanus: “Quae est {{domina}} tua, Dēlia?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dominari","latin":"(dominōr) dominārī","headword":"dominārī","letter":"d","pos":"","posGroup":"other","english":"be master, rule","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dominatio","latin":"dominātiō, -ōnis ( f.)","headword":"dominātiō","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dominion, power","forms":["dominātiō","dominātiōne","dominātiōnem","dominātiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neque glōriae neque {{dominātiōnis}} certāmen inter cīvēs erat; metus hostīlis in bonīs artibus cīvitātem retinēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dominatus","latin":"dominātus, -ūs (< dominārī Cap. XXXVII)","headword":"dominātus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dominion, power; rule, domination","forms":["dominātū","dominātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed et in rēgnīs nimis expertēs sunt cēterī commūnis iūris et cōnsiliī; et in optimātium dominātū vix particeps lībertātis potest esse multitūdō, cum omnī cōnsiliō commūnī ac potestāte careat; et cum omnia per populum geruntur, quamvīs iūstum atque moderātum, tamen ipsa aequābilitās est inīqua, cum habet nūllōs gradūs dignitātis...'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dominicum","latin":"dominicum, dominici","headword":"dominicum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"church with all its possessions","forms":["dominicum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vînum {{dominicum}} minīs - 1_ Trimalchiô 1. summus in summô 2.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"domino","latin":"domino, dominare, dominavi, dominatus","headword":"domino","letter":"d","pos":"verb","posGroup":"verb","english":"be master/despot/in control, rule over, exercise sovereignty; rule/dominate","forms":["dominō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mēdus quoque in oppidō Tūsculō est, neque is in forō est cum dominō, sed sine dominō in templō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dominor","latin":"dominor, dominari, dominatus sum","headword":"dominor","letter":"d","pos":"verb","posGroup":"verb","english":"be master/despot/in control, rule over, exercise sovereignty; rule/dominate","forms":["dominantur","dominātur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Incēnsā Danaī {{dominantur}} in urbe.\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dominus","latin":"dominus, -ī","headword":"dominus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"master; master, lord; lord, master, mister","forms":["domine","dominī","dominīs","dominōs","dominum","dominus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius {{dominus}} meus est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"domitianus","latin":"Domitianus, Domitiani","headword":"Domitianus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Domitian (Emperor 81-96); (son of Vespasian, brother of Titus, last Flavian)","forms":["Domitiānī","Domitiānō","Domitiānus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Omnium vērō magnificentissima est domus illa ā Domitiānō prīncipe in colle Palātīnō aedificāta, quae vocātur \"domus Augustāna\".","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"domitius","latin":"Domitius, Domiti","headword":"Domitius","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"Domitius; (Roman gens name)","forms":["Domitiō","Domitium","Domitius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Trānsgressus inde ad Āfricam {{Domitium}}, Mariānae partis ducem, et Hiarbam, rēgem Mauretāniae, quī Domitiō auxilium ferēbat, occīdit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"domo","latin":"domō","headword":"domō","letter":"d","pos":"verb","posGroup":"verb","english":"(abl.) from home","forms":["domāre","domat","domētur","domita","domitī","domitīs","domō","domuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In urbe Rōmā male mē habeō, sed Tūsculī semper dēlector domō meā pulcherrimā....”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"domus","latin":"domus, -ūs","headword":"domus","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"(f.) house; house, home","forms":["domi","domibus","domōrum","domōs","domū","domuī","domum","domus","domuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas {{domi}} quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"donare","latin":"(dōnō) dōnāre, -āvisse, -ātum","headword":"dōnāre","letter":"d","pos":"","posGroup":"other","english":"give, present with","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"donatus","latin":"donatus, donati","headword":"donatus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"oblate; one devoted/dedicated to a monastery; (often as a child)","forms":["dōnātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Gābelō cuidam egentī decem talenta, quibus ā rēge {{dōnātus}} erat, perhūmāniter commodāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"donec","latin":"dōnec","headword":"dōnec","letter":"d","pos":"conjunction","posGroup":"conjunction","english":"until; until, as long as; until, up to the time when","forms":["dōnec"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quaerēs ex eā vīctum cum multō labōre, {{dōnec}} abeās in terram, ē quā ortus es.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dono","latin":"dono, donare, donavi, donatus","headword":"dono","letter":"d","pos":"verb","posGroup":"verb","english":"present, grant; forgive; give (gifts), bestow","forms":["dōnābit","dōnāre","dōnārent","dōnāret","dōnās","donat","dōnātā","Dōnātam","dōnātū","dōnātum","dōnāverat","dōnāvērunt","dōnāvit","dōnem","dōnēs","dōnō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Oppidum diripit atque incendit, praedam militibus {{donat}}, exercitum Ligerim traducit atque in Biturigum fines pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"donum","latin":"dōnum, -ī","headword":"dōnum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"gift","forms":["dōna","dōnī","donis","dōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nec minus quam est pollicitus Vercingetorix animo laborabat ut reliquas civitates adiungeret, atque eas {{donis}} pollicitationibusque alliciebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dormio","latin":"dormio, dormire, dormivi, dormitus","headword":"dormio","letter":"d","pos":"verb","posGroup":"verb","english":"sleep, rest; be/fall asleep; behave as if asleep; be idle, do nothing","forms":["dormī","dormiam","dormiās","dormiat","dormiēbam","dormiēbant","dormiēbat","dormiēmus","dormienda","dormiendī","dormiendum","dormiēns","dormient","dormiente","dormientem","dormientēs","dormientī","dormientīs","dormiet","dormiētis","dormīmus","dormiō","dormīre","dormīret","dormīs","dormit","dormītis","dormītum","dormītūrum","dormītūrus","dormiunt","dormīvī","dormīvimus","dormīvisse","dormīvistī","dormīvistis","dormīvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae est puella quae {{dormit}}?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"dormire","latin":"dormīre","headword":"dormīre","letter":"d","pos":"verb","posGroup":"verb","english":"sleep","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"dormit","latin":"dormit","headword":"dormit","letter":"d","pos":"verb","posGroup":"verb","english":"sleep; sleeps","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"dormito","latin":"dormito, dormitare, dormitavi, dormitatus","headword":"dormito","letter":"d","pos":"verb","posGroup":"verb","english":"feel sleepy, drowsy; do nothing","forms":["dormītāre"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: 'Tē {{dormītāre}}' aibās.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"dormitorius","latin":"dormitorius, dormitoria, dormitorium","headword":"dormitorius","letter":"d","pos":"adjective","posGroup":"adjective","english":"for sleeping","forms":["dormītōriam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēposuī {{dormītōriam}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"dorsum","latin":"dorsum, -ī","headword":"dorsum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"back","forms":["dorsō","dorsum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Neptūnus, eius precibus permōtus, parvam īnsulam ex Ōceanī fundō extulit; tum delphīnum ex altō marī ad Lātōnam mīsit, quī eam in dorsō suō sedentem ā lītore maris usque ad parvae illīus īnsulae ōram vēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dos","latin":"dos, dotis","headword":"dos","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"dowry, dower; talent, quality","forms":["dōs","dōte","dōtem","dōtēs","dōtīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Inde fidēs dextraeque datae thalamōque receptus\nconiugiī {{dōtem}} sociōrum corpora poscit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"dotatus","latin":"dotatus, dotata, dotatum","headword":"dotatus","letter":"d","pos":"adjective","posGroup":"adjective","english":"richly endowed","forms":["dōtātam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Adoptat illum puerum surreptīcium sibi fīlium, eīque uxōrem {{dōtātam}} dedit, eumque hērēdem fēcit cum ipse obiit diem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"draco","latin":"dracō, -ōnis","headword":"dracō","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"dragon, serpent; serpent, dragon","forms":["dracō","dracōnem","dracōnēs","dracōnī","dracōnibus","dracōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum aureum eius vellus ad Colchidis rēgem portāvit, quī: “Cūrābō” inquit, “ut hoc vellus aureum in rāmō altissimae quercus pōnātur, quae in silvā prope rēgiam est.” Dracō vērō saevus, quī in silvā vīvēbat, circum arboris truncum sē volvēns vellus per multōs annōs cūstōdīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"du","latin":"du","headword":"du","letter":"d","pos":"numeral","posGroup":"numeral","english":"two (pl.)","forms":["bīna","bīnae","bīnās","bīnī","bīnīs","bīnōrum","binos","bis","Dua","duabus","duae","duarum","duas","duo","duobus","duōrum","duōs","duum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi {{duae}} legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"duae","latin":"duae","headword":"duae","letter":"d","pos":"numeral","posGroup":"numeral","english":"two (fem.)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"dubitare","latin":"(dubitō) dubitāre, dubitāvisse, dubitātum","headword":"dubitāre","letter":"d","pos":"verb","posGroup":"verb","english":"doubt; to doubt","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"dubitatio","latin":"dubitatio, dubitationis","headword":"dubitatio","letter":"d","pos":"noun (f.)","posGroup":"noun","english":"doubt, irresolution, uncertainty; wavering, hesitation; questioning","forms":["dubitatione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati praecipue indulserat, nulla interposita {{dubitatione}} legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dubito","latin":"dubitō (1)","headword":"dubitō","letter":"d","pos":"verb","posGroup":"verb","english":"doubt, hesitate","forms":["dubitā","dubitābam","dubitābant","dubitābat","dubitābit","dubitamus","dubitandī","dubitandō","dubitandum","dubitāns","dubitantes","dubitantibus","dubitare","dubitāret","dubitās","dubitat","dubitatis","dubitāveris","dubitāvit","dubitēs","dubitet","dubitō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Summae diligentiae summam imperi severitatem addit; magnitudine supplici {{dubitantes}} cogit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dubium","latin":"dubium, -ī","headword":"dubium","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"point of separation","forms":["dubi","dubium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cūr usque ad meam rēgiam iter fēcistī, fīlī mī?” Ille vērō respondit: “Ō Phoebe pater, quī es lūx tōtīus mundī: quīdam, quī fortasse invident mihi, negāvērunt mē fīlium tuum esse: nunc igitur tē orō et rogō ut mihi {{dubium}} tollās, et aliquō modō certō dēmōnstrēs ā mē verē et iūre ‘patrem’ tē nōminan posse!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dubius","latin":"dubius, -a, -um","headword":"dubius","letter":"d","pos":"adjective","posGroup":"adjective","english":"undecided, doubtful; doubtful, uncertain","forms":["dubia","dubiae","dubiam","dubiē","dubiī","dubiīs","dubiō","dubius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum a meridie prope ad solis occasum {{dubia}} victoria pugnaretur, Germani una in parte confertis turmis in hostes impetum fecerunt eosque propulerunt; quibus in fugam coniectis, sagittarii circumventi interfectique sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ducent","latin":"ducent","headword":"ducent","letter":"d","pos":"numeral","posGroup":"numeral","english":"two hundred","forms":["ducenta","ducentās","Ducentēsimō","ducentōs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Homō sānus nōnāgintā vel etiam centum annōs vīvere potest; {{ducentōs}} annōs vīvere nēmō potest.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ducentesimus","latin":"ducentēsimus, -a, -um","headword":"ducentēsimus","letter":"d","pos":"","posGroup":"other","english":"two hundredth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ducenti","latin":"ducentī, -ae, -a","headword":"ducentī","letter":"d","pos":"","posGroup":"other","english":"two hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ducere","latin":"dūcere","headword":"dūcere","letter":"d","pos":"verb","posGroup":"verb","english":"to lead","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ducit","latin":"dūcit, -unt","headword":"dūcit","letter":"d","pos":"","posGroup":"other","english":"guide, lead, draw, trace","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"duco","latin":"dūcō, -ere, dūxī, ductum","headword":"dūcō","letter":"d","pos":"verb","posGroup":"verb","english":"to lead, draw","forms":["dūc","dūcam","dūcat","ducebantur","dūcēbat","ducenda","dūcendī","dūcendum","ducent","dūcente","dūcentēs","ducentī","ducentīs","dūcere","dūcerent","dūcerentur","dūceret","dūcerētur","dūceris","dūcet","dūcētur","dūcit","dūcite","dūcitis","dūcitur","dūcō","ducta","ductae","ducti","ductīs","ductu","ductum","ductūram","ductūrī","ductūrōs","ductūrum","dūcunt","dūcuntur","dūxerant","dūxerat","dūxerō","duxerunt","dūxī","dūxisse","dūxissent","duxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui tum primum allato nuntio de oppugnatione Vellaunoduni, cum longius eam rem {{ductum}} iri existimarent, praesidium Cenabi tuendi causa quod eo mitterent comparabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ducto","latin":"ducto, ductare, ductavi, ductatus","headword":"ducto","letter":"d","pos":"verb","posGroup":"verb","english":"lead","forms":["ductābat","ductō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Marcō in cubiculum ductō atque inclūsō, Dāvus redit et 'Mārcus' inquit 'inclūsus est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ductor","latin":"ductor, -ōris (m.)","headword":"ductor","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"leader","forms":["ductor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mettius ille est {{ductor}} itineris huius, Mettius īdem huius auctor bellī, Mettius foederis Rōmānī Albānīque ruptor!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ductus","latin":"ductus, -ūs","headword":"ductus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"leadership, command","forms":["ductūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aqua, cuius magna cōpia ā lavantibus cōnsūmitur, ē montibus in thermās dēdūcitur per longōs aquae {{ductūs}}, quōrum veterrimus, aqua Appia, in urbem inducta est ab Appiō Claudiō Caecō, quī etiam viam Appiam ā portā Capēnā ad urbem Capuam mūniendam cūrāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"dudum","latin":"dūdum","headword":"dūdum","letter":"d","pos":"adverb","posGroup":"adverb","english":"a little while ago, formerly","forms":["dūdum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dīxit, et ingentī iam {{dūdum}} dé grege dūcī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"duello","latin":"duello, duellare, duellavi, duellatus","headword":"duello","letter":"d","pos":"verb","posGroup":"verb","english":"duel","forms":["duellō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"duellō exstīnctō maximō atque internecātīs hostibus!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"duellum","latin":"duellum, -ī","headword":"duellum","letter":"d","pos":"","posGroup":"other","english":"war","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"dulce","latin":"dulce, dulcis","headword":"dulce","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"sweet drink; sweets (pl.)","forms":["dulce"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōmen {{dulce}} sonāns Phoebō levis aura ferēbat:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"dulcis","latin":"dulcis, -e","headword":"dulcis","letter":"d","pos":"adjective","posGroup":"adjective","english":"sweet; sweet, dear","forms":["dulcem","dulcēs","dulcī","dulcia","dulcibus","dulcior","dulciōra","dulciōrem","dulciōrēs","dulcis","dulcissimē","dulcissimum","dulcius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Interdum etiam dēfuit aquā: at, iubente Deō, Moysēs percutiēbat rūpem virgā, et continuō ērumpēbant fontēs aquae {{dulcis}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dum","latin":"dum","headword":"dum","letter":"d","pos":"conjunction","posGroup":"conjunction","english":"while, as long as; while, until; while (+ present indicative); until","forms":["dum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sic deinceps omne opus contexitur, {{dum}} iusta muri altitudo expleatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"dummodo","latin":"dummodo","headword":"dummodo","letter":"d","pos":"conjunction","posGroup":"conjunction","english":"provided that, if only; provided that","forms":["dummodo"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Marcus vero, si quis eum laedere vult, ipse se defendere potest.\" Fabia: \"Item Sextus scit se defendere, {{dummodo}} cum singulis certet.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"dumtaxat","latin":"dumtaxat","headword":"dumtaxat","letter":"d","pos":"adverb","posGroup":"adverb","english":"only, just","forms":["dumtaxat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"IOsiās, moriēns, trēs relīquit fīliōs: ex hīs Iōachas trēs {{dumtaxat}} mēnsēs rēgnāvit: hellō captus est ab Assyriōrum rēge.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"dumus","latin":"dumus, dumi","headword":"dumus","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"thorn or briar bush","forms":["dūmīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Canēs, hūc et illūc currentēs, vestīgia sequēbantur ad bēstiam inveniendam; tandem aprum inventum ex {{dūmīs}}, in quibus sē occultāverat, expulērunt; quī, cum ex latibulō suō excurrisset atque fugere vellet, ab Adōne, quī parātus erat ad eum trānsfīgendum, hastā percussus cecidit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"duo","latin":"duo","headword":"duo","letter":"d","pos":"numeral","posGroup":"numeral","english":"two","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"duodecim","latin":"duodecim","headword":"duodecim","letter":"d","pos":"numeral","posGroup":"numeral","english":"twelve","forms":["duodecim","duodecima","duodecimam","duodecimō","duodecimum","duodecimus","duodenum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem {{duodenum}} pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium incursu etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"duodecimus","latin":"duodecimus, -a, -um","headword":"duodecimus","letter":"d","pos":"","posGroup":"other","english":"twelfth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"duodequadraginta","latin":"duodēquadrāgintā","headword":"duodēquadrāgintā","letter":"d","pos":"numeral","posGroup":"numeral","english":"thirty-eight","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"duodequinquaginta","latin":"duodequinquāgintā","headword":"duodequinquāgintā","letter":"d","pos":"numeral","posGroup":"numeral","english":"forty-eight","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"duodetriginta","latin":"duodētrīgintā","headword":"duodētrīgintā","letter":"d","pos":"numeral","posGroup":"numeral","english":"twenty-eight","forms":["duodētrīgintā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iānuārius tam longus est quam December, sed Februārius brevior est: duodētrīgintā aut ūndētrīgintā diēs tantum habet.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"duodeviginti","latin":"duodēvīgintī","headword":"duodēvīgintī","letter":"d","pos":"numeral","posGroup":"numeral","english":"eighteen","forms":["duodēvīgintī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus: “... quīndecim, sēdecim, septendecim, duodēvīgintī, ūndēvīgintī, vīgintī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"duplex","latin":"duplex, -icis","headword":"duplex","letter":"d","pos":"adjective","posGroup":"adjective","english":"double","forms":["duplex","duplicem","duplicī","duplicīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque {{duplicem}} duodenum pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium incursu etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"duplicare","latin":"(duplicō) duplicāre","headword":"duplicāre","letter":"d","pos":"","posGroup":"other","english":"double","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"duplico","latin":"duplico, duplicare, duplicavi, duplicatus","headword":"duplico","letter":"d","pos":"verb","posGroup":"verb","english":"double, bend double; duplicate; enlarge","forms":["Duplicātur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Duplicātur}} cīvium numerus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"duplum","latin":"duplum, dupli","headword":"duplum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"double; (esp. double penalty)","forms":["duplum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dēferte virō mūnera et {{duplum}} pretium, nē forte errōre factum sit ut vōbīs redderētur prior pecūnia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"durare","latin":"(dūrō) dūrāre","headword":"dūrāre","letter":"d","pos":"","posGroup":"other","english":"harden, hold out, last","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"duro","latin":"duro, durare, duravi, duratus","headword":"duro","letter":"d","pos":"verb","posGroup":"verb","english":"harden, make hard; become hard/stern; bear, last, remain, continue; endure","forms":["dūrāre","dūrāret","dūrat","Dūrāte","dūrāvit","dūret","dūrō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Īnfēstā tibi erit terrā, quae bibit sanguinem Abēlīs; cum coluerīs eam longō et dūrō labōre, nūllōs feret frūctūs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"durum","latin":"durum, duri","headword":"durum","letter":"d","pos":"noun (n.)","posGroup":"noun","english":"hardships (pl.)","forms":["dūrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pars, quae in illTs ūmida fuit, in corporum membra est conversā; quod {{dūrum}} erat in ossa mūtātum est; quae lapidum vēnae fuērunt, suum nōmen retinuērunt, et corporum vēnae factae sunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"durus","latin":"dūrus, -a, -um","headword":"dūrus","letter":"d","pos":"adjective","posGroup":"adjective","english":"hard; hard, harsh","forms":["dūrā","dūrae","dūram","dūrās","dūre","dūrī","duris","dūrissima","dūrissimī","dūrissimīs","durissimo","dūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, {{durissimo}} tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"duumvir","latin":"duumvir, duumviri","headword":"duumvir","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"two man board/court (usu. pl.); (equip fleet/build temple); member thereof","forms":["duumvirī","Duumvirōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēx, nē ipse rem tam trīstem iūdicāret ac secundum iūdicium suppliciī auctor esset, cōnsiliō populī advocātō, \"{{Duumvirōs}}\" inquit, \"quī Horātiō perduelliōnem iūdicent, secundum lēgem faciō.\" Horrenda lēgis verba haec erant: \"Duumvirī perduelliōnem iūdicent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"duumviri","latin":"duumvirī, -ōrum (pl.)","headword":"duumvirī","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"board of two men; two men appointed as judges","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"dux","latin":"dux, ducis","headword":"dux","letter":"d","pos":"noun (m.)","posGroup":"noun","english":"(m.) leader, chief, general; leader, commander; leader","forms":["duce","ducem","duces","ducī","ducibus","ducis","ducum","dux"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno {{ducibus}}, desperatis hominibus, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"e","latin":"ē","headword":"ē","letter":"e","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) out of, from, of, since; out of, from (+ abl.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ea","latin":"eā","headword":"eā","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"that way, there; she","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"eadem","latin":"eadem","headword":"eadem","letter":"e","pos":"adverb","posGroup":"adverb","english":"by the same route; at the same time; likewise; same (NOM S F/ABL S F/NOM P N)","forms":["eadem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec {{eadem}} centurionibus tribunisque militum mandabant, ut per eos ad Caesarem deferrentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eam","latin":"eam","headword":"eam","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"her","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ebibo","latin":"ebibo, ebibere, ebibi, ebibitus","headword":"ebibo","letter":"e","pos":"verb","posGroup":"verb","english":"drink up, drain; absorb; squander","forms":["ēbiberim"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: [sēcum] Factum'st illud, ut ego illīc vīnī hirneam ēbiberim merī.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ebrietas","latin":"ebrietas, ebrietatis","headword":"ebrietas","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"drunkenness, intoxication","forms":["ēbrietās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"\" ēbrietās -ātīs f « ēbrius Ébrietàs ut vēra nocet, sīc","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ebrius","latin":"ēbrius, -a, -um","headword":"ēbrius","letter":"e","pos":"adjective","posGroup":"adjective","english":"drunk","forms":["ēbrie","ēbriī","ēbrium","ēbrius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At subitō Centaurī, plūrima merī pōcula funditus exhauserant, multō vīnō ēbriī, mēnsās humī prōiecērunt et tōtum convīvium turbāre coepērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ebur","latin":"ebur, eboris","headword":"ebur","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"ivory; object/statue of ivory; curule chair (of magistrate); elephant/tusk","forms":["ebore","eborī","ebur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"eburnus -ā -um - ex {{ebore}} factus;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eburneus","latin":"eburneus, eburnea, eburneum","headword":"eburneus","letter":"e","pos":"adjective","posGroup":"adjective","english":"ivory, of ivory; white as ivory, ivory-colored; [dens ~ => elephant tusk]","forms":["eburneō","eburneum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Rēgia Phoebī, Sōlis deī, cuius tēctum {{eburneum}} altissimīs ā columnīs sustinēbātur, lūcēbat tōta, cum ex pūrissimō aurō aliīsque metallīs ignem imitantibus facta esset; forēs atque fenestrae argenteae clārissimē splendēbant; at opus, quod Vulcānus arte suā in iānuīs cōnfēcerat, māteriam pretiōsam superābat: nam illīc caelāverat maria, quae cingunt terrās,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"eburnus","latin":"eburnus, eburna, eburnum","headword":"eburnus","letter":"e","pos":"adjective","posGroup":"adjective","english":"made of ivory; decorated with/made partially out of ivory; white as ivory","forms":["eburnās","eburnīs","eburnōs","eburnus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"lestibus (: signīs deōrum) {{eburnīs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ecastor","latin":"ecastor","headword":"ecastor","letter":"e","pos":"interjection","posGroup":"interjection","english":"by Castor (interjection used by women)","forms":["Ēcastor"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: Ēcastor!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"eccam","latin":"eccam","headword":"eccam","letter":"e","pos":"interjection","posGroup":"interjection","english":"Here she/it is!; Behold!, Observe!, Lo!","forms":["eccam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Em tibi pateram, {{eccam}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ecce","latin":"ecce!","headword":"ecce","letter":"e","pos":"interjection; adverb","posGroup":"interjection","english":"look! here is!; behold","forms":["ecce"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dāvus: “{{Ecce}} sacculus meus, Syra.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"eccum","latin":"eccum","headword":"eccum","letter":"e","pos":"interjection","posGroup":"interjection","english":"Here he/it is!; Behold!, Observe!, Lo!","forms":["eccum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nam meus pater intus nunc est {{eccum}} Iuppiter;","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"echinus","latin":"echinus, echini","headword":"echinus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"edible sea-urchin; copper dish","forms":["echīnus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cēna ministrātur puerīs tribus, et lapis albus pōcula cum cyathō duo sustinet; adstat {{echīnus}} vīlis, cum paterā gūtus, Campāna supellex.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"echo","latin":"Ēchō, -ūs","headword":"Ēchō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Echo (a nymph)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"echoos","latin":"echoos, echi","headword":"echoos","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"echo; (nymph); repeating words/phrases; same phrase at start and end of speech","forms":["ech","Ēchō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Fuit Ēchō iūcundissimā nymphā, quae tam pulchrā vōce canere fābulāsque tam bellē nārrāre solēbat, ut ipsa Iūnō, deōrum rēgīna, saepe ex altō Olympō dēscenderet, ut eam canentem loquentemve studiōsē audīret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ecquid","latin":"ecquid","headword":"ecquid","letter":"e","pos":"adverb","posGroup":"adverb","english":"…? if, whether","forms":["ecquid"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"domī ego sum, inquam—{{ecquid}} audīs?—","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ectum","latin":"-ectum","headword":"ectum","letter":"e","pos":"","posGroup":"other","english":"regard for","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"edepol","latin":"edepol","headword":"edepol","letter":"e","pos":"interjection","posGroup":"interjection","english":"by Pollux!","forms":["edepol"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"eam quoque {{edepol}} etiam multō haec vīcit longitūdine!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"edere","latin":"(ēdō) ēdere, -didisse, -ditum","headword":"ēdere","letter":"e","pos":"verb","posGroup":"verb","english":"emit, bring forth, make; to eat","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"edicere","latin":"(ēdīcō) ēdīcere (< dīcere)","headword":"ēdīcere","letter":"e","pos":"","posGroup":"other","english":"decree, fix","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"edico","latin":"edico, edicere, edixi, edictus","headword":"edico","letter":"e","pos":"verb","posGroup":"verb","english":"proclaim, declare; appoint","forms":["ēdīcere","ēdictās","ēdīxerat","ēdīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Is igitur, ut Hebraeōs opprimeret, prīmum dūrīs illōs labōribus cōnficiēbat; deinde ēdīxit etiam ut parvulī eōrum recēns nātī in flūmen prōicerentur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"edictum","latin":"edictum, edicti","headword":"edictum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"proclamation; edict","forms":["ēdictī","ēdictō","ēdictum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Saūl, cum persequerētur Philistaeōs, ēdīxerat nē quis, nisi cōnfectīs hostibus, cibum sūmeret, mortem minātus illī, quī contrā ēdictum fēcisset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"edisco","latin":"edisco, ediscere, edidici, -","headword":"edisco","letter":"e","pos":"verb","posGroup":"verb","english":"learn by heart; commit to memory; study; get to know","forms":["ēdidicisse","Ēdiscēbam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"cūra sit et linguās ēdidicisse duàs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"edisserere","latin":"(ēdisserō) ēdisserere, -seruisse, -serutum","headword":"ēdisserere","letter":"e","pos":"","posGroup":"other","english":"set forth, expound","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"edissero","latin":"edissero, edisserere, edisserui, edissertus","headword":"edissero","letter":"e","pos":"verb","posGroup":"verb","english":"set forth in full, relate at length, dwell upon; unfold, explain, tell","forms":["ēdisserendās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Postquam Rōmam ventum est, senātus extrā urbem Quīnctiō ad rēs gestās ēdisserendās datus est, triumphusque meritō ab libentibus dēcrētus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"edit","latin":"ēdit","headword":"ēdit","letter":"e","pos":"verb","posGroup":"verb","english":"eats","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"editus","latin":"editus, edita -um, editior -or -us, editissimus -a -um","headword":"editus","letter":"e","pos":"adjective","posGroup":"adjective","english":"high, elevated; rising","forms":["ēditiōre","ēditus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī prior ēditus est pilōsus erat, alter vērō lēnis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"edo","latin":"ēdō, -ere, ēdī, ēsum","headword":"ēdō","letter":"e","pos":"verb","posGroup":"verb","english":"to eat, devour","forms":["edam","ēdat","edēbam","ēdēbant","ēdēbās","edēbat","edendam","edendī","ēdendō","edentem","ēderant","ēderat","edere","ēderem","ēderet","ēdērunt","edī","ēdiderat","ēdidisse","ēdidit","edis","ēdit","ēdita","ēditīs","edito","edō","edunt","eduntur","Esā","estur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in artiores silvas abdiderunt, copias omnes in loco {{edito}} atque aperto instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"edoceo","latin":"edoceo, edocere, edocui, edoctus","headword":"edoceo","letter":"e","pos":"verb","posGroup":"verb","english":"teach or inform thoroughly","forms":["ēdocēbat","edocet","edocti","ēdoctus","edocuerat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes {{edocet}} quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"edormisco","latin":"edormisco, edormiscere, -, -","headword":"edormisco","letter":"e","pos":"verb","posGroup":"verb","english":"sleep away/through/off; sleep one's fill","forms":["ēdormīscat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: [ad Amphitryōnem] Paulisper manē, dum ēdormīscat ūnum somnum!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"educare","latin":"(ēducō) ēducāre, ēducāvisse, ēducātum","headword":"ēducāre","letter":"e","pos":"verb","posGroup":"verb","english":"train, educate, rear; to bring up, educate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"educere","latin":"(ēducō) ēdūcere, ēdūxisse, ēductum","headword":"ēdūcere","letter":"e","pos":"verb","posGroup":"verb","english":"lead out; to draw out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"educo","latin":"educo, educere, eduxi, eductus","headword":"educo","letter":"e","pos":"verb","posGroup":"verb","english":"lead out; draw up; bring up; rear","forms":["Ēdūc","ēducābantur","ēducāmus","ēducandōs","ēducandum","ēducant","ēducārētur","ēducārī","ēducās","ēducat","ēducātī","ēducātum","ēducātus","ēducāverat","ēducāvit","ēdūcere","ēdūcerēs","educeret","educi","educit","eductae","ēductam","educto","educunt","ēdūxerant","ēdūxerit","ēdūxērunt","ēdūxī","eduxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis {{educeret}}, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"effarcio","latin":"effarcio, effarcire, -, effartus","headword":"effarcio","letter":"e","pos":"verb","posGroup":"verb","english":"stuff full","forms":["effarciuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hae revinciuntur introrsus et multo aggere vestiuntur; ea autem quae diximus intervalla grandibus in fronte saxis {{effarciuntur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"effatum","latin":"effatum, effati","headword":"effatum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"pronouncement (by seer), prediction; announcement; assertion/proposition/axiom","forms":["effāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sīc {{effāta}} sinum lacrimīs implēvit obortīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"effero","latin":"effero, efferare, efferavi, efferatus","headword":"effero","letter":"e","pos":"verb","posGroup":"verb","english":"make wild/savage/barbaric; brutalize; exasperate","forms":["effera","efferantur","efferatur","efferēbātur","efferent","efferet","efferre","efferret","efferrī","effert","efferunt","extulerat","extulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, prius quam eorum clandestina consilia {{efferantur}}, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"efferre","latin":"(efferō) efferre (< ferre)","headword":"efferre","letter":"e","pos":"verb","posGroup":"verb","english":"carry/bring out, lift, elate; to carry out, lift up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"effetus","latin":"effetus, effeta, effetum","headword":"effetus","letter":"e","pos":"adjective","posGroup":"adjective","english":"exhausted, worn out","forms":["effēta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed postquam luxū atque dēsidiā cīvitās corrupta est, rūrsus rēs pūblica magnitūdine suā imperātōrum atque magistrātuum vitia sustentābat ac, sīcuti esset {{effēta}} pariendō, multīs tempestātibus haud sānē quisquam Rōmae virtūte magnus fuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"efficio","latin":"efficiō, efficere","headword":"efficiō","letter":"e","pos":"verb","posGroup":"verb","english":"bring about","forms":["effēcerant","effēcerat","effēcisse","effēcisset","effēcit","effectā","effecto","effectum","effecturos","effecturum","efficere","efficī","efficiam","efficiant","efficiās","efficiat","efficiēbat","efficiēbātur","efficieminī","efficienda","efficiēs","efficiet","efficit","efficitur","efficiunt","efficiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus {{efficiat}} constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"effigies","latin":"effigiēs, -ēī","headword":"effigiēs","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"likeness, portrait; image, likeness","forms":["effigiem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad fontem cervus, cum bibisset, restitit et in liquōre vīdit {{effigiem}} suam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"efflictim","latin":"efflictim","headword":"efflictim","letter":"e","pos":"adverb","posGroup":"adverb","english":"passionately, desperately, to distraction","forms":["efflīctim"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"sīc {{efflīctim}} amāre proinde ut hic tē efflīctim dēperit.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"efflo","latin":"efflō, -āre, -āvī, -ātum","headword":"efflō","letter":"e","pos":"verb","posGroup":"verb","english":"breathe out, blow out","forms":["efflābant","efflābat","efflāvērunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Simul clāmāvērunt ob dolōrem; simul membra in solō posuērunt; simul oculōs clausērunt; simul dēnique animam {{efflāvērunt}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"effluo","latin":"effluo, effluere, effluxi, -","headword":"effluo","letter":"e","pos":"verb","posGroup":"verb","english":"flow out, flow forth; disappear, vanish, escape; be forgotten","forms":["efflūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Postquam illud tempus {{efflūxit}}, Cȳrus, Persārum rēx, dēvictō B abylōniorum rege, IŪdaeīs:fēcit potestātem in patriam remigrandī, templumque restituendī: sacra etiam vāsa, quae N abuchodonosor abstulerat, reddī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"effodere","latin":"effodere","headword":"effodere","letter":"e","pos":"verb","posGroup":"verb","english":"to dig","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"effodio","latin":"effodio, effodere, effodi, effossus","headword":"effodio","letter":"e","pos":"verb","posGroup":"verb","english":"dig out, excavate; gouge out","forms":["effōdēre","effōdit","effodiunt","effossis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis {{effossis}} oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"effor","latin":"effor, effari, effatus sum","headword":"effor","letter":"e","pos":"verb","posGroup":"verb","english":"utter, say (solemn words); declare, announce, make known; speak, express","forms":["effārī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"incipit effārī mediāque in vōce resistit;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"effrenatus","latin":"effrenatus, effrenata, effrenatum","headword":"effrenatus","letter":"e","pos":"adjective","posGroup":"adjective","english":"unbridled; unrestrained, unruly, headstrong, violent; freed from/not subject t","forms":["effrēnāta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quem ad fīnem sēsē {{effrēnāta}} iactābit audācia?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"effringere","latin":"(effringō) effringere (< frangere)","headword":"effringere","letter":"e","pos":"","posGroup":"other","english":"break open","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"effringo","latin":"effringo, effringere, effregi, effractus","headword":"effringo","letter":"e","pos":"verb","posGroup":"verb","english":"break open; smash; break in","forms":["effrāctīs","effrēgērunt","effrēgistī","effringere"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque vigilēs, quī cüstôdiëbant vîcînam regiônem, ratî ārdēre Trimalchiônis domum, {{effrēgērunt}} iânuam subitô et cum aquā secüribusque tumultuärî suô iūre coepënmt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"effugere","latin":"(effugiō) effugere, effūgisse","headword":"effugere","letter":"e","pos":"verb","posGroup":"verb","english":"escape; to escape, flee from","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"effugio","latin":"effugiō, -ere, -fūgī","headword":"effugiō","letter":"e","pos":"verb","posGroup":"verb","english":"flee, escape from","forms":["effuge","effūgerant","effugere","effugerent","effugeret","effūgī","effugiam","effugiant","effugiendī","effugiendus","effugiēns","effugientem","effugiēs","effūgimus","effugiō","effūgisse","effūgissent","effūgit","effugite","effugiunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quārē lanceā cōnfodere cōnātus est, sed Dāvīd ictum lētālem dēclīnātiōne corporis {{effūgit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"effugit","latin":"effugit","headword":"effugit","letter":"e","pos":"verb","posGroup":"verb","english":"escapes, flees from","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"effugium","latin":"effugium, effugi(i)","headword":"effugium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"flight; way of escape","forms":["effugium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"[{{Effugium}} Daedalī et Īcarī]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"effulgere","latin":"(effulgeō) effulgēre, -fulsisse, -fulsum","headword":"effulgēre","letter":"e","pos":"","posGroup":"other","english":"shine forth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"effundere","latin":"(effundō) effundere, effūdisse, effūsum","headword":"effundere","letter":"e","pos":"verb","posGroup":"verb","english":"pour out; to pour out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"effundo","latin":"effundō, -ere, -fūdī, -fūsum","headword":"effundō","letter":"e","pos":"verb","posGroup":"verb","english":"pour out","forms":["effūdisse","effūdissem","effūdisset","effūdit","effundēbant","effundēbat","effundēbātur","effundēns","effundere","effunderent","effundētur","effundī","effundit","effunditur","effundō","effundunt","effūsa","effūsī","effūsīs","effūsō","effūsōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum aperuissent saccōs, ut {{effunderent}} frūmenta, mīrantēs reperērunt pecūniam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"effuse","latin":"effuse, effusius, effusissime","headword":"effuse","letter":"e","pos":"adverb","posGroup":"adverb","english":"over a wide area, extensively; freely, in a disorderly manner; lavishly","forms":["effūsē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum undique effūsē fugiunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"effusus","latin":"effusus, effusa -um, effusior -or -us, effusissimus -a -um","headword":"effusus","letter":"e","pos":"adjective","posGroup":"adjective","english":"vast, wide, sprawling; disheveled, loose (hair/reins); disorderly; extravagant","forms":["effūsior","effūsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Forte super rīpās Tiberis {{effūsus}} erat nec quisquam ad ipsum amnis cursum adīre poterat; itaque servī rēgis in proximō stagnō, quod īnfrā collem Palātīnum factum erat, puerōs expōnunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"egens","latin":"egēns (gen. egentis)","headword":"egēns","letter":"e","pos":"adjective","posGroup":"adjective","english":"poor, needy; needy, destitute","forms":["egēns","egentem","egentēs","egentī","egentia","egentium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum {{egentium}} ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"egenus","latin":"egenus, egena, egenum","headword":"egenus","letter":"e","pos":"adjective","posGroup":"adjective","english":"in want of, destitute of","forms":["egēnōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In hāc calamitāte Tobiās frātrēs invīsēbat, miserōs cōnsōlāns, {{egēnōs}} opibus suīs iuvāns, et mortuōs sepeliēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"egeo","latin":"egeo, egere, egui, -","headword":"egeo","letter":"e","pos":"verb","posGroup":"verb","english":"need (w/GEN/ABL), lack, want; require, be without","forms":["egēbis","egēmus","egēre","egeret","egēs","eget","eguēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deversī in patriam IUdaeī, compositō urbis stātiī, nōn iam {{egēs}} habuēre, sed imperium penes pontificēs fuit: tribūta tamen pēnsitārunt prīmum Persīs, deinde Graecīs, post dēvictum ab Alexandra Darīum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"egere","latin":"(egeō) egēre, eguisse","headword":"egēre","letter":"e","pos":"","posGroup":"other","english":"need","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"egestas","latin":"egestas, egestatis","headword":"egestas","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"need, poverty, extreme poverty; lack, want","forms":["egestās","egestāte","egestātem","egestātis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tunc Aegyptiī, quōs premēbat {{egestās}}, adiērunt rēgem, postulantēs cibum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ego","latin":"ego","headword":"ego","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"I, myself; I","forms":["ego","me","mēd","mei","mī","mihi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"'Haec,' inquit, 'a {{me}},' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine vestro sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"egomet","latin":"egomet","headword":"egomet","letter":"e","pos":"","posGroup":"other","english":"I (myself )","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"egredi","latin":"ēgredī","headword":"ēgredī","letter":"e","pos":"verb","posGroup":"verb","english":"to go out, leave","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"egredior","latin":"ēgredior, -gredī, -gressus sum","headword":"ēgredior","letter":"e","pos":"verb","posGroup":"verb","english":"step out, go out, disembark","forms":["ēgredere","ēgrederentur","egredi","ēgrediar","ēgrediēbātur","ēgrediēmur","ēgredientem","ēgredientibus","egreditur","ēgrediuntur","egressa","ēgressae","egressi","Ēgressīs","ēgressum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore ex hibernis {{egredi}} neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"egreditur","latin":"ēgreditur, ēgredī","headword":"ēgreditur","letter":"e","pos":"verb","posGroup":"verb","english":"go out; goes out, leaves","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"egregie","latin":"egregie","headword":"egregie","letter":"e","pos":"adverb","posGroup":"adverb","english":"excellently, admirably well; signally/remarkably, to outstanding degree","forms":["egregie"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat e regione oppidi collis sub ipsis radicibus montis {{egregie}} munitus atque ex omni parte circumcisus; quem si tenerent nostri, et aquae magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"egregius","latin":"ēgregius, -a, -um","headword":"ēgregius","letter":"e","pos":"adjective","posGroup":"adjective","english":"outstanding","forms":["egregiā","ēgregiam","ēgregiārum","ēgregiās","ēgregiīs","ēgregiō","ēgregium","ēgregius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Uterque obtulit dōna Dominō: Caīnus quidem frūctus terrae; Abel autem, ovēs ēgregiās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"egressus","latin":"ēgressus, -ūs","headword":"ēgressus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"going out; going out, departure","forms":["egressus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Silentio noctis Caesar ex castris {{egressus}}, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem duodenum pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium incursu etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eheu","latin":"eheu","headword":"eheu","letter":"e","pos":"interjection","posGroup":"interjection","english":"alas! (exclamation of grief/pain/fear)","forms":["Ēheu"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ēheu, quam multós advena torsit amor!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ei","latin":"eī, eae, ea","headword":"eī","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"they (plural)","forms":["ei"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus profligatis, rursus oppidani perterriti comprehensos eos quorum opera plebem concitatam existimabant ad Caesarem perduxerunt seseque {{ei}} dediderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eia","latin":"eia","headword":"eia","letter":"e","pos":"interjection","posGroup":"interjection","english":"exclamation of joy, pleased surprise; also “come on,” “hurry up”","forms":["ēia"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Dā negandī et affirmandī!' Discipulus: 'Negandī, ut nōn; affirmandī, ut etiam, quidnī.' Magister: 'Dā dēmōnstrandī et optandī!' Discipulus: 'Dēmōnstrandī, ut ēn, ecce; optandī, ut utinam.' Magister: 'Dā hortandī et ōrdinis!' Discipulus: 'Hortandī, ut ēia; ōrdinis, ut deinde.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"eicere","latin":"(ēiciō) ēicere, ēiēcisse, ēiectum","headword":"ēicere","letter":"e","pos":"verb","posGroup":"verb","english":"throw out, eject; to throw out, cast overboard","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"eicio","latin":"eicio, eicere, eici, eictus","headword":"eicio","letter":"e","pos":"verb","posGroup":"verb","english":"accomplish, perform, bring about, cause","forms":["ēicere","ēiceret","ēicerētur","ēiciēbam","ēicit","ēiciunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ille vērō, eōrum precibus minimē mōtus, iīs ut abīrent īrātus imperāvit, dīcēns ‘sē neque Rōmānōs, ā quibus tam indignē pulsus erat, iam amāre, neque dē patriā, quae suōs fīliōs laudem ac glōriam merentēs tam turpiter ē fīnibus ēiceret, multum cūrāre’; immō dīxit ‘eam nē nōmine quidem patriae dignam esse’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"eiecto","latin":"ejecto, ejectare, ejectavi, ejectatus","headword":"ejecto","letter":"e","pos":"verb","posGroup":"verb","english":"cast out","forms":["ēiecta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Et cum vēnisset domum prīncipis, et vīdisset tībīcinēs et turbam tumultuantem, dīcēbat:\"Recēdite: nōn est enim mortua puella, sed dormit.\"Et cum ēiecta esset turba, intrāvit, et tenuit manum eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eiectus","latin":"ejectus, ejectus","headword":"ejectus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"expulsion, driving out; banishment/exile (Ecc)","forms":["eiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat {{eiectus}} expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eiicio","latin":"ejicio, ejicere, ejeci, ejectus","headword":"ejicio","letter":"e","pos":"verb","posGroup":"verb","english":"cast/throw/fling/drive out/up, extract, expel, discharge, vomit; out (tongue)","forms":["ēiēcerit","eiecerunt","ēiēcimus","ēiēcit","ēiectae","ēiectī","ēiectum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Denique ex omni numero, qui fuit circiter milium XL, vix DCCC, qui primo clamore audito se ex oppido {{eiecerunt}}, incolumes ad Vercingetorigem pervenerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eius","latin":"eius","headword":"eius","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"his (gen. sing. of is, ea, id); his, her, its","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"elabi","latin":"(ēlābor) ēlābī (< labī)","headword":"ēlābī","letter":"e","pos":"","posGroup":"other","english":"slip out, escape","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"elabor","latin":"elabor, elabi, elapsus sum","headword":"elabor","letter":"e","pos":"verb","posGroup":"verb","english":"slip away; escape; elapse","forms":["ēlābitur","ēlāpsa","ēlāpsī","ēlāpsīs","ēlāpsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et affīget ad pālum, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"elaborare","latin":"(ēlabōrō) ēlabōrāre","headword":"ēlabōrāre","letter":"e","pos":"","posGroup":"other","english":"work out, prepare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"elaboro","latin":"elaboro, elaborare, elaboravi, elaboratus","headword":"elaboro","letter":"e","pos":"verb","posGroup":"verb","english":"take pains, exert oneself; bestow care on","forms":["ēlabōrātās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinceps inde multae, quās nōs dīligenter ēlabōrātās et tamquam ēlūcubrātās afferēbāmus.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"elapsus","latin":"elapsus, elapsus","headword":"elapsus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"lapse","forms":["ēlāpsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce autem Panthūs, Apollinis sacerdōs, ex tēlīs Graecōrum ēlāpsus, amēns ad līmen accurrit sacra manū tenēns.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"elatus","latin":"elatus, elata -um, elatior -or -us, elatissimus -a -um","headword":"elatus","letter":"e","pos":"adjective","posGroup":"adjective","english":"raised, reaching high level; head high, proudly erect; sublime/exalted/grand","forms":["elati","Ēlātum","ēlātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed {{elati}} spe celeris victoriae et hostium fuga et superiorum temporum secundis proeliis, nihil adeo arduum sibi esse existimaverunt quod non virtute consequi possent, neque finem prius sequendi fecerunt quam muro oppido portisque appropinquarunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"electrum","latin":"electrum, electri","headword":"electrum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"electrum (alloy of gold and silver); amber; electron (Cal)","forms":["Ēlectrī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"quīcum Alcumēnā est nūpta, Ēlectrī fīlia.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"electus","latin":"electus, electa, electum","headword":"electus","letter":"e","pos":"adjective","posGroup":"adjective","english":"chosen, select, picked; choice","forms":["ēlēctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quam ob causam reiectus est ā Deō, et in eius locum Dāvīd, adhūc iuvenis, ē tribū Iūdae ēlēctus est, et ā Samūēle ūnctus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"elegans","latin":"elegans, (gen.), elegantis","headword":"elegans","letter":"e","pos":"adjective","posGroup":"adjective","english":"elegant, fine, handsome; tasteful; fastidious, critical; discriminating, polite","forms":["ēlegantēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"(täbulae) sūrsum versā; supînä manû drāta; pl tēctum (intexius) Priāpus -î m, deus frūctuum (ut mälum, pirum, prūnum, suāvius esse : s. tē habēre vîderint (: videant) quid Nec diū mîrärî licuit tam ēlegantēs strophās; nam repente lacūnāria sonāre coepērunt tôtumque triclînium intremuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"eleganter","latin":"eleganter, elegantius, elegantissime","headword":"eleganter","letter":"e","pos":"adverb","posGroup":"adverb","english":"elegantly, attractively; properly/rightly, w/correct taste/conduct; neatly","forms":["ēlegantius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quaerentī deinde 'quem secundum pōneret?' 'Pyrrhum' inquit, 'castra mētārī prīmum docuisse, ad hoc nēminem loca ēlegantius cēpisse, praesidia dispōsuisse.' Exsequentī 'quem tertium dīceret?' 'sēmet ipsum' dīxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"elegus","latin":"elegus, elegi","headword":"elegus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"elegiac verses (pl.), elegy","forms":["elegīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"- imparibus rotīs (: versibus) : {{elegīs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"elementum","latin":"elementum, elementi","headword":"elementum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"|element, origin; first principle","forms":["elementa"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nōn reddidistī.” “Nōn mentior!” — “Sī vērum dīcis, dictō.” Inter haec iussū magistrī surgunt pusillī ad {{elementa}}, et syllabās dīnumerāvit eīs ūnus dē māiōribus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"elephantus","latin":"elephantus, -ī","headword":"elephantus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"elephant","forms":["elephantī","elephantīs","elephantōrum","elephantōs","elephantus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"pretiōsa: dēns elephantī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"elevo","latin":"elevo, elevare, elevavi, elevatus","headword":"elevo","letter":"e","pos":"verb","posGroup":"verb","english":"lift up, raise; alleviate; lessen; make light of","forms":["ēlevant"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quam tangere ut nōn potuit, discēdēns ait: “Nōndum mātūra est, nōlō acerbam sūmere!” Quī facere quae nōn possunt verbīs ēlevant, ascrībere hoc dēbēbunt exemplum sibī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"elicio","latin":"elicio, elicere, elicui, elicitus","headword":"elicio","letter":"e","pos":"verb","posGroup":"verb","english":"draw/pull out/forth, entice, elicit, coax","forms":["ēliciendus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ācribus est stimulīs ēliciendus amor.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"elidere","latin":"(ēlīdō) ēlīdere, ēlīsisse, ēlīsum","headword":"ēlīdere","letter":"e","pos":"","posGroup":"other","english":"break thoroughly, omit, elide","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"elido","latin":"elido, elidere, elisi, elisus","headword":"elido","letter":"e","pos":"verb","posGroup":"verb","english":"strike or dash out; expel; shatter; crush out; strangle; destroy","forms":["ēlīditur","ēlīsī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ille quidem tōtam gemebundus obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"eligere","latin":"(ēligō) ēligere, ēlēgisse, ēlectum","headword":"ēligere","letter":"e","pos":"verb","posGroup":"verb","english":"pick out, choose; to choose, pick out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"eligo","latin":"ēligō, -ere, -lēgī, -lēctum","headword":"ēligō","letter":"e","pos":"verb","posGroup":"verb","english":"to pick out, choose","forms":["ēlēctae","ēlēctī","ēlēgērunt","ēlēgit","ēligat","ēlige","ēligendī","ēligere","ēligit","ēliguntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dīligēbat Deus Salomōnem: eī per quiētem adstāre vīsus est, deditque optiōnem ēligendī quidquid vellet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"elire","latin":"(sepeliō) -elīre, -elīvisse, -ultum","headword":"elīre","letter":"e","pos":"","posGroup":"other","english":"bury","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"elixus","latin":"elixus, elixa, elixum","headword":"elixus","letter":"e","pos":"adjective","posGroup":"adjective","english":"boiled; (of meat)","forms":["ēlixus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vîcit scîlicet, et Îphigenîam, ﬁliam suam, Achillî dedit uxô- rem. 0b eam rem Âiäx însänit et statim argūmentum Haec ut dîxit Trimalchiô, clämôrem Homēristae sustulērunt, intcrque familiam discurrentem vitulus in lance ducënâriä ēlixus allātus est, et quidem galeātus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"elocutus","latin":"elocutus, elocuta, elocutum","headword":"elocutus","letter":"e","pos":"adjective","posGroup":"adjective","english":"declared, uttered; out spoken","forms":["Ēlocūtus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: [sēcum] Ēlocūtus est. [Ad Mercurium] Ubī patera nunc est?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"eloquens","latin":"ēloquēns, (gen. -entis) (< loquī)","headword":"ēloquēns","letter":"e","pos":"adjective","posGroup":"adjective","english":"eloquent","forms":["ēloquenti"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ascyltos et Gïtôn cum omnia êlüdant ac rîdeant, Herme- rôs êloquëns iîs convîciumfacit.] Coeperat Ascyltos respondēre convîciô, sed Trimalchiô dēlectātus collîbertî ēloquentiä “Agite!” inquit “scordā- līās dē mediô!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"eloquentia","latin":"ēloquentia, -ae ( f.)","headword":"ēloquentia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"eloquence","forms":["ēloquentiā","ēloquentiae","ēloquentiam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[Dē ēloquentiā litterārum]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eloqui","latin":"(ēloquōr) ēloquī (< loquī)","headword":"ēloquī","letter":"e","pos":"","posGroup":"other","english":"express, tell","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eloquium","latin":"eloquium, eloqui(i)","headword":"eloquium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"eloquence; speech, utterance/word; manner of speaking, diction; pronouncement","forms":["ēloquiō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tam dabit ēloquiō vīcta puella manūs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eloquor","latin":"eloquor, eloqui, elocutus sum","headword":"eloquor","letter":"e","pos":"verb","posGroup":"verb","english":"speak out, utter","forms":["ēloquar","ēloquere"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nunc argūmentum huius ēloquar tragoediae.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"eluceo","latin":"eluceo, elucere, eluxi, -","headword":"eluceo","letter":"e","pos":"verb","posGroup":"verb","english":"shine forth; show itself; be manifest","forms":["ēlūcēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea vīta via est in caelum et in hunc coetum eōrum quī iam vīxērunt et corpore laxātī illum incolunt locum quem vidēs' — erat autem is splendidissimō candōre inter flammās circus ēlūcēns — 'quem vōs, ut ā Graecīs accēpistis, \"orbem lacteum\" nuncupātis.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"elucere","latin":"(ēlūceō) ēlūcēre (< lūcēre)","headword":"ēlūcēre","letter":"e","pos":"","posGroup":"other","english":"shine forth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"elucubrare","latin":"(ēlūcubrō) ēlūcubrāre","headword":"ēlūcubrāre","letter":"e","pos":"verb","posGroup":"verb","english":"prepare by lamplight; to polish by night, work over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"elucubro","latin":"elucubro, elucubrare, elucubravi, elucubratus","headword":"elucubro","letter":"e","pos":"verb","posGroup":"verb","english":"compose at night; burn the midnight oil over, spend the night working","forms":["ēlūcubrātās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinceps inde multae, quās nōs dīligenter ēlabōrātās et tamquam ēlūcubrātās afferēbāmus.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"eludere","latin":"(ēlūdō) ēlūdere, ēlūsisse, ēlūsum","headword":"ēlūdere","letter":"e","pos":"","posGroup":"other","english":"deceive, mock","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eludo","latin":"eludo, eludere, elusi, elusus","headword":"eludo","letter":"e","pos":"verb","posGroup":"verb","english":"elude, escape from; parry; baffle; cheat; frustrate; mock, make fun of","forms":["ēlūdere","ēlūdet","ēlūdī","ēlūdis","ēlūsit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"611 Quā vafer ēlūdī possit ratiōne marītus,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eluo","latin":"eluo, eluere, elui, elutus","headword":"eluo","letter":"e","pos":"verb","posGroup":"verb","english":"wash clean; wash away, clear oneself (of)","forms":["ēluere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hīc patemī in IŪdaeōs odiī hērēs, contrā eōs mīsit Lisiam, quī iam semel victus ā Ilīdā, hanc maculam cupiēbat ēluere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eluvio","latin":"ēluviō, -ōnis ( f.)","headword":"ēluviō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"flood, inundation; flood, deluge","forms":["ēluviōnēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quīn etiam sī cupiat prōlēs illa futūrōrum hominum deinceps laudēs ūnius cuiusque nostrum ā patribus acceptās posterīs prōdere, tamen propter ēluviōnēs exustiōnēsque terrārum, quās accidere tempore certō necesse est, nōn modo nōn aeternam, sed nē dīturnam quidem glōriam assequī possumus.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"em","latin":"em","headword":"em","letter":"e","pos":"interjection","posGroup":"interjection","english":"there! (of wonder); here!","forms":["em"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deum ūnum timē, Deum intuēre, ā quō mercēdem recipiēs.\"Hīs verbīs cōnfirmātus, adulēscēns exclāmāvit:\"Nōn regī obsequor, sed legī.\"Tūne conversus ad Antiochum:\"Tū quid {{em}}, ō sceleste, Deī omnipotentis Īram nōn effugiēs: erit tempus cum, ab eō percussus et dolōre victus, tē hominem esse cōnfitēberis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"emendo","latin":"emendo, emendare, emendavi, emendatus","headword":"emendo","letter":"e","pos":"verb","posGroup":"verb","english":"correct, emend, repair; improve, free from errors","forms":["ēmendārī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ex quō facile est opīnārī quae turba hominum ēmendārī possit sī sit paenitentiae locus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ementior","latin":"ementior, ementiri, ementitus sum","headword":"ementior","letter":"e","pos":"verb","posGroup":"verb","english":"lie, feign, falsify, invent","forms":["ēmentītū"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Quīn quae dīxistī modo omnia ēmentītū's: equidem Sōsia Amphitryōnis sum.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"emereo","latin":"emereo, emerere, emerui, emeritus","headword":"emereo","letter":"e","pos":"verb","posGroup":"verb","english":"earn, obtain by service, merit, deserve; emerge; complete/serve out one's time","forms":["ēmeruit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ennius ēmeruit, Calabrīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"emergere","latin":"(ēmergō) ēmergere (< mergere)","headword":"ēmergere","letter":"e","pos":"","posGroup":"other","english":"come out, emerge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"emergo","latin":"emergo, emergere, emersi, emersus","headword":"emergo","letter":"e","pos":"verb","posGroup":"verb","english":"rise up out of the water, emerge; escape; appear; arrive","forms":["ēmergēbant","ēmergēns","ēmersisset","ēmersit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Vidēbātur sibi adstāre Nīlō flūminī; et ecce ēmergēbant dē flūmine septem vaccae pinguēs, quae pāscēbantur in palūde.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"emico","latin":"emico, emicare, emicui, emicatus","headword":"emico","letter":"e","pos":"verb","posGroup":"verb","english":"leap/dash/bolt/jump/spurt/burst/break/shine out; spring/dart/shoot forth/up","forms":["emicat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cruor in herbam {{emicat}} ut fōns; ubi rādīcem arboris mōrī tangit, pōma alba facit purpurea.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"eminens","latin":"eminens, eminentis (gen.), eminentior -or -us, eminentissimus -a -um","headword":"eminens","letter":"e","pos":"adjective","posGroup":"adjective","english":"eminent/distinguished/notable; lofty/towering; prominent/projecting; foreground","forms":["ēminēns","eminentibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Huic loricam pinnasque adiecit, grandibus cervis {{eminentibus}} ad commissuras pluteorum atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"emineo","latin":"emineo, eminere, eminui, -","headword":"emineo","letter":"e","pos":"verb","posGroup":"verb","english":"stand out; be prominent/preeminent, excel; project","forms":["eminebant","ēminēbit","eminent","eminerent","ēminet","ēminuēre"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Huc illi stipites demissi et ab infimo revincti, ne revelli possent, ab ramis {{eminebant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eminere","latin":"(ēmineō) ēminēre, ēminuisse","headword":"ēminēre","letter":"e","pos":"","posGroup":"other","english":"stick out, project, emit, utter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eminus","latin":"eminus","headword":"eminus","letter":"e","pos":"adverb","posGroup":"adverb","english":"at/from a distance/long range/afar; beyond sword reach, a spear's throw off","forms":["eminus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem {{eminus}} iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"emit","latin":"emit, emunt","headword":"emit","letter":"e","pos":"verb","posGroup":"verb","english":"buy; buys","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"emittere","latin":"(ēmittō) ēmittere (< mittere)","headword":"ēmittere","letter":"e","pos":"","posGroup":"other","english":"send out, emit, utter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"emitto","latin":"emitto, emittere, emisi, emissus","headword":"emitto","letter":"e","pos":"verb","posGroup":"verb","english":"hurl; let go; utter; send out; drive; force; cast; discharge; expel; publish","forms":["ēmīseris","ēmīsisse","ēmīsisset","ēmīsit","ēmissa","ēmissō","ēmissum","ēmissus","ēmittēbat","ēmittēbātur","ēmitterent","ēmittit","ēmittite","emittuntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tandem mēnse ūndecimō postquam dīluvium coeperat, Noēmus aperuit fenestram arcae, et ēmīsit corvum, quī nōn est reversus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"emo","latin":"emo, emere, emi, emptus","headword":"emo","letter":"e","pos":"verb","posGroup":"verb","english":"buy; gain, acquire, obtain","forms":["emam","emāmus","emat","emātis","emēmus","emendam","ēmerat","emere","emerem","ēmērunt","emī","ēmissē","ēmissēs","ēmistī","emit","Emite","emitur","emō","emor","ēmpta","ēmptam","Emptos","ēmptum","emunt","emuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Forum plēnum est virōrum et fēminārum quī {{emunt}} aut vēndunt, in hīs Flōra, puella fōrmōsa, quae rosās vēndit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"emorior","latin":"emorior, emori, emortuus sum","headword":"emorior","letter":"e","pos":"verb","posGroup":"verb","english":"die, die off, perish; die out; decease, pass away","forms":["ēmorī","ēmoriar","ēmortuum","ēmortuus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ante” ait ’’ēmoriar, quam sit tibi cōpia nostrī”;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"emptor","latin":"ēmptor, -ōris (m.)","headword":"ēmptor","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"buyer","forms":["ēmptor","emptōrem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed postquam Rōmā ēgressus est, fertur saepe eō tacitūs respiciēns postrēmō dīxisse: 'urbem vēnālem et mātūre peritūram, sī {{emptōrem}} invēnerit!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"emunio","latin":"emunio, emunire, emunivi, emunitus","headword":"emunio","letter":"e","pos":"verb","posGroup":"verb","english":"fortify; make roads through","forms":["ēmūnītus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed et turris ingēns imminebat, et mūrus, ut in suspectō locō, ēmūnītus erat, et iuventūs dēlēcta ubi plūrimum perīculī ac timōris ostendēbātur ibi vī maiōre obsistēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"emunire","latin":"(ēmūniō) ēmūnīre","headword":"ēmūnīre","letter":"e","pos":"","posGroup":"other","english":"fortify","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"en","latin":"ēn","headword":"ēn","letter":"e","pos":"interjection","posGroup":"interjection","english":"presents something important and/or unexpected","forms":["Ēn"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ēn Rebecca: proficīscātur tēcum, nūptūra Isaacō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"enarro","latin":"enarro, enarrare, enarravi, enarratus","headword":"enarro","letter":"e","pos":"verb","posGroup":"verb","english":"describe; explain/relate in detail","forms":["ēnārrāre","ēnārrāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cave nē mē quidquam cēlēs eōrum quae audīstī.” Iubentī pāruit Samūēl, illīque ēnārrāvit omnia verba Dominī, cui Hēlī: “Dominus est” ait “faciat quod sibi libuerit.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"enato","latin":"enato, enatare, enatavi, enatatus","headword":"enato","letter":"e","pos":"verb","posGroup":"verb","english":"escape by swimming","forms":["ēnatā","ēnatant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"P ortae templī exustae erant, altāre pollūtum, virgulta in ātriīs, quasi in saltil, ēnatā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"enervare","latin":"(ēnervō) ēnervāre","headword":"ēnervāre","letter":"e","pos":"","posGroup":"other","english":"weaken, enervate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"enico","latin":"enico, enicare, enicui, enictus","headword":"enico","letter":"e","pos":"verb","posGroup":"verb","english":"kill/slay; deprive of life; kill off; exhaust/wear out, plague/torture to death","forms":["ēnicat","ēnicer"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"iam ut opprimar, ut ēnicer.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"enim","latin":"enim","headword":"enim","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"for; for, in fact, truly (postpositive)","forms":["enim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cur {{enim}} potius Aedui de suo iure et de legibus ad Caesarem disceptatorem quam Romani ad Aeduos veniant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"enimvero","latin":"enimvērō","headword":"enimvērō","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"truly, certainly","forms":["enimvērō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"SOSIA: Aiō enimvērō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"eniteo","latin":"eniteo, enitere, enitui, -","headword":"eniteo","letter":"e","pos":"verb","posGroup":"verb","english":"shine forth/out; be outstanding/conspicuous","forms":["ēnitet"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aenēās, tantum ēgregiō decus ēnitet ōre.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"enitesco","latin":"enitesco, enitescere, enitui, -","headword":"enitesco","letter":"e","pos":"verb","posGroup":"verb","english":"become bright, gleam; stand out","forms":["ēnitēscere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postrēmō Caesar in animum indūxerat vigilāre, negōtiīs amīcōrum intentus sua neglegere, nihil dēnegāre quod dōnō dignum esset; sibi magnum imperium, exercitum, bellum novum exoptābat, ubi ēnitēscere posset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"eniti","latin":"(ēnītor) ēnītī, ēnīsum","headword":"ēnītī","letter":"e","pos":"","posGroup":"other","english":"strive, exert oneself","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"enitor","latin":"enitor, eniti, enixus sum","headword":"enitor","letter":"e","pos":"verb","posGroup":"verb","english":"bring forth, bear, give birth to; struggle upwards, mount, climb, strive","forms":["enīsum","ēnītar","ēnītere","ēnītiminī","Ēnīxa"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ēnīxa puerum, nōmen Samsōnis eī indidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eno","latin":"eno, enare, enavi, enatus","headword":"eno","letter":"e","pos":"verb","posGroup":"verb","english":"swim out","forms":["ēnēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sīren -enis f, pl Gr -ēnēs: IĪ virginēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"enodo","latin":"enodo, enodare, enodavi, enodatus","headword":"enodo","letter":"e","pos":"verb","posGroup":"verb","english":"make clear","forms":["ēnōdāvit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tacē!” [Lūcius:] “Taceō.” [Postquam adversārius interpellāvit et Lūciī causidicus rem ēnōdāvit, surgit iūdex.] [Praecō praedicat:] “Silentium habēte!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ens","latin":"ens, entis","headword":"ens","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"being; something having esse/existence; (basic concept of St. Thomas Aquinas)","forms":["ens"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nec somnīs posita tūtum succumbere mé{{ens}}à,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ensis","latin":"ēnsis, ēnsis","headword":"ēnsis","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"(m.) sword","forms":["ēnse","ensem","ēnsēs","ēnsis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quae, cum graviter vulnerātam sē esse sēnsisset, prīmum sē in aquās mersit; deinde ex flūctibus surrēxit, horrenda vīsū; tum Persēum iterum iterumque mordēre cōnābātur, at ille, hūc illūc vēlōcissimē volāns, eius impetus facile vītābat; dēnique maxima cum vī saevam bēstiam etiam atque etiam in complūribus corporis partibus ēnse vulnerāvit, dōnec illa, multō sanguine effūsō, ex vulneribus mortua est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"enumerare","latin":"(ēnumerō) ēnumerāre","headword":"ēnumerāre","letter":"e","pos":"","posGroup":"other","english":"count up, enumerate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"enumero","latin":"enumero, enumerare, enumeravi, enumeratus","headword":"enumero","letter":"e","pos":"verb","posGroup":"verb","english":"count up, pay out; specify, enumerate","forms":["ēnumerāre","ēnumerāvēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Longum est omnia ēnumerāre proelia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"enuntio","latin":"enuntio, enuntiare, enuntiavi, enuntiatus","headword":"enuntio","letter":"e","pos":"verb","posGroup":"verb","english":"reveal/divulge/make known/disclose; speak out, express/state/assert; articulate","forms":["ēnūntiāret","ēnūntiat"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Curius, ubi intellegit quantum perīculum cōnsulī impendeat, properē per Fulviam Cicerōnī dolum quī parābātur ēnūntiat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"eo","latin":"eo, ire, ivi(ii), itus","headword":"eo","letter":"e","pos":"verb","posGroup":"verb","english":"go, walk; march, advance; pass; flow; ride; sail","forms":["eāmus","eant","eat","eo","ētīs","eto","eundī","eundō","eunt","ēvisse","Ībam","Ībant","Ībat","ībimus","ībit","ībitis","ībō","ierīs","ire","īrent","īret","iretur","iri","it","īte","ītis","itū","itum","itūra","itūram","itūrō","itūrōs","itūrum","itūrus","īverant","īvisse","īvisset","īvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Eo}} cum venisset, magna difficultate adficiebatur, qua ratione ad exercitum pervenire posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eodem","latin":"eōdem","headword":"eōdem","letter":"e","pos":"adverb","posGroup":"adverb","english":"to the same place","forms":["eodem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sic milites consolatus {{eodem}} die reducit in castra reliquaque quae ad oppugnationem pertinebant oppidi administrare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eos","latin":"eōs","headword":"eōs","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"them (acc.)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ephesus","latin":"Ephesus, Ephesi","headword":"Ephesus","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Ephesus, city in Asia Minor (w/temple of Artemis/a 7 wonder)","forms":["Ephesī","Ephesum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec contentus fuit recumbere, sed continuô {{Ephesum}} tragoedum coepit imitärî et subinde dominum suum spônsiône prôvocäre: ‘sī prasinus proxī- mîs circēnsibus prîmam palmam?’ [T rimalchiô dê testämentô et monumentô suô] Diﬂîlsus hāc contentiône Trimalchiô “Amîci!” inquit, “Et servī hominēs sunt et aequē ūnum lactem bibērunt, etiam sî illôs mālus tātus oppresserit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"epidipnis","latin":"epidipnis, epidipnidis","headword":"epidipnis","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"dessert","forms":["epidīpnis"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Composita ergô in gremiô Scintillae, incënsissī- mam rubôre faciem südäriô abscondit. [Mēnsae secundae sîve {{epidīpnis}}] Interpositô deinde spatiô, cum ‘secundās mēnsās’ Trī- malchiô iussisset afferrî, sustulērunt servī omnēs mēnsās Statim Trimalchiô “Poteram quīdam” inquit “hôc fer- culô esse contentus, ‘secundâs’ enim ‘mēnsās’ habētis!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"epigramma","latin":"epigramma, epigrammatis","headword":"epigramma","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"(n.) epigram","forms":["epigrammata","epigrammate","epigrammatis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum vero Cornelius \"Bene quidem\" inquit \"et iocose scripsit Catullus, nec tamen versus eius comparandi sunt cum {{epigrammatis}} sale plenis quae Martialis in inimicos scripsit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"epirus","latin":"Epirus, Epiri","headword":"Epirus","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Epirus; (region of northwestern Greece)","forms":["Ēpīrī","Ēpīrum","Ēpīrus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ēpīrī; āles Chāonis (: columba) ha-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"epistula","latin":"epistula, -ae","headword":"epistula","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"a letter; letter (message)","forms":["epistulā","epistulae","epistulam","epistulās","epistulīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister {{epistulam}} prōmit atque “Hanc epistulam” inquit “volō tē ad Lūcium Iūlium Balbum ferre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"eporedorix","latin":"Eporedorix, Eporedorigis","headword":"Eporedorix","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"Eporedorix; (Aedui Gaul)","forms":["Eporedorige","Eporedorigem","Eporedorigi","Eporedorigis","Eporedorix"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Omnis noster equitatus, omnis nobilitas interiit; principes civitatis, {{Eporedorix}} et Viridomarus, insimulati proditionis ab Romanis indicta causa interfecti sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"epula","latin":"epula, epulae","headword":"epula","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"courses (pl.), food, dishes of food; dinner; banquet; feast for the eyes","forms":["Epulae","epulās","epulīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nocte domum repetēns {{epulīs}} perfūncta redībit:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"epulae","latin":"epulae, -ārum (pl.)","headword":"epulae","letter":"e","pos":"","posGroup":"other","english":"meal, feast","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"epulari","latin":"(epulor) epulārī","headword":"epulārī","letter":"e","pos":"","posGroup":"other","english":"dine, feast","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"epulor","latin":"epulor, epulari, epulatus sum","headword":"epulor","letter":"e","pos":"verb","posGroup":"verb","english":"dine sumptuously, feast","forms":["epulābantur","epulāberis","epulandum","epulārer","epulārī","epulāta","epulēmur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Domus, in quā omnis populus et prīncipēs Philistaeōrum {{epulābantur}}, subnīxa erat duābus columnīs mīrae magnitūdinis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"epulum","latin":"epulum, epuli","headword":"epulum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"feast; solemn or public banquet; entertainment","forms":["epulum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sed quî asinum nôn potest, strātum caedit. @�� “Sed subolfaciô quia nôbîs {{epulum}} datūrus est Mam- maea: bînôs dënäriôs mihi et meîs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"equa","latin":"equa, equae","headword":"equa","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"mare","forms":["equae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"In furiàs agitantur {{equae}} spatiōque remōtā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eques","latin":"eques, equitis","headword":"eques","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"(m.) horseman; horseman, cavalryman","forms":["eques","equite","equitem","equites","equitibus","equitis","equitum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fufium Citam, honestum {{equitem}} Romanum, qui rei frumentariae iussu Caesaris praeerat, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"equester","latin":"equester, equestris, equestre","headword":"equester","letter":"e","pos":"adjective","posGroup":"adjective","english":"equestrian, mounted on horse; of/belonging to/consisting of horseman/cavalry","forms":["equestri","equestribus","equestris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum Vercingetorix nihilo minus in aequum locum descenderet, levi facto {{equestri}} proelio atque secundo in castra exercitum reduxit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"equestre","latin":"equestre, equestris","headword":"equestre","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"seats (pl.) in theater reserved for members of equestrian order/class","forms":["equestre"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Caesar ex castris equitatum educi iubet, proelium {{equestre}} committit; laborantibus iam suis Germanos equites circiter CCCC summittit, quos ab initio habere secum instituerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"equestris","latin":"equestris, -e","headword":"equestris","letter":"e","pos":"","posGroup":"other","english":"equestrian","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"equidem","latin":"equidem","headword":"equidem","letter":"e","pos":"adverb","posGroup":"adverb","english":"indeed","forms":["equidem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Propter amōrem, quem in animō sentiō, iam multī diēs sunt, cum cibum nōn sūmpsī; at {{equidem}} cibō et aquā carēre, famem et sitim perferre facilius possum quam paulisper sine tē vīvere.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"equinus","latin":"equinus, equina, equinum","headword":"equinus","letter":"e","pos":"adjective","posGroup":"adjective","english":"concerning horses","forms":["equīna"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Centaurī mīra mōnstra fuērunt, quibus vultūs, pectora et bracchia hominum erant, cētera vērō corporis membra {{equīna}}; nātūram vērō ferōcem et saevam habēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"equitare","latin":"(equitō) equitāre","headword":"equitāre","letter":"e","pos":"","posGroup":"other","english":"ride on horseback","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"equitatus","latin":"equitātus, equitātūs","headword":"equitātus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"cavalry","forms":["equitatu","equitatui","equitatum","equitatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis {{equitatui}} studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"equito","latin":"equito, equitare, equitavi, equitatus","headword":"equito","letter":"e","pos":"verb","posGroup":"verb","english":"ride (horseback)","forms":["equitāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī ubi prīmum adolēvit, pollēns vīribus, decōrā faciē, sed multō maximē ingeniō validus, nōn sē luxuī neque inertiae corrumpendum dedit, sed, utī mōs gentis illīus est, {{equitāre}}, iaculārī, cursū cum aequalibus certāre; et, cum omnēs glōriā anteīret, omnibus tamen cārus esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"equus","latin":"equus, -ī","headword":"equus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"horse","forms":["eque","equī","equis","equo","equorum","equos","equum","equus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ille oppidum Biturigum positum in via Noviodunum oppugnare instituerat. (Quo ex oppido cum legati ad eum venissent oratum ut sibi ignosceret suaeque vitae consuleret, ut celeritate reliquas res conficeret, qua pleraque erat consecutus, arma conferri, {{equos}} produci, obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"era","latin":"era, erae","headword":"era","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"mistress; lady of the house; woman in relation to her servants; Lady","forms":["era","erae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"lacer -{{era}} -erum — scissus, frāctus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"erat","latin":"erat, erant","headword":"erat","letter":"e","pos":"","posGroup":"other","english":"was, were","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"erebus","latin":"Erebus, Erebi","headword":"Erebus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"Erebus; (the underworld, realm of the dead)","forms":["Erebō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"pallentīs umbrās Erebō noctemque profundam,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"erectus","latin":"erectus, erecta -um, erectior -or -us, erectissimus -a -um","headword":"erectus","letter":"e","pos":"adjective","posGroup":"adjective","english":"upright, erect; perpendicular; confident/bold/assured; noble; attentive/alert","forms":["ērēcta","ērēctās","ērēctī","ērēctīs","ērēctō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tūne, duce Mathathīā, statuērunt p atriam armīs lThērāre, et religiōnem tuerī: itaque ārās passim falsīs niiminibus ērēctās ēvertērunt, neglēctumque vērum Deī cultum restituērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"erga","latin":"ergā","headword":"ergā","letter":"e","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) toward","forms":["ergā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Admīrandum sānē vērī ac sincērī ergā inimīcum amōris exemplum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ergo","latin":"ergō","headword":"ergō","letter":"e","pos":"adverb","posGroup":"adverb","english":"therefore, so; therefore","forms":["ergo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quid {{ergo}} mei consili est?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"erigere","latin":"(ērigō) ērigere (< regere)","headword":"ērigere","letter":"e","pos":"","posGroup":"other","english":"lift up, erect, cheer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"erigo","latin":"erigo, erigere, erexi, erectus","headword":"erigo","letter":"e","pos":"verb","posGroup":"verb","english":"raise, erect, build; rouse, excite, stimulate","forms":["ērēxēre","ērēxit","Ērige","ērigēbātur","ērigēns","ērigimur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum ērēxit altāre, et obtulit sacrificium Dominō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"erilis","latin":"erilis, erilis, erile","headword":"erilis","letter":"e","pos":"adjective","posGroup":"adjective","english":"of a master or mistress","forms":["Erīlis"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{Erīlis}} praevertit metus: accurrō ut scīscam quid velit,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"erinys","latin":"Erīnys, -yos","headword":"Erīnys","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"one of the Furies","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"eripere","latin":"(ēripiō) ēripere, ēripuisse, ēreptum","headword":"ēripere","letter":"e","pos":"","posGroup":"other","english":"snatch away, deprive","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"eripio","latin":"ēripiō, -ere, ēripuī, ēreptum","headword":"ēripiō","letter":"e","pos":"verb","posGroup":"verb","english":"snatch away, rescue","forms":["ērepta","ēreptae","ēreptam","ereptis","ēreptum","ēreptus","ēripe","ēripere","ēriperentur","eriperet","ēripī","ēripiam","ēripiantur","ēripiar","ēripient","ēripiet","ēripis","ēripit","ēripite","ēripiundum","Ēripiunt","ēripiuntur","ēripuēre","ēripuī","ēripuistī","ēripuistis","ēripuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum {{eriperet}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eris","latin":"eris, eris","headword":"eris","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"hedgehog","forms":["eris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dominus dīxit serpentī: quia dēcēpistī mulierem, {{eris}} odiōsus et exsecrātus inter omnia animantia; rēptābis super pectus, et comedēs terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ero","latin":"ero, eronis","headword":"ero","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"kind of basket made with plaited reeds; hamper; (aero)","forms":["erō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tlēpolemus: “Sed erō meō prōmīsī ‘mē brevī tempore reditūrum esse.’ Neque enim aliōs habet servōs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"errat","latin":"errat, -ant","headword":"errat","letter":"e","pos":"verb","posGroup":"verb","english":"wander, stray; wanders, strays","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"erro","latin":"errō, -āre, -āvī, -ātum","headword":"errō","letter":"e","pos":"verb","posGroup":"verb","english":"wander; to wander, go astray","forms":["errābant","errābat","errāmus","errandō","errāns","errant","errante","errantem","errantēs","errantīs","errāre","errāret","errat","errāverat","errāverit","errāveritis","errāvit","errent","errēs","errētis","errō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Errare}}, si qui in bello omnes secundos rerum proventus exspectent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"error","latin":"error, -ōris (m.)","headword":"error","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"wandering, error; wandering; mistake; error","forms":["error","errōre","errōrem","errōris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēferte virō mūnera et duplum pretium, nē forte {{errōre}} factum sit ut vōbīs redderētur prior pecūnia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"erubescere","latin":"(ērubēscō) ērubēscere, ērubuisse","headword":"ērubēscere","letter":"e","pos":"verb","posGroup":"verb","english":"blush; to blush; to blush, grow red","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"erubesco","latin":"erubesco, erubescere, erubui, -","headword":"erubesco","letter":"e","pos":"verb","posGroup":"verb","english":"redden, blush, blush at; blush for shame, be ashamed of","forms":["erubescit","ērubuēre","ērubuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī, cum prīmum in antrum intrāvit, ā Nymphīs cōnspectus est Diānam lavantibus; quae, animō valdē perturbātae, magnīs clāmōribus ingentibusque ululātibus tōtum lūcum implēvērunt, et circumdantēs Diānam suīs corporibus tēxērunt; tamen ipsa dea altior illīs erat; ērubuit igitur, atque color, quī cum sōl oritur aut occīdit","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"erudio","latin":"erudio, erudire, erudivi, eruditus","headword":"erudio","letter":"e","pos":"verb","posGroup":"verb","english":"educate, teach, instruct","forms":["ērūdīenda","ērudīre","ērudit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"&-rudīre (« € * rudis) 7 docēre ērudit infirmàs ut sua","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"erudire","latin":"(ērudiō) ērudīre, -rudīvisse, -rudītum","headword":"ērudīre","letter":"e","pos":"","posGroup":"other","english":"instruct, educate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eruditus","latin":"ērudītus, -a, -um","headword":"ērudītus","letter":"e","pos":"adjective","posGroup":"adjective","english":"well instructed, learned","forms":["ērudīta","ērudītus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inter trēs līberōs eius — maximus nātū Micipsa, Gulussa, Mastanabal, quī etiam Graecīs litterīs ērudītus erat — P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"eruere","latin":"(ēruō) ēruere, -uisse, -utum","headword":"ēruere","letter":"e","pos":"","posGroup":"other","english":"unearth, clear up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"erumpere","latin":"(ērumpō) ērumpere, ērūpisse, ēruptum","headword":"ērumpere","letter":"e","pos":"verb","posGroup":"verb","english":"break out; to burst out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"erumpo","latin":"erumpo, erumpere, erupi, eruptus","headword":"erumpo","letter":"e","pos":"verb","posGroup":"verb","english":"burst/pop (abscess/boil); cause (swelling) to burst; become dislocated (limb)","forms":["ērumpēbant","ērumpēbat","ērumpendum","ērumpēns","ērumpere","ērumpunt","ērūpērunt","ērūpit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam Noëmus ipse ingressus est in arcam cum coniuge, tribus fīliīs et totidem nuribus, aquā maris et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eruo","latin":"eruo, eruere, erui, erutus","headword":"eruo","letter":"e","pos":"verb","posGroup":"verb","english":"pluck/dig/root up, overthrow, destroy; elicit","forms":["ēruerint","ēruta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tulliī Cicerōnis ēruta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"eruptio","latin":"ēruptiō, -ōnis ( f.) (<rumpere)","headword":"ēruptiō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"a breaking out, sally, eruption","forms":["eruptio","eruptione","eruptionem","ēruptiōnēs","eruptionibus","eruptionis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Progressus in Nitiobriges et Gabalos ab utrisque obsides accipit et magna coacta manu in provinciam Narbonem versus {{eruptionem}} facere contendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"erus","latin":"erus, -ī","headword":"erus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"master","forms":["ere","erī","erum","erus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Certē nōn dīves est {{erus}} meus, sed vir doctus est, quī multōs librōs habet et Latīnōs et Graecōs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"esca","latin":"esca, escae","headword":"esca","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"food, meat; a dish prepared for the table; victuals; bait (for fish/animals)","forms":["ēscam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum: adī, inquit, patrem tuum, et offer illī ēscam quam appetit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"escarius","latin":"escarius, escaria, escarium","headword":"escarius","letter":"e","pos":"adjective","posGroup":"adjective","english":"relating to food or bait","forms":["ēscāriīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pōne discum cum ēscāriīs!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"escendere","latin":"(ēscendō) ēscendere (< scandere)","headword":"ēscendere","letter":"e","pos":"","posGroup":"other","english":"ascend, go up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"escendo","latin":"escendo, escendere, escendi, escensus","headword":"escendo","letter":"e","pos":"verb","posGroup":"verb","english":"ascend, go up, mount","forms":["ēscenderō","ēscendit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[tēctum mōnstrāns] atque illāc sūrsum ēscenderō, inde optimē aspellam virum","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"esse","latin":"(sum) esse, fuisse","headword":"esse","letter":"e","pos":"verb","posGroup":"verb","english":"be; to be (ero, eris, erit)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"essedarius","latin":"essedarius, essedaria, essedarium","headword":"essedarius","letter":"e","pos":"adjective","posGroup":"adjective","english":"of or belonging to a war chariot","forms":["essedāriam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et habet unde: relictum est illî sēstertium trecentiēs: dēcessit illîus Mäniôs aliquot habet, et mulierem {{essedāriam}}, et dīs- pënsätôrem Glycônis, quî dēprehēnsus est cum dominam suam dēlectārētur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"est","latin":"est","headword":"est","letter":"e","pos":"verb","posGroup":"verb","english":"he/she/it is; eat; is","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"esurio","latin":"esurio, esurire, esurivi, esuritus","headword":"esurio","letter":"e","pos":"verb","posGroup":"verb","english":"be hungry, hunger; want to eat, desire food; desire eagerly","forms":["ēsuriēbat"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quamquam vērō sitiēbat et ēsuriēbat, neque aquam invenīre poterat, neque quisquam cibum eī largīrī volēbat: omnēs enim Iūnōnem īrātam metuēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"et","latin":"et","headword":"et","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"and, also; and","forms":["et"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi {{et}} adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"et ... et","latin":"et ... et","headword":"et ... et","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"both ... and","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"et...et","latin":"et...et","headword":"et...et","letter":"e","pos":"","posGroup":"other","english":"both…and","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"etenim","latin":"etenim","headword":"etenim","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"and indeed, for","forms":["etenim"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Fateor mē lacrimās effūdisse cum oculōs eius clausissem, sed illae lacrimae et mīlitem et amīcum decēbant; {{etenim}} malus amīcus fuissem, nisi lacrimās effūdissem super corpus amīcī mortuī, cum ille sanguinem suum prō mē effūdisset.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"etiam","latin":"etiam","headword":"etiam","letter":"e","pos":"adverb","posGroup":"adverb","english":"also, even, yet; also, even; still, yet, even","forms":["etiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid {{etiam}} de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"etiamnunc","latin":"etiamnunc","headword":"etiamnunc","letter":"e","pos":"adverb","posGroup":"adverb","english":"even now; still, even now; yet, still","forms":["etiamnunc"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eōrum inter rāmōs {{etiamnunc}} incolae illīus locī flōrum serta pōnere solent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"etiamsi","latin":"etiamsi","headword":"etiamsi","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"even if, although","forms":["etiamsī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cui rēx prōmīsit nihil eī sē negafilrum, etiamsī dīmidiam regnī suī partem peteret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"etsi","latin":"etsī","headword":"etsī","letter":"e","pos":"conjunction","posGroup":"conjunction","english":"even if, although","forms":["etsi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Etsi}} mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"euax","latin":"euax","headword":"euax","letter":"e","pos":"","posGroup":"other","english":"exclamation of joy","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"euge","latin":"euge","headword":"euge","letter":"e","pos":"interjection","posGroup":"interjection","english":"oh, good! fine! well done! (delight/pleasure/surprise, sometimes ironic)","forms":["Eugē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: [ad Amphitryōnem] Eugē, optimē!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"euhios","latin":"Euhios, Euhii","headword":"Euhios","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"Bacchus, title given to Bacchus","forms":["Euhiōn"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pars ^Hymenaee!\" canunt, pars clàmant {{Euhiōn}},","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"euhoe","latin":"euhoe","headword":"euhoe","letter":"e","pos":"interjection","posGroup":"interjection","english":"cry of joy used by the votaries of Bacchus","forms":["euhoe"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"157 Tàlem té Bacchus, Satyrīs clāmantibus *{{euhoe}}!\",","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eum","latin":"eum","headword":"eum","letter":"e","pos":"pronoun","posGroup":"pronoun","english":"him","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"euminis","latin":"Euminis, Eumenidos/is","headword":"Euminis","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Fury/Eumenide; (usu. pl.); (euphemistically) the gracious/benevolent ones","forms":["Eumenidēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Eumenidēs}} quidem lacrimās nōn retinēbant nec rēx Plūtō nec coniūnx Proserpina eī ōrantī negāre potuērunt; Eurydicēn vocant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"euripus","latin":"euripus, euripi","headword":"euripus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"channel, canal","forms":["Eurīpī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi sacrificiō Apollinī factō, Chalcidem ad spectāculum Eurīpī Euboeaeque, tantae īnsulae ponte continentī iūnctae, dēscendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"europa","latin":"Eurōpa, -ae","headword":"Eurōpa","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Europa; Europe","forms":["Eurōpā","Eurōpae","Eurōpam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mārcus: “Barabia in Eurōpā, in Āfricā, in Asiā {i}nōn {/i} est!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"eurus","latin":"Eurus, -ī","headword":"Eurus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"southeast wind; east wind","forms":["Eure","EURŌS","Eurum","Eurus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"DĀ {{EURŌS}}. [Ubīque sequere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"eurydice","latin":"Eurydicē, -ēs","headword":"Eurydicē","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Eurydice (wife of Orpheus)","forms":["Eurydicē","Eurydicēn","Eurydicēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum igitur Orpheus {{Eurydicēn}}, pulcherrimam virginem, valdē amāret neque iam sine eā vīvere posset, eam uxōrem dūcere cupiēbat, quae tamen eius amōrem contemnere vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"eva","latin":"Eva, Evae","headword":"Eva","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"Eve","forms":["Ēva","Ēvam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nōmen prīmae mulieris fuit Ēva.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"evadere","latin":"(ēvādō) ēvādere (< vādere)","headword":"ēvādere","letter":"e","pos":"","posGroup":"other","english":"get out, escape, pass, turn out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"evado","latin":"evado, evadere, evasi, evasus","headword":"evado","letter":"e","pos":"verb","posGroup":"verb","english":"evade, escape; avoid","forms":["ēvādat","ēvādendī","ēvādit","ēvādunt","ēvāsī","ēvāsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"IOsaphātus tamen cum Achabō Isrāēlītārum rēge impiō amīcitiam iūnxit, quae rēs illī magnō damnō fuit: nam, coniuncfīs cōpiīs, pugnārunt adversus rēgem Syriae: in proeliō Achabus interfectus est, parumque āfuit quīn perīret et ipse IOsaphātus, nec sine auxiliō dīvīnō incolumīs ēvāsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"evander","latin":"Evander, Evandri","headword":"Evander","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"Evander; (Arcadian king, ally of Aeneas, father of Pallas)","forms":["Euander","Euandrō","Euandrum","Evandrī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Auget uterque suās externō rōbore vīrēs,\net multī Rutulōs, multī Trōiāna tuentur\ncastra, neque Aenēās Evandrī ad moenia frūstrā\n[īvit; nam Pallas, fīlius Evandrī, ad bellum pugnandum missus est.]\n[Bellum] perstat, habetque deōs pars utraque, quodque\ndeōrum est īnstar, habent animōs. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"evanescere","latin":"(ēvānēscō) ēvānēscere, -uisse","headword":"ēvānēscere","letter":"e","pos":"","posGroup":"other","english":"vanish, disappear","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"evanesco","latin":"evanesco, evanescere, evanui, -","headword":"evanesco","letter":"e","pos":"verb","posGroup":"verb","english":"vanish/disappear; pass/fade/die (away/out); lapse; become weak/void/forgotten","forms":["ēvānuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec locūtus deus ex oculīs Aenēae in tenuēs aurās ēvānuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"evehere","latin":"(ēvehō) ēvehere (< vehere)","headword":"ēvehere","letter":"e","pos":"","posGroup":"other","english":"carry out, pass. ride out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eveho","latin":"eveho, evehere, evexi, evectus","headword":"eveho","letter":"e","pos":"verb","posGroup":"verb","english":"carry away, convey out; carry up; exalt; jut out, project","forms":["ēvectī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quam incōndītam turbam cum vixdum in rīpam ēgressī clāmōre ac tumultū fugāssent, in statiōnem quoque prō vallō locātam atque ipsās prope portās ēvectī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"evenio","latin":"ēveniō, -īre, ēvēnī, ēventum","headword":"ēveniō","letter":"e","pos":"verb","posGroup":"verb","english":"turn out, come about","forms":["ēvēnerant","ēvēnerat","ēvēnēre","ēvēnerit","ēvēnērunt","ēveniat","ēvenient","ēveniet","ēvenīre","ēvenit","ēveniunt","ēventū","ēventūrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ita indignātiō patris et damnum mihi ēvenient prō eius benevolentia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"evenire","latin":"(ēveniō) ēvenīre (< venīre)","headword":"ēvenīre","letter":"e","pos":"","posGroup":"other","english":"happen, fall by lot","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eventum","latin":"eventum, eventi","headword":"eventum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"occurrence, event; issue, outcome","forms":["eventum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ipse paulum ex eo loco cum legione progressus, ubi constiterat, {{eventum}} pugnae exspectabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"eventus","latin":"ēventus, -ūs","headword":"ēventus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"outcome, result; outcome","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"everbero","latin":"everbero, everberare, everberavi, everberatus","headword":"everbero","letter":"e","pos":"verb","posGroup":"verb","english":"beat violently","forms":["ēverberat"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mulier fit audiendī cupidior: sēcrētum reī et silentium puerī animum eius ad inquīrendum ēverberat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"evertere","latin":"(ēvertō) ēvertere","headword":"ēvertere","letter":"e","pos":"verb","posGroup":"verb","english":"overturn, overthrow; to overthrow, demolish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"everto","latin":"everto, evertere, everti, eversus","headword":"everto","letter":"e","pos":"verb","posGroup":"verb","english":"overturn, turn upside down; overthrow, destroy, ruin","forms":["ēversā","ēversam","ēvertendās","ēvertere","ēvertērunt","ēvertēs","ēvertit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Salomōnī Roboāmus fīlius successit: is imperium culpā paternā iam nūtāns stultitiā suā ēvertit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"evigilo","latin":"evigilo, evigilare, evigilavi, evigilatus","headword":"evigilo","letter":"e","pos":"verb","posGroup":"verb","english":"be wakeful; watch throughout the night; devise or study with careful attention","forms":["ēvigilāvī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ante lūcem ēvigilāvī dē somnō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"evincere","latin":"(ēvincō) ēvincere (< vincere)","headword":"ēvincere","letter":"e","pos":"","posGroup":"other","english":"conquer; persuade","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"evinco","latin":"evinco, evincere, evici, evictus","headword":"evinco","letter":"e","pos":"verb","posGroup":"verb","english":"overcome, conquer, subdue, overwhelm, defeat utterly; prevail, bring to pass","forms":["ēvicēre","ēvīcit","ēvicta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ubi Trōiānae rēmīs avidamque Charybdin\nēvicēre ratēs, cum iam prope lītus adessent\nAusonium, Libycās ventō referuntur ad ōrās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"evito","latin":"ēvītō, -āre, -āvī, -ātum","headword":"ēvītō","letter":"e","pos":"verb","posGroup":"verb","english":"avoid, shun","forms":["ēvītat","ēvītāvisset","ēvītāvit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ita Iuppiter victor erat; Callistō autem, nympha misera, silvās nōtās et amīcās nōtās et deam Diānam ēvītāvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"evocare","latin":"(ēvocō) ēvocāre","headword":"ēvocāre","letter":"e","pos":"verb","posGroup":"verb","english":"call out, summon; to call out, summon","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"evocator","latin":"evocator, evocatoris","headword":"evocator","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"one who orders out troops","forms":["ēvocātōrem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tūne eum quem esse hostem comperistī, quem ducem bellī futūrum vidēs, quem exspectārī imperātōrem in castrīs hostium sentīs, auctōrem sceleris, prīncipem coniūrātiōnis, ēvocātōrem servōrum et cīvium perditōrum, exīre patiēre, ut abs tē nōn ēmissus ex urbe, sed immissus in urbem esse videātur?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"evocatus","latin":"evocatus, evocati","headword":"evocatus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"veteran; volunteer; veterans again called to service (pl.)","forms":["Ēvocāte","evocati","evocatis","ēvocātōs","evocatus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, pari aetate et gratia sed genere dispari, quem Caesar ab Diviciaco sibi traditum ex humili loco ad summam dignitatem perduxerat, in equitum numero convenerant nominatim ab eo {{evocati}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"evoco","latin":"evoco, evocare, evocavi, evocatus","headword":"evoco","letter":"e","pos":"verb","posGroup":"verb","english":"call forth; lure/entice out; summon, evoke","forms":["ēvocā","ēvocat","evocata","ēvocāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deprensis navibus circiter quinquaginta celeriterque coniunctis atque eo militibus iniectis et rei novitate perterritis oppidanis, quorum magna pars erat ad bellum {{evocata}}, sine contentione oppido potitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"evolare","latin":"(ēvolō) ēvolāre, ēvolāvisse, ēvolātum","headword":"ēvolāre","letter":"e","pos":"verb","posGroup":"verb","english":"fly away; to fly out, fly away","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"evolo","latin":"evolo, evolare, evolavi, evolatus","headword":"evolo","letter":"e","pos":"verb","posGroup":"verb","english":"fly away, fly up/out/forth; rush out/forth","forms":["ēvolābimus","ēvolantēs","evolaverunt","ēvolāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Illi subito ex omnibus partibus {{evolaverunt}} murumque celeriter compleverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"evolvere","latin":"(ēvolvō) ēvolvere, ēvolvisse, ēvolūtum","headword":"ēvolvere","letter":"e","pos":"","posGroup":"other","english":"unroll","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"evolvo","latin":"ēvolvō, -ere, -volvī, -volūtum","headword":"ēvolvō","letter":"e","pos":"verb","posGroup":"verb","english":"roll out, unroll","forms":["ēvolūtūrus","Ēvolve","ēvolvit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mēdus, quī legere nōn didicit, Lȳdiae librum reddit et rogat ut aliquid sibi lēgat; quae continuō librum ēvolvit et \"Legam tibi\" inquit \"dē virō claudō cui imperāvit ut surgeret et tolleret lectum suum et ambulāret.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ex","latin":"ex","headword":"ex","letter":"e","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) out of, by","forms":["ex"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore {{ex}} hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ex / e","latin":"ex / ē","headword":"ex / ē","letter":"e","pos":"preposition","posGroup":"preposition","english":"out of, from (+ abl.)","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ex composito","latin":"ex compositō","headword":"ex compositō","letter":"e","pos":"","posGroup":"other","english":"according to agreement","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exactus","latin":"exactus, exacta, exactum","headword":"exactus","letter":"e","pos":"adjective","posGroup":"adjective","english":"exact, accurate","forms":["exāctā","exāctōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tertiō annō post rēgēs {{exāctōs}} Tarquinius, cum suscipī nōn posset in rēgnum neque eī Porsenna, quī pācem cum Rōmānīs fēcerat, praestāret auxilium, Tusculum sē contulit, quae cīvitās nōn longē ab urbe est, atque ibi per quattuordecim annōs prīvātus cum uxōre cōnsenuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exaequare","latin":"(exaequō) exaequāre","headword":"exaequāre","letter":"e","pos":"","posGroup":"other","english":"make equal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exaequo","latin":"exaequo, exaequare, exaequavi, exaequatus","headword":"exaequo","letter":"e","pos":"verb","posGroup":"verb","english":"equalize, make equal; regard as equal; be equal (to)","forms":["exaequanda","exaequātō","exaequātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cornēliō Scīpiōne — adiuvante Eumene, rēge Pergamī — pāx data est eā condiciōne 'ut omnibus prōvinciīs citrā Taurum montem cēderet.' Cornēlius Scīpiō, quī cum Antiochō dēbellāverat, eō cognōmine frātrī {{exaequātus}} 'Asiāticus' appellātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exagitare","latin":"(exagitō) exagitāre","headword":"exagitāre","letter":"e","pos":"verb","posGroup":"verb","english":"stir, worry, harass; to harass, drive about","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exagito","latin":"exagito, exagitare, exagitavi, exagitatus","headword":"exagito","letter":"e","pos":"verb","posGroup":"verb","english":"drive out; stir up, disturb continually, harass; attack, scold, discuss","forms":["exagitābat","exagitanda","exagitātī","exagitātum","exagitātus","exagitāverant"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Marcius Coriolānus, {{exagitātus}} vexātusque ā tribūnīs plēbis, ad Volscōs, quī tum hostēs erant, ā rē pūblicā dēscīvit bellumque populō Rōmānō fēcit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"examino","latin":"examino, examinare, examinavi, examinatus","headword":"examino","letter":"e","pos":"verb","posGroup":"verb","english":"weigh, examine, consider","forms":["examinat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nērēides nymphaeque simul, quae vellera mōtīs\nnūlla trahunt digitīs nec fīla sequentia dūcunt,\nherbās dispōnunt sparsōsque sine ōrdine flōrēs\nsēcernunt calathīs variāsque colōribus herbās;\nipsa, quod hae faciunt, opus exigit, ipsa, quis ūsus\nquōve sit in foliō, quae sit concordia mixtīs,\nnōvit et advertēns pensās {{examinat}} herbās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exanimare","latin":"(exanimō) exanimāre","headword":"exanimāre","letter":"e","pos":"","posGroup":"other","english":"kill; die","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exanimo","latin":"exanimo, exanimare, exanimavi, exanimatus","headword":"exanimo","letter":"e","pos":"verb","posGroup":"verb","english":"kill, deprive of life; scare, alarm greatly; tire, exhaust; be out of breath","forms":["exanimātam","exanimato","exanimātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis {{exanimato}} alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exanimus","latin":"exanimus, exanima, exanimum","headword":"exanimus","letter":"e","pos":"adjective","posGroup":"adjective","english":"dead; lifeless","forms":["exanimī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"corpore ut exanimī crūdēlia lūmina pāscās.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"exardescere","latin":"(exārdēscō) exārdēscere, -ārsisse","headword":"exārdēscere","letter":"e","pos":"","posGroup":"other","english":"flare up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exardo","latin":"exardo, exardere, exarsi, exarsus","headword":"exardo","letter":"e","pos":"verb","posGroup":"verb","english":"kindle; inflame; break out","forms":["exārsērunt","exārsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Antiochus, ubi audīvit vīctum esse Apollōnium, Īra {{exārsit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exaudio","latin":"exaudiō, exaudīre","headword":"exaudiō","letter":"e","pos":"verb","posGroup":"verb","english":"hear plainly or favorably","forms":["exaudiēbantur","exaudīre","exaudīrent","exaudiri","exaudit","exaudīta","exaudito","exaudīverat","exaudīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non {{exaudito}} sono tubae, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excalceo","latin":"excalceo, excalceare, excalceavi, excalceatus","headword":"excalceo","letter":"e","pos":"verb","posGroup":"verb","english":"remove the shoes from","forms":["Excalceā"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Excalceā mē, puer!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"excedere","latin":"(excēdō) excēdere (< cēdere)","headword":"excēdere","letter":"e","pos":"verb","posGroup":"verb","english":"go away, depart; to leave, go out (with abl.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"excedo","latin":"excedo, excedere, excessi, excessus","headword":"excedo","letter":"e","pos":"verb","posGroup":"verb","english":"pass, withdraw, exceed; go away/out/beyond; die","forms":["excedant","excedebant","excēdēbat","excēdēns","excēdere","excēderet","excesserant","excesserint","excesserunt","excessit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Depopulata Gallia Cimbri magnaque inlata calamitate finibus quidem nostris aliquando {{excesserunt}} atque alias terras petierunt; iura, leges, agros, libertatem nobis reliquerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excellens","latin":"excellēns (gen. excellentis)","headword":"excellēns","letter":"e","pos":"adjective","posGroup":"adjective","english":"outstanding; outstanding, excellent","forms":["excellēns","excellente"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Erat Saūlī ingēns statūra et fōrma {{excellēns}}, adeō ut dignitās corporis dignitātī rēgiae pulchrē convenīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"excellere","latin":"(excellō) excellere","headword":"excellere","letter":"e","pos":"","posGroup":"other","english":"be outstanding, excel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excello","latin":"excello, excellere, -, excelsus","headword":"excello","letter":"e","pos":"verb","posGroup":"verb","english":"be eminent/preeminent; excel","forms":["excellebant","excellere","excellit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Antōnium et Hortēnsium, quī tum arte ōrātōriā {{excellebant}}, assiduē audiēbat, ac simul apud doctōrēs Graecōs, Molōnem rhētorem et Diodōtum philosophum, discēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"excelsum","latin":"excelsum, excelsi","headword":"excelsum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"height, high place/ground/altitude; eminence; high position/rank/station","forms":["excelsum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In dē- mentô levātum in tribūnal {{excelsum}} Mercurius rapiēbat. cornū abundantī et très Parcae aurea pēnsa torquentēs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"excelsus","latin":"excelsus, -a, -um","headword":"excelsus","letter":"e","pos":"adjective","posGroup":"adjective","english":"lofty, high","forms":["excelsō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Vidēsne illam urbem quae, pārēre populō Rōmānō coācta per mē, renovat prīstina bella nec potest quiēscere?' — ostendēbat autem Karthāginem dē excelsō et plēnō stellārum illūstrī et clārō quōdam locō — 'ad quam tū oppugnandam nunc vēnis paene mīles.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"excepto","latin":"excepto, exceptare, exceptavi, exceptatus","headword":"excepto","letter":"e","pos":"verb","posGroup":"verb","english":"take out, take up; inhale, take (to oneself)","forms":["exceptans"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Fabius, centurio legionis VIII., quem inter suos eo die dixisse constabat excitari se Avaricensibus praemiis neque commissurum ut prius quisquam murum ascenderet, tres suos nactus manipulares atque ab eis sublevatus murum ascendit; hos ipse rursus singulos {{exceptans}} in murum extulit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exceptus","latin":"exceptus, excepta, exceptum","headword":"exceptus","letter":"e","pos":"adjective","posGroup":"adjective","english":"only; excepted","forms":["exceptus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi {{exceptus}} benignē ab ignārīs cōnsiliī, cum post cēnam in hospitāle cubiculum dēductus esset, amōre ārdēns, postquam satis tūta circa sopītīque omnēs vidēbantur, strictō gladiō ad dormientem Lūcrētiam venit, sinistrāque manū mulieris pectore oppressō, 'Tacē, Lūcrētia!' inquit, 'Sextus Tarquinius sum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"excerpere","latin":"(excerpō) excerpere, -sisse, -tum","headword":"excerpere","letter":"e","pos":"verb","posGroup":"verb","english":"pick out; to pick out, excerpt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"excessus","latin":"excessus, -ūs (< excēdere Cap. XXXVIII)","headword":"excessus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"departure, death","forms":["excessū"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ab excessū dīvī Augustī, II.9–11.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"excidere","latin":"(excīdō) excīdere, -disse, -sum","headword":"excīdere","letter":"e","pos":"","posGroup":"other","english":"destroy; fall out, be dropped","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excidium","latin":"excidium, -ī","headword":"excidium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"destruction","forms":["excidiō","excidium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx Assyriōrum bellum Ezechiae intulit: Hierosolymam obsidiōne cīnxit, minitāns urbis {{excidium}}, nisi cīvēs matlirā dēditiōne sibi cōnsulerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"excido","latin":"excidō, -ere, -cidī","headword":"excidō","letter":"e","pos":"verb","posGroup":"verb","english":"to fall out, slip from the mind","forms":["exciderant","exciderat","excidere","Exciderunt","excidit","excīdunt","excīsae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas {{excidere}} conatus esset, a multitudine oppressus ac sibi desperans, multis iam vulneribus acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem certe vitae prospiciam, quos cupiditate gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excio","latin":"excio, excire, excivi, excitus","headword":"excio","letter":"e","pos":"verb","posGroup":"verb","english":"rouse; call out send for; summon; evoke","forms":["excit","excitam","excitī","excīvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi modicō praesidiō relictō, ēgressus cum omnibus cōpiīs partem mīlitum locīs occultīs sedēre in īnsidiīs iussit, ipse cum parte māiōre atque omnī equitātū profectus ad ipsās prope portās Fīdēnārum accēdēns hostēs ad pugnam {{excit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"excipere","latin":"(excipō) excipere (< capere)","headword":"excipere","letter":"e","pos":"","posGroup":"other","english":"receive, catch","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excipio","latin":"excipiō, -ere, excēpī, exceptum","headword":"excipiō","letter":"e","pos":"verb","posGroup":"verb","english":"take out, receive; take up, receive; to receive, catch up","forms":["exceperunt","excēpī","excēpissent","excepit","exceptī","excipere","exciperem","exciperēs","exciperet","excipiet","Excipimus","excipit","excipite","excipitur","excipiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps {{excipiunt}} et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excire","latin":"(exciō) excīre, excīvisse, excitum","headword":"excīre","letter":"e","pos":"","posGroup":"other","english":"call out, summon","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excitat","latin":"excitat, excitāre","headword":"excitat","letter":"e","pos":"verb","posGroup":"verb","english":"wake up, arouse; wakes, rouses","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"excitatus","latin":"excitātus, -a, -um (< excitāre Caps. XIV, XIX)","headword":"excitātus","letter":"e","pos":"","posGroup":"other","english":"lively, vigorous, loud","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excito","latin":"excito, excitare, excitavi, excitatus","headword":"excito","letter":"e","pos":"verb","posGroup":"verb","english":"wake up, stir up; cause; raise, erect; incite; excite, arouse","forms":["excitā","excitabat","excitābor","excitābuntur","excitāminī","excitāmur","excitandī","excitandō","excitant","excitantur","excitāre","excitāret","excitārētur","excitari","excitās","excitat","excitāta","excitātae","excitāte","excitātī","excitātō","excitātum","excitātur","excitātus","excitāvit","excitet","excitētis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis {{excitari}} potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exclamat","latin":"exclāmat","headword":"exclāmat","letter":"e","pos":"verb","posGroup":"verb","english":"exclaims, cries out","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"exclamo","latin":"exclāmō, exclāmāre","headword":"exclāmō","letter":"e","pos":"verb","posGroup":"verb","english":"cry out, exclaim","forms":["exclāmāns","exclāmat","exclāmāvērunt","exclamāvisset","exclāmāvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia {{exclāmat}}: “Nōn sum fessa!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"excludere","latin":"(exclūdō) exclūdere (< claudere)","headword":"exclūdere","letter":"e","pos":"","posGroup":"other","english":"shut out, cut off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excludo","latin":"excludo, excludere, exclusi, exclusus","headword":"excludo","letter":"e","pos":"verb","posGroup":"verb","english":"shut out, shut off; remove; exclude; hinder, prevent","forms":["excludere","exclūserat","exclūsī","exclusus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore {{exclusus}} in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excogitare","latin":"(excōgitō) excōgitāre, excōgitāvisse, excōgitātum","headword":"excōgitāre","letter":"e","pos":"verb","posGroup":"verb","english":"think out, devise; to devise, think out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"excogito","latin":"excogito, excogitare, excogitavi, excogitatus","headword":"excogito","letter":"e","pos":"verb","posGroup":"verb","english":"think out; devise, invent, contrive","forms":["excōgitāvī","excōgitāvistī","excōgitāvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Quā dē causā cōnsilium eam rapiendī {{excōgitāvit}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"excors","latin":"excors, (gen.), excordis","headword":"excors","letter":"e","pos":"adjective","posGroup":"adjective","english":"silly, stupid","forms":["excors"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quis enim est tam {{excors}} quem ista moveant?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"excruciare","latin":"(excruciō) excruciāre, excruciāvisse, excruciātum","headword":"excruciāre","letter":"e","pos":"","posGroup":"other","english":"torture, torment","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"excrucio","latin":"excrucio, excruciare, excruciavi, excruciatus","headword":"excrucio","letter":"e","pos":"verb","posGroup":"verb","english":"torture; torment","forms":["excruciatos","excruciātum","excruciātur","excrucior"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter {{excruciatos}} interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excubia","latin":"excubia, excubiae","headword":"excubia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"watching (pl.); keeping of a watch/guard/vigil; the watch, soldiers on guard","forms":["excubiās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cūr audet Ulixēs īre per {{excubiās}} et sē committere noctī perque ferōs ēnsēs nōn tantum moenia Trōum, vērum etiam summās arcēs intrāre suāque ēripere aede deam raptamque adferre per hostēs?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"excubiae","latin":"excubiae, -ārum","headword":"excubiae","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"sentries, night-watch","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"excubitor","latin":"excubitor, excubitoris","headword":"excubitor","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"sentinel; watchman","forms":["excubitoribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Castra opportunis locis erant posita, ibique castella XXIII facta, quibus in castellis interdiu stationes ponebantur, ne qua subito: eruptio fieret; haec eadem noctu {{excubitoribus}} ac firmis praesidiis tenebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excubo","latin":"excubo, excubare, excubui, excubitus","headword":"excubo","letter":"e","pos":"verb","posGroup":"verb","english":"sleep/lie in the open/out of doors; keep watch; be attentive","forms":["excubabant","excubare","excubaret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis {{excubare}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excudo","latin":"excudo, excudere, excudi, excusus","headword":"excudo","letter":"e","pos":"verb","posGroup":"verb","english":"strike out; forge; fashion; print (Erasmus)","forms":["excūdit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ac prīmum silicī scintillam {{excūdit}} Achātēs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"exculco","latin":"exculco, exculcare, exculcavi, exculcatus","headword":"exculco","letter":"e","pos":"verb","posGroup":"verb","english":"trample down","forms":["exculcabantur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huc teretes stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra {{exculcabantur}}; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"excurrere","latin":"(excurrō) excurrere, excucurrisse or excurrisse, excursum","headword":"excurrere","letter":"e","pos":"verb","posGroup":"verb","english":"run out, rush out; to run out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"excurro","latin":"excurro, excurrere, excucurri, excursus","headword":"excurro","letter":"e","pos":"verb","posGroup":"verb","english":"run out; make an excursion; sally; extend; project","forms":["excurram","excurrēns","excurrente","excurrentēs","excurrērunt","excurrisset","excurrit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Canis laetus ē domō {{excurrit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"excursio","latin":"excursiō, -ōnis ( f.)","headword":"excursiō","letter":"e","pos":"","posGroup":"other","english":"sortie, sally","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"excusare","latin":"(excūsō) excūsāre, excūsāvisse,  excūsātum","headword":"excūsāre","letter":"e","pos":"verb","posGroup":"verb","english":"excuse; to excuse","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"excusat","latin":"excūsat","headword":"excūsat","letter":"e","pos":"verb","posGroup":"verb","english":"excuses","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"excusatio","latin":"excusatio, excusationis","headword":"excusatio","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"excuse","forms":["excūsātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iūdās respondit: fateor, rēs est manifēsta; nūllam possumus {{excūsātiōnem}} affēre, nec audēmus petere veniam aut spērāre; nōs omnēs erimus servī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"excuso","latin":"excuso, excusare, excusavi, excusatus","headword":"excuso","letter":"e","pos":"verb","posGroup":"verb","english":"excuse/justify/explain; make excuse for/plead as excuse; allege; absolve/exempt","forms":["excūsāre","excūsāret","excūsārī","excūsat","excūsātum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tantalus vēro, aliquantum turbātus, ut sē {{excūsāret}}, deīs tālia verba dicēbat “Ignōscite mihi dēbili: nimium ego vīnī biberam atque ēbrius nūgās dīcere coepī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"excutio","latin":"excutio, excutere, excussi, excussus","headword":"excutio","letter":"e","pos":"verb","posGroup":"verb","english":"shake out or off; cast out; search, examine","forms":["Excussimus","excute","excutere","excutiendīs","excutiendus","excutiente","excutiēs","excutitur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dé-cīdere -disse « dé * cadere dēciderit, digitīs {{excutiendus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exemplar","latin":"exemplar, -āris (n.)","headword":"exemplar","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"pattern, model","forms":["exemplar"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et ideô ante HŌC MONVMENTVM HĒRĒDEM NŌN SEQVATVR ūnum lactem (acc) : idem lac aquam lîberam : libenātem inter quattuor viās sitae vîcësima -ae_ﬁ vîcësima pars (Van) pretiī suî quam servus {{exemplar}} -ārīs n: complūra hērēdem nê sequātur : nē hë- rëdī lēgētur (H.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"exemplo","latin":"exemplo, exemplare, exemplavi, exemplatus","headword":"exemplo","letter":"e","pos":"verb","posGroup":"verb","english":"adduce/serve as example/model/pattern; form after a pattern","forms":["exemplō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post hunc Ochosiās fīlius rēgnum adeptus est, nec diū tenuit, nam pessimī p ātrīs exemplō ad vitia impulsūs, miserē interiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exemplum","latin":"exemplum, -ī","headword":"exemplum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"example, model; example","forms":["exempla","exemplī","exemplīs","exemplum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cuius rei si {{exemplum}} non haberemus, tamen libertatis causa institui et posteris prodi pulcherrimum iudicarem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exemptus","latin":"exemptus, exempta, exemptum","headword":"exemptus","letter":"e","pos":"adjective","posGroup":"adjective","english":"exempt","forms":["exēmpta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam {{exēmpta}} famēs epulīs mēnsaeque remōtae,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"exeo","latin":"exeō, -īre, -iī, -itum","headword":"exeō","letter":"e","pos":"verb","posGroup":"verb","english":"go out, depart","forms":["exeat","exeunt","exeunte","exeuntem","exī","exībit","exiēns","exierīs","exire","exīret","exit","exitu","exitum","exitūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi neminem in aequum locum sese demittere sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto {{exitu}} portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exequia","latin":"exequia, exequiae","headword":"exequia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"funeral procession/rites/services (pl.), obsequies; [~ ire => attend funeral]","forms":["exequiae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Urbs erat, et septem possēs ostendere portās:\nhae prō nōmine erant, et quae foret illa, docēbant;\nante urbem {{exequiae}} tumulīque ignēsque pyraeque\neffūsaeque comās et apertae pectora mātrēs\nsignificant lūctum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exerceo","latin":"exerceō, -ēre, -uī, -itum","headword":"exerceō","letter":"e","pos":"verb","posGroup":"verb","english":"train, exercise","forms":["exerce","exerceātur","exercēbar","exercēbat","exercent","exercentem","exercēre","exerceri","exercet","exercēte","exercētur","exercuerit","exercuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Romanos in illis ulterioribus munitionibus animine causa cotidie {{exerceri}} putatis?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exercere","latin":"(exerceō) exercēre, -cuisse, -citum","headword":"exercēre","letter":"e","pos":"","posGroup":"other","english":"exercise, practice, worry","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exercitare","latin":"(exercitō) exercitāre","headword":"exercitāre","letter":"e","pos":"","posGroup":"other","english":"train, exercise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exercitatio","latin":"exercitātiō, -ōnis ( f.)","headword":"exercitātiō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"exercise, practice","forms":["exercitātiō","exercitātiōnibus","exercitātiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huic ego doctōrī et eius artibus variīs atque multīs ita eram tamen dēditus ut ab {{exercitātiōnibus}} ōrātōriīs nūllus diēs vacuus esset.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exercitatus","latin":"exercitātus, -a, -um","headword":"exercitātus","letter":"e","pos":"adjective","posGroup":"adjective","english":"practiced, proficient","forms":["exercitātior","exercitātōs","exercitātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīs ēgregiīs magistrīs in ēloquentiā {{exercitātus}} causās agere coepit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exercitium","latin":"exercitium, exercitii","headword":"exercitium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"exercise; training; practice; proficiency/skill; written exercises (pl.)","forms":["exercitiīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Eō confliīxit multitiīdō hominum, quibus cordī erant lēgēs dīvīnae, brevīque ad speciem iiisfī {{exercitiīs}} crēvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exercitus","latin":"exercitus, exercitūs","headword":"exercitus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"army","forms":["exercitibus","exercitu","exercitui","exercitum","exercitus","exercituum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad {{exercitum}} venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exhaurio","latin":"exhaurio, exhaurire, exhausi, exhaustus","headword":"exhaurio","letter":"e","pos":"verb","posGroup":"verb","english":"draw out; drain, drink up, empty; exhaust, impoverish; remove; end","forms":["exhauriāmus","exhauriēns","exhauriētur","exhaurit","exhaurīte","exhauserant","exhausit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hīc Symmachus pōculum {{exhauriēns}} “Bene valē” inquit, “discipule Epicūrī!” Sed eō ipsō tempore fulgur clārissimum tabernam obscūram illūstrat, sequente tonitrū māximō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"exhaurire","latin":"(exhauriō) exhaurīre, exhausisse, exhaustum","headword":"exhaurīre","letter":"e","pos":"verb","posGroup":"verb","english":"drain, drink up; to drain, empty","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"exhaustus","latin":"exhaustus, exhausta, exhaustum","headword":"exhaustus","letter":"e","pos":"adjective","posGroup":"adjective","english":"exhausted","forms":["exhaustā","exhāustīs","exhaustō","exhaustōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ex manibus puerī, quī ingentī metū afficiēbātur, habēnae dēlāpsae sunt: cum autem equī in tergō sēnsissent habēnās relictās esse, per āera sine lēge errant et ignōtās regiōnēs percurrunt; cum ad montēs campōsque accēdunt, terrā, exhaustā aquā, sicca subitō fit, et ūritur igne; ūruntur et arborēs in agrīs;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"exhibeo","latin":"exhibeo, exhibere, exhibui, exhibitus","headword":"exhibeo","letter":"e","pos":"verb","posGroup":"verb","english":"present; furnish; exhibit; produce","forms":["exhibeat","exhibeātur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ex-hibé&rē — ostendere; noxque diēs- {{exhibeat}} vultüs noxque","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exhorto","latin":"exhorto, exhortare, exhortavi, exhortatus","headword":"exhorto","letter":"e","pos":"verb","posGroup":"verb","english":"encourage","forms":["exhortā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Et sānē nôlentem mē negôtium meum agere exhortā- vit mathēmaticus, quî vēnerat forte in colôniam nostram, Graeculiô, Seräpa nômine, cônsiliätor deôrum!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"exhortor","latin":"exhortor, exhortārī, exhortātus sum","headword":"exhortor","letter":"e","pos":"verb","posGroup":"verb","english":"urge on, encourage","forms":["exhortātus","exhortor"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iam curru īnstābat Achillēs āgmina perque aciēs aut Cygnum aut Hectora quaerēns; occurrit Cygnō (decimum dīlāta in annum mors Hectoris erat): tum ... {{exhortātus}} equōs currum dīrēxit in hostem concutiensque suīs vibrantia tēla lacertīs “Quisquis es, ō iuvenis” dīxit “sōlāmen habētō mortis, ab Aeacidē quod sīs iugulātus Achille!”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exigere","latin":"(exigō) exigere (< agere)","headword":"exigere","letter":"e","pos":"","posGroup":"other","english":"drive out, exact, require, pass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exigo","latin":"exigo, exigere, exegi, exactus","headword":"exigo","letter":"e","pos":"verb","posGroup":"verb","english":"drive out, expel; finish; examine, weigh","forms":["exēgit","exigat","exigere","exiget","exigit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Multa deinceps bella Dāvīd prosperē gessit contrā Philistaeōs, rēbusque forīs et domī compositīs, reliquum vītae tempus in flōrentī pāce {{exēgit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exiguus","latin":"exiguus, -a, -um","headword":"exiguus","letter":"e","pos":"adjective","posGroup":"adjective","english":"small, scanty","forms":["exigua","exiguam","exiguās","exigue","exiguī","exiguō","exiguum","exiguus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non multum adiuvabant, alteri non magnis facultatibus, quod civitas erat {{exigua}} et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exilio","latin":"exilio, exilire, exilui, -","headword":"exilio","letter":"e","pos":"verb","posGroup":"verb","english":"spring/leap/burst forth/out, leap up, start up, bound; emerge into existence","forms":["exiliō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"*Sit modus exiliō,\" dīxit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exilis","latin":"exilis, exile, exilior -or -us, exilissimus -a -um","headword":"exilis","letter":"e","pos":"adjective","posGroup":"adjective","english":"small, thin; poor","forms":["exīlēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Septem spīcae plēnae ēnāscēbantur in ūnō culmō, aliaeque totidem {{exīlēs}} succrēscēbant, ēspīcās plēnās cōnsūmēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eximere","latin":"(eximō) eximere (< emere)","headword":"eximere","letter":"e","pos":"","posGroup":"other","english":"take away, remove","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"eximius","latin":"eximius, -a, -um","headword":"eximius","letter":"e","pos":"adjective","posGroup":"adjective","english":"choice, outstanding","forms":["eximia","eximiae","eximiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ecce statim Rebecca, virgō {{eximia}} pulchritūdine, prōdiit, gerēns urnam hūmēris; quae dēscendit ad puteum, et implēvit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"eximo","latin":"eximo, eximere, exemi, exemptus","headword":"eximo","letter":"e","pos":"verb","posGroup":"verb","english":"remove/extract, take/lift out/off/away; banish, get rid of; free/save/release","forms":["exēmistī","exēmit","eximeret","Eximit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Id ubi rēx cognōvit, fīlium morte plectī voluit; sed recēns meritum perīculō iuvenem {{exēmit}}, nec populus tulit īnsontem ad supplicium trahī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"existimare","latin":"(exīstimō) exīstimāre, exīstimāvisse, exīstimātum","headword":"exīstimāre","letter":"e","pos":"","posGroup":"other","english":"think","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"existimo","latin":"existimo, existimare, existimavi, existimatus","headword":"existimo","letter":"e","pos":"verb","posGroup":"verb","english":"value/esteem; form/hold opinion/view; think/suppose; estimate; judge/consider","forms":["exīstimābam","existimabant","existimabat","existimabatur","existimans","existimantes","existimantur","exīstimāre","existimarent","exīstimāret","existimārī","exīstimās","exīstimat","existimatis","exīstimātur","existimaverunt","existimavit","existiment","existimet","existimētis","exīstimō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non {{existimabant}}; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exit","latin":"exit, exeunt","headword":"exit","letter":"e","pos":"verb","posGroup":"verb","english":"go out; goes out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"exitiabilis","latin":"exitiabilis, exitiabilis, exitiabile","headword":"exitiabilis","letter":"e","pos":"adjective","posGroup":"adjective","english":"destructive, deadly","forms":["exitiābile","exitiābilis"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Nerōne Imperātōre {{exitiābile}} incendium magnam Rōmae partem cōnsūmpsit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"exitium","latin":"exitium, exiti(i)","headword":"exitium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"destruction, ruin; death; mischief","forms":["exitiī","exitiō","exitium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"... cecidistī et fēmina ferrō, totque tuōs idem frātrēs, tē perdidit īdem, {{exitium}} Trōiae nostrīque orbātor, Achillēs; at postquam cecidit Paridis Phoebīque sagittīs, ‘nunc certē’ dīxī ‘nōn est metuendus Achillēs’: nunc quoque mī metuendus erat; cinis ipse sepultī in genus hoc saevit, tumulō quoque sēnsimus hostem, Aeacidae fēcunda fuī!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exitus","latin":"exitus, -ūs","headword":"exitus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"(m.) way out, end; exit, way out","forms":["exitus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra: \"Ego nōn minus dēlector nārrandō illās tabulās, nōn modo quod ipsae per sē pulcherrimae esse mihi videntur, sed etiam quia {{exitus}} tabulārum hominēs temerāriōs optimē monent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"exonerare","latin":"(exonerō) exonerāre","headword":"exonerāre","letter":"e","pos":"","posGroup":"other","english":"unburden","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exonero","latin":"exonero, exonerare, exoneravi, exoneratus","headword":"exonero","letter":"e","pos":"verb","posGroup":"verb","english":"unload, disburden, discharge","forms":["exonerāre","exonerārent","Exonerātā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Exonerātā vésîca 111ē vëslcā aquam poposclt ad æ manûs, digitôsque paululum ad- ‘ÊSÜWH spersôs in capite puerî tersit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"exopto","latin":"exopto, exoptare, exoptavi, exoptatus","headword":"exopto","letter":"e","pos":"verb","posGroup":"verb","english":"long for","forms":["exoptābant","exoptābat","exoptant","exoptātum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"AMPHITRYO: [quī uxōrem nōndum videt, ad Sōsiam] Edepol mē uxōrī {{exoptātum}} crēdō adventūrum domum,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"exordior","latin":"exordior, exordiri, exorsus sum","headword":"exordior","letter":"e","pos":"verb","posGroup":"verb","english":"begin, commence","forms":["exōrsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dē vestrī imperiī dignitāte atque glōriā, quoniam is est {{exōrsus}} ōrātiōnis meae, vidēte quem vōbīs animum suscipiendum putētis.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exordium","latin":"exōrdium, -ī","headword":"exōrdium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"beginning","forms":["exōrdia","exōrdium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam et mūrō lapideō, cuius operis {{exōrdium}} Sabīnō bellō turbātum erat, urbem cingere parat, et īnfima urbis loca circā forum aliāsque convallēs collibus interiectās cloācīs in Tiberim ductīs siccat, et aedis in Capitōliō Iovis, quam vōverat bellō Sabīnō, fundāmenta iacit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exorior","latin":"exorior, exoriri, exortus sum","headword":"exorior","letter":"e","pos":"verb","posGroup":"verb","english":"come out, come forth; bring; appear; rise, begin, spring up; cheer up","forms":["exoriāre","Exoriātur","exoriēns","exorta","exortō","exortum","exortus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Paulō post bellum {{exortum}} est inter Philistaeōs et Hebraeōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exornare","latin":"(exōrnō) exōrnāre, -āvisse, -ātum","headword":"exōrnāre","letter":"e","pos":"verb","posGroup":"verb","english":"decorate; to adorn, decorate; to decorate, adorn","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"exornatus","latin":"exornatus, exornata -um, exornatior -or -us, exornatissimus -a -um","headword":"exornatus","letter":"e","pos":"adjective","posGroup":"adjective","english":"ornamented; embellished","forms":["exōrnāta","exōrnātam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum haec ex caelō spectāret, Iūnō, deōrum rēgīna, Īridem, suam nūntiam variīs colōribus {{exōrnātam}}, vocāvit et eī imperāvit ut somnium ad Alcyonēm mitteret, quō coniugis mors nūntiārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"exorno","latin":"exorno, exornare, exornavi, exornatus","headword":"exorno","letter":"e","pos":"verb","posGroup":"verb","english":"furnish with, adorn, embellish","forms":["exōrnat","exōrnātum","exōrnātur","exōrnāverant","exōrnāvērunt","exōrnāvit","exōrnētur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quoniam vērō Apollō illīs ōrnāmentīs eam gaudēre animadvertēbat, “Ō mea Corōnis,” aiēbat, “nōlī timēre: nam cūrābō ut cotīdiē novīs gemmīs novīsque margarītīs corpus tuum fōrmōsissimum {{exōrnētur}}.” Apollō autem etiam corvum habēbat album, quī eum valdē amābat, puellam vērō ōderat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"exoro","latin":"exoro, exorare, exoravi, exoratus","headword":"exoro","letter":"e","pos":"verb","posGroup":"verb","english":"persuade, obtain/win over by entreaty, prevail upon; beg, plead, entreat","forms":["exōranda","exōrāre","exōrāta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Anāpis mē dīlēxit; {{exōrāta}} tamen nec, ut haec, exterrita nūpsī.\" Dīxit et in partēs dīversās bracchia tendēns obstitit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exors","latin":"exors, (gen.), exortis","headword":"exors","letter":"e","pos":"adjective","posGroup":"adjective","english":"without share in; exempt from lottery","forms":["exortī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ubi uterō exortī dolōrēs, ut solent puerperae,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"exorsus","latin":"exōrsus, -ūs","headword":"exōrsus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"beginning; beginning, opening","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exosculor","latin":"exosculor, exosculari, exosculatus sum","headword":"exosculor","letter":"e","pos":"verb","posGroup":"verb","english":"kiss fondly; express fondness for; admire greatly","forms":["exōsculātur"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Senātus fidem atque ingenium puerī {{exōsculātur}}, cōnsultum facit ‘utī posthāc puerī cum patribus in Cūriam nē introeant — praeter ille ūnus Papīrius’, atque puerō posteā cognōmentum honōris grātiā inditum Praetextātus ob tacendī loquendīque in aetāte praetextae prūdentiam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"exosso","latin":"exosso, exossare, exossavi, exossatus","headword":"exosso","letter":"e","pos":"verb","posGroup":"verb","english":"bone/de-bone, take out the bones, filet","forms":["exossās"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: Quid id exquīris tū, quī pugnīs os {{exossās}} hominibus?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"expallesco","latin":"expallesco, expallescere, expallui, -","headword":"expallesco","letter":"e","pos":"verb","posGroup":"verb","english":"turn pale, turn very pale; go white as a ghost","forms":["Expalluit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Expalluit}} aequē","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"expavescere","latin":"(expavēscō) expavēscere, -avisse, -atum","headword":"expavēscere","letter":"e","pos":"","posGroup":"other","english":"become frightened (at)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expavesco","latin":"expavesco, expavescere, expavi, -","headword":"expavesco","letter":"e","pos":"verb","posGroup":"verb","english":"become frightened","forms":["expāvērunt","expāvit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Admissus ergô ad Caesarem est cum suô mūnere. (Phialam porrēxit) Caesarî, deinde tēcit rēpor- valdius quam {{expāvit}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"expectatio","latin":"expectātiō, -tiōnis ( f.)","headword":"expectātiō","letter":"e","pos":"","posGroup":"other","english":"awaiting, expectation","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expecto","latin":"expecto, expectare, expectavi, expectatus","headword":"expecto","letter":"e","pos":"verb","posGroup":"verb","english":"await, expect; anticipate; hope for","forms":["Expectābam","expectantēs","expectātā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Continuôque cocum vocârî iussit et, nôn expectātā ëlëctiône nostIā, mäximum nātū iussit occîdî; et clārä vôce: “Ex quotā decuriā es?” Cum ille ‘sē ex quadrägësimâ’ respqndisset, “Ëmptî- cius an” inquit “domī nātus?” “Neutrum” inquit cocus, “sed testâmentô Pānsae tibi “Vidé ergô” ait “ut dîligenter pônäs!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"expedio","latin":"expedio, expedire, expedivi, expeditus","headword":"expedio","letter":"e","pos":"verb","posGroup":"verb","english":"disengage, loose, set free; be expedient; procure, obtain, make ready","forms":["expedī","expediam","expedient","expediet","expediō","expediri","expedit","expedītīs","expediunt","expedīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qua re nuntiata Caesar celeriter sarcinas conferri, arma {{expediri}} iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expedire","latin":"(expediō) expedīre","headword":"expedīre","letter":"e","pos":"","posGroup":"other","english":"make ready, extricate, explain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expeditio","latin":"expedītiō, -ōnis ( f.)","headword":"expedītiō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"foray, raid, expedition; expedition","forms":["expedītiōnibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Licinius Crassus cōnsul, cui mandātum erat, in Macedoniam trānsiit, levibusque {{expedītiōnibus}}, equestribus proeliīs, in Thessaliā cum Perseō, quem Cotys, rēx Thrāciae, adiuvābat, parum prosperō ēventū pugnāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"expeditus","latin":"expeditus, expedita -um, expeditior -or -us, expeditissimus -a -um","headword":"expeditus","letter":"e","pos":"adjective","posGroup":"adjective","english":"unencumbered; without baggage; light armed","forms":["expeditas","expeditiore","expedītus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo {{expeditiore}} re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expellere","latin":"(expellō) expellere (< pellere)","headword":"expellere","letter":"e","pos":"","posGroup":"other","english":"drive out, expel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expello","latin":"expellō, -ere, -pulī, -pulsum","headword":"expellō","letter":"e","pos":"verb","posGroup":"verb","english":"drive out, expel","forms":["expellātis","expellere","expellit","expellitur","expellunt","expulerat","expulēre","expulērunt","expulit","expulsam","expulsīs","expulsum","expulsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; {{expellitur}} ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expergefacio","latin":"expergefacio, expergefacere, expergefeci, expergefactus","headword":"expergefacio","letter":"e","pos":"verb","posGroup":"verb","english":"awaken/wake up (from sleep); rouse/arouse (from inactivity); excite/stir up","forms":["expergēfactus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iacobus {{expergēfactus}} adōrāvit Dominum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"expergisci","latin":"(expergīscor) expergīscī, -perrēctum","headword":"expergīscī","letter":"e","pos":"","posGroup":"other","english":"wake up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expergiscor","latin":"expergiscor, expergisci, experrectus sum","headword":"expergiscor","letter":"e","pos":"verb","posGroup":"verb","english":"awake; bestir oneself","forms":["expergīscere","expergīsciminī","experrēctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Pharaō {{experrēctus}} rūrsum dormīvit, et alterum habuit somnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"experientia","latin":"experientia, -ae","headword":"experientia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"experience","forms":["Experientia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Experientia}} docet.\" Sed Arachne iterum affirmat, \"Formō pictūrās melius quam Minerva.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"experior","latin":"experior, experiri, expertus sum","headword":"experior","letter":"e","pos":"verb","posGroup":"verb","english":"test, put to the test; find out; attempt, try; prove, experience","forms":["experiantur","experiar","experiāre","experior","experīrī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sententiis dictis constituunt, ut ei qui valetudine aut aetate inutiles sunt bello oppido excedant atque omnia prius {{experiantur}} quam ad Critognati sententiam descendant; illo tamen tempore potius utendum consilio, si res cogat atque auxilia morentur, quam aut deditionis aut pacis subeundam condicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"experiri","latin":"(experior) experīrī, -pertum","headword":"experīrī","letter":"e","pos":"verb","posGroup":"verb","english":"try, experience; to try, experience","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"expers","latin":"expers (gen. expertis)","headword":"expers","letter":"e","pos":"adjective","posGroup":"adjective","english":"having no share in","forms":["expertem","expertēs","experti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnia {{experti}} Galli, quod res nulla successerat, postero die consilium ceperunt ex oppido profugere, hortante et iubente Vercingetorige.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expertus","latin":"expertus, experta, expertum","headword":"expertus","letter":"e","pos":"adjective","posGroup":"adjective","english":"well-proved, tested; shown to be true","forms":["expertus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ūsus (: quod {{expertus}} sum) hoc opus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"expetere","latin":"(expetō) expetere (< petere)","headword":"expetere","letter":"e","pos":"verb","posGroup":"verb","english":"request, demand, desire; to seek, demand","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"expeto","latin":"expeto, expetere, expeti, expetitus","headword":"expeto","letter":"e","pos":"verb","posGroup":"verb","english":"ask for; desire; aspire to; demand; happen; fall on (person)","forms":["expetam","expetendam","expetī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ut Iovis suprēmī multīs hostiīs pācem {{expetam}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"expio","latin":"expio, expiare, expiavi, expiatus","headword":"expio","letter":"e","pos":"verb","posGroup":"verb","english":"expiate, atone for; avert by expiatory rites","forms":["expiāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Statim ut rēgnō pofitus est, populum et sacerdōtēs cohortātus, urbem ā p atēmīs superstitiōnibus {{expiāvit}}, templum omāvit, caerimōniās, quae iam prldem omissae erant, restituit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"expiro","latin":"expiro, expirare, expiravi, expiratus","headword":"expiro","letter":"e","pos":"verb","posGroup":"verb","english":"breathe out; exhale; expire; die; cease","forms":["expīrantem"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"illum {{expīrantem}} trānsfīxō pectore flammās","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"explanare","latin":"(explānō) explānāre, -āvisse, -ātum","headword":"explānāre","letter":"e","pos":"verb","posGroup":"verb","english":"make intelligible, explain; to explain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"explano","latin":"explano, explanare, explanavi, explanatus","headword":"explano","letter":"e","pos":"verb","posGroup":"verb","english":"explain","forms":["explānanda","explānat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Magister: 'Adverbium quid est?' Discipulus: 'Pars ōrātiōnis quae adiectā verbō significātiōnem eius {{explānat}} atque implet.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"expleo","latin":"expleo, explere, explevi, expletus","headword":"expleo","letter":"e","pos":"verb","posGroup":"verb","english":"fill out; fill, fill up, complete, finish; satisfy, satiate","forms":["expleant","expleatur","explendam","explent","explere","explērī","explētum","expletur","explēverat","explēvisse","explēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sic deinceps omne opus contexitur, dum iusta muri altitudo {{expleatur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"explere","latin":"(expleō) explēre (< plēre)","headword":"explēre","letter":"e","pos":"","posGroup":"other","english":"fill, complete, satisfy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"expletiva","latin":"explētīva","headword":"explētīva","letter":"e","pos":"","posGroup":"other","english":"(coniūnctiō) (f.) exclamatory conjunction","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"expletivus","latin":"expletivus, expletiva, expletivum","headword":"expletivus","letter":"e","pos":"adjective","posGroup":"adjective","english":"expletive, serving to fill out, introduced to occupy space or make up number","forms":["explētīvās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis adnectēns ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: 'Cōpulātīvās, disiūnctīvās, {{explētīvās}}, causālēs, ratiōnālēs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"explicare","latin":"(explicō) explicāre, -uisse, -itum","headword":"explicāre","letter":"e","pos":"verb","posGroup":"verb","english":"extricate, unfold, explain; to disentangle, free oneself; to free, extricate; to explain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"explico","latin":"explico, explicare, explicavi, explicatus","headword":"explico","letter":"e","pos":"verb","posGroup":"verb","english":"unfold, extend; set forth, display, exhibit, explain, disentangle","forms":["explicābō","explicandās","explicāre","explicārem","explicātī","explicentur","explicet","explicētur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ille simul manibus sē {{explicāre}} cōnātur, simul clāmōrēs horrendōs ad caelum tollit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"explorare","latin":"(explōrō) explōrāre","headword":"explōrāre","letter":"e","pos":"","posGroup":"other","english":"reconnoiter, investigate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"explorator","latin":"explōrātor, -ōris (m.)","headword":"explōrātor","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"scout, spy","forms":["exploratores","exploratoribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qua re per {{exploratores}} nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exploro","latin":"exploro, explorare, exploravi, exploratus","headword":"exploro","letter":"e","pos":"verb","posGroup":"verb","english":"search out, explore; test, try out; reconnoiter, investigate","forms":["Explōrantēs","explōrāre","explōrārent","explōrāret","explorari","explōrat","explorata","explōrātīs","explōrātum","explōrāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi solaci proponebant, quod se prope {{explorata}} victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exponere","latin":"(expōnō) expōnere, exposuisse, expositum","headword":"expōnere","letter":"e","pos":"verb","posGroup":"verb","english":"put out, expose; to set ashore; to explain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"expono","latin":"expono, exponere, exposui, expositus","headword":"expono","letter":"e","pos":"verb","posGroup":"verb","english":"set/put forth/out; abandon, expose; publish; explain, relate; disembark","forms":["expōnam","expōnere","expōnī","expōnit","exponunt","expositās","expositī","expositis","exposītō","expositōs","expositum","expositus","exposuī","exposuisset","exposuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Producuntur ei quos ille edocuerat quae dici vellet, atque eadem quae Litaviccus pronuntiaverat multitudini {{exponunt}}: multos equites Aeduorum interfectos, quod collocuti cum Arvernis dicerentur; ipsos se inter multitudinem militum occultasse atque ex media caede fugisse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exportare","latin":"(exportō) exportāre","headword":"exportāre","letter":"e","pos":"","posGroup":"other","english":"export","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exposcere","latin":"(exposcō) exposcere (< poscere)","headword":"exposcere","letter":"e","pos":"","posGroup":"other","english":"ask for, demand","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exposco","latin":"exposco, exposcere, expoposci, -","headword":"exposco","letter":"e","pos":"verb","posGroup":"verb","english":"request, ask for, demand; demand the surrender of","forms":["exposcendī","exposcentes","exposcit","exposcō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli {{exposcentes}} edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expostulo","latin":"expostulo, expostulare, expostulavi, expostulatus","headword":"expostulo","letter":"e","pos":"verb","posGroup":"verb","english":"demand, call for, remonstrate, complain about","forms":["expostulant"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vident hominem posterō diē: nārrant, {{expostulant}}, accūsant!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"expressus","latin":"expressus, expressa -um, expressior -or -us, expressissimus -a -um","headword":"expressus","letter":"e","pos":"adjective","posGroup":"adjective","english":"distinct/clear/plain/visible/prominent, clearly defined; closely modeled on","forms":["expressa"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Habuit enim ille, sīcuti meminisse vōs arbitror, permulta maximārum nōn {{expressa}} signa sed adumbrāta virtūtum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"exprimo","latin":"exprimo, exprimere, expressi, expressus","headword":"exprimo","letter":"e","pos":"verb","posGroup":"verb","english":"squeeze, squeeze/press out; imitate, copy; portray; pronounce, express","forms":["expresserat","expressit","exprimēbam","exprimeret","exprimit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger {{expresserat}}, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exprobro","latin":"exprobro, exprobrare, exprobravi, exprobratus","headword":"exprobro","letter":"e","pos":"verb","posGroup":"verb","english":"reproach, upbraid, reprove; bring up as reproach (against person DAT)","forms":["exprobrābat","exprobrāre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"At nēmō contrā illum exīre audēbat, et Goliathus suam Hebraeīs ignāviam cum irrīsū ac lūdibriō {{exprobrābat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"expugnare","latin":"expugnāre","headword":"expugnāre","letter":"e","pos":"verb","posGroup":"verb","english":"to storm, take by assault","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"expugnat","latin":"expugnat, expugnāre","headword":"expugnat","letter":"e","pos":"verb","posGroup":"verb","english":"conquer; storms, captures","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"expugnatio","latin":"expugnātiō, expugnātiōnis","headword":"expugnātiō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"(f.) conquest","forms":["expugnatione","expugnātiōnem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Caesar ex eo loco quintis castris Gergoviam pervenit equestrique eo die proelio levi facto, perspecto urbis situ, quae posita in altissimo monte omnes aditus difficiles habebat, de {{expugnatione}} desperavit; de obsessione non prius agendum constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expugno","latin":"expugno, expugnare, expugnavi, expugnatus","headword":"expugno","letter":"e","pos":"verb","posGroup":"verb","english":"assault, storm; conquer, plunder; accomplish; persuade","forms":["expugnābant","expugnābis","expugnandī","expugnandum","expugnant","expugnantur","expugnāre","expugnari","expugnat","expugnāta","expugnatis","expugnato","expugnātum","expugnātūrum","expugnāverat","expugnāverō","expugnāvimus","expugnāvissēs","expugnāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum {{expugnatis}} cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"expuo","latin":"expuo, expuere, expui, exputus","headword":"expuo","letter":"e","pos":"verb","posGroup":"verb","english":"spit out; eject; rid oneself of","forms":["expuit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec südâvit umquam nec {{expuit}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"expurgatio","latin":"expurgatio, expurgationis","headword":"expurgatio","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"justification, vindication; excuse; action of cleaning","forms":["expūrgātiōnem"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"IVPPITER: Habuī {{expūrgātiōnem}}; facta pāx est.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"expurgo","latin":"expurgo, expurgare, expurgavi, expurgatus","headword":"expurgo","letter":"e","pos":"verb","posGroup":"verb","english":"cleanse, purify; exculpate","forms":["expūrgandī"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postrēmō, dissimulandī causa aut suī expūrgandī, sīcut iūrgiō lacessītus foret, in senātum venit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"exquiro","latin":"exquiro, exquirere, exquisivi, exquisitus","headword":"exquiro","letter":"e","pos":"verb","posGroup":"verb","english":"seek out, search for, hunt up; inquire into","forms":["exquīre","exquīrēbant","exquīrendīs","exquīrere","exquīreret","exquīris","exquīrit","exquīrunt","exquīsīvī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"“Quod tibi nōlīs fierī, aliīs nē facitō, fīlī mī: sī quis tibi opus fēcerit, statim eī mercēdem persolve; cōnsilium semper ā virō sapiente {{exquīre}}; nē societātem cum improbīs iungitō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exquisitus","latin":"exquīsītus, -a, -um","headword":"exquīsītus","letter":"e","pos":"adjective","posGroup":"adjective","english":"attentive to every detail, meticulous","forms":["exquīsītō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nisi gēns nostra in Deum peccāvisset, numquam in hās miseriās incīdissēmus; sed mox Deus, meō frātrumque meōrum sanguine plācātus, genfī nostrae reconciliābitur, et nōs post mortem patienter tolerātam aetēma vlta dōnābit.\"Tum Antiochus indignē ferēns sē dērīsum esse, in illum exquīsītō suppliciō necāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsanguis","latin":"exsanguis, -e","headword":"exsanguis","letter":"e","pos":"adjective","posGroup":"adjective","english":"bloodless, lifeless","forms":["exsanguem","exsanguēs","exsanguis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eum dīcentem tālia animae {{exsanguēs}} audiēbant et lacrimābant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"exscindere","latin":"(exscindō) exscindere (< scindere)","headword":"exscindere","letter":"e","pos":"","posGroup":"other","english":"demolish, destroy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exscindo","latin":"exscindo, exscindere, exscidi, exscissus","headword":"exscindo","letter":"e","pos":"verb","posGroup":"verb","english":"demolish/destroy, raze to ground (town/building); exterminate/destroy (people)","forms":["exscindere","exscindēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum autem Karthāginem dēlēveris, triumphum ēgeris cēnsorque fueris et obieris lēgātus Aegyptum, Syriam, Asiam, Graeciam, dēligēre iterum cōnsul absēns bellumque maximum cōnficiēs: Numantiam {{exscindēs}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exsecrandus","latin":"exsecrandus, -a, -um","headword":"exsecrandus","letter":"e","pos":"adjective","posGroup":"adjective","english":"accursed","forms":["exsecrandum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hinc iam bellum cīvīle successit {{exsecrandum}} et lacrimābile, quō praeter calamitātēs quae in proeliīs accidērunt, etiam populī Rōmānī fortūna mūtāta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exsecrari","latin":"(exsecrōr) exsecrārī","headword":"exsecrārī","letter":"e","pos":"","posGroup":"other","english":"curse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsecratio","latin":"exsecratio, exsecrationis","headword":"exsecratio","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"imprecation, curse","forms":["exsecrātiōnem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Fuēre eā tempestāte quī dīcerent Catilīnam, ōrātiōne habitā, cum ad iūs iūrandum populārēs sceleris suī adigeret, hūmānī corporis sanguinem vīnō permixtum in paterīs circumtulisse; inde cum post {{exsecrātiōnem}} omnēs dēgustāvissent, sīcuti in sollemnibus sacrīs fierī cōnsuēvit, aperuisse cōnsilium suum, atque eō ita fēcisse, quō inter sē fīdī magis forent, alius aliī tantī facinoris cōnsciī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"exsecror","latin":"exsecror, -ārī, -ātus sum","headword":"exsecror","letter":"e","pos":"verb","posGroup":"verb","english":"to curse","forms":["exsecrantibus","exsecrārī","exsecrātur","exsecrātus","exsecrēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dominus dīxit serpentī: quia dēcēpistī mulierem, eris odiōsus et {{exsecrātus}} inter omnia animantia; rēptābis super pectus, et comedēs terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsequi","latin":"(exsequor) exsequī (< sequī)","headword":"exsequī","letter":"e","pos":"","posGroup":"other","english":"pursue, go on, execute","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsequia","latin":"exsequia, exsequiae","headword":"exsequia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"funeral procession/rites (pl.), obsequies; [~as ire => attend funeral]","forms":["exsequiās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vtque vident habitum, 'Quae lūctūs causa?' requīrunt, 'Cui paret {{exsequiās}}, quōve sit icta malō?' Illa diū reticet pudibundaque cēlat amictū ōra; fluunt lacrimae more perennis aquae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exsequiae","latin":"exsequiae, -ārum (pl.)","headword":"exsequiae","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"funeral procession, rites; funeral, funeral rites","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exsequor","latin":"exsequor, exsequi, exsecutus sum","headword":"exsequor","letter":"e","pos":"verb","posGroup":"verb","english":"follow, go along/on with; pursue for vengeance/punishment; strive/search after","forms":["exsecūtūrum","exsequar","exsequēbantur","exsequēbātur","Exsequentī","exsequere","exsequerētur","exsequī","exsequitur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque Philistaeī, perturbātī, coepērunt nōn iam ōrdinēs servāre, nōn imperia exsequī, sed fugae sē committere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsero","latin":"exsero, exserere, exserui, exsertus","headword":"exsero","letter":"e","pos":"verb","posGroup":"verb","english":"stretch forth; thrust out (of land); put out (plants); lay bare, uncover (body)","forms":["exsertae","exsertis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hi similitudine armorum vehementer nostros perterruerunt, ac, tametsi dextris umeris {{exsertis}} animadvertebantur, quod insigne pactum esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exsicco","latin":"exsicco, exsiccare, exsiccavi, exsiccatus","headword":"exsicco","letter":"e","pos":"verb","posGroup":"verb","english":"dry up; empty (vessel)","forms":["exsiccātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Flāvit etiam ventus vehemēns, quō {{exsiccātus}} est alveus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsilio","latin":"exsilio, exsilire, exsilui, -","headword":"exsilio","letter":"e","pos":"verb","posGroup":"verb","english":"spring/leap/burst forth/out, leap up, start up, bound; emerge into existence","forms":["Exsiliēns","exsiliō","exsilit","exsiliunt","exsiluit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Exsiliēns}} statim Tobiās cadāver occultē portāvit domum, ut illud noctū sepelīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsilire","latin":"(exsiliō) exsilīre, -uisse","headword":"exsilīre","letter":"e","pos":"","posGroup":"other","english":"jump up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsilium","latin":"exsilium, -ī","headword":"exsilium","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"exile","forms":["exsiliī","exsilium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum in captīvitātem abductus esset, eandem in Deum pietātem semper retinuit: omnia bona, quae habēre poterat, cotīdiē exsiliī suī comitibus impertiēbat, eōsque monitīs salūtāribus ad colendum Deum hortābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsistere","latin":"(existō) exsistere, -itisse, -itum","headword":"exsistere","letter":"e","pos":"verb","posGroup":"verb","english":"appear, arise; to arise, emerge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exsisto","latin":"exsisto, exsistere, exstiti, -","headword":"exsisto","letter":"e","pos":"verb","posGroup":"verb","english":"step out, come forth, emerge, appear, stand out, project; arise; come to light","forms":["exsistat","exstiterit","exstitisse","exstitisset","exstitit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Multum ad terrendos nostros valet clamor, qui post tergum pugnantibus {{exstitit}}, quod suum periculum in aliena vident salute constare; omnia enim plerumque quae absunt vehementius hominum mentes perturbant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exsolvere","latin":"(exsolvō) exsolvere (< solvere)","headword":"exsolvere","letter":"e","pos":"","posGroup":"other","english":"set free, release","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsolvo","latin":"exsolvo, exsolvere, exsolvi, exsolutus","headword":"exsolvo","letter":"e","pos":"verb","posGroup":"verb","english":"unfasten/undo/loose; open (vein); thaw (ice); let flow (body discharge); solve","forms":["exsolvam","exsolve","exsolvendum","exsolvite"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tē ōrō atque obsecrō ut sinās puerum abīre, mēque prō eō addīcās in servitūtem; ego poenam, quā dignus est, mihi sūmō et {{exsolvam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exspectare","latin":"exspectāre","headword":"exspectāre","letter":"e","pos":"verb","posGroup":"verb","english":"to wait (for)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"exspectat","latin":"exspectat, exspectant","headword":"exspectat","letter":"e","pos":"verb","posGroup":"verb","english":"wait (for), expect; waits for, expects","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"exspectatio","latin":"exspectatio, exspectationis","headword":"exspectatio","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"expectation; suspense","forms":["exspectātiō","exspectātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Isthmiōrum lūdicrum aderat tempus, semper frequēns — cum propter spectāculī studium, tum quia Graeciae is mercātus erat; tum vērō nōn ad solitōs modo ūsūs undique convēnerant, sed {{exspectātiōne}} ērectī, quī deinde status futūrus Graeciae, quae sua fortūna esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exspecto","latin":"exspectō, -āre, -āvī, -ātum","headword":"exspectō","letter":"e","pos":"verb","posGroup":"verb","english":"await, wait for","forms":["exspectā","exspectabant","exspectabat","exspectans","exspectant","exspectantem","exspectantēs","exspectantibus","exspectare","exspectārent","exspectari","exspectās","exspectat","exspectāta","exspectātī","exspectātīs","exspectātō","exspectātum","exspectaverant","exspectāvit","exspectent","exspectēs","exspectet","exspectō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Errare, si qui in bello omnes secundos rerum proventus {{exspectent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exspirare","latin":"(exspīrō) exspīrāre","headword":"exspīrāre","letter":"e","pos":"","posGroup":"other","english":"breathe one’s last, die","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exspiro","latin":"exspiro, exspirare, exspiravi, exspiratus","headword":"exspiro","letter":"e","pos":"verb","posGroup":"verb","english":"breathe out, exhale; expire; cease, die","forms":["exspīrābat","exspīrantem","exspīrantēs","exspīrāre","exspīrāvisset","exspīrāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad cuius aspectum Tobiās perterritus exclāmāvit: “Domine, invādit mē.” Cui angelus: “Apprehende illum et trahe ad tē.” Piscis attractus in rīpam aliquamdiū palpitāvit et {{exspīrāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exspolio","latin":"exspolio, exspoliare, exspoliavi, exspoliatus","headword":"exspolio","letter":"e","pos":"verb","posGroup":"verb","english":"pillage, rob, plunder","forms":["exspoliare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nolite hos vestro auxilio {{exspoliare}}, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi imbecillitate omnem Galliam prosternere et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exspuo","latin":"exspuo, exspuere, exspui, exsputus","headword":"exspuo","letter":"e","pos":"verb","posGroup":"verb","english":"spit out; eject; rid oneself of","forms":["Exspuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Exspuit}} ergō Iēsus in terram, et recit lutum ex spūtō et līnīvit oculōs eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exstimulare","latin":"(exstimulō) exstimulāre","headword":"exstimulāre","letter":"e","pos":"","posGroup":"other","english":"stir up, incite","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exstimulo","latin":"exstimulo, exstimulare, exstimulavi, exstimulatus","headword":"exstimulo","letter":"e","pos":"verb","posGroup":"verb","english":"goad; stimulate","forms":["exstimulāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīs solita est dictīs {{exstimulāre}} virum: \"Rēgia rēs scelus est: socerō cape rēgna necātō!\" Ille, sedēns soliō prīvātus in altō, sēderat; attonitum vulgus ad arma ruit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exstinguere","latin":"(exstinguō) exstinguere, -tinxisse, -stinctum","headword":"exstinguere","letter":"e","pos":"","posGroup":"other","english":"extinguish, put out, kill, annihilate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exstinguo","latin":"exstinguō, -ere, -stīnxī, -stīnctum","headword":"exstinguō","letter":"e","pos":"verb","posGroup":"verb","english":"extinguish, put out","forms":["exstīnctā","exstīnctae","exstīnctās","exstīnctō","exstīnctōs","exstīnctum","exstinctus","exstinguam","exstinguantur","exstinguātur","exstinguere","exstinguētur","exstinguī","exstinguit","exstinguitur","exstīnxī","exstīnxissem","exstīnxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ut vīdit Iōsēphus {{exstīnctum}} patrem, ruit super eum flēns, et ōsculātus est eum, lūxitque illum diū.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsto","latin":"exsto, exstare, -, -","headword":"exsto","letter":"e","pos":"verb","posGroup":"verb","english":"stand forth/out; exist; be extant/visible; be on record","forms":["exstat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Quid tūtī superest, cum nóminīs {{exstat}} adulter","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exstruere","latin":"(exstruō) exstruere (< struere)","headword":"exstruere","letter":"e","pos":"verb","posGroup":"verb","english":"erect, build; to build up, erect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exstruo","latin":"exstruo, exstruere, exstruxi, exstructus","headword":"exstruo","letter":"e","pos":"verb","posGroup":"verb","english":"pile/build up, raise, build, construct","forms":["exstrūctae","exstrūctum","exstruendō","exstruis","exstruit","exstruxerunt","exstruxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis imbribus tardarentur, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX {{exstruxerunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exsul","latin":"exsul, -is (m./f.)","headword":"exsul","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"banished person, exile; exile","forms":["exsul","exsule","exsulem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Spernentibus Etrūscīs Lucumōnem \"{{exsule}} advena ortum\", Tanaquil eam indignitātem ferre nōn potuit, oblītaque amōris patriae, dummodo virum honōrātum vidēret, cōnsilium migrandī ab Tarquiniīs cēpit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exsulare","latin":"(exsulō) exsulāre","headword":"exsulāre","letter":"e","pos":"","posGroup":"other","english":"live in exile","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsulo","latin":"exsulo, exsulare, exsulavi, exsulatus","headword":"exsulo","letter":"e","pos":"verb","posGroup":"verb","english":"be exile, live in exile; be banished; be a stranger","forms":["exsulābat","exsulātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ancī līberī iam tum, comprehēnsīs sceleris ministrīs, ut vīvere rēgem et tantās esse opēs Serviī nūntiātum est, Suessam Pōmētiam {{exsulātum}} ierant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exsultare","latin":"(exsultō) exsultāre","headword":"exsultāre","letter":"e","pos":"","posGroup":"other","english":"jump up; rejoice","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exsulto","latin":"exsulto, exsultare, exsultavi, exsultatus","headword":"exsulto","letter":"e","pos":"verb","posGroup":"verb","english":"rejoice; boast; exalt; jump about, let oneself go","forms":["exsultā","exsultābat","exsultābis","exsultābit","exsultāre","exsultet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"315 Aspice ut ante ipsum tenēris {{exsultet}} in herbīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exsupero","latin":"exsupero, exsuperare, exsuperavi, exsuperatus","headword":"exsupero","letter":"e","pos":"verb","posGroup":"verb","english":"excel; overtop; surpass; overpower","forms":["exsuperat"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam sī digna poena prō factīs eōrum reperītur, novum cōnsilium approbō; sīn magnitūdō sceleris omnium ingenia {{exsuperat}}, eīs ūtendum cēnseō quae lēgibus comparāta sunt.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"exsurgo","latin":"exsurgo, exsurgere, exsurrexi, exsurrectus","headword":"exsurgo","letter":"e","pos":"verb","posGroup":"verb","english":"bestir oneself/take action; swell/rise/move/extend up/out/to higher moral level","forms":["Exsurgēns","Exsurgite","exsurgō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ecce prīnceps quīdam accessit ad Iēsum adōrāns eum ed dīcēns:\"Domine, fīlia mea modo defilncta est, sed venī, impōne manum tuam et vīvet.\"{{Exsurgēns}} Iēsus sequēbātur eum et discipulī eius erant cum illō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exsuscitare","latin":"(exsuscitō) exsuscitāre","headword":"exsuscitāre","letter":"e","pos":"","posGroup":"other","english":"rouse, kindle","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"extemplo","latin":"extemplō","headword":"extemplō","letter":"e","pos":"adverb","posGroup":"adverb","english":"at once","forms":["extemplō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sī quae asportāssent reddere, sē exercitum extemplō domum","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"extendere","latin":"(extendō) extendere, extendisse, extentum","headword":"extendere","letter":"e","pos":"","posGroup":"other","english":"extend","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"extendo","latin":"extendo, extendere, extendi, extensus","headword":"extendo","letter":"e","pos":"verb","posGroup":"verb","english":"stretch/thrust out; make taut; extend/prolong/continue; enlarge/increase","forms":["Extende","extendendō","extendēns","extendent","extendentēs","extendere","extenderet","extendit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum eā nōn invēnisset locum ubi pōneret pedem, reversā est ad Noëmum, quī {{extendit}} manum, et intulit eam in arcam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"extensus","latin":"extensus, extensa, extensum","headword":"extensus","letter":"e","pos":"adjective","posGroup":"adjective","english":"lengthened (vowel); wide, extended, extensive (L+S); prolonged, drawn out","forms":["extēnsa","extēnsam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Fēcit Moysēs quod iusserat Deus: cum tenēret manum {{extēnsam}} super mare, aquae dīvīsae sunt, et intumēscentēs hinc et inde pendēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exter","latin":"exter, -era, -erum","headword":"exter","letter":"e","pos":"adjective","posGroup":"adjective","english":"external, foreign; foreign, outside","forms":["exterae","exterās","exteriore","exteriorem","exteriores","extrema","extremam","extrēmās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto {{extremam}} famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"extera","latin":"extera, exterae","headword":"extera","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"foreigner (female)","forms":["extera"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"invidia est? et nōs fās {{extera}} quaerere rēgna.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"extergeo","latin":"extergeo, extergere, extersi, extersus","headword":"extergeo","letter":"e","pos":"verb","posGroup":"verb","english":"wipe; wipe dry; wipe away","forms":["Extergē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mandūcēmus!” [Convīvae:] “Optimē factum est.” [Iūlius, ad ministrōs:] “Date aquam ad manūs! — Extergē mēnsam! — Dā nōbīs bibere!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"extermino","latin":"extermino, exterminare, exterminavi, exterminatus","headword":"extermino","letter":"e","pos":"verb","posGroup":"verb","english":"banish, expel; dismiss","forms":["exterminārī"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam tum cum ex urbe Catilīnam ēiciēbam — nōn enim iam vereor huius verbī invidiam, cum illa magis sit timenda, quod vīvus exierit! — sed tum cum illum exterminārī volēbam, aut reliquam coniūrātōrum manum simul exitram aut eōs quī restitissent īnfirmōs sine illō ac dēbilēs fore putābam.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"externo","latin":"externo, externare, externavi, externatus","headword":"externo","letter":"e","pos":"verb","posGroup":"verb","english":"terrify greatly, frighten; madden","forms":["externō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Auget uterque suās externō rōbore vīrēs,\net multī Rutulōs, multī Trōiāna tuentur\ncastra, neque Aenēās Evandrī ad moenia frūstrā\n[īvit; nam Pallas, fīlius Evandrī, ad bellum pugnandum missus est.]\n[Bellum] perstat, habetque deōs pars utraque, quodque\ndeōrum est īnstar, habent animōs. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"externus","latin":"externus, -a, -um","headword":"externus","letter":"e","pos":"adjective","posGroup":"adjective","english":"external, extraneous","forms":["externa","externōrum","externus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{externus}} -ā -um («» internus) : extrà addidit, externō marmore","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exterreo","latin":"exterreo, exterrere, exterrui, exterritus","headword":"exterreo","letter":"e","pos":"verb","posGroup":"verb","english":"strike with terror, scare","forms":["exterrita","exterriti","exterritus","exterruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec faciunt reciperandorum suorum causa; sed contaminati facinore et capti compendio ex direptis bonis, quod ea res ad multos pertinebat, timore poenae {{exterriti}} consilia clam de bello inire incipiunt civitatesque reliquas legationibus sollicitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exterrere","latin":"(exterreō) exterrēre (< terrēre)","headword":"exterrēre","letter":"e","pos":"","posGroup":"other","english":"scare, terrify","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"extimesco","latin":"extimesco, extimescere, extimui, -","headword":"extimesco","letter":"e","pos":"verb","posGroup":"verb","english":"take fright, be alarmed, dread","forms":["Extimēscēbat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Extimēscēbat}} īram frātris suī: ut plācāret animum eius, praemīsit ad eum nūntiōs, quī offerent eī mūnera.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"extimus","latin":"extimus, -a, -um (sup. of exter)","headword":"extimus","letter":"e","pos":"adjective","posGroup":"adjective","english":"outermost, farthest","forms":["extimus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Novem tibi orbibus vel potius globīs cōnexa sunt omnia, quōrum ūnus est caelestis, {{extimus}}, quī reliquōs omnēs complectitur, summus ipse deus arcēns et continēns cēterōs; in quō sunt īnfīxī illī quī volvuntur stellārum cursūs sempiternī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exto","latin":"exto, extare, extiti, -","headword":"exto","letter":"e","pos":"verb","posGroup":"verb","english":"stand out or forth, project be visible, exist, be on record","forms":["extent"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô etiam pullārius erat - omnīs mortuum plangere/plôräre : plangere/plôräre dē mortuô (servum) macū (: ê potestāte minimus, quārta pars assis solidus -ā -um 4-) liquidus; sēcum in sepulcrum tulisse que pretiurrx; quid ā. mordeat Sâturnälia agere : in luxū leô : vir fortis ac ferôx rēctus, certus: probus, ﬁdusﬁdt micāre: lūdere digitîs {{extent}}îs spūtum (-î n) ex ôre êmittere pānem quem asse ëmissês...","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"extollere","latin":"(extollō) extollere (< tollere)","headword":"extollere","letter":"e","pos":"","posGroup":"other","english":"raise, praise, extol","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"extollo","latin":"extollo, extollere, -, -","headword":"extollo","letter":"e","pos":"verb","posGroup":"verb","english":"raise; lift up; extol, advance; erect (building)","forms":["extollere","extollunt"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"maximī; continuō {{extollunt}} ambō capita.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"extorqueo","latin":"extorqueo, extorquere, extorsi, extortus","headword":"extorqueo","letter":"e","pos":"verb","posGroup":"verb","english":"extort; tear away, twist away; twist/wrench out","forms":["extorquēbat","extorsit","extorta","extortis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia {{extortis}}, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"extorris","latin":"extorris, -e (< terra)","headword":"extorris","letter":"e","pos":"adjective","posGroup":"adjective","english":"exiled, banished","forms":["extorris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōs cum flentēs cerneret, et ipse illacrimāsse dīcitur sortī hūmānae, quod quī paulō ante nōn contentus rēgnō Macedoniae Dardanōs Illyriōsque oppugnāsset, is tum āmissō exercitū, {{extorris}} rēgnō, in parvam īnsulam compulsus, supplex, fānī religiōne, nōn vīribus suīs tūtus esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"extra","latin":"extrā","headword":"extrā","letter":"e","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) outside","forms":["extra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam de equitibus hostium quin nemo eorum progredi modo {{extra}} agmen audeat, ipsos quidem non debere dubitare; et quo maiore faciant animo, copias se omnes pro castris habiturum et terrori hostibus futurum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"extractum","latin":"extractum, extracti","headword":"extractum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"extract (chemistry)","forms":["extracta","extractī","extractum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum vērō amīcī, quī apud eum stābant, ferrum ēdūxērunt, ūna cum sagittā cruentā pars pulmōnis est {{extracta}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"extrahere","latin":"(extrahō) extrahere (< trahere)","headword":"extrahere","letter":"e","pos":"","posGroup":"other","english":"pull out, extract","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"extraho","latin":"extraho, extrahere, extraxi, extractus","headword":"extraho","letter":"e","pos":"verb","posGroup":"verb","english":"drag out; prolong; rescue, extract; remove","forms":["extrahere","extrāxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Habēbat in animō līberāre Iōsēphum ex eōrum manibus, et illum {{extrahere}} ē foveā, atque ad patrem redūcere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"extraneus","latin":"extrāneus, -a, -um","headword":"extrāneus","letter":"e","pos":"adjective","posGroup":"adjective","english":"foreign, stranger","forms":["extrāneus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aegrē propter onus incēdentī dīcēbat: 'Cum gladiō tē vallāre scieris, vallum ferre dēsinitō!' Quem mīlitem extrā ōrdinem dēprehendit, sī Rōmānus esset, vītibus, sī {{extrāneus}}, virgīs cecīdit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"extremum","latin":"extremum, extremi","headword":"extremum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"limit, outside; end","forms":["extrēmum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum {{extrēmum}} spīritum ageret, ad rēgem conversus:\"Tū quidem\"ait,\"hanc vltam nōbīs ēripis, sed āmissam nōbīs reddet Deus, prō cuius lēge linguam postulanfī prōtulit amputandam, manusque prōtendēns, dīxit:\"Haec membra, ā Deō acceptā, nunc propter Deum contemnō, quia spērō fore ut eā reciperem.\"Rēx et aliī circumstantēs admīrābantur animum adulēscentis, quī acerbissimum dolōrem prō nihilō dūcēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"extremus","latin":"extrēmus, -a, -um","headword":"extrēmus","letter":"e","pos":"noun (m.)","posGroup":"noun","english":"outermost, utmost, last","forms":["extremī","extrēmīs","extrēmō","Extremōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Addit sēmina et flōrēs et sūcōs ācrēs et lapidēs Oriente extrēmō petītōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"extrico","latin":"extrico, extricare, extricavi, extricatus","headword":"extrico","letter":"e","pos":"verb","posGroup":"verb","english":"disentangle, extricate, free","forms":["extrīcās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hoc scrīptum est tibi quī, magna cum mīrāris, {{extrīcās}} nihil.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"extum","latin":"extum, exti","headword":"extum","letter":"e","pos":"noun (n.)","posGroup":"noun","english":"bowels (pl.); entrails of animals (esp. heart, lungs, liver) for divination","forms":["exta","extīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"320 ettenuitlaetà paelicis {{exta}} manū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exuere","latin":"(exuō) exuere, exūtum","headword":"exuere","letter":"e","pos":"","posGroup":"other","english":"take off, deprive of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"exululo","latin":"exululo, exululare, exululavi, exululatus","headword":"exululo","letter":"e","pos":"verb","posGroup":"verb","english":"invoke with howls","forms":["exululāta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"concinitur Phrygiīs {{exululāta}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"exuo","latin":"exuo, exuere, exui, exutus","headword":"exuo","letter":"e","pos":"verb","posGroup":"verb","english":"pull off; undress, take off; strip, deprive of; lay aside, cast off","forms":["exuant","exue","exuerat","exuit","exuitur","exūta","exūtus","exuunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne {{exuant}}, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"exurere","latin":"(exūrō) exūrere (< ūrere)","headword":"exūrere","letter":"e","pos":"verb","posGroup":"verb","english":"burn up; to burn up, destroy by fire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exuro","latin":"exuro, exurere, exussi, exustus","headword":"exuro","letter":"e","pos":"verb","posGroup":"verb","english":"burn (up/out/completely); destroy/devastate by fire; dry up, parch; scald","forms":["exūrere","exussissent","exussit","exustae","exustī","exustōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Omnēs sēgetēs, vīneae et oleae {{exustae}} sunt; nec inimīcam gentem variīs incommodīs vexāre dēstitit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"exustio","latin":"exustiō, -ōnis ( f.)","headword":"exustiō","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"conflagration; burning up, conflagration","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"exuvia","latin":"exuvia, exuviae","headword":"exuvia","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"things stripped off (pl.); spoils, booty; memento, something of another's","forms":["exuviae","exuviās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rogō ingentī in rēgiā ērēctō, rēgīna locum flōribus et fronde exōrnat; super rogum {{exuviās}} et ēnsem relictum effigiemque Aenēae in torō locat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"exuviae","latin":"exuviae, -ārum (pl.)","headword":"exuviae","letter":"e","pos":"noun (f.)","posGroup":"noun","english":"clothing, armor; spoils, cast-off clothing","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"faba","latin":"faba, fabae","headword":"faba","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"bean (plant/seed); bead, pellet (resembling bean)","forms":["fabam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Inde duo crotalia prôtulit et °r°t3|ī33 '5' Fortūnātae in vicem cônsîderanda dedit, et “Dominî” inquit “meî beneﬁciô nëmô “Quid?” inquit Habinnās, “excatarissästî mē, ut tibi emerem {{fabam}} vitream.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fabella","latin":"fabella, fabellae","headword":"fabella","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"story, fable; play","forms":["fābella"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post brevem prōlogum, quō poēta lēctōribus prōpōnit dōtem librī suī duplicem — id est dēlectāre atque admonēre —, {{fābella}} prīma nārrātur dē iūrgiō ācrī quod habuit lupus latrō cum agnō innocentī (Aesōpus Latīnus, fābula 3).] Aesōpus auctor quam māteriam repperit hanc ego polīvī versibus sēnāriīs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"faber","latin":"faber, fabrī","headword":"faber","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"craftsman; craftsman, smith","forms":["faber","fabrīs","fabrōrum","fabrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Arcessītē eum!” Vulcānus, deōrum {{faber}}, cum Iovem Īrātum et tālī modō clāmantem audīret, statim accurrit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fabius","latin":"Fabius, Fabi","headword":"Fabius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"Fabius; (Roman gens name); Q. Fabius Maximus Cunctator, hero second Punic War","forms":["Fabia","Fabiam","Fabiī","Fabio","Fabium","Fabius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Fabium}} legatum cum legionibus duabus castris praesidio relinquit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fabricare","latin":"(fabricō) fabricāre","headword":"fabricāre","letter":"f","pos":"verb","posGroup":"verb","english":"forge, build, construct; to build, construct","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"fabrico","latin":"fabricō (1)","headword":"fabricō","letter":"f","pos":"verb","posGroup":"verb","english":"to make, craft, fashion","forms":["fābricāta","fabricāvērunt"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aut hōc inclūsī lignō occultantur Achīvī,\naut haec in nostrōs {{fābricāta}} est māchina mūrōs\nīnspectūra domōs ventūraque dēsuper urbī,\naut aliquis latet error: equō nē crēdite, Teucrī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fabula","latin":"fābula, -ae","headword":"fābula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"story; story, fable; story, tale","forms":["fābulā","fābulae","fābulam","fābulārum","fābulās","fābulīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ulixēs igitur, quī statim dīxit sē esse cupidum in patriam redeundī, multīs cum lacrimīs trīstem {{fābulam}} suam omnibus, quī ibi aderant, nārrāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fabulari","latin":"(fābulor) fābulārī, fābulātum","headword":"fābulārī","letter":"f","pos":"verb","posGroup":"verb","english":"chat, tell a story; to talk, chat","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"fabulor","latin":"fabulor, fabulari, fabulatus sum","headword":"fabulor","letter":"f","pos":"verb","posGroup":"verb","english":"talk (familiarly), chat, converse; invent a story, make up a fable","forms":["fābulābantur","fabulantēs","fābulārentur","fābulārī","fābulārier","fābulor"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Dītī igitur omnēs laetī ab ōvō iīsque ad mala {{fābulābantur}} optimōs cibōs gustantēs et vīnum, quod ministrī in pōcula fundēbant, magnō cum gaudiō pōtantēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fabulosus","latin":"fābulōsus, -a, -um","headword":"fābulōsus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fabulous, celebrated in fable","forms":["fābulōsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sīve per Syrtēs iter aestuōsās / sīve factūrus per inhospitālem / Caucasum vel quae loca {{fābulōsus}} / lambit Hydaspēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"facessere","latin":"(facessō) facessere","headword":"facessere","letter":"f","pos":"","posGroup":"other","english":"do eagerly, go away, be off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"facesso","latin":"facesso, facessere, facessi, facessitus","headword":"facesso","letter":"f","pos":"verb","posGroup":"verb","english":"do; perpetrate; go away","forms":["facesse","facessere","facessunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{facessere}} -īvisse -itum - facere Mīlle facesse iocōs; turpe","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"facetia","latin":"facetia, facetiae","headword":"facetia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"wit (pl.), joke","forms":["facētiae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vērum ingenium eius haud absurdum: posse versūs facere, iocum movēre, sermōne utī vel modestō, vel mollī, vel procācī — prōrsus multae {{facētiae}} multusque lepōs inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"facies","latin":"faciēs, -ēī","headword":"faciēs","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"face; face, appearance","forms":["faciē","faciēī","faciem","faciēs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Medicus: “Sed {{faciēs}} eius nimis rubra erat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"facile","latin":"facile","headword":"facile","letter":"f","pos":"adverb","posGroup":"adverb","english":"easily","forms":["facile"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Id esse {{facile}}, quod neque legiones audeant absente imperatore ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"facilis","latin":"facilis, -e","headword":"facilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"(sup.facillimus) easy","forms":["facilem","facilēs","facilī","facilia","facilior","faciliora","faciliōrem","facilis","facilius","facillime","facillimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, legatos mittunt subsidium rogatum, quo {{facilius}} hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"facilitas","latin":"facilitās, -atis ( f.)","headword":"facilitās","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"ease, facility; ease, affability","forms":["facilitās","facilitāte","facilitātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac prīmum quanta innocentia dēbent esse imperātōrēs! quanta deinde in omnibus rēbus temperantia! quanta fide, quanta {{facilitāte}}, quanto ingeniō, quanta hūmānitāte!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"facinus","latin":"facinus, -ōris (n.)","headword":"facinus","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"deed, act, misdeed; bad deed, crime; deed, crime","forms":["facinora","facinore","facinoribus","facinoris","facinorum","facinus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"An dubitamus quin nefario {{facinore}} admisso Romani iam ad nos interficiendos concurrant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"facio","latin":"faciō, facere, fēcī, factum","headword":"faciō","letter":"f","pos":"verb","posGroup":"verb","english":"make, do","forms":["fac","facere","facerem","facerent","facerēs","faceret","faciam","faciāmus","faciant","Faciantur","faciās","faciat","faciātis","faciēbam","faciēbant","faciēbās","faciēbat","facienda","faciendam","faciendī","faciendīs","faciendōs","faciendum","faciendus","faciēns","facient","facientem","facientēs","facientia","faciet","faciētis","facimus","faciō","facit","facite","facitis","facitō","faciundī","Faciundum","faciunt","factae","factam","factās","factōs","factū","factūrī","facturos","factūrum","factūrus","factus","faxō","fēceram","fecerant","fēcerat","fēcēre","fecerimus","fecerint","fēcerīs","fecerit","fēcerō","fecerunt","fēcī","fēcimus","fēcisse","fēcissem","fēcissēmus","fecissent","fecisset","fēcissētis","fēcistī","fēcistis","fecit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior {{factus}}, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"facit","latin":"facit, facere","headword":"facit","letter":"f","pos":"","posGroup":"other","english":"make, do, cause","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"factio","latin":"factiō, -ōnis ( f.)","headword":"factiō","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"party, faction; faction, party","forms":["factiō","factiōne","factiōnēs","factiōnī","factiōnis","factiōnum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aedēs Concordiae antīqua eō tempore aedificāta esse dīcitur cum post longam discordiam, quae populum Rōmānum dīvīserat in duās {{factiōnēs}} inter sē inimīcissimās, patriciōs et plēbēiōs, tandem concordia omnium collāpsam in meliōrem faciem restituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"factiosus","latin":"factiōsus, -a, -um","headword":"factiōsus","letter":"f","pos":"adjective","posGroup":"adjective","english":"factious, scheming; factional, intriguing","forms":["factiōsī","factiōsō","factiōsōs","factiōsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eā tempestāte exercitū nostrō fuēre complūrēs novī atque nōbilēs, quibus dīvitiae bonō honestōque potiōrēs erant, factiōsī domī, potentēs apud sociōs, clārī magis quam honestī; quī Iugurthae nōn mediocrem animum pollicitandō accendēbant, 'sī Micipsa rēx occidisset, fore utī sōlus imperiī Numidiae potīrētur: in ipsō maximam virtūtem, Rōmae omnia vēnālia esse!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"factum","latin":"factum, -ī","headword":"factum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"deed","forms":["facta","factī","factīs","facto","factōrum","factum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne {{facto}} initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"factura","latin":"factura, facturae","headword":"factura","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"creation; work; deed; performance; handiwork","forms":["factūra"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quae simul attigimus stetimusque in līmine tēctī,\nmīlle lupī mixtaeque lupīs ursaeque leaeque\noccursū fēcēre metum, sed nūlla timenda\nnūllaque erat nostrō {{factūra}} in corpore vulnus;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"factus","latin":"factus, -a, -um","headword":"factus","letter":"f","pos":"adjective","posGroup":"adjective","english":"wrought; done, made","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"facula","latin":"facula, faculae","headword":"facula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"little torch","forms":["faculam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Bene nōs accēpistī.” [Iūlius, ad servum:] “Accende {{faculam}}!” [Gāius:] “Dā ministrantibus bibere et cēnāre, et cocō, quia bene ministrāvit.” [Discēdunt convīvae.] [Iūlius:] “Puer, venī!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"facultas","latin":"facultās, -ātis ( f.)","headword":"facultās","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"capability, possibility, (pl.) resources; means, resources","forms":["facultas","facultate","facultatem","facultātēs","facultatibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non multum adiuvabant, alteri non magnis {{facultatibus}}, quod civitas erat exigua et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"facundia","latin":"facundia, facundiae","headword":"facundia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"eloquence","forms":["fācundia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nōn tua sub nostrās veniat {{fācundia}} lēgēs;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"facundus","latin":"fācundus, -a, -um","headword":"fācundus","letter":"f","pos":"adjective","posGroup":"adjective","english":"eloquent","forms":["fācundus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn fōrmōsus erat, sed erat {{fācundus}} Ulixēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"faenero","latin":"faenero, faenerare, faeneravi, faeneratus","headword":"faenero","letter":"f","pos":"verb","posGroup":"verb","english":"lend money at interest; make interest/profit; invest/finance/supply; borrow","forms":["faenerāre","Faenerāvī","faenerāvisse"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sustulî mē dē negôtiätiône et coepî per lîbertôs {{faenerāre}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"faenus","latin":"faenus, faenoris","headword":"faenus","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"interest (on capital), usury; profit, gain; advantage","forms":["faenore","faenus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dītā (: sēmina) cum {{faenore}} reddunt","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"falcarius","latin":"falcarius, falcarii","headword":"falcarius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"sickle-maker, scythe-maker","forms":["falcāriōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dīcō tē priōre nocte vēnisse inter {{falcāriōs}} — nōn agam obscūrē — in M.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"falerius","latin":"Falerius, Falerii","headword":"Falerius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"Falisci (pl.); (Latin people/Etruscan culture)","forms":["Falēriōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Post eam cēpit et {{Falēriōs}}, nōn minus nōbilem cīvitātem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"falernum","latin":"Falernum, Falerni","headword":"Falernum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"Falernian wine","forms":["Falerna","Falernō","Falernum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec vīnum meum peius esse mihi vidētur quam vīnum illud {{Falernum}}, quod vīnum Italiae optimum habētur.' (Falernum est vīnum ex agrō Falernō, regiōne Campāniae.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fallacia","latin":"fallācia, -ae","headword":"fallācia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"trick, deceit","forms":["fallācia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tanta est {{fallācia}} tēctī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fallax","latin":"fallāx","headword":"fallāx","letter":"f","pos":"adjective","posGroup":"adjective","english":"(gen.fallācis) false, deceitful; deceitful, false","forms":["fallācem","fallācī","fallācibus","fallāx"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mercurius intereā celerrimē ad terrās volāvit ut Promēthēum {{fallācibus}} verbīs ac prōmissīs in Olympum retraheret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fallere","latin":"(fallō) fallere, fefellisse, falsum","headword":"fallere","letter":"f","pos":"verb","posGroup":"verb","english":"deceive; to deceive, trick","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"fallit","latin":"fallit","headword":"fallit","letter":"f","pos":"verb","posGroup":"verb","english":"deceives, tricks","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"fallo","latin":"fallō, -ere, fefellī, falsum","headword":"fallō","letter":"f","pos":"verb","posGroup":"verb","english":"deceive","forms":["fallāris","fallās","fallat","falle","fallendi","fallendō","fallendum","fallere","fallerent","falleret","fallēs","fallīs","fallit","fallitur","fallō","fallunt","fefellit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hi similitudine armorum vehementer nostros perterruerunt, ac, tametsi dextris umeris exsertis animadvertebantur, quod insigne pactum esse consuerat, tamen id ipsum sui {{fallendi}} causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"falso","latin":"falsō","headword":"falsō","letter":"f","pos":"verb","posGroup":"verb","english":"false, deceived, wrong","forms":["falsō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"perque fretum falsō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"falsum","latin":"falsum, falsi","headword":"falsum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"falsehood, untruth, fraud, deceit","forms":["falsum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iam vērō intellegō Lepidum, quī ānulum ferreum mihi dedit, {{falsum}} amīcum quantī est? = esse.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"falsus","latin":"falsus, -a, -um","headword":"falsus","letter":"f","pos":"adjective","posGroup":"adjective","english":"false","forms":["falsa","falsae","falsam","falsī","falsīs","falsōrum","falsōs","falsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Rēx autem ut explōrāret latentem vēritātem: “Dīvidātur” inquit “puer dē quō contrōversia est, et pars ūna ūnī mulierī, altera alterī dētur.” Iūdiciō assēnsa est {{falsa}} māter; altera vērō exclāmāvit: “Nē, quaesō, nē occīdātur puer, ō rēx: mālō ista tōtum habeat.” Tunc rēx ait: “Rēs est manifēsta: haec vērē est māter puerī.” Et huic illum adiūdicāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"falx","latin":"falx, falcis","headword":"falx","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f.) sickle","forms":["falce","falcem","falces","falcibus","Falx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam et laqueis {{falces}} avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fama","latin":"fāma, -ae","headword":"fāma","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"report, reputation; reputation, report, fame; report, rumour, fame","forms":["fama","fāmae","fāmam","famis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Celeriter ad omnes Galliae civitates {{fama}} perfertur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fames","latin":"famēs, famis","headword":"famēs","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f.) hunger","forms":["fame","famem","famēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam {{famem}} sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"familia","latin":"familia, -ae","headword":"familia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"domestic staff, family; household, family; family","forms":["familia","familiae","familiam","familiārum","familiās","familiīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres {{familiae}} repente in publicum procurrerunt flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"familiaris","latin":"familiāris, -e","headword":"familiāris","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"intimate (as noun: close friend); friend, intimate","forms":["familiārem","familiārēs","familiārī","familiaribus","familiaris","familiārium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea salutis causa rei {{familiaris}} commoda neglegenda: vicos atque aedificia incendi oportere hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"familiaritas","latin":"familiaritas, familiaritatis","headword":"familiaritas","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"intimacy; close friendship; familiarity","forms":["familiāritātēs","familiāritātis"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed maximē adulēscentium {{familiāritātēs}} appetēbat: eōrum animī mollēs etiam et flūxī dolīs haud difficulter capiēbantur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"famula","latin":"famula, -ae","headword":"famula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"servant girl, maid; maidservant","forms":["famulābus","famulae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prōspexit fiscellam in harundinibus haerentem, mīsitque illūc ūnam ē {{famulābus}} suīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"famulus","latin":"famulus, -ī","headword":"famulus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"servant, slave","forms":["famulī","famulīs","famulōs","famulum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Diē septimō īnfāns mortuus est, nec ausī sunt famulī id rēgī nūntiāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fanum","latin":"fānum, -ī","headword":"fānum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"shrine, consecrated spot","forms":["fāna","fānī","fānum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Fānum}} in colle Quirīnālī Rōmulō deō, quī idem Quirīnus vocātur, dicātum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"far","latin":"far, farris","headword":"far","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"husked wheat; grain, spelt; coarse meal, grits; sacrificial meal; dog's bread","forms":["fār","farris"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{fār}} farris 7 genus frūmentī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fars","latin":"fars, fartis","headword":"fars","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"stuffing; minced meat","forms":["fars"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"P$Ā Nec ūllus tot malôrum ﬁnīs fuisset nisi epidîpnīs esset allāta: turdî silîgineî üvîs passîs ñucibusque {{fars}}î. În- secūta sunt Cydônia etiam mäla spînîs cônﬁxa, ut echînôs Et haec quidem tolerābilia erant, sī nôn ferculum longē mônstrôsius effēcisset ut vel famē perîre mällêmus!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fas","latin":"fās (indec.)","headword":"fās","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"divine law, right","forms":["fās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā animum eius invāsit superbia: mūnus sacerdōtum sibi arrogāvit: ms Deō ausus est offerre; quod s olīs sacerdōtibus {{fās}} erat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fasces","latin":"fascēs, -ium (m. pl.)","headword":"fascēs","letter":"f","pos":"","posGroup":"other","english":"bundle of rods, fasces","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fascia","latin":"fascia, fasciae","headword":"fascia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"band/strip; ribbon; B:bandage; streak/band of cloud; headband/filet; sash (Ecc)","forms":["fasciā","fasciae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"angustum circā fasciā pectus eat.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fascis","latin":"fascis, -is","headword":"fascis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"bundle of rods (carried before a magistrate)","forms":["fascēs","fasci","fascibus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cēterum ad scindendum aprum nôn ille Ca1pūs ac- cessit quī altilia lacerāverat, sed barbātus ingēns, {{fasci}}îs crürâlibus alligātus et āliculā sub- ômâtus polymitā, strictôque vënätôriô cultrô latus aprî vehementer percussit ēvolāvērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fastidio","latin":"fastidio, fastidire, fastidivi, fastiditus","headword":"fastidio","letter":"f","pos":"verb","posGroup":"verb","english":"disdain; be scornful; feel aversion to, be squeamish","forms":["fastīdīs","fastīdit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē {{fastīdīs}} refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fastigium","latin":"fastigium, fastigi(i)","headword":"fastigium","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"peak, summit, top; slope, declivity, descent; gable, roof; sharp point, tip","forms":["fastīgia","fastigio","fastigium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ante id oppidum planities circiter milia passuum III in longitudinem patebat; reliquis ex omnibus partibus colles mediocri interiecto spatio pari altitudinis {{fastigio}} oppidum cingebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fastus","latin":"fāstus, -a, -um","headword":"fāstus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"court-day, work day","forms":["fāstōs","fastum","fastūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"fàastus -üs 7ī — superbia ({{fastūs}} : -um)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fatalis","latin":"fātālis, -e (cf. fātum, -ī Caps. XXXIV, XXXIX)","headword":"fātālis","letter":"f","pos":"adjective","posGroup":"adjective","english":"fateful, destined; ordained by fate, fatal","forms":["fātālibus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"quem rēgnō Hesperiae fraudō et {{fātālibus}} arvīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fateor","latin":"fateor, -ērī, fassus sum","headword":"fateor","letter":"f","pos":"verb","posGroup":"verb","english":"confess, say","forms":["fassō","fassum","fassus","fateātur","fatēbor","fatentēs","fatentī","fatentibus","fatentur","fateor","fatērentur","fatērī","fatēris","fatētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūdās respondit: {{fateor}}, rēs est manifēsta; nūllam possumus excūsātiōnem affēre, nec audēmus petere veniam aut spērāre; nōs omnēs erimus servī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fateri","latin":"(fateor) fatērī, fassum","headword":"fatērī","letter":"f","pos":"verb","posGroup":"verb","english":"acknowledge; to confess, admit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"fatetur","latin":"fatētur","headword":"fatētur","letter":"f","pos":"verb","posGroup":"verb","english":"confesses, admits","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"fatigare","latin":"(fatīgō) fatīgāre, -āvisse, -ātum","headword":"fatīgāre","letter":"f","pos":"verb","posGroup":"verb","english":"tire out, weary; to tire, weary","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"fatigatus","latin":"fatigatus, fatigata, fatigatum","headword":"fatigatus","letter":"f","pos":"adjective","posGroup":"adjective","english":"weary","forms":["fatīgātī","fatīgātōs","fatīgātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hostēs hāc rē perturbātī, cum iam longa pugnā fatīgātī essent, impetum Rōmānōrum ab utrāque parte venientium diūtius sustinēre nōn potuērunt, ac post brevem pugnam terga vertērunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fatigo","latin":"fatigo, fatigare, fatigavi, fatigatus","headword":"fatigo","letter":"f","pos":"verb","posGroup":"verb","english":"weary, tire, fatigue; harass; importune; overcome","forms":["fatīgāre","fatīgārī","fatīgat","fatīgātum","fatīgāverit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Epistulae quās pater ad fīlium dat praecipuē dē glōriā et virtūte sunt, sed ex iīs litterīs prīvātīs quās Aemilia nūper ā frātre suō accēpit plānē appāret eum iam vītā mīlitārī {{fatīgātum}} esse.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fatisco","latin":"fatisco, fatiscere, -, -","headword":"fatisco","letter":"f","pos":"verb","posGroup":"verb","english":"gape, crack; crack open, part asunder; grow weak or exhausted, droop","forms":["fatīscunt"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"accipiunt inimīcum imbrem, rīmīsque {{fatīscunt}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fatue","latin":"fatue","headword":"fatue","letter":"f","pos":"adverb","posGroup":"adverb","english":"foolishly","forms":["fatue"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Paene effrēgistī, {{fatue}}, foribus cardinēs!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"fatum","latin":"fātum, -ī","headword":"fātum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"fate; fate, destiny; (pl.) fates","forms":["fāta","fātī","fātīs","fato","fātōrum","fatum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"pervēnit in lūcum: sīc illum {{fāta}} ferēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fatuus","latin":"fatuus, fatua, fatuum","headword":"fatuus","letter":"f","pos":"adjective","posGroup":"adjective","english":"foolish, silly; idiotic","forms":["fatuum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Scîmus tē prae litterās {{fatuum}} esse.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fauces","latin":"faucēs, -ium (f. pl.)","headword":"faucēs","letter":"f","pos":"","posGroup":"other","english":"upper part of the throat; opening; pass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"faunus","latin":"Faunus, Fauni","headword":"Faunus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"rustic god; deity of forest, herdsman; sometimes identified with Pan","forms":["Faunō","Faunus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Post hunc Pīcus, deinde {{Faunus}} in Latiō rēgnāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"faustus","latin":"faustus, -a, -um","headword":"faustus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fortunate, favorable","forms":["fausta","Fauste","faustum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Isaacus iam senuisset, et factus esset caecus, vocāvit Esāüm: sūmitō, inquit pharetram, arcum et sagittās; affer mihi et parā dē vēnātiōne pulmentum, ut comedam et apprecer tibi {{fausta}} omnia, antequam moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fautor","latin":"fautor, -ōris (m.)","headword":"fautor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"supporter","forms":["fautōrem","Fautōrēs","fautōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita nātum, ita creātum rēgem, {{fautōrem}} īnfimī generis hominum, ex quō ipse sit, agrum prīmōribus ēreptum sordidissimō cuique dīvīsisse...\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"faux","latin":"faux, faucis","headword":"faux","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"pharynx (usu pl.), gullet/throat/neck/jaws/maw; narrow pass/shaft/strait; chasm","forms":["fauce","faucēs","faucibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"“Nōn poteris” inquit “adulēscentulus cum virō rōbustissimō pugnāre.” Respondit Dāvīd: “Nē timeās, ō rēx: cum pāscerem ovēs patris meī, leō invāsit gregem, ovemque corripuit: ego illum persecūtus occīdī, et ovem ē {{faucibus}} illīus ēripuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"faveo","latin":"faveo, favere, favi, fautus","headword":"faveo","letter":"f","pos":"verb","posGroup":"verb","english":"favor (w/DAT), befriend, support, back up","forms":["fautum","faveat","favebant","favēbat","favēbō","favēns","favent","favente","faventēs","favēre","fāverit","faves","favet","favēte","favisse","fāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iam fidēs tua mihi perspecta est, cum nōn pepercerīs fīliō tuō ūnicō; et ego favēbō tibi; remūnerābō splendidē fidem tuam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"favere","latin":"(faveō) favēre, fāvisse","headword":"favēre","letter":"f","pos":"","posGroup":"other","english":"favor, support (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"favilla","latin":"favilla, favillae","headword":"favilla","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"glowing ashes, embers; spark; ashes","forms":["favīllā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nec pudor est oculōs tenuī signàre favīllā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"favor","latin":"favor, -ōris (m.)","headword":"favor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"goodwill, favor","forms":["favor","favōre","favōrem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tantus populī {{favor}} invidiam Saūlis accendit, quī deinceps malevolō fuit in Davidem animō, nec iam eum benignīs oculīs aspiciēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"favus","latin":"favus, favi","headword":"favus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"honeycomb","forms":["favē","favum","favus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In mediā mēnsā vērō {{favum}} cum meile apium posuērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fax","latin":"fax, facis ( f.)","headword":"fax","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"torch","forms":["face","facem","faces","faci","facis","Fax"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Alii {{faces}} atque aridam materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fe","latin":"fe, undeclined","headword":"fe","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"pe; (17th letter of Hebrew alphabet)","forms":["fē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"turbā, aquilās fugiunt fē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"febris","latin":"febris, febris","headword":"febris","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"fever, attack of fever","forms":["febrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Servī autem occurrērunt eī et nūntiāvērunt fīlium lTuerātum esse febrī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"februarius","latin":"Februarius, Februaria, Februarium","headword":"Februarius","letter":"f","pos":"adjective","posGroup":"adjective","english":"February (month/mensis understood); abb. Feb.","forms":["Februāriae","Februāriās","Februāriī","Februāriō","Februārium","Februārius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; {{Februārius}}, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fecundus","latin":"fecundus, fecunda -um, fecundior -or -us, fecundissimus -a -um","headword":"fecundus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fertile, fruitful; productive (of offspring), prolific; abundant; imaginative","forms":["fēcunda"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"... cecidistī et fēmina ferrō, totque tuōs idem frātrēs, tē perdidit īdem, exitium Trōiae nostrīque orbātor, Achillēs; at postquam cecidit Paridis Phoebīque sagittīs, ‘nunc certē’ dīxī ‘nōn est metuendus Achillēs’: nunc quoque mī metuendus erat; cinis ipse sepultī in genus hoc saevit, tumulō quoque sēnsimus hostem, Aeacidae {{fēcunda}} fuī!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fel","latin":"fel, fellis","headword":"fel","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"gall, bile; poison; bitterness, venom; gall bladder","forms":["fel","felle"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tunc iussit angelus {{fel}} piscis sēpōnī, utpote medicāmentum salūtāre; deinde partem carnis coxērunt comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"felicitas","latin":"fēlīcitās, fēlīcitātis","headword":"fēlīcitās","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f.) happiness","forms":["fēlīcitās","fēlīcitāte","fēlīcitātem","fēlīcitātī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum amīcus eius, rēx Aegyptī, cum {{fēlīcitātem}} atque glōriam eius ingentem vidēret, tyrannō suāsit ut iactūram faceret eius reī quā maximē omnium gaudēret, ita deōrum invidiam āvertī posse spērāns.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"feliciter","latin":"feliciter","headword":"feliciter","letter":"f","pos":"adverb","posGroup":"adverb","english":"happily","forms":["fēlīciter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quīnctius Flāminīnus cōnsul adversus Philippum {{fēlīciter}} pugnāvit in faucibus Ēpīrī fugātumque coēgit in rēgnum revertī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"felix","latin":"fēlīx","headword":"fēlīx","letter":"f","pos":"adjective","posGroup":"adjective","english":"(gen.fēlīcis) lucky, fortunate; happy, fortunate; happy, lucky","forms":["felicem","fēlīcēs","fēlīcī","fēlīcia","fēlīcior","felīciōrēs","fēlīcissimam","fēlīcissimē","fēlīcius","fēlīx"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Laetī igitur et maximō amōre coniūnctī, Orpheus et Eurydicē ad nūptiārum diem pervēnērunt; quī tam {{fēlīcēs}} omnibus esse vidēbantur, ut nēmō fortūnam eōrum umquam mūtārī posse putāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"femina","latin":"fēmina, -ae","headword":"fēmina","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"woman","forms":["fēmina","fēminae","fēminam","fēminārum","fēminās","feminis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Huc teretes stipites {{feminis}} crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"femineus","latin":"femineus, feminea, femineum","headword":"femineus","letter":"f","pos":"adjective","posGroup":"adjective","english":"woman's; female, feminine; proper to/typical of a woman; effeminate, cowardly","forms":["fēmineā","fēmineō","fēmineus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{fēmineus}} -ā -um « fēmina","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"femininum","latin":"fēminīnum, -ī (genus)","headword":"fēminīnum","letter":"f","pos":"adjective","posGroup":"adjective","english":"feminine","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"femininus","latin":"fēminīnus","headword":"fēminīnus","letter":"f","pos":"adjective","posGroup":"adjective","english":"feminine","forms":["fēminīnum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Genera nōminum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: 'Masculīnum, ut hic magister; {{fēminīnum}}, ut haec fēmina; neutrum, ut hoc scamnum; commūne, ut hic et haec sacerdōs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fenestra","latin":"fenestra, -ae","headword":"fenestra","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"window","forms":["fenestra","fenestrae","fenestram","fenestrās","fenestrīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa, amīca Lȳdiae, ē lectō surgit et {{fenestram}} aperit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fer","latin":"fer., abb.","headword":"fer","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"weekday; abb. of feria; [(w/ordinals) quintus feria => fifth day/Thursday]","forms":["fer"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tunc “Auxilium {{fer}}, Diāna!” invocat, “ST mē amās, quae saepe et arcum et sagittās tibi tulī, servā mē!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fera","latin":"fera, -ae","headword":"fera","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"wild animal; wild beast","forms":["fera"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra magnam avem quae suprā hortum volat digitō mōnstrat: “Ecce avis {{fera}} quae ā parvīs avibus timētur.” Avis magnīs ālīs sustinētur, neque Iūlia ālās movērī videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"feralis","latin":"feralis, feralis, ferale","headword":"feralis","letter":"f","pos":"adjective","posGroup":"adjective","english":"funereal; deadly, fatal","forms":["fērālī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sōlaque culminibus fērālī carmine būbō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ferculum","latin":"ferculum, ferculi","headword":"ferculum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"food tray; dish, course; food; bread; bier (Ecc); litter","forms":["fercula","ferculum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[{{Ferculum}} prîmum: duodecim signa caelestial] Laudätiônem ferculum est însecütum, plānē nôn prô oculôs: rotundum enim repositôrium duodecim habēbat signa in orbe disposita, super quae proprium conveniēn- temque māteriae strūctor imposuerat cibum: statēram in cuius alterâ parte scriblîta erat, in alterā placentā; In mediô autem caespes cum herbîs excîsus favum sustinēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fere","latin":"ferē","headword":"ferē","letter":"f","pos":"adverb","posGroup":"adverb","english":"about, almost; about, nearly","forms":["fere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex omnibus {{fere}} partibus palus difficilis atque impedita cingebat, non latior pedibus quinquaginta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ferentarius","latin":"ferentarius, ferentari(i)","headword":"ferentarius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"light-armed soldier skirmisher","forms":["ferentāriīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postquam eō ventum est unde ā {{ferentāriīs}} proelium committī posset, maximō clāmōre cum īnfēstīs signīs concurrunt; pīla omittunt, gladiīs rēs geritur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"feretrum","latin":"feretrum, feretri","headword":"feretrum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"bier","forms":["feretrō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Corpus eius conditum est, et in feretrō positum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"feria","latin":"feria, feriae","headword":"feria","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"festival/holy day; day of rest/holiday/leisure; holidays (pl.); fair","forms":["fēriae","fēriīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Āfricānus, hic Paulī fīlius, {{fēriīs}} Latīnīs Tūditānō cōnsule et Aquīliō, cōnstituisset in hortīs esse familiārissimīque eius ad eum frequenter per eōs diēs ventitātūrī sē esse dīxissent, Latīnīs ipsīs māne ad eum prīmus sorōris fīlius vēnit Q.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"feriae","latin":"fēriae, -ārum (pl.)","headword":"fēriae","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"festival days, holidays; holiday, festival","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"feriatus","latin":"fēriātus, -a, -um","headword":"fēriātus","letter":"f","pos":"adjective","posGroup":"adjective","english":"keeping holiday","forms":["fēriātī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum Laelius: 'Nōn impediō, praesertim quoniam fēriātī sumus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ferina","latin":"ferina, ferinae","headword":"ferina","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"game, flesh of wild animals","forms":["ferīnae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"implentur veteris Bacchī pinguisque {{ferīnae}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ferio","latin":"ferio, ferire, -, -","headword":"ferio","letter":"f","pos":"verb","posGroup":"verb","english":"hit, strike; strike a bargain; kill, slay","forms":["feriēbantur","feriet","ferīre","ferit","ferītur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē {{feriet}} secūrī, et affīget ad pālum, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ferire","latin":"(feriō) ferīre","headword":"ferīre","letter":"f","pos":"","posGroup":"other","english":"strike, hit, kill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ferme","latin":"fermē","headword":"fermē","letter":"f","pos":"adverb","posGroup":"adverb","english":"about, almost","forms":["fermē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde Tobiās oculōs patris līnīvit felle piscis, et post dīmidiam fermē hōram coepit albūgō, quasi membrāna ōvī, ex oculīs eius ēgredī, quam apprehēnsam fīlius extrāxit, atque ille statim vīsum recēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fermentum","latin":"fermentum, fermenti","headword":"fermentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"fermentation, leavening (process/cause); yeast; ferment/passion; sour/spoil","forms":["fermentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hoc fuit pecüliî meî {{fermentum}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fero","latin":"ferō, ferre, tulī, lātum","headword":"ferō","letter":"f","pos":"verb","posGroup":"verb","english":"bear, bring, carry","forms":["feram","ferant","ferar","ferās","ferat","ferātur","ferebant","ferebat","ferēbātur","Ferēmus","ferenda","ferendī","ferendum","ferendus","ferēns","ferent","ferente","ferentem","ferentēs","ferentī","ferentīs","ferēris","ferēs","feret","ferimus","fero","feror","ferre","ferret","ferretur","fers","fert","ferte","fertis","fertur","ferunt","feruntur","latum","lātūra","laturos","tulerant","tulerat","tulere","tulerit","tulero","tulērunt","tulī","tulisse","tulissem","tulissēs","tulisset","tulistī","tulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non {{laturos}} aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ferocia","latin":"ferocia, ferociae","headword":"ferocia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"fierceness, ferocity; insolence","forms":["ferōcia"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quoniam tantam in mē et amīcōs iniūriam fēcit, certē mihi est pūniendum: nec enim eius {{ferōcia}} mē dēterret nē in illud impetum faciam!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ferocio","latin":"ferocio, ferocire, -, -","headword":"ferocio","letter":"f","pos":"verb","posGroup":"verb","english":"rampage, act in a fierce/violent/savage manner","forms":["ferōcior"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is canis lupō {{ferōcior}} est!'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ferocitas","latin":"ferōcitās, -ātis ( f.)","headword":"ferōcitās","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"fierceness; ferocity; fierceness, ferocity","forms":["ferōcitāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quō in locō cum esset silvestris bēluae sustentātus ūberibus pastōrēsque eum sustulissent et in agrēstī cultū labōreque aluissent, perhibētur, ut adolēverit, et corporis vīribus et animī {{ferōcitāte}} tantum cēterīs praestitisse ut omnēs quī tum eōs agrōs ubi hodiē est haec urbs incolēbant aequō animō illī libenterque pārērent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ferociter","latin":"ferociter, ferocius, ferocissime","headword":"ferociter","letter":"f","pos":"adverb","posGroup":"adverb","english":"fiercely/ferociously/aggressively; arrogantly/insolently/defiantly; boldly","forms":["ferōcissimē","ferōciter","ferōcius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum aliī Centaurī {{ferōciter}} pugnāre coepērunt et “Arma!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ferox","latin":"ferōx (ferōcis)","headword":"ferōx","letter":"f","pos":"adjective","posGroup":"adjective","english":"fierce, ferocious; fierce, savage; savage, wild","forms":["ferōcem","ferōcēs","ferōcī","ferōcibus","ferōcis","ferōx"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sed eō absente canis meus {{ferōx}} domum cūstōdit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ferramentum","latin":"ferramentum, ferramenti","headword":"ferramentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"iron tool","forms":["ferrāmentōrum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Cethēgus, quī paulō ante aliquid tamen dē gladiīs ac sīcīs quae apud ipsum erant dēprehēnsae respondisset dīxissetque sē semper bonōrum {{ferrāmentōrum}} studiōsum fuisse, recitātīs litterīs dēbilitātus atque abiectus cōnscientiā repente conticuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ferrarius","latin":"ferrarius, ferraria, ferrarium","headword":"ferrarius","letter":"f","pos":"adjective","posGroup":"adjective","english":"of/concerned with iron, iron-; [officina/taberna ~ => smithy/blacksmith shop]","forms":["ferrariae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt {{ferrariae}} atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ferratus","latin":"ferrātus, -a, -um","headword":"ferrātus","letter":"f","pos":"","posGroup":"other","english":"tipped with iron","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ferre","latin":"(ferō) ferre, tulisse, lātum","headword":"ferre","letter":"f","pos":"verb","posGroup":"verb","english":"carry, bear; bring (together), carry; to carry, bring; lead (of a road)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ferreus","latin":"ferreus, -a, -um","headword":"ferreus","letter":"f","pos":"adjective","posGroup":"adjective","english":"iron; iron, made of iron","forms":["ferreā","ferreae","ferream","ferreās","ferreis","ferreō","ferreōs","ferreum","ferreus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ante haec taleae pedem longae {{ferreis}} hamis infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ferrum","latin":"ferrum, -ī","headword":"ferrum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"iron, sword; iron; iron, weapon, sword; iron weapon, spear","forms":["ferrī","ferrō","ferrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Albīnus: “Nōn ut aurum, sed ut {{ferrum}} tinnit iste ānulus: est ānulus ferreus aurō opertus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fert","latin":"fert, ferre","headword":"fert","letter":"f","pos":"verb","posGroup":"verb","english":"carry, bring, bear; carries, bears","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"fertilis","latin":"fertilis, -e","headword":"fertilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"fertile","forms":["fertile","fertīlem","fertilēs","Fertilior","fertiliōra","fertilis","fertilissima"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quibus rebus confectis Caesar ad oppidum Avaricum, quod erat maximum munitissimumque in finibus Biturigum atque agri {{fertilissima}} regione, profectus est, quod eo oppido recepto civitatem Biturigum se in potestatem redacturum confidebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ferula","latin":"ferula, ferulae","headword":"ferula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"stick, rod","forms":["ferulā","ferulam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Dum vērō ad currum accēdit, {{ferulam}} in hortō vīdit, quam eō cōnsiliō carpsit, ut in eā ignem latentem ad hominēs portāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ferus","latin":"ferus, -a, -um","headword":"ferus","letter":"f","pos":"adjective","posGroup":"adjective","english":"wild","forms":["ferae","ferārum","ferī","ferīs","ferōrum","ferōs","ferum","ferus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sed {{ferae}} Daniell pepercērunt, rēxque, mīrāculō commōtus, ipsōs accūsātōrēs leōnibus dēvorandōs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fervefacio","latin":"fervefacio, fervefacere, fervefeci, fervefactus","headword":"fervefacio","letter":"f","pos":"verb","posGroup":"verb","english":"heat; melt; boil; make (intensely) hot","forms":["fervefacta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice {{fervefacta}} et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fervens","latin":"fervēns (gen. -entis)","headword":"fervēns","letter":"f","pos":"adjective","posGroup":"adjective","english":"hot, boiling, ardent; burning, passionate","forms":["fervēns","ferventī","ferventia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"meétaque ferventī circumeunda rotā.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ferveo","latin":"ferveo, fervere, ferbui, -","headword":"ferveo","letter":"f","pos":"verb","posGroup":"verb","english":"be (very) hot; boil/burn; seethe/surge; swarm; be turbulent/run strongly; froth","forms":["fervēre","fervet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā aēnō in igne positō medicāmen validum {{fervet}} et albet spūmīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fervere","latin":"(fervō) fervere, feruisse","headword":"fervere","letter":"f","pos":"","posGroup":"other","english":"boil, seethe, swarm4","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fervidus","latin":"fervidus, fervida, fervidum","headword":"fervidus","letter":"f","pos":"adjective","posGroup":"adjective","english":"glowing; boiling hot; fiery, torrid, roused, fervid; hot blooded","forms":["fervida"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ōraque fontāna {{fervida}} pulsat aquá.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fessus","latin":"fessus, -a, -um","headword":"fessus","letter":"f","pos":"adjective","posGroup":"adjective","english":"tired, weary","forms":["fessa","fessam","fessās","fessī","fessīs","fessō","fessōs","fessum","fessus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Via Latīna est longa, sed Mēdus, quī viā Latīnā Tūsculō Rōmam ambulat, {{fessus}} nōn est, nam is ambulat ad Lȳdiam amīcam, quae Rōmae habitat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"festinare","latin":"(festīnō) festīnāre","headword":"festīnāre","letter":"f","pos":"","posGroup":"other","english":"hasten, hurry","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"festino","latin":"festino, festinare, festinavi, festinatus","headword":"festino","letter":"f","pos":"verb","posGroup":"verb","english":"hasten, hurry","forms":["festīnāns","festīnantēs","festīnāre","festīnat","festīnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rachel {{festīnāns}} id nūntiāvit patrī suō, quī agnōvit fīlium sorōris suae, deditque eī Rachēlem in mātrimōnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"festivus","latin":"festivus, festiva -um, festivior -or -us, festivissimus -a -um","headword":"festivus","letter":"f","pos":"adjective","posGroup":"adjective","english":"feast/festive (day); excellent/fine; jovial, genial; lively (speech), witty","forms":["fēstīvī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum puer, mātre urgente, lepidī atque fēstīvī mendāciī cōnsilium capit: ‘Āctum in senātū’ dīxit, ‘utrum vidērētur ūtilius exque rē pūblicā esse: ūnusne ut duās uxōrēs habēret an ut ūna apud duōs nūpta esset?!’","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"festuca","latin":"festuca, festucae","headword":"festuca","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"straw; stalk (used in manumission); ram for beating down earth, piledriver","forms":["festūcam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Bice prīmum trabem d ē oculō tuō, ē t tūne perspiciēs ut ēducās {{festūcam}} dē oculō frātris tuī.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"festum","latin":"festum, festi","headword":"festum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"holiday; festival; feast day; day in memory of saint/event (usu. pl.) (Bee)","forms":["fēstum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"gerenda | colere — {{fēstum}} habēre","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"festus","latin":"fēstus, -a, -um","headword":"fēstus","letter":"f","pos":"adjective","posGroup":"adjective","english":"holiday, festal","forms":["fēsta","fēstī","festīs","fēstō","fēstōs","fēstus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat Philistaeīs mōs, cum diēs {{fēstōs}} agerent, prōdūcere Samsōnem quasi in pompam pūblicam, captōque īnsultāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"feteo","latin":"feteo, fetere, -, -","headword":"feteo","letter":"f","pos":"verb","posGroup":"verb","english":"stink; have a bad/offensive smell/odor","forms":["fētentem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Certē ego notävî super mē positum cocum quī dē porcô ānserem fēcerat, muriā cōn- dîmentîsque {{fētentem}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fetialis","latin":"fētiālis, -e","headword":"fētiālis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"fetial; diplomatic","forms":["fētiāle"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quoniam autem Numa in pāce religiōnēs īnstituerat, Ancus, ut bella nōn sōlum gererentur sed etiam indīcerentur aliquō rītū, iūs {{fētiāle}} scrīpsit, quō rēs repetuntur et bellum indīcitur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fetus","latin":"fētus, -a, -um","headword":"fētus","letter":"f","pos":"adjective","posGroup":"adjective","english":"having young; teeming, full of (+ abl.)","forms":["fēta","fētum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neptūnus, quī rēgem pūnīre voluit, fēcit ut Pāsiphaē, coniūnx eius, taurum amāret; adultera lignō taurum saevum dēcēperat ut {{fētum}} discordem uterō ferret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fibula","latin":"fībula, -ae","headword":"fībula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"pin","forms":["fībula"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Fībula}} vestīmentum retinēbat et vitta neglēctōs capillōs retinēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fictilis","latin":"fictilis, -e","headword":"fictilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"earthen, earthenware; earthen, made of clay","forms":["fictilia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Imperāvit quam plūrimās venēnātās serpentēs vīvās colligī eāsque in vāsa {{fictilia}} conicī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fictus","latin":"fictus, ficta, fictum","headword":"fictus","letter":"f","pos":"adjective","posGroup":"adjective","english":"feigned, false; counterfeit","forms":["fictā","fictās","fictī","fictīs","fictus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fīlium praetereā Aesonis, nōmine Iāsonem, occīdere temptāvit Pelias, homō scelestus, sed eī, fābulā fictā, nūntiāvērunt amīcī Aesonis puerum iam mortuum esse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fidelis","latin":"fidēlis, -e","headword":"fidēlis","letter":"f","pos":"adjective","posGroup":"adjective","english":"faithful, loyal; faithful (to, + dat.)","forms":["fideli","fidēlibus","fidēlis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, {{fideli}} atque utili superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, iura legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fideliter","latin":"fideliter, fidelius, fidelissime","headword":"fideliter","letter":"f","pos":"adverb","posGroup":"adverb","english":"faithfully/constantly/loyally; earnestly; reliably/accurately; securely/firmly","forms":["fidēliter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Vīderit ütilitàs: ego coepta {{fidēliter}} ēdam:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fidens","latin":"fidens, (gen.), fidentis","headword":"fidens","letter":"f","pos":"adjective","posGroup":"adjective","english":"confident; bold","forms":["fīdēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Haudquāquam parī tum animō Antiochus, intrā 'portās' locī eius castrīs positīs, cum duplicī vallō fossāque et mūrō etiam permūnīsset omnia, satis {{fīdēns}} numquam eā viam Rōmānum exercitum factūrum, Aetōlōs ad Hēraclēam praesidiō obtinendam (quae ante ipsās faucēs posita est) mittit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fidere","latin":"(fīdō) fīdere, fīsum","headword":"fīdere","letter":"f","pos":"verb","posGroup":"verb","english":"(+ dat.) trust, rely on; to trust (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"fides","latin":"fidēs, fidium","headword":"fidēs","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f. pl.) lyre; loyalty, good faith; faith, trust; trust, belief, faith, pledge; faith, pledge, promise","forms":["fide","fideī","fidem","fidēs","fīdī","fidibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac {{fide}} sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fidicen","latin":"fidicen, fidicinis","headword":"fidicen","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(f.) lyre-player; lyre-player, musician","forms":["fidicen","fidicinēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Orpheus nōbilissimus {{fidicen}} atque poēta ēgregius fuit, quī inde ā puerō tam pulchrē canēbat, ut nōn sōlum bēstiae ferae ad eum accurrerent, vērum etiam rapida flūmina cōnsisterent, nē strepitū cantum eius turbārent, ac saxa ipsa arborēsque (mīrābile vīsū!) ad audiendum venīrent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fido","latin":"fido, fidere, fisus sum","headword":"fido","letter":"f","pos":"verb","posGroup":"verb","english":"trust (in), have confidence (in) (w/DAT or ABL)","forms":["fīdēbam","fīdendum","fīdere","fīdō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iuppiter igitur, postquam haec audīvit: “Ō scelestum Promēthēum!” clāmāvit, “Atque ego illī praeter cēterōs {{fīdēbam}}!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fiducia","latin":"fīdūcia, -ae","headword":"fīdūcia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"trust, confidence; confidence","forms":["fiducia","fiduciae","fīdūciam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius praesidi {{fiducia}} una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fidus","latin":"fīdus, -a, -um","headword":"fīdus","letter":"f","pos":"adjective","posGroup":"adjective","english":"loyal, faithful; faithful, loyal","forms":["fīda","fīdam","fīdum","fīdus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In familiā meā ūnum solum servum {{fīdum}} esse crēdō.' Hīc Aemilia marītum interpellat et 'St, Iūlī!' inquit, 'Nōlī servum praesentem laudāre!'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fieri","latin":"fierī","headword":"fierī","letter":"f","pos":"verb","posGroup":"verb","english":"to become, be made","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"figere","latin":"(fīgō) fīgere, fīxisse, fīxum","headword":"fīgere","letter":"f","pos":"verb","posGroup":"verb","english":"fix, fasten; to fix, fasten","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"figit","latin":"fīgit","headword":"fīgit","letter":"f","pos":"verb","posGroup":"verb","english":"fixes, fastens","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"figo","latin":"fīgō, -ere, fīxī, fīxum","headword":"fīgō","letter":"f","pos":"verb","posGroup":"verb","english":"fasten, affix, transfix, pierce","forms":["fīgam","fīgere","fīgeret","fīget","fīgētur","fīgit","fīgitur","fīgunt","fīxa","fīxae","fīxērunt","Fīxistī","fīxit","fīxōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Locus erat amoenissimus; īnsula autem nōn {{fīxa}} stābat, sed, tamquam nāvis, modo hūc modo illūc flūctibus iactābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"figulus","latin":"figulus, figuli","headword":"figulus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"potter; maker of earthenware vessels","forms":["Figulō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Figulō cōnsulibus, prīmō singulōs appellāre, hortārī aliōs, aliōs temptāre: opēs suās, imparātam rem pūblicam, magna praemia coniūrātiōnis docēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"figura","latin":"figūra, -ae ( f.)","headword":"figūra","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"form, appearance; form, shape, figure","forms":["figūrā","figūrae","figūram","figūrās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Figūram}} pulchram tuam mūtābō.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"filia","latin":"fīlia, -ae","headword":"fīlia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"daughter","forms":["fīlia","fīliābus","filiae","fīliam","fīliārum","fīliās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēlia: “Trēs: duo fīliī et ūna {{fīlia}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"filiola","latin":"fīliola, -ae","headword":"fīliola","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"diminuitive of fīlia","forms":["fīliolam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Aemilia: \"Iam fīliōs tuōs magis amās quam tuam Iūliam {{fīliolam}}: Marcum et Quīntum saepe laudās, sed Iūliam rārō laudās, quamquam proba est puella.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"filiolus","latin":"fīliolus, -ī","headword":"fīliolus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"diminuitive of fīlius","forms":["fīliolum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hodiē vērō Mārcus rīdēns dīxit ‘mē, ut {{fīliolum}} probum, semper rēctā viā ad mammam meam redīre!’ Ita Mārcus mē sēcum dūxit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"filius","latin":"fīlius, -ī","headword":"fīlius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"son","forms":["fīlī","fīliī","fīliīs","filio","fīliōrum","fīliōs","fīlium","filius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli {{filius}}, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"filum","latin":"fīlum, -ī","headword":"fīlum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"thread; thread, fillet; thread, string","forms":["fīla","fīlīs","fīlō","fīlum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dederat illī togam textam ē {{fīlīs}} variī colōris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"findo","latin":"findo, findere, fidi, fissus","headword":"findo","letter":"f","pos":"verb","posGroup":"verb","english":"split, cleave, divide","forms":["fissā","fissum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Fissum}} erat in pariete domuum quod nēmō per multōs annōs vīderat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fine","latin":"fine","headword":"fine","letter":"f","pos":"preposition","posGroup":"preposition","english":"up to","forms":["fīne"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Plōrābat enim ille, ac multīs cum lacrimīs flēbat; tam trīstis erat, ut vīvere iam nōllet; immō, ā deīs inter lacrimās petīvit, ut sibi flēre sine {{fīne}} licēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fingere","latin":"(fingō) fingere, finxisse, fictum","headword":"fingere","letter":"f","pos":"","posGroup":"other","english":"form, make up, invent","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fingo","latin":"fingo, fingere, finxi, fictus","headword":"fingo","letter":"f","pos":"verb","posGroup":"verb","english":"mold, form, shape; create, invent; produce; imagine; compose; devise, contrive","forms":["fingat","finge","fingēns","fingere","fingis","fingit","Fingite","fingitur","fingunt","fīnxerat","fīnxerō","fīnxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deus {{fīnxit}} corpus hominis ē līmō terrae; dēdit illī animam vīventem; fēcit illum ad similitūdinem suam, et nōmināvit illum Adamum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"finio","latin":"fīniō, -īre, fīnīvī, fīnītum","headword":"fīniō","letter":"f","pos":"verb","posGroup":"verb","english":"end, conclude, finish","forms":["fīnīre","fīnīret","fīnit","fīnītō","fīnītum","fīnītur","Fīnītūrus","fīnīverat","fīnīvit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita nōnnumquam vītā beātā morte miserrimā {{fīnītur}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"finire","latin":"(fīniō) fīnīre, fīnīvisse, fīnītum","headword":"fīnīre","letter":"f","pos":"","posGroup":"other","english":"finish","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"finis","latin":"fīnis, fīnis","headword":"fīnis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(m.) boundary, limit, end; end; (pl.) boundary","forms":["finem","fines","finibus","finis","fīnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in {{finibus}} Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"finitimus","latin":"fīnitimus, -a, -um","headword":"fīnitimus","letter":"f","pos":"adjective","posGroup":"adjective","english":"adjacent, neighboring","forms":["finitima","finitimam","fīnitimārum","finitimi","finitimis","fīnitimōrum","fīnitimōs","fīnitimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eo cum venisset, timentes confirmat, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant {{finitima}}, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fio","latin":"fīō, fierī, factus sum","headword":"fīō","letter":"f","pos":"verb","posGroup":"verb","english":"become, be made, happen","forms":["fi","fīant","fiat","fīēbant","fiebat","fīent","fierent","fieret","fieri","fīet","fīō","fit","fīunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hoc idem {{fit}} in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi solaci proponebant, quod se prope explorata victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"firmamentum","latin":"firmāmentum, -ī","headword":"firmāmentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"support, strength; support, strengthening","forms":["firmāmenta","firmāmentī","firmāmentum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Secundō diē, fēcit {{firmāmentum}}, quod vocāvit caelum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"firmare","latin":"(fīrmō) fīrmāre","headword":"fīrmāre","letter":"f","pos":"","posGroup":"other","english":"reinforce, strengthen","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"firmitudo","latin":"firmitūdo, -dinis ( f.)","headword":"firmitūdo","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"stability, firmness; firmness, stability","forms":["firmitūdinem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec cōnstitūtiō prīmum habet aequābilitātem quandam magnam, quā carēre diūtius vix possunt līberī, deinde {{firmitūdinem}} — quod et illa prīma facile in contrāria vitia convertuntur, ut exsistat ex rēge dominus, ex optimātibus factiō, ex populō turba et cōnfūsiō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"firmo","latin":"firmo, firmare, firmavi, firmatus","headword":"firmo","letter":"f","pos":"verb","posGroup":"verb","english":"strengthen, harden; support; declare; prove, confirm, establish","forms":["firmandī","firmāre","firmārent","firmat","firmāta","firmātum","firmāvī","firmāvit","firment","firmo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed is locus praesidio ab his, non nimis {{firmo}} tamen, tenebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"firmus","latin":"fīrmus, -a, -um","headword":"fīrmus","letter":"f","pos":"adjective","posGroup":"adjective","english":"strong, stable, firm","forms":["firma","firmam","firmas","firmis","firmissimīs","firmissimus","firmōs","firmum","firmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quinque cohortes, quas minime {{firmas}} ad dimicandum esse existimabat, castris praesidio relinquit; quinque eiusdem legionis reliquas de media nocte cum omnibus impedimentis adverso flumine magno tumultu proficisci imperat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fiscella","latin":"fiscella, fiscellae","headword":"fiscella","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"small wicker-basket","forms":["fiscella","fiscellam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē abscondit eum tribus mēnsibus; sed cum nōn posset eum diūtius occultāre, sūmpsit {{fiscellam}}, quam līnīvit bitūmine ac pice; deinde posuit intus īnfantulum, et exposuit eum inter harundinēs rīpae flūminis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fiscus","latin":"fiscus, -ī","headword":"fiscus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"public treasury; treasury, public purse","forms":["fiscō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Senātus iussit 'sine pretiō darī eōs quī in pūblicā custōdiā essent; quī autem ā prīvātīs tenērentur, id pretium ex fiscō magis quam ā Carthāginiēnsibus solverētur.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fissum","latin":"fissum, -ī","headword":"fissum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"crack","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"fistula","latin":"fistula, -ae","headword":"fistula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"reed pipe, pipes of Pan","forms":["fīstula","fistulae","fistulam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ita Pān {{fistulam}} fōrmat, et fistulae nōmen Syringam dat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fit","latin":"fit, fierī","headword":"fit","letter":"f","pos":"","posGroup":"other","english":"be done, become, happen","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"fixum","latin":"fixum, fixi","headword":"fixum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"fixtures (pl.), fittings","forms":["fīxum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sī mihi nōn animō {{fīxum}} immōtumque sedēret","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fixus","latin":"fixus, fixa, fixum","headword":"fixus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fixed; firmly established (decision/ordinance), unhangable, irrevocable","forms":["fīxus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ipse meā manū mortem inveniam!\" Tālia dīcēns {{fīxus}} eōdem locō haerēbat, dum fīlius et parvus nepōs omnisque domus multīs cum lacrimīs eī suādent nē omnēs suōs sēcum perderet!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flaccus","latin":"Flaccus, Flacci","headword":"Flaccus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"Flaccus; (Roman cognomen); [Q. Horatius Flaccus => the poet Horace]","forms":["Flaccī","Flaccō","Flaccum","Flaccus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fulviō Flaccō cōnsulibus, quibus Hierō Rōmam vēnerat, etiam contrā Ligurēs intrā Italiam bellum gestum est et dē iīs triumphātum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flagello","latin":"flagello, flagellare, flagellavi, flagellatus","headword":"flagello","letter":"f","pos":"verb","posGroup":"verb","english":"flog, whip, lash, scourge; strike repeatedly; thresh/flail (grain); \"whip up\"","forms":["flagellābitur","flagellāverint"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Assilmpsit autem Jēsus duodecim discipulōs et ait illīs:\"Ecce, ascendimus Hierosolymam et cōnsummābuntur omnia quae scrlpta sunt dē Fīliō hominis: trādētur enim gentibus, et illūdētur, et {{flagellābitur}}, et cōnspuētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"flagellum","latin":"flagellum, flagelli","headword":"flagellum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"whip, lash, scourge; thong (javelin); vine shoot; arm/tentacle (of polyp)","forms":["flagellum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Prope erat Pascha ludaeōrum, {{flagellum}} -Ī n et ascendit Iēsus Hierosolymam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"flagitare","latin":"(flāgitō) flāgitāre","headword":"flāgitāre","letter":"f","pos":"verb","posGroup":"verb","english":"demand insistently; to demand eagerly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"flagitiosus","latin":"flāgitiōsus, -a, -um","headword":"flāgitiōsus","letter":"f","pos":"adjective","posGroup":"adjective","english":"disgraceful","forms":["flagitiōsam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Calpurnius, corruptus rēgis pecūniā, bellum trahere coepit atque pācem cum Iugurthā {{flagitiōsam}} fēcit iniussū populī et senātūs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flagitium","latin":"flāgitium, -ī","headword":"flāgitium","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"disgrace; shameful act, outrage","forms":["flāgitia","flāgitiīs","flagitiō","flāgitiōrum","flāgitium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, homicīdium; ūnō verbō, sē contāminābant omnibus {{flāgitiīs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"flagrans","latin":"flagrans, flagrantis (gen.), flagrantior -or -us, flagrantissimus -a -um","headword":"flagrans","letter":"f","pos":"adjective","posGroup":"adjective","english":"flaming, fiery, blazing; hot, scorching; in the ascendant (person/popularity)","forms":["flagrāns","flagrantēs","flagrantī","flagrantis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce vēro, Daphnē prīma Apollinī amōre flagrantī occurrit, pulcherrima nympha quae, cum ferās in silvīs persē quendō et occīdendō atque lībera per campōs currendō gaudēret dominamque Diānam virginem habēret, numquam virum ūllum cognōverat neque amāverat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"flagrare","latin":"(flagrō) flagrāre","headword":"flagrāre","letter":"f","pos":"","posGroup":"other","english":"burn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"flagro","latin":"flagro, flagrare, flagravi, flagratus","headword":"flagro","letter":"f","pos":"verb","posGroup":"verb","english":"be on fire; blaze, flame, burn; be inflamed/excited","forms":["Flagrābant","flagrābat","flagrat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At rēgīna iam caecō amōre {{flagrat}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flamen","latin":"flāmen, -inis (m.)","headword":"flāmen","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"flamen (priest); flamen, priest of a single god","forms":["flāmen","flāmine","flāminēs","flāminibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Invidus adstābat vehementī {{flāmine}} anhēlāns occiduus ventus, quī vērīs signa redūcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"flamina","latin":"flamina, flaminae","headword":"flamina","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"wife of a flamen/priest; priestess","forms":["flāmina"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ut dolor ūnius Danaōs pervēnit ad omnēs, exspectāta diū, nūlla aut contrāria classī {{flāmina}} erant, dūraeque iubent Agamemnona sortēs immeritam saevae nātam mactāre Diānae.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"flaminia","latin":"flaminia, flaminiae","headword":"flaminia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"priest-assistantess; female assistant to flamen; flamen's dwelling","forms":["Flāminia","Flāmīniam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In Italiā multae et magnae viae sunt: via Appia, via Latīna, via {{Flāminia}}, via Aurēlia, via Aemilia.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"flaminium","latin":"flaminium, flaminii","headword":"flaminium","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"priest's office; office of flamen","forms":["Flāminiī","Flāminiō","Flāminium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Flāminiī, quī eōdem tempore viam Flāmīniam mūnīvit; tertius circus trāns Tiberim in agrō Vāticānō cōnstitūtus ā prīncipe C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flaminius","latin":"flaminius, flaminia, flaminium","headword":"flaminius","letter":"f","pos":"adjective","posGroup":"adjective","english":"priestly; of flamen (priest of deity)","forms":["Flāminius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Alter circus posteā in campō Mārtiō aedificātus est et circus {{Flāminius}} appellātus ā nōmine C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"flamma","latin":"flamma, -ae","headword":"flamma","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"flame","forms":["flamma","flammae","flammam","flammārum","flammās","flammīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Īrātus rēx eōs vesfītōs et catēnīs vīnctōs coniēcit in fomaeem ārdentem, sed {{flamma}} nihil illīs nocuit: nec corpus adussit ignis, nec vestēs quidem mūtāvit, at solvit tantummodo vincula, quibus eonstringēbantur, ita ut illaesī in mediā fomace ambulārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"flammifer","latin":"flammifer, flammifera, flammiferum","headword":"flammifer","letter":"f","pos":"adjective","posGroup":"adjective","english":"flaming, fiery","forms":["flammiferās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Illa duābus manibus pīnūs {{flammiferās}} ab Aetnā tulit; sine requiēte errābat per terrās fīliam ab occāsū sōlis ad ortūs quaerēns.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"flammo","latin":"flammo, flammare, flammavi, flammatus","headword":"flammo","letter":"f","pos":"verb","posGroup":"verb","english":"inflame, set on fire; excite","forms":["flammātō","flammāvit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tālia flammātō sēcum dea corde volūtāns","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"flare","latin":"flāre","headword":"flāre","letter":"f","pos":"verb","posGroup":"verb","english":"to blow","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"flatus","latin":"flātus, -ūs","headword":"flātus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"blowing, breeze","forms":["flātū","flātūs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Zephyrus enim, quī iam diū, occultātus inter nūbēs, eōs lūdentēs spectābat, cum ipse quoque puerī amōre accēnsus esset, et Apollinī hāc dē causā invidēret, īrātus in discum vehementī flātū spīrāvit; quod cum fēcisset, discus, dē suō cursū flectēns, Hyacinthī caput graviter percussit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"flavus","latin":"flavus, flava, flavum","headword":"flavus","letter":"f","pos":"adjective","posGroup":"adjective","english":"yellow, golden, gold colored; flaxen, blond; golden-haired (Latham)","forms":["flāvō","flāvōs","Flāvum","Flāvus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Annō XVI Arminius cum Flāvō frātre, quī tunc in exercitū Rōmānō merēbat, hoc colloquium habuisse dīcitur trāns Visurgim flūmen, quod exercitūs in utrāque rīpā locātōs interfluēbat.]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"flebilis","latin":"flēbilis, -e","headword":"flēbilis","letter":"f","pos":"","posGroup":"other","english":"plaintive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"flectere","latin":"(flectō) flectere, flexisse, flectum","headword":"flectere","letter":"f","pos":"verb","posGroup":"verb","english":"bend; to bend, turn","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"flecto","latin":"flectō, -ere, flexī, flexum","headword":"flectō","letter":"f","pos":"verb","posGroup":"verb","english":"to bend, turn, influence","forms":["flectēns","flectentem","flectit","flectitur","flectunt","flexēre","flexit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"S ē d quia ea omnia metus mortis extorquēbat, nōn vērā paenitentiā, dīvīnam misericordiam nōn {{flexit}} rēx impius et homicīda, et, morbō in hōrās ingravēscente, miserē interiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fleo","latin":"fleo, flere, flevi, fletus","headword":"fleo","letter":"f","pos":"verb","posGroup":"verb","english":"cry for; cry, weep","forms":["flē","flēbat","flēbis","flēbit","flēbō","flendō","flēns","flentem","flentes","flentī","flentibus","fleō","flēret","flērī","flēvērunt","flēvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hi cum ad munitiones Romanorum accessissent, {{flentes}} omnibus precibus orabant ut se in servitutem receptos cibo iuvarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"flere","latin":"(fleō) flēre, flēvisse, flētum","headword":"flēre","letter":"f","pos":"verb","posGroup":"verb","english":"weep; to weep, cry","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"fletus","latin":"flētus, -ūs","headword":"flētus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"weeping","forms":["flētibus","flētū","flētum","flētus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quō flētū, quā vōce Plūtōnis et Proserpinae animōs movēret?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"flexilis","latin":"flexilis, flexilis, flexile","headword":"flexilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"pliant, pliable, supple","forms":["Flexilem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Flexilem}} arcum curvāvit inque cor sagittā acūtā Plūtōnem percussit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"flexus","latin":"flexus, flexus","headword":"flexus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"turning, winding; swerve; bend; turning point","forms":["flexibus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Daedalus, quī celeberrimus in arte aedificandī erat, hunc labyrinthum cōnstrūxit quī lūmina in errōrem variārum viārum multīs {{flexibus}} dūceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"flo","latin":"flō, flāre","headword":"flō","letter":"f","pos":"verb","posGroup":"verb","english":"blow","forms":["Flante","flāre","flat","flāvit","flent","flēre","flet"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ventus frīgidus ā montibus {{flāre}} incipit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"flora","latin":"Flora, Florae","headword":"Flora","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"Flora; goddess of flowers","forms":["Flōra","Flōrae","Flōram"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Forum plēnum est virōrum et fēminārum quī emunt aut vēndunt, in hīs {{Flōra}}, puella fōrmōsa, quae rosās vēndit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"florens","latin":"florens, florentis (gen.), florentior -or -us, florentissimus -a -um","headword":"florens","letter":"f","pos":"adjective","posGroup":"adjective","english":"blooming/in bloom, flowering; flowery, bright/shining; flourishing, prosperous","forms":["flōrente","florentem","flōrentēs","flōrentī","flōrentia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, {{florentem}} et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"floreo","latin":"floreo, florere, florui, -","headword":"floreo","letter":"f","pos":"verb","posGroup":"verb","english":"flourish, blossom, be prosperous; be in one's prime","forms":["flōrent","flōrēre","flōruerint","flōruērunt","flōruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ezechlas singularī pietāte {{flōruit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"florere","latin":"(flōreō) flōrēre, flōruisse","headword":"flōrēre","letter":"f","pos":"verb","posGroup":"verb","english":"bloom, flourish; to flourish, be at one's prime","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"flos","latin":"flōs, flōris","headword":"flōs","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(m.) flower","forms":["flōre","flōrem","flōrēs","flōribus","floris","flōrum","flōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id ex similitudine {{floris}} lilium appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fluctuo","latin":"fluctuo, fluctuare, fluctuavi, fluctuatus","headword":"fluctuo","letter":"f","pos":"verb","posGroup":"verb","english":"rise in waves, surge, swell, undulate, fluctuate; float; be agitated/restless","forms":["fluctuat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"saevit amor magnōque īrārum {{fluctuat}} aestū.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fluctus","latin":"flūctus, -ūs","headword":"flūctus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(m.) wave","forms":["flūctibus","flūctū","flūctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēlētus est ūniversus exercitus pharaōnis in mediīs {{flūctibus}}, nec ūnus quidem nūntius tantae clādis superfuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fluentum","latin":"fluentum, fluenti","headword":"fluentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"stream/river; flood; (waters of) lake; flow (L+S); current/draft/draught of air","forms":["fluenta","fluentīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"mōre (: modo) {{fluentīs}} aquae : sīcut","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fluere","latin":"fluere","headword":"fluere","letter":"f","pos":"verb","posGroup":"verb","english":"to flow","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"fluidus","latin":"fluidus, fluida, fluidum","headword":"fluidus","letter":"f","pos":"adjective","posGroup":"adjective","english":"liquid; soft, feeble","forms":["fluidōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dīxit Achaemenidēs: \"iterum Polyphēmon et illōs\nadspiciam {{fluidōs}} hūmānō sanguine rīctūs,\nhāc mihi sī cārior domus est Īthacāque carīna,\nsī minus Aenēān veneror genitōre, nec umquam\nesse satis poterō, nōn sī dederō omnia, grātus.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"fluit","latin":"fluit, fluere","headword":"fluit","letter":"f","pos":"","posGroup":"other","english":"flow","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"fluito","latin":"fluito, fluitare, fluitavi, fluitatus","headword":"fluito","letter":"f","pos":"verb","posGroup":"verb","english":"float; flow; waver","forms":["fluitābat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Omnia absūmpta sunt dīluviō; arca autem sublevātā aquīs {{fluitābat}} in altō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"flumen","latin":"flūmen, flūminis","headword":"flūmen","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"(n.) river","forms":["flumen","flumina","flumine","flūminī","flūminibus","fluminis","flūminum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qui cum ad {{flumen}} Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fluo","latin":"fluo, fluere, fluxi, fluxus","headword":"fluo","letter":"f","pos":"verb","posGroup":"verb","english":"flow, stream; emanate, proceed from; fall gradually","forms":["fluēbant","fluēbat","fluēns","fluentem","fluentia","fluentibus","fluere","flueret","fluit","fluō","fluunt","flūxērunt","flūxī","flūxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dē fronte eius sanguis {{fluit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fluvius","latin":"fluvius, -ī","headword":"fluvius","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"river","forms":["fluviī","fluviīs","fluviō","fluviōrum","fluviōs","fluvium","fluvius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia: “Nīlus magnus {{fluvius}} est.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fluxus","latin":"fluxus, fluxa, fluxum","headword":"fluxus","letter":"f","pos":"adjective","posGroup":"adjective","english":"flowing; fluid; loose; transient, frail, dissolute","forms":["flūxa"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam dīvitiārum et fōrmae glōria {{flūxa}} atque fragilis est, virtūs clāra aeternaque habētur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"foculus","latin":"foculus, -ī","headword":"foculus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"hearth","forms":["foculum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum illa {{foculum}} cōram cum ignī appōnit, trēs librōs ex novem deūrit, et 'ecquid reliquōs sex eōdem pretiō emere vellet?' rēgem interrogāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"focus","latin":"focus, -ī","headword":"focus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"hearth","forms":["focī","focīs","focō","focum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sacrīs domesticīs in focō ūritur tūs MŌRĒS.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fodio","latin":"fodio, fodere, fodi, fossus","headword":"fodio","letter":"f","pos":"verb","posGroup":"verb","english":"dig, dig out/up; stab","forms":["fodiebantur","fodit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ante hos obliquis ordinibus in quincuncem dispositis scrobes tres in altitudinem pedes {{fodiebantur}} paulatim angustiore ad infimum fastigio.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"foede","latin":"foede, foedius, foedissime","headword":"foede","letter":"f","pos":"adverb","posGroup":"adverb","english":"foully, repulsively; horribly, hideously; in way that offends senses/feelings","forms":["foedē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Neque sōlum foedē, sed etiam prāvē scrīpsit discipulus tuus optimus!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"foederatus","latin":"foederātus, -a, -um","headword":"foederātus","letter":"f","pos":"adjective","posGroup":"adjective","english":"federated, allied; allied by treaty","forms":["foederātam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sīc Hannibal, minor quīnque et vīgintī annīs nātus, imperātor factus, proximō trienniō omnēs gentēs Hispāniae bellō subēgit, Saguntum, {{foederātam}} cīvitātem, vī expugnāvit, trēs exercitūs maximōs comparāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"foeditas","latin":"foeditās, -ātis ( f.)","headword":"foeditās","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"ugliness, shame; foulness, baseness","forms":["foeditāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quō enim dūcere hunc iuvenem potestis ubi nōn sua decora eum ā tantā {{foeditāte}} suppliciī dēfendant?\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"foedo","latin":"foedo, foedare, foedavi, foedatus","headword":"foedo","letter":"f","pos":"verb","posGroup":"verb","english":"defile; pollute; soil, stain, make filthy/unclean; contaminate; corrupt","forms":["foedat"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Lābitur ā ille in equī iubam, et terram calidō sanguine {{foedat}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"foedus","latin":"foedus, -a, -um","headword":"foedus","letter":"f","pos":"adjective; noun (n.)","posGroup":"adjective","english":"ugly, hideous; treaty; ugly, foul; covenant, agreement, treaty; treaty, compact; treaty, alliance","forms":["foeda","foedae","foedam","foedās","foederā","foedere","foederibus","foederis","foedī","foedīs","foedissimae","foedissimē","foedissimīs","foedius","foedōs","foedum","foedus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ō, quam foedī sunt pullī mortuī!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"foenum","latin":"foenum, foeni","headword":"foenum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"hay","forms":["foenī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Est domī locus ad commorandum amplissmus; est etiam plūrimum foenī et paleārum ad ūsum camēlōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"foetor","latin":"foetor, foetoris","headword":"foetor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"stench; bad/foul smell, stink; foulness, noisomeness (L+S)","forms":["foetōrem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At illum subitus vīscerum dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta scatērent vermibus, et {{foetōrem}} lātē ēmitterent, exercituī et aegrō ipsī intolerābilem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"folium","latin":"folium, -ī","headword":"folium","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"leaf; leaf, petal","forms":["folia","foliīs","foliō","foliōrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Syra rāmōs et {{folia}} arboris movet et inter rāmōs parvum nīdum videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"follis","latin":"follis, follis","headword":"follis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"bag, purse; handball; pair of bellows; scrotum","forms":["follem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec amplius eam repetēbat quae terram contigerat, sed {{follem}} plēnum habēbat servus sufﬁciëbatque lūdentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fomes","latin":"fomes, fomitis","headword":"fomes","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"chips of wood, etc for kindling/feeding a fire","forms":["fōmite"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nūtrīmenta dedit, rapuitque in {{fōmite}} flammam.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fons","latin":"fōns, fontis (m.)","headword":"fōns","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"spring, source; fountain, pool, spring; spring, fountain","forms":["fōns","fonte","fontem","fontēs","fontī","fontis","fontium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam Noëmus ipse ingressus est in arcam cum coniuge, tribus fīliīs et totidem nuribus, aquā maris et omnium {{fontium}} ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fontanus","latin":"fontanus, fontana, fontanum","headword":"fontanus","letter":"f","pos":"adjective","posGroup":"adjective","english":"of a spring","forms":["fontāna"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ōraque {{fontāna}} fervida pulsat aquá.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"for","latin":"for, fārī","headword":"for","letter":"f","pos":"verb","posGroup":"verb","english":"speak","forms":["fandī","fandō","fārī","fātur","fātus","for"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{b}[[Insert Colloquia_5.tif here, see orig {/b} {b}{{for}} size/placement]]{/b}","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"foras","latin":"forās","headword":"forās","letter":"f","pos":"adverb","posGroup":"adverb","english":"outside (toward); out, out of doors (with motion)","forms":["forās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque ūna ambō abiērunt {{forās}}, et cum essent in agrō, Caīnus irruit in Abēlem, et interfēcit illum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fore","latin":"fore","headword":"fore","letter":"f","pos":"verb","posGroup":"verb","english":"= futurum esse; to be about to be","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"foris","latin":"foris, foris","headword":"foris","letter":"f","pos":"noun (f.); adverb","posGroup":"noun","english":"(f.) folding door; outside (place where); door, door-leaf; (pl.) double doors; outside, out of doors; (pl.) doors","forms":["foribus","foris","forium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnes alacres et fiduciae pleni ad Alesiam proficiscuntur, neque erat omnium quisquam qui aspectum modo tantae multitudinis sustineri posse arbitraretur, praesertim ancipiti proelio, cum ex oppido eruptione pugnaretur, {{foris}} tantae copiae equitatus peditatusque cernerentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"forma","latin":"fōrma, -ae","headword":"fōrma","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"form, shape, figure; form, shape","forms":["forma","fōrmae","fōrmam","fōrmās","fōrmīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Muri autem omnes Gallici hac fere {{forma}} sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"format","latin":"format, formant","headword":"format","letter":"f","pos":"verb","posGroup":"verb","english":"makes, shapes, fashions","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"formica","latin":"formica, formicae","headword":"formica","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"ant","forms":["formīca"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ut redit itque frequēns longum {{formīca}} per agmen,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"formidabilis","latin":"formīdābilis, -e","headword":"formīdābilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"fearful, terrible","forms":["formīdābilis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pāruit Aenēās et {{formīdābilis}} Orcī\nvīdit opēs ātavōsque suōs umbramque senīlem\nmagnanimī Anchīsae; didicit quoque iūra locōrum,\nquaeque novīs essent adeunda perīcula bellīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"formido","latin":"formīdō, -inis ( f.)","headword":"formīdō","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"dread, terror","forms":["formīdāns","formīdine","formīdinī","formīdō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Deus dīxit Iosue: “Nē timeās eōs: tua erit victōria.” Iosue igitur magnō impetū illōs adortus est, quī, subitā {{formīdine}} correptī, fūgērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"formidolosus","latin":"formidolosus, formidolosa -um, formidolosior -or -us, formidolosissimus -a -um","headword":"formidolosus","letter":"f","pos":"adjective","posGroup":"adjective","english":"terrible, scary; dangerous, alarming; formidable; fearful/timorous/frightened","forms":["formīdolōsa","formīdolōsum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"AMPHITRYO: Mīrā memorās, nimis {{formīdolōsum}} facinus praedicās;","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"formo","latin":"formo, formare, formavi, formatus","headword":"formo","letter":"f","pos":"verb","posGroup":"verb","english":"form, shape, fashion, model","forms":["formābat","format","fōrmāvit","formet","Formō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ex ea {{fōrmāvit}} mulierem, quam dedit sociam Adamō, sīcque īnstituit mātrimōnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"formose","latin":"formose, formosius, formosissime","headword":"formose","letter":"f","pos":"adverb","posGroup":"adverb","english":"beautifully, in a beautiful manner","forms":["fōrmōse"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō {{fōrmōse}} puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"formosus","latin":"fōrmōsus, -a, -um","headword":"fōrmōsus","letter":"f","pos":"adjective","posGroup":"adjective","english":"beautiful; beautiful, handsome; beautiful, shapely","forms":["fōrmōsā","fōrmōsae","fōrmōsam","fōrmōsās","Fōrmōsī","fōrmōsissima","fōrmōsissimae","fōrmōsissimam","fōrmōsissimum","fōrmōsissimus","fōrmōsōs","fōrmōsum","fōrmōsus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa: “Quia in vīllā multae sunt ancillae {{fōrmōsae}}... ”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"formula","latin":"fōrmula, -ae","headword":"fōrmula","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"terms, formula","forms":["fōrmula"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Collātīnīs hīs verbīs dēditī sunt, eaque dēditiōnis {{fōrmula}} est: Rēx interrogāvit: \"Estisne vōs lēgātī ōrātōrēsque ut missī ā populō Collātīnō, vōs populumque Collātīnum dēderētis?\" \"Sumus.\" \"Estne populus Collātīnus in suā potestāte?\" \"Est.\" \"Dēditisne vōs populumque Collātīnum, urbem, agrōs, aquam, terminōs, dēlūbra, dīvīna hūmānaque omnia in meam populumque Rōmānum diciōnem?\" \"Dedimus.\" \"At ego recipiō.\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fornix","latin":"fornix, fornicis","headword":"fornix","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"arch, vault, vaulted opening; monument arch; brothel, cellar for prostitution","forms":["fornicibus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eum mūniunt undique parietēs atque īnsuper camera lapideīs {{fornicibus}} iūncta; sed incultū, tenebrīs, odōre foeda atque terribilis eius faciēs est.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"fors","latin":"fors, fortis","headword":"fors","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"chance; luck, fortune; accident","forms":["fors"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Labienus, postquam neque aggeres neque fossae vim hostium sustinere poterant, coactis una XI cohortibus, quas ex proximis praesidiis deductas {{fors}} obtulit, Caesarem per nuntios facit certiorem quid faciendum existimet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"forsan","latin":"forsan","headword":"forsan","letter":"f","pos":"adverb","posGroup":"adverb","english":"perhaps, maybe","forms":["forsan"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Forsan}} et haec ōlim meminisse iuvābit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"forsitan","latin":"forsitan","headword":"forsitan","letter":"f","pos":"adverb","posGroup":"adverb","english":"maybe, perhaps; perhaps; perhaps, it may be","forms":["forsitan"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At Dāvīd eōs cohibuit: “Sinite” inquit “istum mihi maledīcere; {{forsitan}} Deus, hīs quae patior malīs plācātus, meī miserēbitur, et meum dolōrem respiciet.” Incrēdibilem rēgis patientiam admīrātī, comitēs dictō aegrē pāruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fortasse","latin":"fortasse","headword":"fortasse","letter":"f","pos":"adverb","posGroup":"adverb","english":"perhaps","forms":["fortasse"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tlēpolemus: “{{Fortasse}} nōn tam stultus est canis tuus: certē ūnam litteram scit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fortassis","latin":"fortassis","headword":"fortassis","letter":"f","pos":"adverb","posGroup":"adverb","english":"perhaps, possibly; it may be","forms":["fortassis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"665 Pugnàbit prīmō {{fortassis}} et \"improbe!\" dīcet","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"forte","latin":"forte","headword":"forte","letter":"f","pos":"adverb","posGroup":"adverb","english":"by chance","forms":["forte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Isaacus {{forte}} tunc dēambulābat rūre; vīdit camēlōs venientēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fortis","latin":"fortis, -e","headword":"fortis","letter":"f","pos":"adjective","posGroup":"adjective","english":"strong, brave; brave, strong","forms":["fortem","fortēs","fortī","fortia","fortibus","fortior","fortiōrēs","fortis","fortissimae","fortissimē","fortissimī","fortissimīs","fortissimō","fortissimōs","fortissimum","fortissimus","fortium","fortius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum {{fortium}} morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fortiter","latin":"fortiter","headword":"fortiter","letter":"f","pos":"adverb","posGroup":"adverb","english":"bravely","forms":["fortiter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī vestrō obsequar cōnsiliō, hominum quidem suppliciīs ēripiar, sed Īram dīvīnam nōn effugiam.\"Hīs dicfīs, mortem {{fortiter}} subiit, aetēmamque glōriam est cōnsecūtus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fortitudo","latin":"fortitūdō, -inis ( f.)","headword":"fortitūdō","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"strength, bravery; strength, courage; bravery, courage; courage, bravery","forms":["fortitūdine","fortitūdinem","fortitūdinis","fortitūdō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnēs igitur Callistō summīs laudibus afficiēbant eiusque vīrēs tam multum admīrābantur ut dē ea eiusque factīs omnēs hominēs fābulārentur, atque ūnō ōre optārent ut praemia {{fortitūdinis}} ac probitātis ā deīs acciperet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fortuito","latin":"fortuītō","headword":"fortuītō","letter":"f","pos":"","posGroup":"other","english":"by chance, fortuitously","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fortuna","latin":"fortūna, -ae","headword":"fortūna","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"fortune; fortune, luck","forms":["fortuna","fortunae","fortunam","fortunarum","fortūnās","fortunis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae {{fortunam}}; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fortunatus","latin":"fortūnātus, -a, -um","headword":"fortūnātus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fortunate; fortunate, blessed","forms":["fortūnāta","Fortūnātae","Fortūnātam","fortūnātī","fortūnātissimam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque quotiēnscumque dîcit “Carpe!” eôdem verbô et [Dê Fortûnätä, dê dîvitiîs T rimalchiônis, dē collîbertîs] Nôn potuî amplius quicquam gustāre, sed conversus ad eum, ut quam plūrima exciperem, longē accersere täbulās coepî scîscitäxîque ‘quae esset mulier illa quae hūc atque “Uxor” inquit “Trīma1chiônis, ‘{{Fortūnāta}}’ appellättlr; quae nummôs modiô mëtîtur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"forum","latin":"forum, -ī","headword":"forum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"forum; public space, marketplace; forum, market-place","forms":["fora","forī","foro","forum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque deiecti in {{foro}} ac locis patentioribus cuneatim constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"forus","latin":"forus, fori","headword":"forus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"gangway in a ship; row of benches erected for games/circus; cell of bees","forms":["forōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quī labor cum mīlitiae adderētur, minus tamen plēbs indignābātur sē templa deōrum aedificāre manibus suīs, quam postquam ad alia opera speciē minōra, sed labōris aliquantō maiōris traducēbātur, velut ad {{forōs}} in circō faciendōs cloācamque Maxumam sub terrā agendam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fossa","latin":"fossa, -ae","headword":"fossa","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"ditch, trench; ditch; trench, ditch","forms":["fossa","fossae","fossam","fossas","fossum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fit magna caedes; non nulli relictis equis {{fossam}} transire et maceriam transcendere conantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fovea","latin":"fovea, foveae","headword":"fovea","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"pit, pitfall","forms":["foveā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Habēbat in animō līberāre Iōsēphum ex eōrum manibus, et illum extrahere ē foveā, atque ad patrem redūcere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"foveo","latin":"foveo, fovere, fovi, fotus","headword":"foveo","letter":"f","pos":"verb","posGroup":"verb","english":"keep warm; favor, cherish, maintain, foster","forms":["fōtum","foveam","fovēmus","fovēre","fovet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōlīte, inquiēbat, interficere puerum; est enim frāter noster; dēmittite eum potius in hanc {{foveam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fragilis","latin":"fragilis, -e (< frangere Caps. XXIV, XLIII, XLVI)","headword":"fragilis","letter":"f","pos":"adjective","posGroup":"adjective","english":"fragile, frail","forms":["fragile","fragilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ut {{fragilis}} glaciēs interit īra mora.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fragmentum","latin":"fragmentum, -ī (< frangere)","headword":"fragmentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"fragment, piece","forms":["fragmenta","fragmentīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā collēgērunt {{fragmenta}}, et superfuērunt duodecim cophinī","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fragor","latin":"fragor, -ōris (m.)","headword":"fragor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"crash; crash, thunder","forms":["fragor","fragōre","fragōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Parentēs expavidī ignem aquā restinguere properant; at pater Anchīsēs laetus Iovem invocat, subitōque {{fragōre}} ā laevā gravis tonat, et simul stēlla dē caelō lāpsa multā cum lūce per tenebrās currit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"frangere","latin":"(frangō) frangere, frēgisse, frāctum","headword":"frangere","letter":"f","pos":"verb","posGroup":"verb","english":"break; to break; to break, wreck","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"frango","latin":"frangō, -ere, frēgī, frāctum","headword":"frangō","letter":"f","pos":"verb","posGroup":"verb","english":"break, shatter","forms":["frāctā","frāctās","frāctīs","frāctum","frāctus","frangās","frangat","frangere","frangētur","frangis","frangitur","franguntur","frēgēre","frēgisse","frēgit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Solve canem tuum!” clāmat aliquis, dum aliī magnō cum strepitū forēs {{frangere}} cōnantur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"frater","latin":"frāter, frātris","headword":"frāter","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(m.) brother","forms":["frater","fratre","fratrem","fratres","frātrī","fratribus","frātris","frātrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius {{frater}} Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fraternus","latin":"fraternus, fraterna, fraternum","headword":"fraternus","letter":"f","pos":"adjective","posGroup":"adjective","english":"brotherly/brother's; of/belonging to a brother; fraternal; friendly; of cousin","forms":["frāternā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"coniugis et sparsōs frāternā caede penātīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"fraudo","latin":"fraudo, fraudare, fraudavi, fraudatus","headword":"fraudo","letter":"f","pos":"verb","posGroup":"verb","english":"cheat/defraud/swindle; deprive deceitfully; baffle, make ineffectual; dishonor","forms":["fraudāre","fraudat","Fraudātor","fraudātur","fraudō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"verba superba ferōx et spē quoque {{fraudat}} amantem.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fraus","latin":"fraus, -audis ( f.)","headword":"fraus","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"deceit, guile","forms":["fraude","fraudem","fraudis","fraus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His cognitis et Litavicci {{fraude}} perspecta Aedui manus tendere et deditionem significare et proiectis armis mortem deprecari incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fremere","latin":"(fremō) fremere, fremuisse,  fremitum","headword":"fremere","letter":"f","pos":"","posGroup":"other","english":"growl","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"fremitus","latin":"fremitus, -ūs","headword":"fremitus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"rumble, growl; roar, murmur","forms":["fremitus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quārtō post diē quam cum rēge est pugnātum, cum in circō lūdī fierent, murmur repentē populum tōtā spectācula pervāsit 'pugnātum in Macedoniā et dēvictum rēgem esse'; dein {{fremitus}} incrēvit; postrēmō clāmor, plausus, velut certō nūntiō victōriae allātō, est exortus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fremo","latin":"fremo, fremere, fremui, fremitus","headword":"fremo","letter":"f","pos":"verb","posGroup":"verb","english":"roar; growl; rage; murmur, clamor for","forms":["fremēbant","fremēns","frementem","fremere","fremit","fremunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Canis īrātus dentēs ostendit ac {{fremit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"frendere","latin":"(frendō) frendere, frenduisse,","headword":"frendere","letter":"f","pos":"","posGroup":"other","english":"gnash one’s teeth frēsum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"frendo","latin":"frendo, frendere, frendui, fresus","headword":"frendo","letter":"f","pos":"verb","posGroup":"verb","english":"gnash the teeth, grind up small","forms":["frendēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"scit bene, quà {{frendēns}} valle morētur aper;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"freno","latin":"freno, frenare, frenavi, frenatus","headword":"freno","letter":"f","pos":"verb","posGroup":"verb","english":"brake, curb, restrain, check","forms":["frēnāre","frēnat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"imperiō premit ac vinclīs et carcere {{frēnat}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"frenum","latin":"frenum, freni","headword":"frenum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"bridle/harness/rein/bit; harnessed horses/team; check/restraint/brake; mastery","forms":["frēna","frēnum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In somnīs vērō deā Minerva eī dormientī appāruit, quae “Ō Bellerophōn” inquit, “ecce: aureum {{frēnum}} tibi dō; quaere igitur Pēgasum, equum quī ālās habet et volāre potest tamquam magna quaedam avis.” Haec cum dīxisset, abiit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"frequens","latin":"frequēns","headword":"frequēns","letter":"f","pos":"adjective","posGroup":"adjective","english":"(gen.frequentis) crowded, numerous, frequent; frequent, common","forms":["frequēns","frequentem","frequentes","frequentibus","frequentis","frequentissimum","frequentius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eodem conveniunt undique {{frequentes}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frequenter","latin":"frequenter","headword":"frequenter","letter":"f","pos":"adverb","posGroup":"adverb","english":"often, frequently; in great numbers; in crowds","forms":["frequenter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Āfricānus, hic Paulī fīlius, fēriīs Latīnīs Tūditānō cōnsule et Aquīliō, cōnstituisset in hortīs esse familiārissimīque eius ad eum {{frequenter}} per eōs diēs ventitātūrī sē esse dīxissent, Latīnīs ipsīs māne ad eum prīmus sorōris fīlius vēnit Q.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"frequentia","latin":"frequentia, frequentiae","headword":"frequentia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"crowd; large attendance; abundance of persons/things; frequency","forms":["frequentiā","frequentiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iildās omnia pūrgāvit, portās refēcit, novum altāre ērēxit, cuius dēdicātiō magna tofius populī frequentiā, clangentibus tubīs, facta est; dēcrētumque, ad memoriam reī sempitēmam, quotannīs diem sollemnem celebrātum In.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fretum","latin":"fretum, -ī","headword":"fretum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"strait, channel","forms":["freta","frētī","fretō","fretum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus et Lȳdia ventō secundō per mare Īnferum nāvigāre pergunt ad {{fretum}} Siculum (id est fretum quō Sicilia ab Italiā disiungitur).","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fretus","latin":"frētus, -a, -um","headword":"frētus","letter":"f","pos":"adjective","posGroup":"adjective","english":"relying on, confident of (+ abl.); relying on, trusting (+ abl.)","forms":["frētus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iosue dīvīnō auxiliō {{frētus}}, nōn armīs aut vīribus urbem aggressus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"frico","latin":"frico, fricare, fricui, frictus","headword":"frico","letter":"f","pos":"verb","posGroup":"verb","english":"rub, chafe","forms":["Fricā","fricāre","fricuisse"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"nec cōram dentēs dé{{fricuisse}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"friget","latin":"frīget, frīgēre","headword":"frīget","letter":"f","pos":"verb","posGroup":"verb","english":"be cold; is cold","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"frigidus","latin":"frīgidus, -a, -um","headword":"frīgidus","letter":"f","pos":"adjective","posGroup":"adjective","english":"cold, chilly, cool; cold","forms":["frīgida","frīgidae","frīgidam","frīgidārum","frīgidior","frīgidiōrēs","frīgidissimus","frīgidō","frīgidum","frīgidus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Merīdiē in sōle ambulāre mē nōn dēlectat, sed vesperī āēr nec nimis calidus nec nimis {{frīgidus}} est.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"frigo","latin":"frigo, frigere, frixi, frictus","headword":"frigo","letter":"f","pos":"verb","posGroup":"verb","english":"roast, parch; fry (L+S)","forms":["frīgent","frīgentī","frīgentia","frīget","frīgī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Prīmum hominēs, rē novā perterritī, fugere volēbant; Promētheus vērō eōs retinuit atque mōnstrāvit quam ūtile illud mūnus eīs esset: “Igne corpora vestra nūda et {{frīgentia}} calefacere poteritis; ferōcissimae quoque bēstiae ab igne fugient, neque in vōs impetum facere audēbunt; praetereā igne vōbīs etiam ferrum mollīre et arma cōnficere licēbit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"frigus","latin":"frīgus, frīgoris","headword":"frīgus","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"(n.) chill, cold; cold; cold, chill of death","forms":["frīgora","frigore","frīgoribus","frīgoris","frīgus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore {{frigore}} et assiduis imbribus tardarentur, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frondeo","latin":"frondeō, -ēre","headword":"frondeō","letter":"f","pos":"verb","posGroup":"verb","english":"put out leaves","forms":["frondēre","frondet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sed ōlim dum duo piī prō templō stant, Philēmōn coniugem {{frondēre}} et Baucis Philēmōnem frondēre vīdit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"frondeus","latin":"frondeus, frondea, frondeum","headword":"frondeus","letter":"f","pos":"adjective","posGroup":"adjective","english":"leafy","forms":["frondea"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"miscet agēns tēlīs nemora inter {{frondea}} turbam;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"frons","latin":"frōns, frontis","headword":"frōns","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f.) forehead; foliage, leaves; a leaf, foliage; leaf, foliage","forms":["fronde","frondēs","frondibus","frondis","frōns","fronte","frontem","frontī","frontibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hae revinciuntur introrsus et multo aggere vestiuntur; ea autem quae diximus intervalla grandibus in {{fronte}} saxis effarciuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fructus","latin":"frūctus, -ūs","headword":"frūctus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"produce, fruit; fruit, produce, profit","forms":["frūctibus","fructum","frūctūs","frūctuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ipse adit reliquos, cohortatur ne labori succumbant; omnium superiorum dimicationum {{fructum}} in eo die atque hora docet consistere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frugaliter","latin":"frugaliter, frugalius, frugalissime","headword":"frugaliter","letter":"f","pos":"adverb","posGroup":"adverb","english":"simply, frugally, economically; soberly; in a restrained manner","forms":["frūgāliter"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quārē inquīsīstī?” [Iūlius:] “Sī tibi suāve est, hodiē apud mē prandē {{frūgāliter}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"fruges","latin":"frūgēs, frūgum","headword":"frūgēs","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"(f. pl.) crops; crops, fruits of the earth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"frui","latin":"(fruor) fruī, fructum","headword":"fruī","letter":"f","pos":"verb","posGroup":"verb","english":"(+ abl.) enjoy; to enjoy (+ abl.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"frumentarius","latin":"frūmentārius, -a, -um","headword":"frūmentārius","letter":"f","pos":"adjective","posGroup":"adjective","english":"of or belonging to wheat, grain","forms":["frumentaria","frumentariae","frumentariam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Fufium Citam, honestum equitem Romanum, qui rei {{frumentariae}} iussu Caesaris praeerat, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frumentatio","latin":"frumentatio, frumentationis","headword":"frumentatio","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"foraging; collecting of grain","forms":["frumentationem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Dum haec apud Alesiam geruntur, Galli, concilio principum indicto, non omnes eos qui arma ferre possent, ut censuit Vercingetorix, convocandos statuunt sed certum numerum cuique ex civitate imperandum, ne tanta multitudine confusa nec moderari nec discernere suos nec {{frumentationem}} habere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frumentor","latin":"frumentor, frumentari, frumentatus sum","headword":"frumentor","letter":"f","pos":"verb","posGroup":"verb","english":"get grain, forage","forms":["frumentari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Erat eodem tempore et materiari et {{frumentari}} et tantas munitiones fieri necesse deminutis nostris copiis, quae longius ab castris progrediebantur; ac non numquam opera nostra Galli temptare atque eruptionem ex oppido pluribus portis summa vi facere conabantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frumentum","latin":"frūmentum, -ī","headword":"frūmentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"grain; grain, wheat","forms":["frūmenta","frumenti","frumento","frumentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies {{frumento}} milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fruor","latin":"fruor, frui, fructus sum","headword":"fruor","letter":"f","pos":"verb","posGroup":"verb","english":"enjoy (proceeds/socially/sexually), profit by, delight in (w/ABL)","forms":["fruantur","fruātur","fruēbantur","fruēbātur","Fruēre","frueris","fruī","fruimur","fruitur","fruor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Iacobus: satis diū vīxī, inquit; nunc aequō animō moriar, quoniam cōnspectū tuō fruī mihi licuit, et tē mihi superstitem relinquō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"frustra","latin":"frūstrā","headword":"frūstrā","letter":"f","pos":"adverb","posGroup":"adverb","english":"in vain","forms":["frūstrā"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Conantibus auxiliari suis, '{{Frustra}}', inquit, 'meae vitae subvenire conamini, quem iam sanguis viresque deficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"frustrari","latin":"(frūstror) frūstrārī","headword":"frūstrārī","letter":"f","pos":"","posGroup":"other","english":"deceive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"frustror","latin":"frustror, frustrari, frustratus sum","headword":"frustror","letter":"f","pos":"verb","posGroup":"verb","english":"disappoint, frustrate, deceive (w/false hope); escape/elude; baffle/evade; fail","forms":["frūstrāberis","frūstrandā","frūstrārīs","frūstrātur"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"AMPHITRYO: Nescioquis praestigiātor hanc {{frūstrātur}} mulierem.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"frustum","latin":"frustum, frusti","headword":"frustum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"crumb, morsel, scrap of food","forms":["frusta","frustum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Secūtus est Âiäx, strictôque gladiô, tamquam însänîret, vitulum concîdit, ac modo versā modō supînä gesticulātus mucrône {{frusta}} m collegnt mnranubusque parūtus est. pônere (Diāna cervam subië- cit Ïphigenîae sacriﬁcandae) argūmentum -î n: ā.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"frutex","latin":"frutex, fruticis","headword":"frutex","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"shrub, bush; shoot, stem, stalk, growth; \"blockhead\"","forms":["frutex","fruticēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"aucupibus nōtī {{fruticēs}}; quī sustinet hāmōs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"frux","latin":"frux, frugis","headword":"frux","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"crops (pl.), fruits, produce, legumes; honest men","forms":["frūgēs","frūgibus","frūgum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque, Rēx, praefice tōtī Aegyptō virum sapientem et industrium, quī partem {{frūgum}} recondat in horreīs pūblicīs, servetque dīligenter in subsidium famis secūtūrae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fuga","latin":"fuga, -ae","headword":"fuga","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"flight, a running away; flight, escape; flight","forms":["fuga","fugae","fugam","fugās","fugis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis {{fugam}} intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fugare","latin":"(fugō) fugāre","headword":"fugāre","letter":"f","pos":"verb","posGroup":"verb","english":"put to flight, rout; to rout, put to flight","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"fugio","latin":"fugiō, -ere, fūgī, -itum","headword":"fugiō","letter":"f","pos":"verb","posGroup":"verb","english":"flee; to flee, avoid","forms":["fuge","fugerant","fugerat","fugere","fugerent","fugeret","fūgerīs","fugerunt","fūgī","fugiam","fugiās","fugiat","fugiēbam","fugiēbant","fugiēbat","fugiendī","fugiendō","fugiendum","fugiēns","fugient","fugientem","fugientes","Fugientī","fugientibus","fugientis","fugientium","fugimur","fugiō","fugisse","fugit","fugite","fugiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et maxime, quod ipse animo non defecerat tanto accepto incommodo neque se in occultum abdiderat et conspectum multitudinis {{fugerat}}; plusque animo providere et praesentire existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fugit","latin":"fugit, fugere","headword":"fugit","letter":"f","pos":"verb","posGroup":"verb","english":"run away, flee; flees","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"fugitat","latin":"fugitat","headword":"fugitat","letter":"f","pos":"verb","posGroup":"verb","english":"flees, runs away","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"fugitivus","latin":"fugitīvus, -a, -um","headword":"fugitīvus","letter":"f","pos":"adjective","posGroup":"adjective","english":"fugitive; runaway, fugitive","forms":["fugitīvīs","fugitīvōs","fugitīvum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: 'Etiam sī adhūc Rōmae latet, difficile erit servum {{fugitīvum}} in tantā urbe reperīre.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"fugito","latin":"fugitō, -āre, -āvī, -ātum","headword":"fugitō","letter":"f","pos":"verb","posGroup":"verb","english":"flee, avoid, shun","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"fugo","latin":"fugō (1)","headword":"fugō","letter":"f","pos":"verb","posGroup":"verb","english":"put to flight, drive away","forms":["fugant","fugāre","fugat","fugātī","fugātis","fugātō","fugātum","fugātus","fugāverit","fugāvit","fugent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Fugato}} omni equitatu, Vercingetorix copias, ut pro castris collocaverat, reduxit protinusque Alesiam, quod est oppidum Mandubiorum, iter facere coepit celeriterque impedimenta ex castris educi et se subsequi iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fulcio","latin":"fulcio, fulcire, fulsi, fultus","headword":"fulcio","letter":"f","pos":"verb","posGroup":"verb","english":"prop up, support","forms":["fulcīre","fulcit","fultum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{fulcīre}} fulsisse fultum - sustinēre, atque erit oppositā iānuā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fulcire","latin":"(fulciō) fulcīre, -sisse, -tum","headword":"fulcīre","letter":"f","pos":"","posGroup":"other","english":"hold up, support","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fulgens","latin":"fulgens, fulgentis (gen.), fulgentior -or -us, fulgentissimus -a -um","headword":"fulgens","letter":"f","pos":"adjective","posGroup":"adjective","english":"flashing, gleaming/glittering, resplendent; brilliant (white); bright, splendid","forms":["fulgēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum subitō māter Venus, in lūce pūrā per noctem {{fulgēns}}, fīliō sē videndam obtulit eīque suāsit ut celeriter domum ad suōs fugeret, simulque prōmīsit sē ipsam fīlium tūtum ad līmen domūs patriae ductūram esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fulgeo","latin":"fulgeō, -ēre, fulsī","headword":"fulgeō","letter":"f","pos":"verb","posGroup":"verb","english":"flash, shine","forms":["fulgēbant","fulgēbat","fulgent","fulgentem","fulgentis","fulget","fulsēre","fulsisse","fulsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Salomōn templum immēnsī operis Hierosolymae aedificāvit: omnia aurō, argentō, gemmīsque in eō {{fulgēbant}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fulgere","latin":"(fulgeō) fulgēre, -sisse","headword":"fulgēre","letter":"f","pos":"","posGroup":"other","english":"flash, gleam","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fulgor","latin":"fulgor, -ōris (m.)","headword":"fulgor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"flash; flash of lightning; radiance, brightness","forms":["fulgor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde est hominum generī prosperus et salūtāris ille {{fulgor}} quī dīcitur \"Iovis\"; tum rutilus horribilisque terrīs quem \"Martium\" dīcitis.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fulgur","latin":"fulgur, fulguris","headword":"fulgur","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"(n.) flash of lightning","forms":["fulgur","fulgura","fulgure","fulguribus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nōnne tempestātem ac {{fulgura}} verēminī?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"fulmen","latin":"fulmen, -inis (n.)","headword":"fulmen","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"flash of lightning; lightning, thunderbolt; thunderbolt","forms":["fulmen","fulmina","fulmine","fulminibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eō in proeliō Deus manirestum sē praebuit adiūtōrem; nam inter pugnandum appāruērunt quīnque virī equīs et virtūte servābant, in hostēs vērō tēla et {{fulmina}} iaciēbant: unde illī, oculīs et mente turbafī, ad viginfī quīnque mīlia interfecfī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fulmineus","latin":"fulmineus, fulminea, fulmineum","headword":"fulmineus","letter":"f","pos":"adjective","posGroup":"adjective","english":"of lightning; destructive","forms":["fulmineō","fulmineum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fulmineō rabidōs cum rotat ōre canēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fultus","latin":"fultus, fulta, fultum","headword":"fultus","letter":"f","pos":"adjective","posGroup":"adjective","english":"propped up; supported","forms":["fulta","fultus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"mūnīre; (sera) {{fulta}} : bene clausa","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fulvus","latin":"fulvus, fulva, fulvum","headword":"fulvus","letter":"f","pos":"adjective","posGroup":"adjective","english":"tawny, reddish yellow; yellow","forms":["fulva","fulvum","fulvus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed neque {{fulvus}} aper mediā tam saevus in irà est,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fumo","latin":"fumo, fumare, fumavi, -","headword":"fumo","letter":"f","pos":"verb","posGroup":"verb","english":"smoke, steam, fume, reek","forms":["fūmantia","fūmantis","fumare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante tertiam vigiliam est animadversum {{fumare}} aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fumus","latin":"fūmus, -ī","headword":"fūmus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"smoke","forms":["fūmōs","fūmum","fūmus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Item Symmachus caelum intuētur et “Nōn nūbēs” inquit, “sed {{fūmus}} est.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"funale","latin":"funale, funalis","headword":"funale","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"torch of wax or tallow soaked rope; chandelier","forms":["fūnālia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"incēnsī, et noctem flammīs {{fūnālia}} vincunt.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"funda","latin":"funda, -ae","headword":"funda","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"sling","forms":["fundā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fundamentum","latin":"fundāmentum, -ī","headword":"fundāmentum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"foundation","forms":["fundāmenta","fundāmentīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque IUdaeī, dūce Zorobabele, Hierosolymam regressī sunt, et prlma novī templī:{{fundāmenta}} iēcērunt; sed aedificātiō diū intermissa est, quia illam impediēbant vīcīnae gentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fundere","latin":"(fundō) fundere, fūdisse, fūsum","headword":"fundere","letter":"f","pos":"verb","posGroup":"verb","english":"pour; to pour","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"funditor","latin":"funditor, -ōris (m.)","headword":"funditor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"slinger","forms":["funditōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is missus cum praesidiō equitum atque {{funditōrum}} Balearum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"funditus","latin":"funditus","headword":"funditus","letter":"f","pos":"adverb","posGroup":"adverb","english":"utterly (from the root); from the bottom, utterly","forms":["funditus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At subitō Centaurī, plūrima merī pōcula {{funditus}} exhauserant, multō vīnō ēbriī, mēnsās humī prōiecērunt et tōtum convīvium turbāre coepērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"fundo","latin":"fundō, -ere, fūdī, fūsum","headword":"fundō","letter":"f","pos":"verb","posGroup":"verb","english":"pour, shed; to found, establish","forms":["fūderat","fūdērunt","fūdisse","fūdisset","fūdistī","fūdit","fundam","fundantem","fundat","fundātīs","fundebant","fundēbat","fundere","funderet","fundēs","fundet","fundī","fundis","fundit","fundō","fundunt","fūsa","fūsās","fūsī","fūsīs","fūsō","fūsōs","fūsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest {{fundebant}}, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"fundus","latin":"fundus, -ī","headword":"fundus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"bottom; bottom, depths","forms":["fundum","fundus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iuppiter igitur, postquam hoc animadvertit, dē altō Olympō dēscendit atque catēnīs ferreīs īnsulam ad maris {{fundum}} vīnxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"funereus","latin":"funereus, funerea, funereum","headword":"funereus","letter":"f","pos":"adjective","posGroup":"adjective","english":"funereal; deadly; fatal","forms":["fūnereā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fūnereā; super exuviās ēnsemque relictum","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"funestus","latin":"fūnestus, -a, -um","headword":"fūnestus","letter":"f","pos":"adjective","posGroup":"adjective","english":"deadly, grievous, sinister","forms":["fūnēstam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nē {{fūnēstam}} hanc pugnam mōnstrandō cōnsulis fēceris!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fungi","latin":"(fungor) fungī, fūnctum (+ abl.)","headword":"fungī","letter":"f","pos":"","posGroup":"other","english":"discharge, complete","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"fungor","latin":"fungor, fungi, functus sum","headword":"fungor","letter":"f","pos":"verb","posGroup":"verb","english":"perform, execute, discharge (duty); be engaged in (w/ABL of function)","forms":["fūncta","fūnctūrum","Fūnctus","fungantur","fungebatur","fungētur","fungitur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere {{fungebatur}}; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"funis","latin":"fūnis, -is (m.)","headword":"fūnis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"rope; rope, cable","forms":["fūne","fūnem","fūnēs","fūnibus","fūnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Incolae perterritī, quamquam {{fūnibus}} et hastīs ūtēbantur, taurum hūc et illūc currentem capere nōn poterant; nec ē tālī perīculō līberātī sunt, dōnec Herculēs, quī in Crētam vēnerat, illam saevissimam bēstiam tandem cēpit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"funus","latin":"fūnus, -eris (n.)","headword":"fūnus","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"funeral, death; funeral; (pl. fūnera) funerals","forms":["fūnera","fūnere","fūneribus","fūneris","fūnus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi {{fūnus}} fēcērunt cum magnō plānctū, et sepeliērunt corpus in spēluncā ubi iacēbant Abrahāmus et Isaacus; reversīque sunt in Aegyptum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fur","latin":"fūr, fūris","headword":"fūr","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"(m.) thief","forms":["fūr","fūrem","fūrēs","furi","fūribus","Fūrium","fūrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam mē pudet tē, {{fūrem}} nēquissimum, amāvisse!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"furca","latin":"furca, -ae","headword":"furca","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"fork, forked frame","forms":["furcā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Matiēnius accūsātus est apud tribūnōs plēbis 'quod exercitum ex Hispāniā dēseruisset' damnātusque sub furcā diū virgīs caesus est et sēstertiō nummō vēniit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"furcifer","latin":"furcifer, furciferi","headword":"furcifer","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"yoke-bearer; rascal, scoundrel, rogue; gallows-bird; jailbird","forms":["furcifer"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nōnne ego possum, {{furcifer}}, tē perdere?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"fureo","latin":"fureō, -ere, furuī","headword":"fureō","letter":"f","pos":"verb","posGroup":"verb","english":"to rage, be furious","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"furere","latin":"(furō) furere, furuisse","headword":"furere","letter":"f","pos":"","posGroup":"other","english":"be mad, rage, rave","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"furia","latin":"furia, furiae","headword":"furia","letter":"f","pos":"noun (f.)","posGroup":"noun","english":"frenzy, fury; rage (pl.); mad craving; Furies, avenging spirits","forms":["Furiae","furiās","furiīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ō Sōl, quī omnia terrārum opera flammīs tuīs illūstrās, tūque Iūnō, testis hārum cūrārum, et {{Furiae}} ultrīcēs, audīte precēs nostrās: Sī necesse est virum impium terram Italiae attingere et sīc fāta poscunt — at bellō et hostium armīs ex fīnibus suīs pulsus auxilium implōret videatque indigna suōrum fūnera!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"furibundus","latin":"furibundus, furibunda, furibundum","headword":"furibundus","letter":"f","pos":"adjective","posGroup":"adjective","english":"raging, mad, furious; inspired","forms":["furibunda","furibundus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At illa diū vultum tellūre morātum\nērēxit tandemque deō {{furibunda}} receptō\n\"magna petis,\" dīxit, \"vir factīs māxime, cuius\ndextera per ferrum, pietās spectāta per ignēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"furio","latin":"furio, furiare, furiavi, furiatus","headword":"furio","letter":"f","pos":"verb","posGroup":"verb","english":"madden, enrage","forms":["Furiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae cum profectae essent adversum Gallōs duce Furiō, quīdam ex Gallīs ūnum ex Rōmānīs, 'quī esset optimus', prōvocāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"furiosus","latin":"furiosus, furiosa, furiosum","headword":"furiosus","letter":"f","pos":"adjective","posGroup":"adjective","english":"furious, mad, frantic, wild","forms":["furiōsa","furiōsē","furiōsum","furiōsus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Parcior in nōbīs nec tam {{furiōsa}} libīdō est:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"furo","latin":"furo, furere, -, -","headword":"furo","letter":"f","pos":"verb","posGroup":"verb","english":"rave, rage; be mad/furious; be wild","forms":["furēns","furēntem","furentēs","furentī","furentibus","furit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Herculī amīcitiam Thēseus fert postquam ille {{furēns}} coniugem et līberōs necāverat et posteā in sānitātem mentis revēnerat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"furor","latin":"furor, -ōris (m.)","headword":"furor","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"madness; madness, insanity","forms":["fūrātī","furere","furor","furōre","furorem","furōrēs","furōrī","furōris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Adiuvat rem proclinatam Convictolitavis plebemque ad {{furorem}} impellit, ut facinore admisso ad sanitatem reverti pudeat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"furtim","latin":"furtim","headword":"furtim","letter":"f","pos":"adverb","posGroup":"adverb","english":"stealthily, secretly; imperceptibly","forms":["fūrtim"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Blanditiīs animum {{fūrtim}} dēprēndere nunc sit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"furtivus","latin":"furtivus, furtiva, furtivum","headword":"furtivus","letter":"f","pos":"adjective","posGroup":"adjective","english":"stolen; secret, furtive","forms":["fūrtīva","fūrtīvam","fūrtīvōs","fūrtīvum","fūrtīvus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"275 Utque virō {{fūrtīva}} vēnus, sīc grāta puellae;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"furtum","latin":"fūrtum, -ī","headword":"fūrtum","letter":"f","pos":"noun (n.)","posGroup":"noun","english":"theft","forms":["fūrta","fūrtī","fūrtīs","fūrtō","fūrtum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, {{fūrtum}}, homicīdium; ūnō verbō, sē contāminābant omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"fusco","latin":"fusco, fuscare, fuscavi, fuscatus","headword":"fusco","letter":"f","pos":"verb","posGroup":"verb","english":"darken, blacken, make dark; (INTRANS) become dark","forms":["fuscā","fuscentur","fuscet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Mundītīé placeant, {{fuscentur}} corpora Campō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"fuscus","latin":"fuscus, fusca, fuscum","headword":"fuscus","letter":"f","pos":"adjective","posGroup":"adjective","english":"dark, swarthy, dusky; husky; hoarse","forms":["Fusce","Fuscus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Integer vītae scelerisque pūrus / nōn eget Maurīs iaculīs neque arcū / nec venēnātīs gravidā sagittīs, / {{Fusce}}, pharetrā,","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"fustis","latin":"fustis, fustis","headword":"fustis","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"staff club; stick","forms":["fuste","fustem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Cum ergô Trimalchiô iūs inter lîtigantës dîceret, neuter sententiam tulit dëcementīs, sed alterîus amphoram {{fuste}} percussit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"fusus","latin":"fusus, fusi","headword":"fusus","letter":"f","pos":"noun (m.)","posGroup":"noun","english":"spindle; (e.g., of the Fates)","forms":["fūsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ecce cruor, quī {{fūsus}} humō signāverat herbās,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"futurus","latin":"futūrus, -a, -um","headword":"futūrus","letter":"f","pos":"adjective","posGroup":"adjective","english":"future; future, about to be","forms":["futūra","futūrae","futūram","futūrārum","futūrās","futūrī","futūrīs","futūrō","futūrōrum","futūrōs","futurum","futūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ex his Eporedorix cognito Litavicci consilio media fere nocte rem ad Caesarem defert; orat ne patiatur civitatem pravis adulescentium consiliis ab amicitia populi Romani deficere; quod {{futurum}} provideat, si se tot hominum milia cum hostibus coniunxerint, quorum salutem neque propinqui neglegere neque civitas levi momento aestimare posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gabalus","latin":"Gabalus, Gabali","headword":"Gabalus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Gabali, tribe of Gaul","forms":["Gabalos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Progressus in Nitiobriges et {{Gabalos}} ab utrisque obsides accipit et magna coacta manu in provinciam Narbonem versus eruptionem facere contendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gabinius","latin":"Gabinius, Gabini","headword":"Gabinius","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Gabinus; (Roman gens name)","forms":["Gabīnī","Gabīniō","Gabīnium","Gabīnius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi cum — īnscia multitūdine quid agerētur — proelia parva inter Rōmam Gabiōsque fierent, quibus plērumque Gabīna rēs superior esset, tum universī Gabīnī Sex.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gaetulus","latin":"Gaetulus, Gaetula, Gaetulum","headword":"Gaetulus","letter":"g","pos":"adjective","posGroup":"adjective","english":"Gaetulian; of the Gaetuli (North African people)","forms":["Gaetūlae","Gaetūlī","Gaetūlōrum","Gaetūlōs","Gaetūlus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōnne tibi in mentem venit quī hostēs nōs cingant: Gaetūlī Numidaeque, gentēs invictae, et frāter tuus Pygmaliōn, quī Tyrō bellum minātur?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gaius","latin":"Gaius, Gai","headword":"Gaius","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Gaius (Roman praenomen); (abb. C.)","forms":["Gāī","Gāiī","Gāiō","Gāium","Gāius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cornēlia bona et proba fēmina Rōmāna fuit, quae duōs habuit fīliōs, quōrum alterī Tiberius, alterī {{Gāius}} nōmina erant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"galatea","latin":"Galatea, Galateae","headword":"Galatea","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Galatia, region of Asia Minor","forms":["Galatēa","Galatēam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ibi {{Galatēa}}, nymphārum omnium pulcherrima, quae ūna cum sorōribus Siciliae undās incolēbat, ab Ācide pāstōre amābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"galatee","latin":"Galatee, Galatees","headword":"Galatee","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Galatea; (sea nymph loved by Polyphemus; also statue of Pygmalion)","forms":["Galatēae"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Nōn ante requiēscam quam mea uxor fuerīs, Galatēa.” Hīs verbīs {{Galatēae}} persuadēre cōnābātur nē sē timēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"galba","latin":"Galba, Galbae","headword":"Galba","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Galba (Servinus Supicius Galba, Emperor, 69 AD, year of the 4 Emperors)","forms":["Galbā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sulpiciō Galbā C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"galea","latin":"galea, -ae","headword":"galea","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"helmet","forms":["galeā","galeae","galeam","galeās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Saūl ipse sua iuvenī arma voluit accommodāre: {{galeam}} capitī eius imposuit, lōrīcā pectus circumtēxit, latus gladiō accīnxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"galeatus","latin":"galeatus, galeata, galeatum","headword":"galeatus","letter":"g","pos":"adjective","posGroup":"adjective","english":"helmeted","forms":["galeātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vîcit scîlicet, et Îphigenîam, ﬁliam suam, Achillî dedit uxô- rem. 0b eam rem Âiäx însänit et statim argūmentum Haec ut dîxit Trimalchiô, clämôrem Homēristae sustulērunt, intcrque familiam discurrentem vitulus in lance ducënâriä ēlixus allātus est, et quidem {{galeātus}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"galilaea","latin":"Galilaea, Galilaeae","headword":"Galilaea","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Galilee","forms":["Galilaeae","Galilaeam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Postquam Hērōdēs mortuus est, angelō admonente, Iōseph accēpit puerum et mātrem eius et venit in {{Galilaeam}} et habitāvit in cīvitāte, quae vocātur Nazareth.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"galilaeus","latin":"Galilaeus, Galilaea, Galilaeum","headword":"Galilaeus","letter":"g","pos":"adjective","posGroup":"adjective","english":"Galilean","forms":["Galilaeum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Coepērunt IUdaeī accūsāre Iēsum dīcentēs:\"Rūne invenīmus subvertentem gentem nostram, et dīcentem sē rēgem esse.\"Pīlātus, cum eum interrogāsset et cognōvisset eum {{Galilaeum}} esse, mīsit ad Hērōdem, quī sprēvit Iēsum, induit veste albā et remīsit ad Pīlātum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gallia","latin":"Gallia, -ae","headword":"Gallia","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Gaul (modern France)","forms":["Gallia","Galliae","Galliam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quieta {{Gallia}}, Caesar, ut constituerat, in Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gallicinium","latin":"gallicinium, gallicinii","headword":"gallicinium","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"cock-crow; daybreak, dawn; last watch of the night","forms":["gallicinia","galliciniō"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Apoculāmus nôs circā {{gallicinia}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"gallicus","latin":"Gallicus, Gallica, Gallicum","headword":"Gallicus","letter":"g","pos":"adjective","posGroup":"adjective","english":"Gallic, of Gaul, of the Gauls","forms":["Gallica","Gallicam","Gallici","Gallico"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Muri autem omnes {{Gallici}} hac fere forma sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gallina","latin":"gallina, gallinae","headword":"gallina","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"hen","forms":["gallīna","gallīnam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Affer olīvās albās et cāseum!” [Ad hospitēs:] “Cēnāte!” [Post gustātiōnem appōnuntur varia fercula, ut {{gallīna}}, lepus, aper.] [Iūlius, ad ministrum:] “Praecīde aprum et gallīnam et lepōrem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"gallus","latin":"gallus, -ī","headword":"gallus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"cock, rooster; cockerel, rooster","forms":["Galli","Gallis","gallō","Gallorum","Gallos","gallum","gallus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus {{Galli}}, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"garrio","latin":"garrio, garrire, garrivi, garritus","headword":"garrio","letter":"g","pos":"verb","posGroup":"verb","english":"chatter/prattle/jabber; talk rapidly; talk/write nonsense; (birds/instruments)","forms":["garrīret"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Ō tē, Bōlāne, cerebrī fēlīcem!” aiēbam tacitus, cum quidlibet ille {{garrīret}}, vīcōs, urbem laudāret.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"garrulus","latin":"garrulus, garrula, garrulum","headword":"garrulus","letter":"g","pos":"adjective","posGroup":"adjective","english":"talkative, loquacious; chattering, garrulous; blabbing; that betrays secrets","forms":["garrulus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{garrulus}} in mediā Tantalus āret aquā!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gaudeo","latin":"gaudeo, gaudere, gavisus sum","headword":"gaudeo","letter":"g","pos":"verb","posGroup":"verb","english":"be glad, rejoice","forms":["gaudē","Gaudeāmus","gaudēbant","gaudēbat","gaudēbis","gaudēbit","Gaudēbō","gaudendum","gaudēns","gaudent","gaudentem","gaudeō","gaudēre","gaudērem","gaudērent","gaudēret","gaudēs","gaudet","gaudēte","gavisī","gāvīsus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mēdus, quī mīlitem vīvere {{gaudet}}, ex parvō rīvō aquam arcessit et mīlitī dat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"gaudere","latin":"gaudēre","headword":"gaudēre","letter":"g","pos":"verb","posGroup":"verb","english":"to rejoice","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"gaudet","latin":"gaudet, gaudēre","headword":"gaudet","letter":"g","pos":"verb","posGroup":"verb","english":"be glad, be pleased; rejoices, is glad","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"gaudium","latin":"gaudium, -ī","headword":"gaudium","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"joy","forms":["gaudia","gaudiīs","gaudiō","gaudium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ōsculātus est eum, coepēruntque ambō prae gaudiō lacrimās fundere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gausapa","latin":"gausapa, gausapae","headword":"gausapa","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"cloth of woolen frieze (coarse wool cloth w/nap); cloak of this material","forms":["gausapā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Gausapa}} sī sūmit, gausapā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gausapum","latin":"gausapum, gausapi","headword":"gausapum","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"cloth of woolen frieze (coarse wool cloth w/nap); cloak of this material","forms":["gausapum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{gausapum}} -ī 7: — pallium 6ē lānā factā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gaza","latin":"gaza, -ae","headword":"gaza","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"treasure","forms":["gāza"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Aliārum deinde secundārum rērum velut prōventus secūtus: cīvitātēs omnēs Macedoniae sē dēdidērunt, {{gāza}} rēgia in potestātem vēnit, rēx ipse — trādentibus prope ipsīs dīs — in templō Samothrācum cum līberīs est captus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gelidus","latin":"gelidus, gelida, gelidum","headword":"gelidus","letter":"g","pos":"adjective","posGroup":"adjective","english":"ice cold, icy","forms":["gelidam","gelidās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Mollīrī membra vidērēs: ossa et caeruleī crīnēs digitīque et crura et pedēs liquēscunt; post haec umerī et tergum et pectus in {{gelidās}} undās abeunt; dēnique prō sanguine vīvō subit aqua clāra; nihil restat quod tangere possēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gemebundus","latin":"gemebundus, gemebunda, gemebundum","headword":"gemebundus","letter":"g","pos":"adjective","posGroup":"adjective","english":"groaning, sighing","forms":["gemebundus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille quidem tōtam {{gemebundus}} obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gemellus","latin":"gemellus, gemelli","headword":"gemellus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"twin","forms":["gemellōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vēnit ad exposītōs (mīrum!) lupa fēta {{gemellōs}} — quis crēdat puerīs nōn nocuisse feram?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gemere","latin":"(gemō) gemere, -isse, -itum","headword":"gemere","letter":"g","pos":"","posGroup":"other","english":"groan (for)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"geminare","latin":"(geminō) gemināre","headword":"gemināre","letter":"g","pos":"","posGroup":"other","english":"double","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gemini","latin":"geminī","headword":"geminī","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"twins","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"gemino","latin":"gemino, geminare, geminavi, geminatus","headword":"gemino","letter":"g","pos":"verb","posGroup":"verb","english":"double; repeat; double the force of; pair (with)","forms":["gemināta","geminātīs","geminō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"mōbilis in geminō cui pede pinna fuit;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"geminus","latin":"geminus, -a, -um","headword":"geminus","letter":"g","pos":"adjective","posGroup":"adjective","english":"twin","forms":["geminā","geminam","geminās","geminē","geminī","geminīs","geminos","geminum","geminus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cornelius: \" ... et decimo post mense filios {{geminos}} peperit, quorum alter fuit Hercules.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gemitus","latin":"gemitus, -ūs","headword":"gemitus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"groaning; groan, sigh; groan, lament","forms":["gemitū","gemitum","gemitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iacobus, ut audīvit Beniamīnum arcessī ā praefectō Aegyptī, cum gemitū questus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gemma","latin":"gemma, -ae","headword":"gemma","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"precious stone, jewel; gem, jewel; jewel, gem","forms":["gemmā","gemmae","gemmās","gemmīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus dīcit ‘mātrem suam et {{gemmīs}} et margarītīs et ānulīs pulchrīs ōrnārī nec aliam fēminam tam fōrmōsam esse...’”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"gemmatus","latin":"gemmātus, -a, -um","headword":"gemmātus","letter":"g","pos":"adjective","posGroup":"adjective","english":"set with a jewel; jewelled, set with a gem","forms":["gemmātam","gemmātum","gemmātus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Albīnus Dōrippae ānulum aureum {{gemmātum}} ostendit et “Hic {i}pos{/i} ānulus” inquit “centum sēstertiīs cōnstat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"gemo","latin":"gemō, -ere, gemuī","headword":"gemō","letter":"g","pos":"verb","posGroup":"verb","english":"groan, lament","forms":["gemēns","gementem","gementēs","gemit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"neque {{gementem}} neque plōrantem nostrum quisquam audīvimus,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"gena","latin":"gena, -ae","headword":"gena","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"cheek","forms":["genae","genās","genīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Alcyonē autem, cum prīmum hoc nōvit, acerbō dolōre affectā, lacrimās per {{genās}} effūdit tōtōque vultū palluit et, postquam ter frūstrā prae tristitiāā cōnāta est loquī, tum dēmum “Heu, mē miseram!” inquit, “Nōn iam mē amās, ō Cēyx?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"gener","latin":"gener, -erī (m.)","headword":"gener","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"son-in-law","forms":["gener","generi","generis","generōs","generum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multitudine sagittarum atque omnis {{generis}} telorum multos vulneratos; ad haec sustinenda magno usui fuisse tormenta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"generare","latin":"(generō) generāre","headword":"generāre","letter":"g","pos":"","posGroup":"other","english":"beget, produce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"genero","latin":"genero, generare, generavi, generatus","headword":"genero","letter":"g","pos":"verb","posGroup":"verb","english":"beget, father, produce, procreate; spring/descend from (PASSIVE)","forms":["generat","generātī","generātus","generō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīs aliīsque increpandō iuvenem īnstīgat, nec conquiēscere ipsa potest, sī — cum Tanaquil, peregrīna mulier, duo continua rēgna virō ac deinceps generō dedisset — ipsa, rēgiō sanguine orta, nec dare nec adimere rēgnum posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"generosus","latin":"generōsus, -a, -um","headword":"generōsus","letter":"g","pos":"adjective","posGroup":"adjective","english":"noble","forms":["Generōsam","generōsō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Brūtus adest, tandemque animō sua nōmina fallit, fīxaque sēmi-animī corpore tēla rapit, stīllantemque tenēns generōsō sanguine cultrum ēdidit impavidōs ōre minante sonōs: 'Per tibi ego hunc iūrō fortem castumque cruōrem perque tuōs Mānēs, quī mihi nūmen erunt, Tarquinium profugā poenās cum stirpe datūrum!' Illa iacēns ad verba oculōs sine lūmine mōvit vīsaque concussā dicta probāre comā.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"genetivus","latin":"genetīvus, -ī (cāsus)","headword":"genetīvus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"genitive","forms":["genetīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: 'Nōminātīvus, {{genetīvus}}, dativus, accūsātīvus, vocātīvus, ablātīvus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"genetrix","latin":"genetrīx, -īcis ( f.)","headword":"genetrīx","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"mother; mother, ancestress","forms":["genetricī","genetricis","genetrīx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At sī quōs tamen ultima nostrī verba movent ōris (Prīamī vōs fīlia rēgis, nōn captīva rogat), genetricī corpus inemptum reddite, nēve aurō redimat iūs triste sepulcrī, sed lacrimīs! tunc, cum poterat, redimēbat et aurō.” Dīxerat, at populus lacrimās, quās illa tenēbat, nōn tenet; ipse etiam flēns invītusque sacerdōs virginis ferrum in pectore condit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"genialis","latin":"geniālis, -e","headword":"geniālis","letter":"g","pos":"adjective","posGroup":"adjective","english":"marriage-, conjugal","forms":["geniālis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dūcuntur raptae, {{geniālis}} praeda, puellae, et potuit multās ipse decēre timor.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"genitor","latin":"genitor, -ōris (m.)","headword":"genitor","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"father; father, parent; father, begetter","forms":["genitor","genitōre","genitōrem","genitōris"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnegat hoc {{genitor}} dīvīsque īrāscitur ipsīs atque in rēge tamen pater est; ego mīte parentis ingenium verbīs ad pūblica commoda vertī: difficilem tenuī sub inīquō iūdice causam.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"genitus","latin":"genitus, genita, genitum","headword":"genitus","letter":"g","pos":"adjective","posGroup":"adjective","english":"begotten; engendered","forms":["genitī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita genitī itaque ēducātī Rōmulus et Remus — ea frātribus geminīs nōmina fuērunt — cum prīmum adolēvērunt, nōn in stabulīs apud pecus sēgnēs manēbant, sed per saltūs vēnābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"genius","latin":"genius, geni","headword":"genius","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"genius","forms":["geni","genium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"u; 35mēn dîvidätur ā paleā) Eôdem diê: Mithridätês servus in crucem āctus est, quia Gāī nostrî{{geni}}ä male dīxerat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"gens","latin":"gēns, gentis","headword":"gēns","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"(f.) tribe, nation; people, nation; tribe, people, clan; race, people, clan","forms":["gēns","gente","gentem","gentēs","gentī","gentibus","gentis","gentium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnēs {{gentēs}} propāgātae sunt ā fīliīs Noēmī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gentilis","latin":"gentilis, gentilis","headword":"gentilis","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"gentiles (pl.); non-Jews (to Jew); heathens (to Christian), not of one's faith","forms":["gentīlēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulierēs exterae, quās adamāvit, eum iam senem ad rītūs {{gentīlēs}} pertraxērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"genu","latin":"genū, genūs","headword":"genū","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"(n.) knee","forms":["genibus","genū","genua"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Et ipse āvulsus ē s t ab iīs quantum ē s t ī āctus lapidī s: et posifīs {{genibus}}, ōrābat dīcēns:\"Pater, sī vīs, trānsfer calicem istum ā mē; vērumtamen nōn mea voluntās, sed tua fīat.\"Et ecce sūdor eius, sīcut guttae sanguinis, dēcurrit in terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"genus","latin":"genus, generis","headword":"genus","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"(n.) kind, sort; gender, kind; race, kind, family","forms":["genera","genere","generibus","genus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Singulari militum nostrorum virtuti consilia cuiusque modi Gallorum occurrebant, ut est summae {{genus}} sollertiae atque ad omnia imitanda et efficienda quae ab quoque traduntur aptissimum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"geographicus","latin":"geographicus, -a, -um","headword":"geographicus","letter":"g","pos":"adjective","posGroup":"adjective","english":"geographical","forms":["geographica"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hic est charta {{geographica}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gerere","latin":"gerere","headword":"gerere","letter":"g","pos":"verb","posGroup":"verb","english":"to bear, carry, wear, accomplish, do","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"gergovia","latin":"Gergovia, Gergoviae","headword":"Gergovia","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Gergovia; (town of the Arverni in central Gaul)","forms":["Gergovia","Gergoviam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido {{Gergovia}}; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gerit","latin":"gerit, gerere","headword":"gerit","letter":"g","pos":"","posGroup":"other","english":"carry, wear, carry on, do","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"germana","latin":"germāna, -ae","headword":"germāna","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"sister","forms":["germāna","germānae","germānam","Germanis","germānum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ab hoc concilio Remi, Lingones, Treveri afuerunt; illi, quod amicitiam Romanorum sequebantur; Treveri, quod aberant longius et ab {{Germanis}} premebantur, quae fuit causa quare toto abessent bello et neutris auxilia mitterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"germania","latin":"Germania, Germaniae","headword":"Germania","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Germany","forms":["Germānia","Germāniae","Germaniam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Caesar, quod hostes equitatu superiores esse intellegebat et interclusis omnibus itineribus nulla re ex provincia atque Italia sublevari poterat, trans Rhenum in {{Germaniam}} mittit ad eas civitates quas superioribus annis pacaverat equitesque ab his arcessit et levis armaturae pedites, qui inter eos proeliari consuerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"germanus","latin":"Germanus, Germani","headword":"Germanus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Germans (pl.)","forms":["germāne","germānī","Germānōrum","Germanos","germānus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Caesar ex castris equitatum educi iubet, proelium equestre committit; laborantibus iam suis {{Germanos}} equites circiter CCCC summittit, quos ab initio habere secum instituerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gero","latin":"gerō, -ere, gessī, gestum","headword":"gerō","letter":"g","pos":"verb","posGroup":"verb","english":"do, make, experience, achieve","forms":["geram","geratur","gere","gerēbant","gerēbat","gerebatur","gerenda","gerendae","gerendam","gerendās","gerendi","gerendīs","gerendō","gerendum","gerēns","gerente","gerentēs","gerere","gererent","gererentur","gereret","gereretur","geri","gerimus","geris","gerit","Gerite","geritis","geritur","gerō","gerunt","geruntur","gesserat","gesserit","gesserunt","gessī","gessimus","gessisse","gessistī","gessit","gesta","gestae","gestam","gestārum","gestās","gestīs","gestū","gesturos","gestūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam quae Cenabi oriente sole {{gesta}} essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gerundium","latin":"gerundium, -ī","headword":"gerundium","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"gerund","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"gerundivum","latin":"gerundīvum","headword":"gerundīvum","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"gerundive","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"gestare","latin":"(gestō) gestāre","headword":"gestāre","letter":"g","pos":"","posGroup":"other","english":"carry","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gesticulor","latin":"gesticulor, gesticulari, gesticulatus sum","headword":"gesticulor","letter":"g","pos":"verb","posGroup":"verb","english":"gesticulate; make mimic or pantomimic movements","forms":["gesticulātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Secūtus est Âiäx, strictôque gladiô, tamquam însänîret, vitulum concîdit, ac modo versā modō supînä {{gesticulātus}} mucrône frusta m collegnt mnranubusque parūtus est. pônere (Diāna cervam subië- cit Ïphigenîae sacriﬁcandae) argūmentum -î n: ā.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"gesto","latin":"gesto, gestare, gestavi, gestatus","headword":"gesto","letter":"g","pos":"verb","posGroup":"verb","english":"bear, carry; wear","forms":["gestābam","gestāmus","gestantem","gestāre","gestāret","gestat","gestavī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alter quoque nārrāvit somnium suum Iōsēphō: {{gestābam}} in capite tria canistra in quibus erant cibī quōs pistōrēs solent cōnficere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gestum","latin":"gestum, gesti","headword":"gestum","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"what has been carried out, a business; deeds (pl.), exploits","forms":["gestum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Docet longe alia ratione esse bellum gerendum atque antea {{gestum}} sit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gestus","latin":"gestus, -ūs","headword":"gestus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"gesture","forms":["gestus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"755 Carpe cibōs digitīs — est quiddam {{gestus}} edendī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"giganteus","latin":"Giganteus, Gigantea, Giganteum","headword":"Giganteus","letter":"g","pos":"adjective","posGroup":"adjective","english":"of/connected with the Giants; like that of the Giants","forms":["Gigantēō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Voluī inclāmāre, sed hostī\nprōdere mē timuī; vīdī, cum monte revulsum\nimmāne scopulum mediās permīsit in undās;\nvīdī iterum velutī tormentī vīribus ācta\nvāsta Gigantēō iaculantem saxa lacertō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gigas","latin":"gigās, -antis","headword":"gigās","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"giant","forms":["gigantis","gigās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Vāsta īnsula Sicilia in corpore {{gigantis}} Typhōēī iacet premitque eum quī saepe pugnat et surgere temptat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gignere","latin":"(gignō) gignere, genuisse,","headword":"gignere","letter":"g","pos":"","posGroup":"other","english":"beget, create, bear genitum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gigno","latin":"gigno, gignere, genui, genitus","headword":"gigno","letter":"g","pos":"verb","posGroup":"verb","english":"give birth to, bring forth, bear; beget; be born (PASSIVE)","forms":["genuerat","genuēre","genuerit","genuērunt","genuī","genuisse","genuissem","genuit","gignere","gignerētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iacobus habuit duodecim fīliōs, inter quōs erat Iōsēphus: hunc pater amābat prae cēterīs, quia senex {{genuerat}} eum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"git","latin":"git, undeclined","headword":"git","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"black cumin (Nigella sativa); Roman coriander (L+S); melanthion/melanspermon","forms":["git"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"vītis agit gemmàs pigraque fü{{git}} hiems,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"glabrio","latin":"glabrio, glabrionis","headword":"glabrio","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"hairless-person; ringworm; L:Glabrio (Roman surname)","forms":["Glabriō","Glabriōnī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Acīlius Glabriō dē Antiochō, quem Graecia expulerat, et dē Aetōlīs triumphāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"glacialis","latin":"glacialis, glacialis, glaciale","headword":"glacialis","letter":"g","pos":"adjective","posGroup":"adjective","english":"icy, frozen","forms":["glaciālis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"'Er y Vērque novum stābat cīnctum flōrente corōnā, stābat nūda Aestās et spīcea serta gerēbat, stābat et Autumnus calcātīs sordidus ūvīs et {{glaciālis}} Hiems cānōs hirsūta capillōs","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"glacies","latin":"glaciēs, -ēī","headword":"glaciēs","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"ice","forms":["glaciē","glaciem","glaciēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"siccī fīunt fontēs, {{glaciēs}} nivēsque molliuntur; omnia ignis cōnsūmit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"gladiator","latin":"gladiātor, -tōris","headword":"gladiātor","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"(m.) gladiator; gladiator, swordsman","forms":["gladiatores","gladiātōrī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Modo in amphitheatro certamen magnificum spectavi: plus trecenti {{gladiatores}} certabant.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gladiatorius","latin":"gladiātōrius, -a, -um","headword":"gladiātōrius","letter":"g","pos":"adjective","posGroup":"adjective","english":"gladiatorial","forms":["gladiātōriae","gladiatorii","gladiatorium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Plerique gladiis et scutis armati erant, alii retia gerebant.\" Aemilia, quae certamen {{gladiatorium}} non spectavit, a Cornelio quaerit 'quomodo gladiatores retibus certent?'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gladius","latin":"gladius, -ī","headword":"gladius","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"sword","forms":["gladi","gladiī","gladiis","gladiō","gladiōrum","gladiōs","gladium","gladius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi aliquid ab eis iniri consili intellexissent, {{gladiis}} destrictis portas occupaverunt suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"glaeba","latin":"glaeba, glaebae","headword":"glaeba","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"clod/lump of earth/turf; land, soil; hard soil; piece, lump, mass","forms":["glaebae","glaebas"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas {{glaebas}} in ignem e regione turris proiciebat; scorpione ab latere dextro traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"glans","latin":"glans, glandis","headword":"glans","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"mast/acorn/beechnut/chestnut; missile/bullet thrown/discharged from sling","forms":["glande","glandem","glandēs","glandibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nostri, ut superioribus diebus, ut cuique erat locus attributus, ad munitiones accedunt; fun: dis librilibus sudibusque, quas in opere disposuerant, ac {{glandibus}} Gallos proterrent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"glaucus","latin":"glaucus, glauca, glaucum","headword":"glaucus","letter":"g","pos":"adjective","posGroup":"adjective","english":"bluish gray","forms":["Glaucō","Glaucus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Piscātor quīdam, nōmine {{Glaucus}}, ōlim Anthēdonem, īnsulam Graecam, incolēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"globosus","latin":"globōsus, -a, -um","headword":"globōsus","letter":"g","pos":"adjective","posGroup":"adjective","english":"spherical, round","forms":["globōsae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Homines enim sunt hāc lēge generātī, quī tuērentur illum globum quem in hōc templō medium vidēs, quae \"terra\" dīcitur, iīsque animus datus est ex illīs sempiternīs ignibus quae \"sīdera\" et \"stellās\" vocātis, quae {{globōsae}} et rotundae, dīvīnīs animātae mentibus, circōs suōs orbēsque cōnficiunt celeritāte mīrābilī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"globus","latin":"globus, -ī","headword":"globus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"globe, sphere, ball, band","forms":["globī","globīs","globō","globum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam sciunt longē aliud esse virginēs rapere, aliud pugnāre cum virīs!\" In eum haec glōriantem cum globō ferōcissimōrum iuvenum Rōmulus impetum facit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"glomerat","latin":"glomerat, glomerant","headword":"glomerat","letter":"g","pos":"verb","posGroup":"verb","english":"winds into a ball","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"glomero","latin":"glomero, glomerare, glomeravi, glomeratus","headword":"glomero","letter":"g","pos":"verb","posGroup":"verb","english":"collect, amass, assemble; form into a ball","forms":["glomerābat","glomerandum","glomerant","glomerantur","glomerat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Saepe nymphae silvae spectant dum puella perīta lānam {{glomerat}} et pictūrās in textilī format.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gloria","latin":"glōria, -ae","headword":"glōria","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"glory","forms":["glōria","gloriae","gloriam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postremo in acie praestare interfici quam non veterem belli {{gloriam}} libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gloriari","latin":"(glōriōr) glōriārī","headword":"glōriārī","letter":"g","pos":"","posGroup":"other","english":"boast","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"glorior","latin":"glorior, gloriari, gloriatus sum","headword":"glorior","letter":"g","pos":"verb","posGroup":"verb","english":"boast, brag; glory, pride oneself","forms":["glōriantem","glōriārī","glōriātus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":": dē actīs glōriārī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gloriosus","latin":"glōriōsus, -a, -um","headword":"glōriōsus","letter":"g","pos":"adjective","posGroup":"adjective","english":"full of glory","forms":["glōriōsā","glōriōsam","glōriōsī","glōriōsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ultimus autem rēx, nōmine Tarquinius, quī nōn Rōmānus sed Tuscus erat, {{glōriōsus}}, sevērissimus et tam nēquam fuit ut ‘Superbus’ appellārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"gnavus","latin":"gnāvus, -a, -um","headword":"gnāvus","letter":"g","pos":"","posGroup":"other","english":"diligent, active","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"grabatus","latin":"grabatus, grabati","headword":"grabatus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"cot, camp bed, pallet; low couch or bed; (usu.) mean/wretched bed/couch","forms":["grabātō","grabātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat ibi in grabātō vir quīdam magnā dētentus Īnfirmitāte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gracilis","latin":"gracilis, -e","headword":"gracilis","letter":"g","pos":"adjective","posGroup":"adjective","english":"slender; slender, slim","forms":["gracilia","gracilior","gracilis","gracilius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At Minerva eam inventam et in vītam reductam herbae cuiusdam sūcō aspersit; quō factum est ut tōtum eius corpus parvum fieret; in utrōque latere octo {{gracilia}} crūra appāruerunt; ex ventre verō iam ab illō tempore stāmen ēmittit: arānea enim facta, ut anteā, etiam nunc tēlās tēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"gracilitas","latin":"gracilitās, -ātis ( f.)","headword":"gracilitās","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"slenderness, thinness","forms":["grācilitās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat eō tempore in nōbīs summa {{grācilitās}} et īnfirmitās corporis, prōcērum et tenue collum; quī habitus et quae fīgūra nōn procul abesse putātur ā vītae perīculō, sī accēdit labor et laterum magna contentiō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gradi","latin":"(gradior) gradī, gressum","headword":"gradī","letter":"g","pos":"","posGroup":"other","english":"walk, proceed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gradior","latin":"gradior, gradi, gressus sum","headword":"gradior","letter":"g","pos":"verb","posGroup":"verb","english":"walk, step, take steps, go, advance","forms":["gradiebātur","gradientēs","gradientibus","graditur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tunc Deus Moȳsī: “Prōtende” inquit “dextram tuam in mare, et dīvidē aquās, ut illae Hebraeīs {{gradientibus}} iter siccum praebeant.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gradus","latin":"gradus, -ūs","headword":"gradus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"(m.) step; degree, step; step, pace","forms":["gradibus","gradū","gradum","gradūs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Servus ad ōstium versus {{gradum}} facit, cum Diodōrus “Manē!” inquit, “Nōlī abīre!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"graece","latin":"Graece","headword":"Graece","letter":"g","pos":"adverb","posGroup":"adverb","english":"in Greek","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"graecia","latin":"Graecia, -ae","headword":"Graecia","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"Greece","forms":["Graeciā","Graeciae","Graeciam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In Graeciā sunt multae īnsulae.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"graeculus","latin":"Graeculus, Graeculi","headword":"Graeculus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"little Greek; contemptible Greek","forms":["Graeculi"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Et sānē nôlentem mē negôtium meum agere exhortā- vit mathēmaticus, quî vēnerat forte in colôniam nostram, {{Graeculi}}ô, Seräpa nômine, cônsiliätor deôrum!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"graecus","latin":"Graecus, -a, -um","headword":"Graecus","letter":"g","pos":"adjective","posGroup":"adjective","english":"Greek","forms":["Graeca","Graecae","Graecam","Graecārum","Graecās","Graecē","Graecī","Graecīs","Graecō","Graecōrum","Graecōs","Graecum","Graecus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus: “{i}Y {/i} nōn est littera Latīna, sed littera {{Graeca}}. {i}Syria {/i} est vocābulum Graecum.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"graius","latin":"Graius, -a, -um","headword":"Graius","letter":"g","pos":"adjective","posGroup":"adjective","english":"Greek","forms":["Grāia","Graiās","Graiī","Graiōrum","Graium","Graius"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fēcerat haec [fāma] nōtum {{Graiās}} cum mīlite fortī adventāre ratēs neque inexspectātus in armīs hostis adest; prohibent aditūs lītusque tuentur Trōes, et magnō quid Achāica dextera posset sanguine sēnsērunt, et iam Phrygia rubēbant lītora, iam lētō prōlēs Neptūnia, Cygnus, mīlle virōs dederat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gramen","latin":"gramen, graminis","headword":"gramen","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"grass, turf; herb; plant","forms":["grāmine"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Turpe pecus mutilum, turpis sine {{grāmine}} campus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"grammatica","latin":"grammatica, -ae","headword":"grammatica","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"grammar","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"grandaevus","latin":"grandaevus, -a, -um","headword":"grandaevus","letter":"g","pos":"adjective","posGroup":"adjective","english":"aged","forms":["grandaevus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"et quā vectus Abās, et quā {{grandaevus}} Alētēs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"grandis","latin":"grandis, -e","headword":"grandis","letter":"g","pos":"adjective","posGroup":"adjective","english":"big, large","forms":["grande","grandem","grandibus","grandīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hae revinciuntur introrsus et multo aggere vestiuntur; ea autem quae diximus intervalla {{grandibus}} in fronte saxis effarciuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"grando","latin":"grandō, -inis ( f.)","headword":"grandō","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"hail","forms":["grandine","grandō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc in eōs cecidit grandō lapidea, et multōs interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"granifer","latin":"granifer, granifera, graniferum","headword":"granifer","letter":"g","pos":"adjective","posGroup":"adjective","english":"grain-carrying","forms":["grāniferō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"grāniferō solitum cum vehit óre cibum,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"granum","latin":"granum, grani","headword":"granum","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"grain; seed","forms":["grāna"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nam Proserpina, dum errat in hortīs quī sub terrā sunt, malum Pūnicum ex arbore carpserat; ex quō mālō septem {{grāna}} sūmpta ēderat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"grassor","latin":"grassor, grassari, grassatus sum","headword":"grassor","letter":"g","pos":"verb","posGroup":"verb","english":"march on, advance; roam in search of victims, prowl; proceed; run riot","forms":["grassentur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sunt quī mendáci speciē {{grassentur}} amōris","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"grate","latin":"grate, gratius, gratissime","headword":"grate","letter":"g","pos":"adverb","posGroup":"adverb","english":"with pleasure/delight; agreeably, pleasantly; with gratitude, thankfully","forms":["grātē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tīā in-grātē servit : quibus indul-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"grates","latin":"grātēs (nom. and acc. f. pl.)","headword":"grātēs","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"thanks","forms":["grātēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vōs autem dēbitās Deō {{grātēs}} rependite.” Haec locūtus, ab illōrum cōnspectū ablātus est, nec ultrā compāruit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gratia","latin":"grātia, -ae","headword":"grātia","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"favor, gratitude, thanks (pl.); favour, gratitude","forms":["gratia","grātiae","gratiam","Grātiārum","grātiās","grātiīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius indicio vocati, huic habendam {{gratiam}}, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gratiam habere","latin":"grātiam habēre","headword":"grātiam habēre","letter":"g","pos":"phrase","posGroup":"other","english":"to feel gratitude","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"gratiam referre","latin":"grātiam referre","headword":"grātiam referre","letter":"g","pos":"phrase","posGroup":"other","english":"to return a favour","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"gratias agere","latin":"grātiās agere","headword":"grātiās agere","letter":"g","pos":"phrase","posGroup":"other","english":"to give thanks","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"gratificari","latin":"(grātificor) grātificārī","headword":"grātificārī","letter":"g","pos":"","posGroup":"other","english":"oblige, gratify (+ dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gratificor","latin":"gratificor, gratificari, gratificatus sum","headword":"gratificor","letter":"g","pos":"verb","posGroup":"verb","english":"oblige, gratify, humor, show kindness to; bestow, make a present of","forms":["grātificārī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Litterās igitur nūntiōsque ad prīncipēs factiōnis Barcīnae praemittit 'ut praeparārent suōrum animōs, nē quid pars altera grātificārī populō Rōmānō posset.' Itaque ea quoque vāna lēgātiō fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gratiosus","latin":"gratiosus, gratiosa, gratiosum","headword":"gratiosus","letter":"g","pos":"adjective","posGroup":"adjective","english":"agreeable, enjoying favor; kind","forms":["grātiōsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat tūne aulicus quīdam apud rēgem {{grātiōsus}}, nōmine Amān, quī, favōre rēgiō superbiēns, adorarī sē volēbat, quod facere renuēns Mardochaeus, grave in sē odium Amānīs accenderat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gratis","latin":"gratis","headword":"gratis","letter":"g","pos":"adverb","posGroup":"adverb","english":"gratis, without payment, for nothing; freely; for no reward but thanks","forms":["grātīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"né dederit {{grātīs}} quae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"grator","latin":"grator, gratari, gratatus sum","headword":"grator","letter":"g","pos":"verb","posGroup":"verb","english":"congratulate (w/DAT); rejoice with","forms":["grātāre"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"'invēnī, germāna, viam ({{grātāre}} sorōrī)","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"gratuito","latin":"gratuito","headword":"gratuito","letter":"g","pos":"adverb","posGroup":"adverb","english":"gratis, without pay, for naught, gratuitously; for no special reason; wantonly","forms":["grātuītō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī causa peccandī in praesēns minus suppetēbat, nihilō minus īnsontēs sīcuti sontēs circumvenīre, iugulāre; scīlicet nē per ōtium torpēscerent manūs aut animus, grātuītō potius malus atque crūdēlis erat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"gratuitus","latin":"grātuītus, -a, -um","headword":"grātuītus","letter":"g","pos":"adjective","posGroup":"adjective","english":"gratuitous, futile","forms":["grātuīta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec nocte nec interdiū virum conquiēscere patī, nē {{grātuīta}} praeterita parricīdia essent: \"nōn sibi dēfuisse marītum cum quō tacita servīret; dēfuisse virum quī sē rēgnō dignum esse putāret, quī meminisset sē esse Prīscī Tarquiniī fīlium, quī habēre quam spērāre rēgnum māllet!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"gratulari","latin":"(grātulor) grātulārī","headword":"grātulārī","letter":"g","pos":"","posGroup":"other","english":"congratulate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"gratulatio","latin":"gratulatio, gratulationis","headword":"gratulatio","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"congratulation; rejoicing","forms":["gratulatio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Concurrunt his auxiliis visis; fit {{gratulatio}} inter eos atque omnium animi ad laetitiam excitantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gratulor","latin":"gratulor, gratulari, gratulatus sum","headword":"gratulor","letter":"g","pos":"verb","posGroup":"verb","english":"congratulate; rejoice, be glad; thank, give/render thanks","forms":["Grātulāmur","grātulantēs","grātulārentur","grātulātur","grātulor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hebraeī, {{grātulantēs}}, victōrem dēdūcunt ad urbem: ipsae mulierēs, domibus ēgressae, cum tympanīs laudēs eius canēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gratus","latin":"grātus, -a, -um","headword":"grātus","letter":"g","pos":"adjective","posGroup":"adjective","english":"grateful, pleasing; pleasing, welcome; pleasing (to) (+ dat.)","forms":["grāta","grātae","grātī","grātior","grātissima","grātissimum","grātius","grātōs","grātum","grātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnēs autem eius līberī et nepōtēs domesticam virtūtem sunt imitātī, Deōque pariter et hominibus grātī et acceptī fuērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gravida","latin":"gravida","headword":"gravida","letter":"g","pos":"adjective","posGroup":"adjective","english":"pregnant","forms":["gravidā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōlī mē ab uxōre gravidā rapere!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gravidus","latin":"gravidus, -a , -um","headword":"gravidus","letter":"g","pos":"adjective","posGroup":"adjective","english":"heavy, weighty, pregnant","forms":["gravidam","gravidum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"mīlitibus {{gravidum}} laeta recēpit equum.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gravis","latin":"gravis, -e","headword":"gravis","letter":"g","pos":"adjective","posGroup":"adjective","english":"heavy, severe, grave; heavy, serious; heavy; heavy, weighty, grave","forms":["grave","gravem","gravēs","gravī","gravia","gravibus","gravior","graviōra","graviōrēs","gravis","gravissima","gravissimam","gravissimās","gravissimē","gravissimī","gravissimō","gravissimum","gravius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum {{gravissima}} caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"gravitas","latin":"gravitās, -ātis ( f.)","headword":"gravitās","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"weight, gravity, dignity","forms":["gravitāte","gravitātem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sed leve pondus erat nec quod cognōscere possent Sōlis equī, solitaque iugum {{gravitāte}} carēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"graviter","latin":"graviter","headword":"graviter","letter":"g","pos":"adverb","posGroup":"adverb","english":"heavily, deeply","forms":["graviter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hēlī vērō habēbat fīliōs perditīs mōribus, adeō ut populum ā colendō Deō abdūcerent, nec satis {{graviter}} eōs umquam reprehendit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gravo","latin":"gravō, -āre, -āvī, -ātum","headword":"gravō","letter":"g","pos":"verb","posGroup":"verb","english":"load, burden, weigh down","forms":["gravat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nam mē {{gravat}} invītam nova vīs, aliudque cupīdō, mēns aliud suādet: videō meliōra probōque, dēteriōra sequor.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gregarius","latin":"gregarius, gregaria, gregarium","headword":"gregarius","letter":"g","pos":"adjective","posGroup":"adjective","english":"of/belonging to rank and file; [miles gregarius => common soldier]","forms":["gregāriīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ab eīs centuriōnēs, omnēs lēctōs et ēvocātōs, praetereā ex {{gregāriīs}} mīlitibus optimum quemque armātum in prīmam aciem subdūcit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"gremium","latin":"gremium, -ī","headword":"gremium","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"lap; lap, bosom","forms":["gremi","gremio","gremium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"in {{gremio}} sedit protinus illa meo!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gressus","latin":"gressus, gressus","headword":"gressus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"going; step; the feet (pl.)","forms":["gressū","gressum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ēgressus -üs ry «€ ē-grēdī -{{gressum}};","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"grex","latin":"grex, gregis","headword":"grex","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"(m.) herd; flock, herd","forms":["grege","gregem","gregēs","gregis","grex"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iacobus iter persecūtus pervenit in Mesopotamiam; vīdit trēs pecorum {{gregēs}} propter puteum cubantēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"grus","latin":"grus, gruis","headword":"grus","letter":"g","pos":"noun","posGroup":"noun","english":"crane; large bird; siege engine","forms":["grūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{grūs}} -uis f, avis (cui color cànus est,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gryneus","latin":"Gryneus, Grynea, Gryneum","headword":"Gryneus","letter":"g","pos":"adjective","posGroup":"adjective","english":"Grynean; of Grynium (site of Apollo oracle in Aeolis)","forms":["Grȳnēus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sed nunc Ītaliam magnam {{Grȳnēus}} Apollō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"gubernator","latin":"gubernātor, gubernātōris","headword":"gubernātor","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"(m.) steersman; helmsman, pilot; steersman, captain; helmsman, captain; steersman, pilot","forms":["gubernātor","gubernātōre","gubernātōrem","gubernātōrī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum igitur in portū {{gubernātōrem}}, quī nāvī praeerat, ‘nāvem profectūram’ nūntiantem audīret, tum dēmum uxōrem valēre iussit et, osculō datō, nānāvem parātam cōnscendit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"guberno","latin":"gubernō, gubernāre","headword":"gubernō","letter":"g","pos":"verb","posGroup":"verb","english":"steer, govern","forms":["gubernārī","gubernat","gubernō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In puppī sedet gubernātor, quī nāvem {{gubernat}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"gula","latin":"gula, gulae","headword":"gula","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"throat, neck, gullet, maw; palate, appetite","forms":["gūla","gulam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"té{{gūla}}-aefitéctum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gurges","latin":"gurges, -itis (m.)","headword":"gurges","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"whirlpool, flood; whirlpool, abyss","forms":["gurgite","gurgitibus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"quó minimé crédis {{gurgite}} piscis erit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"gustare","latin":"(gustō) gustāre, -āvisse, -ātum","headword":"gustāre","letter":"g","pos":"verb","posGroup":"verb","english":"taste; to taste","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"gusto","latin":"gusto, gustare, gustavi, gustatus","headword":"gusto","letter":"g","pos":"verb","posGroup":"verb","english":"taste, sip; have some experience of; enjoy","forms":["gustābis","gustābit","gustābunt","gustāns","gustantēs","gustantibus","gustāre","gustat","gustāverimus","gustāverō","gustāvērunt","gustāvit","gustēmus","gustētur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sī ego eam sūmpserō atque gustāverō, quid mihi, quid corporī meō fīet?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"gustus","latin":"gustus, gustus","headword":"gustus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"tasting, appetite; draught of water","forms":["gustū","gustum","gustus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ingēns fluvius irrigābat hortum: erant ibi omnēs arborēs iūcundae aspectū, et frūctūs gustū suāvēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"gutta","latin":"gutta, guttae","headword":"gutta","letter":"g","pos":"noun (f.)","posGroup":"noun","english":"drop, spot, speck","forms":["gutta","guttae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et ipse āvulsus ē s t ab iīs quantum ē s t ī āctus lapidī s: et posifīs genibus, ōrābat dīcēns:\"Pater, sī vīs, trānsfer calicem istum ā mē; vērumtamen nōn mea voluntās, sed tua fīat.\"Et ecce sūdor eius, sīcut {{guttae}} sanguinis, dēcurrit in terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"guttur","latin":"guttur, -uris","headword":"guttur","letter":"g","pos":"noun (n.)","posGroup":"noun","english":"throat","forms":["guttur","gutture"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tum in {{guttur}} ātrae ovis gladium cōnicit et fossam sanguine perfundit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"gyasas","latin":"Gyasas, Gyae","headword":"Gyasas","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"Gyas; (Trojan companion of Aeneas)","forms":["Gyān"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fāta Lycī, fortemque {{Gyān}}, fortemque Cloanthum.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"gypsatus","latin":"gypsatus, gypsata, gypsatum","headword":"gypsatus","letter":"g","pos":"adjective","posGroup":"adjective","english":"plastered; covered with gypsum; (slave) chalked for sale","forms":["gypsātās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Ad dexteram meam pônäs statuam Fortūnātae meae columbam tenentem, et catellam cingulô alligâtam dūcat; et cicarônem meum; et amphorās côpiôsäs {{gypsātās}}, nē eam puerum plôrantem.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"gyrus","latin":"gyrus, gyri","headword":"gyrus","letter":"g","pos":"noun (m.)","posGroup":"noun","english":"circle, ring; circuit; course; circular course for training/racing horses","forms":["gȳrōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"armaque et in {{gȳrōs}} īre coāctus equus;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ha","latin":"ha","headword":"ha","letter":"h","pos":"interjection","posGroup":"interjection","english":"Ah!; (distress/regret/pity, appeal/entreaty, surprise/joy, objection/contempt)","forms":["ha"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ēpīrī; āles Chāonis (: columba) {{ha}}-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"habena","latin":"habena, habenae","headword":"habena","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"thong, strap; whip; halter; reins (pl.); direction, management, government","forms":["habēnae","habēnās","habēnīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ibi cōnscenderant equōs duo ex septem Niobēs fīliīs; prīmus vēro, cum equum currentem eō cōnsiliō verteret, ut ad urbem redīret, “Heu mihi!” subitō exclāmāvit, sagittā in mediō pectore percussus: {{habēnīs}} ex monentibus manibus dēlāpsīs, iuvenis ā dextrō latere ad terram cecidit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"habeo","latin":"habeō, -ēre","headword":"habeō","letter":"h","pos":"verb","posGroup":"verb","english":"have, hold; passive: be held, be regarded","forms":["habē","habeam","habeāmus","habeant","habeantur","habeās","habeat","habeātis","habēbam","habēbāmus","habebant","habēbantur","habēbās","habebat","habēbātis","habēbātur","habēberis","habēbimus","habēbis","habēbit","habēbō","habēbunt","habēmus","habenda","habendam","habendās","habendī","habendos","habendum","habēns","habent","habente","habentem","habentēs","habentibus","habentur","habeō","habere","habērem","haberemus","habērent","habērentur","habērēs","haberet","habērētis","habērētur","habērī","habēs","habet","habēte","habetis","habētō","habētōte","habētur","habita","habitās","habitīs","habitōs","habitū","habitum","habitūrōs","habiturum","habuerant","habuerat","habuēre","habuerim","habuerint","habuerunt","habuī","habuimus","habuisse","habuissent","habuisset","habuistis","habuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia {{habere}} instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"haberi","latin":"(habeor) habērī, habitum","headword":"habērī","letter":"h","pos":"","posGroup":"other","english":"be held, be considered","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"habet","latin":"habet","headword":"habet","letter":"h","pos":"verb","posGroup":"verb","english":"have, hold, consider; has, holds","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"habilis","latin":"habilis, -e","headword":"habilis","letter":"h","pos":"adjective","posGroup":"adjective","english":"fit, appropriate","forms":["habilem","habilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"dīc {{habilem}}\" quaecumque","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"habitabilis","latin":"habitābilis, -e (< habitāre Caps. V, XLIII)","headword":"habitābilis","letter":"h","pos":"adjective","posGroup":"adjective","english":"habitable","forms":["habitābilēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Duō sunt {{habitābilēs}}, quōrum austrālis ille, in quō quī īnsistunt adversa vōbīs urgent vestīgia, nihil ad vestrum genus; hic autem alter subiectus aquilōnī quem incolitis, cerne quam tenuī vōs parte contingat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"habitans","latin":"habitans, habitantis","headword":"habitans","letter":"h","pos":"noun","posGroup":"noun","english":"inhabitant; dweller","forms":["habitantēs","habitantium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Callistō optima omnium fēminārum in Arcadiā {{habitantium}} fuit, Arcasque, eius fīlius, pulcherrimus omnium puerōrum esse vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"habitat","latin":"habitat","headword":"habitat","letter":"h","pos":"verb","posGroup":"verb","english":"lives, dwells","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"habitat/habitant","latin":"habitat/habitant","headword":"habitat/habitant","letter":"h","pos":"","posGroup":"other","english":"dwell, live","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"habito","latin":"habito, habitare, habitavi, habitatus","headword":"habito","letter":"h","pos":"verb","posGroup":"verb","english":"inhabit, dwell; live, stay","forms":["habitābāmus","habitābant","habitābat","habitābātis","habitāmus","habitandam","habitandum","habitant","habitantur","habitāre","habitāret","habitārī","habitat","habitātum","habitātur","habitāvērunt","habitāvisse","habitāvisset","habitāvit","habitent","habitō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Via Latīna est longa, sed Mēdus, quī viā Latīnā Tūsculō Rōmam ambulat, fessus nōn est, nam is ambulat ad Lȳdiam amīcam, quae Rōmae {{habitat}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"habitus","latin":"habitus, -ūs","headword":"habitus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"state, condition","forms":["habitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic, summo in Arvernis ortus loco et magnae {{habitus}} auctoritatis, 'nihil', inquit, 'de eorum sententia dicturus sum, qui turpissimam servitutem deditionis nomine appellant, neque hos habendos civium loco neque ad concilium adhibendos censeo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hac","latin":"hāc","headword":"hāc","letter":"h","pos":"adverb","posGroup":"adverb","english":"this way","forms":["hac"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Hac}} impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hactenus","latin":"hactenus","headword":"hactenus","letter":"h","pos":"adverb","posGroup":"adverb","english":"as far as this, to this place/point/time/extent, thus far, til now, hitherto","forms":["Hāctenus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Hāctenus}} ea, quae ad rēgnum Isrāēlīticum spectābant, breviter attigī, nunc revertor ad rēgēs Iūdae, ā quibus dīgressus sum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hadrianus","latin":"Hadrianus, Hadriani","headword":"Hadrianus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hadrian (P. Aelius Hadrianus, Emperor, 117-138 AD); Adriatic","forms":["Hadriānī","Hadriānum","Hadriānus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aelius {{Hadriānus}} templum praeclārum post basilicam Ulpiam aedificātum Dīvō Trāiānō dēdicāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hadrumetum","latin":"Hadrumetum, Hadrumeti","headword":"Hadrumetum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"Andrumetum/Hadrumetum (city of Africa propria, capital of province Byzacene)","forms":["Hadrūmētum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hannibal cum paucīs equitibus inter tumultum ēlāpsus {{Hadrūmētum}} perfūgit, omnia et ante aciem et in proeliō, priusquam excēderet pugnā, expertus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hadrumetus","latin":"Hadrumetus, Hadrumeti","headword":"Hadrumetus","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Andrumetum/Hadrumetum (city of Africa propria, capital of province Byzacene)","forms":["Hadrūmētī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hadrūmētī reliquōs ē fugā collēgit, novīs dīlēctibus paucīs diēbus multōs contrāxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"haedus","latin":"haedus, haedi","headword":"haedus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"kid, young goat; two stars in constellation Auriga (Charioteer), \"The Kid\"","forms":["haedī","haedōs","haedum","haedus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rebecca audierat Isaacum loquentem; vocāvit Iacobum, et: affertō, inquit, mihi duōs {{haedōs}} opīmōs; cōnficiam pulmentum, quō pater tuus valdē dēlectātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"haereo","latin":"haereo, haerere, haesi, haesus","headword":"haereo","letter":"h","pos":"verb","posGroup":"verb","english":"stick, adhere, cling to; hesitate; be in difficulties (sticky situation?)","forms":["haereant","haereat","haerēbat","haerēns","haerent","haerentem","haeret","haesit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Abrahamus respexit, et vīdit arietem {{haerentem}} cornibus inter veprēs, quem immolāvit locō fīliī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"haerere","latin":"(haereō) haerēre, -sisse, -sum","headword":"haerēre","letter":"h","pos":"","posGroup":"other","english":"stick, cling","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"haesitare","latin":"(haesitō) haesitāre","headword":"haesitāre","letter":"h","pos":"","posGroup":"other","english":"hesitate, be uncertain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"haesito","latin":"haesito, haesitare, haesitavi, haesitatus","headword":"haesito","letter":"h","pos":"verb","posGroup":"verb","english":"stick hesitate, be undecided; be stuck","forms":["haesitāvī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec mediocriter haesitāvī: sitne aliquod discrīmen aetātum, an quamlibet tenerī nihil ā rōbustiōribus differant?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"hahahae","latin":"hahahae","headword":"hahahae","letter":"h","pos":"interjection","posGroup":"interjection","english":"Ha ha!; (laughter, derision)","forms":["Hahahae"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Dēlia: “{{Hahahae}}!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"halo","latin":"halo, halare, halavi, halatus","headword":"halo","letter":"h","pos":"verb","posGroup":"verb","english":"emit (vapor, etc); be fragrant","forms":["hālant"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tūre calent ārae, sertīsque recentibus {{hālant}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"hama","latin":"hama, hamae","headword":"hama","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"bucket; water bucket; (esp. fireman's bucket)","forms":["hamis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis {{hamis}} infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hamus","latin":"hamus, hami","headword":"hamus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"hook; barb of an arrow; spike","forms":["hāmōs","hāmus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"aucupibus nōtī fruticēs; quī sustinet {{hāmōs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hannibal","latin":"Hannibal, Hannibalis","headword":"Hannibal","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hannibal; (Carthaginian general in 2nd Punic War)","forms":["Hannibal","Hannibale","Hannibalem","Hannibalī","Hannibalis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Bellum maximē omnium memorābile quae umquam gesta sunt scrīptūrus sum, quod {{Hannibale}} duce Carthāginiēnsēs cum populō Rōmānō gessērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hara","latin":"hara, -ae","headword":"hara","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"pig-sty","forms":["hara"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"cumque eadem passīs (tantum medicāmina possunt!)\nclaudor {{hara}}, sōlumque suīs caruisse figūrā\nvīdimus Eurylochum: sōlus data pōcula fūgit;\nquae nisi vītāsset, pecoris pars ūna manērem\nnunc quoque saetigerī, nec tantae clādis ab illō\ncertior ad Circēn ultor vēnisset Ulixēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"harena","latin":"harena, harenae","headword":"harena","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"sand, grains of sand; sandy land or desert; seashore; arena, place of contest","forms":["harēnā","harēnae","harēnīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Accipiunt ventōs ā tergō mīlle carīnae multaque perpessae Phrygiā potiuntur harēnā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hariolus","latin":"hariolus, harioli","headword":"hariolus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"soothsayer, prophet","forms":["Hariolōs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{Hariolōs}}, haruspicēs","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"harpago","latin":"harpago, harpagonis","headword":"harpago","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"hook; grappling iron","forms":["harpagonum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Uno die intermisso Galli atque hoc spatio magno cratium, scalarum, {{harpagonum}} numero effecto, media nocte silentio ex castris egressi ad campestres munitiones accedunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"harpyiae","latin":"Harpyiae, -ārum","headword":"Harpyiae","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"the Harpies, half woman, half bird","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"harum","latin":"harum, hari","headword":"harum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"plants of genus arum","forms":["hārum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Harum}} ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"harundo","latin":"harundo, harundinis","headword":"harundo","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"reed, cane, fishing rod, limed twigs for catching birds; arrow shaft; pipe","forms":["harundine","harundinēs","harundinibus","harundō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quārē abscondit eum tribus mēnsibus; sed cum nōn posset eum diūtius occultāre, sūmpsit fiscellam, quam līnīvit bitūmine ac pice; deinde posuit intus īnfantulum, et exposuit eum inter {{harundinēs}} rīpae flūminis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"haruspex","latin":"haruspex, haruspicis","headword":"haruspex","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"soothsayer, diviner; inspector of entrails of victims","forms":["haruspicēs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hariolōs, {{haruspicēs}}","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"hasdrubal","latin":"Hasdrubal, Hasdrubalis","headword":"Hasdrubal","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hasdrubal; (Carthaginian name, general brother of Hanninbal)","forms":["Hasdrubal","Hasdrubale","Hasdrubalem","Hasdrubalis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Medius {{Hasdrubal}} inter patrem ac fīlium octō fermē annōs imperium obtinuit — quia gener erat, factiōnis Barcīnae opibus in imperiō positus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hasta","latin":"hasta, -ae","headword":"hasta","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"lance; spear, lance; spear, javelin; spear","forms":["hastā","hastae","hastam","hastās","hastīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hastile","latin":"hastile, hastilis","headword":"hastile","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"spear shaft; spear; cane","forms":["hastīlia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"bīna manū lātō crispāns {{hastīlia}} ferrō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"haud","latin":"haud","headword":"haud","letter":"h","pos":"adverb","posGroup":"adverb","english":"not, scarcely; not at all","forms":["haud"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ōlim, dum ambulat, subitō parvum lacum {{haud}} procul ā viā vīdit, ad quem laetissima statim cucurrit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"haudquaquam","latin":"haudquāquam","headword":"haudquāquam","letter":"h","pos":"adverb","posGroup":"adverb","english":"by no means","forms":["haudquāquam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Carpetānī clāmōre sublātō, passim sine ūllīus imperiō in amnem ruunt, mediōque alveō {{haudquāquam}} parī certāmine concursum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"haurio","latin":"hauriō, haurīre","headword":"hauriō","letter":"h","pos":"verb","posGroup":"verb","english":"draw (water), bail; to drink, drain, swallow","forms":["hauriat","hauriēbantur","haurientem","haurīre","haurit","Haurīte","hauriunt","hausērunt","hausī","hausimus","hausit","hausta","haustam","haustī","haustōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ubi pervēnit in Mesopotamiam, cōnstitit cum camēlīs prope puteum aquae ad vesperum, quō tempore mulierēs solēbant convenīre ad {{haurientem}} aquam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"haurire","latin":"haurīre","headword":"haurīre","letter":"h","pos":"verb","posGroup":"verb","english":"to draw (water), bail out","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"haustus","latin":"haustus, haustus","headword":"haustus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"drink; draught; drawing (of water)","forms":["haustūs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ā tē dēcurrit ad meōs {{haustūs}} liquor!” Repulsus ille vēritātis vīribus: “Ante hōs sex mēnsēs” ait “maledīxistī mihi!” Respondit agnus: “Equidem nātus nōn eram!” “Pater hercle tuus” ille inquit “maledīxit mihi!” — atque ita correptum lacerat iniūstā nece!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"he","latin":"he, undeclined","headword":"he","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"he; (5th letter of Hebrew alphabet)","forms":["HE"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cūr Iūnōnem et Pallada nunc quoque {{HE}} Dua.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hebes","latin":"hebes (gen. hebetis)","headword":"hebes","letter":"h","pos":"adjective","posGroup":"adjective","english":"dull, blunt","forms":["hebēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn sum ita {{hebēs}} ut istud dīcam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"hebesco","latin":"hebesco, hebescere, -, -","headword":"hebesco","letter":"h","pos":"verb","posGroup":"verb","english":"grow blunt or feeble","forms":["hebēscere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At vērō nōs vīcēsimum iam diem patimur {{hebēscere}} aciem hōrum auctōritātis!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"hebraea","latin":"Hebraea, Hebraeae","headword":"Hebraea","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Hebrew/Jewish woman","forms":["Hebraea","Hebraeam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulier {{Hebraea}} peperit fīlium, quem, cum vidēret fōrmōsum, voluit servāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hebraeus","latin":"Hebraeus, Hebraei","headword":"Hebraeus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hebrew, Jew; the Hebrews (pl.)","forms":["Hebraeī","Hebraeīs","Hebraeōrum","Hebraeōs","hebraeus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat ibi puer {{hebraeus}}, quī nōbīs sapienter interpretātus est somnia; rēs enim interpretātiōnem comprobāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hecate","latin":"Hecatē, -ēs","headword":"Hecatē","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Hecate (goddess of magic)","forms":["Hecatae","Hecatē","Hecatēn","Hecatēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Medea nunc ad ārās antīquās {{Hecatēs}} īvit ut in silvā carmina sēcrēta et artēs magicās disceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hector","latin":"Hector, Hectoris","headword":"Hector","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hector; (chief Trojan hero)","forms":["Hector","Hectore","Hectorem","Hectoris"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tacente Quīntō, Syrā pergit: 'An cupis audīre tabulam dē Achille, duce Graecōrum, quī {{Hectorem}}, ducem Troiānum, interfēcit atque corpus eius mortuum post currum suum trāxit circum moenia urbis Trōiae?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"hecuba","latin":"Hecuba, Hecubae","headword":"Hecuba","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Hecuba; (queen of Troy, wife of Priam, mother of Hector and Paris)","forms":["Hecuba"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ultima cōnscendit classem — miserābile vīsū! — in mediīs {{Hecuba}} nātōrum inventa sepulcrīs: [eam] prensantem tumulōs atque ossibus ōscula dantem Graecōrum trāxēre manūs, tamen ūnius hausit inque sinū cinerēs sēcum tulit Hectoris haustōs; Hectoris in tumulō crīnem lacrimāsque relīquit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hedera","latin":"hedera, hederae","headword":"hedera","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"ivy","forms":["hederā","hederae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nunc {{hederae}} sine honōrē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"heia","latin":"heia","headword":"heia","letter":"h","pos":"interjection","posGroup":"interjection","english":"how now!, Ha, Good, see! (of joy); see!, Quick! (of urgency/astonishment)","forms":["hēia"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"IVPPITER: {{Hēia}} autem, 'inimīcōs'?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"helena","latin":"Helena, Helenae","headword":"Helena","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Helen; (of Troy/Sparta, wife of Menelaus, abducted by Paris)","forms":["Helena","Helenae","Helenam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Orontēs: 'Ille servus nōn pūniendus, sed potius laudandus fuit; namque ita Paridem servāvit — eum quī posteā {{Helenam}}, fēminam omnium pulcherrimam, ā marītō Menelāō abdūxit.' Paulā: 'Num tantam iniūriam laudandam esse cēnsēs?' Orontēs: 'Quod Venus suādet iniūria nōn est!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"helenusus","latin":"Helenusus, Heleni","headword":"Helenusus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Helenus; (Trojan prophet, son of Priam)","forms":["Helēnō","Helēnum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīc iam incrēdibilis fāma iīs allāta est: {{Helēnum}}, Priamī fīlium, rēgnō Ēpīrī potītum esse atque Andromachēn, viduam Hectoris, uxōrem dūxisse!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"heli","latin":"Heli","headword":"Heli","letter":"h","pos":"interjection","posGroup":"interjection","english":"My God; [~ ~ lemma sabacthani => My God, my God why hast thou forsaken me]","forms":["Hēlī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum Hēlī esset summus sacerdōs, nātus est Samūēl.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"helvetius","latin":"Helvetius, Helvetii","headword":"Helvetius","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Helvetii (pl.), tribe in Central Gaul (Switzerland); (Caesar's \"Gallic War\")","forms":["Helvētiōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is prīmus vīcit {{Helvētiōs}}, deinde vincendō per bella gravissima usque ad Ōceanum Britannicum prōcessit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hendecasyllabus","latin":"hendecasyllabus, -ī","headword":"hendecasyllabus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"“eleven-syllable verse”; hendecasyllable (eleven-syllable verse)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"herba","latin":"herba, -ae","headword":"herba","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"grass, herb; grass; herb, plant, grass","forms":["herbā","herbae","herbam","herbārum","herbās","herbīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faustīnus: “Ovēs nōn rosās, sed {{herbam}} edunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"herbosus","latin":"herbōsus, -a, -um","headword":"herbōsus","letter":"h","pos":"adjective","posGroup":"adjective","english":"grassy","forms":["herbōsā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ōlim vērō, quoniam āēr calidissimus erat, circā merīdiem cervus fessus suum corpus in herbōsā terrā posuit sub altae arboris umbrā, ut frīgus ibi caperet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hercle","latin":"hercle","headword":"hercle","letter":"h","pos":"interjection","posGroup":"interjection","english":"By Hercules!; assuredly, indeed","forms":["hercle"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vērum, utut es factūrus, hoc quidem {{hercle}} haud reticēbō tamen,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"hercule","latin":"hercule","headword":"hercule","letter":"h","pos":"interjection","posGroup":"interjection","english":"by Hercules! really!","forms":["hercule"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipse vērō poposcit ab {{Hercule}}, ut sineret sē Īre dormītum, atque discessit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hercules","latin":"Hercules, Herculis","headword":"Hercules","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hercules (Greek hero of great strength)","forms":["Herculem","herculēs","Herculī","Herculis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Incolae perterritī, quamquam fūnibus et hastīs ūtēbantur, taurum hūc et illūc currentem capere nōn poterant; nec ē tālī perīculō līberātī sunt, dōnec {{Herculēs}}, quī in Crētam vēnerat, illam saevissimam bēstiam tandem cēpit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"here","latin":"here","headword":"here","letter":"h","pos":"adverb","posGroup":"adverb","english":"yesterday","forms":["here"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"{b}[[Insert Colloquia_5.tif {{here}}, see orig {/b} {b}for size/placement]]{/b}","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hereditarius","latin":"hērēditārius, -a, -um","headword":"hērēditārius","letter":"h","pos":"adjective","posGroup":"adjective","english":"inherited, hereditary","forms":["hērēditāriō","hērēditārium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Habet fīliam ūnicam, quam tē oportet uxōrem dūcere: pete eam ā patre, nec dubitō quīn postulātiōnī tuae libenter annuat: Deus enim hās tibi dēstinat nūptiās, et omnēs Rāgūēlis facultātēs iūre hērēditāriō ad tē pervenient.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hereditas","latin":"hērēditās, -ātis ( f.)","headword":"hērēditās","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"inheritance","forms":["hērēditāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic autem, velut {{hērēditāte}} relictum, odium paternum ergā Rōmānōs sīc cōnservāvit ut prius animam dēpōneret quam id dēposuerit — quī quidem, cum patriā pulsus esset et aliēnārum opum indigeret, numquam dēstiterit animō bellāre cum Rōmānīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"heres","latin":"hērēs, -ēdis (m.)","headword":"hērēs","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"heir","forms":["hērēdem","hērēdēs","hērēdis","hērēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum esset extrēmā senectūte et īnfirmā valētūdine, Salomōnem {{hērēdem}} rēgnī cōnstituit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"heri","latin":"herī","headword":"herī","letter":"h","pos":"adverb","posGroup":"adverb","english":"yesterday","forms":["heri"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Heri}} ē flūctibus maris, quibus vīgintī diēs iactātus sum, effūgī; saeva tempestās in hōc lītus mē pepulit, ut adhūc, fortasse, etiam hīc mala paterer, sīcut iam aliīs in locīs passus sum; tū vērō adiuvā mē: tibi enim prīmae hīs in terrīs occurrī: cēterōrum hominum, quī hanc urbem et regiōnem incolunt, nēminem nōvī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hermes","latin":"Hermes, Hermae","headword":"Hermes","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hermes; (Greek god Hermes = Roman Mercury); herm (pillar with bust of Hermes)","forms":["Hermē"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nam Hermē- rôtīs pugnās et Petraitis in pôculîs habeô, omnia ponderôsa.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"herodes","latin":"Herodes, Herodis","headword":"Herodes","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Herod; (Greek name, used by ruling family of Judea)","forms":["Hērōdem","Hērōdēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Paulō post rēgnum Iildae invāsit {{Hērōdēs}} aliēnigena: hunc prīmum Iiidaēī habuērunt rēgem ex aliā gente ortum, eōque rēgnante nātus est Chrīstus, ufī praedīxerant prophētae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"herois","latin":"herois, heroidos/is","headword":"herois","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"heroine (mythical)","forms":["herōis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Māter laeta Iphigeniam mittit ut fīlia coniūnx {{herōis}} praeclārī Danaōrum fīat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"heros","latin":"hērōs, -ōis","headword":"hērōs","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"hero","forms":["hērōe","hērōem","hērōī","hērōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nunc vincēs!\" {{Herōs}} gaudet; gaudet sēcrētō virgō quoque.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"herus","latin":"herus, heri","headword":"herus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"master, lord; owner, proprietor","forms":["Hērō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fretum trànsnàbas ut illa (Hērō) ānī- transnabàs, animum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hesperia","latin":"Hesperia, Hesperiae","headword":"Hesperia","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Italy, the western land","forms":["Hesperiae","Hesperiam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Seu vōs {{Hesperiam}} magnam Sāturniaque arva\nsīve Erycīs fīnīs rēgemque optātis Acestēn,\n[vōs] auxiliō tūtōs dīmittam opibusque iuvābō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hesperus","latin":"Hesperus, Hesperi","headword":"Hesperus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"evening-star","forms":["Hesperus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Aurōra et {{Hesperus}} illam quaerentem vīdit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hesternus","latin":"hesternus, -a, -um","headword":"hesternus","letter":"h","pos":"adjective","posGroup":"adjective","english":"of yesterday","forms":["hesterna","hesternam","hesternō","hesternum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{hesternam}} crēdās — illa repexa modo est.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hetaeria","latin":"hetaeria, hetaeriae","headword":"hetaeria","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"society, guild, fraternity; brotherhood","forms":["hetaeriās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus perāctīs, mōrem sibi discēdendī fuisse rūrsusque coeundī ad capiendum cibum, prōmiscuum tamen et innoxium — quod ipsum facere dēsiisse post ēdictum meum, quō secundum mandāta tua {{hetaeriās}} esse vetueram.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"heu","latin":"heu","headword":"heu","letter":"h","pos":"interjection","posGroup":"interjection","english":"alas","forms":["heu"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum vērō illās puellās spectat, sīc sēcum loquitur: “{{Heu}}, mē miserum!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"heus","latin":"heus","headword":"heus","letter":"h","pos":"interjection","posGroup":"interjection","english":"hey!, ho!, ho there!, listen!","forms":["heus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum viam aspiciēns puerum sōlum ambulantem videt atque “Vidēsne” inquit “parvum puerum quī nec fulgura nec imbrem metuit?” {{heus}}!: audi! sub +","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hexameter","latin":"hexameter, hexametrī","headword":"hexameter","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"having six metrical feet; hexameter (six-foot verse)","forms":["hexametrīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Nōmina duodecim deōrum hīs Enniī versibus {{hexametrīs}} continentur: Iūnō, Vesta, Minerva, Cerēs, Diāna, Venus, Mars, Mercurius, Iovis, Neptūnus, Vulcānus, Apollō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hiberna","latin":"hīberna, -ōrum (n. pl.)","headword":"hīberna","letter":"h","pos":"","posGroup":"other","english":"winter quarters","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"hibernacula","latin":"hībernācula, -ōrum (n. pl.)","headword":"hībernācula","letter":"h","pos":"","posGroup":"other","english":"winter camp/quarters","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"hibernaculum","latin":"hibernaculum, hibernaculi","headword":"hibernaculum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"winter quarters","forms":["hībernāculīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Exercitū in {{hībernāculīs}} compositō, cum expedītīs cohortibus et parte equitātūs proficīscitur in loca sōla obsessum turrim rēgiam, quō Iugurtha praesidium imposuerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hibernare","latin":"(hībernō) hībernāre","headword":"hībernāre","letter":"h","pos":"","posGroup":"other","english":"spend the winter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"hiberno","latin":"hiberno, hibernare, hibernavi, hibernatus","headword":"hiberno","letter":"h","pos":"verb","posGroup":"verb","english":"spend the winter; be in winter quarters","forms":["Hībernābat","hībernent","hībernō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quīn etiam hībernō tempore classem ōrnās et per mediōs Aquilōnēs nāvigāre properās!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hibernum","latin":"hibernum, hiberni","headword":"hibernum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"winter camp (pl.); winter quarters","forms":["hībernum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dein, cum essent perpauca inter sē ūnō aut alterō spatiō collocūtī Scīpiōnīque eōrum adventus periūcundus et pergrātus fuisset, placitum est ut in apricō maximē prātulō locō, quod erat {{hībernum}} tempus annī, cōnsīderent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hibernus","latin":"hībernus, -a, -um","headword":"hībernus","letter":"h","pos":"adjective","posGroup":"adjective","english":"winter-, of winter","forms":["hiberna","hībernam","hībernī","hibernis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore ex {{hibernis}} egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hic","latin":"hīc","headword":"hīc","letter":"h","pos":"adverb; pronoun","posGroup":"adverb","english":"here; this; he, she, it; the latter","forms":["hae","haec","hanc","has","hi","hic","his","hoc","horum","hos","huic","huius","hunc","HVIC"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse {{hunc}} casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hic / haec / hoc","latin":"hīc / haec / hoc","headword":"hīc / haec / hoc","letter":"h","pos":"pronoun","posGroup":"pronoun","english":"this (one)","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"hic/haec/hoc","latin":"hīc/haec/hoc","headword":"hīc/haec/hoc","letter":"h","pos":"pronoun","posGroup":"pronoun","english":"this (one)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"hiemo","latin":"hiemo, hiemare, hiemavi, hiematus","headword":"hiemo","letter":"h","pos":"verb","posGroup":"verb","english":"winter, pass the winter, keep winter quarters; be wintry/frozen/stormy","forms":["hiemabant","hiemare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones {{hiemabant}}, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hiems","latin":"hiems, hiemis","headword":"hiems","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"(f.) winter","forms":["hieme","hiemem","hiemēs","hiemis","hiems"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem {{hiemis}} uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hierosolyma","latin":"Hierosolyma, Hierosolymae","headword":"Hierosolyma","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Jerusalem (Hebrew)","forms":["Hierosolymā","Hierosolymae","Hierosolymam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Id ubi cognōvit Dāvīd, excessit Hierosolymā, veritus nē, sī ibi remanēret, Absalōn, cum exercitū veniēns, urbem rēgiam obsidēret, eamque ferrō et igne vastāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hierosolymum","latin":"Hierosolymum, Hierosolymi","headword":"Hierosolymum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"Jerusalem (pl.) (Hebrew)","forms":["Hierosolymōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In templō Pācis servantur rēs sacrae quās Titus Iūdaeīs victīs adēmit, in iīs candēlābrum aureum et mēnsa aurāta quae in templō {{Hierosolymōrum}} stābat tubaeque argenteae quibus Iūdaeī convocābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hierus","latin":"hierus, hiera, hierum","headword":"hierus","letter":"h","pos":"adjective","posGroup":"adjective","english":"sacred/supernatural; [hiera botane => vervain, medicinal/sacred plant]","forms":["Hierō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eōdem tempore potentissimus rēx Siciliae Hierō Rōmam vēnit ad lūdōs spectandōs et ducenta mīlia modiōrum trīticī populō dōnum praebuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hilaris","latin":"hilaris, hilare, hilarior -or -us, hilarissimus -a -um","headword":"hilaris","letter":"h","pos":"adjective","posGroup":"adjective","english":"cheerful, lively, light-hearted","forms":["hilarem","hilarēs","hilarī","hilaria","hilaris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Assuerus ad convīvium cum Amāne venit, et cum hilarī esset animō, Ē sther ad illīus pedēs sē abiēcit supplex.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hilaritas","latin":"hilaritas, hilaritatis","headword":"hilaritas","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"cheerfulness, lightheartedness","forms":["hilaritās","hilaritāte"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Dēlectātus hāc Trimalchiô {{hilaritāte}} et ipse capäciôrem poposcit scyphum quaesîvitque ‘quômodo acceptus esset?’ “Omnia” inquit “habuimus praeter tē; oculî enim meî hîc erant.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"hilum","latin":"hilum, hili","headword":"hilum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"trifle; (with negative) not a whit, not in the least","forms":["hīla","hīlum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cēterum laudâtus Trimalchiô {{hīla}}- solium Iovis tenēre : fëlîcis- in argentô studiôsus zargentî s. nôn Cassandra, sed Mêdêa fî- Daedalus Päsiphaên in vaccam ligneam inclūsit (Päsiphaë Hermerôs -ôtis, Petraîtës -is, ëbriô proximus à paene êbrius horreum -î n à aediﬁcium ubi lae rūsticae (praediô) prae- rius bibit et iam ëbriô proximus “Nëmô”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"hinc","latin":"hinc","headword":"hinc","letter":"h","pos":"adverb","posGroup":"adverb","english":"from here; here, on this side, hence","forms":["hinc"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quīn {{hinc}} discēdis?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hinnio","latin":"hinnio, hinnire, hinnivi, hinnitus","headword":"hinnio","letter":"h","pos":"verb","posGroup":"verb","english":"neigh","forms":["hinnīre","hinnit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Equus Cornēliī, quī duōs virōs gravēs Tūsculum vehere nōn potest, īrātus {{hinnit}}: “Hihihī!” atque in viā cōnsistit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hio","latin":"hio, hiare, hiavi, hiatus","headword":"hio","letter":"h","pos":"verb","posGroup":"verb","english":"be wide open, gape; be greedy for; be open-mouthed (with astonishment, etc)","forms":["hiantia","hiāre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nec violae semper nec {{hiantia}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hippolyta","latin":"Hippolyta, -ae","headword":"Hippolyta","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Hippolyta, queen of the Amazons","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"hippolytus","latin":"Hippolytus, -ī","headword":"Hippolytus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Hippolytus, son of Theseus","forms":["Hippolytum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cum Athēnās redīret, Hippolytam rēgīnam eārum sēcum rettulit, quae maximē amāta fīlium {{Hippolytum}} peperit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hirnea","latin":"hirnea, hirneae","headword":"hirnea","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"jug; hernia/rupture; (esp. enlarged scrotum as result of scrotal hernia)","forms":["hirneā","hirneam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Cadus erat vīnī, inde implēvī {{hirneam}}...","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"hirsutus","latin":"hirsutus, hirsuta, hirsutum","headword":"hirsutus","letter":"h","pos":"adjective","posGroup":"adjective","english":"rough, shaggy, hairy, bristly, prickly; rude","forms":["hirsūta","hirsūtās","hirsūtus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"'Er y Vērque novum stābat cīnctum flōrente corōnā, stābat nūda Aestās et spīcea serta gerēbat, stābat et Autumnus calcātīs sordidus ūvīs et glaciālis Hiems cānōs {{hirsūta}} capillōs","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hirtus","latin":"hirtus, hirta, hirtum","headword":"hirtus","letter":"h","pos":"adjective","posGroup":"adjective","english":"hairy/shaggy, covered with hair/wool; thick growth (plants); rough/unpolished","forms":["hirtus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{hirtus}} -ā -um - hirsūtus, capillōs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hirundo","latin":"hirundo, hirundinis","headword":"hirundo","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"swallow; martin; small bird; flying fish","forms":["hirundinum","hirundō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Forte ex nīdō {{hirundinum}} stercora calida incidērunt in oculōs dormientīs, unde caecus factus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hisco","latin":"hisco, hiscare, -, -","headword":"hisco","letter":"h","pos":"verb","posGroup":"verb","english":"(begin to) open, gape; open the mouth to speak","forms":["hiscere"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Convocat Ātrīdēs sociōs terrōre paventīs: nec Tēlamōniadēs etiamnunc {{hiscere}} quicquam audet. ...","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hispania","latin":"Hispānia, -ae","headword":"Hispānia","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"Spain","forms":["Hispania","Hispāniae","Hispāniam","Hispāniās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Huc Caesar omnes obsides Galliae, frumentum, pecuniam publicam, suorum atque exercitus impedimentorum magnam partem contulerat; huc magnum numerum equorum huius belli causa in Italia atque {{Hispania}} coemptum miserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hispanus","latin":"Hispanus, Hispana, Hispanum","headword":"Hispanus","letter":"h","pos":"adjective","posGroup":"adjective","english":"Spanish, of Spain","forms":["Hispānī","Hispānīs","Hispānum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In Hispāniā et in Galliā nōn multī sunt mīlitēs Rōmānī, nam Hispānī et Gallī, quī eās prōvinciās incolunt, iam exercitibus nostrīs pārent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"historia","latin":"historia, -ae","headword":"historia","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"account, story, history","forms":["historiae","historiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec deinceps ab avītā religiōne umquam dēscīvērunt, quamvīs ea dē causā ā plūribus rēgibus vexatī sint, ac praesertim ab Antiochō rēge Syriae; quae pars {{historiae}} Iūdaicae nunc nārranda venit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"historicus","latin":"historicus, -ī","headword":"historicus","letter":"h","pos":"adjective","posGroup":"adjective","english":"historian","forms":["historicō","historicus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed prō Rōmānīs tōta Italia cōnsēnsit, trāditumque est ā Fabiō historicō, quī eī bellō interfuit, octingenta mīlia hominum parāta ad id bellum fuisse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hoc modo","latin":"hōc modō","headword":"hōc modō","letter":"h","pos":"idiom","posGroup":"other","english":"in this manner, thus","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"hodie","latin":"hodiē","headword":"hodiē","letter":"h","pos":"adverb","posGroup":"adverb","english":"today","forms":["hodiē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa Mēdum aspicit, tum ad Lȳdiam sē vertēns “Et tū” inquit “es fēmina proba atque vēra amīca, quae nōn relinquis amīcam tuam. — Sed quid hodiē māne ad mē venīs?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hodiernus","latin":"hodiernus, -a, -um","headword":"hodiernus","letter":"h","pos":"adjective","posGroup":"adjective","english":"today’s, of today","forms":["hodiernā","hodiernō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"Quirītēs!\" inquit, \"Rōmulus, parēns urbis huius, prīmā hodiernā lūce dē caelō repente dēlāpsus mihi obvius fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"holus","latin":"holus, holeris","headword":"holus","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"(n.) vegetable","forms":["holera","holus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum Philēmōn {{holera}} ex hortō allāta in culīnā parāvit et coxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"homicida","latin":"homicida, homicidae","headword":"homicida","letter":"h","pos":"noun","posGroup":"noun","english":"murderer, homicide; killer of men (applied to epic heroes)","forms":["homicīda"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"S ē d quia ea omnia metus mortis extorquēbat, nōn vērā paenitentiā, dīvīnam misericordiam nōn flexit rēx impius et {{homicīda}}, et, morbō in hōrās ingravēscente, miserē interiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"homicidium","latin":"homicidium, homicidi(i)","headword":"homicidium","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"homicide, murder","forms":["homicīdium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, {{homicīdium}}; ūnō verbō, sē contāminābant omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"homo","latin":"homō, hominis","headword":"homō","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"(m.) human being, person; man, human being","forms":["homine","hominem","homines","homini","hominibus","hominis","hominum","homō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis {{hominibus}}, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"homunculus","latin":"homunculus, homunculi","headword":"homunculus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"little man, manikin","forms":["homunculī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Ipsum deinde convīvium cōnstat” inquit “ex rēbus quattuor et tum dēnique omnibus suīs numerīs absolūtum est: sī bellī homunculī collēctī sunt, sī ēlēctus locus, sī tempus lēctum, sī apparātus nōn neglēctus.”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"honestas","latin":"honestās, -ātis ( f.)","headword":"honestās","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"honesty, virtue; honour, integrity","forms":["honestāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum rēx admīrātus eum dīxisse fertur: 'Ille est Fabricius quī difficilius ab {{honestāte}} quam sōl ā cursū suō āvertī potest!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"honeste","latin":"honeste","headword":"honeste","letter":"h","pos":"adverb","posGroup":"adverb","english":"honorably; decently","forms":["honestē"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ille habet quod sibi dêbëbätm: honestē vîxit, honestē obiit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"honesto","latin":"honesto, honestare, honestavi, honestatus","headword":"honesto","letter":"h","pos":"verb","posGroup":"verb","english":"honor (with); adorn, grace","forms":["honestō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"timuit sē committere virō honestō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"honestus","latin":"honestus, -a, -um","headword":"honestus","letter":"h","pos":"adjective","posGroup":"adjective","english":"honorable, respectable; (n.) virtue","forms":["honesta","honestam","honestī","honestīs","honestissimī","honestissimīs","honestissimus","honestum","honestus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Fufium Citam, {{honestum}} equitem Romanum, qui rei frumentariae iussu Caesaris praeerat, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"honor","latin":"honor, honoris","headword":"honor","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"honor; respect/regard; mark of esteem, reward; dignity/grace; public office","forms":["honor"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"...quod vērō nōmine poena, nōn {{honor}} est: poenam, Phaethōn, prō mūnere poscis!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"honorare","latin":"(honōrō) honōrāre","headword":"honōrāre","letter":"h","pos":"","posGroup":"other","english":"honor","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"honorarium","latin":"honorarium, honorarii","headword":"honorarium","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"stipend; honorarium; reimbursement","forms":["honōrārium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēmus causidicō {{honōrārium}} et advocātīs et iūris perītō, ut studiōsius dēfendant nōs.” [Servus, nummulārium cōnspiciēns:] “Iste est.” [Lūcius:] “Accipe ab eō nummōs, et sequere!” [Nummīs acceptīs, servus Lūcium ad forum sequitur.] [Lūcius:] “Sīcut cōnstituimus adest Gāius.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"honorifice","latin":"honorifice, honorificentius, honorificentissime","headword":"honorifice","letter":"h","pos":"adverb","posGroup":"adverb","english":"honorably; respectfully; with honor/respect","forms":["honōrificē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Lēgātī ad Pyrrhum dē redimendīs captīvīs missī ab eō honōrificē susceptī sunt; captīvōs sine pretiō Rōmam mīsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"honorificus","latin":"honōrificus, -a, -um","headword":"honōrificus","letter":"h","pos":"","posGroup":"other","english":"honorable","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"honoro","latin":"honōrō, -āre, -āvī, -ātum","headword":"honōrō","letter":"h","pos":"verb","posGroup":"verb","english":"honour","forms":["honōrābor","honōrat","honōrātum","honōrāvistī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dīxit ita māter: “Populus templum meum nōn {{honōrat}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"honos","latin":"honōs, -ōris","headword":"honōs","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"honour, glory","forms":["honōre","honorem","honōrēs","honōribus","honōris","honōrum","honōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ad eum est {{honorem}} evocatus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"honos/honor","latin":"honōs/honor, -ōris (m.)","headword":"honōs/honor","letter":"h","pos":"","posGroup":"other","english":"honor, high office","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"hora","latin":"hōra, -ae","headword":"hōra","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"hour","forms":["hora","hōrae","hōram","hōrās","horis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Caesar, nuntiis ad civitatem Aeduorum missis qui suo beneficio conservatos docerent quos iure belli interficere potuisset, tribusque {{horis}} noctis exercitui ad quietem datis, castra ad Gergoviam movit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"horologium","latin":"horologium, horologi(i)","headword":"horologium","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"clock, sundial","forms":["hōrologiō","hōrologium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Precibus eius et lacrimīs mōtus, Deus quīndecim annōrum ūsūram illī concessit, atque, ad faciendam fidem, sōlis umbrā, rēge ita postulante, per decem līneās regressa est in eius hōrologiō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"horrendus","latin":"horrendus, -a, -um","headword":"horrendus","letter":"h","pos":"adjective","posGroup":"adjective","english":"dreadful; horrible, dreadful; horrible, terrible","forms":["horrenda","horrendam","horrendōs","horrendum","horrendus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Haec verba locūtus, ex stabulō taurum, quī ferōcissimus factus erat, ēmīsit; quī, in hominēs impetum īnfēstīs cornibus suīs faciēns, multōs virōs multāsque fēminās {{horrenda}} morte interfēcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"horreo","latin":"horreo, horrere, horrui, -","headword":"horreo","letter":"h","pos":"verb","posGroup":"verb","english":"dread, shrink from, shudder at; stand on end, bristle; have rough appearance","forms":["horream","horrēbant","horrēmus","horrēns","horrent","horrentem","horrentia","horrentibus","horrēre","horret"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlius id quod in herbā iacet manū tangit atque “Fui!” inquit {{horrēns}}, “Est parva bēstia nūda.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"horresco","latin":"horrēscō, -ere, horruī","headword":"horrēscō","letter":"h","pos":"verb","posGroup":"verb","english":"grow rough","forms":["horrēscēbant","horrēscere","horruit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Quō ubi prīmum pervēnit, sē ipsam in aquā tamquam in speculō Vidēns valdē {{horruit}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"horret","latin":"horret, horrēre","headword":"horret","letter":"h","pos":"","posGroup":"other","english":"bristle, shudder (at)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"horreum","latin":"horreum, horrei","headword":"horreum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"storehouse; barn","forms":["horrea","horreīs","horreum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque, Rēx, praefice tōtī Aegyptō virum sapientem et industrium, quī partem frūgum recondat in {{horreīs}} pūblicīs, servetque dīligenter in subsidium famis secūtūrae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"horribilis","latin":"horribilis, -e","headword":"horribilis","letter":"h","pos":"adjective","posGroup":"adjective","english":"horrible, terrifying","forms":["horribilem","horribilī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"T rimalchiô item fābulam {{horribilem}} nārrat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"horridus","latin":"horridus, horrida, horridum","headword":"horridus","letter":"h","pos":"adjective","posGroup":"adjective","english":"wild, frightful, rough, bristly, standing on end, unkempt; grim; horrible","forms":["horrida"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ascendit nāvem, quam tempestās {{horrida}} — simul et vetustās — mediō dissolvit marī!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"horror","latin":"horror, -ōris (m.)","headword":"horror","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"dread, horror; horror, dread; horror, shuddering","forms":["horror","horrōre"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mors erat ante oculōs, mē lūridus occupat {{horror}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hortari","latin":"(hortor) hortārī, hortātum","headword":"hortārī","letter":"h","pos":"verb","posGroup":"verb","english":"encourage, urge; to encourage, urge","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"hortatus","latin":"hortatus, hortata, hortatum","headword":"hortatus","letter":"h","pos":"adjective","posGroup":"adjective","english":"encouragement, urging","forms":["hortātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quārē mātrem rēx {{hortātus}} est, ut fīliō suādēret imperāta facere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hortensium","latin":"hortensium, hortensii","headword":"hortensium","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"garden herb","forms":["Hortēnsio","Hortēnsium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Antōnium et {{Hortēnsium}}, quī tum arte ōrātōriā excellebant, assiduē audiēbat, ac simul apud doctōrēs Graecōs, Molōnem rhētorem et Diodōtum philosophum, discēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hortensius","latin":"hortensius, hortensia, hortensium","headword":"hortensius","letter":"h","pos":"adjective","posGroup":"adjective","english":"grown in gardens; belonging to/in a garden","forms":["Hortēnsius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duo tum excellebant ōrātōrēs, quī mē imitandī cupiditāte incitārent, Cotta et {{Hortēnsius}}, quōrum alter remissus et lēnis, alter ōrnātus, ācer et verbōrum et actiōnis genere commōtior.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hortor","latin":"hortor, hortari, hortatus sum","headword":"hortor","letter":"h","pos":"verb","posGroup":"verb","english":"encourage; cheer; incite; urge; exhort","forms":["hortābantur","hortābātur","hortanda","hortandī","hortante","hortantibus","hortantur","hortāre","hortārentur","hortaretur","hortārī","hortatur","hortor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; {{hortatur}} ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hortus","latin":"hortus, -ī","headword":"hortus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"garden","forms":["hortī","hortīs","hortō","hortōs","hortum","hortus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: “{{Hortus}} noster plēnus est rosārum.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"hospes","latin":"hospes, hospitis","headword":"hospes","letter":"h","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) guest, stranger; guest; host; guest, host","forms":["hospes","hospite","hospitem","hospitēs","hospitī","hospitibus","hospitis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vēnit ad hominem dīvitem {{hospes}} quīdam; cumque eī parandum esset convīvium, dīves ille pepercit suīs ovibus, et oviculam pauperis, vī ēreptam, hospitī edendam apposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hospita","latin":"hospita, -ae","headword":"hospita","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"(female) guest, stranger","forms":["hospita"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In antīquīs annalibus memoria super librīs Sibyllīnīs haec prōdita est: anus {{hospita}} atque incōgnita ad Tarquinium Superbum rēgem adiit novem librōs ferēns quōs esse dīcēbat dīvīna ōrācula: 'eōs velle vēnumdarī'.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hospitale","latin":"hospitale, hospitalis","headword":"hospitale","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"hospital; guesthouse, guestroom","forms":["hospitāle"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi exceptus benignē ab ignārīs cōnsiliī, cum post cēnam in {{hospitāle}} cubiculum dēductus esset, amōre ārdēns, postquam satis tūta circa sopītīque omnēs vidēbantur, strictō gladiō ad dormientem Lūcrētiam venit, sinistrāque manū mulieris pectore oppressō, 'Tacē, Lūcrētia!' inquit, 'Sextus Tarquinius sum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hospitalis","latin":"hospitālis, -e","headword":"hospitālis","letter":"h","pos":"","posGroup":"other","english":"hospitable, guest-","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"hospitaliter","latin":"hospitaliter","headword":"hospitaliter","letter":"h","pos":"adverb","posGroup":"adverb","english":"in a hospitable manner","forms":["hospitāliter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Invītātī {{hospitāliter}} per domōs, cum situm moeniaque et frequentia urbis tēcta vīdissent, mīrantur tam brevī rem Rōmānam crēvisse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hospitium","latin":"hospitium, -ī","headword":"hospitium","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"guest friendship/house; hospitality; hospitality, guest-friendship","forms":["hospitia","hospitiī","hospitio","hospitium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ex his Bellovaci suum numerum non compleverunt, quod se suo nomine atque arbitrio cum Romanis bellum gesturos dicebant, neque cuiusquam imperio obtemperaturos; rogati tamen ab Commio pro eius {{hospitio}} duo milia una miserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hostia","latin":"hostia, -ae","headword":"hostia","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"sacrificial animal; sacrificial victim","forms":["hostia","hostiae","hostiam","hostiās","hostiīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum iter facerent simul, Isaacus dīxit patrī: mī pater, ecce ligna; sed ubinam est {{hostia}} immolanda?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hosticus","latin":"hosticus, hostica, hosticum","headword":"hosticus","letter":"h","pos":"adjective","posGroup":"adjective","english":"of or belonging to an enemy, hostile","forms":["hosticus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Namque īnstat fātum mihi trīste, Sabellā quod puerō cecinit dīvīnā mōta anus urnā: Hunc neque dīra venēna nec {{hosticus}} auferet ēnsis, nec laterum dolor, aut tussis, nec tarda podagra.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"hostilis","latin":"hostīlis, -e","headword":"hostīlis","letter":"h","pos":"adjective","posGroup":"adjective","english":"enemy, hostile","forms":["hostīle","hostīlem","hostīlī","hostīlia","hostīlis","Hostīlium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn est ita, inquit Iōsēphus; sed vēnistis hūc animō hostīlī: vultis explōrāre nostrās urbēs et loca Aegyptī parum mūnīta.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hostiliter","latin":"hostiliter","headword":"hostiliter","letter":"h","pos":"adverb","posGroup":"adverb","english":"in an unfriendly/hostile way, in the manner of an enemy","forms":["hostīliter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum ea ibi Rōmānī gerunt, Antemnātium exercitus per occāsiōnem {{hostīliter}} in fīnēs Rōmānōrum invāsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"hostis","latin":"hostis, hostis","headword":"hostis","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"(m.) enemy","forms":["hoste","hostem","hostes","hostī","hostibus","hostis","hostium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, legatos mittunt subsidium rogatum, quo facilius {{hostium}} copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"huc","latin":"hūc","headword":"hūc","letter":"h","pos":"adverb","posGroup":"adverb","english":"to this place; to here, hither; to this place, here","forms":["huc"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Huc}} biduo pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"hue","latin":"hue","headword":"hue","letter":"h","pos":"adverb","posGroup":"adverb","english":"hither, to the person speaking/indicated; so far, to this point/place/degree","forms":["hve"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Dominus {{hve}} illūc in hortō suō amoenō ambulat, deinde exit in agrōs, quī hortum cingunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"humanitas","latin":"hūmānitās, -atis ( f.)","headword":"hūmānitās","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"human feeling, culture; humanity, kindness, culture","forms":["hūmānitāte","hūmānitātem","hūmānitātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac prīmum quanta innocentia dēbent esse imperātōrēs! quanta deinde in omnibus rēbus temperantia! quanta fide, quanta facilitāte, quanto ingeniō, quanta {{hūmānitāte}}!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"humano","latin":"humano, humanare, humanavi, humanatus","headword":"humano","letter":"h","pos":"verb","posGroup":"verb","english":"make human; (in PASSIVE of the incarnation of Christ)","forms":["hūmānō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duae manūs et duo pedēs in corpore hūmānō sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"humanum","latin":"humanum, humani","headword":"humanum","letter":"h","pos":"noun (n.)","posGroup":"noun","english":"human affairs (pl.), concerns of men; events of life","forms":["hūmānum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Medicus: “Sanguis ā corde per vēnās fluit in tōtum corpus {{hūmānum}}, ut dīcit Hippocratēs...” Hippocratēs -is","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"humanus","latin":"hūmānus, -a, -um","headword":"hūmānus","letter":"h","pos":"adjective","posGroup":"adjective","english":"human; human, humane","forms":["hūmāna","hūmānae","hūmānam","hūmānārum","hūmānās","hūmānē","hūmānī","hūmāniōrum","hūmānīs","hūmānōrum","hūmānōs","hūmānus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In hortō Aemilia “Nōnne pulchra est lūna?” inquit, “Est ut faciēs {{hūmāna}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"humi","latin":"humī","headword":"humī","letter":"h","pos":"adverb","posGroup":"adverb","english":"(loc.) on the ground","forms":["humī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sextus: “Quia humī iacuī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"humilis","latin":"humilis, -e","headword":"humilis","letter":"h","pos":"adjective","posGroup":"adjective","english":"low; low, humble","forms":["humiles","humili","humilia","humiliōrem","humilis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, pari aetate et gratia sed genere dispari, quem Caesar ab Diviciaco sibi traditum ex {{humili}} loco ad summam dignitatem perduxerat, in equitum numero convenerant nominatim ab eo evocati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"humo","latin":"humō (1)","headword":"humō","letter":"h","pos":"verb","posGroup":"verb","english":"bury","forms":["humāre","humāta","hūmēris","humō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce statim Rebecca, virgō eximia pulchritūdine, prōdiit, gerēns urnam {{hūmēris}}; quae dēscendit ad puteum, et implēvit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"humus","latin":"humus, -ī","headword":"humus","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"(f.) ground; ground, earth","forms":["humum","humus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ariēs vērō aureus sūrsum suprā {{humum}} sē levāvit et ex eō locō, ubi sita erat puerōrum casa, ēvolāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hyacinthus","latin":"hyacinthus, hyacinthi","headword":"hyacinthus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"iris; (prob. not hyacinth); sapphire; blue-dyed cloth (Souter)","forms":["Hyacinthe","Hyacinthī","Hyacinthō","Hyacinthus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Nihil enim eī grātius iam poterat esse quam ipsum nōmen Hyacinthī: sīc enim puer vocābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"hydraulus","latin":"hydraulus, hydrauli","headword":"hydraulus","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"water organ","forms":["hydraulē"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn minus et Trimalchiô eiusmodî methodiô laetus “Carpe!” inquit. essedärius Prôcessit statim scissor, et ad _, cerâvit obsônium, ut putārēs Ā’ ' essedärium hydraulē cantante Ingerēbat nihilô minus Trimal- chiô lentissimä vôce: “Carpe!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"hydria","latin":"hydria, -ae","headword":"hydria","letter":"h","pos":"noun (f.)","posGroup":"noun","english":"large water jar","forms":["hydria","hydriae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Et dēficiente vinō, dīcit māter Iēsu:\"VĪnum nōn habent.\"Deinde dīcit māter eius ministrīs:\"Quodcumque dīxerit vōbīs, facite.\"Brant ibi lapideae {{hydriae}} sex, quās aquā implerī iussit Iēsus.\"Haurīte nunc\"inquit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"hymen","latin":"Hymen, undeclined","headword":"Hymen","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Greek wedding chant/refrain; (personified as a god); marriage, wedding, match","forms":["Hymēn"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Hymēn}} vōce Orpheī ad nūptiās cum Eurydicē vocātur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"hymenaeos","latin":"Hymenaeos, Hymenaei","headword":"Hymenaeos","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Greek wedding chant/refrain; (personified as a god); marriage, wedding, match","forms":["hymenaeōs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pergama cum peteret inconcessōsque {{hymenaeōs}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"hymenaeus","latin":"Hymenaeus, Hymenaei","headword":"Hymenaeus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"Greek wedding chant/refrain; (personified as a god); marriage, wedding, match","forms":["Hymenaee"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pars ^{{Hymenaee}}!\" canunt, pars clàmant Euhiōn,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"hymnus","latin":"hymnus, hymni","headword":"hymnus","letter":"h","pos":"noun (m.)","posGroup":"noun","english":"hymn","forms":["hymnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hic est enim sanguis meus novī testamentī, quī prō mulfīs effundētur in remissiōnem peccātōrum.\"Et hymnō dictō, exiērunt in montem Olivefī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iaceo","latin":"iaceō, -ēre, -uī","headword":"iaceō","letter":"i","pos":"verb","posGroup":"verb","english":"lie (at rest)","forms":["iacē","iaceant","iaceās","iacēbant","iacēbat","iacēbit","iacēns","iacent","iacentem","iacentēs","iacentī","iacentia","iaceō","iacēre","iacērentur","iacēret","iacēs","iacet","iacitē","iacuerat","iacuerit","iacuērunt","iacuī","iacuisse","iacuistī","iacuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ex proximis unus {{iacentem}} transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iacere","latin":"iacere","headword":"iacere","letter":"i","pos":"verb","posGroup":"verb","english":"to throw","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"iacet","latin":"iacet, -ent","headword":"iacet","letter":"i","pos":"verb","posGroup":"verb","english":"lie; lies (down)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"iacio","latin":"jacio, jacere, jeci, jactus","headword":"jacio","letter":"i","pos":"verb","posGroup":"verb","english":"throw, hurl, cast; throw away; utter","forms":["iac","iacī","iaciam","iaciebant","iaciēbantur","iaciēbat","iaciendīs","iaciēns","iacientium","iaciēs","iacis","iacit","iaciunt","iactae","iactīs","iactum","iēcerat","iēcēre","iēcērunt","iēcī","iēcimus","iēcisse","iēcissem","iēcisset","iēcit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem eminus {{iaciebant}}, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iacit","latin":"iacit, iacere","headword":"iacit","letter":"i","pos":"","posGroup":"other","english":"throw, hurl","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"iactans","latin":"jactans, jactantis (gen.), jactantior -or -us, jactantissimus -a -um","headword":"jactans","letter":"i","pos":"adjective","posGroup":"adjective","english":"arrogant; boastful; proud; exaltant","forms":["iactāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Turnus vērō minās in rēgem Rōmānum {{iactāns}} ex conciliō abiit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iactito","latin":"jactito, jactitare, jactitavi, jactitatus","headword":"jactito","letter":"i","pos":"verb","posGroup":"verb","english":"mention; bandy; (Col)","forms":["iactitābat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Illum, quī ā sē Saūlem occīsum esse {{iactitābat}}, et rēgia īnsignia attulerat, perimī iussit, in poenam violātae māiestātis rēgiae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iacto","latin":"iactō, iactāre","headword":"iactō","letter":"i","pos":"verb","posGroup":"verb","english":"throw, toss about","forms":["iacta","iactabant","iactābātur","iactābit","iactāminī","iactāmur","iactandīs","iactantēs","iactantī","iactantur","iactāret","iactāris","iactās","iactat","iactāta","iactātam","iactātī","iactātis","iactātōs","iactātum","iactātur","iactātus","iactāvit","iactēmur","iactentur","iactet","iactētur","iactor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Matres familiae de muro vestem argentumque {{iactabant}}, et pectore nudo prominentes passis manibus obtestabantur Romanos ut sibi parcerent neu, sicut Avarici fecissent, ne a mulieribus quidem atque infantibus abstinerent; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iactor","latin":"iactor","headword":"iactor","letter":"i","pos":"verb","posGroup":"verb","english":"be tossed, be thrown about","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"iactura","latin":"iactūra, -ae","headword":"iactūra","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"throwing away, loss; loss, throwing overboard","forms":["iactura","iacturam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id silentio noctis conati non magna {{iactura}} suorum sese effecturos sperabant, propterea quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua intercedebat, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iactus","latin":"jactus, jactus","headword":"jactus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"throwing, hurling, cast, throw","forms":["iactus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{iactus}} -üs 71 € lacerē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iaculari","latin":"(iaculor) iaculārī","headword":"iaculārī","letter":"i","pos":"","posGroup":"other","english":"throw (the javelin)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iaculor","latin":"iaculor, -ārī, -ātus sum","headword":"iaculor","letter":"i","pos":"verb","posGroup":"verb","english":"to hurl, throw","forms":["iaculantem","iaculārī","iaculāta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Voluī inclāmāre, sed hostī\nprōdere mē timuī; vīdī, cum monte revulsum\nimmāne scopulum mediās permīsit in undās;\nvīdī iterum velutī tormentī vīribus ācta\nvāsta Gigantēō {{iaculantem}} saxa lacertō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iaculum","latin":"iaculum, -ī","headword":"iaculum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"throwing-spear, javelin; javelin","forms":["iaculīs","iaculō","Iaculum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Iaculum}} et sagittās portābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iam","latin":"iam","headword":"iam","letter":"i","pos":"adverb","posGroup":"adverb","english":"now, already","forms":["iam","Jam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui {{iam}} ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iambicus","latin":"iambicus, iambica, iambicum","headword":"iambicus","letter":"i","pos":"adjective","posGroup":"adjective","english":"iambic, composed of iambi","forms":["iambicus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Iambicus}} est versus quī iambōs continet aliōsve pedēs quōrum secunda aut tertia syllaba acuitur: u —’ —, — —’ —, u u —’ —, — u u, u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"iambus","latin":"iambus, -ī","headword":"iambus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"iamb","forms":["iambōs","iambus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: {{iambus}} u —, trochaeus — u, anapaestus u u —, dactylus — u u, spondēus — —, tribrachys u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"iamdudum","latin":"jamdudum","headword":"jamdudum","letter":"i","pos":"adverb","posGroup":"adverb","english":"long ago/before/since; a long time ago; this long time; immediately, at once","forms":["iamdūdum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Iamdūdum}} persuāsus erit, miserēbitur ultrō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iamiam","latin":"jamjam","headword":"jamjam","letter":"i","pos":"adverb","posGroup":"adverb","english":"already; now","forms":["Iamiam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"715 {{Iamiam}} ventūram, quaecumque erat Aurā, putàbàs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ianitor","latin":"iānitor, iānitōris","headword":"iānitor","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"(m.) door keeper = ōstiārius; doorkeeper, porter; doorkeeper","forms":["iānitor","iānitōre","iānitōrem","iānitōrēs","iānitōrī","iānitōribus","iānitōris"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Iānitor}}, cui nōmen est Sanniō, Dōrippam ēgredientem Sanniō -ōnis interrogat: “Quō īs, Dōrippa?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ianua","latin":"iānua, -ae","headword":"iānua","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"door","forms":["iānuā","iānuae","iānuam","iānuās","iānuīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Age, aperī {{iānuam}}, Diodōre!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ianus","latin":"Iānus, -ī","headword":"Iānus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Janus; his temple, open in war","forms":["Iāne","Iānī","Iānō","Iānum","Iānus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quot oculī sunt deō Iānō?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"iarbas","latin":"Iarbas, Iarbae","headword":"Iarbas","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Iarbas; (Libyan king, suitor of Dido rejected)","forms":["Iarbān","Iarbās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"An dum frāter Pygmaliōn mea moenia dēstruat aut {{Iarbās}}, rēx Gaetūlōrum, captam mē abdūcat?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iason","latin":"Iāsōn, -onis","headword":"Iāsōn","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Jason","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"iaspis","latin":"jaspis, jaspidis","headword":"jaspis","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"jasper","forms":["iaspide"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cōnspicit. atque illī stēllātus {{iaspide}} fulvā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ibi","latin":"ibi","headword":"ibi","letter":"i","pos":"adverb","posGroup":"adverb","english":"there, in that place; there","forms":["ibi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Ibi}} cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ibidem","latin":"ibīdem","headword":"ibīdem","letter":"i","pos":"adverb","posGroup":"adverb","english":"in the same place","forms":["ibīdem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rōmānī cotīdiē in thermās illās celebres lavātum eunt atque {{ibīdem}} corpora exercent natandō, currendō, luctandō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ibis","latin":"ibis, ibis","headword":"ibis","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ibis; (sacred Egyptian bird)","forms":["ībis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"īnferius terrās; mediō tūtissimus ībis.” Occupat ille levem iuvenālī corpore currum statque super, manibusque levēs contingere habēnās gaudet et invītō grātēs agit inde parentī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"icarus","latin":"Īcarus","headword":"Īcarus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Icarus, son of Daedalus","forms":["Īcare","Īcarī","Īcarō","Īcarum","Īcarus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tum rēx īrātus cēpit Daedalum, quī fīlum cōnfēcerat et Ariadnae dederat, eumque in labyrinthum inclūdī iussit ūna cum eius Īcarō fīliō; vērum pater et fīlius mīrābilī modō ē labyrinthō fūgērunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"icere","latin":"(īcō) īcere, -īcisse, -ictum","headword":"īcere","letter":"i","pos":"","posGroup":"other","english":"strike, make, conclude","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"icio","latin":"icio, icere, ici, ictus","headword":"icio","letter":"i","pos":"verb","posGroup":"verb","english":"hit, strike; smite, stab, sting; [foedus ~ => conclude/make a treaty, league]","forms":["iciunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"virginibus-que in-{{iciunt}}... virginibus cupidās iniciuntque","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ico","latin":"ico, icere, ici, ictus","headword":"ico","letter":"i","pos":"verb","posGroup":"verb","english":"hit, strike; smite, stab, sting; [foedus ~ => conclude/make a treaty, league])","forms":["Icar","icere","icis","īcit","icta","ictō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"cervīx -{{icis}} f — collī pars posterior Sed tamen et taurī cervīx","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ictus","latin":"ictus, -ūs","headword":"ictus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"stroke, blow; blow, stroke, kick","forms":["ictibus","ictu","ictum","ictūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione {{ictu}} scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"id","latin":"Id., abb.","headword":"Id","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Ides (pl.), abb. Id.; 15th of month, March, May, July, Oct., 13th elsewhen","forms":["id"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Id}} esse facile, quod neque legiones audeant absente imperatore ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ida","latin":"Ida, Idae","headword":"Ida","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Ida; (mountain near Troy; mountain in Crete)","forms":["Īda","Īdam","īdās","īdīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Bacchis -īdīs m, Alexander -dn m, Triphōn -ōnis m, 1ōannes -is m,","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"idcirco","latin":"idcirco","headword":"idcirco","letter":"i","pos":"adverb","posGroup":"adverb","english":"on that account; therefore","forms":["idcircō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quod audiēns Sarā rīsit, nec statim adhibuit fidem prōmissīs Deī, et idcircō reprehēnsa est ā Deō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"idem","latin":"īdem, eadem, idem","headword":"īdem","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"the same (adj./pronoun)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"identidem","latin":"identidem","headword":"identidem","letter":"i","pos":"adverb","posGroup":"adverb","english":"repeatedly","forms":["identidem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inambulābat in cēnāculō maerēns, et in hās vōcēs {{identidem}} ērumpēns: “Fīlī mī Absalōn, Absalōn fīlī mī: utinam prō tē moriar, Absalōn fīlī mī, fīlī mī Absalōn.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ideo","latin":"ideō","headword":"ideō","letter":"i","pos":"adverb","posGroup":"adverb","english":"for that reason","forms":["ideō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quam calamitātem ideō permīsit Deus illī ēvenīre, ut esset illūstrē patientiae exemplum posterīs prōpositum ad imitandum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"idoneus","latin":"idōneus, -a, -um","headword":"idōneus","letter":"i","pos":"adjective","posGroup":"adjective","english":"suitable; suitable, fit","forms":["idōneam","idonei","idoneis","idoneo","idoneos","idoneum","idōneus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Defensores oppido {{idonei}} deliguntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"idus","latin":"īdūs, īduum","headword":"īdūs","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"(f. pl.) 13th/15th of the month; the Ides (thirteenth or fifteenth day)","forms":["Īdibus","Īdūs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diēs tertius decimus post kalendās \"Īdūs\" nōminātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iecur","latin":"iecur, iecoris","headword":"iecur","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"(n.) liver","forms":["iecur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postquam vērō cōram deīs fuit, Iuppiter hanc sevērissimam gravissimamque poenam in eum statuit: ut in monte Caucasō catēnā ferreā vincīrētur; praetereā ut aquila cotīdiē eius {{iecur}} interdiū vorāret, quod nocte iterum nāscerētur, nē supplicium umquam fīnem habēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ieiunus","latin":"jejunus, jejuna -um, jejunior -or -us, jejunissimus -a -um","headword":"jejunus","letter":"i","pos":"adjective","posGroup":"adjective","english":"fasting, abstinent, hungry; dry, barren, unproductive; scanty, meager","forms":["ieiūnus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc, lūctū dēpositō, iussit sibi appōnī cibōs, mīrantibusque aulicīs dīxit: “Aegrōtante puerulō {{ieiūnus}} ōrābam, spērāns scīlicet Deum plācārī posse; nunc autem, cum mortuus sit, cūr frūstrā lūgeam?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iens","latin":"iens, (gen.), euntis","headword":"iens","letter":"i","pos":"adjective","posGroup":"adjective","english":"going; (PRES PPL of eo)","forms":["euntem","euntēs","euntī","euntibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus ille amīce: accēdite, inquit, ad mē: ego sum Iōsēphus, frāter vester, quem vēndidistis mercātōribus {{euntibus}} in Aegyptum; nōlīte timēre: Deī prōvidentia id factum est ut ego salūtī vestrae cōnsulerem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"igitur","latin":"igitur","headword":"igitur","letter":"i","pos":"adverb","posGroup":"adverb","english":"therefore, then, so; therefore","forms":["igitur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In duōbus pedibus tuīs tot digitī sunt quot in manibus: quot {{igitur}} digitī sunt tibi?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ignarus","latin":"ignārus, -a, -um","headword":"ignārus","letter":"i","pos":"adjective","posGroup":"adjective","english":"ignorant, unaware; unknowing, unaware; unknown (+ dat.)","forms":["ignāra","ignārae","ignārī","ignārīs","ignārō","ignārōs","ignārum","ignārus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Alphēus frūstrā eam sīc nūbe opertam quaerēbat et {{ignārus}} bis aspexit stupēns omnia loca atque vestīgia circā nūbem in quā deā Arethūsam occultāverat; bis etiam “Arethūsa!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ignavia","latin":"ignāvia, -ae","headword":"ignāvia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"idleness, cowardice","forms":["īgnāviā","ignāviae","ignāviam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At nēmō contrā illum exīre audēbat, et Goliathus suam Hebraeīs {{ignāviam}} cum irrīsū ac lūdibriō exprobrābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ignavus","latin":"ignavus, ignava -um, ignavior -or -us, ignavissimus -a -um","headword":"ignavus","letter":"i","pos":"adjective","posGroup":"adjective","english":"lazy/idle/sluggish; spiritless; cowardly, faint-hearted; ignoble, mean; useless","forms":["ignāvō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Compertum ego habeō, mīlitēs, verba virtūtem nōn addere neque ex ignāvō strēnuum neque fortem ex timidō exercitum ōrātiōne imperātōris fierī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"igneus","latin":"igneus, ignea, igneum","headword":"igneus","letter":"i","pos":"adjective","posGroup":"adjective","english":"fiery, hot; ardent","forms":["ignea","igneōs","igneum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum ēiēcit Adamum et Ēvam ex hortō, ut ille coleret terram, et collocāvit Angelum, quī praeferēbat manū gladium {{igneum}}, ut cūstōdīret aditum Paradīsī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ignis","latin":"ignis, ignis","headword":"ignis","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"(m.) fire","forms":["igne","ignem","ignēs","ignī","ignibus","ignis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto {{igne}} atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ignobilis","latin":"ignōbilis, -e","headword":"ignōbilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unknown, of low birth","forms":["ignōbilem","ignōbilēs","ignōbilis"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nunc quandō ego sum, vāpulābis, nī hinc abīs, {{ignōbilis}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ignominia","latin":"ignominia, ignominiae","headword":"ignominia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"disgrace, ignominy, dishonor","forms":["ignōminiā","ignominiae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod in conspectu omnium res gerebatur neque recte ac turpiter factum celari poterat, utrosque et laudis cupiditas et timor {{ignominiae}} ad virtutem excitabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ignominiosus","latin":"ignōminiōsus, -a, -um","headword":"ignōminiōsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"disgraceful; disgraceful, shameful","forms":["ignōminiōsam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hostīliō Mancīnō cōnsule sacrificante pullī ex caveā ēvolāvērunt; cōnscendentī deinde nāvem, ut in Hispāniam proficīscerētur, accidit vōx: 'Manē, Mancīne!' Quae auspicia trīstia fuisse ēventū probātum est: victus enim ā Numantīnīs et castrīs exūtus, cum spēs nūlla servandī exercitūs esset, pācem cum hīs fēcit {{ignōminiōsam}}, quam ratam esse senātus vetuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ignorans","latin":"ignorans, (gen.), ignorantis","headword":"ignorans","letter":"i","pos":"adjective","posGroup":"adjective","english":"ignorant (of), unaware, not knowing; ignorant of Christian truth (Souter)","forms":["ignōrāns","īgnōrantēs","ignōrantis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nec diū superfuit fīliō pater; quī cum {{ignōrāns}} nurum ventrem ferre dēcessisset oblītus nepōtis in testāmentō, puerō egentī post avī mortem nātō ab inopiā \"Egēriō\" nōmen datum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ignorantia","latin":"ignorantia, ignorantiae","headword":"ignorantia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ignorance; lack of knowledge; absence of data on which to make judgment","forms":["ignōrantiam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quis enim potest melius vel cūnctātiōnem meam regere vel {{ignōrantiam}} īnstruere?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ignorare","latin":"(ignōrō) ignōrāre, ignōrāvisse,  ignōrātum","headword":"ignōrāre","letter":"i","pos":"verb","posGroup":"verb","english":"not to know, be ignorant of","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"ignoro","latin":"ignoro, ignorare, ignoravi, ignoratus","headword":"ignoro","letter":"i","pos":"verb","posGroup":"verb","english":"not know; be unfamiliar with; disregard; ignore; be ignorant of","forms":["ignōrābat","ignōrābātur","ignōrant","ignōrāre","ignōrārem","ignōrārent","ignōrāret","ignōrās","ignōrat","ignoratis","Ignorō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod si ea quae in longinquis nationibus geruntur {{ignoratis}}, respicite finitimam Galliam, quae in provinciam redacta, iure et legibus commutatis, securibus subiecta perpetua premitur servitute.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ignoscere","latin":"(ignōscō) ignōscere, ignōvisse ignōtum ({i}+ dat.{/i})","headword":"ignōscere","letter":"i","pos":"verb","posGroup":"verb","english":", forgive; to forgive (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ignosco","latin":"ignosco, ignoscere, ignovi, ignotus","headword":"ignosco","letter":"i","pos":"verb","posGroup":"verb","english":"pardon, forgive (with DAT)","forms":["ignōscāmus","ignōsce","ignōscere","ignosceret","ignōscis","ignōscit","ignōscite","ignōscundō","ignōscunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ille oppidum Biturigum positum in via Noviodunum oppugnare instituerat. (Quo ex oppido cum legati ad eum venissent oratum ut sibi {{ignosceret}} suaeque vitae consuleret, ut celeritate reliquas res conficeret, qua pleraque erat consecutus, arma conferri, equos produci, obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ignotus","latin":"ignōtus, -a, -um","headword":"ignōtus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unknown; unknown, strange","forms":["ignōta","ignōtae","ignōtam","ignōtās","ignōtī","ignōtīs","ignōtō","ignōtōs","ignōtum","ignōtus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ille enim Cyparissus, cervō sagittā percussō, ob animī dolōrem in arborem mūtātur collum manibus, quamquam {{ignōtīs}}, nōn sine gaudiō offerēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ile","latin":"ile, ilis","headword":"ile","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"groin, private parts; side of body from hips to groin (pl.), loin; guts","forms":["īlia","īlium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn crēdidērunt IUdaeī īlium caecum fuisse.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ilex","latin":"ilex, ilicis","headword":"ilex","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"holm-oak, great scarlet oak, tree or wood; its acorn","forms":["īlice"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"149 Sed neque ràmosà numeràbīs in īlice glandēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iliacus","latin":"iliacus, iliaca, iliacum","headword":"iliacus","letter":"i","pos":"adjective","posGroup":"adjective","english":"colicky","forms":["Īliacās","Īliacīs","Īliacōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi cūria Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) nefandās, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ilico","latin":"īlicō","headword":"īlicō","letter":"i","pos":"adverb","posGroup":"adverb","english":"at once","forms":["īlicō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum arca septiēs circumlāta esset, mūrī et turrēs īlicō corruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ilion","latin":"Ilion, Ilii","headword":"Ilion","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"Ilium, Troy","forms":["īliō","Īlion"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum ita in mediō flūmine nūda natāret ac frīgidārum aquārum beneficiō gaudēret, subitō vōcem audīvit, quae “Ō Arethūsa” clāmāvit, “audī verba mea!” Cum autem nympha vōcem quidem audīret, nēminem vēro quī loquerētur cemere posset, ita perterrita est, ut, ex aquīs sine morā ēgressā, continuō ad rīpam curreret, ut ex īliō locō terribilī quam celerrimē fugeret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ilioneus","latin":"Ilioneus, Ilionei","headword":"Ilioneus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Ilioneus; (Trojan spokesman of Aeneas)","forms":["Īlioneā","Īlioneī","Īlionēō","Īlioneus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ultimus, nōmine Īlioneus, ōrābat ut sibi dī parcē rent: Apollō eius precibus lacrimīsque animō movēbātur, sed sagitta iam missa revocārī nōn poterat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"illac","latin":"illac","headword":"illac","letter":"i","pos":"adverb","posGroup":"adverb","english":"that way","forms":["illāc"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mīra sunt, nisi latuit intus illīc in {{illāc}} hirneā!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"illacrimare","latin":"(illacrimō) illacrimāre","headword":"illacrimāre","letter":"i","pos":"","posGroup":"other","english":"weep over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"illaesus","latin":"illaesus, illaesa, illaesum","headword":"illaesus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uninjured; inviolate","forms":["illaesī","illaesus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nam Dāvīd, occīsīs ducentīs Philistaeīs, rediit {{illaesus}}, atque ita rēgis fīliam in mātrimōnium accēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ille","latin":"ille, illa, illud","headword":"ille","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"that, the one, he; that; he, she, it; the former","forms":["illa","illae","illam","illārum","illās","ille","illi","illis","illīus","illorum","illos","illud","illum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus in Italiam Caesari nuntiatis, cum iam {{ille}} urbanas res virtute Cn.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ille / illa / illud","latin":"ille / illa / illud","headword":"ille / illa / illud","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"that (one), he, she, it","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"ille/illa/illud","latin":"ille/illa/illud","headword":"ille/illa/illud","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"that (one), he, she, it","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"illecebra","latin":"illecebra, -ae","headword":"illecebra","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"enticement, allurement; enticement, lure","forms":["illecebrā","illecebrae","illecebrīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Suīs tē oportet {{illecebrīs}} ipsa virtūs trahat ad vērum decus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"illic","latin":"illīc","headword":"illīc","letter":"i","pos":"adverb","posGroup":"adverb","english":"there","forms":["illīc"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum mīles {{illīc}} in sōle iacet, Mēdus advenit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"illicere","latin":"(illicō) illicere, -ēxisse, -ectum","headword":"illicere","letter":"i","pos":"","posGroup":"other","english":"entice, attract","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"illicio","latin":"illicio, illicere, illexi, illectus","headword":"illicio","letter":"i","pos":"verb","posGroup":"verb","english":"allure, entice","forms":["illexerat","illicere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quem Antiochus coepit {{illicere}} ut lēgem dēsereret, affirmāns eum dīvitem fore et beātum; sed adulēscēns nec minīs movēbātur, nec prōmissīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"illinc","latin":"illinc","headword":"illinc","letter":"i","pos":"adverb","posGroup":"adverb","english":"from there; there, on that side, thence","forms":["illinc"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus: “Sōlus intrāvī, nex sōlus {{illinc}} exiī: servus meus, quī interim advēnerat, mē vix vīvum ē domō ārdentī tulit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"illo","latin":"illo","headword":"illo","letter":"i","pos":"adverb","posGroup":"adverb","english":"there, thither, to that place/point","forms":["illo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem {{illo}} munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"illuc","latin":"illūc","headword":"illūc","letter":"i","pos":"adverb","posGroup":"adverb","english":"to that place; to there, thither","forms":["illūc"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iacobus accessit {{illūc}}, et dīxit pāstōribus: frātrēs, unde estis?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"illucescere","latin":"(illūcēscō) illūcēscere, -lūxisse, -lūctum","headword":"illūcēscere","letter":"i","pos":"","posGroup":"other","english":"dawn, grow light","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"illucesco","latin":"illucesco, illucescere, illuxi, -","headword":"illucesco","letter":"i","pos":"verb","posGroup":"verb","english":"begin to dawn","forms":["illūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubī {{illūxit}}, Pharaō perturbātus convocāvit omnēs coniectōrēs Aegyptī, et nārrāvit illīs somnium; at nēmō poterat illud interpretārī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"illudere","latin":"(illūdō) illūdere, -ūsisse, -ūsum","headword":"illūdere","letter":"i","pos":"","posGroup":"other","english":"make a game of, fool","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"illudo","latin":"illudo, illudere, illusi, illusus","headword":"illudo","letter":"i","pos":"verb","posGroup":"verb","english":"mock, ridicule, speak mockingly of; fool, dupe; use for sexual pleasure","forms":["illūdētur","illūserit","illūsīs","illūsisse"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Assilmpsit autem Jēsus duodecim discipulōs et ait illīs:\"Ecce, ascendimus Hierosolymam et cōnsummābuntur omnia quae scrlpta sunt dē Fīliō hominis: trādētur enim gentibus, et {{illūdētur}}, et flagellābitur, et cōnspuētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"illustrat","latin":"illūstrat, illūstrāre","headword":"illūstrat","letter":"i","pos":"","posGroup":"other","english":"illustrate, make clear","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"illustre","latin":"illustre, illustrius, illustrissime","headword":"illustre","letter":"i","pos":"adverb","posGroup":"adverb","english":"with clarity; clearly, distinctly, perspicuously (L+S)","forms":["illūstrē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quam calamitātem ideō permīsit Deus illī ēvenīre, ut esset illūstrē patientiae exemplum posterīs prōpositum ad imitandum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"illustris","latin":"illūstris, -re","headword":"illūstris","letter":"i","pos":"adjective","posGroup":"adjective","english":"brilliant, illustrious","forms":["illūstrēs","illūstrī","illūstris","illūstrissimus","illūstrium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Apellés -is 7, pictor Cōus {{illūstris}};","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"illustro","latin":"illustro, illustrare, illustravi, illustratus","headword":"illustro","letter":"i","pos":"verb","posGroup":"verb","english":"illuminate, light up; give glory; embellish; make clear, elucidate; enlighten","forms":["illūstrābantur","illūstrābat","illūstrant","illūstrantur","illūstrās","illūstrat","illūstrāta","illūstrātor","illūstrātur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed rēs male {{illūstrantur}} lūce lūnae.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"illyricum","latin":"Illyricum, Illyrici","headword":"Illyricum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"Illyricum; territory NE of Adriatic; Slovenia/Croatia region, Dalmatia/Albania","forms":["Illyricā","Illyricī","Illyricō","Illyricum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"est nigrior pīce Illyricā | nig-rī-ō|r","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"imago","latin":"imāgō, imāginis","headword":"imāgō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"(f.) picture, image; image, reflection; image, likeness; image, likeness, pretext","forms":["imāgine","imāginem","imaginēs","imāginī","imāginibus","imāginis","imāginum","imāgō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In speculō aquae videt {{imāginem}} suam.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"imbecillitas","latin":"imbecillitas, imbecillitatis","headword":"imbecillitas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"weakness, feebleness; moral/intellectual weakness","forms":["imbecillitate"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nolite hos vestro auxilio exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi {{imbecillitate}} omnem Galliam prosternere et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"imbecillus","latin":"imbēcillus, -a, -um","headword":"imbēcillus","letter":"i","pos":"adjective","posGroup":"adjective","english":"weak; weak, feeble","forms":["imbēcilla"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quae tametsī animus aspernābātur īnsolēns malārum artium, tamen inter tanta vitia {{imbēcilla}} aetās ambitiōne corrupta tenēbātur; ac mē, cum ab reliquōrum malīs mōribus dissentīrem, nihilō minus honōris cupīdō eadem quā cēterōs fāma atque invidia vexābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"imbellis","latin":"imbellis, -e","headword":"imbellis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unwarlike, cowardly","forms":["imbellēs","imbellis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec procul iam ā portā Palātiī erat, clāmitāns: \"Vīcimus perfidōs hospitēs, {{imbellēs}} hostēs!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"imber","latin":"imber, imbris","headword":"imber","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"(m.) rain, shower; rain, rainstorm; rain, rain-shower","forms":["imber","imbre","imbrem","imbrēs","imbribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis {{imbribus}} tardarentur, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"imbuo","latin":"imbuo, imbuere, imbui, imbutus","headword":"imbuo","letter":"i","pos":"verb","posGroup":"verb","english":"wet, soak, dip; give initial instruction (in)","forms":["imbūtus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"An tū dialecticīs nōn {{imbūtus}} quidem es?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"imitari","latin":"(imitor) imitārī, imitātum","headword":"imitārī","letter":"i","pos":"verb","posGroup":"verb","english":"imitate; to imitate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"imitor","latin":"imitor, imitari, imitatus sum","headword":"imitor","letter":"i","pos":"verb","posGroup":"verb","english":"imitate/copy/mimic; follow; make an imitation/reproduction; resemble; simulate","forms":["imitābere","imitābimur","imitāminī","imitāmur","imitanda","imitandī","imitandum","imitantibus","imitantur","imitārentur","imitārī","imitāta","imitātī","imitātur","imitātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Singulari militum nostrorum virtuti consilia cuiusque modi Gallorum occurrebant, ut est summae genus sollertiae atque ad omnia {{imitanda}} et efficienda quae ab quoque traduntur aptissimum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"immanis","latin":"immānis, -e","headword":"immānis","letter":"i","pos":"adjective","posGroup":"adjective","english":"huge, monstrous, savage; huge, monstrous","forms":["immāne","immānēs","immānia","immānibus","immānior"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Voluī inclāmāre, sed hostī\nprōdere mē timuī; vīdī, cum monte revulsum\n{{immāne}} scopulum mediās permīsit in undās;\nvīdī iterum velutī tormentī vīribus ācta\nvāsta Gigantēō iaculantem saxa lacertō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"immanitas","latin":"immānitās, -tātis ( f.)","headword":"immānitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"monstrousness, brutality; savagery, cruelty","forms":["immānitās","immānitāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Simulatque enim sē īnflexit hic rēx in dominātum iniūstiōrem, fit continuō tyrannus, quō neque taetrius neque foedius nec dīs hominibusque invīsius animāl ūllum cōgitārī potest — quī, quamquam figūra est hominis, mōrum tamen {{immānitāte}} vāstissimās vincit bēluās!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"immaturus","latin":"immātūrus, -a, -um","headword":"immātūrus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not ripe; unripe, premature","forms":["immātūram","immātūrō","immātūrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum vērō, dum pāstor territus verbera exspectat, ovēs sine pāstōre relictae dē viā in agrōs aberrant ac frūmentum {{immātūrum}} carpere incipiunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"immedicabilis","latin":"immedicabilis, immedicabilis, immedicabile","headword":"immedicabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"incurable","forms":["immedicābile"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Nīl prōsunt artēs: erat {{immedicābile}} vulnus.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"immemor","latin":"immemor, (gen. -oris)","headword":"immemor","letter":"i","pos":"adjective","posGroup":"adjective","english":"unmindful, forgetful (of ) (+ gen.); forgetful, unmindful (+ gen.)","forms":["immemor","immemorēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Est, ubi Trōia fuit, Phrygiae contrāria tellus; lītore Thrēiciō classem religārat Ātrīdēs dum mare pācātum dum ventus amīcior esset: hīc subitō, quantus, cum vīveret, esse solēbat, exit humō lātē ruptā similisque minantī temporis illīus vultum referēbat Achillēs, quō ferus iniūstō petiit Agamemnona ferrō “{{immemorēs}}” que “meī discēditis” inquit “Achīvī, obrutaque est mēcum virtūtis grātia nostrae?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"immensum","latin":"immensum","headword":"immensum","letter":"i","pos":"adverb","posGroup":"adverb","english":"to an enormous extent/degree","forms":["immēnsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mulier nimium atque {{immēnsum}} poposcit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"immensus","latin":"immēnsus, -a, -um","headword":"immēnsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"immeasurable, endless; immense, boundless; boundless, immense","forms":["immēnsa","immēnsī","immēnsō","immēnsōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Salomōn templum immēnsī operis Hierosolymae aedificāvit: omnia aurō, argentō, gemmīsque in eō fulgēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"immeritus","latin":"immeritus, -a, -um","headword":"immeritus","letter":"i","pos":"adjective","posGroup":"adjective","english":"undeserving, innocent","forms":["immeritam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ut dolor ūnius Danaōs pervēnit ad omnēs, exspectāta diū, nūlla aut contrāria classī flāmina erant, dūraeque iubent Agamemnona sortēs {{immeritam}} saevae nātam mactāre Diānae.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"immineo","latin":"immineo, imminere, -, -","headword":"immineo","letter":"i","pos":"verb","posGroup":"verb","english":"threaten, be a threat (to); overhang, be imminent; with DAT","forms":["imminebat","imminēns","imminent","imminentem","imminentia","imminēre","imminērent","imminet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi sēnsit mortem sibi {{imminēre}}, arcessītō Iōsēphō dīxit: sī mē amās, iūra tē id factūrum esse quod ā tē petam, scīlicet ut nē mē sepeliās in Aegyptō, sed corpus meum trānsferās ex hāc regiōne, et condās in sepulcrō maiōrum meōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"imminere","latin":"(immineō) imminēre (< minēre)","headword":"imminēre","letter":"i","pos":"","posGroup":"other","english":"overhang, be imminent","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"imminuere","latin":"(imminuō) imminuere, -uisse, -ūtum","headword":"imminuere","letter":"i","pos":"verb","posGroup":"verb","english":"make smaller, reduce; to lessen, reduce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"imminuo","latin":"imminuo, imminuere, imminui, imminutus","headword":"imminuo","letter":"i","pos":"verb","posGroup":"verb","english":"diminish; impair; abbreviate (Col)","forms":["imminuī","imminūtae","imminūtam","imminūtō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deus immīsit ventum vehementem, et sēnsim aquae {{imminūtae}} sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"immisceo","latin":"immisceo, immiscere, immiscui, immixtus","headword":"immisceo","letter":"i","pos":"verb","posGroup":"verb","english":"mix in, mingle; confuse","forms":["immiscuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Varium et mūtābile semper fēmina!' Sīc fātus noctī sē {{immiscuit}} ātrae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"immiscere","latin":"(immisceō) immiscēre, -scuisse, -xtum","headword":"immiscēre","letter":"i","pos":"","posGroup":"other","english":"mingle, merge (into)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"immitis","latin":"immitis, immite, immitior -or -us, immitissimus -a -um","headword":"immitis","letter":"i","pos":"adjective","posGroup":"adjective","english":"cruel, rough, harsh, sour; rude, rough; severe, stern; inexorable; savage","forms":["immītibus","immītis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"spernit et irrīdet, factīsque {{immītibus}} addit","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"immittere","latin":"(immittō) immittere (< mittere)","headword":"immittere","letter":"i","pos":"","posGroup":"other","english":"send in, send (into)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"immitto","latin":"immitto, immittere, immisi, immissus","headword":"immitto","letter":"i","pos":"verb","posGroup":"verb","english":"send in/to/into/against; cause to go; insert; hurl/throw in; let go/in; allow","forms":["immīsit","immissā","immissīs","immisso","immissus","immittere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Adhortatus milites ne necessario tempore itineris labore permoveantur, cupidissimis omnibus progressus milia passuum XXV, agmen Aeduorum conspicatus, {{immisso}} equitatu iter eorum moratur atque impedit; interdicitque omnibus ne quemquam interficiant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"immo","latin":"immō","headword":"immō","letter":"i","pos":"adverb","posGroup":"adverb","english":"no, on the contrary; on the contrary, no indeed","forms":["immō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Rūfus: “Immō bonus canis est Persa.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"immobilis","latin":"immōbilis, -e (< movēre)","headword":"immōbilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"immovable, motionless","forms":["immōbilis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam terra, nōna, {{immōbilis}} manēns ūnā sēde semper haeret complexa medium mundī locum.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"immoderatus","latin":"immoderatus, immoderata, immoderatum","headword":"immoderatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unlimited, immoderate, disorderly","forms":["immoderāta","immoderātae","immoderātum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vastus animus {{immoderāta}}, incrēdibilia, nimis alta semper cupiēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"immodicus","latin":"immodicus, immodica, immodicum","headword":"immodicus","letter":"i","pos":"adjective","posGroup":"adjective","english":"beyond measure, immoderate, excessive","forms":["immodicam","immodicōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ōdimus (: ōdī) im-modicum fastwn Ōdimus {{immodicōs}} — expertó","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"immolare","latin":"(immolō) immolāre","headword":"immolāre","letter":"i","pos":"verb","posGroup":"verb","english":"sacrifice, immolate; to sacrifice","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"immolo","latin":"immolō (1)","headword":"immolō","letter":"i","pos":"verb","posGroup":"verb","english":"to sacrifice, slay","forms":["immolā","immolābimus","immolanda","immolant","immolat","immolātīs","immolātūrus","immolāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Postquam Isaacus adolēvit, deus tentāns fidem Abrahamī, dīxit illī: Abrahame, tolle fīlium tuum ūnicum quem amās, et immolā eum mihi in monte quem ostendam tibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"immortalis","latin":"immortālis, -e","headword":"immortālis","letter":"i","pos":"adjective","posGroup":"adjective","english":"immortal","forms":["immortālem","immortālēs","immortālī","immortālibus","immortālīs","immortālium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tam magnī sē ipsa aestimābat, quae tot fīliōs filiāsque pepererat, ut, cum nūllum deōrum plurēs līberōs quam sē habēre vidēret, ipsōs {{immortālēs}} contemneret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"immortalitas","latin":"immortalitas, immortalitatis","headword":"immortalitas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"immortality; divinity, being a god; indestructibility; permanence; remembrance","forms":["immortālitāte"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed, nesciō quōmodo, dum legō, assentior — cum posuī librum et mēcum ipse dē {{immortālitāte}} animōrum coepī cōgitāre, assēnsiō illa omnis ēlābitur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"immotus","latin":"immōtus, -a, -um","headword":"immōtus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unmoving","forms":["immōta","immōtīs","immōtōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sēdit tunc Niobē inter fīliōs fīliāsque mortuās, ipsa etiam ferē mortua: nūlla membra movēbat: {{immōtīs}} oculīs ante sē spectābat; ipse sanguis in vēnīs cōnstitit; nec caput iam flec tēbātur, nec bracchia tollēbantur: etiam vīscera saxum erant facta.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"immundus","latin":"immundus, immunda, immundum","headword":"immundus","letter":"i","pos":"adjective","posGroup":"adjective","english":"dirty, filthy, foul; (morally); unclean, impure; untidy/slovenly/squalid; evil","forms":["immundā","immundum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ef-fer ex immundā humō!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"immunis","latin":"immūnis, -e","headword":"immūnis","letter":"i","pos":"adjective","posGroup":"adjective","english":"exempt (from), tax-free (+ abl.); exempt (from service)","forms":["immunem","immunēs","immūnis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, fideli atque utili superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius {{immunem}} esse iusserat, iura legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"immurmurare","latin":"immurmurāre","headword":"immurmurāre","letter":"i","pos":"verb","posGroup":"verb","english":"to whisper into","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"immurmuro","latin":"immurmuro, immurmurare, immurmuravi, immurmuratus","headword":"immurmuro","letter":"i","pos":"verb","posGroup":"verb","english":"murmur, mutter (at or to)","forms":["immurmurat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Effōdit igitur terram, in quam {{immurmurat}} parvā voce dē auribus dominī vīsīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"immuto","latin":"immuto, immutare, immutavi, immutatus","headword":"immuto","letter":"i","pos":"verb","posGroup":"verb","english":"change, alter, transform","forms":["immūtat","immūtāta","immūtātus","immūtō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ubi {{immūtātus}} sum?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"imo","latin":"imo","headword":"imo","letter":"i","pos":"adverb","posGroup":"adverb","english":"no indeed (contradiction); on the contrary, more correctly; indeed, nay more","forms":["īmō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum vēro ōlim Arethūsa, postquam diū per silvāsas cucurrerat, domum sōia redīret, ad rapidum fluvium pervēnit, cuius frīgidae aquae, nūllō modō turbidae ac percussae radiīs sōlis, quī in mediō caelō sine nūbibus fulgēbat, ita illūstrābantur ut nympha ipsōs calculōs in īmō flūmine iacentēs cemere posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"imp","latin":"imp., abb.","headword":"imp","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"emperor (abb.); general; ruler; commander (-in-chief)","forms":["imp"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":": véla datō ({{imp}} fit) quà ferent aurae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"impar","latin":"impār","headword":"impār","letter":"i","pos":"adjective","posGroup":"adjective","english":"(gen. imparis) unequal; unequal, uneven","forms":["impar","imparēs","imparibus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quīntus mīrātur quod pedēs, quī heri parēs erant, hodiē tam {{imparēs}} sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"imparatus","latin":"imparatus, imparata -um, imparatior -or -us, imparatissimus -a -um","headword":"imparatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not prepared; unready","forms":["imparātam","imparātum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Figulō cōnsulibus, prīmō singulōs appellāre, hortārī aliōs, aliōs temptāre: opēs suās, {{imparātam}} rem pūblicam, magna praemia coniūrātiōnis docēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"impartire = impertire","latin":"(impartīo) impartīre = impertīre (Cap. LIV)","headword":"impartīre = impertīre","letter":"i","pos":"","posGroup":"other","english":"give a share of, impart","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"impatiens","latin":"impatiēns","headword":"impatiēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"(gen.impatientis) impatient","forms":["impatiēns","impatientem","impatientēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum igitur plūra ēsse optārent, quīdam ex dīīs, {{impatiēns}} “Age, Tantale” inquit, “aliōs cibōs accipere volumus: iam prīdem eōs appositōs esse oportēbat!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"impatientia","latin":"impatientia, -ae","headword":"impatientia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"impatience, lack of endurance","forms":["impatientiā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vērum cum impatientiā Varrōnis cōnsulis — contrādīcente alterō cōnsule — apud vīcum quī Cannae appellātur in Āpūliā pugnātum esset, ambō cōnsulēs ab Hannibale vincuntur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impavidus","latin":"impavidus, -a, -um","headword":"impavidus","letter":"i","pos":"adjective","posGroup":"adjective","english":"fearless","forms":["impavidōs","impavidus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Brūtus adest, tandemque animō sua nōmina fallit, fīxaque sēmi-animī corpore tēla rapit, stīllantemque tenēns generōsō sanguine cultrum ēdidit {{impavidōs}} ōre minante sonōs: 'Per tibi ego hunc iūrō fortem castumque cruōrem perque tuōs Mānēs, quī mihi nūmen erunt, Tarquinium profugā poenās cum stirpe datūrum!' Illa iacēns ad verba oculōs sine lūmine mōvit vīsaque concussā dicta probāre comā.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impedimentum","latin":"impedīmentum, -ī","headword":"impedīmentum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"obstacle","forms":["impedimenta","impedimentis","impedimentorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Duabus Agedinci legionibus atque {{impedimentis}} totius exercitus relictis, ad Boios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impedio","latin":"impedio, impedire, impedivi, impeditus","headword":"impedio","letter":"i","pos":"verb","posGroup":"verb","english":"hinder, impede, hamper, obstruct, prevent from (w/ne, quin, or quominus)","forms":["impediēbant","impediebat","impedienda","impediō","impedire","impediret","impediretur","impedit","impediunt","impedīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter {{impediebat}}, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impedire","latin":"(impediō) impedīre, -pedīvisse, -pedītum","headword":"impedīre","letter":"i","pos":"","posGroup":"other","english":"impede, obstruct","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"impeditus","latin":"impedītus, -a, -um","headword":"impedītus","letter":"i","pos":"adjective","posGroup":"adjective","english":"obstructed, encumbered","forms":["impedita","impedītī","impeditos","impeditum","impedītus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hunc ex omnibus fere partibus palus difficilis atque {{impedita}} cingebat, non latior pedibus quinquaginta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impellere","latin":"(impellō) impellere (< pellere)","headword":"impellere","letter":"i","pos":"","posGroup":"other","english":"strike, drive, compel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"impello","latin":"impellō, -ere, impulī, impulsum","headword":"impellō","letter":"i","pos":"verb","posGroup":"verb","english":"strike, push, overthrow","forms":["impellat","impellentēs","impelleretur","impellī","impellit","impellite","impulēre","impulit","impulsa","impulsae","impulsi","impulsū","impulsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac {{impulsi}} occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impendeo","latin":"impendeo, impendere, -, -","headword":"impendeo","letter":"i","pos":"verb","posGroup":"verb","english":"overhang, hang over; threaten; be imminent, impend; (w/DAT)","forms":["impendeat","impendēbat","impendēns","impendent","impendentem","impendēre","impendēret","impendet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postquam vēro Coriolānī verba audivērunt, mīrābantur senātōrēs, et perterritī ac valdē turbātī erant cīvēs, perīculum sibi {{impendēns}} timentēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"impendere","latin":"(impendeō) impendēre,  impendisse  ({i}intr. + dat.{/i})","headword":"impendēre","letter":"i","pos":"verb","posGroup":"verb","english":"threaten; to threaten, hang over","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"impensa","latin":"impēnsa, -ae","headword":"impēnsa","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"cost, expenditure; expense, cost","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"impensus","latin":"impensus, impensa, impensum","headword":"impensus","letter":"i","pos":"adjective","posGroup":"adjective","english":"immoderate, excessive","forms":["impēnsō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīs dictīs impēnsō animum flammāvit amōre","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"imperare","latin":"imperāre","headword":"imperāre","letter":"i","pos":"verb","posGroup":"verb","english":"to order, command (+ dat.)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"imperat","latin":"imperat","headword":"imperat","letter":"i","pos":"verb","posGroup":"verb","english":"(+ dat.) command, order, rule; commands, orders; commands; orders, commands","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"imperativus","latin":"imperātīvus, -ī (modus)","headword":"imperātīvus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"imperative","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"imperator","latin":"imperātor, imperātōris","headword":"imperātor","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"(m.) general, emperor; commander, general","forms":["imperator","imperatore","imperatorem","imperātōrēs","imperātōrī","imperātōribus","imperātōris","imperatorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente {{imperatore}} ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"imperatorius","latin":"imperātōrius, -a, -um","headword":"imperātōrius","letter":"i","pos":"adjective","posGroup":"adjective","english":"of a general","forms":["imperātōria","imperātōriae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neque enim illae sunt sōlae virtūtēs {{imperātōriae}} quae vulgō existimantur: labor in negōtiīs, fortitūdō in perīculīs, industria in agendō, celeritās in cōnficiendō, cōnsilium in prōvidendō — quae tanta sunt in hōc ūnō quanta in omnibus reliquīs imperātōribus quōs aut vīdimus aut audīvimus nōn fuērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"imperfectum","latin":"imperfectum, -ī","headword":"imperfectum","letter":"i","pos":"","posGroup":"other","english":"imperfect (tense)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"imperfectus","latin":"imperfectus, -a, -um","headword":"imperfectus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unfinished","forms":["imperfectā","imperfectum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Magister: 'Quot sunt tempora in dēclīnātiōne verbōrum?' Discipulus: 'Quīnque.' Magister: 'Quae?' Discipulus: 'Praesēns, ut lēgō; praeteritum {{imperfectum}}, ut legēbam; praeteritum perfectum, ut lēgī; praeteritum plusquamperfectum, ut lēgeram; futūrum, ut legam.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"imperitare","latin":"(imperitō) imperitāre","headword":"imperitāre","letter":"i","pos":"","posGroup":"other","english":"govern, be in command","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"imperitia","latin":"imperītia, -ae","headword":"imperītia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"inexperience, ignorance","forms":["imperītiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam quae ad hoc tempus Iugurtham tūtāta sunt, omnia remōvistis: avāritiam, {{imperītiam}} atque superbiam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"imperito","latin":"imperito, imperitare, imperitavi, imperitatus","headword":"imperito","letter":"i","pos":"verb","posGroup":"verb","english":"command, govern","forms":["imperītā","imperitābant","Imperitābat","imperitante","imperitāret","imperitātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Absalōn, fīlius Davidis, paternum rēgnum affectāvit: concitātā multitūdine imperītā, adversus patrem rebellāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"imperitus","latin":"imperitus, imperita, imperitum","headword":"imperitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unskilled, inexperienced (in); unfamiliar, ignorant (of) (w/GEN)","forms":["imperiti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Non virtute neque in acie vicisse Romanos, sed artificio quodam et scientia oppugnationis, cuius rei fuerint ipsi {{imperiti}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"imperium","latin":"imperium, -ī","headword":"imperium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"command, empire; empire, command","forms":["imperi","imperia","imperiī","imperiīs","imperio","imperium","IMPERIVM"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani {{imperio}} subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impero","latin":"imperō (1)","headword":"imperō","letter":"i","pos":"verb","posGroup":"verb","english":"command, order, bid (+ dat.)","forms":["imperā","imperabat","imperābis","imperābit","imperābō","imperandum","imperant","imperante","imperāre","imperarentur","imperaret","imperās","imperat","imperāta","imperati","imperāverant","imperāverat","imperāvērunt","imperāvisse","imperāvisset","imperāvistī","imperāvit","imperent","imperet","imperō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides {{imperat}}, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impertio","latin":"impertio, impertire, impertivi, impertitus","headword":"impertio","letter":"i","pos":"verb","posGroup":"verb","english":"bestow, impart, give a share (of); communicate (w/DAT)","forms":["impertiēbat","impertītum","impertītur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum in captīvitātem abductus esset, eandem in Deum pietātem semper retinuit: omnia bona, quae habēre poterat, cotīdiē exsiliī suī comitibus {{impertiēbat}}, eōsque monitīs salūtāribus ad colendum Deum hortābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impertire","latin":"(impertiō) impertīre, -īsse, -ītum (< pars)","headword":"impertīre","letter":"i","pos":"","posGroup":"other","english":"give a share of, impart","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"impeto","latin":"impeto, impetere, impetivi, impetitus","headword":"impeto","letter":"i","pos":"verb","posGroup":"verb","english":"attack, assail; rush upon (L+S); accuse","forms":["impete"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō {{impete}} caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"impetrare","latin":"(impetrō) impetrāre","headword":"impetrāre","letter":"i","pos":"verb","posGroup":"verb","english":"obtain (by request); to obtain, win by asking","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"impetro","latin":"impetro, impetrare, impetravi, impetratus","headword":"impetro","letter":"i","pos":"verb","posGroup":"verb","english":"obtain/procure (by asking/request/entreaty); succeed/achieve/be granted; obtain","forms":["impetrandā","impetrāre","impetrari","impetrata","impetrātīs","impetrāvēre","impetrāvērunt","impetrāvissent","impetrāvit","impetrēs","impetret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Interea aequum esse ab eis communis salutis causa {{impetrari}} ut castra munire instituerent, quo facilius repentinos hostium impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impetus","latin":"impetus, impetūs","headword":"impetus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"attack, charge; charge, attack","forms":["impetu","impetum","impetus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque cohortatus Aeduos de supportando commeatu, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium {{impetum}} magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impietas","latin":"impietas, impietatis","headword":"impietas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"failure in duty or respect, etc","forms":["impietātem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ad {{impietātem}} accessit crūdēlitās: cum enim Isaliī s prophēta Īram dīvīnam illī dēnūntiāsset, rēx furōre percitus prophētam serrā ligneā secarī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impiger","latin":"impiger, -gra, -grum","headword":"impiger","letter":"i","pos":"adjective","posGroup":"adjective","english":"active, energetic; diligent, active","forms":["impiger","impigrō","impigrōs","impigrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sextus: 'Ego frequentēs epistulās ad patrem meum absentem scrībō.' Sextus puer probus est ac tam {{impiger}} quam apis.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"impigre","latin":"impigre","headword":"impigre","letter":"i","pos":"adverb","posGroup":"adverb","english":"actively, energetically,smartly","forms":["impigrē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eum et rōbora virōrum sequēbantur, et ipse, quācumque in parte premī ac labōrāre sēnserat suōs, impigrē ferēbat opem, īnsignemque armīs et hostēs summā vī petēbant et tuēbantur cīvēs — dōnec Īnsubēr eques faciē quoque nōscitāns cōnsulem 'Ēn' inquit 'hic est' populāribus suīs 'quī legiōnēs nostrās cecīdit agrōsque et urbem est dēpopulātus!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impingo","latin":"impingo, impingere, impegi, impactus","headword":"impingo","letter":"i","pos":"verb","posGroup":"verb","english":"thrust, strike or dash against","forms":["impingit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego et dîxî quia müstella comēdit! iam Graeculîs calcem {{impingit}}, et Latīnās coepit nôn male appetere. ��; Ëmî ergô nunc c ‘x “f: Pedīs puerô aliquot lībra rubrīcāta, quia volô illum pars posterior ad domüsiônem aliquid dē iūre gustāre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"impio","latin":"impio, impiare, impiavi, impiatus","headword":"impio","letter":"i","pos":"verb","posGroup":"verb","english":"render impervious; stain with sin","forms":["impiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"IOsaphātus tamen cum Achabō Isrāēlītārum rēge impiō amīcitiam iūnxit, quae rēs illī magnō damnō fuit: nam, coniuncfīs cōpiīs, pugnārunt adversus rēgem Syriae: in proeliō Achabus interfectus est, parumque āfuit quīn perīret et ipse IOsaphātus, nec sine auxiliō dīvīnō incolumīs ēvāsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impius","latin":"impius, -a, -um","headword":"impius","letter":"i","pos":"adjective","posGroup":"adjective","english":"impious; wicked, impious; impious, godless; impious, wicked","forms":["impia","impiam","impiās","impiī","impiīs","impiōs","impium","impius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx {{impius}} renuit pārēre mandātīs Deī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"implacabilis","latin":"implacabilis, implacabilis, implacabile","headword":"implacabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"relentless, irreconcilable","forms":["implācābilem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dāvīd, ut vīdit {{implācābilem}} esse Saūlis in sē animum, excessit āulā, et sōlitūdinem petīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impleo","latin":"impleō, implēre","headword":"impleō","letter":"i","pos":"verb","posGroup":"verb","english":"fill, complete","forms":["impleat","impleātur","implēbat","implēbunt","implendā","implendum","implentur","implēre","implērent","implēret","implērī","implet","impletī","implētur","implētus","implēverat","implēvērunt","implēvī","implēvissent","implēvisset","implēvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ego aliquam domum ārdēre putō.” brevī tempore viae oppidī {{implentur}} hominibus, quī omnēs in eam partem currunt unde fūmus oritur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"implicare","latin":"(implicō) implicāre, implicuisse, implicitum","headword":"implicāre","letter":"i","pos":"verb","posGroup":"verb","english":"enfold; to entangle; to entangle, involve","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"implicatus","latin":"implicatus, implicata, implicatum","headword":"implicatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"entangled, confused, obscure; implicated, involved","forms":["implicati"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quini erant ordines coniuncti inter se atque {{implicati}}; quo qui intraverant, se ipsi acutissimis vallis induebant; hos cippos appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"implicitus","latin":"implicitus, implicita, implicitum","headword":"implicitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"entangled, confused, obscure; implicated, involved","forms":["implicitā","implicitī","implicitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"implico","latin":"implico, implicare, implicavi, implicatus","headword":"implico","letter":"i","pos":"verb","posGroup":"verb","english":"implicate; involve/engage/entangle/embroil; interweave/fold/twine w/itself","forms":["implicare","implicat","implicet"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cornelius: \"Alter alterum in rete {{implicare}} conatur, nam qui reti implicitus est non potest se defendere et sine mora interficitur, nisi tam fortiter pugnavit ut spectatores eum vivere velint.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"implorare","latin":"(implōrō) implōrāre","headword":"implōrāre","letter":"i","pos":"","posGroup":"other","english":"beseech, implore","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"imploro","latin":"implōrō (1)","headword":"implōrō","letter":"i","pos":"verb","posGroup":"verb","english":"implore, beg for","forms":["implōrat","implōrāvērunt","implōrēs","implōret"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Varia deinceps fuit Hebraeōrum fortūna prō variīs eōrum mōribus: iī saepe in Deum peccāvērunt; tunc dīvīnō praesidiō dēstitūtī ab hostibus superābantur; quotiēs ad Deum conversī eius auxilium {{implōrāvērunt}}, plācātus Deus eōs līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impluvium","latin":"impluvium, -ī","headword":"impluvium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"water basin in the atrium for collecting rainwater; water-basin in the atrium","forms":["impluviō","impluvium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In vīllā Iūliī magnum ātrium est cum impluviō.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"imponit","latin":"impōnit, -unt","headword":"impōnit","letter":"i","pos":"verb","posGroup":"verb","english":"place (in/on), put; puts on, places on","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"impono","latin":"impono, imponere, imposui, impositus","headword":"impono","letter":"i","pos":"verb","posGroup":"verb","english":"impose, put upon; establish; inflict; assign/place in command; set","forms":["impōnam","impōnās","impōnat","impōne","impōnēns","impōnere","impōnerentur","impōneret","impōnet","impōnī","impōnit","imposita","impositīs","imposito","impositōs","impositum","impositus","imposuerant","imposuerat","imposuēre","imposuisse","imposuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, {{imposito}} stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"importunus","latin":"importunus, importuna, importunum","headword":"importunus","letter":"i","pos":"adjective","posGroup":"adjective","english":"inconvenient; annoying; rude; monstrous, unnatural; ruthless, cruel, hard","forms":["importūnā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sīn autem servīre meae laudī et glōriae māvīs, ēgredere cum importūnā scelerātōrum manū, cōnfer tē ad Mānlium, concitā perditōs cīvēs, sēcerne tē ā bonīs, īnfer patriae bellum, exsultā impiō latrōciniō, ut ā mē nōn ēiectus ad aliēnōs, sed invītātus ad tuōs īsse videāris!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"impostor","latin":"impostor, impostoris","headword":"impostor","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"deceiver; impostor","forms":["impostor"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prōcūrātor meus es?” [Iūlius:] “Dūc tē!” [Sōsia:] “Recēde, {{impostor}}!” [Iūlius:] “Maledīcis mihi, malum caput?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"impraesentiarum","latin":"impraesentiarum","headword":"impraesentiarum","letter":"i","pos":"adverb","posGroup":"adverb","english":"in present circumstances, for the present","forms":["impraesentiārum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum hōc — exhāustīs iam patriae facultātibus — cupīvit {{impraesentiārum}} bellum compōnere, quō valentior posteā congrederētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impransus","latin":"impransus, impransa, impransum","headword":"impransus","letter":"i","pos":"adjective","posGroup":"adjective","english":"without breakfast, fasting","forms":["imprānsus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"hoc adeō hoc commeminī magis, quia illō diē {{imprānsus}} fuī—","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"imprecor","latin":"imprecor, imprecari, imprecatus sum","headword":"imprecor","letter":"i","pos":"verb","posGroup":"verb","english":"call down/upon, invoke; pray for; utter curses","forms":["imprecor"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{imprecor}}, arma armīs: pugnent ipsīque nepōtēsque.'","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"impresentiarum at","latin":"impresentiārum at","headword":"impresentiārum at","letter":"i","pos":"","posGroup":"other","english":"the present moment","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"imprimis","latin":"imprīmīs","headword":"imprīmīs","letter":"i","pos":"adverb","posGroup":"adverb","english":"especially, among the first","forms":["imprīmīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Aliī Aegīdem rogāvērunt ut auxilium daret, {{imprīmīs}} septem prīncipēs quī bellum contrā Thēbānōs gessērunt, quōrum rēx Creōn eōs vetuerat corpora interfectorum humāre.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"imprimo","latin":"imprimō, imprimere","headword":"imprimō","letter":"i","pos":"verb","posGroup":"verb","english":"seal, emboss","forms":["impressa","imprimēns","imprimuntur"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister, antequam epistulam signat, pauca verba addit. 'Quid nunc scrībis?' interrogat Mārcus. 'Scrībō tē mercēdem ad diem nōn afferre,' respondet magister, atque epistulam signat ānulum suum in cēram {{imprimēns}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"improbitas","latin":"improbitas, improbitatis","headword":"improbitas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"wickedness unscrupulousness, dishonesty; shamelessness; want of principle","forms":["improbitās","improbitāte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haedum bālantem audīvit Tobiās, et, veritus nē fūrtō ablātus esset, dīxit uxōrī: “Vidē nē iste clam alicui ēreptus sit: redde illum dominō suō; nefās enim est nōbīs ex raptō vīvere.” Adeō vir iūstus ab omnī {{improbitāte}} abhorrēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"improbo","latin":"improbo, improbare, improbavi, improbatus","headword":"improbo","letter":"i","pos":"verb","posGroup":"verb","english":"disapprove of, express disapproval of, condemn; reject","forms":["improbō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aemilia vērō, quae tabellam Mārcī esse crēdit, ā fīliō suō improbō fallitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"improbus","latin":"improbus, -a, -um","headword":"improbus","letter":"i","pos":"adjective","posGroup":"adjective","english":"bad, wicked; bad, naughty; wicked, bad; naughty, bad","forms":["improba","improbae","improbe","improbī","improbīs","improbōrum","improbōs","improbum","improbus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aemilia īrāta Syram interrogat: “Quae est ancilla {{improba}} quae cantat et rīdet?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"improvisus","latin":"imprōvīsus, -a, -um","headword":"imprōvīsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unforeseen, unexpected","forms":["imprōvīsa","improviso","imprōvīsum","imprōvīsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus corona militum cingeretur, ne de {{improviso}} aut noctu ad munitiones hostium multitudo advolaret aut interdiu tela in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"imprudens","latin":"imprūdēns (gen. imprūdentis)","headword":"imprūdēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"ignorant, imprudent; unaware, imprudent","forms":["imprūdēns","imprūdentibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cyparissus autem, {{imprūdēns}}, dum suō arcū in silvā lūdit, sagittā cervum sub arbore cubantem forte percussit; cum vērō, accurrēns, eum morientem vīdit, ita turbātus est animō, ut ipse cum cervō moīī vellet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"imprudenter","latin":"imprudenter, imprudentius, imprudentissime","headword":"imprudenter","letter":"i","pos":"adverb","posGroup":"adverb","english":"rashly, unwisely; carelessly, unmindfully; unintentionally, without design","forms":["imprūdenter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Arachnē nihil timuit: “Videāmus” inquit, “utra nostrum melior sit: tū illam vestem, ego hanc acū pingāmus; tū ipsa sentiēs opera mea multō meliōra et pulchriōra tuīs esse: nisi forte timēs nē mēcum tē compārēs!” Minerva vērō “{{Imprūdenter}} facis” ait, “quod cum deā certāre vīs, neque sciō quae superbia tibi suāserit ut hoc facerēs: poenam tuī sceleris sentiēs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"imprudentia","latin":"imprudentia, imprudentiae","headword":"imprudentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ignorance; lack of knowledge/thought/awareness/judgment/foresight/intention","forms":["imprudentia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sibi numquam placuisse Avaricum defendi, cuius rei testes ipsos haberet; sed factum {{imprudentia}} Biturigum et nimia obsequentia reliquorum uti hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"impudens","latin":"impudēns (gen. impudentis)","headword":"impudēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"shameless, impudent","forms":["impudēns","impudente","impudentem"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quid illāc {{impudente}} audācius?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"impudenter","latin":"impudenter","headword":"impudenter","letter":"i","pos":"adverb","posGroup":"adverb","english":"shamelessly, impudently","forms":["impudenter"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Gabīnius deinde intrōductus, cum prīmō {{impudenter}} respondēre coepisset, ad extrēmum nihil ex eīs quae Gallī īnsimulābant negāvit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"impudentia","latin":"impudentia, -ae","headword":"impudentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"shamelessness; shamelessness, effrontery","forms":["impudentia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Baebium tribūnum plēbis magnā mercēde parat, cuius {{impudentia}} contrā iūs et iniūriās omnēs mūnītus foret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impudicus","latin":"impudīcus, -a, -um","headword":"impudīcus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unchaste, immoral","forms":["impudīca","impudīcam","impudīcīs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"AMPHITRYO: [quī iam uxōrem suam {{impudīcam}} exīstimat] Perdidistī!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"impugnare","latin":"(impugnō) impugnāre","headword":"impugnāre","letter":"i","pos":"","posGroup":"other","english":"attack, oppose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"impugno","latin":"impugno, impugnare, impugnavi, impugnatus","headword":"impugno","letter":"i","pos":"verb","posGroup":"verb","english":"fight against, attack, assail","forms":["impugnāverat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum socius et administer omnium cōnsiliōrum assūmitur Scaurus, quī tametsī ā principiō ācerrimē rēgem {{impugnāverat}}, tamen magnitūdine pecūniae ā bonō honestōque in prāvum abstractus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impulsus","latin":"impulsus, -ūs (< impellere Cap. XXXIX)","headword":"impulsus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"impact, impulse","forms":["impulsūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post hunc Ochosiās fīlius rēgnum adeptus est, nec diū tenuit, nam pessimī p ātrīs exemplō ad vitia {{impulsūs}}, miserē interiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impune","latin":"impūne","headword":"impūne","letter":"i","pos":"adverb","posGroup":"adverb","english":"with impunity","forms":["impūnē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Suī Davidem comitēs hortābantur, ut opportūnam Saūlis interficiendī occāsiōnem arríperet: sed Dāvīd nōluit, cum impūnē posset, inimīcum occīdere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"impunitas","latin":"impūnitās, -ātis ( f.)","headword":"impūnitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"impunity, license; licence, unchecked freedom","forms":["impūnitāte","impūnitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is dedit operam — sī modo id cōnsequī potuit — ut nimis redundantēs nōs et superfluentēs iuvenīlī quādam dīcendī {{impūnitāte}} et licentiā reprimeret et quasi extrā rīpās diffluentēs coercēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"impunitus","latin":"impunitus, impunita -um, impunitior -or -us, impunitissimus -a -um","headword":"impunitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unpunished, unrestrained, unbridled; safe, secure, free from danger","forms":["impūnīta","impūnītōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae tēcum, Catilīna, sīc agit et quōdam modo tacita loquitur: ‘Nūllum iam aliquot annīs facinus exstitit nisi per tē, nūllum flāgitium sine tē; tibi ūnī multōrum cīvium necēs, tibi vexātiō dīreptiōque sociōrum {{impūnīta}} fuit ac lībera; tū nōn sōlum ad neglegendās lēgēs et quaestiōnēs, vērum etiam ad ēvertendās perfringendāsque valuistī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"impurus","latin":"impurus, impura, impurum","headword":"impurus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unclean, filthy, foul; impure; morally foul","forms":["impūrus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Namque animus {{impūrus}}, dīs hominibusque īnfēstus, neque vigiliīs neque quiētibus sēdārī poterat: ita cōnscientia mentem excitam vastābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"imus","latin":"īmus, -a, -um","headword":"īmus","letter":"i","pos":"adjective","posGroup":"adjective","english":"bottom of","forms":["īma","īmīs","īmōs","Īmum","īmus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"“Quō īmus?” interrogat Diodōrus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"in","latin":"in","headword":"in","letter":"i","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) in, on, at; in, on (+ ablative); in, into; into (+ acc.); in, on, into","forms":["in"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, {{in}} Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"in promptu","latin":"in prōmptū","headword":"in prōmptū","letter":"i","pos":"","posGroup":"other","english":"visible, manifest, easy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inadsuetus","latin":"inadsuetus, inadsueta, inadsuetum","headword":"inadsuetus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unaccustomed","forms":["inadsuēta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"in-adsuētus -ā -um («» solitus) 7 quī fertur {{inadsuēta}} subsecuisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inamabilis","latin":"inamabilis, inamabilis, inamabile","headword":"inamabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"disagreeable, unattractive","forms":["inamābile"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sonat raucum quiddam atque {{inamābile}}: rīdet","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inambulare","latin":"(inambulō) inambulāre","headword":"inambulāre","letter":"i","pos":"","posGroup":"other","english":"walk up and down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inambulo","latin":"inambulo, inambulare, inambulavi, inambulatus","headword":"inambulo","letter":"i","pos":"verb","posGroup":"verb","english":"walk up and down","forms":["Inambulābat","inambulāns","inambulāvisset"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Inambulābat}} in cēnāculō maerēns, et in hās vōcēs identidem ērumpēns: “Fīlī mī Absalōn, Absalōn fīlī mī: utinam prō tē moriar, Absalōn fīlī mī, fīlī mī Absalōn.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inane","latin":"inane, inanis","headword":"inane","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"empty space/expanse/part of structure, hollow, void; space devoid of matter","forms":["ināne"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōmen 'amīcitia' est, nōmen {{ināne}} 'fidēs'.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inanimus","latin":"inanimus, -a, -um","headword":"inanimus","letter":"i","pos":"adjective","posGroup":"adjective","english":"lifeless, inanimate","forms":["Inanimum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Inanimum}} est enim omne quod pulsū agitātur externō; quod autem est animāl, id mōtū ciētur interiōre et suō, nam haec est propria nātūra animī atque vīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inanis","latin":"inānis, -e","headword":"inānis","letter":"i","pos":"adjective","posGroup":"adjective","english":"empty, gaping","forms":["inānem","inānēs","inānī","inānia"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quod adventū tuō ista subsellia vacuēfacta sunt, quod omnēs cōnsulārēs, quī tibi persaepe ad caedem cōnstitūtī fuērunt, simul atque assēdistī, partem istam subselliōrum nūdam atque {{inānem}} relīquērunt, quō tandem animō tibi ferendum putās?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inauditus","latin":"inaudītus, -a, -um","headword":"inaudītus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unheard (of )","forms":["inaudītīs","inaudītum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ārās falsīs dīīs per ūniversam IŪdaeam exstrūxit; omnia templī Hierosolymitanī omāmenta dētrāxit; librōs sacrōs iussit comburī; reluctantēs {{inaudītīs}} suppliciīs afrecit; urbem innumerā caede vastāvit: ac nē Iudaeī tot malīs oppressī rebellārent, praesidium in arce collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inauris","latin":"inauris, inauris","headword":"inauris","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ear rings (pl.); ornaments worn in ears; ear drops (L+S); nose ring (Souter)","forms":["inaurēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Eliezer prōtulit {{inaurēs}} aureās et armillās, quās dēdit Rebeccae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inauro","latin":"inauro, inaurare, inauravi, inauratus","headword":"inauro","letter":"i","pos":"verb","posGroup":"verb","english":"gild, make rich","forms":["inaurā","inaurātae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"mōvit {{inaurātae}} pollice fīla lyrae.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"incalescere","latin":"(incalēscō) incalēscere, -uisse","headword":"incalēscere","letter":"i","pos":"","posGroup":"other","english":"become heated","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incalesco","latin":"incalesco, incalescere, incalui, -","headword":"incalesco","letter":"i","pos":"verb","posGroup":"verb","english":"grow hot; become heated","forms":["Incaluerant"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde certāmine accēnsō, Collātīnus negat verbīs opus esse: 'paucīs id quidem hōrīs posse scīrī quantum cēterīs praestet Lūcrētia sua!' 'Quīn, sī vigor iuventae inest, cōnscendimus equōs invīsimusque praesentēs nostrārum ingenia?' {{Incaluerant}} vīnō. 'Age sānē!' inquiunt omnēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incandesco","latin":"incandēscō, -ere, incanduī","headword":"incandēscō","letter":"i","pos":"verb","posGroup":"verb","english":"begin to glow, grow hot","forms":["incanduit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hīc dē mōre patriō cum Iovī sacra parāvissent, ut āra accēnsīs ignibus {{incanduit}}, Danai dracōnem in arbore vīdēre quae proxima ārīs sacrīs stābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"incautus","latin":"incautus, -a, -um","headword":"incautus","letter":"i","pos":"adjective","posGroup":"adjective","english":"incautious, unsuspecting","forms":["incautam","incautē","incautī","incautīs","incautius","incautōs","incautum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"cum puer {{incautīs}} nimium tēmērárius annīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"incedere","latin":"(incēdō) incēdere (< cēdere)","headword":"incēdere","letter":"i","pos":"","posGroup":"other","english":"walk, advance, occur","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incedo","latin":"incedo, incedere, incessi, incessus","headword":"incedo","letter":"i","pos":"verb","posGroup":"verb","english":"advance, march; approach; step, walk, march along","forms":["incēde","incēdēbant","incēdēbat","incēdendī","incēdentem","incēdentī","incēdere","incēdit","incēdō","incēdunt","incesserat","incessī","incessit","incessū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hebraeī {{incēdēbant}} per ārentem alveum, dōnec rīpam oppositam attingerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"incendere","latin":"(incendō) incendere, -cendisse, -censum","headword":"incendere","letter":"i","pos":"","posGroup":"other","english":"set on fire, inflame","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incendium","latin":"incendium, -ī","headword":"incendium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"fire, conflagration","forms":["incendia","incendiis","incendio","incendiōrum","incendium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus {{incendia}} conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi solaci proponebant, quod se prope explorata victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incendo","latin":"incendō, -ere, -cendī, -cēnsum","headword":"incendō","letter":"i","pos":"verb","posGroup":"verb","english":"to set on fire, inflame","forms":["incendat","incendendae","incendendum","incenderant","incendere","incenderit","incenderunt","incendi","incendis","incendissent","incendit","incenditur","incendunt","incenduntur","incēnsa","incēnsae","incēnsam","incēnsī","incensis","incēnsōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile {{incendit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incenso","latin":"incenso, incensare, incensavi, incensatus","headword":"incenso","letter":"i","pos":"verb","posGroup":"verb","english":"burn incense","forms":["incēnsō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At ego, deōrum rēgīna Iovisque et soror et coniūnx, ūnā cum gente tot annōs bellum gerō!' Tālia animō incēnsō sēcum volvēns dea in Aeoliam, nimbōrum patriam, vēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incensum","latin":"incensum, incensi","headword":"incensum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"incense; sacrifice (w/incense/burning victims); lighting (L+S); setting fire","forms":["incēnsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum oppidum {{incēnsum}}, Numidae pūberēs interfectī, aliī omnēs vēnumdatī, praeda mīlitibus dīvīsa.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incepto","latin":"incepto, inceptare, inceptavi, inceptatus","headword":"incepto","letter":"i","pos":"verb","posGroup":"verb","english":"begin; undertake; attempt","forms":["inceptō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sēnseris, inceptō parce","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inceptum","latin":"inceptum, -ī","headword":"inceptum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"undertaking, enterprise; undertaking, plan","forms":["incepta","inceptīs","inceptum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{inceptum}} -ī 7: — quod coeptum est","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"incerto","latin":"incerto, incertare, incertavi, incertatus","headword":"incerto","letter":"i","pos":"verb","posGroup":"verb","english":"render uncertain","forms":["incerto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At {{incerto}} etiam nunc exitu victoriae, cum Septimae legionis tribunis esset nuntiatum quae in sinistro cornu gererentur, post tergum hostium legionem ostenderunt signaque intulerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incertus","latin":"incertus, -a, -um","headword":"incertus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uncertain; uncertain, unsure","forms":["incerta","incertam","incertās","incertī","incertis","incertum","incertus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque observabat dispersosque, cum longius necessario procederent, adoriebatur magnoque incommodo adficiebat, etsi quantum ratione provideri poterat ab nostris occurrebatur, ut {{incertis}} temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incesso","latin":"incesso, incessere, incesivi, incessus","headword":"incesso","letter":"i","pos":"verb","posGroup":"verb","english":"assault, attack; reproach, abuse","forms":["incessēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed ubi illa formīdō mentibus dēcessit, scīlicet ea quae rēs secundae amant, lascīvia atque superbia, {{incessēre}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incessus","latin":"incessus, incessus","headword":"incessus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"walking; advance; procession","forms":["incessus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{incessus}} -üs 71 — modus incēdendī est et in incessū pars nón","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"incidere","latin":"(incīdō) incīdere, -disse, -sum","headword":"incīdere","letter":"i","pos":"","posGroup":"other","english":"cut into; occur, present itself","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incido","latin":"incido, incidere, incidi, incasus","headword":"incido","letter":"i","pos":"verb","posGroup":"verb","english":"happen; fall into, fall in with, meet; fall upon, assail","forms":["inciderat","incidere","incīderet","incidērunt","incīdimus","incidisse","incīdissēmus","incidit","incīdite"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior {{incidit}} res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incipere","latin":"(incipiō) incipere, coepisse,coeptum","headword":"incipere","letter":"i","pos":"","posGroup":"other","english":"begin","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"incipio","latin":"incipio, incipere, incepi, inceptus","headword":"incipio","letter":"i","pos":"verb","posGroup":"verb","english":"begin; start, undertake","forms":["inceptōs","Incipe","incipere","inciperent","inciperet","incipiam","incipiās","incipiēbat","Incipiēmus","incipiēns","incipiet","incipit","Incipite","incipiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire {{incipiunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incipit","latin":"incipit, incipere","headword":"incipit","letter":"i","pos":"verb","posGroup":"verb","english":"begin; begins","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"incitare","latin":"(incitō) incitāre","headword":"incitāre","letter":"i","pos":"","posGroup":"other","english":"set in motion, stir up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incitatus","latin":"incitātus, -a, -um (< incitāre Caps. XXXVII, XXXVIII)","headword":"incitātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"fast-moving, rapid","forms":["incitatas","incitati","incitātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sic et Cenabi caede et labore operis {{incitati}} non aetate confectis, non mulieribus, non infantibus pepercerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incito","latin":"incito, incitare, incitavi, incitatus","headword":"incito","letter":"i","pos":"verb","posGroup":"verb","english":"enrage; urge on; inspire; arouse","forms":["Incitābant","incitantur","incitāre","incitārent","incitāret","incitārī","incitat","incitāverat","incitāvērunt","incitet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{incitet}} et vēlō rēmigis addat opem,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inclamare","latin":"(inclāmō) inclāmāre","headword":"inclāmāre","letter":"i","pos":"","posGroup":"other","english":"shout (at)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inclamo","latin":"inclāmō (1)","headword":"inclāmō","letter":"i","pos":"verb","posGroup":"verb","english":"to shout out, cry out; to shout out","forms":["inclāmantēs","inclāmāre","inclāmat","inclāmāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mulier īrāta {{inclāmāvit}} servōs, et Iōsēphum accūsāvit apud virum, quī, nimium crēdulus, coniēcit Iōsēphum in carcerem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inclinare","latin":"(inclīnō) inclīnāre","headword":"inclīnāre","letter":"i","pos":"","posGroup":"other","english":"turn, bend, incline","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inclino","latin":"inclino, inclinare, inclinavi, inclinatus","headword":"inclino","letter":"i","pos":"verb","posGroup":"verb","english":"bend; lower; incline; decay; grow worse; set (of the sun); deject","forms":["inclīnābant","inclīnāret","inclīnārī","inclīnātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum autem diēs in vesperum {{inclīnāret}}, rē nōndum cōnfecta, Iosue iussit sōlem cōnsistere, et vērē stetit sōl, et diem prōdūxit, dōnec dēlētus esset hostium exercitus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"includere","latin":"(inclūdō) inclūdere, inclūsisse, inclūsum","headword":"inclūdere","letter":"i","pos":"verb","posGroup":"verb","english":"shut in; to shut in, lock up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"includit","latin":"inclūdit","headword":"inclūdit","letter":"i","pos":"verb","posGroup":"verb","english":"shuts in, locks up","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"includo","latin":"inclūdō, -ere, -sī, -sum","headword":"inclūdō","letter":"i","pos":"verb","posGroup":"verb","english":"to shut up, enclose","forms":["inclūde","inclūdī","inclūdit","inclūduntur","inclūsa","inclūsae","inclūserat","inclūsī","inclūsīs","inclūsit","inclūsō","inclūsōs","inclūsum","inclūsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Noēmus ēgressus est ex arcā, postquam ibi {{inclūsus}} fuerat per annum tōtum ipse et familia eius: ēdūxit sēcum avēs cēteraque animantia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inclutus","latin":"inclutus, -a, -um","headword":"inclutus","letter":"i","pos":"adjective","posGroup":"adjective","english":"famous; famous, renowned","forms":["inclūtam","inclūtī","inclutum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam tum erat {{inclutum}} fānum Diānae Ephesī; id commūniter ā cīvitātibus Asiae factum fāma ferēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incognitus","latin":"incognitus, -a, -um","headword":"incognitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unknown","forms":["incōgnita","incognitōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Commissā mox pugnā, cum iam Pyrrhus fugeret, elephantōrum auxiliō vīcit, quōs {{incognitōs}} Rōmānī expāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incohare","latin":"(incohō) incohāre","headword":"incohāre","letter":"i","pos":"","posGroup":"other","english":"start work on, begin","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incoho","latin":"incoho, incohare, incohavi, incohatus","headword":"incoho","letter":"i","pos":"verb","posGroup":"verb","english":"begin/start (work); set going, establish; draft/sketch/outline; enter upon","forms":["incohāta","incohātum","incohāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus victīs Octāviānus iūxtā forum Iūlium novum forum cum templō Martis {{incohāvit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incola","latin":"incola, -ae","headword":"incola","letter":"i","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) inhabitant","forms":["incolae","incolārum","incolās","incolis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Incolae}} perterritī, quamquam fūnibus et hastīs ūtēbantur, taurum hūc et illūc currentem capere nōn poterant; nec ē tālī perīculō līberātī sunt, dōnec Herculēs, quī in Crētam vēnerat, illam saevissimam bēstiam tandem cēpit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"incolit","latin":"incolit, incolere","headword":"incolit","letter":"i","pos":"","posGroup":"other","english":"inhabit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"incolo","latin":"incolo, incolere, incolui, -","headword":"incolo","letter":"i","pos":"verb","posGroup":"verb","english":"live, dwell/reside (in); inhabit; sojourn","forms":["incolat","incolēbant","incolēbat","incolentium","incolerent","incolit","incolitis","incoluit","incolunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sēmus {{incoluit}} Asiam; Chāmus, Āfricam; Iaphētus, Eurōpam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"incolumis","latin":"incolumis, -e","headword":"incolumis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unharmed, safe","forms":["incolume","incolumem","incolumes","incolumis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi aliquid ab eis iniri consili intellexissent, gladiis destrictis portas occupaverunt suosque omnes {{incolumes}} receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incolumitas","latin":"incolumitās, -ātis ( f.)","headword":"incolumitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"soundness, safety; safety","forms":["incolumitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Octāviī prōnūntiātum est per praecōnem 'rēgiōs puerōs Macedonāsque aliōs quī Samothrācae essent, sī transīrent ad Rōmānōs, {{incolumitātem}} lībertātemque et sua omnia servātūrōs quae aut sēcum habērent aut in Macedoniā relīquissent.' Ad hanc vōcem trānsitiō omnium facta est, nōminaque dabant ad C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incolunt","latin":"incolunt","headword":"incolunt","letter":"i","pos":"verb","posGroup":"verb","english":"inhabit","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"incomitatus","latin":"incomitatus, incomitata, incomitatum","headword":"incomitatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unaccompanied","forms":["incomitāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sōla sibī, semper longam {{incomitāta}} vidētur","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"incommodo","latin":"incommodo, incommodare, incommodavi, incommodatus","headword":"incommodo","letter":"i","pos":"verb","posGroup":"verb","english":"inconvenience, obstruct, hinder; be inconvenient/troublesome, cause difficulty","forms":["incommodo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque observabat dispersosque, cum longius necessario procederent, adoriebatur magnoque {{incommodo}} adficiebat, etsi quantum ratione provideri poterat ab nostris occurrebatur, ut incertis temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incommodum","latin":"incommodum, -ī","headword":"incommodum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"disadvantage, misfortune; disadvantage, loss","forms":["incommodis","incommodum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vercingetorix, tot continuis {{incommodis}} Vellaunoduni, Cenabi, Novioduni acceptis, suos ad concilium convocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inconditus","latin":"inconditus, -a, -um","headword":"inconditus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unpolished, rough","forms":["inconditā","incōndītam","inconditus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Interiectiō quid est?' Discipulus: 'Pars ōrātiōnis significāns mentīs affectum vōce inconditā.' Magister: 'Significātiō interiectiōnis in quō est?' Discipulus: 'Aut laetitiam significāmus, ut euax!; aut dolōrem, ut heu!; aut admīrātiōnem, ut pāpae!; aut metum, ut attat!; et sī quā sunt similia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"inconsideratus","latin":"inconsideratus, inconsiderata, inconsideratum","headword":"inconsideratus","letter":"i","pos":"adjective","posGroup":"adjective","english":"thoughtless, inconsiderate; unadvised, reckless (passive)","forms":["incōnsīderāta","incōnsīderātē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At illum deinde {{incōnsīderāta}} fīdūcia perdidit, nam contrā Aegyptiōs exercitum dūxit, admonitusque ā Deō ut proeliō abstinēret, nihilōminus aciē dīmicāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inconspectus","latin":"incōnspectus, -a, -um","headword":"incōnspectus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unfounded; unexamined, not properly considered","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"inconsulte","latin":"inconsulte, inconsultius, inconsultissime","headword":"inconsulte","letter":"i","pos":"adverb","posGroup":"adverb","english":"rashly, ill-advisedly, incautiously; without due care and consideration","forms":["incōnsultē","incōnsultius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur ūnus ex eō numerō quī ad īnsidiās et caedem parātī erant paulō {{incōnsultius}} Massīvam aggreditur: illum obtruncat, sed ipse dēprehēnsus, multīs hortantibus et in prīmīs Albīnō cōnsule, indicium profitētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inconsultus","latin":"incōnsultus, -a, -um","headword":"incōnsultus","letter":"i","pos":"","posGroup":"other","english":"thoughtless, rash","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incredibilis","latin":"incrēdibilis, -e","headword":"incrēdibilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"incredible, unbelievable; incredible","forms":["incrēdibile","incrēdibilem","incrēdibilī","incrēdibilia","incrēdibilis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit comam, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis rōbore: obvium leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"increpare","latin":"(increpō) increpāre","headword":"increpāre","letter":"i","pos":"","posGroup":"other","english":"rattle, clash, scold","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"increpito","latin":"increpito, increpitare, increpitavi, increpitatus","headword":"increpito","letter":"i","pos":"verb","posGroup":"verb","english":"chide, utter (noisy) reproaches at","forms":["increpitāns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tum Bitiae dedit {{increpitāns}}; ille impiger hausit","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"increpo","latin":"increpo, increpare, increpui, increpitus","headword":"increpo","letter":"i","pos":"verb","posGroup":"verb","english":"rebuke, chide, reprove; protest at/indignantly, complain loudly/scornfully","forms":["increpābat","increpandī","increpandō","increpāns","increpant","increpantēs","increpat","increpuēre","increpuerit","increpuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vīdit quīdam pendentem Absalōnem, nec ausus est illī manūs violentās īnferre, sed nūntiāvit Iōābō, quī eum {{increpāns}}: “Debuerās” inquit “iuvenem impium cōnfodere.” “Atquī” respondit ille “mē praesente, rēx praecēpit tibi, ut fīliō suō parcerēs.” “Ego vērō nōn parcam” ait Iōāb, et statim sūmpsit trēs lanceās, quās in pectus Absalōnis dēfīxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"increscere","latin":"(incrēscō) incrēscere (< crēscere)","headword":"incrēscere","letter":"i","pos":"","posGroup":"other","english":"grow, increase","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incresco","latin":"incresco, increscere, increvi, -","headword":"incresco","letter":"i","pos":"verb","posGroup":"verb","english":"grow (in or upon); grow, swell, increase, be augmented; be swollen","forms":["incrēvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārtō post diē quam cum rēge est pugnātum, cum in circō lūdī fierent, murmur repentē populum tōtā spectācula pervāsit 'pugnātum in Macedoniā et dēvictum rēgem esse'; dein fremitus {{incrēvit}}; postrēmō clāmor, plausus, velut certō nūntiō victōriae allātō, est exortus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incruentus","latin":"incruentus, incruenta, incruentum","headword":"incruentus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not stained with blood; bloodless, without shedding of blood; w/no casualties","forms":["incruentam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Neque tamen exercitus populī Rōmānī laetam aut {{incruentam}} victōriam adeptus erat; nam strēnuissimus quisque aut occiderat in proeliō aut graviter vulnerātus discesserat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"incubo","latin":"incubo, incubare, incubui, incubitus","headword":"incubo","letter":"i","pos":"verb","posGroup":"verb","english":"lie in or on (w/DAT); sit upon; brood over; keep a jealous watch (over)","forms":["incubant","incubāre","incubās","incubat","Incubuēre","incubuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Audīvit Dominum dīcentem sibi: Ego sum Deus patris tuī; dabō tibi et posterīs tuīs terram cui {{incubās}}: nōlī timēre; ego favēbō tibi; erō cūstōs tuus quōcumque perrēxerīs, et redūcam tē in patriam, ac per tē omnēs orbis nātiōnēs erunt bonīs cumulātae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"incultus","latin":"incultus, -a, -um","headword":"incultus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uncultivated, untilled","forms":["inculta","incultū"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eius cīvēs apud Iugurtham immūnēs, levī imperiō, et ob ea fīdissimī habēbantur, mūnītī adversum hostēs nōn moenibus modo et armīs atque virīs, vērum etiam multō magis locōrum asperitāte; nam praeter oppidō propinqua alia omnia vāsta, {{inculta}}, egentia aquae, īnfēsta serpentibus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incumbere","latin":"(incumbō) incumbere, -uisse,","headword":"incumbere","letter":"i","pos":"","posGroup":"other","english":"lie down on itum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incumbo","latin":"incumbo, incumbere, incumbui, incumbitus","headword":"incumbo","letter":"i","pos":"verb","posGroup":"verb","english":"lean forward/over/on, press on; attack, apply force; fall on (one's sword)","forms":["incumbēns","incumberent","incumbit","incumbunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tamen tanta universae Galliae consensio fuit libertatis vindicandae et pristinae belli laudis reciperandae, ut neque beneficis neque amicitiae memoria moverentur, omnesque et animo et opibus in id bellum {{incumberent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incunabulum","latin":"incunabulum, incunabuli","headword":"incunabulum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"apparatus of the cradle (pl.); one's earliest years; birthplace","forms":["incūnābulīs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Neque eum quisquam colligāre quīvit {{incūnābulīs}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"incurrere","latin":"(incurrō) incurrere (< currere)","headword":"incurrere","letter":"i","pos":"","posGroup":"other","english":"rush in, make an inroad","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incurro","latin":"incurro, incurrere, incucurri, incursus","headword":"incurro","letter":"i","pos":"verb","posGroup":"verb","english":"run into or towards, attack, invade; meet (with); befall","forms":["incurrērunt","incurrit","incurrunt","incursu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem duodenum pedum a maioribus castris ad minora perduxit, ut tuto ab repentino hostium {{incursu}} etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"incursio","latin":"incursiō, -ōnis ( f.)","headword":"incursiō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"incursion, inroad; raid, invasion","forms":["incursiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Igitur Latīnī, cum quibus Tullō rēgnante foedus ictum erat, sustulerant animōs, et cum {{incursiōnem}} in agrum Rōmānum fēcissent, repetentibus rēs Rōmānīs superbē respōnsum reddunt — ōtiōsum Rōmānum rēgem inter lānā et ārās rēgnum āctūrum esse ratī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incurso","latin":"incurso, incursare, incursavi, incursatus","headword":"incurso","letter":"i","pos":"verb","posGroup":"verb","english":"strike/run/dash against, attack; make raids upon","forms":["incursat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille quidem tōtam gemebundus obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus {{incursat}} foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"incusare","latin":"(incūsō) incūsāre","headword":"incūsāre","letter":"i","pos":"","posGroup":"other","english":"reproach, accuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"incuso","latin":"incuso, incusare, incusavi, incusatus","headword":"incuso","letter":"i","pos":"verb","posGroup":"verb","english":"accuse, blame, criticize, condemn","forms":["incūsāre","incūsat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille ubi mātrem agnōvit, fugientem tālibus verbīs {{incūsat}}: 'Ō māter crūdēlis!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"incutio","latin":"incutio, incutere, incussi, incussus","headword":"incutio","letter":"i","pos":"verb","posGroup":"verb","english":"strike on or against; instill","forms":["incute","incutiēbat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā posterī Iacobī, seu Hebraeī, numerō auctī sunt mīrum in modum, et eōrum multitūdō crēscēns in diēs metum {{incutiēbat}} Aegyptiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inde","latin":"inde","headword":"inde","letter":"i","pos":"adverb","posGroup":"adverb","english":"from there","forms":["inde"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque {{inde}} profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indeclinabilis","latin":"indēclīnābilis","headword":"indēclīnābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"indeclinable","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"indemnatus","latin":"indemnātus, -a, -um","headword":"indemnātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uncondemned","forms":["indemnātum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eī prīmō coepere pessimum quemque et omnibus invīsum {{indemnātum}} necāre; ea populus laetārī et meritō dīcere fierī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"indestrictus","latin":"indestrictus, indestricta, indestrictum","headword":"indestrictus","letter":"i","pos":"adjective","posGroup":"adjective","english":"untouched, unhurt","forms":["indestrictus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"(Mīrābātur Achillēs enim.) “Nec haec cassis quam vidēs neque scūtum, onus sinistrae, auxiliō mihi sunt; decor est quaesītus ab istīs; Mars quoque ob hoc capere arma solet! [Sī] removēbitur huius tegminis officium, tamen {{indestrictus}} abībō; est aliquid nōn esse nātum Nērēide, sed quī Nēreaque et nātās et tōtum temperat aequor.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"index","latin":"index, indicis","headword":"index","letter":"i","pos":"noun","posGroup":"noun","english":"sign, token, proof; informer, tale bearer","forms":["index"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Crédērē quae iubeant locus est et nōmen et {{index}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"india","latin":"India, Indiae","headword":"India","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"India; (ill-defined region of Asia)","forms":["Indiā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ad summam, lacte gallînäceum sî quaesierīs, domî näscerëttlr, apēs ab Athënîs iussit afferrî: obiter et nec est quod pūtēs :nec causa est cūr putēs (: nôlî putâre) Graeciae (caput: Athênae) ut sibi ex Indiā (Indiā -aeﬁ tum nâtum ex asinô et equâ animî b. : eius b.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"indicare","latin":"(indicō) indicāre","headword":"indicāre","letter":"i","pos":"","posGroup":"other","english":"make known, declare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"indicativus","latin":"indicātīvus, -ī (modus)","headword":"indicātīvus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"indicative","forms":["Indicātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Modī verbōrum quī sunt?' Discipulus: '{{Indicātīvus}}, ut lēgō; imperātīvus, ut lēge; optātīvus, ut utinam legerem; coniūnctīvus, ut cum legam; īnfīnītīvus, ut legere.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"indicere","latin":"(indīcō) indīcere (< dīcere)","headword":"indīcere","letter":"i","pos":"","posGroup":"other","english":"notify, declare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"indicium","latin":"indicium, -ī","headword":"indicium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"information, disclosure; evidence, disclosure","forms":["indici","indicia","indiciīs","indicio","indicium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius {{indicio}} vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indico","latin":"indico, indicere, indixi, indictus","headword":"indico","letter":"i","pos":"verb","posGroup":"verb","english":"declare publicly; proclaim, announce; appoint; summon","forms":["indicā","indicāre","indicāret","indicārī","indicātum","indicātūrum","indicāvisset","indicem","indīcere","indīcerent","indīcerentur","indīcerētur","indicet","indīcit","indicitur","indīctum","indīxerant","indīxerit","indīxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Re impetrata contendunt ut ipsis summa imperi tradatur et re in controversiam deducta totius Galliae concilium Bibracte {{indicitur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indictus","latin":"indictus, indicta, indictum","headword":"indictus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not said/mentioned; (~ cause, without the case's being pleaded); unheard","forms":["indicta","indīctīs","indicto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Indictis}} inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indicus","latin":"Indicus, Indica, Indicum","headword":"Indicus","letter":"i","pos":"adjective","posGroup":"adjective","english":"Indian","forms":["indice"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aliī ab {{indice}} nōminātī ‘esse sē Christiānōs’ dīxērunt — et mox negāvērunt: ‘fuisse quīdam, sed dēsiisse’, quīdam ‘ante triennium’, quīdam ‘ante plūrēs annōs’, nōnnēmō etiam ‘ante vīgintī’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"indigeo","latin":"indigeo, indigere, indigui, -","headword":"indigeo","letter":"i","pos":"verb","posGroup":"verb","english":"need, lack, require (w/GEN or ABL)","forms":["indigeret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hic autem, velut hērēditāte relictum, odium paternum ergā Rōmānōs sīc cōnservāvit ut prius animam dēpōneret quam id dēposuerit — quī quidem, cum patriā pulsus esset et aliēnārum opum {{indigeret}}, numquam dēstiterit animō bellāre cum Rōmānīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"indigere","latin":"(indigeō) indigēre, -uisse, -itum","headword":"indigēre","letter":"i","pos":"","posGroup":"other","english":"need, desire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"indignari","latin":"(indignōr) indignārī","headword":"indignārī","letter":"i","pos":"","posGroup":"other","english":"resent, be indignant","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"indignatio","latin":"indignātiō, -ōnis ( f.)","headword":"indignātiō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"indignation, resentment","forms":["indignātiō","indignātiōnem","indignātiōnēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita indignātiō patris et damnum mihi ēvenient prō eius benevolentia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"indigne","latin":"indigne, indignius, indigissime","headword":"indigne","letter":"i","pos":"adverb","posGroup":"adverb","english":"undeservedly; unjustly; unworthily; unbecomingly; shamefully; outrageously","forms":["indignē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quod illī indignē ferentēs volēbant ulcīscī iniūriam, et maledicī convīciātōris caput amputāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"indignitas","latin":"indignitās, -ātis ( f.)","headword":"indignitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"indignity, humiliation; outrage, indignity","forms":["indignitas","indignitāte","indignitātem","indignitātibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam converteret, ut ne metu quidem necessario faciendum existimabat, cum infamia atque {{indignitas}} rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indignor","latin":"indignor, -ārī, -ātus sum","headword":"indignor","letter":"i","pos":"verb","posGroup":"verb","english":"to be indignant, resent","forms":["indignābantur","indignābātur","indignāns","indignantēs","indignantibus","indignāta","Indignātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Indignantes}} milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indignus","latin":"indignus, -a, -um","headword":"indignus","letter":"i","pos":"adjective","posGroup":"adjective","english":"(+ abl. of respect) unworthy, shameful; unworthy, disgraceful","forms":["indigna","indignam","indignās","indignīs","indignissime","indignissimō","indignissimum","indignō","indignōs","indignum","indignus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis {{indigna}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indiligens","latin":"indiligens, indiligentis (gen.), indiligentior -or -us, indiligentissimus -a -um","headword":"indiligens","letter":"i","pos":"adjective","posGroup":"adjective","english":"careless, negligent; inattentive; neglected, not cared for","forms":["indiligentiores"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quod si {{indiligentiores}} fuerint, milia hominum delecta LXXX una secum interitura demonstrat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indiligentia","latin":"indiligentia, indiligentiae","headword":"indiligentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"negligence, want of care; want of concern (for)","forms":["indiligentia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, {{indiligentia}} Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indo","latin":"indo, indere, indedi, inditus","headword":"indo","letter":"i","pos":"verb","posGroup":"verb","english":"put in or on; introduce","forms":["indat","indit","inditum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Syrācūsās dē sē rē rediit nūntius ad avum puerōrum ‘puerum surrēptum alterum patremque puerī esse Tarentī ēmortuum’, immūtat nōmen avus huic geminō alterī — ita eum dīlēxit quī surreptus est alterum — illīus nōmen {{indit}} illī quī domī est ‘Menaechmō’, idem quod alterī nōmen fuit (et ipse eōdem avus est vocātus nōmine).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"indoctus","latin":"indoctus, -a, -um","headword":"indoctus","letter":"i","pos":"adjective","posGroup":"adjective","english":"ignorant; unlearned, ignorant","forms":["indoctae","indoctī","indoctīs","indoctum","indoctus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus: “Nōn dīcō ‘eum {{indoctum}} esse’, nam is multās rēs scit quās nōs discipulī nescīmus; sed malus est magister, quia nihil nōs docēre potest.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"indoles","latin":"indolēs, -is ( f.)","headword":"indolēs","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"character, nature; natural character, disposition","forms":["indole","indolis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Puer crēscēbat egregiā praeditus {{indole}}, eratque Deō et hominibus cārus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inducere","latin":"(indūcō) indūcere (< dūcere)","headword":"indūcere","letter":"i","pos":"","posGroup":"other","english":"lead, bring (in), introduce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"induco","latin":"induco, inducere, induxi, inductus","headword":"induco","letter":"i","pos":"verb","posGroup":"verb","english":"lead in, bring in (performers); induce, influence; introduce","forms":["indūcere","indūcerēs","indūcit","inductā","inductīs","inductō","inductum","inductus","indūxerat","indūxerīs","indūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Noēmus, admonitus ā Deō, exstrūxit ingentem arcam in modum nāvis; līnīvit eam bitūmine, et in eam {{indūxit}} pār ūnum omnium avium et animantium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"induit","latin":"induit, induere","headword":"induit","letter":"i","pos":"verb","posGroup":"verb","english":"put on (clothes); puts on","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"indulgens","latin":"indulgens, indulgentis (gen.), indulgentior -or -us, indulgentissimus -a -um","headword":"indulgens","letter":"i","pos":"adjective","posGroup":"adjective","english":"indulgent; kind, mild; gracious; bestowing favor; partial/addicted to (doing)","forms":["indulgēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tandem, praemonitus ā sacerdōte, Samūēl respondit Deō vocantī: “Loquēre, Domine: audit enim servus tuus.” Tum Deus Samūēlī: “Ego” ait “afficiam domum Hēlī iīs malīs, quae nēmō audīre possit, quīn eī ambae aurēs tinniant, proptereā quod in līberōs suōs plūs aequō {{indulgēns}} fuerit, illōrumque vitia nimium patienter tulerit.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"indulgentia","latin":"indulgentia, indulgentiae","headword":"indulgentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"leniency, concession, pardon; kindness, gentleness; favor bounty; indulging","forms":["indulgentia","indulgentiae","indulgentiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Magno dolore Aedui ferunt se deiectos principatu, queruntur fortunae commutationem et Caesaris {{indulgentiam}} in se requirunt; neque tamen suscepto bello suum consilium ab reliquis separare audent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indulgeo","latin":"indulgeo, indulgere, indulsi, indultus","headword":"indulgeo","letter":"i","pos":"verb","posGroup":"verb","english":"indulge; be indulgent/lenient/kind; grant/bestow; gratify oneself; give in to","forms":["indulgē","indulget","indulserat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati praecipue {{indulserat}}, nulla interposita dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"induo","latin":"induō, -ere, -uī, -ūtum","headword":"induō","letter":"i","pos":"verb","posGroup":"verb","english":"put on, wear, dress","forms":["indue","induebant","induebātur","induere","Induī","induit","induite","induō","indūta","indūtam","indūtum","indūtus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quini erant ordines coniuncti inter se atque implicati; quo qui intraverant, se ipsi acutissimis vallis {{induebant}}; hos cippos appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"indus","latin":"Indus, Inda, Indum","headword":"Indus","letter":"i","pos":"adjective","posGroup":"adjective","english":"Indian, from/of/belonging to India; of Indian ivory; [dens ~ => Indian ivory]","forms":["Indīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sinistrā manū lyram gemmīs atque dentibus {{Indīs}} decorātam, dextrā manū plectrum tenuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"industria","latin":"industria, -ae","headword":"industria","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"hard work, industry; diligence, energy","forms":["industriā","industriae","industriam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cēra est māteria mollis quam apēs, bēstiolae {{industriae}}, faciunt.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"industrie","latin":"industrie, industrius, industrissime","headword":"industrie","letter":"i","pos":"adverb","posGroup":"adverb","english":"industriously; diligently; assiduously; vigorously","forms":["industriē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Colōnī Iūliī sunt agricolae validī quī industriē labōrant omnēsque mercēdem ad diem solvere solent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"industrius","latin":"industrius, -a, -um","headword":"industrius","letter":"i","pos":"adjective","posGroup":"adjective","english":"industrious; industrious, hard-working","forms":["industriī","industriō","industrium","industrius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Sextus discipulus {{industrius}} ac prūdēns est, ut scīs; ergō bene discit, quamquam male docētur ā magistrō pigrō atque stultō!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"indutia","latin":"indutia, indutiae","headword":"indutia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"truce (pl.), armistice, cessation of hostilities; respite, period of grace","forms":["indūtiae","indūtiārum","indūtiās"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"MERCVRIVS: Immō {{indūtiae}} parumper fīant, sī quid vīs loquī.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"indutiae","latin":"indūtiae, -ārum (pl.)","headword":"indūtiae","letter":"i","pos":"","posGroup":"other","english":"armistice, truce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inedia","latin":"inedia, inediae","headword":"inedia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"fasting, starvation","forms":["inediae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Corpus patiēns {{inediae}}, algōris, vigiliae, suprā quam cuīquam crēdibile est.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"ineluctabilis","latin":"inēluctābilis, -e","headword":"inēluctābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"inescapable, inevitable","forms":["inēlūctābile"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quem cum Aenēās interrogāvisset \"quae fortūna esset patriae?\", magnō cum gemitū haec respondit: \"Vēnit summa diēs et {{inēlūctābile}} tempus Dardaniae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inemptus","latin":"inemptus, -a, -um","headword":"inemptus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unbought, without ransom","forms":["inemptum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"At sī quōs tamen ultima nostrī verba movent ōris (Prīamī vōs fīlia rēgis, nōn captīva rogat), genetricī corpus {{inemptum}} reddite, nēve aurō redimat iūs triste sepulcrī, sed lacrimīs! tunc, cum poterat, redimēbat et aurō.” Dīxerat, at populus lacrimās, quās illa tenēbat, nōn tenet; ipse etiam flēns invītusque sacerdōs virginis ferrum in pectore condit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ineo","latin":"ineo, inire, inivi(ii), initus","headword":"ineo","letter":"i","pos":"verb","posGroup":"verb","english":"enter; undertake; begin; go in; enter upon; [consilium ~ => form a plan]","forms":["ineāmus","ineunt","ineunte","inī","inibat","inibatur","inībitis","inire","inīret","iniretur","iniri","īnīs","init","inita","initō","initum","initūra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia {{inire}} incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ineptio","latin":"ineptio, ineptire, -, -","headword":"ineptio","letter":"i","pos":"verb","posGroup":"verb","english":"play the fool, trifle","forms":["ineptiās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et prôdîsset in medium, decēre gravitātem eius tam humilēs {{ineptiās}}! ’ [Âctuärius ācta praediôrum recitat] Et plānē interpellāvit saltätiônis libîdinem āctuārius, 53 quī tamquam urbis âcta recitāvit: VIĪ kalendās Sextîlês: in prae- diô Cūmānä, quod est Trimal- chiônis, nātī sunt puerÏXIOÇ pu- ellae XL; sublāta in horreum ex āreā trīticī mîlia modium quîn- genta; bovēs domitî quîngentï.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"inermis","latin":"inermis, -e","headword":"inermis","letter":"i","pos":"adjective","posGroup":"adjective","english":"(in + arm) unarmed","forms":["inermē","inermem","inermēs","inermīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nūdī, {{inermēs}}, miserī in silvīs et in campīs errābant, neque quidquam habēbant quō ā ferīs aut ā tempestātibus sē tuērentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"iners","latin":"iners (gen. inertis)","headword":"iners","letter":"i","pos":"adjective","posGroup":"adjective","english":"inactive, idle","forms":["iners","inertēs","inertī","inertium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rūre erit, et dīcet 'veniās!\" Amor ōdit {{inertēs}}:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inertia","latin":"inertia, -ae","headword":"inertia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"idleness, sloth; idleness, inactivity","forms":["inertiā","inertiae","inertiam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quid sī praecipiam 'né fuscet inertiā dentēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inest","latin":"inest, insunt","headword":"inest","letter":"i","pos":"","posGroup":"other","english":"be in","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"inexorabilis","latin":"inexorabilis, inexorabilis, inexorabile","headword":"inexorabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"inexorable, relentless","forms":["inexōrābilēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tantalus, tum illud quod Sīsyphus versat saxum sūdāns nītendō neque prōficit hīlum, ... fortasse etiam {{inexōrābilēs}} iūdicēs Minōs et Rhadamanthus?...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"inexpertus","latin":"inexpertus, inexperta, inexpertum","headword":"inexpertus","letter":"i","pos":"adjective","posGroup":"adjective","english":"inexperienced (in), untried","forms":["inexpertum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nē quid {{inexpertum}} frūstrā moritūra relinquat.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"inexplorato","latin":"inexplōrātō","headword":"inexplōrātō","letter":"i","pos":"","posGroup":"other","english":"without reconnoitering","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inexploratus","latin":"inexploratus, inexplorata, inexploratum","headword":"inexploratus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unexplored; not investigated","forms":["inexplōrātō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Flāminius, cum prīdiē sōlis occāsū ad lacum pervēnisset, inexplōrātō posterō diē, vixdum satis certā lūce angustiīs superātīs, postquam in patentiorēm campum pandī agmen coepit, id tantum hostium quod ex adversō erat cōnspexit: ā tergō ac super caput dēcēpēre īnsidiae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inexpugnabilis","latin":"inexpugnābilis, -e","headword":"inexpugnābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"impregnable","forms":["inexpūgnābilia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ā quō quīntō diē in castra pervēnī; ubi exercitū acceptō, mūtātīs quibusdam quae magna impedīmenta victōriae erant, prōgressus, quia {{inexpūgnābilia}} castra hostium erant neque cōgī pugnāre poterat rēx, inter praesidia eius saltum ad Petram ēvāsī et ad Pydnam rēgem aciē vīcī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inexspectatus","latin":"inexspectātus, -a, -um","headword":"inexspectātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unexpected","forms":["inexspectāta","inexspectātī","inexspectātō","inexspectātus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sī in illud intrāverīs, etiam sī {{inexspectāta}} vēnerīs, semper bene tē recipiam et multōs cibōs appōnam: mihi est enim magna cōpia lactis atque cāseī, quibus aestāte et hieme fruor, nam multae ovēs multaeque caprae in meīs vallibus errant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"infabricatus","latin":"infabricatus, infabricata, infabricatum","headword":"infabricatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unwrought, unfashioned","forms":["īnfabricāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"īnfabricāta fugae studiō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"infamia","latin":"infamia, infamiae","headword":"infamia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"disgrace, dishonor; infamy","forms":["infamia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam converteret, ut ne metu quidem necessario faciendum existimabat, cum {{infamia}} atque indignitas rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infamis","latin":"īnfāmis, -e","headword":"īnfāmis","letter":"i","pos":"adjective","posGroup":"adjective","english":"disgraced","forms":["īnfāmēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum Rōmānī iussērunt captīvōs omnēs quōs Pyrrhus reddiderat īnfāmēs habērī, 'quod armātī capī potuissent, nec ante eōs ad veterem statum revertī quam sī bīnōrum hostium occīsōrum spolia rettulissent.' Ita lēgātus Pyrrhī reversus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infandus","latin":"infandus, -a, -um","headword":"infandus","letter":"i","pos":"adjective","posGroup":"adjective","english":"horrible, unspeakable; unspeakable, monstrous","forms":["īnfandī","īnfandōs","īnfandum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mōnstrum īnfandum est Cyclōps ille nōmine Polyphēmus, quī carne et sanguine hominum miserōrum vēscitur!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infans","latin":"īnfāns, īnfantis","headword":"īnfāns","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"(m./f.) baby; infant, baby","forms":["īnfāns","īnfante","īnfantem","Īnfantēs","īnfantī","infantibus","īnfantīs","īnfantium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sic et Cenabi caede et labore operis incitati non aetate confectis, non mulieribus, non {{infantibus}} pepercerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infantia","latin":"infantia, infantiae","headword":"infantia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"infancy; inability to speak","forms":["īnfantiā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tobiās adultus uxōrem dūxit, habuitque fīlium, quem ab īnfantiā docuit timēre Deum, et ab omnī peccātō abstinēre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"infantulus","latin":"infantulus, infantuli","headword":"infantulus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"baby boy; little babe; little infant","forms":["īnfantulum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē abscondit eum tribus mēnsibus; sed cum nōn posset eum diūtius occultāre, sūmpsit fiscellam, quam līnīvit bitūmine ac pice; deinde posuit intus īnfantulum, et exposuit eum inter harundinēs rīpae flūminis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"infectus","latin":"īnfectus, -a, -um","headword":"īnfectus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unwrought, not effected","forms":["infecta","infectīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita re {{infecta}} in oppidum reverterunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infeliciter","latin":"infeliciter, infelicius, infelicissime","headword":"infeliciter","letter":"i","pos":"adverb","posGroup":"adverb","english":"unfortunately; without good luck; without success","forms":["īnfēlīciter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Carthāginiēnsēs, portū novō — quia vetus obstrictus ā Scīpiōne erat — factō et contractā clam exiguō tempore amplā classe, īnfēlīciter nāvālī proeliō pugnāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infelix","latin":"īnfēlīx","headword":"īnfēlīx","letter":"i","pos":"adjective","posGroup":"adjective","english":"(gen.īnfēlīcis) unlucky; unhappy, unlucky; unhappy; unhappy, unfortunate; unhappy, ill-fated","forms":["īnfēlīcem","Īnfēlīcī","īnfēlīcis","īnfēlīx"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cūr mē īnfēlīcem relīquistī, mea cārissima coniūnx?” Per multōs diēs, trīstis et maestus, neque cibum neque aquam sūmere voluit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"infensus","latin":"īnfēnsus, -a, -um","headword":"īnfēnsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"hostile","forms":["īnfēnsī","īnfēnsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā exortus est novus Assyriōrum rēx Isrāēlītīs īnfēnsus, quī eōs vexābat, necābat, et sepelīrī vetābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"infer","latin":"infer, infera -um, inferior -or -us, infumus -a -um","headword":"infer","letter":"i","pos":"adjective","posGroup":"adjective","english":"below, beneath, underneath; of hell; vile; lower, further down; lowest, last","forms":["īnfer"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sīn autem servīre meae laudī et glōriae māvīs, ēgredere cum importūnā scelerātōrum manū, cōnfer tē ad Mānlium, concitā perditōs cīvēs, sēcerne tē ā bonīs, īnfer patriae bellum, exsultā impiō latrōciniō, ut ā mē nōn ēiectus ad aliēnōs, sed invītātus ad tuōs īsse videāris!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inferi","latin":"īnferī","headword":"īnferī","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"the underworld, the dead","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"inferior","latin":"īnferior, -ius","headword":"īnferior","letter":"i","pos":"","posGroup":"other","english":"lower, inferior","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"infernus","latin":"īnfernus, -a, -um","headword":"īnfernus","letter":"i","pos":"adjective","posGroup":"adjective","english":"of the underworld","forms":["īnfernī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Illa quidem trīstis neque etiam adhūc interrita, sed tamen est rēgīna maxima rēgnī obscūrī, tamen uxor rēgis īnfernī.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"infero","latin":"infero, inferre, intuli, illatus","headword":"infero","letter":"i","pos":"verb","posGroup":"verb","english":"bring/carry in, import; advance, bring/march/step/move foward; impel, urge","forms":["inferant","īnferar","inferebant","īnferēbat","īnferentem","īnferentēs","inferre","īnferrent","inferri","Īnfert","īnfertur","inlata","intulerat","intulerunt","intulī","intulissent","intulisset","intulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem {{inferant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inferre","latin":"(īnferō) īnferre (< ferre)","headword":"īnferre","letter":"i","pos":"","posGroup":"other","english":"bring (in), cause, inflict","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inferus","latin":"īnferus, -a, -um","headword":"īnferus","letter":"i","pos":"adjective","posGroup":"adjective","english":"lower","forms":["īnfera","inferior","inferiore","īnferiōrem","īnferiōris","Īnferīs","īnferius","Īnferōrum","Īnferōs","Īnferum","īnfimā","īnfimī","īnfimīs","īnfimōrum","infimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His quam longissime possent egredi iussis, cum iam ex diei tempore coniecturam ceperat in castra perventum,: isdem sublicis, quarum pars {{inferior}} integra remanebat, pontem reficere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infesto","latin":"infesto, infestare, infestavi, infestatus","headword":"infesto","letter":"i","pos":"verb","posGroup":"verb","english":"vex (w/attacks), harass, molest; make unsafe, disturb; infest; damage, impair","forms":["īnfestat","īnfēstō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Chimaeram igitur, saevissimum illud animal quod campōs nostrōs īnfestat, pete et armīs tuīs occīde!” Bellerophōn igitur, cum haec audīvisset, trīstis et maestus ā rēgiā ad Polydum, callidum virum, abiit, ut eius cōnsilium peteret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"infestus","latin":"īnfēstus, -a, -um","headword":"īnfēstus","letter":"i","pos":"adjective","posGroup":"adjective","english":"dangerous; hostile (to, + dat.); hostile, dangerous","forms":["Īnfēstā","īnfēstam","īnfēstās","īnfēstior","infestis","īnfēstissimam","īnfēstius","īnfēstōs","īnfestum","īnfestus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Legiones, ubi primum planitiem attigerunt, {{infestis}} contra hostes signis constiterunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infidelis","latin":"infidelis, infidelis, infidele","headword":"infidelis","letter":"i","pos":"adjective","posGroup":"adjective","english":"treacherous, disloyal","forms":["infideles"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Bellovaci autem, defectione Aeduorum cognita, qui iam ante erant per se {{infideles}}, manus cogere atque aperte bellum parare coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infidus","latin":"īnfīdus, -a, -um","headword":"īnfīdus","letter":"i","pos":"adjective","posGroup":"adjective","english":"treacherous; faithless","forms":["īnfīdā","Īnfīdam","īnfīdī","īnfīdōs","īnfīdus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Antīquissimīs temporibus hominēs tam scelestī factī erant, ut, īnfīdī et falsī, omnis generis iniūriās facerent, neque quidquam magis optārent quam aurum et dīvitiās, quārum cupidissimī esse vidēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"infigere","latin":"(īnfīgō) īnfīgere (< fīgere)","headword":"īnfīgere","letter":"i","pos":"","posGroup":"other","english":"fix, fasten","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"infigo","latin":"infigo, infigere, infixi, infixus","headword":"infigo","letter":"i","pos":"verb","posGroup":"verb","english":"fasten (on), fix, implant, affix; impose; drive/thrust in","forms":["īnfīxa","īnfīxī","infixis","īnfīxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis hamis {{infixis}} totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infimo","latin":"infimo, infimare, infimavi, infimatus","headword":"infimo","letter":"i","pos":"verb","posGroup":"verb","english":"bring down to the lowest level; weaken, enfeeble; refute, invalidate, annul","forms":["infimo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Collis erat leniter ab {{infimo}} acclivis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infimus","latin":"īnfimus, -a, -um","headword":"īnfimus","letter":"i","pos":"adjective","posGroup":"adjective","english":"lowest","forms":["īnfimus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quam ob causam summus ille caelī stellifer cursus, cuius conversiō est concitātior, acūtō et excitātō movētur sonō, gravissimō autem hic lūnāris atque īnfimus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infinitivus","latin":"īnfīnītīvus (modus)","headword":"īnfīnītīvus","letter":"i","pos":"","posGroup":"other","english":"infinitive","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"infinitus","latin":"īnfinītus, -a, -um","headword":"īnfinītus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unlimited, infinite; boundless, endless","forms":["īnfīnīta","īnfīnītam","īnfīnītum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat porrō īnfīnīta multitūdō in exercitū Madianitārum, nam cum iīs rēx Amalēcītārum sē coniūnxerat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"infirmare","latin":"(īnfirmō) īnfirmāre","headword":"īnfirmāre","letter":"i","pos":"","posGroup":"other","english":"weaken, refute, annul","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"infirmatio","latin":"infīrmātiō, -ōnis ( f.)","headword":"infīrmātiō","letter":"i","pos":"","posGroup":"other","english":"invalidation, rebuttal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"infirmis","latin":"infirmis, infirmis, infirme","headword":"infirmis","letter":"i","pos":"adjective","posGroup":"adjective","english":"weak/fragile/frail/feeble; unwell/sick/infirm","forms":["īnfirmīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēx Priamus senex, ut prīmum forēs frāctās et hostēs in mediīs aedibus vīdit, manibus īnfirmīs arma capit et gladiō cingitur atque moritūrus in hostēs prōgreditur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infirmitas","latin":"īnfirmitās, -ātis ( f.)","headword":"īnfirmitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"weakness","forms":["infirmitas","Īnfirmitāte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres familiae repente in publicum procurrerunt flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium {{infirmitas}} impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infirmo","latin":"infirmo, infirmare, infirmavi, infirmatus","headword":"infirmo","letter":"i","pos":"verb","posGroup":"verb","english":"weaken; diminish; annul; (PASS) be ill (Bee)","forms":["Īnfirmābātur","īnfirmātam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Erat quīdam rēgulus, cuius fīlius Īnfirmābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"infirmus","latin":"īnfīrmus, -a, -um","headword":"īnfīrmus","letter":"i","pos":"adjective","posGroup":"adjective","english":"weak","forms":["infirma","īnfirmās","īnfirmior","īnfirmōs","īnfirmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non multum adiuvabant, alteri non magnis facultatibus, quod civitas erat exigua et {{infirma}}, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infitiari","latin":"(īnfitior) īnfitiārī","headword":"īnfitiārī","letter":"i","pos":"","posGroup":"other","english":"deny","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"infitior","latin":"infitior, infitiari, infitiatus sum","headword":"infitior","letter":"i","pos":"verb","posGroup":"verb","english":"deny; not confess/acknowledge; withhold; disown; repudiate (claim); contradict","forms":["īnfitiandum","īnfitiārī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī vērum est — quod nēmō dubitat — ut populus Rōmānus omnēs gentēs virtūte superārit, nōn est īnfitiandum Hannibalem tantō praestitisse cēterōs imperātōrēs prūdentiā, quantō populus Rōmānus antecēdat fortitūdine cūnctās nātiōnēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inflammare","latin":"(īnflammō) īnflammāre","headword":"īnflammāre","letter":"i","pos":"verb","posGroup":"verb","english":"kindle, inflame; to kindle, set on fire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"inflammatus","latin":"inflammatus, inflammata, inflammatum","headword":"inflammatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"excited; inflamed; set on fire","forms":["īnflammātōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque ego ut vīdī quōs maximō furōre et scelere esse īnflammātōs sciēbam eōs nōbīscum esse et Rōmae remānsisse, in eō omnēs diēs noctēsque cōnsūmpsī ut quid agerent, quid mōlīrentur sentīrem ac vidērem, ut, quoniam auribus vestrīs propter incrēdibilem magnitūdinem sceleris minōrem fidem faceret ōrātiō mea, rem ita comprehenderem, ut tum dēmum animīs salūtī vestrae prōvidērētis, cum oculīs maleficium ipsum vidērētis.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inflammo","latin":"inflammo, inflammare, inflammavi, inflammatus","headword":"inflammo","letter":"i","pos":"verb","posGroup":"verb","english":"set on fire, inflame, kindle; excite","forms":["īnflammandam","īnflammāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hīs dictīs animum sorōris amōre īnflammāvit et mentī dubiae spem dedit atque pudōrem solvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inflare","latin":"(īnflō) īnflāre","headword":"īnflāre","letter":"i","pos":"verb","posGroup":"verb","english":"inflate, puff up, elate; to blow into","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"inflatus","latin":"inflatus, inflata -um, inflatior -or -us, inflatissimus -a -um","headword":"inflatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"inflated, puffed up; bombastic; turgid","forms":["inflāta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Musica Graeca in fistulam ā Mary Johnson {{inflāta}} est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"inflectere","latin":"(īnflectō) īnflectere, -flexisse, -xum","headword":"īnflectere","letter":"i","pos":"verb","posGroup":"verb","english":"bend, curve, inflect; to inflect, bend","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"inflecto","latin":"inflecto, inflectere, inflexi, inflexus","headword":"inflecto","letter":"i","pos":"verb","posGroup":"verb","english":"bend; curve; change","forms":["īnflectuntur","īnflexit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magister: 'Cāsus item prōnōminum quot sunt?' Discipulus: 'Sex, quem ad modum et nōminum, per quōs omnium generum prōnōmina īnflectuntur.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"inflexibilis","latin":"inflexibilis, inflexibilis, inflexibile","headword":"inflexibilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unbendable; inflexible","forms":["īnflexibilem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Neque enim dubitābam, quālecumque esset quod fatērentur, pertināciam certē et īnflexibilem obstinātiōnem dēbēre pūnīrī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"inflo","latin":"inflo, inflare, inflavi, inflatus","headword":"inflo","letter":"i","pos":"verb","posGroup":"verb","english":"blow into/upon; puff out","forms":["inflāre","īnflat","īnflātum","inflāvit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Est in Lydiā mōns altus, Tmōlus nōmine, summō quō Pān nymphīs carmina sua cantābat, dum fīstulam cērā coniūnctam īnflat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"influo","latin":"īnfluō, īnfluere","headword":"īnfluō","letter":"i","pos":"verb","posGroup":"verb","english":"flow into","forms":["influeret","īnfluit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Is cum animadvertisset perpetuam esse paludem quae {{influeret}} in Sequanam atque illum omnem locum magnopere impediret, hic consedit nostrosque transitu prohibere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infodio","latin":"infodio, infodere, infodi, infossus","headword":"infodio","letter":"i","pos":"verb","posGroup":"verb","english":"bury, inter","forms":["infodiebantur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis hamis infixis totae in terram {{infodiebantur}} mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"informis","latin":"īnfōrmis, -e","headword":"īnfōrmis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unshapely, ugly; shapeless, hideous","forms":["īnfōrme","īnfōrmem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praestat tōtam Siciliam longō cursū circumīre quam semel Scyllam īnfōrmem vidēre et saxa illa resonantia experīrī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infortunium","latin":"infortunium, infortuni(i)","headword":"infortunium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"misfortune, punishment","forms":["īnfortūnium"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"atque hinc fugiās, ita vix poteris effugere īnfortūnium!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"infra","latin":"īnfrā","headword":"īnfrā","letter":"i","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) below","forms":["infra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Uno fere tempore sub lucem hostibus nuntiatur in castris Romanorum praeter consuetudinem tumultuari et magnum ire agmen adverso flumine sonitumque remorum in eadem parte exaudiri et paulo {{infra}} milites navibus transportari.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"infractus","latin":"infractus, infracta, infractum","headword":"infractus","letter":"i","pos":"adjective","posGroup":"adjective","english":"broken; humble in tone","forms":["īnfrāctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rōmānī tamen statim ducentās nāvēs reparāvērunt, neque aliquō animus hīs īnfrāctus fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infrenus","latin":"infrenus, infrena, infrenum","headword":"infrenus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not bridled; unrestrained","forms":["īnfrēnī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et Numidae īnfrēnī cingunt et inhospita Syrtīs;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"infringere","latin":"(īnfringō) īnfringere (< frangere)","headword":"īnfringere","letter":"i","pos":"","posGroup":"other","english":"break, crush","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"infringo","latin":"infringo, infringere, infregi, infractus","headword":"infringo","letter":"i","pos":"verb","posGroup":"verb","english":"break, break off; lessen, weaken, diminish, dishearten; overcome, crush","forms":["īnfringent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is dēmum vir erit cuius animum nec prosperae rēs flātū suō efferent nec adversae īnfringent.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"infundo","latin":"infundo, infundere, infudi, infusus","headword":"infundo","letter":"i","pos":"verb","posGroup":"verb","english":"pour in, pour on, pour out","forms":["Īnfundēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et appropinquāns alligāvit vulnera eius Īnfundēns oleum et vīnum; et impōnēns illum iūmentō suō, dūxit in stabulum, et cūram eius ēgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ingemescere","latin":"(ingemēscō) ingemēscere","headword":"ingemēscere","letter":"i","pos":"","posGroup":"other","english":"groan, moan","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ingemesco","latin":"ingemesco, ingemescere, ingemui, ingemitus","headword":"ingemesco","letter":"i","pos":"verb","posGroup":"verb","english":"groan/moan (begin to) at/over; cry w/pain/anguish/sorrow; creak/groan (object)","forms":["ingemēscente"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et haec ideô omnia püblicô, ut familia mea iam nunc sîc mē amet tamquam mortuum!” Grātiās agere omnēs indulgentiae coeperant dominī, afferrî, et tôtum ā prîmô ad ultimum, {{ingemēscente}} Respiciēns deinde Habinnam “Quid dîcis” inquit, “amîce cārissime?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ingemino","latin":"ingemino, ingeminare, ingeminavi, ingeminatus","headword":"ingemino","letter":"i","pos":"verb","posGroup":"verb","english":"redouble; increase in intensity","forms":["ingeminant","ingeminat"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{ingeminat}} vōcēs audītaque verba reportat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ingemo","latin":"ingemo, ingemere, ingemui, ingemitus","headword":"ingemo","letter":"i","pos":"verb","posGroup":"verb","english":"groan/moan/sigh (at/over); utter cry of pain/anguish; creak/groan (objects)","forms":["ingemit","ingemuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Ingemuit}}: vōx illa fuit, lacrimaeque per ōra nōn sua flūxērunt; mēns tantum prīstina mānsit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ingeniosus","latin":"ingeniosus, ingeniosa -um, ingeniosior -or -us, ingeniosissimus -a -um","headword":"ingeniosus","letter":"i","pos":"adjective","posGroup":"adjective","english":"clever, ingenious; naturally suited (to); having natural abilities/talents","forms":["ingeniōsus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"\"máteriam quà sīs {{ingeniōsus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ingenium","latin":"ingenium, -ī","headword":"ingenium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"nature, character; nature, talent; nature, talent, wit","forms":["ingeni","ingenia","ingeniī","ingeniīs","ingeniō","ingenium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ovidius poeta, qui {{ingenium}} mulierum tam bene noverat quam ipsae mulieres, rationem reddit hoc versu: 'Spectatum veniunt, veniunt spectentur ut ipsae!'\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ingens","latin":"ingēns","headword":"ingēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"(gen.ingentis) huge, vast; huge","forms":["ingēns","ingentem","ingentēs","ingentī","ingentia","ingentibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Ingēns}} fluvius irrigābat hortum: erant ibi omnēs arborēs iūcundae aspectū, et frūctūs gustū suāvēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ingenuus","latin":"ingenuus, ingenua, ingenuum","headword":"ingenuus","letter":"i","pos":"adjective","posGroup":"adjective","english":"natural, indigenous; free-born; noble, generous, frank","forms":["ingenuā","ingenuās","ingenuus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec levīs {{ingenuās}} pectus coluisse per artés","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ingero","latin":"ingero, ingerere, ingessi, ingestus","headword":"ingero","letter":"i","pos":"verb","posGroup":"verb","english":"carry in, throw in; heap; force/thrust/throw upon","forms":["Ingerēbat"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn minus et Trimalchiô eiusmodî methodiô laetus “Carpe!” inquit. essedärius Prôcessit statim scissor, et ad _, cerâvit obsônium, ut putārēs Ā’ ' essedärium hydraulē cantante {{Ingerēbat}} nihilô minus Trimal- chiô lentissimä vôce: “Carpe!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ingratus","latin":"ingrātus, -a, -um","headword":"ingrātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unpleasant, ungrateful; unpleasant, unpleasing, ungrateful","forms":["ingrata","ingrātās","ingrātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Fuit haec oratio non {{ingrata}} Gallis, et maxime, quod ipse animo non defecerat tanto accepto incommodo neque se in occultum abdiderat et conspectum multitudinis fugerat; plusque animo providere et praesentire existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ingravesco","latin":"ingravesco, ingravescere, -, -","headword":"ingravesco","letter":"i","pos":"verb","posGroup":"verb","english":"grow heavy; increase in force or intensity","forms":["ingravēscēbat","ingravēscente","ingravēscet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Secūta est inopia septem annōrum, et in orbe ūniversō famēs {{ingravēscēbat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ingredi","latin":"(ingredior) ingredī, -gressum","headword":"ingredī","letter":"i","pos":"","posGroup":"other","english":"enter, begin, walk","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ingredior","latin":"ingredior, ingredi, ingressus sum","headword":"ingredior","letter":"i","pos":"verb","posGroup":"verb","english":"advance, walk; enter, step/go into; undertake, begin","forms":["ingredere","ingredī","ingrediar","ingrediēns","ingredientem","ingredientēs","ingreditur","ingrediuntur","ingressa","ingressae","ingressī","ingressīs","ingressōs","Ingressū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Labānus, frāter Rebeccae, cum audīvisset sorōrem nārrantem, adiit hominem, quī stābat ad fontem cum camēlīs, et compellāns eum: {{ingredere}}, inquit, domine mī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ingressus","latin":"ingressus, ingressus","headword":"ingressus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"entry; going in/embarking on (topic/speech); point of entry, approach; steps","forms":["ingressus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Noëmus ipse {{ingressus}} est in arcam cum coniuge, tribus fīliīs et totidem nuribus, aquā maris et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ingruo","latin":"ingruo, ingruere, ingrui, -","headword":"ingruo","letter":"i","pos":"verb","posGroup":"verb","english":"advance threateningly; make an onslaught on; break in, come violently, force","forms":["ingruunt"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"hostēs crēbrī cadunt, nostrī contrā {{ingruunt}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"inhibeo","latin":"inhibeo, inhibere, inhibui, inhibitus","headword":"inhibeo","letter":"i","pos":"verb","posGroup":"verb","english":"restrain, curb; prevent","forms":["inhibēre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Sponte suā properant: labor est {{inhibēre}} volentēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"inhonesto","latin":"inhonesto, inhonestare, inhonestavi, inhonestatus","headword":"inhonesto","letter":"i","pos":"verb","posGroup":"verb","english":"disgrace","forms":["inhonesta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Metellus Crēticus in Āpūliam circumque ea loca missī (hī utrīque ad urbem imperātōrēs erant, impedītī nē triumphārent calumniā paucōrum quibus omnia honesta atque {{inhonesta}} vēndere mōs erat), sed praetōrēs Q.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inhonestus","latin":"inhonestus, inhonesta -um, inhonestior -or -us, inhonestissimus -a -um","headword":"inhonestus","letter":"i","pos":"adjective","posGroup":"adjective","english":"shameful, not regarded with honor/respect; degrading (appearance)","forms":["inhonestam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nōnne ēmorī per virtūtem praestat quam vītam miseram atque {{inhonestam}}, ubi aliēnae superbiae lūdibriō fuerīs, per dēdecus āmittere?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inhospitalis","latin":"inhospitālis, -e (< hospes, l.30, hospitālis, ll.42, 45)","headword":"inhospitālis","letter":"i","pos":"adjective","posGroup":"adjective","english":"inhospitable","forms":["inhospitālem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sīve per Syrtēs iter aestuōsās / sīve factūrus per {{inhospitālem}} / Caucasum vel quae loca fābulōsus / lambit Hydaspēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inhospitus","latin":"inhospitus, inhospita, inhospitum","headword":"inhospitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not welcoming strangers, not providing shelter/subsistence; inhospitable","forms":["inhospita"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et Numidae īnfrēnī cingunt et {{inhospita}} Syrtīs;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"inhumane","latin":"inhumane, inhumanius, inhumanissime","headword":"inhumane","letter":"i","pos":"adverb","posGroup":"adverb","english":"rudely, discourteously; heartlessly, unfeelingly; inhumanly","forms":["inhūmānē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Sīc Tantalus, quī etiam cognōscere volēbat utrum dīī omnia animadverterent, carnēs miserī fīliī inhūmānē interfectī ē culīnā in trīclīnium portāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"inhumanus","latin":"inhūmānus, -a, -um","headword":"inhūmānus","letter":"i","pos":"adjective","posGroup":"adjective","english":"inhumane","forms":["inhūmāna","inhūmānae","inhūmānum","inhūmānus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Utrum sunt bonae et probae, an ferōcēs, saevae atque {{inhūmānae}}?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"inhumatus","latin":"inhumatus, inhumata, inhumatum","headword":"inhumatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unburied","forms":["inhumātī","inhumātus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ipsa sed in somnīs inhumātī vēnit imāgō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"inicere","latin":"(inicō) inicere (< icere)","headword":"inicere","letter":"i","pos":"","posGroup":"other","english":"throw/lay on, instill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inicio","latin":"inicio, inicere, injeci, injectus","headword":"inicio","letter":"i","pos":"verb","posGroup":"verb","english":"hurl/throw/strike in/into; inject; put on; inspire, instill (feeling, etc)","forms":["iniceret","iniciendi","iniciendum","iniēcit","iniectis","iniectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ipsi ex finitimis regionibus copias cogere, praesidia custodiasque ad ripas Ligeris disponere equitatumque omnibus locis {{iniciendi}} timoris causa ostentare coeperunt, si ab re frumentaria Romanos excludere aut adductos inopia ex provincia expellere possent Quam ad spem multum eos adiuvabat quod Liger ex nivibus creverat, ut omnino vado non posse transiri videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iniecto","latin":"injecto, injectare, injectavi, injectatus","headword":"injecto","letter":"i","pos":"verb","posGroup":"verb","english":"apply; lay on","forms":["iniectā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"iniectā lateant fac tibi","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inimicitia","latin":"inimicitia, inimicitiae","headword":"inimicitia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"unfriendliness, enmity, hostility","forms":["Inimīcitiae","inimīcitiās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Inimīcitiae}} erunt inter tē et mulierem; ipsa ōlim conteret caput tuum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inimico","latin":"inimico, inimicare, inimicavi, inimicatus","headword":"inimico","letter":"i","pos":"verb","posGroup":"verb","english":"make enemies","forms":["inimīcō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quam ob rem, ut saepe iam dīxī, proficīscere ac, sī mihi inimīcō, ut praedicās, tuō cōnflāre vīs invidiam, rēcta perge in exsilium!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inimicus","latin":"inimīcus, -ī","headword":"inimīcus","letter":"i","pos":"noun (m.); adjective","posGroup":"noun","english":"(personal) enemy; hostile, unfriendly","forms":["inimīcā","inimīcam","inimīcī","inimīcīs","inimīcissimās","inimīcissimum","inimīcōrum","inimīcōs","inimīcum","inimīcus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Omnēs sēgetēs, vīneae et oleae exustae sunt; nec {{inimīcam}} gentem variīs incommodīs vexāre dēstitit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iniquitas","latin":"inīquitās, -tātis ( f.)","headword":"inīquitās","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"unfairness; injustice, unfairness","forms":["iniquitas","iniquitātī","inīquitātibus","iniquitatis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se {{iniquitatis}} condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iniquus","latin":"inīquus, -a, -um","headword":"inīquus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uneven, unfair","forms":["inīquā","inīquae","Inīquē","iniquo","inīquum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Caesar, cum {{iniquo}} loco pugnari hostiumque augeri copias videret, praemetuens suis ad T.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inire","latin":"(ineō) inīre (< īre)","headword":"inīre","letter":"i","pos":"","posGroup":"other","english":"enter (upon), begin","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"initio","latin":"initio, initiare, initiavi, initiatus","headword":"initio","letter":"i","pos":"verb","posGroup":"verb","english":"initiate (into); admit (to) with introductory rites","forms":["Initiantī","initiāta","initio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto {{initio}} belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"initium","latin":"initium, -ī","headword":"initium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"beginning","forms":["initi","initia","initium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli {{initia}} faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iniungo","latin":"injungo, injungere, injunxi, injunctus","headword":"injungo","letter":"i","pos":"verb","posGroup":"verb","english":"enjoin, charge, bring/impose upon; unite; join/fasten/attach (to)","forms":["iniungere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Romani vero quid petunt aliud aut quid volunt, nisi invidia adducti, quos fama nobiles potentesque bello cognoverunt, horum in agris civitatibusque considere atque his aeternam {{iniungere}} servitutem?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iniuratus","latin":"injuratus, injurata, injuratum","headword":"injuratus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unsworn","forms":["iniūrātō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nam iniūrātō, sciō, plūs crēdet mihi quam iūrātō tibi!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"iniuria","latin":"iniūria, -ae","headword":"iniūria","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"injury, injustice; injury, wrong; injury, hurt, wrong","forms":["iniūria","iniūriae","iniuriam","iniurias","iniūriīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nuntios tota civitate Aeduorum dimittit, eodem mendacio de caede equitum et principum permovet; hortatur ut simili ratione atque ipse fecerit suas {{iniurias}} persequantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iniuriosus","latin":"iniūriōsus, -a, -um","headword":"iniūriōsus","letter":"i","pos":"","posGroup":"other","english":"unjust, wrongful","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iniussu","latin":"iniussū2","headword":"iniussū","letter":"i","pos":"adverb","posGroup":"adverb","english":"without orders","forms":["iniussū"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam iniussū meō Albānī subiēre ad montēs!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iniustus","latin":"iniūstus, -a, -um","headword":"iniūstus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unjust; unjust, unfair","forms":["iniūstā","iniūstae","iniūstē","iniūstō","iniūstōs","iniūstum","iniūstus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sīc Deus līberāvit Hebraeōs ab iniūstā servitūte Aegyptiōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inlustris","latin":"inlustris, inlustre, inlustrior -or -us, inlustrissimus -a -um","headword":"inlustris","letter":"i","pos":"adjective","posGroup":"adjective","english":"bright, shining, brilliant; clear, lucid; illustrious, distinguished, famous","forms":["inlustrior"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam, ubique maior atque {{inlustrior}} incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inlustro","latin":"inlustro, inlustrare, inlustravi, inlustratus","headword":"inlustro","letter":"i","pos":"verb","posGroup":"verb","english":"illuminate, light up; give glory; embellish; make clear, elucidate; enlighten","forms":["inlustrem","inlūstrēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et {{inlustrem}} adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"innato","latin":"innato, innatare, innatavi, innatatus","headword":"innato","letter":"i","pos":"verb","posGroup":"verb","english":"swim (in or on); float upon","forms":["innata"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Impellit alios avaritia, alios iracundia et temeritas quae maxime illi hominum generi est {{innata}}, ut levem auditionem habeant pro re comperta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"innecto","latin":"innecto, innectere, innexui, innexus","headword":"innecto","letter":"i","pos":"verb","posGroup":"verb","english":"tie, fasten (to); devise, weave (plots)","forms":["innecte"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"indulgē hospitiō causāsque {{innecte}} morandī,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"innitor","latin":"innitor, inniti, innixus sum","headword":"innitor","letter":"i","pos":"verb","posGroup":"verb","english":"lean/rest on (w/DAT), be supported by (w/ABL)","forms":["innīxa"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iacobus vīdit in somnīs scālam, quae {{innīxa}} terrae pertinēbat ad caelum, atque Angelōs Deī adscendentēs et dēscendentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"innocens","latin":"innocēns (gen. innocentis)","headword":"innocēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"innocent, blameless; innocent, harmless","forms":["innocente","innocentēs","innocentī","innocentium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Utinam, Quirītēs, virōrum fortium atque {{innocentium}} cōpiam tantam habērētis ut haec vōbīs dēlīberātiō difficilis esset, quemnam potissimum tantīs rēbus ac tantō bellō praeficiendum putārētis!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"innocentia","latin":"innocentia, -ae","headword":"innocentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"innocence, integrity; integrity, innocence","forms":["innocentia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnia tēla mōta carmine Orpheī futūra essent {{innocentia}}; sed clāmor ingēns fēminārum īrātissimārum clāmantium et tympana et tībiae et cornua sonum lyrae vīcērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"innocuus","latin":"innocuus, innocua, innocuum","headword":"innocuus","letter":"i","pos":"adjective","posGroup":"adjective","english":"innocent; harmless","forms":["innocuus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vir iūstus, probus, {{innocuus}} — timēris!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"innotesco","latin":"innotesco, innotescere, innotui, -","headword":"innotesco","letter":"i","pos":"verb","posGroup":"verb","english":"become known, be made conspicuous","forms":["innōtuit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quīcumque turpī fraude semel {{innōtuit}}, etiam sī vērum dīcit, āmittit fidem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"innoxius","latin":"innoxius, innoxia, innoxium","headword":"innoxius","letter":"i","pos":"adjective","posGroup":"adjective","english":"harmless, innocuous; unhurt, unharmed","forms":["innoxiōs","innoxium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cūr virum {{innoxium}} tibi mīlitantem gladiō hostium interfēcistī?” Hīs prophētae verbīs mōtus Dāvīd culpam agnōvit et cōnfessus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"innubus","latin":"innubus, -a, -um","headword":"innubus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unwed; unwed, unmarried","forms":["innuba"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nōn debēs coniugem habēre; erit mors tibi.\" Territa virgō in silvā vīvit {{innuba}} et turbam procōrum fugat hīs verbīs dūrīs: \"Nōn erō coniūnx, nisi prius victa cursū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"innumerabilis","latin":"innumerābilis, -e","headword":"innumerābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"countless, innumerable","forms":["innumerābilēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inter alia cum quaereret ab Hannibale 'quem fuisse maximum imperātōrem crēderet?' Hannibal respondit 'Alexandrum Macedonum rēgem, quod parvā manū {{innumerābilēs}} exercitūs fūdisset, quodque ultimās ōrās, quās vīsere suprā spem hūmānam esset, peragrāsset.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"innumerus","latin":"innumerus, innumera, innumerum","headword":"innumerus","letter":"i","pos":"adjective","posGroup":"adjective","english":"innumerable, countless, numberless; without number; immense","forms":["innumerā","innumerīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ārās falsīs dīīs per ūniversam IŪdaeam exstrūxit; omnia templī Hierosolymitanī omāmenta dētrāxit; librōs sacrōs iussit comburī; reluctantēs inaudītīs suppliciīs afrecit; urbem innumerā caede vastāvit: ac nē Iudaeī tot malīs oppressī rebellārent, praesidium in arce collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"innuo","latin":"innuo, innuere, innui, innutus","headword":"innuo","letter":"i","pos":"verb","posGroup":"verb","english":"nod or beckon (to)","forms":["innuet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Innuet}} illa, ferās! scrībet,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inopia","latin":"inopia, -ae","headword":"inopia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"lack; scarcity, want","forms":["inopia","inopiae","inopiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut {{inopiam}} non laturos aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inopinans","latin":"inopinans, (gen.), inopinantis","headword":"inopinans","letter":"i","pos":"adjective","posGroup":"adjective","english":"unaware, off guard; unexpected, not expecting","forms":["inopinantes","inopinantibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quibus oppressis {{inopinantibus}}, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inops","latin":"inops, (gen.), inopis","headword":"inops","letter":"i","pos":"adjective","posGroup":"adjective","english":"weak, poor, needy, helpless; lacking, destitute (of), meager","forms":["inops"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"465 Quis, nisi mentis {{inops}}, tenerae dēclāmat amīcae?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"inquiam","latin":"inquiam, -, -","headword":"inquiam","letter":"i","pos":"verb","posGroup":"verb","english":"say (defective); (postpositive - for direct quote); [inquiens => saying]","forms":["inquam","inque","inquis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec si, {{inquam}}, attuleris, venuste noster,","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"inquies","latin":"inquies, (gen.), inquietis","headword":"inquies","letter":"i","pos":"adjective","posGroup":"adjective","english":"restless, impatient; full of tumult","forms":["inquiēs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"'Cūr dīxistī?' {{inquiēs}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"inquilinus","latin":"inquilinus, inquilini","headword":"inquilinus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"inhabitant of same house, tenant, lodger; inhabitant, denizen; type of serf","forms":["inquilīnus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tullius, {{inquilīnus}} cīvis urbis Rōmae.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inquirere","latin":"(inquīrō) inquīrere (< quaero)","headword":"inquīrere","letter":"i","pos":"","posGroup":"other","english":"inquire, make inquiries","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inquiro","latin":"inquiro, inquirere, inquisivi, inquisitus","headword":"inquiro","letter":"i","pos":"verb","posGroup":"verb","english":"examine, investigate, scrutinize; seek grounds for accusation; search, seek","forms":["inquīrendum","inquīsītam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mulier, istam rem {{inquīsītam}} certum est nōn āmittere.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"inquit","latin":"inquit, inquiunt","headword":"inquit","letter":"i","pos":"verb","posGroup":"verb","english":"(he/she) says/said; he says, she says, said; says, said","forms":["inquiēbat","inquit","inquiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"'Haec,' {{inquit}}, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine vestro sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inrequietus","latin":"inrequietus, inrequieta, inrequietum","headword":"inrequietus","letter":"i","pos":"adjective","posGroup":"adjective","english":"restless, troubled","forms":["inrequiēta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Scylla latus dextrum, laevum {{inrequiēta}} Charybdis\nīnfestat; vorat haec raptās revomitque carīnās;\nilla ferīs canibus succingitur, illa etiam nunc\nvirginis ōra gerēns, et, sī nōn omnia vātēs\nficta relīquērunt, aliquō quoque tempore virgō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"inrideo","latin":"inrideo, inridere, inrisi, inrisus","headword":"inrideo","letter":"i","pos":"verb","posGroup":"verb","english":"laugh at, ridicule","forms":["inrīsa"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"'ēn, quid agō? rūrsusne procōs {{inrīsa}} priōrēs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"inrigo","latin":"inrigo, inrigare, inrigavi, inrigatus","headword":"inrigo","letter":"i","pos":"verb","posGroup":"verb","english":"water/irrigate; inundate/flood; refresh; wet/moisten; diffuse, shed (sensation)","forms":["inrigat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{inrigat}}, et fōtum gremiō dea tollit in altōs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"inrumpo","latin":"inrumpo, inrumpere, inrupi, inruptus","headword":"inrumpo","letter":"i","pos":"verb","posGroup":"verb","english":"invade; break/burst/force/rush in/upon/into, penetrate; intrude on; interrupt","forms":["inrumpit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"interiōra domūs {{inrumpit}} līmina et altōs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"insanabilis","latin":"insānābilis, -e","headword":"insānābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"incurable","forms":["īnsānābile"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nunc, quoniam tuum īnsānābile ingenium est, at tū tuō suppliciō docē hūmānum genus ea sāncta crēdere quae ā tē violāta sunt!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insania","latin":"īnsānia, -ae","headword":"īnsānia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"madness","forms":["īnsānia","īnsāniam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc illa: “Quae īnsānia” inquit, “et mē et tē perdidit, Orpheu?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"insanio","latin":"insanio, insanire, insanivi, insanitus","headword":"insanio","letter":"i","pos":"verb","posGroup":"verb","english":"be mad, act crazily","forms":["īnsānīre"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sermō intereā huius cōnsūmitur omnis in ostentātiōne: quaerit ‘in agrīs frūmenta cuius modī sint?’, negat ‘sē, quia vīllae incēnsae sint, accēdere posse, nec aedificāre etiamnunc audēre’, “tametsī in Tūsculānō quīdam coepit īnsānīre et in iīsdem fundāmentīs aedificāre.”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"insanum","latin":"insanum","headword":"insanum","letter":"i","pos":"adverb","posGroup":"adverb","english":"immensely, enormously, exceedingly","forms":["īnsānum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: [quī eum īnsānum esse cēnset] Quās—malum!—nūgās?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"insanus","latin":"īnsānus, -a, -um","headword":"īnsānus","letter":"i","pos":"adjective","posGroup":"adjective","english":"mad, insane; maddened, insane","forms":["īnsāna","īnsānīs","īnsānissimae","īnsānō","īnsānus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dum carmine maestissimō dulcissimōque vātēs Orpheus silvās et animālia fera et saxa dūra quidem movet, ecce turba Maenadum īrāta et īnsāna, pectoribus velleribus tēctīs, eum dē monte vīdit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"insatiabilis","latin":"īnsatiābilis, -e","headword":"īnsatiābilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"insatiable","forms":["īnsatiābilī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Duodecim mīlia sē Sullae dēdidērunt, cēterī in aciē, in castrīs, in fugā īnsatiābilī īrā victōrum cōnsūmptī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inscendo","latin":"inscendo, inscendere, inscendi, inscensus","headword":"inscendo","letter":"i","pos":"verb","posGroup":"verb","english":"climb on, ascend, mount","forms":["īnscendās"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Quadrīgās sī nunc īnscendās Iovis","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"insciens","latin":"īnsciēns (gen. īnscientis)","headword":"īnsciēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"not knowing, unaware","forms":["īnscientibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Gortȳniī templum magnā cūrā custōdiunt, nōn tam ā cēterīs quam ab Hannibale, nē ille īnscientibus iīs tolleret sēcumque dūceret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inscientia","latin":"inscientia, inscientiae","headword":"inscientia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ignorance","forms":["inscientiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quae tametsi Caesar intellegebat, tamen quam mitissime potest legatos appellat: nihil se propter {{inscientiam}} levitatemque vulgi gravius de civitate iudicare neque de sua in Aeduos benevolentia deminuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inscius","latin":"īnscius, -a, -um","headword":"īnscius","letter":"i","pos":"adjective","posGroup":"adjective","english":"not knowing, unaware","forms":["īnscia","inscii","īnsciīs","īnsciō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At ei qui Alesiae obsidebantur, praeterita die qua auxilia suorum exspectaverant, consumpto omni frumento, {{inscii}} quid in Aeduis gereretur, concilio coacto de exitu suarum fortunarum consultabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inscribere","latin":"(īnscrībō) īnscrībere, īnscrīpsisse, īnscrīptum","headword":"īnscrībere","letter":"i","pos":"verb","posGroup":"verb","english":"inscribe; to write on, inscribe","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"inscribo","latin":"inscribo, inscribere, inscripsi, inscriptus","headword":"inscribo","letter":"i","pos":"verb","posGroup":"verb","english":"write on/in; inscribe, brand; record as; entitle","forms":["īnscrībant","īnscrībat","īnscrībendum","īnscrībere","īnscrībit","īnscrībitur","īnscrīpsit","īnscrīptam","īnscrīptum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iānitor: “Ergō lege mihi id quod in solō īnscrīptum est īnfrā hanc imāginem.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"inscriptio","latin":"inscriptio, inscriptionis","headword":"inscriptio","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"inscription","forms":["īnscrīptiōnem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ostendite mihi dēnārium! — Cuius habet imāginem et īnscrīptiōnem?” Respondentēs dīxērunt: “Caesaris.” Et ait illīs: “Reddite ergō quae Caesaris sunt Caesarī — et quae Deī sunt Deō!”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"insepultus","latin":"īnsepultus, -a, -um","headword":"īnsepultus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unburied","forms":["īnsēpultum","īnsepultus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec in pāce rēgnō fruātur, sed ipse ante diem cadat īnsepultus!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insequi","latin":"(īnsequor) īnsequī (< sequī)","headword":"īnsequī","letter":"i","pos":"","posGroup":"other","english":"follow, pursue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"insequor","latin":"insequor, insequi, insecutus sum","headword":"insequor","letter":"i","pos":"verb","posGroup":"verb","english":"follow/come after; attack; overtake; pursue (hostile); come after (time)","forms":["insecuti","insecutis","īnsecūtus","insequendum","insequentes","Insequentī","Īnsequere","insequerentur","īnsequitur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id silentio noctis conati non magna iactura suorum sese effecturos sperabant, propterea quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua intercedebat, Romanos ad {{insequendum}} tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insero","latin":"insero, inserere, inserui, insertus","headword":"insero","letter":"i","pos":"verb","posGroup":"verb","english":"plant, sow; graft on; put in, insert","forms":["Īnsere","īnserere","īnseruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tum dētrāxit ē manū suā annulum, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō torquem aureum circumdedit, eumque in currū suō secundum collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"insidere","latin":"(īnsideō) īnsidēre (< sedēre)","headword":"īnsidēre","letter":"i","pos":"","posGroup":"other","english":"hold, occupy, be seated; occupy, settle, be fixed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"insidia","latin":"insidia, insidiae","headword":"insidia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ambush/ambuscade (pl.); plot; treachery, treacherous attack/device; trap/snare","forms":["īnsidiae","insidiarum","insidias","īnsidiīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum iam muro turres appropinquassent, ex captivis Caesar cognovit Vercingetorigem consumpto pabulo castra movisse propius Avaricum atque ipsum cum equitatu expeditisque qui inter equites proeliari consuessent {{insidiarum}} causa eo profectum quo nostros postero die pabulatum venturos arbitraretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insidiae","latin":"īnsidiae, -ārum (pl.)","headword":"īnsidiae","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"ambush, plot, wiles; ambush, treachery; ambush, trap","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"insidiari","latin":"(īnsidior) īnsidiārī","headword":"īnsidiārī","letter":"i","pos":"","posGroup":"other","english":"lie in wait, lie in ambush","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"insidiator","latin":"īnsidiātor, -ōris (m.)","headword":"īnsidiātor","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"waylayer, one who lies in ambush; ambusher, assassin","forms":["īnsidiātōrēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae postquam Massīva agitāre coepit, neque Iugurthae in amīcīs satis praesidiī est, Bomilcarī, proximō et maximē fidō sibi, imperat, pretiō īnsidiātōrēs Massīvae paret ac maximē occultē Numidam interficiat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insidior","latin":"īnsidior, -ārī, īnsidiātus sum","headword":"īnsidior","letter":"i","pos":"verb","posGroup":"verb","english":"lie in wait for, plot against (+ dat.)","forms":["īnsidiantem","īnsidiantibus","īnsidiārī","īnsidiātī","īnsidiātum","īnsidiātus","īnsidior"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam sī mea facta requīris, hostibus īnsidior, fossā mūnīmina cingō, cōnsōlor sociōs, ut longī taedia bellī mente ferant placidā, doceō, quō sīmus alendī armandīque modō, mittor, quō postulat ūsus.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"insidiosus","latin":"insidiosus, insidiosa -um, insidiosior -or -us, insidiosissimus -a -um","headword":"insidiosus","letter":"i","pos":"adjective","posGroup":"adjective","english":"treacherously; deceitfully; cunningly; stealthily; insidiously","forms":["īnsidiōsa"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Pācifer huic dederat flōrem Mercurius album:\nmōly vocant superī, nigrā rādīce tenētur;\ntūtus eō monitīsque simul caelestibus intrat\nille domum Circēs et ad īnsidiōsa vocātus\npōcula cōnantem virgā mulcēre capillōs\nreppulit et strictō pavidam dēterruit ēnse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"insido","latin":"insido, insidere, insedi, insessus","headword":"insido","letter":"i","pos":"verb","posGroup":"verb","english":"sit/settle on; occupy/seize, hold (position); penetrate, sink in; merge into","forms":["īnsēderat","īnsessa","īnsīdat","īnsidēbat","īnsīdentem","insidi"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"insigne","latin":"īnsigne, -is (n.)","headword":"īnsigne","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"mark, token, symbol; badge, mark, trophy","forms":["insigne"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hi similitudine armorum vehementer nostros perterruerunt, ac, tametsi dextris umeris exsertis animadvertebantur, quod {{insigne}} pactum esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insignis","latin":"īnsignis, -e","headword":"īnsignis","letter":"i","pos":"adjective","posGroup":"adjective","english":"noted, remarkable","forms":["īnsignem","insigni","īnsignia","īnsignibus","Īnsignis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eius adventu ex colore vestitus cognito, quo {{insigni}} in proeliis uti consuerat, turmisque equitum et cohortibus visis quas se sequi iusserat, ut de locis superioribus haec declivia et devexa cernebantur, hostes proelium committunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insilio","latin":"insilio, insilire, insilui, -","headword":"insilio","letter":"i","pos":"verb","posGroup":"verb","english":"come/leap upon/in; leap/spring up/at; attack/throw oneself upon; bound; mount","forms":["īnsiluit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lupus, ut agnum vīdit, sīc ait: “Cūr turbāvistī mihi aquam bibentī?” Agnus patiēns dīxit: “Quōmodo aquam tibi turbāvī, quae ā tē ad mē dēcurrit?” Cui lupus “Ante hōs sex mēnsēs” inquit “maledīxistī mihi!” Agnus ait: “Nōn maledīxī tibi, nam tunc ego nātus nōn eram!” Lupus dīxit: “Ergō pater tuus maledīxit mihi!” — et statim īnsiluit in eum et innocentī vītam ēripuit!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"insimulo","latin":"insimulo, insimulare, insimulavi, insimulatus","headword":"insimulo","letter":"i","pos":"verb","posGroup":"verb","english":"accuse, charge; allege","forms":["īnsimulābant","īnsimulāre","insimulati","insimulatis","īnsimulātūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis {{insimulatis}}; cuius opera sine vestro sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insistere","latin":"(īnsistō) īnsistere, -itisse","headword":"īnsistere","letter":"i","pos":"","posGroup":"other","english":"stand (on), pursue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"insisto","latin":"insisto, insistere, institi, -","headword":"insisto","letter":"i","pos":"verb","posGroup":"verb","english":"stand/tread upon, stand, stop; press on, persevere (with); pursue, set about","forms":["īnsistit","īnsistunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Duō sunt habitābilēs, quōrum austrālis ille, in quō quī īnsistunt adversa vōbīs urgent vestīgia, nihil ad vestrum genus; hic autem alter subiectus aquilōnī quem incolitis, cerne quam tenuī vōs parte contingat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insolens","latin":"īnsolēns (gen. īnsolentis)","headword":"īnsolēns","letter":"i","pos":"adjective","posGroup":"adjective","english":"haughty, arrogant","forms":["īnsolēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec atque alia similia cum homō īnsolēns iactāret, intervenit Tarquinius.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insolentia","latin":"īnsolentia, -ae","headword":"īnsolentia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"unusualness; arrogance; arrogance, excess","forms":["īnsolentiā","īnsolentiae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde, victōriīs dīvitiīsque subnīxus, exsultābat īnsolentiā neque suōs mōrēs regere poterat neque suōrum libīdinēs.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insolitus","latin":"īnsolitus, -a, -um","headword":"īnsolitus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unusual, unwonted","forms":["īnsolitā","īnsolitus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huius adventus et Mithridātem īnsolitā īnflātum victōriā continuit et Tigrānem magnīs cōpiīs minitantem Asiae retardāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"insomnium","latin":"insomnium, insomni(i)","headword":"insomnium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"wakefulness; vision, dream","forms":["īnsomnia","īnsomniīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā Rōmae multa simul mōlīrī, cōnsulibus īnsidiās tendere, parāre incendia, opportūna loca armātīs hominibus obsīdere, ipse cum tēlō esse, item aliōs iubēre, hortārī utī semper intentī parātīque essent, diēs noctēsque festīnāre, vigilāre, neque īnsomniīs neque labōre fatīgārī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"insons","latin":"īnsōns (gen. īnsontis)","headword":"īnsōns","letter":"i","pos":"adjective","posGroup":"adjective","english":"innocent","forms":["īnsons","īnsontem","īnsontēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Id ubi rēx cognōvit, fīlium morte plectī voluit; sed recēns meritum perīculō iuvenem exēmit, nec populus tulit īnsontem ad supplicium trahī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inspecto","latin":"inspecto, inspectare, inspectavi, inspectatus","headword":"inspecto","letter":"i","pos":"verb","posGroup":"verb","english":"look at, observe; look on, watch","forms":["īnspectantibus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Iam hic dēlūdētur, spectātōrēs, vōbīs īnspectantibus!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"insperatus","latin":"īnspērātus, -a, -um","headword":"īnspērātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"not hoped for, unexpected","forms":["īnspērāta","īnspērātam","īnspērāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Lāvīniō quidem īnspērāta pāx erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inspicere","latin":"(īnspiciō) īnspicere, -spexisse, -spectum","headword":"īnspicere","letter":"i","pos":"","posGroup":"other","english":"examine, inspect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inspicio","latin":"inspicio, inspicere, inspexi, inspectus","headword":"inspicio","letter":"i","pos":"verb","posGroup":"verb","english":"examine, inspect; consider, look into/at, observe","forms":["īnspectūra","īnspexī","īnspice","īnspīcēre","inspiceret","īnspiciam","īnspiciās","īnspiciēbant","īnspiciendās","īnspiciendī","īnspiciēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"“Heu, quid faciam?” sē ipsa interrogābat, “parēamne Iovī an vās aperiam?” Fēmina, quae animō valdē perturbāta erat, nesciēbat quid faceret: saepe tam cupida erat īnspiciendī quid in illō vāse inesset, ut manum extenderet ad aperiendum; sed continuō manum retrahēbat, ut īram Iovis vītāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"inspiro","latin":"inspiro, inspirare, inspiravi, inspiratus","headword":"inspiro","letter":"i","pos":"verb","posGroup":"verb","english":"inspire; excite, inflame; instill, implant; breathe into; blow upon/into","forms":["īnspīrēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"occultum īnspīrēs ignem fallāsque venēnō.'","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"instans","latin":"instans, (gen.), instantis","headword":"instans","letter":"i","pos":"adjective","posGroup":"adjective","english":"eager; urgent; present","forms":["īnstāns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"per mediōs, īnstāns operī rēgnīsque futūrīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"instar","latin":"instar, undeclined","headword":"instar","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"image, likeness, resemblance; counterpart; the equal/form of (w/GEN)","forms":["īnstar"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Appropinquante arca, aquae, quae superne dēfluēbant, stetērunt īnstar mūrī; quae autem īnfrā, dēscendērunt, et alveum siccum relīquērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"instare","latin":"(īnstō) īnstāre","headword":"īnstāre","letter":"i","pos":"","posGroup":"other","english":"press, urge, insist","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"instaurare","latin":"(īnstaurō) īnstaurāre","headword":"īnstaurāre","letter":"i","pos":"","posGroup":"other","english":"renew","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"instauro","latin":"instauro, instaurare, instauravi, instauratus","headword":"instauro","letter":"i","pos":"verb","posGroup":"verb","english":"renew, repeat, restore","forms":["instaurāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sinite {{instaurāta}} revīsam proelia!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"instigare","latin":"(īnstīgō) īnstīgāre","headword":"īnstīgāre","letter":"i","pos":"","posGroup":"other","english":"urge, incite","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"instigo","latin":"instigo, instigare, instigavi, instigatus","headword":"instigo","letter":"i","pos":"verb","posGroup":"verb","english":"urge on; incite, rouse","forms":["īnstīgat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hīs aliīsque increpandō iuvenem īnstīgat, nec conquiēscere ipsa potest, sī — cum Tanaquil, peregrīna mulier, duo continua rēgna virō ac deinceps generō dedisset — ipsa, rēgiō sanguine orta, nec dare nec adimere rēgnum posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"instimulo","latin":"instimulo, instimulare, instimulavi, instimulatus","headword":"instimulo","letter":"i","pos":"verb","posGroup":"verb","english":"goad on","forms":["īnstimulat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ecce iterum īnstimulat. sequimur tē, sāncte deōrum,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"instinctus","latin":"instinctus, instinctus","headword":"instinctus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"inspiration; instigation","forms":["īnstīnctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hōc muliebrī furōre īnstīnctus Tarquinius circumīre et conciliāre sibi patrēs, admonēre Tarquiniī Prīscī beneficiī ac prō eō grātiam repetere, allicere dōnīs iuvenēs, cum ingentia pollicendō, tum rēgis crīminibus, omnibus locīs crēscere.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"instita","latin":"instita, institae","headword":"instita","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"band on a dress","forms":["īnstita"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"īnstita -ae f, mātrōnae vestis longa","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"institor","latin":"institor, institoris","headword":"institor","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"shopkeeper, peddler; who displays (thing) as if for sale","forms":["Īnstitor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Īnstitor ad dominam veniet discīnctus emàcem,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"instituere","latin":"(īnstituō) īnstituere, -tuisse, set","headword":"īnstituere","letter":"i","pos":"","posGroup":"other","english":"up, establish, start, appoint,","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"instituo","latin":"instituo, instituere, institui, institutus","headword":"instituo","letter":"i","pos":"verb","posGroup":"verb","english":"set up, establish, found, make, institute; build; prepare; decide","forms":["īnstituās","instituebatur","īnstituendīs","īnstituendō","instituerat","instituerent","īnstituerētur","instituerunt","institui","īnstituisse","īnstituistī","instituit","īnstitūtae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota provincia habere {{instituit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"institutum","latin":"īnstitūtum, -ī","headword":"īnstitūtum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"practice, custom, usage","forms":["īnstitūta","īnstitūtīs","instituto","īnstitūtum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tamen, quod {{instituto}} Caesaris semper duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque interscinderent, omnis vero ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insto","latin":"īnstō, -āre, īnstitī","headword":"īnstō","letter":"i","pos":"verb","posGroup":"verb","english":"press on, stand upon","forms":["instabant","īnstābat","īnstandō","īnstant","Īnstante","īnstāre","īnstāret","īnstat","īnstiterat","īnstitisset","īnstitit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Namque altera ex parte Bellovaci, quae civitas in Gallia maximam habet opinionem virtutis, {{instabant}}, alteram Camulogenus parato atque instructo exercitu tenebat; tum legiones a praesidio atque impedimentis interclusas maximum flumen distinebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"instructus","latin":"instructus, instructus","headword":"instructus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"equipment, apparatus","forms":["īnstrūctus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Exercitus ita īnstrūctus aciēs appellātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"instruere","latin":"(īnstruō) īnstruere, īnstrūxisse, īnstrūctum","headword":"īnstruere","letter":"i","pos":"verb","posGroup":"verb","english":"draw up, arrange; to draw up, arrange","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"instrumentum","latin":"īnstrūmentum, -ī","headword":"īnstrūmentum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"tool, instrument","forms":["īnstrūmenta","īnstrūmentō","īnstrūmentum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ignis erit īnstrūmentum omnium artium, quās vōs continuō docēbō!” Hominēs igitur, quī circā Promēthēum erant, statim didicērunt quōmodo ignem servārent eōque ad artēs variās ūterentur; deinde, per nūntiōs, etiam aliī ea, quae Promētheus docuerat, cognōvērunt atque ipsī in campīs ignēs accendere coepērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"instruo","latin":"īnstruō","headword":"īnstruō","letter":"i","pos":"verb","posGroup":"verb","english":"to draw up, arrange","forms":["instructa","īnstrūctae","īnstrūctās","īnstrūctī","instructo","īnstrūctōs","īnstrūctum","īnstruere","īnstruerētur","īnstruī","īnstruit","īnstruitur","īnstruunt","īnstruuntur","instruxerunt","īnstrūximus","īnstrūxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in artiores silvas abdiderunt, copias omnes in loco edito atque aperto {{instruxerunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insuescere","latin":"(īnsuēscō) īnsuēscere, -ēvisse, -ētum","headword":"īnsuēscere","letter":"i","pos":"","posGroup":"other","english":"become accustomed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"insuetus","latin":"insuetus, insueta, insuetum","headword":"insuetus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unused/unaccustomed to (w/GEN/DAT), unusual","forms":["insueti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Simul in spem veniebant eius adfirmatione de reliquis adiungendis civitatibus; primumque eo tempore Galli castra munire instituerunt; et sic sunt animo consternati homines {{insueti}} laboris ut omnia quae imperarentur sibi patienda existimarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insula","latin":"īnsula, -ae","headword":"īnsula","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"island","forms":["insula","īnsulae","īnsulam","īnsulārum","īnsulās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id est oppidum Parisiorum, quod positum est in {{insula}} fluminis Sequanae.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insulto","latin":"insulto, insultare, insultavi, insultatus","headword":"insulto","letter":"i","pos":"verb","posGroup":"verb","english":"leap/jump/spring (in/on); dance/trample (on); enter with a leap","forms":["īnsultāre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat Philistaeīs mōs, cum diēs fēstōs agerent, prōdūcere Samsōnem quasi in pompam pūblicam, captōque īnsultāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"insum","latin":"insum, inesse, infui, infuturus","headword":"insum","letter":"i","pos":"verb","posGroup":"verb","english":"be in/on/there; belong to; be involved in","forms":["inerat","inerit","inesse","inesset","inest","īnsunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Inerat}} huic cibō gustus similiae cum melle mixtae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"insuper","latin":"īnsuper","headword":"īnsuper","letter":"i","pos":"preposition","posGroup":"preposition","english":"in addition","forms":["insuper"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His collocatis et coagmentatis alius {{insuper}} ordo additur, ut idem illud intervallum servetur neque inter se contingant trabes, sed paribus intermissae spatiis singulae singulis saxis interiectis arte contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"insuperabilis","latin":"insuperabilis, insuperabilis, insuperabile","headword":"insuperabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"insurmountable; unconquerable","forms":["īnsuperābile"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"hinc Gaetūlae urbēs, genus īnsuperābile bellō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"intactus","latin":"intāctus, -a, -um","headword":"intāctus","letter":"i","pos":"adjective","posGroup":"adjective","english":"untouched, uninjured","forms":["intāctam","intāctum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Alterum {{intāctum}} ferrō corpus et gemināta victōria ferōcem in certāmen tertium dabat; alter, fessum vulnere fessum cursū corpus trahēns vīctusque frātrum ante sē strāge, victōrī obicitur hostī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"integer","latin":"integer, -ra, -rum","headword":"integer","letter":"i","pos":"adjective","posGroup":"adjective","english":"whole, undamaged; whole, intact, unbroken","forms":["integer","integra","integrae","integram","integri","integrīs","integros","integrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et maxime, quod ipse animo non defecerat tanto accepto incommodo neque se in occultum abdiderat et conspectum multitudinis fugerat; plusque animo providere et praesentire existimabatur, quod re {{integra}} primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intego","latin":"intego, integere, intexi, intectus","headword":"intego","letter":"i","pos":"verb","posGroup":"verb","english":"cover; cover over","forms":["integebatur","integunt","intexerant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Totum autem murum ex omni parte turribus contabulaverant atque has coriis {{intexerant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"integritas","latin":"integritas, integritatis","headword":"integritas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"soundness; chastity; integrity","forms":["integritāte"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caesar beneficiīs ac mūnificentiā magnus habēbātur, {{integritāte}} vītae Catō.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"integro","latin":"integro, integrare, integravi, integratus","headword":"integro","letter":"i","pos":"verb","posGroup":"verb","english":"renew; refresh; integrate (Cal)","forms":["integrō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī rēgnō ita potītus urbem novam, conditam vī et armīs, iūre lēgibusque ac mōribus dē integrō condere parat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"intellegens","latin":"intellegens, (gen.), intellegentis","headword":"intellegens","letter":"i","pos":"adjective","posGroup":"adjective","english":"intelligent; discerning","forms":["intellegēns"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At illum ingēns cūra atque laetitia simul occupāvēre: nam laetābātur {{intellegēns}} coniūrātiōne patefactā cīvitātem perīculīs ēreptam esse; porrō autem ānxius erat dubitāns, in maximō scelere tantīs cīvibus dēprehēnsīs, quid factō opus esset, poenam illōrum sibi onerī, impūnitātem perdundae reī pūblicae fore crēdēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"intellegere","latin":"intellegere","headword":"intellegere","letter":"i","pos":"verb","posGroup":"verb","english":"to understand","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"intellego","latin":"intellegō, intellegere","headword":"intellegō","letter":"i","pos":"verb","posGroup":"verb","english":"understand","forms":["intellectum","intellegant","intellegās","Intellegēbam","intellegebant","intellegebat","intellegēbātur","intellegere","intellegerent","intellegeret","intellegēs","intellegī","intellegis","intellegit","intellegitis","intellegō","intellegunt","intellexerant","intellēxerat","intellēxērunt","intellēxī","intellēxissem","intellexissent","intellēxisset","intellēxistī","intellēxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Pompei commodiorem in statum pervenisse {{intellegeret}}, in Transalpinam Galliam profectus est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intemperies","latin":"intemperies, intemperiei","headword":"intemperies","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"lack of temperateness (of weather, etc); outrageous behavior","forms":["intemperiēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Senātōrēs ingredientēs in Cūriam, quae illa mulierum {{intemperiēs}} et quid sibi postulātiō istaec vellet, mīrābantur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"intempestus","latin":"intempestus, intempesta, intempestum","headword":"intempestus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unseasonable stormy, unhealthy; nox intempesta the dead of night","forms":["intempestā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postrēmō, ubi multa agitantī nihil prōcēdit, rūrsus intempestā nocte coniūrātiōnis prīncipēs convocat per M.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"intendere","latin":"(intendō) intendere, -disse, -tum","headword":"intendere","letter":"i","pos":"","posGroup":"other","english":"strain, direct, strive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intendo","latin":"intendo, intendere, intendi, intentus","headword":"intendo","letter":"i","pos":"verb","posGroup":"verb","english":"hold out; stretch, strain, exert","forms":["intenderīs","intendit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ezechliis, tantō perlcūlō lTuerātus, in summā pāce reliquum vītae tempus ēgit: omnī ā illī reliciter cēdēbant, quia Deus illī favēbat; ipse tot beneficiīs dīvīnīs obligātus, in eādem cōnstanter pietāte mānsit: omnem suam spem in Deī auxiliō posuit; iīs rēbus, quae Deō placēbant, animum semper {{intendit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intentio","latin":"intentiō, -ōnis ( f.)","headword":"intentiō","letter":"i","pos":"","posGroup":"other","english":"charge, accusation","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intento","latin":"intento, intentare, intentavi, intentatus","headword":"intento","letter":"i","pos":"verb","posGroup":"verb","english":"point (at); point (weapons, etc) in a threatening manner, threaten","forms":["intentant","intentāvī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cônstemätî nôs însolentiä ëbriôrum intentāvī- que ē gastñs lābentia, quae collēcta puer lance circum- Hās lautitiās aequāvit ingeniôsus cocus: in crätîculä enim argenteā cochleâs attulit et tremulā taeterrimāque Pudet referre quae secuntur: inaudîtô enim môre puerî capillätî attulērunt unguentum in argenteā pēlve pedësque recumbentium ūnxērunt, cum ante crūra tälôsque corônîs vînxissent.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"intentus","latin":"intentus, -a, -um","headword":"intentus","letter":"i","pos":"adjective","posGroup":"adjective","english":"intent, attentive","forms":["intenti","intentīs","intentōs","intentum","intentus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat ex omnibus castris, quae summum undique iugum tenebant, despectus, atque omnes milites {{intenti}} pugnae proventum exspectabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"inter","latin":"inter","headword":"inter","letter":"i","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) between, among, during; between, among (with acc.)","forms":["inter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis {{inter}} se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intercedere","latin":"(intercēdō) intercēdere (< cēdere)","headword":"intercēdere","letter":"i","pos":"","posGroup":"other","english":"intervene, intercede","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intercedo","latin":"intercedo, intercedere, intercessi, intercessus","headword":"intercedo","letter":"i","pos":"verb","posGroup":"verb","english":"intervene; intercede, interrupt; hinder; veto; exist/come between","forms":["intercedebat","intercederet","intercessit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Id silentio noctis conati non magna iactura suorum sese effecturos sperabant, propterea quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua {{intercedebat}}, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intercludere","latin":"(interclūdō) interclūdere (< claudere)","headword":"interclūdere","letter":"i","pos":"","posGroup":"other","english":"shut out, cut off, block","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intercludo","latin":"intercludo, intercludere, interclusi, interclusus","headword":"intercludo","letter":"i","pos":"verb","posGroup":"verb","english":"cut off; blockade; hinder, block up","forms":["intercludatur","interclūderentur","interclusas","intercluserant","interclusis","interclūsōs","interclusum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, prius quam eorum clandestina consilia efferantur, ut Caesar ab exercitu {{intercludatur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interdico","latin":"interdico, interdicere, interdixi, interdictus","headword":"interdico","letter":"i","pos":"verb","posGroup":"verb","english":"forbid, interdict, prohibit; debar (from)","forms":["interdīcēbat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Īnsignis fuit Eleazarī senis cōnstantia: is apertō ōre compellēbātur camem suillam comedere, quā Hidaeis lēx {{interdīcēbat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interdiu","latin":"interdiū","headword":"interdiū","letter":"i","pos":"adverb","posGroup":"adverb","english":"by day","forms":["interdiu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castra opportunis locis erant posita, ibique castella XXIII facta, quibus in castellis {{interdiu}} stationes ponebantur, ne qua subito: eruptio fieret; haec eadem noctu excubitoribus ac firmis praesidiis tenebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interdum","latin":"interdum","headword":"interdum","letter":"i","pos":"adverb","posGroup":"adverb","english":"now and then; sometimes","forms":["interdum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Interdum}} etiam dēfuit aquā: at, iubente Deō, Moysēs percutiēbat rūpem virgā, et continuō ērumpēbant fontēs aquae dulcis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interea","latin":"intereā","headword":"intereā","letter":"i","pos":"adverb","posGroup":"adverb","english":"meanwhile","forms":["intereā"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Interea}} aequum esse ab eis communis salutis causa impetrari ut castra munire instituerent, quo facilius repentinos hostium impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interemo","latin":"interemo, interemere, interemi, interemptus","headword":"interemo","letter":"i","pos":"verb","posGroup":"verb","english":"do away with; kill, cut off from life; extinguish; put an end to, destroy","forms":["interēmisse","interēmit","interemptī","interemptīs","interemptō","interemptōrum","interēmptum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sōlō armigerō comite, castra hostium ingressus est, et vīgintī ferē Philistaeīs {{interemptīs}}, ūniversum exercitum terrōre perculit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intereo","latin":"intereo, interire, interivi(ii), interitus","headword":"intereo","letter":"i","pos":"verb","posGroup":"verb","english":"perish, die; be ruined; cease","forms":["Inteream","interibant","interībit","interīre","interit","interitura","interitūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quod si indiligentiores fuerint, milia hominum delecta LXXX una secum {{interitura}} demonstrat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interest","latin":"interest, interesse","headword":"interest","letter":"i","pos":"","posGroup":"other","english":"be between","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"interficere","latin":"(interficiō) interficere, interfēcisse, interfectum","headword":"interficere","letter":"i","pos":"verb","posGroup":"verb","english":"kill; to kill","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"interficio","latin":"interficiō, -ere, -fēcī, -fectum","headword":"interficiō","letter":"i","pos":"verb","posGroup":"verb","english":"kill","forms":["interfēcerant","interfecērunt","interfēcī","interfēcissent","interfēcisset","interfēcistī","interfēcit","interfecta","interfecti","interfectis","interfectō","interfectorum","interfectos","interfectum","interfectūrōs","interfectus","interficere","interficerent","interficerentur","interficeret","interficerētur","interfici","interficiāminī","interficiamus","interficiant","interficiat","interficiēbantur","interficiendī","interficiendos","interficiendum","interficiēre","interficit","interficitur","interficiunt","interficiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postremo in acie praestare {{interfici}} quam non veterem belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interfluo","latin":"interfluo, interfluere, interfluxi, -","headword":"interfluo","letter":"i","pos":"verb","posGroup":"verb","english":"flow between or through","forms":["interfluēbat"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Annō XVI Arminius cum Flāvō frātre, quī tunc in exercitū Rōmānō merēbat, hoc colloquium habuisse dīcitur trāns Visurgim flūmen, quod exercitūs in utrāque rīpā locātōs {{interfluēbat}}.]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"interfor","latin":"interfor, interfari, interfatus sum","headword":"interfor","letter":"i","pos":"verb","posGroup":"verb","english":"interrupt, interpose; break in conversation; speak between/while other speaking","forms":["interfāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"passa Venus mediō sīc {{interfāta}} dolōre est:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"interfusus","latin":"interfusus, interfusa, interfusum","headword":"interfusus","letter":"i","pos":"adjective","posGroup":"adjective","english":"poured/flowing/spread out between, suffused here and there","forms":["interfūsa"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{interfūsa}} genās et pallida morte futūra,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"interiacio","latin":"interjacio, interjacere, interjaeci, interjaectus","headword":"interjacio","letter":"i","pos":"verb","posGroup":"verb","english":"put/throw between; interpose; insert; introduce","forms":["interiaciēbat"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cernēbātur contrā minitābundus Arminius ‘proeliumque’ dēnūntiāns — nam plēraque Latīnō sermōne {{interiaciēbat}}, ut quī Rōmānīs in castrīs ductor populārium meruisset.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"interiectio","latin":"interiectiō, interiectiōnis","headword":"interiectiō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"(f.) interjection","forms":["interiectiō","interiectiōnēs","interiectiōnis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister discipulum interrogat: 'Partēs ōrātiōnis quot sunt?' Discipulus respondet: 'Octō.' Magister: 'Quae?' Discipulus: 'Nōmen, prōnōmen, verbum, adverbium, participium, coniūnctiō, praepositiō, interiectiō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"interiectus","latin":"interiectus, -a, -um","headword":"interiectus","letter":"i","pos":"adjective","posGroup":"adjective","english":"situated between","forms":["interiecta","interiectās","interiectis","interiecto","interiectum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio {{interiecto}}, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interiicio","latin":"interjicio, interjicere, interjeci, interjectus","headword":"interjicio","letter":"i","pos":"verb","posGroup":"verb","english":"put/throw between; interpose; insert; introduce","forms":["interiecerant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Galli inter equites raros sagittarios expeditosque levis armaturae {{interiecerant}}, qui suis cedentibus auxilio succurrerent et nostrorum equitum impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interim","latin":"interim","headword":"interim","letter":"i","pos":"adverb","posGroup":"adverb","english":"meanwhile","forms":["interim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Interim}} Lucterius Cadurcus in Rutenos missus eam civitatem Arvernis conciliat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interimere","latin":"(interimō) interimere (< emere)","headword":"interimere","letter":"i","pos":"","posGroup":"other","english":"kill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"interimo","latin":"interimo, interimere, interimi, interemptus","headword":"interimo","letter":"i","pos":"verb","posGroup":"verb","english":"do away with; kill, cut off from life; extinguish; put an end to, destroy","forms":["interimam","interimērunt","interimit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum Absalōn adhūc palpitāret haerēns in quercū, armigerī Iōābī repetītīs ictibus cōnfossum {{interimērunt}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interior","latin":"interior, interius","headword":"interior","letter":"i","pos":"adjective","posGroup":"adjective","english":"interior, inner (part of )","forms":["interior","interiōra","interiōre","interiorem","interiores"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc intermisso spatio duas fossas quindecim pedes latas eadem altitudine perduxit, quarum {{interiorem}} campestribus ac demissis locis aqua ex flumine derivata complevit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interire","latin":"(intereō) interīre (< īre)","headword":"interīre","letter":"i","pos":"","posGroup":"other","english":"die, perish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"interitus","latin":"interitus, -ūs (< interīre Cap. XLI)","headword":"interitus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"death; death, destruction","forms":["interitū"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sermō autem omnis ille et angustiīs cingitur iīs regiōnum quās vidēs, nec umquam dē illō perennis fuit, et obruitur hominum interitū et oblīviōne posteritātis exstinguitur.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"intermittere","latin":"(intermittō) intermittere (< mittere)","headword":"intermittere","letter":"i","pos":"","posGroup":"other","english":"interupt, discontinue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intermitto","latin":"intermitto, intermittere, intermisi, intermissus","headword":"intermitto","letter":"i","pos":"verb","posGroup":"verb","english":"interrupt; omit; stop; leave off (temporarily); leave a gap","forms":["intermīsisset","intermissa","intermissae","intermissam","intermissis","intermisso","intermissum","intermitteretur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere {{intermisso}} per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"internicio","latin":"interniciō, -ōnis ( f.)","headword":"interniciō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"annihilation, massacre; slaughter, destruction","forms":["interniciōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Caepiō ā Cimbrīs et Teutonibus et Tīgurīnīs et Ambrōnibus, quae erant Germānōrum et Gallōrum gentēs, victī sunt iuxtā flūmen Rhodanum ingentī {{interniciōne}}; etiam castra sua et magnam partem exercitūs perdidērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"internosco","latin":"internosco, internoscere, internovi, internotus","headword":"internosco","letter":"i","pos":"verb","posGroup":"verb","english":"distinguish between; pick out","forms":["internōscere"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Amphitryō dēspērāns cīvēs Thēbānōs advocat, nec quisquam eōrum adulterum ac marītum {{internōscere}} potest.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"internus","latin":"internus, -a, -um","headword":"internus","letter":"i","pos":"adjective","posGroup":"adjective","english":"internal, domestic","forms":["Internō","Internum","internus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ex eō tempore rārō fit ut nāvis praedōnum in marī Internō appāreat, nam classēs Rōmānae, quae cūncta maria percurrunt, nāvēs mercātōriās atque ōram maritimam dīligenter tuentur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"interpellare","latin":"(interpellō) interpellāre, interpellāvisse, interpellātum","headword":"interpellāre","letter":"i","pos":"verb","posGroup":"verb","english":"interrupt, break in; to interrupt","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"interpello","latin":"interpellō, interpellāre","headword":"interpellō","letter":"i","pos":"verb","posGroup":"verb","english":"interrupt","forms":["interpellā","interpellābō","Interpellandī","interpellāre","interpellās","interpellat","interpellāvit","interpellet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iuppiter autem deōs ita clāmantēs {{interpellāvit}} et “Nōlīte Tantalum interficiendum esse dīcere!” inquit, “Clēmentēs ēstote!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"interponere","latin":"(interpōnō) interpōnere (< pōnere)","headword":"interpōnere","letter":"i","pos":"","posGroup":"other","english":"place between","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"interpono","latin":"interpono, interponere, interposui, interpositus","headword":"interpono","letter":"i","pos":"verb","posGroup":"verb","english":"insert, introduce; admit; allege; interpose; (interponere se = to intervene)","forms":["interpōnerentur","interposita","interpositus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati praecipue indulserat, nulla {{interposita}} dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interpres","latin":"interpres, interpretis","headword":"interpres","letter":"i","pos":"noun","posGroup":"noun","english":"interpreter, translator","forms":["interpres","interpretem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Putābant haec verba nōn intellegī ā Iōsēphō, quia per {{interpretem}} cum eīs loquēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interpretamentum","latin":"interpretamentum, interpretamenti","headword":"interpretamentum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"explanation; interpretation","forms":["interpretāmenta"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ēdiscēbam {{interpretāmenta}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"interpretatio","latin":"interpretatio, interpretationis","headword":"interpretatio","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"interpretation; meaning","forms":["interpretātiō","interpretātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et affīget ad pālum, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interpretor","latin":"interpretor, interpretari, interpretatus sum","headword":"interpretor","letter":"i","pos":"verb","posGroup":"verb","english":"explain/expound; interpret/prophesy from (dream/omen); understand/comprehend","forms":["interpretārī","interpretātus","interpretētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī respondērunt: obvenit nōbīs somnium, nec quisquam est quī illud nōbīs {{interpretētur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"interregnum","latin":"interrēgnum, -ī","headword":"interrēgnum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"interval between reigns; period between two kings","forms":["interrēgnō","interrēgnum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Id \"{{interrēgnum}}\" appellātum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"interrex","latin":"interrēx, -rēgis (m.)","headword":"interrēx","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"intermediary regent; regent between two kings","forms":["interregem","interrēgēs","interrēx"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnī simul quīnōs diēs imperitābant, quōrum prīncipēs, quī \"{{interrēgēs}}\" nōminābantur, cum īnsignibus imperiī erant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"interritus","latin":"interritus, -a, -um","headword":"interritus","letter":"i","pos":"adjective","posGroup":"adjective","english":"undaunted","forms":["interrita","interritus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Illa quidem trīstis neque etiam adhūc {{interrita}}, sed tamen est rēgīna maxima rēgnī obscūrī, tamen uxor rēgis īnfernī.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"interrogat","latin":"interrogat","headword":"interrogat","letter":"i","pos":"verb","posGroup":"verb","english":"ask, question; asks, questions","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"interrogativum","latin":"interrogātīvum","headword":"interrogātīvum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"interrogative","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"interrogo","latin":"interrogō","headword":"interrogō","letter":"i","pos":"verb","posGroup":"verb","english":"ask, question","forms":["interrogā","interrogābat","interrogāminī","interrogāmur","interrogandī","Interrogandō","interrogant","interrogantem","interrogantī","interrogantur","interrogāre","interrogāret","interrogārī","interrogāris","interrogās","interrogat","interrogāta","interrogātē","interrogati","interrogātus","interrogāverint","interrogāvērunt","interrogāvī","interrogāvisset","interrogāvit","interrogem","interroget","interrogō","interrogor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi iam ante edocti quae {{interrogati}} pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interrumpere","latin":"(interrumpō) interrumpere (< rumpere)","headword":"interrumpere","letter":"i","pos":"","posGroup":"other","english":"break up, cut, interrupt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"interrumpo","latin":"interrumpo, interrumpere, interrupi, interruptus","headword":"interrumpo","letter":"i","pos":"verb","posGroup":"verb","english":"drive a gap in, break up; cut short, interrupt","forms":["interrupta","interruptis","interruptōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qua re cognita Vercingetorix omnibus {{interruptis}} eius fluminis pontibus ab altera fluminis parte iter facere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"interscindo","latin":"interscindo, interscindere, interscidi, interscissus","headword":"interscindo","letter":"i","pos":"verb","posGroup":"verb","english":"cut down; cut through, sever","forms":["interscinderent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Tamen, quod instituto Caesaris semper duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque {{interscinderent}}, omnis vero ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intersum","latin":"intersum, interesse, interfui, interfuturus","headword":"intersum","letter":"i","pos":"verb","posGroup":"verb","english":"be/lie between, be in the midst; be present; take part in; be different","forms":["interesse","interesset","interest","interfuī","interfuissēs","interfuit","intersit","intersunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris processuros; neque {{interesse}} ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intervallo","latin":"intervallo, intervallare, intervallavi, intervallatus","headword":"intervallo","letter":"i","pos":"verb","posGroup":"verb","english":"take at intervals","forms":["intervāllō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Neque magnō intervāllō posteā Q.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"intervallum","latin":"intervāllum, -ī","headword":"intervāllum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"interval, space, distance; gap, interval","forms":["intervalla","intervallis","intervallum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Trabes directae perpetuae in longitudinem paribus {{intervallis}} distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intervenio","latin":"intervenio, intervenire, interveni, interventus","headword":"intervenio","letter":"i","pos":"verb","posGroup":"verb","english":"come between, intervene; occur, crop up","forms":["intervenerint","interveniente","intervēnimus","intervēnisset","intervēnit","interveniunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Romani si casu {{intervenerint}}, fortunae, si alicuius indicio vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intervenire","latin":"(interveniō) intervenīre (< venīre)","headword":"intervenīre","letter":"i","pos":"","posGroup":"other","english":"turn up, occur, disturb","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"interventus","latin":"interventus, -ūs (< intervenīre (Cap. XLIV)","headword":"interventus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"arrival; interruption, arrival","forms":["interventū","interventus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sed proelium id tandem dirēmit nox interventū suō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"intestina","latin":"intestina, intestinae","headword":"intestina","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"intestines","forms":["intestīna","intestīnam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Huic ab adulēscentiā bella {{intestīna}}, caedēs, rapīnae, discordia cīvīlis grāta fuēre, ibique iuventūtem suam exercuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"intimus","latin":"intimus, intima, intimum","headword":"intimus","letter":"i","pos":"adjective","posGroup":"adjective","english":"inmost; most secret; most intimate","forms":["intima"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Alphenor, fīliōrum quīntus, eōs cadentēs aspicit, et continuō accurrit, ut frīgida corpora complectātur: cadit et ipse; nam Apollō {{intima}} vīscera eī rumpit ferrō.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"intingo","latin":"intingo, intingere, intinxi, intinctus","headword":"intingo","letter":"i","pos":"verb","posGroup":"verb","english":"dip/plunge in; saturate, steep; cause to soak in; color (w/cosmetics)","forms":["intīnctam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōnāthās ēdictī paternī nescius extendit virgam quam manū tenēbat, eamque in mel {{intīnctam}} ōrī admōvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intolerabilis","latin":"intolerabilis, intolerabilis, intolerabile","headword":"intolerabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unable to endure, impatient (of ); insufferable","forms":["intolerābilem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At illum subitus vīscerum dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta scatērent vermibus, et foetōrem lātē ēmitterent, exercituī et aegrō ipsī {{intolerābilem}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intolerandus","latin":"intolerandus, intoleranda, intolerandum","headword":"intolerandus","letter":"i","pos":"adjective","posGroup":"adjective","english":"insupportable, insufferable; unbearable, intolerable; physically unendurable","forms":["intoleranda"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Licuit vōbīs cum summā turpitūdine in exsiliō aetātem agere; potuistis nōnnūllī Rōmae, āmissīs bonīs, aliēnās opēs exspectāre: quia illa foeda atque {{intoleranda}} vīrīs vidēbantur, haec sequī dēcrēvistis.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"intolerans","latin":"intolerans, intolerantis (gen.), intolerantior -or -us, intolerantissimus -a -um","headword":"intolerans","letter":"i","pos":"adjective","posGroup":"adjective","english":"insufferable, unbearable; unable to endure; impatient (of); intolerant (later)","forms":["intolerantius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sed {{intolerantius}} Gallos insequentes legio decima tardavit, quae pro subsidio paulo aequiore loco constiterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intono","latin":"intono, intonare, intonui, intonitus","headword":"intono","letter":"i","pos":"verb","posGroup":"verb","english":"thunder","forms":["Intonuēre","intonuit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dîcite aliquid bellî!” Cônsonuëre cornicinēs fünebrî strepitū. Ünus praecī- puê, servus libitînäriî illîus quī inter hôs honestissimus erat, tam valdē {{intonuit}} ut tôtam concitāret vîcîniam!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"intonsus","latin":"intonsus, intonsa, intonsum","headword":"intonsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uncut; unshaven, unshorn; not stripped of foliage","forms":["intōnsam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Puer crēvit: {{intōnsam}} habuit comam, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis rōbore: obvium leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intra","latin":"intrā","headword":"intrā","letter":"i","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) inside, within","forms":["intra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus comparatis, represso iam Lucterio et remoto, quod intrare {{intra}} praesidia periculosum putabat, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intractabilis","latin":"intractabilis, intractabilis, intractabile","headword":"intractabilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"unmanageable, intractable","forms":["intractābile"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sed fīnēs Libycī, genus {{intractābile}} bellō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"intrat","latin":"intrat, intrant","headword":"intrat","letter":"i","pos":"verb","posGroup":"verb","english":"enter; enters; enters, goes into","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"intremisco","latin":"intremisco, intremiscere, intremui, -","headword":"intremisco","letter":"i","pos":"verb","posGroup":"verb","english":"begin to tremble","forms":["intremuēre","intremuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ut vērō summō dēspexit ab aethere terrās īnfēlīx Phaethōn penitus penitusque iacentēs, palluit et subitō genua {{intremuēre}} timōre suntque oculīs tenebrae per tantum lūmen obortae, et iam māllet equōs numquam tetigisse paternōs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"intro","latin":"intrō (1)","headword":"intrō","letter":"i","pos":"verb","posGroup":"verb","english":"enter","forms":["intrābat","intrābitis","intrāns","intrant","intrante","intrantem","intrantēs","intrare","intrat","intrāta","intraverant","intrāvēre","intrāverīs","intrāvērunt","intrāvī","intrāvimus","intrāvisse","intrāvistī","intrāvit","intrēmus","intret","intrētis","intrō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus comparatis, represso iam Lucterio et remoto, quod {{intrare}} intra praesidia periculosum putabat, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"introducere","latin":"(intrōdūcō) intrōdūcere (< dūcere)","headword":"intrōdūcere","letter":"i","pos":"","posGroup":"other","english":"lead/bring in, introduce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"introduco","latin":"introduco, introducere, introduxi, introductus","headword":"introduco","letter":"i","pos":"verb","posGroup":"verb","english":"introduce, bring/lead in","forms":["intrōdūc","intrōdūcerentur","intrōdūcī","intrōdūcit","Intrōductī","intrōductīs","intrōductum","intrōductus","Intrōdūxī","intrōdūxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Isaacus {{intrōdūxit}} Rebeccam in tabernāculum mātris suae, et lēnītus est dolor quem capiēbat ex morte mātris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"introeo","latin":"introeo, introire, introivi(ii), introitus","headword":"introeo","letter":"i","pos":"verb","posGroup":"verb","english":"enter, go in or into; invade","forms":["Introeāmus","introeant","introeunt","introeuntī","introiēns","introīre","introīvit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et, ēiectā turbā, {{introīvit}} et tenuit manum eius et dīxit: Puella, surge!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"introgredior","latin":"introgredior, introgredi, introgressus sum","headword":"introgredior","letter":"i","pos":"verb","posGroup":"verb","english":"enter; go in; step in (L+S)","forms":["introgressī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam introgressī et cōram data cōpia fandī,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"introire","latin":"(introeō) introīre (< īre)","headword":"introīre","letter":"i","pos":"","posGroup":"other","english":"enter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"intromitto","latin":"intromitto, intromittere, intromisi, intromissus","headword":"intromitto","letter":"i","pos":"verb","posGroup":"verb","english":"admit, let into, allow to come in; send/put in; introduce","forms":["intromissis","intromittit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis {{intromittit}} atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"introrsus","latin":"introrsus","headword":"introrsus","letter":"i","pos":"adverb","posGroup":"adverb","english":"within, inside, to within, inwards, inwardly, internally","forms":["introrsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis {{introrsus}} reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"intueor","latin":"intueor, intueri, intuitus sum","headword":"intueor","letter":"i","pos":"verb","posGroup":"verb","english":"look at; consider, regard; admire; stare","forms":["intueāris","intueātur","intuēbantur","intuēbātur","Intuēminī","intuēns","intuentur","intuēre","intuērer","intuērī","intuētur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dōrippa tacita Lepidum {{intuētur}} neque locō sē movet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"intueri","latin":"intuērī","headword":"intuērī","letter":"i","pos":"verb","posGroup":"verb","english":"to look at, gaze at","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"intuetur","latin":"intuētur, intuērī","headword":"intuētur","letter":"i","pos":"verb","posGroup":"verb","english":"look at, watch; looks at, watches","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"intumesco","latin":"intumesco, intumescere, intumui, -","headword":"intumesco","letter":"i","pos":"verb","posGroup":"verb","english":"swell up, become swollen; rise","forms":["intumēscentēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Fēcit Moysēs quod iusserat Deus: cum tenēret manum extēnsam super mare, aquae dīvīsae sunt, et {{intumēscentēs}} hinc et inde pendēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"intus","latin":"intus","headword":"intus","letter":"i","pos":"adverb","posGroup":"adverb","english":"within; inside, indoors","forms":["intus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quārē abscondit eum tribus mēnsibus; sed cum nōn posset eum diūtius occultāre, sūmpsit fiscellam, quam līnīvit bitūmine ac pice; deinde posuit {{intus}} īnfantulum, et exposuit eum inter harundinēs rīpae flūminis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inultus","latin":"inultus, -a, -um","headword":"inultus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unavenged","forms":["inulta","inultae","inultam","inultī","inultum","inultus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās concussit, et turba omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn {{inultus}} occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inundo","latin":"inundo, inundare, inundavi, inundatus","headword":"inundo","letter":"i","pos":"verb","posGroup":"verb","english":"overflow, inundate, flood; swarm","forms":["inundet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille quidem tōtam gemebundus obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis {{inundet}}\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"inurbanus","latin":"inurbanus, inurbana, inurbanum","headword":"inurbanus","letter":"i","pos":"adjective","posGroup":"adjective","english":"rustic, boorish, dull","forms":["inurbānus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Servulus nōn {{inurbānus}} satis strēnuē et concinnē comparārat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"inuro","latin":"inuro, inurere, inussi, inustus","headword":"inuro","letter":"i","pos":"verb","posGroup":"verb","english":"burn, scorch; burn (off/away/hole); cauterize; curl (hair w/hot tongs); tinge","forms":["inūrere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Eleazarus rem prāvam suādentibus nōluit assenfirī:\"Aetafī nostrae\"inquit,\"nōn convenit ista simulātiō: nōn committam ut perīculōsum exemplum adulēscentibus relinquam: multō satius est perīre, quam propter brevem vītae ūsūram turpirūdinis nōtam meō nominī {{inūrere}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inustum","latin":"inustum, inusti","headword":"inustum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"burned parts (pl.); burns","forms":["inusta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae nota domesticae turpitūdinis nōn {{inusta}} vītae tuae est?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"inutilis","latin":"inūtilis, -e","headword":"inūtilis","letter":"i","pos":"adjective","posGroup":"adjective","english":"useless","forms":["inūtile","inutiles","inūtilī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Facere, quod nostri maiores nequaquam pari bello Cimbrorum Teutonumque fecerunt; qui in oppida compulsi ac simili inopia subacti eorum corporibus qui aetate ad bellum {{inutiles}} videbantur vitam toleraverunt neque se hostibus tradiderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"invadere","latin":"(invādō) invādere (< vādere)","headword":"invādere","letter":"i","pos":"","posGroup":"other","english":"enter, attack, invade","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"invado","latin":"invado, invadere, invasi, invasus","headword":"invado","letter":"i","pos":"verb","posGroup":"verb","english":"enter, attempt; invade; take possession of; attack (with in +acc.)","forms":["invādat","invādendī","invādendōs","invādere","invādī","invādit","invāditur","invādunt","invāserat","invāsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Saūlem, postquam Deī mandāta sprēverat, {{invāsit}} spīritus malus, ita ut ille in furōrem saepe incīderet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invalesco","latin":"invalesco, invalescere, invalui, -","headword":"invalesco","letter":"i","pos":"verb","posGroup":"verb","english":"strengthen, grow strong; increase in power/effectiveness/intensity/frequency","forms":["invaluēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Postquam numerus hominum crēvit, omnia vitia {{invaluēre}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invalidus","latin":"invalidus, -a, -um","headword":"invalidus","letter":"i","pos":"adjective","posGroup":"adjective","english":"weak; weak, infirm","forms":["invalida","invalidōs","invalidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sīc pater ille scelerātus, dēbilis et {{invalidus}}, sine cibō et sine pōtiōne semper manet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"invehere","latin":"(invehō) invehere, invēxisse, invectum","headword":"invehere","letter":"i","pos":"verb","posGroup":"verb","english":"import; import, ride in; to carry in, import","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"inveho","latin":"inveho, invehere, invexi, invectus","headword":"inveho","letter":"i","pos":"verb","posGroup":"verb","english":"carry/bring in, import; ride (PASS), drive, sail, attack","forms":["invectā","invectīs","invectus","invehitur"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Frūmentum minōris pretiī est, quia magna cōpia frūmentī ex Āfricā in Italiam {{invehitur}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"invenio","latin":"inveniō, -īre, invēnī, inventum","headword":"inveniō","letter":"i","pos":"verb","posGroup":"verb","english":"find, discover","forms":["invēnerat","invēnerimus","invēnerīs","invēnerit","invēnerō","invēnērunt","invēnī","inveniam","inveniās","inveniēbātur","inveniēmus","inveniendam","inveniēs","inveniētis","invenīmus","inveniō","invenīre","invenīret","invenīrī","invenīs","invēnisset","invenit","invenītis","invenītur","inveniunt","inveniuntur","inventa","inventam","inventī","inventīs","inventō","inventūrōs","inventus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum eā nōn {{invēnisset}} locum ubi pōneret pedem, reversā est ad Noëmum, quī extendit manum, et intulit eam in arcam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invenire","latin":"(inveniō) invenīre, invēnisse, inventum","headword":"invenīre","letter":"i","pos":"verb","posGroup":"verb","english":"come upon, find; to find","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"inventio","latin":"inventiō, -ōnis ( f.)","headword":"inventiō","letter":"i","pos":"","posGroup":"other","english":"art of devising arguments","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inventum","latin":"inventum, inventi","headword":"inventum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"invention, discovery","forms":["inventum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Canēs, hūc et illūc currentēs, vestīgia sequēbantur ad bēstiam inveniendam; tandem aprum {{inventum}} ex dūmīs, in quibus sē occultāverat, expulērunt; quī, cum ex latibulō suō excurrisset atque fugere vellet, ab Adōne, quī parātus erat ad eum trānsfīgendum, hastā percussus cecidit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"investigare","latin":"(investīgō) investīgāre","headword":"investīgāre","letter":"i","pos":"verb","posGroup":"verb","english":"inquire into, investigate; to investigate, search out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"investigo","latin":"investigo, investigare, investigavi, investigatus","headword":"investigo","letter":"i","pos":"verb","posGroup":"verb","english":"investigate; search out/after/for; track down; find (by following game trail)","forms":["investīgāre","investīgāta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Num sermōnem vestrum aliquem dīrēmit noster interventus?' 'Minimē vērō!' Āfricānus; 'sōlēs enim tē haec studiōsē {{investīgāre}} quae sunt in hōc genere, dē quō īnstituerat paulō ante Tubērō quaerere; Rutilius quidem noster etiam sub ipsīs Numantiae moenibus solēbat, mēcum interdum eius modī aliquid conquīrere.' 'Quae rēs tandem inciderat?' inquit Philus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"inveterascere","latin":"(inveterāscō) inveterāscere, -āvisse (< vetus)","headword":"inveterāscere","letter":"i","pos":"","posGroup":"other","english":"grow old, become fixed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inveteratus","latin":"inveterātus, -a, -um","headword":"inveterātus","letter":"i","pos":"","posGroup":"other","english":"hardened by age, of long-standing","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"invicem","latin":"invicem","headword":"invicem","letter":"i","pos":"adverb","posGroup":"adverb","english":"mutually, one another","forms":["invicem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnique gladiōs in sē {{invicem}} convērtērunt, et mūtuā caede sē trucīdārunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invictus","latin":"invictus, -a, -um","headword":"invictus","letter":"i","pos":"adjective","posGroup":"adjective","english":"unconquered, invincible; unconquered","forms":["invictae","invictī","invictum","invictus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōnne tibi in mentem venit quī hostēs nōs cingant: Gaetūlī Numidaeque, gentēs {{invictae}}, et frāter tuus Pygmaliōn, quī Tyrō bellum minātur?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"invideo","latin":"invideo, invidere, invidi, invisus","headword":"invideo","letter":"i","pos":"verb","posGroup":"verb","english":"envy, regard with envy/ill will; be jealous of; begrudge, refuse","forms":["invide","Invideat","invidēbant","invidēbat","invident","invidēre","invidērent","invidēret","invīderit","invidēs","invidet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dominus dīxit Caīnō: cūr {{invidēs}} frātrī?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invidere","latin":"(invideō) invidēre, invīdisse  ({i}intr. + dat.{/i})","headword":"invidēre","letter":"i","pos":"verb","posGroup":"verb","english":"envy, grudge; to envy (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"invidet","latin":"invidet","headword":"invidet","letter":"i","pos":"verb","posGroup":"verb","english":"envies (with dative)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"invidia","latin":"invidia, -ae","headword":"invidia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"envy, ill will; envy, ill will, dislike; envy, jealousy; envy, hatred, unpopularity","forms":["invidia","invidiae","invidiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Romani vero quid petunt aliud aut quid volunt, nisi {{invidia}} adducti, quos fama nobiles potentesque bello cognoverunt, horum in agris civitatibusque considere atque his aeternam iniungere servitutem?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"invidiosus","latin":"invidiōsus, -a, -um","headword":"invidiōsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"hateful, enviable","forms":["invidiōsa"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dardanidās mātrēs patriōrum signa deōrum dum licet amplexās succēnsaque templa tenentīs {{invidiōsa}} trahunt victōrēs praemia Graī; mittitur Astyanax illīs dē turribus, unde pugnantem prō sē prōavītaque rēgna tuentem saepe vidēre patrem mōnstrātum ā mātre solēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"invidus","latin":"invidus, invida, invidum","headword":"invidus","letter":"i","pos":"adjective","posGroup":"adjective","english":"hateful, ill disposed, hostile, malevolent; envious, jealous, grudging","forms":["invida","invidus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Malō animō id faciēbat rēx {{invidus}}: spērābat scīlicet iuvenem audācem facile peritūrum; at sua eum spēs dēlūsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"inviolatus","latin":"inviolatus, inviolata, inviolatum","headword":"inviolatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"uninjured, unhurt; inviolable","forms":["inviolātōs","inviolātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea postquam Cirtae audīta sunt, Italicī, quōrum virtūte moenia dēfendēbantur, cōnfīsī dēditiōne factā propter magnitūdinem populī Rōmānī {{inviolātōs}} sēsē fore, Adherbalī suādent 'utī sēque et oppidum Iugurthae trādat, tantum ab eō vītam pācīscātur.' At ille, tametsī omnia potiōra fidē Iugurthae rebātur, tamen — quia penes eōsdem, sī adversārētur, cogundī potestās erat — ita utī cēnsuerant Italicī dēditiōnem facit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"invisere","latin":"(invīsō) invīsere (< vīsere)","headword":"invīsere","letter":"i","pos":"","posGroup":"other","english":"go to see","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"inviso","latin":"inviso, invisere, invisi, invisus","headword":"inviso","letter":"i","pos":"verb","posGroup":"verb","english":"go to see, visit; watch over","forms":["invīsēbat","invīsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In hāc calamitāte Tobiās frātrēs {{invīsēbat}}, miserōs cōnsōlāns, egēnōs opibus suīs iuvāns, et mortuōs sepeliēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invisus","latin":"invīsus, -a, -um","headword":"invīsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"odious, disliked","forms":["invīsa","invīsam","invīsōs","invīsum","invīsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob causam Iōsēphus erat {{invīsus}} suīs frātribus, praesertim postquam nārrāvisset eīs duplex somnium, quō futūra eius magnitūdō portendēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invitare","latin":"(invitō) invitāre","headword":"invitāre","letter":"i","pos":"","posGroup":"other","english":"invite, entertain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"invito","latin":"invītō (1)","headword":"invītō","letter":"i","pos":"verb","posGroup":"verb","english":"invite","forms":["invīta","invītāminī","invītandō","invītāret","invītās","invītat","Invītātī","invītātīs","invītātus","invītāvit","invītem","invītō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diē quōdam fēstō, cum domī lautum convīvium parāvisset, mīsit fīlium ut aliquot ē sociīs ad prandium {{invītāret}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"invitus","latin":"invītus, -a, -um","headword":"invītus","letter":"i","pos":"adjective","posGroup":"adjective","english":"against one’s will, unwilling; unwilling; unwilling, against one’s will","forms":["invītae","invītam","Inviti","invītōs","invītus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Inviti}} summae spei adulescentes Eporedorix et Viridomarus Vercingetorigi parent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"invius","latin":"invius, -a, -um (< via)","headword":"invius","letter":"i","pos":"adjective","posGroup":"adjective","english":"trackless, impassable; impassable","forms":["invia","inviōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec poena dīlāta foret, nisi saevī ventī fēcissent aequora {{invia}} et tellūs Aulide puppēs tenuisset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"invoco","latin":"invocō, invocāre","headword":"invocō","letter":"i","pos":"verb","posGroup":"verb","english":"call upon, invoke; invoke","forms":["invocābat","invocāns","invocant","invocantēs","invocantibus","invocāre","invocās","invocat","invocātā","invocātō","invocāverat","invocāvit","invocō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ē sther, lāmentantis vōce audīta, quaesīvit quid istud reī esset: ut cognōvit l\\1ardochaeum IŪdaeōsque omnēs esse necī dēstinātōs, invocātō Deō, adiit rēgem, suae gentis ruīnam dēprecātūra.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"involvo","latin":"involvo, involvere, involvi, involutus","headword":"involvo","letter":"i","pos":"verb","posGroup":"verb","english":"wrap (in), cover, envelop; roll along","forms":["involūtum","involūtus","involverat","involvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cum essent ibi, impletī sunt diēs pariendī, et peperit fīlium, quem pannīs {{involvit}} et reclīnāvit in praesēpiō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"io","latin":"Io","headword":"Io","letter":"i","pos":"interjection","posGroup":"interjection","english":"Yo!; Hurrah! (ritual exclamation of strong emotion/joy); Ho!; Look!; Quick!","forms":["iō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Huius fluviī deus fīliam habēbat cui nōmen Iō dederat; ea virgō valdē iuvenis et fōrmōsa nōn modo in rīpā flūminis, vērum etiam in umbrā arborum, quae prope erant, saepe lūdēbat et sōle gaudēbat, quō campī illūstrābantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ioco","latin":"joco, jocare, jocavi, jocatus","headword":"joco","letter":"i","pos":"verb","posGroup":"verb","english":"joke, jest; say in jest; make merry","forms":["iocō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"cum eā tū sermōnem nec iocō nec sēriō","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"iocor","latin":"jocor, jocari, jocatus sum","headword":"jocor","letter":"i","pos":"verb","posGroup":"verb","english":"joke, jest; say in jest; make merry","forms":["iocantīs","iocārī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Excipimus urbānitātem {{iocantīs}}, et ante onmēs Agamemnôn, quī sciēbat quibus meritīs revocärëttlr ad cēnam!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"iocose","latin":"jocose, jocosius, jocosissime","headword":"jocose","letter":"i","pos":"adverb","posGroup":"adverb","english":"jokingly, jocosely","forms":["iocose"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Tum vero Cornelius \"Bene quidem\" inquit \"et {{iocose}} scripsit Catullus, nec tamen versus eius comparandi sunt cum epigrammatis sale plenis quae Martialis in inimicos scripsit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iocosus","latin":"iocōsus, -a, -um","headword":"iocōsus","letter":"i","pos":"adjective","posGroup":"adjective","english":"humorous, funny; joking, witty","forms":["iocosa","iocosos"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quin versus {{iocosos}} recitas nobis?\" Cui Iulius \"At Catullus\" inquit \"non tantum carmina seria, sed etiam iocosa scripsit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iocus","latin":"jocus, joci","headword":"jocus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"joke, jest; sport","forms":["iocīs","iocōs","iocum","iocus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"(7 ac satis fīda), cōnscia tacitīs {{iocīs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ion","latin":"Ion, undeclined","headword":"Ion","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Isis; daughter of Inachus","forms":["Īōn"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"et modo sé Eurōpam fierī, modo postulat Īōn:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ipse","latin":"ipse, ipsa, ipsum","headword":"ipse","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"myself, yourself, etc; the very, the actual; self, himself, herself, itself, themselves; himself, herself, itself; (pl.) themselves","forms":["ipsa","ipsae","ipsam","ipsās","ipse","ipsi","ipsis","ipsīus","ipsō","ipsorum","ipsos","ipsum","ipsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Addunt {{ipsi}} et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ira","latin":"īra, -ae","headword":"īra","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"anger; wrath; anger, wrath","forms":["īra","īrae","īram","īrārum","īrās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Caīnus nōn pāruit Deō monentī; dissimulāns īram, dīxit frātrī suō: Age, eāmus dēambulātum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iracundia","latin":"iracundia, iracundiae","headword":"iracundia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"irascibility, hot temper; passion; resentment; anger; wrath (Ecc)","forms":["iracundia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Impellit alios avaritia, alios {{iracundia}} et temeritas quae maxime illi hominum generi est innata, ut levem auditionem habeant pro re comperta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iracundus","latin":"iracundus, iracunda, iracundum","headword":"iracundus","letter":"i","pos":"adjective","posGroup":"adjective","english":"angry; hot-tempered; enraged; furious","forms":["īrācunda"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"IVPPITER: [manum extendēns] Nimis īrācunda es.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"irasci","latin":"(īrāscor) īrāscī, īrātum (< īra)","headword":"īrāscī","letter":"i","pos":"","posGroup":"other","english":"be angry","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"irascor","latin":"īrāscor, īrāscī, īrātus sum","headword":"īrāscor","letter":"i","pos":"verb","posGroup":"verb","english":"be angry (+ dat.)","forms":["īrāscī","īrāscitur","īrātum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Syra dominum īrātum — et baculum eius — videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"irate","latin":"irate, iratius, iratissime","headword":"irate","letter":"i","pos":"adverb","posGroup":"adverb","english":"angrily; indignantly; furiously","forms":["īrātē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Mārcus magistrō īrātē 'Ego' inquit 'nōn dormiō.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iratus","latin":"īrātus, -a, -um","headword":"īrātus","letter":"i","pos":"adjective","posGroup":"adjective","english":"angry; angry, irate","forms":["īrāta","īrātae","īrātam","īrātī","īrātissima","īrātissimārum","Īrātissimus","īrātō","īrātōs","īrātus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia tē audit.” Syra īrāta est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ire","latin":"īre","headword":"īre","letter":"i","pos":"verb","posGroup":"verb","english":"to go","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"iris","latin":"Iris, Iridis","headword":"Iris","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Iris (messenger of the gods, goddess of the rainbow); rainbow","forms":["Īridem","Īris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum haec ex caelō spectāret, Iūnō, deōrum rēgīna, Īridem, suam nūntiam variīs colōribus exōrnātam, vocāvit et eī imperāvit ut somnium ad Alcyonēm mitteret, quō coniugis mors nūntiārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"irrideo","latin":"irrideo, irridere, irrisi, irrisus","headword":"irrideo","letter":"i","pos":"verb","posGroup":"verb","english":"ridicule, mock, make fun of; laugh at","forms":["irrīdēns","irrīdet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illa {{irrīdēns}} crūdēlem tyrannum, sīc fīlium allocūta est:\"Miserēre, filī mī, miserēre mātris tuae, quae tē uterō gestavī, quae tē nātum lacte aluī: nolī ā fratēmā virtūte dēgenerāre; nōn timēre camificem istum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"irrigo","latin":"irrigo, irrigare, irrigavi, irrigatus","headword":"irrigo","letter":"i","pos":"verb","posGroup":"verb","english":"water/irrigate; inundate/flood; refresh; wet/moisten; diffuse, shed (sensation)","forms":["irrigābat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ingēns fluvius {{irrigābat}} hortum: erant ibi omnēs arborēs iūcundae aspectū, et frūctūs gustū suāvēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"irrisus","latin":"irrisus, irrisus","headword":"irrisus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"mockery; laughingstock","forms":["irrīsū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At nēmō contrā illum exīre audēbat, et Goliathus suam Hebraeīs ignāviam cum irrīsū ac lūdibriō exprobrābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"irritare","latin":"(irrītō) irrītāre","headword":"irrītāre","letter":"i","pos":"","posGroup":"other","english":"excite, stimulate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"irrito","latin":"irrito, irritare, irritavi, irritatus","headword":"irrito","letter":"i","pos":"verb","posGroup":"verb","english":"excite; exasperate, provoke, aggravate, annoy, irritate","forms":["irrītābat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Utrimque in pugnam prōcursum est; hinc spēs, hinc dēspērātiō animōs {{irrītābat}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"irritus","latin":"irritus, -a, -um","headword":"irritus","letter":"i","pos":"adjective","posGroup":"adjective","english":"invalid, ineffectual","forms":["irrita","irrītam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aeoliós periūria ir-rita auferre et iubet Aeoliōs {{irrita}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"irruere","latin":"(irruō) irruere (< ruere)","headword":"irruere","letter":"i","pos":"","posGroup":"other","english":"rush in, charge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"irrumpere","latin":"(irrumpō) irrumpere (< rumpere)","headword":"irrumpere","letter":"i","pos":"","posGroup":"other","english":"break, force one’s way","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"irrumpo","latin":"irrumpo, irrumpere, irrupi, irruptus","headword":"irrumpo","letter":"i","pos":"verb","posGroup":"verb","english":"invade; break/burst/force/rush in/upon/into, penetrate; intrude on; interrupt","forms":["irrumperent","irrumpunt","irrūpēre","irrūpērunt","irrūpissent","irrupit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vos data facultate vobis consulite.' Simul in medios hostes {{irrupit}} duobusque interfectis reliquos a porta paulum summovit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"irruo","latin":"irruo, irruere, irrui, irrutus","headword":"irruo","letter":"i","pos":"verb","posGroup":"verb","english":"rush/dash/run in/upon/headlong, attack/charge; throw self on; intrude/encroach","forms":["irruerent","irruērunt","irruit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque ūna ambō abiērunt forās, et cum essent in agrō, Caīnus {{irruit}} in Abēlem, et interfēcit illum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"irruptio","latin":"irruptiō, -ōnis ( f.)","headword":"irruptiō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"violent entry, assault","forms":["irruptio","irruptiōnem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Laborantibus nostris Caesar Germanos summittit legionesque pro castris constituit, ne qua subito {{irruptio}} ab hostium peditatu fiat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"is","latin":"is, ea, id","headword":"is","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"he, she, it, that; he, she, it","forms":["ea","eae","eam","earum","eas","eis","eius","eorum","eos","eum","iī","iīs","is"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Eae}} res in Galliam Transalpinam celeriter perferuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"is / ea / id","latin":"is / ea / id","headword":"is / ea / id","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"he, she, it; this, that","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"is/ea/id","latin":"is/ea/id","headword":"is/ea/id","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"he, she, it; this, that","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"israel","latin":"Israel, Israelis","headword":"Israel","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Israel/Jacob; Israelites, decedents of Israel; people of God","forms":["Isrāēlis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sīc duo ex ūnō rēgna facta sunt: alterum Iūdae, alterum {{Isrāēlis}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"israelita","latin":"Israelita, Israelitae","headword":"Israelita","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Israelite","forms":["Isrāēlītam","Isrāēlītārum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Reversus fīlius nūntiāvit patrī hominem {{Isrāēlītam}} iacēre in forō mortuum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"israelitis","latin":"Israelitis, Israelitidis","headword":"Israelitis","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Israelite woman","forms":["Isrāēlītīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Posteā exortus est novus Assyriōrum rēx {{Isrāēlītīs}} īnfēnsus, quī eōs vexābat, necābat, et sepelīrī vetābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"isse","latin":"isse, issa, issum","headword":"isse","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"himself/herself/itself; the very/actual one; (endearment/colloquial of ipse)","forms":["īsse"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Magister: 'Dā utriusque cāsūs praepositiōnēs!' Discipulus: 'In, sub, super.' Magister: 'In et sub quandō accūsātīvō cāsuī iunguntur?' Discipulus: 'Quandō nōs in locum īre, īsse, futūrōs esse significāmus.' Magister: 'Quandō ablātīvō?' Discipulus: 'Quandō nōs in locō esse, fuisse, futūrōs esse significāmus.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iste","latin":"iste, ista, istud","headword":"iste","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"that one (of yours)","forms":["ista","istae","istam","istārum","istās","iste","istīs","istīus","istos","istud","istum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Animi est {{ista}} mollitia, non virtus, paulisper inopiam ferre non posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"isthmus","latin":"isthmus, -ī","headword":"isthmus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"isthmus, especially the Isthmus of Corinth","forms":["Isthmī","isthmum","Isthmus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quae est illā īnsula?\" Daedalus: \"Peloponnēsus est, Graeciae pars, nec vērō īnsula est, sed paenīnsula, nam Peloponnēsus terrā angustā, quae {{Isthmus}} vocātur, cum reliquā Graeciā coniungitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"isti","latin":"isti","headword":"isti","letter":"i","pos":"adverb","posGroup":"adverb","english":"there, in that place; where you are; herein, in this affair","forms":["istī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cornēlium Rūfīnum, quī bis cōnsul et dictātor fuerat, senātū mōvērunt: causamque istī notae subscrīpsērunt 'quod eum comperissent argentī factī cēnae grātiā decem pondō lībrās habēre.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"istic","latin":"istic, istaec, istoc","headword":"istic","letter":"i","pos":"pronoun","posGroup":"pronoun","english":"that of yours/mentioned by you/at hand","forms":["istaec","istanc","istīc","istunc"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"AMPHITRYO: Tū {{istīc}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"isto","latin":"isto","headword":"isto","letter":"i","pos":"adverb","posGroup":"adverb","english":"thither, to you, to where you are; in that matter; to the point you reached","forms":["istō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Samūēl prīmō rem dissuāsit, Hebraeōsque ab istō cōnsiliō dīmovēre cōnātus est; sed illī in sententiā perstitērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"istoc","latin":"istoc","headword":"istoc","letter":"i","pos":"adverb","posGroup":"adverb","english":"thither, that way, yonder","forms":["istōc"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Ergō {{istōc}} magis, quia vaniloquū's, vāpulābis!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"istuc","latin":"istuc","headword":"istuc","letter":"i","pos":"adverb","posGroup":"adverb","english":"thither, to you, to where you are; in that direction; to that subject/point","forms":["istuc"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"ALCVMENA: Experīrī {{istuc}} mavellem mē quam mihi memorārier.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"it","latin":"it","headword":"it","letter":"i","pos":"verb","posGroup":"verb","english":"goes","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"it/eunt","latin":"it/eunt","headword":"it/eunt","letter":"i","pos":"","posGroup":"other","english":"go","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ita","latin":"ita","headword":"ita","letter":"i","pos":"adverb","posGroup":"adverb","english":"so, in such a way; thus, in this way; yes, thus, so","forms":["ita"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque {{ita}} viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"italia","latin":"Italia, -ae","headword":"Italia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Italy","forms":["Ītaliā","Ītaliae","Ītaliam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, in {{Italiam}} ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"italicus","latin":"Italicus, Italici","headword":"Italicus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Italians (pl.)","forms":["Italicī","Ītalicum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea postquam Cirtae audīta sunt, Italicī, quōrum virtūte moenia dēfendēbantur, cōnfīsī dēditiōne factā propter magnitūdinem populī Rōmānī inviolātōs sēsē fore, Adherbalī suādent 'utī sēque et oppidum Iugurthae trādat, tantum ab eō vītam pācīscātur.' At ille, tametsī omnia potiōra fidē Iugurthae rebātur, tamen — quia penes eōsdem, sī adversārētur, cogundī potestās erat — ita utī cēnsuerant Italicī dēditiōnem facit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"italus","latin":"Italus, Itali","headword":"Italus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Italian","forms":["Itali"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"[EX PETRŌNIĪ SĀ TYRICON LIBRŌ XV] [In parte librîpraecêdentî, quae periit, haecferë nārrāta Encolgius et Asczltos, amïcî adulêscentulî, quî ūnä cum ī puerô iter in {{Itali}}äfaciêbant, in quādam cō- lôniä Campāniae rhētorem Agamemnonem convênerant, quôcum ad ‘lîberam cēnam’ vocätî erant apud T rimal- chiônem lîbertînum dîvitissimum atque lautissimum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"itaque","latin":"itaque","headword":"itaque","letter":"i","pos":"adverb; conjunction","posGroup":"adverb","english":"therefore; therefore, and so; and so, and thus, therefore","forms":["itaque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Itaque}} cohortatus Aeduos de supportando commeatu, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium impetum magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"item","latin":"item","headword":"item","letter":"i","pos":"adverb","posGroup":"adverb","english":"likewise, also","forms":["item"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Altera ex parte Gabalos proximosque pagos Arvernorum in Helvios, {{item}} Rutenos Cadurcosque ad fines Volcarum Arecomicorum depopulandos mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iter","latin":"iter, itineris","headword":"iter","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"(n.) journey, trip; journey, road; road, path, way","forms":["iter","itinera","itinere","itineribus","itineris","itinerum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in {{itinere}} proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iterare","latin":"(iterō) iterāre","headword":"iterāre","letter":"i","pos":"","posGroup":"other","english":"repeat, renew","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"itero","latin":"itero, iterare, iteravi, iteratus","headword":"itero","letter":"i","pos":"verb","posGroup":"verb","english":"do a second time; repeat; renew, revise","forms":["iterandō","iterāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Haec precātus, velut sī sēnsisset audītās precēs, \"Hinc\" inquit, \"Rōmānī, Iuppiter Optimus Maximus resistere atque {{iterāre}} pugnam iubet!\" Restitēre Rōmānī tamquam caelestī vōce iussī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iterum","latin":"iterum","headword":"iterum","letter":"i","pos":"adverb","posGroup":"adverb","english":"again, a second time; again","forms":["iterum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Immō magister mē lacrimantem facere nōn potest, etiam sī mē {{iterum}} atque iterum verberat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ithaca","latin":"Ithaca, -ae","headword":"Ithaca","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Ithaca, the island home of Ulysses","forms":["Ithaca","Ithacae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Trāns mare tranquillum nāvēs paene ad lītus {{Ithacae}} adveniunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"itidem","latin":"itidem","headword":"itidem","letter":"i","pos":"adverb","posGroup":"adverb","english":"in the same manner/way, just so; likewise, similarly, also","forms":["itidem"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{itidem}} habet petasum ac vestītum—tam cōnsimile'st atque ego:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"iuba","latin":"juba, jubae","headword":"juba","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"mane of a horse; crest (of a helmet)","forms":["iubae","iubam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Lābitur ā ille in equī {{iubam}}, et terram calidō sanguine foedat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"iubar","latin":"jubar, jubaris","headword":"jubar","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"radiance of the heavenly bodies, brightness; first light of day; light source","forms":["iubare"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"it portīs {{iubare}} exortō dēlēcta iuventūs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"iubatus","latin":"jubatus, jubata, jubatum","headword":"jubatus","letter":"i","pos":"adjective","posGroup":"adjective","english":"having mane, crest","forms":["iubātī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"dēvolant anguēs iubātī deorsum in impluvium duo","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"iubeo","latin":"iubeō, -ēre, iussī, iussum","headword":"iubeō","letter":"i","pos":"verb","posGroup":"verb","english":"order, command, ask, bid","forms":["iubē","iubeant","iubēbam","iubēbant","iubebat","iubēbit","iubēbō","iubent","iubente","iubentī","iubentur","iubeō","iubēre","iubērentur","iubēret","iubēs","iubet","iussae","iusseram","iusserās","iusserat","iussēre","iusserīs","iusserit","iusserō","iussērunt","iussī","iussimus","iussisse","iussisset","iussistī","iussistis","iussit","iussōs","iussu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fufium Citam, honestum equitem Romanum, qui rei frumentariae {{iussu}} Caesaris praeerat, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iubet","latin":"iubet, iubēre","headword":"iubet","letter":"i","pos":"verb","posGroup":"verb","english":"order, tell; orders, bids","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"iucunde","latin":"jucunde, jucundius, jucundissime","headword":"jucunde","letter":"i","pos":"adverb","posGroup":"adverb","english":"pleasantly; delightfully; pleasingly, gratifyingly, agreeably","forms":["iūcundē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Orontēs rīdēns 'Equidem' inquit 'sine aquā iūcundē vīvere nōn possum, sine vīnō nōn item!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iucunditas","latin":"jucunditas, jucunditatis","headword":"jucunditas","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"charm, agreeableness, pleasing quality; pleasantness/amiability; favors (pl.)","forms":["iūcunditās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae enim potest in vītā esse {{iūcunditās}}, cum diēs et noctēs cōgitandum sit iam iamque esse moriendum?...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"iucundus","latin":"iūcundus, -a, -um","headword":"iūcundus","letter":"i","pos":"adjective","posGroup":"adjective","english":"pleasant, agreeable","forms":["iūcunda","iūcundae","iūcundam","iūcundior","iūcundissimā","iūcundius","iūcundōs","iūcundum","iūcundus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ingēns fluvius irrigābat hortum: erant ibi omnēs arborēs {{iūcundae}} aspectū, et frūctūs gustū suāvēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iudex","latin":"iūdex, -icis (m.)","headword":"iūdex","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"judge","forms":["iūdex","iūdice","iūdicēs","iūdicibus","IVDICE"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde summa potestās dēlāta est ad {{iūdicēs}}, inter quōs ēminuēre Gedeon, Samsōn et Samuel.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iudicatio","latin":"iūdicātiō, -ōnis ( f.)","headword":"iūdicātiō","letter":"i","pos":"","posGroup":"other","english":"point at issue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iudicium","latin":"iūdicium, -ī","headword":"iūdicium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"judgment, trial, court; judgment; judgement, decision","forms":["iūdicia","iūdiciī","iūdiciīs","iūdiciō","iūdicium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx autem ut explōrāret latentem vēritātem: “Dīvidātur” inquit “puer dē quō contrōversia est, et pars ūna ūnī mulierī, altera alterī dētur.” Iūdiciō assēnsa est falsa māter; altera vērō exclāmāvit: “Nē, quaesō, nē occīdātur puer, ō rēx: mālō ista tōtum habeat.” Tunc rēx ait: “Rēs est manifēsta: haec vērē est māter puerī.” Et huic illum adiūdicāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iudico","latin":"judico, judicare, judicavi, judicatus","headword":"judico","letter":"i","pos":"verb","posGroup":"verb","english":"judge, give judgment; sentence; conclude, decide; declare, appraise","forms":["iudicabant","iudicabiminī","iūdicandō","iudicare","iudicarem","iūdicārent","iūdicāret","iūdicārī","iūdicat","iūdicātus","iūdicāverat","iudicavissent","iūdicent","iūdicō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae tametsi Caesar intellegebat, tamen quam mitissime potest legatos appellat: nihil se propter inscientiam levitatemque vulgi gravius de civitate {{iudicare}} neque de sua in Aeduos benevolentia deminuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iugalis","latin":"iugālis, -e","headword":"iugālis","letter":"i","pos":"adjective","posGroup":"adjective","english":"marriage, conjugal","forms":["iugālem","iugālī","iugālia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"nē cui mē vinclō vellem sociāre iugālī,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"iugerum","latin":"iūgerum, -ī","headword":"iūgerum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"area of about 2/3 of an acre; a measure of land (about ¼ hectare)","forms":["iūgera","iūgerum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quīnctius Cincinnātus dictātor est factus, quī agrum quattuor {{iūgerum}} possidēns manibus suīs colēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iugis","latin":"jugis, jugis, juge","headword":"jugis","letter":"i","pos":"adjective","posGroup":"adjective","english":"continual; ever-flowing","forms":["iūgīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{iūgīs}} aurēs timidàs memorī ōre au-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iugo","latin":"jugo, jugare, jugavi, jugatus","headword":"jugo","letter":"i","pos":"verb","posGroup":"verb","english":"marry; join (to)","forms":["iugo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Legionem unam eodem {{iugo}} mittit et paulum progressam inferiore constituit loco silvisque occultat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iugulo","latin":"iugulō, -āre, iugulāvī","headword":"iugulō","letter":"i","pos":"verb","posGroup":"verb","english":"butcher, kill","forms":["iugulandī","iugulāre","iugulārī","iugulātum","iugulātus","iugulō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iam curru īnstābat Achillēs āgmina perque aciēs aut Cygnum aut Hectora quaerēns; occurrit Cygnō (decimum dīlāta in annum mors Hectoris erat): tum ... exhortātus equōs currum dīrēxit in hostem concutiensque suīs vibrantia tēla lacertīs “Quisquis es, ō iuvenis” dīxit “sōlāmen habētō mortis, ab Aeacidē quod sīs {{iugulātus}} Achille!”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iugulum","latin":"iugulum, -ī","headword":"iugulum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"throat","forms":["iugulīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam tōtī urbī, templīs, dēlūbrīs, tēctīs ac moenibus subiectōs prope iam ignēs circumdatōsque restīnximus, iīdemque gladiōs in rem pūblicam dēstrictōs rettudimus mucrōnēsque eōrum ā {{iugulīs}} vestrīs dēiēcimus!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"iugum","latin":"iugum, -ī","headword":"iugum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"yoke, ridge; yoke; sub iugum mittere, to send under the yoke","forms":["iuga","iugum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tandem Germani ab dextro latere summum {{iugum}} nacti hostes loco depellunt; fugientes usque ad flumen, ubi Vercingetorix cum pedestribus copiis consederat, persequuntur compluresque interficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iulus","latin":"julus, juli","headword":"julus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"plant-down; woolly part of plant (Pliny)","forms":["Iūlum","Iūlus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Parvum {{Iūlum}} mēcum dūcam, et Creūsa vestīgia nostra sequētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iumentum","latin":"iūmentum, -ī","headword":"iūmentum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"beast of burden/draft","forms":["iumenta","iūmentō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, {{iumenta}} produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iunctus","latin":"junctus, juncta -um, junctior -or -us, junctissimus -a -um","headword":"junctus","letter":"i","pos":"adjective","posGroup":"adjective","english":"connected in space, adjoining, contiguous; closely related/associated","forms":["iūnctus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hostis ut hospes init penetrālia Collātīnī: comiter excipitur; sanguine {{iūnctus}} erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iungit","latin":"iungit","headword":"iungit","letter":"i","pos":"verb","posGroup":"verb","english":"joins, connects","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"iungo","latin":"iungō, iungere","headword":"iungō","letter":"i","pos":"verb","posGroup":"verb","english":"join","forms":["iūncta","iūnctae","iūnctī","iūnctīs","iūnctōs","iūnctum","iungam","iungat","iunge","iungēbat","iungentēs","iungere","iungerētur","iungī","iungit","iungitō","iungitur","iungunt","iunguntur","iūnxerat","iūnxērunt","iūnxisset","iūnxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Bituriges eorum discessu statim cum Arvernis {{iunguntur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iunior","latin":"junior, junioris","headword":"junior","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"younger man, junior; (in Rome a man younger than 45)","forms":["iūniōrem","iuniores","iūnioribus","Iūnius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes {{iuniores}} Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iuniores","latin":"iūniōrēs, -um (m. pl.)","headword":"iūniōrēs","letter":"i","pos":"","posGroup":"other","english":"younger men","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iuno","latin":"Iūnō, Iūnōnis","headword":"Iūnō","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"Juno (queen of the gods)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"iuppiter","latin":"Iuppiter, Iovis","headword":"Iuppiter","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"Jupiter, Jove","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"iurandum","latin":"jurandum, jurandi","headword":"jurandum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"oath","forms":["iurando","iūrandum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure {{iurando}} ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iurare","latin":"(iūrō) iūrāre","headword":"iūrāre","letter":"i","pos":"","posGroup":"other","english":"swear","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iure","latin":"jure","headword":"jure","letter":"i","pos":"adverb","posGroup":"adverb","english":"by right, rightly, with justice; justly, deservedly","forms":["iure"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut {{iure}} iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iurgium","latin":"jurgium, jurgi(i)","headword":"jurgium","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"quarrel/dispute/strife; abuse/vituperation/invective; L:separation (man+wife)","forms":["iūrgia","iūrgiī","iūrgiō","iūrgium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{iūrgium}} -ī7z1 — certāmen dē iūre Iüurgīā praecipuē vīnō stimulàta","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iuro","latin":"juro, jurare, juravi, juratus","headword":"juro","letter":"i","pos":"verb","posGroup":"verb","english":"swear; call to witness; vow obedience to; [jus jurandum => oath]; conspire","forms":["iūrābit","iūrāmus","iūrant","iūrantēs","iūrāre","iūrās","iūrāte","iūrātō","iūrāverint","iūrāvī","iūrāvit","iūret","iūrō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Esāüs {{iūrāvit}} et vēndidit iūs suum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ius","latin":"iūs, iūris","headword":"iūs","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"(n.) law, right; also gravy, soup; right, law; law, right, justice","forms":["iura","iūris","iūrium","iūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, fideli atque utili superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, {{iura}} legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ius iurandum","latin":"iūs iūrandum (iūris iūrandī) (n.)","headword":"iūs iūrandum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"oath; oath, sworn formula","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"iussu","latin":"iussū2","headword":"iussū","letter":"i","pos":"","posGroup":"other","english":"by order of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"iussum","latin":"iussum, -ī","headword":"iussum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"command, order; order, command","forms":["iussa","iussis","iussō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His quam longissime possent egredi {{iussis}}, cum iam ex diei tempore coniecturam ceperat in castra perventum,: isdem sublicis, quarum pars inferior integra remanebat, pontem reficere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iussus","latin":"jussus, jussus","headword":"jussus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"order, command, decree, ordinance; [only ABL S => by order/decree/command]","forms":["iussus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tū vērō nē dubitēs facere quod {{iussus}} es.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iusta","latin":"iūsta, -ōrum (n. pl.)","headword":"iūsta","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"due ceremonies, funeral rites; funeral rites","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"iuste","latin":"juste, justius, justissime","headword":"juste","letter":"i","pos":"adverb","posGroup":"adverb","english":"justly, rightly, lawfully, legitimately, justifiably; properly, honorably","forms":["iūste"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duōbus senibus dīxit: \"Quid dēsīderātis, senex {{iūste}} et fēmina pia?\" Senēs respondērunt: \"Dēsīderāmus sacerdōtēs in templō Iovis esse, et quoniam multōs annōs beātōs inter nōs habuimus, morī dēsīderāmus eādem hōrā.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iustitia","latin":"iūstitia, -ae","headword":"iūstitia","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"justice","forms":["iūstitiā","iūstitiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aborīginēs Italiae incolae prīmī fuērunt, quōrum rēx Sāturnus tantā iūstitiā fuisse dīcitur ut neque servīret quisquam sub illō neque quidquam suum proprium habēret, sed omnia commūnia omnibus essent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iustum","latin":"justum, justi","headword":"justum","letter":"i","pos":"noun (n.)","posGroup":"noun","english":"justice; what is fair/equitable/right/due/proper; funeral rites/offerings","forms":["iūstum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Servus dominum iniūstum ōdit, {{iūstum}} et sevērum metuit, nōn ōdit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iustus","latin":"iūstus, -a, -um","headword":"iūstus","letter":"i","pos":"adjective","posGroup":"adjective","english":"just; just, upright, true","forms":["iusta","iūstae","iūstam","iūstī","iūstior","iūstīs","iustissimam","iūstissime","iūstō","iūstōs","iūstus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sic deinceps omne opus contexitur, dum {{iusta}} muri altitudo expleatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iuvare","latin":"(iuvō) iuvāre, iūvisse","headword":"iuvāre","letter":"i","pos":"verb","posGroup":"verb","english":"help, delight; to help; to help, please","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"iuvat","latin":"juvat, juvare, juvit, jutus est","headword":"juvat","letter":"i","pos":"verb","posGroup":"verb","english":"it pleases/delights; it is enjoyable; it is helpful","forms":["iuvat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"\"Daedalus vērō \"Quid {{iuvat}} deōs invocāre\" inquit \"dum hīc quiētus sēdēs?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"iuvenalis","latin":"iuvenālis, -e","headword":"iuvenālis","letter":"i","pos":"adjective","posGroup":"adjective","english":"youthful","forms":["iuvenālī","iuvenālia","iuvenālis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"īnferius terrās; mediō tūtissimus ībis.” Occupat ille levem iuvenālī corpore currum statque super, manibusque levēs contingere habēnās gaudet et invītō grātēs agit inde parentī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"iuvenaliter","latin":"juvenaliter","headword":"juvenaliter","letter":"i","pos":"adverb","posGroup":"adverb","english":"youthfully, like a youth","forms":["iuvenāliter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sé feram vīdisse ratus (— arbitrātus) Ille feram vīdisse ratus {{iuvenāliter}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iuvenca","latin":"juvenca, juvencae","headword":"juvenca","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"young cow, heifer; girl","forms":["iuvenca","iuvencam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{iuvenca}} -ae f — vacca iuvenis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iuvencus","latin":"iuvencus, -ī","headword":"iuvencus","letter":"i","pos":"noun (m.)","posGroup":"noun","english":"young bull, bullock; young bull","forms":["iuvencī","iuvencīs","iuvencōrum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tempore difficilēs veniunt ad aràtra iuvencī,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"iuvenilis","latin":"iuvenīlis, -e","headword":"iuvenīlis","letter":"i","pos":"adjective","posGroup":"adjective","english":"youthful","forms":["iuvenīlem","iuvenīlī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In librō quem Caesare dictātōre scrīpsit ad Brūtum 'Dē clārīs ōrātōribus', Cicerō inter alia haec dē doctrīnā suā iuvenīlī nārrat: 'At vērō ego hōc tempore omnēs noctēs et diēs in omnium doctrīnārum meditātiōne versābar.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"iuvenis","latin":"iuvenis, iuvenis","headword":"iuvenis","letter":"i","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) young person (not an i-stem); young man; youth, young person","forms":["iuvene","iuvenem","iuvenēs","iuvenī","iuvenibus","iuvenis","iuvenum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id ubi rēx cognōvit, fīlium morte plectī voluit; sed recēns meritum perīculō {{iuvenem}} exēmit, nec populus tulit īnsontem ad supplicium trahī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"iuventa","latin":"iuventa, -ae","headword":"iuventa","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"youth","forms":["iuventa","iuventae","iuventam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hōs tamen ille mihi dabat aeternamque {{iuventam}},\nsī Venerem paterer: contemptō mūnere Phoebī,\ninnuba permaneō; sed iam fēlīcior aetās\nterga dedit, tremulōque gradū venit aegra senectūs,\nquae patienda diū est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iuventus","latin":"iuventūs, -ūtis ( f.)","headword":"iuventūs","letter":"i","pos":"noun (f.)","posGroup":"noun","english":"youth, young men; Youth (personified)","forms":["iuventūs","iuventūte","iuventūtem","Iuventūtī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prō valvīs rēgiae duās ārās aedificāvit, ūnam dextrā parte Hecatae et alteram sinistrā parte Iuventūtī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"iuvo","latin":"iuvō, -āre, iūvī, iūtum","headword":"iuvō","letter":"i","pos":"verb","posGroup":"verb","english":"help, aid","forms":["iuvā","iuvābātur","iuvābit","iuvābō","iuvābunt","iuvandum","iuvāns","iuvant","iuvante","iuvantēs","iuvantia","iuvantibus","iuvāre","iuvarent","iuvās","iuvāte","iuvent","iūverant","iuvēs","iuvet","iūvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hi cum ad munitiones Romanorum accessissent, flentes omnibus precibus orabant ut se in servitutem receptos cibo {{iuvarent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"iuxta","latin":"iūxtā","headword":"iūxtā","letter":"i","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) next to, beside; beside, next to","forms":["iuxtā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Angelus Dominī stetit iuxtā illōs et clāritās magna circumfulsit illōs ita ut timērent valdē.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"januarius","latin":"Januarius, Januaria, Januarium","headword":"Januarius","letter":"j","pos":"adjective","posGroup":"adjective","english":"January (month/mensis understood); abb. Jan.","forms":["Iānuāriae","Iānuāriam","Iānuāriās","Iānuāriī","Iānuāriīs","Iānuāriō","Iānuārius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: {{Iānuārius}}, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"jason","latin":"Jason, Jasonis","headword":"Jason","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Jason; (leader of the Argonauts, sought the Golden Fleece)","forms":["Iāsōn","Iāsone","Iāsonem","Iāsonī","Iāsonis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Fīlium praetereā Aesonis, nōmine {{Iāsonem}}, occīdere temptāvit Pelias, homō scelestus, sed eī, fābulā fictā, nūntiāvērunt amīcī Aesonis puerum iam mortuum esse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"jesus","latin":"Jesus, Jesu","headword":"Jesus","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Jesus","forms":["Iēsu","Iēsum","Iēsus","Jēsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Cum nātus esset {{Iēsus}} m cīvitāte Bēthlehem, magī ab Oriente vēnērunt Hierosolymam ut eum adōrārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"joannes","latin":"Joannes, Joannis","headword":"Joannes","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"John","forms":["Iōannes"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Brant autem Andreās et {{Iōannes}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"juda","latin":"Juda, undeclined","headword":"Juda","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Judah; Jude; Judas; a son of Jacob; tribe of Judah","forms":["IŪdā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Antiochus, ut cognōvit suōs ducēs ā IŪdā Machabaeō esse dēvictōs, āmēns furōre, in liidaeam citātō cursū contendit, excidiō gentis et urbis acceptam clādem ulrūrus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"judaea","latin":"Judaea, Judaeae","headword":"Judaea","letter":"j","pos":"noun (f.)","posGroup":"noun","english":"Judea; Israel; Canaan; Palestine","forms":["Iūdaea","IŪdaeam","IŪdaeīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam illud tempus efflūxit, Cȳrus, Persārum rēx, dēvictō B abylōniorum rege, {{IŪdaeīs}}:fēcit potestātem in patriam remigrandī, templumque restituendī: sacra etiam vāsa, quae N abuchodonosor abstulerat, reddī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"judaeus","latin":"Judaeus, Judaei","headword":"Judaeus","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Jew, Jewish person; the Jews (pl.)","forms":["IUdaeī","Iudaeō","IŪdaeōrum","IŪdaeōs","Iudaeum","Jūdaeōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mardochaeus, ūnus ex capfīvīs, {{IŪdaeōs}} ē magnō perieūlō llbērāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"judaicus","latin":"Judaicus, Judaica, Judaicum","headword":"Judaicus","letter":"j","pos":"adjective","posGroup":"adjective","english":"of/relating to the Jews, Jewish; of/originating/stationed in Judea (troops)","forms":["Iūdaicae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nec deinceps ab avītā religiōne umquam dēscīvērunt, quamvīs ea dē causā ā plūribus rēgibus vexatī sint, ac praesertim ab Antiochō rēge Syriae; quae pars historiae {{Iūdaicae}} nunc nārranda venit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"judas","latin":"Judas, Judae","headword":"Judas","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Judas; Jude","forms":["Iūdās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc {{Iūdās}}, ūnus ē fīliīs Iacobī, dīxit patrī: committe mihi puerum; ego illum recipiō in fidem meam; ego servābō, ego redūcam illum ad tē; nisi fēcerō, huius reī culpa in mē residēbit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"judes","latin":"Judes, Judae","headword":"Judes","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Judah; Jude; Judas; a son of Jacob; tribe of Judah","forms":["Iūdae","Iūdam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iacobus profectus cum fīliīs et nepōtibus pervēnit in Aegyptum, et praemīsit {{Iūdam}} ad Iōsēphum ut eum faceret certiōrem dē adventū suō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"julius","latin":"Julius, Julia, Julium","headword":"Julius","letter":"j","pos":"adjective","posGroup":"adjective","english":"July (month/mensis understood); abb. Jul.; renamed from Quintilis in 44 BC","forms":["Iūlī","Iūlia","Iūliae","Iūliam","Iūliās","Iūliī","Iūliō","Iūlium","Iūlius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mārcus: “Ubi est Syria, {{Iūlia}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"junius","latin":"Junius, Junia, Junium","headword":"Junius","letter":"j","pos":"adjective","posGroup":"adjective","english":"June (month/mensis understood); abb. Jun.","forms":["Iuniae","Iūniās","Iuniīs","Iūniō","iūnium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Lūnam spectāns Iūlius “Lūna plēna est hāc nocte” inquit “quae est ante kalendās {{Iūniās}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"juno","latin":"Juno, Junonis","headword":"Juno","letter":"j","pos":"noun (f.)","posGroup":"noun","english":"Juno; (Roman goddess, wife of Jupiter)","forms":["Iūnō","Iūnōne","Iūnōnem","Iūnōnī","Iūnōnis","IVNONEM","Jūnōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Lātōna dea fuit, quam Iūnō, deōrum rēgīna, nōn amābat; itaque dē Olympō expulsam in terram mīsit, ubi ipsa maerēns per campōs silvāsque errābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"juppiter","latin":"Juppiter, Jovis","headword":"Juppiter","letter":"j","pos":"noun (m.)","posGroup":"noun","english":"Jupiter; (Roman chief/sky god); heavens/sky (poetic)","forms":["Iove","Iovem","Iovī","Iovis","Iuppiter","IVPPITER","Juppiter"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tūne {{Iovem}} cēterōsque deōs verēris?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"kaeso","latin":"Kaeso, Kaesonis","headword":"Kaeso","letter":"k","pos":"noun (m.)","posGroup":"noun","english":"Kaeso/Caeso (Roman praenomen); (abb. K.)","forms":["Kaesō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"K litterā, quae frequēns est in linguā Graeca, littera Latīna rārissima est, nam K in ūnō vocābulō Latīnō tantum reperītur, id est kalendae (itemque in praenōmine Kaesō, quod praenōmen Rōmānōrum rārissimum est).","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"kalenda","latin":"Kalenda, Kalendae","headword":"Kalenda","letter":"k","pos":"noun (f.)","posGroup":"noun","english":"Kalends (pl.), 1st of month; abb. Kal./Kl.; day of proclamation, interest due","forms":["kalendae","kalendās","kalendīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lūnam spectāns Iūlius “Lūna plēna est hāc nocte” inquit “quae est ante {{kalendās}} Iūniās.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"kalendae","latin":"kalendae, -ārum","headword":"kalendae","letter":"k","pos":"noun (f.)","posGroup":"noun","english":"(pl.) the 1st of the month; the Kalends (first day of the month)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"karthago","latin":"Karthago, Karthaginis","headword":"Karthago","letter":"k","pos":"noun (f.)","posGroup":"noun","english":"Carthage","forms":["Karthāgine","Karthāginem","Karthāginī","Karthāginis","Karthāgō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Urbs antīqua fuit, Karthāgō, in ōrā Āfricae contrā Italiam sita, dīves atque bellicōsa.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"labefacio","latin":"labefacio, labefacere, labefeci, labefactus","headword":"labefacio","letter":"l","pos":"verb","posGroup":"verb","english":"make unsteady/totter; loosen, shake; subvert (power/authority); weaken resolve","forms":["labefactus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"multa gemēns magnōque animum {{labefactus}} amōre","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"labefactare","latin":"(labefactō) labefactāre","headword":"labefactāre","letter":"l","pos":"verb","posGroup":"verb","english":"shake, undermime; to shake, undermine","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"labefacto","latin":"labefacto, labefactare, labefactavi, labefactatus","headword":"labefacto","letter":"l","pos":"verb","posGroup":"verb","english":"shake; cause to waver; make unsteady, loosen; undermine","forms":["labefactandī","labefactantem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quī patre Marte nātus cum Remō frātre dīcitur ab Amūliō, rēge Albānō, ob labefactandī rēgnī timōrem ad Tiberim expōnī iussus esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"labellum","latin":"labellum, labelli","headword":"labellum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"lip","forms":["labella","labellīs","labellum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{labellum}} -ī 7 7 lābrum (parvum)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"labeo","latin":"Labeo, Labeonis","headword":"Labeo","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Labeo; (Roman cognomen); one who has large/blubber lips (L+S)","forms":["Labeōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fabiō {{Labeōne}} cōnsulibus mortuum in annālī suō scrīptum relīquit, at Polybius Aemiliō Paulō Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"labes","latin":"lābēs, -is ( f.)","headword":"lābēs","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"stain, disgrace","forms":["lābēs","lābī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ille trīstīs mercēs suās dē nāve lābī et in mare mergī videt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"labi","latin":"lābī","headword":"lābī","letter":"l","pos":"verb","posGroup":"verb","english":"to slip, slide, fall","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"labitur","latin":"lābitur, lābī","headword":"lābitur","letter":"l","pos":"","posGroup":"other","english":"slip, drop, fall","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"labo","latin":"labo, labare, labavi, labatus","headword":"labo","letter":"l","pos":"verb","posGroup":"verb","english":"totter, be ready to fall; begin to sink; give way; waver, decline, sink; err","forms":["labant","labantem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":";5 Vincla {{labant}} et céra deō propiōre liquēscit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"labor","latin":"labor, labōris","headword":"labor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"(m.) labor, toil","forms":["lābēbantur","lābēbātur","lābente","lābentem","lābentia","lābentis","lābere","Lāberis","lābitur","labor","labore","laborem","labōrēs","labori","labōribus","laboris","laborum","lābuntur","lāpsa","lāpsī","lapsū","lāpsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summam imperi se consulto nulli discedentem tradidisse, ne is multitudinis studio ad dimicandum impelleretur; cui rei propter animi mollitiem studere omnes videret, quod diutius {{laborem}} ferre non possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"laborare","latin":"(labōrō) labōrāre, labōrāvisse, labōrātum","headword":"labōrāre","letter":"l","pos":"verb","posGroup":"verb","english":"work, toil; to work, labour","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"laborat","latin":"labōrat, labōrant","headword":"labōrat","letter":"l","pos":"verb","posGroup":"verb","english":"works","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"laboriosus","latin":"labōriōsus, -a, -um","headword":"labōriōsus","letter":"l","pos":"adjective","posGroup":"adjective","english":"hard, laborious","forms":["labōriōsō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[Ex Periochā librī XXI:] Hannibal, superātō Pyrēnaeō saltū, per Galliam ad Alpēs vēnit, et labōriōsō per eās trānsitū dēscendit in Ītaliam, et ad Tīcīnum flūmen Rōmānōs equestrī proeliō fūdit; in quō vulnerātum P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"laboro","latin":"laboro, laborare, laboravi, laboratus","headword":"laboro","letter":"l","pos":"verb","posGroup":"verb","english":"work, labor; produce, take pains; be troubled/sick/oppressed, be in distress","forms":["labōrā","labōrābant","laborabat","labōrant","labōrantem","laborantibus","laborare","labōrārent","laboraret","labōrat","labōrātae","laboratur","labōrāvimus","labōrāvit","labōrētis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus {{laboraret}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"labrum","latin":"labrum, -ī","headword":"labrum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"lip","forms":["labra","lābrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fossam pedum XX derectis lateribus duxit, ut eius fossae solum tantundem pateret quantum summae fossae {{labra}} distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"labyrinthus","latin":"labyrinthus, -ī","headword":"labyrinthus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"labyrinth; labyrinth, maze","forms":["labyrinthī","labyrinthō","labyrinthum","labyrinthus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In magnō labyrinthō habitābat.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lac","latin":"lac, lactis","headword":"lac","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"(n.) milk","forms":["lac","lactis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Diodōrus: “Cūr nōn {{lac}} bibere mē iubēs, medice, ut parvulum īnfantem?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lacedaemon","latin":"Lacedaemon, Lacedaemonis","headword":"Lacedaemon","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lacedaemon/Sparta; (city in the Peloponnese)","forms":["Lacedaemonem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde {{Lacedaemonem}} adit, nōn operum magnificentia, sed disciplīnā īnstitūtīsque memorābilem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lacer","latin":"lacer, lacera, lacerum","headword":"lacer","letter":"l","pos":"adjective","posGroup":"adjective","english":"mangled, torn, rent, mutilated; maimed, dismembered","forms":["lacer","lacerae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lacer}} -era -erum — scissus, frāctus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lacerare","latin":"(lacerō) lacerāre","headword":"lacerāre","letter":"l","pos":"","posGroup":"other","english":"tear","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"lacero","latin":"lacerō, -āre, -āvī, -ātum","headword":"lacerō","letter":"l","pos":"verb","posGroup":"verb","english":"tear to pieces, maim","forms":["lacerāre","lacerārī","lacerat","lacerātīs","Lacerātus","lacerāverat","lacerāvērunt"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Miserrimus Orpheus tendēns manūs et ōrāns Bacchantes vōce movēre frūstrā temptāvit; īnsānissimae eum {{lacerāvērunt}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"lacertus","latin":"lacertus, -ī","headword":"lacertus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"arm; arm, upper arm","forms":["lacertīs","lacertō","lacertōrum","lacertōs","lacertum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ōlim igitur, cum, positīs vestīmentīs, oleō membra aspersissent, in lātissimō campō herbīs opertō discīs iactandīs certābant; Hyacinthus, quī certandī studiōsissimus erat, prior discum in āera omnibus {{lacertōrum}} vīribus ēmīsit; quī, sē celerrimē vertēns, usque ad caelum ascendit, atque, cum nūbēs scidisset, rūrsus ad terram dēscendit, ceciditque procul ā locō unde puer et deus intuēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lacessere","latin":"(lacessō) lacessere, -īvisse, -ītum","headword":"lacessere","letter":"l","pos":"verb","posGroup":"verb","english":"challenge, provoke; to provoke, challenge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"lacesso","latin":"lacesso, lacessere, lacessivi, lacessitus","headword":"lacesso","letter":"l","pos":"verb","posGroup":"verb","english":"provoke, excite, harass, challenge, harass; attack, assail","forms":["lacessendās","lacessere","lacesseret","lacessītus","lacessīverat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Labienus tanta rerum commutatione longe aliud sibi capiendum consilium atque antea senserat intellegebat, neque iam ut aliquid adquireret proelioque hostes {{lacesseret}} sed ut incolumem exercitum Agedincum reduceret cogitabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lacrima","latin":"lacrima, -ae","headword":"lacrima","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"tear","forms":["lacrimae","lacrimam","lacrimārum","lacrimās","lacrimīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In oculīs eius {{lacrimae}} sunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lacrimabilis","latin":"lacrimābilis, -e","headword":"lacrimābilis","letter":"l","pos":"adjective","posGroup":"adjective","english":"mournful, pitiful","forms":["lacrimābile"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hinc iam bellum cīvīle successit exsecrandum et {{lacrimābile}}, quō praeter calamitātēs quae in proeliīs accidērunt, etiam populī Rōmānī fortūna mūtāta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lacrimat","latin":"lacrimat","headword":"lacrimat","letter":"l","pos":"verb","posGroup":"verb","english":"cry; weeps, cries","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"lacrimo","latin":"lacrimō, -āre, -āvī, -ātum","headword":"lacrimō","letter":"l","pos":"verb","posGroup":"verb","english":"cry, weep","forms":["lacrimābant","Lacrimābat","lacrimandī","lacrimans","lacrimante","lacrimantem","lacrimantēs","lacrimāre","lacrimārent","lacrimat","lacrimāvit","Lacrimō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Litaviccus accepto exercitu, cum milia passuum circiter XXX ab Gergovia abesset, convocatis subito militibus {{lacrimans}}: quo proficiscimur', inquit, 'milites?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lacrimosus","latin":"lacrimōsus, -a, -um","headword":"lacrimōsus","letter":"l","pos":"adjective","posGroup":"adjective","english":"tearful, sad","forms":["lacrimōsā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"membra suī, postquam miserōrum verba parentum ēdidit et mātrum miserārum facta perēgit, fūnera dūcēbat mediam lacrimōsā per urbem.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lacte","latin":"lacte, lactis","headword":"lacte","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"milk; milky juice of plants; spat/spawn (of oyster)","forms":["lacte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illa irrīdēns crūdēlem tyrannum, sīc fīlium allocūta est:\"Miserēre, filī mī, miserēre mātris tuae, quae tē uterō gestavī, quae tē nātum {{lacte}} aluī: nolī ā fratēmā virtūte dēgenerāre; nōn timēre camificem istum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lactens","latin":"lactens, lactentis","headword":"lactens","letter":"l","pos":"noun","posGroup":"noun","english":"suckling, unweaned animal suitable for sacrifice","forms":["lactentibus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"375 nec lea, cum catulīs {{lactentibus}} ūbera praebet,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lacteus","latin":"lacteus, -a, -um","headword":"lacteus","letter":"l","pos":"adjective","posGroup":"adjective","english":"milky","forms":["lacteum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ea vīta via est in caelum et in hunc coetum eōrum quī iam vīxērunt et corpore laxātī illum incolunt locum quem vidēs' — erat autem is splendidissimō candōre inter flammās circus ēlūcēns — 'quem vōs, ut ā Graecīs accēpistis, \"orbem {{lacteum}}\" nuncupātis.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lacto","latin":"lacto, lactare, lactavi, lactatus","headword":"lacto","letter":"l","pos":"verb","posGroup":"verb","english":"entice, lead on, induce; wheedle, cajole, dupe","forms":["lactem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec contentus fuit recumbere, sed continuô Ephesum tragoedum coepit imitärî et subinde dominum suum spônsiône prôvocäre: ‘sī prasinus proxī- mîs circēnsibus prîmam palmam?’ [T rimalchiô dê testämentô et monumentô suô] Diﬂîlsus hāc contentiône Trimalchiô “Amîci!” inquit, “Et servī hominēs sunt et aequē ūnum {{lactem}} bibērunt, etiam sî illôs mālus tātus oppresserit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lactuca","latin":"lactuca, lactucae","headword":"lactuca","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lettuce","forms":["lactūcās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pōne oxygarum et {{lactūcās}} et cucumerēs!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lacuna","latin":"lacuna, lacunae","headword":"lacuna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"pit/hollow/cavity/depression; pool; gap/deficiency; [~ legis => gap in the law]","forms":["lacūnā","lacūnae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"sint modicī rictūs parvaeque utrimque {{lacūnae}},","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lacunar","latin":"lacunar, lacunaris","headword":"lacunar","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"paneled ceiling","forms":["lacūnāria"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"(täbulae) sūrsum versā; supînä manû drāta; pl tēctum (intexius) Priāpus -î m, deus frūctuum (ut mälum, pirum, prūnum, suāvius esse : s. tē habēre vîderint (: videant) quid Nec diū mîrärî licuit tam ēlegantēs strophās; nam repente {{lacūnāria}} sonāre coepērunt tôtumque triclînium intremuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lacus","latin":"lacus, -ūs","headword":"lacus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"lake","forms":["lace","lacū","lacum","lacus","lacuum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ōlim, dum ambulat, subitō parvum {{lacum}} haud procul ā viā vīdit, ad quem laetissima statim cucurrit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laedere","latin":"(laedō) laedere, laesisse, laesum","headword":"laedere","letter":"l","pos":"verb","posGroup":"verb","english":"injure, hurt; to hurt, injure","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"laedo","latin":"laedo, laedere, laesi, laesus","headword":"laedo","letter":"l","pos":"verb","posGroup":"verb","english":"strike; hurt, injure, wound; offend, annoy","forms":["laedat","laedere","laedit","laesa","laeserant","laeserit","laesō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Attamen, īrātus, puerum nunc {{laedere}} māvult","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laena","latin":"laena, laenae","headword":"laena","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"woolen double cloak","forms":["laena"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ēnsis erat Tyriōque ārdēbat mūrice {{laena}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"laestrygon","latin":"Laestrygon, -onis","headword":"Laestrygon","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"a Laestrygonian, one of a race of giants; a Laestrygonian, one of the cannibal giants","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"laetari","latin":"laetārī","headword":"laetārī","letter":"l","pos":"verb","posGroup":"verb","english":"to rejoice; rejoice, be glad","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"laetatur","latin":"laetātur, laetārī","headword":"laetātur","letter":"l","pos":"verb","posGroup":"verb","english":"rejoice, be glad; rejoices (deponent)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"laete","latin":"laete, laetius, laetissime","headword":"laete","letter":"l","pos":"adverb","posGroup":"adverb","english":"joyfully, gladly; luxuriantly/lushly/abundantly; in rich/florid style","forms":["laetē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Īnō autem nōn gaudēbat quod vidēbat puerum  puelIamque tam laetōs esse, iīsque invidēbat: “Nōlō iam vidēre hōs puerōs tam laetē vīventēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laetitia","latin":"laetitia, -ae","headword":"laetitia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"happiness; joy, gladness","forms":["laetitia","laetitiae","laetitiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Concurrunt his auxiliis visis; fit gratulatio inter eos atque omnium animi ad {{laetitiam}} excitantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"laeto","latin":"laeto, laetare, laetavi, laetatus","headword":"laeto","letter":"l","pos":"verb","posGroup":"verb","english":"gladden, cheer; be glad/joyful, rejoice (medieval)","forms":["laetō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quisquis dē hōc laetō convīviō gaudet, pōculum tollat et bibat mecurn!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laetor","latin":"laetor","headword":"laetor","letter":"l","pos":"verb","posGroup":"verb","english":"rejoice, be glad (deponent)","forms":["laetābantur","laetābātur","laetāberis","laetābor","Laetāminī","laetantēs","Laetantium","laetantur","laetāre","laetārī","laetāris","laetātur","laetātus","laetor"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mārcus rīdēns “{{Laetor}}” inquit “quod ā sorōre meā laudor.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"laetus","latin":"laetus, -a, -um","headword":"laetus","letter":"l","pos":"adjective","posGroup":"adjective","english":"glad, happy; happy, glad","forms":["laeta","laetae","laetam","laetārum","laetās","laetī","laetior","laetīs","laetissima","laetissimīs","laetissimus","laetōs","laetum","laetus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēlia cantat quia {{laeta}} est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"laeva","latin":"laeva, laevae","headword":"laeva","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"left hand","forms":["laeva"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tunc Hebraeī ingressī sunt in mare siccum: erat enim aquā tamquam mūrus ā dextrā eōrum et {{laeva}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"laevus","latin":"laevus, -a, -um","headword":"laevus","letter":"l","pos":"adjective","posGroup":"adjective","english":"left; left, on the left","forms":["laevam","laevō","laevum","laevus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Puer territus pedēs nōdōs aspicit et 'Quid hoc est?' inquit; 'Pēs dexter multō maior est quam pēs {{laevus}}!'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lagoena","latin":"lagoena, lagoenae","headword":"lagoena","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"flask/flagon; bottle w/narrow neck; big earthen jar w/handles; pitcher (Douay)","forms":["lagoenās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Gedeōn trecentōs virōs in trēs partēs dīvīsit, deditque illīs tubās et {{lagoenās}}, in quibus erant lampadēs accēnsae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lambere","latin":"(lambō) lambere, -isse, -itum","headword":"lambere","letter":"l","pos":"","posGroup":"other","english":"lick, wash","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"lambo","latin":"lambo, lambere, lambi, -","headword":"lambo","letter":"l","pos":"verb","posGroup":"verb","english":"lick; lap/lick/suck up, absorb; wash/bathe; surround; fondle/caress (L+S); fawn","forms":["lambentem","lambit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea adeō mītis ut fuisse dīcitur īnfantibus ubera praebēret et pāstor rēgius eam linguā {{lambentem}} puerōs invēnerit — Faustulus eī nōmen fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lamentabilis","latin":"lāmentābilis, -e","headword":"lāmentābilis","letter":"l","pos":"adjective","posGroup":"adjective","english":"deplorable, lamentable","forms":["lāmentābile"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn iam Athēnae ad Crētam tribūtum {{lāmentābile}} mittere dēbēbant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"lamentatio","latin":"lāmentātiō, -ōnis ( f.)","headword":"lāmentātiō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"wailing, lamentation","forms":["lāmentātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is animadvertit sorōrem suam dē frātrum morte nōn labōrantem, spōnsī autem nōmen appellantem identidem \"Curiātiī\" cum gemitū et {{lāmentātiōne}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lamentor","latin":"lamentor, lamentari, lamentatus sum","headword":"lamentor","letter":"l","pos":"verb","posGroup":"verb","english":"lament; utter cries of grief; bewail; lament for; complain that","forms":["lāmentantis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ē sther, {{lāmentantis}} vōce audīta, quaesīvit quid istud reī esset: ut cognōvit l\\1ardochaeum IŪdaeōsque omnēs esse necī dēstinātōs, invocātō Deō, adiit rēgem, suae gentis ruīnam dēprecātūra.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lamentum","latin":"lamentum, lamenti","headword":"lamentum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"wailing (pl.), weeping, groans, laments","forms":["lāmentīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quod audiēns Esāüs ēdidit magnum clāmōrem, et implēvit domum {{lāmentīs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lamia","latin":"lamia, lamiae","headword":"lamia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"witch; bogey/demon; female monster (eats children/child's blood); vampire (Cas)","forms":["Lamīam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum nūntiōs in Aetōliam mīsit 'ut omnī contractā iuventūte convenīrent {{Lamīam}}', et ipse eō decem mīlia ferē peditum et equitēs quīngentōs dūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lampas","latin":"lampas, lampadis","headword":"lampas","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lamp/lantern; light/torch/flame/flambeau/link; firebrand; meteor (like torch)","forms":["lampade","lampadēs","lampadibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Gedeōn trecentōs virōs in trēs partēs dīvīsit, deditque illīs tubās et lagoenās, in quibus erant {{lampadēs}} accēnsae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lana","latin":"lāna, -ae","headword":"lāna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"wool; wool, spinning","forms":["lānā","lānae","lānam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At ego sciō quā dē causā mē fugiās: tibi neque capillī neque barbā meā placent, etsī capillī et barba virum decent: num tū pulchram sine frondibus arborem, pulchram sine pennīs avem, pulchram sine lānā ovem umquam vīdistī?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lancea","latin":"lancea, -ae","headword":"lancea","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lance, spear","forms":["lanceā","lanceās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quārē lanceā cōnfodere cōnātus est, sed Dāvīd ictum lētālem dēclīnātiōne corporis effūgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"langueo","latin":"langueo, languere, -, -","headword":"langueo","letter":"l","pos":"verb","posGroup":"verb","english":"be tired; be listless/sluggish/unwell/ill; wilt, lack vigor","forms":["languēns","languentibus","languēre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"[Amīca {{languēns}} cūranda]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"languor","latin":"languor, languoris","headword":"languor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"faintness, feebleness; languor apathy","forms":["languor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"āere nōn certō corpora {{languor}} habet.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"laniare","latin":"(laniō) laniāre","headword":"laniāre","letter":"l","pos":"","posGroup":"other","english":"tear","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"laniger","latin":"laniger, lanigera, lanigerum","headword":"laniger","letter":"l","pos":"adjective","posGroup":"adjective","english":"wool-bearing, fleecy; woolly","forms":["Lāniger"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc fauce improbā latrō incitātus iūrgiī causam intulit: “Cūr” inquit “turbulentam fēcistī mihi aquam bibentī?” {{Lāniger}} contrā timēns: “Quī possum, quaesō, facere quod quereris, lupe?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lanio","latin":"lanio, laniare, laniavi, laniatus","headword":"lanio","letter":"l","pos":"verb","posGroup":"verb","english":"tear, mangle, mutilate, pull to pieces","forms":["laniāre","laniat","laniātur","laniāvit","laniem","laniet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi fugit, vēlāmina relinquit quae leō ōre cruentō {{laniat}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"lanius","latin":"lanius, lanii","headword":"lanius","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"butcher","forms":["lanius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"inquit “vēnissēs, saltem nôbîs adiūtāssēs: {{lanius}} sanguinem illîs mîsit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lanterna","latin":"lanterna, lanternae","headword":"lanterna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lantern; lamp (L+S); torch","forms":["lanternā","lanternam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ā portū illīc nunc hūc cum lanternā advēnit.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"lanx","latin":"lanx, lancis","headword":"lanx","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"plate, metal dish, tray, platter, charger; pan of a pair of scales","forms":["lance"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In aditū autem ipsô stābat ôstiärius prasinātus, cerasinô succînctus cingulô, atque in {{lance}} argenteā pīsum pūrgā- bat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"laocoon","latin":"Laocoon, Laocoonis","headword":"Laocoon","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Laocoon; (Trojan priest, warned against wooden horse, killed by serpents)","forms":["Lāocoōn"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Lāocoōn}} ārdēns summā dēcurrit ab arce,\net procul: \"Ō miserī, quae tanta īnsānia, cīvēs?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"laomedon","latin":"Laomedon, Laomedontis","headword":"Laomedon","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Laomedon; (king of Troy, father of Priam)","forms":["Lāomedōn","Lāomedonte"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Apollō igitur, cum rēgem in opere perficiendō adiuvāre vellet, ūna cum Neptūnō mortālem fōrmam induit; tum deī, cum ad rēgem adiissent, sē in mūrīs aedificandīs auxilium lāturōs esse dīxērunt; postulāvērunt vērō ut {{Lāomedōn}} idōneam operis mercēdem daret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lapideus","latin":"lapideus, -a, -um","headword":"lapideus","letter":"l","pos":"adjective","posGroup":"adjective","english":"of stone, stone","forms":["lapidea","lapideae","lapideīs","lapideō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc in eōs cecidit grandō {{lapidea}}, et multōs interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lapillus","latin":"lapillus, lapilli","headword":"lapillus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"little stone, pebble; precious stone, gem, jewel","forms":["lapillus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lapillus}} -ī m 7 parvus lapis: gemma VŌs quoque nec cāris aurēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lapis","latin":"lapis, -idis (m.)","headword":"lapis","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"stone, milestone; stone","forms":["lapī","lapide","lapidem","lapidēs","lapidī","lapidibus","lapidum","lapis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio {{lapis}} et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lapsus","latin":"lapsus, lapsus","headword":"lapsus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"gliding, sliding; slipping and falling","forms":["lāpsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Equidem nōn ante recēdām quam pōns {{lāpsus}} erit.” Hic fortissimus mīles Horātius appellābātur, cognōmen vērō eius ‘Cocles’ erat, nam alterō oculō carēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laquear","latin":"laquear, laquearis","headword":"laquear","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"paneled/fretted ceiling (usu. pl.); rafter, ceiling, panel","forms":["laqueāribus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ātria; dēpendent lychnī {{laqueāribus}} aureīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"laqueum","latin":"laqueum, laquei","headword":"laqueum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"noose, halter; snare, trap; lasso; bond, tie","forms":["laqueum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"\"Līctor, colliga manūs!\" Accesserat līctor iniciēbatque {{laqueum}} collō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"laqueus","latin":"laqueus, -ī","headword":"laqueus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"loop, noose; noose","forms":["laqueis","laqueō","laqueōs","laqueus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et {{laqueis}} falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lar","latin":"Lar, Laris","headword":"Lar","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Lares; (usu. pl.); tutelary god/gods of home/hearth/crossroads; home/dwelling","forms":["Larem","Larēs","Larī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praeter- eä grande armārium in angulô vîdî, in cuius aediculā erant {{Larēs}} argenteî positī Venerisque signum marmoreum et pyxis aurea nôn pusilla, in quā barbam ipsîus Interrogāre ego ātriēnsem coepī ‘quās in mediô pictūrās habērent?’ “Îliada et Odys- sîan”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lardum","latin":"lardum, lardi","headword":"lardum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"lard, fat; bacon","forms":["lārdum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Onerävî rūrsus vînum, {{lārdum}}, fabam, sēplasium, mān- “Hôc locô Fortūnāta rem piam fécit: omne enim aurum suum, omnia vestîmenta vēndidit, et mî centum aureôs in manū posuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"largior","latin":"largior, largīrī","headword":"largior","letter":"l","pos":"verb","posGroup":"verb","english":"give generously","forms":["largiantur","largior","largīrētur","largīrī","largīris","largīta","largītur","largītus","largiundō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque mātrī ōrnāmenta et vestīmenta pulchra {{largītur}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"largiri","latin":"largīrī","headword":"largīrī","letter":"l","pos":"verb","posGroup":"verb","english":"to give generously","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"largiter","latin":"largiter","headword":"largiter","letter":"l","pos":"adverb","posGroup":"adverb","english":"in abundance, plentifully, liberally, much; greatly; has great influence","forms":["largiter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ornne genus enim pôma volô sint circum cinerēs meôs, et vīneārum {{largiter}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"largitio","latin":"largītiō, -ōnis ( f.)","headword":"largītiō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"largesse, bribery; bribery, lavish giving","forms":["largītiō","largītiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam rēx fīnem loquendī fēcit, lēgātī Iugurthae, {{largītiōne}} magis quam causā frētī, paucīs respondent: 'Hiempsalem ob saevitiam suam ab Numidīs interfectum; Adherbalem ultrō bellum īnferentem, postquam superātus sit, querī quod iniūriam facere nequīvisset!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"largitor","latin":"largītor, -ōris (m.)","headword":"largītor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"one who gives generously","forms":["largītor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multārum rērum ac maximē pecūniae {{largītor}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"largo","latin":"largo, largare, largavi, largatus","headword":"largo","letter":"l","pos":"verb","posGroup":"verb","english":"enlarge","forms":["largō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quantō est facilius mihi sub tēctō vīvere et ōtiōsum largō satiārī cibō!” [Canis:] “Venī ergō mēcum!” Dum prōcēdunt, lupus ā catēnā collum dētrītum canī aspicit. [Lupus:] “Unde hoc, amīce?” [Canis:] “Nīl est.” [Lupus:] “Dīc, sōdēs, tamen!” [Canis:] “Quia videor ācer, alligant mē interdiū, lūce ut quiēscam, ut vigilem nox cum vēnerit: crepusculō solūtus quā vīsum est vāgor.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"largus","latin":"largus, -a, -um","headword":"largus","letter":"l","pos":"adjective","posGroup":"adjective","english":"generous; generous, lavish","forms":["largae","largus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Largus}} nōn es, magister.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"larva","latin":"larva, larvae","headword":"larva","letter":"l","pos":"noun","posGroup":"noun","english":"evil spirit/demon/devil; horrific mask; model skeleton; ghost/specter/hobgoblin","forms":["lārva","lārvam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Herî nôn tam bonum posuî Pôtantibus ergô nôbîs et lautitiās mîrantibus, {{lārvam}} argenteam attulit servus sîc aptātam ut articulî eius Verte- braeque laxātae in omnem partem ﬂecterentur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lasanum","latin":"lasanum, lasani","headword":"lasanum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"cooking-pot","forms":["lasanum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"@�> (palma) caryôta, thébaica: duo genera palmārum (ﬁﬁctuum) ūberibus im-minēre : nūtrīrī vivîs sêcum ferendus datur al-ligâre: fasciîs alligātus : cui fasciae ligâtae erant ad numerum : ad symphôniam laecasïn (ÂatKâÇstv), verbum pectus pulsāre (ob lūctum), [Sermô convîvärum: Dāma dëﬁîgore, Seleucus dêfünere] Ab hôc ferculô Trimalchiô ad {{lasanum}} surrēxit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lascivia","latin":"lascīvia, -ae","headword":"lascīvia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"wantonness; licence, wantonness","forms":["lascīvia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed ubi illa formīdō mentibus dēcessit, scīlicet ea quae rēs secundae amant, {{lascīvia}} atque superbia, incessēre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lascivus","latin":"lascivus, lasciva, lascivum","headword":"lascivus","letter":"l","pos":"adjective","posGroup":"adjective","english":"playful; lustful, wanton; impudent, mischievous; free from restraint","forms":["lascīva","lascīvae","Lascīvī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cētera {{lascīvae}} faciant concēde puellae,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lassitudo","latin":"lassitudo, lassitudinis","headword":"lassitudo","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"weariness, exhaustion, faintness; lassitude","forms":["lassitūdine"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quādam diē, cum Iacobus sibi parāvisset pulmentum ex lentibus, venit Esāüs fessīs dē viā, et dīxit frātrī: dā mihi hoc pulmentum; nam redeō rūre exanimātus {{lassitūdine}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lassus","latin":"lassus, lassa, lassum","headword":"lassus","letter":"l","pos":"adjective","posGroup":"adjective","english":"tired, weary; languid","forms":["lassus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{lassus}} -ā -um - fessus lassus in hāc iuvenis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"late","latin":"late","headword":"late","letter":"l","pos":"adverb","posGroup":"adverb","english":"widely, far and wide","forms":["lātē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At illum subitus vīscerum dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta scatērent vermibus, et foetōrem lātē ēmitterent, exercituī et aegrō ipsī intolerābilem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"latebra","latin":"latebra, -ae","headword":"latebra","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"hiding-place, retreat","forms":["latebra","latebrās","latebrīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{latebra}} -ē f— locus ubi latet aliquis et, nē tē capiat latebrīs sibi","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"latebrae","latin":"latebrae, -ārum","headword":"latebrae","letter":"l","pos":"","posGroup":"other","english":"hiding place","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"latens","latin":"latens, latentis (gen.), latentior -or -us, latentissimus -a -um","headword":"latens","letter":"l","pos":"adjective","posGroup":"adjective","english":"hidden, concealed; secret, not revealed; [in latenti => in secret]","forms":["latēns","latentem","latentēs","latentia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Forte Saūl sōlus in illam spēluncam ingressūs est, nec {{latentēs}} vīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lateo","latin":"lateo, latere, latui, -","headword":"lateo","letter":"l","pos":"verb","posGroup":"verb","english":"lie hidden, lurk; live a retired life, escape notice","forms":["lateant","lateat","latēbant","latēbat","latent","latēret","latēs","latet","latuēre","latuērunt","latuisse","latuisset","latuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Erat in dēsertō spēluncā vastō recessū patēns: ibi Dāvīd cum suīs comitibus in interiōre parte {{latēbat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"later","latin":"later, -eris (m.)","headword":"later","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"brick","forms":["laterēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc vērō ācerrimē pugnābātur: Graecīs undique prōcurrentibus Trōiānī inclūsī vī et armīs resistēbant, aliī turrēs et culmina domōrum dēstrūēbant atque {{laterēs}} trabēsque in hostēs mūrōs ascendentēs coniciēbant, aliī strictīs gladiīs forēs dēfendēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"latere","latin":"(lateō) latēre, latuisse","headword":"latēre","letter":"l","pos":"verb","posGroup":"verb","english":"lie hidden, lurk; to hide, lurk","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"latericius","latin":"latericius, -a, -um","headword":"latericius","letter":"l","pos":"adjective","posGroup":"adjective","english":"of brick","forms":["laterīciam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn sōlum aedēs sacrās vetustāte collāpsās aut incendiīs absūmptās refēcit, sed plūrimās domōs ē lateribus factās dēstrūxit atque tot et tanta nova opera marmorea aedificāvit ut iūre glōriātus sit \"marmoream sē relinquere urbem quam {{laterīciam}} accēpisset\".","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"latex","latin":"latex, laticis","headword":"latex","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"water; (any) liquid/fluid; running/stream/spring water; juice","forms":["laticēs","laticum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīxit, et in mēnsam {{laticum}} lībāvit honōrem,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"latibulum","latin":"latibulum, latibuli","headword":"latibulum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"hiding-place, den","forms":["latibulō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Canēs, hūc et illūc currentēs, vestīgia sequēbantur ad bēstiam inveniendam; tandem aprum inventum ex dūmīs, in quibus sē occultāverat, expulērunt; quī, cum ex latibulō suō excurrisset atque fugere vellet, ab Adōne, quī parātus erat ad eum trānsfīgendum, hastā percussus cecidit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laticlavius","latin":"laticlavius, laticlavia, laticlavium","headword":"laticlavius","letter":"l","pos":"adjective","posGroup":"adjective","english":"having broad crimson stripe","forms":["lāticlāviam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Palliô enim coccineô adrāsum exclūserat caput, circäque onerātās veste cer- vîcës {{lāticlāviam}} immîserat mappam ﬁmbriîs hinc atque illinc pendentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"latifundium","latin":"latifundium, latifundi(i)","headword":"latifundium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"large estate, farm","forms":["lātifundia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tū {{lātifundia}} gustāre (sentîre) nôn potuî centiēs séstertium corrotun- dâvî : circiter centiēs cen- têna mīlia sēstertium fécî manum dē tabulā!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"latina","latin":"Latina, Latinae","headword":"Latina","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Latin (lingua/language); Latin Way (via); (road between Rome and Beneventum)","forms":["Latīna"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iūlia: “Nōn {i}i{/i}, sed {i}y{/i}:{i} i–y, i–y. {/i} Num {i}y{/i} littera {{Latīna}} est?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"latine","latin":"Latīne","headword":"Latīne","letter":"l","pos":"adverb","posGroup":"adverb","english":"in Latin","forms":["Latīnē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tlēpolemus: “Graecē nec loquī nec legere sciō, sed sciō Latīnē legere.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"latino","latin":"latino, latinare, latinavi, latinatus","headword":"latino","letter":"l","pos":"verb","posGroup":"verb","english":"translate into Latin","forms":["Latīnō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"K litterā, quae frequēns est in linguā Graeca, littera Latīna rārissima est, nam K in ūnō vocābulō Latīnō tantum reperītur, id est kalendae (itemque in praenōmine Kaesō, quod praenōmen Rōmānōrum rārissimum est).","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"latinus","latin":"Latīnus, -a, -um","headword":"Latīnus","letter":"l","pos":"adjective","posGroup":"adjective","english":"Latin","forms":["Latīnae","Latīnās","Latīnī","Latīnīs","Latīnōrum","Latīnōs","Latīnum","Latīnus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Certē nōn dīves est erus meus, sed vir doctus est, quī multōs librōs habet et {{Latīnōs}} et Graecōs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"latio","latin":"latio, lationis","headword":"latio","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"right; proposal (of law); entering (payment); [suffragii ~ => right to vote]]","forms":["Latiō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōlim Sabīnī, quī in Latiō habitābant, magnō exercitū Rōmānōs, hostēs suōs, oppugnāvērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"latito","latin":"latitō (1)","headword":"latitō","letter":"l","pos":"verb","posGroup":"verb","english":"to hide, lurk","forms":["latitāns"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Perque diēs multōs {{latitāns}} omnemque tremīscēns\nad strepitum mortemque timēns cupidusque morīrī,\nglande famem pellēns et mixtā frondibus herbā\nhanc procul adspexī longō post tempore nāvem\nōrāvīque fugam gestū ad lītusque cucurrī,\net mōvī: Graiumque ratis Trōiāna recēpit.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"latium","latin":"Latium, Latii","headword":"Latium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"Latium; (region of central Italy, homeland of the Latins)","forms":["Latiī","Latium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deus agricolārum est Sāturnus, quī ōlim rēx caelī, sed ā fīliō suō Iove ē caelō pulsus, in Italiam venit, eamque regiōnem quae {{Latium}} appellātur optimē rēxit hominēsque, ut tunc erant rudēs ac barbarōs, colere docuit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"latius","latin":"Latius, Latia, Latium","headword":"Latius","letter":"l","pos":"adjective","posGroup":"adjective","english":"Latin; of Latium (central Italy including Rome/Italy); Roman; Italian","forms":["latius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His paucos addit equites qui {{latius}} ostentationis causa vagarentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"latona","latin":"Lātōna, -ae","headword":"Lātōna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Latona (mother of Apollo and Diana)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"latrare","latin":"lātrāre","headword":"lātrāre","letter":"l","pos":"verb","posGroup":"verb","english":"to bark","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"latrat","latin":"lātrat, -ant","headword":"lātrat","letter":"l","pos":"verb","posGroup":"verb","english":"bark; barks","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"latratus","latin":"lātrātus, -ūs","headword":"lātrātus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"barking","forms":["lātrātibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Clāmāre libēbat: “Actaeōn ego sum: dominum cognōscite vestrum!” Verba animō dēsunt; resonat {{lātrātibus}} aether.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"latro","latin":"latrō, -ōnis (m.)","headword":"latrō","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"brigand, robber; robber, brigand; robber, bandit","forms":["lātrandō","lātrante","lātrāre","lātrat","lātrō","latrōnem","latrones","latrōnibus","latrōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos {{latrones}} interficiamus.' Ostendit cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"latrocinium","latin":"latrōcinium, -ī","headword":"latrōcinium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"robbery","forms":["latrōcinia","latrōciniō","latrōcinium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quī omnēs aut arma capiēbant aut capientēs aliōs ab hostibus dēfendēbant; pars equōs ascendere, obviam īre hostibus; pugna latrōciniō magis quam proeliō similis fierī; neque virtūs neque arma satis tegere, quia hostēs numerō plūrēs et undique circumfūsī erant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"latus","latin":"lātus, lāteris","headword":"lātus","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"(n.) side, flank; wide; (n.) side","forms":["lāta","lātae","lātam","latas","latera","latere","laterī","lateribus","lateris","laterum","lātī","latior","lātīs","latissime","lātissimō","lātō","latus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam {{latissime}} possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"laudare","latin":"laudāre","headword":"laudāre","letter":"l","pos":"verb","posGroup":"verb","english":"to praise; praise","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"laudat","latin":"laudat","headword":"laudat","letter":"l","pos":"verb","posGroup":"verb","english":"praises","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"laudo","latin":"laudō, laudāre","headword":"laudō","letter":"l","pos":"verb","posGroup":"verb","english":"praise","forms":["laudābant","laudābar","laudābāris","laudābat","laudābātur","laudābitur","laudāminī","laudāmur","laudāmus","laudandam","laudandī","laudandum","laudandus","laudant","laudantēs","laudantī","laudantibus","laudantium","laudantur","laudāre","laudārent","laudāret","laudārī","laudaris","laudās","laudat","laudātae","laudātī","Laudātīs","laudātum","laudātur","laudātus","laudāvī","laudāvisset","laudāvistī","laudāvit","laudētur","laudō","laudor"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus sorōrem {{laudat}}: “Rēctē respondēs, Iūlia.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"laureatus","latin":"laureātus, -a, -um","headword":"laureātus","letter":"l","pos":"","posGroup":"other","english":"adorned with laurel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"lauretum","latin":"lauretum, laureti","headword":"lauretum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"laurel grove; (esp. as proper name) place on Aventine Hill at Rome","forms":["laurētum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed ubi est?” [Servus:] “Illūc dēscendit ad {{laurētum}} deambulāre.” [Iūlius:] “Grātulāmur illī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lauriger","latin":"lauriger, laurigera, laurigerum","headword":"lauriger","letter":"l","pos":"adjective","posGroup":"adjective","english":"bearing/producing laurels; decked/crowned w/laurels; laurel-wreathed/crowned","forms":["laurigērō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Vīsite laurigērō sacráta Palātia Phoebō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"laurus","latin":"laurus, -ī","headword":"laurus","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"laurel; laurel tree","forms":["laurī","laurō","laurum","laurus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Frūstrā nunc Apollō Daphnēs corpus complectēbātur dūrum ac frīgidum, in eius arboris fōrmam mūtātum, quae ‘{{laurus}}’ appellātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"laus","latin":"laus, laudis","headword":"laus","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"(f.) praise","forms":["laude","laudem","laudēs","laudī","laudibus","laudis","laus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua {{laude}} periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lautitia","latin":"lautitia, lautitiae","headword":"lautitia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"elegance, splendor, sumptuousness, luxury","forms":["lautitiās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cum hās ergô mîrärëmur {{lautitiās}}, accurrit Menelāus et “Hic est” inquit “apud quem cubitum pônëtis, et quidem iam prîncipium cēnae vidētis.” Et iam nôn loquēbātur Mēne- `� läus, cum Trimalèhiô digitôs cōn- m!”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lautus","latin":"lautus","headword":"lautus","letter":"l","pos":"adjective","posGroup":"adjective","english":"washed, bathed","forms":["lauta","lautī","lautissimum","lautum","lautus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iussit Iōsēphus eōs intrōdūcī domum, et {{lautum}} parārī convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lava","latin":"lava, lavae","headword":"lava","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lava","forms":["lavā","lavis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Et dīxit eī:\"Vāde, lavā in natātōriā Sīlō ē.\"Abiit ille, et lāvit et vēnit vidēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lavare","latin":"lavāre","headword":"lavāre","letter":"l","pos":"verb","posGroup":"verb","english":"to wash","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"lavat","latin":"lavat, lavāre","headword":"lavat","letter":"l","pos":"verb","posGroup":"verb","english":"wash, bathe; washes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"lavere","latin":"lavere","headword":"lavere","letter":"l","pos":"verb","posGroup":"verb","english":"to wash","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"lavinia","latin":"Lavinia, Laviniae","headword":"Lavinia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lavinium; (city in Latium founded by Aeneas)","forms":["Lavīnia","Lāvīniae","Lāvīnium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Huius fīlius in prīmā iuventūte periit; sōla in rēgiā erat fīlia, nōmine {{Lavīnia}}, iam mātūra virō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lavo","latin":"lavo, lavare, lavi, lotus","headword":"lavo","letter":"l","pos":"verb","posGroup":"verb","english":"wash, bathe; soak","forms":["lavandī","lavant","lavantibus","lavāre","lavārent","lavārētur","lavārī","lavat","lāvātum","lavātur","lavēmus","laventur","lavere","lāverō","lāvērunt","lavet","lavētur","lāvī","lāvistī","lāvit","lavō","lavor","lōtum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et dīxit eī:\"Vāde, lavā in natātōriā Sīlō ē.\"Abiit ille, et {{lāvit}} et vēnit vidēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"laxare","latin":"(laxō) laxāre","headword":"laxāre","letter":"l","pos":"","posGroup":"other","english":"loose, untie, release","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"laxatus","latin":"laxatus, laxata -um, laxatior -or -us, laxatissimus -a -um","headword":"laxatus","letter":"l","pos":"adjective","posGroup":"adjective","english":"wide, large in extent, spacious; loose, slack, lax","forms":["laxātae","laxātī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Herî nôn tam bonum posuî Pôtantibus ergô nôbîs et lautitiās mîrantibus, lārvam argenteam attulit servus sîc aptātam ut articulî eius Verte- braeque {{laxātae}} in omnem partem ﬂecterentur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"laxe","latin":"laxe, laxius, laxissime","headword":"laxe","letter":"l","pos":"adverb","posGroup":"adverb","english":"loosely, amply; without restraint; over a wide area, widely; on a large scale","forms":["laxe"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"145 Huic decet inflàátos {{laxe}} iacuisse capillōs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"laxo","latin":"laxo, laxare, laxavi, laxatus","headword":"laxo","letter":"l","pos":"verb","posGroup":"verb","english":"loosen, slaken, relax, weaken; expand, open up, extend","forms":["laxābō","laxāre","laxātē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ut cessāvit loquī, dīxit Simonī:\"Due in altum, et laxātē rētia.\"Respondit Simōn:\"Praeceptor, tōtam noctem labōrāvimus, sed nihil cēpimus; tamen, sīcut dixisfī, laxābō rēte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"laxus","latin":"laxus, laxa -um, laxior -or -us, laxissimus -a -um","headword":"laxus","letter":"l","pos":"adjective","posGroup":"adjective","english":"wide, spacious, ample, roomy; loose, not close packed; slack, not tight; lax","forms":["laxīs","laxum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"laxāre («» firmāre) 7 {{laxum}} facere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lea","latin":"lea, -ae","headword":"lea","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lioness","forms":["lea","leās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"et revocat cupidās à{{lea}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lectica","latin":"lectīca, -ae","headword":"lectīca","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"litter, sedan; litter, sedan-chair","forms":["lectīcā","lectīcae","lectīcam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Via quae est inter Tūsculum et vīllam Iūliī nōn tam longa est quam via Latīna, sed servī quattuor quī Tūsculō ad vīllam ambulant fessī sunt, quia {{lectīcam}} et saccōs portant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lectio","latin":"lectio, lectionis","headword":"lectio","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"reading (aloud); perusal; choosing; lecture (Bee); narrative","forms":["lēctiōnem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Iam teneō meam {{lēctiōnem}}: meus, mihi, noster, nōbīs, tuus, tibi, vester, vōbīs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lectissimus","latin":"lēctissimus, -a, -um","headword":"lēctissimus","letter":"l","pos":"adjective","posGroup":"adjective","english":"picked, elite","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"lector","latin":"lector, lectoris","headword":"lector","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"reader","forms":["lēctor","lēctōribus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{lēctor}} carmina dulcī sōnō (: vōce)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lectulus","latin":"lectulus, -ī","headword":"lectulus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"bed; little bed","forms":["lectulī","lectulīs","lectulō","lectulum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam Iūlia quiēta in lectulō suō dormit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lectus","latin":"lectus, -ī","headword":"lectus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"bed, couch; bed; couch, bed","forms":["lēcta","lēctās","lectī","lectīs","lēctissima","lectō","lectōs","lectus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum Quīntus in lectō iacet in cubiculō suō, Medicus in ātriō Iūlium exspectat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"legare","latin":"(lēgō) lēgāre","headword":"lēgāre","letter":"l","pos":"","posGroup":"other","english":"bequeath, send, delegate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"legatio","latin":"lēgātiō, -ōnis ( f.)","headword":"lēgātiō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"embassy, deputation","forms":["lēgātiō","lēgātiōne","legationes","legationibus","lēgātiōnis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dimittit quoque versus {{legationes}}; obtestatur ut in fide maneant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"legatum","latin":"legatum, legati","headword":"legatum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"bequest, legacy","forms":["legatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Trebonium {{legatum}} relinquit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"legatus","latin":"lēgātus, -ī","headword":"lēgātus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"envoy, delegate; envoy; envoy, lieutenant","forms":["legati","legato","legatorum","legatos","lēgātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, {{legatos}} mittunt subsidium rogatum, quo facilius hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"legere","latin":"legere","headword":"legere","letter":"l","pos":"verb","posGroup":"verb","english":"to read; to read, gather, choose","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"legifer","latin":"legifer, legifera, legiferum","headword":"legifer","letter":"l","pos":"adjective","posGroup":"adjective","english":"law-giving","forms":["lēgiferae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{lēgiferae}} Cererī Phoebōque patrīque Lyaeō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"legio","latin":"legiō, -ōnis","headword":"legiō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"(f.) legion","forms":["legio","legione","legionem","legiones","legionibus","legionis","legionum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id esse facile, quod neque {{legiones}} audeant absente imperatore ex hibernis egredi neque imperator sine praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"legionarius","latin":"legiōnārius, -ī","headword":"legiōnārius","letter":"l","pos":"adjective","posGroup":"adjective","english":"legionary","forms":["Legiōnāriī","legionarios","legiōnārius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse {{legionarios}} dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"legit","latin":"legit","headword":"legit","letter":"l","pos":"verb","posGroup":"verb","english":"reads","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"legitimus","latin":"lēgitimus, -a, -um","headword":"lēgitimus","letter":"l","pos":"adjective","posGroup":"adjective","english":"legal, lawful; lawful, legitimate","forms":["lēgitimā","lēgitimae","lēgitimōs","lēgitimum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cui successit IOsiās, vir sānctus et religiōsus, quī ā puerō virtūfi dēditus, populum ad {{lēgitimum}} cultum revocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lego","latin":"legō, legere","headword":"legō","letter":"l","pos":"verb","posGroup":"verb","english":"pick, read","forms":["lectum","lēctūra","lēctūram","lēctūrum","lēctūrus","legam","lēgantur","lēgās","lēgat","legatis","legēbam","legēbās","legēbat","legenda","legendi","legendīs","legendum","legendus","legēns","legente","legentem","legentēs","legentī","legentīs","lēgeram","lēgerat","legere","legerem","lēgerit","leget","lēgētur","legimus","legisse","lēgisset","legit","Legite","legitur","legō","legor","legunt","leguntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id eane de causa, quam {{legatis}} pronuntiarunt, an perfidia adducti fecerint, quod nihil nobis constat, non videtur pro certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lembus","latin":"lembus, -ī","headword":"lembus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"small boat","forms":["lembum","lembus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Oroandem dēnique Crētēnsem, cui nōta Thrāciae ōra erat quia mercātūrās in eā regiōne fēcerat, appellat, 'ut sē sublātum in {{lembum}} ad Cotym dēveheret.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lemnos","latin":"Lemnos, Lemni","headword":"Lemnos","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lemnos; (island sacred to Vulcan)","forms":["Lemnōn","Lēmnos"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Crēta, Rhodus, Naxus, Samos, Chios, Lesbos, {{Lēmnos}}, Euboea sunt īnsulae Graecae.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lena","latin":"lena, lenae","headword":"lena","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"procuress; brothel-keeper","forms":["lēnā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"lēnā -ae f — fēmina quae vīrīs pūellàs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lenio","latin":"lenio, lenire, lenivi, lenitus","headword":"lenio","letter":"l","pos":"verb","posGroup":"verb","english":"mitigate, moderate; alleviate, allay, assuage, ease, calm, placate, appease","forms":["lēniet","lēnīre","lēnīrent","lēnīrī","lēnītus","lēniunda"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Isaacus intrōdūxit Rebeccam in tabernāculum mātris suae, et {{lēnītus}} est dolor quem capiēbat ex morte mātris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lenire","latin":"(lēniō) lēnīre, -īvisse, -ītum","headword":"lēnīre","letter":"l","pos":"verb","posGroup":"verb","english":"placate, appease; to soften, soothe, calm","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"lenis","latin":"lēnis, -e","headword":"lēnis","letter":"l","pos":"adjective","posGroup":"adjective","english":"gentle, mild","forms":["Lēnibus","lēnis","lēnius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quī prior ēditus est pilōsus erat, alter vērō {{lēnis}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lenitas","latin":"lenitas, lenitatis","headword":"lenitas","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"smoothness; gentleness, mildness; lenience","forms":["lēnitāte"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque eā {{lēnitāte}} senātus est ūsus, Quirītēs, ut ex tantā coniūrātiōne tantāque hāc multitūdine domesticōrum hostium, novem hominum perditissimōrum poena rē pūblicā cōnservāta, reliquōrum mentēs sānārī posse arbitrārētur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"leniter","latin":"leniter, lenius, lenissime","headword":"leniter","letter":"l","pos":"adverb","posGroup":"adverb","english":"gently/mildly/lightly/slightly; w/gentle movement/incline; smoothly; moderately","forms":["leniter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Collis erat {{leniter}} ab infimo acclivis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"leno","latin":"leno, lenonis","headword":"leno","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"brothel keeper; bawd; procurer, pimp; panderer","forms":["lēnō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec urbs Epidamnus est, dum haec agitur fābula — quandō alia agētur, aliud fīet oppidum, sīcut familiae quoque solent mūtārier: modo lēnō hīc habitat, modo adulēscēns, modo senex...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lens","latin":"lens, lentis","headword":"lens","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lentil; lentil-plant; S:lens (Cal)","forms":["lentem","lentibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quādam diē, cum Iacobus sibi parāvisset pulmentum ex {{lentibus}}, venit Esāüs fessīs dē viā, et dīxit frātrī: dā mihi hoc pulmentum; nam redeō rūre exanimātus lassitūdine.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lente","latin":"lente","headword":"lente","letter":"l","pos":"adverb","posGroup":"adverb","english":"slowly","forms":["lentē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aqua flūminis tam lentē currēbat, ut in utram partem flueret oculīs cernī nōn posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lentesco","latin":"lentesco, lentescere, -, -","headword":"lentesco","letter":"l","pos":"verb","posGroup":"verb","english":"become sticky; relax","forms":["lentēscere","lentēscunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lentēscere}} — lentus fierī, neglegī Sed mora tūta brevis: lentēscunt","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lento","latin":"lento, lentare, lentavi, lentatus","headword":"lento","letter":"l","pos":"verb","posGroup":"verb","english":"bend under strain","forms":["lenter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lenter}}, comp violentius","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lentulus","latin":"lentulus, lentula, lentulum","headword":"lentulus","letter":"l","pos":"adjective","posGroup":"adjective","english":"somewhat slow","forms":["Lentulī","Lentulō","Lentulum","Lentulus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Curius Dentātus et Cornēlius {{Lentulus}} adversum Pyrrhum missī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lentus","latin":"lentus, -a, -um","headword":"lentus","letter":"l","pos":"adjective","posGroup":"adjective","english":"slow","forms":["lenta","lentissima","lentius","lentum","lentus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tū modo Pompēia {{lentus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"leo","latin":"leō, leōnis","headword":"leō","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"(m.) lion","forms":["leō","leōne","leōnem","leonēs","leōnibus","leōnis","leōnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit comam, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis rōbore: obvium {{leōnem}} manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lepide","latin":"lepide","headword":"lepide","letter":"l","pos":"adverb","posGroup":"adverb","english":"charmingly delightfully; wittily; fine, excellent (formula approbation)","forms":["Lepide"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Iam discēde, {{Lepide}}, antequam ille revenit!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lepidus","latin":"lepidus, lepida -um, lepidior -or -us, lepidissimus -a -um","headword":"lepidus","letter":"l","pos":"adjective","posGroup":"adjective","english":"agreeable, charming, delightful, nice; amusing, witty (remarks/books)","forms":["lepidī","Lepidissimus","Lepidō","Lepidum","Lepidus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Meus amīcus, {{Lepidus}}, nōn est servus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lepor","latin":"lepor, leporis","headword":"lepor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"charm, pleasantness","forms":["lepōrem","leporēs","leporī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Maenalius leporī det sua terga canis,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lepos","latin":"lepos, leporis","headword":"lepos","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"charm, grace; wit; humor","forms":["lepōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vērum ingenium eius haud absurdum: posse versūs facere, iocum movēre, sermōne utī vel modestō, vel mollī, vel procācī — prōrsus multae facētiae multusque {{lepōs}} inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"lepra","latin":"lepra, leprae","headword":"lepra","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"leprosy; various inflammatory skin diseases; psoriasis; (usu. pl.)","forms":["lepram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cumque ā pontifice admonitus nōn pāruisset, turpl morbō, quem ' {{lepram}}' vocant, correptus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lepus","latin":"lepus, leporis","headword":"lepus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"hare","forms":["lepus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Affer olīvās albās et cāseum!” [Ad hospitēs:] “Cēnāte!” [Post gustātiōnem appōnuntur varia fercula, ut gallīna, {{lepus}}, aper.] [Iūlius, ad ministrum:] “Praecīde aprum et gallīnam et lepōrem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lesbius","latin":"Lesbius, Lesbia, Lesbium","headword":"Lesbius","letter":"l","pos":"adjective","posGroup":"adjective","english":"Lesbian, of Lesbos (Aegean island); type of sculptured decoration","forms":["Lesbia","Lesbiae","Lesbiam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Me vero magis iuvant carmina bella quae Catullus scripsit ad {{Lesbiam}} amicam.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lesbos","latin":"Lesbos, Lesbi","headword":"Lesbos","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lesbos; (island in North Aegean, famous for lyric poetry of Sappho and wine)","forms":["Lesbos"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Crēta, Rhodus, Naxus, Samos, Chios, {{Lesbos}}, Lēmnos, Euboea sunt īnsulae Graecae.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lesbus","latin":"Lesbus, Lesbi","headword":"Lesbus","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lesbos; (island in North Aegean, famous for lyric poetry of Sappho and wine)","forms":["Lesbī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Arīōn, vir nōbilis Lesbī nātus, tam pulchrē fidibus canēbat ut alter Orpheus appellārētur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"letalis","latin":"letalis, letalis, letale","headword":"letalis","letter":"l","pos":"adjective","posGroup":"adjective","english":"deadly, fatal; lethal, mortal","forms":["lētālem","lētālis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quārē lanceā cōnfodere cōnātus est, sed Dāvīd ictum {{lētālem}} dēclīnātiōne corporis effūgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lethaeus","latin":"Lethaeus, Lethaea, Lethaeum","headword":"Lethaeus","letter":"l","pos":"adjective","posGroup":"adjective","english":"of Lethe; causing forgetfulness, of the underworld","forms":["Lēthaeīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Iāsōn eum aquīs {{Lēthaeīs}} sparsit et ter dīxit verba somnōs placidōs facientia ut somnus in oculōs dracōnis venīret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"leto","latin":"leto, letare, letavi, letatus","headword":"leto","letter":"l","pos":"verb","posGroup":"verb","english":"kill","forms":["lētō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Et vērē nocte sequenfi angelus Deī centum octōgintā quīnque hostium milia lētō dedit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"letum","latin":"lētum, -ī","headword":"lētum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"death, ruin","forms":["lētī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"ille diēs prīmus lētī prīmusque malōrum","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"levare","latin":"(levō) levāre, levāvisse, levātum","headword":"levāre","letter":"l","pos":"verb","posGroup":"verb","english":"lift, raise; to lift, raise","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"levat","latin":"levat","headword":"levat","letter":"l","pos":"verb","posGroup":"verb","english":"lifts, raises","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"levis","latin":"levis, -e","headword":"levis","letter":"l","pos":"adjective","posGroup":"adjective","english":"light, slight; light (in weight)","forms":["leve","levem","levēs","levi","levia","levibus","levior","leviōra","leviore","levis","levissimē","levium","levius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, {{leviore}} de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"levita","latin":"Levita, Levitae","headword":"Levita","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"deacon; Levite","forms":["Lēvīta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Similiter {{Lēvīta}} quīdam, cum eum vīdisset, pertransiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"leviter","latin":"leviter, levius, levissime","headword":"leviter","letter":"l","pos":"adverb","posGroup":"adverb","english":"lightly/gently/softly/quietly/mildly/slightly; groundlessly/thoughtlessly","forms":["leviter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum prīmum autem {{leviter}} operculum sustulit, subitō omnia mala, omnēs morbī omnēsque dolōrēs ex illō vāse exiērunt atque longē lātēque per tōtum terrārum orbem sparsī sunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"levo","latin":"levo, levare, levavi, levatus","headword":"levo","letter":"l","pos":"verb","posGroup":"verb","english":"lift/raise/hold up; support; erect, set up; lift off, remove (load); comfort","forms":["levāre","levāret","levārī","levat","levātī","levātōs","levātum","levāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Praesertim lūctus mātris nūllō sōlāciō levārī poterat: haec cotīdiē, domō ēgressa, circumībat viās omnēs, quā fīlium suum reditūrum esse spērābat, ut procul vidēret eum, sī fierī posset, venientem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lex","latin":"lēx, lēgis","headword":"lēx","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"(f.) law, motion, bill; law","forms":["lege","lēgem","leges","legī","legibus","lēgis","lēgum","lēx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum {{leges}} duo ex una familia vivo utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"libare","latin":"(lībō) lībāre","headword":"lībāre","letter":"l","pos":"","posGroup":"other","english":"make a libation, pour","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"libellus","latin":"libellus, -ī","headword":"libellus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"small book; little book, scroll","forms":["libellī","libellis","libellō","libellos","libellum","libellus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sed ipsa male nārrō: ex libellō recitābō tibi aliquid.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"libens","latin":"libēns (gen. libentis)","headword":"libēns","letter":"l","pos":"adjective","posGroup":"adjective","english":"willing, glad","forms":["libēns","libente","libentibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīs vēro {{libēns}}, quī omnibus pulchn et for tēs vidēbantur, tanta laetitia afficiēbātur, ut sē mortālium fēlīcissimam esse crēderet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"libenter","latin":"libenter","headword":"libenter","letter":"l","pos":"adverb","posGroup":"adverb","english":"with pleasure, gladly; gladly; gladly, willingly","forms":["libenter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faciam {{libenter}}, inquit Esāüs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"liber","latin":"liber, -brī","headword":"liber","letter":"l","pos":"noun (m.); adjective","posGroup":"noun","english":"book; free","forms":["liber","libera","līberae","līberam","līberī","liberis","liberius","līberōrum","liberos","līberum","librī","librōs","librum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio subiectos dolerent {{liberius}} atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"liberalis","latin":"liberalis, liberalis, liberale","headword":"liberalis","letter":"l","pos":"adjective","posGroup":"adjective","english":"honorable; courteous, well bred, gentlemanly; liberal; generous","forms":["līberālēs","līberālis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Miserēre pauperum, ut Deus tuī misereātur: quantum potuerīs, estō beneficus et {{līberālis}}; sī tibi magnae opēs suppetant, multum tribue, sī parvae, parum, sed libenter; quoniam beneficentia hominem ab aeternā morte līberat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"liberalitas","latin":"liberalitas, liberalitatis","headword":"liberalitas","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"courtesy, kindness, nobleness; generosity; frankness; gift","forms":["līberālitās"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iam prīdem equidem nōs vēra vocābula rērum āmīsimus: quia bona aliēna largīrī {{līberālitās}}, malārum rērum audācia fortitūdō vocātur, eō rēs pūblica in extrēmō sita est.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"liberare","latin":"(līberō) līberāre, -āvisse, -ātum","headword":"līberāre","letter":"l","pos":"verb","posGroup":"verb","english":"set free; to free, set free, liberate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"liberator","latin":"līberātor, -ōris (m.)","headword":"līberātor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"deliverer, liberator; liberator, deliverer","forms":["līberātor","līberātōrem","līberātōris","līberātōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Caput obnūbe — {{līberātōris}} urbis huius!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"libere","latin":"(libet) libēre","headword":"libēre","letter":"l","pos":"verb","posGroup":"verb","english":"it pleases (+ dat.); to please (+ dat.)","forms":["libere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sextium legatum, quem minoribus castris praesidio reliquerat, misit, ut cohortes ex castris celeriter educeret et sub infimo colle ab dextro latere hostium constitueret, ut, si nostros loco depulsos vidisset, quo minus {{libere}} hostes insequerentur terreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"liberi","latin":"līberī, -ōrum","headword":"līberī","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"children","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"libero","latin":"libero, liberare, liberavi, liberatus","headword":"libero","letter":"l","pos":"verb","posGroup":"verb","english":"free; acquit, absolve; manumit; liberate, release","forms":["līberābantur","Līberābis","līberāre","līberārēmur","līberārent","līberāret","līberārī","līberat","līberāta","līberātae","līberātam","līberātās","līberātī","līberātum","līberātus","līberāverīs","līberāverit","līberāvit","līberet","līberō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Habēbat in animō {{līberāre}} Iōsēphum ex eōrum manibus, et illum extrahere ē foveā, atque ad patrem redūcere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"libertas","latin":"lībertās, lībertātis","headword":"lībertās","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"(f.) freedom; liberty, freedom; freedom, liberty","forms":["lībertās","libertate","libertatem","libertati","libertatis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in {{libertatem}} vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"libertinus","latin":"lībertīnus, -a, -um","headword":"lībertīnus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"freed","forms":["lībertīnī","Lībertīnīs","lībertīnum","lībertīnus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sōlus Orontēs, cui nōn placet vīnum mixtum, merum pōtat, sed is Graecus est atque {{lībertīnus}}. (Lībertīnus est quī servus fuit et līberātus est; in lectō īmō accumbunt lībertīnī.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"libertus","latin":"libertus, liberti","headword":"libertus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"freedman; ex-slave","forms":["lībertī","lībertīs","lībertus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Volturciō, comprobātō eōrum indiciō, praemia dēcernuntur, lībertī et paucī ex clientibus Lentulī dīversīs itineribus opificēs atque servitia in vīcīs ad eum ēripiundum sollicitābant, partim exquīrēbant ducēs multitūdinum quī pretiō rem pūblicam vexāre solitī erant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"libet","latin":"libet, libere, libuit, libitus est","headword":"libet","letter":"l","pos":"verb","posGroup":"verb","english":"it pleases, is pleasing/agreeable; (w/qui whatever, whichever, no matter)","forms":["libeat","libēbat","libet","libuerit","libuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cave nē mē quidquam cēlēs eōrum quae audīstī.” Iubentī pāruit Samūēl, illīque ēnārrāvit omnia verba Dominī, cui Hēlī: “Dominus est” ait “faciat quod sibi {{libuerit}}.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"libidinosus","latin":"libidinosus, libidinosa, libidinosum","headword":"libidinosus","letter":"l","pos":"adjective","posGroup":"adjective","english":"lustful, wanton; capricious","forms":["libīdinōsē"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Post, ubi paulātim licentia crēvit, iuxtā bonōs et malōs libīdinōsē interficere, cēterōs metū terrēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"libido","latin":"libīdō, -inis ( f.)","headword":"libīdō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"desire, lust","forms":["libīdine","libīdinem","libīdinēs","libīdinī","libīdinis","libīdinum","libīdō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Parcior in nōbīs nec tam furiōsa libīdō est:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"libo","latin":"libo, libare, libavi, libatus","headword":"libo","letter":"l","pos":"verb","posGroup":"verb","english":"nibble, sip; pour in offering/a libation; impair; graze, touch, skim (over)","forms":["lībāre","lībat","lībātō","lībāvit","lībō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quid? quasi nātālī cum poscit mūnera lībō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"libra","latin":"lībra, -ae","headword":"lībra","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"balance, pound (327 g); pound (a weight)","forms":["lībra","lībrās","librīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōlī putāre, Symmache, hominī satis esse corpus cūrāre: etiam mentem cūrāre opus est, neque id fierī potest sine {{librīs}} mēns mentis philosophōrum.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"librilis","latin":"librilis, librilis, librile","headword":"librilis","letter":"l","pos":"adjective","posGroup":"adjective","english":"weighing a (Roman) pound","forms":["librilibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nostri, ut superioribus diebus, ut cuique erat locus attributus, ad munitiones accedunt; fun: dis {{librilibus}} sudibusque, quas in opere disposuerant, ac glandibus Gallos proterrent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"libro","latin":"libro, librare, libravi, libratus","headword":"libro","letter":"l","pos":"verb","posGroup":"verb","english":"balance,swing; hurl","forms":["librō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et cum ille ē librō suō recitat, nōs simper dormīmus!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"libya","latin":"Libya, Libyae","headword":"Libya","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Libya (general term for North Africa); peoples (pl.) of Libya","forms":["Libyae","Libyam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Spectāte terrās in Āfricā: Maurītāniam, Numidiam, {{Libyam}}, Aethiopiam, Aegyptum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"libycus","latin":"Libycus, Libyca, Libycum","headword":"Libycus","letter":"l","pos":"adjective","posGroup":"adjective","english":"Libyan; African","forms":["Libycae","Libycās","Libycī","Libycīs","Libycōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ubi Trōiānae rēmīs avidamque Charybdin\nēvicēre ratēs, cum iam prope lītus adessent\nAusonium, {{Libycās}} ventō referuntur ad ōrās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"licentia","latin":"licentia, -ae","headword":"licentia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"wantonness, license; licence, unrestrained freedom","forms":["licentiā","licentiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quā tū audācia, mē vīvō, vocāre ausus es patrēs aut sēde cōnsīdere mea?\" Cum ille ferōciter ad haec — \"sē patris suī tenēre sēdem: fīlium rēgis multō potiōrem rēgnī hērēdem esse quam servum; illum satis diū per {{licentiam}} illūsisse dominīs\" — clāmor ab utriusque fautōribus oritur et concursus populī fīēbat in cūriam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"liceo","latin":"liceo, licere, licui, -","headword":"liceo","letter":"l","pos":"verb","posGroup":"verb","english":"fetch (price); (with ABL or GEN)","forms":["līce"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hannibal {{līce}} prīmā Balāribus levīque aliā armātūrā praemissā trānsgressus flūmen, ut quōsque trādūxerat ita in aciē locābat: Gallōs Hispānōsque equitēs prope rīpam laevō in cornū adversus Rōmānum equitātum; dextrum cornū Numidīs equitibus datum; media aciēs peditibus firmāta ita ut Āfrōrum utraque cornua essent, interpōnerentur hīs mediī Gallī atque Hispānī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"licere","latin":"licēre","headword":"licēre","letter":"l","pos":"verb","posGroup":"verb","english":"to be allowed (licet, it is allowed)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"licet","latin":"licet, licēre","headword":"licet","letter":"l","pos":"verb","posGroup":"verb","english":"(+ dat.) it is allowed, one may; it is permitted (+ dat. + inf.)","forms":["liceat","licēbat","licēbit","licēre","licēret","licet","licitō","licitum","licuisse","licuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia: “Sī magistrum rīdētis atque in lūdō dormītis, rēctē reprehendiminī et verberāminī, neque enim in lūdō dormīre {{licet}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"licinius","latin":"Licinius, Licinia, Licinium","headword":"Licinius","letter":"l","pos":"adjective","posGroup":"adjective","english":"Licinian; of Licenius gens","forms":["Liciniī","Licinium","Licinius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Aliquot deinde annīs post bellum Senonicum Thebānī Lacedaemoniōs, duce Epamīnondā, apud Leuctra superāvērunt, ac brevī post tempore in urbe Rōmā lēge Liciniī Stōlōnis cōnsulēs creārī etiam ex plēbe coepī, cum anteā iūs nōn esset nisi ex patriciīs gentibus fierī cōnsulem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"licium","latin":"licium, lici(i)","headword":"licium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"thread; leash or heddle (in weaving)","forms":["lici","licium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Erat autem vë- nä{{licium}} cum titulîs pictum, et ipse Trimalchiô capillātus cādūceum tenēbat Minerväque dūcente Rômam intrābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lictor","latin":"līctor, -ōris (m.)","headword":"līctor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"lictor; lictor, attendant of a magistrate","forms":["līctor","līctōre","līctōrēs","līctōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et ut hominēs agrestēs novum rēgem verērentur, ipse sē īnsignibus imperiī augustiōrem fēcit: cum vestem purpuream induit, tum {{līctōrēs}} duodecim sūmpsit, quī fascēs et secūrēs ante eum gerentēs īrent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ligare","latin":"(ligō) ligāre","headword":"ligāre","letter":"l","pos":"","posGroup":"other","english":"bind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"liger","latin":"Liger, Ligeris","headword":"Liger","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Liger; the Loire, river in western Gaul","forms":["Liger"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ipsi ex finitimis regionibus copias cogere, praesidia custodiasque ad ripas Ligeris disponere equitatumque omnibus locis iniciendi timoris causa ostentare coeperunt, si ab re frumentaria Romanos excludere aut adductos inopia ex provincia expellere possent Quam ad spem multum eos adiuvabat quod {{Liger}} ex nivibus creverat, ut omnino vado non posse transiri videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ligneus","latin":"ligneus, -a, -um","headword":"ligneus","letter":"l","pos":"adjective","posGroup":"adjective","english":"wooden","forms":["ligneā","ligneam","ligneās","ligneō","ligneōs","ligneum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ad impietātem accessit crūdēlitās: cum enim Isaliī s prophēta Īram dīvīnam illī dēnūntiāsset, rēx furōre percitus prophētam serrā ligneā secarī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lignum","latin":"lignum, -ī","headword":"lignum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"wood","forms":["ligna","lignō","lignōrum","lignum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Abrahāmus nōn dubitāvit pārēre Deō iubentī: imposuit {{ligna}} Isaacō; ipse vērō portābat ignem et gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ligo","latin":"ligō (1)","headword":"ligō","letter":"l","pos":"verb","posGroup":"verb","english":"bind, tie, fasten; tie, bind","forms":["ligābāmus","ligāre","ligārī","ligat","ligātās","Ligere","Ligeris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis {{Ligeris}} contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lilium","latin":"līlium, -ī","headword":"līlium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"lily","forms":["līlia","lilium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id ex similitudine floris {{lilium}} appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"limbus","latin":"limbus, limbi","headword":"limbus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"border, edge; ornamental border of a robe","forms":["limbō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīdoniam pictō chlamydem circumdata limbō;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"limen","latin":"līmen, līminis","headword":"līmen","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"(n.) threshold","forms":["līmen","līmina","līmine","līminibus","līminis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa intrā {{līmen}} resistēns “Ad forum eō” inquit, “Nōlō sōla manēre in hāc domō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"limes","latin":"līmes, -ītis (m.)","headword":"līmes","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"path, track; path, boundary","forms":["līmes"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Quae cum dīxisset, \"Egō vērō\" inquam \"Āfricāne, sīquidem bene meritīs dē patriā quasi {{līmes}} ad caelī aditum patet, quamquam ā pueritiā vestīgiīs ingressus patris et tuīs decōrī vestrō nōn dēfuī, nunc tamen tantō praemiō exposītō ēnītar multō vigilantius!\" Et ille: \"Ille vērō ēnītere et sīc habētō: nōn esse tē mortālem, sed corpus hoc.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"limo","latin":"limo, limare, limavi, limatus","headword":"limo","letter":"l","pos":"verb","posGroup":"verb","english":"file; polish; file down; detract gradually from","forms":["līmō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deus fīnxit corpus hominis ē līmō terrae; dēdit illī animam vīventem; fēcit illum ad similitūdinem suam, et nōmināvit illum Adamum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"limus","latin":"līmus, -ī","headword":"līmus","letter":"l","pos":"","posGroup":"other","english":"mud","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"linea","latin":"līnea, -ae","headword":"līnea","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"string, line; line; necklace","forms":["līnea","līneam","līneās","lineis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis {{lineis}} suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lingon","latin":"Lingon, Lingonis","headword":"Lingon","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Lingones (pl.), a people of W Cen. Gaul - in Caesar's \"Gallic War\"","forms":["Lingones"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in {{Lingones}} contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lingua","latin":"lingua, -ae","headword":"lingua","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"tongue, language","forms":["lingua","linguae","linguam","linguās","linguīs","LINGVA"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, {{linguam}} amputarī, cutem capitis detrahī, summās mantīs ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lingula","latin":"lingula, lingulae","headword":"lingula","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"tongue of land","forms":["lingula"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec brevis in rūgās {{lingula}} pressa suās,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"linio","latin":"linio, linire, linivi, linitus","headword":"linio","letter":"l","pos":"verb","posGroup":"verb","english":"smear, plaster (with); seal (wine jar); erase/rub over; befoul; cover/overlay","forms":["līnīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Noēmus, admonitus ā Deō, exstrūxit ingentem arcam in modum nāvis; {{līnīvit}} eam bitūmine, et in eam indūxit pār ūnum omnium avium et animantium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lino","latin":"lino, linere, levi, litus","headword":"lino","letter":"l","pos":"verb","posGroup":"verb","english":"smear, plaster (with); seal (wine jar); erase/rub over; befoul; cover/overlay","forms":["lēvīt","līne","linere","līnī","līnō","linunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In itinere dīxit illī angelus: “Statim ut domum ingressūs eris, Deum adōrā, et, complexūs patrem, {{līne}} oculōs eius felle piscis, quod servāstī: tunc sānābuntur oculī eius, tēque et caelum pater laetus cōnspiciet.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"linquere","latin":"(linquō) linquere, līquisse","headword":"linquere","letter":"l","pos":"","posGroup":"other","english":"leave","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"linquo","latin":"linquo, linquere, liqui, lictus","headword":"linquo","letter":"l","pos":"verb","posGroup":"verb","english":"leave, quit, forsake; abandon, desist from; allow to remain in place; bequeath","forms":["linquant","linquēns","linquere","linquit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum sociōs portum {{linquere}} iussit, ac nāvēs ab īnsulā Leucadiā praeter lītora Ēpīrī vectae prōtinus ad portum Būthrōtī urbis accessērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"linter","latin":"linter, -tris ( f./m.)","headword":"linter","letter":"l","pos":"noun","posGroup":"noun","english":"small boat, skiff","forms":["lintres"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Conquirit etiam {{lintres}}; has magno sonitu remorum incitatas in eandem partem mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"linteum","latin":"linteum, lintei","headword":"linteum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"linen cloth; linen; sail; napkin; awning; bedsheet (Cal)","forms":["lintea","linteum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sed sī Tēlamōnius isset, orba suīs essent etiam nunc {{lintea}} ventīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"linum","latin":"linum, lini","headword":"linum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"flax, linen cloth/thread; rope; fishing line; (hunter's/fisher's) net","forms":["līnum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nōs {{līnum}} incīdimus, legimus.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"lippus","latin":"lippus, lippa, lippum","headword":"lippus","letter":"l","pos":"adjective","posGroup":"adjective","english":"having watery or inflamed eyes","forms":["lippus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hinc, involūtus coccinā gausapā, lectīcae impositus est, praecēdentibus phalerātis cursôribus quattuor et chîra- maxiô in quô dēliciae eius vehēbantur, puer vetulus, {{lippus}}, dominô Trimalchī- ône dëfôrmior.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"liqueo","latin":"liqueo, liquere, licui, -","headword":"liqueo","letter":"l","pos":"verb","posGroup":"verb","english":"be in molten/liquid state; be clear to a person; be evident","forms":["līque"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nàvà{{līque}} gener cīnctus honōre caput.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"liquesco","latin":"liquesco, liquescere, -, -","headword":"liquesco","letter":"l","pos":"verb","posGroup":"verb","english":"become liquid/fluid, melt, liquefy; decompose, putrefy; grow soft/effeminate","forms":["liquēscit","liquēscunt"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Mollīrī membra vidērēs: ossa et caeruleī crīnēs digitīque et crura et pedēs {{liquēscunt}}; post haec umerī et tergum et pectus in gelidās undās abeunt; dēnique prō sanguine vīvō subit aqua clāra; nihil restat quod tangere possēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"liquidus","latin":"liquidus, -a, -um","headword":"liquidus","letter":"l","pos":"adjective","posGroup":"adjective","english":"liquid","forms":["liquida","liquidīs","liquidō","liquidōs","liquidum","liquidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cupit ipse tenērī: nam quotiēs {{liquidīs}} porrēximus ōscula lymphīs, hīc totiēs ad mē resupīnō nītitur ōre.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"liquor","latin":"liquor, liquoris","headword":"liquor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"fluid, liquid","forms":["liquor","liquōre"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ā tē dēcurrit ad meōs haustūs {{liquor}}!” Repulsus ille vēritātis vīribus: “Ante hōs sex mēnsēs” ait “maledīxistī mihi!” Respondit agnus: “Equidem nātus nōn eram!” “Pater hercle tuus” ille inquit “maledīxit mihi!” — atque ita correptum lacerat iniūstā nece!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"lis","latin":"līs, litis ( f.)","headword":"līs","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"dispute, lawsuit","forms":["līs","Līte","lītem","lītēs","lītis","litum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"/vé{{līs}} t&cta; tentōria : castra (Rhēsus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"litaviccus","latin":"Litaviccus, Litavicci","headword":"Litaviccus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Litaviccus; (Aedui Gaul, led forces against Caesar)","forms":["Litavicci","Litavicco","Litaviccum","Litaviccus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, sollicitatus ab Arvernis pecunia cum quibusdam adulescentibus colloquitur; quorum erat princeps {{Litaviccus}} atque eius fratres amplissima familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lito","latin":"lito, litare, litavi, litatus","headword":"lito","letter":"l","pos":"verb","posGroup":"verb","english":"obtain/give favorable omens from sacrifice; make (acceptable) offering (to)","forms":["litātīs","litēre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"conchā (: margarīta) ē dīversō {{litēre}} — Jectāque dīversō lītore","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"littera","latin":"littera, -ae","headword":"littera","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"letter; pl. writing, letter","forms":["littera","litterae","litteram","litterārum","litterās","litteris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His {{litteris}} cognitis Romae dierum viginti supplicatio redditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"litterae","latin":"litterae, -ārum","headword":"litterae","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"a letter = epistula; a letter, epistle; writing","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"litus","latin":"lītus, lītoris","headword":"lītus","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"(n.) shore; shore, beach; shore, coast","forms":["lītora","lītore","lītorī","lītoribus","lītus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Post paucōs diēs multitūdō Hebraeōrum pervēnit ad {{lītus}} maris Rubrī, ibique castra posuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lituus","latin":"lituus, -ī","headword":"lituus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"augur’s staff, trumpet; augur’s curved staff; curved trumpet","forms":["lituō","lituum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Augur ad laevam eius capite vēlātō sēdem cēpit dextrā manū baculum aduncum tenēns, quem \"{{lituum}}\" appellāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lo","latin":"lo","headword":"lo","letter":"l","pos":"interjection","posGroup":"interjection","english":"Lo!; (magic word to cure bite of mad dog)","forms":["lō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Itaque cotldiē, cum sōl altissimus erat, silvās petēbant in quibus Iuppiter puellae fābulās nārrābat atque lō ipsā canēbat. lunō autem, rēgīna deōrum atque hominum, postquam hoc animadvertit neque marītum in caelō repperit, ad terram dēscendit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"locare","latin":"(locō) locāre","headword":"locāre","letter":"l","pos":"","posGroup":"other","english":"place","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"locativus","latin":"locātīvus (cāsus)","headword":"locātīvus","letter":"l","pos":"","posGroup":"other","english":"locative","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"loco","latin":"loco, locare, locavi, locatus","headword":"loco","letter":"l","pos":"verb","posGroup":"verb","english":"place, put, station; arrange; contract (for); farm out (taxes) on contract","forms":["loca","locābat","locant","locārī","locās","locat","locāta","locātam","locātī","locātōs","locāvī","locāvit","loco"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eo cum venisset, timentes confirmat, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae {{loca}} hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"loculus","latin":"loculus, loculi","headword":"loculus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"spot, little/small place; compartment/pigeon-hole; coffin, bier (Vulgate)","forms":["loculum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quam cum vīdisset Jēsus, misericordiā mōtus, dīxit mulierī:\"Noll flēre.\"Et accessit et tetigit {{loculum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"locum","latin":"locum, loci","headword":"locum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"seat, rank, position; soldier's post; quarters; category; book passage, topic","forms":["locum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eo cum pervenisset, ad reliquas legiones mittit priusque omnes in unum {{locum}} cogit quam de eius adventu Arvernis nuntiari posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"locuples","latin":"locuplēs (gen. -ētis)","headword":"locuplēs","letter":"l","pos":"adjective","posGroup":"adjective","english":"rich, wealth","forms":["locuplēs","locuplētissimī","locuplētium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aliquot annīs post pater Cicerōnis, eques {{locuplēs}}, Rōmam migrāvit, ut fīliōs Marcum et Quīntum optimīs magistrīs docendōs trāderet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"locupletare","latin":"(locuplētō) locuplētāre","headword":"locuplētāre","letter":"l","pos":"","posGroup":"other","english":"enrich","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"locupleto","latin":"locupleto, locupletare, locupletavi, locupletatus","headword":"locupleto","letter":"l","pos":"verb","posGroup":"verb","english":"enrich","forms":["locuplētāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque, hōc cōnsiliō et quasi senātū fultus et mūnītus, et bella cum fīnitimīs fēlīcissimē multa gessit et, cum ipse nihil ex praedā domum suam reportāret, {{locuplētāre}} cīvēs nōn dēstitit.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"locus","latin":"locus, -ī","headword":"locus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"place","forms":["loci","locis","locorum","locōs","locus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis {{locis}} queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"longe","latin":"longē","headword":"longē","letter":"l","pos":"adverb","posGroup":"adverb","english":"far; far away","forms":["longe"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Docet {{longe}} alia ratione esse bellum gerendum atque antea gestum sit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"longinquitas","latin":"longinquitās, -ātis ( f.)","headword":"longinquitās","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"remoteness; distance, remoteness","forms":["longinquitāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Noster autem exercitus, tametsī urbem ex Tigrānis rēgnō cēperat et proeliīs ūsus erat secundīs, tamen nimiā {{longinquitāte}} locōrum ac dēsīderiō suōrum commovēbātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"longinquus","latin":"longinquus, -a, -um","headword":"longinquus","letter":"l","pos":"adjective","posGroup":"adjective","english":"remote; far off, distant","forms":["longinquam","longinquās","longinquioribus","longinquis","longinquum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex {{longinquioribus}} vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"longitudo","latin":"longitūdō, -inis ( f.)","headword":"longitūdō","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"length","forms":["longitūdine","longitudinem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Trabes directae perpetuae in {{longitudinem}} paribus intervallis distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"longule","latin":"longule","headword":"longule","letter":"l","pos":"adverb","posGroup":"adverb","english":"rather far, at a little distance","forms":["longulē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam rūs ut ībat forte, ut multum plūverat, ingressus fluvium rapidum ab urbe haud longulē, rapidus raptōrī puerī subdūxit pedēs abstrāxitque hominem in māximam mālam crucem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"longurius","latin":"longurius, longuri(i)","headword":"longurius","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"long pole","forms":["longurios"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Vercingetorix ex arce Alesiae suos conspicatus ex oppido egreditur, crates, {{longurios}}, musculos, falces reliquaque quae eruptionis causa paraverat profert.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"longus","latin":"longus, -a, -um","headword":"longus","letter":"l","pos":"adjective","posGroup":"adjective","english":"long","forms":["longa","longae","longam","longās","longī","longior","longiōra","longiōrem","longiōrēs","longīs","longissima","longissimam","longissime","longissimī","longissimus","longius","longō","longōs","longum","longus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne {{longius}} triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"loquax","latin":"loquax, (gen.), loquacis","headword":"loquax","letter":"l","pos":"adjective","posGroup":"adjective","english":"talkative, loquacious","forms":["loquācēs","loquāx"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"admoneō, veniat néē quis ad illa {{loquāx}}.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"loqui","latin":"loquī, -or, locūtus sum","headword":"loquī","letter":"l","pos":"verb","posGroup":"verb","english":"to speak, say; to speak; speak","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"loquitur","latin":"loquitur, loquī","headword":"loquitur","letter":"l","pos":"","posGroup":"other","english":"speak, talk","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"loquor","latin":"loquor, loqui, locutus sum","headword":"loquor","letter":"l","pos":"verb","posGroup":"verb","english":"speak, tell; talk; mention; say, utter; phrase","forms":["locūta","locūtī","locūtum","locūtus","loquantur","loquar","loquāris","loquātur","loquēbantur","loquēbātur","loquendī","loquēns","loquentem","loquentis","loquentium","loquentur","loquere","loquerentur","loquerer","loquerētur","loqueris","loquī","loquimur","loquitur","loquor","loquuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum Dōrippa {{loquitur}}, aperītur ōstium, atque Lȳdia cum Mēdō cubiculum intrat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lorica","latin":"lorica, loricae","headword":"lorica","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"coat of mail; breastwork, parapet, fortification","forms":["lōrīcā","loricam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Huic {{loricam}} pinnasque adiecit, grandibus cervis eminentibus ad commissuras pluteorum atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lorum","latin":"lorum, lori","headword":"lorum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"leather strap, thong; shoe strap; rawhide whip; dog leash; reins (usu. pl.)","forms":["lōra","lōrīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"“Sī potes hīs saltem monitīs pārēre parentīs, parce, puer, stimulīs et fortius ūtere {{lōrīs}}!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lotus","latin":"lotus, lota -um, lotior -or -us, lotissimus -a -um","headword":"lotus","letter":"l","pos":"adjective","posGroup":"adjective","english":"elegant, fashionable; sumptuous/luxurious; fine, well turned out; washed/clean","forms":["lōta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus, {{lōta}} faciē, regressus continuit sē, et iussit appōnī cibōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lubet","latin":"lubet, lubere, lubuit, lubitus est","headword":"lubet","letter":"l","pos":"verb","posGroup":"verb","english":"it pleases/is pleasing/agreeable; please/want/feel like; [w/qui => no matter]","forms":["lubet"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ita versipellem sē facit quandō {{lubet}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"luceo","latin":"luceo, lucere, luxi, -","headword":"luceo","letter":"l","pos":"verb","posGroup":"verb","english":"shine, emit light (heavenly body); dawn; cause to shine; be clear/evident","forms":["lūcēbant","lūcēbat","lūcēbit","lūcent","lūcente","lūcentem","lūcentēs","lūcentia","lūcērent","lūcet","lūxērunt","lūxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sōl {{lūcet}} in caelō sine nūbibus.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lucerna","latin":"lucerna, -ae","headword":"lucerna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lamp","forms":["lucernā","Lucernae","lucernās","Lucernis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Lucernas}} accendite, servi!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lucescit","latin":"lucescit, lucescere, luxit, -","headword":"lucescit","letter":"l","pos":"verb","posGroup":"verb","english":"it grows light, it is getting light, dawn is coming/breaking, day is breaking","forms":["Lūcēscit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{Lūcēscit}} hoc iam.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"lucesco","latin":"lucesco, lucescere, luxi, -","headword":"lucesco","letter":"l","pos":"verb","posGroup":"verb","english":"begin to shine; grow light (of the day), dawn; (usu. IMPERS)","forms":["lūcēscat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Tempus est: exīre ex urbe prius quam {{lūcēscat}} volō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"lucet","latin":"lūcet, -ent","headword":"lūcet","letter":"l","pos":"verb","posGroup":"verb","english":"shine; shines, is light","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"lucidus","latin":"lucidus, lucida, lucidum","headword":"lucidus","letter":"l","pos":"adjective","posGroup":"adjective","english":"bright, shining; clear","forms":["lūcide"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"vel prope té natō, {{lūcide}} Cydne, crocō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lucifer","latin":"Lucifer, Luciferi","headword":"Lucifer","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Lucifer, Satan","forms":["lūcifer"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lūcifer}} -ā -um 7 quī lūcem fert","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lucius","latin":"Lucius, Luci","headword":"Lucius","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Lucius (Roman praenomen); (abb. L.)","forms":["Lūciī","Lūciō","Lūcius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eī nōmen est '{{Lūcius}} Iūlius Balbus'.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"lucrum","latin":"lucrum, -ī","headword":"lucrum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"profit; profit, gain","forms":["lucra","lucrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ita spērābat sē magnum {{lucrum}} factūrum esse.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"luctari","latin":"(luctor) luctārī, luctātum","headword":"luctārī","letter":"l","pos":"","posGroup":"other","english":"wrestle","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"luctor","latin":"luctor, luctari, luctatus sum","headword":"luctor","letter":"l","pos":"verb","posGroup":"verb","english":"wrestle; struggle; fight (against)","forms":["luctandō","luctantēs","luctārī","luctātur","luctēmur","luctor"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tertius et quārtus ex fīliīs, postquam operī cotīdiānō fīnem imposuerant, in palaestram īverant, ut validiōra corpons membra facerent: cum vērō iam alter alterum luctandō complecterētur, ūnā sagittā eōs ita iūnctōs trānsfīxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"luctuosus","latin":"luctuosus, luctuosa, luctuosum","headword":"luctuosus","letter":"l","pos":"adjective","posGroup":"adjective","english":"mournful; grievous","forms":["lūctuōsam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod sī virtūtī vestrae fortūna invīderit, cavēte inultī animam āmittātis neu captī potius sīcuti pecora trucīdēminī quam virōrum mōre pugnantēs cruentam atque {{lūctuōsam}} victōriam hostibus relinquātis!”","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"luctus","latin":"lūctus, -ūs","headword":"lūctus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"grief, moaning; grief, mourning","forms":["lūctū","lūctum","lūctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Per septem diēs Dāvīd in magnō lūctū fuit, cibō abstinēns et ōrāns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"luculentus","latin":"luculentus, luculenta, luculentum","headword":"luculentus","letter":"l","pos":"adjective","posGroup":"adjective","english":"shining, bright, brilliant, splendid","forms":["lūculentam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tullius cōnsul, sīve praesentiam eius timēns sīve īrā commōtus, ōrātiōnem habuit {{lūculentam}} atque ūtilem reī pūblicae, quam posteā scrīptam ēdidit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"lucumo","latin":"lucumo, lucumonis","headword":"lucumo","letter":"l","pos":"noun","posGroup":"noun","english":"one possessed; an Etrurian","forms":["Lucumō","Lucumōnem","Lucumōnī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ancō rēgnante Lucumō, vir impiger ac dīvitiīs potēns, cum omnibus bonīs suīs Tarquiniīs ex oppidō Etrūriae Rōmam commigrāvit, cupīdine maximē ac spē magnī honōris, quem Tarquiniīs — nam ibi quoque peregrīnus erat — adipīscī nōn potuerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lucus","latin":"lūcus, -ī","headword":"lūcus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"sacred grove","forms":["luce","Lūcī","lūcis","lūcō","lūcōs","lūcum","Lūcus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prima {{luce}} magnum numerum impedimentorum ex castris mulorumque produci deque his stramenta detrahi mulionesque cum cassidibus equitum specie ac simulatione collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ludibrium","latin":"lūdibrium, -ī","headword":"lūdibrium","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"mockery, derision, sport; mockery, laughing-stock","forms":["lūdibriō","lūdibrium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Illī, effossīs oculīs, vīnctum in carcerem coniēcērunt, diūque lūdibriō habuērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ludicrum","latin":"lūdicrum, -ī","headword":"lūdicrum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"sport, toy, show","forms":["lūdicrō","lūdicrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Turbātō per metum lūdicrō, maestī parentēs virginum profugiunt Rōmānōs \"perfidōs hospitēs\" inclāmantēs deumque Neptūnum invocantēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ludicrus","latin":"ludicrus, ludicra, ludicrum","headword":"ludicrus","letter":"l","pos":"adjective","posGroup":"adjective","english":"connected with sport or the stage","forms":["lūdicram"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam et artificum omnis generis quī {{lūdicram}} artem faciēbant ex tōtō orbe terrārum multitūdō et athlētārum et nōbilium equōrum convēnit et lēgātiōnēs cum victimīs, et quidquid aliud deōrum hominumque causā fierī magnīs lūdīs in Graeciā solet ita factum est ut nōn magnificentiam tantum sed prūdentiam in dandīs spectāculīs, ad quae rudēs tum Rōmānī erant, admīrārentur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ludifico","latin":"ludifico, ludificare, ludificavi, ludificatus","headword":"ludifico","letter":"l","pos":"verb","posGroup":"verb","english":"make fun/sport of, treat as a plaything; trifle with","forms":["lūdificābit","lūdificant","lūdificārī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"AMPHITRYO: Tūn' mē, verberō, audēs erum lūdificārī?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"ludit","latin":"lūdit, lūdere","headword":"lūdit","letter":"l","pos":"verb","posGroup":"verb","english":"play; plays","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ludius","latin":"ludius, ludi(i)","headword":"ludius","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"dancer; stage performer","forms":["lūdius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{lūdius}} -ī;1 ^ quī saltat in theātrō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ludo","latin":"ludo, ludere, lusi, lusus","headword":"ludo","letter":"l","pos":"verb","posGroup":"verb","english":"play, mock, tease, trick","forms":["Lūdāmus","lūdēbat","lūdendō","lūdēns","lūdentem","lūdentēs","lūdentibus","lūdere","lūderet","lūdet","lūdit","lūdite","lūditur","lūdō","lūdunt","lūsērunt","lūsī","lūsisse","lūsit","lūsū","lūsum","lūsus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlia: “Sī magistrum rīdētis atque in lūdō dormītis, rēctē reprehendiminī et verberāminī, neque enim in lūdō dormīre licet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ludus","latin":"lūdus, -ī","headword":"lūdus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"play, game, school; school; game, play; game, school; school, game; game","forms":["lūdī","ludis","ludos","lūdum","lūdus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In viā ante {{lūdum}} Sextus Mārcum interrogat: “Ubi est is servus quī solet tē hīc exspectāre?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lues","latin":"lues, luis","headword":"lues","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"plague, pestilence; scourge, affliction","forms":["luēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sī rēctē faciēs, recipiēs mercēdem; sīn autem male, {{luēs}} poenam peccātī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lugeo","latin":"lugeo, lugere, luxi, luctus","headword":"lugeo","letter":"l","pos":"verb","posGroup":"verb","english":"mourn, grieve (over); bewail, lament; be in mourning","forms":["lūgeam","lūgēbat","lūgēbit","lūgentibus","lūgentium","lugere","luget","Lugete"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tunc, lūctū dēpositō, iussit sibi appōnī cibōs, mīrantibusque aulicīs dīxit: “Aegrōtante puerulō ieiūnus ōrābam, spērāns scīlicet Deum plācārī posse; nunc autem, cum mortuus sit, cūr frūstrā {{lūgeam}}?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lugere","latin":"(lūgeō) lūgēre, lūxisse","headword":"lūgēre","letter":"l","pos":"verb","posGroup":"verb","english":"mourn; to mourn; to mourn, grieve","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"lugubris","latin":"lūgubris, -e","headword":"lūgubris","letter":"l","pos":"adjective","posGroup":"adjective","english":"sad, grievous","forms":["lūgubrem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nāvēs prōvectās in altum incendī iussit; quīngentās fuisse omnis generis quae rēmīs agerentur quīdam trādunt, quārum cōnspectum repentīnum incendium 'tam {{lūgubrem}} fuisse Poenīs quam sī ipsa Carthāgō ārderet.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lumen","latin":"lūmen, -inis (n.)","headword":"lūmen","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"light; eye","forms":["lūmen","lūmina","lūmine","lūminibus","lūminis","lūminum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{lūmina}} mors clausit dominī mīrantia fōrmam: tum quoque sē, postquam est mfemā sēde receptus, in Stygiā spectābat aquā.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"luna","latin":"lūna, -ae","headword":"lūna","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"moon","forms":["lūna","lūnae","lūnam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aemilia: “Hāc nocte hortus obscūrus nōn est, nam {{lūna}} et stēllae lūcent.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"lunaris","latin":"lūnāris, -e (< luna, l.13)","headword":"lūnāris","letter":"l","pos":"adjective","posGroup":"adjective","english":"of the moon, lunar","forms":["lūnāris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob causam summus ille caelī stellifer cursus, cuius conversiō est concitātior, acūtō et excitātō movētur sonō, gravissimō autem hic {{lūnāris}} atque īnfimus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"luno","latin":"luno, lunare, lunavi, lunatus","headword":"luno","letter":"l","pos":"verb","posGroup":"verb","english":"make crescent-shaped, curve","forms":["lūnātīs","lunō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque cotldiē, cum sōl altissimus erat, silvās petēbant in quibus Iuppiter puellae fābulās nārrābat atque lō ipsā canēbat. lunō autem, rēgīna deōrum atque hominum, postquam hoc animadvertit neque marītum in caelō repperit, ad terram dēscendit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"luo","latin":"luo, luere, lui, lutus","headword":"luo","letter":"l","pos":"verb","posGroup":"verb","english":"pay; pay fine, compensate/atone; [poenam ~ => suffer punishment as expiation]","forms":["luere","luētis","luī","luimus","luit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tunc coepērunt inter sē dīcere: meritō haec patimur; crūdēlēs fuimus in frātrem nostrum; nunc poenam huius sceleris {{luimus}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lupa","latin":"lupa, -ae","headword":"lupa","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"she-wolf","forms":["lupa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"lupus -ī 7ī, {{lupa}} -ae f.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lupus","latin":"lupus, -ī","headword":"lupus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"wolf","forms":["lupe","lupī","lupīs","lupō","lupōs","lupum","lupus","LVPO","LVPVS"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Canis ille parvus tam malus est quam {{lupus}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"luridus","latin":"luridus, lurida, luridum","headword":"luridus","letter":"l","pos":"adjective","posGroup":"adjective","english":"sallow, wan, ghastly","forms":["lūridus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mors erat ante oculōs, mē {{lūridus}} occupat horror.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"luscinia","latin":"luscinia, lusciniae","headword":"luscinia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"nightingale","forms":["lusciniās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Interim puer Alexandrînus, quī caldam ministrābat, {{lusciniās}} coepit imitärî, clāmante Trimalchiône subinde: Ecce alius lūdus: servus quī ad pedēs Habinnae sēdë- bat, iussus, crëdô, ā dominô suô, prôclämävit subitô Nūllus sonus umquam acidior percussit aurēs meâs, tunc prîmum mē etiam Vergilius offenderit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lusor","latin":"lusor, lusoris","headword":"lusor","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"player; tease; one who treats (of a subject) lightly","forms":["lūsor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sīc {{lūsor}}, né pecūniam perdat, nōn","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lustrare","latin":"(lūstrō) lūstrāre","headword":"lūstrāre","letter":"l","pos":"","posGroup":"other","english":"irradiate, purify, survey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"lustro","latin":"lūstrō (1)","headword":"lūstrō","letter":"l","pos":"verb","posGroup":"verb","english":"to purify, cleanse","forms":["lūstrābat","lūstrābunt","lūstrāre","lūstrās","lūstrat","lūstrātum","lūstrāvisset","lūstrāvit","lūstret","lūstrō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Atque utinam rēx ipse Notō compulsus eōdem\nadforet Aenēās: equidem per lītora certōs\ndīmittam et Libyae {{lūstrāre}} extrēma iubēbō,\nsī quibus ēiectus silvīs aut urbibus errat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"lustrum","latin":"lūstrum, -ī","headword":"lūstrum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"ceremony of purification; purification; five-year period","forms":["lustra","lūstrīs","lustrum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"est pia Pēnelope {{lūstrīs}} errante","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lutetia","latin":"Lutetia, Lutetiae","headword":"Lutetia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Paris; (city in Gaul/France)","forms":["Lutetia","Lutetiae","Lutetiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Dum haec apud Caesarem geruntur, Labienus eo supplemento, quod nuper ex Italia venerat, relicto Agedinci, ut esset impedimentis praesidio, cum IIII legionibus {{Lutetiam}} proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"lutum","latin":"lutum, luti","headword":"lutum","letter":"l","pos":"noun (n.)","posGroup":"noun","english":"mud, dirt, clay; (for modelling/building); [pro ~ => common as dirt]","forms":["lutum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Exspuit ergō Iēsus in terram, et recit {{lutum}} ex spūtō et līnīvit oculōs eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"lux","latin":"lūx, lūcis","headword":"lūx","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"(f.) light, daylight; light; light, day","forms":["lucem","Lūcium","lux"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Uno fere tempore sub {{lucem}} hostibus nuntiatur in castris Romanorum praeter consuetudinem tumultuari et magnum ire agmen adverso flumine sonitumque remorum in eadem parte exaudiri et paulo infra milites navibus transportari.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"luxuria","latin":"luxuria, -ae","headword":"luxuria","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"extravagance, luxury","forms":["luxuria","luxuriae","luxuriam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Incitābant praetereā corruptī cīvitātis mōrēs, quōs pessima ac dīversa inter sē mala, {{luxuria}} atque avāritia, vexābant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"luxuriari","latin":"(luxurior) luxuriārī","headword":"luxuriārī","letter":"l","pos":"","posGroup":"other","english":"revel, live in luxury","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"luxurio","latin":"luxurio, luxuriare, luxuriavi, luxuriatus","headword":"luxurio","letter":"l","pos":"verb","posGroup":"verb","english":"grow luxuriantly/rank; luxuriate; frisk/gambol; revel/run riot; indulge oneself","forms":["luxuriābit","luxuriant","luxuriāre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"360 utsēgēs in pinguī {{luxuriābit}} humō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"luxuriosus","latin":"luxuriosus, luxuriosa, luxuriosum","headword":"luxuriosus","letter":"l","pos":"adjective","posGroup":"adjective","english":"luxuriant, exuberant; immoderate; wanton, luxurious, self-indulgent","forms":["luxuriōsa","luxuriōsē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nē nimium {{luxuriōsa}} siet!...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"luxus","latin":"luxus, -ūs","headword":"luxus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"extravagance, luxury; luxury, excess","forms":["luxū","luxuī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Immô etiam pullārius erat - omnīs mortuum plangere/plôräre : plangere/plôräre dē mortuô (servum) macū (: ê potestāte minimus, quārta pars assis solidus -ā -um 4-) liquidus; sēcum in sepulcrum tulisse que pretiurrx; quid ā. mordeat Sâturnälia agere : in luxū leô : vir fortis ac ferôx rēctus, certus: probus, ﬁdusﬁdt micāre: lūdere digitîs extentîs spūtum (-î n) ex ôre êmittere pānem quem asse ëmissês...","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"lyaeus","latin":"Lyaeus, Lyaei","headword":"Lyaeus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"Lyaeus; (epithet of Bacchus/Dionysus as the liberator)","forms":["Lyaeō","Lyaeum","Lyaeus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Lyaeus}} -im- Bacchus; vīnum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"lychnus","latin":"lychnus, lychni","headword":"lychnus","letter":"l","pos":"noun (m.)","posGroup":"noun","english":"lamp (esp. one hung from the ceiling)","forms":["lychnī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ātria; dēpendent lychnī laqueāribus aureīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"lycia","latin":"Lycia, Lyciae","headword":"Lycia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lycia; (region in Asia Minor, sacred to Apollo)","forms":["Lyciae","Lyciam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Is Cīliciam subēgit, {{Lyciae}} urbēs clārissimās oppugnāvit et cēpit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"lydia","latin":"Lydia, -ae","headword":"Lydia","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"Lydia (a country in Asia Minor)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"lympha","latin":"lympha, lymphae","headword":"lympha","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"water; water-nymph","forms":["lymphārum","lymphās","lymphīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cupit ipse tenērī: nam quotiēs liquidīs porrēximus ōscula {{lymphīs}}, hīc totiēs ad mē resupīnō nītitur ōre.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"lynx","latin":"lynx, lyncis","headword":"lynx","letter":"l","pos":"noun","posGroup":"noun","english":"lynx; lynx skin/pelt; fictitious tree (invented to explain lyncurium/ligure)","forms":["lyncis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"succīnctam pharetrā et maculōsae tegmine {{lyncis}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"lyra","latin":"lyra, -ae","headword":"lyra","letter":"l","pos":"noun (f.)","posGroup":"noun","english":"lyre","forms":["lyrā","lyrae","lyram"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Attamen, cum dī sōlī mānsissent, Apollō, lyrā suā canēns, effēcit ut saxa ipsa per sē movērentur ad mūrōs aedificandōs; Neptūnus vērō eadem saxa, vīcīnī maris flūctibus tergendō, quasi aurum lūcentia fēcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"macedo","latin":"Macedo, Macedonis","headword":"Macedo","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Macedonian, one from Macedonia; Macedonia, the territory; men Macedonian armed","forms":["Macedone","Macedonēs","Macedonum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eō annō etiam Alexandrīa ab Alexandrō {{Macedone}} condita est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"macedonia","latin":"Macedonia, Macedoniae","headword":"Macedonia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Macedonia","forms":["Macedoniā","Macedoniae","Macedoniam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Athos -ī71, mōns {{Macedoniae}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"macedonicus","latin":"Macedonicus, Macedonica, Macedonicum","headword":"Macedonicus","letter":"m","pos":"adjective","posGroup":"adjective","english":"Macedonian, of/from/belonging to Macedonia","forms":["Macedonicō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Bellō Macedonicō, quod cum rēge Persē gessimus, Rhodiōrum cīvitās magna atque magnifica, quae populī Rōmānī opibus crēverat, īnfīda atque adversa nōbīs fuit; sed postquam bellō cōnfectō dē Rhodiīs cōnsultum est, maiōrēs nostrī, nē quis dīvitiārum magis quam iniūriae causa bellum inceptum dīceret, impūnītōs eōs dīmīsēre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"macellum","latin":"macellum, macelli","headword":"macellum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"provision-market","forms":["macellum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Domī sum.” [Iūlius:] “Sīc fīat nōbīs.” [Gāius domum pergit.] [Iūlius, ad servum suum:] “Tū, puer, sequere mē ad {{macellum}}!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"macer","latin":"macer, macra -um, macrior -or -us, macerrimus -a -um","headword":"macer","letter":"m","pos":"adjective","posGroup":"adjective","english":"thin (men, animals, plants), scraggy, lean, small, meager; thin (soil), poor","forms":["MACRO"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"DE LVPO {{MACRO}} ET CANE PERPASTO","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"maceria","latin":"māceria, -ae","headword":"māceria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"brick or stone wall, garden wall; garden wall","forms":["maceriam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sub muro, quae pars collis ad orientem solem spectabat, hunc omnem locum copiae Gallorum compleverant fossamque et {{maceriam}} sex in altitudinem pedum praeduxerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"machina","latin":"māchina, -ae","headword":"māchina","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"machine; machine, engine","forms":["māchina","māchinīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aut hōc inclūsī lignō occultantur Achīvī,\naut haec in nostrōs fābricāta est {{māchina}} mūrōs\nīnspectūra domōs ventūraque dēsuper urbī,\naut aliquis latet error: equō nē crēdite, Teucrī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"machinari","latin":"(māchinōr) māchinārī","headword":"māchinārī","letter":"m","pos":"verb","posGroup":"verb","english":"devise, plot; to contrive, plot","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"machinator","latin":"machinator, machinatoris","headword":"machinator","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"engineer, one who devises/constructs machines; contriver of plots/events","forms":["māchinātōrem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque hōrum omnium scelerum improbissimum {{māchinātōrem}}, Cimbrum Gabīnium, statim ad mē nihildum suspicantem vocāvī, deinde item accersītus est L.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"machinor","latin":"machinor, machinari, machinatus sum","headword":"machinor","letter":"m","pos":"verb","posGroup":"verb","english":"devise; plot","forms":["māchinābantur","māchināris","māchinātur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quam rem Tarquinius aegrē ferēns cōnfestim Turnō necem {{māchinātur}}, ut eundem terrōrem quō cīvium animōs domī oppresserat Latīnīs iniceret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"macies","latin":"macies, maciei","headword":"macies","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"leanness, meagerness; poverty","forms":["maciē","maciem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"sit 'gracilis!' maciē quae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"macilentus","latin":"macilentus, macilenta -um, macilentior -or -us, macilentissimus -a -um","headword":"macilentus","letter":"m","pos":"adjective","posGroup":"adjective","english":"thin, lean; meager (L+S)","forms":["macilentae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deinde septem aliae vaccae {{macilentae}} exiērunt ex eōdem flūmine, quae dēvorārunt priōrēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"macte","latin":"macte (virtūte estō)","headword":"macte","letter":"m","pos":"","posGroup":"other","english":"well done!","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"macto","latin":"mactō, -āre, mactāvī, mactātum","headword":"mactō","letter":"m","pos":"verb","posGroup":"verb","english":"sacrifice, slay","forms":["mactābis","mactant","mactāre","mactārī","mactāta"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ut dolor ūnius Danaōs pervēnit ad omnēs, exspectāta diū, nūlla aut contrāria classī flāmina erant, dūraeque iubent Agamemnona sortēs immeritam saevae nātam {{mactāre}} Diānae.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mactus","latin":"mactus, macta, mactum","headword":"mactus","letter":"m","pos":"adjective","posGroup":"adjective","english":"of the Gods, worshiped, honored","forms":["macte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Angelus adstitit Gedeōnī: “Dominus tēcum” inquit “vir fortissimē.” Respondit Gedeōn: “Sī Deus nōbīscum est, cūr dūra premimur servitūte?” Ait angelus: “Mactē animō!","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"macula","latin":"macula, -ae","headword":"macula","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"stain, blemish; stain, blot; disgrace","forms":["maculam","maculīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc patemī in IŪdaeōs odiī hērēs, contrā eōs mīsit Lisiam, quī iam semel victus ā Ilīdā, hanc {{maculam}} cupiēbat ēluere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maculare","latin":"(maculō) maculāre","headword":"maculāre","letter":"m","pos":"","posGroup":"other","english":"stain, defile","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"maculo","latin":"maculo, maculare, maculavi, maculatus","headword":"maculo","letter":"m","pos":"verb","posGroup":"verb","english":"spot; pollute; dishonor, taint","forms":["maculātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Nam rēx ille dē quō loquor prīmum optimī rēgis caede {{maculātus}} integram mentem nōn erat, et, cum metueret ipse poenam sceleris suī summam, metuī sē volēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maculosus","latin":"maculosus, maculosa, maculosum","headword":"maculosus","letter":"m","pos":"adjective","posGroup":"adjective","english":"spotted; disreputable","forms":["maculōsae"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"succīnctam pharetrā et {{maculōsae}} tegmine lyncis,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"madefactus","latin":"madefactus, madefacta, madefactum","headword":"madefactus","letter":"m","pos":"adjective","posGroup":"adjective","english":"wet, soaked, stained","forms":["madefactā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"765 Turpe iacēns mulier multō madefactā Lyaeō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"madeo","latin":"madeo, madere, madui, -","headword":"madeo","letter":"m","pos":"verb","posGroup":"verb","english":"be wet (w/tears/perspiration), be dripping/sodden","forms":["madent","madentem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"520 quae patimur multō spīcula felle {{madent}}.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"madianitis","latin":"Madianitis, Madianitos/is","headword":"Madianitis","letter":"m","pos":"noun","posGroup":"noun","english":"Madianite/Midianite, person from Madian/Midian","forms":["Madianitīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Hebraeī ā {{Madianitīs}} vexātī opem ā Deō petīvērunt: Deus illōrum precēs audīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"madidus","latin":"madidus, madida, madidum","headword":"madidus","letter":"m","pos":"adjective","posGroup":"adjective","english":"wet, moist; dripping, juicy; sodden, drenched; drunk, tipsy; steeped in","forms":["madidā","madidās","madidus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ut levis in madidā canna palūde tremit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"maenas","latin":"Maenas, -adis","headword":"Maenas","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"a Bacchante, a maddened woman, a Maenad","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"maeonia","latin":"Maeonia, Maeoniae","headword":"Maeonia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Maeonia; (ancient name for Lydia in Asia Minor)","forms":["Maeoniā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Maeoniā mentum mitrā crīnemque madentem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"maerens","latin":"maerens, (gen.), maerentis","headword":"maerens","letter":"m","pos":"adjective","posGroup":"adjective","english":"sad, melancholy; mournful, gloomy woeful, doleful; mourning, lamenting (L+S)","forms":["maerēns","maerentem","maerentēs","maerentia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Inambulābat in cēnāculō {{maerēns}}, et in hās vōcēs identidem ērumpēns: “Fīlī mī Absalōn, Absalōn fīlī mī: utinam prō tē moriar, Absalōn fīlī mī, fīlī mī Absalōn.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maereo","latin":"maereo, maerere, -, -","headword":"maereo","letter":"m","pos":"verb","posGroup":"verb","english":"grieve, be sad, mourn; bewail/mourn for/lament; utter mournfully","forms":["maereat","maerēbant","maerēbat","maerent","maereō","maeret"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam servus tubā signum proficīscendī dedit, omnēs celeriter currere coepērunt: ante omnēs, sagitta celerior, currēbat Atalanta; cēterī vērō, cōnātī eam cōnsequī atque per longum spatium secūtī, tandem ita currendō fessī fuērunt, ut alius post alium cōnsisterent et vīctōs sē esse fatērentur: ex iīs complūrēs multīs cum lacrimīs {{maerēbant}}; nam sciēbant sē ad certam mortem missum īrī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"maerere","latin":"(maereō) maerēre","headword":"maerēre","letter":"m","pos":"","posGroup":"other","english":"grieve","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"maeret","latin":"maeret","headword":"maeret","letter":"m","pos":"verb","posGroup":"verb","english":"grieves, mourns","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"maeror","latin":"maeror, -ōris (m.)","headword":"maeror","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"grief","forms":["maeror","maerōre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam cams populō fuerit, {{maerōre}} filneris indicātum est: suī eum cīvēs diū liīxērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maestitia","latin":"maestitia, -ae","headword":"maestitia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"sadness, sorrow","forms":["maestitiā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae ubi intrāvēre portās, nōn quidem fuit tumultus ille nec pavor quālis captārum esse urbium solet, cum effrāctīs portīs strātīsve mūris aut arce vī captā clāmor hostīlis et cursus per urbem armātōrum omnia ferrō flammāque miscet, sed silentium trīste ac tacitā maestitiā ita dēfīxit omnium animōs ut nunc cūnctantēs in līminibus stārent, nunc per domōs suās, quās tum postrēmum vīdērunt, vagārentur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maesto","latin":"maesto, maestare, maestavi, maestatus","headword":"maesto","letter":"m","pos":"verb","posGroup":"verb","english":"grieve, make sad; afflict (L+S)","forms":["maestō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Dea territa et mātrem et comitēs (sed mātrem saepius) ōre maestō clāmat, et quod vestīmentum laniātur, collēctī flōrēs, tunicā remissā, cecidērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"maestus","latin":"maestus, -a, -um","headword":"maestus","letter":"m","pos":"adjective","posGroup":"adjective","english":"sad; sad, sorrowful; sad, gloomy","forms":["maesta","maestae","maestam","maesti","maestissima","maestissimae","maestissimē","maestissimō","maestissimum","maestissimus","maestōrum","maestōs","maestum","maestus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At ei qui ab Alesia processerant {{maesti}} prope victoria desperata se in oppidum receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maga","latin":"maga, -ae","headword":"maga","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"witch, sorceress","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"magicus","latin":"magicus, -a, -um","headword":"magicus","letter":"m","pos":"adjective","posGroup":"adjective","english":"magic","forms":["magica","magicae","magicās","magicīs","magicum","magicus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Medea nunc ad ārās antīquās Hecatēs īvit ut in silvā carmina sēcrēta et artēs {{magicās}} disceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"magis","latin":"magis","headword":"magis","letter":"m","pos":"adverb","posGroup":"adverb","english":"more","forms":["magis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Proinde agmine impeditos adoriantur; si pedites suis auxilium ferant atque in eo morentur, iter facere non posse; si, id quod {{magis}} futurum confidat, relictis impedimentis suae saluti consulant, et usu rerum necessariarum et dignitate spoliatum iri.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"magister","latin":"magister, magistrī","headword":"magister","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"schoolmaster, teacher; teacher, master; teacher (male)","forms":["magister","magistrī","magistrīs","magistrō","magistrōs","magistrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iūlia Mārcum interrogat: “Quid vōs discitis apud {{magistrum}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"magistra","latin":"magistra, -ae","headword":"magistra","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"teacher (female)","forms":["magistra","magistram"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Omnēs dē lēctābantur cum eam acū vestēs pingentem spectārent, eamque ūnō ōre laudābant dīcentēs ‘Minervam ipsam eius fuisse {{magistram}}’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"magistratus","latin":"magistrātus, -ūs","headword":"magistrātus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"office, magistrate","forms":["magistratibus","magistrātū","magistrātuī","magistratum","magistratus","magistratuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem {{magistratum}} gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"magnanimus","latin":"magnanimus, -a, -um","headword":"magnanimus","letter":"m","pos":"adjective","posGroup":"adjective","english":"great-hearted, noble","forms":["magnanimī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Pāruit Aenēās et formīdābilis Orcī\nvīdit opēs ātavōsque suōs umbramque senīlem\nmagnanimī Anchīsae; didicit quoque iūra locōrum,\nquaeque novīs essent adeunda perīcula bellīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"magnas","latin":"magnas, magnatis","headword":"magnas","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"great man; important person; magnate; vassal (Z); tenant-in-chief; baron","forms":["magnās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus verbīs audītis, Iuppiter, deōrum omnium rēx, agricolās illōs prāvōs in {{magnās}} rānās convertit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"magnes","latin":"magnes, magnetis","headword":"magnes","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"magnet, lodestone; inhabitants of Magnesia (pl.)","forms":["Magnēs","Magnētas"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quīnctius imperātor, Philippō rēge Macedonibusque dēvictīs, līberōs, immunēs, suīs lēgibus esse iubet Corinthiōs, Phocēnsēs, Locrensēsque omnēs et īnsulam Euboeam et {{Magnētas}}, Thessalōs, Perrhaebōs, Achaeōs Phthīōtās.' Percēnsuerat omnēs gentēs quae sub diciōne Philippī rēgis fuerant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"magnesium","latin":"magnesium, magnesii","headword":"magnesium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"magnesium","forms":["Magnēsia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ante saltum Thermopylārum in septentriōnem versa Ēpīrus et Perrhaebia et {{Magnēsia}} et Thessalia est et Phthīōtae Achaeī et sinus Maliacus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"magnifice","latin":"magnifice, magnificentius, magnificentissime","headword":"magnifice","letter":"m","pos":"adverb","posGroup":"adverb","english":"splendidly, in fine/lordly manner/language; superbly; proudly/boastfully","forms":["magnificē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Is filnus frātris magnificē cfuāvit, nec diū rēgnāvit; nam et ipse generī suī fraude periit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"magnificentia","latin":"magnificentia, -ae","headword":"magnificentia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"magnificence","forms":["magnificentia","magnificentiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ardeam Rutulī habēbant, gens — ut in eā regiōne et in eā aetāte — dīvitiīs praepotēns; eaque ipsa causa bellī fuit, quod rēx Rōmānus cum ipse dītārī volēbat (exhaustō aerāriō {{magnificentia}} pūblicōrum operum), tum praedā lēnīre populārium animōs studēbat, quī sē in servilī opere tam diū habitōs ab rēge indignābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"magnificus","latin":"magnificus, -a, -um","headword":"magnificus","letter":"m","pos":"adjective","posGroup":"adjective","english":"magnificent; magnificent, splendid","forms":["magnifica","magnificae","magnificam","magnificās","magnificentiorēs","magnificentissima","magnificentius","magnificīs","magnificōs","magnificum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Sciō multās domōs Tūsculānās et māiōrēs et meliōrēs esse quam nostram atque columnīs et signīs pulchriōribus ōrnārī, nec tamen haec domus mihi vidētur minus pulchra esse. rēs pulchra (esse) Domūs hominum dīvitum signīs deārum {{magnificīs}} ōrnantur — domus mea fēminā ōrnātur optimā et pulcherrimā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"magnitudo","latin":"magnitūdō, -inis ( f.)","headword":"magnitūdō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"size, greatness; greatness, size","forms":["magnitudine","magnitudinem","magnitūdinēs","magnitūdinis","magnitūdō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summae diligentiae summam imperi severitatem addit; {{magnitudine}} supplici dubitantes cogit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"magnopere","latin":"magnopere","headword":"magnopere","letter":"m","pos":"adverb","posGroup":"adverb","english":"very greatly","forms":["magnopere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Is cum animadvertisset perpetuam esse paludem quae influeret in Sequanam atque illum omnem locum {{magnopere}} impediret, hic consedit nostrosque transitu prohibere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"magnus","latin":"magnus, -a, -um","headword":"magnus","letter":"m","pos":"adjective","posGroup":"adjective","english":"big, large, great; big, great, large; big, great; large, great","forms":["magna","magnae","magnam","magne","magnī","magnis","magno","magnōrum","magnōs","magnum","magnus","maiōra","maximā","maximae","maximam","maximārum","maximās","maximi","maximis","māximō","maximōs","maximum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eo cum venisset, {{magna}} difficultate adficiebatur, qua ratione ad exercitum pervenire posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"magus","latin":"magus, magi","headword":"magus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"wise/learned man; magician (Persian); astrologer","forms":["maga","magī","Māgō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum nātus esset Iēsus m cīvitāte Bēthlehem, magī ab Oriente vēnērunt Hierosolymam ut eum adōrārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maiestas","latin":"majestas, majestatis","headword":"majestas","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"majesty, dignity (of god/rank/position); majesty of people/state; sovereignty","forms":["maiestās","maiestate","māiestātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani {{maiestate}} et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maior","latin":"māior, māius","headword":"māior","letter":"m","pos":"adjective","posGroup":"adjective","english":"larger, greater; greater, bigger; greater","forms":["maior","maiore","maiorem","maiores","maioribus","maiōris","maiōrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postremo in acie praestare interfici quam non veterem belli gloriam libertatemque quam a {{maioribus}} acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maiores","latin":"māiōrēs, -um (m. pl.)","headword":"māiōrēs","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"ancestors","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"maius","latin":"Maius, Maia, Maium","headword":"Maius","letter":"m","pos":"adjective","posGroup":"adjective","english":"May (month/mensis understood); abb. Mai.","forms":["Maī","Maiās","Maiī","Maiīs","Maiō","Maium","maius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"...et quid Iove {{maius}} habēmus?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mala","latin":"mala, malae","headword":"mala","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"cheeks, jaws","forms":["mala"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec omnia {{mala}} in mē recīdunt; nōn dīmittam Beniamīnum; nam sī quid eī adversī acciderit in viā, nōn poterō eī superstes vīvere; sed dolōre oppressūs moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"male","latin":"male","headword":"male","letter":"m","pos":"adverb","posGroup":"adverb","english":"badly, ill; badly","forms":["male"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mīles: “Nōn {{male}} dolet...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"maledicere","latin":"(maledīcō) maledīcere (< dīcere)","headword":"maledīcere","letter":"m","pos":"","posGroup":"other","english":"abuse, insult","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"maledico","latin":"maledico, maledicere, maledixi, maledictus","headword":"maledico","letter":"m","pos":"verb","posGroup":"verb","english":"speak ill/evil of, revile, slander; abuse, curse","forms":["maledīcere","maledīcerent","maledīcit","maledīxērunt","maledīxī","maledīximus","maledīxistī","maledīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At Dāvīd eōs cohibuit: “Sinite” inquit “istum mihi {{maledīcere}}; forsitan Deus, hīs quae patior malīs plācātus, meī miserēbitur, et meum dolōrem respiciet.” Incrēdibilem rēgis patientiam admīrātī, comitēs dictō aegrē pāruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maledictum","latin":"maledictum, maledicti","headword":"maledictum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"insult, reproach, taunt","forms":["maledicta","maledictīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Fugientī occurrit vir quīdam ē genere Saūlis, nōmine Semēī, quī coepit Davidem eiusque comitēs {{maledictīs}} et lapidibus appetere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maledicus","latin":"maledicus, maledica, maledicum","headword":"maledicus","letter":"m","pos":"adjective","posGroup":"adjective","english":"slanderous; abusive; scurrilous; evil-speaking; (of persons/remarks)","forms":["maledīcās","maledicī","Maledīcis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quod illī indignē ferentēs volēbant ulcīscī iniūriam, et maledicī convīciātōris caput amputāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"malefacio","latin":"malefacio, malefacere, malefeci, malefactus","headword":"malefacio","letter":"m","pos":"verb","posGroup":"verb","english":"do evil/wrong/harm/injury/mischief; act wickedly","forms":["malefēcimus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Spērātus dīxit: “Numquam {{malefēcimus}}, iniquitātī nūllam operam praebuimus; numquam maledīximus, sed male acceptī grātiās ēgimus, proptereā quod Imperātōrem nostrum observāmus.” Saturnīnus prōcōnsul dīxit: “Et nōs religiōsī sumus, et simplex est religiō nostra, et iūrāmus per genium dominī nostrī Imperātōris et prō salūte eius supplicāmus — quod et vōs quoque facere dēbētis.”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"maleficio","latin":"maleficio, maleficere, -, -","headword":"maleficio","letter":"m","pos":"verb","posGroup":"verb","english":"practice sorcery/black magic","forms":["maleficiō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tanta tamen erat cupiditās īnspiciendī, ut sē ā maleficiō retinēre nōn posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"maleficium","latin":"maleficium, -ī","headword":"maleficium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"evil deed; wicked deed, crime","forms":["maleficia","maleficiīs","maleficium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōn sōlum nūllum ā mē {{maleficium}} patiēris, sed etiam rēgnābis mēcum apud Īnferōs, neque misera erit vīta tua: ego enim tē tam multum amō, ut tantum laetitia animum tuum afficere cupiam.” Hīs verbīs Plūtō perterritam virginem cōnsōlātus est; agēns deinde currum, equīs celeriter currentibus, ad locum pervēnit, ubi terrā, scēptrō percussa, sē aperuit ut iīs viam ad Īnferōs faceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"malevolentia","latin":"malevolentia, malevolentiae","headword":"malevolentia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"ill-will/spite/malice; malevolence; dislike/hatred/envy (L+S); evil disposition","forms":["malevolentiā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ac mihi quidem, tametsī haudquāquam pār glōria sequitur scrīptōrem et āctōrem rērum, tamen in prīmīs arduum vidētur rēs gestās scrībere: prīmum quod factīs dicta exaequanda sunt; dehinc quia plērīque, quae dēlicta reprehenderīs, malevolentiā et invidiā dicta putant; ubi dē magnā virtūte atque glōriā bonōrum memorēs, quae sibi quisque facilia factū putat, aequō animō accipit, suprā eā velutī ficta prō falsīs dūcit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"malevolus","latin":"malevolus, malevola, malevolum","headword":"malevolus","letter":"m","pos":"adjective","posGroup":"adjective","english":"spiteful, malevolent; ill-disposed; disaffected (L+S); envious","forms":["malevolō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tantus populī favor invidiam Saūlis accendit, quī deinceps malevolō fuit in Davidem animō, nec iam eum benignīs oculīs aspiciēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"malignus","latin":"malignus, maligna, malignum","headword":"malignus","letter":"m","pos":"adjective","posGroup":"adjective","english":"spiteful; niggardly; narrow","forms":["malignē"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tamen bene ēlātus est, vîtälî lectô, strägulîs bonīs. malignē illum plôrävit uxor. ...” [Philerôs dê Chrÿsanthô mortuô] Molestus fuit, Philerôsque prôclämävit: “Vîvôrum mē- minerimus!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"malitia","latin":"malitia, malitiae","headword":"malitia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"ill will, malice; wickedness; vice, fault","forms":["malitiā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quōrum Iugurtha acceptā ōrātiōne respondit: 'Sibi neque māius quicquam neque cārius auctōritāte senātūs esse; ab adulēscentiā ita sē enīsum ut ab optimō quōque probārētur; virtūte, nōn malitiā P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"malitiosus","latin":"malitiosus, malitiosa, malitiosum","headword":"malitiosus","letter":"m","pos":"adjective","posGroup":"adjective","english":"wicked; crafty, roguish, knavish","forms":["Malitiōsam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pugna atrōx ad silvam {{Malitiōsam}} fuit, ubi equitātū nūper auctō plūrimum Rōmāna aciēs valuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"malle","latin":"(mālō) mālle, māluisse","headword":"mālle","letter":"m","pos":"verb","posGroup":"verb","english":"prefer; to prefer","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"malleolus","latin":"malleolus, malleoli","headword":"malleolus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"fire-dart; brush for burning (Vulgate Prayer of Azariah 1:23)","forms":["malleolōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quārē sēcēdant improbī, sēcernant sē ā bonīs, ūnum in locum congregentur, mūrō dēnique, quod saepe iam dīxī, sēcernantur ā nōbīs, dēsinant īnsidiārī domī suae cōnsulī, circumstāre tribūnal praetōris urbānī, obsīdere cum gladiīs cūriam, {{malleolōs}} et facēs ad īnflammandam urbem comparāre!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"malo","latin":"mālō, mālle, māluī","headword":"mālō","letter":"m","pos":"verb","posGroup":"verb","english":"prefer","forms":["mālam","mālēbant","mālēbat","mālent","malī","mālim","malis","mālit","mālle","māllem","māllet","mālō","māluērunt","mālumus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium {{malis}} adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"malum","latin":"mālum, -ī","headword":"mālum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"apple","forms":["malum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dīcit ‘tē esse {{malum}} medicum!’”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"malus","latin":"malus, -a, -um","headword":"malus","letter":"m","pos":"adjective","posGroup":"adjective","english":"bad, wicked, evil; bad, wicked; evil, bad","forms":["malae","malārum","malās","malōrum","malōs","malus","pēior","peiōrem","pēiōrēs","peius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Canis ille parvus tam {{malus}} est quam lupus!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mam","latin":"Mam., abb.","headword":"Mam","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mamereus (Roman praenomen); (abb. Mam.)","forms":["mam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Erat autem vë- nälicium cum titulîs pictum, et ipse Trimalchiô capillātus cādūceum tenēbat Minerväque dūcente Rô{{mam}} intrābat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"mamma","latin":"mamma, -ae","headword":"mamma","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mommy; mummy, mum","forms":["mamma","mammae","mammam","mammās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia Aemiliam vocat: “{{Mamma}}!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"man","latin":"man, undeclined","headword":"man","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"manna; (food from God in Siani); [man/man hu => (Hebrew) what/what is this]","forms":["man"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"admótae {{man}}üs fōrmam capillīs admōtae fōrmam","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"manare","latin":"(mānō) mānāre","headword":"mānāre","letter":"m","pos":"","posGroup":"other","english":"flow, be wet, drip","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"manasses","latin":"Manasses, Manassae","headword":"Manasses","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Manasses; (son of Joseph in Vulgate Genesis)","forms":["Mānāssēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ezechiae successit {{Mānāssēs}}, patris religiosī fīlius impius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mandare","latin":"(mandō) mandāre","headword":"mandāre","letter":"m","pos":"verb","posGroup":"verb","english":"assign, order; to order, entrust (+ dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"mandatum","latin":"mandātum, -ī","headword":"mandātum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"order; command, order","forms":["mandāta","mandatis","mandātum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His datis {{mandatis}} eos ab se dimisit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mando","latin":"mando, mandare, mandavi, mandatus","headword":"mando","letter":"m","pos":"verb","posGroup":"verb","english":"entrust, commit to one's charge, deliver over; commission; order, command","forms":["mandabant","mandandum","mandant","mandāre","mandat","mandāte","mandāvit","mandī","mandit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec eadem centurionibus tribunisque militum {{mandabant}}, ut per eos ad Caesarem deferrentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"manduco","latin":"manduco, manducare, manducavi, manducatus","headword":"manduco","letter":"m","pos":"verb","posGroup":"verb","english":"chew, masticate, gnaw; eat, devour","forms":["mandūcābant","mandūcāvit","mandūcēmus","mandūcent"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum sublevāsset ergō oculōs Jēsus et vīdisset turbam maximam illam, dīxit Philippō:\"Unde emēmus pānēs ut {{mandūcent}} hī?\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mane","latin":"māne","headword":"māne","letter":"m","pos":"noun (n.); adverb","posGroup":"noun","english":"morning; in the morning; in the morning, early","forms":["mane"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quibus rebus cognitis media nocte silentio profectus ad hostium castra {{mane}} pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maneo","latin":"maneō, manēre","headword":"maneō","letter":"m","pos":"verb","posGroup":"verb","english":"remain; remain, stay","forms":["maneam","maneant","maneās","maneat","manēbant","manēbimus","manēbit","manēbitis","manēbō","manēbunt","manendō","manēns","manent","manentibus","maneō","manēre","manērem","manērent","manēret","manēs","manet","manētis","mānserant","mānsērunt","mānsissent","mānsistī","mānsit","mānsūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dimittit quoque versus legationes; obtestatur ut in fide {{maneant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"manes","latin":"mānēs, -ium","headword":"mānēs","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"the shades of the dead","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"mania","latin":"mania, maniae","headword":"mania","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mania; craze","forms":["maniīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quīdam eōrum, nōmine Eurytus, quī māmaximē ēbrius erat, Hippodamen rapuit; aliī ra puērunt quās poterant; puellārum mātrōnārumque clamōribus tōta domus replēbātur: “Heus, tū, mōnstrum!” clāmābant, “Abstinē {{maniīs}} ā mē!” “Ō virī, auxilium ferte!” Omnēs igitur vīn, cum haec indigna scelera fierī vidērent, statim ē lectīs surrēxērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"manifesto","latin":"manifesto, manifestare, manifestavi, manifestatus","headword":"manifesto","letter":"m","pos":"verb","posGroup":"verb","english":"make visible/clearer/evident/plain; reveal, make known; disclose; clarify","forms":["manifestāvit","manifestō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Posteā {{manifestāvit}} sē Iēsus ad mare Tiberiadis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"manifestus","latin":"manifēstus, -a, -um","headword":"manifēstus","letter":"m","pos":"adjective","posGroup":"adjective","english":"flagrant, plain","forms":["manifēsta","manifēstī","manifēstīs","manifēstōs","manifēstum","manifēstus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iūdās respondit: fateor, rēs est {{manifēsta}}; nūllam possumus excūsātiōnem affēre, nec audēmus petere veniam aut spērāre; nōs omnēs erimus servī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"manipularis","latin":"manipularis, manipularis","headword":"manipularis","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"soldier of a maniple; common soldier, private; marine; comrades (pl.)","forms":["manipulares","manipularibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Fabius, centurio legionis VIII., quem inter suos eo die dixisse constabat excitari se Avaricensibus praemiis neque commissurum ut prius quisquam murum ascenderet, tres suos nactus {{manipulares}} atque ab eis sublevatus murum ascendit; hos ipse rursus singulos exceptans in murum extulit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"manipulus","latin":"manipulus, -ī","headword":"manipulus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"maniple; maniple, company of soldiers","forms":["manipulī","manipulīs","manipulōs","manipulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec porrō erant Iōsēphī somnia: ligābāmus, inquit, simul {{manipulōs}} in agrō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"manis","latin":"mānis, -ium","headword":"mānis","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"shades of the dead, ghost","forms":["mānīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"id cinerem aut {{mānīs}} crēdis cūrāre sepultōs?","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"manius","latin":"Manius, Mani","headword":"Manius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Manius (Roman praenomen); (abb. M'.); one who has fallen on hard times","forms":["māniī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Omnia optimī ducis miinia ēgregiē implēvit: dīvīnō, quod invocāverat, auxiliō frētus, castella expugnāvit, urbēs praesidiīs miīnīvit; Apollōnium, iinum ex praefecfīs Antiochī, vīcit, et ipse sua māniī inter:Iēcit, eiusque gladiō, quem illī dētrāxerat, in proeliīs deinceps iīsus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"manlius","latin":"Manlius, Manlia, Manlium","headword":"Manlius","letter":"m","pos":"adjective","posGroup":"adjective","english":"Manlian; of Manlius gens","forms":["Manliō","Manlium","Mānlius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eius reī exemplum memorātur Titus {{Mānlius}} Torquātus, quī fīlium suum cōram exercitū necārī iussit quia contrā imperium patris cum hoste pugnāverat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"manna","latin":"manna, mannae","headword":"manna","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"manna; (food from God for Exodus Jews); food for the soul, divine support","forms":["manna"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dēerat pānis; at Deus ipse eōs aluit: ē caelō per annōs quadrāgintā cecidit cibus, quem appellāvērunt ‘{{manna}}’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mano","latin":"mano, manare, manavi, manatus","headword":"mano","letter":"m","pos":"verb","posGroup":"verb","english":"flow, pour; be shed; be wet; spring","forms":["manant","manantem","mānāre","mānāret"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum Nīobē lacrimat, in statuam congelat; etiam nunc lacrimae {{manant}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mansuetudo","latin":"mānsuētūdō, -inis ( f.)","headword":"mānsuētūdō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mildness, clemency; gentleness, clemency","forms":["mānsuētūdine","mānsuētūdinem","mānsuētūdō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hūmānitāte iam tanta est ut difficile dictū sit, utrum hostēs magis virtūtem eius pugnantēs timuerint an {{mānsuētūdinem}} victī dīlēxerint.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mantele","latin":"mantele, mantelis","headword":"mantele","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"handtowel; napkin; towel, cloth; tablecloth (L+S)","forms":["mantēlia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"expediunt, tōnsīsque ferunt {{mantēlia}} vīllīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"manto","latin":"Mantō, -ūs","headword":"Mantō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Manto (a wise woman)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"mantum","latin":"mantum, manti","headword":"mantum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"Spanish cloak","forms":["mantīs","Mantō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, linguam amputarī, cutem capitis detrahī, summās {{mantīs}} ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"manus","latin":"manus","headword":"manus","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) hand","forms":["manibus","manu","manum","manus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac coacta {{manu}}, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mappa","latin":"mappa, mappae","headword":"mappa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"white cloth; napkin; handkerchief; cloth dropped as start signal; tablecloth","forms":["mappam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Palliô enim coccineô adrāsum exclūserat caput, circäque onerātās veste cer- vîcës lāticlāviam immîserat {{mappam}} ﬁmbriîs hinc atque illinc pendentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"marco","latin":"marco, marcere, marcui, marcitus","headword":"marco","letter":"m","pos":"verb","posGroup":"verb","english":"be withered/flabby, droop/shrivel; flag/faint; be weak/enfeebled/idle/apathetic","forms":["Mārce","Mārcī","Mārcō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Audītur vōx Mārcī: “Venī, Quīnte!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"marcus","latin":"Marcus, Marci","headword":"Marcus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Marcus (Roman praenomen); (abb. M.)","forms":["Mārcum","Mārcus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Mārcus}}: “Ubi est Syria, Iūlia?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mare","latin":"mare, maris","headword":"mare","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"(n.) sea","forms":["mare","marī","maribus","maris","marium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postquam Noëmus ipse ingressus est in arcam cum coniuge, tribus fīliīs et totidem nuribus, aquā {{maris}} et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"margarita","latin":"margarīta, -ae","headword":"margarīta","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"pearl","forms":["margarīta","margarītae","margarītam","margarītārum","margarītās","margarītīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia et Syra in hortō ambulant cum Margarītā, cane Iūliae parvā et crassā.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"margo","latin":"margo, marginis","headword":"margo","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"margin, edge, flange, rim, border; threshold; bank, retaining wall; gunwale","forms":["marginibus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tegēbant asellum duae ‘lancés, in quärurn {{marginibus}} nômen Trimalchiônis înscrîptum erat et argentî pondus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"maria","latin":"Maria, Mariae","headword":"Maria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Mary","forms":["maria","Mariam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ascendit Iōsēph dē cīvitāte Nazareth in cīvitātem, quae vocātur Bēthlehem, cum Marīā, uxōre suā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"marinus","latin":"marinus, marina, marinum","headword":"marinus","letter":"m","pos":"adjective","posGroup":"adjective","english":"marine; of the sea; sea born","forms":["marīnās","marīnī","marīnō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Rēx, cum nūllō aliō modō deōrum īram minuere sē posse vidēret, quamquam maximō dolōre afficiēbātur, virginem catēnīs vīnctam in maris lītore expōnī iussit ut ā mōnstrō illō marīnō vorārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"marita","latin":"marita, maritae","headword":"marita","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"wife","forms":["marīta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Coniugis admissum violātaque iūra {{marīta}} est","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"maritimus","latin":"maritimus, -a, -um","headword":"maritimus","letter":"m","pos":"adjective","posGroup":"adjective","english":"seaside, coastal; maritime, of the sea","forms":["maritimā","maritimae","maritimam","maritimī","maritimīs","maritimō","maritimum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ad ōram {{maritimam}} Lātōna postrēmō advēnit, ubi sīc Neptūnum ōrāvit: “Ō Neptūne, ōrō tē ut mē in īnsulam ferās in mediō marī sitam: optō enim ut ibi īrātam Iūnōnem tandem effugere possim!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"marito","latin":"marito, maritare, maritavi, maritatus","headword":"marito","letter":"m","pos":"verb","posGroup":"verb","english":"marry, give in marriage","forms":["marītō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ille vērō uxōrem mortuam in cubiculō suō flet.” Herculēs igitur surgēns magnā vōce clāmat: “Ad Īnferōs dēscendam, ubi cum Morte ipsā pugnābō, ut, victa, tam probam fēminam marītō vīvīsque reddat!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"maritus","latin":"marītus, -ī","headword":"marītus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"husband","forms":["marītī","marītōrum","marītōs","marītum","marītus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius iam domī est apud Fabiam uxōrem, quae {{marītum}} adesse gaudet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"marius","latin":"Marius, Mari","headword":"Marius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Marius; (Roman gens name)","forms":["Mariī","Mariō","Marius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caecilius Metellus cōnsul, cui {{Marius}} lēgātus datus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"marmor","latin":"marmor, marmoris","headword":"marmor","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"marble, block of marble, marble monument/statue; surface of the sea","forms":["marmorā","marmore","marmoris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cotīdiē enim pulcherrima signa ex {{marmore}} faciēbat, quae tamen nōn signa, sed hominēs vīvī esse vidēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"marmoreus","latin":"marmoreus, -a, -um","headword":"marmoreus","letter":"m","pos":"adjective","posGroup":"adjective","english":"made of marble, marble","forms":["marmorea","marmoream","marmoreīs","marmoreō","marmoreum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc neque marmoreō pendébant vēla theātrō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"marmus","latin":"marmus, marma, marmum","headword":"marmus","letter":"m","pos":"adjective","posGroup":"adjective","english":"marine; belonging to the sea","forms":["marmō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"audīta (: uae audīvērunt) in marmō-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"maro","latin":"Maro, Maronis","headword":"Maro","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Maro; (Virgil's cognomen); mythical character; for outstanding poets (pl.)","forms":["Maro"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Si non es stultus, scis, {{Maro}}, quid cupiam! —","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mars","latin":"Mars, Martis","headword":"Mars","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mars, Roman god of war; warlike spirit, fighting, battle, army, force of arms","forms":["Mārs","Mārte","Mārtem","Mārtī","Mārtis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mēnsī prīmō et mēnsī tertiō ā deīs nōmina sunt: Iānuāriō ā deō Iānō, Mārtiō ā deō {{Mārte}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"martialis","latin":"Martialis, Martialis, Martiale","headword":"Martialis","letter":"m","pos":"adjective","posGroup":"adjective","english":"of or belonging to Mars","forms":["Martialis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Tum vero Cornelius \"Bene quidem\" inquit \"et iocose scripsit Catullus, nec tamen versus eius comparandi sunt cum epigrammatis sale plenis quae {{Martialis}} in inimicos scripsit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"martius","latin":"Martius, Martia, Martium","headword":"Martius","letter":"m","pos":"adjective","posGroup":"adjective","english":"March (month/mensis understood); abb. Mart.; of/belonging to Mars","forms":["Mārtiae","Martiās","Mārtiī","Mārtiīs","Mārtiō","Martium","Mārtius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; {{Mārtius}}, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"martyr","latin":"martyr, martyris","headword":"martyr","letter":"m","pos":"noun","posGroup":"noun","english":"martyr; witness; one who by his death bears witness to the truth of Christ","forms":["martyrēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Saturnīnus prōcōnsul dēcrētum ex tabellā recitāvit: “Spērātum, Nartzālum, Cittīnum, Dōnātam, Vestiam, Secundam et cēterōs ‘rītū Christiānō sē vīvere’ cōnfessōs, quoniam oblātā sibi facultāte ad Rōmānōrum mōrem redeundī obstīnanter persevērāvērunt, gladiō animadvertī placet.” Spērātus dīxit: “Deō grātiās agimus.” Nartzalus dīxit: “Hodiē {{martyrēs}} in caelīs sumus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"mas","latin":"mas, maris","headword":"mas","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"male (human/animal/plant); man","forms":["marem"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sustinet immundum sīmā capellā {{marem}}.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"masculinum","latin":"masculīnum, -ī (genus)","headword":"masculīnum","letter":"m","pos":"adjective","posGroup":"adjective","english":"masculine","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"masculinus","latin":"masculīnus","headword":"masculīnus","letter":"m","pos":"adjective","posGroup":"adjective","english":"masculine","forms":["masculīnum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Genera nōminum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: '{{Masculīnum}}, ut hic magister; fēminīnum, ut haec fēmina; neutrum, ut hoc scamnum; commūne, ut hic et haec sacerdōs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"massa","latin":"massa, massae","headword":"massa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mass, bulk; heavy weight, load, burden; lump; kneaded dough","forms":["massā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"massā -ae f — mōlēs (marmoris/āeris)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"massylus","latin":"Massylus, Massyla, Massylum","headword":"Massylus","letter":"m","pos":"adjective","posGroup":"adjective","english":"Massylian; of the Massyli (Numidian people)","forms":["Massȳlae","Massȳlōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Scīpiō in Hispāniā cum Poenīs dēbellāvit quārtō decimō annō eius bellī; et ā Tarracōne in Āfricam ad Syphācem, rēgem {{Massȳlōrum}}, trānsvectus, foedus cum eō iūnxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mater","latin":"māter","headword":"māter","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) mother","forms":["māter","mātre","mātrem","matres","mātrī","mātribus","mātris","mātrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum {{matres}} familiae repente in publicum procurrerunt flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"materia","latin":"māteria, -ae","headword":"māteria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"material; material, substance; material, matter","forms":["materia","māteriae","māteriam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta {{materia}} et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"materies","latin":"materies, materiei","headword":"materies","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"wood (building material), lumber, timber; woody branch/growth/part of tree","forms":["materiem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Alii faces atque aridam {{materiem}} de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium vix ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"materior","latin":"materior, materiari, materiatus sum","headword":"materior","letter":"m","pos":"verb","posGroup":"verb","english":"get timber","forms":["materiari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Erat eodem tempore et {{materiari}} et frumentari et tantas munitiones fieri necesse deminutis nostris copiis, quae longius ab castris progrediebantur; ac non numquam opera nostra Galli temptare atque eruptionem ex oppido pluribus portis summa vi facere conabantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maternus","latin":"māternus, -a, -um","headword":"māternus","letter":"m","pos":"adjective","posGroup":"adjective","english":"maternal","forms":["māterna","māternam","māternē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Utra īnfantem Aemiliae alet, māternē an nūtrīx?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mathematicus","latin":"mathematicus, mathematici","headword":"mathematicus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"mathematician; astrologer","forms":["mathēmaticus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Et sānē nôlentem mē negôtium meum agere exhortā- vit {{mathēmaticus}}, quî vēnerat forte in colôniam nostram, Graeculiô, Seräpa nômine, cônsiliätor deôrum!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"matricidium","latin":"mātrīcīdium, -iī","headword":"mātrīcīdium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"matricide","forms":["Mātrīcīdium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Mātrīcīdium}} prohibuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"matrimonium","latin":"mātrimōnium, -ī","headword":"mātrimōnium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"matrimony, marriage; matrimony, wedding","forms":["mātrimōniī","mātrimōniō","mātrimōnium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ex ea fōrmāvit mulierem, quam dedit sociam Adamō, sīcque īnstituit {{mātrimōnium}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"matrona","latin":"mātrōna, -ae","headword":"mātrōna","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"married woman; married woman, matron","forms":["mātrōna","mātrōnae","mātrōnās","mātrōnīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum haec dīcerent, Hippodame, pulcherrima virgō, tīna cum aliīs fēminīs et {{mātrōnīs}} trīclīnium intrāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"matronalis","latin":"mātrōnālis, -e","headword":"mātrōnālis","letter":"m","pos":"adjective","posGroup":"adjective","english":"of a married woman","forms":["mātrōnālēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ēloquar' inquit, 'ēloquar īnfēlīx dēdecus ipsa meum?' Quaeque potest, nārrat; restābant ultima: flēvit, et {{mātrōnālēs}} ērubuēre genae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mattea","latin":"mattea, matteae","headword":"mattea","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"dainty dish","forms":["matteae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Canem suum addûcî iubet, quî cum parvô cānē pugnāns tumultum facit. Înse- quuntur {{matteae}}: gallînae altilês et ôva änserîna.] Inter haec triclîniî valvās lîctor percussit, amictusque veste albā cum ingentî frequentiā cômissätor intrāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"maturare","latin":"(mātūrō) mātūrāre","headword":"mātūrāre","letter":"m","pos":"","posGroup":"other","english":"make haste, hurry","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"mature","latin":"mātūrē","headword":"mātūrē","letter":"m","pos":"adverb","posGroup":"adverb","english":"quickly, early","forms":["mātūre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Bomilcar {{mātūre}} rēgis mandāta exsequitur, et per hominēs tālis negōtiī artificēs itinera ēgressūsque eius, postrēmō loca atque tempora cūncta explōrat; deinde, ubi rēs postulābat, īnsidiās tendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maturesco","latin":"maturesco, maturescere, maturui, -","headword":"maturesco","letter":"m","pos":"verb","posGroup":"verb","english":"become ripe, ripen mature","forms":["mātūrēscēbant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum prior sīc exposuit Iōsēphō somnium suum: vīdī in quiēte vītem in quā erant trēs palmitēs; ea paulātim prōtulit gemmās; deinde flōrēs ērūpērunt, ac dēnique ūvae {{mātūrēscēbant}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maturitas","latin":"mātūritās, -ātis ( f.)","headword":"mātūritās","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"ripeness, maturity","forms":["mātūritās","mātūritātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Cum autem annō post ex Siciliā mē recēpissem, iam vidēbātur illud in mē — quicquid esset — esse perfectum et habēre {{mātūritātem}} quandam suam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maturo","latin":"maturo, maturare, maturavi, maturatus","headword":"maturo","letter":"m","pos":"verb","posGroup":"verb","english":"ripen, hurry, make haste to, hasten","forms":["mātūrandī","maturandum","mātūrantēs","Mātūrāte","mātūret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus rebus cognitis Caesar {{maturandum}} sibi censuit, si esset in perficiendis pontibus periclitandum, ut prius quam essent maiores eo coactae copiae dimicaret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maturus","latin":"mātūrus, -a, -um","headword":"mātūrus","letter":"m","pos":"adjective","posGroup":"adjective","english":"ripe, early; ripe, mature","forms":["mātūra","mātūrae","mātūrīs","maturius","mātūrum","mātūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si {{maturius}} ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"matutinus","latin":"matutinus, matutina, matutinum","headword":"matutinus","letter":"m","pos":"adjective","posGroup":"adjective","english":"early; of the (early) morning","forms":["mātūtīnōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hanc {{mātūtīnōs}} pectēns ancilla capillōs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"maurus","latin":"Maurus, Mauri","headword":"Maurus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Moor; (inhabitant of North Africa); Mauretanian","forms":["Maurī","Maurīs","Maurus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ita ambōrum exercitū coniūnctō, Marium iam in hīberna proficīscentem, vix decimā parte diēī reliquā, invādunt: priusquam exercitus aut īnstruī aut sarcīnās colligere quīvit, equitēs Maurī atque Gaetūlī in nostrōs incurrunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maurusia","latin":"Maurusia, Maurusiae","headword":"Maurusia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Maurusia/Mauritania; (region of North Africa)","forms":["Maurūsia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"'Iuppiter omnipotēns, cui nunc {{Maurūsia}} pictīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"mausoleum","latin":"mausōlēum, -ī","headword":"mausōlēum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"mausoleum; mausoleum, great tomb","forms":["mausōlēum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Claudiō Marcellō; āra Pācis, in quā sacerdōtēs virginēsque Vestālēs anniversārium sacrificium facere iussit; {{mausōlēum}} Augustī, id est monumentum in quō ossa prīncipis cremāta servantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mavors","latin":"Mavors, Mavortis","headword":"Mavors","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mars, Roman god of war; warlike spirit, fighting, battle, army, force of arms","forms":["Māvors"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Māvors}} -rtīs ; — Mārs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"maxilla","latin":"maxilla, maxillae","headword":"maxilla","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"jaw (viewed externally), lower part of the face; jaws/jaw-bones (usu. pl.)","forms":["maxillā","māxillae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Trāditus Philistaeīs rūpit vincula, quibus constrīctus erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"maxime","latin":"maximē","headword":"maximē","letter":"m","pos":"adverb","posGroup":"adverb","english":"very, exceedingly; yes indeed","forms":["maxime"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et {{maxime}}, quod ipse animo non defecerat tanto accepto incommodo neque se in occultum abdiderat et conspectum multitudinis fugerat; plusque animo providere et praesentire existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"maximus","latin":"māximus, -a, -um","headword":"māximus","letter":"m","pos":"adjective","posGroup":"adjective","english":"largest, greatest; greatest, biggest","forms":["māximus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Cornēlius rīdēns “Id nōn dīcis” inquit “cum pulchritūdinem tuam laudō!” — sed eō ipsō tempore ātrium illūstrātur clārissimō fulgure atque {{māximus}} tonitrus audītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"maxume","latin":"maxume","headword":"maxume","letter":"m","pos":"adverb","posGroup":"adverb","english":"especially, chiefly; certainly; most, very much; (forms SUPER w/ADJ/ADV)","forms":["maxumē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque Delphōs, ad maxumē inclutum in terrīs ōrāculum, mittere statuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"maxumus","latin":"maxumus, maxuma, maxumum","headword":"maxumus","letter":"m","pos":"adjective","posGroup":"adjective","english":"greatest/biggest/largest; longest; oldest; highest, utmost; leading, chief","forms":["Maxumam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī labor cum mīlitiae adderētur, minus tamen plēbs indignābātur sē templa deōrum aedificāre manibus suīs, quam postquam ad alia opera speciē minōra, sed labōris aliquantō maiōris traducēbātur, velut ad forōs in circō faciendōs cloācamque {{Maxumam}} sub terrā agendam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"me","latin":"mē","headword":"mē","letter":"m","pos":"pronoun","posGroup":"pronoun","english":"me; me, myself","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"mecastor","latin":"mecastor","headword":"mecastor","letter":"m","pos":"interjection","posGroup":"interjection","english":"by Castor!","forms":["mecastor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nusquam igitur scrīptum invenīre est — apud idōneōs quidem scrīptōrēs — aut 'mehercle' fēminam dīcere aut '{{mecastor}}' virum; 'edepol' autem, quod iūs iūrandum per Pollūcem est, et virō et fēminae commūne est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mecum","latin":"mēcum","headword":"mēcum","letter":"m","pos":"","posGroup":"other","english":"with me","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"medea","latin":"Medea, -ae","headword":"Medea","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Medea (princess of Colchis)","forms":["Medea","Medeae","Medeam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aeētēs autem fīliam nōmine {{Medeam}} habēbat, quae auxiliō magnō Iāsonī futūra erat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"medeor","latin":"medeor, mederi, -","headword":"medeor","letter":"m","pos":"verb","posGroup":"verb","english":"heal, cure; remedy, assuage, comfort, amend","forms":["medendī","medērī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"735 Quantus apud Danaōs Podalīrius arte medendī,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mederi","latin":"(medeor) medērī (+ dat.)","headword":"medērī","letter":"m","pos":"","posGroup":"other","english":"heal, cure, remedy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"medicamen","latin":"medicāmen, -inis","headword":"medicāmen","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"drug, medicine; drug, medicine, charm","forms":["medicāmen","medicāmina","medicāmine"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tantum {{medicāmina}} poterant ut sine timōre dextrā fortī iugum grave in umerīs taurōrum pōneret et ferreō arātrō campum coleret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"medicamentum","latin":"medicamentum, medicamenti","headword":"medicamentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"drug, remedy, medicine","forms":["medicāmentum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc iussit angelus fel piscis sēpōnī, utpote {{medicāmentum}} salūtāre; deinde partem carnis coxērunt comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"medice","latin":"medice, medices","headword":"medice","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"doctor (female), physician, healer","forms":["medice"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Sānā tē ipsum, {{medice}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"medicina","latin":"medicīna, -ae","headword":"medicīna","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"medicine","forms":["medicīnae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sum deus sōlis, mūsicae, {{medicīnae}}, artium.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"medico","latin":"medico, medicare, medicavi, medicatus","headword":"medico","letter":"m","pos":"verb","posGroup":"verb","english":"heal, cure; medicate; dye","forms":["medicō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Syra (parvā vōce ad Aemiliam): “Is nōn est tam crassus quam ipse medicus!” Sed ea verba ā crassō medicō nōn audiuntur. cui color faciēī ruber est, nimis multum sanguinis habet...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"medicus","latin":"medicus, -ī","headword":"medicus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"doctor; doctor, physician","forms":["medicī","medicum","medicus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus: “Venī Rōmam ad {{medicum}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"medio","latin":"medio, mediare, mediavi, mediatus","headword":"medio","letter":"m","pos":"verb","posGroup":"verb","english":"halve, divide in the middle; be in the middle","forms":["medio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Medio}} fere itinere equites a Fabio missi quanto res in periculo fuerit exponunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mediocris","latin":"mediocris, -e","headword":"mediocris","letter":"m","pos":"adjective","posGroup":"adjective","english":"moderate, ordinary","forms":["mediocrem","mediocri","mediocris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ante id oppidum planities circiter milia passuum III in longitudinem patebat; reliquis ex omnibus partibus colles {{mediocri}} interiecto spatio pari altitudinis fastigio oppidum cingebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mediocriter","latin":"mediocriter, mediocrius, mediocrissime","headword":"mediocriter","letter":"m","pos":"adverb","posGroup":"adverb","english":"to moderate/subdued extent/degree, ordinarily/moderately/tolerably; not very","forms":["mediocriter"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Gracchum, {{mediocriter}} labefactantem statum reī pūblicae, prīvātus interfēcit — Catilīnam, orbem terrae caede atque incendiīs vastāre cupientem, nōs cōnsulēs perferēmus?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"meditatio","latin":"meditātiō, -ōnis ( f.)","headword":"meditātiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"reflection, practicing","forms":["meditātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In librō quem Caesare dictātōre scrīpsit ad Brūtum 'Dē clārīs ōrātōribus', Cicerō inter alia haec dē doctrīnā suā iuvenīlī nārrat: 'At vērō ego hōc tempore omnēs noctēs et diēs in omnium doctrīnārum {{meditātiōne}} versābar.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mediterraneus","latin":"mediterraneus, mediterranea, mediterraneum","headword":"mediterraneus","letter":"m","pos":"adjective","posGroup":"adjective","english":"inland, remote from the coast","forms":["Mediterrāneō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sunt in marī Mediterrāneō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"meditor","latin":"meditor, meditari, meditatus sum","headword":"meditor","letter":"m","pos":"verb","posGroup":"verb","english":"consider/contemplate/ponder; meditate, think about; reflect on; devise/plan","forms":["meditābātur","meditābor","meditāmur","meditāns","meditārī","meditātī","meditātur","meditēre","meditor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At illī: minimē, inquiunt; nihil malī {{meditāmur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"medium","latin":"medium, medi(i)","headword":"medium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"middle, center; medium, mean; midst, community, public; publicity","forms":["mēdī","medium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In sacculō Mēdī nōn ūnus tantum, sed multī nummī sunt.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"medius","latin":"medius, -a, -um","headword":"medius","letter":"m","pos":"adjective","posGroup":"adjective","english":"mid, middle; middle of; middle; middle, middle of","forms":["media","mediae","mediam","mediās","mediī","mediīs","medios","medius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cenabenses paulo ante {{mediam}} noctem silentio ex oppido egressi flumen transire coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"medulla","latin":"medulla, medullae","headword":"medulla","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"marrow, kernel; innermost part; quintessence","forms":["medullae","medullās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{medullae}} -àrum fpl — ossīs media","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mehercle","latin":"mehercle","headword":"mehercle","letter":"m","pos":"interjection","posGroup":"interjection","english":"by Hercules!","forms":["mehercle"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nusquam igitur scrīptum invenīre est — apud idōneōs quidem scrīptōrēs — aut '{{mehercle}}' fēminam dīcere aut 'mecastor' virum; 'edepol' autem, quod iūs iūrandum per Pollūcem est, et virō et fēminae commūne est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mehercule","latin":"mehercule","headword":"mehercule","letter":"m","pos":"interjection","posGroup":"interjection","english":"by Hercules! assuredly, indeed","forms":["mēhercule"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deinde exercitus ibi est locōrum sciēns, sed {{mēhercule}} magis strēnuus quam fēlīx; nam magna pars eius avāritiā aut temeritāte ducum attrīta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mehercules","latin":"mehercules","headword":"mehercules","letter":"m","pos":"interjection","posGroup":"interjection","english":"by Hercules! assuredly, indeed","forms":["meherculēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn putô illum capillôs lîberôs habēre, nec {{meherculēs}} suā culpā: ipsô enim homô melior nôn est; sed lîbertî scelerätî, quî omnia ad sē fēcērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"meile","latin":"meile, meilis","headword":"meile","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"thousand (men); thousands; (archaic plural of mille); [milia (passuum) => mile]","forms":["meile"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Mūsae ex altō Olympō eum ōrantem audīvērunt, et apēs ad arcam mīsērunt, quae, in cubiculum per parvam rīmam ingressae, in arcam intrāvērunt et Comātam {{meile}} aluērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mel","latin":"mel, mellis","headword":"mel","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"(n.) honey","forms":["mel","mella","melle","mellis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Inerat huic cibō gustus similiae cum {{melle}} mixtae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"meleager","latin":"Meleager, -grī","headword":"Meleager","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Meleager, prince of Calydon","forms":["Meleager","Meleagrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Supplex Calydōn, urbs vīcīna, auxilium huius petīvit, quamquam {{Meleagrum}} fortem ducem habēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"melior","latin":"melior, melius","headword":"melior","letter":"m","pos":"adjective","posGroup":"adjective","english":"better","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"melissa","latin":"melissa, melissae","headword":"melissa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"balm","forms":["Melissa"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In lārvam inträvî, paene animam ébul- lîvî, sūdor mihi per bifurcum volābat, oculî mortuî, vix “{{Melissa}} mea mîrärî coepit quod tam sërô ambulārem, et “Sî ante”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"melita","latin":"Melita, Melitae","headword":"Melita","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Malta (island); Mljet/Meleda (Adriatic island); some cities (L+S); sea-nymph","forms":["Melita"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"{{Melita}} est īnsula parva.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"melius quam","latin":"melius quam","headword":"melius quam","letter":"m","pos":"phrase","posGroup":"other","english":"better than","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"meliusculus","latin":"meliusculus, meliuscula, meliusculum","headword":"meliusculus","letter":"m","pos":"adjective","posGroup":"adjective","english":"somewhat better","forms":["meliusculae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"(dîvitiae) octingenta mîlia sēstertium Incubô -ônis m, deus cüstôs thêsauﬂ occultî, quī pilleô nôn male (: bene) sibi vult lîbertînî locus: medius in îmô sēstertium deciēs centêna capillôs lîberôs : quicquam ipsô melior z melior quam ille ad sé fēcērunt : suā tëcêrunt gôtium est ﬁmera apparāre .”‘“ vernāculae quae sunt {{meliusculae}} ā Graeculîs citās: nūlla nôn aut cōn- “Rē1iquôs autem collîbertôs eius cavē contemnās!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"mellitus","latin":"mellītus, -a, -um","headword":"mellītus","letter":"m","pos":"adjective","posGroup":"adjective","english":"sweet","forms":["mellitus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"nam {{mellitus}} erat suamque norat","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"melos","latin":"melos, meli","headword":"melos","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"song, tune, air, strain, lay, melody; hymn","forms":["mēlōs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Certē {{Mēlos}} īnsula, quae īnfrā nōs est, nōn tam parva est quam tibi vidētur.\" Īcarus: \"Sed illa īnsula quae nōbīs ā sinistrā est multō maior esse mihi vidētur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"membrana","latin":"membrana, membranae","headword":"membrana","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"membrane; skin; parchment","forms":["membrāna","membrānam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Deinde Tobiās oculōs patris līnīvit felle piscis, et post dīmidiam fermē hōram coepit albūgō, quasi {{membrāna}} ōvī, ex oculīs eius ēgredī, quam apprehēnsam fīlius extrāxit, atque ille statim vīsum recēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"membrum","latin":"membrum, -ī","headword":"membrum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"limb; limb, member; leg (of a table)","forms":["membra","membrīs","membrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum comprehēnsus est secundus, et post dētractam capitis cutem cum capillls, interrogātus num vellet camem oblātam edere, negāvit sē id factūrum: quāpropter praecīsīs {{membrīs}}, in ōllam ārdentem missus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"memet","latin":"mēmet","headword":"mēmet","letter":"m","pos":"","posGroup":"other","english":"me, myself","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"memini","latin":"memini, meminisse","headword":"memini","letter":"m","pos":"verb","posGroup":"verb","english":"remember (PERF form, PRES force); keep in mind, pay heed to; be sure; recall","forms":["meminerat","meminēre","meminerint","meminerīs","meminerit","meminerītis","meminī","meminisse","meminissēs","meminisset","meministī","meminit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum his praemium communicat hortaturque eos ut se liberos et imperio natos {{meminerint}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"meminisse","latin":"(meminī) meminisse","headword":"meminisse","letter":"m","pos":"verb","posGroup":"verb","english":"(+ gen. or acc.) keep in mind, remember; to remember (+ gen.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"memor","latin":"memor (gen. memoris)","headword":"memor","letter":"m","pos":"adjective","posGroup":"adjective","english":"mindful, reminding","forms":["memor","memorem","memorēs","memorī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum ex hāc vītā dēcesserō, sepelī corpus meum; mātrem tuam colitō, {{memor}} malōrum quae passa est, cum tē in uterō gestāret, et cum ipsā suprēmum diem obierit, eam pōnitō mēcum in eōdem sepulcrō.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"memorabilis","latin":"memorābilis, -e","headword":"memorābilis","letter":"m","pos":"adjective","posGroup":"adjective","english":"memorable","forms":["memorābile","memorābilem","memorabilī","Memorābilis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Memorābilis}} fuit haec pugna fortitiidīne et morte Eleazarī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"memorandum","latin":"memorandum, memorandi","headword":"memorandum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"memorandum","forms":["memoranda","memorandī","memorandum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In campō Mārtiō plūrima opera exstrūxit, ē quibus {{memoranda}} sunt haec: porticus ad circum Flāminium, quam ā nōmine sorōris suae porticum Octāviae nōmināvit; theātrum Marcellī, appellātum ā sorōris fīliō M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"memorare","latin":"(memorō) memorāre, memorāvisse, memorātum","headword":"memorāre","letter":"m","pos":"","posGroup":"other","english":"relate, recall","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"memoria","latin":"memoria, -ae","headword":"memoria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"memory","forms":["memoria","memoriae","memoriam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Labienus milites cohortatus ut suae pristinae virtutis et secundissimorum proeliorum retinerent {{memoriam}} atque ipsum Caesarem, cuius ductu saepe numero hostes superassent, praesentem adesse existimarent, dat signum proeli.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"memoriter","latin":"memoriter","headword":"memoriter","letter":"m","pos":"adverb","posGroup":"adverb","english":"from memory","forms":["memoriter"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"hīc quidem certē quae illīc sunt rēs gestae memorat {{memoriter}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"memoro","latin":"memoro, memorare, memoravi, memoratus","headword":"memoro","letter":"m","pos":"verb","posGroup":"verb","english":"remember; be mindful of (w/GEN/ACC); mention/recount/relate, remind/speak of","forms":["memorā","memorābat","memorābitur","memorāns","memorant","memorantem","memorantur","memorārier","memorās","memorat","memorāta","memorātis","memorātur","memorāvī","memorāvimus","memorāvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīc ūnus vir fortiter Rōmam dēfendit, quī semper ā Rōmānīs propter magnam virtūtem {{memorābitur}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"menda","latin":"menda, mendae","headword":"menda","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"bodily defect, blemish; fault, error (usu. in writing)","forms":["menda","mendae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Quattuor {{menda}} in quīnque vocābulīs!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mendaciter","latin":"mendaciter","headword":"mendaciter","letter":"m","pos":"adverb","posGroup":"adverb","english":"falsely,deceptively, mendaciously","forms":["mendāciter"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At ille sīmius māior ait illī quī fallāx erat: “Quid sum ego?” Fallāx dīxit: “Tū es Imperātor!” Iterum interrogāvit: “Et istī quōs ante mē stāre vidēs, quid sunt?” Īdem fallāx respondit: “Hī comitēs sunt tuī, prīmicēriī, campidoctōrēs, et cēterī officiālēs.” Et prō hōc sīmius, quī {{mendāciter}} laudātus est cum turbā suā, ōsculātus est hominem fallācem et mūnera illī dedit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"mendacium","latin":"mendacium, mendaci(i)","headword":"mendacium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"lie, lying, falsehood, untruth; counterfeit, fraud","forms":["mendāciī","mendacio","mendācium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nuntios tota civitate Aeduorum dimittit, eodem {{mendacio}} de caede equitum et principum permovet; hortatur ut simili ratione atque ipse fecerit suas iniurias persequantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mendax","latin":"mendax, (gen.), mendacis","headword":"mendax","letter":"m","pos":"adjective","posGroup":"adjective","english":"lying, false; deceitful; counterfeit","forms":["mendācēs","mendācī","mendāx"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{mendāx}} -àcis adī —^ quī mentītur;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mendum","latin":"mendum, -ī","headword":"mendum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"mistake; fault, mistake","forms":["mendum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simul Titus idem {{mendum}} eōdem modo corrigit in suā tabulā, neque vērō magister hoc animadvertit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mens","latin":"mēns, mentis","headword":"mēns","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) mind","forms":["mēns","mente","mentem","mentes","mentī","mentibus","mentis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nihilo minus clandestinis nuntiis legationibusque Allobrogas sollicitat, quorum {{mentes}} nondum ab superiore bello resedisse sperabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mensa","latin":"mēnsa, -ae","headword":"mēnsa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"table","forms":["mēnsā","mēnsae","mēnsam","mēnsās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus autem pōculum vacuum in mēnsā pōnit et “Tempus iam est” inquit “domum mē redīre.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mensis","latin":"mēnsis, mēnsis","headword":"mēnsis","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) month","forms":["mēnse","mēnsēs","mēnsī","mēnsibus","mēnsis","mēnsum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Sciō Diodōrum adhūc quattuor discipulōs habēre, quōrum duo sunt fīliī Iūliī; sed ante paucōs {{mēnsēs}} octō discipulōs habēbat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mensura","latin":"mensura, mensurae","headword":"mensura","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"measure; length, area, capacity","forms":["mēnsūrā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"mēnsūrā -ae f — quantitās, modus Certa tibi à nōbīs dabitur","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"menta","latin":"menta, mentae","headword":"menta","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mint; any cultivated mint","forms":["menta"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Deinde ut respexî ad comitem, ille exuit sē et omnia vestî{{menta}} secundum viam posuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"mentio","latin":"mentiō, -ōnis ( f.)","headword":"mentiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mention, reference; mention","forms":["mentiō","mentiōne","mentiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cūr, inquit pater, {{mentiōnem}} fēcistis dē frātre vestrō minimō?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mentionem facere","latin":"mentiōnem facere","headword":"mentiōnem facere","letter":"m","pos":"phrase","posGroup":"other","english":"mention; to mention","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"mentior","latin":"mentior, mentiri, mentitus sum","headword":"mentior","letter":"m","pos":"verb","posGroup":"verb","english":"lie, deceive, invent; imitate; feign; pretend; speak falsely about","forms":["mentiar","mentior","Mentīre","mentīrī","mentīris","mentītum","mentītur","mentītus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sextus: “Meus pater mihi crēdet: scit enim mē nōn mentīrī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mentiri","latin":"(mentior) mentīrī, mentītum","headword":"mentīrī","letter":"m","pos":"verb","posGroup":"verb","english":"lie; to lie, tell a lie","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mentitur","latin":"mentītur","headword":"mentītur","letter":"m","pos":"verb","posGroup":"verb","english":"lies, deceives","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mentum","latin":"mentum, menti","headword":"mentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"chin; projecting edge (architecture)","forms":["mentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aenêīs 11.44 praxis -is f (acc -im): habêre citrat (: pedibus pulsat) mäteriâ mollî (ut cērä, gyp- pedês (vincula pedum) gerit unguentārius unguentum, ve- mola -ae f: înstrü{{mentum}} rō- vertitur; ita sēmen mōlītur comparāre + dat: illî : cum “In Geminîs autem nāscuntur bîgae et bovēs et coleî et quî utrôsque parietēs linunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"meo","latin":"meo, meare, meavi, meatus","headword":"meo","letter":"m","pos":"verb","posGroup":"verb","english":"go along, pass, travel","forms":["meō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In sacculō meō est pecūnia.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mercari","latin":"(mercōr) mercārī","headword":"mercārī","letter":"m","pos":"","posGroup":"other","english":"buy, purchase","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"mercator","latin":"mercātor, mercātōris","headword":"mercātor","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) merchant","forms":["mercātor","mercātōre","mercātōrem","mercātōrēs","mercātōribus","mercātōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Deinde cum cōnsēdissent ad sūmendum cibum, cōnspexērunt {{mercātōrēs}} quī petēbant Aegyptum cum camēlīs portantibus varia arōmata.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mercatorius","latin":"mercātōrius, -a, -um","headword":"mercātōrius","letter":"m","pos":"adjective","posGroup":"adjective","english":"mercantile; merchant’s, trading","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"mercatura","latin":"mercātūra, -ae","headword":"mercātūra","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"trade, commerce","forms":["mercātūrās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Oroandem dēnique Crētēnsem, cui nōta Thrāciae ōra erat quia {{mercātūrās}} in eā regiōne fēcerat, appellat, 'ut sē sublātum in lembum ad Cotym dēveheret.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mercatus","latin":"mercātus, -ūs","headword":"mercātus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"market, fair","forms":["mercātum","mercātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quī {{mercātus}} est sindonem, et dēpōnēns eum ē cruce, involvit sindone et posuit in monumentō, et advolvit lapidem ad ōstium monumenfī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mercennarius","latin":"mercennarius, mercennarii","headword":"mercennarius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"hired worker; mercenary","forms":["mercennariī","mercēnnāriīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In sē autem reversus, dīxit: ' Quanfī mercennariī in domō patris meī abundant pānibus, ego autem hīc famē pereō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"merces","latin":"mercēs, mercēdis","headword":"mercēs","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) hire, pay, wages; fee, wages; pay, wage; goods, merchandise; rent, wage, pay; goods, cargo; merchandise, goods, cargo","forms":["mercēde","mercēdem","mercēdis","mercēs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Kalendīs {{mercēdem}} accipiō ā discipulīs.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mercor","latin":"mercor, mercari, mercatus sum","headword":"mercor","letter":"m","pos":"verb","posGroup":"verb","english":"trade; buy","forms":["mercārī","mercātur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tarquinius ōre iam sēriō atque attentiōre animō fit, eam cōnstantiam cōnfīdentiamque nōn īnsuper habendam intellegit: librōs trēs reliquōs {{mercātur}} nihilo minōre pretiō quam quod erat petītum prō omnibus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mercurius","latin":"Mercurius, -iī","headword":"Mercurius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mercury","forms":["Mercuriī","Mercuriō","Mercurium","Mercurius","MERCVRIVS"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Mercurius}} tamen, malō hoc cōnsiliō cognitō, aureum arietem, quī duās ālās habēbat, dē caelō mīsit; quī, prīmum ad eum locum pervēnit, ubi puer et puella habitābant, ā Phrixō cōnspectus est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mereo","latin":"mereo, merere, merui, meritus","headword":"mereo","letter":"m","pos":"verb","posGroup":"verb","english":"earn; deserve/merit/have right; win/gain/incur; earn soldier/whore pay, serve","forms":["merēbat","merēret","meret","meruēre","meruerit","meruērunt","meruī","meruisse","meruisset","meruistī","meruit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Egone hoc meruī?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mereor","latin":"mereor, -ērī, meritus sum","headword":"mereor","letter":"m","pos":"verb","posGroup":"verb","english":"to deserve, earn","forms":["merentēs","meritam","meritās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille vērō, eōrum precibus minimē mōtus, iīs ut abīrent īrātus imperāvit, dīcēns ‘sē neque Rōmānōs, ā quibus tam indignē pulsus erat, iam amāre, neque dē patriā, quae suōs fīliōs laudem ac glōriam {{merentēs}} tam turpiter ē fīnibus ēiceret, multum cūrāre’; immō dīxit ‘eam nē nōmine quidem patriae dignam esse’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"merere","latin":"(mereō) merēre, meruisse, meritum","headword":"merēre","letter":"m","pos":"verb","posGroup":"verb","english":"earn, deserve; to deserve, earn","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"meretrix","latin":"meretrix, meretricis","headword":"meretrix","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"courtesan, kept woman; public prostitute; harlot","forms":["meretrīcibus","meretrīcum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"435 Nōn mihi, sacrilegās {{meretrīcum}} ut persequar artēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mergere","latin":"mergere","headword":"mergere","letter":"m","pos":"verb","posGroup":"verb","english":"to sink, plunge","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mergit","latin":"mergit, mergere","headword":"mergit","letter":"m","pos":"verb","posGroup":"verb","english":"dip, plunge, sink; plunges, dips; sinks, plunges","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mergo","latin":"mergo, mergere, mersi, mersus","headword":"mergo","letter":"m","pos":"verb","posGroup":"verb","english":"dip, plunge, immerse; sink, drown, bury; overwhelm","forms":["Merge","mergēminī","mergerēmur","mergerentur","mergerētur","mergeris","mergētur","mergī","mergimur","mergit","mergitur","mergor","merguntur","mersae","mersī","mersit","mersōs","mersum","mersus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Et vēnērunt sociī et implēvērunt ambās nāvēs ita ut paene {{mergerentur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mergor","latin":"mergor","headword":"mergor","letter":"m","pos":"verb","posGroup":"verb","english":"be sunk, be drowned","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"meridies","latin":"merīdiēs, -ēī","headword":"merīdiēs","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) midday, noon, south; midday, noon; south; midday","forms":["meridie","merīdiem","meridies"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut {{meridie}} conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"merito","latin":"merito","headword":"merito","letter":"m","pos":"adverb","posGroup":"adverb","english":"deservedly; rightly","forms":["meritō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc coepērunt inter sē dīcere: meritō haec patimur; crūdēlēs fuimus in frātrem nostrum; nunc poenam huius sceleris luimus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"meritum","latin":"meritum, -ī","headword":"meritum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"merit; service, merit","forms":["merita","meritī","meritis","meritum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos {{merita}} exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"meritus","latin":"meritus, merita, meritum","headword":"meritus","letter":"m","pos":"adjective","posGroup":"adjective","english":"deserved, due","forms":["meritus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Horātius, etsī tam bene dē patriā {{meritus}} erat, tamen in iūs ad rēgem raptus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"merso","latin":"merso, mersare, mersavi, mersatus","headword":"merso","letter":"m","pos":"verb","posGroup":"verb","english":"dip (in), immerse; overwhelm, drown","forms":["mersa"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hellē autem dēspiciēns magnōs flūctūs Īnfrā sē vīdit; puella perterrita dē arietis dorsō dēlāpsa est; dum vērō cadit, “Ō frāter,” clāmāvit, “ōrō tē ut auxilium mihi ferās!” Deinde, quatiēns bracchia et crūra dē summō caelō in mare cecidit ac {{mersa}} est, neque frāter eam servāre potuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"merum","latin":"merum, -ī","headword":"merum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"unmixed wine; pure, unmixed wine","forms":["merum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Rōmānī vīnum cum aquā miscent neque vīnum {{merum}} bibere solent.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"merus","latin":"merus, -a, -um","headword":"merus","letter":"m","pos":"adjective","posGroup":"adjective","english":"unmixed, pure; pure, undiluted","forms":["mera","merae","mere","merī","merō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"At subitō Centaurī, plūrima merī pōcula funditus exhauserant, multō vīnō ēbriī, mēnsās humī prōiecērunt et tōtum convīvium turbāre coepērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"merx","latin":"merx, mercis","headword":"merx","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) commodity, pl. goods; goods, merchandise","forms":["mercibus","mercium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum prīmum Orpfieus respicit, Eurydicē ad Īnferōs iterum trafiitur Hominēs magnī aestimāvērunt illud deae beneficium, quō maximā laetitiā affectī sunt, cum vidērent sē, agrōs colendō, nōn sōlum facilius līberōs et uxōrēs cotīdiē alere, vērum etiam tantam frūmentī cōpiam colligere posse, ut aliīs hominibus vēnderent aut cum aliīs {{mercibus}} ad vītam necessāriīs commūtārent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mese","latin":"mese, meses","headword":"mese","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"highest tetrachord note; middle-note (L+S); A-note; notes (pl.) above lowest","forms":["MESĒ"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"quàs illā *īnspiciās!', sapere ut videāre, MESĒ,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"messis","latin":"messis, messis","headword":"messis","letter":"m","pos":"noun","posGroup":"noun","english":"harvest, crop; harvest time","forms":["messis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tunc forte {{messis}} mātūra erat: ita facile incendium fuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"meta","latin":"mēta, -ae","headword":"mēta","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"goal, post","forms":["mētā","mētam","metās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Atalanta intereā tam celeriter cucurrit ad {{mētam}}, quō prīma pervēnit, ut ālae in pedibus eius esse vidērentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"metallum","latin":"metallum, -ī","headword":"metallum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"metal","forms":["metalla","metallīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēgia Phoebī, Sōlis deī, cuius tēctum eburneum altissimīs ā columnīs sustinēbātur, lūcēbat tōta, cum ex pūrissimō aurō aliīsque {{metallīs}} ignem imitantibus facta esset; forēs atque fenestrae argenteae clārissimē splendēbant; at opus, quod Vulcānus arte suā in iānuīs cōnfēcerat, māteriam pretiōsam superābat: nam illīc caelāverat maria, quae cingunt terrās,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"metari","latin":"(mētor) mētārī","headword":"mētārī","letter":"m","pos":"","posGroup":"other","english":"measure off, lay out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"metere","latin":"(metō) metere, messuisse, messum","headword":"metere","letter":"m","pos":"verb","posGroup":"verb","english":"reap, harvest; to reap, harvest","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"methodus","latin":"methodus, methodi","headword":"methodus","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"method; mode of proceeding; way of teaching (L+S); road (Latham)","forms":["methodi"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn minus et Trimalchiô eiusmodî {{methodi}}ô laetus “Carpe!” inquit. essedärius Prôcessit statim scissor, et ad _, cerâvit obsônium, ut putārēs Ā’ ' essedärium hydraulē cantante Ingerēbat nihilô minus Trimal- chiô lentissimä vôce: “Carpe!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"metior","latin":"metior, metiri, mensus sum","headword":"metior","letter":"m","pos":"verb","posGroup":"verb","english":"measure, estimate; distribute, mete; traverse, sail/walk through","forms":["metientibus","metiri","mētītur","metiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, viritim distribuit; frumentum parce et paulatim {{metiri}} instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"metiri","latin":"(mētior) mētīrī","headword":"mētīrī","letter":"m","pos":"","posGroup":"other","english":"measure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"metit","latin":"mētit","headword":"mētit","letter":"m","pos":"verb","posGroup":"verb","english":"reaps, harvests","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"meto","latin":"meto, metere, messui, messus","headword":"meto","letter":"m","pos":"verb","posGroup":"verb","english":"reap; mow, cut off","forms":["messuerant","messum","mete","metēbant","metere","mētit","metunt","metuntur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Agricolae vērō, quī frūmentum in campīs {{metēbant}}, postquam eam cōnspexērunt ad lacum currentem: “Abī!” clāmāvērunt, “Nōli aquae appropinquāre!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"metor","latin":"metor, metari, metatus sum","headword":"metor","letter":"m","pos":"verb","posGroup":"verb","english":"measure off, mark out","forms":["mētārī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quaerentī deinde 'quem secundum pōneret?' 'Pyrrhum' inquit, 'castra mētārī prīmum docuisse, ad hoc nēminem loca ēlegantius cēpisse, praesidia dispōsuisse.' Exsequentī 'quem tertium dīceret?' 'sēmet ipsum' dīxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"metuens","latin":"metuens, metuentis (gen.), metuentior -or -us, -","headword":"metuens","letter":"m","pos":"adjective","posGroup":"adjective","english":"fearing; afraid","forms":["metuēns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Silvam vērō ipsam ingredī numquam ausa erat, {{metuēns}} nē ferae sē caperent nēve ab iīs vorārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"metuit","latin":"metuit, metuere","headword":"metuit","letter":"m","pos":"verb","posGroup":"verb","english":"fear; fears; fears, is afraid of","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"metuo","latin":"metuō, -ere, -uī, -ūtum","headword":"metuō","letter":"m","pos":"verb","posGroup":"verb","english":"fear, be afraid","forms":["metuant","metuat","metuēbant","metuēbat","metuendum","metuendus","metuentēs","metuerat","metuere","metuerent","metuerēs","metueret","metueritis","metuis","metuit","metuitur","metuō","metuunt","metuuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aemilia: “Quia tē atque cultrum tuum {{metuit}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"metus","latin":"metus, metūs","headword":"metus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"fear","forms":["metu","metuī","metum","metus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam converteret, ut ne {{metu}} quidem necessario faciendum existimabat, cum infamia atque indignitas rei et oppositus mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"meus","latin":"meus, -a, -um","headword":"meus","letter":"m","pos":"adjective","posGroup":"adjective","english":"my, mine; my","forms":["mea","meae","meam","meārum","meās","meis","meōrum","meōs","meum","meus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Haec ab ipsis cognoscite qui ex ipsa caede fugerunt; nam ego fratribus atque omnibus {{meis}} propinquis interfectis dolore prohibeor quae gesta sunt pronuntiare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mezentius","latin":"Mezentius, Mezentii","headword":"Mezentius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mezentius; (exiled Etruscan king, ally of Turnus, killed by Aeneas)","forms":["Mezentius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Mezentius}}, quī iam inde ab initiō minimē laetus fuerat orīgine novae urbis, et tum opēs Latīnōrum nimium crēscere rēbātur, statim societātem cum Rutulīs iūnxit Latīnīsque bellum intulit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mi","latin":"mī","headword":"mī","letter":"m","pos":"","posGroup":"other","english":"vocative of meus","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"micans","latin":"micans, (gen.), micantis","headword":"micans","letter":"m","pos":"adjective","posGroup":"adjective","english":"flashing, gleaming, sparkling, twinkling, glittering","forms":["micante","micantēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"pulsantur trepidī corde {{micante}} sinūs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"micare","latin":"(micō) micāre","headword":"micāre","letter":"m","pos":"","posGroup":"other","english":"flicker, flash","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"mico","latin":"mico, micare, micui, -","headword":"mico","letter":"m","pos":"verb","posGroup":"verb","english":"vibrate, quiver, twinkle; tremble, throb; beat (pulse); dart, flash, glitter","forms":["micant","micāre","micat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Coepērunt exaudīrī tonitrua, {{micāre}} fulgura: nūbēs dēnsa operiēbat montem, et clangor buccinae vehementius perstrepēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"midas","latin":"Mīdās, -ae","headword":"Mīdās","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Midas (king of Phrygia)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"migrare","latin":"(migrō) migrāre","headword":"migrāre","letter":"m","pos":"verb","posGroup":"verb","english":"move, migrate; to move, migrate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"migro","latin":"migro, migrare, migravi, migratus","headword":"migro","letter":"m","pos":"verb","posGroup":"verb","english":"transport; move; change residence/condition; go away; depart; remove","forms":["migrandī","migrandum","migrantium","migrāvērunt","migrāvit","migrō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"mea vī subāctā'st facere.—Ego in caelum migrō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"mihi","latin":"mihi","headword":"mihi","letter":"m","pos":"pronoun","posGroup":"pronoun","english":"me, myself (dat.); to me, for me (dative)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"miles","latin":"mīles, mīlitis","headword":"mīles","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) soldier","forms":["mīles","mīlite","mīlitem","milites","mīlitī","militibus","mīlitis","militum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum {{militum}} ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"milia","latin":"mīlia, mīlium","headword":"mīlia","letter":"m","pos":"","posGroup":"other","english":"(n.) thousand","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"miliarium","latin":"mīliārium, -ī","headword":"mīliārium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"milestone","forms":["mīliāriō","mīliārium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rōmānōs saepe vīcit, usque ad quīntum {{mīliārium}} urbis accessit, oppugnātūrus etiam patriam suam (lēgātīs quī pācem petēbant repudiātīs), nisi ad eum māter Veturia et uxor Volumnia ex urbe vēnissent, quārum flētū et dēprecātiōne superātus remōvit exercitum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"militans","latin":"militans, militantis","headword":"militans","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"military man; soldier, warrior","forms":["mīlitāns","mīlitantem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cūr virum innoxium tibi {{mīlitantem}} gladiō hostium interfēcistī?” Hīs prophētae verbīs mōtus Dāvīd culpam agnōvit et cōnfessus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"militari","latin":"militari, militariis","headword":"militari","letter":"m","pos":"noun","posGroup":"noun","english":"knighthood (pl.)","forms":["mīlitārī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Epistulae quās pater ad fīlium dat praecipuē dē glōriā et virtūte sunt, sed ex iīs litterīs prīvātīs quās Aemilia nūper ā frātre suō accēpit plānē appāret eum iam vītā mīlitārī fatīgātum esse.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"militaris","latin":"mīlitāris, -e","headword":"mīlitāris","letter":"m","pos":"adjective","posGroup":"adjective","english":"military","forms":["mīlitāre","mīlitārem","mīlitārēs","militaria","militaribus","militaris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis {{militaribus}} signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"militat","latin":"mīlitat, mīlitāre","headword":"mīlitat","letter":"m","pos":"","posGroup":"other","english":"serve as a soldier","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"militia","latin":"mīlitia, -ae","headword":"mīlitia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"military service; military service, warfare","forms":["mīlitia","mīlitiae","militiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo tuta, neu suis sint ad detrectandam {{militiam}} receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"milito","latin":"milito, militare, militavi, militatus","headword":"milito","letter":"m","pos":"verb","posGroup":"verb","english":"serve as soldier, perform military service, serve in the army; wage/make war","forms":["mīlitandō","mīlitant","mīlitārent","mīlitāverat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In exercitibus Rōmānīs etiam Hispānī et Gallī multī {{mīlitant}}, quī et alia arma et arcūs sagittāsque ferunt.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"milium","latin":"milium, milii","headword":"milium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"millet","forms":["milium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est {{milium}} passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mille","latin":"mīlle","headword":"mīlle","letter":"m","pos":"numeral","posGroup":"numeral","english":"one thousand; a thousand","forms":["milia","milibus","mille"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vercingetorix minoribus Caesarem itineribus subsequitur et locum castris deligit paludibus silvisque munitum ab Avarico longe {{milia}} passuum XVI.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mina","latin":"mina, minae","headword":"mina","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Greek weight unit (100 drachma/one pound); its weight of silver (1/60 talent)","forms":["mina","minam","minās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"parva tibi dabitur vōcisque brevissimus ūsus!” Rēque {{minās}} firmat: tantum haec in fīne loquendī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"minae","latin":"minae, -ārum (pl.)","headword":"minae","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"threats","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"minari","latin":"(minor) minārī, minātum","headword":"minārī","letter":"m","pos":"verb","posGroup":"verb","english":"threaten; to threaten (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"mineo","latin":"mineo, minere, -, -","headword":"mineo","letter":"m","pos":"verb","posGroup":"verb","english":"project, overhang","forms":["mīnēant"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et nihil é{{mīnēant}} et sint sine sordibus unguēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"minerva","latin":"Minerva, -ae","headword":"Minerva","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Minerva (a goddess)","forms":["Minerva","Minervae","Minervam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deōrum quisque, Iove iubente, fōrmōsissimae virginī ita cōnfectae aliquod dēdit dōnum, ut illa hominēs allicere posset: {{Minerva}} enim pulcherrima ōmāmenta eī dōnāvit, Mercurius vēro cōnsilia, quibus hominum animōs falleret, aliī aliās rēs dedērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"minime","latin":"minimē","headword":"minimē","letter":"m","pos":"adverb","posGroup":"adverb","english":"not at all; very little; least; not in the least, not at all","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"minimus","latin":"minimus, -a, -um","headword":"minimus","letter":"m","pos":"adjective","posGroup":"adjective","english":"smallest; very small, very little","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"minister","latin":"minister, -rī","headword":"minister","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"attendant (cf.magister); servant, attendant; servant, waiter; attendant, priest","forms":["minister","ministrī","ministrīs","ministrōrum","ministrōs","ministrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erant in eōdem carcere duo ministrī rēgis Pharaōnis: alter praeerat pincernīs, alter pistōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ministerium","latin":"ministerium, -ī","headword":"ministerium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"office of a minister, ministry, service","forms":["ministerium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam in portū nāvis nōn inventa est, vagātus Perseus aliquamdiū in lītore, postrēmō timēns lūcem iam appropinquantem, in hospitium redīre nōn ausus, in latere templī prope angulum obscūrum dēlituit. 'Puerī rēgiī' apud Macedonas vocābantur prīncipum līberī ad {{ministerium}} ēlēctī rēgis; ea cohors persecūta rēgem fugientem nē tum quidem abscēdēbat — dōnec iussū Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ministra","latin":"ministra, -ae","headword":"ministra","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"female servant","forms":["ministra","ministrae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"nōtās : litterás accipiat missās apta {{ministra}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ministro","latin":"ministro, ministrare, ministravi, ministratus","headword":"ministro","letter":"m","pos":"verb","posGroup":"verb","english":"attend (to), serve, furnish; supply","forms":["ministrābat","ministrant","ministrantibus","ministrārent","ministrāret","ministrātur","ministrāvit","ministrēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc addūxit māter ad sacerdōtem, et obtulit Dominō, ut eī in sacrificiīs faciendīs {{ministrāret}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"minitabundus","latin":"minitabundus, minitabunda, minitabundum","headword":"minitabundus","letter":"m","pos":"adjective","posGroup":"adjective","english":"threatening","forms":["minitābundus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cernēbātur contrā {{minitābundus}} Arminius ‘proeliumque’ dēnūntiāns — nam plēraque Latīnō sermōne interiaciēbat, ut quī Rōmānīs in castrīs ductor populārium meruisset.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"minitari","latin":"(minitor) minitārī","headword":"minitārī","letter":"m","pos":"","posGroup":"other","english":"threaten","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"minitor","latin":"minitor, minitari, minitatus sum","headword":"minitor","letter":"m","pos":"verb","posGroup":"verb","english":"threaten (to), use threats; constitute a danger/threat; hold out as a threat","forms":["minitābātur","minitāns","minitantem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rēx Assyriōrum bellum Ezechiae intulit: Hierosolymam obsidiōne cīnxit, {{minitāns}} urbis excidium, nisi cīvēs matlirā dēditiōne sibi cōnsulerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"minor","latin":"minor, minus","headword":"minor","letter":"m","pos":"adjective","posGroup":"adjective","english":"smaller","forms":["minābantur","minābātur","minante","minantī","minantur","minarī","minātur","minātus","minēre","minor"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Mē quoque dēlectat domus nostra, quamquam {{minor}} est quam aliae domūs nec signīs deōrum ōrnātur.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"minos","latin":"Mīnōs","headword":"Mīnōs","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Minos, king of Crete","forms":["mīne","minīs","Mīnōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quem Antiochus coepit illicere ut lēgem dēsereret, affirmāns eum dīvitem fore et beātum; sed adulēscēns nec {{minīs}} movēbātur, nec prōmissīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"minotaurus","latin":"Mīnōtaurus, -ī","headword":"Mīnōtaurus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"the Minotaur","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"minuo","latin":"minuō, minuere","headword":"minuō","letter":"m","pos":"verb","posGroup":"verb","english":"diminish","forms":["minuēbat","minuēbātur","minuendam","minuere","minuisse","minuit","minuitur","minūtīs","minuunt","minuuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque ut reliquorum imperatorum res adversae auctoritatem {{minuunt}}, sic huius ex contrario dignitas incommodo accepto in dies augebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"minus","latin":"minus","headword":"minus","letter":"m","pos":"adverb","posGroup":"adverb","english":"less","forms":["minus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nec {{minus}} quam est pollicitus Vercingetorix animo laborabat ut reliquas civitates adiungeret, atque eas donis pollicitationibusque alliciebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"minutalis","latin":"minutalis, minutalis, minutale","headword":"minutalis","letter":"m","pos":"adjective","posGroup":"adjective","english":"of minutes","forms":["minūtālia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec tamen in triclîniô ūllum Vetuî facere quod sē omnia forās parāta sunt: aqua, lasanî et cētera {{minūtālia}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"minutus","latin":"minutus, minuta, minutum","headword":"minutus","letter":"m","pos":"adjective","posGroup":"adjective","english":"small, insignificant, petty","forms":["minūtus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Iam pistôribus collūdunt: “Servā mē, serväbô tē!” Itaque populus {{minūtus}} labôrat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"mirabile","latin":"mirabile, mirabilis","headword":"mirabile","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"miracle; wondrous deed; wonders (pl. Ecc); wonderful things; marvelous works","forms":["mīrābile"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Orpheus nōbilissimus fidicen atque poēta ēgregius fuit, quī inde ā puerō tam pulchrē canēbat, ut nōn sōlum bēstiae ferae ad eum accurrerent, vērum etiam rapida flūmina cōnsisterent, nē strepitū cantum eius turbārent, ac saxa ipsa arborēsque ({{mīrābile}} vīsū!) ad audiendum venīrent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mirabilis","latin":"mīrābilis, -e","headword":"mīrābilis","letter":"m","pos":"adjective","posGroup":"adjective","english":"wonderful, marvelous; wonderful, marvellous","forms":["mirābilem","mīrābilēs","mīrābilī","mīrābilia","mīrābilibus","mīrābilis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Pygmaliōn arte suā multās rēs {{mīrābilēs}} cōnfēcerat, quās plūrimī hominēs valdē admīrābantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mirabiliter","latin":"mirabiliter, mirabilius, mirabilissime","headword":"mirabiliter","letter":"m","pos":"adverb","posGroup":"adverb","english":"marvelously, amazingly/remarkably/extraordinarily; to an extraordinary degree","forms":["mīrābiliter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Fuērunt et tō- mäculā ferventia suprā crätîculam argenteam posita, et înfrä crätîcu- lam Syriaca prūna cum gränîs [Trimalchiô accumbit {{mīrābiliter}} exôrnätus] 32 In hîs erāmus lautitiîs, cum ipse Trimalchiô ad sym- phôniam allātus est, positus- que inter cervîcälia minūtīs- sīma expressit imprūdentibus rîsum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"mirabundus","latin":"mīrābundus, -a, -um","headword":"mīrābundus","letter":"m","pos":"adjective","posGroup":"adjective","english":"wondering, full of wonder","forms":["mīrābundī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vix satis crēdere sē quisque audīsse, et aliī aliōs intuērī mīrābundī velut ad somnī vānam speciem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"miraculo","latin":"miraculo","headword":"miraculo","letter":"m","pos":"adverb","posGroup":"adverb","english":"wonderfully","forms":["mīrāculō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Līberābis populum tuum ā servitūte Madianitārum.” Nōlēbat prīmō Gedeōn tantum onus suscipere, sed duplicī mīrāculō cōnfirmātus nōn abnuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"miraculum","latin":"mīrāculum, -ī","headword":"mīrāculum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"marvel; miracle, wonder; wonder, miracle","forms":["mīrāculum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed post cēnam duo, senex et coniūnx, {{mīrāculum}} vīdērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mirari","latin":"(mīror) mīrārī, mīrātum","headword":"mīrārī","letter":"m","pos":"verb","posGroup":"verb","english":"wonder at; to wonder at, be surprised; to wonder at, admire","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"miratur","latin":"mīrātur","headword":"mīrātur","letter":"m","pos":"verb","posGroup":"verb","english":"wonders at, admires","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mire","latin":"mire","headword":"mire","letter":"m","pos":"adverb","posGroup":"adverb","english":"uncommonly, marvelously; in an amazing manner; to a remarkable extent","forms":["mīrē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Intereā mīrē auxit rem suam, et factus est dīves.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"miro","latin":"miro, mirare, miravi, miratus","headword":"miro","letter":"m","pos":"verb","posGroup":"verb","english":"be amazed/surprised/bewildered (at); look in wonder/awe/admiration at","forms":["mīrō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"coniugis antīquī, mīrō quod honōre colēbat,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"miror","latin":"miror, mirari, miratus sum","headword":"miror","letter":"m","pos":"verb","posGroup":"verb","english":"be amazed/surprised/bewildered (at); look in wonder/awe/admiration at","forms":["mīrābantur","Mīrābar","mīrābātur","mīrāmur","mīranda","mīrāns","mīrantēs","mīrantī","mīrantia","mīrantium","mīrantur","mīrārer","mīrārī","mīrāris","mīrāta","mīrātae","mīrātī","mīrātur","mīrātus","mīrer","mīror"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cui Isaacus {{mīrāns}} dīxit: quis est ergō ille quī modo attulit mihi cibum, et cui apprecātus sum omnia fausta, tamquam prīmōgenitō?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mirus","latin":"mīrus, -a, -um","headword":"mīrus","letter":"m","pos":"adjective","posGroup":"adjective","english":"surprising, strange; wonderful, amazing","forms":["mīra","mīrae","mīrīs","mīrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Intereā posterī Iacobī, seu Hebraeī, numerō auctī sunt {{mīrum}} in modum, et eōrum multitūdō crēscēns in diēs metum incutiēbat Aegyptiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"miscellaneum","latin":"miscellaneum, miscellanei","headword":"miscellaneum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"hash (pl.), hotchpotch","forms":["miscellānea"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Et nē mē pūtētis nesapium esse, valdē bene sciô unde prîmum Corinthea nāta sint: Cum Îlium captum est, Hān- nibal, homô vafer et magnus stëliô, omnēs statuās aēneās et aureās et argenteās in ūnum rogum congessit et eâs in- cendit: factae sunt in ūnum āera {{miscellānea}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"misceo","latin":"misceō, -ēre, -uī, mixtum","headword":"misceō","letter":"m","pos":"verb","posGroup":"verb","english":"mix, mingle","forms":["Miscē","misceat","miscent","misceō","miscēre","miscērī","miscet","miscētur","miscuit","mixta","mixtae","mixtās","mixtīs","mixtum","mixtus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Inerat huic cibō gustus similiae cum melle {{mixtae}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"miscere","latin":"(misceō) miscēre, miscuisse, mixtum","headword":"miscēre","letter":"m","pos":"verb","posGroup":"verb","english":"mix; to mix","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"misellus","latin":"misellus, -a, -um","headword":"misellus","letter":"m","pos":"adjective","posGroup":"adjective","english":"poor, wretched; poor little","forms":["miselle","misello"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qui, cum Quintus heri de alta arbore cecidisset, pedem eius turgidum vix tetigit, sed {{misello}} puero sanguinem misit!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"miser","latin":"miser, misera, miserum","headword":"miser","letter":"m","pos":"adjective","posGroup":"adjective","english":"wretched; wretched, unhappy; wretched, unhappy, miserable","forms":["miser","misera","miserae","miserārum","miserī","miserior","miserius","miserōrum","miserōs","miserrima","miserrimē","miserrimus","miserum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa: “Nūlla fēmina mē {{miserior}} vīvit, Sanniō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"miserabilis","latin":"miserābilis, -e","headword":"miserābilis","letter":"m","pos":"adjective","posGroup":"adjective","english":"pitiable; pitiful, wretched","forms":["miserābile","miserābilēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ultima cōnscendit classem — {{miserābile}} vīsū! — in mediīs Hecuba nātōrum inventa sepulcrīs: [eam] prensantem tumulōs atque ossibus ōscula dantem Graecōrum trāxēre manūs, tamen ūnius hausit inque sinū cinerēs sēcum tulit Hectoris haustōs; Hectoris in tumulō crīnem lacrimāsque relīquit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"miserandus","latin":"miserandus, miseranda, miserandum","headword":"miserandus","letter":"m","pos":"adjective","posGroup":"adjective","english":"pitiable, unfortunate","forms":["miserandō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed cavē frūstrā miserandō exiguum tempus ē manibus hostium ēvādendī absūmās!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"miserari","latin":"(miseror) miserārī","headword":"miserārī","letter":"m","pos":"","posGroup":"other","english":"feel sorry for, pity","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"miseratio","latin":"miserātiō, -ōnis ( f.)","headword":"miserātiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"compassion, pity; pity","forms":["miserātiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed postquam Persea cōnsulī 'rēgem Paulō salūtem' lēgisset, {{miserātiōnem}} omnem stultitia ignōrantis fortūnam suam exēmit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"misere","latin":"misere","headword":"misere","letter":"m","pos":"adverb","posGroup":"adverb","english":"wretchedly, desperately","forms":["miserē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post hunc Ochosiās fīlius rēgnum adeptus est, nec diū tenuit, nam pessimī p ātrīs exemplō ad vitia impulsūs, miserē interiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"misereor","latin":"misereor, -ērī, miseritus sum","headword":"misereor","letter":"m","pos":"verb","posGroup":"verb","english":"to pity (+ gen.)","forms":["Misereāminī","misereātur","miserēbitur","miserentur","miserēre","miserita"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aperta fiscella, cernēns parvulum vāgientem, {{miserita}} est illīus: “Iste est” inquit “ūnus ex īnfantibus Hebraeōrum.” Tunc soror puerī accēdēns: “Vīsne” ait “ut arcessam mulierem Hebraeam, quae nūtriat parvulum?” et tunc vocāvit mātrem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"misereri","latin":"(misereor) miserērī, miseritum","headword":"miserērī","letter":"m","pos":"","posGroup":"other","english":"feel pity for","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"miseria","latin":"miseria, -ae","headword":"miseria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"misfortune, misery","forms":["miseriae","miseriam","miseriās","miseriīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nisi gēns nostra in Deum peccāvisset, numquam in hās {{miseriās}} incīdissēmus; sed mox Deus, meō frātrumque meōrum sanguine plācātus, genfī nostrae reconciliābitur, et nōs post mortem patienter tolerātam aetēma vlta dōnābit.\"Tum Antiochus indignē ferēns sē dērīsum esse, in illum exquīsītō suppliciō necāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"misericordia","latin":"misericordia, -ae","headword":"misericordia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"pity; pity, mercy; pity, compassion","forms":["misericordia","misericordiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Datur petentibus venia, dissuadente primo Vercingetorige, post concedente et precibus ipsorum et {{misericordia}} vulgi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"misericors","latin":"misericors, (gen.), misericordis","headword":"misericors","letter":"m","pos":"adjective","posGroup":"adjective","english":"merciful, tenderhearted","forms":["misericordēs","misericors"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ēstatē {{misericordēs}} sīcut et P āter vester misericors est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"misero","latin":"misero, miserare, miseravi, miseratus","headword":"misero","letter":"m","pos":"verb","posGroup":"verb","english":"pity, feel sorry for; view with compassion; (vocal sorrow/compassion)","forms":["miserantur","miserārī","miserāta","miserātī","miserātus","miserō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; {{miserantur}} communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"missa","latin":"missa, missae","headword":"missa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Mass (eccl.)","forms":["missa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam praesidio e regione castrorum relicto et parva manu Metiosedum versus {{missa}}, quae tantum progrediatur quantum naves processissent, reliquas copias contra Labienum duxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"missile","latin":"missile, -is (n.)","headword":"missile","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"missle","forms":["missilibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac prīmō {{missilibus}} submovēre hostem, deinde ad ērumpendum etiam animus erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"missus","latin":"missus, missi","headword":"missus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"messenger; legate","forms":["missus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Interim Lucterius Cadurcus in Rutenos {{missus}} eam civitatem Arvernis conciliat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mithridates","latin":"Mithridates, Mithridatis","headword":"Mithridates","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mithridates; (various kings of Pontus, esp. the Great beaten by Sulla/Pompey)","forms":["Mithridāte","Mithridātem","Mithridātēs","Mithridātī","Mithridātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde Ephesum contendit et per omnem Asiam litterās mīsit 'ut ubicumque inventī essent cīvēs Rōmānī ūnō diē occīderentur!' Intereā etiam Athēnae, cīvitās Achāiae, ab Aristōne Athēniēnsī Mithridātī trādita est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mithridaticus","latin":"Mithridāticus, -a, -um","headword":"Mithridāticus","letter":"m","pos":"adjective","posGroup":"adjective","english":"of Mithridates","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"mitigare","latin":"(mītigō) mītigāre","headword":"mītigāre","letter":"m","pos":"verb","posGroup":"verb","english":"soothe; to soften, calm","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"mitigo","latin":"mitigo, mitigare, mitigavi, mitigatus","headword":"mitigo","letter":"m","pos":"verb","posGroup":"verb","english":"soften; lighten, alleviate; soothe; civilize","forms":["mītigābat","mītigandum","mītigātī","mītigātus","mītigāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Esāüs {{mītigātus}} occurrit obviam Iacobō advenientī; īnsiliit in collum eius, flēnsque ōsculātus est eum, nec quidquam illī nocuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mitis","latin":"mītis, -e","headword":"mītis","letter":"m","pos":"adjective","posGroup":"adjective","english":"gentle, mild, tame; mild, gentle; gentle, mild","forms":["mīte","mītem","miti","mītia","mītis","mitissime","mītissimus","mītius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae tametsi Caesar intellegebat, tamen quam {{mitissime}} potest legatos appellat: nihil se propter inscientiam levitatemque vulgi gravius de civitate iudicare neque de sua in Aeduos benevolentia deminuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mitra","latin":"mitra, mitrae","headword":"mitra","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mitre (bishop/abbot); oriental headband/coif/turban/head-dress; rope/cable","forms":["mitrā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum autem intellēxisset nūllum virum in Pōmōnae hortōs admittī, mitrā in capite positā, membra sustinēns baculō et albōs capillōs sibi addēns simulāvit sē esse ānum","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mittere","latin":"mittere","headword":"mittere","letter":"m","pos":"verb","posGroup":"verb","english":"to send","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"mittit","latin":"mittit","headword":"mittit","letter":"m","pos":"verb","posGroup":"verb","english":"sends","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mitto","latin":"mittō, mittere","headword":"mittō","letter":"m","pos":"verb","posGroup":"verb","english":"send","forms":["miseram","mīserās","miserat","mīserim","miserīs","miserunt","mīsī","misit","missae","missam","missās","missi","missis","missō","missos","missum","missūrum","missūrus","mittam","mittantur","mittar","mittās","mittat","mittātis","mitte","mittēbam","mittēbant","mittēbantur","mittēbās","mittēbat","mittendam","mittendī","mittendum","mittendus","mittere","mitterēmus","mitterent","mitterentur","mitteret","mitterētur","mittet","mitti","mittis","mittit","mittite","mittitis","mittitur","mittō","mittor","mittundum","mittunt","mittuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium Cadurcum, summae hominem audaciae, cum parte copiarum in Rutenos {{mittit}}; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mnestheus","latin":"Mnestheus, Mnesthei","headword":"Mnestheus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Mnestheus; (Trojan companion of Aeneas)","forms":["Mnestheā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mnestheā Sergestumque vocat fortemque Serestum,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"mobilis","latin":"mobilis, mobile, mobilior -or -us, mobilissimus -a -um","headword":"mobilis","letter":"m","pos":"adjective","posGroup":"adjective","english":"movable; mobile; quick, active; changeable, shifting; fickle, easily swayed","forms":["mōbilēs","mōbilis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{mōbilis}} aequoreīs pinnā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mobilitas","latin":"mobilitas, mobilitatis","headword":"mobilitas","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mobility, agility; speed; quickness of mind; inconstancy","forms":["mōbilitās","mōbilitāte"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tantum {{mōbilitās}} illa","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"moderari","latin":"(moderor) moderārī","headword":"moderārī","letter":"m","pos":"","posGroup":"other","english":"temper, moderate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"moderatio","latin":"moderātiō, -ōnis ( f.)","headword":"moderātiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"moderation, restraint","forms":["moderātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed cum cēnserem remissiōne et {{moderātiōne}} vōcis et commūtātō genere dīcendī mē et perīculum vītāre posse et temperātius dīcere, ut cōnsuētūdinem dīcendī mūtārem, ea causa mihi in Asiam proficīscendī fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"moderator","latin":"moderātor, -ōris (m.)","headword":"moderātor","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"ruler, director; ruler, controller","forms":["moderātor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Deinde subter mediam ferē regiōnem Sōl obtinet, dux et prīnceps et {{moderātor}} lūminum reliquōrum, mēns mundī et temperātiō, tantā magnitūdine ut cūncta suā lūce lūstret et compleat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"moderatus","latin":"moderātus, -a, -um","headword":"moderātus","letter":"m","pos":"adjective","posGroup":"adjective","english":"restrained, moderate","forms":["moderātum","moderātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et sānē Gracchīs cupīdine victōriae haud satis {{moderātus}} animus fuit; sed bonō vincī satius est quam malō mōre iniūriam vincere.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"moderor","latin":"moderor, moderari, moderatus sum","headword":"moderor","letter":"m","pos":"verb","posGroup":"verb","english":"guide; control; regulate; govern","forms":["moderābitur","moderārētur","moderari","moderātur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dum haec apud Alesiam geruntur, Galli, concilio principum indicto, non omnes eos qui arma ferre possent, ut censuit Vercingetorix, convocandos statuunt sed certum numerum cuique ex civitate imperandum, ne tanta multitudine confusa nec {{moderari}} nec discernere suos nec frumentationem habere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"modestia","latin":"modestia, -ae","headword":"modestia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"restraint","forms":["modestiae","modestiam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam ut cuiusque studium ex aetāte flagrābat, aliīs scorta praebēre, aliīs canēs atque equōs mercārī, postrēmō neque sūmptuī neque {{modestiae}} suae parcere, dum illōs obnoxiōs fīdōsque sibi faceret.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"modestus","latin":"modestus, -a, -um","headword":"modestus","letter":"m","pos":"adjective","posGroup":"adjective","english":"restrained, modest, calm","forms":["modestō","modestus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{modestus}} -ā -um (€ modus) - mō-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"modicum","latin":"modicum, modici","headword":"modicum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"short/small time; short distance, little way; little, small amount","forms":["modicum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ōdimus (: ōdī) im-{{modicum}} fastwn Ōdimus immodicōs — expertó","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"modicus","latin":"modicus, -a, -um","headword":"modicus","letter":"m","pos":"adjective","posGroup":"adjective","english":"moderate","forms":["modicam","modicī","modicō","modicus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ūnus quī *{{modicam}}' dīceret Hector erat.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"modius","latin":"modius, -ī","headword":"modius","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"a Roman dry meausure, “peck”; peck, a measure of grain","forms":["modiōrum","modiōs","modium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et prôdîsset in medium, decēre gravitātem eius tam humilēs ineptiās! ’ [Âctuärius ācta praediôrum recitat] Et plānē interpellāvit saltätiônis libîdinem āctuārius, 53 quī tamquam urbis âcta recitāvit: VIĪ kalendās Sextîlês: in prae- diô Cūmānä, quod est Trimal- chiônis, nātī sunt puerÏXIOÇ pu- ellae XL; sublāta in horreum ex āreā trīticī mîlia {{modium}} quîn- genta; bovēs domitî quîngentï.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"modo","latin":"modo","headword":"modo","letter":"m","pos":"adverb","posGroup":"adverb","english":"only, just","forms":["modo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam de equitibus hostium quin nemo eorum progredi {{modo}} extra agmen audeat, ipsos quidem non debere dubitare; et quo maiore faciant animo, copias se omnes pro castris habiturum et terrori hostibus futurum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"modus","latin":"modus, -ī","headword":"modus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"manner, way; mood, manner","forms":["modi","modis","modōs","modum","modus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnibus {{modis}} huic rei studendum ut pabulatione et commeatu Romani prohibeantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"moechus","latin":"moechus, moechi","headword":"moechus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"adulterer","forms":["moechō","moechum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"suum esse, quae cum moechō est!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"moene","latin":"moene, moenis","headword":"moene","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"defensive/town walls (pl.), bulwarks; fortifications; fortified town; castle","forms":["moenia","moenibus","moenium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Complūrēs diēs Volscōrum exercitūs ita Rōmānōs intrā urbis {{moenia}} inclūsōs tenuit, ut tandem omnī cibō et aquā cārerent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"moenia","latin":"moenia, moenium","headword":"moenia","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"(n. pl.) walls; walls, fortifications; city walls, ramparts; walls, ramparts","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"moerens","latin":"moerens, (gen.), moerentis","headword":"moerens","letter":"m","pos":"adjective","posGroup":"adjective","english":"sad, melancholy; mournful, gloomy woeful, doleful; mourning, lamenting (L+S)","forms":["moerēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sed Iacobus nōluit accipere cōnsōlātiōnem, dīxitque: ego dēscendam {{moerēns}} cum fīliō meō in sepulcrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"moeror","latin":"moeror, moeroris","headword":"moeror","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"grief, sorrow, sadness; mourning; lamentation (L+S)","forms":["moerōre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc frātrēs Iōsēphī {{moerōre}} oppressī revertuntur in urbem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"moestitia","latin":"moestitia, moestitiae","headword":"moestitia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"sadness, sorrow, grief; source of grief; dullness, gloom","forms":["moestitiae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ad quōs cum vēnisset Iōsēphus māne, et animadvertisset eōs trīstiōrēs solitō, interrogāvit quaenam esset {{moestitiae}} causa.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mola","latin":"mola, molae","headword":"mola","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"millstone; ground meal; mill (pl.) [salsa ~ => salted meal, for sacrifices]","forms":["mola"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sī quis autem scandalizāverit ūnum dē parvulīs isfīs, expedit eī ut suspendiitur {{mola}} collō eius et dēmergātur in profundum mare.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"moles","latin":"mōlēs, -is ( f.)","headword":"mōlēs","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"mass, bulk, effort; mass, huge bulk","forms":["mōle","mōlem","mōlēs","mōlis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"...quārum pars nāre vidētur, pars in {{mōle}} sedēns viridēs siccāre capillōs, pisce vehī quaedam: faciēs nōn omnibus ūna, nōn dīversa tamen, quālem decet esse sorōrum.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"moleste","latin":"moleste, molestius, molestissime","headword":"moleste","letter":"m","pos":"adverb","posGroup":"adverb","english":"annoyingly; in a vexing/annoying/distressing/tiresome manner","forms":["moleste"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Turnus, rēx Rutulōrum, cui Lāvīnia ante adventum Aenēae sponsa fuerat, {{moleste}} patiēns advenam sibi praelātum esse, simul Aenēae Latīnōque bellum intulerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"molestia","latin":"molestia, molestiae","headword":"molestia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"trouble, annoyance","forms":["molestiam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Āmōvī ā foribus maximam {{molestiam}},","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"molestus","latin":"molestus, -a, -um","headword":"molestus","letter":"m","pos":"adjective","posGroup":"adjective","english":"annoying; troublesome, annoying","forms":["molesta","molestī","molestior","molestum","molestus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Num ita {{molesta}} sum tibi, ut abīre mālīs quam mēcum manēre?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"molior","latin":"molior, moliri, molitus sum","headword":"molior","letter":"m","pos":"verb","posGroup":"verb","english":"struggle, labor, labor at; construct, build; undertake, set in motion, plan","forms":["mōlientem","mōlīmur","mōlior","mōlīre","mōlīrentur","mōlīrī","mōlīris","mōlītur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quae tibi placuit! dīcere {{mōlior}}:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"moliri","latin":"(mōlīōr) mōlīrī, mōlītum","headword":"mōlīrī","letter":"m","pos":"","posGroup":"other","english":"labor, strive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"mollio","latin":"molliō, -īre, -īvī, -ītum","headword":"molliō","letter":"m","pos":"verb","posGroup":"verb","english":"make pliant, make soft, soften","forms":["molliam","molliendum","molliet","mollīre","mollīrī","mollīte","mollītum","mollītur","molliuntur","mollīvimus","mollīvisse","mollīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio ascensus recta regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad {{molliendum}} clivum accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mollire","latin":"(molliō) mollīre, mollīvisse,  mollītum","headword":"mollīre","letter":"m","pos":"verb","posGroup":"verb","english":"make soft, soften; to soften","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"mollis","latin":"mollis, molle","headword":"mollis","letter":"m","pos":"adjective","posGroup":"adjective","english":"soft","forms":["mollēs","mollī","mollia","mollibus","mollior","mollis","mollissimā","mollissimam","mollius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Item Mārcus rēs suās tollit atque abīre vult, cum tabulam Sextī in mollī herbā apud viam iacēre videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mollit","latin":"mollit","headword":"mollit","letter":"m","pos":"verb","posGroup":"verb","english":"softens","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"molliter","latin":"molliter, mollius, mollissime","headword":"molliter","letter":"m","pos":"adverb","posGroup":"adverb","english":"calmly/quietly/softly/gently/smoothly/easily; w/out pain/anger/harshness; weakly","forms":["molliter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"bracchia {{molliter}} movet)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mollitia","latin":"mollitia, mollitiae","headword":"mollitia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"softness, tenderness; weakness, effeminacy","forms":["mollitia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Animi est ista {{mollitia}}, non virtus, paulisper inopiam ferre non posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mollities","latin":"mollities, mollitiei","headword":"mollities","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"softness, tenderness; weakness, effeminacy","forms":["mollitiem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Summam imperi se consulto nulli discedentem tradidisse, ne is multitudinis studio ad dimicandum impelleretur; cui rei propter animi {{mollitiem}} studere omnes videret, quod diutius laborem ferre non possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"moly","latin":"moly, molyos/is","headword":"moly","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"plant (white flower and black root) (mythical used by Odysseus against Circe)","forms":["mōly"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pācifer huic dederat flōrem Mercurius album:\n{{mōly}} vocant superī, nigrā rādīce tenētur;\ntūtus eō monitīsque simul caelestibus intrat\nille domum Circēs et ad īnsidiōsa vocātus\npōcula cōnantem virgā mulcēre capillōs\nreppulit et strictō pavidam dēterruit ēnse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"momentum","latin":"mōmentum, -ī","headword":"mōmentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"movement, motion; moment","forms":["mōmenta","momento","momentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ex his Eporedorix cognito Litavicci consilio media fere nocte rem ad Caesarem defert; orat ne patiatur civitatem pravis adulescentium consiliis ab amicitia populi Romani deficere; quod futurum provideat, si se tot hominum milia cum hostibus coniunxerint, quorum salutem neque propinqui neglegere neque civitas levi {{momento}} aestimare posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"moneo","latin":"moneō, -ēre, -uī, -itum","headword":"moneō","letter":"m","pos":"verb","posGroup":"verb","english":"warn, advise","forms":["monē","moneam","monēbant","monēbat","monēmur","monenda","monendī","monent","monentī","monentibus","moneō","moneor","monēre","monērem","monērī","monēs","monet","monitī","monitīs","monitō","monitū","monuerat","monuī","monuisse","monuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc {{monet}} ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"monere","latin":"(moneō) monēre, monuisse, monitum","headword":"monēre","letter":"m","pos":"verb","posGroup":"verb","english":"advise, warn; to warn, advise","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"monet","latin":"monet","headword":"monet","letter":"m","pos":"verb","posGroup":"verb","english":"warns, reminds; warns, advises","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"moneta","latin":"moneta, monetae","headword":"moneta","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"money/coinage; die on which coin is struck, stamp; mint, temple striking coins","forms":["Monētae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In summā arce templum Iūnōnis {{Monētae}} situm est, in quō nummī ē metallīs pretiōsīs, aurō, argentō, aere efficiuntur atque imāginibus prīncipis imprimuntur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"monile","latin":"monile, monilis","headword":"monile","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"necklace, collar; collar (for horses and other animals)","forms":["monīle"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"maxima nātārum Priamī, colloque {{monīle}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"monimentum","latin":"monimentum, monimenti","headword":"monimentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"monument","forms":["monimenta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quaeque soror coniünxque ducīs {{monimenta}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"monitus","latin":"monitus, -ūs","headword":"monitus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"warning, instruction","forms":["monitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Moysēs ā Deō {{monitus}} cōnficī iussit tabernāculum ex pellibus et cortīnīs pretiōsissimīs, īnsuper arcam foederis aurō pūrō vestītam, in quā reposuit tabulās lēgis dīvīnae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mons","latin":"mōns, montis","headword":"mōns","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) mountain","forms":["mons","monte","montem","montēs","montibus","montis","montium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi {{mons}} Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"monstrat","latin":"mōnstrat, mōnstrant","headword":"mōnstrat","letter":"m","pos":"verb","posGroup":"verb","english":"point out, show; points out, shows","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"monstro","latin":"mōnstrō, -āre","headword":"mōnstrō","letter":"m","pos":"verb","posGroup":"verb","english":"show, point out","forms":["mōnstrābit","mōnstrābō","mōnstrandō","mōnstrāns","mōnstrante","mōnstrāre","mōnstrat","mōnstrāta","mōnstrāte","mōnstrātum","mōnstrāvī","mōnstrāvit","mōnstrō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aemilia: “Quās illa puella vēndit.” Puellam digitō {{mōnstrat}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"monstrum","latin":"mōnstrum, -ī","headword":"mōnstrum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"monster; monster, portent","forms":["mōnstra","mōnstrī","mōnstrīs","mōnstrōrum","mōnstrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Efficiam igitur ut pulcherrimus ille taurus, quem tibi largītus eram, in saevum {{mōnstrum}} mūtētur!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"monumentum","latin":"monumentum, -ī","headword":"monumentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"memorial, monument; memorial, reminder","forms":["monumenta","monumentō","monumentum","MONVMENTVM"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum reversae sunt aquae in locum prīstinum; Iosue vērō duodecim lapidēs ē mediō amne sublātōs ērēxit, ut essent perenne reī {{monumentum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mora","latin":"mora, -ae","headword":"mora","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"delay","forms":["morā","morae","moram","morās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Diē septimā cum Samūēl morārētur, et populus {{morae}} pertaesus dīlāberētur, Saūl ipse sacrificium fēcit locō sacerdōtis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"morari","latin":"(moror) morārī","headword":"morārī","letter":"m","pos":"","posGroup":"other","english":"delay, stay, stop","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"moratus","latin":"moratus, morata, moratum","headword":"moratus","letter":"m","pos":"adjective","posGroup":"adjective","english":"endowed with character or manners of a specified kind; gentle, civilized","forms":["morātā","morati","moratus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi {{morati}} neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"morbus","latin":"morbus, -ī","headword":"morbus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"disease, illness","forms":["morbī","morbō","morbum","morbus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Paulō post īnfāns in gravem {{morbum}} incīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mordax","latin":"mordax, (gen.), mordacis","headword":"mordax","letter":"m","pos":"adjective","posGroup":"adjective","english":"biting, snappish; tart; cutting, sharp; caustic","forms":["mordāx"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{mordāx}} -àcīs adī — quī mordet/rādit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mordeo","latin":"mordeō, -ēre, momordī, morsum","headword":"mordeō","letter":"m","pos":"verb","posGroup":"verb","english":"bite","forms":["momordit","mordeat","mordēbit","mordendum","mordēre","mordet","mordētur","morsū","morsum","morsūrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ovem meam {{mordet}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"mordere","latin":"(mordeō) mordēre, momordisse, morsum","headword":"mordēre","letter":"m","pos":"verb","posGroup":"verb","english":"bite; to bite","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mori","latin":"(morior) morī, mortuum","headword":"morī","letter":"m","pos":"verb","posGroup":"verb","english":"die; to die","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"moribundus","latin":"moribundus, -a, -um","headword":"moribundus","letter":"m","pos":"adjective","posGroup":"adjective","english":"dying","forms":["moribunda","moribundam","moribundum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cuī mē {{moribundam}} dēseris?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"morigero","latin":"morigero, morigerare, morigeravi, morigeratus","headword":"morigero","letter":"m","pos":"verb","posGroup":"verb","english":"be compliant/indulgent to; gratify; humor","forms":["mōrigerō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"uxōre nunc mī mōrigerō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"morior","latin":"morior, morī, mortuus sum","headword":"morior","letter":"m","pos":"verb","posGroup":"verb","english":"to die","forms":["morere","morerentur","morerer","morerētur","moriāmur","moriar","moriātur","moriēbantur","moriēbātur","moriēminī","moriēmur","moriendum","moriēns","morientem","morientēs","morientia","morientis","moriēre","moriēris","moriētur","morior","morīrī","moritur","moritūra","moritūrī","moritūrum","moritūrus","moriuntur","mortuum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ergō Mēdus mīlitem {{mortuum}} esse putat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"moror","latin":"moror, morari, moratus sum","headword":"moror","letter":"m","pos":"verb","posGroup":"verb","english":"delay; stay, stay behind; devote attention to","forms":["morabantur","morandī","morantem","morantur","morārētur","morārī","morāris","morātum","moratur","morentur","mōrer","morētur","moror"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis saxis {{morabantur}} moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"morosus","latin":"morosus, morosa, morosum","headword":"morosus","letter":"m","pos":"adjective","posGroup":"adjective","english":"hard to please, persnickety","forms":["morōsā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Illō praecipuē né sīs morōsā cavētō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mors","latin":"mors, mortis","headword":"mors","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) death","forms":["mors","morte","mortem","morti","mortis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis {{morte}}; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"morsus","latin":"morsus, morsus","headword":"morsus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"bite, sting; anguish, pain; jaws; teeth","forms":["morsibus","morsus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quīntus: 'Ego canem iānitōris nōn vereor neque umquam ab eō {{morsus}} sum.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mortalis","latin":"mortālis, -e","headword":"mortālis","letter":"m","pos":"adjective","posGroup":"adjective","english":"mortal","forms":["mortāle","mortālem","mortālēs","mortālia","mortālibus","mortālis","mortālium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Antiochus dolōris acerbitāte victus tandem ad sānam mentem rediit: sē {{mortālem}} esse agnōvit, et recordātus malōrum, quibus IŪdaeōs afrēcerat, apertē cōnfessus est sē suōrum scelerum poenās luere, ac dēmum prōmīsit sē Ilidaēōs flōrentēs beātōsque facrurum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mortifer","latin":"mortifer, mortifera, mortiferum","headword":"mortifer","letter":"m","pos":"adjective","posGroup":"adjective","english":"deadly, fatal, death bringing; destructive","forms":["mortiferīs","mortiferum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hoc {{mortiferum}} venēnum, quod Medea sēcum attulerat, ōlim factum est dē spūmīs albīs quibus Cerberus agrōs lātrātibus sparsit, dum Hercules eum ex Orcō aufert.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mortuus","latin":"mortuus, -a, -um","headword":"mortuus","letter":"m","pos":"adjective","posGroup":"adjective","english":"dead","forms":["mortua","mortuam","mortuās","mortuī","mortuīs","mortuō","mortuōrum","mortuōs","mortuus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mīles autem quiētus in viā iacet ut {{mortuus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"morum","latin":"morum, mori","headword":"morum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"mulberry; fruit of the black mulberry","forms":["mōrum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"déve tribus lībrīs titulō quōs signat 4mōrum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"morus","latin":"morus, mori","headword":"morus","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"black mulberry tree","forms":["mōrus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Arbor est {{mōrus}}, ūberrima pōmīs albīs, vīcīna fontī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mos","latin":"mōs, mōris","headword":"mōs","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"(m.) custom, habit; pl. behavior, morals; custom","forms":["more","mōrem","mōrēs","morī","mōribus","mōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo {{more}} eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"moto","latin":"moto, motare, motavi, motatus","headword":"moto","letter":"m","pos":"verb","posGroup":"verb","english":"set in motion, shake, stir, etc","forms":["mōta","mōtanda"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diāna, sīc invocātā, animō valdē {{mōta}} est; itaque ex altō caelō nūbem in nympham suam immīsit, quā eam occultāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"motus","latin":"mōtus, ūs","headword":"mōtus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"movement, rising","forms":["mōtibus","motu","motum","mōtus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano {{motu}} Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"moveo","latin":"moveo, movere, movi, motus","headword":"moveo","letter":"m","pos":"verb","posGroup":"verb","english":"move, stir, agitate, affect, provoke, disturb; [movere se => dance]","forms":["mōtae","mōtī","mōtīs","mōtōs","moveant","moveāris","moveat","moveātur","movēbant","movēbantur","movēbat","movēbātur","movēbit","movēbunt","movendam","movendī","movent","moventem","moventēs","moventur","moveō","mōverant","mōverat","movēre","moverentur","movēret","movērī","mōvērunt","movēs","movet","movētur","mōvī","movisse","movit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quorum ille precibus permotus castra ex Biturigibus {{movet}} in Arvernos versus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"movere","latin":"movēre","headword":"movēre","letter":"m","pos":"verb","posGroup":"verb","english":"to move, stir","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"movet","latin":"movet, movēre","headword":"movet","letter":"m","pos":"","posGroup":"other","english":"move, stir","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"mox","latin":"mox","headword":"mox","letter":"m","pos":"adverb","posGroup":"adverb","english":"soon, next; soon","forms":["mox"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus: “Adhūc quattuor; sed {{mox}} iī quoque mē relinquent.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"moyses","latin":"Moyses, Moysis","headword":"Moyses","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"Moses","forms":["Moysēs","Moȳsī","Moysis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Moysēs}} iam senex, iubente Deō, adiit pharaōnem, eīque praecēpit nōmine Deī, ut dīmitteret Hebraeōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mugio","latin":"mugio, mugire, mugivi, mugitus","headword":"mugio","letter":"m","pos":"verb","posGroup":"verb","english":"low, bellow; make a loud deep noise","forms":["mūgiēbat","mūgīre","mūgīrent","mūgīvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Taurus {{mūgīvit}}; Eurōpa vērō herbās ex campō carptās taurō dedit, quī eās ēdendō laetābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mugire","latin":"(mūgiō) mūgīre, -īvisse, -ītum","headword":"mūgīre","letter":"m","pos":"","posGroup":"other","english":"low, bellow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"mulceo","latin":"mulceō, -ēre, mulsī, mulsum","headword":"mulceō","letter":"m","pos":"verb","posGroup":"verb","english":"to stroke, soothe","forms":["mulcēre","mulcet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pācifer huic dederat flōrem Mercurius album:\nmōly vocant superī, nigrā rādīce tenētur;\ntūtus eō monitīsque simul caelestibus intrat\nille domum Circēs et ad īnsidiōsa vocātus\npōcula cōnantem virgā {{mulcēre}} capillōs\nreppulit et strictō pavidam dēterruit ēnse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mulciber","latin":"Mulciber, Mulciberis","headword":"Mulciber","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"surname of Vulcan; P:fire","forms":["Mulciber","Mulciberīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Mulciberīs}} captī Màarsque Venusque dolīs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mulcto","latin":"mulcto, mulctare, mulctavi, mulctatus","headword":"mulcto","letter":"m","pos":"verb","posGroup":"verb","english":"punish, fine; extract as forfeit; sentence to pay","forms":["mulctētur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Apud quem fūrtum dēprehēnsum fuerit, is morte {{mulctētur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"muliebris","latin":"muliebris, -e","headword":"muliebris","letter":"m","pos":"adjective","posGroup":"adjective","english":"of a woman","forms":["muliebre","muliebrem","muliebrī","muliebribus","Muliebris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tantum tamen opēs Latīnōrum crēverant — maximē victīs Etrūscīs — ut ne morte quidem Aenēae nec deinde inter rēgnum {{muliebre}} et Ascaniī pueritiam aut Etrūscī aut ūllī aliī fīnitimī arma movēre ausī sint.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mulier","latin":"mulier, mulieris","headword":"mulier","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) woman, wife; woman","forms":["mulier","muliere","mulierem","mulierēs","mulierī","mulieribus","mulieris","mulierum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sic et Cenabi caede et labore operis incitati non aetate confectis, non {{mulieribus}}, non infantibus pepercerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"multa","latin":"multa, multae","headword":"multa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"fine; penalty; penalty involving property (livestock, later money)","forms":["multa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quos ille {{multa}} iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum disparandos deducendosque ad suos curaret, quae cuique civitati pars castrorum ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"multae","latin":"multae","headword":"multae","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"many women (pl.)","forms":["multae"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In Graeciā sunt {{multae}} īnsulae.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"multare","latin":"(multō) multāre","headword":"multāre","letter":"m","pos":"","posGroup":"other","english":"punish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"multi","latin":"multī, -ae, -a","headword":"multī","letter":"m","pos":"adjective","posGroup":"adjective","english":"(pl.) many, a great many; many","forms":["multī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In familiā Iūliī sunt multī servī et paucī līberī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"multiplex","latin":"multiplex, -icis","headword":"multiplex","letter":"m","pos":"adjective","posGroup":"adjective","english":"many-winding, manifold","forms":["multiplicī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mīnōs hunc pudōrem thalamō removēre et eum multiplicī domō sub rēgiam cēlāre cōnstituit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"multitudo","latin":"multitūdō, multitūdinis","headword":"multitūdō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"(f.) large number, multitude","forms":["multitudine","multitudinem","multitudini","multitudinis","multitūdinum","multitudo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae {{multitudinis}} fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"multo","latin":"multo, multare, multavi, multatus","headword":"multo","letter":"m","pos":"verb","posGroup":"verb","english":"punish, fine; extract as forfeit; sentence to pay","forms":["multārī","multatos","multem","multo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, {{multo}} illa gravius aestimare, liberos, coniuges in servitutem abstrahi, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"multum","latin":"multum, -ī","headword":"multum","letter":"m","pos":"adverb","posGroup":"adverb","english":"a lot, a good deal of","forms":["multum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo studio agebant, non {{multum}} adiuvabant, alteri non magnis facultatibus, quod civitas erat exigua et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"multus","latin":"multus","headword":"multus","letter":"m","pos":"adjective","posGroup":"adjective","english":"much, many; much; (pl.) many","forms":["multam","multārum","multās","multis","multōrum","multos","plūrima","plūrimae","plūrimās","plūrimī","plūrimīs","Plūrimō","plūrimōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem {{multis}} ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mulus","latin":"mulus, muli","headword":"mulus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"mule","forms":["mūlō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"munditia","latin":"munditia, munditiae","headword":"munditia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"cleanness, elegance of appearance, manners or taste","forms":["munditia","munditiīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{munditia}} -ae/-ītīēs -ei £ « mundus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mundo","latin":"mundo, mundare, mundavi, mundatus","headword":"mundo","letter":"m","pos":"verb","posGroup":"verb","english":"clean, cleanse, make clean/tidy; (eccl. - ceremonially/spiritually)","forms":["mundō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Postquam deī omnia cētera animālia in mundō posuerant et etiam hominēs ex terrā ūmidā et mollī ignī mixta cōnfēcerant, Epimētheō, Promēthēī frātrī, imperāvērunt ut singulīs animālibus mūnera daret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"mundus","latin":"mundus, -a, -um","headword":"mundus","letter":"m","pos":"adjective; noun (m.)","posGroup":"adjective","english":"clean, neat; world","forms":["munda","mundam","mundī","mundum","mundus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cūr usque ad meam rēgiam iter fēcistī, fīlī mī?” Ille vērō respondit: “Ō Phoebe pater, quī es lūx tōtīus mundī: quīdam, quī fortasse invident mihi, negāvērunt mē fīlium tuum esse: nunc igitur tē orō et rogō ut mihi dubium tollās, et aliquō modō certō dēmōnstrēs ā mē verē et iūre ‘patrem’ tē nōminan posse!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"municipium","latin":"municipium, municipi(i)","headword":"municipium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"municipality, town; town subject to Rome but under its own laws; free town","forms":["mūnicipia","mūnicipiīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cornēlius; ad hōc multī ex colōniīs et {{mūnicipiīs}}, domī nōbilēs.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"munificentia","latin":"munificentia, munificentiae","headword":"munificentia","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"bountifulness, munificence","forms":["mūnificentiā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caesar beneficiīs ac mūnificentiā magnus habēbātur, integritāte vītae Catō.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"munimen","latin":"mūnīmen, -inis","headword":"mūnīmen","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"defence, fortification","forms":["mūnīmina"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nam sī mea facta requīris, hostibus īnsidior, fossā {{mūnīmina}} cingō, cōnsōlor sociōs, ut longī taedia bellī mente ferant placidā, doceō, quō sīmus alendī armandīque modō, mittor, quō postulat ūsus.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"munimentum","latin":"mūnīmentum, -ī","headword":"mūnīmentum","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"fortification","forms":["mūnīmenta","mūnīmentō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Septem mīlia hominum in minōra castra, decem in maiōra, duo fermē in vīcum ipsum Cannās perfūgērunt, quī extemplō ab equitibus, nūllō mūnīmentō tegentī vīcum, circumventī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"munio","latin":"munio, munire, munivi, munitus","headword":"munio","letter":"m","pos":"verb","posGroup":"verb","english":"fortify; strengthen; protect, defend, safeguard; build (road)","forms":["mūniant","mūniendam","munire","mūnīrentur","mūnīrī","munitum","mūniunt","mūniuntur","mūnīvī","mūnīvisse","mūnīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vercingetorix minoribus Caesarem itineribus subsequitur et locum castris deligit paludibus silvisque {{munitum}} ab Avarico longe milia passuum XVI.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"munire","latin":"(mūniō) mūnīre, mūnīvisse,  mūnītum","headword":"mūnīre","letter":"m","pos":"verb","posGroup":"verb","english":"fortify; to fortify; to fortify, build (a wall)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"munitio","latin":"mūnītiō, -ōnis ( f.)","headword":"mūnītiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"fortification","forms":["munitione","munitionem","munitiones","munitionibus","munitionis","munitionum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non {{munitione}} et loci natura ab omni sint periculo tuta, neu suis sint ad detrectandam militiam receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"munitus","latin":"munitus, munita -um, munitior -or -us, munitissimus -a -um","headword":"munitus","letter":"m","pos":"adjective","posGroup":"adjective","english":"defended, fortified; protected, secured, safe","forms":["mūnīta","mūnītae","mūnītam","mūnītī","mūnītissimus","munitos","munitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro {{munitos}} existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"munus","latin":"mūnus, mūneris","headword":"mūnus","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"(n.) service, duty, gift; gift, service; gift, duty, service; gift, duty","forms":["mūnera","munere","mūnerī","mūneribus","mūneris","mūnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo {{munere}} fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"muralis","latin":"muralis, muralis, murale","headword":"muralis","letter":"m","pos":"adjective","posGroup":"adjective","english":"of walls; of a (city) wall; turreted; mural","forms":["muralibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Dum longius ab munitione aberant Galli, plus multitudine telorum proficiebant; postea quam propius successerunt, aut se stimulis inopinantes induebant aut in scrobes delati transfodiebantur aut ex vallo ac turribus traiecti pilis {{muralibus}} interibant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"murena","latin":"murena, murenae","headword":"murena","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"kind of eel, the moray or lamprey","forms":["Mūrēna","Mūrēnam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Triumphāvit Sulla, triumphāvit {{Mūrēna}} dē Mithridāte, duo fortissimī virī et summī imperātōrēs, sed ita triumphārunt ut ille pulsus superātusque rēgnāret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"murex","latin":"murex, muricis","headword":"murex","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"purple fish, shellfish which gave Tyrian dye; purple dye; purple cloth","forms":["mūrex","murice"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi carmen Pānis terminātum est, sacer Tmōlus ōs vertit ad ōs Phoebī, quī gerēbat laurum in capite vestīmentumque longum tīnctum Tyriō {{murice}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"muria","latin":"muria, muriae","headword":"muria","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"brine, salt liquor, pickling","forms":["muriā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Certē ego notävî super mē positum cocum quī dē porcô ānserem fēcerat, muriā cōn- dîmentîsque fētentem.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"murmur","latin":"murmur, -uris (n.)","headword":"murmur","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"mutter, murmur; murmur","forms":["murmur","murmura","murmure"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae simul ārentī sitientēs hausimus ōre,\net tetigit summōs virgā dea dīra capillōs,\n(et pudet et referam) saetīs horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\n{{murmur}} et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla tumēre torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"murmuro","latin":"murmurō (1)","headword":"murmurō","letter":"m","pos":"verb","posGroup":"verb","english":"murmur","forms":["murmurābant","murmurant"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pyramus stābat hinc, illinc Thisbē, et per fissum verba mollia {{murmurābant}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"murus","latin":"mūrus, -ī","headword":"mūrus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"wall","forms":["muri","mūrīs","muro","mūrōrum","muros","murum","murus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut {{muro}} munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"mus","latin":"mus, muris","headword":"mus","letter":"m","pos":"noun","posGroup":"noun","english":"mouse","forms":["mūrem","mūrēs","mus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Noë{{mus}} ipse ingressus est in arcam cum coniuge, tribus fīliīs et totidem nuribus, aquā maris et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"musa","latin":"mūsa, -ae","headword":"mūsa","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"a muse (one of the nine daughters of Memory); Muse","forms":["Mūsa","Mūsae","Mūsārum","Mūsās","Mūsīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Subitō autem novem pulcherrimās puellās vīdit, quās statim intellēxit novem {{Mūsās}} esse, deās artium canendī, scrībendī, saltandī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"musca","latin":"musca, muscae","headword":"musca","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"fly (insect); gadfly, bothersome person","forms":["muscae","muscam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cum vērō Iuppiter dē nūbibus dēspiciēns eōs ad montem Olympum appropinquantēs vidēret, īrātus propter Bellerophontīs superbiam, {{muscam}} dē caelō mīsit, quae in equō cōnsīdēns eum momordit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"musculus","latin":"musculus, musculi","headword":"musculus","letter":"m","pos":"noun (m.)","posGroup":"noun","english":"little mouse, small rodent; common mouse; various (sea) creatures; mussel","forms":["musculos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Vercingetorix ex arce Alesiae suos conspicatus ex oppido egreditur, crates, longurios, {{musculos}}, falces reliquaque quae eruptionis causa paraverat profert.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"musica","latin":"mūsica, -ae","headword":"mūsica","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"music","forms":["Musica","mūsicae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sum deus sōlis, {{mūsicae}}, medicīnae, artium.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"mussito","latin":"mussito, mussitare, mussitavi, mussitatus","headword":"mussito","letter":"m","pos":"verb","posGroup":"verb","english":"mutter/whisper, talk in subdued tones; keep quiet/say nothing (about)","forms":["mussitantēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quōs ut vīdit Dāvīd {{mussitantēs}}, intellēxit id quod erat: mortuum esse īnfantem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mutabilis","latin":"mūtābilis, -e","headword":"mūtābilis","letter":"m","pos":"adjective","posGroup":"adjective","english":"changeable; changeable, fickle","forms":["mūtābile"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Varium et {{mūtābile}} semper fēmina!' Sīc fātus noctī sē immiscuit ātrae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mutare","latin":"(mūtō) mūtāre, mūtāvisse, mūtātum","headword":"mūtāre","letter":"m","pos":"verb","posGroup":"verb","english":"change, exchange; to change","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mutat","latin":"mūtat","headword":"mūtat","letter":"m","pos":"verb","posGroup":"verb","english":"changes","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"mutatio","latin":"mūtātiō, -ōnis ( f.)","headword":"mūtātiō","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"change, alteration; change, reversal","forms":["mūtātiōnem","mūtātiōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec Graecō sermōne Perseō; Latīnē deinde suīs: 'Exemplum īnsigne cernitis' inquit '{{mūtātiōnis}} rērum hūmānārum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"mutilus","latin":"mutilus, mutila, mutilum","headword":"mutilus","letter":"m","pos":"adjective","posGroup":"adjective","english":"maimed, broken, mutilated; hornless, having lost/stunted horns","forms":["mutilum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Turpe pecus {{mutilum}}, turpis sine grāmine campus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"muto","latin":"mūtō, -āre","headword":"mūtō","letter":"m","pos":"verb","posGroup":"verb","english":"change; change, transform","forms":["mūta","mūtābat","mūtābō","mūtandam","mūtandī","mūtant","mūtantur","mūtāre","mūtārem","mūtārent","mūtāret","mūtārī","mūtārier","mūtat","mūtāta","mūtātae","mūtāte","mūtātī","mūtātīs","mūtātō","mūtātum","mūtātur","mūtātus","mūtāverat","mūtāvērunt","mūtāvī","mūtāvisse","mūtāvistī","mūtāvistis","mūtāvit","mūtet","mūtētur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vōsne tabulās {{mūtāvistis}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"muttio","latin":"muttio, muttire, muttivi, muttitus","headword":"muttio","letter":"m","pos":"verb","posGroup":"verb","english":"mutter, murmur","forms":["muttīs","Muttītō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Etiam {{muttīs}}?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"mutuor","latin":"mutuor, mutuari, mutuatus sum","headword":"mutuor","letter":"m","pos":"verb","posGroup":"verb","english":"borrow, obtain on loan","forms":["mūtuārī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Iūlius ante nummulāriī mēnsam adsistit.] [Nummulārius:] “Domine, quid imperās?” [Iūlius:] “Numquid habēs pecūniam vacuam?” [Nummulārius:] “Quid opus habēs mūtuārī?” [Iūlius:] “Sī habēs, commodā mihi quīnque sēstertia.” [Nummulārius:] “Et sī nōn habērem, undecumque explicārem.” [Iūlius:] “Pignus vīs?” [Nummulārius:] “Absit, nōn opus habeō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"mutus","latin":"mūtus, -a, -um","headword":"mūtus","letter":"m","pos":"adjective","posGroup":"adjective","english":"mute; mute, silent","forms":["mūtī","mūtōs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Lȳdia: \"Quī medicus verbīs sōlīs potest facere ut hominēs caecī videant, surdī audiant, mūtī loquantur, claudī ambulent?\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"mutuus","latin":"mūtuus, -a, -um","headword":"mūtuus","letter":"m","pos":"adjective","posGroup":"adjective","english":"on loan; borrowed, lent","forms":["mūtuā","mūtuam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēnique gladiōs in sē invicem convērtērunt, et mūtuā caede sē trucīdārunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"mycena","latin":"Mycena, Mycenae","headword":"Mycena","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"Mycenae; (ancient Greek city, seat of Agamemnon)","forms":["Mycēnis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ōrnātūs Argīvae Helenae, quōs illa {{Mycēnis}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"myrrha","latin":"myrrha, myrrhae","headword":"myrrha","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"myrrh (aromatic gum/ointment); tree source of myrrh (Commiphora schimperi)","forms":["Myrrhā","myrrham"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et cum cognōvissent magī ubi Chrīstus nātus esset, abiērunt, et vēnērunt Bēthlehem et invēnērunt puerum cum Mada mātre eius et adōrāvērunt eum et obtulērunt eī aurum, tīīs, et {{myrrham}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"myrteus","latin":"myrteus, myrtea, myrteum","headword":"myrteus","letter":"m","pos":"adjective","posGroup":"adjective","english":"of myrtle","forms":["myrtea"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sertaque odōrātae {{myrtea}} ferte comae!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"myrtus","latin":"myrtus, myrti","headword":"myrtus","letter":"m","pos":"noun (f.)","posGroup":"noun","english":"myrtle, myrtle-tree","forms":["myrtōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"hic Pāphīàs {{myrtōs}}, hīc","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mysterium","latin":"mysterium, mysteri(i)","headword":"mysterium","letter":"m","pos":"noun (n.)","posGroup":"noun","english":"mystery, secret service/rite/worship (usu. pl.); secret, things not divulged","forms":["mystēria","mystērium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[| {{Mystēria}} ' Veneris cēlanda sunt]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"mysticus","latin":"mysticus, mystica, mysticum","headword":"mysticus","letter":"m","pos":"adjective","posGroup":"adjective","english":"of/belonging to/used in sacred mysteries/rites; secret, mysterious; mystical","forms":["mystica"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"540 tēctaque sunt solidà {{mystica}} fūrta fide.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"n","latin":"n","headword":"n","letter":"n","pos":"pronoun","posGroup":"pronoun","english":"we (pl.), us","forms":["nobis","nos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia adducti fecerint, quod nihil {{nobis}} constat, non videtur pro certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nae","latin":"nae","headword":"nae","letter":"n","pos":"adverb","posGroup":"adverb","english":"truly, indeed, verily, assuredly; (particle of assurance)","forms":["nae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"fuisse' iüràs (mihi à virgine cà{{nae}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nais","latin":"Nais, Naidos/is","headword":"Nais","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"Naiad; water nymph; nymph","forms":["Naide"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"pallidus in lentà {{Naide}} Daphnis erat.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nam","latin":"nam","headword":"nam","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"for; for, because","forms":["nam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Nam}}, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"namque","latin":"namque","headword":"namque","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"for in fact (strong nam)","forms":["namque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Namque}} altera ex parte Bellovaci, quae civitas in Gallia maximam habet opinionem virtutis, instabant, alteram Camulogenus parato atque instructo exercitu tenebat; tum legiones a praesidio atque impedimentis interclusas maximum flumen distinebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nancisci","latin":"(nancīscor) nancīscī, nactum/","headword":"nancīscī","letter":"n","pos":"verb","posGroup":"verb","english":"get, obtain, find, meet nanctum; to get, obtain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"nanciscor","latin":"nanciscor, nancisci, nactus sum","headword":"nanciscor","letter":"n","pos":"verb","posGroup":"verb","english":"obtain, get; find, meet with, receive, stumble on, light on","forms":["nactae","nacti","nactus","nancīscātur","nancīscī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ibi {{nactus}} recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"narcissus","latin":"Narcissus, -ī","headword":"Narcissus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"Narcissus (a youth)","forms":["Narcisse","Narcissī","Narcissum","Narcissus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Cum ōlim īnfēlīx nympha per silvāsas errāret, subitō {{Narcissum}}, fōrmōsissimum adulēscentulum sēdecim annōrum, quī arcū et sagittīs armātus timidōs cervōs persequēbātur, cōnspexit; quem cum prīmum pulcherrimīs membrīs currentem cervīque vestīgia oculīs quaerentem vīdisset, statim amāvit nec iam sine eō sē vīvere posse putāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nardus","latin":"nardus, nardi","headword":"nardus","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"unguent/balsam/oil of nard (an aromatic plant); the plant nard","forms":["nardō","nardus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec coma vōs fallat liquidō nitidissima nardō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nare","latin":"(nō) nāre","headword":"nāre","letter":"n","pos":"","posGroup":"other","english":"swim","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"narrare","latin":"(nārrō) nārrāre, nārrāvisse,  nārrātum","headword":"nārrāre","letter":"n","pos":"verb","posGroup":"verb","english":"relate, tell; to tell, narrate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"narrat","latin":"nārrat","headword":"nārrat","letter":"n","pos":"verb","posGroup":"verb","english":"tells, relates","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"narratio","latin":"nārrātiō, nārrātiōnis","headword":"nārrātiō","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) story","forms":["nārrātiō","nārrātiōnem","nārrātiōnis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Redeō ad {{nārrātiōnem}} tabulae, quam prope oblīta sum, dum dē aliīs loquor.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"narro","latin":"narro, narrare, narravi, narratus","headword":"narro","letter":"n","pos":"verb","posGroup":"verb","english":"tell, tell about, relate, narrate, recount, describe","forms":["nārrā","nārrābat","nārrābit","nārrābō","nārranda","nārrandī","nārrandīs","nārrandō","nārrandum","nārrant","nārrantem","nārrantibus","nārrantis","nārrantur","nārrāre","nārrārent","nārrāret","nārrārī","nārrās","nārrat","nārrāta","Nārrātē","nārrātōte","nārrātur","nārrāverim","nārrāverīs","nārrāvērunt","nārrāvī","nārrāvisset","nārrāvistī","nārrāvit","narrem","nārrēmur","nārrentur","nārretur","nārrō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed vestis Mārcī tam sordida est quam mea: is quoque humī iacuit...” Sīc Sextus dē pugnā puerōrum {{nārrāre}} pergit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nasci","latin":"(nāscor) nāscī, nātum","headword":"nāscī","letter":"n","pos":"verb","posGroup":"verb","english":"be born; to be born","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"nasciturus","latin":"nasciturus, nascitura, nasciturum","headword":"nasciturus","letter":"n","pos":"adjective","posGroup":"adjective","english":"about to be born/come into being; should be born/rise; (FUT ACTIVE PPL nascor)","forms":["nasciturum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quibus tamen Deus prōmīsit fīlium ex eīs {{nasciturum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nascor","latin":"nāscor, nāscī, nātus sum","headword":"nāscor","letter":"n","pos":"verb","posGroup":"verb","english":"be born, originate from","forms":["nāscantur","nāscātur","nāscentem","nāscentur","nāscerentur","nāscerētur","nāscētur","nāscī","nāscimur","nāscitur","nāscuntur","nātū","natum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia {{natum}}: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus proximo anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nasus","latin":"nāsus, -ī","headword":"nāsus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"nose","forms":["nāsō","nāsum","nāsus","NASVM"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc accipe!” Ita dīcēns Sextus {{nāsum}} Mārcī pugnō pulsat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nata","latin":"nāta, -ae","headword":"nāta","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"daughter","forms":["nata"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ipse maiorem Galliae motum exspectans, ne ab omnibus civitatibus circumsisteretur, consilia inibat quem ad modum ab Gergovia discederet ac rursus omnem exercitum contraheret, ne profectio {{nata}} ab timore defectionis similis fugae videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"natalis","latin":"nātālis, -is","headword":"nātālis","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"birthday; (pl.) birth","forms":["nātālem","nātālēs","nātālī","nātālis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Diē tertiō, quī diēs {{nātālis}} Pharaōnis erat, splendidum convīvium parandum fuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"natat","latin":"natat, natāre","headword":"natat","letter":"n","pos":"verb","posGroup":"verb","english":"swim; swims","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"natio","latin":"nātiō, -ōnis ( f.)","headword":"nātiō","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"people, nation","forms":["nātiōnēs","nationibus","nātiōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quod si ea quae in longinquis {{nationibus}} geruntur ignoratis, respicite finitimam Galliam, quae in provinciam redacta, iure et legibus commutatis, securibus subiecta perpetua premitur servitute.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"natis","latin":"natis, natis","headword":"natis","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"buttocks (usu. pl.), rump","forms":["natis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Minervae verbīs parēns, Cadmus tergum cuiusdam ex illīs mīlitibus ē terrā {{natis}} hasta percussit: quī, crēdēns sē ab aliō mīlite pulsātum esse, eum gladiō trānsfīxit; ita iī ferī hominēs ex agrō ortī suīs armīs inter sē occīdēbant; post longam autem pugnam eōrum trēs tantum mānsērunt; quōs Minerva Cadmō suāsit ut amīcōs sociōsque acciperet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nato","latin":"natō, -āre, -āvī, -ātum","headword":"natō","letter":"n","pos":"verb","posGroup":"verb","english":"swim","forms":["natābant","natābat","natandō","natāns","natant","natantem","natantīs","natāre","natāret","natat","Natāvī","natentur","natēs","natet","nātō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quīntō diē, avēs quae volitant in aere, et piscēs quī {{natant}} in aquīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"natu","latin":"nātū","headword":"nātū","letter":"n","pos":"","posGroup":"other","english":"older/younger (abl. māior/ minor [n.])","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"natura","latin":"nātūra, -ae","headword":"nātūra","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"nature","forms":["natura","naturae","nātūram"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci {{natura}} ab omni sint periculo tuta, neu suis sint ad detrectandam militiam receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"naturalis","latin":"nātūrālis, -e","headword":"nātūrālis","letter":"n","pos":"adjective","posGroup":"adjective","english":"natural, of nature","forms":["nātūrālis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iūxtā ea tempora Empedoclēs Agrigentīnus in philosophiae {{nātūrālis}} studiō flōruit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"natus","latin":"nātus, -ūs","headword":"nātus","letter":"n","pos":"adjective","posGroup":"adjective","english":"birth; born","forms":["nātam","nātārum","nātās","nāte","nati","nātōrum","natos","natus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, sollicitatus ab Arvernis pecunia cum quibusdam adulescentibus colloquitur; quorum erat princeps Litaviccus atque eius fratres amplissima familia {{nati}} adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"naufragium","latin":"naufragium, -ī","headword":"naufragium","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"shipwreck","forms":["naufragī","naufragiō","naufragium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"naufragus -ā -um — quī {{naufragium}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"naufrago","latin":"naufrago, naufragare, naufragavi, naufragatus","headword":"naufrago","letter":"n","pos":"verb","posGroup":"verb","english":"be shipwrecked","forms":["naufraga","NAVFRAGO"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"vix tenuit lacerae {{naufraga}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"naufragus","latin":"naufragus, naufraga, naufragum","headword":"naufragus","letter":"n","pos":"adjective","posGroup":"adjective","english":"shipwrecked; ruined; causing shipwreck","forms":["naufragōs","naufragus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{naufragus}} -ā -um — quī naufragium","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nausea","latin":"nausea, nauseae","headword":"nausea","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"nausea; seasickness","forms":["nauseam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"inquit “ad parentālia mea in- Îbat rēs ad surnmam {{nauseam}}, cum Trimalchiô, ēbrie- tâte turpissirnä gravis, novum acroânna, cornicinēs, in trī- clînium iussit addücî; fultusque cervîcälibus multîs ex- tendit sē suprā torum extrēmum, et “Fingite mē” inquit “mortuum esse!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"nauta","latin":"nauta, -ae","headword":"nauta","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"(m.) sailor","forms":["nauta","nautae","nautam","nautārum","nautās","nautīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam singulī {{nautae}} singulōs rēmōs sūrsum deorsum movēbant et nāvis ē portū proficiscēbatur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nauticus","latin":"nauticus, -a, -um","headword":"nauticus","letter":"n","pos":"adjective","posGroup":"adjective","english":"nautical, naval","forms":["nautica"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam autem nāvēs suās opplētās cōnspexērunt serpentibus, novā rē perterritī, cum quid potissimum vītārent nōn vidērent, puppēs vertērunt sēque ad sua castra {{nautica}} rettulērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"navale","latin":"navale, navalis","headword":"navale","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"dock, shipway","forms":["nāvāle"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[Spectāculum Augustī: proelium {{nāvāle}}]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"navalia","latin":"nāvālia, -ium (n. pl.)","headword":"nāvālia","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"dockyard; dockyards","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"navalis","latin":"nāvālis, -e","headword":"nāvālis","letter":"n","pos":"adjective","posGroup":"adjective","english":"naval","forms":["nāvālem","nāvālī","nāvālia","nāvālibus","nāvālis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quid? modo cum bellī {{nāvālis}} imāgine Caesar","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"navicula","latin":"nāvicula, -ae","headword":"nāvicula","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"small boat; little ship, boat","forms":["nāviculā","nāviculam","nāviculīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum turbae irruerent in Iēsum ut audīrent verbum Deī, ipse ascendit in nāvem quae erat secus stāgnum, et sedēns docēbat dē nāviculā turbās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"navicularius","latin":"nāviculārius, -ī","headword":"nāviculārius","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"ship-owner; shipowner, shipper","forms":["nāviculāriīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Maiōrēs nostrī saepe prō mercātōribus aut {{nāviculāriīs}} nostrīs iniūriōsius tractātīs bella gessērunt — vōs, tot mīlibus cīvium Rōmānōrum ūnō nūntiō atque ūnō tempore necātīs, quō tandem animō esse debētis?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"navigare","latin":"nāvigāre","headword":"nāvigāre","letter":"n","pos":"verb","posGroup":"verb","english":"to sail","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"navigat","latin":"nāvigat","headword":"nāvigat","letter":"n","pos":"verb","posGroup":"verb","english":"sails","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"navigatio","latin":"nāvigātiō, nāvigātiōnis","headword":"nāvigātiō","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) sailing","forms":["nāvigātiōne"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Semper gaudeō cum dē līberīs meīs cōgitō, quī maximā laetitiā afficiuntur cum patrem suum ē {{nāvigātiōne}} perīculōsā salvum redīre vident.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"navigo","latin":"nāvigō, nāvigāre","headword":"nāvigō","letter":"n","pos":"verb","posGroup":"verb","english":"sail","forms":["nāvigābant","nāvigābimus","nāvigāmus","nāvigandō","nāvigandum","nāvigant","nāvigantēs","nāvigantibus","nāvigāre","nāvigārēmus","nāvigāret","nāvigat","nāvigāte","nāvigāvērunt","nāvigāvit","nāvigem","nāviget"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Bene {{nāvigāte}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"navis","latin":"nāvis, nāvis","headword":"nāvis","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) ship","forms":["nāve","nāvem","naves","nāvī","navibus","nāvis","nāvium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque interfectis Novioduni custodibus quique eo negotiandi causa convenerant, pecuniam atque equos inter se partiti sunt; obsides civitatum Bibracte ad magistratum deducendos curaverunt; oppidum, quod a se teneri non posse iudicabant, ne cui esset usui Romanis, incenderunt; frumenti quod subito potuerunt {{navibus}} avexerunt, reliquum flumine atque incendio corruperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"navo","latin":"navo, navare, navavi, navatus","headword":"navo","letter":"n","pos":"verb","posGroup":"verb","english":"do with zeal; [operam navare => do one's best]","forms":["nāvābat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulieris marītus, nōmine Ūriās, vir fortissimus, tum in castrīs erat, et ēgregiam patriae operam {{nāvābat}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nazareth","latin":"Nazareth, undeclined","headword":"Nazareth","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"Nazareth; city in Palestine; (home of the parents of Jesus)","forms":["Nazareth"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ascendit Iōsēph dē cīvitāte {{Nazareth}} in cīvitātem, quae vocātur Bēthlehem, cum Marīā, uxōre suā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ne","latin":"-ne?","headword":"ne","letter":"n","pos":"particle; conjunction","posGroup":"particle","english":"enclitic added to the emphatic word at the beginning of a question the answer to which may be either “yes” or “no.” It can be used in both direct and indirect questions (Cap. XIX).; negative conjunction; (turns a sentence into a question); lest, that not; that not, lest","forms":["ne"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint {{ne}} res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ne ... quidem","latin":"nē ... quidem","headword":"nē ... quidem","letter":"n","pos":"particle","posGroup":"particle","english":"not even","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"nebula","latin":"nebula, -ae","headword":"nebula","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"mist, fog; cloud, mist","forms":["nebulā","nebulae","nebulīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi cālīgō {{nebulīs}} miscētur, nec ūllus sonus silentia rumpit: omnia, mūta, quiēscunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nec","latin":"nec","headword":"nec","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"and/but not, nor, not","forms":["nec"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, {{nec}} iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nec ... nec","latin":"nec ... nec","headword":"nec ... nec","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"neither ... nor","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"necare","latin":"(necō) necāre, necāvisse, necātum","headword":"necāre","letter":"n","pos":"verb","posGroup":"verb","english":"kill; to kill, slay","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"necdum","latin":"necdum","headword":"necdum","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"and (/but) not yet","forms":["necdum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Frātrēs Iōsēphī sēsē in viam dederant, {{necdum}} procul ab urbe aberant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"necessaria","latin":"necessaria, necessariae","headword":"necessaria","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"connection (female), she closely connected by friendship/family/obligation","forms":["necessāria"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Uxor Tobiae in texendā tēlā comparābat ea, quae ad vīctum erant {{necessāria}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"necessario","latin":"necessāriō","headword":"necessāriō","letter":"n","pos":"adverb","posGroup":"adverb","english":"necessarily, unavoidably","forms":["necessario"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Pabulum secari non posse; {{necessario}} dispersos hostes ex aedificiis petere; hos omnes cotidie ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"necessarium","latin":"necessarium, necessarii","headword":"necessarium","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"necessities (pl.), what is needed; necessities of life","forms":["necessārium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nōn multum eī {{necessārium}} est, nec vērō sine librīs potest vīvere.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"necessarius","latin":"necessārius, -a, -um","headword":"necessārius","letter":"n","pos":"adjective","posGroup":"adjective","english":"necessary; relative, friend","forms":["necessāriae","necessāriam","necessariarum","necessāriās","necessāriī","necessāriīs","necessāriōrum","necessārius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Proinde agmine impeditos adoriantur; si pedites suis auxilium ferant atque in eo morentur, iter facere non posse; si, id quod magis futurum confidat, relictis impedimentis suae saluti consulant, et usu rerum {{necessariarum}} et dignitate spoliatum iri.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"necesse est","latin":"necesse est","headword":"necesse est","letter":"n","pos":"","posGroup":"other","english":"it is necessary","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"necesseus","latin":"necesseus, necessea, necesseum","headword":"necesseus","letter":"n","pos":"adjective","posGroup":"adjective","english":"necessary, essential; unavoidable, compulsory, inevitable; a natural law; true","forms":["necesse"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius aestimare, liberos, coniuges in servitutem abstrahi, ipsos interfici; quae sit {{necesse}} accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"necessitas","latin":"necessitās, -ātis ( f.)","headword":"necessitās","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"need, necessity; necessity, compulsion","forms":["necessitāte","necessitātem","necessitatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postero die Vercingetorix concilio convocato id bellum se suscepisse non suarum {{necessitatum}} sed communis libertatis causa demonstrat et, quoniam sit fortunae cedendum, ad utramque rem se illis offere, seu morte sua Romanis satisfacere seu vivum tradere velint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"necessitudo","latin":"necessitudo, necessitudinis","headword":"necessitudo","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"obligation; bond, connection, affinity; compulsion; needs; poverty; relative","forms":["necessitūdinibus","necessitūdō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ubi satis explōrāta sunt quae voluit, in ūnum omnēs convocat quibus maxima necessitūdō et plūrimum audāciae inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"neco","latin":"necō, -āre","headword":"necō","letter":"n","pos":"verb","posGroup":"verb","english":"kill","forms":["necābat","necandī","necandum","necandus","necāre","necārent","necāret","necārētur","necārī","necat","necāta","necātam","necātīs","necātō","necātōs","necātus","necāverat","necāvēre","necāvisset","necāvistī","necāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis {{necat}}, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nectar","latin":"nectar, -aris","headword":"nectar","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"nectar, drink of the gods","forms":["nectare"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quicquid in Aenēā fuerat mortāle, repurgat\net respersit aquīs; pars optima restitit illī,\nlūstrātum genetrīx dīvīnō corpus odōre\nunxit et ambrosiā cum dulcī {{nectare}} mixtā\ncontigit ōs fēcitque deum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"nectere","latin":"(nectō) nectere, nexuisse, nexum","headword":"nectere","letter":"n","pos":"","posGroup":"other","english":"attach","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"necto","latin":"necto, nectere, nexui, nexus","headword":"necto","letter":"n","pos":"verb","posGroup":"verb","english":"tie, bind","forms":["nectit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et leve per līnī vincula {{nectit}} opus;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"necubi","latin":"necubi","headword":"necubi","letter":"n","pos":"adverb","posGroup":"adverb","english":"lest anywhere/at any place; lest on any occasion; that nowhere","forms":["necubi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Cum uterque utrimque exisset exercitus, in conspectu fereque e regione castris castra ponebant, dispositis exploratoribus {{necubi}} effecto ponte Romani copias traducerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nefandus","latin":"nefandus, -a, -um","headword":"nefandus","letter":"n","pos":"adjective","posGroup":"adjective","english":"heinous; wicked, unspeakable","forms":["nefanda","nefandās","nefandī","nefandō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi cūria Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) {{nefandās}}, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"nefarium","latin":"nefarium, nefarii","headword":"nefarium","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"crime; wicked/impious/nefarious/heinous act","forms":["nefārium"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Numquam tū nōn modo ōtium sed nē bellum quidem nisi {{nefārium}} concupīstī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"nefarius","latin":"nefārius, -a, -um","headword":"nefārius","letter":"n","pos":"adjective","posGroup":"adjective","english":"impious, wicked, abominable","forms":["nefāria","nefariam","nefāriī","nefario","nefāriōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"An dubitamus quin {{nefario}} facinore admisso Romani iam ad nos interficiendos concurrant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nefas","latin":"nefās","headword":"nefās","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"impious act, crime; a wicked deed, an unspeakable crime; crime against divine law","forms":["nefas"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Litaviccus cum suis clientibus, quibus more Gallorum {{nefas}} est etiam in extrema fortuna deserere patronos, Gergoviam profugit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nefastus","latin":"nefāstus, -a, -um","headword":"nefāstus","letter":"n","pos":"","posGroup":"other","english":"public holiday","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"negare","latin":"(negō) negāre, negāvisse, negātum","headword":"negāre","letter":"n","pos":"verb","posGroup":"verb","english":"deny, say…not; to deny","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"negat","latin":"negat","headword":"negat","letter":"n","pos":"verb","posGroup":"verb","english":"denies","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"negitare","latin":"(negitō) negitāre","headword":"negitāre","letter":"n","pos":"","posGroup":"other","english":"deny repeatedly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"negito","latin":"negito, negitare, negitavi, negitatus","headword":"negito","letter":"n","pos":"verb","posGroup":"verb","english":"deny or refuse repeatedly","forms":["negitāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quem sī Rōmānīs trādidisset, amīcitiam, foedus, Numidiae partem quam nunc peteret, tum ultrō adventūram.' Rēx prīmō {{negitāre}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"neglectus","latin":"neglēctus, -a, -um","headword":"neglēctus","letter":"n","pos":"adjective","posGroup":"adjective","english":"neglected","forms":["neglēctā","neglēctōs","neglēctus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fībula vestīmentum retinēbat et vitta {{neglēctōs}} capillōs retinēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"neglegens","latin":"neglegēns","headword":"neglegēns","letter":"n","pos":"adjective","posGroup":"adjective","english":"(gen. neglegentis) careless; careless, neglectful","forms":["neglegēns","neglegentēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ego cūrābō nē posthāc {{neglegēns}} sīs nēve dormiās!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"neglegenter","latin":"neglegenter, neglegentius, neglegentissime","headword":"neglegenter","letter":"n","pos":"adverb","posGroup":"adverb","english":"heedlessly, neglectfully, carelessly; unconcernedly, indifferently; slovenly","forms":["neglegenter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quōdam diē, postquam multōs piscēs rētī cēperat, ē marī reversus, ita {{neglegenter}} prope ōram maritimam ambulābat, ut per ignōta loca errāret, ubi neque ūllae ovēs umquam herbam ēderant neque ūlla apis meī ē flōribus fēcerat neque agricolae, falce ūsī, frūmentum messuerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"neglegentia","latin":"neglegentia, neglegentiae","headword":"neglegentia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"heedlessness, neglect; carelessness, negligence; coldness; disrespect","forms":["neglegentiam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed ea tametsī vōs parvī pendēbātis, tamen rēs pūblica firma erat: opulentia {{neglegentiam}} tolerābat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"neglegere","latin":"(neglegō) neglegere, neglēxisse, neglēctum","headword":"neglegere","letter":"n","pos":"","posGroup":"other","english":"neglect","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"neglego","latin":"neglego, neglegere, neglexi, neglectus","headword":"neglego","letter":"n","pos":"verb","posGroup":"verb","english":"disregard, neglect, ignore, regard of no consequence; do nothing about; despise","forms":["neglegās","neglegat","neglegēbat","neglegenda","neglegendās","neglegere","neglegētis","neglegī","neglegis","neglegit","neglēxerat","neglēxerīs","neglexerunt","neglēxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Praeterea salutis causa rei familiaris commoda {{neglegenda}}: vicos atque aedificia incendi oportere hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"negligo","latin":"negligo, negligere, neglixi, neglictus","headword":"negligo","letter":"n","pos":"verb","posGroup":"verb","english":"disregard, neglect, ignore, regard of no consequence; do nothing about; despise","forms":["negligere","negligerentur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed quia in cīvitāte bellicōsā plūrēs Rōmulī quam Numae similēs rēgēs fore putābat, itūrōsque ipsōs ad bella, nē rēge absente sacra {{negligerentur}}, Iovī assiduum sacerdōtem creāvit quī \"flāmen Diālis\" appellātus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nego","latin":"negō, -āre","headword":"negō","letter":"n","pos":"verb","posGroup":"verb","english":"deny, say that ... not","forms":["negā","negābāmus","negābant","negābat","negābis","negābit","negābitur","negābō","negandī","negant","negantī","negāre","negārem","negārent","negās","negāsset","negat","negātā","negātum","negātūrum","negāverat","negāverit","negāvērunt","negāvī","negāvit","negem","neget","negō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Diodōrus: “Lucrētius dīcit ‘tonitrum fierī quia nūbēs volantēs in caelō concurrunt ventīs pugnantibus...’ Certē {{negat}} ‘Iovem facere tonitrum’.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"negotiari","latin":"(negōtior) negōtiārī","headword":"negōtiārī","letter":"n","pos":"","posGroup":"other","english":"do business, trade","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"negotiatio","latin":"negotiatio, negotiationis","headword":"negotiatio","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"business","forms":["negōtiātiōnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et hīs quī columbās vēndēbant dīxit:\"Auferte ista et nōlīte facere domum Patrīs meī domum {{negōtiātiōnis}}.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"negotiator","latin":"negōtiātor, -ōris (m.)","headword":"negōtiātor","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"trader, agent; trader, businessman","forms":["negōtiātōrēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iugurtha in prīmīs Adherbalem excruciātum necat; deinde omnēs pūberēs Numidās et {{negōtiātōrēs}}, utī quisque armātus obvius fuerat, interficit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"negotio","latin":"negotio, negotiare, negotiavi, negotiatus","headword":"negotio","letter":"n","pos":"verb","posGroup":"verb","english":"carry on business; trade","forms":["negotiandi","negōtiātus","negotio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum signo dato concurrunt civesque Romanos qui {{negotiandi}} causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"negotium","latin":"negōtium, -ī","headword":"negōtium","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"business; work, business; business, task; business, affair, task","forms":["negōtī","negōtia","negōtiī","negōtiīs","negōtium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iōsēphus ergō administrābat rem familiārem Putiphāris: omnia fīēbant ad nūtum eius, nec Putiphar ūllīus negōtiī cūram gerēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nemo","latin":"nēmō","headword":"nēmō","letter":"n","pos":"pronoun","posGroup":"pronoun","english":"no one","forms":["neminem","nēminī","nemo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ubi {{neminem}} in aequum locum sese demittere sed toto undique muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nemorosus","latin":"nemorosus, nemorosa, nemorosum","headword":"nemorosus","letter":"n","pos":"adjective","posGroup":"adjective","english":"well-wooded","forms":["nemorōsa","nemorōsae","nemorōsīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"105 illīc quàs tulerant {{nemorōsa}} Palātia frondēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nempe","latin":"nempe","headword":"nempe","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"truly, certainly, of course","forms":["nempe"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Saūl victōrī fīliam suam spoponderat uxōrem; at prōmissīs nōn stetit, novamque condiciōnem prōposuit, sī {{nempe}} Dāvīd centum Philistaeōs interfēcisset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nemus","latin":"nemus, nemoris","headword":"nemus","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"wood, forest","forms":["nemora","nemore","nemorum","nemus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ego tē in {{nemore}} dēfendam!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nenia","latin":"nenia, neniae","headword":"nenia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"funeral dirge sung; incantation, jingle","forms":["nēnia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{nēnia}} -aē f — carmen magicum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nepos","latin":"nepōs, -ōtis (m./f.)","headword":"nepōs","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"grandson; grandson, descendant","forms":["nepōs","nepōtem","nepōtēs","nepōtibus","nepōtis","nepōtum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iacobus profectus cum fīliīs et {{nepōtibus}} pervēnit in Aegyptum, et praemīsit Iūdam ad Iōsēphum ut eum faceret certiōrem dē adventū suō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"neptunus","latin":"Neptūnus","headword":"Neptūnus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"Neptune, god of the sea","forms":["Neptūne","Neptūnī","Neptūnō","Neptūnum","Neptūnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōlim, multīs hominibus spectantibus, ambulātum exiit et ōram maris petīvit; ibi vērō {{Neptūnum}} tālibus verbīs ōrāvit: “Ō Neptūne” inquit, “ōrō tē ut pulchrum taurum ad meam īnsulam mittās, quem tibi, marium omnium deō quī magnōs flūctūs excitās tempestātēsque sēdāre solēs, sacrificābō!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nequam/nequior","latin":"nēquam/nēquior, nēquius/ nēquissimus, -a, -um","headword":"nēquam/nēquior","letter":"n","pos":"","posGroup":"other","english":"worthless","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nequamus","latin":"nequamus, nequama, nequamum","headword":"nequamus","letter":"n","pos":"adjective","posGroup":"adjective","english":"wicked/licentious/depraved; bad/vile; naughty/roguish; worthless/useless","forms":["nēquam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ultimus autem rēx, nōmine Tarquinius, quī nōn Rōmānus sed Tuscus erat, glōriōsus, sevērissimus et tam {{nēquam}} fuit ut ‘Superbus’ appellārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nequaquam","latin":"nēquāquam","headword":"nēquāquam","letter":"n","pos":"adverb","posGroup":"adverb","english":"by no means, not at all","forms":["nequaquam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Facere, quod nostri maiores {{nequaquam}} pari bello Cimbrorum Teutonumque fecerunt; qui in oppida compulsi ac simili inopia subacti eorum corporibus qui aetate ad bellum inutiles videbantur vitam toleraverunt neque se hostibus tradiderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"neque","latin":"neque","headword":"neque","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"and not, but not, nor, neither; and not, nor; and not","forms":["neque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem {{neque}} in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"neque...neque","latin":"neque...neque","headword":"neque...neque","letter":"n","pos":"","posGroup":"other","english":"neither…nor","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nequeo","latin":"nequeo, nequire, nequivi(ii), nequitus","headword":"nequeo","letter":"n","pos":"verb","posGroup":"verb","english":"be unable, cannot","forms":["nequeō","nequeunt","nequībat","nequit","nequītis","nequīverant","nequīverat","nequīverim","nequīverit","nequīvisset"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tandem Philistaeī, quī Samsōnem comprehendere {{nequīverant}}, Dalilam uxōrem pecūniā corrūpērunt, ut ea virum prōderet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nequiquam","latin":"nēquīquam","headword":"nēquīquam","letter":"n","pos":"adverb","posGroup":"adverb","english":"in vain, fruitlessly","forms":["nēquīquam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ALCVMENA: Vēra dīcō, sed {{nēquīquam}}, quoniam nōn vīs crēdere.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"nequire","latin":"(nequiō) nequīre","headword":"nequīre","letter":"n","pos":"","posGroup":"other","english":"be unable","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nequissimusus","latin":"nequissimusus, nequissimusa, nequissimusum","headword":"nequissimusus","letter":"n","pos":"adjective","posGroup":"adjective","english":"most wicked/vile/licentious/worthless, good for nothing; (nequam SUPER)","forms":["nēquissimus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Posteā sî fēcerit, nëmô nostrum prô illô rogābit.” Ego, crūdēlissimae sevēritātis, nôn potuî mē tenēre, sed inclînätus ad aurem Agamemnonis “Plānē” inquam “hic dēbet servus esse {{nēquissimus}}: aliquis oblîvîscerëtur porcum exinterāre?!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"nequitia","latin":"nequitia, nequitiae","headword":"nequitia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"wickedness; idleness; negligence; worthlessness; evil ways","forms":["nēquitia","nēquitiae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"nec sint {{nēquitiae}} tempora","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nero","latin":"Nero, Neronis","headword":"Nero","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"Nero; (cognomen of Claudian gens)","forms":["Nerō","Nerōne","Nerōnem","Nerōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hae prīmae thermae Rōmae fuērunt, sed posteā aliae thermae etiam magnificentiorēs aedificātae sunt ab imperātōre {{Nerōne}} in campō Mārtiō, ā Titō et Trāiānō in Esquiliīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nerva","latin":"Nerva, Nervae","headword":"Nerva","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"Nerva; (Roman cognomen); [M. Cocceius Nerva => Emperor, 96-98 AD]","forms":["Nerva","Nervae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cocceius {{Nerva}} annum tantum et quattuor mēnsēs imperāvit, deinde M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nervus","latin":"nervus, -ī","headword":"nervus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"sinew, muscle; vigor","forms":["nervīs","nervōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inter cētera iuvenālia opera quae ad ultimum ēdidit, adeō etiam {{nervīs}} in senectā viguit ut post sextum et octōgēsimum annum fīlium genuerit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nescio","latin":"nesciō, nescīre","headword":"nesciō","letter":"n","pos":"verb","posGroup":"verb","english":"not know; not know, be ignorant of","forms":["nesci","nesciat","nesciēbam","nesciēbat","nesciēns","nescīmus","nesciō","nescīre","nescīrent","nescīs","nescit","nesciunt","nescīvisse","nescīvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia: “Id nesciō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nescire","latin":"nescīre","headword":"nescīre","letter":"n","pos":"verb","posGroup":"verb","english":"not to know","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"nescius","latin":"nescius, -a, -um","headword":"nescius","letter":"n","pos":"adjective","posGroup":"adjective","english":"not knowing, ignorant","forms":["nescius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iōnāthās ēdictī paternī {{nescius}} extendit virgam quam manū tenēbat, eamque in mel intīnctam ōrī admōvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"neu","latin":"neu","headword":"neu","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"or not, and not (nēve…nēve); and not, nor","forms":["neu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo tuta, {{neu}} suis sint ad detrectandam militiam receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"neuter","latin":"neuter, -tra, -trum","headword":"neuter","letter":"n","pos":"pronoun; adjective","posGroup":"pronoun","english":"neither; neither of the two; neuter","forms":["neuter","neutra","neutris","neutrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ab hoc concilio Remi, Lingones, Treveri afuerunt; illi, quod amicitiam Romanorum sequebantur; Treveri, quod aberant longius et ab Germanis premebantur, quae fuit causa quare toto abessent bello et {{neutris}} auxilia mitterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"neutrum","latin":"neutrum (genus)","headword":"neutrum","letter":"n","pos":"adjective","posGroup":"adjective","english":"neuter","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"neve","latin":"nēve","headword":"nēve","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"and not, nor","forms":["neve"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat {{neve}} ab hostibus diripiantur, praesertim cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nex","latin":"nex, necis","headword":"nex","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) death; death, killing; death, murder","forms":["nece","necem","necēs","necī","nex"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus: “Sōlus intrāvī, {{nex}} sōlus illinc exiī: servus meus, quī interim advēnerat, mē vix vīvum ē domō ārdentī tulit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nexo","latin":"nexo, nexere, nexi, -","headword":"nexo","letter":"n","pos":"verb","posGroup":"verb","english":"tie together; bind together; (see also nectere)","forms":["nexās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tempore nec {{nexās}} saepe resolve comās!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nexum","latin":"nexum, nexi","headword":"nexum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"obligation between creditor/debtor; (pre-300 BC debtor bondman for non-payment)","forms":["nexā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"haeret 'adulteriō'\" cum cānē nexā cānīs;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ni","latin":"nī","headword":"nī","letter":"n","pos":"adverb","posGroup":"adverb","english":"= nisi: unless, if not","forms":["nī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cynthius -1, Apollō («€ Cynthus -ī nī,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nidus","latin":"nīdus, -ī","headword":"nīdus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"nest","forms":["nīdī","nīdīs","nīdō","nīdōs","nīdum","nīdus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra: “Magna aquila etiam parvam puellam capere potest et ad {{nīdum}} suum portāre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"niger","latin":"niger, -gra, -grum","headword":"niger","letter":"n","pos":"adjective","posGroup":"adjective","english":"black","forms":["niger","nigra","nigrae","nigram","nigrās","nigrī","nigrīs","nigros","nigrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faustīnus, pāstor Iūliī, abest ab ovibus suīs, quia ovem {{nigram}} in silvā quaerit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nigresco","latin":"nigresco, nigrescere, nigrui, -","headword":"nigresco","letter":"n","pos":"verb","posGroup":"verb","english":"become black, grow dark","forms":["nigrēscere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"(horrendum dictū) laticēs {{nigrēscere}} sacrōs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"nihil","latin":"nihil","headword":"nihil","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"(n.) nothing","forms":["nihil"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia adducti fecerint, quod {{nihil}} nobis constat, non videtur pro certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nihil/nil","latin":"nihil/nīl","headword":"nihil/nīl","letter":"n","pos":"","posGroup":"other","english":"nothing, not at all","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nihildum","latin":"nihildum, undeclined","headword":"nihildum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"nothing; nothing as yet; not a shred; less than nothing","forms":["nihildum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Atque hōrum omnium scelerum improbissimum māchinātōrem, Cimbrum Gabīnium, statim ad mē {{nihildum}} suspicantem vocāvī, deinde item accersītus est L.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"nihilo","latin":"nihilō","headword":"nihilō","letter":"n","pos":"","posGroup":"other","english":"no, by no means","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nihilominus","latin":"nihilominus","headword":"nihilominus","letter":"n","pos":"adverb","posGroup":"adverb","english":"never/none the less, notwithstanding, just the same; likewise, as well","forms":["nihilōminus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum {{nihilōminus}} pharaō in sententiā perstāret, Deus interfēcit prīmōgenitum eius fīlium, et omnēs prīmōgenitōs Aegyptiōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nihilum","latin":"nihilum, nihili","headword":"nihilum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"nothing; nothingness, which does not exist; something valueless; no respect","forms":["nihilo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum Vercingetorix {{nihilo}} minus in aequum locum descenderet, levi facto equestri proelio atque secundo in castra exercitum reduxit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nil","latin":"nīl","headword":"nīl","letter":"n","pos":"pronoun","posGroup":"pronoun","english":"nothing (= nihil)","forms":["nīl"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"grātius illī {{nīl}} Hyacinthī nōmine vīsum est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nilum","latin":"nilum, nili","headword":"nilum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"nothing; nothingness, which does not exist; something valueless; no respect","forms":["Nīlī","Nīlō","Nīlum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Vidēbātur sibi adstāre Nīlō flūminī; et ecce ēmergēbant dē flūmine septem vaccae pinguēs, quae pāscēbantur in palūde.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nimbosus","latin":"nimbosus, nimbosa, nimbosum","headword":"nimbosus","letter":"n","pos":"adjective","posGroup":"adjective","english":"full of/surrounded by rain clouds","forms":["nimbōsus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cum subitō adsurgēns flūctū {{nimbōsus}} Ōrīōn","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"nimbus","latin":"nimbus, -ī","headword":"nimbus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"rain cloud; storm-cloud","forms":["nimbō","nimbōrum","nimbus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam in altum prōvectae sunt nāvēs nec iam ūllae terrae appārēbant, {{nimbus}} repentīnus solem occultāvit imbrem tempestātemque afferēns.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nimio","latin":"nimio","headword":"nimio","letter":"n","pos":"adverb","posGroup":"adverb","english":"by a very great degree, far","forms":["nimiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn poterant respondēre frātrēs eius nimiō timōre perturbātī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nimirum","latin":"nīmīrum","headword":"nīmīrum","letter":"n","pos":"adverb","posGroup":"adverb","english":"without doubt, evidently","forms":["nimīrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"{{Nīmīrum}} haec est illa Charybdis\" inquit Anchīsēs, \"Hōs scopulōs, haec saxa horrenda Helēnus memorābat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nimis","latin":"nimis","headword":"nimis","letter":"n","pos":"adverb","posGroup":"adverb","english":"too, too much","forms":["nimis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sed is locus praesidio ab his, non {{nimis}} firmo tamen, tenebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nimium","latin":"nimium","headword":"nimium","letter":"n","pos":"adverb","posGroup":"adverb","english":"too, too much; very, very much, beyond measure, excessive, too great","forms":["nimium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mulier īrāta inclāmāvit servōs, et Iōsēphum accūsāvit apud virum, quī, {{nimium}} crēdulus, coniēcit Iōsēphum in carcerem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nimium/nimis","latin":"nimium/nimis","headword":"nimium/nimis","letter":"n","pos":"","posGroup":"other","english":"(adv.) too much","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nimius","latin":"nimius, -a, -um","headword":"nimius","letter":"n","pos":"adjective","posGroup":"adjective","english":"too big; too much, excessive","forms":["nimia","nimiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sibi numquam placuisse Avaricum defendi, cuius rei testes ipsos haberet; sed factum imprudentia Biturigum et {{nimia}} obsequentia reliquorum uti hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"niobe","latin":"Nīobē, -ēs","headword":"Nīobē","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"Niobe (a queen)","forms":["Niobē","Niobēn","Niobēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Niobē fēmina Graeca fuit, cui septem fīliī septemque fīliae erant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nisi","latin":"nisi","headword":"nisi","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"if not, except, but; unless, if not; unless, if ... not","forms":["nisi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, {{nisi}} eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"niteo","latin":"niteo, nitere, nitui, -","headword":"niteo","letter":"n","pos":"verb","posGroup":"verb","english":"shine, glitter, look bright; be sleek/in good condition; bloom, thrive","forms":["nītēbantur","nītēmur","nītendō","nītēns","nitentem","nīterētur","nitēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quīn etiam laetās mōvēre per āera caudās\nnostraque adūlantēs comitantur vestīgia, dōnec\n[nōs] excipiunt famulae perque ātria marmore tēcta\nad dominam dūcunt: pulchrō sedet illa recessū\nsollemnī soliō, pallamque indūta {{nitentem}}\nīnsuper aurātō circumvelātur amictū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"niti","latin":"(nītor) nītī, nīsusm","headword":"nītī","letter":"n","pos":"","posGroup":"other","english":"exert oneself, strive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nitidus","latin":"nitidus, nitida, nitidum","headword":"nitidus","letter":"n","pos":"adjective","posGroup":"adjective","english":"shining, bright","forms":["nitidīs","nitidō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fōns erat illīmīs, {{nitidīs}} argenteus undīs, quem neque pāstōrēs neque pastae monte capellae contigerant aliudve pecus, quem nūlla volucris","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nitor","latin":"nitor, niti, nisus sum","headword":"nitor","letter":"n","pos":"verb","posGroup":"verb","english":"press/lean upon; struggle; advance; depend on (with abl.); strive, labor","forms":["nīsū","nītar","nītī","nītitur","nitor","nitōre","nituntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Legationes in omnes partes circummittuntur; quantum gratia, auctoritate, pecunia valent ad sollicitandas civitates {{nituntur}}; nacti obsides quos Caesar apud eos deposuerat, horum supplicio dubitantes territant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"niveus","latin":"niveus, -a, -um","headword":"niveus","letter":"n","pos":"adjective","posGroup":"adjective","english":"snow white; snow-white","forms":["niveā","niveam","niveīs","niveō","niveos"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque Iuppiter, nē puella ā limōne inventa pūnīrētur, eam in fōrmōsam et {{niveam}} vaccam mūtāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nix","latin":"nix, nivis","headword":"nix","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) snow","forms":["nive","nivēs","nivibus","nix"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima {{nive}} iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"no","latin":"no, nare, navi, -","headword":"no","letter":"n","pos":"verb","posGroup":"verb","english":"swim, float","forms":["nā","nandō","nantēs","nāre","nās","nem","ner","nēre","nes","net","nō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tlēpolemus: “c-a ca, v-e vē: ca-vē, c-a ca, n-e-m {{nem}}: canem: cavē canem!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nobilis","latin":"nōbilis, -e","headword":"nōbilis","letter":"n","pos":"adjective","posGroup":"adjective","english":"well-known, famous; noble, famous","forms":["nōbile","nōbilem","nobiles","nōbilī","nōbilia","Nōbilior","Nobiliōre","nōbilis","nōbilissima","nōbilissimam","nobilissimi","nōbilissimīs","nōbilissimō","nōbilissimōs","nōbilissimus","nobilium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tres {{nobilissimi}} Aedui capti ad Caesarem perducuntur: Cotus, praefectus equitum, qui controversiam cum Convictolitavi proximis comitiis habuerat, et Cavarillus, qui post defectionem Litavicci pedestribus copiis praefuerat, et Eporedorix, quo duce ante adventum Caesaris Aedui cum Sequanis bello contenderant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nobilitare","latin":"(nōbilitō) nōbilitāre","headword":"nōbilitāre","letter":"n","pos":"","posGroup":"other","english":"make famous","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nobilitas","latin":"nōbilitās, -ātis ( f.)","headword":"nōbilitās","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"renown, nobility, nobles; nobility, high birth","forms":["nobilitas","nōbilitāte","nōbilitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Omnis noster equitatus, omnis {{nobilitas}} interiit; principes civitatis, Eporedorix et Viridomarus, insimulati proditionis ab Romanis indicta causa interfecti sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nobilito","latin":"nobilito, nobilitare, nobilitavi, nobilitatus","headword":"nobilito","letter":"n","pos":"verb","posGroup":"verb","english":"make known/noted/renown; render famous/notorious; ennoble; make more majestic","forms":["nōbilitātus","nōbiliter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Neque multō posteā Eudoxus astrologus in terrā Graeciā {{nōbilitātus}} est, Lacedaemoniīque ab Athēniēnsibus apud Corinthum superātī duce Phormiōne; et M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"noceo","latin":"noceō, -ēre, -uī, -itum","headword":"noceō","letter":"n","pos":"verb","posGroup":"verb","english":"harm (+ dat.)","forms":["noceant","noceās","nocēbant","nocēbat","nocēbit","nocēbō","nocendī","nocent","nocēre","nocērent","nocēret","nocet","nocuerat","nocueris","nocuērunt","nocuisse","nocuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum angelus clāmāvit dē caelō: Abrahame, continē manum tuam; nē {{noceās}} puerō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nocere","latin":"(noceō) nocēre, nocuisse","headword":"nocēre","letter":"n","pos":"verb","posGroup":"verb","english":"(intr. + dat.) harm; to harm (with dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"nocet","latin":"nocet","headword":"nocet","letter":"n","pos":"verb","posGroup":"verb","english":"harms, does harm to","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"noctu","latin":"noctū","headword":"noctū","letter":"n","pos":"adverb","posGroup":"adverb","english":"by night, at night","forms":["noctu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne {{noctu}} ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nocturnus","latin":"nocturnus, -a, -um","headword":"nocturnus","letter":"n","pos":"adjective","posGroup":"adjective","english":"nocturnal, at night","forms":["nocturna","nocturnīs","nocturno","nocturnōs","nocturnum","nocturnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque {{nocturno}} itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nocuus","latin":"nocuus, nocua, nocuum","headword":"nocuus","letter":"n","pos":"adjective","posGroup":"adjective","english":"hurtful, injurious","forms":["nocuus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"in-{{nocuus}} -ā -um - sine maleficiō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nodo","latin":"nodo, nodare, nodavi, nodatus","headword":"nodo","letter":"n","pos":"verb","posGroup":"verb","english":"tie in a knot/knots","forms":["nōdantur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cui pharetrā ex aurō, crīnēs {{nōdantur}} in aurum,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"nodus","latin":"nōdus, -ī","headword":"nōdus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"knot, bond","forms":["nōdōs","nōdum","nōdus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum igitur ōlim in illam silvae partem pervēnisset, nymphārum ūriī arcum sagittāsque suās trādidit, alterī vērō vestem dedit; duae calceōs ex pedibus exuunt, dum tertia capillōs per collum sparsōs colligit in {{nōdum}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nolle","latin":"nōlle","headword":"nōlle","letter":"n","pos":"verb","posGroup":"verb","english":"not to want; to be unwilling, not want","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"nolo","latin":"nōlō, nōlle","headword":"nōlō","letter":"n","pos":"verb","posGroup":"verb","english":"be unwilling, not want; not wish, be unwilling","forms":["nōlēbat","nōlentem","nōlī","nōlim","nōlīs","nōlit","nōlīte","nōlle","nōllent","nōllet","nōlō","nōluerant","nōluerat","nōluit","nōlumus","nōlunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Nolite}} hos vestro auxilio exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi imbecillitate omnem Galliam prosternere et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nomen","latin":"nōmen, nōminis","headword":"nōmen","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"(n.) name; noun, name","forms":["nōmen","nōmina","nominī","Nōminibus","nōminis","nōminum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iānitor, cui {{nōmen}} est Sanniō, Dōrippam ēgredientem Sanniō -ōnis interrogat: “Quō īs, Dōrippa?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nominare","latin":"nōmināre","headword":"nōmināre","letter":"n","pos":"verb","posGroup":"verb","english":"to call, name","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"nominat","latin":"nōminat, nōmināre","headword":"nōminat","letter":"n","pos":"","posGroup":"other","english":"name, call","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nominatim","latin":"nominatim","headword":"nominatim","letter":"n","pos":"adverb","posGroup":"adverb","english":"by name","forms":["nominatim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, pari aetate et gratia sed genere dispari, quem Caesar ab Diviciaco sibi traditum ex humili loco ad summam dignitatem perduxerat, in equitum numero convenerant {{nominatim}} ab eo evocati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nominativus","latin":"nōminātīvus, -ī (cāsus)","headword":"nōminātīvus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"nominative","forms":["Nōminātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: '{{Nōminātīvus}}, genetīvus, dativus, accūsātīvus, vocātīvus, ablātīvus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"nominatur","latin":"nōminātur","headword":"nōminātur","letter":"n","pos":"verb","posGroup":"verb","english":"is named","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"nomine","latin":"nomine","headword":"nomine","letter":"n","pos":"adverb","posGroup":"adverb","english":"in name only, nominally (ABL S of nomen)","forms":["nomine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ex his Bellovaci suum numerum non compleverunt, quod se suo {{nomine}} atque arbitrio cum Romanis bellum gesturos dicebant, neque cuiusquam imperio obtemperaturos; rogati tamen ab Commio pro eius hospitio duo milia una miserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nomino","latin":"nomino, nominare, nominavi, nominatus","headword":"nomino","letter":"n","pos":"verb","posGroup":"verb","english":"name, call","forms":["nominabant","nōminābantur","nōminābātur","nōmināmus","nōmināns","nōminant","nōminantur","nōmināre","nōminārēmus","nōminārētur","nōminārī","nōminat","Nōminātae","nōminātī","nōminātum","nōminātur","nōmināverant","nōmināvit","nōminō","nōminor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis hamis infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos {{nominabant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"non","latin":"nōn","headword":"nōn","letter":"n","pos":"adverb","posGroup":"adverb","english":"not","forms":["non"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postremo in acie praestare interfici quam {{non}} veterem belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"non iam","latin":"nōn iam","headword":"nōn iam","letter":"n","pos":"adverb; phrase","posGroup":"adverb","english":"no longer","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"non procul","latin":"nōn procul","headword":"nōn procul","letter":"n","pos":"phrase","posGroup":"other","english":"not distant, near by","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"non solum ... sed etiam","latin":"nōn sōlum ... sed etiam","headword":"nōn sōlum ... sed etiam","letter":"n","pos":"conjunction","posGroup":"conjunction","english":"not only ... but also","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"non solum…sed etiam","latin":"nōn sōlum…sed etiam","headword":"nōn sōlum…sed etiam","letter":"n","pos":"","posGroup":"other","english":"not only…but also","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nona","latin":"Nona, Nonae","headword":"Nona","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"Nones (pl.), abb. Non.; 7th of month, March, May, July, Oct., 5th elsewhen","forms":["nōna"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aemilia: 'Hōra {{nōna}} est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"nonae","latin":"nōnae, -ārum","headword":"nōnae","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(pl.) 5th/7th of the month; the Nones (fifth or seventh day)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"nonagesimus","latin":"nōnāgēsimus, -a, -um","headword":"nōnāgēsimus","letter":"n","pos":"","posGroup":"other","english":"ninetieth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nonaginta","latin":"nōnāgintā","headword":"nōnāgintā","letter":"n","pos":"numeral","posGroup":"numeral","english":"ninety","forms":["nōnāgēsimō","nōnāgēsimum","nōnāgintā"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ūnus, duo, trēs, quattuor, quīnque, sex, septem, octō, novem, decem..... nōnāgintā.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nondum","latin":"nōndum","headword":"nōndum","letter":"n","pos":"adverb","posGroup":"adverb","english":"not yet","forms":["nondum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nihilo minus clandestinis nuntiis legationibusque Allobrogas sollicitat, quorum mentes {{nondum}} ab superiore bello resedisse sperabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nongent","latin":"nongent","headword":"nongent","letter":"n","pos":"numeral","posGroup":"numeral","english":"nine hundred","forms":["nōngentī","nōngentīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sextus: 'Centum, ducentī, trecentī, quadringentī, quīngentī, sēscentī, septingentī, octingentī, nōngentī, mīlle.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"nongenti","latin":"nōngentī, -ae, -a","headword":"nōngentī","letter":"n","pos":"","posGroup":"other","english":"nine hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nonne","latin":"nōnne?","headword":"nōnne","letter":"n","pos":"particle","posGroup":"particle","english":"not?; (expects the answer “yes”)","forms":["nōnne"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Nōnne}} Mēdī est pecūnia quae est in sacculō eius?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nonnemo","latin":"nonnemo, nonneminis","headword":"nonnemo","letter":"n","pos":"noun","posGroup":"noun","english":"some persons, a few","forms":["nōnnēmō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aliī ab indice nōminātī ‘esse sē Christiānōs’ dīxērunt — et mox negāvērunt: ‘fuisse quīdam, sed dēsiisse’, quīdam ‘ante triennium’, quīdam ‘ante plūrēs annōs’, nōnnēmō etiam ‘ante vīgintī’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"nonnihil","latin":"nōnnihil","headword":"nōnnihil","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"not a little, something","forms":["nōnnihil"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Atque hic tantus vir tantīsque bellīs distrīctus {{nōnnihil}} temporis tribuit litterīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nonnulli","latin":"nōnnūllī, -ae, -a","headword":"nōnnūllī","letter":"n","pos":"","posGroup":"other","english":"several","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nonnullus","latin":"nonnullus, nonnulla, nonnullum (gen -ius)","headword":"nonnullus","letter":"n","pos":"adjective","posGroup":"adjective","english":"some, several, a few; one and another; considerable","forms":["nōnnūlla","Nōnnūllae","nōnnūllī","nōnnūllōrum","nōnnūllōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At nēmō illōrum, etsī omnēs magnās dīvitiās habēbant, bonō animō erat, immō nōnnūllī iīs minābantur atque eōs celeriter abīre iubēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nonnumquam","latin":"nōnnumquam","headword":"nōnnumquam","letter":"n","pos":"adverb","posGroup":"adverb","english":"often","forms":["nōnnumquam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ut vērō amōris dolōrem, quō animus eius afficiēbātur, levāret, {{nōnnumquam}} in celsum saxum ascendēbat, unde, mare prōspiciēns, tībiīs ūsus hōc modō canēbat: “Ō fōrmōsa Galatēa, cāseō candidior, agnō suāvior, ūva mātūra dulcior, cūr mē amantem contemnis, sī dīligenter tē cūrō?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nonus","latin":"nōnus, -a, -um","headword":"nōnus","letter":"n","pos":"","posGroup":"other","english":"ninth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"nos","latin":"nōs","headword":"nōs","letter":"n","pos":"pronoun","posGroup":"pronoun","english":"we, us, ourselves; we; we, us","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"noscere","latin":"(nōscō) nōscere, nōvisse, nōtum","headword":"nōscere","letter":"n","pos":"verb","posGroup":"verb","english":"get to know; pf.: know; to get to know","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"noscitare","latin":"(nōscitō) nōscitāre","headword":"nōscitāre","letter":"n","pos":"","posGroup":"other","english":"recognize","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"noscito","latin":"noscito, noscitare, noscitavi, noscitatus","headword":"noscito","letter":"n","pos":"verb","posGroup":"verb","english":"recognize; be acquainted with","forms":["nōscitāns","nōscitō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eum et rōbora virōrum sequēbantur, et ipse, quācumque in parte premī ac labōrāre sēnserat suōs, impigrē ferēbat opem, īnsignemque armīs et hostēs summā vī petēbant et tuēbantur cīvēs — dōnec Īnsubēr eques faciē quoque {{nōscitāns}} cōnsulem 'Ēn' inquit 'hic est' populāribus suīs 'quī legiōnēs nostrās cecīdit agrōsque et urbem est dēpopulātus!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nosco","latin":"nōscō, -ere, nōvī, nōtum","headword":"nōscō","letter":"n","pos":"verb","posGroup":"verb","english":"come to know, get to know; to know, recognise","forms":["nōscam","nōscar","nōscenda","nōscere","nōsceret","nōscēs","nōverant","nōverat","nōvēre","nōverīs","noverit","nōvimus","nōvisse","nōvissēmus","nōvisset","nōvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Caesar, omni exercitu ad utramque partem munitionum disposito, ut, si usus veniat, suum quisque locum teneat et {{noverit}}, equitatum ex castris educi et proelium committi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"noster","latin":"noster, nostra, nostrum","headword":"noster","letter":"n","pos":"adjective","posGroup":"adjective","english":"our, ours; our","forms":["noster","nostra","nostrae","nostram","nostrarum","nostras","nostri","nostris","nostro","nostrorum","nostros","nostrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque {{nostris}} renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nota","latin":"nota, -ae","headword":"nota","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"mark, sign","forms":["nota"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Illa fabula omnibus {{nota}} est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"notare","latin":"(notō) notāre","headword":"notāre","letter":"n","pos":"","posGroup":"other","english":"mark, note, censure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"notatio","latin":"notatio, notationis","headword":"notatio","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"marking","forms":["notātiō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eius modī ōrātiō, quā notantur vitia hominis, appellātur ‘notātiō’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"notitia","latin":"notitia, notitiae","headword":"notitia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"notice; acquaintance","forms":["nōtitiā"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum haec loquitur, venit in aedēs quāsdam in quibus sodālicium erat eōdem diē futūrum; quō iste — prō nōtitiā dominī aedium — ingreditur cum hospitibus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"noto","latin":"noto, notare, notavi, notatus","headword":"noto","letter":"n","pos":"verb","posGroup":"verb","english":"observe; record; brand; write, inscribe","forms":["notandīs","notant","notantur","notāre","notat","notāvī","Notāvimus","Notāvit","Notō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cum rīsī, arrīdēs; lacrimās quoque saepe notāvī mē lacrimante tuās!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"notum","latin":"notum, noti","headword":"notum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"notorious facts (pl.); scandal","forms":["notum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum {{notum}} atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"notus","latin":"nōtus, -a, -um","headword":"nōtus","letter":"n","pos":"adjective","posGroup":"adjective","english":"known; familiar, well-known","forms":["notae","nōtam","nōtās","nōtī","nōtior","nōtīs","nōtissima","nōtissimus","nōtōs","nōtus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eleazarus rem prāvam suādentibus nōluit assenfirī:\"Aetafī nostrae\"inquit,\"nōn convenit ista simulātiō: nōn committam ut perīculōsum exemplum adulēscentibus relinquam: multō satius est perīre, quam propter brevem vītae ūsūram turpirūdinis {{nōtam}} meō nominī inūrere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"novella","latin":"novella, novellae","headword":"novella","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"news (literary kind)","forms":["novella"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut fugiunt aquilās, timidissima turba, columbae, utque fugit vīsōs agna {{novella}} lupōs, sīc illae timuēre virōs sine lēge ruentēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"novellus","latin":"novellus, -a, -um","headword":"novellus","letter":"n","pos":"adjective","posGroup":"adjective","english":"new, young","forms":["novellus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{novellus}} -ā -um columba","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"novem","latin":"novem","headword":"novem","letter":"n","pos":"numeral","posGroup":"numeral","english":"nine","forms":["nōnae","nōnam","nōnās","nōnīs","nōnō","nōnus","novem"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ūnus, duo, trēs, quattuor, quīnque, sex, septem, octō, {{novem}}, decem..... nōnāgintā.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"november","latin":"November, Novembris, Novembre","headword":"November","letter":"n","pos":"adjective","posGroup":"adjective","english":"November (month/mensis understood); abb. Nov.; of/pertaining to November","forms":["November","Novembrem","Novembrēs","Novembribus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; Octōber, decimus; {{November}}, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"noverca","latin":"noverca, novercae","headword":"noverca","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"stepmother","forms":["noverca"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Saepe vērō {{noverca}} ē rēgiā venīre solēbat eōsque spectābat lūdentēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"novi","latin":"novi, novisse, notus","headword":"novi","letter":"n","pos":"verb","posGroup":"verb","english":"know, know of; know how, be able (to); experience; (PERF form, PRES force)","forms":["novi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum {{novi}} aliquid ab eis iniri consili intellexissent, gladiis destrictis portas occupaverunt suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"novissime","latin":"novissime","headword":"novissime","letter":"n","pos":"adverb","posGroup":"adverb","english":"lately, very recently; last, after all else; for last time; lastly; in the end","forms":["novissimē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam — alia magna et ēgregia tua omittam — novissimē rediēns Numantiā mēque rēgnumque meum glōriā honōrāvistī tuāque virtūte nōbīs Rōmānōs ex amīcīs amīcissimōs fēcistī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"novissimum","latin":"novissimum, novissimi","headword":"novissimum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"rear (pl.), those at the rear (the freshest troops)","forms":["novissimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"De media nocte missus equitatus {{novissimum}} agmen consequitur; magnus numerus capitur atque interficitur, reliqui ex fuga in civitates discedunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"novitas","latin":"novitās, -ātis ( f.)","headword":"novitās","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"novelty, inexperience","forms":["novitās","novitate","novitātem","novitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deprensis navibus circiter quinquaginta celeriterque coniunctis atque eo militibus iniectis et rei {{novitate}} perterritis oppidanis, quorum magna pars erat ad bellum evocata, sine contentione oppido potitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"novo","latin":"novo, novare, novavi, novatus","headword":"novo","letter":"n","pos":"verb","posGroup":"verb","english":"make new, renovate; renew, refresh, change","forms":["novanda","novandīs","novantem","novārētur","novō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīc taberna novō fulgure illūstrātur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"novus","latin":"novus, -a, -um","headword":"novus","letter":"n","pos":"adjective","posGroup":"adjective","english":"new; new, strange","forms":["nov","nova","novae","novam","novārum","novās","novīs","novissima","novissimae","novissimīs","novissimo","novōrum","novōs","novum","novus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hostes re {{nova}} perterriti, muro turribusque deiecti in foro ac locis patentioribus cuneatim constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nox","latin":"nox, noctis","headword":"nox","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) night","forms":["nocte","noctem","noctēs","noctī","noctibus","noctis","nox"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cenabenses paulo ante mediam {{noctem}} silentio ex oppido egressi flumen transire coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"noxa","latin":"noxa, -ae","headword":"noxa","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"harm, guilt; guilt, harm","forms":["noxam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cōnsōlantur aegram animī āvertendō {{noxam}} ab coāctā in auctōrem dēlictī: 'mentem peccāre, nōn corpus, et unde cōnsilium fūerit, culpam abesse.' 'Vōs' inquit 'vīderitis quid illī dēbeātur!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"noxia","latin":"noxia, noxiae","headword":"noxia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"crime, fault","forms":["noxia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Gracchus, quōrum maiōrēs Pūnicō atque aliīs bellīs multum reī pūblicae addiderant, vindicāre plēbem in lībertātem et paucōrum scelera patefacere coepēre, nōbilitās {{noxia}} atque eō perculsa Gracchōrum āctiōnibus obviam ierat, et prīmō Tiberium, dein paucōs post annōs eādem ingredientem Gāium, tribūnum alterum, alterum triumvirum colōniīs dēdūcendīs, cum M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"noxius","latin":"noxius, -a, -um","headword":"noxius","letter":"n","pos":"","posGroup":"other","english":"guilty","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nubere","latin":"(nūbō) nūbere, nūpsisse","headword":"nūbere","letter":"n","pos":"verb","posGroup":"verb","english":"(+ dat.) marry; to marry (a man) (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"nubes","latin":"nūbēs, nūbis","headword":"nūbēs","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) cloud","forms":["nūbe","nūbem","nūbēs","nūbibus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sōl lūcet in caelō sine {{nūbibus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nubilum","latin":"nubilum, nubili","headword":"nubilum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"clouds (pl.), rain clouds","forms":["nūbilum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Caelum {{nūbilum}} suspiciēns gubernātor optat ut ventus in adversum vertātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"nubilus","latin":"nūbilus, -a, -um","headword":"nūbilus","letter":"n","pos":"adjective","posGroup":"adjective","english":"cloudy","forms":["nūbila"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tempora sī fuerint {{nūbila}}, sōlus eris!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"nubis","latin":"nubis, nubis","headword":"nubis","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"cloud/mist/haze/dust/smoke; sky/air; billowy formation (hair); swarm/multitude","forms":["nūbis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Illīs ēgredientibus praeībat columna {{nūbis}} interdiū, et columna ignis noctū, quae esset dux viae; nec umquam per quadrāgintā annōs dēfuit illā columnā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nubo","latin":"nubo, nubere, nupsi, nuptus","headword":"nubo","letter":"n","pos":"verb","posGroup":"verb","english":"marry, be married to","forms":["nubere","nūpserant","nūpsī","nupsit","nūptūra"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ēn Rebecca: proficīscātur tēcum, {{nūptūra}} Isaacō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nudare","latin":"(nūdō) nūdāre","headword":"nūdāre","letter":"n","pos":"","posGroup":"other","english":"bare, leave unprotected","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nudo","latin":"nudo, nudare, nudavi, nudatus","headword":"nudo","letter":"n","pos":"verb","posGroup":"verb","english":"lay bare, strip; leave unprotected","forms":["nūdant","nudata","nūdātam","nudatum","nūdāvit","nudentur","nudo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam cum in minora castra operis perspiciendi causa venisset, animadvertit collem, qui ab hostibus tenebatur, {{nudatum}} hominibus, qui superioribus diebus vix prae multitudine cerni poterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nudus","latin":"nūdus, -a, -um","headword":"nūdus","letter":"n","pos":"adjective","posGroup":"adjective","english":"naked; naked, bare","forms":["nūda","nūdam","nūdās","Nūdī","nūdīs","nūdōs","nūdum","nūdus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: “Sed collum tibi {{nūdum}} est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"nuga","latin":"nuga, nugae","headword":"nuga","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"trifles (pl.), nonsense; trash; frivolities; bagatelle(s)","forms":["nūgārum","nūgās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tantalus vēro, aliquantum turbātus, ut sē excūsāret, deīs tālia verba dicēbat “Ignōscite mihi dēbili: nimium ego vīnī biberam atque ēbrius {{nūgās}} dīcere coepī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nugae","latin":"nūgae, -ārum","headword":"nūgae","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"trifles; trifles, nonsense","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"nullus","latin":"nūllus, -a, -um","headword":"nūllus","letter":"n","pos":"adjective","posGroup":"adjective","english":"no, none","forms":["nulla","nullae","nullam","nūllās","nulli","nullis","nūllīus","nullo","nūllōs","nullum","nullus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se {{nullum}} periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"num","latin":"num?","headword":"num","letter":"n","pos":"particle","posGroup":"particle","english":"if, whether; expects a “no” answer; (introduces a “no” question)","forms":["num"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia: “Nōn {i}i{/i}, sed {i}y{/i}:{i} i–y, i–y. {/i} {{Num}} {i}y{/i} littera Latīna est?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"numen","latin":"nūmen, -inis (n.)","headword":"nūmen","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"divine will; divine will, divinity","forms":["nūmen","nūmina","nūmine","nūminum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Asa Deō grātus ob pietātem fuit: quippe ārās falsōrum {{nūminum}} ēvertit, et impiōs rēgnō suō expulit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"numerat","latin":"numerat","headword":"numerat","letter":"n","pos":"verb","posGroup":"verb","english":"count; counts","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"numero","latin":"numero, numerare, numeravi, numeratus","headword":"numero","letter":"n","pos":"verb","posGroup":"verb","english":"count, add up, reckon/compute; consider; relate; number/enumerate, catalog; pay","forms":["numerā","numerābant","numerābantur","numerābis","numerant","numerantur","numerāre","numerāret","numerārī","numerās","numerat","numerātīs","numerētur","numero"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium {{numero}} desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"numerosus","latin":"numerōsus, -a, -um","headword":"numerōsus","letter":"n","pos":"adjective","posGroup":"adjective","english":"numerous, many","forms":["numerōsā","numerōsīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deus fēcit foedus cum illō hīs verbīs: exī ē domō paternā, dēsere patriam, et pete regiōnem quam datūrus sum posterīs tuīs: augēbō tē prōle numerōsā; eris pater multārum gentium, ac per tē omnēs orbis nātiōnēs erunt bonīs cumulātae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"numerus","latin":"numerus, -ī","headword":"numerus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"number","forms":["numerī","numerīs","numerōs","numerum","numerus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum {{numerum}} militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"numida","latin":"Numida, Numidae","headword":"Numida","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"Numidian; (inhabitant of Numidia in North Africa)","forms":["Numida","Numidae","Numidam","Numidārum","Numidās","Numidīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Numida}} -ae adī jn « Numidia, regiō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nummularius","latin":"nummularius, nummulari(i)","headword":"nummularius","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"kind of small-change state banker; (to change foreign currency and test coins)","forms":["nummulāriī","nummulāriōs","nummulārium","Nummulārius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et invēnit in templō vēndentēs bovēs, et ovēs et columbās et ~ {{nummulāriōs}} sedentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nummus","latin":"nummus, -ī","headword":"nummus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"coin","forms":["nummī","nummīs","nummō","nummōrum","nummōs","nummum","nummus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dāvus, servus Iūliī, laetus est, quia {{nummum}} habet in sacculō suō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"numquam","latin":"numquam","headword":"numquam","letter":"n","pos":"adverb","posGroup":"adverb","english":"never","forms":["numquam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sibi {{numquam}} placuisse Avaricum defendi, cuius rei testes ipsos haberet; sed factum imprudentia Biturigum et nimia obsequentia reliquorum uti hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"numquid","latin":"numquid","headword":"numquid","letter":"n","pos":"adverb","posGroup":"adverb","english":"is it possible, surely ... not; can it be that; (question expecting negative)","forms":["Numquid"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Numquid}} et vōs vultis discipulī eius fierī?\"Maledīxerunt ergō eī et ēiēcērunt eum forās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nunc","latin":"nunc","headword":"nunc","letter":"n","pos":"adverb","posGroup":"adverb","english":"now","forms":["nunc"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At incerto etiam {{nunc}} exitu victoriae, cum Septimae legionis tribunis esset nuntiatum quae in sinistro cornu gererentur, post tergum hostium legionem ostenderunt signaque intulerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nunciam","latin":"nunciam","headword":"nunciam","letter":"n","pos":"adverb","posGroup":"adverb","english":"here and now; now at last","forms":["nūnciam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ALCVMENA: Age, aspice hūc, sīs, {{nūnciam}}:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"nuncupare","latin":"(nūncupō) nūncupāre","headword":"nūncupāre","letter":"n","pos":"","posGroup":"other","english":"designate, call","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"nuncupo","latin":"nuncupo, nuncupare, nuncupavi, nuncupatus","headword":"nuncupo","letter":"n","pos":"verb","posGroup":"verb","english":"call, name; express","forms":["nuncupātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea vīta via est in caelum et in hunc coetum eōrum quī iam vīxērunt et corpore laxātī illum incolunt locum quem vidēs' — erat autem is splendidissimō candōre inter flammās circus ēlūcēns — 'quem vōs, ut ā Graecīs accēpistis, \"orbem lacteum\" {{nuncupātis}}.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"nuntia","latin":"nuntia, nuntiae","headword":"nuntia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"female messenger; she who brings tidings (L+S)","forms":["nūntiā"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"MERCVRIVS: Tuae, sī quid vīs, nūntiā!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"nuntiare","latin":"(nūntiō) nūntiāre, -āvisse, -ātum","headword":"nūntiāre","letter":"n","pos":"verb","posGroup":"verb","english":"announce; to announce, report","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"nuntio","latin":"nuntio, nuntiare, nuntiavi, nuntiatus","headword":"nuntio","letter":"n","pos":"verb","posGroup":"verb","english":"announce/report/bring word/give warning; convey/deliver/relate message/greeting","forms":["nūntiābant","nūntiābantur","nūntiābit","nūntiābitis","nūntiant","nūntiantem","nūntiantī","nūntiāre","nūntiārentur","nūntiāret","nūntiārētur","nuntiari","nūntiat","nuntiata","nūntiātē","nuntiatis","nūntiātō","nuntiatum","nuntiatur","nūntiāvērunt","nūntiāvit","nūntiem","nūntient","nūntiet","nuntio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus in Italiam Caesari {{nuntiatis}}, cum iam ille urbanas res virtute Cn.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nuntium","latin":"nuntium, nunti(i)","headword":"nuntium","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"message, announcement; news; notice of divorce/annulment of betrothal","forms":["nūntium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad quem {{nūntium}} Iacobus, quasi ē gravī somnō excitātus, obstupuit, nec prīmum fīliīs rem nārrantibus fidem adhibēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nuntius","latin":"nūntius, -ī","headword":"nūntius","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"message, messenger; messenger; news","forms":["nūntiam","nuntii","nuntiis","nuntios","nūntius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Celeriter haec fama ac {{nuntii}} ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat neve ab hostibus diripiantur, praesertim cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nuo","latin":"nuo, nuere, nui, nuitus","headword":"nuo","letter":"n","pos":"verb","posGroup":"verb","english":"nod","forms":["nuam","nūēre","nuet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"in-{{nūēre}} — capīte mótō signum dare","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"nuper","latin":"nūper","headword":"nūper","letter":"n","pos":"adverb","posGroup":"adverb","english":"recently","forms":["nuper","nūperrimē"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dum haec apud Caesarem geruntur, Labienus eo supplemento, quod {{nuper}} ex Italia venerat, relicto Agedinci, ut esset impedimentis praesidio, cum IIII legionibus Lutetiam proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"nupta","latin":"nūpta, -ae","headword":"nūpta","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"wife","forms":["nūpta","nūptae","nūptam","nūptum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Habēbat ante oculōs ulmum pulcherrimam, ex quā pendēbant mīrābilēs ūvae; quās cum multīs verbīs laudāvisset, “At sī arbor” inquit “stāret sine vīte, nūllā esset causā cūr hominēs eam peterent, praeter umbram, quam facit; haec quoque vītis, quae cum ulmō iūncta est, in arbore quiēscit; sī enim nōn {{nūpta}} esset, humī iacēret;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nuptia","latin":"nuptia, nuptiae","headword":"nuptia","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"marriage (pl.), nuptials, wedding","forms":["nūptiae","nūptiārum","nūptiās","nūptiīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum Saūl magna praemia et fīliae {{nūptiās}} eī prōmīsit, quī prōvocantis spolia rettulisset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nuptiae","latin":"nūptiae, -ārum (pl.)","headword":"nūptiae","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"wedding; marriage, wedding","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"nurus","latin":"nurus, -ūs ( f.)","headword":"nurus","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"daughter-in-law","forms":["nuribus","nurum","nurūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam Noëmus ipse ingressus est in arcam cum coniuge, tribus fīliīs et totidem {{nuribus}}, aquā maris et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nusquam","latin":"nusquam","headword":"nusquam","letter":"n","pos":"adverb","posGroup":"adverb","english":"nowhere","forms":["nusquam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{nusquam}} corpus erat; croceum prō corpore flōrem","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nuto","latin":"nuto, nutare, nutavi, nutatus","headword":"nuto","letter":"n","pos":"verb","posGroup":"verb","english":"waver, give way","forms":["nūtāns","nūtant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Salomōnī Roboāmus fīlius successit: is imperium culpā paternā iam {{nūtāns}} stultitiā suā ēvertit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nutrimentum","latin":"nutrimentum, nutrimenti","headword":"nutrimentum","letter":"n","pos":"noun (n.)","posGroup":"noun","english":"nourishment, sustenance","forms":["nūtrīmenta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{nūtrīmenta}} dedit, rapuitque in fōmite flammam.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"nutrio","latin":"nutrio, nutrire, nutrivi, nutritus","headword":"nutrio","letter":"n","pos":"verb","posGroup":"verb","english":"suckle. breast feed; nourish/feed/fuel, supply, build up; preserve, look after","forms":["nūtriat","nūtriēbat","nūtriēris","nūtrīrī","nūtrīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aperta fiscella, cernēns parvulum vāgientem, miserita est illīus: “Iste est” inquit “ūnus ex īnfantibus Hebraeōrum.” Tunc soror puerī accēdēns: “Vīsne” ait “ut arcessam mulierem Hebraeam, quae {{nūtriat}} parvulum?” et tunc vocāvit mātrem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nutrire","latin":"(nūtriō) nūtrīre, -īvisse, -ītum","headword":"nūtrīre","letter":"n","pos":"verb","posGroup":"verb","english":"feed, suckle; to suckle, nourish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"nutrix","latin":"nūtrīx, nūtrīcis","headword":"nūtrīx","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) (wet) nurse; nurse, wet-nurse","forms":["nūtrīce","nūtrīcem","nūtrīcēs","nūtrīcibus","nūtrīcis","nūtrīx"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dīmīsērunt ergō Rebeccam et {{nūtrīcem}} illīus, precantēs eī omnia prōspera.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nutus","latin":"nūtus, -ūs","headword":"nūtus","letter":"n","pos":"noun (m.)","posGroup":"noun","english":"nod, gravitation; nod, downward pressure","forms":["nūtū","nūtum","nūtūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iōsēphus ergō administrābat rem familiārem Putiphāris: omnia fīēbant ad {{nūtum}} eius, nec Putiphar ūllīus negōtiī cūram gerēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"nux","latin":"nux, nucis","headword":"nux","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"(f.) nut","forms":["nucēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sunt mihi etiam ūvae aurō similēs, {{nucēs}} atque varia genera malōrum, meile multō dulciōra.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"nympha","latin":"nympha, -ae","headword":"nympha","letter":"n","pos":"noun (f.)","posGroup":"noun","english":"nymph","forms":["nympha","nymphae","nympham","nymphārum","nymphās","nymphīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōlim NNausicaa cum aliīs puellīs et ancillīs suīs in ōrā maritimā pilā lūdēbat: illa, sīcut Diāna inter {{Nymphās}}, omnium fōrmōsissima esse vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"o","latin":"ō!","headword":"ō","letter":"o","pos":"interjection","posGroup":"interjection","english":"oh!; oh","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ob","latin":"ob","headword":"ob","letter":"o","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) on account of; because of, on account of (+ acc.); on account of, against","forms":["ob"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et {{ob}} eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obambulo","latin":"obambulo, obambulare, obambulavi, obambulatus","headword":"obambulo","letter":"o","pos":"verb","posGroup":"verb","english":"walk up to, so as to meet; traverse","forms":["obambulat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille quidem tōtam gemebundus {{obambulat}} Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"obdo","latin":"obdo, obdere, obdidi, obditus","headword":"obdo","letter":"o","pos":"verb","posGroup":"verb","english":"put before/against; shut, close, fasten","forms":["obde"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"et centum dūrīs postibus {{obde}} serás!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"obdormio","latin":"obdormio, obdormire, obdormivi, obdormitus","headword":"obdormio","letter":"o","pos":"verb","posGroup":"verb","english":"fall asleep","forms":["obdormiās","obdormīverit","obdormīvistī","obdormīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iter faciēns pervenit ad quemdam locum, ubi fessus dē viā pernoctāvit; supposuit lapidem capitī suō et {{obdormīvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obducere","latin":"(obdūcō) obdūcere (< dūcere)","headword":"obdūcere","letter":"o","pos":"","posGroup":"other","english":"draw over (to cover)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obduco","latin":"obduco, obducere, obduxi, obductus","headword":"obduco","letter":"o","pos":"verb","posGroup":"verb","english":"lead or draw before; cover/lay over; overspread; wrinkle; screen","forms":["obdūxerō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum obdūxerō nūbēs caelō, arcus meus appārēbit, et recordābor foederis meī, nec unquam dīluvium erit ad perdendum orbem terrārum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obducto","latin":"obducto, obductare, obductavi, obductatus","headword":"obducto","letter":"o","pos":"verb","posGroup":"verb","english":"lead in rivalry","forms":["obductā","obductō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"et nunc obductō cortice pressa latet;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"obeo","latin":"obeo, obire, obivi(ii), obitus","headword":"obeo","letter":"o","pos":"verb","posGroup":"verb","english":"go to meet; attend to; fall; die","forms":["obeundī","obeundum","obeuntis","obieris","obīret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Apud mīlitēs vērō, cum pariter perīcula {{obīret}} ac labōrēs tolerāret praedamque benignē largīrētur, tanta caritāte esse ut nōn pater Tarquinius potentior Rōmae quam fīlius Gabiīs esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obicere","latin":"(obiciō) obicere (< iacere)","headword":"obicere","letter":"o","pos":"","posGroup":"other","english":"place before, expose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obicio","latin":"obicio, obicere, objeci, objectus","headword":"obicio","letter":"o","pos":"verb","posGroup":"verb","english":"throw before/to, cast; object, oppose; upbraid; throw in one's teeth; present","forms":["obicī","obicienda","obicitur","obiēcit","obiectū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc Dāvīd inīquō pugnae locō hostibus obicī iussit, atque ita necandum cūrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obiectare","latin":"(obiectō) obiectāre","headword":"obiectāre","letter":"o","pos":"","posGroup":"other","english":"throw before or against; expose, abandon","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obiecto","latin":"objecto, objectare, objectavi, objectatus","headword":"objecto","letter":"o","pos":"verb","posGroup":"verb","english":"expose/throw (to); throw/put in the way; lay to one's charge, put before","forms":["obiectāre","obiectō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi castra in apertō locat, ubi ipse cum Āfrīs modo Hispānīsque cōnsīderet; Baliares cēteramque levem armātūram post montēs circumdūcit; equitēs ad ipsās faucēs saltūs, tumulīs aptē tegentibus, locat, ut, ubi intrāssent Rōmānī, obiectō equitātū clausa omnia lacū ac montibus essent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obiectum","latin":"objectum, objecti","headword":"objectum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"accusation, charge; S:object, something presented to the senses","forms":["obiectum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"AMPHITRYO: Huic hominī nescioquid est malī mala {{obiectum}} manū,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"obiectus","latin":"objectus, objecta -um, objectior -or -us, objectissimus -a -um","headword":"objectus","letter":"o","pos":"adjective","posGroup":"adjective","english":"opposite","forms":["obiectis","obiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tantis subito difficultatibus {{obiectis}} ab animi virtute auxilium petendum videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obire","latin":"(obeō) obīre (< īre)","headword":"obīre","letter":"o","pos":"","posGroup":"other","english":"meet, visit, go into, enter upon, set; meet, visit, go into","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obiter","latin":"obiter","headword":"obiter","letter":"o","pos":"adverb","posGroup":"adverb","english":"on the way, by the way, in passing","forms":["obiter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ad summam, lacte gallînäceum sî quaesierīs, domî näscerëttlr, apēs ab Athënîs iussit afferrî: {{obiter}} et nec est quod pūtēs :nec causa est cūr putēs (: nôlî putâre) Graeciae (caput: Athênae) ut sibi ex Indiā (Indiā -aeﬁ tum nâtum ex asinô et equâ animî b. : eius b.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"obitus","latin":"obitus, -ūs","headword":"obitus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"death","forms":["obitum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hāc igitur, quā dīximus, aetāte cum patre in Hispāniam profectus est, cuius post {{obitum}}, Hasdrubale imperātōre suffectō, equitātuī omnī praefuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obligare","latin":"(obligō) obligāre","headword":"obligāre","letter":"o","pos":"","posGroup":"other","english":"bind","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obligo","latin":"obligo, obligare, obligavi, obligatus","headword":"obligo","letter":"o","pos":"verb","posGroup":"verb","english":"bind, oblige","forms":["obligāre","obligātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ezechliis, tantō perlcūlō lTuerātus, in summā pāce reliquum vītae tempus ēgit: omnī ā illī reliciter cēdēbant, quia Deus illī favēbat; ipse tot beneficiīs dīvīnīs {{obligātus}}, in eādem cōnstanter pietāte mānsit: omnem suam spem in Deī auxiliō posuit; iīs rēbus, quae Deō placēbant, animum semper intendit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obliquo","latin":"oblīquō","headword":"oblīquō","letter":"o","pos":"adverb","posGroup":"adverb","english":"to the side","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"obliquus","latin":"obliquus, obliqua, obliquum","headword":"obliquus","letter":"o","pos":"adjective","posGroup":"adjective","english":"slanting; oblique","forms":["obliquis","oblīquō","oblīquōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ante hos {{obliquis}} ordinibus in quincuncem dispositis scrobes tres in altitudinem pedes fodiebantur paulatim angustiore ad infimum fastigio.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oblitus","latin":"oblitus, oblita, oblitum","headword":"oblitus","letter":"o","pos":"adjective","posGroup":"adjective","english":"forgetful (with gen.)","forms":["oblītus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tamen praefectus pincernārum {{oblītus}} est Iōsēphī, nec illīus in sē meritī recordātus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"oblivio","latin":"oblīviō, -ōnis ( f.)","headword":"oblīviō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"a forgetting; oblivion","forms":["oblīviōne","oblīviōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mithridātēs autem omne reliquum tempus nōn ad {{oblīviōnem}} veteris bellī, sed ad comparātiōnem novī contulit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"oblivisci","latin":"(oblīviscor) oblīvīscī, oblītum","headword":"oblīvīscī","letter":"o","pos":"verb","posGroup":"verb","english":"forget; to forget (+ gen.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"obliviscitur","latin":"oblīvīscitur","headword":"oblīvīscitur","letter":"o","pos":"verb","posGroup":"verb","english":"forgets (with gen.)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"obliviscor","latin":"oblīvīscor, -ī, oblītus sum","headword":"oblīvīscor","letter":"o","pos":"verb","posGroup":"verb","english":"forget (+ gen.)","forms":["oblīta","oblītae","oblīte","oblītī","oblītōs","oblītum","oblīvīscāris","oblīvīscendum","Oblīvīscēre","oblīvīscerētur","oblīvīscī","oblīvīscitur","oblīvīscor","oblīvīscuntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Oblītī sunt Deī creātōris; adōrābant sōlem et lūnam; nōn verēbantur parentēs; dīcēbant mendācium; faciēbant fraudem, fūrtum, homicīdium; ūnō verbō, sē contāminābant omnibus flāgitiīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obmutescere","latin":"(obmūtēscō) obmūtēscere, -tuisse","headword":"obmūtēscere","letter":"o","pos":"","posGroup":"other","english":"become speechless","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obmutesco","latin":"obmutesco, obmutescere, obmutui, -","headword":"obmutesco","letter":"o","pos":"verb","posGroup":"verb","english":"lose one's speech, become silent","forms":["obmūtuit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aenēās vērō {{obmūtuit}} amēns, tantō imperiō deōrum attonitus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obnixus","latin":"obnixus, obnixa, obnixum","headword":"obnixus","letter":"o","pos":"adjective","posGroup":"adjective","english":"resolute, determined; obstinate","forms":["obnīxus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"lūmina et {{obnīxus}} cūram sub corde premēbat.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"obnoxius","latin":"obnoxius, obnoxia, obnoxium","headword":"obnoxius","letter":"o","pos":"adjective","posGroup":"adjective","english":"liable; guilty","forms":["obnoxia","obnoxiī","obnoxiōs","obnoxius"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam ut cuiusque studium ex aetāte flagrābat, aliīs scorta praebēre, aliīs canēs atque equōs mercārī, postrēmō neque sūmptuī neque modestiae suae parcere, dum illōs {{obnoxiōs}} fīdōsque sibi faceret.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"obnubere","latin":"(obnūbō) obnūbere, -ūpsisse, -ūptum","headword":"obnūbere","letter":"o","pos":"","posGroup":"other","english":"veil, cover","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obnubo","latin":"obnubo, obnubere, obnupsi, obnuptus","headword":"obnubo","letter":"o","pos":"verb","posGroup":"verb","english":"veil, cover (the head)","forms":["obnūbe","obnūbitō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī vincent, caput obnūbitō!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"oboediens","latin":"oboediens, (gen.), oboedientis","headword":"oboediens","letter":"o","pos":"adjective","posGroup":"adjective","english":"obedient, submissive","forms":["oboedientium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Namque eōrum animī quī sē corporis voluptātibus dēdiderunt eārumque sē quasi ministrōs praebuērunt impulsūque libīdinum voluptātibus {{oboedientium}} deōrum et hominum iūra violāvērunt, corporibus ēlāpsī circum terram ipsam volūtantur nec hunc in locum, nisi multīs exagitātī saeculīs, revertuntur.' Ille discessit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"oboedientia","latin":"oboedientia, oboedientiae","headword":"oboedientia","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"obedience, compliance, submission to authority","forms":["oboedientia"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Omnēs hominēs quī sēsē student praestāre cēterīs animālibus summā ope nītī decet, nē vītam silentiō trānseant velutī pecora, quae nātūra prōna atque ventrī {{oboedientia}} fīnxit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"oboedio","latin":"oboedio, oboedire, oboedivi, oboeditus","headword":"oboedio","letter":"o","pos":"verb","posGroup":"verb","english":"obey; listen/harken/submit (to); be subject/obedient/responsible/a slave (to)","forms":["oboedīre","oboedīrent","oboediunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Īris igitur, vēlōcissima ad Somnī spēluncam volāvit (Somnus enim est deus cui somnia {{oboediunt}}).","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"oboedire","latin":"(oboediō) oboedīre, -īvisse/ iisse ({i}+ dat.{/i})","headword":"oboedīre","letter":"o","pos":"verb","posGroup":"verb","english":"obey; to obey (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"oboriri","latin":"(oborior) oborīrī (< orīrī)","headword":"oborīrī","letter":"o","pos":"","posGroup":"other","english":"spring up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obortus","latin":"obortus, oborta, obortum","headword":"obortus","letter":"o","pos":"adjective","posGroup":"adjective","english":"rising, flowing","forms":["oborta","obortae","obortīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ut vērō summō dēspexit ab aethere terrās īnfēlīx Phaethōn penitus penitusque iacentēs, palluit et subitō genua intremuēre timōre suntque oculīs tenebrae per tantum lūmen {{obortae}}, et iam māllet equōs numquam tetigisse paternōs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"obrepere","latin":"(obrēpō) obrēpere (< repere)","headword":"obrēpere","letter":"o","pos":"verb","posGroup":"verb","english":"creep up, steal up; to creep up secretly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"obrepo","latin":"obrepo, obrepere, obrepsi, obreptus","headword":"obrepo","letter":"o","pos":"verb","posGroup":"verb","english":"creep up on/approach unawares/unobserved; sneak/drop in; pay surprise visit on","forms":["obrēpentēs","obrēpere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Superbiam fuge, neque eam in animum aut in sermōnem sinās {{obrēpere}}.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obrigescere","latin":"(obrigēscō) obrigēscere, -uisse","headword":"obrigēscere","letter":"o","pos":"","posGroup":"other","english":"become stiff","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obrigesco","latin":"obrigesco, obrigescere, obrigui, -","headword":"obrigesco","letter":"o","pos":"verb","posGroup":"verb","english":"stiffen","forms":["obriguisse"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cernis autem eandem terram quasi quibusdam redimītam et circumdatam cingulīs, ē quibus duōs maximē inter sē dīversōs et caelī verticibus ipsīs ex utrāque parte subnīxōs {{obriguisse}} pruīnā vidēs, medium autem illum et maximum sōlis ārdōre torrērī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obruere","latin":"(obruō) obruere (< ruere)","headword":"obruere","letter":"o","pos":"","posGroup":"other","english":"cover up, bury, crush","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obruo","latin":"obruo, obruere, obrui, obrutus","headword":"obruo","letter":"o","pos":"verb","posGroup":"verb","english":"cover up, hide, bury; overwhelm, ruin; crush","forms":["obrue","obruēre","obruērunt","obruī","obruitur","obruta","obrutus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Metū perculsī Aegyptiī coepērunt fugere; at Deus dīxit Moȳsī: “Extende rūrsus dextram in mare, ut aquae revertantur in locum suum.” Pāruit Moysēs, et statim aquae refluentēs {{obruērunt}} Aegyptiōs, et eōrum currūs, et equitēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obrussa","latin":"obrussa, obrussae","headword":"obrussa","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"assay; test; assaying/testing of gold; [aurum ad ~ => tested/fine gold]","forms":["obrussā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ultimô etiam periscelidês resolvit et rēticulum aureum quem ‘ex obrussā’ esse dîcëbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"obscenum","latin":"obscenum, obsceni","headword":"obscenum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"private parts (pl.), external sexual/excretory organs; excrements (L+S); urine","forms":["obscēnum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fūsaque in {{obscēnum}} sē vertere vīna cruōrem;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"obscenus","latin":"obscenus, obscena -um, obscenior -or -us, obscenissimus -a -um","headword":"obscenus","letter":"o","pos":"adjective","posGroup":"adjective","english":"repulsive, detestable; foul; indecent, obscene, lewd; (sexual/excretory things)","forms":["obscēnae","obscēnīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"partibus {{obscēnīs}} opposuisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"obscurare","latin":"(obscūrō) obscūrāre","headword":"obscūrāre","letter":"o","pos":"","posGroup":"other","english":"obscure, darken","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obscuro","latin":"obscuro, obscurare, obscuravi, obscuratus","headword":"obscuro","letter":"o","pos":"verb","posGroup":"verb","english":"darken, obscure; conceal; make indistinct; cause to be forgotten","forms":["obscūrāre","obscūrātō","obscūrātus","obscūrō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dnus autem d ē hīs latrōnibus, quī pendēbant, blasphēmābat eum, dīcēns:\"Sī tū es Chrīstus, salvā tē ipsum et nōs.\"Et alter ihcrepābat eum dīcēns:\"Neque tū timēs Deum?\"Et dīxit illī Jēsus:\"Hodiē mēcum eris in paradīsō.\"Et {{obscūrātus}} est sōl, et vēlum temp lī scissum est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obscurus","latin":"obscūrus, -a, -um","headword":"obscūrus","letter":"o","pos":"adjective","posGroup":"adjective","english":"dark; dark, obscure","forms":["obscūra","obscūram","obscūrās","obscūrē","obscūrī","obscūrīs","obscūrōs","obscūrum","obscūrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: “Sed {{obscūrus}} est hortus vesperī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"obsecro","latin":"obsecro, obsecrare, obsecravi, obsecratus","headword":"obsecro","letter":"o","pos":"verb","posGroup":"verb","english":"entreat/beseech/implore/pray; (w/deity as object); [fidem ~ => beg support]","forms":["obsecrant","obsecrantēs","obsecrō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque {{obsecrant}} ut suis fortunis consulat neve ab hostibus diripiantur, praesertim cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsecundare","latin":"(obsecundō) obsecundāre","headword":"obsecundāre","letter":"o","pos":"","posGroup":"other","english":"comply with, obey (intr. + dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obsequentia","latin":"obsequentia, obsequentiae","headword":"obsequentia","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"obsequiousness; complaisance","forms":["obsequentia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sibi numquam placuisse Avaricum defendi, cuius rei testes ipsos haberet; sed factum imprudentia Biturigum et nimia {{obsequentia}} reliquorum uti hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsequi","latin":"(obsequōr) obsequī (< sequī)","headword":"obsequī","letter":"o","pos":"","posGroup":"other","english":"comply with, obey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obsequium","latin":"obsequium, obsequi(i)","headword":"obsequium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"compliance (act/form/sex/orders); consideration/deference/solicitude; services","forms":["obsequiō","obsequium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{obsequium}} -ī 7 (€ obsequī) - indul-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"obsequor","latin":"obsequor, obsequi, obsecutus sum","headword":"obsequor","letter":"o","pos":"verb","posGroup":"verb","english":"yield to; humor","forms":["obsecūtus","obsequar","obsequerētur","obsequī","obsequitur","obsequor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī vestrō {{obsequar}} cōnsiliō, hominum quidem suppliciīs ēripiar, sed Īram dīvīnam nōn effugiam.\"Hīs dicfīs, mortem fortiter subiit, aetēmamque glōriam est cōnsecūtus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obsero","latin":"obsero, obserare, obseravi, obseratus","headword":"obsero","letter":"o","pos":"verb","posGroup":"verb","english":"bolt, fasten, place a bar across; bar, prohibit access to; shot off, enclose","forms":["obserārī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Philistaeī occāsiōnem captantēs, portās obserārī iussērunt, nē quis exīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"observare","latin":"(observō) observāre","headword":"observāre","letter":"o","pos":"","posGroup":"other","english":"observe, respect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"observo","latin":"observo, observare, observavi, observatus","headword":"observo","letter":"o","pos":"verb","posGroup":"verb","english":"watch, observe; heed","forms":["observabat","Observābō","observāmus","observāret","observāte","observent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque {{observabat}} dispersosque, cum longius necessario procederent, adoriebatur magnoque incommodo adficiebat, etsi quantum ratione provideri poterat ab nostris occurrebatur, ut incertis temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obses","latin":"obses, -idis (m.)","headword":"obses","letter":"o","pos":"noun","posGroup":"noun","english":"hostage","forms":["obses","obsidem","obsides","obsidibus","obsidum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia {{obsidibus}} cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsessio","latin":"obsessio, obsessionis","headword":"obsessio","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"blockade, siege; obsession (Cal)","forms":["obsessione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Caesar ex eo loco quintis castris Gergoviam pervenit equestrique eo die proelio levi facto, perspecto urbis situ, quae posita in altissimo monte omnes aditus difficiles habebat, de expugnatione desperavit; de {{obsessione}} non prius agendum constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsideo","latin":"obsideo, obsidere, obsedi, obsessus","headword":"obsideo","letter":"o","pos":"verb","posGroup":"verb","english":"blockade, besiege, invest, beset; take possession of","forms":["obsēdissent","obsēdit","obsessa","obsessōs","obsessum","obsessus","obsidebantur","obsīdendum","obsidēns","obsident","obsidēre","obsidērent","obsidērentur","obsidēret","obsidērētur","obsidērī","obsidet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hos continuo in itinere adorti omnibus impedimentis exuunt; repugnantes diem noctemque {{obsident}}; multis utrimque interfectis maiorem multitudinem ad arma concitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsidere","latin":"(obsideō) obsidēre, -sidisse, -sessum","headword":"obsidēre","letter":"o","pos":"","posGroup":"other","english":"besiege","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obsidio","latin":"obsidiō, -ōnis ( f.)","headword":"obsidiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"siege; siege, blockade","forms":["obsidiō","obsidione","obsidiōnem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipsum erat oppidum Alesia in colle summo, admodum edito loco, ut nisi {{obsidione}} expugnari non posse videretur; cuius collis radices duo duabus ex partibus flumina subluebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obsidis","latin":"obsidis, -is","headword":"obsidis","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"hostage","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"obsido","latin":"obsido, obsidere, -, -","headword":"obsido","letter":"o","pos":"verb","posGroup":"verb","english":"besiege; occupy","forms":["obsīdunt"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Illī, hominēs mīlitārēs, sine tumultū praesidiīs collocātīs, sīcuti praeceptum erat, occultē pontem {{obsīdunt}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"obsigno","latin":"obsigno, obsignare, obsignavi, obsignatus","headword":"obsigno","letter":"o","pos":"verb","posGroup":"verb","english":"sign, seal","forms":["obsignāta","obsignātam","obsignāvī"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: Est in cistulā, Amphitryōnis {{obsignāta}} signō est.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"obsistere","latin":"(obsistō) obsistere, -stitisse, -stitum","headword":"obsistere","letter":"o","pos":"","posGroup":"other","english":"resist","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obsisto","latin":"obsisto, obsistere, obstiti, obstitus","headword":"obsisto","letter":"o","pos":"verb","posGroup":"verb","english":"oppose, resist; stand in the way; make a stand against, withstand","forms":["obsistēbat","obsistere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam quae ab reliquis Gallis civitates dissentirent, has sua diligentia adiuncturum atque unum consilium totius Galliae effecturum, cuius consensui ne orbis quidem terrarum possit {{obsistere}}; idque se prope iam effectum habere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obstare","latin":"(obstō) obstāre, obstitisse,","headword":"obstāre","letter":"o","pos":"","posGroup":"other","english":"stand in the way obstitum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obstinatio","latin":"obstinatio, obstinationis","headword":"obstinatio","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"determination, stubbornness","forms":["obstinātiōnem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Neque enim dubitābam, quālecumque esset quod fatērentur, pertināciam certē et īnflexibilem {{obstinātiōnem}} dēbēre pūnīrī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"obstinatus","latin":"obstinātus, -a, -um","headword":"obstinātus","letter":"o","pos":"adjective","posGroup":"adjective","english":"stubborn, obstinate","forms":["obstinātam","obstinātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi {{obstinātam}} vidēbat neque mortis quidem metū inclīnārī, addit ad metum dēdecus: cum mortuā iugulātum servum nūdum positūrum sē esse, ut in sordidō adulteriō necāta dīcerētur!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obstipesco","latin":"obstipesco, obstipescere, obstipui, -","headword":"obstipesco","letter":"o","pos":"verb","posGroup":"verb","english":"be amazed","forms":["Obstipuit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Obstipuit}} simul ipse simul perculsus Achātēs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"obsto","latin":"obstō, -āre, obstitī","headword":"obstō","letter":"o","pos":"verb","posGroup":"verb","english":"stand in the way, block (+ dat.)","forms":["obstābant","obstābat","obstābit","obstant","obstat","obstet","obstitī","obstitit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Posse pūtēs tangī: minimum est, quod amantibus {{obstat}}!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"obstrepo","latin":"obstrepo, obstrepere, obstrepui, obstrepitus","headword":"obstrepo","letter":"o","pos":"verb","posGroup":"verb","english":"roar against; make a loud noise","forms":["obstrepere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad hōc maledicta alia cum adderet, {{obstrepere}} omnēs, hostem atque parricīdam vocāre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"obstringo","latin":"obstringo, obstringere, obstrinxi, obstrictus","headword":"obstringo","letter":"o","pos":"verb","posGroup":"verb","english":"confine; involve; oblige, put under an obligation, bind, bind by oath","forms":["obstrictus","obstringere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Carthāginiēnsēs, portū novō — quia vetus {{obstrictus}} ā Scīpiōne erat — factō et contractā clam exiguō tempore amplā classe, īnfēlīciter nāvālī proeliō pugnāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obstruere","latin":"(obstruō) obstruere, -struxisse, -structum","headword":"obstruere","letter":"o","pos":"","posGroup":"other","english":"bar, block","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obstruo","latin":"obstruo, obstruere, obstruxi, obstructus","headword":"obstruo","letter":"o","pos":"verb","posGroup":"verb","english":"block up, barricade","forms":["obstruere","obstruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fabium discessu eorum duabus relictis portis {{obstruere}} ceteras pluteosque vallo addere et se in posterum diem similemque casum apparare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obstupescere","latin":"(obstupēscō) obstupēscere,","headword":"obstupēscere","letter":"o","pos":"","posGroup":"other","english":"be stunned/astounded obstupuisse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obstupesco","latin":"obstupesco, obstupescere, obstupui, -","headword":"obstupesco","letter":"o","pos":"verb","posGroup":"verb","english":"be stupefied; be struck dumb; be astounded","forms":["obstupuerant","obstupuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad quem nūntium Iacobus, quasi ē gravī somnō excitātus, {{obstupuit}}, nec prīmum fīliīs rem nārrantibus fidem adhibēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"obsurdescere","latin":"(obsurdēscō) obsurdēscere, -uisse","headword":"obsurdēscere","letter":"o","pos":"","posGroup":"other","english":"become deaf","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obsurdesco","latin":"obsurdesco, obsurdescere, obsurdui, -","headword":"obsurdesco","letter":"o","pos":"verb","posGroup":"verb","english":"become deaf; turn a deaf ear","forms":["obsurduērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc sonitū opplētae aurēs hominum {{obsurduērunt}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obtemperare","latin":"(obtemperō) obtemperāre","headword":"obtemperāre","letter":"o","pos":"","posGroup":"other","english":"obey (intr. + dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obtempero","latin":"obtempero, obtemperare, obtemperavi, obtemperatus","headword":"obtempero","letter":"o","pos":"verb","posGroup":"verb","english":"obey; comply with the demands of; be submissive to; (w/DAT)","forms":["obtemperāns","obtemperaturos","obtemperātūrum","obtemperō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ex his Bellovaci suum numerum non compleverunt, quod se suo nomine atque arbitrio cum Romanis bellum gesturos dicebant, neque cuiusquam imperio {{obtemperaturos}}; rogati tamen ab Commio pro eius hospitio duo milia una miserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obtestari","latin":"(obtestor) obtestārī","headword":"obtestārī","letter":"o","pos":"","posGroup":"other","english":"beseech, implore","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obtestor","latin":"obtestor, obtestari, obtestatus sum","headword":"obtestor","letter":"o","pos":"verb","posGroup":"verb","english":"call to witness; implore","forms":["obtestabantur","obtestari","obtestatur","obtestātus","obtestor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dimittit quoque versus legationes; {{obtestatur}} ut in fide maneant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obtineo","latin":"obtineo, obtinere, obtinui, obtentus","headword":"obtineo","letter":"o","pos":"verb","posGroup":"verb","english":"get hold of; maintain; obtain; hold fast, occupy; prevail","forms":["obtinebant","obtinendam","obtinendās","obtinente","obtinere","obtinēret","obtinet","obtinuerat","obtinuerint","obtinuerit","obtinuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius {{obtinuerat}} et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obtinere","latin":"(obtineō) obtinēre (< tenēre)","headword":"obtinēre","letter":"o","pos":"","posGroup":"other","english":"hold, gain, obtain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obtrectare","latin":"(obtrectō) obtrectāre","headword":"obtrectāre","letter":"o","pos":"verb","posGroup":"verb","english":"criticize, disparagement; to disparage, attack in words","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"obtrectatio","latin":"obtrectātiō, -tiōnis ( f.)","headword":"obtrectātiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"criticism, disparagement","forms":["obtrectātiō","obtrectātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam ēdita sunt mandāta, 'Vīcit ergō Hannibalem' inquit 'nōn populus Rōmānus totiēs caesus fugātusque, sed senātus Carthāginiēnsis {{obtrectātiōne}} atque invidiā.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obtrecto","latin":"obtrecto, obtrectare, obtrectavi, obtrectatus","headword":"obtrecto","letter":"o","pos":"verb","posGroup":"verb","english":"detract from; disparage, belittle","forms":["obtrectandīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ennius, mox et iūxtā Caecilius et Terentius, et subinde Pācuvius, et continuō Pācuviō iam sene Accius, clāriorque tunc in poēmatis tragicī Rōmānī eōrum {{obtrectandīs}} Lūcīlius fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"obtruncare","latin":"(obtruncō) obtruncāre","headword":"obtruncāre","letter":"o","pos":"verb","posGroup":"verb","english":"slaughter, kill; to cut down, slaughter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"obtrunco","latin":"obtrunco, obtruncare, obtruncavi, obtruncatus","headword":"obtrunco","letter":"o","pos":"verb","posGroup":"verb","english":"kill; cut down","forms":["obtruncābō","obtruncant","obtruncat","obtruncātī","obtruncāvit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ipsusque Amphitryō rēgem Pterelam suā {{obtruncāvit}} manū.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"obtundo","latin":"obtundo, obtundere, obtudi, obtunsus","headword":"obtundo","letter":"o","pos":"verb","posGroup":"verb","english":"strike, beat, batter; make blunt; deafen","forms":["obtūnsa"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn {{obtūnsa}} adeō gestāmus pectora Poenī,\nnec tam āversus equōs Tyriā Sōl iungit ab urbe.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"obtunsus","latin":"obtūnsus, -a, -um","headword":"obtūnsus","letter":"o","pos":"adjective","posGroup":"adjective","english":"blunt, dull; blunted, dull","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"obtusus","latin":"obtūsus, -a, -um","headword":"obtūsus","letter":"o","pos":"adjective","posGroup":"adjective","english":"dull, blunt","forms":["obtūsa","obtūsum","obtūsus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hoc est acūtum, illud est {{obtūsum}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"obvenio","latin":"obvenio, obvenire, obveni, obventus","headword":"obvenio","letter":"o","pos":"verb","posGroup":"verb","english":"meet","forms":["obvenerant","obvenerat","obvenit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi seditio oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum disparandos deducendosque ad suos curaret, quae cuique civitati pars castrorum ab initio {{obvenerat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obvenire","latin":"(obveniō) obvenīre (< venīre)","headword":"obvenīre","letter":"o","pos":"","posGroup":"other","english":"meet, fall to the lot of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"obviam","latin":"obviam","headword":"obviam","letter":"o","pos":"adverb","posGroup":"adverb","english":"(go to) meet, oppose, in the way","forms":["obviam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vercingetorix, ubi de Caesaris adventu cognovit, oppugnatione destitit atque {{obviam}} Caesari proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"obvius","latin":"obvius, -a, -um","headword":"obvius","letter":"o","pos":"adjective","posGroup":"adjective","english":"coming to meet","forms":["obvia","obviīs","obviōs","obvium","obvius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit comam, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis rōbore: {{obvium}} leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"occasio","latin":"occāsiō, -ōnis ( f.)","headword":"occāsiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"opportunity, chance; opportunity, favourable moment","forms":["occasione","occāsiōnem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hac impulsi {{occasione}} qui iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occasus","latin":"occāsus, -ūs","headword":"occāsus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"setting","forms":["occāsū","occasum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum a meridie prope ad solis {{occasum}} dubia victoria pugnaretur, Germani una in parte confertis turmis in hostes impetum fecerunt eosque propulerunt; quibus in fugam coniectis, sagittarii circumventi interfectique sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occidens","latin":"occidēns, occidentis","headword":"occidēns","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"(m.) west","forms":["occidēns","occidente","occidentem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Bellerophōn, postquam grātiās Polydō ēgit, sōlē {{occidente}} domō exiit, ut Minervae templum peteret; quō cum ingressus esset, ad signum accessit, sub quō recumbēns dormīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"occidere","latin":"(occīdō) occīdere, occīdisse,occīsum","headword":"occīdere","letter":"o","pos":"verb","posGroup":"verb","english":"kill; to set (of the sun); to kill; to kill, cut down","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"occidit","latin":"occīdit","headword":"occīdit","letter":"o","pos":"verb","posGroup":"verb","english":"kills","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"occido","latin":"occidō, occidere","headword":"occidō","letter":"o","pos":"verb","posGroup":"verb","english":"fall, sink, set; die, perish, fall down; kill","forms":["occāsūrum","occīdam","Occīdāmus","occīdant","occīdar","occīdās","occīdat","occīdātur","occīde","occīdēbant","occīdēbantur","occīdēmus","occīdendī","occīdendō","occīdent","occīderant","occiderat","occīdere","occīderentur","occīderet","occīderīs","occīdērunt","occīdēs","occīdētis","occīdī","occīdisse","occidisset","occīdistī","occīdistis","occīdit","occīdite","occiditur","occīdō","occīdunt","occīsa","occīsī","occīsīs","occīsō","occīsōrum","occīsōs","occīsum","occīsūrum","occīsus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sedulius, dux et princeps Lemovicum, {{occiditur}}; Vercassivellaunus Arvernus vivus in fuga comprehenditur; signa militaria LXXIIII ad Caesarem referuntur; pauci ex tanto numero se incolumes in castra recipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occiduus","latin":"occiduus, occidua, occiduum","headword":"occiduus","letter":"o","pos":"adjective","posGroup":"adjective","english":"setting; westerly","forms":["occiduus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Invidus adstābat vehementī flāmine anhēlāns {{occiduus}} ventus, quī vērīs signa redūcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"occipio","latin":"occipio, occipere, occepi, occeptus","headword":"occipio","letter":"o","pos":"verb","posGroup":"verb","english":"begin","forms":["occēpit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Is amārē {{occēpit}} Alcumēnam clam virum","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"occludo","latin":"occludo, occludere, occlusi, occlusus","headword":"occludo","letter":"o","pos":"verb","posGroup":"verb","english":"shut up, close up","forms":["occlūsērunt"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"[Ad ōstium accēdit.] Sed aedēs {{occlūsērunt}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"occubo","latin":"occubo, occubare, occubui, occubitus","headword":"occubo","letter":"o","pos":"verb","posGroup":"verb","english":"lie (against/on top of); lie dead","forms":["occubat","occubuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās concussit, et turba omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn inultus {{occubuit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"occulo","latin":"occulo, occulere, occului, occultus","headword":"occulo","letter":"o","pos":"verb","posGroup":"verb","english":"cover; cover up, hide, cover over, conceal","forms":["occulit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{occulit}}; ipse ūnō graditur comitātus Achātē,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"occultat","latin":"occultat, occultāre","headword":"occultat","letter":"o","pos":"","posGroup":"other","english":"hide","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"occulte","latin":"occulte","headword":"occulte","letter":"o","pos":"adverb","posGroup":"adverb","english":"secretly","forms":["occulte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cognitis per exploratores regionibus, duces hostium LX milia ex omni numero deligunt earum civitatum quae maximam virtutis opinionem habebant, quid quoque pacto agi placeat {{occulte}} inter se constituunt, adeundi tempus definiunt, cum meridies esse videatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occulto","latin":"occulto, occultare, occultavi, occultatus","headword":"occulto","letter":"o","pos":"verb","posGroup":"verb","english":"hide; conceal","forms":["occultābat","occultandas","occultāns","occultant","occultantur","occultāre","occultāret","occultat","occultātō","occultātus","occultaverant","occultāverat","occultāvisset","occultavit","occultem","occultētis","occulto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Itaque, ne id accideret, silvestri loco castris positis e regione unius eorum pontium quos Vercingetorix rescindendos curaverat, postero die cum duabus legionibus in {{occulto}} restitit; reliquas copias cum omnibus impedimentis, ut consueverat, misit, apertis quibusdam cohortibus, uti numerus legionum constare videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occultum","latin":"occultum, occulti","headword":"occultum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"secrecy; hiding","forms":["occultum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et maxime, quod ipse animo non defecerat tanto accepto incommodo neque se in {{occultum}} abdiderat et conspectum multitudinis fugerat; plusque animo providere et praesentire existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occultus","latin":"occultus, -a, -um","headword":"occultus","letter":"o","pos":"adjective","posGroup":"adjective","english":"hidden, secret","forms":["occultās","occultīs","occultissimē","occultius","occultōs","occultus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interdum, armātus gladiō, mīlitis fōrmam sūmēbat; nōnnumquam, harundine sūmpta, piscātōrī similem sē ipse faciēbat; modo hāc, modo illā veste induēbātur, ut ferē {{occultus}} ac latēns prope Pōmōnae hortōs ad eam spectandam venīret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"occumbo","latin":"occumbo, occumbere, occumbui, occumbitus","headword":"occumbo","letter":"o","pos":"verb","posGroup":"verb","english":"meet with (death); meet one's death","forms":["occumbere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mēne Īliacīs {{occumbere}} campīs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"occupare","latin":"(occupō) occupāre","headword":"occupāre","letter":"o","pos":"","posGroup":"other","english":"occupy, take possession of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"occupatus","latin":"occupatus, occupata, occupatum","headword":"occupatus","letter":"o","pos":"adjective","posGroup":"adjective","english":"occupied; busy","forms":["occupātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum in apparandō ācerrimē esset {{occupātus}}, Carthāginiēnsēs bellum cum Rōmānīs composuērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"occupo","latin":"occupō, -āre, occupāvī","headword":"occupō","letter":"o","pos":"verb","posGroup":"verb","english":"seize, occupy","forms":["occupandam","occupandō","occupantem","occupāre","occupārent","occupat","occupāta","occupāte","occupātī","occupātīs","occupato","occupatos","occupātūrum","occupāverat","occupāvēre","occupaverunt","occupāvī","occupāvisse","occupāvit","occupō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi aliquid ab eis iniri consili intellexissent, gladiis destrictis portas {{occupaverunt}} suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occurrere","latin":"occurrere","headword":"occurrere","letter":"o","pos":"verb","posGroup":"verb","english":"meet, run up to","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"occurro","latin":"occurrō, occurrere","headword":"occurrō","letter":"o","pos":"verb","posGroup":"verb","english":"run up; run to meet; occur (+ dat.)","forms":["occurram","occurrāmus","Occurrās","occurrat","Occurre","occurrebant","occurrebatur","occurrēns","occurrentēs","occurrentium","occurrere","occurreret","occurrerīmus","occurrerit","occurrērunt","occurrī","occurrit","occurrunt","occursū"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque observabat dispersosque, cum longius necessario procederent, adoriebatur magnoque incommodo adficiebat, etsi quantum ratione provideri poterat ab nostris {{occurrebatur}}, ut incertis temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"occursare","latin":"(occursō) occursāre","headword":"occursāre","letter":"o","pos":"","posGroup":"other","english":"run to meet","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"oceanus","latin":"ōceanus, -ī","headword":"ōceanus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"ocean","forms":["Ōceanī","Ōceanō","Ōceanum","Ōceanus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Celeriter sibi Senones, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui {{Oceanum}} attingunt adiungit; omnium consensu ad: eum defertur imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ocellus","latin":"ocellus, -ī","headword":"ocellus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"(little) eye; little eye","forms":["ocellī","ocellīs","ocellōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ocis","latin":"ocis, oce, ocior -or -us, ocissimus -a -um","headword":"ocis","letter":"o","pos":"adjective","posGroup":"adjective","english":"swift/rapid, at speed; (COMP) arriving/appearing/occurring earlier/sooner","forms":["ōcius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Idque ōcius faciet, sī iam tum cum erit inclūsus in corpore, ēminēbit forās et ea quae extra erunt contemplāns quam maximē sē ā corpore abstrahet.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ocissime","latin":"ōcissimē","headword":"ōcissimē","letter":"o","pos":"","posGroup":"other","english":"most quickly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ocius","latin":"ōcius (comp. without positive)","headword":"ōcius","letter":"o","pos":"","posGroup":"other","english":"quicker, sooner","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ocrea","latin":"ocrea, ocreae","headword":"ocrea","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"greave, armor for leg below the knee; leg-covering","forms":["ocream","ocreās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Lōrīcā induebātur; {{ocreās}} in crūribus āereās habēbat; cassis āerea caput eius operiēbat, et clipeus aureus tegēbat umerōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"octavius","latin":"Octavius, Octavii","headword":"Octavius","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Octavius; name of Roman gens","forms":["Octāviī","Octāviō","Octāvius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Latīnōrum sibi maximē gentem conciliābat, ut peregrīnīs quoque opibus tūtior inter cīvēs esset; hospitia cum prīmōribus eōrum iungēbat, atque Octāviō Māmiliō Tusculānō — is longē prīnceps Latīnī nōminis erat — fīliam nūptum dat, perque eās nūptiās multōs sibi cognātōs amīcōsque eius conciliat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"octavus","latin":"octāvus, -a, -um","headword":"octāvus","letter":"o","pos":"","posGroup":"other","english":"eighth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"octies","latin":"octiēs (Cap. XXX: distributive numbers)","headword":"octiēs","letter":"o","pos":"","posGroup":"other","english":"eight times","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"octingent","latin":"octingent","headword":"octingent","letter":"o","pos":"numeral","posGroup":"numeral","english":"eight hundred","forms":["octingenta","octingentī","octingentos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His constitutis rebus, Aeduis Segusiavisque, qui sunt finitimi provinciae, decem milia peditum imperat; huc addit equites {{octingentos}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"octingenti","latin":"octingentī, -ae, -a","headword":"octingentī","letter":"o","pos":"","posGroup":"other","english":"eight hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"octo","latin":"octō","headword":"octō","letter":"o","pos":"numeral","posGroup":"numeral","english":"eight","forms":["octāva","octāvō","octāvum","octāvus","octō","octoni"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Huius generis {{octoni}} ordines ducti ternos inter se pedes distabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"october","latin":"October, Octobris","headword":"October","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"October; (8th month before Caesar, 10 th after); abb. Oct.","forms":["Octōber","Octōbrēs","Octōbrī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; September, nōnus; {{Octōber}}, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"octogesimus","latin":"octōgēsimus, -a, -um","headword":"octōgēsimus","letter":"o","pos":"","posGroup":"other","english":"eightieth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"octoginta","latin":"octōgintā","headword":"octōgintā","letter":"o","pos":"numeral","posGroup":"numeral","english":"eighty","forms":["octōgēsimum","octōgintā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Et vērē nocte sequenfi angelus Deī centum octōgintā quīnque hostium milia lētō dedit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"octus","latin":"Octus, Octa, Octum","headword":"Octus","letter":"o","pos":"adjective","posGroup":"adjective","english":"October (month/mensis understood); abb. Oct.","forms":["Oct"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Oct}}àvia, Augustī soror, porticum dē-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"oculus","latin":"oculus, -ī","headword":"oculus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"eye","forms":["oculī","oculis","oculō","oculōrum","oculōs","oculum","OCVLŌS"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis {{oculis}} domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"odi","latin":"odi, odisse, osus","headword":"odi","letter":"o","pos":"verb","posGroup":"verb","english":"hate (PERF form, PRES force), dislike; be disinclined/reluctant/adverse to","forms":["ōderam","Ōderant","ōderat","ōdēre","ōderint","ōderīs","ōderit","ōdērunt","ōdī","Ōdimus","ōdisse","ōdissent","ōdit","ōsa"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōderant illum tantopere, ut nōn possent cum eō amīcē loquī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"odio","latin":"odio, odire, odivi, -","headword":"odio","letter":"o","pos":"verb","posGroup":"verb","english":"hate; dislike; be disinclined/reluctant/adverse to; (usu. PREFDEF)","forms":["odiō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vidēns Jēsus turbās, ascendit in montem et docēbat eās:\"Audīstis dictum esse ab antīquīs: ' dīligēs proximum tuum, et odiō habēbis inimīcum tuum. ' Ego autem dīcō vōbīs: dīligite inimīcōs vestrōs, et benefacite hīs quī ōdērunt vōs, et ōrātē prō persequentibus et calumniantibus vōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"odiosus","latin":"odiosus, odiosa -um, odiosior -or -us, odiosissimus -a -um","headword":"odiosus","letter":"o","pos":"adjective","posGroup":"adjective","english":"distasteful. disagreeable, offensive; tiresome, boring, troublesome, annoying","forms":["odiōsō","odiōsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Dominus dīxit serpentī: quia dēcēpistī mulierem, eris {{odiōsus}} et exsecrātus inter omnia animantia; rēptābis super pectus, et comedēs terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"odisse","latin":"(ōdī) ōdisse, ōsum","headword":"ōdisse","letter":"o","pos":"verb","posGroup":"verb","english":"hate; to hate","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"odium","latin":"odium, -ī","headword":"odium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"hatred","forms":["odiī","odiīs","odium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Crēscēbat in diēs Saūlis {{odium}}, stimulante invidiā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"odor","latin":"odor, -ōris (m.)","headword":"odor","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"smell; smell, odor; smell, fragrance","forms":["odor","odōre","odōrem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post novem diēs et novem noctēs, herbīs collēctīs, Medea curru dracōnibus pennātīs tractō rediit; dracōnēs sōlum {{odōre}} herbārum tāctī pellēs senectūtis dēposuērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"odoratus","latin":"odoratus, odorata, odoratum","headword":"odoratus","letter":"o","pos":"adjective","posGroup":"adjective","english":"smelling, having smell/odor/scent; fragrant/perfumed/sweet smelling","forms":["odōrātae"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sertaque {{odōrātae}} myrtea ferte comae!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"odoro","latin":"odoro, odorare, odoravi, odoratus","headword":"odoro","letter":"o","pos":"verb","posGroup":"verb","english":"perfume, make fragrant","forms":["odōra"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Massȳlīque ruunt equitēs et {{odōra}} canum vīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"odorus","latin":"odorus, odora, odorum","headword":"odorus","letter":"o","pos":"adjective","posGroup":"adjective","english":"odorous, fragrant; keen-scented","forms":["odōrus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{odōrus}} | tūra p/ : tūs sg","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"oedipus","latin":"Oedipus, -ī","headword":"Oedipus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Oedipus, king of Thebes","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"offendere","latin":"(offendō) offendere, -disse, -sum","headword":"offendere","letter":"o","pos":"","posGroup":"other","english":"hit upon, come upon, find","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"offendo","latin":"offendo, offendere, offendi, offensus","headword":"offendo","letter":"o","pos":"verb","posGroup":"verb","english":"offend, give offense (to); displease/annoy/vex; trouble/upset, hurt (feelings)","forms":["offendās","offendat","offendēns","offenderit","offendēs","offendī","offendisse","offendit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed deinde Saūl Deum graviter {{offendit}}: vetuerat Deus nē quid ex spoliīs hostium reservārētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"offensa","latin":"offēnsa, -ae","headword":"offēnsa","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"offense, resentment; offence, resentment","forms":["offēnsā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deinde, cum minus agrī esset quam quod dīvidī posset sine offēnsā etiam plēbis — quoniam eōs ad cupiditātem amplum modum spērandī incitāverat — lēgem sē iūgerum prōmulgātūrum ostendit: 'ut iīs quī Semprōniā lēge agrum accipere dēbērent, pecūnia quae rēgis Attalī fuisset dīviderētur.' Hērēdem autem populum Rōmānum relīquerat Attalus, rēx Pergamī, Eumenis fīlius.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"offensio","latin":"offēnsiō, -ōnis ( f.)","headword":"offēnsiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"setback, misfortune; reverse, disaster","forms":["offēnsiōne","offēnsiōnibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc in illō ipsō malō gravissimāque bellī {{offēnsiōne}} L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"offensum","latin":"offensum, offensi","headword":"offensum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"offense","forms":["offēnsum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Et sī mē meīs cīvibus iniūria suspectum tam graviter atque {{offēnsum}} vidērem, carēre mē aspectū cīvium quam īnfēstīs omnium oculīs cōnspicī māllem — tū, cum cōnscientiā scelerum tuōrum agnōscās odium omnium iūstum et iam diū tibi dēbitum, dubitās, quōrum mentēs sēnsūsque vulnerās, eōrum aspectum praesentiamque vītāre?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"offensus","latin":"offensus, offensus","headword":"offensus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"collision, knock","forms":["offēnsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē {{offēnsus}} Deus statuit perdere hominum genus dīluviō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"offero","latin":"offerō, offerre, obtulī, oblātum","headword":"offerō","letter":"o","pos":"verb","posGroup":"verb","english":"offer, present","forms":["oblata","oblātam","oblātum","obtulerat","obtulērunt","obtulit","offer","offerant","offerēbat","offerendam","offerent","offerentēs","offerre","offerret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qua {{oblata}} potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"offerre","latin":"(offerō) offerre, obtulisse, oblātum","headword":"offerre","letter":"o","pos":"verb","posGroup":"verb","english":"offer, present; to offer","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"officialis","latin":"officialis, officialis","headword":"officialis","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"official/servant attending a magistrate; an official; civil servant (Cal)","forms":["officiālēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At ille sīmius māior ait illī quī fallāx erat: “Quid sum ego?” Fallāx dīxit: “Tū es Imperātor!” Iterum interrogāvit: “Et istī quōs ante mē stāre vidēs, quid sunt?” Īdem fallāx respondit: “Hī comitēs sunt tuī, prīmicēriī, campidoctōrēs, et cēterī {{officiālēs}}.” Et prō hōc sīmius, quī mendāciter laudātus est cum turbā suā, ōsculātus est hominem fallācem et mūnera illī dedit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"officio","latin":"officio, officere, offeci, offectus","headword":"officio","letter":"o","pos":"verb","posGroup":"verb","english":"block the path (of ), check, impede","forms":["officere","officiō","officit","officiunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quārē ēgressus cum suīs, quī in officiō manēbant, cōnscendit montem Olīvārum flēns, nūdīs pedibus et opertō capite.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"officium","latin":"officium, -ī","headword":"officium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"duty; duty, job","forms":["officia","officiīs","officium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Tū {{officium}} tuum cūrā!” inquit Diodōrus, “Nōn medicus, sed servus meus es.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"offirmatus","latin":"offirmatus, offirmata -um, offirmatior -or -us, offirmatissimus -a -um","headword":"offirmatus","letter":"o","pos":"adjective","posGroup":"adjective","english":"resolute; firm","forms":["offirmātō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"abitum eius animō fortī atque offirmātō, id modo sī mercēdis","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"olea","latin":"olea, oleae","headword":"olea","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"olive; olive-tree","forms":["oleae","oleārum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Omnēs sēgetēs, vīneae et {{oleae}} exustae sunt; nec inimīcam gentem variīs incommodīs vexāre dēstitit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"olens","latin":"olens, (gen.), olentis","headword":"olens","letter":"o","pos":"adjective","posGroup":"adjective","english":"odorous; fragrant; stinking","forms":["olēns","olentiā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"95 aut ut apēs saltüsque suōs et olentiā nactae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"oleo","latin":"oleo, olere, olui, -","headword":"oleo","letter":"o","pos":"verb","posGroup":"verb","english":"smell of, smell like","forms":["oleō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ōlim igitur, cum, positīs vestīmentīs, oleō membra aspersissent, in lātissimō campō herbīs opertō discīs iactandīs certābant; Hyacinthus, quī certandī studiōsissimus erat, prior discum in āera omnibus lacertōrum vīribus ēmīsit; quī, sē celerrimē vertēns, usque ad caelum ascendit, atque, cum nūbēs scidisset, rūrsus ad terram dēscendit, ceciditque procul ā locō unde puer et deus intuēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"oleum","latin":"oleum, olei","headword":"oleum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"oil","forms":["oleīs","oleum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et appropinquāns alligāvit vulnera eius Īnfundēns {{oleum}} et vīnum; et impōnēns illum iūmentō suō, dūxit in stabulum, et cūram eius ēgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"olim","latin":"ōlim","headword":"ōlim","letter":"o","pos":"adverb","posGroup":"adverb","english":"once, long ago; once, formerly; once, once upon a time; once, once upon a time, formerly","forms":["ōlim"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Inimīcitiae erunt inter tē et mulierem; ipsa ōlim conteret caput tuum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"oliva","latin":"olīva, -ae","headword":"olīva","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"olive; olive branch","forms":["olīvae","Olīvārum","olīvās","olīvīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Columba rūrsum ēmissa attulit in ōre suō rāmum {{olīvae}} virentis, quō fīnis dīluviī significābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"olivum","latin":"olivum, olivi","headword":"olivum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"olive-oil; wrestling","forms":["olīvō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post hanc vāgor — aut ego, lēctō aut scrīptō quod mē tacitum iuvet, ungor olīvō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"olla","latin":"olla, ollae","headword":"olla","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"pot, jar","forms":["ōllā","ōllam","ōllās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, linguam amputarī, cutem capitis detrahī, summās mantīs ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"olympia","latin":"Olympia, Olympiae","headword":"Olympia","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"Olympia","forms":["Olympiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Unde per Megalopolim {{Olympiam}} ēscendit; ubi et alia quidem spectanda eī vīsa — Iovem velut praesentem intuēns mōtus animō est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"olympus","latin":"Olympus, Olympi","headword":"Olympus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Olympus; Mt Olympus in Greece; the gods; heaven","forms":["Olympī","Olympō","Olympum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Lātōna dea fuit, quam Iūnō, deōrum rēgīna, nōn amābat; itaque dē Olympō expulsam in terram mīsit, ubi ipsa maerēns per campōs silvāsque errābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"omen","latin":"ōmen, -inis (n.)","headword":"ōmen","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"sign, token, omen; omen, portent; sign, omen; omen, sign","forms":["ōmen","ōmina","ōminibus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ille deus mātrimōniī adfuit, sed nec verba laeta nec ōmen fēlīx attulit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"omissus","latin":"omissus, omissa -um, omissior -or -us, omississimus -a -um","headword":"omissus","letter":"o","pos":"adjective","posGroup":"adjective","english":"remiss; negligent","forms":["omissā","omissae","omissis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nostri {{omissis}} pilis gladiis rem gerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"omitto","latin":"omitto, omittere, omisi, omissus","headword":"omitto","letter":"o","pos":"verb","posGroup":"verb","english":"lay aside; omit; let go; disregard","forms":["omittam","omitte","omittite","omittō","omittunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Proinde {{omittite}} Saguntī atque Hibērī mentiōnem facere, et quod diū parturit animus vester, aliquandō pariat!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ommittere","latin":"(ommittō) ommittere (< mittere)","headword":"ommittere","letter":"o","pos":"","posGroup":"other","english":"abandon, leave off/out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"omne","latin":"omne, omnis","headword":"omne","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"all things (pl.); everything; a/the whole, entity, unit","forms":["omne"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat neve ab hostibus diripiantur, praesertim cum videat {{omne}} ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"omnes","latin":"omnēs, -ia","headword":"omnēs","letter":"o","pos":"adjective","posGroup":"adjective","english":"all, everyone","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"omnia","latin":"omnia","headword":"omnia","letter":"o","pos":"adverb","posGroup":"adverb","english":"in all respects","forms":["omnia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Singulari militum nostrorum virtuti consilia cuiusque modi Gallorum occurrebant, ut est summae genus sollertiae atque ad {{omnia}} imitanda et efficienda quae ab quoque traduntur aptissimum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"omnino","latin":"omnīnō","headword":"omnīnō","letter":"o","pos":"adverb","posGroup":"adverb","english":"altogether","forms":["omnino"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod {{omnino}} tempus ab opere intermitteretur, paulo ante tertiam vigiliam est animadversum fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"omnipotens","latin":"omnipotens, (gen.), omnipotentis","headword":"omnipotens","letter":"o","pos":"adjective","posGroup":"adjective","english":"all-powerful, omnipotent","forms":["omnipotēns","omnipotentis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deum ūnum timē, Deum intuēre, ā quō mercēdem recipiēs.\"Hīs verbīs cōnfirmātus, adulēscēns exclāmāvit:\"Nōn regī obsequor, sed legī.\"Tūne conversus ad Antiochum:\"Tū quid em, ō sceleste, Deī {{omnipotentis}} Īram nōn effugiēs: erit tempus cum, ab eō percussus et dolōre victus, tē hominem esse cōnfitēberis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"omnis","latin":"omnis, -e","headword":"omnis","letter":"o","pos":"adjective","posGroup":"adjective","english":"all, every; each, every; (pl.) all","forms":["omnem","omnes","omni","omnibus","OMNIBVS","omnis","omnium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut {{omnes}} iuniores Italiae coniurarent, dilectum tota provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"onerare","latin":"(onerō) onerāre","headword":"onerāre","letter":"o","pos":"","posGroup":"other","english":"load","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"onero","latin":"onero, onerare, oneravi, oneratus","headword":"onero","letter":"o","pos":"verb","posGroup":"verb","english":"load, burden; oppress","forms":["onerant","onerat","onerātās","onerāvit","onerent"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Palliô enim coccineô adrāsum exclūserat caput, circäque {{onerātās}} veste cer- vîcës lāticlāviam immîserat mappam ﬁmbriîs hinc atque illinc pendentibus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"onus","latin":"onus, -eris (n.)","headword":"onus","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"burden, load","forms":["onere","onerī","onus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Līberābis populum tuum ā servitūte Madianitārum.” Nōlēbat prīmō Gedeōn tantum {{onus}} suscipere, sed duplicī mīrāculō cōnfirmātus nōn abnuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"onustus","latin":"onustus, -a, -um","headword":"onustus","letter":"o","pos":"adjective","posGroup":"adjective","english":"laden","forms":["onustam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ubi Mīdās satis gāvīsus erat, servī prō eō mēnsam carne atque dōnīs Cereris {{onustam}} posuērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"opacus","latin":"opācus, -a, -um","headword":"opācus","letter":"o","pos":"adjective","posGroup":"adjective","english":"shady","forms":["opācīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Alveus in līmō, silvīs appulsus {{opācīs}}, paulātim fluviō dēficiente sedet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"opera","latin":"opera, -ae","headword":"opera","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"effort, pains; work, effort","forms":["opera","operae","operam","operārum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se {{operam}} ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"operarius","latin":"operārius, -ī","headword":"operārius","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"laborer; workman, labourer","forms":["operāriīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Intentus perficiendō templō, fabrīs undique ex Etrūriā accītīs, nōn pecūniā sōlum ad id pūblicā est ūsus, sed {{operāriīs}} etiam ex plēbe.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"operculum","latin":"operculum, operculi","headword":"operculum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"lid, cover","forms":["operculō","operculum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum prīmum autem leviter {{operculum}} sustulit, subitō omnia mala, omnēs morbī omnēsque dolōrēs ex illō vāse exiērunt atque longē lātēque per tōtum terrārum orbem sparsī sunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"operio","latin":"operio, operire, operui, opertus","headword":"operio","letter":"o","pos":"verb","posGroup":"verb","english":"cover (over); bury; overspread; shut/close; conceal; clothe, cover/hide the head","forms":["operiēbant","operiēbat","operiēbātur","operīre","operīrētur","operīrī","operit","operīte","operītur","operiunt","operiuntur","operuisset","operuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iam vērō caelum nūbibus ātrīs {{operītur}}, itaque obscūrum est ātrium.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"operit","latin":"operit, operīre","headword":"operit","letter":"o","pos":"verb","posGroup":"verb","english":"cover; covers","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"operor","latin":"operor, operari, operatus sum","headword":"operor","letter":"o","pos":"verb","posGroup":"verb","english":"labor, toil, work; perform (religious service), attend, serve; devote oneself","forms":["operāta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cūra vigil doctīs Mūsīs {{operāta}} : la-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"operosus","latin":"operosus, operosa, operosum","headword":"operosus","letter":"o","pos":"adjective","posGroup":"adjective","english":"painstaking; laborious; elaborate","forms":["operōsa","operōsus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{operōsus}} -ā -um « opera","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"opertum","latin":"opertum, operti","headword":"opertum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"secret; secret place","forms":["operta","opertīs","opertō","opertum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Quārē ēgressus cum suīs, quī in officiō manēbant, cōnscendit montem Olīvārum flēns, nūdīs pedibus et opertō capite.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"opertus","latin":"opertus, operta, opertum","headword":"opertus","letter":"o","pos":"adjective","posGroup":"adjective","english":"hidden; obscure, secret","forms":["opertae","opertam","opertās","opertōs","opertus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Albīnus: “Nōn ut aurum, sed ut ferrum tinnit iste ānulus: est ānulus ferreus aurō {{opertus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"opes","latin":"opēs, opum","headword":"opēs","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"(f. pl.) wealth; resources, wealth, power, influence; wealth, riches; wealth, resources","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"opifex","latin":"opifex, -icis (m.)","headword":"opifex","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"workman, artisan; craftsman, worker","forms":["opificēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Volturciō, comprobātō eōrum indiciō, praemia dēcernuntur, lībertī et paucī ex clientibus Lentulī dīversīs itineribus {{opificēs}} atque servitia in vīcīs ad eum ēripiundum sollicitābant, partim exquīrēbant ducēs multitūdinum quī pretiō rem pūblicam vexāre solitī erant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"opimus","latin":"opīmus, -a, -um","headword":"opīmus","letter":"o","pos":"adjective","posGroup":"adjective","english":"rich","forms":["opīma","opīmam","opimīs","opīmōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rebecca audierat Isaacum loquentem; vocāvit Iacobum, et: affertō, inquit, mihi duōs haedōs {{opīmōs}}; cōnficiam pulmentum, quō pater tuus valdē dēlectātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"opinari","latin":"(opīnor) opīnārī","headword":"opīnārī","letter":"o","pos":"","posGroup":"other","english":"think, believe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"opinatus","latin":"opinatus, opinatus","headword":"opinatus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"supposition","forms":["opīnātūs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: Quod numquam {{opīnātūs}} fuī—neque alius quisquam cīvium","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"opinio","latin":"opīniō, -ōnis ( f.)","headword":"opīniō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"opinion, belief","forms":["opīniō","opinione","opinionem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura {{opinione}} praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opinor","latin":"opinor, opinari, opinatus sum","headword":"opinor","letter":"o","pos":"verb","posGroup":"verb","english":"suppose, imagine","forms":["opīnārī","opīnor"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"AMPHITRYO: Homō hīc ēbrius est, ut {{opīnor}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"oportet","latin":"oportet, oportēre","headword":"oportet","letter":"o","pos":"verb","posGroup":"verb","english":"it is right, one should; it is necessary (+ acc. + inf.)","forms":["oportēbat","oportēbit","oportere","oportet","oportuerat","oportuerit","oportuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Praeterea salutis causa rei familiaris commoda neglegenda: vicos atque aedificia incendi {{oportere}} hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppedo","latin":"oppedo, oppedere, -, -","headword":"oppedo","letter":"o","pos":"verb","posGroup":"verb","english":"break wind; insult","forms":["oppēdere"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hodiē trīcēsima sabbata: vīn’ tū curtīs Iūdaeīs {{oppēdere}}?” “Nūlla mihi” inquam “religiō est.” [Fuscus:] “At mī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"opperior","latin":"opperior, opperiri, opperitus sum","headword":"opperior","letter":"o","pos":"verb","posGroup":"verb","english":"wait (for); await","forms":["opperiēbātur","opperiēns","opperior","Opperīre","opperīrētur","opperīrī","opperītur","opperiuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In portū Ōstiēnsī bona nāvis nōs {{opperītur}}, atque ventus secundus est.” neque amīcam Rōmae habeō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"opperiri","latin":"opperīrī","headword":"opperīrī","letter":"o","pos":"verb","posGroup":"verb","english":"to wait for","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"opperitur","latin":"opperītur, opperīrī","headword":"opperītur","letter":"o","pos":"","posGroup":"other","english":"wait (for), await","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"oppeto","latin":"oppeto, oppetere, oppetivi, oppetitus","headword":"oppeto","letter":"o","pos":"verb","posGroup":"verb","english":"meet, encounter; perish","forms":["oppetere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"contigit {{oppetere}}!","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"oppidani","latin":"oppidānī, -ōrum (m. pl.)","headword":"oppidānī","letter":"o","pos":"","posGroup":"other","english":"townspeople","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"oppidanus","latin":"oppidanus, oppidani","headword":"oppidanus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"townspeople (pl.)","forms":["oppidani","oppidanis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quem simul atque {{oppidani}} conspexerunt atque in spem auxili venerunt, clamore sublato arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppido","latin":"oppido","headword":"oppido","letter":"o","pos":"adverb","posGroup":"adverb","english":"exceedingly, utterly, altogether","forms":["oppido"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex {{oppido}} Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppidum","latin":"oppidum, -ī","headword":"oppidum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"town","forms":["oppida","oppidi","oppidīs","oppidōrum","oppidum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum {{oppidum}}, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppleo","latin":"oppleo, opplere, opplevi, oppletus","headword":"oppleo","letter":"o","pos":"verb","posGroup":"verb","english":"fill (completely); overspread","forms":["opplētae","opplētās","opplētum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Lentulus tribūnus mīlitum, cum praetervehēns equō sedentem in saxō cruōre {{opplētum}} cōnsulem vīdisset, 'L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"opplere","latin":"(oppleō) opplēre (< plēre)","headword":"opplēre","letter":"o","pos":"","posGroup":"other","english":"fill up, cover","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"opponere","latin":"(oppōnō) oppōnere (< pōnere)","headword":"oppōnere","letter":"o","pos":"","posGroup":"other","english":"put in the way, oppose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"oppono","latin":"oppono, opponere, opposui, oppositus","headword":"oppono","letter":"o","pos":"verb","posGroup":"verb","english":"oppose; place opposite","forms":["opponebantur","oppōnerentur","oppōnō","opposuisse"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Caesare legato ad omnes partes {{opponebantur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opportune","latin":"opportune, opportunius, opportunissime","headword":"opportune","letter":"o","pos":"adverb","posGroup":"adverb","english":"suitably; advantageously; conveniently, opportunely, favorably","forms":["Opportūnē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eāmus ad dominum tuum!” [Sōsia:] “Fortasse.” [Iūlius:] “Ego enim ingenuus omnibus nōtus sum et pater familiās.” [Sōsia:] “Appāret ā faciē tuā!” [Iūlius:] “Eāmus nōs!” [Iūlius Sōsiam sēcum abstrahere temptat, cum dominus Sōsiae iīs obviam venit.] [Iūlius:] “Opportūnē vēnistī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"opportunitas","latin":"opportūnitās, -ātis ( f.)","headword":"opportūnitās","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"convenience, advantage; opportunity, advantage","forms":["opportunitatem","opportūnitātēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet {{opportunitatem}}, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opportunus","latin":"opportūnus, -a, -um","headword":"opportūnus","letter":"o","pos":"adjective","posGroup":"adjective","english":"convenient, exposed (to); suitable; exposed to","forms":["opportūna","opportūnam","opportunis","opportūnissimam","opportuno","opportūnum","opportūnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Noviodunum erat oppidum Aeduorum ad ripas Ligeris {{opportuno}} loco positum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppositus","latin":"oppositus, oppositus","headword":"oppositus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"opposing; intervention","forms":["oppositā","oppositam","oppositās","oppositō","oppositus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam, ut commutato consilio iter in provinciam converteret, ut ne metu quidem necessario faciendum existimabat, cum infamia atque indignitas rei et {{oppositus}} mons Cevenna viarumque difficultas impediebat, tum maxime quod abiuncto Labieno atque eis legionibus quas una miserat vehementer timebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppressus","latin":"oppressus, oppressus","headword":"oppressus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"pressure","forms":["oppressus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo {{oppressus}}, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opprimere","latin":"(opprimō) opprimere (< premere)","headword":"opprimere","letter":"o","pos":"","posGroup":"other","english":"press on, overwhelm","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"opprimo","latin":"opprimo, opprimere, oppressi, oppressus","headword":"opprimo","letter":"o","pos":"verb","posGroup":"verb","english":"press down; suppress; overthrow; crush, overwhelm, fall upon, oppress","forms":["oppressa","oppresserat","oppressēre","oppresserit","oppressī","oppressis","oppressisse","oppressisset","oppressit","oppressō","oppressōs","opprimar","opprimendā","opprimeret","opprimī","opprimundae","opprimunt","opprimuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus {{oppressis}} inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opprobrium","latin":"opprobrium, -iī","headword":"opprobrium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"scandal, disgrace","forms":["opprobrium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dum Mīnōs bellum gerit, {{opprobrium}} generis crēverat et adulterium foedum rēgīnae mōnstrō biformī patēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"oppugnare","latin":"oppugnāre","headword":"oppugnāre","letter":"o","pos":"verb","posGroup":"verb","english":"to attack, besiege","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"oppugnat","latin":"oppugnat, oppugnāre","headword":"oppugnat","letter":"o","pos":"verb","posGroup":"verb","english":"attack; attacks","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"oppugnatio","latin":"oppugnātiō, -tiōnis ( f.)","headword":"oppugnātiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"attack, assault","forms":["oppugnātiō","oppugnatione","oppugnationem","oppugnationis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qui tum primum allato nuntio de {{oppugnatione}} Vellaunoduni, cum longius eam rem ductum iri existimarent, praesidium Cenabi tuendi causa quod eo mitterent comparabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"oppugno","latin":"oppugnō","headword":"oppugnō","letter":"o","pos":"verb","posGroup":"verb","english":"to attack","forms":["oppugnābant","oppugnābātur","oppugnandā","oppugnandam","oppugnandī","oppugnandīs","oppugnant","oppugnantem","oppugnantur","oppugnare","oppugnārent","oppugnāret","oppugnārī","oppugnat","oppugnata","oppugnātam","oppugnātum","oppugnātur","oppugnātūrus","oppugnāvērunt","oppugnāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, {{oppugnare}} instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ops","latin":"ops, -opis ( f.)","headword":"ops","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"power, aid, assistance; power, aid, abundance; power, help; (pl.) wealth, resources","forms":["ope","opem","opēs","opibus","opis","opum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum {{opibus}} subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"optare","latin":"(optō) optāre, optāvisse, optātum","headword":"optāre","letter":"o","pos":"verb","posGroup":"verb","english":"choose, wish for; to wish, desire","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"optativus","latin":"optātīvus","headword":"optātīvus","letter":"o","pos":"","posGroup":"other","english":"(modus) optative (wishing) mood","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"optimas","latin":"optimas, optimatis","headword":"optimas","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"aristocrat, patrician; wellborn; nobles/patricians/\"Good men\" adherent/partisan","forms":["optimātibus","optimātium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cornēliō Nāsīcā in Capitōliō ab {{optimātibus}} occīsus est, ictus prīmum fragmentīs subselliī, et inter aliōs quī in eādem sēditiōne occīsī erant īnsepultus in flūmen prōiectus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"optimates","latin":"optimātēs, -ium (m. pl.)","headword":"optimātēs","letter":"o","pos":"","posGroup":"other","english":"the nobility","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"optime","latin":"optimē","headword":"optimē","letter":"o","pos":"adverb","posGroup":"adverb","english":"very good, excellent","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"optimus","latin":"optimus, -a, -um","headword":"optimus","letter":"o","pos":"adjective","posGroup":"adjective","english":"best; very good, excellent","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"optio","latin":"optio, optionis","headword":"optio","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"adjutant, assistant, helper; junior officer chosen by centurion to assist","forms":["optiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dīligēbat Deus Salomōnem: eī per quiētem adstāre vīsus est, deditque {{optiōnem}} ēligendī quidquid vellet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"opto","latin":"optō (1)","headword":"optō","letter":"o","pos":"verb","posGroup":"verb","english":"wish for, desire; to wish, choose","forms":["optābam","optābat","optāmus","optandī","optandum","optāre","optārent","optāret","optās","optat","optāta","optātis","optātō","optāverant","optāverīs","optāveritis","optāvī","optem","optēs","optō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ad ōram maritimam Lātōna postrēmō advēnit, ubi sīc Neptūnum ōrāvit: “Ō Neptūne, ōrō tē ut mē in īnsulam ferās in mediō marī sitam: optō enim ut ibi īrātam Iūnōnem tandem effugere possim!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"opulentia","latin":"opulentia, -ae","headword":"opulentia","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"sumptuosness","forms":["opulentiā","opulentiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Epulae quoque lēgātiōnibus parātae et opulentiā et cūrā eādem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"opulentus","latin":"opulentus, -a, -um","headword":"opulentus","letter":"o","pos":"adjective","posGroup":"adjective","english":"wealthy, powerful","forms":["opulentā","opulentam","opulentior","opulentīs","opulentissima","opulentissimae","opulentius","opulentō","opulentum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interim Turnus Rutulīque, cum rēbus suīs diffīderent, ad Etrūscōs Mezentiumque, rēgem eōrum, cōnfūgerant, quī Caere, opulentō tum oppidō, imperābat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"opus","latin":"opus, operis","headword":"opus","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"(n.) work; work, task; work, labor","forms":["opere","operi","operibus","operis","operum","opus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre {{operis}} laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"opus esse","latin":"opus esse","headword":"opus esse","letter":"o","pos":"","posGroup":"other","english":"(+ inf. or abl.) to need","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ora","latin":"ōra, -ae","headword":"ōra","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"border, coast; coast, shore; shore, sea shore","forms":["ōra","ōrae","ōram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quādam diē mulier apprehendit ōram palliī eius; at Iōsēphus relīquit pallium in manibus eius, et fugit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"oraculum","latin":"ōrāculum, -ī","headword":"ōrāculum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"oracle","forms":["ōrācula","ōrāculī","ōrāculum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi haec virgō dē coniuge scīre dēsīderāvit, ōrāculum respondit: \"Fuge coniugem, Atalanta.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"orare","latin":"(ōrō) ōrāre, ōrāvisse, ōrātum","headword":"ōrāre","letter":"o","pos":"","posGroup":"other","english":"beg, pray","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"oratio","latin":"ōrātiō, ōrātiōnis","headword":"ōrātiō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"(f.) speech; speech, sentence","forms":["oratio","oratione","orationem","ōrātiōnēs","ōrātiōnī","ōrātiōnibus","ōrātiōnis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Conclamat omnis multitudo et suo more armis concrepat, quod facere in eo consuerunt cuius {{orationem}} approbant: summum esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"orator","latin":"ōrātor, -ōris (m.)","headword":"ōrātor","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"speaker, orator, envoy; orator, speaker","forms":["ōrātor","ōrātōre","ōrātōrēs","ōrātōribus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi cūria Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) nefandās, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"oratorius","latin":"ōrātōrius, -a, -um","headword":"ōrātōrius","letter":"o","pos":"adjective","posGroup":"adjective","english":"oratorical","forms":["ōrātōriā","ōrātōriīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Antōnium et Hortēnsium, quī tum arte ōrātōriā excellebant, assiduē audiēbat, ac simul apud doctōrēs Graecōs, Molōnem rhētorem et Diodōtum philosophum, discēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"oratrix","latin":"ōrātrīx, -trīcis ( f.)","headword":"ōrātrīx","letter":"o","pos":"","posGroup":"other","english":"female suppliant","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"orbator","latin":"orbātor, -ōris","headword":"orbātor","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"bereaver, destroyer","forms":["orbātor"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"... cecidistī et fēmina ferrō, totque tuōs idem frātrēs, tē perdidit īdem, exitium Trōiae nostrīque {{orbātor}}, Achillēs; at postquam cecidit Paridis Phoebīque sagittīs, ‘nunc certē’ dīxī ‘nōn est metuendus Achillēs’: nunc quoque mī metuendus erat; cinis ipse sepultī in genus hoc saevit, tumulō quoque sēnsimus hostem, Aeacidae fēcunda fuī!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"orbis","latin":"orbis, orbis","headword":"orbis","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"(f.) circle, orbit; circle; orbis terrārum = the world","forms":["orbe","orbem","orbēs","orbī","orbibus","orbis","orbium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae ab reliquis Gallis civitates dissentirent, has sua diligentia adiuncturum atque unum consilium totius Galliae effecturum, cuius consensui ne {{orbis}} quidem terrarum possit obsistere; idque se prope iam effectum habere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"orbitas","latin":"orbitās, -ātis ( f.)","headword":"orbitās","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"loss of children/parents","forms":["orbitātem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec tantō dicta animō magis cōnfūdēre audientium animōs quam sī miserābiliter {{orbitātem}} suam dēflendō locūtus esset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"orbo","latin":"orbo, orbare, orbavi, orbatus","headword":"orbo","letter":"o","pos":"verb","posGroup":"verb","english":"bereave (of parents, children, etc), deprive (of)","forms":["orbātus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pompēium, quī tantā dignitāte, tantā glōriā sit {{orbātus}}, omnēs dēnique miserōs quī hāc lūce careant’...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"orbus","latin":"orbus, -a, -um","headword":"orbus","letter":"o","pos":"adjective","posGroup":"adjective","english":"childless, orphaned","forms":["orba","orbae","orbam","orbum","orbus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Orbum}} mē līberīs fēcistis: Iōsēphus mortuus est; Simeon retentus est in Aegyptō; Beniamīnum vultis abdūcere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"orcus","latin":"Orcus, -ī","headword":"Orcus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Orcus, the underworld","forms":["Orci","Orcō","Orcus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Orci}}, quae omnia bella devoratis:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ordinare","latin":"(ōrdinō) ōrdināre, -āvisse, -ātum","headword":"ōrdināre","letter":"o","pos":"","posGroup":"other","english":"put in order","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ordinatus","latin":"ordinatus, ordinata, ordinatum","headword":"ordinatus","letter":"o","pos":"adjective","posGroup":"adjective","english":"well-ordered; appointed","forms":["ōrdināta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pāx inter eōs ōrdināta est, ut Sulla ad bellum cīvīle festīnāns ā tergō perīculum nōn habēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ordino","latin":"ordino, ordinare, ordinavi, ordinatus","headword":"ordino","letter":"o","pos":"verb","posGroup":"verb","english":"order/arrange, set in order; adjust, regulate; compose; ordain/appoint (Bee)","forms":["ōrdinantur","ōrdinātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prīmus urbem Rōmam armātus ingressus est, Sulpicium interfēcit, Marium fugāvit, atque ita ōrdinātīs cōnsulibus in futūrum annum Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ordior","latin":"ordior, ordiri, orsus sum","headword":"ordior","letter":"o","pos":"verb","posGroup":"verb","english":"begin","forms":["Ōrdior","ōrdītur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"101 Ōrdior à cultū: cultīs bene Liber ab ūvīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ordiri","latin":"(ōrdior) ōrdīrī, orsum","headword":"ōrdīrī","letter":"o","pos":"","posGroup":"other","english":"begin (to speak)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ordo","latin":"ōrdō, ōrdinis","headword":"ōrdō","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"(f.) order; rank, order","forms":["ōrdine","ōrdinem","ordines","ordinibus","ōrdinis","ordo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His collocatis et coagmentatis alius insuper {{ordo}} additur, ut idem illud intervallum servetur neque inter se contingant trabes, sed paribus intermissae spatiis singulae singulis saxis interiectis arte contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"orestes","latin":"orestes, orestae","headword":"orestes","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Orestes; son of Agamennon and Clytaemnestra; play by Euripides; book by Varro","forms":["Orestē"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed quae fortūna tē revīsit, Hectoris Andromachē?\" Illa vultum dēmīsit et parvā vōce locūta est: sē et Helēnum Trōiā captā ā Pyrrhō in Ēpīrum abductōs esse; posteā vērō, cum Pyrrhus interfectus esset ab Orestē, Agamemnonis fīliō, Helēnum Chaoniā, parte Ēpīrī extrēmā, potītum esse et sē uxōrem dūxisse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"orgium","latin":"orgium, orgi(i)","headword":"orgium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"secret rites (of Bacchus) (pl.), mysteries; orgies","forms":["orgia"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{orgia}} nocturnusque vocat clāmōre Cithaerōn.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"oriens","latin":"oriēns, orientis","headword":"oriēns","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"(m.) east; the rising sun; the East, the land of the rising sun","forms":["oriēns","oriente","orientem","orientis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae Cenabi {{oriente}} sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"orientalis","latin":"orientālis, -e","headword":"orientālis","letter":"o","pos":"","posGroup":"other","english":"eastern","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"origo","latin":"orīgō, -inis ( f.)","headword":"orīgō","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"beginning, origin; origin, beginning","forms":["orīgine","orīginem","Orīginēs","orīginis","orīgō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic tibi quaerātur sociī sermōnis orīgō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"orior","latin":"orior, oriri, ortus sum","headword":"orior","letter":"o","pos":"verb","posGroup":"verb","english":"rise (sun/river); arise/emerge, crop up; get up (wake); begin; originate from","forms":["oriēbātur","Orior","orīrētur","orīrī","oriuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī nūllus est deus, quōmodo sōl et stēllae movērī possunt? unde {{oriuntur}} ventī et imbrēs? quis fulgura tonitrūsque efficit?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"oriri","latin":"orīrī","headword":"orīrī","letter":"o","pos":"verb","posGroup":"verb","english":"to rise","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"oritur","latin":"oritur, orīrī","headword":"oritur","letter":"o","pos":"","posGroup":"other","english":"rise, appear","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"ornamentum","latin":"ōrnāmentum, -ī","headword":"ōrnāmentum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"ornament, piece of jewelry; ornament, piece of jewellery","forms":["ōrnāmenta","ōrnāmentīs","ornamento","ōrnāmentōrum","ōrnāmentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et {{ornamento}} sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ornat","latin":"ornat, ornant","headword":"ornat","letter":"o","pos":"verb","posGroup":"verb","english":"equip, adorn; adorns, decorates","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ornatus","latin":"ōrnātus, -a, -um","headword":"ōrnātus","letter":"o","pos":"adjective","posGroup":"adjective","english":"embellished, distinguished; adorned, distinguished","forms":["ōrnāta","ōrnātam","ōrnātās","ornatōs","ōrnātus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mercurius vērō continuō, sine morā, patris imperiō pāruit: induit calceōs suōs aureōs et ālis {{ornatōs}}, quibus ventō celerius volāre potest sīve super mare sīve super terram, et, virgam manū gerēns, ad campōs, in quibus ignēs ab hominibus accēnsōs vīderat, volandō pervēnit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"orno","latin":"ōrnō, -āre, -āvī, -ātum","headword":"ōrnō","letter":"o","pos":"verb","posGroup":"verb","english":"decorate, adorn","forms":["ōrnābat","ōrnābātur","ōrnābis","ōrnandī","ōrnant","ōrnantur","ōrnāre","ōrnārent","ōrnāret","ōrnārī","ōrnās","ōrnat","ōrnātīs","ōrnātō","ōrnātum","ōrnātur","ōrnāverant","ōrnāverat","ōrnāverint","ōrnāvit","ōrnent"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus dīcit ‘mātrem suam et gemmīs et margarītīs et ānulīs pulchrīs ōrnārī nec aliam fēminam tam fōrmōsam esse...’”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ornus","latin":"ornus, orni","headword":"ornus","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"ash-tree","forms":["ornōs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sub pedibus terram et dēscendere montibus {{ornōs}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"oro","latin":"ōrō, -āre, -āvī, -ātum","headword":"ōrō","letter":"o","pos":"verb","posGroup":"verb","english":"beg for, ask for, pray to, implore","forms":["ōrābam","orabant","ōrābat","Ōrāmus","ōrāns","ōrant","ōrantem","ōrantēs","ōrantī","ōrantibus","ōrāre","ōrās","orat","ōrātē","ōrātis","oratum","ōrāverit","ōrāvērunt","ōrāvisse","ōrāvit","oreretur","oritur","ōrō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille oppidum Biturigum positum in via Noviodunum oppugnare instituerat. (Quo ex oppido cum legati ad eum venissent {{oratum}} ut sibi ignosceret suaeque vitae consuleret, ut celeritate reliquas res conficeret, qua pleraque erat consecutus, arma conferri, equos produci, obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"orpheus","latin":"Orpheus, -ī","headword":"Orpheus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Orpheus (the singer, bard of Apollo)","forms":["Orpheī","Orpheū","Orphēum","Orpheus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Orpheus}} nōbilissimus fidicen atque poēta ēgregius fuit, quī inde ā puerō tam pulchrē canēbat, ut nōn sōlum bēstiae ferae ad eum accurrerent, vērum etiam rapida flūmina cōnsisterent, nē strepitū cantum eius turbārent, ac saxa ipsa arborēsque (mīrābile vīsū!) ad audiendum venīrent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"orsus","latin":"orsus, orsus","headword":"orsus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"web (weaving); beginning, start; attempt (ACC P), undertaking, initiative","forms":["ōrsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quī postquam ad rēgīnam addūctī sunt, Īlionēus, maximus eōrum, sīc ōrsus est: 'Ō rēgīna!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"orto","latin":"orto, ortare, ortavi, ortatus","headword":"orto","letter":"o","pos":"verb","posGroup":"verb","english":"procreate; give birth/rise to; beget; engender/produce/generate (offspring)","forms":["orto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum vero ex omnibus urbis partibus {{orto}} clamore, qui longius aberant repentino tumultu perterriti, cum hostem intra portas esse existimarent, sese ex oppido eiecerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ortus","latin":"ortus, -ūs","headword":"ortus","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"rising, sunrise, origin; source, origin; rising (of the sun)","forms":["orta","ortae","ortī","ortū","ortum","ortus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His rebus cognitis, Caesar summo studio militum ante {{ortum}} solis in castra pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"os","latin":"ōs, ōris","headword":"ōs","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"(n.) mouth; (n.) bone; mouth, face; opening","forms":["ōre","ōrī","ōris","ōrum","ōs","ossa","osse","ossibus","ossīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce ōs eius quod ad tē rīdet.” rīdentem: “Ad mē” inquit “nōn sōlum ōs lūnae rīdet, sed etiam ōs tuum rubrum ut rosa.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"oscitare","latin":"(ōscitō) ōscitāre, ōscitāvisse, ōscitātum","headword":"ōscitāre","letter":"o","pos":"verb","posGroup":"verb","english":"gape, yawn; to yawn","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"oscito","latin":"oscito, oscitare, -, -","headword":"oscito","letter":"o","pos":"verb","posGroup":"verb","english":"gape; yawn","forms":["oscitat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Ecce rubet quidam, pallet, stupet, {{oscitat}}, odit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"osculatur","latin":"ōsculātur","headword":"ōsculātur","letter":"o","pos":"verb","posGroup":"verb","english":"kisses","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"osculor","latin":"ōsculor, ōsculārī","headword":"ōsculor","letter":"o","pos":"verb","posGroup":"verb","english":"kiss","forms":["ōsculābātur","ōsculāns","ōsculantur","ōsculārētur","ōsculāta","ōsculātur","ōsculātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ego sum, inquit, fīlius Rebeccae; et ōsculātus est eam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"osculum","latin":"ōsculum, -ī","headword":"ōsculum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"kiss","forms":["ōscula","ōsculīs","osculō","ōsculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus laetus ad Lȳdiam adit et eī multa ōscula dat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ossuculum","latin":"ossuculum, ossuculi","headword":"ossuculum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"small bone","forms":["ossucula"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Bī Sed tamen suāviter fuit, etiam sî coäctî sumus dîmidiäs pôtiônës super {{ossucula}} eius efﬁmdere!” “Tamen” inquit Trimalchiô “quid habuistis in cēnā?” sum ut ﬁequenter nômen meum oblîvîscar!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ostendit","latin":"ostendit, ostendunt","headword":"ostendit","letter":"o","pos":"verb","posGroup":"verb","english":"show; shows, points out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ostendo","latin":"ostendō, -ere, -tendī, -tēnsum","headword":"ostendō","letter":"o","pos":"verb","posGroup":"verb","english":"to show, point out","forms":["ostendam","ostendās","ostende","ostendēbat","ostendēbātur","ostendendī","ostendēns","ostendere","ostenderet","ostenderō","ostenderunt","ostendet","ostendī","ostendimus","ostendis","ostendisset","ostendit","Ostendite","ostendō","ostendunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' {{Ostendit}} cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ostentare","latin":"(ostentō) ostentāre","headword":"ostentāre","letter":"o","pos":"","posGroup":"other","english":"display ostentatiously","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ostentatio","latin":"ostentatio, ostentationis","headword":"ostentatio","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"exhibition, display; showing off","forms":["ostentātiōne","ostentationem","ostentationis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"His paucos addit equites qui latius {{ostentationis}} causa vagarentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ostentator","latin":"ostentator, ostentatoris","headword":"ostentator","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"displayer; boaster","forms":["ostentātōrem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Notātiō est cum alicuius nātūra certīs dēscrībitur signīs, quae, sīcutī notae quaedam, nātūrae sunt attribūtae — ut sī velīs nōn dīvitem, sed {{ostentātōrem}} pecūniōsī dēscrībere: “Iste,” inquiēs, “quī sē dīcī ‘dīvitem’ putat esse praeclārum, prīmum nunc vidēte, quō vultū nōs intueātur: nōnne vōbīs vidētur dīcere: ‘Darem vōbīs quidlibet, sī mihi molestī nōn essētis!’?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ostento","latin":"ostento, ostentare, ostentavi, ostentatus","headword":"ostento","letter":"o","pos":"verb","posGroup":"verb","english":"show, display; point out, declare; disclose, hold out (prospect)","forms":["ostentandō","ostentāns","ostentare","ostentat","ostentēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quorum cum magna multitudo convenisset, matres familiae, quae paulo ante Romanis de muro manus tendebant, suos obtestari et more Gallico passum capillum {{ostentare}} liberosque in conspectum proferre coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ostiarius","latin":"ōstiārius, -ī","headword":"ōstiārius","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"doorkeeper","forms":["ōstiāriō","Ōstiārius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Pater fīliōs salūtat: 'Salvēte, fīliī!' et ā fīliīs salūtātur: 'Salvē, pater!' Iūlius ambulat ad ōstium, quod ab ōstiāriō aperītur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ostium","latin":"ōstium, -ī","headword":"ōstium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"door, entrance; door; mouth (of a river), entrance","forms":["ōstia","ōstiō","ōstium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus ōstium aperit et intrat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ostrum","latin":"ostrum, ostri","headword":"ostrum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"purple dye; purple color; material/garment/anything that has been dyed purple","forms":["ostrō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"conveniunt, strātōque super discumbitur ostrō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"otior","latin":"otior, otiari, otiatus sum","headword":"otior","letter":"o","pos":"verb","posGroup":"verb","english":"be at leisure, enjoy a holiday","forms":["ōtior"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prānsus nōn avidē (quantum interpellet inānī ventre diem dūrāre), domesticus ōtior.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"otiosus","latin":"ōtiōsus, -a, -um","headword":"ōtiōsus","letter":"o","pos":"adjective","posGroup":"adjective","english":"leisured, idle; at leisure, idle","forms":["ōtiōsam","ōtiōsiōrem","ōtiōsōrum","ōtiōsōs","ōtiōsum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Poētās ut hominēs ōtiōsōs ōderam, praecipuē Tibullum, quī vītam rūsticam atque ōtiōsam laudābat, vītam mīlitārem dēspiciēbat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"otium","latin":"ōtium, -ī","headword":"ōtium","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"leisure; leisure, free time","forms":["ōtia","ōtiī","ōtiō","ōtium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In urbe semper in negōtiō est, sed rūrī in ōtiō cōgitat dē urbānīs.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ovare","latin":"(ovō) ovāre","headword":"ovāre","letter":"o","pos":"","posGroup":"other","english":"exult, rejoice","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"ovicula","latin":"ovicula, oviculae","headword":"ovicula","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"little sheep; E:Christ's sheep; sheep of Christ's flock","forms":["oviculam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Vēnit ad hominem dīvitem hospes quīdam; cumque eī parandum esset convīvium, dīves ille pepercit suīs ovibus, et {{oviculam}} pauperis, vī ēreptam, hospitī edendam apposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ovidius","latin":"Ovidius, -ī","headword":"Ovidius","letter":"o","pos":"noun (m.)","posGroup":"noun","english":"Ovid, the poet","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ovile","latin":"ovile, ovilis","headword":"ovile","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"sheepfold","forms":["ovīle"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{ovīle}} -is /' ? locus quó inclūduntur","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ovis","latin":"ovis, ovis","headword":"ovis","letter":"o","pos":"noun (f.)","posGroup":"noun","english":"(f.) sheep","forms":["ove","ovem","ovēs","ōvī","ovibus","ovis","ovium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faustīnus, pāstor Iūliī, abest ab {{ovibus}} suīs, quia ovem nigram in silvā quaerit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ovo","latin":"ovo, ovare, ovavi, ovatus","headword":"ovo","letter":"o","pos":"verb","posGroup":"verb","english":"rejoice","forms":["ovantem","ovantēs","ovantīs","ōvō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dītī igitur omnēs laetī ab ōvō iīsque ad mala fābulābantur optimōs cibōs gustantēs et vīnum, quod ministrī in pōcula fundēbant, magnō cum gaudiō pōtantēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ovum","latin":"ōvum, -ī","headword":"ōvum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"egg","forms":["ōva"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In nīdīs sunt ōva.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"oxygarum","latin":"oxygarum, oxygari","headword":"oxygarum","letter":"o","pos":"noun (n.)","posGroup":"noun","english":"vinegar-garum sauce","forms":["oxygarum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pōne {{oxygarum}} et lactūcās et cucumerēs!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pabulari","latin":"(pābulor) pābulārī","headword":"pābulārī","letter":"p","pos":"","posGroup":"other","english":"forage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pabulatio","latin":"pabulatio, pabulationis","headword":"pabulatio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"foraging","forms":["pabulatione","pabulationes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Omnibus modis huic rei studendum ut {{pabulatione}} et commeatu Romani prohibeantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pabulor","latin":"pabulor, pabulari, pabulatus sum","headword":"pabulor","letter":"p","pos":"verb","posGroup":"verb","english":"forage","forms":["pabulandi","pabulatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Praeterea salutis causa rei familiaris commoda neglegenda: vicos atque aedificia incendi oportere hoc spatio ab via quoqueversus quo {{pabulandi}} causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pabulum","latin":"pābulum, -ī","headword":"pābulum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"fodder; fodder, feed; fodder, food","forms":["pābula","pābulī","pabulo","pabulum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Pabulum}} secari non posse; necessario dispersos hostes ex aedificiis petere; hos omnes cotidie ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pacare","latin":"(pācō) pācāre","headword":"pācāre","letter":"p","pos":"","posGroup":"other","english":"subdue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pacatum","latin":"pacatum, pacati","headword":"pacatum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"friendly country","forms":["pācātum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Est, ubi Trōia fuit, Phrygiae contrāria tellus; lītore Thrēiciō classem religārat Ātrīdēs dum mare {{pācātum}} dum ventus amīcior esset: hīc subitō, quantus, cum vīveret, esse solēbat, exit humō lātē ruptā similisque minantī temporis illīus vultum referēbat Achillēs, quō ferus iniūstō petiit Agamemnona ferrō “immemorēs” que “meī discēditis” inquit “Achīvī, obrutaque est mēcum virtūtis grātia nostrae?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pacifer","latin":"pacifer, pacifera, paciferum","headword":"pacifer","letter":"p","pos":"adjective","posGroup":"adjective","english":"that brings peace; (esp. of various gods); of olive/laurel peace symbols/tokens","forms":["Pācifer"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Pācifer}} huic dederat flōrem Mercurius album:\nmōly vocant superī, nigrā rādīce tenētur;\ntūtus eō monitīsque simul caelestibus intrat\nille domum Circēs et ad īnsidiōsa vocātus\npōcula cōnantem virgā mulcēre capillōs\nreppulit et strictō pavidam dēterruit ēnse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pacisci","latin":"(pacīscor) pacīscī, pactum","headword":"pacīscī","letter":"p","pos":"","posGroup":"other","english":"contract/stipulate for","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pacisco","latin":"pacisco, paciscere, -, pactus","headword":"pacisco","letter":"p","pos":"verb","posGroup":"verb","english":"make a bargain or agreement; agree, enter into a marriage contract; negotiate","forms":["pācīscātur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ea postquam Cirtae audīta sunt, Italicī, quōrum virtūte moenia dēfendēbantur, cōnfīsī dēditiōne factā propter magnitūdinem populī Rōmānī inviolātōs sēsē fore, Adherbalī suādent 'utī sēque et oppidum Iugurthae trādat, tantum ab eō vītam {{pācīscātur}}.' At ille, tametsī omnia potiōra fidē Iugurthae rebātur, tamen — quia penes eōsdem, sī adversārētur, cogundī potestās erat — ita utī cēnsuerant Italicī dēditiōnem facit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"paco","latin":"pācō (1)","headword":"pācō","letter":"p","pos":"verb","posGroup":"verb","english":"make peaceful, pacify","forms":["pācātō","pacaverat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caesar, quod hostes equitatu superiores esse intellegebat et interclusis omnibus itineribus nulla re ex provincia atque Italia sublevari poterat, trans Rhenum in Germaniam mittit ad eas civitates quas superioribus annis {{pacaverat}} equitesque ab his arcessit et levis armaturae pedites, qui inter eos proeliari consuerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pactio","latin":"pactio, pactionis","headword":"pactio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"bargain, agreement","forms":["pactiōne"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad hōc collēgam suum Antōnium {{pactiōne}} prōvinciae perpulerat nē contrā rem pūblicam sentīret; circum sē praesidia amīcōrum atque clientium occultē habēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"pactum","latin":"pactum, pacti","headword":"pactum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"bargain, agreement; manner","forms":["pacto","pactum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hi similitudine armorum vehementer nostros perterruerunt, ac, tametsi dextris umeris exsertis animadvertebantur, quod insigne {{pactum}} esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pactus","latin":"pactus, pacta, pactum","headword":"pactus","letter":"p","pos":"adjective","posGroup":"adjective","english":"agreed upon, appointed","forms":["pactam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cui sciam {{pactam}} et cōnstitūtam cum Mānliō diem?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"padus","latin":"Padus, Padi","headword":"Padus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Po river","forms":["Padum","Padus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tiberis fluvius nōn tam longus est quam fluvius {{Padus}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"paedagogus","latin":"paedagogus, paedagogi","headword":"paedagogus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"slave, who accompanied children to school; pedagogue","forms":["paedagōgō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prōcessī dē cubiculō cum paedagōgō et cum nūtrīce salūtāre patrem et mātrem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"paelex","latin":"paelex, -icis ( f.)","headword":"paelex","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"concubine","forms":["paelex","paelice","Paelicibus","paelicis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"320 ettenuitlaetà {{paelicis}} exta manū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"paene","latin":"paene","headword":"paene","letter":"p","pos":"adverb","posGroup":"adverb","english":"nearly, almost; almost, nearly; almost","forms":["paene"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum is murum hostium {{paene}} contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante tertiam vigiliam est animadversum fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paeninsula","latin":"paenīnsula, -ae","headword":"paenīnsula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"peninsula","forms":["paenīnsula","paenīnsulae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quae est illā īnsula?\" Daedalus: \"Peloponnēsus est, Graeciae pars, nec vērō īnsula est, sed {{paenīnsula}}, nam Peloponnēsus terrā angustā, quae Isthmus vocātur, cum reliquā Graeciā coniungitur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"paenitentia","latin":"paenitentia, paenitentiae","headword":"paenitentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"regret (for act); change of mind/attitude; repentance/contrition (Def); penance","forms":["paenitentiā","paenitentiae","paenitentiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Amōn, Mānāssis fīlius, patēmam impietātem imitātus est, nōn vērō {{paenitentiam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"paeniteo","latin":"paeniteo, paenitere, paenitui, -","headword":"paeniteo","letter":"p","pos":"verb","posGroup":"verb","english":"displease; (cause to) regret; repent, be sorry; [me paenitet => I am sorry]","forms":["paenitēbat","paenitēbit","paenitēre","paenitēret","paenituisse","paenituit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Brevī rēgem {{paenituit}}, quod tot mīlia hominum dīmīsisset, et, collēctō ingentī exercitū, eōs persecūtus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"paenitere","latin":"(paeniteō) paenitēre, paenituisse","headword":"paenitēre","letter":"p","pos":"","posGroup":"other","english":"regret, repent","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"paenitet","latin":"paenitet, paenitere, paenituit, -","headword":"paenitet","letter":"p","pos":"verb","posGroup":"verb","english":"it displeases, makes angry, offends, dissatisfies, makes sorry","forms":["paenitet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"paenitēre -uisse; {{paenitet}} ^ acc/gen:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"paenula","latin":"paenula, paenulae","headword":"paenula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"hooded weatherproof cloak","forms":["paenulam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Suprā induō {{paenulam}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"paetus","latin":"paetus, paeta, paetum","headword":"paetus","letter":"p","pos":"adjective","posGroup":"adjective","english":"having cast in the eye, squinting slightly","forms":["paeta","paetus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"sī {{paeta}} est, * Venerī similīs',","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pagina","latin":"pāgina, -ae","headword":"pāgina","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"page","forms":["pāginā","pāginae","pāginam","pāginās"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In LINGVĀ LATĪNĀ sunt multae {{pāginae}} et multa capitula: capitulum prīmum, secundum, tertium, cētera. 'IMPERIVM ROMANVM' est titulus capitulī prīmī.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pagus","latin":"pagus, pagi","headword":"pagus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"country district/community, canton","forms":["pagos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Altera ex parte Gabalos proximosque {{pagos}} Arvernorum in Helvios, item Rutenos Cadurcosque ad fines Volcarum Arecomicorum depopulandos mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"palaestra","latin":"palaestra, palaestrae","headword":"palaestra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"palaestra, wrestling school; gymnasium","forms":["palaestram"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Tertius et quārtus ex fīliīs, postquam operī cotīdiānō fīnem imposuerant, in {{palaestram}} īverant, ut validiōra corpons membra facerent: cum vērō iam alter alterum luctandō complecterētur, ūnā sagittā eōs ita iūnctōs trānsfīxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"palam","latin":"palam","headword":"palam","letter":"p","pos":"adverb","posGroup":"adverb","english":"openly, publicly","forms":["palam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mēne {{palam}} nostrae det","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"palari","latin":"(pālor) pālārī","headword":"pālārī","letter":"p","pos":"","posGroup":"other","english":"stray, be dispersed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"palatinus","latin":"Palatinus, Palatina, Palatinum","headword":"Palatinus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Palatine; imperial; name of one of the hills of Rome, the Palatine","forms":["Palātīnam","Palātīnō","Palātīnum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Omnium vērō magnificentissima est domus illa ā Domitiānō prīncipe in colle Palātīnō aedificāta, quae vocātur \"domus Augustāna\".","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"palatium","latin":"Palatium, Palati(i)","headword":"Palatium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"Palatine Hill","forms":["Palātia","Palātiī","Palātiō","Palātium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In mediā urbe inter collēs Capitōlium et {{Palātium}} est forum Rōmānum, quō hominēs ex tōtā Italiā atque ex omnibus prōvinciīs Rōmānīs conveniunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"palatum","latin":"palatum, palati","headword":"palatum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"palate; sense of taste","forms":["Palātī","palātō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Illa parāvit senī cibum quem nōverat suāvem esse palātō eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"palea","latin":"palea, paleae","headword":"palea","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"chaff, husk","forms":["paleā","paleam","paleārum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Est domī locus ad commorandum amplissmus; est etiam plūrimum foenī et {{paleārum}} ad ūsum camēlōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"palinurus","latin":"Palinurus, Palinuri","headword":"Palinurus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Palinurus; (helmsman of Aeneas, fell overboard)","forms":["Palīnūrus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Palīnūrus}}, optimus gubernātor, rēctum cursum tenēre nōn poterat neque diem noctemque discernere, cum nec sōl interdiū nec stēllae noctū appārērent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"palla","latin":"palla, pallae","headword":"palla","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"palla, a lady's outer garment","forms":["pallam"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ferre iubet, {{pallam}} signīs aurōque rigentem,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pallas","latin":"Pallas, Pallantis","headword":"Pallas","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pallas; (son of Evander, young warrior ally of Aeneas, killed by Turnus)","forms":["Palladis","Pallas"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Auget uterque suās externō rōbore vīrēs,\net multī Rutulōs, multī Trōiāna tuentur\ncastra, neque Aenēās Evandrī ad moenia frūstrā\n[īvit; nam {{Pallas}}, fīlius Evandrī, ad bellum pugnandum missus est.]\n[Bellum] perstat, habetque deōs pars utraque, quodque\ndeōrum est īnstar, habent animōs. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"palleo","latin":"palleō, -ēre, palluī","headword":"palleō","letter":"p","pos":"verb","posGroup":"verb","english":"become pale","forms":["palleat","pallēbat","pallentia","pallentīs","pallēre","pallēs","pallet","palluit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pater vērō, cubiculum ingressus, fīlium colōrem mūtāvisse animadvertit et “Quid {{pallēs}}, fīlī?” inquit “Utrum aegrōtās an territus es?” Fīlius autem id, quod Apollō dīxerat, patrī nārrāvit, eumque rogāvit, ut prō sē ad illud rēgnum dēscenderet, ubi umbrae mortuōrum versārī dīcuntur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pallere","latin":"(palleō) pallēre","headword":"pallēre","letter":"p","pos":"","posGroup":"other","english":"be pale","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"pallescere","latin":"(pallēscō) pallēscere, -luisse","headword":"pallēscere","letter":"p","pos":"verb","posGroup":"verb","english":"grow pale; to grow pale","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"pallesco","latin":"pallesco, pallescere, pallui, -","headword":"pallesco","letter":"p","pos":"verb","posGroup":"verb","english":"grow pale; blanch; fade","forms":["pallēscunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"palluit ut {{pallēscunt}} sērae frondés...","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pallidus","latin":"pallidus, -a, -um","headword":"pallidus","letter":"p","pos":"adjective","posGroup":"adjective","english":"pale","forms":["pallida","pallidō","pallidum","pallidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postquam vērō Admētus ad quadrāgēsimum aetātis annum pervēnit, Apollō eī in cubiculō suō versantī “Mox” inquit “{{pallida}} mors ad tē veniet, quae imperābit ut ad Īnferōs dēscendās, unde nēmō rediit umquam.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pallio","latin":"pallio, palliare, palliavi, palliatus","headword":"pallio","letter":"p","pos":"verb","posGroup":"verb","english":"disguise; cloak; palliate","forms":["palliō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Illa statim operuit sē palliō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"palliolum","latin":"palliolum, pallioli","headword":"palliolum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"little Greek cloak; a hood","forms":["palliolum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{palliolum}} nitidīs imposuisse comīs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pallium","latin":"pallium, -ī","headword":"pallium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"cloak; cloak, mantle","forms":["palli","Pallia","palliī","pallium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quādam diē mulier apprehendit ōram palliī eius; at Iōsēphus relīquit pallium in manibus eius, et fugit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pallor","latin":"pallor, palloris","headword":"pallor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"wanness; paleness of complexion; pallidness","forms":["pallor","pallōre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"inductō {{pallōre}}, fugit, cōnātaque retrō","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"palma","latin":"palma, -ae","headword":"palma","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"palm; palm, hand; palm, prize; palm (of victory), prize","forms":["palma","palmam","palmārum","palmās","palmīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sed plerumque is qui victus est occiditur, victor vero {{palmam}} accipit, dum spectatores delectati clamant ac manibus plaudunt.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"palmes","latin":"palmes, palmitis","headword":"palmes","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"young vine branch/shoot/sprig/sprout; vine, bough, branch","forms":["palmitēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum prior sīc exposuit Iōsēphō somnium suum: vīdī in quiēte vītem in quā erant trēs {{palmitēs}}; ea paulātim prōtulit gemmās; deinde flōrēs ērūpērunt, ac dēnique ūvae mātūrēscēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"palpitat","latin":"palpitat, palpitāre","headword":"palpitat","letter":"p","pos":"verb","posGroup":"verb","english":"beat, throb; beats, throbs","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"palpito","latin":"palpito, palpitare, palpitavi, palpitatus","headword":"palpito","letter":"p","pos":"verb","posGroup":"verb","english":"throb, beat, pulsate","forms":["palpitāre","palpitāret","palpitat","palpitāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Cum Absalōn adhūc {{palpitāret}} haerēns in quercū, armigerī Iōābī repetītīs ictibus cōnfossum interimērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"paludamentum","latin":"palūdāmentum, -ī","headword":"palūdāmentum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"military cloak; commander’s cloak","forms":["palūdāmentō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cui soror virgō, quae dēspōnsa ūnī ex Curiātiīs fuerat, obvia ante portam Capēnam fuit, cognitōque super umerōs frātris palūdāmentō spōnsī, quod ipsa cōnfēcerat, solvit crīnēs et flēbiliter nōmine spōnsum mortuum appellat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"palum","latin":"palum, pali","headword":"palum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"stake/pile/pole/unsplit wood; peg/pin; execution stake; wood sword; fence (pl.)","forms":["pālum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et affīget ad {{pālum}}, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"palumbus","latin":"palumbus, palumbi","headword":"palumbus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"wood-pigeon, ringdove; dupe, pigeon, mark, gull, one deceived/fooled/cheated","forms":["palumbum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Voluerīs: dē vulvā faciet piscem, dē lärdô {{palumbum}}, dē pēmā turturem, dē côlëpiô gallînam.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"palus","latin":"palūs, -ūdis ( f.)","headword":"palūs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"fen, swamp; stake; marsh, swamp","forms":["palude","paludem","paludibus","palūdis","palus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et {{palude}} circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paluster","latin":"paluster, palustris, palustre","headword":"paluster","letter":"p","pos":"adjective","posGroup":"adjective","english":"marshy; of marshes","forms":["palustribus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"[Aenēās] . . . loca fēta {{palustribus}} undīs,\nlītora Cūmārum vīvācisque antrā Sibyllae\nintrat, et [ut] ad mānēs veniat per Averna paternōs\nōrat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pan","latin":"Pān, Pānos","headword":"Pān","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pan (a forest divinity, satyr)","forms":["Pan"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Neque igitur Satyrī, neque {{Pan}} et Silvānus, silvārum dī, ad eam accēdere potuerant, etsī nōn parvō amōre accēnsī erant; sed","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pandere","latin":"(pandō) pandere, -disse, -passum","headword":"pandere","letter":"p","pos":"","posGroup":"other","english":"spread out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pando","latin":"pando, pandere, pandi, passus","headword":"pando","letter":"p","pos":"verb","posGroup":"verb","english":"spread out [passis manibus => with hands outstretched]","forms":["pandere","pandī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"sinūs -üs »/ — fōrma curváta plénaque curvātō {{pandere}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pane","latin":"pane, panis","headword":"pane","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"bread","forms":["pāne"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Pāstor saccum cum {{pāne}} in colle relinquit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"panis","latin":"pānis, pānis","headword":"pānis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) bread, loaf; bread","forms":["pānem","pānēs","pānibus","pānis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Paulō post {{pānem}} et duōs piscēs et pōculum aquae plēnum dominō affert.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pannus","latin":"pannus, panni","headword":"pannus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"cloth, garment; charioteer's colored shirt; rags","forms":["pannīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum essent ibi, impletī sunt diēs pariendī, et peperit fīlium, quem {{pannīs}} involvit et reclīnāvit in praesēpiō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pansa","latin":"pansa, pansae","headword":"pansa","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"splay-footed","forms":["Pānsae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Continuôque cocum vocârî iussit et, nôn expectātā ëlëctiône nostIā, mäximum nātū iussit occîdî; et clārä vôce: “Ex quotā decuriā es?” Cum ille ‘sē ex quadrägësimâ’ respqndisset, “Ëmptî- cius an” inquit “domī nātus?” “Neutrum” inquit cocus, “sed testâmentô {{Pānsae}} tibi “Vidé ergô” ait “ut dîligenter pônäs!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pantheum","latin":"Pantheum, Panthei","headword":"Pantheum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"Pantheon, temple to all gods; (esp. rotunda temple by Agrippa in Rome)","forms":["Pantheum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eōdem tempore {{Pantheum}}, altum templum rotundum, in campō Mārtiō exstrūctum est ā M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"panthus","latin":"Panthus, Panthi","headword":"Panthus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Panthus, a priest of Apollo at Troy; used as a pseudonym","forms":["Panthūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce autem {{Panthūs}}, Apollinis sacerdōs, ex tēlīs Graecōrum ēlāpsus, amēns ad līmen accurrit sacra manū tenēns.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"papa","latin":"Papa, Papae","headword":"Papa","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pope","forms":["pāpae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Interiectiō quid est?' Discipulus: 'Pars ōrātiōnis significāns mentīs affectum vōce inconditā.' Magister: 'Significātiō interiectiōnis in quō est?' Discipulus: 'Aut laetitiam significāmus, ut euax!; aut dolōrem, ut heu!; aut admīrātiōnem, ut {{pāpae}}!; aut metum, ut attat!; et sī quā sunt similia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"papae","latin":"papae","headword":"papae","letter":"p","pos":"","posGroup":"other","english":"exclamation of wonder and joy","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"papaver","latin":"papāver, -eris (n.)","headword":"papāver","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"poppy","forms":["papāver","papāvere","papāverum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ponticulî etiam ferrüminätî sustiñëbant glîrës melle ac {{papāvere}} sparsôs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"papyrus","latin":"papȳrus, -ī","headword":"papȳrus","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"papyrus (paper); papyrus, reed","forms":["papyrī","papȳrō","papyrōs","papȳrus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister calamum et chartam prōmit et ipse scrībere incipit; is enim calamō in chartā scrībit, nōn stilō in cērā ut discipulī. (Charta ex papȳrō efficitur, id est ex altā herbā quae in Aegyptō apud Nīlum flūmen reperītur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"par","latin":"pār","headword":"pār","letter":"p","pos":"adjective","posGroup":"adjective","english":"(gen. paris) equal; equal, like","forms":["pār","paribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Trabes directae perpetuae in longitudinem {{paribus}} intervallis distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paradisus","latin":"paradisus, paradisi","headword":"paradisus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Paradise, Garden of Eden; abode of the blessed; park, orchard; a town/river","forms":["Paradīsī","paradīsō","Paradīsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Deus posuit Adamum et Ēvam in hortō amoenissimō, quī solet appellārī {{Paradīsus}} terrestris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"parare","latin":"(parō) parāre, -āvisse, -ātum","headword":"parāre","letter":"p","pos":"verb","posGroup":"verb","english":"get, prepare; to prepare","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"paratus","latin":"parātus, -a, -um","headword":"parātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"ready","forms":["parāta","parātae","parātam","parātās","parātī","parātissimā","paratos","parātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo {{paratos}} videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parce","latin":"parce, parcius, parcissime","headword":"parce","letter":"p","pos":"adverb","posGroup":"adverb","english":"sparingly, moderately; economically, frugally, thriftily, stingily","forms":["parce"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, viritim distribuit; frumentum {{parce}} et paulatim metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parcere","latin":"(parcō) parcere, pepercisse ({i}intr. + dat.{/i})","headword":"parcere","letter":"p","pos":"verb","posGroup":"verb","english":"spare; to spare (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"parco","latin":"parcō, parcere, pepercī","headword":"parcō","letter":"p","pos":"verb","posGroup":"verb","english":"spare (+ dat.)","forms":["parcam","parcās","parcendo","parcent","parcere","parcerent","parcerēs","parceret","parcimus","Parcīs","parcite","parcunt","pepercerant","pepercerīs","pepercerunt","pepercisset","pepercit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sic et Cenabi caede et labore operis incitati non aetate confectis, non mulieribus, non infantibus {{pepercerunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parcus","latin":"parcus, parca, parcum","headword":"parcus","letter":"p","pos":"adjective","posGroup":"adjective","english":"sparing, frugal; scanty, slight","forms":["Parcae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In dē- mentô levātum in tribūnal excelsum Mercurius rapiēbat. cornū abundantī et très {{Parcae}} aurea pēnsa torquentēs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"parens","latin":"parēns, parentis","headword":"parēns","letter":"p","pos":"noun","posGroup":"noun","english":"parent","forms":["parēns","parente","parentem","parentes","parentī","parentibus","parentīs","parentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Conclamant equites, sanctissimo iure iurando confirmari oportere, ne tecto recipiatur, ne ad liberos, ne ad {{parentes}}, ne ad uxorem aditum habeat qui non bis per agmen hostium perequitasset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parentale","latin":"parentale, parentalis","headword":"parentale","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"Parentalia; festival for dead ancestors","forms":["parentālia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"inquit “ad {{parentālia}} mea in- Îbat rēs ad surnmam nauseam, cum Trimalchiô, ēbrie- tâte turpissirnä gravis, novum acroânna, cornicinēs, in trī- clînium iussit addücî; fultusque cervîcälibus multîs ex- tendit sē suprā torum extrēmum, et “Fingite mē” inquit “mortuum esse!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"parentes","latin":"parentēs, -um","headword":"parentēs","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m. pl.) parents","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pareo","latin":"pareo, parere, parui, paritus","headword":"pareo","letter":"p","pos":"verb","posGroup":"verb","english":"obey, be subject/obedient to; submit/yield/comply; pay attention; attend to","forms":["pāreāmus","pārēbam","pārēbant","pārēbat","pārendō","pārendum","pāreō","pārēte","paruerint","pāruērunt","pāruisse","pāruissem","pāruissēs","pāruisset","pāruistī","pāruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non {{paruerint}} constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, viritim distribuit; frumentum parce et paulatim metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parere","latin":"pārēre","headword":"pārēre","letter":"p","pos":"verb","posGroup":"verb","english":"obey; to obey (+ dat.)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"paret","latin":"pāret","headword":"pāret","letter":"p","pos":"verb","posGroup":"verb","english":"(+ dat.) obey; obeys","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"paries","latin":"pariēs, -etis (m.)","headword":"pariēs","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"wall (of a house)","forms":["pariēs","pariete","parietem","parietēs","parietī","parietibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dīxit etiam mulierī: afficiam tē multīs malīs; {{pariēs}} līberōs in dolōre, et eris in potestāte virī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pario","latin":"pariō, -ere, peperī, partum","headword":"pariō","letter":"p","pos":"verb","posGroup":"verb","english":"give birth to","forms":["pārērent","pari","pariant","pariat","pariendī","pariendō","pariente","pariet","parit","paritūram","paritūrum","paritūrus","pariunt","parta","partam","partū","pepererat","peperērunt","peperī","peperisse","peperisset","peperistī","peperit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eporedorix Aeduus, summo loco natus adulescens et summae domi potentiae, et una Viridomarus, {{pari}} aetate et gratia sed genere dispari, quem Caesar ab Diviciaco sibi traditum ex humili loco ad summam dignitatem perduxerat, in equitum numero convenerant nominatim ab eo evocati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paris","latin":"Paris, Paridis","headword":"Paris","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Paris; (Trojan prince, abductor of Helen, slayer of Achilles)","forms":["Paridem","Paridis","Paris"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Orontēs: 'Sīcut {{Paris}}, rēgis Priamī fīlius dēbilis, quī ā servō rēgis fīdō in quōdam monte prope urbem Trōiam expositus...' At Cornēlius: 'Opus nōn est,' inquit, 'vetus exemplum Graecum afferre, cum complūrēs fābulae nārrentur dē Rōmānīs puerīs quī ita servātī sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"parit","latin":"parit, parere","headword":"parit","letter":"p","pos":"verb","posGroup":"verb","english":"give birth to, lay; gives birth to, lays","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pariter","latin":"pariter","headword":"pariter","letter":"p","pos":"adverb","posGroup":"adverb","english":"equally, together","forms":["pariter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mulier, dēcepta hīs verbīs, dēcerpsit frūctum et comēdit; deinde obtulit virō, quī {{pariter}} comēdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"paro","latin":"parō (1)","headword":"parō","letter":"p","pos":"verb","posGroup":"verb","english":"prepare","forms":["parā","parābant","parābantur","parābat","parābātur","parābis","paranda","parandum","parant","parante","parantem","parantur","parare","parārent","parārēs","parāret","parārētur","parārī","parat","parātīs","parato","parātum","parātur","paraverant","paraverat","parāvēre","parāverit","parāvērunt","Parāvī","parāvisse","parāvissent","parāvisset","parāvit","parem","pārēmus","parent","pārēre","pares","pāret","pārō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Bellovaci autem, defectione Aeduorum cognita, qui iam ante erant per se infideles, manus cogere atque aperte bellum {{parare}} coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paropsis","latin":"paropsis, paropsidis","headword":"paropsis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"dish for serving vegetables/fruit; desert dish (Cas)","forms":["paropsidēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ita ex hāc massā fabrî sustulērunt et tēcērunt catîlla et {{paropsidēs}} et stattmcula.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"parricida","latin":"parricīda, -ae","headword":"parricīda","letter":"p","pos":"noun","posGroup":"noun","english":"(m./f.) murderer of a near relative or head of state","forms":["parricīda","parricīdam","parricīdās","parricīdīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sōlō, vir sapiēns et iūstus, quī Athēniēnsibus lēgēs scrīpsit, nūllam poenam statuit in {{parricīdās}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"parricidium","latin":"parricīdium, -ī","headword":"parricīdium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"murder of near relation; murder of a parent","forms":["parricīdia","parricīdiī","parricīdiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec nocte nec interdiū virum conquiēscere patī, nē grātuīta praeterita {{parricīdia}} essent: \"nōn sibi dēfuisse marītum cum quō tacita servīret; dēfuisse virum quī sē rēgnō dignum esse putāret, quī meminisset sē esse Prīscī Tarquiniī fīlium, quī habēre quam spērāre rēgnum māllet!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pars","latin":"pars, partis","headword":"pars","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) part, direction; part","forms":["pars","parte","partem","partes","partibus","partis","partium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His suppliciis celeriter coacto exercitu, Lucterium Cadurcum, summae hominem audaciae, cum {{parte}} copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"parthus","latin":"Parthus, Parthi","headword":"Parthus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Parthian; inhabitant of Parthia (country south of Caspian Sea)","forms":["Parthī","Parthīs","Parthōrum","Parthōs","Parthus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Proelia cum {{Parthīs}}, cum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"particeps","latin":"particeps (gen. participis) (+ gen.)","headword":"particeps","letter":"p","pos":"adjective","posGroup":"adjective","english":"having a share in; sharing in, partaking of","forms":["particeps","participēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed et in rēgnīs nimis expertēs sunt cēterī commūnis iūris et cōnsiliī; et in optimātium dominātū vix {{particeps}} lībertātis potest esse multitūdō, cum omnī cōnsiliō commūnī ac potestāte careat; et cum omnia per populum geruntur, quamvīs iūstum atque moderātum, tamen ipsa aequābilitās est inīqua, cum habet nūllōs gradūs dignitātis...'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"participium","latin":"participium, -ī","headword":"participium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"participle","forms":["participia","participiī","participiōrum","participium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister discipulum interrogat: 'Partēs ōrātiōnis quot sunt?' Discipulus respondet: 'Octō.' Magister: 'Quae?' Discipulus: 'Nōmen, prōnōmen, verbum, adverbium, {{participium}}, coniūnctiō, praepositiō, interiectiō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"particula","latin":"particula, particulae","headword":"particula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"small part, little bit, particle, atom","forms":["particulae","particulīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Praetereā dīcit, ut ante eum Dēmocritus, ‘omnem rem, omnem māteriam efficī ex partibus minimīs, quae semper moventur.’ Eae {{particulae}} minimae, quae dīvidī nōn possunt, Graecē appellantur ‘atomī’.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"partim","latin":"partim","headword":"partim","letter":"p","pos":"adverb","posGroup":"adverb","english":"in part, partly","forms":["partim"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Igitur Iugurtha quam maximās potest cōpiās armat, urbēs {{partim}} vī, aliās voluntāte imperiō suō adiungit, omnī Numidiae imperāre parat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"partior","latin":"partior, partīrī","headword":"partior","letter":"p","pos":"verb","posGroup":"verb","english":"share, divide","forms":["partiēbātur","partīminī","partior","partīrī","partīris","partiti","partitis","partītur","partītus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tamen, quod instituto Caesaris semper duae legiones pro castris excubabant pluresque {{partitis}} temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque interscinderent, omnis vero ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"partiri","latin":"partīrī","headword":"partīrī","letter":"p","pos":"verb","posGroup":"verb","english":"to share, divide","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"partite","latin":"partite","headword":"partite","letter":"p","pos":"adverb","posGroup":"adverb","english":"with proper division of subject into its parts","forms":["partītē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"BLEPHARO: Vōs inter vōs partītē!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"partum","latin":"partum, parti","headword":"partum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"gains, acquisitions; savings; what one has acquired/saved","forms":["partum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hanc hōc bienniō cōnsul ēvertēs, eritque cōgnōmen id tibi per tē {{partum}} quod habēs adhūc hērēditārium ā nōbīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"parturio","latin":"parturio, parturire, parturivi, -","headword":"parturio","letter":"p","pos":"verb","posGroup":"verb","english":"be in labor; bring forth; produce; be pregnant with/ready to give birth","forms":["parturiēbat","Parturient","parturīre","parturit","PARTVRIENTI"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"IVPPITER: [parvā vōce] Intrō ego hinc eō: Alcumēna {{parturit}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"parturire","latin":"(parturiō) parturīre","headword":"parturīre","letter":"p","pos":"","posGroup":"other","english":"be ready to give birth to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"partus","latin":"partus, -ūs","headword":"partus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(giving) birth; birth, offspring","forms":["partūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{partūs}} -üs n € pārēre","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"parum","latin":"parum","headword":"parum","letter":"p","pos":"adverb","posGroup":"adverb","english":"little, too little, also indecl. noun","forms":["parum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nōn est ita, inquit Iōsēphus; sed vēnistis hūc animō hostīlī: vultis explōrāre nostrās urbēs et loca Aegyptī {{parum}} mūnīta.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"parumper","latin":"parumper","headword":"parumper","letter":"p","pos":"adverb","posGroup":"adverb","english":"for a short while","forms":["parumper"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"MERCVRIVS: Immō indūtiae {{parumper}} fīant, sī quid vīs loquī.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"parvulus","latin":"parvulus, -a, -um","headword":"parvulus","letter":"p","pos":"adjective","posGroup":"adjective","english":"small; little, tiny","forms":["parvula","parvulam","parvulī","parvulīs","parvulō","parvulōs","parvulum","parvulus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Diodōrus: “Cūr nōn lac bibere mē iubēs, medice, ut {{parvulum}} īnfantem?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"parvus","latin":"parvus, -a, -um","headword":"parvus","letter":"p","pos":"adjective","posGroup":"adjective","english":"little, small; small, little","forms":["minima","minimae","minimam","minime","minimīs","minimō","minimum","minimus","minora","minore","minōrem","minōrēs","minōrī","minoribus","minōris","pāruī","parva","parvae","parvam","parvās","parvē","parvī","parvīs","parvō","parvōs","parvum","parvus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vercingetorix {{minoribus}} Caesarem itineribus subsequitur et locum castris deligit paludibus silvisque munitum ab Avarico longe milia passuum XVI.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pascere","latin":"(pāscō) pāscere, pāvisse, pāstum","headword":"pāscere","letter":"p","pos":"verb","posGroup":"verb","english":"to pasture; to graze, feed","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"pascha","latin":"Pascha, Paschae","headword":"Pascha","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Passover; Easter","forms":["Pascha"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Prope erat {{Pascha}} ludaeōrum, flagellum -Ī n et ascendit Iēsus Hierosolymam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pascit","latin":"pāscit","headword":"pāscit","letter":"p","pos":"verb","posGroup":"verb","english":"grazes, feeds","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pasco","latin":"pāscō, -ere, pāvī, pāstum","headword":"pāscō","letter":"p","pos":"verb","posGroup":"verb","english":"feed; pasture","forms":["pāscās","pascat","Pāsce","pāscēbantur","pāscēbat","pāscēbātur","pāscentur","pāscere","pāscerem","pāscerent","pāsceret","pāscet","pāscit","pāscitur","pāscunt","pāscuntur","pastae","pāstum","pāvēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum Iacobus loquerētur cum pāstōribus, Rachēl, fīlia Labānī, venit cum pecore paternō: nam ipsa {{pāscēbat}} gregem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pascua","latin":"pascua, pascuae","headword":"pascua","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"pasture, pasture-land; piece of grazing land","forms":["pāscuā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"pāscuā per flōrēs et thyma summa volant,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"passer","latin":"passer, passeris","headword":"passer","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) sparrow","forms":["passer","passerem","passeris"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Lucernis accensis, Iulius librum Catulli proferri iubet, tum \"Incipiam\" inquit \"a carmine de morte {{passeris}} quem Lesbia in deliciis habuerat:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"passim","latin":"passim","headword":"passim","letter":"p","pos":"adverb","posGroup":"adverb","english":"far and wide, everywhere","forms":["passim"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tūne, duce Mathathīā, statuērunt p atriam armīs lThērāre, et religiōnem tuerī: itaque ārās {{passim}} falsīs niiminibus ērēctās ēvertērunt, neglēctumque vērum Deī cultum restituērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"passivum","latin":"passīvum (verbum)","headword":"passīvum","letter":"p","pos":"adjective","posGroup":"adjective","english":"passive","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"passivus","latin":"passīvus","headword":"passīvus","letter":"p","pos":"adjective","posGroup":"adjective","english":"passive","forms":["passīva"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Genera verbōrum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: 'Āctīva, {{passīva}}, neutra, dēpōnentia.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"passum","latin":"passum, passi","headword":"passum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"raisin-wine","forms":["passum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quorum cum magna multitudo convenisset, matres familiae, quae paulo ante Romanis de muro manus tendebant, suos obtestari et more Gallico {{passum}} capillum ostentare liberosque in conspectum proferre coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"passus","latin":"passus, passūs","headword":"passus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pace; pace, step","forms":["passa","passī","passibus","passis","passus","passuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium {{passuum}} circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pastio","latin":"pāstiō, -ōnis ( f.)","headword":"pāstiō","letter":"p","pos":"","posGroup":"other","english":"pasturage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pastor","latin":"pāstor, pāstōris","headword":"pāstor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) shepherd","forms":["pāstor","pāstōre","pāstōrem","pāstōrēs","pastōri","pāstōribus","pāstōris","pāstōrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Faustīnus, {{pāstor}} Iūliī, abest ab ovibus suīs, quia ovem nigram in silvā quaerit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pastoralis","latin":"pastoralis, pastoralis, pastorale","headword":"pastoralis","letter":"p","pos":"adjective","posGroup":"adjective","english":"pastoral","forms":["pāstōrālem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sūmpsit autem pēram {{pāstōrālem}}, quā illī cōnsuēverat, et fundam cum quīnque lapidibus in sacculō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"patefacere","latin":"(patefaciō) patefacere (< facere)","headword":"patefacere","letter":"p","pos":"","posGroup":"other","english":"open, reveal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"patefacio","latin":"patefacio, patefacere, patefeci, patefactus","headword":"patefacio","letter":"p","pos":"verb","posGroup":"verb","english":"reveal/uncover/disclose/expose; bring to light; make known/visible; dissect","forms":["patefacere","patefaceret","patefacit","patefacta","patefactam","patefactis","patefactō","patefēcerat","patefēcērunt","patefēcit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis {{patefactis}} summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"patefio","latin":"patefio, patefere, patefactus sum","headword":"patefio","letter":"p","pos":"verb","posGroup":"verb","english":"be made known/opened/revealed/uncovered/disclosed/exposed; (patefacio PASS)","forms":["patefierent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cassius, quī tum praetor erat, ad Iugurtham mitterētur eumque, datā fidē pūblicā, Rōmam dūceret, ut eius indiciō {{patefierent}} dēlicta eōrum et reliquōrum quī pecūniae acceptae accūsābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"patens","latin":"patens, patentis (gen.), patentior -or -us, patentissimus -a -um","headword":"patens","letter":"p","pos":"adjective","posGroup":"adjective","english":"open, accessible","forms":["patēns","patentiorēm","patentioribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hostes re nova perterriti, muro turribusque deiecti in foro ac locis {{patentioribus}} cuneatim constiterunt, hoc animo ut, si qua ex parte obviam contra veniretur, acie instructa depugnarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pateo","latin":"pateō, -ēre, patuī","headword":"pateō","letter":"p","pos":"verb","posGroup":"verb","english":"lie open, be disclosed, be revealed","forms":["pateat","patēbant","patebat","patēbit","patēbunt","patent","patente","patentibus","patentīs","patere","paterentur","paterer","pateret","paterētur","paterīs","patet","patuerant","patuerat","patuērunt","patuisset","patuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae {{patuerant}}, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pater","latin":"pater","headword":"pater","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) father","forms":["pater","patre","patrem","patrēs","patrī","patribus","patris","patrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius {{pater}} principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"patera","latin":"patera, -ae","headword":"patera","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"bowl; libation-bowl","forms":["paterā","pateram"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post ob virtūtem erō Amphitryōnī paterā dōnātā aurea est,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"patere","latin":"(pateō) patēre","headword":"patēre","letter":"p","pos":"","posGroup":"other","english":"(intr.) lie open","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"paterfamilias","latin":"paterfamiliās","headword":"paterfamiliās","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"head of the household","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"paternus","latin":"paternus, -a, -um","headword":"paternus","letter":"p","pos":"adjective","posGroup":"adjective","english":"paternal; of a father, paternal","forms":["paternā","paternae","paternī","paternīs","paternō","paternōs","paternum","paternus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deus fēcit foedus cum illō hīs verbīs: exī ē domō paternā, dēsere patriam, et pete regiōnem quam datūrus sum posterīs tuīs: augēbō tē prōle numerōsā; eris pater multārum gentium, ac per tē omnēs orbis nātiōnēs erunt bonīs cumulātae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"patescere","latin":"(patēscō) patēscere, patuisse","headword":"patēscere","letter":"p","pos":"","posGroup":"other","english":"be laid open, extend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"patesco","latin":"patesco, patescere, patui, -","headword":"patesco","letter":"p","pos":"verb","posGroup":"verb","english":"be opened/open/revealed; become clear/known; open; extend, spread","forms":["patescit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Via tantum interest perangusta, deinde paulō lātior {{patescit}} campus, inde collēs assurgunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pati","latin":"(patior) patī, passum","headword":"patī","letter":"p","pos":"verb","posGroup":"verb","english":"suffer, permit, allow; to endure, suffer; to allow, suffer, permit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"patiens","latin":"patiēns","headword":"patiēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"(gen. patientis) enduring, patient; patient","forms":["patiēns","patiente","patientior"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum vērō iam procul sōlis lūcem aspiceret, neque ūllum sonum post sē audīret, dubitāns an Eurydicē sē sequerētur, tantō metū captus est, ut iam dēsīderium uxōris rūrsus videndī, quō ārdēbat, retinēre nōn posset: cōnstitit igitur nōn iam {{patiēns}} morae, et ferē sub ipsā lūce, amōre victus, rēs pexit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"patienter","latin":"patienter, patientius, patientissime","headword":"patienter","letter":"p","pos":"adverb","posGroup":"adverb","english":"patiently; with patience/toleration","forms":["patienter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Qui se ultro morti offerant facilius reperiuntur quam qui dolorem {{patienter}} ferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"patientia","latin":"patientia, -ae","headword":"patientia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"patience","forms":["patientia","patientiae","patientiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At Dāvīd eōs cohibuit: “Sinite” inquit “istum mihi maledīcere; forsitan Deus, hīs quae patior malīs plācātus, meī miserēbitur, et meum dolōrem respiciet.” Incrēdibilem rēgis {{patientiam}} admīrātī, comitēs dictō aegrē pāruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"patior","latin":"patior, -ī, passus sum","headword":"patior","letter":"p","pos":"verb","posGroup":"verb","english":"to suffer, endure, allow","forms":["passū","passūrum","patī","patiar","patiāris","patiatur","patiēbantur","patiēminī","patiēmur","patienda","patiendī","patiēre","patiēris","patimur","patior","patitur","patiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Simul in spem veniebant eius adfirmatione de reliquis adiungendis civitatibus; primumque eo tempore Galli castra munire instituerunt; et sic sunt animo consternati homines insueti laboris ut omnia quae imperarentur sibi {{patienda}} existimarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"patrare","latin":"(patrō) patrāre","headword":"patrāre","letter":"p","pos":"","posGroup":"other","english":"achieve, carry through","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"patres conscripti","latin":"patrēs cōnscrīptī","headword":"patrēs cōnscrīptī","letter":"p","pos":"","posGroup":"other","english":"senators","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"patria","latin":"patria, -ae","headword":"patria","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"native country/town; homeland, fatherland; fatherland","forms":["patria","patriae","patriam","patriās","patriīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mēdus: “Vērum dīcis: necesse est nōs simul in {{patriam}} nostrum redīre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"patricius","latin":"patricius, patricii","headword":"patricius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"patrician; aristocrat","forms":["patriciae","patriciī","patriciīs","patriciō","patriciōs","patricius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Aedēs Concordiae antīqua eō tempore aedificāta esse dīcitur cum post longam discordiam, quae populum Rōmānum dīvīserat in duās factiōnēs inter sē inimīcissimās, {{patriciōs}} et plēbēiōs, tandem concordia omnium collāpsam in meliōrem faciem restituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"patrimonium","latin":"patrimōnium, -ī","headword":"patrimōnium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"patrimony, fortune; inherited property, patrimony","forms":["patrimōniō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed Tarquiniō Collātīnō statim sublāta est dignitās; placuerat enim 'nē quisquam in urbe manēret quī Tarquinius vocārētur.' Ergō acceptō omnī patrimōniō suō ex urbe migrāvit, et locō ipsīus factus est P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"patrius","latin":"patrius, -a, -um","headword":"patrius","letter":"p","pos":"adjective","posGroup":"adjective","english":"of the father, paternal; paternal, ancestral","forms":["patriī","patriō","patriōrum","patriōs","patrius"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc dē mōre patriō cum Iovī sacra parāvissent, ut āra accēnsīs ignibus incanduit, Danai dracōnem in arbore vīdēre quae proxima ārīs sacrīs stābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"patro","latin":"patro, patrare, patravi, patratus","headword":"patro","letter":"p","pos":"verb","posGroup":"verb","english":"accomplish, bring to completion","forms":["patrātīs","patrātum","patrāvisse","patrāvissent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Iugurtha, {{patrātīs}} cōnsiliīs, postquam omnis Numidiae potiēbātur, in ōtiō facinus suum cum animō reputāns, timēre populum Rōmānum neque adversus īram eius usquam, nisi in avāritiā nōbilitātis et pecūniā suā, spem habēre.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"patrocinium","latin":"patrōcinium, -ī (n.)","headword":"patrōcinium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"protection, defense; legal defence, patronage","forms":["patrōciniō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Roscium parricīdiī reum clārissimā ōrātiōne dēfendit, eōque patrōciniō maximam laudem meruit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"patronus","latin":"patrōnus, -ī (m.)","headword":"patrōnus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"patron, leader, advocate","forms":["patrōnīs","patronos","patrōnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Litaviccus cum suis clientibus, quibus more Gallorum nefas est etiam in extrema fortuna deserere {{patronos}}, Gergoviam profugit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"patruus","latin":"patruus, -ī","headword":"patruus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"father’s brother, uncle; paternal uncle","forms":["patruo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prohibetur ab Gobannitione, {{patruo}} suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pauci","latin":"paucī, -ae, -a","headword":"paucī","letter":"p","pos":"adjective","posGroup":"adjective","english":"(pl.) few, a few; few","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"paucitas","latin":"paucitās, -ātis ( f.)","headword":"paucitās","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"small number, paucity; fewness, small number","forms":["paucitās","paucitāte","paucitatem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius indicio vocati, huic habendam gratiam, quod et {{paucitatem}} eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paucum","latin":"paucum, pauci","headword":"paucum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"only a small/an indefinite number of/few things (pl.), a few words/points","forms":["pauca"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In Arabiā nōn multī, sed paucī fluviī sunt et {{pauca}} oppida.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"paucus","latin":"paucus, pauci","headword":"paucus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"only a small/an indefinite number of people (pl.), few; a few; a select few","forms":["paucae","paucārum","paucās","pauci","pauciōrēs","paucis","paucissima","paucissimī","paucōrum","paucos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, {{paucos}} dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paulatim","latin":"paulātim","headword":"paulātim","letter":"p","pos":"adverb","posGroup":"adverb","english":"little by little, gradually","forms":["paulatim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, viritim distribuit; frumentum parce et {{paulatim}} metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paulisper","latin":"paulisper","headword":"paulisper","letter":"p","pos":"adverb","posGroup":"adverb","english":"for a short time","forms":["paulisper"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Animi est ista mollitia, non virtus, {{paulisper}} inopiam ferre non posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paullum","latin":"paullum, paulli","headword":"paullum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"little/small; (only a) small amount/quantity/extent; little bit/while; trifle","forms":["Paullī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō exemplō patris suī, Aemiliī Paullī, quī Macedoniam vīcerat, lūdōs fēcit transfugāsque ac fugitīvōs bēstiīs obiēcit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"paulo","latin":"paulo","headword":"paulo","letter":"p","pos":"adverb","posGroup":"adverb","english":"by a little; by only a small amount; a little; somewhat","forms":["paulo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus {{paulo}} ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paululum","latin":"paululum","headword":"paululum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"a little","forms":["paululum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Exonerātā vésîca 111ē vëslcā aquam poposclt ad æ manûs, digitôsque {{paululum}} ad- ‘ÊSÜWH spersôs in capite puerî tersit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"paulum","latin":"paulum, -ī","headword":"paulum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"a little (also, adv.); a little, little","forms":["Paulā","Paulī","paulum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Legionem unam eodem iugo mittit et {{paulum}} progressam inferiore constituit loco silvisque occultat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"paulus","latin":"paulus, paula, paulum","headword":"paulus","letter":"p","pos":"adjective","posGroup":"adjective","english":"little; small; (only a) small amount/quantity of/little bit of","forms":["Paulam","Paulus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aemiliae est ūnus frāter, cui 'Aemilius' nōmen est (praenōmen 'Pūblius', cognōmen '{{Paulus}}').","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pauper","latin":"pauper","headword":"pauper","letter":"p","pos":"adjective","posGroup":"adjective","english":"(gen.pauperis) poor","forms":["pauper","pauperem","pauperēs","pauperī","pauperibus","pauperiōrēs","pauperis","pauperrima","pauperrimō","pauperrimus","pauperum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iānitor: “Quis est iste dominus {{pauper}} cui ūnus servus est?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"paupertas","latin":"paupertas, paupertatis","headword":"paupertas","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"poverty, need; humble circumstances","forms":["paupertās","paupertātem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ac mihi multa agitantī cōnstābat paucōrum cīvium ēgregiam virtūtem cūncta patrāvisse, eōque factum utī dīvitiās {{paupertās}}, multitūdinem paucitās superāret.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"paveo","latin":"paveo, pavere, pavi, -","headword":"paveo","letter":"p","pos":"verb","posGroup":"verb","english":"be frightened or terrified at","forms":["pavē","pavēns","paventīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Convocat Ātrīdēs sociōs terrōre {{paventīs}}: nec Tēlamōniadēs etiamnunc hiscere quicquam audet. ...","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pavere","latin":"(paveō) pavēre, pavisse","headword":"pavēre","letter":"p","pos":"","posGroup":"other","english":"be terrified","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pavidus","latin":"pavidus, -a, -um","headword":"pavidus","letter":"p","pos":"adjective","posGroup":"adjective","english":"terrified; frightened, timid","forms":["pavidā","pavidae","pavidam","pavidē","pavidīs","pavidō","pavidum","pavidus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Pācifer huic dederat flōrem Mercurius album:\nmōly vocant superī, nigrā rādīce tenētur;\ntūtus eō monitīsque simul caelestibus intrat\nille domum Circēs et ad īnsidiōsa vocātus\npōcula cōnantem virgā mulcēre capillōs\nreppulit et strictō {{pavidam}} dēterruit ēnse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pavo","latin":"pavo, pavonis","headword":"pavo","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"peacock","forms":["pāvō","pāvōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hoc cum prīmum Iūnō cognōvit, oculōs Argī in caudā et in pennīs {{pāvōnis}}, avis suae, posuit, ubi adhūc vidērī possunt, Vaccam autem, quam Iūnō causam mortis Argī esse putāvit, per omnēs terrās ēgit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pavor","latin":"pavor, -ōris (m.)","headword":"pavor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"trembling with fear; fear, panic; panic, dread","forms":["pavor","pavōre","pavōrī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"... {{pavor}} occupat illum, ante oculōsque natant tenebrae retrōque ferentī āversōs passūs mediō lapis obstitit arvō; quem super impulsum resupīnō corpore Cygnum vī multā vertit terraeque affīxit Achillēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pax","latin":"pāx, pācis","headword":"pāx","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) peace","forms":["pace","pācem","pacis","pāx"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eo cum Eporedorix Viridomarusque venissent et de statu civitatis cognovissent, Litaviccum Bibracte ab Aeduis receptum, quod est oppidum apud eos maximae auctoritatis, Convictolitavem magistratum magnamque partem senatus ad eum convenisse, legatos ad Vercingetorigem de {{pace}} et amicitia concilianda publice missos, non praetermittendum tantum commodum existimaverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"peccare","latin":"(peccō) peccāre","headword":"peccāre","letter":"p","pos":"verb","posGroup":"verb","english":"do wrong; to sin, make a mistake, err","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"peccator","latin":"peccator, peccatoris","headword":"peccator","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"sinner; transgressor","forms":["peccātor","peccātōrem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Vocāvērunt ergō rūrsus hominem quī fuerat caecus, et dīxērunt eī:\"Dā glōriam Deō: nōs scīmus {{peccātōrem}} esse hominem ill um.\"Respondit ill ē:\"Sī peccātor est, nesciō; ūnum sciō: mē, cum caecus fuerim, nunc vidēre.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"peccatum","latin":"peccātum, -ī","headword":"peccātum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"error, offense","forms":["peccāta","peccātī","peccātō","peccātōrum","peccātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sī rēctē faciēs, recipiēs mercēdem; sīn autem male, luēs poenam peccātī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pecco","latin":"pecco, peccare, peccavi, peccatus","headword":"pecco","letter":"p","pos":"verb","posGroup":"verb","english":"sin; do wrong, commit moral offense; blunder, stumble; be wrong","forms":["peccandī","peccandum","peccantēs","peccāre","peccāris","peccat","Peccāveram","peccāvērunt","peccavī","peccāvimus","peccāvisset","peccāvit","peccent","peccēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Varia deinceps fuit Hebraeōrum fortūna prō variīs eōrum mōribus: iī saepe in Deum {{peccāvērunt}}; tunc dīvīnō praesidiō dēstitūtī ab hostibus superābantur; quotiēs ad Deum conversī eius auxilium implōrāvērunt, plācātus Deus eōs līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pecto","latin":"pecto, pectere, pexi, pectitus","headword":"pecto","letter":"p","pos":"verb","posGroup":"verb","english":"comb; card (wool, etc)","forms":["pectendōs","pectēns","pectere","pexit","pexum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cum vērō iam procul sōlis lūcem aspiceret, neque ūllum sonum post sē audīret, dubitāns an Eurydicē sē sequerētur, tantō metū captus est, ut iam dēsīderium uxōris rūrsus videndī, quō ārdēbat, retinēre nōn posset: cōnstitit igitur nōn iam patiēns morae, et ferē sub ipsā lūce, amōre victus, rēs {{pexit}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pectus","latin":"pectus, pectoris","headword":"pectus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(n.) chest; chest, breast; breast, heart","forms":["pectora","pectore","pectoribus","pectoris","pectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Matres familiae de muro vestem argentumque iactabant, et {{pectore}} nudo prominentes passis manibus obtestabantur Romanos ut sibi parcerent neu, sicut Avarici fecissent, ne a mulieribus quidem atque infantibus abstinerent; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pecua","latin":"pecua, -um (n. pl.)2","headword":"pecua","letter":"p","pos":"","posGroup":"other","english":"farm animals","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"peculatus","latin":"peculātus, -ūs","headword":"peculātus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"embezzlement","forms":["pecūlātūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Scīpiō Asiāticus, frāter Āfricānī, {{pecūlātūs}} accūsātus damnātusque cum in vincula et carcerem dūcerētur, Ti.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"peculium","latin":"pecūlium, -ī","headword":"pecūlium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"money (given to slaves), “slave stipend”; savings, private property","forms":["pecūliī","pecūlium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Num dominus ille sevērus, quī tibi imperābat ut opus sordidum facerēs, tantum {{pecūlium}} tibi dabat prō opere sordidō?\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pecunia","latin":"pecūnia, -ae","headword":"pecūnia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"money","forms":["pecunia","pecūniae","pecuniam","pecūniārum","pecunias"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, sollicitatus ab Arvernis {{pecunia}} cum quibusdam adulescentibus colloquitur; quorum erat princeps Litaviccus atque eius fratres amplissima familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pecuniarius","latin":"pecuniarius, pecuniaria, pecuniarium","headword":"pecuniarius","letter":"p","pos":"adjective","posGroup":"adjective","english":"of money, pecuniary","forms":["pecūniāria"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quōmodo habēs?” [Gāius:] “Grātulor tibi — sīcut mihi.” [Lūcius:] “Vocātus sum in iūdicium.” [Gāius:] “Quālis est ipsa rēs?” [Lūcius:] “Nōn valdē magna, est enim {{pecūniāria}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pecuniosus","latin":"pecūniōsus, -a, -um","headword":"pecūniōsus","letter":"p","pos":"adjective","posGroup":"adjective","english":"wealthy; rich, wealthy","forms":["pecūniōsa","pecūniōsī","pecūniōsō","pecūniōsōs","pecūniōsum","pecūniōsus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Quia pater tuus nōn tam {{pecūniōsus}} est quam pater Mārcī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pecus","latin":"pecus, pecoris","headword":"pecus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(n.) livestock, cattle; farm animal, sheep; cattle, flock; herd, cattle; beast","forms":["pecora","pecore","pecoris","pecorum","pecudēs","pecudum","pecus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et {{pecore}} ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pedes","latin":"pedes, peditis","headword":"pedes","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) footsoldier; foot-soldier","forms":["pedes","pedites","peditibus","peditis","peditum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad {{pedes}} Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pedester","latin":"pedester, -tris, -tre","headword":"pedester","letter":"p","pos":"adjective","posGroup":"adjective","english":"pedestrian, infantry","forms":["pedestre","pedestrī","pedestribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tandem Germani ab dextro latere summum iugum nacti hostes loco depellunt; fugientes usque ad flumen, ubi Vercingetorix cum {{pedestribus}} copiis consederat, persequuntur compluresque interficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"peditatus","latin":"peditatus, peditatus","headword":"peditatus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"infantry","forms":["peditatu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Laborantibus nostris Caesar Germanos summittit legionesque pro castris constituit, ne qua subito irruptio ab hostium {{peditatu}} fiat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pedum","latin":"pedum, pedi","headword":"pedum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"shepherd's crook","forms":["pedum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem {{pedum}} atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"peior","latin":"pēior, pēius","headword":"pēior","letter":"p","pos":"adjective","posGroup":"adjective","english":"worse","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pelagus","latin":"pelagus, pelagi","headword":"pelagus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"sea; the open sea, the main; (-us neuter, only sing.)","forms":["pelagī","pelagō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nōn illī imperium pelagī saevumque tridentem,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pelasgus","latin":"Pelasgus, Pelasgi","headword":"Pelasgus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"ancient Greek","forms":["Pelasgī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Augur “Vincēmus” ait “Pelasgī; gaudēte!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pelias","latin":"Pelias, -ae","headword":"Pelias","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pelias (usurper king of Thessaly)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"pellego","latin":"pellego, pellegere, pellegi, pellectus","headword":"pellego","letter":"p","pos":"verb","posGroup":"verb","english":"read over/through (silent/aloud); scan, survey, run one's eyes over; recount","forms":["pellectus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"ēgregiā puerī fōrmā {{pellectus}} honestī,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pellere","latin":"(pellō) pellere, pepulisse, pulsum","headword":"pellere","letter":"p","pos":"verb","posGroup":"verb","english":"strike, drive out; to drive (out)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pellicio","latin":"pellicio, pellicere, pellexi, pellectus","headword":"pellicio","letter":"p","pos":"verb","posGroup":"verb","english":"attract/draw away; allure/seduce/entice/captivate; coax/induce/wheedle/win over","forms":["pelliciēbat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus erat īnsignī et pulchra faciē: uxor Putiphāris eum {{pelliciēbat}} ad flāgitium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pellis","latin":"pellis, pellis","headword":"pellis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"skin, hide; pelt","forms":["pellem","pellibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deinde induit Iacobum vestibus frātris; aptāvit {{pellem}} haedī manibus eius et collō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pello","latin":"pellō, -ere, pepulī, pulsum","headword":"pellō","letter":"p","pos":"verb","posGroup":"verb","english":"drive, push","forms":["Pellam","pellant","pellat","pelle","pellēbantur","pellēns","pellere","pellerentur","pellerētur","pellēs","pellit","pelluntur","pepulerat","pepulisse","pepulit","pulsā","pulsās","pulsi","pulsīs","pulsōs","pulsū","pulsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi septima legio constiterat, hostes {{pelluntur}} atque in fugam coiciuntur; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pelta","latin":"pelta, peltae","headword":"pelta","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"crescent-shaped shield","forms":["peltīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dūcit Amāzonidum lūnātīs agmina {{peltīs}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pelvis","latin":"pelvis, pelvis","headword":"pelvis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"shallow bowl or basin","forms":["pēlve"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cônstemätî nôs însolentiä ëbriôrum intentāvī- que ē gastñs lābentia, quae collēcta puer lance circum- Hās lautitiās aequāvit ingeniôsus cocus: in crätîculä enim argenteā cochleâs attulit et tremulā taeterrimāque Pudet referre quae secuntur: inaudîtô enim môre puerî capillätî attulērunt unguentum in argenteā {{pēlve}} pedësque recumbentium ūnxērunt, cum ante crūra tälôsque corônîs vînxissent.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"penas","latin":"Penas, Penatis","headword":"Penas","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Penates; (usu. pl.); gods of home/larder/family; home/dwelling; family/line","forms":["Penātēs","Penātibus","penātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille graviter gemēns Aenēam monuit ut deōs {{Penātēs}} urbis Trōiae caperet atque ex urbe incēnsā fugeret: \"Heu, fuge, nāte deā, tēque hīs ēripe flammīs!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pendeo","latin":"pendeō, -ēre, pependī, pēnsum","headword":"pendeō","letter":"p","pos":"verb","posGroup":"verb","english":"hang","forms":["Pendē","pendeat","pendēbant","pendēbat","pendēbātis","pendēns","pendent","pendentem","pendentibus","pendēre","penderētur","pendet","pependī","pependissent","pependit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fēcit Moysēs quod iusserat Deus: cum tenēret manum extēnsam super mare, aquae dīvīsae sunt, et intumēscentēs hinc et inde {{pendēbant}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pendere","latin":"(pendeō) pendēre, pependisse","headword":"pendēre","letter":"p","pos":"","posGroup":"other","english":"hang; weigh, pay pensum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"penelope","latin":"Penelopē, -ae","headword":"Penelopē","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Penelope, wife of Ulysses","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"penes","latin":"penes","headword":"penes","letter":"p","pos":"preposition","posGroup":"preposition","english":"in the possession of","forms":["penes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Statuunt ut X milia hominum delecta ex omnibus copiis in oppidum mittantur, nec solis Biturigibus communem salutem committendam censent, quod {{penes}} eos, si id oppidum retinuissent, summam victoriae constare intellegebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"penetrale","latin":"penetrale, penetralis","headword":"penetrale","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"inner part of a place; inner shrine; sanctuary of the household gods","forms":["penetrāle","penetrālī","penetrālia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīs licet īnfestus sociīs rēgīque mihique, dūre Philoctēte, licet exsecrēre meumque dēvoveās sine fīne caput cupiāsque dolentī mē tibi forte darī nostrumque haurīre cruōrem, tē tamen adgrediar mēcumque redūcere nītar tamque tuīs potiar (faveat Fortūna) sagittīs, quam sum Dardaniō, quem cēpī, vāte potītus, quam respōnsa deum Trōiānaque fāta retēxī, quam rapuī Phrygiae signum {{penetrāle}} Minervae hostibus ē mediīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"penetralia","latin":"penetrālia, -ium (n. pl.)","headword":"penetrālia","letter":"p","pos":"","posGroup":"other","english":"the interior","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"penetrare","latin":"(penētrō) penētrāre","headword":"penētrāre","letter":"p","pos":"","posGroup":"other","english":"penetrate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"penetro","latin":"penetro, penetrare, penetravi, penetratus","headword":"penetro","letter":"p","pos":"verb","posGroup":"verb","english":"enter, penetrate","forms":["penetrant","penetrat","penetrāvisse","penetrāvit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quō nōn ars {{penetrat}}?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"peniculus","latin":"peniculus, peniculi","headword":"peniculus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"brush (of ox/horse tail); painter's brush; sponge; diminutive of penis (L+S)","forms":["pēniculō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"(dé-)fricāre -uisse — tergere pēniculō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"penitus","latin":"penitus","headword":"penitus","letter":"p","pos":"adjective","posGroup":"adjective","english":"from within, deep, far","forms":["penitus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ut vērō summō dēspexit ab aethere terrās īnfēlīx Phaethōn {{penitus}} penitusque iacentēs, palluit et subitō genua intremuēre timōre suntque oculīs tenebrae per tantum lūmen obortae, et iam māllet equōs numquam tetigisse paternōs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"penna","latin":"penna, -ae","headword":"penna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"feather, wing; feather","forms":["pennā","pennae","pennārum","pennās","pennīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tū hoc voluistī!” Avem igitur pūnīre cōnstituit: itaque albās eius {{pennās}} in nigrās convertit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pennatus","latin":"pennātus, -a, -um","headword":"pennātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"winged","forms":["pennātīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Neque enim frūstrā stellae micant neque frūstrā currus dracōnibus {{pennātīs}} tractus adest.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pensare","latin":"(pēnsō) pēnsāre","headword":"pēnsāre","letter":"p","pos":"","posGroup":"other","english":"weigh, ponder, consider","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pensio","latin":"pēnsiō, -ōnis ( f.)","headword":"pēnsiō","letter":"p","pos":"","posGroup":"other","english":"payment, installment","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pensitare","latin":"(pēnsitō) pēnsitāre","headword":"pēnsitāre","letter":"p","pos":"","posGroup":"other","english":"pay","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"penso","latin":"penso, pensare, pensavi, pensatus","headword":"penso","letter":"p","pos":"verb","posGroup":"verb","english":"weigh (out); pay/punish for; counterbalance, compensate; ponder, examine","forms":["pēnsandum","pensās","pēnset"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc tamen ūtilitās populī frāterque datī summa movet sceptrī, laudem ut cum sanguine {{pēnset}}; mittor et ad mātrem, quae nōn hortanda, sed astū dēcipienda fuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pensum","latin":"pēnsum, -ī","headword":"pēnsum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"task; exercise, task","forms":["pēnsa","pēnsī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"In dē- mentô levātum in tribūnal excelsum Mercurius rapiēbat. cornū abundantī et très Parcae aurea {{pēnsa}} torquentēs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pentameter","latin":"pentameter, pentametrī","headword":"pentameter","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"having five metrical feet; pentameter (five-foot verse)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"penum","latin":"penum, peni","headword":"penum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"provisions, food; stock of household; storeroom in temple of Vesta","forms":["penum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cūra {{penum}} struere, et flammīs adolēre Penātīs;","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"penuria","latin":"pēnūria, -ae","headword":"pēnūria","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"scarcity, want; want, scarcity","forms":["pēnūriā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Scīpiōnī, summō virō, placuisse; ob eāsdem artēs ā Micipsā, nōn pēnūriā līberōrum, in rēgnum adoptātum esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"per","latin":"per","headword":"per","letter":"p","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) through, by, during; through (with acc.)","forms":["per"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore {{per}} agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"per vicem","latin":"per vicem","headword":"per vicem","letter":"p","pos":"","posGroup":"other","english":"by turns, one after another","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pera","latin":"pera, perae","headword":"pera","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"satchel; bag slung over shoulder (for day's provisions); (affected by Cynics)","forms":["perae","pēram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sūmpsit autem {{pēram}} pāstōrālem, quā illī cōnsuēverat, et fundam cum quīnque lapidibus in sacculō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"peragere","latin":"(peragō) peragere (< agere)","headword":"peragere","letter":"p","pos":"","posGroup":"other","english":"carry out, complete","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perago","latin":"perago, peragere, peregi, peractus","headword":"perago","letter":"p","pos":"verb","posGroup":"verb","english":"disturb; finish; kill; carry through to the end, complete","forms":["perāctīs","perāctō","perāctum","peragat","peragēre","peragit","peragunt","perēgī","perēgit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Perāctō convīviō, Iōsēphus dat negōtium dispēnsātōrī ut saccōs eōrum impleat frūmentō, pecūniam simul repōnat, et īnsuper scyphum suum argenteum in saccō Beniamīnī recondat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"peragrare","latin":"(peragrō) peragrāre","headword":"peragrāre","letter":"p","pos":"","posGroup":"other","english":"travel over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"peragro","latin":"peragro, peragrare, peragravi, peragratus","headword":"peragro","letter":"p","pos":"verb","posGroup":"verb","english":"travel over every part of, scour","forms":["peragrat","peragrātā","peragrāvit","peragrō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Superfūdit deinde sē in Asiam et tredecim annīs quibus Alexander rēgnāvit prīmum omnia qua Persārum prope immēnsō spatiō imperium fuerat suae diciōnis fēcit; Arabās hinc Indiamque, quā terrārum ultimōs fīnēs Rubrum mare amplectitur, {{peragrāvit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perangustus","latin":"perangustus, -a, -um","headword":"perangustus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very narrow","forms":["perangusta","perangustum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et {{perangustum}} aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"peraro","latin":"peraro, perarare, peraravi, peraratus","headword":"peraro","letter":"p","pos":"verb","posGroup":"verb","english":"furrow; inscribe (scratch on a waxen tablet)","forms":["perarētur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ergō eat et blandīs {{perarētur}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"perblandus","latin":"perblandus, perblanda, perblandum","headword":"perblandus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very charming","forms":["perblanda"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posterō diē senātus frequēns datus Hannibalī; ubi prīma eius ōrātiō {{perblanda}} ac benigna fuit, quā grātiās ēgit Campānīs 'quod amīcitiam suam Rōmānae societātī praeposuissent', et inter cētera magnifica prōmissa pollicitus est 'brevī caput Ītaliae omnis Capuam fore!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perbrevis","latin":"perbrevis, -e","headword":"perbrevis","letter":"p","pos":"","posGroup":"other","english":"very short","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perceleriter","latin":"perceleriter","headword":"perceleriter","letter":"p","pos":"","posGroup":"other","english":"very quickly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"percellere","latin":"(percellō) percellere, -ulisse, -ulsum","headword":"percellere","letter":"p","pos":"","posGroup":"other","english":"strike (with fear)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"percello","latin":"percello, percellere, perculi, perculsus","headword":"percello","letter":"p","pos":"verb","posGroup":"verb","english":"strike down; strike; overpower; dismay, demoralize, upset","forms":["perculit","perculsa","perculsī","perculsīs","perculsōs","perculsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Metū perculsī Aegyptiī coepērunt fugere; at Deus dīxit Moȳsī: “Extende rūrsus dextram in mare, ut aquae revertantur in locum suum.” Pāruit Moysēs, et statim aquae refluentēs obruērunt Aegyptiōs, et eōrum currūs, et equitēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"percenseo","latin":"percenseo, percensere, percensui, percensitus","headword":"percenseo","letter":"p","pos":"verb","posGroup":"verb","english":"enumerate, recite from start to finish; inspect/examine/go over thoroughly","forms":["Percēnsuerat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quīnctius imperātor, Philippō rēge Macedonibusque dēvictīs, līberōs, immunēs, suīs lēgibus esse iubet Corinthiōs, Phocēnsēs, Locrensēsque omnēs et īnsulam Euboeam et Magnētas, Thessalōs, Perrhaebōs, Achaeōs Phthīōtās.' {{Percēnsuerat}} omnēs gentēs quae sub diciōne Philippī rēgis fuerant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"percensere","latin":"(percēnseō) percēnsēre, -cēnsuisse","headword":"percēnsēre","letter":"p","pos":"","posGroup":"other","english":"enumerate, survey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perceptio","latin":"perceptiō, -ōnis ( f.)","headword":"perceptiō","letter":"p","pos":"","posGroup":"other","english":"a gathering; perception","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"percipio","latin":"percipio, percipere, percepi, perceptus","headword":"percipio","letter":"p","pos":"verb","posGroup":"verb","english":"secure, gain; perceive, learn, feel","forms":["percipit","percipite"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"nam mihi horror membra miserō {{percipit}} dictīs tuīs.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"percitus","latin":"percitus, percita, percitum","headword":"percitus","letter":"p","pos":"adjective","posGroup":"adjective","english":"roused; excited; stirred up; propelled","forms":["percita","percitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ad impietātem accessit crūdēlitās: cum enim Isaliī s prophēta Īram dīvīnam illī dēnūntiāsset, rēx furōre {{percitus}} prophētam serrā ligneā secarī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"percontari","latin":"(percontōr) percontārī","headword":"percontārī","letter":"p","pos":"verb","posGroup":"verb","english":"inquire (about), ask; to ask, inquire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"percontatio","latin":"percontātiō, -ōnis ( f.)","headword":"percontātiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"interrogation, question; interrogation","forms":["percontātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prima percontātiō fuit 'quā subāctus iniūriā contrā populum Rōmānum bellum tam īnfestō animō suscēpisset, quō sē rēgnumque suum ad ultimum discrīmen addūceret?' Cum, respōnsum exspectantibus cūnctīs, terram intuēns diū tacitus flēret, rūrsus cōnsul:","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"percontor","latin":"percontor, percontari, percontatus sum","headword":"percontor","letter":"p","pos":"verb","posGroup":"verb","english":"inquire","forms":["percontandōs","percontantur","percontārier","percontāta","percontātus","percontēmur","percontor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quī respondērunt: vocēmus puellam, et {{percontēmur}} eius sententiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"percurrere","latin":"percurrere","headword":"percurrere","letter":"p","pos":"verb","posGroup":"verb","english":"to run through, traverse","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"percurrisse","latin":"(percurrō) percurrisse, percursum","headword":"percurrisse","letter":"p","pos":"","posGroup":"other","english":"run through","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"percurro","latin":"percurro, percurrere, percucurri, percursus","headword":"percurro","letter":"p","pos":"verb","posGroup":"verb","english":"quickly move/run/travel/hasten/pass through/over; form continuous line; stroke","forms":["percurrēbant","percurrendam","percurrere","percurrunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vix loquī dēsierat, cum puer rogāvit ut currūs, quō cotīdiē Sōl tōtum caelum ab ortū usque ad occāsum {{percurrere}} solēbat, sibi per ūnum diem regendus traderētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"percussus","latin":"percussus, percussus","headword":"percussus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"buffeting; beating","forms":["percussus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Deum ūnum timē, Deum intuēre, ā quō mercēdem recipiēs.\"Hīs verbīs cōnfirmātus, adulēscēns exclāmāvit:\"Nōn regī obsequor, sed legī.\"Tūne conversus ad Antiochum:\"Tū quid em, ō sceleste, Deī omnipotentis Īram nōn effugiēs: erit tempus cum, ab eō {{percussus}} et dolōre victus, tē hominem esse cōnfitēberis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"percutere","latin":"(percutiō) percutere, percussisse,  percussum","headword":"percutere","letter":"p","pos":"verb","posGroup":"verb","english":"strike, hit; to strike, knock, hammer","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"percutio","latin":"percutiō, -ere, -cussī, -cussum","headword":"percutiō","letter":"p","pos":"verb","posGroup":"verb","english":"to strike, pierce","forms":["percussa","percussae","percussērunt","percussisset","percussit","percussō","percussum","percutere","percuteret","percutiat","percutiēbat","percutiēns","percutit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Restituit praefectō pincernārum mūnus suum; alterum vērō sēcūrī {{percussum}} suspendit ad pālum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"perdere","latin":"(perdō) perdere, perdidisse,  perditum","headword":"perdere","letter":"p","pos":"verb","posGroup":"verb","english":"lose; to lose, destroy","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"perditus","latin":"perditus, perdita -um, perditior -or -us, perditissimus -a -um","headword":"perditus","letter":"p","pos":"adjective","posGroup":"adjective","english":"ruined; broken/debilitated; bankrupt, financially ruined; lost, done for","forms":["perditissimōrum","perditus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum dēnique interficiēre, cum iam nēmō tam improbus, tam {{perditus}}, tam tuī similis invenīrī poterit quī id nōn iūre factum esse fateātur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"perdo","latin":"perdō, -ere, perdidī, perditum","headword":"perdō","letter":"p","pos":"verb","posGroup":"verb","english":"destroy, ruin, lose","forms":["perdat","perdendum","perdere","perderet","perdēt","perdiderint","perdiderit","perdidērunt","perdidī","perdidisse","perdidisset","Perdidistī","perdidit","perdis","perdit","perditā","perditīs","perditorum","perditōs","perditum","perdundae","perdunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac {{perditorum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perdomare","latin":"(perdomō) perdomāre","headword":"perdomāre","letter":"p","pos":"","posGroup":"other","english":"subjugate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perdomo","latin":"perdomo, perdomare, perdomui, perdomitus","headword":"perdomo","letter":"p","pos":"verb","posGroup":"verb","english":"tame/subdue thoroughly, break in (animals); conquer/subjugate completely","forms":["perdomitīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quod cum esset negātum, bellum contrā eōs susceptum est et ingentī pugnā superātī sunt; ac dē iīs {{perdomitīs}} triumphātum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perduco","latin":"perduco, perducere, perduxi, perductus","headword":"perduco","letter":"p","pos":"verb","posGroup":"verb","english":"lead, guide; prolong; induce, conduct, bring through","forms":["perducit","perductōs","perducuntur","perduxerat","perduxerunt","perduxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam sententiam {{perducit}}; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perduellio","latin":"perduelliō, -ōnis ( f.)","headword":"perduelliō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"treason","forms":["perduelliōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx, nē ipse rem tam trīstem iūdicāret ac secundum iūdicium suppliciī auctor esset, cōnsiliō populī advocātō, \"Duumvirōs\" inquit, \"quī Horātiō {{perduelliōnem}} iūdicent, secundum lēgem faciō.\" Horrenda lēgis verba haec erant: \"Duumvirī perduelliōnem iūdicent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perduellis","latin":"perduellis, perduellis","headword":"perduellis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"national enemy; enemy; adherent of country with which one's own is at war","forms":["perduellēs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: '{{Perduellēs}} penetrant sē in fugam; ibi nostrīs animus additū'st.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"peregre","latin":"peregre","headword":"peregre","letter":"p","pos":"adverb","posGroup":"adverb","english":"to/from abroad","forms":["peregrē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"MERCVRIVS: Tūn' domō prohibēre peregrē mē advenientem postulās?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"peregrinans","latin":"peregrinans, peregrinantis","headword":"peregrinans","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pilgrim; (foreign) traveler; wanderer","forms":["peregrīnantēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed multī mortālēs, dēditī ventrī atque somnō, indoctī incultīque vītam sīcuti {{peregrīnantēs}} trānsiēre; quibus profectō contrā nātūram corpus voluptātī, animus onerī fuit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"peregrinator","latin":"peregrīnātor, -ōris","headword":"peregrīnātor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"stranger, traveller","forms":["peregrīnātōrēs","peregrīnātōribus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Hic latrō {{peregrīnātōribus}} imperāvit ut pedēs lavārent; sed cum hī sē inclīnābant ut ita facerent, ille eōs in mare ictū pedis dēmīsit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"peregrinor","latin":"peregrinor, peregrinari, peregrinatus sum","headword":"peregrinor","letter":"p","pos":"verb","posGroup":"verb","english":"travel about, be an alien, sojourn in strange country, go abroad, wander, roam","forms":["peregrīnātur"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deinde cāsū veniunt hospitēs hominī, quōs iste, dum splendidē {{peregrīnātur}}, invītārat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"peregrinus","latin":"peregrīnus, -a, -um","headword":"peregrīnus","letter":"p","pos":"adjective","posGroup":"adjective","english":"foreign, alien; foreign","forms":["peregrīnā","peregrīnī","peregrīnīs","peregrīnō","peregrīnum","peregrīnus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnique flūmine relicto caput in rīpā peregrīnā iacet quod serpēns ferus morsūrus est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"perennis","latin":"perennis, -e","headword":"perennis","letter":"p","pos":"adjective","posGroup":"adjective","english":"enduring, perpetual; perennial, eternal","forms":["perenne","perennis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum reversae sunt aquae in locum prīstinum; Iosue vērō duodecim lapidēs ē mediō amne sublātōs ērēxit, ut essent {{perenne}} reī monumentum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"perenno","latin":"perenno, perennare, perennavi, perennatus","headword":"perenno","letter":"p","pos":"verb","posGroup":"verb","english":"last many years","forms":["perennat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dēfuit ars vōbīs: artē {{perennat}} amor.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pereo","latin":"pereō, -īre, -iī, -itum","headword":"pereō","letter":"p","pos":"verb","posGroup":"verb","english":"die, perish","forms":["pereant","pereat","pereō","pereunt","pereuntem","peri","perībimus","perībit","perībunt","periēre","perīmus","perīre","perīrent","perīret","perit","perītō","perītum","peritūrae","peritūram","peritūrum","peritūrus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Malō animō id faciēbat rēx invidus: spērābat scīlicet iuvenem audācem facile {{peritūrum}}; at sua eum spēs dēlūsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pererrare","latin":"(pererrō) pererrāre","headword":"pererrāre","letter":"p","pos":"","posGroup":"other","english":"wander through","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pererro","latin":"pererro, pererrare, pererravi, pererratus","headword":"pererro","letter":"p","pos":"verb","posGroup":"verb","english":"wander through, roam or ramble over","forms":["pererrat","pererrātūrum","pererrō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tarquinī crēdidisse; quod sī apud eōs supplicibus locus nōn sit, {{pererrātūrum}} sē omne Latium, Volscōsque sē inde et Aequōs et Hernicōs petītūrum, donec ad eōs perveniat quī ā patrum crūdēlibus atque impiīs suppliciīs prōtegere līberōs sciant, et forsitan parātī sint ad bellum gerendum adversus superbissimum rēgem ac ferōcissimum populum!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perexiguus","latin":"perexiguus, -a, -um","headword":"perexiguus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very small","forms":["perexiguā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx cum perexiguā manū sēmiermium mīlitum Chalcidem sē recēpit; sub adventum cōnsulis ā Chalcide profectus Ephesum trānsmīsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perfectum","latin":"perfectum, -ī (tempus)","headword":"perfectum","letter":"p","pos":"","posGroup":"other","english":"perfect (tense)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"perfectus","latin":"perfectus, -a, -um","headword":"perfectus","letter":"p","pos":"adjective","posGroup":"adjective","english":"perfect","forms":["perfecta","perfectam","perfectis","perfectō","perfectum","perfectūs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His rebus {{perfectis}}, regiones secutus quam potuit aequissimas pro loci natura, XIIII milia passuum complexus pares eiusdem generis munitiones, diversas ab his, contra exteriorem hostem perfecit, ut ne magna quidem multitudine, si ita accidat, eius discessu munitionum praesidia circumfundi possent; ne autem cum periculo ex castris egredi cogatur, dierum XXX pabulum frumentumque habere omnes convectum iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perfero","latin":"perfero, perferre, pertuli, perlatus","headword":"perfero","letter":"p","pos":"verb","posGroup":"verb","english":"carry through; bear, endure to the end, suffer; announce","forms":["perfer","perferam","perferant","perferēmus","perferenda","perferre","perfertur","perferuntur","perlāta","perlātīs","pertulēre","pertulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eae res in Galliam Transalpinam celeriter {{perferuntur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perferre","latin":"(perferō) perferre, pertulisse, perlātum","headword":"perferre","letter":"p","pos":"","posGroup":"other","english":"carry through","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"perficere","latin":"(perficiō) perficere, perfēcisse, perfectum","headword":"perficere","letter":"p","pos":"verb","posGroup":"verb","english":"complete, accomplish; to complete, finish","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"perficio","latin":"perficio, perficere, perfeci, perfectus","headword":"perficio","letter":"p","pos":"verb","posGroup":"verb","english":"complete, finish; execute; bring about, accomplish; do thoroughly","forms":["perfēcerit","perfēcī","perfēcissent","perfecit","perfectūrus","perfice","perficere","perficiam","perficiantur","perficiendi","perficiendis","perficiendō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio deductis, cum se vel principes eius consili fore profiterentur, ratio {{perficiendi}} quaerebatur, quod civitatem temere ad suscipiendum bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perfidia","latin":"perfidia, -ae","headword":"perfidia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"faithlessness, treachery; treachery","forms":["perfidia","perfidiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum {{perfidiam}} veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perfidus","latin":"perfidus, -a, -um","headword":"perfidus","letter":"p","pos":"adjective","posGroup":"adjective","english":"faithless, treacherous; treacherous, faithless","forms":["perfide","perfidōs","perfidus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"{{Perfidus}} ille abiit!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"perflo","latin":"perflo, perflare, perflavi, perflatus","headword":"perflo","letter":"p","pos":"verb","posGroup":"verb","english":"blow through or over","forms":["perflant"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quā data porta, ruunt et terrās turbine {{perflant}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"perfringo","latin":"perfringo, perfringere, perfregi, perfractus","headword":"perfringo","letter":"p","pos":"verb","posGroup":"verb","english":"break through","forms":["perfregerint"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Utrisque ad animum occurrit unum esse illud tempus quo maxime contendi conveniat: Galli, nisi {{perfregerint}} munitiones, de omni salute desperant; Romani, si rem obtinuerint, finem laborum omnium exspectant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perfruor","latin":"perfruor, perfrui, perfructus sum","headword":"perfruor","letter":"p","pos":"verb","posGroup":"verb","english":"have full enjoyment of, enjoy","forms":["perfruere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hīc tū quā laetitiā {{perfruere}}, quibus gaudiīs exsultābis, quanta in voluptāte bacchābere, cum in tantō numerō tuōrum neque audiēs virum bonum quemquam neque vidēbis!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"perfuga","latin":"perfuga, -ae","headword":"perfuga","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"deserter","forms":["perfugās","perfugis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Admiratus quaerit ex {{perfugis}} causam, quorum magnus ad eum cotidie numerus confluebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perfugere","latin":"(perfugiō) perfugere (< fugere)","headword":"perfugere","letter":"p","pos":"","posGroup":"other","english":"take refuge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perfugio","latin":"perfugio, perfugere, perfugi, -","headword":"perfugio","letter":"p","pos":"verb","posGroup":"verb","english":"flee, desert; take refuge","forms":["perfūgerat","perfugere","perfugeret","perfūgērunt","perfūgit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eō ex fīnitimīs populīs quīlibet homō, sine discrīmine utrum līber an servus esset, {{perfugere}} poterat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perfugium","latin":"perfugium, -ī","headword":"perfugium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"place of refuge, shelter; refuge, shelter","forms":["perfugium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hiemis enim, nōn avāritiae {{perfugium}} maiōrēs nostrī in sociōrum atque amīcōrum tēctīs esse voluērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perfundere","latin":"(perfundō) perfundere (< fundere)","headword":"perfundere","letter":"p","pos":"","posGroup":"other","english":"wet, drench, imbue, fill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perfundo","latin":"perfundo, perfundere, perfudi, perfusus","headword":"perfundo","letter":"p","pos":"verb","posGroup":"verb","english":"pour over/through, wet, flood, bathe; overspread, coat, overlay; imbue","forms":["Perfūdī","perfūdit","Perfunde","perfundere","perfundit","perfūsus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tum in guttur ātrae ovis gladium cōnicit et fossam sanguine {{perfundit}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"perfungi","latin":"(perfungor) perfungī (< fungī)","headword":"perfungī","letter":"p","pos":"","posGroup":"other","english":"carry through, finish (+ abl.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perfungor","latin":"perfungor, perfungi, perfunctus sum","headword":"perfungor","letter":"p","pos":"verb","posGroup":"verb","english":"perform, discharge, have done with (w/ABL)","forms":["perfūncta","perfūnctus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nocte domum repetēns epulīs {{perfūncta}} redībit:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pergamenum","latin":"pergamenum, pergameni","headword":"pergamenum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"parchment; document","forms":["Pergamēnōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sīc Hannibal cōnsiliō arma {{Pergamēnōrum}} superāvit, neque tum sōlum, sed saepe aliās pedestribus cōpiīs parī prūdentiā pepulit adversāriōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pergamum","latin":"Pergamum, Pergami","headword":"Pergamum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"Pergamum; (citadel of Troy; city in Asia Minor)","forms":["Pergama","Pergamī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Illā nocte mihi Trōiae victōria parta est: {{Pergama}} tunc vīcī, cum vincī posse coēgī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pergere","latin":"pergere","headword":"pergere","letter":"p","pos":"verb","posGroup":"verb","english":"continue, go on; to continue, proceed","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pergo","latin":"pergō, pergere","headword":"pergō","letter":"p","pos":"verb","posGroup":"verb","english":"continue","forms":["pergam","pergās","perge","pergēbat","pergente","pergere","pergerent","pergeret","perget","pergit","pergunt","perrēxerīs","perrēxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Inter tonitrūs amīcī colloquī ac vīnum bibere {{pergunt}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pergratus","latin":"pergrātus, -a, -um","headword":"pergrātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very pleasing","forms":["pergrātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dein, cum essent perpauca inter sē ūnō aut alterō spatiō collocūtī Scīpiōnīque eōrum adventus periūcundus et {{pergrātus}} fuisset, placitum est ut in apricō maximē prātulō locō, quod erat hībernum tempus annī, cōnsīderent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pergula","latin":"pergula, pergulae","headword":"pergula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"attachment to front of building for trading, booth/stall/shop; painting studio","forms":["pergulā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"At înﬂat sē tam- quam rāna, et in sinum suum côn- quī in pergulā nâtus est aedēs nôn sonmiätilr.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"perhibeo","latin":"perhibeo, perhibere, perhibui, perhibitus","headword":"perhibeo","letter":"p","pos":"verb","posGroup":"verb","english":"present, give, bestow; regard, hold; name","forms":["perhibent","perhibētur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quō in locō cum esset silvestris bēluae sustentātus ūberibus pastōrēsque eum sustulissent et in agrēstī cultū labōreque aluissent, {{perhibētur}}, ut adolēverit, et corporis vīribus et animī ferōcitāte tantum cēterīs praestitisse ut omnēs quī tum eōs agrōs ubi hodiē est haec urbs incolēbant aequō animō illī libenterque pārērent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perhibere","latin":"(perhibeō) perhibēre (< habēre)","headword":"perhibēre","letter":"p","pos":"","posGroup":"other","english":"report, say","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perhumaniter","latin":"perhumaniter","headword":"perhumaniter","letter":"p","pos":"adverb","posGroup":"adverb","english":"very civilly","forms":["perhūmāniter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Gābelō cuidam egentī decem talenta, quibus ā rēge dōnātus erat, {{perhūmāniter}} commodāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"periclitor","latin":"periclitor, periclitari, periclitatus sum","headword":"periclitor","letter":"p","pos":"verb","posGroup":"verb","english":"try, prove, test, make a trial of, put to the test/in peril; risk, endanger","forms":["perīclitāminī","perīclitanda","periclitandum","perīclitantium","perīclitātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus rebus cognitis Caesar maturandum sibi censuit, si esset in perficiendis pontibus {{periclitandum}}, ut prius quam essent maiores eo coactae copiae dimicaret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"periclum","latin":"periclum, pericli","headword":"periclum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"danger, peril; trial, attempt; risk; responsibility for damage, liability","forms":["perīclī","perīclum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi cūria Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) nefandās, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"periculosus","latin":"perīculōsus, -a, -um","headword":"perīculōsus","letter":"p","pos":"adjective","posGroup":"adjective","english":"dangerous","forms":["perīculōsa","perīculōsam","perīculōsior","perīculōsīs","perīculōsissima","perīculōsissimī","periculosum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus comparatis, represso iam Lucterio et remoto, quod intrare intra praesidia {{periculosum}} putabat, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"periculum","latin":"perīculum, -ī","headword":"perīculum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"risk, danger; danger; danger, risk","forms":["perīcula","periculī","perīculīs","periculo","perīculōrum","periculum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis {{periculo}} Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perimere","latin":"(perimō) perimere (< emere)","headword":"perimere","letter":"p","pos":"","posGroup":"other","english":"destroy, kill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perimo","latin":"perimo, perimere, peremi, peremptus","headword":"perimo","letter":"p","pos":"verb","posGroup":"verb","english":"kill, destroy","forms":["perēmit","peremptōrum","perimī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Illum, quī ā sē Saūlem occīsum esse iactitābat, et rēgia īnsignia attulerat, perimī iussit, in poenam violātae māiestātis rēgiae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"perire","latin":"(pereō) perīre, periisse","headword":"perīre","letter":"p","pos":"verb","posGroup":"verb","english":"perish; to perish, be lost","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"periscelis","latin":"periscelis, periscelidos/is","headword":"periscelis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"garter, anklet, leg-band","forms":["periscelidēs","periscelis"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vënit ergô, galbinô succîncta cingillô, {{periscelis}} _ ita ut înfrä cerasina appārēret tunica et periscelidēs tortae phaecasiaeque inaurā- tae.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"peristylum","latin":"peristȳlum, -i","headword":"peristȳlum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"peristyle; peristyle, colonnaded garden court; peristyle, colonnaded court; peristyle, colonnade","forms":["peristȳla","peristȳlī","peristȳlō","peristȳlum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aemilia in peristȳlō est cum Iūliō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"perit","latin":"perit","headword":"perit","letter":"p","pos":"verb","posGroup":"verb","english":"perishes, is lost","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"peritus","latin":"perītus, -a, -um","headword":"perītus","letter":"p","pos":"adjective","posGroup":"adjective","english":"practiced, expert; skilled, skilful; skilled, expert","forms":["perīta","peritos","perītus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Bis magno cum detrimento repulsi Galli quid agant consulunt; locorum {{peritos}} adhibent; ex his superiorum castrorum situs munitionesque cognoscunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"periucundus","latin":"periūcundus, -a, -um","headword":"periūcundus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very agreeable","forms":["periūcundus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dein, cum essent perpauca inter sē ūnō aut alterō spatiō collocūtī Scīpiōnīque eōrum adventus {{periūcundus}} et pergrātus fuisset, placitum est ut in apricō maximē prātulō locō, quod erat hībernum tempus annī, cōnsīderent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"periurium","latin":"periurium, periuri(i)","headword":"periurium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"false oath, perjury","forms":["periūria"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"per-iūrium 41 — quod falsum iarātur Juppiter ex altō {{periūria}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"perlabor","latin":"perlabor, perlabi, perlapsus sum","headword":"perlabor","letter":"p","pos":"verb","posGroup":"verb","english":"glide along, over or through, skim","forms":["perlābitur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"atque rotīs summās levibus {{perlābitur}} undās.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"perlateo","latin":"perlateo, perlatere, perlatui, perlatitus","headword":"perlateo","letter":"p","pos":"verb","posGroup":"verb","english":"lie well hidden","forms":["perlatuisset"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"inque suà turrī {{perlatuisset}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"perlego","latin":"perlego, perlegere, perlegi, perlectus","headword":"perlego","letter":"p","pos":"verb","posGroup":"verb","english":"read over/through (silent/aloud); scan, survey, run one's eyes over; recount","forms":["perlēctā","perlēctīs","perlegentem","perlegitur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Igitur, {{perlēctīs}} litterīs, cum prius omnēs signa sua cognōvissent, senātus dēcernit utī abdicātō magistrātū Lentulus itemque cēterī in līberīs cūstōdiīs habeantur.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"perlustro","latin":"perlustro, perlustrare, perlustravi, perlustratus","headword":"perlustro","letter":"p","pos":"verb","posGroup":"verb","english":"go or wander all through; view all over, scan, scrutinize","forms":["perlūstrāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iōsēphus {{perlūstrāvit}} omnēs Aegyptī regiōnēs, et per septem annōs ūbertātis congessit maximam frūmentī cōpiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"permagnus","latin":"permagnus, -a, -um","headword":"permagnus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very large","forms":["permagnam","permagnum","permagnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qui Avarico expugnato refugerant, armandos vestiendosque curat; simul, ut deminutae copiae redintegrarentur, imperat certum numerum militum civitatibus, quem et quam ante diem in castra adduci velit, sagittariosque omnes, quorum erat {{permagnus}} numerus in Gallia, conquiri et ad se mitti iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"permaneo","latin":"permaneō, -ēre, permānsī","headword":"permaneō","letter":"p","pos":"verb","posGroup":"verb","english":"remain, persist","forms":["permanendum","permaneō","permanēre","permanet","permānsit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri defessis succederent nostrosque assiduo labore defatigarent, quibus propter magnitudinem castrorum perpetuo esset isdem in vallo {{permanendum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"permanere","latin":"(permaneō) permanēre (< manēre)","headword":"permanēre","letter":"p","pos":"","posGroup":"other","english":"remain, continue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"permisceo","latin":"permisceo, permiscere, permiscui, permixtus","headword":"permisceo","letter":"p","pos":"verb","posGroup":"verb","english":"mix or mingle together; confound; embroil; disturb thoroughly","forms":["permixtum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ad haec audienda cum {{permixtum}} senātuī esset populī concilium, repentē prīmōrēs, priusquam respōnsum darētur, argentum aurumque omne ex pūblicō prīvātōque in forum collātum in ignem coniciunt, eōdemque plērīque sēmet ipsī praecipitāvērunt!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"permiscere","latin":"(permisceō) permiscēre (< miscēre)","headword":"permiscēre","letter":"p","pos":"","posGroup":"other","english":"mix thoroughly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"permittere","latin":"(permittō) permittere, permīsisse ({i}intr. + dat.{/i})","headword":"permittere","letter":"p","pos":"","posGroup":"other","english":"allow, permit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"permitto","latin":"permitto, permittere, permisi, permissus","headword":"permitto","letter":"p","pos":"verb","posGroup":"verb","english":"let through; let go through; relinquish; permit, allow; entrust; hurl","forms":["permīsērunt","permīsit","permissa","permissū","permissum","permittat","permitte","permittendum","permittere","permitteret","permittī","permittis","permittit","Permittite","Permittitis","permittitur","permittunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Multitudinis suffragiis res {{permittitur}}; ad unum omnes Vercingetorigem probant imperatorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"permixtio","latin":"permixtiō, -ōnis ( f.)","headword":"permixtiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"mixture, disturbance, chaos","forms":["permixtiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam ubi prīmum ex nōbilitāte repertī sunt quī vēram glōriam iniūstae potentiae antepōnerent, movērī cīvitās et dissēnsiō cīvīlis quasi permixtiō terrae orīrī coepit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"permixtus","latin":"permixtus, permixta, permixtum","headword":"permixtus","letter":"p","pos":"adjective","posGroup":"adjective","english":"promiscuous; confused","forms":["permixti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Sic cum suis fugientibus {{permixti}}, quos non silvae montesque texerunt, ab equitatu sunt interfecti.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"permolestus","latin":"permolestus, -a, -um","headword":"permolestus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very troublesome","forms":["permolestum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Senātum vērō et populum ut ūnum habeāmus, et fierī potest, et {{permolestum}} est nisi fit, et secus esse scīmus, et vidēmus, sī id effectum sit, et melius nōs esse victūrōs et beātius.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"permoveo","latin":"permoveo, permovere, permovi, permotus","headword":"permoveo","letter":"p","pos":"verb","posGroup":"verb","english":"stir up; move deeply; influence; agitate","forms":["permōta","permōtī","permōtum","permotus","permoveantur","permovēbantur","permoveor","permoverentur","permovet","permōvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quorum ille precibus {{permotus}} castra ex Biturigibus movet in Arvernos versus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"permovere","latin":"(permoveō) permovēre,permōvisse,  permōtum","headword":"permovēre","letter":"p","pos":"verb","posGroup":"verb","english":"move deeply; to move deeply","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"permulti","latin":"permultī, -ae, -a","headword":"permultī","letter":"p","pos":"","posGroup":"other","english":"a great many","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"permultus","latin":"permultus, permulta, permultum","headword":"permultus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very much; very many (pl.)","forms":["permulta"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Habuit enim ille, sīcuti meminisse vōs arbitror, {{permulta}} maximārum nōn expressa signa sed adumbrāta virtūtum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"permunire","latin":"(permūniō) permūnīre","headword":"permūnīre","letter":"p","pos":"","posGroup":"other","english":"fortify","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"permutatio","latin":"permūtātiō, -ōnis ( f.)","headword":"permūtātiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"exchange","forms":["permūtātiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Post haec mala Carthāginiēnsēs Regulum ducem, quem cēperant, petīvērunt ut Rōmam proficīscerētur et pācem ā Rōmānīs obtinēret ac {{permūtātiōnem}} captīvōrum faceret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pernicies","latin":"perniciēs, -ēī","headword":"perniciēs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"destruction; destruction, ruin","forms":["perniciē","perniciem","perniciēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et duce Xanthippō, quī ā Lacedaemoniīs missus fuerat, Rōmānōrum dux Regulus victus est ultimā perniciē.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perniciosus","latin":"perniciōsus, -a, -um","headword":"perniciōsus","letter":"p","pos":"adjective","posGroup":"adjective","english":"destructive, disasterous; destructive, ruinous","forms":["perniciōsa","perniciōsam","perniciōsōs","perniciōsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Perniciōsum}} admodum hoc bellum fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pernix","latin":"pernix, (gen.), pernicis","headword":"pernix","letter":"p","pos":"adjective","posGroup":"adjective","english":"persistent, preserving; nimble, brisk, active, agile, quick, swift, fleet","forms":["pernīcibus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"prōgenuit pedibus celerem et {{pernīcibus}} ālīs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pernocto","latin":"pernocto, pernoctare, pernoctavi, pernoctatus","headword":"pernocto","letter":"p","pos":"verb","posGroup":"verb","english":"spend the night; occupy the night (w/person or in place); guard all night","forms":["pernoctātūrus","pernoctāvit","pernoctet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iter faciēns pervenit ad quemdam locum, ubi fessus dē viā {{pernoctāvit}}; supposuit lapidem capitī suō et obdormīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"perobscurus","latin":"perobscurus, perobscura, perobscurum","headword":"perobscurus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very obscure, very vague","forms":["perobscūra"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Difficilis erat atque {{perobscūra}} quaestiō, cum nūllus esset testis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"perorare","latin":"(perōrō) perōrāre","headword":"perōrāre","letter":"p","pos":"","posGroup":"other","english":"conclude (a speech)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perpastus","latin":"perpastus, perpasta, perpastum","headword":"perpastus","letter":"p","pos":"adjective","posGroup":"adjective","english":"well-fed","forms":["perpastō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"DE LVPO MACRO ET CANE {{PERPASTO}}","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"perpauci","latin":"perpaucī, -ae, -a","headword":"perpaucī","letter":"p","pos":"","posGroup":"other","english":"very few","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perpaucum","latin":"perpaucum, perpauci","headword":"perpaucum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"very few (pl.), very little","forms":["perpauca","perpaucis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, {{perpaucis}} ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perpellere","latin":"(perpellō) perpellere (< pellere)","headword":"perpellere","letter":"p","pos":"","posGroup":"other","english":"enforce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perpello","latin":"perpello, perpellere, perpuli, perpulsus","headword":"perpello","letter":"p","pos":"verb","posGroup":"verb","english":"compel, constrain, prevail upon; enforce","forms":["perpulerat","perpulit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Saepe iterandō eadem {{perpulit}} tandem ut Rōmae in Aventīnō fānum Diānae populus Latīnus cum populō Rōmānō faceret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perperam","latin":"perperam","headword":"perperam","letter":"p","pos":"adverb","posGroup":"adverb","english":"wrongly, incorrectly","forms":["perperam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Hominēs sumus, nôn deî.” Idem et Scintilla ﬂëns dîxit, ac per genium eius ‘Gāium’ appellandô rogāre coepit ‘ut Nôn tenuit ultrā lacrimās Trimalchiô, et “Rogô” inquit, “Habinnä, @`� sî quid {{perperam}} tëcî, in faciem meam in- spue!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"perpes","latin":"perpes, (gen.), perpetis","headword":"perpes","letter":"p","pos":"adjective","posGroup":"adjective","english":"continuous, lasting, unbroken in time, perpetual, neverending; whole period","forms":["perpetem","perpeti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Praestare visum est tamen omnes difficultates {{perpeti}} quam tanta contumelia accepta omnium suorum voluntates alienare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perpetior","latin":"perpetior, perpeti, perpessus sum","headword":"perpetior","letter":"p","pos":"verb","posGroup":"verb","english":"endure to the full","forms":["perpessae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Accipiunt ventōs ā tergō mīlle carīnae multaque {{perpessae}} Phrygiā potiuntur harēnā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"perpetuo","latin":"perpetuo","headword":"perpetuo","letter":"p","pos":"adverb","posGroup":"adverb","english":"without interruption; constantly; forever; continually; perpetual","forms":["perpetuo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri defessis succederent nostrosque assiduo labore defatigarent, quibus propter magnitudinem castrorum {{perpetuo}} esset isdem in vallo permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perpetuus","latin":"perpetuus, -a, -um","headword":"perpetuus","letter":"p","pos":"adjective","posGroup":"adjective","english":"continuous, permanent; perpetual, everlasting","forms":["perpetua","perpetuae","perpetuam","perpetuis","perpetuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Trabes directae {{perpetuae}} in longitudinem paribus intervallis distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perrogare","latin":"(perrogō) perrogāre","headword":"perrogāre","letter":"p","pos":"verb","posGroup":"verb","english":"ask in turn; to ask in order, poll (the senate)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"perrogo","latin":"perrogo, perrogare, perrogavi, perrogatus","headword":"perrogo","letter":"p","pos":"verb","posGroup":"verb","english":"ask/question/solicit in turn; L:propose/pass a law; carry (bill)","forms":["perrogārī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum lēgātī ex Āfricā cum ōrātōribus Carthāginiēnsium et Gulussā redīssent dīcerentque 'et exercitum sē dēprehendisse et classem Carthāgine dēprehendisse', perrogārī sententiās placuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"perrumpo","latin":"perrumpo, perrumpere, perrupi, perruptus","headword":"perrumpo","letter":"p","pos":"verb","posGroup":"verb","english":"break through","forms":["perrumpi","perrupta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque {{perrumpi}} neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"persa","latin":"Persa, Persae","headword":"Persa","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Persian, native of Persia; (sometimes for Parthian; Persian breed of dog)","forms":["Persa","Persārum","Persās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rūfus: “Ecce {{Persa}}, canis meus, quī cum ovibus tuīs venit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"persaepe","latin":"persaepe","headword":"persaepe","letter":"p","pos":"adverb","posGroup":"adverb","english":"very often","forms":["persaepe"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod adventū tuō ista subsellia vacuēfacta sunt, quod omnēs cōnsulārēs, quī tibi {{persaepe}} ad caedem cōnstitūtī fuērunt, simul atque assēdistī, partem istam subselliōrum nūdam atque inānem relīquērunt, quō tandem animō tibi ferendum putās?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"perscribo","latin":"perscribo, perscribere, perscripsi, perscriptus","headword":"perscribo","letter":"p","pos":"verb","posGroup":"verb","english":"report; describe; write out in full; finish writing, write a detailed record","forms":["perscrīptum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Et quoniam nōndum est {{perscrīptum}} senātūs cōnsultum, ex memoriā vōbīs, Quirītēs, quid senātus cēnsuerit expōnam.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"persequi","latin":"(persequor) persequī, persecūtum","headword":"persequī","letter":"p","pos":"verb","posGroup":"verb","english":"follow, pursue; to pursue, chase","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"persequor","latin":"persequor, persequi, persecutus sum","headword":"persequor","letter":"p","pos":"verb","posGroup":"verb","english":"follow up, pursue; overtake; attack; take vengeance on; accomplish","forms":["persecūta","persecūtī","persecūtus","persequamur","persequantur","persequar","persequāre","persequātur","persequēbantur","persequēbātur","persequendī","persequendīs","persequendōs","persequente","persequentibus","persequere","persequerētur","persequī","persequitur","persequuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, {{persequamur}} eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perses","latin":"Perses, Persae","headword":"Perses","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Persian, native of Persia; (sometimes for Parthian; Persian breed of dog)","forms":["persē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ecce vēro, Daphnē prīma Apollinī amōre flagrantī occurrit, pulcherrima nympha quae, cum ferās in silvīs persē quendō et occīdendō atque lībera per campōs currendō gaudēret dominamque Diānam virginem habēret, numquam virum ūllum cognōverat neque amāverat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"perseus","latin":"Perseus, Persei","headword":"Perseus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Perseus; (son of Jupiter and Danae, slayer of Medusa)","forms":["Persea","Perseī","Perseō","Persēum","Persēus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pudēbat enim oculōsque replēvit lacrimīs; deinde, cum {{Persēus}} etiam atque etiam interrogāret, nē vidērētur nōlle cāsūs suōs fatērī, quod nōmen illī terrae esset dīxit, neque occultāvit quōmodo ipsa vocārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"perseverans","latin":"perseverans, perseverantis (gen.), perseverantior -or -us, perseverantissimus -a -um","headword":"perseverans","letter":"p","pos":"adjective","posGroup":"adjective","english":"steadfast, persistent, untiring; continually maintained, persistent (activity)","forms":["Persevērantēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Persevērantēs}} dūcī iussī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"perseverare","latin":"(persevērō) persevērāre","headword":"persevērāre","letter":"p","pos":"","posGroup":"other","english":"persist, continue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"persevero","latin":"persevero, perseverare, perseveravi, perseveratus","headword":"persevero","letter":"p","pos":"verb","posGroup":"verb","english":"persist, persevere; continue","forms":["perseverāret","Persevērās","persevērat","perseverāvērunt","perseverāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Īnstante autem morte, vocātum fīlium monuit, ut semper in timōre Dominī {{perseverāret}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"persicus","latin":"Persicus, Persica, Persicum","headword":"Persicus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Persian","forms":["Persicō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nōnne hāc nocte nostrā nāvis hūc ex portū Persicō","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"persido","latin":"persido, persidere, persedi, persessus","headword":"persido","letter":"p","pos":"verb","posGroup":"verb","english":"settle down; sink into","forms":["Persīdās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Persīdās}} indūxit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"persis","latin":"Persis, (gen.), Persidos","headword":"Persis","letter":"p","pos":"adjective","posGroup":"adjective","english":"Persian","forms":["Persīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deversī in patriam IUdaeī, compositō urbis stātiī, nōn iam egēs habuēre, sed imperium penes pontificēs fuit: tribūta tamen pēnsitārunt prīmum {{Persīs}}, deinde Graecīs, post dēvictum ab Alexandra Darīum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"persolvere","latin":"(persolvō) persolvere (< solvere)","headword":"persolvere","letter":"p","pos":"","posGroup":"other","english":"pay in full, fulfill","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"persolvo","latin":"persolvo, persolvere, persolvi, persolutus","headword":"persolvo","letter":"p","pos":"verb","posGroup":"verb","english":"pay","forms":["persolve","persolvere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"“Quod tibi nōlīs fierī, aliīs nē facitō, fīlī mī: sī quis tibi opus fēcerit, statim eī mercēdem {{persolve}}; cōnsilium semper ā virō sapiente exquīre; nē societātem cum improbīs iungitō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"persona","latin":"persōna, -ae","headword":"persōna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"character, person; person (of the verb); mask, character","forms":["persōnā","Persōnae","persōnam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Persōnae}}: Iūlia, Mārcus, Quīntus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"personale","latin":"persōnāle","headword":"persōnāle","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"personal","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"persono","latin":"persono, personare, personavi, personatus","headword":"persono","letter":"p","pos":"verb","posGroup":"verb","english":"make loud/continuous/pervasive noise/loud music; ring/resound; chant/shout out","forms":["personat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{personat}} aurātā, docuit quem maximus Atlās.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"perspecto","latin":"perspecto, perspectare, perspectavi, perspectatus","headword":"perspecto","letter":"p","pos":"verb","posGroup":"verb","english":"look through to end; examine closely","forms":["perspecta","perspecto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Caesar ex eo loco quintis castris Gergoviam pervenit equestrique eo die proelio levi facto, {{perspecto}} urbis situ, quae posita in altissimo monte omnes aditus difficiles habebat, de expugnatione desperavit; de obsessione non prius agendum constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perspectus","latin":"perspectus, perspecta, perspectum","headword":"perspectus","letter":"p","pos":"adjective","posGroup":"adjective","english":"evident; well-known","forms":["perspectam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Etsi multis iam rebus perfidiam Aeduorum {{perspectam}} habebat atque horum discessu admaturari defectionem civitatis existimabat, tamen eos retinendos non constituit, ne aut inferre iniuriam videretur aut daret timoris aliquam suspicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perspicere","latin":"(perspicō) perspicere","headword":"perspicere","letter":"p","pos":"","posGroup":"other","english":"survey, recognize","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"perspicio","latin":"perspicio, perspicere, perspexi, perspectus","headword":"perspicio","letter":"p","pos":"verb","posGroup":"verb","english":"see through; examine; observe","forms":["perspicere","perspicias","perspiciendi","perspiciēs","perspicis","Perspicit","perspicite"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam cum in minora castra operis {{perspiciendi}} causa venisset, animadvertit collem, qui ab hostibus tenebatur, nudatum hominibus, qui superioribus diebus vix prae multitudine cerni poterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perstare","latin":"(perstō) perstāre","headword":"perstāre","letter":"p","pos":"","posGroup":"other","english":"stand firm, persist","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"persto","latin":"perstō, -āre, -stitī, -stātum","headword":"perstō","letter":"p","pos":"verb","posGroup":"verb","english":"to stand firm, continue","forms":["perstare","perstāret","perstārētur","perstat","perstitērunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi eos in sententia {{perstare}} viderunt, quod plerumque in summo periculo timor misericordiam non recipit, conclamare et significare de fuga Romanis coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"persuadeo","latin":"persuadeo, persuadere, persuasi, persuasus","headword":"persuadeo","letter":"p","pos":"verb","posGroup":"verb","english":"persuade, convince (with dat.)","forms":["persuādeam","persuādēbit","persuādentia","persuādēre","persuādērī","persuādet","persuādēte","persuāsī","persuāsit","persuāsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus Iōsēphus: īte, inquit, properātē ad patrem meum, eīque nūntiātē fīlium suum vīvere, et apud Pharaōnem plūrimum posse; {{persuādēte}} illī ut in Aegyptum cum omnī familiā commigret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"persuadere","latin":"(persuādeō) persuādēre,  persuāsisse  ({i}intr. + dat.{/i})","headword":"persuādēre","letter":"p","pos":"verb","posGroup":"verb","english":"persuade, convince; to persuade (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"pertaedet","latin":"pertaedet, pertaedere, pertaeduit, pertaesus est","headword":"pertaedet","letter":"p","pos":"verb","posGroup":"verb","english":"it wearies; it disgusts; it bores","forms":["pertaesus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Diē septimā cum Samūēl morārētur, et populus morae {{pertaesus}} dīlāberētur, Saūl ipse sacrificium fēcit locō sacerdōtis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pertempto","latin":"pertempto, pertemptare, pertemptavi, pertemptatus","headword":"pertempto","letter":"p","pos":"verb","posGroup":"verb","english":"test, try out; explore thoroughly; agitate thoroughly","forms":["pertemptant"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Lātōnae tacitum {{pertemptant}} gaudia pectus:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"perterreo","latin":"perterreo, perterrere, perterrui, perterritus","headword":"perterreo","letter":"p","pos":"verb","posGroup":"verb","english":"frighten greatly, terrify","forms":["perterreant","perterruerunt","perterruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae {{perterreant}} alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perterritus","latin":"perterritus, -a, -um","headword":"perterritus","letter":"p","pos":"adjective","posGroup":"adjective","english":"terrified","forms":["perterrita","perterritae","perterritam","perterriti","perterritis","perterritōs","perterritum","perterritus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem {{perterriti}} omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat neve ab hostibus diripiantur, praesertim cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pertimescere","latin":"(pertimēscō) pertimēscere, -muisse (< timēre)","headword":"pertimēscere","letter":"p","pos":"","posGroup":"other","english":"be frightened (of)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pertimesco","latin":"pertimesco, pertimescere, pertimui, -","headword":"pertimesco","letter":"p","pos":"verb","posGroup":"verb","english":"become very scared (of )","forms":["pertimēscās","pertimēscenda","pertimēscendam","pertimescendum","pertimēscēs","pertimuerat","pertimuisse","pertimuissent"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"crēditur annósum {{pertimuisse}} senem:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pertinacia","latin":"pertinacia, pertinaciae","headword":"pertinacia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"determination/perseverance; persistence; obstinacy, stubbornness, defiance","forms":["pertināciam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Moysēs, ut pharaōnis {{pertināciam}} vinceret, multa et stupenda ēdidit prōdigia, quae vocantur ‘plāgae Aegyptī’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pertineo","latin":"pertineo, pertinere, pertinui, pertentus","headword":"pertineo","letter":"p","pos":"verb","posGroup":"verb","english":"reach; extend; relate to; concerns, pertain to","forms":["pertineat","pertinebant","pertinebat","pertinent","pertinēre","pertinet","pertinuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sic milites consolatus eodem die reducit in castra reliquaque quae ad oppugnationem {{pertinebant}} oppidi administrare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pertinere","latin":"(pertineō) pertinēre (< tenēre)","headword":"pertinēre","letter":"p","pos":"","posGroup":"other","english":"relate, pertain (to)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pertraho","latin":"pertraho, pertrahere, pertraxi, pertractus","headword":"pertraho","letter":"p","pos":"verb","posGroup":"verb","english":"draw or drag through or to, bring or conduct forcibly to; draw on, lure","forms":["pertraxērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulierēs exterae, quās adamāvit, eum iam senem ad rītūs gentīlēs {{pertraxērunt}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pertundo","latin":"pertundo, pertundere, pertudi, pertusus","headword":"pertundo","letter":"p","pos":"verb","posGroup":"verb","english":"bore through, perforate","forms":["pertundimus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Temptēmus tamen, Accipimus nôs cochleāria nôn minus sëlîbräs {{pertundimus}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"perturbare","latin":"(perturbō) perturbāre, -āvisse, -ātum","headword":"perturbāre","letter":"p","pos":"verb","posGroup":"verb","english":"disturb; to disturb, alarm","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"perturbatus","latin":"perturbatus, perturbata, perturbatum","headword":"perturbatus","letter":"p","pos":"adjective","posGroup":"adjective","english":"troubled","forms":["perturbāta","perturbātae","perturbātam","perturbātī","perturbatos","perturbātus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus rebus auditis, quod existimabant tribus locis transire legiones atque omnes {{perturbatos}} defectione Aeduorum fugam parare, suas quoque copias in tres partes distribuerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"perturbo","latin":"perturbo, perturbare, perturbavi, perturbatus","headword":"perturbo","letter":"p","pos":"verb","posGroup":"verb","english":"confuse, throw into confusion; disturb, perturb, trouble; alarm","forms":["perturbandam","perturbant","perturbantur","perturbarentur","perturbātum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postero die concilio convocato, consolatus cohortatusque est ne se admodum animo demitterent, ne {{perturbarentur}} incommodo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pervadere","latin":"(pervādō) pervādere (< vādere)","headword":"pervādere","letter":"p","pos":"","posGroup":"other","english":"go through, spread, pervade","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pervado","latin":"pervado, pervadere, pervasi, pervasus","headword":"pervado","letter":"p","pos":"verb","posGroup":"verb","english":"go or come through; spread through; penetrate; pervade","forms":["pervāserat","pervāserit","pervāsisset","pervāsit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum ex eō pavor ac trepidātiō tōtam urbem {{pervāsisset}}, alius īnsuper tumultus ex arce audītur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pervagor","latin":"pervagor, pervagari, pervagatus sum","headword":"pervagor","letter":"p","pos":"verb","posGroup":"verb","english":"wander or range through, rove about; pervade, spread widely; extend","forms":["pervagāta","pervagentur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime {{pervagentur}}; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pervagus","latin":"pervagus, pervaga, pervagum","headword":"pervagus","letter":"p","pos":"adjective","posGroup":"adjective","english":"wandering everywhere","forms":["pervagus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dīcere, tam vàsto {{pervagus}} orbe puer.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pervastare","latin":"(pervāstō) pervāstāre","headword":"pervāstāre","letter":"p","pos":"","posGroup":"other","english":"completely devastate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pervasto","latin":"pervasto, pervastare, pervastavi, pervastatus","headword":"pervasto","letter":"p","pos":"verb","posGroup":"verb","english":"devastate completely","forms":["pervāstat","pervāstātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hannibal īnfestō exercitū ingressus fīnēs, {{pervāstātīs}} passim agrīs, urbem aggreditur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pervenio","latin":"perveniō, -īre, pervēnī, perventum","headword":"perveniō","letter":"p","pos":"verb","posGroup":"verb","english":"arrive","forms":["pervēnerāmus","pervēnerant","pervēnerat","pervēnēre","pervēnerint","pervēnerit","pervenerunt","pervēnī","perveniam","perveniant","perveniat","perveniēmus","perveniēns","pervenient","pervēniēs","perveniet","pervenire","pervenīrent","pervenīret","pervenisse","pervēnissent","pervenisset","pervenit","perveniunt","perventum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore ex hibernis egredi neque imperator sine praesidio ad legiones {{pervenire}} possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pervenire","latin":"(perveniō) pervenīre, pervēnisse","headword":"pervenīre","letter":"p","pos":"verb","posGroup":"verb","english":"arrive; to arrive, reach","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"perversus","latin":"perversus, perversa, perversum","headword":"perversus","letter":"p","pos":"adjective","posGroup":"adjective","english":"askew, awry; perverse, evil, bad","forms":["perversās","perversō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"turbida {{perversās}} induit illā cōmās!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pervideo","latin":"pervideō, -ēre, -vīdī, -vīsum","headword":"pervideō","letter":"p","pos":"verb","posGroup":"verb","english":"see through, discern, realize","forms":["pervīdit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dēnique {{pervīdit}} sē imāginem esse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pervigil","latin":"pervigil, -is","headword":"pervigil","letter":"p","pos":"adjective","posGroup":"adjective","english":"ever-watchful","forms":["pervigilī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Superest herbīs somnum dracōnī pervigilī dare, quī horrendus custōs velleris aureī erat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pervolare","latin":"(pervolō) pervolāre","headword":"pervolāre","letter":"p","pos":"","posGroup":"other","english":"move rapidly, rush, fly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pervolo","latin":"pervolo, pervolare, pervolavi, pervolatus","headword":"pervolo","letter":"p","pos":"verb","posGroup":"verb","english":"fly or flit through; wing one's way; move rapidly through the air","forms":["pervolābit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sunt autem optimae cūrae dē salūte patriae, quibus agitātus et exercitātus animus velōcius in hanc sēdem et domum suam {{pervolābit}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pes","latin":"pēs, pedis","headword":"pēs","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) foot","forms":["pede","pedem","pedī","pedibus","pedis","pēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex omnibus fere partibus palus difficilis atque impedita cingebat, non latior {{pedibus}} quinquaginta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pessimus","latin":"pessimus, -a, -um","headword":"pessimus","letter":"p","pos":"adjective","posGroup":"adjective","english":"worst","forms":["pessima","pessimē","pessimī","pessimum","pessimus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōnne tibi satis est laudāre malum magistrum — etiamne discipulum eius {{pessimum}} laudāre audēs?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pessum","latin":"pessum","headword":"pessum","letter":"p","pos":"adverb","posGroup":"adverb","english":"to the lowest part, to the bottom, [~ dare => destroy, ruin]","forms":["pessum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quae rēs plērumque magnās cīvitātēs {{pessum}} dedit, dum alterī alterōs vincere quōvīs modō et victōs acerbius ulcīscī volunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pessum dare","latin":"pessum dāre","headword":"pessum dāre","letter":"p","pos":"phrase","posGroup":"other","english":"destroy, ruin; to ruin, destroy utterly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"pestifer","latin":"pestifer, -era, -erum","headword":"pestifer","letter":"p","pos":"adjective","posGroup":"adjective","english":"disastrous, pernicious","forms":["pestiferum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sextus est Tarquinius quī hostis prō hospite priōre nocte vī armātus mihi — sibique, sī vōs virī estis! — {{pestiferum}} hinc abstulit gaudium.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pestilentia","latin":"pestilentia, -ae","headword":"pestilentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"plague, pestilence","forms":["pestilentia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nāvibus in lītus subductīs, iuvenēs Trōiānī iam novam urbem aedificābant et arva nova colēbant, cum foeda {{pestilentia}} hominēs miserōs afficere coepit, et simul sōl flagrāns agrōs siccōs adeō torrēbat ut nec herbam nec frūmentum ferre possent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pestis","latin":"pestis, pestis","headword":"pestis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"plague, pestilence, curse, destruction","forms":["peste","pestem","pestī","pestis"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ad mortem tē, Catilīna, dūcī iussū cōnsulis iam prīdem oportēbat, in tē cōnferrī {{pestem}} quam tū in nōs omnēs iam diū māchināris!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"petaso","latin":"petaso, petasonis","headword":"petaso","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"forequarter/shoulder of pork","forms":["petasō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mercurius autem ut avis volāre potest, nam in pedibus et in petasō eius ālae sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"petasus","latin":"petasus, -ī","headword":"petasus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"hat with a brim","forms":["petasum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mercurius statim ālās, {{petasum}}, virgam sūmpsit; at cum prīmum in terram venit, vestēs pāstōris induit et aliquot capellās virgā per agrōs ēgit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"petisso","latin":"petisso, petissere, -, -","headword":"petisso","letter":"p","pos":"verb","posGroup":"verb","english":"long for, strive after","forms":["petīsse"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus oppugnandīs quia haud dubiē Rōmāna arma movēbantur, in Olcādum prius fīnēs indūxit exercitum, ut nōn {{petīsse}} Saguntīnōs, sed fīnitimīs domitīs gentibus tractus ad id bellum vidērī posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"petit","latin":"petit, -unt","headword":"petit","letter":"p","pos":"verb","posGroup":"verb","english":"make for, aim at, attack, seek, ask for, request; seeks, heads for; attacks","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"petitio","latin":"petītiō, -ōnis ( f.)","headword":"petītiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"pursuit, candidature","forms":["petītiō","petitione","petītiōnem","petītiōnēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Catilīna, bis repulsam in {{petitione}} cōnsulātūs passus, cum Lentulō praetōre et Cethēgō et complūribus aliīs coniūrāvit dē caede cōnsulum et senātūs, incendīs urbis et opprimendā rē pūblicā, exercitū quoque in Etrūriā comparātō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"peto","latin":"petō, -ere, petīvī, petītum","headword":"petō","letter":"p","pos":"verb","posGroup":"verb","english":"seek, ask, pursue; to seek, ask, attack","forms":["petam","petāmus","petant","petās","petat","petātur","pete","petēbāmus","petēbant","petēbat","petēmus","petenda","petendae","petendam","petendī","petendum","petēns","petentem","petentēs","petentī","petentibus","petere","peterem","peterent","peterēs","peteret","peterētur","petēs","petet","petī","petis","petit","petīta","petītē","petītī","petītīs","petītōs","petītum","petitur","petītūrum","petītus","petīverat","petīvēre","petīverint","petīverīs","petiverunt","petīvī","petīvisse","petīvisset","petīvit","petō","petunt","petuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur {{petunt}}, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"petra","latin":"petra, petrae","headword":"petra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"rock, boulder; shaped stone as used in building","forms":["Petra","Petram"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum laudâtus Trimalchiô hīla- solium Iovis tenēre : fëlîcis- in argentô studiôsus zargentî s. nôn Cassandra, sed Mêdêa fî- Daedalus Päsiphaên in vaccam ligneam inclūsit (Päsiphaë Hermerôs -ôtis, {{Petra}}îtës -is, ëbriô proximus à paene êbrius horreum -î n à aediﬁcium ubi lae rūsticae (praediô) prae- rius bibit et iam ëbriô proximus “Nëmô”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"petrus","latin":"Petrus, Petri","headword":"Petrus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Peter","forms":["Petrus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Nōlīte timēre.\" Respondēns autem eī {{Petrus}} dīxit: \"Domine, sī tū es, iubē mē ad tē venīre super aquam!\" At ipse ait: \"Venī!\" Et dēscendēns Petrus dē nāviculā ambulābat super aquam, ut venīret ad Iēsum.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"petulans","latin":"petulans, petulantis (gen.), petulantior -or -us, petulantissimus -a -um","headword":"petulans","letter":"p","pos":"adjective","posGroup":"adjective","english":"insolent, unruly, smart-alecky; forward, aggressive; impudent; reprobate/wanton","forms":["petulāns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{petulāns}} -antīs adī 7 protervus, īrī-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"phaedrus","latin":"Phaedrus, Phaedri","headword":"Phaedrus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Phaedo (pupil of Socrates); Phaedrus (Latin fabulist); (Cicero's teacher)","forms":["Phaedrī","Phaedrus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hōc versū ūtitur Plautus in prōlogō — et {{Phaedrus}} in Fābulīs Aesōpiīs (vidē pāginās 33–41).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"phaethon","latin":"Phaethon, Phaethontis","headword":"Phaethon","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Phaethon; (son of Sol/Helios, killed driving the sun chariot)","forms":["Phaethōn"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Hūc cum vēnisset Phaetōn, Sōlis fīlius, patris domum intrāvit ac gradūs ad parentem versus fēcit, quī, indūtus purpureā veste, sedēbat in soliō clārīs gemmīs lūcente; {{Phaethōn}} procul cōnstitit; nam magnam lūcem propius oculīs sustinēre nōn poterat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"phalera","latin":"phalera, phalerae","headword":"phalera","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"ornaments (pl.) worn by men of arms and horses","forms":["phalerās","phalerīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is vīderat bēluam ūnam cēterīs maiōrem, ac {{phalerīs}} rēgis circumtēctam; exīstimāns illa rēgem vehī, sē prō communī saliite dēvōvit: per mediōs hostēs ad bēluam properāvit, sub illīus ventrem subiit, repefifīs ictibus cōnfossam occīdit, et bēluae lābentis pondere oppressus ipse occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"phalerae","latin":"phalerae, -ārum (pl.)","headword":"phalerae","letter":"p","pos":"","posGroup":"other","english":"military decoration","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"phaleratus","latin":"phaleratus, phalerata, phaleratum","headword":"phaleratus","letter":"p","pos":"adjective","posGroup":"adjective","english":"wearing phalerae/ornaments","forms":["phalerātis"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hinc, involūtus coccinā gausapā, lectīcae impositus est, praecēdentibus {{phalerātis}} cursôribus quattuor et chîra- maxiô in quô dēliciae eius vehēbantur, puer vetulus, lippus, dominô Trimalchī- ône dëfôrmior.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"phantasia","latin":"phantasia, phantasiae","headword":"phantasia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"fancy, imagined situation; mental image (Latham); imagination; phenomenon (Def)","forms":["Phantasia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Phantasia}}, nôn homô!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"phantasma","latin":"phantasma, phantasmatis","headword":"phantasma","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(n.) ghost, apparition","forms":["Phantasma"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Discipulī autem, videntēs eum super mare ambulantem, turbātī sunt dīcentēs: \"{{Phantasma}} est!\" et prae timōre clāmāvērunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pharao","latin":"Pharao, Pharaonis","headword":"Pharao","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pharaoh, title of King of Egypt","forms":["pharaō","pharaōnem","Pharaōnī","pharaōnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erant in eōdem carcere duo ministrī rēgis {{Pharaōnis}}: alter praeerat pincernīs, alter pistōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pharetra","latin":"pharētra, -ae","headword":"pharētra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"quiver","forms":["pharetrā","pharetram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Isaacus iam senuisset, et factus esset caecus, vocāvit Esāüm: sūmitō, inquit {{pharetram}}, arcum et sagittās; affer mihi et parā dē vēnātiōne pulmentum, ut comedam et apprecer tibi fausta omnia, antequam moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"phiala","latin":"phiala, phialae","headword":"phiala","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"drinking vessel; a bowl, saucer","forms":["phialam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Fuit tamen faber quī tëcit {{phialam}} vitream quae nôn ﬁangëbätur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"philargyrus","latin":"philargyrus, philargyra, philargyrum","headword":"philargyrus","letter":"p","pos":"adjective","posGroup":"adjective","english":"fond of money","forms":["Philargyre"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hinc ex eôdem unguentô in vînärium atque lucēmam aliquantum est înñsum Iam coeperat Fortūnāta velle saltâre, iam Scintilla frequentius plaudēbat quam loquēbātur, cum Trimalchiô “Permittô” inquit, “{{Philargyre}}, etsî prasiniânus es fämô- Quid multa?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"philemon","latin":"Philēmōn, -mōnis","headword":"Philēmōn","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Philemon","forms":["Philēmōn","Philēmone","Philēmōnem","Philēmōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Utinam nē nōs in viam pellant!” Hīs verbīs dictīs iānuam pulsāvērunt casae, in quā Baucis cum {{Philēmone}} habitābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"philippus","latin":"Philippus, Philippi","headword":"Philippus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Philip (name of several Macedonian kings); (Philip II, father of Alexander)","forms":["Philippī","Philippō","Philippum","Philippus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum sublevāsset ergō oculōs Jēsus et vīdisset turbam maximam illam, dīxit Philippō:\"Unde emēmus pānēs ut mandūcent hī?\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"philologia","latin":"philologia, philologiae","headword":"philologia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"love of learning, study of literature","forms":["philologiam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Rogô, mē putātis illā cēnā esse contentum quam in thēcā repositôriî vîderâtis? cēnandum {{philologiam}} nôsse.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"philosophia","latin":"philosophia, -ae","headword":"philosophia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"philosophy","forms":["philosophiae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iūxtā ea tempora Empedoclēs Agrigentīnus in {{philosophiae}} nātūrālis studiō flōruit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"philosophicus","latin":"philosophicus, philosophica, philosophicum","headword":"philosophicus","letter":"p","pos":"adjective","posGroup":"adjective","english":"philosophical, philosophic; of/concerning philosophy","forms":["philosophica"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praeter ōrātiōnēs multās et epistulās ad familiārēs suōs ēdidit opera rhētorica, ut trēs librōs ‘Dē ōrātōre’, et {{philosophica}}, ut ‘Tūsculānās disputātiōnēs’, quae annō XLV a.C. cōnscrīptae sunt.]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"philosophus","latin":"philosophus, -ī","headword":"philosophus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"philosopher","forms":["philosophī","philosophīs","philosophō","philosophōrum","philosophōs","philosophum","philosophus","PHILOSOPHVM"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Diodōrus: “Epicūrus est {{philosophus}} Graecus, ut Sōcratēs et philosophus -ī Platō et Aristotelēs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"philtrum","latin":"philtrum, philtri","headword":"philtrum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"love-potion","forms":["philtra","philtrum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{philtrum}} -ī ;/ 7 pótió magicā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"phoca","latin":"phoca, phocae","headword":"phoca","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"seal; (marine mammal)","forms":["Phōcis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Intrā faucēs ad meridiem vergunt Aetōliae pars maior et Acarnānia et cum Locride {{Phōcis}} et Boeōtia adiūnctaque īnsula Euboea et, excurrente in altum velut prōmunturiō, Attica terra et sita ā tergō Peloponnēsus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"phoebe","latin":"Phoebe, Phoebes","headword":"Phoebe","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Diana; moon goddess","forms":["Phoebe"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Cūr usque ad meam rēgiam iter fēcistī, fīlī mī?” Ille vērō respondit: “Ō {{Phoebe}} pater, quī es lūx tōtīus mundī: quīdam, quī fortasse invident mihi, negāvērunt mē fīlium tuum esse: nunc igitur tē orō et rogō ut mihi dubium tollās, et aliquō modō certō dēmōnstrēs ā mē verē et iūre ‘patrem’ tē nōminan posse!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"phoebus","latin":"Phoebus, -ī","headword":"Phoebus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Phoebus Apollo","forms":["Phoebī","Phoebō","Phoebum","Phoebus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde multās aliās fābulās pīnxit; tum {{Phoebum}}, et Bacchum; dēnique extrēmam vestis partem pulcherrimīs flōribus ōrnāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"phoenice","latin":"Phoenīcē, -ēs","headword":"Phoenīcē","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Phoenicia","forms":["Phoenīcē","Phoenīcēs","Phoenīcum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Terrae in Āsiā sunt Āsia Minor, Armenia, Mesopotamia, Arabia, Syria, Phoenīcē.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"phoenicius","latin":"Phoenīcius, -a, -um","headword":"Phoenīcius","letter":"p","pos":"adjective","posGroup":"adjective","english":"Phoenician, of Phoenicia","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"phoenissa","latin":"Phoenissa, Phoenissae","headword":"Phoenissa","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Phoenician woman; (epithet of Dido)","forms":["Phoenissa","Phoenissam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"In Āfricā Dīdō, rēgīna {{Phoenissa}}, habitat et regnat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"phrygia","latin":"Phrygia, -ae","headword":"Phrygia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Phrygia","forms":["Phrygiā"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nārrābō dē duābus arboribus, dē tiliā et quercū in Phrygiā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"phrygius","latin":"Phrygius, -a, -um","headword":"Phrygius","letter":"p","pos":"adjective","posGroup":"adjective","english":"Phrygian, Trojan","forms":["Phrygiae","Phrygiī","Phrygiīs","Phrygiō","Phrygium"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mīdās, magnus rēx {{Phrygiae}}, magnam sapientiam nōn habēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pica","latin":"pica, picae","headword":"pica","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"magpie; jay","forms":["pīca","picis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac {{picis}} traditas glaebas in ignem e regione turris proiciebat; scorpione ab latere dextro traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pictor","latin":"pictor, pictoris","headword":"pictor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"painter","forms":["pictor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Apellés -is 7, {{pictor}} Cōus illūstris;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pictura","latin":"pictūra, -ae","headword":"pictūra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"picture","forms":["pictūra","pictūrae","pictūram","pictūrās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Pictūrās}} pulchrās in textilī format.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"picus","latin":"picus, pici","headword":"picus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"woodpecker","forms":["Pīcus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Post hunc {{Pīcus}}, deinde Faunus in Latiō rēgnāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pietas","latin":"pietās, -ātis ( f.)","headword":"pietās","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"respect, devotion, piety; respect, devotion, dutiful conduct; respect, reverence; piety; duty, piety; piety, duty","forms":["pietās","pietāte","pietātem","pietātis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum in captīvitātem abductus esset, eandem in Deum {{pietātem}} semper retinuit: omnia bona, quae habēre poterat, cotīdiē exsiliī suī comitibus impertiēbat, eōsque monitīs salūtāribus ad colendum Deum hortābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"piger","latin":"piger, pigra, pigrum","headword":"piger","letter":"p","pos":"adjective","posGroup":"adjective","english":"lazy; lazy, idle; lazy, slow","forms":["piger","pigra","pigrī","pigrīs","pigrōs","pigrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Ego nōn putō {{pigrum}} esse magistrum Sextī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pigere","latin":"(piget) pigēre, piguit, pigitum","headword":"pigēre","letter":"p","pos":"","posGroup":"other","english":"feel annoyance at, regret","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"piget","latin":"piget, pigere, -, pigitus est","headword":"piget","letter":"p","pos":"verb","posGroup":"verb","english":"it disgusts, irks, pains, chagrins, afflicts, grieves","forms":["pigeat","pigēbit","piget"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"pigére; m8 {{piget}} — mihi molestum 3 IN-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pignus","latin":"pignus, -oris (n.)","headword":"pignus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"pledge","forms":["pignora","pignore","pignus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"et quaerit, positō {{pignore}}, 'vincat uter?'","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pigro","latin":"pigro, pigrare, pigravi, pigratus","headword":"pigro","letter":"p","pos":"verb","posGroup":"verb","english":"hesitate; hang back","forms":["pigrō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Fabia: “Sextus discipulus industrius ac prūdēns est, ut scīs; ergō bene discit, quamquam male docētur ā magistrō pigrō atque stultō!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pila","latin":"pila, -ae","headword":"pila","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"ball","forms":["pilā","pilae","pilam","pilis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dum longius ab munitione aberant Galli, plus multitudine telorum proficiebant; postea quam propius successerunt, aut se stimulis inopinantes induebant aut in scrobes delati transfodiebantur aut ex vallo ac turribus traiecti {{pilis}} muralibus interibant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pilatus","latin":"Pilatus, Pilati","headword":"Pilatus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pilatus; (Roman cognomen); [Pontius ~ (Pilate) => prefect Judea, 26-36 AD]","forms":["Pīlātō","Pīlātum","Pīlātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ecce haec est hōrā vestrā.\"Comprehendērunt ergō eum, et dūxērunt ad {{Pīlātum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pilleum","latin":"pilleum, pillei","headword":"pilleum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"felt cap (worn at Saturnalia/by manumited slaves); freedom/liberty; beret","forms":["pilleum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi eī in carpentō sedentī cum uxōre aquilā repente dēlāpsa {{pilleum}} aufert, superque carpentum volitāns rūrsus, velut dīvīnitus missa, capitī aptē repōnit; inde sublīmis abit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pilleus","latin":"pilleus, -ī","headword":"pilleus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"felt cap; cap of a free man","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"pilo","latin":"pilo, pilare, pilavi, pilatus","headword":"pilo","letter":"p","pos":"verb","posGroup":"verb","english":"grow hairy; depilate; plunder","forms":["pīlō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Quī cum mihi in hostēs prōgressō auxilium ferre vellet, ipse ex aciē excurrēns pīlō percussus cecidit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pilosus","latin":"pilosus, pilosa -um, pilosior -or -us, pilosissimus -a -um","headword":"pilosus","letter":"p","pos":"adjective","posGroup":"adjective","english":"hairy, shaggy, covered with hair; uncouth","forms":["pilōsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī prior ēditus est {{pilōsus}} erat, alter vērō lēnis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pilum","latin":"pīlum, -ī","headword":"pīlum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"spear, javelin; javelin","forms":["pīlum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Singulī peditēs gladium, scūtum et {{pīlum}} acūtum ferēbant, et sīc armātī fortiter oppida oppugnābant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pilus","latin":"pilus, pili","headword":"pilus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"hair; bit/whit (thing of minimal size/value); hair shirt/garment (pl.) (L+S)","forms":["pilōs","pilus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Epimētheus igitur aliīs celeritātem dedit, quā vēlōcissimē currentēs ā bēstiīs ferīs sē persequentibus fugere possent; aliīs vērō unguēs et dentēs, quibus et impetum in aliās bēstiās facerent et sē ipsa dēfenderent; aliīs dēnique {{pilōs}} multōs, quibus tōtum corpus tegerent et facilius frīgora paterentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pincerna","latin":"pincerna, pincernae","headword":"pincerna","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"cupbearer, butler, one who mixes drinks/serves wine; bartender; sommelier","forms":["pincernārum","pincernīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erant in eōdem carcere duo ministrī rēgis Pharaōnis: alter praeerat {{pincernīs}}, alter pistōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pingere","latin":"(pingō) pingere, pinxisse,","headword":"pingere","letter":"p","pos":"","posGroup":"other","english":"paint, embroider pictum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pingo","latin":"pingō, -ere, pīnxī, pictum","headword":"pingō","letter":"p","pos":"verb","posGroup":"verb","english":"paint, depict, draw","forms":["picta","pictam","pictās","pictīs","pictō","pictōrum","pictum","pingāmus","pingēbat","pingendī","pingentem","pingit","pingitur","pīnxī","pīnxisse","pīnxit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Omnēs dē lēctābantur cum eam acū vestēs {{pingentem}} spectārent, eamque ūnō ōre laudābant dīcentēs ‘Minervam ipsam eius fuisse magistram’.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pingue","latin":"pingue, pinguis","headword":"pingue","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"grease","forms":["pingue"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{pingue}} solum et variīs flōrentia līmina sertīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pinguis","latin":"pinguis, pingue, pinguior -or -us, pinguissimus -a -um","headword":"pinguis","letter":"p","pos":"adjective","posGroup":"adjective","english":"fat; rich, fertile; thick; dull, stupid","forms":["pinguēs","pinguī","pinguis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vidēbātur sibi adstāre Nīlō flūminī; et ecce ēmergēbant dē flūmine septem vaccae {{pinguēs}}, quae pāscēbantur in palūde.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pinna","latin":"pinna, pinnae","headword":"pinna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"feather; wing; fin; battlement/parapet, spire/steeple; flap; water wheel paddle","forms":["pinna","pinnae","pinnās","pinnīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"— āūdàcem {{pinnīs}} repperit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pinnula","latin":"pinnula, pinnulae","headword":"pinnula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"small/little wing/feather; little fin; skirt (of garment) (Souter)","forms":["pinnulae","pinnulās"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Vestītum servīlem gerēns atque in fōrmam Sōsiae servī commūtātus nūllō modō deī similis est—nisi quod {{pinnulae}}, quās in petasō gerit, significant eum esse Mercurium.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"pinus","latin":"pīnus, -ūs","headword":"pīnus","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"pine tree","forms":["pīnūs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Deinde ille occīdit Sinem magnīs vīribus male ūsum, quī tam validus erat ut {{pīnūs}} ad terram curvāre posset.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pio","latin":"pio, piare, piavi, piatus","headword":"pio","letter":"p","pos":"verb","posGroup":"verb","english":"appease, propitiate; cleanse, expiate","forms":["pianda","pīēt","piō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tunc amor et {{pīēt}}às tua sit manifēsta puellae;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"piper","latin":"piper, piperis","headword":"piper","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pepper","forms":["piper"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"W/ Nec est quod putês illum quicquam emere: omnia domî nāscuntur: lānā, cre- drae, {{piper}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pipiare","latin":"(pīpiō) pīpiāre, pīpiāvisse, pīpiātum","headword":"pīpiāre","letter":"p","pos":"","posGroup":"other","english":"chirp","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"pipio","latin":"pipio, pipiare, pipiavi, pipiatus","headword":"pipio","letter":"p","pos":"verb","posGroup":"verb","english":"chirp, pipe","forms":["pipiabat","pīpiant","pīpiat"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Pullī autem tacent neque iam {{pīpiant}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pirata","latin":"pīrāta, -ae","headword":"pīrāta","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) pirate","forms":["pīrātae","pīrātās","pīrātīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus: \"Cum homō līber Athēnīs vīverem, ā quōdam amīcō litterās accēpī quibus ille mihi nūntiāvit sē ā {{pīrātīs}} captum esse ac mē per amīcitiam nostram ōrāvit ut sē ē servitūte redimerem magnum pretium solvendō.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"piraticus","latin":"pīrāticus, -a, -um","headword":"pīrāticus","letter":"p","pos":"","posGroup":"other","english":"of pirates","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pirithous","latin":"Pīrithous, -ī","headword":"Pīrithous","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pirithous, friend of Theseus","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"pirum","latin":"pirum, -ī","headword":"pirum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"pear","forms":["pira","pirōrum","pirum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: 'In saccō eius {{pira}} īnsunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"piscator","latin":"piscātor, piscātōris","headword":"piscātor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) fisherman","forms":["piscātor","piscātōre","piscātōrī","piscātōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Piscātor}} quīdam, nōmine Glaucus, ōlim Anthēdonem, īnsulam Graecam, incolēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"piscina","latin":"piscina, piscinae","headword":"piscina","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"pool; fishpond; swiming pool, spa; tank, vat, basin","forms":["piscīnā","piscīnam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mitte tē ipsum in {{piscīnam}} subdīvālem!” [Forās exeunt et in piscīnam frīgidam sē mittunt.] [Iūlius, natāns:] “Natā!” [Gāius:] “Natāvī.” [Iūlius, cum Gāiō ē piscīnā ēgressus:] “Frīgidam habuimus bonam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"piscis","latin":"piscis, piscis","headword":"piscis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) fish","forms":["pisce","piscem","piscēs","piscibus","piscis","piscium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Paulō post pānem et duōs {{piscēs}} et pōculum aquae plēnum dominō affert.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"piscosus","latin":"piscosus, piscosa, piscosum","headword":"piscosus","letter":"p","pos":"adjective","posGroup":"adjective","english":"teeming with fish","forms":["piscōsīs","piscōsōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"piscósus--ā -um - plénus piscium cīnctaque {{piscōsīs}} Astypalaeā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"piso","latin":"Piso, Pisonis","headword":"Piso","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Piso; (Roman cognomen); [L. Calpurnius ~/M. Pupius ~ => consul 58/61 BC]","forms":["Pīsō","Pīsōnem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Pīsō, adulēscēns nōbilis, summae audāciae, egēns, factiōsus, quem ad perturbandam rem pūblicam inopia atque malī mōrēs stimulābant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"pistor","latin":"pistor, pistoris","headword":"pistor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pounder of far (emmer wheat); miller/baker","forms":["pistōrēs","pistōribus","pistōrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erant in eōdem carcere duo ministrī rēgis Pharaōnis: alter praeerat pincernīs, alter {{pistōribus}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pisum","latin":"pisum, pisi","headword":"pisum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"pea","forms":["pīsa","pīsum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In aditū autem ipsô stābat ôstiärius prasinātus, cerasinô succînctus cingulô, atque in lance argenteā {{pīsum}} pūrgā- bat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pius","latin":"pius, -a, -um","headword":"pius","letter":"p","pos":"adjective","posGroup":"adjective","english":"pious, reverent; dutiful, devoted, pious","forms":["pia","piae","piam","piē","piī","pīīs","piōrum","piōs","Pium","pius","PIVS"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi calamitāte ēdoctus scelerum veniam suppliciter ā Deō pefīvit et impetrāvit: in rēgnum restirūtus, Deum piē coluit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pix","latin":"pix, picis","headword":"pix","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"pitch, tar","forms":["pice","picem","pix"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et {{pice}} fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"placatus","latin":"placatus, placata, placatum","headword":"placatus","letter":"p","pos":"adjective","posGroup":"adjective","english":"kindly disposed; peaceful, calm","forms":["plācātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Varia deinceps fuit Hebraeōrum fortūna prō variīs eōrum mōribus: iī saepe in Deum peccāvērunt; tunc dīvīnō praesidiō dēstitūtī ab hostibus superābantur; quotiēs ad Deum conversī eius auxilium implōrāvērunt, {{plācātus}} Deus eōs līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"placenta","latin":"placenta, placentae","headword":"placenta","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"cake; kind of flat cake","forms":["placentā","placentam","placentās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Ferculum prîmum: duodecim signa caelestial] Laudätiônem ferculum est însecütum, plānē nôn prô oculôs: rotundum enim repositôrium duodecim habēbat signa in orbe disposita, super quae proprium conveniēn- temque māteriae strūctor imposuerat cibum: statēram in cuius alterâ parte scriblîta erat, in alterā placentā; In mediô autem caespes cum herbîs excîsus favum sustinēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"placeo","latin":"placeo, placere, placui, placitus","headword":"placeo","letter":"p","pos":"verb","posGroup":"verb","english":"please, satisfy, give pleasure to (with dat.)","forms":["placē","placeant","placeat","placēbant","placēbat","placēbit","placendī","Placentia","placeret","placēte","placuerat","placuerint","placuērunt","placuisse","placuissent","placuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Deliberatur de Avarico in communi concilio, incendi {{placeret}} an defendi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"placere","latin":"(placeō) placēre, placuisse,  placitum ({i}intr. + dat.{/i})","headword":"placēre","letter":"p","pos":"","posGroup":"other","english":"please","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"placet","latin":"placet, placere, -, placitus est","headword":"placet","letter":"p","pos":"verb","posGroup":"verb","english":"it is pleasing/satisfying, gives pleasure; is believed/settled/agreed/decided","forms":["placet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Gaudēbō, sī mēcum venīre voluerīs.” Cui Ganymēdēs “Eāmus,” respondit, “sī hoc tibi, summē Iuppiter, {{placet}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"placide","latin":"placide, placidius, placidissime","headword":"placide","letter":"p","pos":"adverb","posGroup":"adverb","english":"gently, calmly, gradually, peacefully, quietly; in a conciliatory manner","forms":["placidē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde placidē obiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"placidus","latin":"placidus, -a, -um","headword":"placidus","letter":"p","pos":"adjective","posGroup":"adjective","english":"quiet, calm, gentle; calm, gentle","forms":["plācidā","placidam","placidō","placidōs","placidum","placidus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ille fuit vēnātor strēnuus, hic autem {{placidus}} et simplex mōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"placito","latin":"placito, placitare, placitavi, placitatus","headword":"placito","letter":"p","pos":"verb","posGroup":"verb","english":"plead","forms":["placitō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iūre quidem anteā rēgēs Libyae tē petentēs dīmīsistī — etiamne placitō amōrī repugnābis?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"placitum","latin":"placitum, placiti","headword":"placitum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"plea","forms":["placitum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ALCVMENA: Ita dīvīs est {{placitum}}, voluptātem ut maeror comes cōnsequātur.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"placitus","latin":"placitus, -a, -um","headword":"placitus","letter":"p","pos":"adjective","posGroup":"adjective","english":"pleasing, agreeable","forms":["placitam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Proximus huic labor est {{placitam}} exōrāre puellam;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"placo","latin":"plācō, -āre, plācāvī, plācātum","headword":"plācō","letter":"p","pos":"verb","posGroup":"verb","english":"calm, appease","forms":["plācandam","plācāre","plācāret","plācārī","plācat","placent","placēre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Extimēscēbat īram frātris suī: ut {{plācāret}} animum eius, praemīsit ad eum nūntiōs, quī offerent eī mūnera.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plaga","latin":"plaga, plagae","headword":"plaga","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"|tract/region/quarter/zone/area; open expanse of country/sea/sky","forms":["plāgae","plāgam","plāgās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Moysēs, ut pharaōnis pertināciam vinceret, multa et stupenda ēdidit prōdigia, quae vocantur ‘{{plāgae}} Aegyptī’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plane","latin":"plānē","headword":"plānē","letter":"p","pos":"adverb","posGroup":"adverb","english":"plainly, clearly","forms":["plānē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Atque canis territus tam plānē dīcit litteram V” inquit iānitor, “Sed stultus est quod tonitrū terrētur.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"plango","latin":"plango, plangere, planxi, planctus","headword":"plango","letter":"p","pos":"verb","posGroup":"verb","english":"strike, beat; bewail; lament for, mourn","forms":["plānctū","plangere","plangit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ibi fūnus fēcērunt cum magnō plānctū, et sepeliērunt corpus in spēluncā ubi iacēbant Abrahāmus et Isaacus; reversīque sunt in Aegyptum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plangor","latin":"plangor, plangoris","headword":"plangor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"outcry, shriek","forms":["plangōribus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tēcta fremunt, resonat magnīs {{plangōribus}} aether,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"planities","latin":"planities, planitiei","headword":"planities","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"plain, plateau, a flat/plane/level surface; a plane (geometry); flatness","forms":["planitie","planitiem","planities"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Oppidi murus ab {{planitie}} atque initio ascensus recta regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum clivum accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"planta","latin":"planta, plantae","headword":"planta","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"cutting, heel, young shoot detached for propagation; seedling, young plant","forms":["plantās","plantīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tertiō diē coēgit aquās in ūnum locum, et ēdūxit ē terrā {{plantās}} et arborēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"planum","latin":"planum, plani","headword":"planum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"plan (drawing)","forms":["plānum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Mārcus vultum ā patre āvertit neque ūllum verbum respondet, at genua trementia et vultus pallidus respōnsum {{plānum}} sunt, quod pater facile intellegit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"planus","latin":"plānus, -a, -um","headword":"plānus","letter":"p","pos":"adjective","posGroup":"adjective","english":"level, clear; plain, clear; equal, level, even, flat","forms":["plāna","plānam","plāniōrem","plānīs","plānissimum","plānius","plānus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Canis īrātus r litteram {{plānius}} dīcit quam homō” inquit Tlēpolemus baculum tollēns, “Audī!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"platea","latin":"platea, plateae","headword":"platea","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"broad way, street","forms":["plateās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc īrātus pater familiās dīxit servō suō: “Exī citō in {{plateās}} et vīcōs cīvitātis, et pauperēs ac dēbilēs et caecōs et claudōs intrōdūc hūc!” 22 Et ait servus: “Domine, factum est ut imperāstī, et adhūc locus est.” 23 Et ait dominus servō: “Exī in viās et saepēs, et compelle intrāre, ut impleātur domus mea. 24 Dīcō autem vōbīs: quod nēmō virōrum illōrum quī vocātī sunt gustābit cēnam meam!”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"plato","latin":"Plato, Platonos/is","headword":"Plato","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Plato; (Greek philosopher 429-347 BC, disciple of Socrates)","forms":["Platō","Platōnem","Platōnis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diodōrus: “Multōs ‘bonōs librōs’ dīcere possum, sed in prīmīs librōs {{Platōnis}}, in quibus Sōcratem cum amīcīs colloquentem Platō -ōnis Sōcratēs -is facit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"plaudere","latin":"(plaudō) plaudere, plausisse, plausum  ({i}+ dat.{/i})","headword":"plaudere","letter":"p","pos":"verb","posGroup":"verb","english":"clap, applaud; to clap, applaud (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"plaudo","latin":"plaudō, -ere, plausī, plausum","headword":"plaudō","letter":"p","pos":"verb","posGroup":"verb","english":"applaud, clap","forms":["plaude","plaudēbat","plaudentem","plaudere","plaudite","plaudunt","plausū","plausum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed plerumque is qui victus est occiditur, victor vero palmam accipit, dum spectatores delectati clamant ac manibus {{plaudunt}}.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"plaustrum","latin":"plaustrum, plaustri","headword":"plaustrum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"wagon, cart, wain; constellation of Great Bear/Big Dipper","forms":["plaustra"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sed, postquam vīdit {{plaustra}} et dōna sibi ā Iōsēphō missa, recēpit animum; et: mihi satis est, inquit, sī vīvit adhūc Iōsēphus meus; ībō, et vidēbō eum antequam moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plausus","latin":"plausus, -ūs","headword":"plausus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"applause; applause, clapping","forms":["plausūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"in mediō plausū — {{plausūs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"plebecula","latin":"plebecula, plebeculae","headword":"plebecula","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"mob, common people","forms":["plēbēculā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"In Iōachae locum suffectus est Ioakim, quō rēgnante, Nabuchodonosor, B abylōniōrum rēx, Hierosolymam expugnāvit, cīvēs B abylōnem trānstulit, relicta vilī plēbēculā, cui prae:Iēcit Sedeciam postrēmum rēgem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plebeii","latin":"plēbēiī, -ōrum (pl.)","headword":"plēbēiī","letter":"p","pos":"","posGroup":"other","english":"plebians","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"plebeius","latin":"plebeius, plebeia, plebeium","headword":"plebeius","letter":"p","pos":"adjective","posGroup":"adjective","english":"plebeian","forms":["plēbēiōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aedēs Concordiae antīqua eō tempore aedificāta esse dīcitur cum post longam discordiam, quae populum Rōmānum dīvīserat in duās factiōnēs inter sē inimīcissimās, patriciōs et {{plēbēiōs}}, tandem concordia omnium collāpsam in meliōrem faciem restituit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"plebes","latin":"plebes, plebei","headword":"plebes","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"common people, general citizens, commons/plebeians; lower class/ranks; mob/mass","forms":["plēbēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Rōmae autem iīs fermē temporibus tribūnōs tum prīmum per sēditiōnem sibi {{plēbēs}} creāvit, ac nōn diū post Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"plebs","latin":"plēbs, -is ( f.)","headword":"plēbs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"the (common) people; the common people, the plebeians","forms":["plēbe","plebem","plebī","plēbis","plēbs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quibus profligatis, rursus oppidani perterriti comprehensos eos quorum opera {{plebem}} concitatam existimabant ad Caesarem perduxerunt seseque ei dediderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"plecto","latin":"plecto, plectere, plexi, plectus","headword":"plecto","letter":"p","pos":"verb","posGroup":"verb","english":"plait, twine","forms":["plectī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Id ubi rēx cognōvit, fīlium morte plectī voluit; sed recēns meritum perīculō iuvenem exēmit, nec populus tulit īnsontem ad supplicium trahī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plectrum","latin":"plectrum, plectri","headword":"plectrum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"quill/ plectrum/pick (to strike strings of musical instrument); keyboard key","forms":["plectrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sinistrā manū lyram gemmīs atque dentibus Indīs decorātam, dextrā manū {{plectrum}} tenuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"plenus","latin":"plēnus, -a, -um","headword":"plēnus","letter":"p","pos":"adjective","posGroup":"adjective","english":"(+ gen./abl.) full (of)","forms":["plēna","plēnae","plēnam","plēnās","pleni","plēnis","plēnissima","plēnius","plēnō","plēnōs","plēnum","plēnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Omnes alacres et fiduciae {{pleni}} ad Alesiam proficiscuntur, neque erat omnium quisquam qui aspectum modo tantae multitudinis sustineri posse arbitraretur, praesertim ancipiti proelio, cum ex oppido eruptione pugnaretur, foris tantae copiae equitatus peditatusque cernerentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"plerique","latin":"plērīque, plēraeque, plēraque","headword":"plērīque","letter":"p","pos":"adjective","posGroup":"adjective","english":"most; most, the majority","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"plerumque","latin":"plērumque","headword":"plērumque","letter":"p","pos":"adverb","posGroup":"adverb","english":"mostly; mostly, generally","forms":["plerumque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos {{plerumque}} introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"plerusque","latin":"plērusque, plera-, plerum-","headword":"plērusque","letter":"p","pos":"","posGroup":"other","english":"most (of ), the greater part","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"plinius","latin":"Plinius, Plini","headword":"Plinius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pliny; (Roman gens name)","forms":["Plīniō","Plīnius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Plīnius}} Trāiānō Imperātōrī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"plorat","latin":"plōrat","headword":"plōrat","letter":"p","pos":"verb","posGroup":"verb","english":"cry; cries, weeps","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ploro","latin":"plōrō, -āre, -āvī, -ātum","headword":"plōrō","letter":"p","pos":"verb","posGroup":"verb","english":"weep, mourn for","forms":["Plōrābat","plōrāns","plōrant","plōrante","plōrantem","plōrāre","plōrat","plōrāvērunt","plōrāvit","plōrō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Iūlia: “Nōn plōrō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pluit","latin":"pluit, pluere, pluvit, pluvitus est","headword":"pluit","letter":"p","pos":"verb","posGroup":"verb","english":"it rains","forms":["plūverat"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam rūs ut ībat forte, ut multum {{plūverat}}, ingressus fluvium rapidum ab urbe haud longulē, rapidus raptōrī puerī subdūxit pedēs abstrāxitque hominem in māximam mālam crucem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pluma","latin":"plūma, -ae","headword":"plūma","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"feather","forms":["plūmae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Extemplō Fāma per urbēs Libyae it, Fāma quā nōn aliud malum ūllum velōcius est — monstrum horrendum, ingēns, cui, quot sunt {{plūmae}} in corpore, tot vigilēs oculī sunt, tot linguae, tot aurēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"plumbum","latin":"plumbum, -ī","headword":"plumbum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"lead","forms":["plumbum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quamquam vērō, postquam prīmam ēmīsit, multīs aliīs sagittīs Chimaeram vulnerāvit, Bellerophōn eam interficere nōn poterat; longam igitur hastam, cuius in extrēmā parte {{plumbum}} addiderat, magnā vī in bēstiae os iniēcit; cum vērō ignis calōre, quī ex ōre ēmittēbātur, plumbum mollītum esset, horrenda illa fera, ustīs vīsceribus, inter maximōs dolōrēs mortua est et humī iacuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pluralis","latin":"plūrālis (numerus)","headword":"plūrālis","letter":"p","pos":"adjective","posGroup":"adjective","english":"plural (plūrālis and singulāris are adjectives of the 3rd declension; you will learn about these in Cap. XII); plural","forms":["plūrālis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Numerī nōminum quot sunt?' Discipulus: 'Duo.' Magister: 'Quī?' Discipulus: 'Singulāris, ut hic magister; {{plūrālis}}, ut hī magistrī.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"plures","latin":"plūres, plūra","headword":"plūres","letter":"p","pos":"adjective","posGroup":"adjective","english":"more","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"plurimi","latin":"plūrimī, -ae, -a","headword":"plūrimī","letter":"p","pos":"adjective","posGroup":"adjective","english":"most, a great many; very many, most","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"plurimum","latin":"plurimum, plurimi","headword":"plurimum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"most/great number of things; greatest amount; very much; the most possible","forms":["plūrimum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Est domī locus ad commorandum amplissmus; est etiam {{plūrimum}} foenī et paleārum ad ūsum camēlōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"plurimus","latin":"plurimus, plurima, plurimum","headword":"plurimus","letter":"p","pos":"adjective","posGroup":"adjective","english":"most, greatest number/amount; very many; most frequent; highest price/value","forms":["plūrimus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aurea sunt veré nunc saecula: {{plūrimus}} aurō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"plus","latin":"plūs","headword":"plūs","letter":"p","pos":"adverb","posGroup":"adverb","english":"(adv. + n. noun) more","forms":["pl","plūra","plurēs","pluribus","plūrīs","plūrium","plus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Esse non nullo se Caesaris beneficio adfectum, sic tamen ut iustissimam apud eum causam obtinuerit; sed {{plus}} communi libertati tribuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"plusquam perfectum","latin":"plūsquam perfectum, -i","headword":"plūsquam perfectum","letter":"p","pos":"","posGroup":"other","english":"(n.) pluperfect (tense)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"plusquamperfectum","latin":"plūsquamperfectum","headword":"plūsquamperfectum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"pluperfect (tense)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pluteus","latin":"pluteus, plutei","headword":"pluteus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"movable screen; breastwork, shed","forms":["pluteorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huic loricam pinnasque adiecit, grandibus cervis eminentibus ad commissuras {{pluteorum}} atque aggeris qui ascensum hostium tardarent, et turres toto opere circumdedit quae pedes LXXX inter se distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pluto","latin":"Plūtō, Plūtōnis","headword":"Plūtō","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pluto (god of the underworld)","forms":["Plūtō","Plūtōne","Plūtōnem","Plūtōnī","Plūtōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tum Alcēstis, quae Admētum tōtam rem nārrantem, parentēsque ‘sē nōlle prō eō morī’ dīcentēs exaudīverat, “Ō Ad mete, dīlēctissime coniūnx,” inquit “tē plūs quam vītam meam amō; sine morā parātissimā sum ad moriendum; {{Plūtōnis}} rēgnum prō tē petam, unde negant redīre quemquam; hoc ūnum tamen tē rogō, ut līberōs nostrōs etiam post mortem meam bene cūrēs et doceās; ōrō quoque nē meī, quae tantum tē amāvī, oblīvīscāris.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pluvia","latin":"pluvia, pluviae","headword":"pluvia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"rain, shower","forms":["pluvia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Simul {{pluvia}} ingēns cecidit per quadrāgintā diēs et totidem noctēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pluvius","latin":"pluvius, pluvia, pluvium","headword":"pluvius","letter":"p","pos":"adjective","posGroup":"adjective","english":"rainy, causing or bringing rain","forms":["pluviae","pluviās","pluvius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{pluvius}} -ā -um « pluvia -ae f^ imber; nec tepidus pluviās concitat","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"poculum","latin":"pōculum, -ī","headword":"pōculum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"cup; drinking cup, goblet; drinking cup, draught","forms":["pōcula","pōculō","pōculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hīc intrat Aemilia cum Syrā ancillā, quae {{pōculum}} fert plēnum sanguinis.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"podagra","latin":"podagra, podagrae","headword":"podagra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"gout","forms":["podagra"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Namque īnstat fātum mihi trīste, Sabellā quod puerō cecinit dīvīnā mōta anus urnā: Hunc neque dīra venēna nec hosticus auferet ēnsis, nec laterum dolor, aut tussis, nec tarda {{podagra}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"poema","latin":"poēma, -atis (n.)","headword":"poēma","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"poem","forms":["poēmata","poēmatis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Archilochum autem Nepōs Cornēlius trādit, Tullō Hostīliō Rōmae regnante, iam tunc fuisse {{poēmatis}} clārum et nōbilem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"poena","latin":"poena, -ae","headword":"poena","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"punishment; punishment, penalty","forms":["poenā","poenae","poenam","poenās","poenīs","Poenum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine {{poenae}} perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"poeniceus","latin":"poeniceus, poenicea, poeniceum","headword":"poeniceus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Phoenician","forms":["poenīceum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dum in hortīs cultīs errat, pōmum {{poenīceum}} dē arbore curvā carpserat et in ōre suō septem grāna presserat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"poenio","latin":"poenio, poenire, poenivi, poenitus","headword":"poenio","letter":"p","pos":"verb","posGroup":"verb","english":"punish (person/offense), inflict punishment; avenge, extract retribution","forms":["Poenī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn obtūnsa adeō gestāmus pectora Poenī,\nnec tam āversus equōs Tyriā Sōl iungit ab urbe.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"poenus","latin":"Poenus, Poeni","headword":"Poenus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Carthaginian; Phoenician; (specifically Hannibal)","forms":["Poenōrum","Poenōs","Poenus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Poenōs}} vīcit (annō 201 ā.C.)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"poeta","latin":"poēta, -ae","headword":"poēta","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) poet","forms":["poēta","poetae","poetam","poētārum","poetas","poētīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Orpheus nōbilissimus fidicen atque {{poēta}} ēgregius fuit, quī inde ā puerō tam pulchrē canēbat, ut nōn sōlum bēstiae ferae ad eum accurrerent, vērum etiam rapida flūmina cōnsisterent, nē strepitū cantum eius turbārent, ac saxa ipsa arborēsque (mīrābile vīsū!) ad audiendum venīrent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"poetica","latin":"poetica, poeticae","headword":"poetica","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"poetry; poetic art","forms":["poēticā"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Parturient montēs — nāscētur rīdiculus mūs! [Horātius: Dē arte poēticā, 139]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"poeticus","latin":"poēticus, -a, -um","headword":"poēticus","letter":"p","pos":"adjective","posGroup":"adjective","english":"poetical; poetic","forms":["poeticae"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Iulius, qui artis {{poeticae}} studiosus est, \"Ovidius ipse\" inquit \"id dicit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pol","latin":"Pol","headword":"Pol","letter":"p","pos":"interjection","posGroup":"interjection","english":"by Pollux; truly; really","forms":["pol"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"SOSIA: Aut {{pol}} haec praestigiātrīx mulier multō maxima est,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"polio","latin":"polio, polire, polivi, politus","headword":"polio","letter":"p","pos":"verb","posGroup":"verb","english":"smooth, polish; refine, give finish to","forms":["polīvī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post brevem prōlogum, quō poēta lēctōribus prōpōnit dōtem librī suī duplicem — id est dēlectāre atque admonēre —, fābella prīma nārrātur dē iūrgiō ācrī quod habuit lupus latrō cum agnō innocentī (Aesōpus Latīnus, fābula 3).] Aesōpus auctor quam māteriam repperit hanc ego polīvī versibus sēnāriīs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pollens","latin":"pollēns (gen. pollentis)","headword":"pollēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"strong, powerful","forms":["pollēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quī ubi prīmum adolēvit, {{pollēns}} vīribus, decōrā faciē, sed multō maximē ingeniō validus, nōn sē luxuī neque inertiae corrumpendum dedit, sed, utī mōs gentis illīus est, equitāre, iaculārī, cursū cum aequalibus certāre; et, cum omnēs glōriā anteīret, omnibus tamen cārus esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"polleo","latin":"polleo, pollere, -, -","headword":"polleo","letter":"p","pos":"verb","posGroup":"verb","english":"exert power or influence; be strong","forms":["pollēbat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cēterum nōbilitās factiōne magis {{pollēbat}}, plēbis vīs, solūta atque dispersa in multitūdine, minus poterat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pollere","latin":"(polleō) pollēre","headword":"pollēre","letter":"p","pos":"verb","posGroup":"verb","english":"be strong; to be strong, prevail","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"pollex","latin":"pollex, pollicis","headword":"pollex","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"thumb","forms":["pollice","pollicem","pollicēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"mōvit inaurātae {{pollice}} fīla lyrae.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"polliceor","latin":"polliceor, polliceri, pollicitus sum","headword":"polliceor","letter":"p","pos":"verb","posGroup":"verb","english":"promise","forms":["polliceantur","polliceātur","pollicēbātur","pollicendō","pollicentī","pollicentur","polliceor","pollicēre","pollicērentur","pollicērētur","pollicērī","pollicetur","pollicitōs","pollicitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos {{pollicentur}}; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"polliceri","latin":"(polliceor) pollicērī, pollicitum","headword":"pollicērī","letter":"p","pos":"verb","posGroup":"verb","english":"promise; to promise","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"pollicetur","latin":"pollicētur","headword":"pollicētur","letter":"p","pos":"verb","posGroup":"verb","english":"promises","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pollicitari","latin":"(pollicitor) pollicitārī","headword":"pollicitārī","letter":"p","pos":"","posGroup":"other","english":"promise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pollicitatio","latin":"pollicitātiō, -ōnis ( f.)","headword":"pollicitātiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"promise; promise, offer","forms":["pollicitationibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus {{pollicitationibus}} ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pollicitor","latin":"pollicitor, pollicitari, pollicitatus sum","headword":"pollicitor","letter":"p","pos":"verb","posGroup":"verb","english":"promise (assiduously)","forms":["pollicitandō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eā tempestāte exercitū nostrō fuēre complūrēs novī atque nōbilēs, quibus dīvitiae bonō honestōque potiōrēs erant, factiōsī domī, potentēs apud sociōs, clārī magis quam honestī; quī Iugurthae nōn mediocrem animum pollicitandō accendēbant, 'sī Micipsa rēx occidisset, fore utī sōlus imperiī Numidiae potīrētur: in ipsō maximam virtūtem, Rōmae omnia vēnālia esse!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pollicitum","latin":"pollicitum, polliciti","headword":"pollicitum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"promise","forms":["pollicitī","pollicitīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"“Ō Tarpēia” dīxērunt, “quamquam mala et improba fēmina nōbīs vidēris esse, dabimus tamen, ut pollicitī sumus, ea, quae in brāchiīs nostrīs sinistrīs gerimus!” Tarpēia laeta ad mīlitēs accessit; quī quidem rīdentēs in eam nōn armillās, sed gravissima sua scūta iēcērunt!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"polluere","latin":"(polluō) polluere, -uisse, -ūtum","headword":"polluere","letter":"p","pos":"","posGroup":"other","english":"soil, violate, degrate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"polluo","latin":"polluo, polluere, pollui, pollutus","headword":"polluo","letter":"p","pos":"verb","posGroup":"verb","english":"soil/foul/dirty/stain/pollute; infect (w/disease); make impure; break (fast)","forms":["polluere","polluī","pollūtum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"P ortae templī exustae erant, altāre {{pollūtum}}, virgulta in ātriīs, quasi in saltil, ēnatā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pollux","latin":"Pollux, Pollucis","headword":"Pollux","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pollux; (son of Tyndarus and Leda, twin of Castor)","forms":["Pollūce","Pollūcem","Pollūcī","Pollūcis","Pollūx"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Leucippī rēgis) à Castore et {{Pollūce}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"polus","latin":"polus, pola, polum","headword":"polus","letter":"p","pos":"adjective","posGroup":"adjective","english":"little; small; (only a) small amount/quantity of/little bit of","forms":["polī","polō","polus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intonuēre polī, et crēbrīs micat ignibus aether,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"polymitus","latin":"polymitus, polymita, polymitum","headword":"polymitus","letter":"p","pos":"adjective","posGroup":"adjective","english":"damasked, woven w/different colored threads; with many threads (L+S); weaving","forms":["polymitā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cēterum ad scindendum aprum nôn ille Ca1pūs ac- cessit quī altilia lacerāverat, sed barbātus ingēns, fasciîs crürâlibus alligātus et āliculā sub- ômâtus polymitā, strictôque vënätôriô cultrô latus aprî vehementer percussit ēvolāvērunt!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"polyphemus","latin":"Polyphemus, -ī","headword":"Polyphemus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Polyphemus, the Cyclops","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"polyphemusus","latin":"Polyphemusus, Polyphemi","headword":"Polyphemusus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Polyphemus; (Cyclops, son of Neptune, blinded by Ulysses)","forms":["Polyphēmum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vix haec dīxerat, cum ipsum {{Polyphēmum}} pastōrem caecum inter pecudēs suās ambulantem vīdērunt et lītora nōta petentem — cui mōnstrum horrendum, īnfōrme, ingēns, lūmen ademptum!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pomerium","latin":"pōmērium, -ī","headword":"pōmērium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"open space round town; sacred city boundary","forms":["pōmērium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Verberātō vel intrā {{pōmērium}} vel extrā pōmērium!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pompa","latin":"pompa, -ae","headword":"pompa","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"public procession; procession, parade","forms":["pompā","pompam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat Philistaeīs mōs, cum diēs fēstōs agerent, prōdūcere Samsōnem quasi in {{pompam}} pūblicam, captōque īnsultāre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pompeius","latin":"Pompeius, Pompei","headword":"Pompeius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pompeius; (Roman gens name); (Cn. Pompeius Magnus (Pompey), triumvir)","forms":["Pompei","Pompēiā","Pompēiī","Pompeiō","Pompēium","Pompēius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Pompei}} commodiorem in statum pervenisse intellegeret, in Transalpinam Galliam profectus est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pomum","latin":"pōmum, -ī","headword":"pōmum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"fruit, apple","forms":["pōma","pōmī","pōmīs","pōmō","pōmōrum","pōmum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ex eō tempore Tantalus, in Īnferōrum flūmine stāns, famē et sitī, quae nūllum habent fīnem, excruciātur: nam simul atque bibere cōnātur, aqua, quam haurīre vult, recēdit; et cum {{pōma}}, quae super caput sunt, sūmere cupit, ventus ea retrahit priusquam capiat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pondo","latin":"pondō","headword":"pondō","letter":"p","pos":"adverb","posGroup":"adverb","english":"in weight, pounds; by weight","forms":["pondō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cornēlium Rūfīnum, quī bis cōnsul et dictātor fuerat, senātū mōvērunt: causamque istī notae subscrīpsērunt 'quod eum comperissent argentī factī cēnae grātiā decem pondō lībrās habēre.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pondus","latin":"pondus, -eris (n.)","headword":"pondus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"weight","forms":["pondera","pondere","ponderis","pondus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi {{ponderis}} saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pone","latin":"pone","headword":"pone","letter":"p","pos":"preposition","posGroup":"preposition","english":"behind (in local relations) (rare)","forms":["pōne"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aemilia: “Age, sūme rosās meās vīgintī, Iūlia, eāsque in aquā {{pōne}}!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ponere","latin":"pōnere, -ō, posuī, positum","headword":"pōnere","letter":"p","pos":"verb","posGroup":"verb","english":"to put, place; take off","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ponit","latin":"pōnit","headword":"pōnit","letter":"p","pos":"verb","posGroup":"verb","english":"place, put, lay down; puts, places","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pono","latin":"pono, ponere, posui, positus","headword":"pono","letter":"p","pos":"verb","posGroup":"verb","english":"put/place/set; station/post (troops); pitch (camp); situate; set up; erect","forms":["pōnam","pōnāmus","pōnant","pōnat","pōnātur","ponebant","ponebantur","pōnēbat","pōnent","pōnere","pōnerent","pōnerentur","pōneret","pōnī","pōnis","pōnit","pōnite","pōnitō","pōnitur","pōnunt","posita","positae","positam","positās","positī","positis","positō","positum","positūrōs","positūrum","posuerant","posuerat","posueris","posuērunt","posuī","posuissem","posuisset","posuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret {{positum}} esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pons","latin":"pōns, pontis (m.)","headword":"pōns","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"bridge","forms":["pons","pontem","pontes","pontibus","pontium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum {{pons}} fluminis Ligeris contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pontifex","latin":"pontifex, -icis (m.)","headword":"pontifex","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"high priest; priest; pontifex maximus","forms":["pontifex","pontifice","Pontificem","pontificēs","pontificī","pontificis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hunc IOiadās {{pontifex}} in templō clanculum aluit atque ēducāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ponto","latin":"ponto, pontonis","headword":"ponto","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"large flat boat, barge; punt; pontoon; ferry boat","forms":["pontō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prīmum ex suō rēgnō sīc Mithridātēs profūgit ex eōdem Pontō, quō Medēa illa quondam profūgisse dīcitur, quam praedicant in fugā frātris suī membra in iīs locīs quā sē parēns persequerētur dissipāvisse, ut eōrum collēctiō dispersa maerorque paternus celeritātem persequendī retardāret!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pontus","latin":"pontus, -ī","headword":"pontus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"sea","forms":["ponte","pontī","pontis","pontum","pontus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod {{pontis}} atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"poplus","latin":"poplus, popli","headword":"poplus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"people, nation, State; public, populace; (= populus)","forms":["poplō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nam cum Tēloboīs bellum est Thēbānō poplō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"populares","latin":"populārēs, -ium","headword":"populārēs","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"fellow citizens, one’s own people","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"populari","latin":"(populor) populārī","headword":"populārī","letter":"p","pos":"","posGroup":"other","english":"ravage, plunder","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"popularis","latin":"populāris, -is (m.)","headword":"populāris","letter":"p","pos":"adjective","posGroup":"adjective","english":"fellow citizen; of the people, popular; popular, of the people","forms":["populāre","populārēs","populāribus","populāris","populārium"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"praeda atque agrō adōriāque affēcit {{populārēs}} suōs","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"populariter","latin":"populariter","headword":"populariter","letter":"p","pos":"adverb","posGroup":"adverb","english":"in everyday language; in a manner designed to win popular support","forms":["populāriter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Homines enim {{populāriter}} annum tantummodo sōlis, id est ūnius astrī, reditū metiuntur; cum autem ad idem unde semel profecta sunt cūncta astra redierint eandemque tōtīus caelī dīscrīptiōnem longīs intervāllīs rettulerint, tum ille vērē vertēns \"annus\" appellārī potest, in quō vix dīcere audeō quam multa hominum saecula teneantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"populatus","latin":"populatus, populatus","headword":"populatus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"devastation; laying-waste","forms":["populātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posteā Pyrrhus, coniūnctīs sibi Samnītibus, Lūcānīs, Bruttiīs, Rōmam perrēxit, omnia ferrō ignīque vāstāvit, Campāniam {{populātus}} est, atque ad Praeneste vēnit, mīliāriō ab urbe octāvō decimō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"populo","latin":"populo, populare, populavi, populatus","headword":"populo","letter":"p","pos":"verb","posGroup":"verb","english":"ravage, devastate, lay waste; plunder; despoil, strip","forms":["populō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Salomōn populō vectīgal gravissimum imposuerat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"populor","latin":"populor, populari, populatus sum","headword":"populor","letter":"p","pos":"verb","posGroup":"verb","english":"ravage, devastate, lay waste; plunder; despoil, strip","forms":["populantur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde ad laevam versī, quia ā dextrā Tiberis eōs arcēbat, cum magnō pavōre agrestium {{populantur}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"populus","latin":"populus, -ī","headword":"populus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"the people (not a person); people","forms":["populi","populīs","populōrum","populōs","populum","populus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se {{populi}} Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"porcus","latin":"porcus, -ī","headword":"porcus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pig; pig, swine","forms":["porcī","porcōs","porcum","porcus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Et abiit et adhaesit um cīvium regiōnis illīus quī mīsit illum in vīllam suam ut pāsceret {{porcōs}}.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"porrigere","latin":"(porrigō) porrigere (< regere)","headword":"porrigere","letter":"p","pos":"","posGroup":"other","english":"stretch out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"porrigo","latin":"porrigo, porrigere, porrexi, porrectus","headword":"porrigo","letter":"p","pos":"verb","posGroup":"verb","english":"stretch out, extend","forms":["porrēxī","porrēximus","porrēxit","Porrige","porrigēbam","porrigere","porrigis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Adamus respondit: mulier, quam dedistī mihi sociam, {{porrēxit}} mihi frūctum istum, ut ēderem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"porro","latin":"porrō","headword":"porrō","letter":"p","pos":"adverb","posGroup":"adverb","english":"forward, ahead","forms":["porrō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Haec porrō erant Iōsēphī somnia: ligābāmus, inquit, simul manipulōs in agrō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"porrus","latin":"porrus, porri","headword":"porrus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"leek","forms":["porrī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Inde domum mē ad porrī et ciceris referō laganīque catīnum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"porta","latin":"porta, -ae","headword":"porta","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"gate","forms":["porta","portae","portam","portarum","portas","portis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat {{portis}} incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"portat","latin":"portat, portant","headword":"portat","letter":"p","pos":"verb","posGroup":"verb","english":"carry; carries","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"portatio","latin":"portatio, portationis","headword":"portatio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"conveyance","forms":["portātiōnibus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Namque illī quōs ante Catilīnā dīmīserat incōnsultē velutī per dēmentiam cūncta simul agēbant: nocturnīs cōnsiliīs, armōrum atque tēlōrum {{portātiōnibus}}, nandō, agitandō omnia, plūs timōris quam perīculī effēcerant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"portendere","latin":"(portendō) portendere (< tendere)","headword":"portendere","letter":"p","pos":"","posGroup":"other","english":"portend, presage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"portendo","latin":"portendo, portendere, portendi, portentus","headword":"portendo","letter":"p","pos":"verb","posGroup":"verb","english":"predict, foretell; point out","forms":["portendēbātur","portendērunt","portendī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quam ob causam Iōsēphus erat invīsus suīs frātribus, praesertim postquam nārrāvisset eīs duplex somnium, quō futūra eius magnitūdō {{portendēbātur}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"portentum","latin":"portentum, -ī","headword":"portentum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"portent, prodigy","forms":["portenta","portentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ego putābam petauristäriôs intrāsse, et porcôs, sîcut in circulîs môs est, {{portenta}} aliquā factürôs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"porticus","latin":"porticus, -ūs ( f.)","headword":"porticus","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"portico, colonnade; colonnade, portico","forms":["porticibus","porticū","porticum","porticūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Octàvia, Augustī soror, {{porticum}} dē-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"portio","latin":"portio, portionis","headword":"portio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"part, portion, share; proportion; [pro portione => proportionally]","forms":["portiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et dīxit adolēscentior patrī: ' P āter, dā mihi {{portiōnem}} substantiae quae mē contingit. ' Et pater dīvīsit illī substantiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"porto","latin":"porto, portare, portavi, portatus","headword":"porto","letter":"p","pos":"verb","posGroup":"verb","english":"carry, bring","forms":["portābant","portābat","portābit","portābō","portābunt","portāmus","portāns","portant","portantēs","portantibus","portantur","portāre","portāret","portārētur","portārī","portat","portāte","portātis","portātur","portātūrum","portātus","portāvit","portō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Via quae est inter Tūsculum et vīllam Iūliī nōn tam longa est quam via Latīna, sed servī quattuor quī Tūsculō ad vīllam ambulant fessī sunt, quia lectīcam et saccōs {{portant}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"portuosus","latin":"portuōsus, -a, -um","headword":"portuōsus","letter":"p","pos":"adjective","posGroup":"adjective","english":"having many harbors; full of harbours","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"portus","latin":"portus, -ūs","headword":"portus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) harbor; harbour, port; harbour","forms":["portū","portum","portūs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"In portū Ōstiēnsī bona nāvis nōs opperītur, atque ventus secundus est.” neque amīcam Rōmae habeō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"poscere","latin":"poscere","headword":"poscere","letter":"p","pos":"verb","posGroup":"verb","english":"to request, demand","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"poscit","latin":"poscit, poscere","headword":"poscit","letter":"p","pos":"verb","posGroup":"verb","english":"demand, call for; asks for, demands","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"posco","latin":"posco, poscere, poposci, -","headword":"posco","letter":"p","pos":"verb","posGroup":"verb","english":"ask, demand","forms":["poposcērunt","poposcī","poposcisset","poposcit","posce","poscēbant","poscēbat","poscente","poscentem","poscere","poscētur","Poscimus","poscis","poscit","poscitur","poscō","poscunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res {{poscere}} videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"positivus","latin":"positīvus","headword":"positīvus","letter":"p","pos":"adjective","posGroup":"adjective","english":"(gradus) positive degree; positive (degree)","forms":["positīvī","positīvō","Positīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Comparātiōnis gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: '{{Positīvus}}, ut doctus; comparātīvus, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat quālitātem aut quantitātem significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"positus","latin":"positus, positus","headword":"positus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"situation, position; arrangement","forms":["positus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Postquam bellum in Urbem nūntiātum est, Rōmānī exercitum parāvērunt ut Urbs, quae mūris et flūmine iam satis dēfēnsa eīs vidēbātur, etiam armīs dēfenderētur; via tamen hostibus patēbat, nam pōns super flūmen {{positus}} erat, per quem facile Rōmam intrāre poterant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"possessio","latin":"possessiō, -ōnis ( f.)","headword":"possessiō","letter":"p","pos":"","posGroup":"other","english":"possession, occupation","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"possessivum","latin":"possessīvum","headword":"possessīvum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"possessive","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"possideo","latin":"possideō, possidēre","headword":"possideō","letter":"p","pos":"verb","posGroup":"verb","english":"possess","forms":["possēdit","posside","possideam","possidēbam","possidēbat","possidēbō","possidēns","possident","possideō","possidēret","possidet"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Omnēs rēs meās vēndam praeter librōs: etiam sī nihil aliud possidēbō, parvō bene vīvere poterō.” parvum -ī","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"possidere","latin":"possidēre","headword":"possidēre","letter":"p","pos":"verb","posGroup":"verb","english":"to own, possess","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"possidet","latin":"possidet","headword":"possidet","letter":"p","pos":"verb","posGroup":"verb","english":"owns, possesses","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"possum","latin":"possum, posse, potuī","headword":"possum","letter":"p","pos":"verb","posGroup":"verb","english":"can, be able","forms":["posse","possem","possēmus","possent","possēs","posset","possim","possīmus","possint","possīs","possit","possītis","possum","possumus","possunt","poteram","poterant","poterat","poterimus","poteris","poterit","poteritis","poterō","poterunt","potes","potest","potestis","potuerant","potuerat","potuerint","potuerīs","potuerunt","potuī","potuimus","potuisse","potuissēmus","potuissent","potuissēs","potuisset","potuistī","potuistis","potuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire {{posse}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"post","latin":"post","headword":"post","letter":"p","pos":"preposition; adverb","posGroup":"preposition","english":"(prp. + acc.) behind, after, later; after, behind (with acc.); after (+ acc.); after, afterwards","forms":["post"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem {{post}} se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"postea","latin":"posteā","headword":"posteā","letter":"p","pos":"adverb","posGroup":"adverb","english":"after; afterwards, thereafter, after that","forms":["postea"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dum longius ab munitione aberant Galli, plus multitudine telorum proficiebant; {{postea}} quam propius successerunt, aut se stimulis inopinantes induebant aut in scrobes delati transfodiebantur aut ex vallo ac turribus traiecti pilis muralibus interibant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"posteaquam","latin":"posteāquam","headword":"posteāquam","letter":"p","pos":"conjunction","posGroup":"conjunction","english":"afterward, since","forms":["posteāquam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ad Alpēs {{posteāquam}} vēnit, quae Ītaliam ā Galliā sēiungunt, quās nēmō umquam cum exercitū ante eum — praeter Herculem Graium — trānsierat (quō factō is hodiē saltus 'Graius' appellātur), Alpicōs cōnantēs prohibēre trānsitū concīdit, loca patefēcit, itinera mūnīvit, effēcit ut ea elephantus ōrnātus īre posset quā anteā ūnus homō inermis vix poterat rēpere.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"posteri","latin":"posterī, -ōrum (m. pl.)","headword":"posterī","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"descendants, posterity; descendants","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"posterior","latin":"posterior, -ius","headword":"posterior","letter":"p","pos":"","posGroup":"other","english":"back, hind, later","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"posteritas","latin":"posteritās, -tātis ( f.)","headword":"posteritās","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"future, posterity; posterity, future generations","forms":["posteritātem","posteritātis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sermō autem omnis ille et angustiīs cingitur iīs regiōnum quās vidēs, nec umquam dē illō perennis fuit, et obruitur hominum interitū et oblīviōne {{posteritātis}} exstinguitur.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"posterius","latin":"posterius","headword":"posterius","letter":"p","pos":"adverb","posGroup":"adverb","english":"later, at a later day; by and by","forms":["posterius"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nē {{posterius}} in mē culpam cōnferās.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"posterus","latin":"posterus, -a, -um","headword":"posterus","letter":"p","pos":"adjective","posGroup":"adjective","english":"next, following; following, next","forms":["postera","posterī","posterior","posteriōre","posteriōrem","posteriōrēs","posteris","postero","posterōs","posterum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in {{posterum}} oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne noctu ex oppido profugerent, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"posthabeo","latin":"posthabeo, posthabere, posthabui, posthabitus","headword":"posthabeo","letter":"p","pos":"verb","posGroup":"verb","english":"esteem less, subordinate (to); postpone","forms":["posthabitā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"posthabitā coluisse Samō; hīc illius arma,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"posthac","latin":"posthāc","headword":"posthāc","letter":"p","pos":"adverb","posGroup":"adverb","english":"after this; from now on, hereafter","forms":["posthāc"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ego cūrābō nē {{posthāc}} neglegēns sīs nēve dormiās!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"posticum","latin":"postīcum, -ī","headword":"postīcum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"backdoor; back door","forms":["posticum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx ipse nocte mediā cum tribus cōnsciīs fugae per {{posticum}} aedium in propinquum cubiculō hortum atque inde, māceriam aegrē trānsgressus, ad mare pervēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"postis","latin":"postis, -is","headword":"postis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"door-post","forms":["poste","postem","postēs","postibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"At Samsōn mediā nocte surrēxit, vēnitque ad portam urbis, quam cum invēnisset clausam, umerīs sustulit cum {{postibus}} et serīs, atque in verticem montis vicīnī supportāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"postmodo","latin":"postmodo","headword":"postmodo","letter":"p","pos":"adverb","posGroup":"adverb","english":"afterwards, presently, later","forms":["postmodo"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Īnsequere! — et vōtī {{postmodo}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"postquam","latin":"postquam","headword":"postquam","letter":"p","pos":"conjunction","posGroup":"conjunction","english":"after, since; after, when","forms":["postquam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Postquam}} id difficilius fieri animadvertit, silentio e castris tertia vigilia egressus eodem quo venerat itinere Metiosedum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"postremo","latin":"postrēmō","headword":"postrēmō","letter":"p","pos":"adverb","posGroup":"adverb","english":"finally","forms":["postremo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Postremo}} in acie praestare interfici quam non veterem belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"postremum","latin":"postrēmum","headword":"postrēmum","letter":"p","pos":"adverb","posGroup":"adverb","english":"for the last time","forms":["postrēmum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In Iōachae locum suffectus est Ioakim, quō rēgnante, Nabuchodonosor, B abylōniōrum rēx, Hierosolymam expugnāvit, cīvēs B abylōnem trānstulit, relicta vilī plēbēculā, cui prae:Iēcit Sedeciam {{postrēmum}} rēgem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"postremus","latin":"postrēmus, -a, -um","headword":"postrēmus","letter":"p","pos":"adjective","posGroup":"adjective","english":"last; last, final","forms":["postrēma","postrēmus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Samūēl fuit {{postrēmus}} Hebraeōrum iūdex, eōrumque rēs in summā pāce et perpetuā tranquillitāte administrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"postridie","latin":"postrīdiē","headword":"postrīdiē","letter":"p","pos":"adverb","posGroup":"adverb","english":"on the following day","forms":["postrīdiē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postrīdiē Eliezer surgēns manē, dīxit parentibus Rebeccae: erus meus mē exspectat; dīmittite mē, ut redeam ad illum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"postulare","latin":"postulāre","headword":"postulāre","letter":"p","pos":"verb","posGroup":"verb","english":"demand, ask for","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"postulat","latin":"postulat","headword":"postulat","letter":"p","pos":"verb","posGroup":"verb","english":"demands, asks","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"postulatio","latin":"postulatio, postulationis","headword":"postulatio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"petition, request","forms":["postulātiō","postulātiōnem","postulātiōnī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Continuō Eliezer exposuit parentibus Rebeccae causam itineris susceptī, rogāvitque ut annuerent postulātiōnī suae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"postulatum","latin":"postulātum, -ī","headword":"postulātum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"demand","forms":["postulāta","postulātum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ego nōn veniō vīllam oppugnātum sīcut hostis, nec pecūniam {{postulātum}} veniō.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"postulo","latin":"postulō, postulāre","headword":"postulō","letter":"p","pos":"verb","posGroup":"verb","english":"demand","forms":["postulābant","postulābantur","postulābat","postulandum","postulant","postulante","postulantēs","postulāre","postulārent","postulāret","postulās","postulat","postulātē","postulāverat","postulāvēre","postulāverint","postulāvērunt","postulāvisse","postulāvit","postulent","postulet","postulō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tunc Aegyptiī, quōs premēbat egestās, adiērunt rēgem, {{postulantēs}} cibum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"potare","latin":"(pōtō) pōtāre, -āvisse, -ātum (or pōtum)","headword":"pōtāre","letter":"p","pos":"verb","posGroup":"verb","english":"drink; to drink","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"potens","latin":"potēns (gen. potēntis)","headword":"potēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"powerful, master(ing); powerful","forms":["potēns","potentem","potentēs","potentī","potentior","potentiorī","potentissimī","potentissimīs","potentissimus","potentium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{potēns}}; vōtī compos esse — vōtō pō-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"potentia","latin":"potentia, -ae","headword":"potentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"power; power, might","forms":["potentia","potentiae","potentiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae {{potentiae}} adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"potest","latin":"potest, possunt, posse","headword":"potest","letter":"p","pos":"verb","posGroup":"verb","english":"be able; can, is able; is able, can","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"potestas","latin":"potestās, potestātis","headword":"potestās","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) power, ability; power","forms":["potestās","potestate","potestatem","potestātēs","potestātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua oblata {{potestate}} omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"potio","latin":"pōtiō, pōtiōnis","headword":"pōtiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) drink","forms":["pōtiō","pōtiōne","pōtiōnēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tantalus, Iovis fīlius, cum nihil magis optāret quam {{pōtiōnēs}} et cibōs, inter deōrum convīvia hospes esse solēbat: ab ovō ūsque ad mala cum deīs cēnābat, quōs dē variīs rēbus fabulantēs audiēbat; omnēs igitur, cum illī praeter cēterōs fīdere solērent, etsī summīs dē rēbus cōnsilia interdum capiēbant, liberē tamen inter sē, eō praesente, loquēbantur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"potior","latin":"potior, -īrī, potītus sum","headword":"potior","letter":"p","pos":"verb","posGroup":"verb","english":"get possession of, possess (+ abl.); get possession of (+ abl.); to obtain, gain possession of (+ gen./abl.)","forms":["poterēmur","poti","potiar","potiāris","potiēbātur","potiēre","potior","potiōra","potiōrem","potiōrēs","potīrētur","potīrī","potītī","potītum","potitur","potitus","potiundī","potiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido {{potitur}}, perpaucis ex hostium numero desideratis quin cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"potiri","latin":"(potior) potīrī, potītum","headword":"potīrī","letter":"p","pos":"verb","posGroup":"verb","english":"get possession of (+ abl.); to seize, possess (with abl.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"potissimum","latin":"potissimum","headword":"potissimum","letter":"p","pos":"adverb","posGroup":"adverb","english":"preferably, especially","forms":["potissimum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam autem nāvēs suās opplētās cōnspexērunt serpentibus, novā rē perterritī, cum quid {{potissimum}} vītārent nōn vidērent, puppēs vertērunt sēque ad sua castra nautica rettulērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"potisus","latin":"potisus, potisa, potisum","headword":"potisus","letter":"p","pos":"adjective","posGroup":"adjective","english":"able, capable; possible; (early Latin potis sum becomes possum)","forms":["potis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"compos -{{potis}} adī - gen — possidēns,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"potito","latin":"potito, potitare, potitavi, potitatus","headword":"potito","letter":"p","pos":"verb","posGroup":"verb","english":"drink","forms":["pōtitāre","pōtitāvit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"quī Pterela {{pōtitāre}} solitus est rēx.'—Haec sīc dicam erae.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"potius","latin":"potius","headword":"potius","letter":"p","pos":"adverb","posGroup":"adverb","english":"rather","forms":["potius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cur enim {{potius}} Aedui de suo iure et de legibus ad Caesarem disceptatorem quam Romani ad Aeduos veniant?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"poto","latin":"poto, potare, potavi, potus","headword":"poto","letter":"p","pos":"verb","posGroup":"verb","english":"drink; drink heavily/convivially, tipple; swallow; absorb, soak up","forms":["pōtābitis","pōtantēs","pōtantibus","pōtat","pōtāverītis","pōtāvistī","poter","potu","pōtum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tālem ānulum {i}{{potu}}{/i} habet amīca tua Lȳdia.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pr","latin":"pr., abb.","headword":"pr","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"praetor (official elected by the Romans who served as a judge); abb. pr.","forms":["pr"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Mollibus in {{pr}}átis admūgit fēmina taurō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"prae","latin":"prae","headword":"prae","letter":"p","pos":"preposition","posGroup":"preposition","english":"before; (prp. + abl.) before, in front of, in comparison with","forms":["prae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam cum in minora castra operis perspiciendi causa venisset, animadvertit collem, qui ab hostibus tenebatur, nudatum hominibus, qui superioribus diebus vix {{prae}} multitudine cerni poterat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeacutus","latin":"praeacutus, praeacuta, praeacutum","headword":"praeacutus","letter":"p","pos":"adjective","posGroup":"adjective","english":"sharpened, pointed","forms":["praeacuta","praeacūtās","praeacuti","praeacutis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et {{praeacuta}} materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praebeo","latin":"praebeo, praebere, praebui, praebitus","headword":"praebeo","letter":"p","pos":"verb","posGroup":"verb","english":"present/show/put forward; offer; expose physically oneself; expose/submit/allow","forms":["praebē","praebeant","praebeat","praebēbat","praebēbō","praebente","praebēre","praebēret","praebet","praebitūrus","praebuēre","praebuerīs","praebuērunt","praebuimus","praebuisset","praebuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fāma dē adventū frātrum Iōsēphī ad aurēs rēgis pervēnit; quī dēdit eīs mūnera perferenda ad patrem cum hīs mandātīs: addūcite hūc patrem vestrum et omnem eius familiam, nec multum cūrātē supellectilem vestram, quia omnia quae opus erunt vōbīs {{praebitūrus}} sum, et omnēs opēs Aegyptī vestrae erunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praebere","latin":"(praebeō) praebēre, -uisse, -itum","headword":"praebēre","letter":"p","pos":"","posGroup":"other","english":"present, offer, show","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praecedere","latin":"(praecēdō) praecēdere (< cēdere)","headword":"praecēdere","letter":"p","pos":"","posGroup":"other","english":"go on ahead, precede","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praecedo","latin":"praecedo, praecedere, praecessi, praecessus","headword":"praecedo","letter":"p","pos":"verb","posGroup":"verb","english":"go before, precede; surpass, excel","forms":["praecēdam","praecēdentibus","praecēdere","Praecēdite","praecēdunt"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hinc, involūtus coccinā gausapā, lectīcae impositus est, {{praecēdentibus}} phalerātis cursôribus quattuor et chîra- maxiô in quô dēliciae eius vehēbantur, puer vetulus, lippus, dominô Trimalchī- ône dëfôrmior.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"praeceps","latin":"praeceps (gen. praecipitis)","headword":"praeceps","letter":"p","pos":"adjective","posGroup":"adjective","english":"headlong, precipitous; headlong, steep","forms":["praeceps","praecipitī","praecipitīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeceptor","latin":"praeceptor, praeceptoris","headword":"praeceptor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"teacher, instructor","forms":["praeceptor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ut cessāvit loquī, dīxit Simonī:\"Due in altum, et laxātē rētia.\"Respondit Simōn:\"{{Praeceptor}}, tōtam noctem labōrāvimus, sed nihil cēpimus; tamen, sīcut dixisfī, laxābō rēte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeceptum","latin":"praeceptum, -ī","headword":"praeceptum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"instruction, order; order, instruction","forms":["praecepta","praeceptīs","praeceptō","praeceptum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono tubae, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare {{praeceptum}}, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praecido","latin":"praecido, praecidere, praecidi, praecisus","headword":"praecido","letter":"p","pos":"verb","posGroup":"verb","english":"cut off in front; cut back, cut short","forms":["Praecīde","praecidī","praecīdit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem probrīs ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī {{praecīdit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praecipere","latin":"(praecipiō) praecipere (< capere)","headword":"praecipere","letter":"p","pos":"","posGroup":"other","english":"anticipate, advise, order","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praecipio","latin":"praecipio, praecipere, praecepi, praeceptus","headword":"praecipio","letter":"p","pos":"verb","posGroup":"verb","english":"take or receive in advance; anticipate; warn; order; teach, instruct","forms":["praeceperat","praecēpit","praeceptam","praeciperet","praecipiam","praecipientis","praecipit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione {{praeceperat}}, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praecipitare","latin":"(praecipitō) praecipitāre","headword":"praecipitāre","letter":"p","pos":"","posGroup":"other","english":"throw, fall, rush headlong","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praecipito","latin":"praecipito, praecipitare, praecipitavi, praecipitatus","headword":"praecipito","letter":"p","pos":"verb","posGroup":"verb","english":"throw headlong, cast down","forms":["praecipitabantur","praecipitandum","praecipitāns","praecipitantur","praecipitāre","praecipitat","praecipitāvērunt","praecipitāvisse","praecipitāvit","praecipitent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fabius centurio quique una murum ascenderant circumventi atque interfecti muro {{praecipitabantur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praecipue","latin":"praecipuē","headword":"praecipuē","letter":"p","pos":"adverb","posGroup":"adverb","english":"especially","forms":["praecipue"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati {{praecipue}} indulserat, nulla interposita dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praecipuus","latin":"praecipuus, -a, -um","headword":"praecipuus","letter":"p","pos":"adjective","posGroup":"adjective","english":"outstanding, exceptional","forms":["praecipua","praecipuae","praecipuam","praecipuum","praecipuus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"opus {{praecipuae}} artis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"praecisus","latin":"praecisus, praecisa, praecisum","headword":"praecisus","letter":"p","pos":"adjective","posGroup":"adjective","english":"abrupt, precipitous; clipped, staccato","forms":["praecīsīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum comprehēnsus est secundus, et post dētractam capitis cutem cum capillls, interrogātus num vellet camem oblātam edere, negāvit sē id factūrum: quāpropter {{praecīsīs}} membrīs, in ōllam ārdentem missus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeclarus","latin":"praeclārus, -a, -um","headword":"praeclārus","letter":"p","pos":"adjective","posGroup":"adjective","english":"splendid, excellent; famous, splendid","forms":["praeclāra","praeclāram","praeclārī","praeclārō","praeclārum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Praeclārum}} Eleazarī exemplum secūta est mulier quaedam cum septem fīliīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeco","latin":"praecō, -ōnis (m.)","headword":"praecō","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"crier, announcer, herald; herald, crier","forms":["praecō","praecōnem","praecōnis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inde, omnibus perculsīs pavōre, in rēgiā sēde prō cūriā sedēns patrēs in cūriam per {{praecōnem}} \"ad rēgem Tarquinium\" cōgī iussit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praeconium","latin":"praeconium, praeconi(i)","headword":"praeconium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"praise, celebrating; proclamation, publication; office of public crier","forms":["praecōniā","praecōnium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{praecōnium}} -T/—- magnaāus dēlectant etiam castàs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"praecordia","latin":"praecordia, praecordiae","headword":"praecordia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"midriff; diaphragm; P:breast","forms":["praecordia"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Platō triplicem fīnxit animum, cuius principātum, id est ratiōnem, in capite sīcut in arce posuit, et duās partēs eī pārēre voluit, īram et cupiditātem, quās suīs locīs, īram in pectore, cupiditātem subter {{praecordia}} locāvit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"praecorrumpo","latin":"praecorrumpo, praecorrumpere, praecorrupi, praecorruptus","headword":"praecorrumpo","letter":"p","pos":"verb","posGroup":"verb","english":"pre-bribe; bribe in advance","forms":["praecorrumpere"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dum tamen hanc sperat, dum {{praecorrumpere}} dōnīs\nmē cupit, \"ēlige\" ait \"virgō Cūmaea, quid optēs:\noptātīs potiēre tuīs.\" Ego pulveris haustī\nostendī cumulum: quot habēret corpora pulvis,\ntot mihi nātālēs contingere vāna rogāvī;\nexcidit, ut peterem iuvenēs quoque prōtinus annōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"praecurro","latin":"praecurro, praecurrere, praecucurri, praecursus","headword":"praecurro","letter":"p","pos":"verb","posGroup":"verb","english":"run before, hasten on before; precede; anticipate","forms":["praecucurristī","praecucurrit","praecurrerent","praecurreret"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate {{praecurreret}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeda","latin":"praeda, -ae","headword":"praeda","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"booty, prey; booty, plunder","forms":["praeda","praedae","praedam","praedās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Oppidum diripit atque incendit, {{praedam}} militibus donat, exercitum Ligerim traducit atque in Biturigum fines pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praedari","latin":"(praedōr) praedārī","headword":"praedārī","letter":"p","pos":"","posGroup":"other","english":"plunder, loot","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praedatorius","latin":"praedātōrius, -a, -um","headword":"praedātōrius","letter":"p","pos":"","posGroup":"other","english":"plundering","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praedicare","latin":"(praedicō) praedicāre","headword":"praedicāre","letter":"p","pos":"","posGroup":"other","english":"declare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praedicere","latin":"(praedīcō) praedīcere (< dīcere)","headword":"praedīcere","letter":"p","pos":"","posGroup":"other","english":"foretell, prophesy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praedico","latin":"praedico, praedicere, praedixi, praedictus","headword":"praedico","letter":"p","pos":"verb","posGroup":"verb","english":"say beforehand, mention in advance; warn/predict/foretell; recommend/prescribe","forms":["praedicant","praedicāre","praedicās","praedicat","praedicātūrus","praedīcēbat","praedīcentī","praedicēs","praedicō","praedīxeram","praedīxerant","praedīxerat","praedīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Captīvitās Babylōnica per septuāgintā annōs dūrāvit, idque {{praedīxerat}} Deus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praedictum","latin":"praedictum, -ī","headword":"praedictum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"prediction, prophecy","forms":["praedicta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multa praetereā vātum {{praedicta}} eam terrēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praeditus","latin":"praeditus, praedita, praeditum","headword":"praeditus","letter":"p","pos":"adjective","posGroup":"adjective","english":"gifted; provided with","forms":["praeditās","praeditī","praeditus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Puer crēscēbat egregiā {{praeditus}} indole, eratque Deō et hominibus cārus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praedium","latin":"praedium, -ī","headword":"praedium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"estate; estate, country property","forms":["praedi","praediō","praedium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dominus autem gregis ex urbe in {{praedium}} suum venit, quia voluit aspicere agricolās et pāstōrēs suōs quī in agrīs et campīs opus faciēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"praedives","latin":"praedīves, (gen. -itis)","headword":"praedīves","letter":"p","pos":"adjective","posGroup":"adjective","english":"very rich","forms":["praedīves"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipse Mummius abstinentissimum virum ēgit, nec quicquam ex iīs operibus ōrnāmentīsque quae {{praedīves}} Corinthos habuit in domum eius pervēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praedo","latin":"praedō, praedōnis","headword":"praedō","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) robber, pirate; pirate; pirate, robber","forms":["praedantium","praedārī","praedātum","praedōne","praedōnēs","praedōnibus","praedōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus {{praedantium}} militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeduco","latin":"praeduco, praeducere, praeduxi, praeductus","headword":"praeduco","letter":"p","pos":"verb","posGroup":"verb","english":"extend; construct","forms":["praedūc","Praedūcere","praeduxerant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"A medio fere colle in longitudinem, ut natura montis ferebat, ex grandibus saxis sex pedum murum, qui nostrum impetum tardaret {{praeduxerant}} Galli atque inferiore omni spatio vacuo relicto superiorem partem collis usque ad murum oppidi densissimis castris compleverant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeeo","latin":"praeeo, praeire, praeivi(ii), praeitus","headword":"praeeo","letter":"p","pos":"verb","posGroup":"verb","english":"go before, precede; dictate","forms":["praeeunte","praeībat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illīs ēgredientibus {{praeībat}} columna nūbis interdiū, et columna ignis noctū, quae esset dux viae; nec umquam per quadrāgintā annōs dēfuit illā columnā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeesse","latin":"(praesum) praeesse, praefuisse ({i}intr. + dat{/i}.)","headword":"praeesse","letter":"p","pos":"verb","posGroup":"verb","english":"be in charge over; to be in charge of (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"praefectura","latin":"praefectura, praefecturae","headword":"praefectura","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"command; office of praefectus","forms":["praefectūrā"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eōdem autem et ipsī, sine cuiusquam suspīciōne, multōs fortēs virōs ēdūxerant, et ego ex praefectūrā Reātīnā complūrēs dēlēctōs adulēscentēs, quōrum opera ūtor assiduē in reī pūblicae praesidiō, cum gladiīs miseram.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"praefectus","latin":"praefectus, -ī","headword":"praefectus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"prefect, commander","forms":["praefecti","praefectō","praefectōs","praefectum","praefectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tres nobilissimi Aedui capti ad Caesarem perducuntur: Cotus, {{praefectus}} equitum, qui controversiam cum Convictolitavi proximis comitiis habuerat, et Cavarillus, qui post defectionem Litavicci pedestribus copiis praefuerat, et Eporedorix, quo duce ante adventum Caesaris Aedui cum Sequanis bello contenderant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praefero","latin":"praefero, praeferre, praetuli, praelatus","headword":"praefero","letter":"p","pos":"verb","posGroup":"verb","english":"carry in front; prefer; display; offer; give preference to","forms":["praeferēbant","praeferēbat","praeferō","praeferre","praeferrī","praelātum","praetulistī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum ēiēcit Adamum et Ēvam ex hortō, ut ille coleret terram, et collocāvit Angelum, quī {{praeferēbat}} manū gladium igneum, ut cūstōdīret aditum Paradīsī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeferre","latin":"(praeferō) praeferre, praetulisse, praelātum","headword":"praeferre","letter":"p","pos":"verb","posGroup":"verb","english":"prefer; to prefer","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"praeficere","latin":"(praeficiō) praeficere (< facere)","headword":"praeficere","letter":"p","pos":"","posGroup":"other","english":"put in charge of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praeficio","latin":"praeficio, praeficere, praefeci, praefectus","headword":"praeficio","letter":"p","pos":"verb","posGroup":"verb","english":"put in charge, place in command (with ACC and DAT)","forms":["praefecerat","praefēcit","praefectū","praefice","praeficere","praeficeretur","praeficiendō","praeficiendum","praeficit","praeficiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis {{praeficit}}; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praemetuo","latin":"praemetuo, praemetuere, -, -","headword":"praemetuo","letter":"p","pos":"verb","posGroup":"verb","english":"fear beforehand","forms":["praemetuens"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Caesar, cum iniquo loco pugnari hostiumque augeri copias videret, {{praemetuens}} suis ad T.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praemittere","latin":"(praemittō) praemittere (< mittere)","headword":"praemittere","letter":"p","pos":"","posGroup":"other","english":"send in advance","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praemitto","latin":"praemitto, praemittere, praemisi, praemissus","headword":"praemitto","letter":"p","pos":"verb","posGroup":"verb","english":"send ahead or forward","forms":["praemiserat","praemīsisse","praemīsistī","praemīsit","praemissā","praemissam","praemissī","praemissis","praemissōs","praemissum","praemissus","praemittit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi nactus recentem equitatum, quem multis ante diebus eo {{praemiserat}}, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praemium","latin":"praemium, -ī","headword":"praemium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"reward","forms":["praemia","praemiis","praemio","praemiōrum","praemium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac {{praemiis}} deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praemonitus","latin":"praemonitus, praemonitus","headword":"praemonitus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"forewarning","forms":["praemonitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tandem, {{praemonitus}} ā sacerdōte, Samūēl respondit Deō vocantī: “Loquēre, Domine: audit enim servus tuus.” Tum Deus Samūēlī: “Ego” ait “afficiam domum Hēlī iīs malīs, quae nēmō audīre possit, quīn eī ambae aurēs tinniant, proptereā quod in līberōs suōs plūs aequō indulgēns fuerit, illōrumque vitia nimium patienter tulerit.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praenestinus","latin":"Praenestinus, Praenestina, Praenestinum","headword":"Praenestinus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Proenestian; of Proeneste (Latium city, famous for roses)","forms":["Praenestīnōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"T. etiam Quīnctius Cincinnātus {{Praenestīnōs}}, quī usque ad urbis Rōmae portās cum bellō vēnerant, per sē secūtus ad flūmen Alliam vīcit, octō cīvitātēs, quae sub ipsīs agēbant, Rōmānīs adiūnxit, ipsum Praeneste aggressus in dēditiōnem accēpit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praenomen","latin":"praenōmen, praenōminis","headword":"praenōmen","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(n.) first name; first name, personal name","forms":["praenōmen","praenōmina","praenōmine"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Fīlium eius māiōrem dīcō, eum cui {{praenōmen}} est Mārcus.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"praenosco","latin":"praenōscō, -ere, praenōvī","headword":"praenōscō","letter":"p","pos":"verb","posGroup":"verb","english":"know beforehand","forms":["praenōscere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nōnne, inquit Iōsēphus, Deī sōlīus est {{praenōscere}} rēs futūrās?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praeoccupare","latin":"(praeoccupō) praeoccupāre","headword":"praeoccupāre","letter":"p","pos":"","posGroup":"other","english":"preoccupy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praeoccupo","latin":"praeoccupo, praeoccupare, praeoccupavi, praeoccupatus","headword":"praeoccupo","letter":"p","pos":"verb","posGroup":"verb","english":"seize upon beforehand; anticipate","forms":["praeoccuparentur","praeoccupāverat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quo timore perterriti Galli ne ab equitatu Romanorum viae {{praeoccuparentur}} consilio destiterunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeparare","latin":"(praeparō) praeparāre","headword":"praeparāre","letter":"p","pos":"","posGroup":"other","english":"prepare","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praeparo","latin":"praeparo, praeparare, praeparavi, praeparatus","headword":"praeparo","letter":"p","pos":"verb","posGroup":"verb","english":"prepare","forms":["praeparārent","praeparata","praeparātī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"At interiores, dum ea quae a Vercingetorige ad eruptionem {{praeparata}} erant proferunt, priores fossas explent, diutius in his rebus administrandis morati prius suos discessisse cognoverunt quam munitionibus appropinquarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeponere","latin":"(praepōnō) praepōnere, praeposuisse, praepositum","headword":"praepōnere","letter":"p","pos":"verb","posGroup":"verb","english":"put (acc.) before (dat.), in charge of; to put in charge of (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"praepono","latin":"praepono, praeponere, praeposui, praepositus","headword":"praepono","letter":"p","pos":"verb","posGroup":"verb","english":"place in command, in front of or before; put X (ACC) in front of Y (DAT)","forms":["praepōnere","praepōnit","praeposita","praeposuissent","praeposuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"auricomum sibi quī dīvum {{praepōnit}} amantī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"praepositio","latin":"praepositiō","headword":"praepositiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) preposition","forms":["praepositiō","praepositiōnēs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister discipulum interrogat: 'Partēs ōrātiōnis quot sunt?' Discipulus respondet: 'Octō.' Magister: 'Quae?' Discipulus: 'Nōmen, prōnōmen, verbum, adverbium, participium, coniūnctiō, praepositiō, interiectiō.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"praepositus","latin":"praepositus, praepositi","headword":"praepositus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"overseer; commander","forms":["praepositī","Praepositō","praepositus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ergō Pompēius, dux ēgregius, classī {{praepositus}} est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"praepotens","latin":"praepotēns (gen. praepotentis)","headword":"praepotēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"very powerful","forms":["praepotēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ardeam Rutulī habēbant, gens — ut in eā regiōne et in eā aetāte — dīvitiīs {{praepotēns}}; eaque ipsa causa bellī fuit, quod rēx Rōmānus cum ipse dītārī volēbat (exhaustō aerāriō magnificentia pūblicōrum operum), tum praedā lēnīre populārium animōs studēbat, quī sē in servilī opere tam diū habitōs ab rēge indignābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praeruptus","latin":"praeruptus, praerupta, praeruptum","headword":"praeruptus","letter":"p","pos":"adjective","posGroup":"adjective","english":"steep","forms":["praerupta","praeruptus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Interiores, desperatis campestribus locis propter magnitudinem munitionum, loca {{praerupta}} ex ascensu temptant; huc ea quae paraverant conferunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praescio","latin":"praescio, praescire, praescivi, praescitus","headword":"praescio","letter":"p","pos":"verb","posGroup":"verb","english":"foreknow; know in advance","forms":["praescīre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Respondimus ad ea quae scīscitābātur; nōn potuimus {{praescīre}} eum dictūrum esse: addūcite hūc frātrem vestrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praesens","latin":"praesēns, entis (tempus)","headword":"praesēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"present tense; (gen.praesentis) present","forms":["praesēns","praesentem","praesentēs","praesentī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Labienus milites cohortatus ut suae pristinae virtutis et secundissimorum proeliorum retinerent memoriam atque ipsum Caesarem, cuius ductu saepe numero hostes superassent, {{praesentem}} adesse existimarent, dat signum proeli.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesente","latin":"praesente, praesentis","headword":"praesente","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"present circumstance","forms":["praesente"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vīdit quīdam pendentem Absalōnem, nec ausus est illī manūs violentās īnferre, sed nūntiāvit Iōābō, quī eum increpāns: “Debuerās” inquit “iuvenem impium cōnfodere.” “Atquī” respondit ille “mē {{praesente}}, rēx praecēpit tibi, ut fīliō suō parcerēs.” “Ego vērō nōn parcam” ait Iōāb, et statim sūmpsit trēs lanceās, quās in pectus Absalōnis dēfīxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"praesentia","latin":"praesentia, praesentiae","headword":"praesentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"present time; presence","forms":["praesentia","praesentiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in {{praesentia}} obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesentio","latin":"praesentio, praesentire, praesensi, praesensus","headword":"praesentio","letter":"p","pos":"verb","posGroup":"verb","english":"feel or perceive beforehand; have a presentiment of","forms":["praesēnsit","praesentire"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fuit haec oratio non ingrata Gallis, et maxime, quod ipse animo non defecerat tanto accepto incommodo neque se in occultum abdiderat et conspectum multitudinis fugerat; plusque animo providere et {{praesentire}} existimabatur, quod re integra primo incendendum Avaricum, post deserendum censuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesentire","latin":"(praesentiō) praesentīre (< sentiō)","headword":"praesentīre","letter":"p","pos":"","posGroup":"other","english":"have a presentiment of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praesepio","latin":"praesepio, praesepire, praesepsi, praeseptus","headword":"praesepio","letter":"p","pos":"verb","posGroup":"verb","english":"block up/fence in front","forms":["praesēpiō","praesepto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Si illorum nuntiis confirmari non potestis omni aditu {{praesepto}}, his utimini testibus appropinquare eorum adventum; cuiusrei timore exterriti diem noctemque in opere versantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesertim","latin":"praesertim","headword":"praesertim","letter":"p","pos":"adverb","posGroup":"adverb","english":"especially","forms":["praesertim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat neve ab hostibus diripiantur, {{praesertim}} cum videat omne ad se bellum translatum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeservio","latin":"praeservio, praeservire, praeservivi, praeservitus","headword":"praeservio","letter":"p","pos":"verb","posGroup":"verb","english":"serve as slave","forms":["praeservīre"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ut {{praeservīre}} amantī meō possem patrī,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"praeses","latin":"praeses, -idis (m./f.)","headword":"praeses","letter":"p","pos":"noun","posGroup":"noun","english":"guardian","forms":["praesidi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Proinde, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius {{praesidi}} fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesideo","latin":"praesideo, praesidere, praesedi, -","headword":"praesideo","letter":"p","pos":"verb","posGroup":"verb","english":"keep/watch/stand//guard (over); preside (over); supervise/govern/control","forms":["praesidēbat"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Metellus Celer cum tribus legiōnibus in agrō Pīcēnō {{praesidēbat}}, ex difficultāte rērum eadem illa exīstimāns quae suprā dīximus Catilīnam agitāre.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"praesidium","latin":"praesidium, -ī","headword":"praesidium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"protection, aid, garrison; garrison, guard","forms":["praesidia","praesidiī","praesidiis","praesidio","praesidium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore ex hibernis egredi neque imperator sine {{praesidio}} ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesignis","latin":"praesignis, praesignis, praesigne","headword":"praesignis","letter":"p","pos":"adjective","posGroup":"adjective","english":"pre-eminent, outstanding","forms":["praesignis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Quae faciē {{praesignis}} erit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"praestans","latin":"praestans, praestantis (gen.), praestantior -or -us, praestantissimus -a -um","headword":"praestans","letter":"p","pos":"adjective","posGroup":"adjective","english":"excellent, outstanding (in quality/worth/degree/importance), surpassing all","forms":["praestāns","praestantissimō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pompēī Magnī in cōnsulātū secundō, contrā Parthōs missus est, et cum circā Carrhās contrā ōmen et auspicia dīmicāsset, ā Surēnā, Orōdis rēgis duce, victus ad postrēmum interfectus est cum fīliō, clārissimō et praestantissimō iuvene.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praestare","latin":"(praestō) praestāre, praestitisse","headword":"praestāre","letter":"p","pos":"verb","posGroup":"verb","english":"furnish, fulfill; furnish, fulfill, surpass; to perform, excel","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"praestat","latin":"praestat, praestare, praestitit, praestitus est","headword":"praestat","letter":"p","pos":"verb","posGroup":"verb","english":"it is better","forms":["praestat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cūr Lātōna mihi {{praestat}}?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"praestigiator","latin":"praestigiator, praestigiatoris","headword":"praestigiator","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"trickster, one who practices deceit; juggler; impostor, cheat, deceiver (L+S)","forms":["praestigiātor"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"AMPHITRYO: Nescioquis {{praestigiātor}} hanc frūstrātur mulierem.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"praestigiatrix","latin":"praestigiatrix, praestigiatricis","headword":"praestigiatrix","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"trickster; conjurer","forms":["praestigiātrīx"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: Aut pol haec {{praestigiātrīx}} mulier multō maxima est,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"praesto","latin":"praestō, -āre, -stitī, -stitum","headword":"praestō","letter":"p","pos":"verb","posGroup":"verb","english":"stand before, surpass (+ dat.)","forms":["praestābant","praestābit","praestābō","praestandō","praestandum","praestant","praestantem","praestantī","praestantibus","praestare","praestāret","praestent","praestet","praestitisse","praestitit","praestō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Postremo in acie {{praestare}} interfici quam non veterem belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praestolor","latin":"praestolor, praestolari, praestolatus sum","headword":"praestolor","letter":"p","pos":"verb","posGroup":"verb","english":"stand ready for, expect, wait for (w/DAT or ACC)","forms":["praestōlārentur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quamquam quid ego tē invītem, ā quō iam sciam esse praemissōs quī tibi ad Forum Aurēlium {{praestōlārentur}} armātī?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"praestringo","latin":"praestringo, praestringere, praestrinxi, praestrictus","headword":"praestringo","letter":"p","pos":"verb","posGroup":"verb","english":"bind or tie up; graze, weaken, blunt","forms":["praestringere"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum vērō sinistrā manū mentum sublevat, exīstimat sē gemmae nitōre et aurī splendōre aspectūs omnium {{praestringere}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"praestruo","latin":"praestruo, praestruere, praestruxi, praestructus","headword":"praestruo","letter":"p","pos":"verb","posGroup":"verb","english":"block up, contrive beforehand","forms":["praestrūxerat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hospitis effugiō {{praestrūxerat}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"praesum","latin":"praesum, praeesse, praefui, praefuturus","headword":"praesum","letter":"p","pos":"verb","posGroup":"verb","english":"be in charge/control/head (of) (w/DAT); take the lead (in); be present (at)","forms":["praeerant","praeerat","praeessent","praeest","praefuerat","praefuērunt","praefuit","praesum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fufium Citam, honestum equitem Romanum, qui rei frumentariae iussu Caesaris {{praeerat}}, interficiunt bonaque eorum diripiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praesumere","latin":"(praesūmō) praesūmere (< sūmere)","headword":"praesūmere","letter":"p","pos":"","posGroup":"other","english":"take for oneself, assume","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praesumo","latin":"praesumo, praesumere, praesumpsi, praesumptus","headword":"praesumo","letter":"p","pos":"verb","posGroup":"verb","english":"consume/perform/employ beforehand; anticipate; presuppose/presume/assume; dare","forms":["praesūme","Praesūmpsērunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"nēve domī {{praesūme}} dapēs, sed dēsine citrā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"praetendo","latin":"praetendo, praetendere, praetendi, praetentus","headword":"praetendo","letter":"p","pos":"verb","posGroup":"verb","english":"stretch out; spread before; extend in front; allege in excuse","forms":["praetendī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"praetendī taedās aut haec in foedera vēnī.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"praeter","latin":"praeter","headword":"praeter","letter":"p","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) past, besides, except; except, beyond (+ acc.)","forms":["praeter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Uno fere tempore sub lucem hostibus nuntiatur in castris Romanorum {{praeter}} consuetudinem tumultuari et magnum ire agmen adverso flumine sonitumque remorum in eadem parte exaudiri et paulo infra milites navibus transportari.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeterea","latin":"praetereā","headword":"praetereā","letter":"p","pos":"adverb","posGroup":"adverb","english":"besides; in addition, further, besides, moreover","forms":["praetereā"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Praeterea}} salutis causa rei familiaris commoda neglegenda: vicos atque aedificia incendi oportere hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praetereo","latin":"praetereo, praeterire, praeterivi(ii), praeteritus","headword":"praetereo","letter":"p","pos":"verb","posGroup":"verb","english":"pass/go by; disregard/neglect/omit/miss; surpass/excel; go overdue; pass over","forms":["praetereō","praetereunda","praetereunte","Praeteriēns","praeterīre","praeterīrent","praeterit","praeteritūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ac variis dictis sententiis, quarum pars deditionem, pars, dum vires suppeterent, eruptionem censebat, non {{praetereunda}} oratio Critognati videtur propter eius singularem et nefariam crudelitatem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeterire","latin":"praeterīre","headword":"praeterīre","letter":"p","pos":"verb","posGroup":"verb","english":"to go past, pass by","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"praeteritum","latin":"praeteritum, -ī (tempus)","headword":"praeteritum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"past (tense)","forms":["praeterita","praeteritīs","praeteritō","praeteritum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At ei qui Alesiae obsidebantur, {{praeterita}} die qua auxilia suorum exspectaverant, consumpto omni frumento, inscii quid in Aeduis gereretur, concilio coacto de exitu suarum fortunarum consultabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeteritus","latin":"praeteritus, -a, -um","headword":"praeteritus","letter":"p","pos":"adjective","posGroup":"adjective","english":"past; past, gone by","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"praetermitto","latin":"praetermitto, praetermittere, praetermisi, praetermissus","headword":"praetermitto","letter":"p","pos":"verb","posGroup":"verb","english":"let pass; pass over; omit; overlook","forms":["praetermissā","praetermissīs","praetermittendum","praetermittimus","praetermittō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eo cum Eporedorix Viridomarusque venissent et de statu civitatis cognovissent, Litaviccum Bibracte ab Aeduis receptum, quod est oppidum apud eos maximae auctoritatis, Convictolitavem magistratum magnamque partem senatus ad eum convenisse, legatos ad Vercingetorigem de pace et amicitia concilianda publice missos, non {{praetermittendum}} tantum commodum existimaverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeterquam","latin":"praeterquam","headword":"praeterquam","letter":"p","pos":"adverb","posGroup":"adverb","english":"except, besides","forms":["praeterquam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Atque ego hanc sententiam probarem (tantum apud me dignitas potest), si nullam {{praeterquam}} vitae nostrae iacturam fieri viderem; sed in consilio capiendo omnem Galliam respiciamus, quam ad nostrum auxilium concitavimus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praetervehi","latin":"(praetervehor) praetervehī (< vehere)","headword":"praetervehī","letter":"p","pos":"","posGroup":"other","english":"ride/drive/sail past","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praetervehor","latin":"praetervehor, praetervehi, praetervectus sum","headword":"praetervehor","letter":"p","pos":"verb","posGroup":"verb","english":"sail by, pass by, ride by; be born by","forms":["praetervehēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Lentulus tribūnus mīlitum, cum {{praetervehēns}} equō sedentem in saxō cruōre opplētum cōnsulem vīdisset, 'L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praetexo","latin":"praetexo, praetexere, praetexui, praetextus","headword":"praetexo","letter":"p","pos":"verb","posGroup":"verb","english":"weave in front, fringe; cloak (with); pretend","forms":["praetexere","praetexit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"coniugium vocat, hoc {{praetexit}} nōmine culpam.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"praetexta","latin":"praetexta, -ae","headword":"praetexta","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"toga with purple border; purple-bordered toga","forms":["praetextae","praetextam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nôn est mōrātus Stichus, sed et strāgulam albam et {{praetextam}} in triclînium attulit. (Quās Trimalchiô mîrätus est) iussitque nôs temptāre an bonīs länîs essent côn- fecta.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"praetextatus","latin":"praetextātus, -a, -um","headword":"praetextātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"wearing a toga praetexta","forms":["praetextātīs","praetextātōs","praetextātum","Praetextātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Tē rogô ut nāvēs etiam (in fronte) monumentî meî faciās plënîs vëlîs euntēs, et mē in tribünälî sedentem {{praetextātum}} cum änulîs aureîs quînque et nummôs in dedî: bînôs dënâriôs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"praetor","latin":"praetor, -ōris (m.)","headword":"praetor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"praetor (magistrate)","forms":["praetor","praetōre","praetōrem","praetōrēs","praetōribus","praetōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Trāditō palam tēlō custōdibus hostium, ad {{praetōrem}} Saguntīnum est dēductus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praetorium","latin":"praetōrium, -ī","headword":"praetōrium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"general’s tent","forms":["praetōria","praetōrium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum hōc Hasdrubale foedus renovāverat populus Rōmānus: 'ut fīnis utrīusque imperiī esset amnis Hibērus, Saguntīnīsque mediīs inter imperia duōrum populōrum lībertās servārētur.' In Hasdrubalis locum haud dubia rēs fuit quīnam successūrus esset, quia extemplō iuvenis Hannibal in {{praetōrium}} dēlātus imperātorque ingentī omnium clāmōre atque assēnsū appellātus erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praetorius","latin":"praetōrius, -a, -um","headword":"praetōrius","letter":"p","pos":"adjective","posGroup":"adjective","english":"of the commander; (m.) an expraetor; of the praetor; of the general","forms":["praetōriam","praetōriō","praetōriōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In {{praetōriam}} nāvem impōnī iussus, eōdem et pecūnia quae superfuit dēlāta est extemplōque classis Amphipolim repetiit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"praetorqueo","latin":"praetorqueo, praetorquere, praetorsi, praetortus","headword":"praetorqueo","letter":"p","pos":"verb","posGroup":"verb","english":"twist round","forms":["praetorquē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hīs mē cōnsōlor vīctūrum suāvius ac sī quaestor avus pater atque meus praetorquē fuissent.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"praetura","latin":"praetūra, -ae ( f.)","headword":"praetūra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"praetorship","forms":["praetūra"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Lentulus, cum sē {{praetūra}} abdicāsset, in cūstōdiam trāderētur; itemque utī C.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"praeustus","latin":"praeustus, praeusta, praeustum","headword":"praeustus","letter":"p","pos":"adjective","posGroup":"adjective","english":"burnt at the end; hardened by burning","forms":["praeusta","praeusti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos {{praeusta}} et praeacuta materia et pice fervefacta et maximi ponderis saxis morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"praeverbium","latin":"praeverbium, -ī","headword":"praeverbium","letter":"p","pos":"","posGroup":"other","english":"prefix","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"praeverto","latin":"praeverto, praevertere, praeverti, -","headword":"praeverto","letter":"p","pos":"verb","posGroup":"verb","english":"anticipate; preoccupy, attend to first; outstrip, outrun","forms":["praevertere","praevertier","praevertisse","praevertit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"nē 'mē uxōrem {{praevertisse}}' dīcant 'prae rē pūblicā.'","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"praevius","latin":"praevius, praevia, praevium","headword":"praevius","letter":"p","pos":"adjective","posGroup":"adjective","english":"going before, leading the way","forms":["praeviā","praevius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ecce, levēs Satyrī, praeviā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"prandeo","latin":"prandeo, prandere, prandi, pransus","headword":"prandeo","letter":"p","pos":"verb","posGroup":"verb","english":"eat one's morning or midday meal","forms":["prandē","prandeat","pranderam","prandēre","Prānsus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Blepharōnem arcessat, quī nōbīscum {{prandeat}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"prandium","latin":"prandium, prandi(i)","headword":"prandium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"lunch","forms":["prandium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diē quōdam fēstō, cum domī lautum convīvium parāvisset, mīsit fīlium ut aliquot ē sociīs ad {{prandium}} invītāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prasinus","latin":"prasinus, prasina, prasinum","headword":"prasinus","letter":"p","pos":"adjective","posGroup":"adjective","english":"leek-green","forms":["prasinā","prasini","prasinus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec tam puerî nôs (quamquam erat operae pretium!) ad spectāculum dūxerant quam ipse pater familiās, quî soleâtus pilā prasinā exercëbätm.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pratulum","latin":"prātulum, -ī","headword":"prātulum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"meadow, lawn","forms":["prātulō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dein, cum essent perpauca inter sē ūnō aut alterō spatiō collocūtī Scīpiōnīque eōrum adventus periūcundus et pergrātus fuisset, placitum est ut in apricō maximē prātulō locō, quod erat hībernum tempus annī, cōnsīderent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pratum","latin":"pratum, prati","headword":"pratum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"meadow, meadowland; meadow grass/crop; broad expanse/field/plain (land/sea)","forms":["prāta","prātō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum puerō lūdēbat Apollō prātō in apertō: corporibus nūdīs, agitantēs candida membra splendida mittēbant trāns āera pondera discī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"prave","latin":"prāvē","headword":"prāvē","letter":"p","pos":"adverb","posGroup":"adverb","english":"wrongly","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pravus","latin":"prāvus, -a, -um","headword":"prāvus","letter":"p","pos":"adjective","posGroup":"adjective","english":"faulty, wrong; wrong, perverse; crooked, wrong","forms":["prāvā","prāvam","prāvē","pravis","prāvōs","prāvum","prāvus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ex his Eporedorix cognito Litavicci consilio media fere nocte rem ad Caesarem defert; orat ne patiatur civitatem {{pravis}} adulescentium consiliis ab amicitia populi Romani deficere; quod futurum provideat, si se tot hominum milia cum hostibus coniunxerint, quorum salutem neque propinqui neglegere neque civitas levi momento aestimare posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"precari","latin":"(precor) precārī, precātum","headword":"precārī","letter":"p","pos":"verb","posGroup":"verb","english":"pray, beg; to pray, beg","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"precatur","latin":"precātur","headword":"precātur","letter":"p","pos":"verb","posGroup":"verb","english":"prays, begs","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"precatus","latin":"precatus, precatus","headword":"precatus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"prayer; request","forms":["precātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum, bene {{precātus}} rēgī, discessit ab eō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"preces","latin":"precēs, precum","headword":"precēs","letter":"p","pos":"","posGroup":"other","english":"(f. pl.) prayers","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"precor","latin":"precor, -ārī, -ātus sum","headword":"precor","letter":"p","pos":"verb","posGroup":"verb","english":"to pray, beg","forms":["precābātur","precābitur","precandō","precantem","precantēs","precantibus","precantum","precāre","precārer","precārī","precāris","precāta","precātī","precātur","precor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīmīsērunt ergō Rebeccam et nūtrīcem illīus, {{precantēs}} eī omnia prōspera.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prehendere","latin":"(prehendō) prehendere, prendisse,  prēnsum","headword":"prehendere","letter":"p","pos":"","posGroup":"other","english":"grab hold of","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"prehendo","latin":"prehendō, -ere, -hendī, -hēnsum","headword":"prehendō","letter":"p","pos":"verb","posGroup":"verb","english":"catch, seize, grasp","forms":["prehendant","prehendēns","prehendentem","prehendere","prehenderent","prehendī","prehendit","Prehendite","prehēnsam","prehēnsōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum tālia dīceret, ut fūmus in āera ē cōnspectū fūgit, neque Orphēum vidēre potuit frūstrā {{prehendentem}} umbrās, et multa volentem dīcere.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"premo","latin":"premō, premere","headword":"premō","letter":"p","pos":"verb","posGroup":"verb","english":"press","forms":["premant","premat","premebantur","premēbat","premenda","prementem","premere","premerent","premerentur","premeret","premerētur","premi","premimur","premis","premit","premitur","premō","premunt","pressa","presserat","pressisse","pressit","pressum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia {{premi}}, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prendo","latin":"prendo, prendere, prendi, prensus","headword":"prendo","letter":"p","pos":"verb","posGroup":"verb","english":"catch/capture; take hold of/possession of/in hand, arrest; occupy; seize/grasp","forms":["prēndēre","prēnsīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{prēndēre}} (: nōlīte dēprēndere) vēs-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"prenso","latin":"prenso, prensare, prensavi, prensatus","headword":"prenso","letter":"p","pos":"verb","posGroup":"verb","english":"grasp/clutch at/constantly; lay hold of; accost/buttonhole; canvass, solicit","forms":["prensantem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ultima cōnscendit classem — miserābile vīsū! — in mediīs Hecuba nātōrum inventa sepulcrīs: [eam] {{prensantem}} tumulōs atque ossibus ōscula dantem Graecōrum trāxēre manūs, tamen ūnius hausit inque sinū cinerēs sēcum tulit Hectoris haustōs; Hectoris in tumulō crīnem lacrimāsque relīquit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"presso","latin":"presso, pressare, pressavi, pressatus","headword":"presso","letter":"p","pos":"verb","posGroup":"verb","english":"press, squeeze","forms":["pressāre"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vellere coepī et {{pressāre}} manū lentissima bracchia, nūtāns, distorquēns oculōs, ut mē ēriperet.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pretiosus","latin":"pretiōsus, -a, -um","headword":"pretiōsus","letter":"p","pos":"adjective","posGroup":"adjective","english":"precious; precious, costly; precious, valuable; precious, expensive; costly","forms":["pretiōsa","pretiōsam","pretiōsās","pretiōsior","pretiōsiōra","pretiōsīs","pretiōsissima","pretiōsissimīs","pretiōsissimum","pretiōsō","pretiōsōs","pretiōsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Eliezer dēprōmpsit vās aurea et argentea, vestēsque {{pretiōsās}}, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pretium","latin":"pretium, -ī","headword":"pretium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"price, value; price; price, reward","forms":["preti","pretia","pretiī","pretiō","pretium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius ūnam rosam sūmit et puellam interrogat: “Quantum est {{pretium}} huius rosae?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"prex","latin":"prex, precis","headword":"prex","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(usually pl.) prayers","forms":["prece","precēs","precibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quorum ille {{precibus}} permotus castra ex Biturigibus movet in Arvernos versus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"priamus","latin":"Priamus, Priami","headword":"Priamus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Priam; (king of Troy, father of Hector and Paris)","forms":["Priamī","Priamō","Prīamum","Priamus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Orontēs: 'Sīcut Paris, rēgis Priamī fīlius dēbilis, quī ā servō rēgis fīdō in quōdam monte prope urbem Trōiam expositus...' At Cornēlius: 'Opus nōn est,' inquit, 'vetus exemplum Graecum afferre, cum complūrēs fābulae nārrentur dē Rōmānīs puerīs quī ita servātī sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pridem","latin":"prīdem","headword":"prīdem","letter":"p","pos":"adverb","posGroup":"adverb","english":"some time ago, previously","forms":["prīdem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At cum prīmum piscēs herbam tetigērunt, aliquid in exspectātum factum est: piscēs enim, quōs iam {{prīdem}} mortuōs esse oportuit, ut paulō ante in marī, sīc tunc in terrā movērī coepērunt; dein, piscātōre spectante, tōtus piscium grex, postquam ad vītam rediit, in maris undās celeriter fūgit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pridie","latin":"prīdiē","headword":"prīdiē","letter":"p","pos":"adverb","posGroup":"adverb","english":"the day before","forms":["prīdiē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce litterae novissimae, quās Aemilia prīdiē kalendās Iunīās ā frātre accēpit et posterō diē in convīviō recitāvit:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"primas","latin":"primas, (gen.), primatis","headword":"primas","letter":"p","pos":"adjective","posGroup":"adjective","english":"noble; of the highest rank; principle","forms":["prīmās"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Post aciēs {{prīmās}} urbis sē moenibus hostēs continuēre diū, nec apertī cōpia Martis ūlla fuit; decimō dēmum pugnāvimus annō; quid facis intereā, quī nīl nisi proelia nōstī?","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"primicerius","latin":"primicerius, primicerii","headword":"primicerius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"chief, head, superintendent; chief clerk; (first-named on wax tablet)","forms":["prīmicēriī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At ille sīmius māior ait illī quī fallāx erat: “Quid sum ego?” Fallāx dīxit: “Tū es Imperātor!” Iterum interrogāvit: “Et istī quōs ante mē stāre vidēs, quid sunt?” Īdem fallāx respondit: “Hī comitēs sunt tuī, prīmicēriī, campidoctōrēs, et cēterī officiālēs.” Et prō hōc sīmius, quī mendāciter laudātus est cum turbā suā, ōsculātus est hominem fallācem et mūnera illī dedit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"primo","latin":"prīmō","headword":"prīmō","letter":"p","pos":"adverb","posGroup":"adverb","english":"at first; first, at first","forms":["primo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Datur petentibus venia, dissuadente {{primo}} Vercingetorige, post concedente et precibus ipsorum et misericordia vulgi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"primogenitum","latin":"primogenitum, primogeniti","headword":"primogenitum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"birth-right, right of the first-born/oldest (child)","forms":["prīmōgenitum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum nihilōminus pharaō in sententiā perstāret, Deus interfēcit {{prīmōgenitum}} eius fīlium, et omnēs prīmōgenitōs Aegyptiōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"primogenitus","latin":"primogenitus, primogenita, primogenitum","headword":"primogenitus","letter":"p","pos":"adjective","posGroup":"adjective","english":"first-born; oldest (child)","forms":["prīmōgenitī","prīmōgenitō","prīmōgenitōs","prīmōgenitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cui Iacobus: dabō, sī concēdās mihi iūs prīmōgenitī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"primordium","latin":"primordium, primordi(i)","headword":"primordium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"first beginning, origin, commencement, beginnings","forms":["prīmōrdia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"j37 et profugum Aenēān, altae {{prīmōrdia}} Rōmae,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"primores","latin":"prīmōrēs, -um (m.pl.)","headword":"prīmōrēs","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"leading men, front ranks; leading men, chiefs","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"primoris","latin":"primoris, primoris","headword":"primoris","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"nobles (pl.), men of the first rank","forms":["prīmōrēs","prīmōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum īnstrūctae aciēs cōnstitissent, priusquam signum pugnandī darētur, prōcessit Latīnus inter {{prīmōrēs}} ducemque advenārum ēvocāvit ad colloquium.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"primulus","latin":"primulus, primula, primulum","headword":"primulus","letter":"p","pos":"adjective","posGroup":"adjective","english":"very first","forms":["Prīmulō","prīmulum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"ALCVMENA: Prīmulō dīlūculō abiistī ad legiōnēs.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"primum","latin":"prīmum","headword":"prīmum","letter":"p","pos":"adverb","posGroup":"adverb","english":"first","forms":["primum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ipse, ut quam {{primum}} iter faceret, Cenabum Carnutum proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"primus","latin":"prīmus, -a, -um","headword":"prīmus","letter":"p","pos":"adjective","posGroup":"adjective","english":"first","forms":["prima","prīmae","primam","primi","primis","prīmōrum","prīmōs","primus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In {{primis}} rationem esse habendam dicunt, prius quam eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"princeps","latin":"prīnceps, prīncipis","headword":"prīnceps","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) chief, leader, head man; chief, leader; chief, leader, prince","forms":["princeps","principe","prīncipem","principes","prīncipī","principibus","prīncipis","principum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se {{principes}} Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"principatus","latin":"principatus, principatus","headword":"principatus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"first place; rule; leadership; supremacy; chief command","forms":["principatu","principatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater {{principatum}} Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"principio","latin":"principio, principiare, principiavi, principiatus","headword":"principio","letter":"p","pos":"verb","posGroup":"verb","english":"begin to speak; begin to peak (medieval)","forms":["principiō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quod (: eam quam) amáàre velīs Prīncipiō, quod amāre velīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"principium","latin":"prīncipium, -ī","headword":"prīncipium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"beginning","forms":["Prīncipiī","principium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce {{principium}} carminis quod scripsit ad amicam secum in circo sedentem:","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"prior","latin":"prior, -ius","headword":"prior","letter":"p","pos":"adjective","posGroup":"adjective","english":"first, former, front; before, earlier (comparative)","forms":["prior","priōra","priōre","priōrem","priores","Priorī","priōribus","priōrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At interiores, dum ea quae a Vercingetorige ad eruptionem praeparata erant proferunt, {{priores}} fossas explent, diutius in his rebus administrandis morati prius suos discessisse cognoverunt quam munitionibus appropinquarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"priscus","latin":"priscus, prisca, priscum","headword":"priscus","letter":"p","pos":"adjective","posGroup":"adjective","english":"ancient, early, former","forms":["prīsca","prīscī","prīscīs","Prisco","Prīscum","Priscus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nubere vis {{Prisco}}; non miror, Paula, sapisti.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pristinus","latin":"prīstinus, -a, -um","headword":"prīstinus","letter":"p","pos":"adjective","posGroup":"adjective","english":"former, original, pristine","forms":["prīstina","pristinae","prīstinārum","pristinum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito stipendio, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in {{pristinum}} statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prius","latin":"prius","headword":"prius","letter":"p","pos":"adverb","posGroup":"adverb","english":"before","forms":["prius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, {{prius}} quam eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"priusquam","latin":"priusquam","headword":"priusquam","letter":"p","pos":"conjunction","posGroup":"conjunction","english":"before, sooner, rather; before","forms":["priusquam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ex eō tempore Tantalus, in Īnferōrum flūmine stāns, famē et sitī, quae nūllum habent fīnem, excruciātur: nam simul atque bibere cōnātur, aqua, quam haurīre vult, recēdit; et cum pōma, quae super caput sunt, sūmere cupit, ventus ea retrahit {{priusquam}} capiat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"privatim","latin":"prīvātim","headword":"prīvātim","letter":"p","pos":"adverb","posGroup":"adverb","english":"privately, personally","forms":["prīvātim"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prō hīs nōs habēmus luxuriam atque avāritiam, pūblicē egestātem, {{prīvātim}} opulentiam; laudāmus dīvitiās, sequimur inertiam; inter bonōs et malōs discrīmen nūllum; omnia virtūtis praemia ambitiō possidet.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"privatus","latin":"prīvātus, -a, -um","headword":"prīvātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"private; private, personal","forms":["prīvāta","prīvātārum","prīvātās","prīvātī","prīvātīs","prīvātō","prīvātōrum","prīvātōs","prīvātum","prīvātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Pater maxime dē rēbus suīs scrībit, sed Aemilia dē rēbus {{prīvātīs}}, ut dē suīs et dē convīviīs, scrībere solet.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"privignus","latin":"privignus, privigni","headword":"privignus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"stepson","forms":["prīvignum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postrēmō captus amōre Aurēliae Orestillae (cuius praeter fōrmam nihil umquam bonus laudāvit!), quod ea nūbere illī dubitābat timēns {{prīvignum}} adultā aetāte, prō certō crēditur necātō fīliō vacuam domum scelestīs nūptiīs fēcisse!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"pro","latin":"prō","headword":"prō","letter":"p","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) before, in front of, on behalf of; in front of, before, for (+ abl.); in place of, before, for (+ abl.)","forms":["pro"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia adducti fecerint, quod nihil nobis constat, non videtur {{pro}} certo esse proponendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proba","latin":"proba, probae","headword":"proba","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"proof; evidence","forms":["proba"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Syra ancilla {{proba}} est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"probare","latin":"(probō) probāre","headword":"probāre","letter":"p","pos":"","posGroup":"other","english":"approve of, prove","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"probatus","latin":"probātus, -a, -um","headword":"probātus","letter":"p","pos":"","posGroup":"other","english":"acceptable, pleasing","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"probe","latin":"probe","headword":"probe","letter":"p","pos":"adverb","posGroup":"adverb","english":"properly, rightly","forms":["probe"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mēdus: “Ecce nummī tuī, {{probe}} serve!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"probitas","latin":"probitas, probitatis","headword":"probitas","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"uprightness, honesty, probity","forms":["probitātis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Omnēs igitur Callistō summīs laudibus afficiēbant eiusque vīrēs tam multum admīrābantur ut dē ea eiusque factīs omnēs hominēs fābulārentur, atque ūnō ōre optārent ut praemia fortitūdinis ac {{probitātis}} ā deīs acciperet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"probo","latin":"probō, -āre, -āvī, -ātum","headword":"probō","letter":"p","pos":"verb","posGroup":"verb","english":"approve","forms":["probābat","probandum","probant","probāre","probarem","probārētur","probat","probata","probātum","probātur","probātus","probāvit","probem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Omnium consensu hac sententia {{probata}}, uno die amplius XX urbes Biturigum incenduntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"probrum","latin":"probrum, probri","headword":"probrum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"disgrace; abuse, insult; disgrace, shame","forms":["probra","probrī","probrīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Accēdēbat ex adversō Goliathus, quī, vīsō adulēscente: “Num” inquit “mē canem esse putās, quī mē cum baculō aggrediāris?” Cui Dāvīd respondit: “Tū venīs ad mē cum gladiō et hastā et clipeō; ego autem veniō in nōmine Dominī exercituum, quem {{probrīs}} ausus es lacessere.” Tunc, missō fundā lapide, Philistaeum in fronte percussit, et humī prōstrāvit, currēnsque suum iacentī gladium dētrāxit, quō caput illī praecīdit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"probus","latin":"probus, -a, -um","headword":"probus","letter":"p","pos":"adjective","posGroup":"adjective","english":"good, honest, proper; good, honest, well-behaved; good, honest","forms":["probae","probam","probōs","probum","probus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dāvus, quī {{probus}} est servus, tacet neque Mēdum accūsat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"procax","latin":"procax, (gen.), procacis","headword":"procax","letter":"p","pos":"adjective","posGroup":"adjective","english":"pushing, impudent; undisciplined; frivolous","forms":["procācī","procācibus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vērum ingenium eius haud absurdum: posse versūs facere, iocum movēre, sermōne utī vel modestō, vel mollī, vel procācī — prōrsus multae facētiae multusque lepōs inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"procedere","latin":"(prōcēdō) prōcēdere, prōcessisse,  processum","headword":"prōcēdere","letter":"p","pos":"","posGroup":"other","english":"move forward","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"procedo","latin":"procedo, procedere, processi, processus","headword":"procedo","letter":"p","pos":"verb","posGroup":"verb","english":"proceed; advance; appear","forms":["Prōcēde","prōcēdēbant","procedendum","prōcēdēns","prōcēdere","procederent","prōcēdis","prōcēdit","Prōcēdō","prōcēdunt","processerant","prōcesserat","prōcessērunt","prōcessī","processissent","prōcessisset","prōcessit","prōcessum","processuros"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Harum ipsis rerum copiam suppetere, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris {{processuros}}; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"procella","latin":"procella, -ae","headword":"procella","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"violent wind, gale; storm, squall","forms":["procella","procellīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Utinam ego quoque in campīs Īliacīs animam prō patriā effūdissem!' Dum tālia verba iactat, rapida {{procella}} vēla scindit fluctūsque ad caelum tollit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"procer","latin":"procer, proceris","headword":"procer","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"nobles (pl.), chiefs, princes; leading men of the country/society/profession","forms":["procerēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"post aliī {{procerēs}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"procerus","latin":"prōcērus, -a, -um","headword":"prōcērus","letter":"p","pos":"adjective","posGroup":"adjective","english":"tall, long","forms":["prōcērum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat eō tempore in nōbīs summa grācilitās et īnfirmitās corporis, {{prōcērum}} et tenue collum; quī habitus et quae fīgūra nōn procul abesse putātur ā vītae perīculō, sī accēdit labor et laterum magna contentiō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"procidere","latin":"(prōcidō) prōcidere, prōcidisse (< cadere)","headword":"prōcidere","letter":"p","pos":"","posGroup":"other","english":"fall forward, collapse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"procido","latin":"procido, procidere, procidi, -","headword":"procido","letter":"p","pos":"verb","posGroup":"verb","english":"fall prostrate, collapse","forms":["prōcidēns","prōciderat","prōcidērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum invēnisset eum Jēsus, dīxit eī:\"Tū crēdis in Fīlium hominis?\"Respondit ille:\"Quis est?\"Et dīxit Jēsus:\"Quī loquitur tēcum, ipse est.\"At ille ait:\"Crēdō, domine.\"Et {{prōcidēns}} adōrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"proclamare","latin":"(prōclāmō) prōclāmāre","headword":"prōclāmāre","letter":"p","pos":"","posGroup":"other","english":"cry out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"proclamo","latin":"proclamo, proclamare, proclamavi, proclamatus","headword":"proclamo","letter":"p","pos":"verb","posGroup":"verb","english":"call/cry out, raise an outcry; appeal noisily; take claim to court; proclaim","forms":["prōclāmante"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Horātiō patre {{prōclāmante}} sē fīliam iūre caesam iūdicāre; ōrābat deinde nē sē, quem paulō ante cum ēgregiā stirpe cōnspexissent, orbum līberīs facerent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proclino","latin":"proclino, proclinare, proclinavi, proclinatus","headword":"proclino","letter":"p","pos":"verb","posGroup":"verb","english":"tilt forward; cause to totter","forms":["proclinatam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Adiuvat rem {{proclinatam}} Convictolitavis plebemque ad furorem impellit, ut facinore admisso ad sanitatem reverti pudeat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proco","latin":"proco, procare, procoravi, procoratus","headword":"proco","letter":"p","pos":"verb","posGroup":"verb","english":"urge/press (w/commands/suits); woo, importune for one's hand; ask/demand (L+S)","forms":["Proca"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Proca}} deinde rēgnat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proconsul","latin":"proconsul, proconsulis","headword":"proconsul","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"proconsul, governor of a province","forms":["proconsul","prōcōnsule"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quīnctius Flāminīnus {{proconsul}} cum Philippō ad Cynoscephalās in Thessaliā aciē victō dēbellāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"procreare","latin":"(prōcreō) prōcreāre","headword":"prōcreāre","letter":"p","pos":"verb","posGroup":"verb","english":"engender, beget; to beget, bring forth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"procreo","latin":"prōcreō (1)","headword":"prōcreō","letter":"p","pos":"verb","posGroup":"verb","english":"beget, produce offspring","forms":["prōcreat","prōcreātūrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aegeus hanc accipit, neque satis hospitium est, sed sē Medeae foedere thalamī quoque iungit, nam spērābat sē arte Medeae fīlium {{prōcreātūrum}} esse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"procubo","latin":"procubo, procubare, procubui, procubitus","headword":"procubo","letter":"p","pos":"verb","posGroup":"verb","english":"lie outstretched","forms":["prōcubuēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut medium campī passīs tetigēre capillīs, in terram positō {{prōcubuēre}} genū, et quasi sentīrent, blandō clāmōre nepōtēs tendēbant ad avōs bracchia parva suōs; quī poterat clāmābat \"avum\", tunc dēnique vīsum, et quī vix poterat posse coāctus erat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"procul","latin":"procul","headword":"procul","letter":"p","pos":"adverb","posGroup":"adverb","english":"far (often combines with prepositionab); far (from), far away; far off; far, far off; far off, at a distance; at a distance, far off","forms":["procul"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, centurionibus et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium {{procul}} visus est, qui agmen Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proculab","latin":"proculab","headword":"proculab","letter":"p","pos":"","posGroup":"other","english":"(+ abl.) far from","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"procumbere","latin":"(prōcumbō) prōcumbere,","headword":"prōcumbere","letter":"p","pos":"","posGroup":"other","english":"lean forward, bow down prōcubuisse, prōcubitum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"procumbo","latin":"procumbo, procumbere, procubui, procubitus","headword":"procumbo","letter":"p","pos":"verb","posGroup":"verb","english":"sink down, lie down, lean forward","forms":["prōcumbat","prōcumbentēs","prōcumbere","Procumbunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Procumbunt}} omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"procuratio","latin":"procuratio, procurationis","headword":"procuratio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"management; administration; charge, responsibility","forms":["prōcūrātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quārē {{prōcūrātiōnem}} regnl coāctus est relinquere IOathae fīliō, qul rēctē imperium administrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"procurator","latin":"prōcūrātor, -ōris (m.)","headword":"prōcūrātor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"manager, superintendent","forms":["prōcūrātor","prōcūrātōrem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Sit huic oppositus alter, bonus et sapiēns et perītus ūtilitātis dignitātisque cīvīlis, quasi tūtor et {{prōcūrātor}} reī pūblicae: sīc enim appelletur quīcumque erit rēctor et gubernātor cīvitātis.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"procurrere","latin":"(prōcurrō) prōcurrere, prōcucurrisse or procurrisse, prōcursum","headword":"prōcurrere","letter":"p","pos":"verb","posGroup":"verb","english":"run forward, charge; to run forward","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"procurro","latin":"procurro, procurrere, procurri, procursus","headword":"procurro","letter":"p","pos":"verb","posGroup":"verb","english":"run out ahead; jut out","forms":["procurrentibus","procurrerunt","prōcursum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres familiae repente in publicum {{procurrerunt}} flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"procus","latin":"procus, -ī","headword":"procus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"suitor","forms":["procī","procōrum","procōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn debēs coniugem habēre; erit mors tibi.\" Territa virgō in silvā vīvit innuba et turbam {{procōrum}} fugat hīs verbīs dūrīs: \"Nōn erō coniūnx, nisi prius victa cursū.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"prodeo","latin":"prodeo, prodire, prodivi(ii), proditus","headword":"prodeo","letter":"p","pos":"verb","posGroup":"verb","english":"go/come forth/out, advance; appear; sprout/spring up; issue/extend/project","forms":["prōdeunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde ad foedus faciendum ducēs {{prōdeunt}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"prodere","latin":"(prōdō) prōdere (< dare)","headword":"prōdere","letter":"p","pos":"","posGroup":"other","english":"hand down, betray","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"prodesse","latin":"(prōsum) prōdesse, prōfuisse","headword":"prōdesse","letter":"p","pos":"verb","posGroup":"verb","english":"(+dat.) to be profitable, of advantage; to be useful to (with dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"prodest","latin":"prōdest","headword":"prōdest","letter":"p","pos":"verb","posGroup":"verb","english":"is useful to, does good to","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"prodigium","latin":"prōdigium, -ī","headword":"prōdigium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"prodigy; portent, wonder","forms":["prōdigia","prōdigiīs","prōdigiō","prōdigiōrum","prōdigium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Moysēs, ut pharaōnis pertināciam vinceret, multa et stupenda ēdidit {{prōdigia}}, quae vocantur ‘plāgae Aegyptī’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prodio","latin":"prodio, prodiere, -, -","headword":"prodio","letter":"p","pos":"verb","posGroup":"verb","english":"go/come forth/forward/out; appear, spring up; advance/proceed; extend, project","forms":["prōdiit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce statim Rebecca, virgō eximia pulchritūdine, {{prōdiit}}, gerēns urnam hūmēris; quae dēscendit ad puteum, et implēvit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prodire","latin":"(prōdeō) prōdīre (< īre)","headword":"prōdīre","letter":"p","pos":"","posGroup":"other","english":"come forward, go forth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"proditio","latin":"prōditiō, -ōnis ( f.)","headword":"prōditiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"betrayal; betrayal, treason","forms":["prōditiōne","prōditiōnem","proditionis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem {{proditionis}} insimulatis; cuius opera sine vestro sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proditor","latin":"prōditor, -ōris (m.)","headword":"prōditor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"traitor","forms":["prōditōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Viriāthus ā {{prōditōribus}}, cōnsiliō Servīliī Caepiōnis, interfectus est et ab exercitū suō multum complōrātus ac nōbiliter sepultus, vir duxque magnus et per quattuordecim annōs quibus cum Rōmānīs bellum gessit frequentius superior.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"prodo","latin":"prōdō, -ere, -didī, -ditum","headword":"prōdō","letter":"p","pos":"verb","posGroup":"verb","english":"to betray, hand over","forms":["prōdere","prōderet","prodi","prōdiderat","prōdidērunt","prōdidit","prōdit","prōdita","prōditē","prōditus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cuius rei si exemplum non haberemus, tamen libertatis causa institui et posteris {{prodi}} pulcherrimum iudicarem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"producere","latin":"(prōdūcō) prōdūcere (< dūcere)","headword":"prōdūcere","letter":"p","pos":"","posGroup":"other","english":"extend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"produco","latin":"produco, producere, produxi, productus","headword":"produco","letter":"p","pos":"verb","posGroup":"verb","english":"lead forward, bring out; reveal; induce; promote; stretch out; prolong; bury","forms":["prōdūcere","produci","prōdūcit","producuntur","prōdūximus","prōdūxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta {{produci}}, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"productum","latin":"productum, producti","headword":"productum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"product","forms":["productis","prōductum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque {{productis}} copiis ante oppidum considunt et proximam fossam cratibus integunt atque aggere explent seque ad eruptionem atque omnes casus comparant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proelior","latin":"proelior, proeliari, proeliatus sum","headword":"proelior","letter":"p","pos":"verb","posGroup":"verb","english":"fight","forms":["proeliari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Cum iam muro turres appropinquassent, ex captivis Caesar cognovit Vercingetorigem consumpto pabulo castra movisse propius Avaricum atque ipsum cum equitatu expeditisque qui inter equites {{proeliari}} consuessent insidiarum causa eo profectum quo nostros postero die pabulatum venturos arbitraretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proelium","latin":"proelium, -ī","headword":"proelium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"battle","forms":["proeli","proelia","proeliis","proelio","proeliorum","proelium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere {{proelio}} dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profanus","latin":"profānus, -a, -um","headword":"profānus","letter":"p","pos":"adjective","posGroup":"adjective","english":"wicked, evil","forms":["profānīs","profānōs","profānum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Factum populī est {{profānum}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"profectio","latin":"profectio, profectionis","headword":"profectio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"departure","forms":["profectio","profectione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ipse maiorem Galliae motum exspectans, ne ab omnibus civitatibus circumsisteretur, consilia inibat quem ad modum ab Gergovia discederet ac rursus omnem exercitum contraheret, ne {{profectio}} nata ab timore defectionis similis fugae videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profecto","latin":"profectō","headword":"profectō","letter":"p","pos":"adverb","posGroup":"adverb","english":"surely; for a fact","forms":["profectō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Diodōrus: “Nōlō profectō!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"profectus","latin":"profectus, profectus","headword":"profectus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"progress, success","forms":["profectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pompei commodiorem in statum pervenisse intellegeret, in Transalpinam Galliam {{profectus}} est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profero","latin":"profero, proferre, protuli, prolatus","headword":"profero","letter":"p","pos":"verb","posGroup":"verb","english":"bring forward; advance; defer; discover; mention","forms":["profer","prōferam","proferre","proferri","profert","prōferte","prōfertō","proferunt","prōlātum","prōtulērunt","prōtulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quorum cum magna multitudo convenisset, matres familiae, quae paulo ante Romanis de muro manus tendebant, suos obtestari et more Gallico passum capillum ostentare liberosque in conspectum {{proferre}} coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proferre","latin":"(prōferō) prōferre, prōtulisse, prōlātum","headword":"prōferre","letter":"p","pos":"verb","posGroup":"verb","english":"bring forward; to bring out, produce","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"proficere","latin":"(prōficiō) prōficere (< facere)","headword":"prōficere","letter":"p","pos":"","posGroup":"other","english":"progress, be successful","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"proficio","latin":"proficio, proficere, profeci, profectus","headword":"proficio","letter":"p","pos":"verb","posGroup":"verb","english":"make, accomplish, effect","forms":["prōfēcī","profecissent","prōfēcisset","proficiebant","prōficiēbat","prōficit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi {{profecissent}}, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proficisci","latin":"proficīscī","headword":"proficīscī","letter":"p","pos":"verb","posGroup":"verb","english":"to set out, depart","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"proficiscitur","latin":"proficīscitur, proficīscī","headword":"proficīscitur","letter":"p","pos":"verb","posGroup":"verb","english":"set out, depart; sets out, departs","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"proficiscor","latin":"proficīscor, -ī, -fectus sum","headword":"proficīscor","letter":"p","pos":"verb","posGroup":"verb","english":"set out, depart","forms":["profecta","profectae","profecti","profectīs","profectum","profectūram","prōfectūrās","proficīscar","proficīscātur","proficiscēbatur","proficīscendī","proficīscēns","proficīscentem","proficīscentēs","proficīscere","proficīscerentur","proficisceretur","proficisci","proficīsciminī","proficiscimur","proficiscitur","proficiscuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quieta Gallia, Caesar, ut constituerat, in Italiam ad conventus agendos {{proficiscitur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profiteor","latin":"profiteor, profiteri, professus sum","headword":"profiteor","letter":"p","pos":"verb","posGroup":"verb","english":"declare; profess","forms":["professōs","profitēmur","profitendum","profitentur","profiterentur","profitērī","profitētur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus agitatis, {{profitentur}} Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profiteri","latin":"(profiteor) profitērī (< fatērī)","headword":"profitērī","letter":"p","pos":"","posGroup":"other","english":"declare, offer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"profligare","latin":"(prōflīgō) prōflīgāre","headword":"prōflīgāre","letter":"p","pos":"","posGroup":"other","english":"defeat decisively, crush","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"profligatus","latin":"profligatus, profligata, profligatum","headword":"profligatus","letter":"p","pos":"adjective","posGroup":"adjective","english":"profligate, depraved","forms":["prōflīgātōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum illī nūntiātum esset {{prōflīgātōs}} hostēs et interfectum esse Absalōnem, nōn modo nōn laetātus est dē victōriā, quam reportāverat, sed maximum quoque dolōrem cēpit ex morte fīliī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"profligo","latin":"profligo, profligare, profligavi, profligatus","headword":"profligo","letter":"p","pos":"verb","posGroup":"verb","english":"overthrow, rout","forms":["profligatis","prōflīgāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus {{profligatis}}, rursus oppidani perterriti comprehensos eos quorum opera plebem concitatam existimabant ad Caesarem perduxerunt seseque ei dediderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profor","latin":"profor, profari, profatus sum","headword":"profor","letter":"p","pos":"verb","posGroup":"verb","english":"speak out","forms":["profātur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum breviter Dīdō, voltum dēmissa, {{profātur}}:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"profugere","latin":"(profugiō) profugere (< fugere)","headword":"profugere","letter":"p","pos":"","posGroup":"other","english":"run away, flee","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"profugio","latin":"profugio, profugere, profugi, -","headword":"profugio","letter":"p","pos":"verb","posGroup":"verb","english":"escape, escape from; run away from","forms":["profūgerant","profūgerat","profugere","profugerent","profūgērunt","profūgisse","profugit","profugiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Castris ante oppidum positis, diei tempore exclusus in posterum oppugnationem differt, quaeque ad eam rem usui sint militibus imperat, et quod oppidum Cenabum pons fluminis Ligeris contingebat, veritus ne noctu ex oppido {{profugerent}}, duas legiones in armis excubare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"profugus","latin":"profugus, -a, -um","headword":"profugus","letter":"p","pos":"adjective","posGroup":"adjective","english":"fleeing, (m.) fugitive; fugitive, exiled","forms":["profugā","profugī","profugōs","profugum","profugus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tālibus atque aliīs, in quae dolor ipse disertum fēcerat, āversōs profugā dē classe redūxī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"profundere","latin":"(profundo) profundere (< fundere)","headword":"profundere","letter":"p","pos":"","posGroup":"other","english":"pour out, shed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"profundo","latin":"profundo, profundere, profudi, profusus","headword":"profundo","letter":"p","pos":"verb","posGroup":"verb","english":"pour, pour out; utter; squander","forms":["profūdī","profūdit","profundant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dāvīd, audītā Saūlis morte, lacrimās {{profūdit}}: montēs Gelboē, ubi caedēs illa facta erat, exsecrātus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"profundum","latin":"profundum, profundi","headword":"profundum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"depths, abyss, chasm; boundless expanse","forms":["profundum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sī quis autem scandalizāverit ūnum dē parvulīs isfīs, expedit eī ut suspendiitur mola collō eius et dēmergātur in {{profundum}} mare.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"profundus","latin":"profundus, profunda, profundum","headword":"profundus","letter":"p","pos":"adjective","posGroup":"adjective","english":"deep, profound; boundless; insatiable","forms":["profundam"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"pallentīs umbrās Erebō noctemque {{profundam}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"profusus","latin":"profusus, profusa, profusum","headword":"profusus","letter":"p","pos":"adjective","posGroup":"adjective","english":"excessive; lavish; extravagant","forms":["profūsīs","profūsō","profūsus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tūre datō flammīs vīnōque in tūra profūsō,\n. . . rēgia tēcta petunt, positīsque tapētibus altīs\nmūnera cum liquidō capiunt Cereālia Bacchō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"progenies","latin":"prōgeniēs, -ēī","headword":"prōgeniēs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"offspring, descent","forms":["prōgenie","prōgeniem","prōgeniēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Adspice caelum; dīnumerā stēllās, sī potes; tua {{prōgeniēs}} eās aequābit numerō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prognatus","latin":"prōgnātus, -a, -um","headword":"prōgnātus","letter":"p","pos":"adjective","posGroup":"adjective","english":"born, son (of ) (+ abl.)","forms":["prōgnātī","prōgnātum","prōgnātus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"MERCVRIVS: Sōsiam vocant Thēbānī, Dāvō {{prōgnātum}} patre.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"progredi","latin":"(prōgredior) prōgredī, prōgressum","headword":"prōgredī","letter":"p","pos":"verb","posGroup":"verb","english":"go forward, advance; to advance","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"progredior","latin":"progredior, progredi, progressus sum","headword":"progredior","letter":"p","pos":"verb","posGroup":"verb","english":"go, come forth, go forward, march forward; advance. proceed. make progress","forms":["prōgrederentur","progredi","progrediatur","progrediebantur","prōgrediēbātur","prōgredientium","prōgreditur","prōgrediuntur","progressam","prōgressī","prōgressō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Legionem unam eodem iugo mittit et paulum {{progressam}} inferiore constituit loco silvisque occultat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"progressio","latin":"prōgressiō, -ōnis ( f.)","headword":"prōgressiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"advance","forms":["prōgressiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Fuit enim illud extrēmum ut ex iīs locīs ā mīlitibus nostrīs reditus magis mātūrus quam prōgressiō longior quaererētur!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"progressus","latin":"progressus, progressus","headword":"progressus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"advance, progress","forms":["progressus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Progressus}} in Nitiobriges et Gabalos ab utrisque obsides accipit et magna coacta manu in provinciam Narbonem versus eruptionem facere contendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prohibeo","latin":"prohibeō, -ēre","headword":"prohibeō","letter":"p","pos":"verb","posGroup":"verb","english":"prevent, stop, prohibit","forms":["prohibē","prohibeam","prohibeantur","prōhibeas","prohibebant","prohibebat","prohibēbit","prohibēbō","prohibēbunt","prohibēmur","prohibendī","prohibent","prohibente","prohibeor","prohibere","prohiberent","prohibērī","prohibet","prohibētis","Prohibetur","prohibitī","prohibituri","prohibitus","prohibuerit","prohibuērunt","prohibuisse","prohibuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Prohibetur}} ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prohibere","latin":"(prohibeō) prohibēre, prohibuisse, prohibitum","headword":"prohibēre","letter":"p","pos":"verb","posGroup":"verb","english":"keep off, prevent; to keep away, prevent","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"proicere","latin":"(prōiciō) prōicere, prōiēcisse, prōiectum","headword":"prōicere","letter":"p","pos":"","posGroup":"other","english":"throw forward","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"proicio","latin":"proicio, proicere, projeci, projectus","headword":"proicio","letter":"p","pos":"verb","posGroup":"verb","english":"throw down, throw out; abandon; throw away","forms":["proicere","prōicerentur","proiciebat","prōiciēns","prōicit","proiciuntur","prōiēcerat","prōiecērunt","prōiēcit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas glaebas in ignem e regione turris {{proiciebat}}; scorpione ab latere dextro traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proiectus","latin":"projectus, projecta, projectum","headword":"projectus","letter":"p","pos":"adjective","posGroup":"adjective","english":"jutting out, projecting; precipitate; abject, groveling","forms":["proiectae","proiectis","prōiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres familiae repente in publicum procurrerunt flentesque {{proiectae}} ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proiicio","latin":"projicio, projicere, projeci, projectus","headword":"projicio","letter":"p","pos":"verb","posGroup":"verb","english":"throw down, throw out; abandon; throw away","forms":["prōiiciāmus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Occīdāmus illum et {{prōiiciāmus}} in puteum; dīcēmus patrī: fera dēvorāvit Iōsēphum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"proinde","latin":"proinde","headword":"proinde","letter":"p","pos":"adverb","posGroup":"adverb","english":"accordingly","forms":["proinde"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Proinde}}, si quid in nobis animi est, persequamur eorum mortem qui indignissime interierunt, atque hos latrones interficiamus.' Ostendit cives Romanos, qui eius praesidi fiducia una erant; magnum numerum frumenti commeatusque diripit; ipsos crudeliter excruciatos interficit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prolabi","latin":"(prōlābor) prōlābī (< lābī)","headword":"prōlābī","letter":"p","pos":"","posGroup":"other","english":"slip, overbalance","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"prolabor","latin":"prolabor, prolabi, prolapsus sum","headword":"prolabor","letter":"p","pos":"verb","posGroup":"verb","english":"glide or slip forwards, fall into decay, go to ruin; collapse","forms":["prōlāpsī","prōlāpsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Brūtus, aliō ratus spectāre dīvīnam vōcem, velut sī {{prōlāpsus}} cecidisset, terram ōsculō tetigit — scīlicet quod ea commūnis 'māter' omnium mortālium esset!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"prolato","latin":"prolato, prolatare, prolatavi, prolatatus","headword":"prolato","letter":"p","pos":"verb","posGroup":"verb","english":"lengthen, enlarge; prolong; put off, defer","forms":["prōlāta","prōlātandō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Inter haec parāta atque dēcrēta Cethēgus semper querēbātur dē ignāviā sociōrum: illōs dubitandō et diēs prōlātandō magnās opportūnitātēs corrumpere; factō, nōn cōnsultō in tālī perīculō opus esse, sēque, sī paucī adiuvārent, languentibus aliīs, impetum in cūriam factūrum!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"proles","latin":"prōlēs, -is ( f.)","headword":"prōlēs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"offspring; offspring, son; offspring, child; offspring, descendants","forms":["prōle","prōlem","prōlēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deus fēcit foedus cum illō hīs verbīs: exī ē domō paternā, dēsere patriam, et pete regiōnem quam datūrus sum posterīs tuīs: augēbō tē {{prōle}} numerōsā; eris pater multārum gentium, ac per tē omnēs orbis nātiōnēs erunt bonīs cumulātae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prolixus","latin":"prolixus, prolixa -um, prolixior -or -us, prolixissimus -a -um","headword":"prolixus","letter":"p","pos":"adjective","posGroup":"adjective","english":"luxuriant, extensive (growth); big/tall (man); generous; running smoothly","forms":["prōlixius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et {{prōlixius}} ōrābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prologus","latin":"prologus, prologi","headword":"prologus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"prologue","forms":["prōlogō","prōlogum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hōc versū ūtitur Plautus in prōlogō — et Phaedrus in Fābulīs Aesōpiīs (vidē pāginās 33–41).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"proloquor","latin":"proloquor, proloqui, prolocutus sum","headword":"proloquor","letter":"p","pos":"verb","posGroup":"verb","english":"speak out","forms":["prōlocūtus","prōloquar","prōloquor"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sīc hoc {{prōloquar}}:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"proludo","latin":"proludo, proludere, prolusi, prolusus","headword":"proludo","letter":"p","pos":"verb","posGroup":"verb","english":"carry out preliminary exercises before a fight; rehearse for","forms":["prōlūsit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sīc ubi {{prōlūsit}}, rudibus puer","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"proluo","latin":"proluo, proluere, prolui, prolutus","headword":"proluo","letter":"p","pos":"verb","posGroup":"verb","english":"wash out; wash away; wash up; purify","forms":["prōluit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"spūmantem pateram, et plēnō sē {{prōluit}} aurō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"promereo","latin":"promereo, promerere, promerui, promeritus","headword":"promereo","letter":"p","pos":"verb","posGroup":"verb","english":"deserve, merit; deserve well of; earn; gain","forms":["prōmerērī","prōmeritam","prōmeruit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haud {{prōmeruit}} quam ob rem vitiō verterēs:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"prominens","latin":"prominens, prominentis","headword":"prominens","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"projection","forms":["prōminentem","prominentes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Matres familiae de muro vestem argentumque iactabant, et pectore nudo {{prominentes}} passis manibus obtestabantur Romanos ut sibi parcerent neu, sicut Avarici fecissent, ne a mulieribus quidem atque infantibus abstinerent; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prominere","latin":"(prōmineō) prōminēre (< minēre)","headword":"prōminēre","letter":"p","pos":"","posGroup":"other","english":"project, stick out","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"promiscuus","latin":"promiscuus, promiscua, promiscuum","headword":"promiscuus","letter":"p","pos":"adjective","posGroup":"adjective","english":"common, shared general, indiscriminate","forms":["prōmiscuae","prōmiscuum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Profectī sunt Hebraeī ex Aegyptō ad sēscenta milia virōrum, praeter parvulōs et {{prōmiscuum}} vulgus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"promissum","latin":"prōmissum, -ī","headword":"prōmissum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"promise","forms":["prōmissā","prōmissīs","prōmissō","prōmissum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quod audiēns Sarā rīsit, nec statim adhibuit fidem {{prōmissīs}} Deī, et idcircō reprehēnsa est ā Deō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"promissus","latin":"promissus, promissa, promissum","headword":"promissus","letter":"p","pos":"adjective","posGroup":"adjective","english":"flowing, hanging down","forms":["prōmissam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum iam in cōnspectū habēret terram ā Deō {{prōmissam}}, mortuus est vir sapientiā et cēterīs virtūtibus plānē admīrābilīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"promittere","latin":"(prōmittō) prōmittere, prōmīsisse, prōmissum","headword":"prōmittere","letter":"p","pos":"verb","posGroup":"verb","english":"promise; to promise","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"promittit","latin":"prōmittit","headword":"prōmittit","letter":"p","pos":"verb","posGroup":"verb","english":"promises","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"promitto","latin":"promitto, promittere, promisi, promissus","headword":"promitto","letter":"p","pos":"verb","posGroup":"verb","english":"promise","forms":["prōmīserat","prōmīsī","prōmīsisse","prōmīsisset","prōmīsistī","prōmīsit","prōmittās","prōmitte","prōmittēns","prōmittentēs","prōmittis","prōmittit","prōmittō","prōmittunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tlēpolemus: “Sed erō meō prōmīsī ‘mē brevī tempore reditūrum esse.’ Neque enim aliōs habet servōs.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"promo","latin":"prōmō, prōmere","headword":"prōmō","letter":"p","pos":"verb","posGroup":"verb","english":"take out","forms":["prōmit","Prōmite","prōmpsistī","prōmpsit","prōmptū"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister epistulam {{prōmit}} atque “Hanc epistulam” inquit “volō tē ad Lūcium Iūlium Balbum ferre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"promotum","latin":"promotum, promoti","headword":"promotum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"preferred thing (as pl.)","forms":["prōmōtum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Vere prīmō in Vaccaeōs {{prōmōtum}} bellum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"promoveo","latin":"promoveo, promovere, promovi, promotus","headword":"promoveo","letter":"p","pos":"verb","posGroup":"verb","english":"move forward","forms":["promoveri"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Paulum legiones Caesar quas pro vallo constituerat {{promoveri}} iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"promovere","latin":"(prōmoveō) prōmovēre (< movēre)","headword":"prōmovēre","letter":"p","pos":"","posGroup":"other","english":"push forward, advance","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"promptus","latin":"prōmptus, -a, -um","headword":"prōmptus","letter":"p","pos":"adjective","posGroup":"adjective","english":"prompt, keen, ready","forms":["prōmptam","prōmptioris","prōmptissimīs","prōmptus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum 'dē aliīs rēbus assentīre sē veteribus Gabīnīs' dīceret, identidem bellī auctor esse et in eō sibi praecipuam prūdentiam assūmere 'quod utrīusque populī vīrēs nōvisset scīretque invīsam profectō superbiam rēgiam cīvibus esse.' Ita cum sēnsim ad rebellandum prīmōrēs Gabīnōrum incitāret et ipse cum {{prōmptissimīs}} iuvenum praedātum īret, dictīs factīsque omnibus ad fallendum aptīs, ad ultimum dux bellī legitur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"promulgare","latin":"(prōmulgō) prōmulgāre","headword":"prōmulgāre","letter":"p","pos":"verb","posGroup":"verb","english":"announce, publish; to publish (a bill), propose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"promulgo","latin":"promulgo, promulgare, promulgavi, promulgatus","headword":"promulgo","letter":"p","pos":"verb","posGroup":"verb","english":"make known by public proclamation; publish","forms":["prōmulgātūrum","Prōmulgāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Prōmulgāvit}} et aliam lēgem agrāriam, quā sibi lātius agrum patefaceret: 'ut iīdem triumvirī iūdicārent quā pūblicus ager, quā prīvātus esset.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"promunturium","latin":"prōmunturium, -ī","headword":"prōmunturium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"headland, promontory","forms":["prōmunturiō","promunturium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Augustus vērō, cum ad Actium, {{promunturium}} Ēpīrī, classem M.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pronomen","latin":"prōnōmen, prōnōminis","headword":"prōnōmen","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(n.) pronoun","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pronuba","latin":"pronuba, pronubae","headword":"pronuba","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"married woman who conducted the bride to the bridal chamber","forms":["prōnuba"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dēveniunt. prīma et Tellūs et {{prōnuba}} Iūnō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pronuntiare","latin":"(prōnūntiō) prōnūntiāre","headword":"prōnūntiāre","letter":"p","pos":"","posGroup":"other","english":"proclaim, announce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pronuntio","latin":"pronuntio, pronuntiare, pronuntiavi, pronuntiatus","headword":"pronuntio","letter":"p","pos":"verb","posGroup":"verb","english":"announce; proclaim; relate; divulge; recite; utter","forms":["pronuntiare","pronuntiarent","prōnūntiat","prōnūntiātum","pronuntiaverat","prōnūntiāvit","prōnūntiēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati {{pronuntiarent}}, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pronus","latin":"prōnus, -a, -um","headword":"prōnus","letter":"p","pos":"adjective","posGroup":"adjective","english":"leaning forward, inclined; bent over, prone","forms":["prōna","prōnam","prōnī","prōnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Decem frātrēs, ubi in cōnspectum Iōsēphī vēnērunt, eum prōnī venerātī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"propago","latin":"propago, propagare, propagavi, propagatus","headword":"propago","letter":"p","pos":"verb","posGroup":"verb","english":"propagate; extend, enlarge, increase","forms":["propāgātae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Omnēs gentēs {{propāgātae}} sunt ā fīliīs Noēmī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"propatulum","latin":"prōpatulum, -ī","headword":"prōpatulum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"forecourt","forms":["prōpatulō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīs in errōrem inductīs, statuās aēneās, quās sēcum portābat, omnēs suā pecūniā complet, eāsque in prōpatulō domī abicit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"prope","latin":"prope","headword":"prope","letter":"p","pos":"preposition; adverb","posGroup":"preposition","english":"(prp. + acc.) near, nearly; near, close to (with acc.); near; near, close by","forms":["prope","propius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi solaci proponebant, quod se {{prope}} explorata victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propediem","latin":"propediem","headword":"propediem","letter":"p","pos":"adverb","posGroup":"adverb","english":"before long, shortly","forms":["propediem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed Cethēgō atque Lentulō cēterīsque quōrum cognōverat prōmptam audāciam mandat quibus rēbus possent opēs factiōnis cōnfirment, īnsidiās cōnsulī matuurent, caedem, incendia, aliaque bellī facinora pārent; sēsē {{propediem}} cum magnō exercitū ad urbem accessūrum.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"propello","latin":"propello, propellere, propuli, propulsus","headword":"propello","letter":"p","pos":"verb","posGroup":"verb","english":"drive forward/forth; drive away/out/off; defeat","forms":["propulerunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Cum a meridie prope ad solis occasum dubia victoria pugnaretur, Germani una in parte confertis turmis in hostes impetum fecerunt eosque {{propulerunt}}; quibus in fugam coniectis, sagittarii circumventi interfectique sunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propemodum","latin":"propemodum","headword":"propemodum","letter":"p","pos":"adverb","posGroup":"adverb","english":"just about, pretty well","forms":["Propemodum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: {{Propemodum}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"properare","latin":"(properō) properāre, -āvisse, -ātum","headword":"properāre","letter":"p","pos":"verb","posGroup":"verb","english":"hasten, hurry; to hurry","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"propere","latin":"properē","headword":"properē","letter":"p","pos":"","posGroup":"other","english":"quickly","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"propero","latin":"propero, properare, properavi, properatus","headword":"propero","letter":"p","pos":"verb","posGroup":"verb","english":"hurry, speed up; be quick","forms":["properā","properāmus","properandum","properant","properantī","properāre","properāret","properārī","properās","properat","properātē","properāvērunt","properāvit","properent","properō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rebecca {{properāvit}} domum, et nārrāvit mātrī suae eā quae sibi contigerant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"properus","latin":"properus, propera, properum","headword":"properus","letter":"p","pos":"adjective","posGroup":"adjective","english":"quick, speedy","forms":["properē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"properē suīs dē fīnibus exercitūs dēdūcerent!'","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"propheta","latin":"propheta, prophetae","headword":"propheta","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"prophet; spokesman/interpreter of a god; foreteller, soothsayer (L+S)","forms":["prophēta","prophētae","prophētam","prophētārum","prophētās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At Deus ad Davidem mīsit {{prophētam}}, quī illum admonēret, eīque poenam sceleris dēnūntiāret subeundam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"propino","latin":"propino, propinare, propinavi, propinatus","headword":"propino","letter":"p","pos":"verb","posGroup":"verb","english":"drink to anyone (his health), pledge; give to drink; hand over, yield up; make","forms":["prōpīnō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Omnēs bibāmus!” [Gāius:] “Sī permittis, prōpīnō tibi.” [Iūlius:] “Bene accipiō. [Ad alium convīvam:] Quid nōn bibis?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"propinquo","latin":"propinquo, propinquare, propinquavi, propinquatus","headword":"propinquo","letter":"p","pos":"verb","posGroup":"verb","english":"bring near; draw near","forms":["propinquō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Macedonēs quīque aliī in castrīs rēgiīs erant prīmō, dum procul nihil aliud quam turba et agmen apparēbat, Aetōlōs crēdere subsidiō venīre; cēterum, ut prīmum signa et arma ex propinquō cognita errōrem aperuērunt, tantus repentē pavor omnēs cēpit ut abiectīs armīs fugerent!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"propinquus","latin":"propinquus, -a, -um","headword":"propinquus","letter":"p","pos":"adjective","posGroup":"adjective","english":"near, close; near, neighbouring","forms":["propinqua","propinquae","propinquam","propinqui","propinquis","propinquōs","propinquum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Haec ab ipsis cognoscite qui ex ipsa caede fugerunt; nam ego fratribus atque omnibus meis {{propinquis}} interfectis dolore prohibeor quae gesta sunt pronuntiare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propior","latin":"propior, propior, propius","headword":"propior","letter":"p","pos":"adjective","posGroup":"adjective","english":"nearer, closer; more recent","forms":["propior","propiōra","propiōre","propiōrēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"sīve humilés {{propiōre}} fretō iactábimus ālās,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"propitius","latin":"propitius, propitia, propitium","headword":"propitius","letter":"p","pos":"adjective","posGroup":"adjective","english":"favorably inclined, well-disposed, propitious","forms":["propitiōs","propitium","propitius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Et rūrsus: Deus sit tibi {{propitius}}, fīlī mī; et abiit festīnāns, quia commōtus erat animō, et lacrimae ērumpēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"proponere","latin":"(prōpōnō) prōpōnere (< pōnere)","headword":"prōpōnere","letter":"p","pos":"","posGroup":"other","english":"set up, propose","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"propono","latin":"prōpōnō, -ere, -posuī, -positum","headword":"prōpōnō","letter":"p","pos":"verb","posGroup":"verb","english":"put forward, propose","forms":["prōpōnant","proponebant","proponendum","prōpōneret","proponit","Prōpositus","proposuerat","prōposuerimus","prōposuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Id eane de causa, quam legatis pronuntiarunt, an perfidia adducti fecerint, quod nihil nobis constat, non videtur pro certo esse {{proponendum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propositum","latin":"prōpositum, -ī (n.)","headword":"prōpositum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"objective, point","forms":["proposita","prōpositī","prōpositum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo tuta, neu suis sint ad detrectandam militiam receptacula neu Romanis {{proposita}} ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propraetor","latin":"prōpraetor, -ōris (m.)","headword":"prōpraetor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"propraetor","forms":["propraetōre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Priusquam satis certa cōnsilia essent, repēns alia nūntiātur clādēs: quattuor mīlia equitum, cum Centēniō {{propraetōre}} missa ad collegam ab Servīliō cōnsule, in Umbriā ab Hannibale circumventa.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proprie","latin":"proprie","headword":"proprie","letter":"p","pos":"adverb","posGroup":"adverb","english":"particularly, specifically, especially; properly, appropriately, rightly","forms":["propriē"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Nōmen quid est?' Discipulus: 'Pars ōrātiōnis cum cāsū, corpus aut rem propriē significāns; aut enim ūnīus nōmen est et proprium dīcitur, aut multōrum et appellātīvum.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"proprium","latin":"proprium, -ī","headword":"proprium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"(nōmen) proper noun","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"proprius","latin":"proprius","headword":"proprius","letter":"p","pos":"adjective","posGroup":"adjective","english":"proper, one’s own","forms":["propria","propriae","propriam","propriōs","proprium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vix perāctō sacrificiō vēnit Samūēl, rēgemque graviter reprehendit, quod mūnus {{proprium}} sacerdōtum sibi temere arrogāvisset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"propter","latin":"propter","headword":"propter","letter":"p","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) because of; on account of, because of (+ acc.)","forms":["propter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summam imperi se consulto nulli discedentem tradidisse, ne is multitudinis studio ad dimicandum impelleretur; cui rei {{propter}} animi mollitiem studere omnes videret, quod diutius laborem ferre non possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propter esse","latin":"propter esse","headword":"propter esse","letter":"p","pos":"","posGroup":"other","english":"to be nearby","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"propterea","latin":"proptereā","headword":"proptereā","letter":"p","pos":"adverb","posGroup":"adverb","english":"therefore","forms":["propterea"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Id silentio noctis conati non magna iactura suorum sese effecturos sperabant, {{propterea}} quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua intercedebat, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propugnaculum","latin":"propugnaculum, propugnaculi","headword":"propugnaculum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"bulwark, rampart; defense","forms":["prōpugnācula"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"exercet portusve aut {{prōpugnācula}} bellō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"propugnator","latin":"propugnator, propugnatoris","headword":"propugnator","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"defender; champion","forms":["propugnatoribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a {{propugnatoribus}} vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"propugno","latin":"propugno, propugnare, propugnavi, propugnatus","headword":"propugno","letter":"p","pos":"verb","posGroup":"verb","english":"fight (on the defensive)","forms":["propugnantes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Multitudine telorum ex turribus {{propugnantes}} deturbant, aggere et cratibus fossas explent, falcibus vallum ac loricam rescindunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prora","latin":"prōra, -ae","headword":"prōra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"prow","forms":["prōrā","prōram"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"Rōstra\" nōmen est huius locī, quia rōstrīs nāvium captārum ōrnātur (\"rōstrum\" enim vocantur eae hastae ferreae quae ē prōrā nāvis longae eminent velut rōstrum avis).","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proripio","latin":"proripio, proripere, proripui, proreptus","headword":"proripio","letter":"p","pos":"verb","posGroup":"verb","english":"drag or snatch away; rush or burst forth","forms":["prōripuit"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Deinde sē ex cūriā domum {{prōripuit}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"prorsus","latin":"prorsus","headword":"prorsus","letter":"p","pos":"adverb","posGroup":"adverb","english":"forwards, right onward; absolutely, entirely, utterly, by all means; in short","forms":["prōrsus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Igitur color eī exsanguis, foedī oculī, citus modō, modo tardus incessus: {{prōrsus}} in faciē vultūque vēcordia inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"proscribere","latin":"(prōscrībō) prōscrībere","headword":"prōscrībere","letter":"p","pos":"verb","posGroup":"verb","english":"proscribe, outlaw; to proscribe, outlaw","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"proscribo","latin":"proscribo, proscribere, proscripsi, proscriptus","headword":"proscribo","letter":"p","pos":"verb","posGroup":"verb","english":"announce, make public, post, advertise; proscribe, deprive of property","forms":["prōscrīpsērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam dum Sulla Achāiā atque Asiā Mithridāten vincit, Marius, quī fugātus erat, et Cornēlius Cinna, ūnus ex cōnsulibus, bellum in Ītaliā reparāvērunt, et ingressī urbem Rōmam nōbilissimōs ē senātū et cōnsulārēs virōs interfēcērunt, multōs {{prōscrīpsērunt}}, ipsīus Sullae domō ēversā fīliōs et uxōrem ad fugam compulērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proscriptio","latin":"proscriptio, proscriptionis","headword":"proscriptio","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"advertisement; notice of confiscation; proscription, pub of names of outlaws","forms":["prōscrīptiōnem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Catilīna pollicērī tabulās novās, {{prōscrīptiōnem}} locuplētium, magistrātūs, sacerdōtia, rapīnās, alia omnia quae bellum atque libīdō victōrum fert. ‘Praetereā esse in Hispāniā citeriōre Pīsōnem, in Maurētāniā cum exercitū P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"proscriptus","latin":"proscriptus, proscripti","headword":"proscriptus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"proscribed person, outlaw","forms":["prōscrīptōrum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed ea rēs magnae initium clādis fuit: nam utī quisque domum aut vīllam, postrēmō vās aut vestīmentum alicuius concupīverat, dabat operam ut is in {{prōscrīptōrum}} numerō esset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"prosequi","latin":"(prōsequor) prōsequī (< sequī)","headword":"prōsequī","letter":"p","pos":"verb","posGroup":"verb","english":"accompany, honor; to honour, praise; to escort","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"prosequor","latin":"prosequor, prosequi, prosecutus sum","headword":"prosequor","letter":"p","pos":"verb","posGroup":"verb","english":"pursue; escort; describe in detail","forms":["prōsecūtus","prōsequantur","prōsequentibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quōrum agmen imperātor secūtus — {{prōsequentibus}} cūnctīs 'servātōrem' 'līberātōrem'que acclāmantibus — eādem quā vēnerat viā Elatēam rediit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proserpina","latin":"Proserpina, -ae","headword":"Proserpina","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Proserpina (goddess of the underworld)","forms":["Proserpinā","Proserpinae","Proserpinam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ad mortuōrum igitur rēgnum dēscendere voluit, ut ā Plūtōne, rēge Īnferōrum, quī ibi cum Proserpinā, eius coniuge, imperābat, peteret ut Eurydicē sibi redderētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"prosilio","latin":"prosilio, prosilire, prosilivi, -","headword":"prosilio","letter":"p","pos":"verb","posGroup":"verb","english":"jump/leap up/forward; rush/leap/spring forth/to; gush/break/jut out","forms":["prosiliunt"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"si quis adest, iussae {{prosiliunt}} lacrimae!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"prosilire","latin":"(prōsiliō) prōsilīre, prōsiluisse","headword":"prōsilīre","letter":"p","pos":"verb","posGroup":"verb","english":"spring forth; to leap forth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"prospero","latin":"prospero, prosperare, prosperavi, prosperatus","headword":"prospero","letter":"p","pos":"verb","posGroup":"verb","english":"cause to succeed, further","forms":["prosperō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Licinius Crassus cōnsul, cui mandātum erat, in Macedoniam trānsiit, levibusque expedītiōnibus, equestribus proeliīs, in Thessaliā cum Perseō, quem Cotys, rēx Thrāciae, adiuvābat, parum prosperō ēventū pugnāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"prosperus","latin":"prosperus, -a, -um","headword":"prosperus","letter":"p","pos":"adjective","posGroup":"adjective","english":"successful, favorable","forms":["prōspera","prosperae","prōsperē","prosperīs","prōsperum","prosperus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quod audiēns Eliezer ēgit grātiās Deō, quī tribuisset iter {{prōsperum}} sibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"prospicere","latin":"(prōspiciō) prōspicere,prōspexisse,  prōspectum","headword":"prōspicere","letter":"p","pos":"verb","posGroup":"verb","english":"look out, look ahead; to look out, gaze","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"prospicio","latin":"prospicio, prospicere, prospexi, prospectus","headword":"prospicio","letter":"p","pos":"verb","posGroup":"verb","english":"foresee; see far off; watch for, provide for, look out for","forms":["Prospectu","prōspectum","prōspexisset","prōspexit","prōspicere","prōspicerēs","prōspiceret","prospiciam","prōspiciēbant","prōspiciēbat","prōspiciēns","prōspiciō","prōspicis","prōspicit","prōspiciunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas excidere conatus esset, a multitudine oppressus ac sibi desperans, multis iam vulneribus acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem certe vitae {{prospiciam}}, quos cupiditate gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prosternere","latin":"(prōsternō) prōsternere (< sternere)","headword":"prōsternere","letter":"p","pos":"","posGroup":"other","english":"knock down, overthrow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"prosterno","latin":"prosterno, prosternere, prostravi, prostratus","headword":"prosterno","letter":"p","pos":"verb","posGroup":"verb","english":"knock over, lay low; strike down, overthrow; exhaust; debase/demean; prostrate","forms":["prosternere","prōstrāvērunt","prōstrāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nolite hos vestro auxilio exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi imbecillitate omnem Galliam {{prosternere}} et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prosum","latin":"prosum, prodesse, profui, profuturus","headword":"prosum","letter":"p","pos":"verb","posGroup":"verb","english":"be useful, be advantageous, benefit, profit (with DAT)","forms":["prōdērunt","prōdest","prōfuerant","prōfuerint","prōfuit","prōsint","prōsit","prōsum","prōsunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc appārēbit quid sua illī {{prōsint}} somnia.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"protegere","latin":"(prōtegō) prōtegere (< tegere)","headword":"prōtegere","letter":"p","pos":"","posGroup":"other","english":"protect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"protego","latin":"protego, protegere, protexi, protectus","headword":"protego","letter":"p","pos":"verb","posGroup":"verb","english":"cover, protect","forms":["prōtegentibus","prōtegere","prōtegitur","prōtēxit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{prōtegitur}} laevā sēmireducta manū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"protendo","latin":"prōtendō, -ere, -tendī, -tēnsum","headword":"prōtendō","letter":"p","pos":"verb","posGroup":"verb","english":"to stretch out, extend","forms":["Prōtende","prōtendēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tunc Deus Moȳsī: “{{Prōtende}}” inquit “dextram tuam in mare, et dīvidē aquās, ut illae Hebraeīs gradientibus iter siccum praebeant.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"proterreo","latin":"proterreo, proterrere, proterrui, proterritus","headword":"proterreo","letter":"p","pos":"verb","posGroup":"verb","english":"frighten","forms":["proterrent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nostri, ut superioribus diebus, ut cuique erat locus attributus, ad munitiones accedunt; fun: dis librilibus sudibusque, quas in opere disposuerant, ac glandibus Gallos {{proterrent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"protervus","latin":"protervus, proterva, protervum","headword":"protervus","letter":"p","pos":"adjective","posGroup":"adjective","english":"violent, reckless; impudent, shameless","forms":["protervē","protervus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{protervus}} -ā -um — audāx, temeràrius","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"protinus","latin":"prōtinus","headword":"prōtinus","letter":"p","pos":"adverb","posGroup":"adverb","english":"immediately, at once; at once, immediately; immediately","forms":["protinus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fit {{protinus}} hac re audita ex castris Gallorum fuga.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"protrahere","latin":"(prōtrahō) prōtrahere (< trahere)","headword":"prōtrahere","letter":"p","pos":"verb","posGroup":"verb","english":"pull out, draw out; to draw out, prolong","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"protraho","latin":"protraho, protrahere, protraxi, protractus","headword":"protraho","letter":"p","pos":"verb","posGroup":"verb","english":"drag forward, produce; bring to light, reveal; prolong, protract","forms":["prōtrahēbātur","prōtraherentur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi eō ventum est, Turnum ex somnō excitātum circumsistunt custōdēs; comprehensīsque servīs, quī caritāte dominī vim parābant, cum gladiī abditī ex omnibus locīs aedium {{prōtraherentur}}, ēnimvērō manifēsta rēs vīsa est, iniectaeque Turnō catēnae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proturbo","latin":"proturbo, proturbare, proturbavi, proturbatus","headword":"proturbo","letter":"p","pos":"verb","posGroup":"verb","english":"drive/push away/out of the way; drive out in confusion; repulse; pitch forward","forms":["proturbare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Subito clamore sublato, qua significatione qui in oppido obsidebantur de suo adventu cognoscere possent, crates proicere, fundis, sagittis, lapidibus nostros de vallo {{proturbare}} reliquaque quae ad oppugnationem pertinent parant administrare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"provectus","latin":"provectus, provecta, provectum","headword":"provectus","letter":"p","pos":"adjective","posGroup":"adjective","english":"advanced, late; elderly","forms":["prōvectae","prōvectās","prōvectī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ergō ubi prīmum ventus secundus fuit, iterum in altum prōvectī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"provehere","latin":"(prōvehō) prōvehere (< vehere)","headword":"prōvehere","letter":"p","pos":"","posGroup":"other","english":"carry forward, convey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"provehi","latin":"prōvehī","headword":"prōvehī","letter":"p","pos":"verb","posGroup":"verb","english":"to sail forward, be carried on","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"provenio","latin":"provenio, provenire, proveni, proventus","headword":"provenio","letter":"p","pos":"verb","posGroup":"verb","english":"come forth; come into being; prosper","forms":["prōvenientem","prōvenīre","prōvēnit","prōventūra"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum Tobiās urbī appropinquāret, māter eius, ut solēbat, in vertice montis sedēbat, unde prōspicere in longinquum posset; vīdit illum {{prōvenientem}}, currēnsque nūntiāvit virō suō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"proventus","latin":"prōventus, -ūs","headword":"prōventus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"growth, crop, harvest","forms":["proventum","proventus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Errare, si qui in bello omnes secundos rerum {{proventus}} exspectent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"providentia","latin":"providentia, providentiae","headword":"providentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"foresight, foreknowledge; providence","forms":["prōvidentia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quibus ille amīce: accēdite, inquit, ad mē: ego sum Iōsēphus, frāter vester, quem vēndidistis mercātōribus euntibus in Aegyptum; nōlīte timēre: Deī {{prōvidentia}} id factum est ut ego salūtī vestrae cōnsulerem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"provideo","latin":"provideo, providere, providi, provisus","headword":"provideo","letter":"p","pos":"verb","posGroup":"verb","english":"foresee; provide for, make provision; with DAT","forms":["provideat","prōvidēbit","prōvidēbō","prōvidendō","prōvidendum","providere","prōvidērētis","provideri","prōvīderīs","prōvidet","prōvīdī","prōvīdimus","prōvīdisset","provisa","provisum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Omnes nostras pabulationes frumentationesque observabat dispersosque, cum longius necessario procederent, adoriebatur magnoque incommodo adficiebat, etsi quantum ratione {{provideri}} poterat ab nostris occurrebatur, ut incertis temporibus diversisque itineribus iretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"providere","latin":"(prōvideō) prōvidēre (< vidēre)","headword":"prōvidēre","letter":"p","pos":"","posGroup":"other","english":"see to it, take care","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"provincia","latin":"prōvincia, -ae","headword":"prōvincia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"province","forms":["provincia","provinciae","provinciam","prōvinciās","prōvinciīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum tota {{provincia}} habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"provincialis","latin":"provincialis, provincialis","headword":"provincialis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"provincial (person)","forms":["provincialibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eo cum venisset, timentes confirmat, praesidia in Rutenis {{provincialibus}}, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"provocare","latin":"(prōvocō) prōvocāre","headword":"prōvocāre","letter":"p","pos":"","posGroup":"other","english":"challenge, appeal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"provocatio","latin":"prōvocātiō, -ōnis ( f.)","headword":"prōvocātiō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"appeal; appeal to the people","forms":["prōvocātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque prōvocātiō facta ad populum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"provoco","latin":"provoco, provocare, provocavi, provocatus","headword":"provoco","letter":"p","pos":"verb","posGroup":"verb","english":"call forth; challenge; provoke","forms":["prōvocābat","prōvocantem","prōvocantis","prōvocāvit","prōvocō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum duae aciēs in cōnspectū essent, Philistaeus quīdam, nōmine Goliathus, vir mīrae magnitūdinis, prōgressus est ante ōrdinēs, et ūnum ex Hebraeīs saepe {{prōvocābat}} ad singulāre certāmen.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"provolare","latin":"(prōvolō) prōvolāre","headword":"prōvolāre","letter":"p","pos":"","posGroup":"other","english":"rush forth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"provolo","latin":"provolo, provolare, provolavi, provolatus","headword":"provolo","letter":"p","pos":"verb","posGroup":"verb","english":"fly forward; dash forth","forms":["prōvolat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ipse ad prīmōrēs Rōmulus {{prōvolat}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"proximo","latin":"proximo, proximare, proximavi, proximatus","headword":"proximo","letter":"p","pos":"verb","posGroup":"verb","english":"come/draw near, approach; be near","forms":["proximo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Horum esse alterum Convictolitavem, florentem et inlustrem adulescentem; alterum Cotum, antiquissima familia natum: atque ipsum hominem summae potentiae et magnae cognationis, cuius frater Valetiacus {{proximo}} anno eundem magistratum gesserit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"proximus","latin":"proximus, -a, -um","headword":"proximus","letter":"p","pos":"adjective","posGroup":"adjective","english":"closest; nearest, closest","forms":["proxima","proximam","proximē","proximī","proximis","proximum","proximus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et {{proximis}} tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"prudens","latin":"prūdēns, prūdentis","headword":"prūdēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"prudent, clever; prudent, wise","forms":["prūdēns","prūdentem","prūdentēs","prūdentī","prūdentiōrēs","prūdentissimī","prūdentissimō","prūdentissimum","prūdentissimus","prūdentius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “Sextus discipulus industrius ac {{prūdēns}} est, ut scīs; ergō bene discit, quamquam male docētur ā magistrō pigrō atque stultō!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"prudenter","latin":"prūdenter","headword":"prūdenter","letter":"p","pos":"adverb","posGroup":"adverb","english":"wisely, sensibly","forms":["prūdenter"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Iūlius frontem contrahit et 'Agricola' inquit 'ipse nōn sum, sed multīs agricolīs praesum ac dīligenter cūrō ut colōnī agrōs meōs bene cōlant.' Orontēs, quī vīta rūstica nōn fruitur, '{{Prūdenter}} facis' inquit 'quod agrōs ipse nōn colis.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"prudentia","latin":"prūdentia, -ae","headword":"prūdentia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"intelligence, proficiency; practical wisdom, good sense; foresight, practical wisdom","forms":["prūdentia","prūdentiae","prūdentiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Admīrātī sunt omnēs singulārem rēgis {{prūdentiam}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pruina","latin":"pruīna, -ae","headword":"pruīna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"hoarfrost, rime; hoar-frost","forms":["pruīnā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cernis autem eandem terram quasi quibusdam redimītam et circumdatam cingulīs, ē quibus duōs maximē inter sē dīversōs et caelī verticibus ipsīs ex utrāque parte subnīxōs obriguisse pruīnā vidēs, medium autem illum et maximum sōlis ārdōre torrērī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pruna","latin":"pruna, prunae","headword":"pruna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"glowing charcoal, a live coal","forms":["prūna"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ibi in vāsīs prīmum holera et olīvās et cāseum et pānem, deinde {{prūna}} et nucēs et mala et ūvās et pōculum lactis plēnum hospitibus obtulērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"prunum","latin":"prunum, pruni","headword":"prunum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"plum","forms":["prūnum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"(täbulae) sūrsum versā; supînä manû drāta; pl tēctum (intexius) Priāpus -î m, deus frūctuum (ut mälum, pirum, {{prūnum}}, suāvius esse : s. tē habēre vîderint (: videant) quid Nec diū mîrärî licuit tam ēlegantēs strophās; nam repente lacūnāria sonāre coepērunt tôtumque triclînium intremuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"psallo","latin":"psallo, psallere, psalli, -","headword":"psallo","letter":"p","pos":"verb","posGroup":"verb","english":"play on the cithara (by plucking with fingers); sing the Psalms (eccl.) (L+S)","forms":["psallere"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Haec mulier genere atque fōrma, praetereā virō atque līberīs satis fortūnāta fuit; litterīs Graecīs et Latīnīs docta, {{psallere}} et saltāre ēlegantius quam necesse est probae, multa alia, quae īnstrūmenta luxuriae sunt.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"pubes","latin":"pūbēs, (gen. puberis)","headword":"pūbēs","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"mature, grown up (m. pl. adults)","forms":["pūbem","pūberem","pūberēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipsa Venus {{pūbem}}, quotiēns vēlāmina","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"publicanus","latin":"pūblicānus, -ī","headword":"pūblicānus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"tax-gatherer, publican; tax-farmer, publican","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"publicare","latin":"(pūblicō) pūblicāre","headword":"pūblicāre","letter":"p","pos":"","posGroup":"other","english":"make public property, confiscate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"publice","latin":"publice","headword":"publice","letter":"p","pos":"adverb","posGroup":"adverb","english":"publicly; at public expense","forms":["publice"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eo cum Eporedorix Viridomarusque venissent et de statu civitatis cognovissent, Litaviccum Bibracte ab Aeduis receptum, quod est oppidum apud eos maximae auctoritatis, Convictolitavem magistratum magnamque partem senatus ad eum convenisse, legatos ad Vercingetorigem de pace et amicitia concilianda {{publice}} missos, non praetermittendum tantum commodum existimaverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"publico","latin":"publico, publicare, publicavi, publicatus","headword":"publico","letter":"p","pos":"verb","posGroup":"verb","english":"confiscate; make public property; publish","forms":["pūblicandās","publicant","publico"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Interim nuntio allato omnes eorum milites in potestate Caesaris teneri, concurrunt ad Aristium; nihil {{publico}} factum consilio demonstrant; quaestionem de bonis direptis decernunt, Litavicci fratrumque bona publicant, legatos ad Caesarem sui purgandi gratia mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"publicus","latin":"pūblicus, -a, -um","headword":"pūblicus","letter":"p","pos":"adjective","posGroup":"adjective","english":"public; public, common","forms":["pūblica","pūblicae","publicam","pūblicārum","pūblicās","pūblicī","pūblicīs","pūblicōrum","publicum","pūblicus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres familiae repente in {{publicum}} procurrerunt flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"publius","latin":"Publius, Publi","headword":"Publius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Publius (Roman praenomen); (abb. P.)","forms":["Pūblī","Pūblius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Alia praenōmina Latīna sunt 'Aulus', 'Decimus', 'Gāius', '{{Pūblius}}', 'Sextus', 'Titus'.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"pudendus","latin":"pudendus, pudenda, pudendum","headword":"pudendus","letter":"p","pos":"adjective","posGroup":"adjective","english":"causing shame, shameful, scandalous, disgraceful, abominable","forms":["pudenda","pudendae","pudendās","pudendum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec locūtus, ē silvā ēgrediēbātur Ulixēs; ex arbore quādam rāmum multīs cum foliīs frēgit manū, ut partēs {{pudendās}} sibi tegeret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pudens","latin":"pudēns (gen. pudentis)","headword":"pudēns","letter":"p","pos":"adjective","posGroup":"adjective","english":"modest, behaving properly; modest, chaste","forms":["pudēns"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{pudēns}} «€» pudēns — pudīcus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pudeo","latin":"pudeo, pudere, pudui, puditus","headword":"pudeo","letter":"p","pos":"verb","posGroup":"verb","english":"be ashamed; make ashamed; [me pudet => I am ashamed]","forms":["puduit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nōn eum {{puduit}} ab Assyrils auxilium petere, aurumque et argentum ā templō ablātum illōrum regl dōnō mittere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pudere","latin":"(pudet) pudēre, puduit","headword":"pudēre","letter":"p","pos":"verb","posGroup":"verb","english":"feel shame (impersonal); to shame (impersonal)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"pudet","latin":"pudet, pudere, -, puditus est","headword":"pudet","letter":"p","pos":"verb","posGroup":"verb","english":"it shames, make ashamed; [me tui pudet => I am ashamed of you]","forms":["pudeat","pudeātur","pudēbat","pudet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Adiuvat rem proclinatam Convictolitavis plebemque ad furorem impellit, ut facinore admisso ad sanitatem reverti {{pudeat}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pudibundus","latin":"pudibundus, -a, -um","headword":"pudibundus","letter":"p","pos":"","posGroup":"other","english":"shamefaced","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pudicitia","latin":"pudīcitia, -ae","headword":"pudīcitia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"chastity, virtue; modesty, chastity","forms":["pudīcitiā","pudīcitiae","pudīcitiam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"quia {{pudīcitiae}} huius vitium mē hinc absente est additum.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"pudicus","latin":"pudīcus, -a, -um","headword":"pudīcus","letter":"p","pos":"adjective","posGroup":"adjective","english":"chaste, pure","forms":["pudīca","pudīcae","pudīcam","pudīcus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"pudēns «€» pudēns — {{pudīcus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pudor","latin":"pudor, pudōris","headword":"pudor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) (good) shame","forms":["pudor","pudōre","pudōrem","pudōrī","pudōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Pudor}} hoc, timor impedit illud.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"puella","latin":"puella, -ae","headword":"puella","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"girl; girl, maiden","forms":["puella","puellae","puellam","puellārum","puellās","puellīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quae est {{puella}} quae dormit?","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"puer","latin":"puer, -erī","headword":"puer","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"boy","forms":["puer","puerī","puerīs","puerō","puerōrum","puerōs","puerum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Puerī nīdum aquilae reperīre nōn possunt.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"puerilis","latin":"puerīlis, -e","headword":"puerīlis","letter":"p","pos":"adjective","posGroup":"adjective","english":"of children","forms":["puerīle","puerīlem","puerīlibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum esset puer, nihil tamen {{puerīle}} gessit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pueriliter","latin":"pueriliter","headword":"pueriliter","letter":"p","pos":"adverb","posGroup":"adverb","english":"childishly, foolishly","forms":["puerīliter"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fāma est etiam Hannibalem annōrum fermē novem, {{puerīliter}} blandientem patrī Hamilcarī ut dūcerētur in Hispāniam, cum — perfectō Āfricō bellō — exercitum eō trāiectūrus sacrificāret, ārīs admōtum tāctīsque sacrīs iūre iūrandō adactum ā patre esse 'sē, cum prīmum posset, hostem fore populō Rōmānō.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pueritia","latin":"pueritia, -ae","headword":"pueritia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"boyhood, childhood; childhood","forms":["pueritia","pueritiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tantum tamen opēs Latīnōrum crēverant — maximē victīs Etrūscīs — ut ne morte quidem Aenēae nec deinde inter rēgnum muliebre et Ascaniī {{pueritiam}} aut Etrūscī aut ūllī aliī fīnitimī arma movēre ausī sint.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"puerpera","latin":"puerpera, puerperae","headword":"puerpera","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"woman in labor, woman who has been/is in process of being delivered of child","forms":["puerperae"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"ubi uterō exortī dolōrēs, ut solent {{puerperae}},","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"puerulus","latin":"puerulus, -ī","headword":"puerulus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"small boy; little boy","forms":["puerulīs","puerulō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc, lūctū dēpositō, iussit sibi appōnī cibōs, mīrantibusque aulicīs dīxit: “Aegrōtante puerulō ieiūnus ōrābam, spērāns scīlicet Deum plācārī posse; nunc autem, cum mortuus sit, cūr frūstrā lūgeam?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pugna","latin":"pugna, -ae","headword":"pugna","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"fight; fight, battle","forms":["pugna","pugnae","pugnam","pugnās","pugnīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Erat Romanis nec loco nec numero aequa contentio; simul et cursu et spatio {{pugnae}} defatigati non facile recentes atque integros sustinebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pugnat","latin":"pugnat, pugnāre","headword":"pugnat","letter":"p","pos":"verb","posGroup":"verb","english":"fight; fights; fights, does battle","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pugnator","latin":"pugnātor, -ōris (m.)","headword":"pugnātor","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"fighter, combatant; fighter, soldier","forms":["pugnātōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aemilius cōnsul centum et quattuor nāvēs hostium dēmersit, trīgintā cum {{pugnātōribus}} cēpit, quīndecim mīlia hostium aut occīdit aut cēpit, mīlitem suum ingentī praedā dītāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pugno","latin":"pugnō","headword":"pugnō","letter":"p","pos":"verb","posGroup":"verb","english":"to fight","forms":["pugnābant","pugnābat","pugnābātur","pugnābis","pugnābō","pugnandi","pugnandō","pugnandum","pugnans","pugnant","pugnantem","pugnantēs","Pugnantia","pugnantibus","pugnantium","pugnāre","pugnārent","pugnāret","pugnaretur","pugnari","pugnat","pugnāta","pugnātum","Pugnatur","pugnātūrum","pugnātūrus","pugnaverant","pugnāverat","pugnāvērunt","pugnāvimus","pugnāvisse","pugnāvissēmus","pugnāvistis","pugnāvit","pugnent","pugnet","pugnō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His erat inter se de principatu contentio, et in illa magistratuum controversia alter pro Convictolitavi, alter pro Coto summis opibus {{pugnaverant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pugnus","latin":"pugnus, -ī","headword":"pugnus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"fist","forms":["pugnum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Sextus {{pugnum}} ante oculōs Mārcī tenēns “Dīc” inquit “‘fēminam pulchriōrem esse mātrem meam quam tuam’!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pulcher","latin":"pulcher, -chra, -chrum","headword":"pulcher","letter":"p","pos":"adjective","posGroup":"adjective","english":"beautiful, fine; beautiful, handsome; beautiful, lovely; beautiful; beautiful, pretty, fair; beautiful, fair","forms":["pulcher","pulcherrimā","pulcherrimae","pulcherrimam","pulcherrimās","pulcherrimē","pulcherrimīs","pulcherrimō","pulcherrimōs","pulcherrimum","pulcherrimus","pulchra","pulchrae","pulchram","pulchrās","pulchrī","pulchrior","pulchriōra","pulchriōrem","pulchriōrēs","pulchriōribus","pulchrīs","pulchrius","pulchrō","pulchrōs","pulchrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne {{pulcherrimam}} prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus succendere cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pulchre","latin":"pulchrē","headword":"pulchrē","letter":"p","pos":"adverb","posGroup":"adverb","english":"finely, beautifully","forms":["pulchrē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ego illās litterās laudāvī: dīxī ‘Sextum et pulchrē et rēctē scrīpsisse’.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pulchritudo","latin":"pulchritūdō, pulchritūdinis","headword":"pulchritūdō","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) beauty","forms":["pulchritūdine","pulchritūdinem","pulchritūdinis","pulchritūdō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum Cornēlius rīdēns “Id nōn dīcis” inquit “cum {{pulchritūdinem}} tuam laudō!” — sed eō ipsō tempore ātrium illūstrātur clārissimō fulgure atque māximus tonitrus audītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pullarius","latin":"pullarius, pullari(i)","headword":"pullarius","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"keeper of the sacred chickens","forms":["pullārius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô etiam {{pullārius}} erat - omnīs mortuum plangere/plôräre : plangere/plôräre dē mortuô (servum) macū (: ê potestāte minimus, quārta pars assis solidus -ā -um 4-) liquidus; sēcum in sepulcrum tulisse que pretiurrx; quid ā. mordeat Sâturnälia agere : in luxū leô : vir fortis ac ferôx rēctus, certus: probus, ﬁdusﬁdt micāre: lūdere digitîs extentîs spūtum (-î n) ex ôre êmittere pānem quem asse ëmissês...","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pullum","latin":"pullum, pulli","headword":"pullum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"dark-gray cloth(es) (as pl.)","forms":["pullum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego quidem paene prôiëcî partem meam, nam Vidēbātur mihi iam in {{pullum}} coîsse.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"pullus","latin":"pullus, -ī","headword":"pullus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"young (of an animal); somber, grey; chick","forms":["pullī","pullīs","Pullō","pullōrum","pullōs","pullus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Syra: “Ecce nīdus in quō quīnque pullī sunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pulmentarium","latin":"pulmentarium, pulmentarii","headword":"pulmentarium","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"relish","forms":["pulmentāria","pulmentārium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēscendat hūc! [Ad cocum quī dēscendit] Tolle, coque dīligenter {{pulmentāria}}! [Ad servum] Affer clāvem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"pulmentum","latin":"pulmentum, pulmenti","headword":"pulmentum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"appetizer, small meat/fish starter portion; savory; relish/condiment/food (L+S)","forms":["pulmentum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quādam diē, cum Iacobus sibi parāvisset {{pulmentum}} ex lentibus, venit Esāüs fessīs dē viā, et dīxit frātrī: dā mihi hoc pulmentum; nam redeō rūre exanimātus lassitūdine.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"pulmo","latin":"pulmō, pulmōnis","headword":"pulmō","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"(m.) lung","forms":["pulmōnēs","pulmōnibus","pulmōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cum vērō amīcī, quī apud eum stābant, ferrum ēdūxērunt, ūna cum sagittā cruentā pars {{pulmōnis}} est extracta.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pulpitum","latin":"pulpitum, pulpiti","headword":"pulpitum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"stage, wooden platform (for performance); lectern/pulpit/bookstand; desk (Cal)","forms":["pulpita"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec fuerant liquidō. {{pulpita}} rubra crocó;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pulsare","latin":"pulsāre","headword":"pulsāre","letter":"p","pos":"verb","posGroup":"verb","english":"to knock, strike","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pulsat","latin":"pulsat","headword":"pulsat","letter":"p","pos":"verb","posGroup":"verb","english":"strike, hit, knock (at); hits, strikes; knocks, beats","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"pulso","latin":"pulso, pulsare, pulsavi, pulsatus","headword":"pulso","letter":"p","pos":"verb","posGroup":"verb","english":"beat; pulsate","forms":["pulsābat","pulsāmus","pulsant","pulsantur","pulsāre","pulsat","pulsāta","pulsāte","pulsātī","pulsātis","pulsātum","pulsātur","pulsātus","pulsāverant","pulsāverat","pulsāveritis","pulsāvērunt","pulsāvī","pulsāvimus","pulsāvisset","pulsāvistī","pulsāvistis","pulsāvit","Pulsēmus","pulsō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iūlia canem, quae ad pedēs eius iacet, pede {{pulsat}}: “Age, curre, Margarīta crassa!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pulsus","latin":"pulsus, -ūs","headword":"pulsus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"thrust, impulse; push, impulse","forms":["pulsūs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ergō Coriolānus, Rōma {{pulsūs}}, ad Volscōs cōnfūgit, quī ōlim hostēs eius fuerant, iīsque persuāsit, ut Rōmānōrum urbem oppugnārent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pulverulentus","latin":"pulverulentus, pulverulenta, pulverulentum","headword":"pulverulentus","letter":"p","pos":"adjective","posGroup":"adjective","english":"dusty","forms":["pulverulenta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{pulverulenta}} fugā glomerant montīsque relinquunt.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"pulvillus","latin":"pulvillus, pulvilli","headword":"pulvillus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"little pillow","forms":["Pulvillō","Pulvillum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Horātium {{Pulvillum}} collēgam sibi sūmpsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pulvinar","latin":"pulvīnar, -āris (n.)","headword":"pulvīnar","letter":"p","pos":"","posGroup":"other","english":"couch for the gods","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"pulvinus","latin":"pulvinus, pulvini","headword":"pulvinus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"cushion/pillow; raised bed of earth; raised border; bath back; platform/socket","forms":["pulvīnum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{pulvīnum}} facilī composuisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pulvis","latin":"pulvis, -eris (m.)","headword":"pulvis","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"dust; dust, sand","forms":["pulvere","pulverem","pulveris","pulvis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dum tamen hanc sperat, dum praecorrumpere dōnīs\nmē cupit, \"ēlige\" ait \"virgō Cūmaea, quid optēs:\noptātīs potiēre tuīs.\" Ego {{pulveris}} haustī\nostendī cumulum: quot habēret corpora pulvis,\ntot mihi nātālēs contingere vāna rogāvī;\nexcidit, ut peterem iuvenēs quoque prōtinus annōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pumex","latin":"pumex, pumicis","headword":"pumex","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"pumice stone, similar volcanic rock; (esp. used to polish books/depilatory)","forms":["pūmex","pūmice"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec tuā mordàci {{pūmice}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"punctum","latin":"pūnctum, -ī","headword":"pūnctum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"dot, point, speck; point, dot","forms":["pūnctum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam ipsa terra ita mihi parva vīsa est ut mē imperiī nostrī, quō quasi {{pūnctum}} eius attingimus, paenitēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"punicus","latin":"Punicus, Punica, Punicum","headword":"Punicus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Carthaginian, Punic; of/associated with Carthage; scarlet, bright red","forms":["Pūnica","Pūnicī","Pūnicīs","Pūnīcō","Pūnicum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam Proserpina, dum errat in hortīs quī sub terrā sunt, malum {{Pūnicum}} ex arbore carpserat; ex quō mālō septem grāna sūmpta ēderat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"punio","latin":"pūniō, pūnīre","headword":"pūniō","letter":"p","pos":"verb","posGroup":"verb","english":"punish","forms":["pūniantur","pūniās","pūniendam","pūniendās","pūniendī","pūniendō","pūniendum","pūniendus","pūniētur","pūnīre","pūnīret","pūnīrētur","pūnīrī","pūnīta","pūnītī","pūnītum","pūnītūram","pūnīverint","pūnīvī","pūnīvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cūr mē sīc {{pūnīvit}} Iuppiter?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"punire","latin":"pūnīre","headword":"pūnīre","letter":"p","pos":"verb","posGroup":"verb","english":"to punish","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"punit","latin":"pūnit","headword":"pūnit","letter":"p","pos":"verb","posGroup":"verb","english":"punishes","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"puppis","latin":"puppis, puppis","headword":"puppis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"(f.) stern, poop deck; stern (of a ship)","forms":["puppe","puppēs","puppī","puppibus","puppim","puppis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Alcyonē tamen nōn surrēxit, sed oculīs ūmentibus marītum quaerēbat, quī in celsā puppī stāns manum agitābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"purgamentum","latin":"purgamentum, purgamenti","headword":"purgamentum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"sweepings, rubbish, filth","forms":["pūrgāmentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque Fortfmātā, ut ex aequô iûs frmum approbâret, maledîcere Trimalchiônî coepit et ‘{{pūrgāmentum}}’ ‘dēdecus’que prae- dicāre ‘quī nôn continēret libîdinem suam!’ Ultimô etiam Trimalchiô contrā, oftēnsus convîciô, calicem in faciem Fortūnātae immîsit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"purgare","latin":"(pūrgō) pūrgāre","headword":"pūrgāre","letter":"p","pos":"","posGroup":"other","english":"clean, purge, excuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"purgo","latin":"purgo, purgare, purgavi, purgatus","headword":"purgo","letter":"p","pos":"verb","posGroup":"verb","english":"make clean, cleanse; excuse","forms":["pūrgā","purgandi","pūrgāre","pūrgārem","pūrgārī","pūrgās","pūrgat","pūrgāvērunt","pūrgāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Interim nuntio allato omnes eorum milites in potestate Caesaris teneri, concurrunt ad Aristium; nihil publico factum consilio demonstrant; quaestionem de bonis direptis decernunt, Litavicci fratrumque bona publicant, legatos ad Caesarem sui {{purgandi}} gratia mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"purpura","latin":"purpura, -ae","headword":"purpura","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"purple","forms":["purpurā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ficere | mūrex -icis ;»? — purpurā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"purpureus","latin":"purpureus, -a, -um","headword":"purpureus","letter":"p","pos":"adjective","posGroup":"adjective","english":"purple","forms":["purpureā","purpureae","purpuream","purpureās","purpureīs","purpureōs","purpureum","purpureus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mūcius ergō, gladiō ē vāgīnā ēductō, in tabernāculum ingressus, in virum scrībentem impetum fēcit, quī, cum {{purpureīs}} vestīmentīs esset indūtus, rēx eī esse vidēbātur, et clāmāns “Ita tē, Porsenna, occīdō!”, eum gladiō percussit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"purum","latin":"purum, puri","headword":"purum","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"clear/bright/unclouded sky","forms":["pūrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ōceanus igitur et Tēthys eum aquā tōtīus maris omniumque flūminum lāvērunt, ut animum {{pūrum}} facerent corpusque mūtārent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"purus","latin":"pūrus, -a, -um","headword":"pūrus","letter":"p","pos":"adjective","posGroup":"adjective","english":"clean, pure; clean","forms":["pūrā","pūrae","pūram","pūrī","pūrior","pūrīs","pūrissimā","pūrissimae","pūrissimō","pūrō","pūrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hic ānulus ex aurō pūrō factus est, ānulus tuus ex ferrō, quod tenuī aurō operītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"pus","latin":"pus, puris","headword":"pus","letter":"p","pos":"noun (n.)","posGroup":"noun","english":"pus; foul/corrupt matter (from a sore); bitterness, gall, venom (Cas)","forms":["pūs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{pūs}} radī, terī, mollīrī potest","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"pusillus","latin":"pusillus, pusilla -um, pusillior -or -us, pusillissimus -a -um","headword":"pusillus","letter":"p","pos":"adjective","posGroup":"adjective","english":"tiny, wee, very small (amount/degree/extent); miniature, on a tiny scale","forms":["pusilla","pusillī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praeter- eä grande armārium in angulô vîdî, in cuius aediculā erant Larēs argenteî positī Venerisque signum marmoreum et pyxis aurea nôn {{pusilla}}, in quā barbam ipsîus Interrogāre ego ātriēnsem coepī ‘quās in mediô pictūrās habērent?’ “Îliada et Odys- sîan”","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"putat","latin":"putat, putāre","headword":"putat","letter":"p","pos":"verb","posGroup":"verb","english":"think, suppose; thinks, supposes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"puteo","latin":"puteo, putere, -, -","headword":"puteo","letter":"p","pos":"verb","posGroup":"verb","english":"stink, be rotten/putrid; smell bad; rot/decompose (in such a way as to stink)","forms":["puteō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nam ex eō puteō gregēs solēbant adaquārī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"puteus","latin":"puteus, putei","headword":"puteus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"well","forms":["puteī","puteum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ubi pervēnit in Mesopotamiam, cōnstitit cum camēlīs prope {{puteum}} aquae ad vesperum, quō tempore mulierēs solēbant convenīre ad haurientem aquam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"putidus","latin":"putidus, putida -um, putidior -or -us, putidissimus -a -um","headword":"putidus","letter":"p","pos":"adjective","posGroup":"adjective","english":"rotten/decaying; foul/stinking; unpleasant/offensive/tiresome/affected/pedantic","forms":["Pūtidus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Pūtidus}} est, totiēs sī mihi pōnis aprum!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"puto","latin":"putō, -āre, -āvī, -ātum","headword":"putō","letter":"p","pos":"verb","posGroup":"verb","english":"think; think, suppose","forms":["putā","putābam","putābant","putabat","putābātur","putābit","putābunt","putāns","putant","putantēs","putāre","putārem","putārent","putārēs","putāret","putārētis","putārētur","putās","putat","putatis","putātur","putāvī","putāvistis","putavit","putem","putēmus","pūtent","pūtēs","putet","pūtētis","putō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"His rebus comparatis, represso iam Lucterio et remoto, quod intrare intra praesidia periculosum {{putabat}}, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"pygmalion","latin":"Pygmalion, Pygmalionis","headword":"Pygmalion","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pygmalion; (brother of Dido, king of Tyre; also sculptor in love with his statue)","forms":["Pygmaliōn","Pygmaliōnī","Pygmaliōnis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Pygmaliōn}} vir Graecus fuit, quī magnam pecūniam, multōs amīcōs, multōs servōs habēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pyra","latin":"pyra, pyrae","headword":"pyra","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"funeral pile, pyre","forms":["pyrā","pyram"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Excipit Aenēān illīc animōque domōque\nnōn bene discidium Phrygiī lātūra marītī\nSīdōnis; inque {{pyram}} sacrī sub imāgine factā\nincubuit ferrō dēceptaque dēcipit omnēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pyramus","latin":"Pyramus, -ī","headword":"Pyramus","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"Pyramus (a youth)","forms":["Pyrame","Pyramī","Pyramus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"{{Pyramus}} iuvenis pulcherrimus et Thisbē virgō fōrmōsissima domōs vīcīnās tenuērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"pyrenaeus","latin":"Pyrenaeus, Pyrenaea, Pyrenaeum","headword":"Pyrenaeus","letter":"p","pos":"adjective","posGroup":"adjective","english":"Pyrenees (w/montes)","forms":["Pyrēnaeō","Pyrēnaeum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inde {{Pyrēnaeum}} trānsgreditur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"pyrrha","latin":"Pyrrha, Pyrrhae","headword":"Pyrrha","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Pyrrha; (wife of Deucalion, survivor of the great flood)","forms":["Pyrrha","Pyrrham"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Iuppiter igitur postquam Deucaliōnem eiusque uxōrem, {{Pyrrham}} nōmine, quōs Mercurius praeter cēterōs servandōs esse cēnsēbat, in rate quādam posuit, ventōs omnēs līberāvit, nūbibusque ātrīs tōtum caelum operuit; deinde ingentēs imbrēs dē caelō mīsit, et aquās tōtīus orbis ita auxit, ut omnēs terrae mergerentur: omnia mare erant, et lītora quoque marī dēerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pythia","latin":"Pythia, -ae","headword":"Pythia","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"Pythia (the priestess of Apollo)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"python","latin":"Python, Pythonis","headword":"Python","letter":"p","pos":"noun (m.)","posGroup":"noun","english":"familiar spirit/demon possessing soothsayer; soothsayer; snake slain at Delphi","forms":["Pȳthōnem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Postquam Apollō, quī deus arcū validissimus est, {{Pȳthōnem}}, anguem ingentem et tam terribilem, ut etiam dīī eum metuerent, mīlle sagittīs eius corpus percutiēns dēvīcit, ob magnam victōriam valdē gaudēbat atque glōriōsus per viās ībat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"pyxis","latin":"pyxis, pyxidos/is","headword":"pyxis","letter":"p","pos":"noun (f.)","posGroup":"noun","english":"small box/casket (originally boxwood) for medicine; iron heel on pestle (L+S)","forms":["pyxīdās","pyxis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{pyxīdās}}: ars faciem dissimulāta","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"qu","latin":"qu","headword":"qu","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"who; that; which, what; of which kind/degree; person/thing/time/point that","forms":["cui","quae","quarum","quas","quem","quibus","quid","quis","quorum","quos","QVAE"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam {{quae}} Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"qua","latin":"quā","headword":"quā","letter":"q","pos":"adverb","posGroup":"adverb","english":"which way, where","forms":["qua"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Qua}} oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quacumque","latin":"quācumque","headword":"quācumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"wherever","forms":["quācumque"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is, {{quācumque}} îbat, terram adūrēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quadragesimus","latin":"quadrāgēsimus, -a, -um","headword":"quadrāgēsimus","letter":"q","pos":"","posGroup":"other","english":"40th","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quadraginta","latin":"quadrāgintā","headword":"quadrāgintā","letter":"q","pos":"numeral","posGroup":"numeral","english":"forty","forms":["quadragenos","quadrāgēsimō","quadrāgēsimum","quadrāgintā"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes {{quadragenos}} plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quadrans","latin":"quadrans, quadrantis","headword":"quadrans","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"fourth part, a quarter; 1/4 as, small coin, \"farthing\"","forms":["quadrantem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ab asse crēvit, et parātus fuit {{quadrantem}} dē stercore mordlcus @ tollere!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quadratus","latin":"quadrātus, -a, -um","headword":"quadrātus","letter":"q","pos":"adjective","posGroup":"adjective","english":"square","forms":["quadrātā","quadrātam","quadrātō"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Super līmen autem cavea pendēbat aurea, in quā pīca varia intrantēs salūtābat. cūrat premendô ac pulsandô veste circumdare, vestīre pīsum (: pīsa) pūrgāre : ē vārius : variīs colôribus litterā quadrātā: Ā B C D Ē... persequī oculîs : spectāre dëﬁciëns porticūs zextrëma p.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quadriennium","latin":"quadriennium, -ī","headword":"quadriennium","letter":"q","pos":"noun (n.)","posGroup":"noun","english":"four years; period of four years","forms":["Quadrienniō","quadriennium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam post aliquantum nūllōs placuit fierī, et {{quadriennium}} in urbe ita flūxit ut potestātēs ibi maiōrēs nōn essent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quadriga","latin":"quadriga, quadrigae","headword":"quadriga","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"four horse chariot (sg. or pl.); chariot team of four horses; any team","forms":["Quadrīgās","quadrīgīs"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"MERCVRIVS: Cum {{quadrīgīs}} Sōl exoriēns.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"quadrigae","latin":"quadrīgae, -ārum (pl.)","headword":"quadrīgae","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"team of four horses","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"quadringent","latin":"quadringent","headword":"quadringent","letter":"q","pos":"numeral","posGroup":"numeral","english":"four hundred","forms":["quadringentās","quadringentēsimō","quadringentēsimum","quadringentī","quadringentīs","quadringentōrum","quadringentos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus {{quadringentos}} reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus corona militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo advolaret aut interdiu tela in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quadringentesimus","latin":"quadringentēsimus, -a, -um","headword":"quadringentēsimus","letter":"q","pos":"","posGroup":"other","english":"four hundredth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quadringenti","latin":"quadringentī, -ae, -a","headword":"quadringentī","letter":"q","pos":"","posGroup":"other","english":"four hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quadro","latin":"quadro, quadrare, quadravi, quadratus","headword":"quadro","letter":"q","pos":"verb","posGroup":"verb","english":"square up, make square/suitable; square/fit; quadruple; form rectangular shape","forms":["quadrat"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“In Cancrô ego nātus sum, ideô multîs pedibus stô, et in marī et in terrâ multa possideô, nam cancer et hôc et illôc {{quadrat}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quadrupes","latin":"quadrupes, quadrupedis","headword":"quadrupes","letter":"q","pos":"noun","posGroup":"noun","english":"quadruped","forms":["quadrupedēs","quadrupēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{quadrupēs}} -edis m (€ Iv * pés) : equus idm","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"quae","latin":"quae","headword":"quae","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"(f.) who, which, she who; who? (f. sg.); who, which (f.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"quaerit","latin":"quaerit, -unt","headword":"quaerit","letter":"q","pos":"verb","posGroup":"verb","english":"look for, seek, ask (for); seeks, looks for","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"quaerito","latin":"quaerito, quaeritare, quaeritavi, quaeritatus","headword":"quaerito","letter":"q","pos":"verb","posGroup":"verb","english":"seek, search for","forms":["quaeritandō","quaeritātum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sum dēfessus quaeritandō, nusquam inveniō Naucratem.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"quaero","latin":"quaerō, -ere, quaesīvī, quaesītum","headword":"quaerō","letter":"q","pos":"verb","posGroup":"verb","english":"seek, ask, inquire","forms":["quaeram","quaerās","quaerat","quaerātur","quaere","Quaerēbam","quaerēbant","quaerēbat","quaerebatur","quaerēmus","quaerenda","quaerendam","quaerendum","quaerendus","quaerēns","quaerent","quaerentem","quaerentī","quaerere","quaererem","quaererent","quaererentur","quaereret","quaererētur","Quaerēs","quaeret","quaerētur","quaerī","quaerimus","quaeris","quaerit","quaeritis","quaeritur","quaerō","quaerundōrum","quaerunt","quaesīta","quaesīverimus","quaesīvī","quaesīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio deductis, cum se vel principes eius consili fore profiterentur, ratio perficiendi {{quaerebatur}}, quod civitatem temere ad suscipiendum bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quaesitum","latin":"quaesitum, quaesiti","headword":"quaesitum","letter":"q","pos":"noun (n.)","posGroup":"noun","english":"question, inquiry; gain, acquisition, earnings","forms":["quaesītum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dardanium, nōn hōs {{quaesītum}} mūnus in ūsūs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"quaesitus","latin":"quaesitus, quaesita -um, quaesitior -or -us, quaesitissimus -a -um","headword":"quaesitus","letter":"q","pos":"adjective","posGroup":"adjective","english":"special, sought out, looked for; select; artificial, studied, affected","forms":["quaesītissimīs","quaesītus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"(Mīrābātur Achillēs enim.) “Nec haec cassis quam vidēs neque scūtum, onus sinistrae, auxiliō mihi sunt; decor est {{quaesītus}} ab istīs; Mars quoque ob hoc capere arma solet! [Sī] removēbitur huius tegminis officium, tamen indestrictus abībō; est aliquid nōn esse nātum Nērēide, sed quī Nēreaque et nātās et tōtum temperat aequor.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"quaeso","latin":"quaesō","headword":"quaesō","letter":"q","pos":"verb","posGroup":"verb","english":"I ask you, please; please (literally, I ask); seek, beg; I beg you, please","forms":["quaesō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx autem ut explōrāret latentem vēritātem: “Dīvidātur” inquit “puer dē quō contrōversia est, et pars ūna ūnī mulierī, altera alterī dētur.” Iūdiciō assēnsa est falsa māter; altera vērō exclāmāvit: “Nē, quaesō, nē occīdātur puer, ō rēx: mālō ista tōtum habeat.” Tunc rēx ait: “Rēs est manifēsta: haec vērē est māter puerī.” Et huic illum adiūdicāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quaestio","latin":"quaestiō, -ōnis ( f.)","headword":"quaestiō","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"inquiry, question; inquiry, subject of inquiry","forms":["quaestiō","quaestionem","quaestiōnēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interim nuntio allato omnes eorum milites in potestate Caesaris teneri, concurrunt ad Aristium; nihil publico factum consilio demonstrant; {{quaestionem}} de bonis direptis decernunt, Litavicci fratrumque bona publicant, legatos ad Caesarem sui purgandi gratia mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quaestor","latin":"quaestor, -ōris (m.)","headword":"quaestor","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"quaestor (magistrate)","forms":["quaestor","quaestōre","quaestōrem","quaestōrēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quadrāgintā quīnque mīlia quīngentī peditēs, duo mīlia septingentī equitēs caesī dīcuntur; in hīs ambō cōnsulum {{quaestōrēs}} et ūndētrīgintā tribūnī mīlitum, cōnsulārēs quīdam praetōriīque (inter eōs Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quaestorius","latin":"quaestōrius, -a, -um","headword":"quaestōrius","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"of, belonging to a quaestor","forms":["quaestōriōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mucium Scaevolam, generōs Laelī, doctōs adulēscentēs, iam aetāte {{quaestōriōs}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quaestura","latin":"quaestūra, -ae ( f.)","headword":"quaestūra","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"quaestorship","forms":["quaestūram"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ūnum igitur annum, cum redissēmus ex Asiā, causās nōbilēs ēgimus, cum {{quaestūram}} nōs, cōnsulātum Cotta, aedīlitātem peteret Hortēnsius.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quaestus","latin":"quaestus, -ūs","headword":"quaestus","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"income, profit; gain, profit","forms":["quaestū","quaestuī","quaestūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quis enim umquam aut obeundī negōtiī aut cōnsequendī {{quaestūs}} studiō tam brevī tempore tot loca adīre, tantōs cursūs cōnficere potuit, quam celeriter Cn.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"qualibet","latin":"qualibet","headword":"qualibet","letter":"q","pos":"adverb","posGroup":"adverb","english":"where you will, anywhere, by any road you like; anyway, as you please","forms":["quālibet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"haec tibi quāērátūr {{quālibet}} arte fidēs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"qualis","latin":"quālis","headword":"quālis","letter":"q","pos":"adjective","posGroup":"adjective","english":"of what kind","forms":["quāle","quālem","quālēs","quālia","quālis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Arethūsae vērō tunc tālis animus fuit, {{quālis}} est agnō, cum lupum audit in silvā ululantem.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"qualis? quale","latin":"quālis? quāle?","headword":"quālis? quāle","letter":"q","pos":"","posGroup":"other","english":"(interrogative and relative) of what sort?","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"qualiscumque","latin":"quāliscumque, quālecumque","headword":"quāliscumque","letter":"q","pos":"","posGroup":"other","english":"of whatever sort","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"qualitas","latin":"quālitās, quālitātis","headword":"quālitās","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"(f.) quality","forms":["quālitātem","quālitātis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Comparātiōnis gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: 'Positīvus, ut doctus; comparātīvus, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat {{quālitātem}} aut quantitātem significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quam","latin":"quam","headword":"quam","letter":"q","pos":"pronoun; conjunction","posGroup":"pronoun","english":"(acc. sing. f.)whom, which, she whom; how, as, than; how?; whom, which (f. acc.); than","forms":["quam","QVAM"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In primis rationem esse habendam dicunt, prius {{quam}} eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quam ob rem","latin":"quam ob rem","headword":"quam ob rem","letter":"q","pos":"phrase","posGroup":"other","english":"for this reason","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quamdiu","latin":"quamdiū","headword":"quamdiū","letter":"q","pos":"adverb","posGroup":"adverb","english":"how long, as long as; as long as","forms":["quamdiū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"IOās, quamdiū cōnsiliīs Ioiadae ūsus est, observantissimus fuit divinī culfils: magnīs sūmptibus templum exomāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quamlibet","latin":"quamlibet","headword":"quamlibet","letter":"q","pos":"adverb","posGroup":"adverb","english":"however, however much","forms":["quamlibet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"hōraque fōrmōsam {{quamlibet}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"quamobrem","latin":"quamobrem","headword":"quamobrem","letter":"q","pos":"adverb","posGroup":"adverb","english":"why? therefore; why, for what reason","forms":["quamobrem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Quamobrem}} Deus erat et līberīs et patrī īrātus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quamquam","latin":"quamquam","headword":"quamquam","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"although","forms":["quamquam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia, quae lacrimās tenēre vix potest, “Sed nimis difficile est” inquit “id quod interrogor ā tē, Mārce; {{quamquam}} multum cōgitō, nōn possum rēctē respondēre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quamvis","latin":"quamvīs","headword":"quamvīs","letter":"q","pos":"adverb","posGroup":"adverb","english":"however, although","forms":["quamvīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec deinceps ab avītā religiōne umquam dēscīvērunt, {{quamvīs}} ea dē causā ā plūribus rēgibus vexatī sint, ac praesertim ab Antiochō rēge Syriae; quae pars historiae Iūdaicae nunc nārranda venit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quando","latin":"quandō","headword":"quandō","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"when, as; when","forms":["quandō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dīxit Hebraeīs: “Sī quandō vōs interrogāverint fīliī vestrī, quōrsum spectet ista lapidum congeriēs, respondēbitis: ‘Siccō pede trāiēcimus Iordānem istum: idcircō positī sunt lapidēs ad sempiternam factī memoriam, ut discant quanta sit Deī potentia.’”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quandocumque","latin":"quandocumque","headword":"quandocumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"whenever, at whatever time; at some time or other/any time; as often/soon as","forms":["quandōcumque"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Garrulus hunc {{quandōcumque}} cōnsūmet.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"quantitas","latin":"quantitās, quantitātis","headword":"quantitās","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"(f.) quantity","forms":["quantitās","quantitātem","quantitātis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Comparātiōnis gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: 'Positīvus, ut doctus; comparātīvus, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat quālitātem aut {{quantitātem}} significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quanto","latin":"quanto","headword":"quanto","letter":"q","pos":"adverb","posGroup":"adverb","english":"(by) how much","forms":["quanto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet {{quanto}} detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quantulus","latin":"quantulus, quantula, quantulum","headword":"quantulus","letter":"q","pos":"adjective","posGroup":"adjective","english":"how small/little/trifling a ...; how small!; of what (small) size","forms":["quantula","quantulus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{quantulus}} -ā -um — quam parvus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"quantum","latin":"quantum","headword":"quantum","letter":"q","pos":"adverb","posGroup":"adverb","english":"(as adv.) so much as, as much as; how much","forms":["quantum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum {{quantum}} quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui studet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quantumcumque","latin":"quantumcumque","headword":"quantumcumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"as far as; to whatever degree","forms":["quantumcumque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōs autem nōn dēsistēbāmus cum omnī genere exercitātiōnis, tum maximē stilō nostrum illud quod erat augēre, {{quantumcumque}} erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quantus","latin":"quantus, -a, -um","headword":"quantus","letter":"q","pos":"adjective","posGroup":"adjective","english":"how large, (as large) as; how great, how big","forms":["quanta","quantae","quantam","quantās","quantī","quantīs","quantus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iam vērō intellegō Lepidum, quī ānulum ferreum mihi dedit, falsum amīcum quantī est? = esse.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quantuscumque","latin":"quantuscumque, -a, -um","headword":"quantuscumque","letter":"q","pos":"","posGroup":"other","english":"however great/much","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quapropter","latin":"quāpropter","headword":"quāpropter","letter":"q","pos":"adverb","posGroup":"adverb","english":"why","forms":["quāpropter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Quāpropter}} Saūl adversus illōs prōcessit, et apud Galgala, urbem īnsignem istīus regiōnis, castra posuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quare","latin":"quārē","headword":"quārē","letter":"q","pos":"adverb","posGroup":"adverb","english":"why","forms":["quare"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ab hoc concilio Remi, Lingones, Treveri afuerunt; illi, quod amicitiam Romanorum sequebantur; Treveri, quod aberant longius et ab Germanis premebantur, quae fuit causa {{quare}} toto abessent bello et neutris auxilia mitterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quartus","latin":"quārtus, -a, -um","headword":"quārtus","letter":"q","pos":"adjective","posGroup":"adjective","english":"fourth","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"quasi","latin":"quasi","headword":"quasi","letter":"q","pos":"adverb","posGroup":"adverb","english":"as if","forms":["quasi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Conclamant Aedui et Litaviccum obsecrant ut sibi consulat. '{{Quasi}} vero', inquit ille, 'consili sit res, ac non necesse sit nobis Gergoviam contendere et cum Arvernis nosmet coniungere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quassare","latin":"(quassō) quassāre","headword":"quassāre","letter":"q","pos":"","posGroup":"other","english":"shake, damage, batter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quasso","latin":"quasso, quassare, quassavi, quassatus","headword":"quasso","letter":"q","pos":"verb","posGroup":"verb","english":"shake repeatedly; wave, flourish; batter; weaken","forms":["quassāta","Quassātam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Turris diū {{quassāta}} prōciderat; perque ruīnam eius cohors Poenōrum impetū factō, cum signum imperātōrī dedisset 'nūdātam statiōnibus custōdiīsque solitīs hostium esse urbem', nōn cunctandum in tālī occāsiōne ratus Hannibal tōtīs vīribus aggressus urbem mōmenta cēpit, signō datō ut omnēs pūberēs interficerentur!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quatenus","latin":"quatenus","headword":"quatenus","letter":"q","pos":"adverb","posGroup":"adverb","english":"how far/long?, to what point; to what extent; where; while, so far as; since","forms":["quātenus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ideō nesciō quid et {{quātenus}} aut pūnīrī soleat aut quaerī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"quater","latin":"quater","headword":"quater","letter":"q","pos":"adverb","posGroup":"adverb","english":"four times","forms":["quater"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus, ut piger discipulus, {{quater}} tantum V scrībit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quatere","latin":"(quatiō) quatere","headword":"quatere","letter":"q","pos":"","posGroup":"other","english":"shake","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quaterni","latin":"quaternī, -ae, -a","headword":"quaternī","letter":"q","pos":"adjective","posGroup":"adjective","english":"four at a time; four each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quatio","latin":"quatio, quatere, -, quassus","headword":"quatio","letter":"q","pos":"verb","posGroup":"verb","english":"shake","forms":["quatere","quateret","quatiendō","quatiēns","quatit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hellē autem dēspiciēns magnōs flūctūs Īnfrā sē vīdit; puella perterrita dē arietis dorsō dēlāpsa est; dum vērō cadit, “Ō frāter,” clāmāvit, “ōrō tē ut auxilium mihi ferās!” Deinde, {{quatiēns}} bracchia et crūra dē summō caelō in mare cecidit ac mersa est, neque frāter eam servāre potuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"quattuor","latin":"quattuor","headword":"quattuor","letter":"q","pos":"numeral","posGroup":"numeral","english":"four","forms":["quārta","quartam","quārtīs","quārtō","quārtum","quartus","quaterna","quaternōs","quattuor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio {{quartus}}; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quattuordecim","latin":"quattuordecim","headword":"quattuordecim","letter":"q","pos":"numeral","posGroup":"numeral","english":"fourteen","forms":["quattuordecim"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia lacrimam dētergēns ab ūndecim numerāre incipit: “Ūndecim, duodecim, trēdecim, {{quattuordecim}}...” Hīc puella numerāre dēsinit atque “Cēterōs” inquit “numerōs nesciō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"que","latin":"-que","headword":"que","letter":"q","pos":"enclitic; particle","posGroup":"other","english":"and enclitic added to the second word of a pair of words in order to link them together; and (attached to a word)","forms":["que"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornēlius: “Ita sunt mātrēs discipulōrum: sī fīliī eārum male discunt, magistrum accūsant ‘eum’{{que}} ‘male docēre’ dīcunt; sī autem bene discunt fīliī, nōn magistrum, sed discipulōs laudant.” Sextum malum esse discipulum?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quem","latin":"quem","headword":"quem","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"(acc. sing. m.) whom, which, he whom; whom, which (m. acc.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"quemadmodum","latin":"quemadmodum","headword":"quemadmodum","letter":"q","pos":"adverb","posGroup":"adverb","english":"in what way, how; as, just as; to the extent that","forms":["quemadmodum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Et abiit et locūtus est cum prīncipibus sacerdōtum et magistrātibus {{quemadmodum}} illum trāderet iīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"queo","latin":"queo, quire, quivi(ii), quitus","headword":"queo","letter":"q","pos":"verb","posGroup":"verb","english":"be able","forms":["queat","quīre","quit","quīvit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"nē-{{quīre}} -ēó -eunt — nón posse C £","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"quercus","latin":"quercus, -ī ( f.)","headword":"quercus","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"oak","forms":["quercū","quercum","quercus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam {{quercum}}, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"querela","latin":"querela, querelae","headword":"querela","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"complaint, grievance; illness; difference of opinion; lament; blame (Plater)","forms":["querēlārum","querēlīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Movet cum patris maestitia, tum Brūtus castīgātor lacrimārum atque inertium {{querēlārum}} auctorque 'quod virōs, quod Rōmānōs deceret!' arma capiendī 'adversus hostīlia ausōs!' Ferōcissimus quisque iuvenum cum armīs voluntārius adest; sequitur et cētera iuventūs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"querella","latin":"querēlla, -ae","headword":"querēlla","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"complaint; complaint, reproach","forms":["querella","querellae","querēllam","querellās","querellīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Longa {{querella}} est mora poenae.” Tum celeriter Diāna et Phoebus per āera ad rēgiam rēgīnae volant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"queri","latin":"(queror) querī, questum","headword":"querī","letter":"q","pos":"verb","posGroup":"verb","english":"complain; to complain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"querimonia","latin":"querimōnia, -ae","headword":"querimōnia","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"complaint, protest","forms":["querimōniae","querimōniam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam vērō ita facilēs aditūs ad eum prīvātōrum, ita līberae {{querimōniae}} dē aliōrum iniūriīs esse dīcuntur, ut is quī dignitāte prīncipibus excellit facilitāte īnfimīs pār esse videātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"queritur","latin":"queritur","headword":"queritur","letter":"q","pos":"verb","posGroup":"verb","english":"complains, laments","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"queror","latin":"queror, queri, questus sum","headword":"queror","letter":"q","pos":"verb","posGroup":"verb","english":"complain; protest, grumble, gripe; make formal complaint in court of law","forms":["querāminī","querātur","querēbātur","querēns","querentem","querentī","querentīs","quererētur","quereris","querī","queritur","queror","queruntur","questum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis {{queruntur}} de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"questus","latin":"questus, questus","headword":"questus","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"complaint","forms":["questibus","questus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iacobus, ut audīvit Beniamīnum arcessī ā praefectō Aegyptī, cum gemitū {{questus}} est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"qui","latin":"quī?","headword":"quī","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"(m. pl.) what, which; (m.) who, which, he who; who, which, that; who? (m. pl.); who, which (m.)","forms":["qui","QVI"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione {{qui}} iam ante se populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"qui / quae / quod","latin":"quī / quae / quod","headword":"quī / quae / quod","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"who, which","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"qui/quae/quod","latin":"quī/quae/quod","headword":"quī/quae/quod","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"who, which","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"quia","latin":"quia","headword":"quia","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"because","forms":["quia"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dēlia cantat {{quia}} laeta est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quicquid","latin":"quicquid","headword":"quicquid","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"whatever","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quicumque","latin":"quīcumque, -quae, -quod","headword":"quīcumque","letter":"q","pos":"","posGroup":"other","english":"whoever, whatever, any","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quid","latin":"quid?","headword":"quid","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"n. (seequis) what, anything; adv. why; why?; what?; what","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quidam","latin":"quīdam, quaedam, quoddam","headword":"quīdam","letter":"q","pos":"pronoun; adjective","posGroup":"pronoun","english":"a certain; a certain one","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quiddam","latin":"quiddam, undeclined","headword":"quiddam","letter":"q","pos":"noun (n.)","posGroup":"noun","english":"something","forms":["quiddam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"opácus -ā-um - umbrósus; {{quiddam}} et, sī nŌn tenebrās, at quiddam","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"quidem","latin":"quidem","headword":"quidem","letter":"q","pos":"adverb","posGroup":"adverb","english":"indeed","forms":["quidem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis {{quidem}} eo tempore qui quieti viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quidnam","latin":"quidnam?","headword":"quidnam","letter":"q","pos":"adverb","posGroup":"adverb","english":"what in the world?","forms":["quidnam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quī eōs interrogāvit {{quidnam}} operis habērent; illī respondērunt sē esse pāstōrēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quidni","latin":"quidnī","headword":"quidnī","letter":"q","pos":"adverb","posGroup":"adverb","english":"why not","forms":["quidnī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Dā negandī et affirmandī!' Discipulus: 'Negandī, ut nōn; affirmandī, ut etiam, quidnī.' Magister: 'Dā dēmōnstrandī et optandī!' Discipulus: 'Dēmōnstrandī, ut ēn, ecce; optandī, ut utinam.' Magister: 'Dā hortandī et ōrdinis!' Discipulus: 'Hortandī, ut ēia; ōrdinis, ut deinde.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quidquid","latin":"quidquid","headword":"quidquid","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"whatever","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quies","latin":"quiēs, -ētis ( f.)","headword":"quiēs","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"rest, repose, sleep; rest, quiet","forms":["quiēs","quietem","quieti","quiētibus","quiētum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui {{quieti}} viderentur, suam salutem recte committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quiescere","latin":"(quiescō) quiescere, quiēvisse","headword":"quiescere","letter":"q","pos":"verb","posGroup":"verb","english":"rest; to rest","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quiesco","latin":"quiesco, quiescere, quievi, quietus","headword":"quiesco","letter":"q","pos":"verb","posGroup":"verb","english":"rest, keep quiet/calm, be at peace/rest; be inactive/neutral; permit; sleep","forms":["quiēscam","quiēscāmus","quiēscēbat","quiēscere","quiēsceret","quiēscit","quiēscite","quiēscunt","quiēvī","quiēvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sextō diē fēcit omnia animantia, postrēmō hominem, et {{quiēvit}} diē septimō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quiete","latin":"quiete, quietius, quietissime","headword":"quiete","letter":"q","pos":"adverb","posGroup":"adverb","english":"quietly, peacefully, calmly, serenely","forms":["quiēte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum prior sīc exposuit Iōsēphō somnium suum: vīdī in {{quiēte}} vītem in quā erant trēs palmitēs; ea paulātim prōtulit gemmās; deinde flōrēs ērūpērunt, ac dēnique ūvae mātūrēscēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quietus","latin":"quiētus, -a, -um","headword":"quiētus","letter":"q","pos":"adjective","posGroup":"adjective","english":"quiet, still","forms":["quiēta","quietās","quiētior","quiētōs","quiētus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Quieta}} Gallia, Caesar, ut constituerat, in Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quilibet","latin":"quīlibet, quaelibet, quodlibet","headword":"quīlibet","letter":"q","pos":"","posGroup":"other","english":"any; no matter what/which","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quin","latin":"quīn","headword":"quīn","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"why not? in fact; but that; from … doing","forms":["quin"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qua re per exploratores nuntiata, Caesar legiones quas expeditas esse iusserat portis incensis intromittit atque oppido potitur, perpaucis ex hostium numero desideratis {{quin}} cuncti caperentur, quod pontis atque itinerum angustiae multitudinis fugam intercluserant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quinctius","latin":"Quinctius, Quinctia, Quinctium","headword":"Quinctius","letter":"q","pos":"adjective","posGroup":"adjective","english":"Quinctian; of Quinctius gens","forms":["Quīnctiō","Quīnctium","Quīnctius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Quīnctius}} Cincinnātus dictātor est factus, quī agrum quattuor iūgerum possidēns manibus suīs colēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quincunx","latin":"quincunx, quincuncis","headword":"quincunx","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"quincunx, the five on dice; 5/12, esp. of an as = 5 unciae","forms":["quincuncem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ante hos obliquis ordinibus in {{quincuncem}} dispositis scrobes tres in altitudinem pedes fodiebantur paulatim angustiore ad infimum fastigio.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quindecim","latin":"quīndecim","headword":"quīndecim","letter":"q","pos":"numeral","posGroup":"numeral","english":"fifteen","forms":["quindecim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Hoc intermisso spatio duas fossas {{quindecim}} pedes latas eadem altitudine perduxit, quarum interiorem campestribus ac demissis locis aqua ex flumine derivata complevit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quindecimvir","latin":"quindecimvir, quindecimviri","headword":"quindecimvir","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"one of board of fifteen magistrates","forms":["quīndecimvirī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad eōs quasi ad ōrāculum quīndecimvirī adeunt, cum dī immortālēs pūblicē cōnsulendī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quindecimviri","latin":"quīndecimvirī, -ōrum (pl.)","headword":"quīndecimvirī","letter":"q","pos":"","posGroup":"other","english":"board of fifteen priests","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quingent","latin":"quingent","headword":"quingent","letter":"q","pos":"numeral","posGroup":"numeral","english":"five hundred","forms":["quīngenta","quīngentās","quīngentēsimō","quīngentī","quīngentōs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sextus: 'Centum, ducentī, trecentī, quadringentī, quīngentī, sēscentī, septingentī, octingentī, nōngentī, mīlle.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quingentesimus","latin":"quīngentēsimus, -a, -um","headword":"quīngentēsimus","letter":"q","pos":"","posGroup":"other","english":"five hundredth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quingenti","latin":"quīngentī, -ae, -a","headword":"quīngentī","letter":"q","pos":"","posGroup":"other","english":"five hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quini","latin":"quīnī, -ae, -a","headword":"quīnī","letter":"q","pos":"adjective","posGroup":"adjective","english":"five at a time; five each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quinquagesimus","latin":"quīnquāgēsimus, -a, -um","headword":"quīnquāgēsimus","letter":"q","pos":"","posGroup":"other","english":"fiftieth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quinquaginta","latin":"quīnquāgintā","headword":"quīnquāgintā","letter":"q","pos":"numeral","posGroup":"numeral","english":"fifty","forms":["quīnquāgēsimō","quinquaginta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex omnibus fere partibus palus difficilis atque impedita cingebat, non latior pedibus {{quinquaginta}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quinque","latin":"quīnque","headword":"quīnque","letter":"q","pos":"numeral","posGroup":"numeral","english":"five","forms":["quīna","Quini","quinos","quinque","quīnquiēs","Quīnta","Quīnte","Quīntī","quintis","quīntō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Caesar ex eo loco {{quintis}} castris Gergoviam pervenit equestrique eo die proelio levi facto, perspecto urbis situ, quae posita in altissimo monte omnes aditus difficiles habebat, de expugnatione desperavit; de obsessione non prius agendum constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quinquennium","latin":"quīnquennium, -ī","headword":"quīnquennium","letter":"q","pos":"noun (n.)","posGroup":"noun","english":"five years; period of five years","forms":["quīnquenniī","quīnquennium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi cum multa dē administrandō imperiō dissererent, Iugurtha inter aliās rēs iacit 'oportere quīnquenniī cōnsulta et dēcrēta omnia rescindī, nam per eōs annōs Micipsam parum animō valuisse.' Tum 'idem' Hiempsal 'placēre sibi' respondit, 'nam ipsum illum tribus proximīs annīs adoptātiōne in rēgnum pervēnisse!' Quod verbum in pectus Iugurthae altius quam quisquam rātus erat dēscendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quinqueremis","latin":"quīnquerēmis, -e","headword":"quīnquerēmis","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"having five banks of oars; ( f.) ship with five banks of oars","forms":["quīnquerēmēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cornēliō sexāgintā {{quīnquerēmēs}} datae et duae Rōmānae legiōnēs cum suō iūstō equitātū et quattuordecim mīlibus sociōrum peditum, equitibus mīlle sescentīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quinquies","latin":"quīnquiēs","headword":"quīnquiēs","letter":"q","pos":"","posGroup":"other","english":"five times","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quintilis","latin":"Quintilis, Quintilis, Quintile","headword":"Quintilis","letter":"q","pos":"adjective","posGroup":"adjective","english":"July (month/mensis); abb. Quin.??; renamed Julius in 44 BC; in 5th place","forms":["Quīntīlis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Ante tempora Caesaris eī mēnsī erat nōmen \"{{Quīntīlis}}\" ā \"quīntō\" numerō — nōn ā nōmine Quīntī.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"quintilius","latin":"Quintilius, Quintili","headword":"Quintilius","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"Quintilius; (Roman gens name)","forms":["Quīntiliō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quīntiliō Vārō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"quinto","latin":"quīntō","headword":"quīntō","letter":"q","pos":"","posGroup":"other","english":"for the fifth time","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quintum","latin":"quintum","headword":"quintum","letter":"q","pos":"adverb","posGroup":"adverb","english":"for the fifth time","forms":["quīntum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ecce puerī quī nīdōs quaerunt in arboribus.” Iūlia Mārcum et {{Quīntum}} in umbrā inter arborēs errāre et nīdōs quaerere videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quintus","latin":"quīntus, -a, -um","headword":"quīntus","letter":"q","pos":"noun (m.)","posGroup":"noun","english":"fifth","forms":["quīntus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dum {{Quīntus}} in lectō iacet in cubiculō suō, Medicus in ātriō Iūlium exspectat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quippe","latin":"quippe","headword":"quippe","letter":"q","pos":"adverb","posGroup":"adverb","english":"inasmuch as, for","forms":["quippe"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Asa Deō grātus ob pietātem fuit: {{quippe}} ārās falsōrum nūminum ēvertit, et impiōs rēgnō suō expulit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quire","latin":"(queō) quīre, quīvisse, quitum","headword":"quīre","letter":"q","pos":"","posGroup":"other","english":"be able to","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quirinale","latin":"Quirinale, Quirinalis","headword":"Quirinale","letter":"q","pos":"noun (n.)","posGroup":"noun","english":"festival (pl.) in honor of Quirinus/Romulus, celebrated 17th of February","forms":["Quirīnālī","Quirīnālis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Moenia Rōmāna antīqua septem collēs sīve montēs complectuntur, quōrum haec sunt nōmina: Palātium, Capitōlium, Aventīnus, Caelius, Esquiliae, Vīminālis, {{Quirīnālis}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quiris","latin":"quiris, quiritis","headword":"quiris","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"spear (Sabine word)","forms":["Quirītēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ut Sabīnīs tamen aliquid darētur, cīvēs Rōmānī \"{{Quirītēs}}\" ā Curibus appellātī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quis","latin":"quis, quid","headword":"quis","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"shortened from aliquis, aliquid; who? (m. sg.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quis? / quid","latin":"quis? / quid?","headword":"quis? / quid","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"who? / what?","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quis? quae? quid","latin":"quis? quae? quid?","headword":"quis? quae? quid","letter":"q","pos":"","posGroup":"other","english":"who, what","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quisnam","latin":"quisnam?","headword":"quisnam","letter":"q","pos":"","posGroup":"other","english":"who in the world?","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quisquam","latin":"quisquam, quidquam","headword":"quisquam","letter":"q","pos":"","posGroup":"other","english":"anyone, anything","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"quisque","latin":"quisque, quaeque, quodque","headword":"quisque","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"each; each one, every one; each, every, everyone, everything","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quisquilia","latin":"quisquilia, quisquiliae","headword":"quisquilia","letter":"q","pos":"noun (f.)","posGroup":"noun","english":"rubbish (pl.), sweepings, refuse","forms":["quisquilia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Corcillum est quod hominēs facit, cētera {{quisquilia}} omnia!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quisquis","latin":"quisquis, quidquid","headword":"quisquis","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"whoever, whatever, each, all; whoever","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"quivis","latin":"quīvīs, quaevīs, quodvīs","headword":"quīvīs","letter":"q","pos":"","posGroup":"other","english":"no matter what, any","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quo","latin":"quō?","headword":"quō","letter":"q","pos":"adverb","posGroup":"adverb","english":"where (to)?; to where?","forms":["quo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, {{quo}} more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quo pacto","latin":"quō pactō","headword":"quō pactō","letter":"q","pos":"","posGroup":"other","english":"= quō modō: in what way, manner","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"quoad","latin":"quoad","headword":"quoad","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"until","forms":["quoad"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Trēs diēs totidemque noctēs nāvēs caecae errābant, {{quoad}} quārtō diē in lītora Strophadum dēlātae sunt. (Strophades dīcuntur duae parvae īnsulae in marī Ioniō sitae.) Inde pulsī ab Harpyīs, mōnstrīs foedissimīs quibus corpora volucrum, vultūs virginum sunt, ad septentriōnēs cursum tenuērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quocirca","latin":"quōcircā","headword":"quōcircā","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"hence, therefore","forms":["Quōcircā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōcircā capere ante dolīs et cingere flammā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"quocumque","latin":"quōcumque","headword":"quōcumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"(to) wherever","forms":["quōcumque"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Audīvit Dominum dīcentem sibi: Ego sum Deus patris tuī; dabō tibi et posterīs tuīs terram cui incubās: nōlī timēre; ego favēbō tibi; erō cūstōs tuus {{quōcumque}} perrēxerīs, et redūcam tē in patriam, ac per tē omnēs orbis nātiōnēs erunt bonīs cumulātae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quod","latin":"quod","headword":"quod","letter":"q","pos":"conjunction; pronoun","posGroup":"conjunction","english":"because; which, that","forms":["quod"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, {{quod}} res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quominus","latin":"quominus","headword":"quominus","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"that not, from (quo minus)","forms":["quōminus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mariō, clārissimō virō, nōn fuerat {{quōminus}} C.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"quomodo","latin":"quōmodo","headword":"quōmodo","letter":"q","pos":"adverb","posGroup":"adverb","english":"how; how, in what manner","forms":["quōmodo"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia: “{{Quōmodo}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"quonam","latin":"quonam","headword":"quonam","letter":"q","pos":"adverb","posGroup":"adverb","english":"to whatever place","forms":["quōnam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nescīmus {{quōnam}} cāsū id factum fuerit; sed eamdem pecūniam reportāvimus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quondam","latin":"quondam","headword":"quondam","letter":"q","pos":"adverb","posGroup":"adverb","english":"once, some day","forms":["quondam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"nec corpus remanet, {{quondam}} quod amāverat Ēchō.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"quoniam","latin":"quoniam","headword":"quoniam","letter":"q","pos":"conjunction","posGroup":"conjunction","english":"since; since, because","forms":["quoniam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, {{quoniam}} in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quoque","latin":"quoque","headword":"quoque","letter":"q","pos":"adverb","posGroup":"adverb","english":"also, too","forms":["quoque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dimittit {{quoque}} versus legationes; obtestatur ut in fide maneant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quoquo","latin":"quoquo","headword":"quoquo","letter":"q","pos":"adverb","posGroup":"adverb","english":"wherever, in whatever place/direction; whatever; anywhere; in each direction","forms":["quōquō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quārē, quoniam dē rē pūblicā quaerimus, hoc prīmum videāmus: quid sit id ipsum quod quaerimus.' Cum approbāvisset Laelius, 'Est igitur' inquit Āfricānus 'rēs pūblica \"rēs populī\", populus autem nōn omnis hominum coetus quōquō modō congregātus, sed coetus multitūdinis iūris cōnsēnsū et ūtilitātis commūniōne sociātus...'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quorsum","latin":"quorsum","headword":"quorsum","letter":"q","pos":"adverb","posGroup":"adverb","english":"whither, in what direction; to what place/action/point/end; with what view?","forms":["quōrsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cui frātrēs respondērunt: {{quōrsum}} spectant ista somnia?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quos","latin":"quōs","headword":"quōs","letter":"q","pos":"pronoun","posGroup":"pronoun","english":"whom (acc. pl.)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quot","latin":"quot?","headword":"quot","letter":"q","pos":"pronoun; adjective","posGroup":"pronoun","english":"(indecl.)how many, (as many) as; how many?; how many, how much","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"quotannis","latin":"quotannīs","headword":"quotannīs","letter":"q","pos":"adverb","posGroup":"adverb","english":"every year; every year, yearly","forms":["quotannīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iildās omnia pūrgāvit, portās refēcit, novum altāre ērēxit, cuius dēdicātiō magna tofius populī frequentiā, clangentibus tubīs, facta est; dēcrētumque, ad memoriam reī sempitēmam, {{quotannīs}} diem sollemnem celebrātum In.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quotiens","latin":"quotiēns","headword":"quotiēns","letter":"q","pos":"adverb","posGroup":"adverb","english":"how often","forms":["quotiēns"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Quotiēns}} in agrīs ōlim suīs errāvit!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"quotienscumque","latin":"quotiēnscumque","headword":"quotiēnscumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"every time that","forms":["quotiēnscumque"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Itaque {{quotiēnscumque}} dîcit “Carpe!” eôdem verbô et [Dê Fortûnätä, dê dîvitiîs T rimalchiônis, dē collîbertîs] Nôn potuî amplius quicquam gustāre, sed conversus ad eum, ut quam plūrima exciperem, longē accersere täbulās coepî scîscitäxîque ‘quae esset mulier illa quae hūc atque “Uxor” inquit “Trīma1chiônis, ‘Fortūnāta’ appellättlr; quae nummôs modiô mëtîtur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"quoties","latin":"quotiēs","headword":"quotiēs","letter":"q","pos":"adverb","posGroup":"adverb","english":"as many times; how many times","forms":["quotiēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Varia deinceps fuit Hebraeōrum fortūna prō variīs eōrum mōribus: iī saepe in Deum peccāvērunt; tunc dīvīnō praesidiō dēstitūtī ab hostibus superābantur; {{quotiēs}} ad Deum conversī eius auxilium implōrāvērunt, plācātus Deus eōs līberāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"quotiescumque","latin":"quotiescumque","headword":"quotiescumque","letter":"q","pos":"adverb","posGroup":"adverb","english":"whenever, every time that; however often, as often as","forms":["quotiēscumque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam {{quotiēscumque}} cum eō congressus est in Ītaliā, semper discessit superior.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"quotus","latin":"quotus, quota, quotum","headword":"quotus","letter":"q","pos":"adjective","posGroup":"adjective","english":"how many; of what number; as many","forms":["quot","quota","quōtī","quotus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et {{quot}} virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"quousque","latin":"quoūsque","headword":"quoūsque","letter":"q","pos":"adverb","posGroup":"adverb","english":"how long? till when?","forms":["quōusque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam cum magis intuērer, 'Quaesō' inquit Āfricānus '{{quōusque}} humī dēfīxa tua mēns erit?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rabidus","latin":"rabidus, rabida, rabidum","headword":"rabidus","letter":"r","pos":"adjective","posGroup":"adjective","english":"mad, raging, frenzied, wild","forms":["rabidae","rabidōs","rabidus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fulmineō {{rabidōs}} cum rotat ōre canēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rabies","latin":"rabiēs, -ēī","headword":"rabiēs","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rage, fury; fury, rage","forms":["rabiem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vōs et Scyllaeam {{rabiem}} penitusque sonantēs accēstis scopulōs, vōs et Cyclōpia saxa expertī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"racemus","latin":"racemus, racemi","headword":"racemus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"bunch/cluster (of grapes or other fruit)","forms":["racēmōs","racēmus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{racēmus}} -ī 7n — ūvā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"radio","latin":"radio, radiare, radiavi, radiatus","headword":"radio","letter":"r","pos":"verb","posGroup":"verb","english":"beam, shine; radiate light","forms":["radiant","radiante","radiāre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui {{radiant}} ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"radius","latin":"radius, -ī","headword":"radius","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"ray; ray, spoke","forms":["radī","radiī","radiīs","radiōs","radius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum vēro ōlim Arethūsa, postquam diū per silvāsas cucurrerat, domum sōia redīret, ad rapidum fluvium pervēnit, cuius frīgidae aquae, nūllō modō turbidae ac percussae {{radiīs}} sōlis, quī in mediō caelō sine nūbibus fulgēbat, ita illūstrābantur ut nympha ipsōs calculōs in īmō flūmine iacentēs cemere posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"radix","latin":"rādīx, -īcis ( f.)","headword":"rādīx","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"root, foot, base; root, radish; root; foot (of a mountain)","forms":["rādīce","rādīcem","radices","radicibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat e regione oppidi collis sub ipsis {{radicibus}} montis egregie munitus atque ex omni parte circumcisus; quem si tenerent nostri, et aquae magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rado","latin":"rado, radere, rasi, rasus","headword":"rado","letter":"r","pos":"verb","posGroup":"verb","english":"shave; scratch, scrape; coast by","forms":["rādere","rādit","rāsīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"vadō fluvius trānsītur; vadum temp- Céra vadum temptet {{rāsīs}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ramosus","latin":"ramosus, ramosa, ramosum","headword":"ramosus","letter":"r","pos":"adjective","posGroup":"adjective","english":"having many branches, branching","forms":["rāmōsa"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ibi dum {{rāmōsa}} mīrāns laudat cornua crūrumque nimiam tenuitātem vituperat, vēnāntum subitō vōcibus conterritus per campum fugere coepit, et cursū levī canēs ēlūsit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ramus","latin":"rāmus, -ī","headword":"rāmus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"branch, bough; branch","forms":["ramī","ramis","rāmō","rāmōs","rāmum","rāmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque truncis arborum aut admodum firmis {{ramis}} abscisis atque horum delibratis ac praeacutis cacuminibus perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rana","latin":"rana, ranae","headword":"rana","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"frog","forms":["rāna","rānae","rānās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quibus verbīs audītis, Iuppiter, deōrum omnium rēx, agricolās illōs prāvōs in magnās {{rānās}} convertit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rapacitas","latin":"rapacitas, rapacitatis","headword":"rapacitas","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rapacity","forms":["rapācitāte"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quis in {{rapācitāte}} avārior — quis in largītiōne effūsior?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"rapere","latin":"(rapiō) rapere, rapuisse, raptum","headword":"rapere","letter":"r","pos":"verb","posGroup":"verb","english":"tear away, carry off; to seize, carry off","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"rapidus","latin":"rapidus, -a, -um","headword":"rapidus","letter":"r","pos":"adjective","posGroup":"adjective","english":"rapid","forms":["rapida","rapidī","rapidō","rapidōs","rapidum","rapidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Prae cēterīs Cyparissus eum tam multum dīligēbat, ut cotīdiē ad novōs campōs dūceret, ut bonam herbam esset, et ad {{rapidōs}} fluviōs ageret, ut pūram aquam biberet; flōribus variōrum colōrum cervī cornua mīrābilī modo ōrnābat, et, tamquam eques, in eius tergō sedēns hūc et illūc vehēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rapina","latin":"rapīna, -ae","headword":"rapīna","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"carrying off, robbery","forms":["rapīnā","rapīnae","rapīnārum","rapīnās","rapīnīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nymphae pictūrās et fābulās puellae amābant; maximē amābant fābulam longam dē rapīnā Eurōpae ā Iove.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"rapio","latin":"rapio, rapere, rapui, raptus","headword":"rapio","letter":"r","pos":"verb","posGroup":"verb","english":"drag off; snatch; destroy; seize, carry off; pillage; hurry","forms":["rape","rapere","raperet","rāpī","rapiant","rapiantur","rapiēbant","rapiēbat","rapiēbātur","rapienda","rapiendās","rapiendī","rapiet","rapimur","rapit","rapitur","rapiunt","raptae","raptam","raptārum","raptōs","rapuēre","rapuērunt","rapuī","rapuisset","rapuistī","rapuistis","rapuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cūr ergō uxōrem Ūriae rapuistī?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"raptim","latin":"raptim","headword":"raptim","letter":"r","pos":"adverb","posGroup":"adverb","english":"hurriedly","forms":["raptim"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Lūdicrum deinde ita {{raptim}} perāctum est ut nūllīus nec animī nec oculī spectāculō intentī essent — adeō ūnum gaudium praeoccupāverat omnium aliārum sēnsum voluptātum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rapto","latin":"rapto, raptare, raptavi, raptatus","headword":"rapto","letter":"r","pos":"verb","posGroup":"verb","english":"drag violently off; ravage","forms":["raptās","raptāverat","raptō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haedum bālantem audīvit Tobiās, et, veritus nē fūrtō ablātus esset, dīxit uxōrī: “Vidē nē iste clam alicui ēreptus sit: redde illum dominō suō; nefās enim est nōbīs ex raptō vīvere.” Adeō vir iūstus ab omnī improbitāte abhorrēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"raptor","latin":"raptor, raptoris","headword":"raptor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"robber; plunderer","forms":["raptor","raptōrēs","raptōrī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Raptor}} currus per lacum stāgnaque agit et equōs hortātur, nōmine quemque vocandō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"raptum","latin":"raptum, rapti","headword":"raptum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"plunder; prey","forms":["rapta","raptī","raptīs","raptum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Servus imperāta dominī statim fēcit; puella {{rapta}} clāmābat et servum ōrābat, quī tamen eius vōcem audīre nōn vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"raptus","latin":"raptus, raptus","headword":"raptus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"violent snatching or dragging away; robbery, carrying off, abduction","forms":["raptus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"cēns fōrmōsus à Nymphīs {{raptus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"raro","latin":"rārō","headword":"rārō","letter":"r","pos":"adverb","posGroup":"adverb","english":"rarely","forms":["rārō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ita haud rārō fīēbat ut dī verba pessima audīrent atque ā līminibus in viās pellerentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rarus","latin":"rārus, -a, -um","headword":"rārus","letter":"r","pos":"adjective","posGroup":"adjective","english":"rare","forms":["rāra","rārae","rārī","rārīs","rārissima","rārissimum","rārissimus","rārius","raros"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Galli inter equites {{raros}} sagittarios expeditosque levis armaturae interiecerant, qui suis cedentibus auxilio succurrerent et nostrorum equitum impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rastrus","latin":"rastrus, rastri","headword":"rastrus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"drag-hoe (pl.); (usu. sg. N, pl. M)","forms":["rastrīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"et gravibus {{rastrīs}} sub Iove versat humum;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ratio","latin":"ratiō, ratiōnis","headword":"ratiō","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"(f.) reason; reason, explanation; reason, account, explanation; reason, order, account","forms":["ratio","ratione","rationem","ratiōnēs","rationibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In primis {{rationem}} esse habendam dicunt, prius quam eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rationalis","latin":"ratiōnālis","headword":"ratiōnālis","letter":"r","pos":"adjective","posGroup":"adjective","english":"(coniūnctiō) (f.) conjunction showing the train of thought","forms":["ratiōnālēs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Coniūnctiō quid est?' Discipulus: 'Pars ōrātiōnis adnectēns ōrdinānsque sententiam.' Magister: 'Potestās coniūnctiōnum quot speciēs habet?' Discipulus: 'Quīnque.' Magister: 'Quās?' Discipulus: 'Cōpulātīvās, disiūnctīvās, explētīvās, causālēs, {{ratiōnālēs}}.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ratis","latin":"ratis, ratis","headword":"ratis","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"(f.) raft; ship, boat","forms":["rate","ratem","ratēs","rati","ratis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iuppiter igitur postquam Deucaliōnem eiusque uxōrem, Pyrrham nōmine, quōs Mercurius praeter cēterōs servandōs esse cēnsēbat, in {{rate}} quādam posuit, ventōs omnēs līberāvit, nūbibusque ātrīs tōtum caelum operuit; deinde ingentēs imbrēs dē caelō mīsit, et aquās tōtīus orbis ita auxit, ut omnēs terrae mergerentur: omnia mare erant, et lītora quoque marī dēerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ratus","latin":"ratus, -a, -um","headword":"ratus","letter":"r","pos":"adjective","posGroup":"adjective","english":"valid, fixed, certain; valid, fixed, certain in proportion","forms":["rata","ratam","ratus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quādam nocte, cum iacēret Hēlī in lectulō, Dominus vocāvit Samūēlem, quī {{ratus}} sē ā sacerdōte arcessī, cucurrit, dīxitque: “Ēn adsum: vocāstī enim mē.” At Hēlī: “Nōn tē vocāvī” inquit “fīlī mī: revertere in lectulum tuum.” Idque iterum et tertiō factum est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"raucus","latin":"raucus, -a, -um","headword":"raucus","letter":"r","pos":"adjective","posGroup":"adjective","english":"hoarse","forms":["rauca","raucum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nūlla verba in nymphā mānsērunt; sōlum vōx {{rauca}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"rea","latin":"rea, reae","headword":"rea","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"party in law suit; plaintiff/defendant; culprit/guilty party, debtor; sinner","forms":["rea"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Haec nostrō signàbitur à{{rea}} currū;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rebellare","latin":"(rebellō) rebellāre","headword":"rebellāre","letter":"r","pos":"","posGroup":"other","english":"reopen the war, revolt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"rebello","latin":"rebello, rebellare, rebellavi, rebellatus","headword":"rebello","letter":"r","pos":"verb","posGroup":"verb","english":"rebel, revolt","forms":["rebellandum","rebellārent","rebellāvērunt","rebellāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Absalōn, fīlius Davidis, paternum rēgnum affectāvit: concitātā multitūdine imperītā, adversus patrem {{rebellāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"recalfacio","latin":"recalfacio, recalfacere, recalfeci, recalfactus","headword":"recalfacio","letter":"r","pos":"verb","posGroup":"verb","english":"make warm again, warm up","forms":["recalface"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"445 Fac timeat dé tē tepidamque {{recalface}} mentem;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"recedere","latin":"(recēdō) recēdere, recessisse,  recessum","headword":"recēdere","letter":"r","pos":"","posGroup":"other","english":"withdraw","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"recedo","latin":"recēdō, -ere, -cessī, -cessum","headword":"recēdō","letter":"r","pos":"verb","posGroup":"verb","english":"go back, draw back, recede, retreat","forms":["recēdām","Recēde","recēdēbant","recēdēns","recēdentibus","recēdere","recēderētur","recēdit","Recēdite","recesserat","recessērunt","recessissent","recessisset","recessit","recessū"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Canis rūrsus fremere incipit: “Rrrr!” Tum vērō, tonitrū territus, post iānitōrem {{recēdit}} atque ululāre incipit: “Uuuū!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"recens","latin":"recēns (gen. recentis)","headword":"recēns","letter":"r","pos":"adverb; adjective","posGroup":"adverb","english":"fresh; recently, freshly; recent","forms":["recēns","recentem","recentes","recentī","recentibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi nactus {{recentem}} equitatum, quem multis ante diebus eo praemiserat, neque diurno neque nocturno itinere intermisso per fines Aeduorum in Lingones contendit, ubi duae legiones hiemabant, ut, si quid etiam de sua salute ab Aeduis iniretur consili, celeritate praecurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recenseo","latin":"recēnseō, -ēre, recēnsuī","headword":"recēnseō","letter":"r","pos":"verb","posGroup":"verb","english":"recount, review","forms":["recensebantur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Coactis equitum VIII milibus et peditum circiter CCXL, haec in Aeduorum finibus {{recensebantur}}, numerusque inibatur, praefecti constituebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"receptaculum","latin":"receptaculum, receptaculi","headword":"receptaculum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"receptacle; place of refuge, shelter","forms":["receptacula"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo tuta, neu suis sint ad detrectandam militiam {{receptacula}} neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recepto","latin":"recepto, receptare, receptavi, receptatus","headword":"recepto","letter":"r","pos":"verb","posGroup":"verb","english":"recover; receive, admit (frequently)","forms":["recepto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus rebus confectis Caesar ad oppidum Avaricum, quod erat maximum munitissimumque in finibus Biturigum atque agri fertilissima regione, profectus est, quod eo oppido {{recepto}} civitatem Biturigum se in potestatem redacturum confidebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"receptum","latin":"receptum, recepti","headword":"receptum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"obligation","forms":["receptum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Eo cum Eporedorix Viridomarusque venissent et de statu civitatis cognovissent, Litaviccum Bibracte ab Aeduis {{receptum}}, quod est oppidum apud eos maximae auctoritatis, Convictolitavem magistratum magnamque partem senatus ad eum convenisse, legatos ad Vercingetorigem de pace et amicitia concilianda publice missos, non praetermittendum tantum commodum existimaverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"receptus","latin":"receptus, -a, -um","headword":"receptus","letter":"r","pos":"adjective","posGroup":"adjective","english":"received, welcomed","forms":["receptui","receptus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar {{receptui}} cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono tubae, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recidere","latin":"(recīdō) recīdere, -cidisse, -āsum (< caedere)","headword":"recīdere","letter":"r","pos":"verb","posGroup":"verb","english":"cut away, cut down; fall back; to cut back, remove","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"recidivus","latin":"recidivus, recidiva, recidivum","headword":"recidivus","letter":"r","pos":"adjective","posGroup":"adjective","english":"recurring","forms":["recidīva"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et {{recidīva}} manū posuissem Pergama victīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"recido","latin":"recido, recidere, recidi, recasus","headword":"recido","letter":"r","pos":"verb","posGroup":"verb","english":"fall/sink back, lapse/relapse/revert; fall to earth; come to naught; rebound on","forms":["recidere","recīdit","recīdunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos {{recidere}} demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recingo","latin":"recingo, recingere, -, recinctus","headword":"recingo","letter":"r","pos":"verb","posGroup":"verb","english":"ungird, unfasten, undo","forms":["recīncta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ūnum exūta pedem vinclīs, in veste {{recīncta}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"reciperare","latin":"(reciperō) reciperāre","headword":"reciperāre","letter":"r","pos":"","posGroup":"other","english":"recover, recapture","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"recipere","latin":"(recipiō) recipere, recēpisse,  receptum","headword":"recipere","letter":"r","pos":"verb","posGroup":"verb","english":"receive; to receive, welcome","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"recipero","latin":"recipero, reciperare, reciperavi, reciperatus","headword":"recipero","letter":"r","pos":"verb","posGroup":"verb","english":"restore, restore to health; refresh, recuperate","forms":["reciperandae","reciperandorum","reciperare","reciperaturos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Postremo in acie praestare interfici quam non veterem belli gloriam libertatemque quam a maioribus acceperint {{reciperare}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recipio","latin":"recipiō, -ere, -cēpī, -ceptum","headword":"recipiō","letter":"r","pos":"verb","posGroup":"verb","english":"regain, take back; receive","forms":["receperant","recēperat","receperint","recēperis","receperunt","recēpī","recēpissem","recēpissent","recēpisset","recēpistī","recēpit","receptā","receptam","receptās","receptī","receptīs","receptos","recipe","recipere","reciperem","reciperet","reciperētur","recipi","recipiam","recipiat","recipiatur","recipiendam","recipiendi","recipiendīs","recipientem","recipiēs","recipiō","recipis","recipit","recipite","recipiunt","recipiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Centuriones in oppido, cum ex significatione Gallorum novi aliquid ab eis iniri consili intellexissent, gladiis destrictis portas occupaverunt suosque omnes incolumes {{receperunt}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recitare","latin":"recitāre","headword":"recitāre","letter":"r","pos":"verb","posGroup":"verb","english":"to recite","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"recitat","latin":"recitat","headword":"recitat","letter":"r","pos":"verb","posGroup":"verb","english":"recites, reads aloud","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"recito","latin":"recitō, recitāre","headword":"recitō","letter":"r","pos":"verb","posGroup":"verb","english":"read aloud","forms":["recita","recitābam","recitābant","recitābat","recitābō","recitāmus","recitandi","recitāns","recitante","recitantem","recitāre","recitās","recitat","recitata","recitātae","recitātis","recitāveram","recitāverāmus","recitāverās","recitāverātis","recitāvērunt","recitāvit","recites","recitet","recitō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Et cum ille ē librō suō {{recitat}}, nōs simper dormīmus!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"reclino","latin":"reclino, reclinare, reclinavi, reclinatus","headword":"reclino","letter":"r","pos":"verb","posGroup":"verb","english":"bend back; [se reclinare => lean back, recline]","forms":["reclīnāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum essent ibi, impletī sunt diēs pariendī, et peperit fīlium, quem pannīs involvit et {{reclīnāvit}} in praesēpiō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"recludo","latin":"recludo, recludere, reclusi, reclusus","headword":"recludo","letter":"r","pos":"verb","posGroup":"verb","english":"open; open up, lay open, disclose, reveal","forms":["reclūdit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"auxiliumque viae veterēs tellūre {{reclūdit}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"recognoscere","latin":"(recognōscō) recognōscere, recognōvisse, recognitum","headword":"recognōscere","letter":"r","pos":"","posGroup":"other","english":"recognize","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"recognosco","latin":"recōgnōscō, -ere, recōgnōvī, recōgnitum","headword":"recōgnōscō","letter":"r","pos":"verb","posGroup":"verb","english":"recognise, recall","forms":["recognōscās","Recognōsce","recognōsceret","recognōscit","recognōvī","recōgnōvit"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Polycratēs, cum ānulum suum {{recognōsceret}}, maxima laetitia affectūs est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"reconciliare","latin":"(reconciliō) reconciliāre","headword":"reconciliāre","letter":"r","pos":"","posGroup":"other","english":"win back, reconcile","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reconcilio","latin":"reconcilio, reconciliare, reconciliavi, reconciliatus","headword":"reconcilio","letter":"r","pos":"verb","posGroup":"verb","english":"restore; reconcile","forms":["reconciliābitur","reconciliāre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nisi gēns nostra in Deum peccāvisset, numquam in hās miseriās incīdissēmus; sed mox Deus, meō frātrumque meōrum sanguine plācātus, genfī nostrae {{reconciliābitur}}, et nōs post mortem patienter tolerātam aetēma vlta dōnābit.\"Tum Antiochus indignē ferēns sē dērīsum esse, in illum exquīsītō suppliciō necāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"recondo","latin":"recondo, recondere, recondidi, reconditus","headword":"recondo","letter":"r","pos":"verb","posGroup":"verb","english":"hide, conceal; put away","forms":["recondam","recondat","reconditum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque, Rēx, praefice tōtī Aegyptō virum sapientem et industrium, quī partem frūgum {{recondat}} in horreīs pūblicīs, servetque dīligenter in subsidium famis secūtūrae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"recordari","latin":"(recordor) recordārī","headword":"recordārī","letter":"r","pos":"","posGroup":"other","english":"call to mind, recollect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"recordor","latin":"recordor, recordari, recordatus sum","headword":"recordor","letter":"r","pos":"verb","posGroup":"verb","english":"think over; call to mind, remember","forms":["recordābātur","recordābor","recordāminī","recordātus","recordēminī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum obdūxerō nūbēs caelō, arcus meus appārēbit, et {{recordābor}} foederis meī, nec unquam dīluvium erit ad perdendum orbem terrārum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"recreare","latin":"(recreō) recreāre","headword":"recreāre","letter":"r","pos":"","posGroup":"other","english":"restore, revive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"recreo","latin":"recreo, recreare, recreavi, recreatus","headword":"recreo","letter":"r","pos":"verb","posGroup":"verb","english":"restore, revive","forms":["recreātur","Recreātus","recreāvit","recreor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Recreātus}} hôc sennône reposuî cubitum, Habinnamque intrantem cum admîrätiône ingentî spectābam.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"recta","latin":"recta","headword":"recta","letter":"r","pos":"adverb","posGroup":"adverb","english":"directly, straight","forms":["recta"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Oppidi murus ab planitie atque initio ascensus {{recta}} regione, si nullus anfractus intercederet, mille CC passus aberat; quidquid huc circuitus ad molliendum clivum accesserat, id spatium itineris augebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recte","latin":"rēctē","headword":"rēctē","letter":"r","pos":"adverb","posGroup":"adverb","english":"correctly; rightly, correctly","forms":["recte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam, si legiones in provinciam arcesseret, se absente in itinere proelio dimicaturas intellegebat; si ipse ad exercitum contenderet, ne eis quidem eo tempore qui quieti viderentur, suam salutem {{recte}} committi videbat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rector","latin":"rēctor, -ōris (m.)","headword":"rēctor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"ruler, governor","forms":["rēctor","rēctōre","rēctōrēs","rēctōribus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Sit huic oppositus alter, bonus et sapiēns et perītus ūtilitātis dignitātisque cīvīlis, quasi tūtor et prōcūrātor reī pūblicae: sīc enim appelletur quīcumque erit {{rēctor}} et gubernātor cīvitātis.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rectum","latin":"rectum, recti","headword":"rectum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"virtue; the_right","forms":["rēctum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus: “Alterum respōnsum est {{rēctum}} — alterum nōn rēctum!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"rectus","latin":"rēctus, -a, -um","headword":"rēctus","letter":"r","pos":"adjective","posGroup":"adjective","english":"straight, correct; right, correct; straight, right","forms":["rēctam","rēctās","rēctī","rectis","rēctissimē","rēctius","rēctus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae {{rectis}} lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"recubo","latin":"recubo, recubare, recubui, recubitus","headword":"recubo","letter":"r","pos":"verb","posGroup":"verb","english":"lie down/back, recline, lie on the back","forms":["recubuisse","recubuit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"circā fontem erat mollis herba, in quā puer cum fessus esset currendō per silvāsam, {{recubuit}}; deinde, cum sitim paterētur, vultum ad aquam admōvit; cum vērō suam imāginem in aquā vīdisset, crēdidit ibi fōrmōsissimum latēre puerum; cuius amōre statim accēnsus est, dumque sitim sēdāre cupit, sitis altera crēvit, dumque bibit, vīsae correptus imāgine fōrmae","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"recumbere","latin":"(recumbō) recumbere, recubuisse","headword":"recumbere","letter":"r","pos":"verb","posGroup":"verb","english":"lie down, lie back; to lie back, recline","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"recumbo","latin":"recumbo, recumbere, recubui, -","headword":"recumbo","letter":"r","pos":"verb","posGroup":"verb","english":"recline, lie at ease, sink/lie/settle back/down; recline at table","forms":["recumbēns","recumbentium","recumbere","recumbit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tum, simul atque eam cōnsistere et in herbā {{recumbere}} vīdit, imperāvit cuidam mīlitī (nam, cum esset prīnceps suī populī, sēcum aliquot amīcōs mīlitēsque dūcēbat) ut fontem quaereret et inde aquam afferret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"recurso","latin":"recurso, recursare, recursavi, recursatus","headword":"recurso","letter":"r","pos":"verb","posGroup":"verb","english":"keep rebounding/recoiling; keep recurring to the mind","forms":["recursat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"multa virī virtūs animō multusque {{recursat}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"recusare","latin":"(recūsō) recūsāre","headword":"recūsāre","letter":"r","pos":"verb","posGroup":"verb","english":"reject, refuse; to refuse","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"recusatio","latin":"recusatio, recusationis","headword":"recusatio","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"refusal","forms":["recūsātiōne"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Illī autem, quī omnia dē rē pūblicā praeclārā atque ēgregiā sentīrent, sine {{recūsātiōne}} ac sine ūllā morā negōtium suscēpērunt, et, cum advesperāsceret, occultē ad pontem Mulvium pervēnērunt atque ibi in proximīs villīs ita bipertītō fuērunt ut Tiberīs inter eōs et pōns interesset.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"recuso","latin":"recūsō (1)","headword":"recūsō","letter":"r","pos":"verb","posGroup":"verb","english":"refuse","forms":["recūsant","recūsantēs","recusare","recūsat","recūsāveris","recūsāvit","recusent","recūsō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa {{recusare}}, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reddere","latin":"reddere","headword":"reddere","letter":"r","pos":"verb","posGroup":"verb","english":"to give back, return","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reddit","latin":"reddit","headword":"reddit","letter":"r","pos":"verb","posGroup":"verb","english":"gives back, returns","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reddo","latin":"reddō, reddere","headword":"reddō","letter":"r","pos":"verb","posGroup":"verb","english":"give back, give; give back, restore","forms":["reddam","reddant","reddantur","reddās","reddat","redde","reddēns","reddent","reddere","redderem","redderent","redderentur","redderet","redderētur","reddet","reddī","reddiderat","reddiderit","reddidērunt","reddidī","reddidistī","reddidit","reddis","reddit","reddita","redditae","reddite","redditī","redditō","redditum","redditur","redditūrum","reddō","reddunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, fideli atque utili superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, iura legesque {{reddiderat}} atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"redeo","latin":"redeō, redīre","headword":"redeō","letter":"r","pos":"verb","posGroup":"verb","english":"go back, return","forms":["redeam","redeāmus","redeās","redeat","redeātis","redeō","redeundī","redeundō","redeundum","redeunt","redeuntem","redeuntēs","Redeuntī","redeuntibus","redeuntis","redī","redībant","redībat","redībimus","redībis","redībit","redībō","rediēns","rediēre","redīmus","redīre","redīrent","redīrēs","redīret","redit","redīte","redītis","reditū","reditum","reditūrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mēdus: “Vērum dīcis: necesse est nōs simul in patriam nostrum {{redīre}}.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"redigere","latin":"(redigō) redigere (< agere)","headword":"redigere","letter":"r","pos":"","posGroup":"other","english":"drive back, bring, reduce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"redigo","latin":"redigō, -ere, -ēgī, -āctum","headword":"redigō","letter":"r","pos":"verb","posGroup":"verb","english":"to reduce, bring back","forms":["redacta","redāctae","redāctum","redacturum","redēgī","redēgit","redigentur","redigunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus rebus confectis Caesar ad oppidum Avaricum, quod erat maximum munitissimumque in finibus Biturigum atque agri fertilissima regione, profectus est, quod eo oppido recepto civitatem Biturigum se in potestatem {{redacturum}} confidebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"redimere","latin":"(redimō) redimere, redēmisse, redēmptum","headword":"redimere","letter":"r","pos":"verb","posGroup":"verb","english":"buy back; to ransom, redeem","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"redimio","latin":"redimio, redimire, redimivi, redimitus","headword":"redimio","letter":"r","pos":"verb","posGroup":"verb","english":"encircle with a garland, wreathe around; surround, encircle","forms":["redimītam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cernis autem eandem terram quasi quibusdam {{redimītam}} et circumdatam cingulīs, ē quibus duōs maximē inter sē dīversōs et caelī verticibus ipsīs ex utrāque parte subnīxōs obriguisse pruīnā vidēs, medium autem illum et maximum sōlis ārdōre torrērī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"redimire","latin":"(redimiō) redimīre, -isse, -ītum","headword":"redimīre","letter":"r","pos":"","posGroup":"other","english":"encircle, surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"redimo","latin":"redimō, -ere, redēmī, redemptum","headword":"redimō","letter":"r","pos":"verb","posGroup":"verb","english":"buy back, ransom","forms":["redēmerim","redēmī","redēmit","redēmpta","redēmptus","redimat","redimēbat","redimendīs","redimere","redimerem","redimerēs","redimī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mēdus: \"Ergō nūlla spēs est mihi, quī nec ipse pecūniam habeō nec amīcum tam pecūniōsum, ut mē ē servitūte {{redimere}} possit aut velit.\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"redintegro","latin":"redintegro, redintegrare, redintegravi, redintegratus","headword":"redintegro","letter":"r","pos":"verb","posGroup":"verb","english":"renew; revive","forms":["redintegrarentur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Qui Avarico expugnato refugerant, armandos vestiendosque curat; simul, ut deminutae copiae {{redintegrarentur}}, imperat certum numerum militum civitatibus, quem et quam ante diem in castra adduci velit, sagittariosque omnes, quorum erat permagnus numerus in Gallia, conquiri et ad se mitti iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"redit","latin":"redit","headword":"redit","letter":"r","pos":"verb","posGroup":"verb","english":"returns, goes back","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reditus","latin":"reditus, -ūs","headword":"reditus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"return","forms":["reditus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{reditus}} -üs r1 € red-īre; dà reditum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"reducere","latin":"(redūcō) redūcere, redūxisse, reductum","headword":"redūcere","letter":"r","pos":"","posGroup":"other","english":"lead back","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"reduco","latin":"reduco, reducere, reduxi, reductus","headword":"reduco","letter":"r","pos":"verb","posGroup":"verb","english":"lead back, bring back; restore; reduce","forms":["redūcam","reducebant","redūcentēs","redūcere","reducerent","reduceret","reducēs","redūcī","reducit","reductūrum","reducunt","redūxī","reduxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum {{reducit}} atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reductus","latin":"reductus, reducta, reductum","headword":"reductus","letter":"r","pos":"adjective","posGroup":"adjective","english":"receding deeply, set back","forms":["reductam","Reductīs","reductōs","reductus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At Minerva eam inventam et in vītam {{reductam}} herbae cuiusdam sūcō aspersit; quō factum est ut tōtum eius corpus parvum fieret; in utrōque latere octo gracilia crūra appāruerunt; ex ventre verō iam ab illō tempore stāmen ēmittit: arānea enim facta, ut anteā, etiam nunc tēlās tēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"redundare","latin":"(redundō) redundāre","headword":"redundāre","letter":"r","pos":"","posGroup":"other","english":"overflow, be exuberant","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"redundo","latin":"redundo, redundare, redundavi, redundatus","headword":"redundo","letter":"r","pos":"verb","posGroup":"verb","english":"overflow; be too numerous","forms":["redundantēs","redundāret"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Is dedit operam — sī modo id cōnsequī potuit — ut nimis {{redundantēs}} nōs et superfluentēs iuvenīlī quādam dīcendī impūnitāte et licentiā reprimeret et quasi extrā rīpās diffluentēs coercēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"refellere","latin":"(refellō) refellere, refellisse","headword":"refellere","letter":"r","pos":"","posGroup":"other","english":"refute","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"refello","latin":"refello, refellere, refelli, -","headword":"refello","letter":"r","pos":"verb","posGroup":"verb","english":"refute, rebut","forms":["refellō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Neque tē teneō neque dicta tua refellō: ī, pete rēgnum Italiae per undās!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"referit","latin":"referit, referre, retulit, relatus est","headword":"referit","letter":"r","pos":"verb","posGroup":"verb","english":"it matters/makes a difference/is of importance; matter/be of importance (PERS)","forms":["retulisse"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Faciundum eī aliquid quod illōrum magis quam sua {{retulisse}} vidērētur; id adeō in prōmptū esse, quoniam cōpiam Iugurthae habēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"refero","latin":"refero, referre, rettuli, relatus","headword":"refero","letter":"r","pos":"verb","posGroup":"verb","english":"bring/carry back/again/home; move/draw/force back, withdraw; go back, return","forms":["refer","referam","referant","referat","referātur","referebam","referēbantur","referēbat","referent","referente","referentibus","referet","referō","referre","referrent","referret","referri","refers","refert","refertō","referundum","referunt","referuntur","relāta","relātam","relātum","rettulerint","rettulērunt","rettulissent","rettulisset","rettulit","retulimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Frumentum omne ad se {{referri}} iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, viritim distribuit; frumentum parce et paulatim metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"referre","latin":"(referō) referre, rettulisse, relātum","headword":"referre","letter":"r","pos":"","posGroup":"other","english":"bring back, return","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"refert  referre","latin":"rēfert (meā) rēferre","headword":"rēfert  rēferre","letter":"r","pos":"","posGroup":"other","english":"it is important (for me)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reficere","latin":"(reficiō) reficere (< facere)","headword":"reficere","letter":"r","pos":"verb","posGroup":"verb","english":"restore, repair; to rebuild, restore","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"reficio","latin":"reficio, reficere, refeci, refectus","headword":"reficio","letter":"r","pos":"verb","posGroup":"verb","english":"rebuild, repair, restore","forms":["refēcerat","refēcit","Refectīs","Refecto","refectum","reficere","reficeret","reficit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Caesar Avarici complures dies commoratus summamque ibi copiam frumenti et reliqui commeatus nactus exercitum ex labore atque inopia {{reficit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"refluo","latin":"refluo, refluere, -, -","headword":"refluo","letter":"r","pos":"verb","posGroup":"verb","english":"flow back, recede","forms":["refluentēs","refluit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Metū perculsī Aegyptiī coepērunt fugere; at Deus dīxit Moȳsī: “Extende rūrsus dextram in mare, ut aquae revertantur in locum suum.” Pāruit Moysēs, et statim aquae {{refluentēs}} obruērunt Aegyptiōs, et eōrum currūs, et equitēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reformido","latin":"reformido, reformidare, reformidavi, reformidatus","headword":"reformido","letter":"r","pos":"verb","posGroup":"verb","english":"dread; shun; shrink from; recoil at the sight of","forms":["reformīdet"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cuius in magnīs catervīs amīcōrum sī fuit etiam Caelius, magis est ut ipse molestē ferat errāsse sē — sīcuti nōnnumquam in eōdem homine mē quoque errōris meī paenitet! — quam ut istīus amīcitiae crīmen {{reformīdet}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"refoveo","latin":"refoveo, refovere, refovi, refotus","headword":"refoveo","letter":"r","pos":"verb","posGroup":"verb","english":"warm again; refresh, revive","forms":["refovet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"quam puer ipse deus collāpsōsque excipit artūs, et modo tē {{refovet}}, modo trīstia vulnera siccat, nunc animam admōtīs fugientem sustinet herbīs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"refugio","latin":"refugio, refugere, refugi, -","headword":"refugio","letter":"r","pos":"verb","posGroup":"verb","english":"flee back; run away, escape","forms":["refugerant","refūgērunt","refugit","refugiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui Avarico expugnato {{refugerant}}, armandos vestiendosque curat; simul, ut deminutae copiae redintegrarentur, imperat certum numerum militum civitatibus, quem et quam ante diem in castra adduci velit, sagittariosque omnes, quorum erat permagnus numerus in Gallia, conquiri et ad se mitti iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"refulgeo","latin":"refulgeo, refulgere, refulsi, -","headword":"refulgeo","letter":"r","pos":"verb","posGroup":"verb","english":"flash back, reflect light; shine brightly; gleam, glitter, glisten","forms":["refulsit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīxit, et āvertēns roseā cervīce {{refulsit}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"refundo","latin":"refundo, refundere, refudi, refusus","headword":"refundo","letter":"r","pos":"verb","posGroup":"verb","english":"pour back","forms":["refūsa"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"stāgna {{refūsa}} vadīs, graviter commōtus; et altō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"regalis","latin":"rēgālis, -e","headword":"rēgālis","letter":"r","pos":"adjective","posGroup":"adjective","english":"royal","forms":["rēgāle","rēgālem","rēgālī","regālia","rēgālis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quid faciat? repetatne domum et {{regālia}} tēcta an lateat silvīs?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"regere","latin":"(regō) regere, rēxisse, rēctum","headword":"regere","letter":"r","pos":"verb","posGroup":"verb","english":"rule; to rule","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"regia","latin":"rēgia, -ae","headword":"rēgia","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"royal palace; palace","forms":["rēgia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Illum, quī ā sē Saūlem occīsum esse iactitābat, et {{rēgia}} īnsignia attulerat, perimī iussit, in poenam violātae māiestātis rēgiae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"regina","latin":"rēgīna, -ae","headword":"rēgīna","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"queen","forms":["rēgīna","rēgīnae","rēgīnam","Reginum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Antistium {{Reginum}} in Ambivaretos, T.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"regio","latin":"regiō, regiōnis","headword":"regiō","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"(f.) region; region, land","forms":["rēgiō","regione","regiōnem","regiones","regionibus","regiōnis","regiōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quibus rebus confectis Caesar ad oppidum Avaricum, quod erat maximum munitissimumque in finibus Biturigum atque agri fertilissima {{regione}}, profectus est, quod eo oppido recepto civitatem Biturigum se in potestatem redacturum confidebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"regius","latin":"rēgius, -a, -um","headword":"rēgius","letter":"r","pos":"adjective","posGroup":"adjective","english":"royal","forms":["rēgiae","rēgiam","rēgiās","rēgiē","rēgiī","rēgiīs","rēgiōs","rēgium","rēgius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat Saūlī ingēns statūra et fōrma excellēns, adeō ut dignitās corporis dignitātī {{rēgiae}} pulchrē convenīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"regnare","latin":"(rēgnō) rēgnāre, rēgnāvisse, rēgnātum","headword":"rēgnāre","letter":"r","pos":"verb","posGroup":"verb","english":"rule; to rule, reign","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"regnat","latin":"regnat","headword":"regnat","letter":"r","pos":"verb","posGroup":"verb","english":"rules, reigns","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"regnator","latin":"regnator, regnatoris","headword":"regnator","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"king, lord","forms":["rēgnātor"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{rēgnātor}}, caelum et terrās quī nūmine torquet,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"regno","latin":"rēgnō (1)","headword":"rēgnō","letter":"r","pos":"verb","posGroup":"verb","english":"to rule, reign","forms":["rēgnābant","rēgnābat","rēgnābis","rēgnandum","rēgnante","regnantibus","rēgnāre","rēgnāret","rēgnās","rēgnat","rēgnāverat","rēgnāvērunt","rēgnāvimus","rēgnāvissent","rēgnāvisset","rēgnāvit","rēgnet","rēgnō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dāvīd, cum fīliō dedisset praecepta rēgnō administrandō ūtilissima, diem suprēmum obiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"regnum","latin":"rēgnum, -ī","headword":"rēgnum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"kingship, kingdom, reign; kingdom, rule; kingdom, kingship","forms":["rēgna","rēgnī","rēgnīs","rēgnōrum","regnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod {{regnum}} appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rego","latin":"rego, regere, rexi, rectus","headword":"rego","letter":"r","pos":"verb","posGroup":"verb","english":"rule, guide; manage, direct","forms":["regēbat","regenda","regendum","regendus","regentibus","regere","regeret","regerētur","reget","regit","rēxit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mīnōs rēx, quī Crētam īnsulam {{regēbat}}, ibi magnam et pulchram rēgiam, multōs servōs, magnam pecūniam habēbat; itaque superbus factus erat, atque deōs omnēs sibi favēre putābat sēque ab iīs omnia petere posse.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"regredi","latin":"(regredior) regredī, -gressum","headword":"regredī","letter":"r","pos":"","posGroup":"other","english":"go back, return","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"regredior","latin":"regredior, regredi, regressus sum","headword":"regredior","letter":"r","pos":"verb","posGroup":"verb","english":"go back, return, retreat","forms":["regressa","regressī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Precibus eius et lacrimīs mōtus, Deus quīndecim annōrum ūsūram illī concessit, atque, ad faciendam fidem, sōlis umbrā, rēge ita postulante, per decem līneās {{regressa}} est in eius hōrologiō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"regressus","latin":"regressus, regressus","headword":"regressus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"going back, return","forms":["regressus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iōsēphus, lōta faciē, {{regressus}} continuit sē, et iussit appōnī cibōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"regula","latin":"rēgula, -ae","headword":"rēgula","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"ruler","forms":["rēgulam","rēgulās","rēgulīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dāvus Mārcō librum et tabulam et stilum et {{rēgulam}} affert.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"regulus","latin":"rēgulus, -ī","headword":"rēgulus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"petty king, prince","forms":["rēgulī","Regulō","Regulum","rēgulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat quīdam {{rēgulus}}, cuius fīlius Īnfirmābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reicio","latin":"reicio, reicere, rejeci, rejectus","headword":"reicio","letter":"r","pos":"verb","posGroup":"verb","english":"throw back; drive back; repulse, repel; refuse, reject, scorn","forms":["reice"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"sed tū sī sapiēs, sī tē bene iungere anumque hanc audīre volēs (quae tē plūs omnibus illīs, plūs, quam crēdis, amō): vulgārēs {{reice}} taedās","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"reiicio","latin":"rejicio, rejicere, rejeci, rejectus","headword":"rejicio","letter":"r","pos":"verb","posGroup":"verb","english":"throw back; drive back; repulse, repel; refuse, reject, scorn","forms":["reiēcit","reiectus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quam ob causam {{reiectus}} est ā Deō, et in eius locum Dāvīd, adhūc iuvenis, ē tribū Iūdae ēlēctus est, et ā Samūēle ūnctus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"relabor","latin":"relabor, relabi, relapsus sum","headword":"relabor","letter":"r","pos":"verb","posGroup":"verb","english":"fall back, vanish","forms":["relāpsa"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Orpheus timēns et avidus magnopere respicere dēsīderābat; amāns oculōs revertit et prōtinus illa {{relāpsa}} est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"relativum","latin":"relātīvum","headword":"relātīvum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"relative","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"relaxare","latin":"(relāxō) relaxāre","headword":"relaxāre","letter":"r","pos":"verb","posGroup":"verb","english":"relax, relieve; to relax, relieve","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"relaxo","latin":"relaxo, relaxare, relaxavi, relaxatus","headword":"relaxo","letter":"r","pos":"verb","posGroup":"verb","english":"loosen, widen; relax","forms":["relaxāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tē autem permagnum est nancīscī ōtiōsum, hōc praesertim mōtū reī pūblicae.' Tum Scīpiō: 'Atquī nactus es, sed mēhercule ōtiōsiōrem operā quam animō.' Et ille: 'At tū vērō animum quoque {{relaxāre}} oportet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"relevo","latin":"relevo, relevare, relevavi, relevatus","headword":"relevo","letter":"r","pos":"verb","posGroup":"verb","english":"relieve/alleviate/diminish/lighten; ease/refresh; exonerate; raise; lift (eyes)","forms":["relevārī","relevātī","relevātus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quod sī ex tantō latrōciniō iste tollētur, vidēbimur fortasse ad breve quoddam tempus cūrā et metū esse relevātī, perīculum autem residēbit et erit inclūsum penitus in vēnīs atque in vīsceribus reī pūblicae.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"relictum","latin":"relictum, relicti","headword":"relictum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"that which is left/forsaken/abandoned/left untouched; the residue/remaining","forms":["relictum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quid faciat? multum caelī post terga {{relictum}}, ante oculōs plūs est;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"relictus","latin":"relictus, relicta -um, relictior -or -us, relictissimus -a -um","headword":"relictus","letter":"r","pos":"adjective","posGroup":"adjective","english":"forsaken, abandoned, derelict; left untouched","forms":["relictus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus {{relictus}} locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"religio","latin":"religiō, -ōnis ( f.)","headword":"religiō","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"fear of the gods, religion","forms":["religiō","religiōne","religiōnem","religiōnēs","religiōnis","religiōnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quīdam tamen sānctī virī coluērunt vēram {{religiōnem}} et virtūtem: inter quōs fuit Abrahamus ē genere Sēmī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"religiosus","latin":"religiōsus, -a, -um","headword":"religiōsus","letter":"r","pos":"adjective","posGroup":"adjective","english":"devout, holy","forms":["religiosī","religiōsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mortuō patre, IOsaphātus rēgnāre coepit, fuitque {{religiōsus}} Deī cultor: quāpropter Deus illum glōria et dīvitiīs auxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"religo","latin":"religo, religare, religavi, religatus","headword":"religo","letter":"r","pos":"verb","posGroup":"verb","english":"tie out of the way; bind fast; moor","forms":["religātā","religāvit","religētur"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nōs quoque Circaeō religātā in lītore nāve,\nAntiphatē memorem tum crūdēlisque Cyclōpis,\nīre negābāmus; sed tēcta ignōta subīre\nsorte sumus lēctī:","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"relinquere","latin":"relinquere","headword":"relinquere","letter":"r","pos":"verb","posGroup":"verb","english":"to leave behind; leave (behind)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"relinquit","latin":"relinquit, -unt","headword":"relinquit","letter":"r","pos":"verb","posGroup":"verb","english":"leave; leaves (behind), abandons; leaves (behind); leaves behind, abandons","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"relinquo","latin":"relinquō, -ere, relīquī, relictum","headword":"relinquō","letter":"r","pos":"verb","posGroup":"verb","english":"leave, leave behind; leave behind; leave behind, abandon; to leave behind, abandon","forms":["relicta","relictae","relictam","relictās","relicti","relictis","relicto","relictōs","relinquam","relinquat","relinquātis","relinque","relinquēbant","relinquendam","relinquendō","relinquendum","relinquēns","relinquent","relinquentem","relinquentēs","relinquere","relinquerem","relinquerent","relinquerēs","relinqueret","relinquētis","relinquī","relinquimus","relinquis","relinquit","relinquite","relinquitur","relinquō","relinquor","relinquunt","relīquerant","reliquerat","relīquēre","relīquerint","relīquerit","reliquerunt","reliqui","relīquisse","relīquissent","relīquisset","relīquistī","relīquit","RELIQVIT"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aedui de consilio legatorum, quos Caesar ad exercitum {{reliquerat}}, copias equitatus peditatusque subsidio Biturigibus mittunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reliquia","latin":"reliquia, reliquiae","headword":"reliquia","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"remains/relics (pl.) (esp. post cremation); remnants/traces/vestiges; survivors","forms":["reliquiae","rēliquiās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam cum Sulla cōnsul contrā Mithridāten gestūrus bellum, quī Asiam et Achāiam occupāverat, mitterētur, isque exercitum in Campaniā paulisper tenēret, ut bellī sociālis — dē quō dīximus — quod intrā Ītaliam gestum fuerat, {{reliquiae}} tollerentur, Marius affectāvit ut ipse ad bellum Mithridāticum mitterētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"reliquiae","latin":"reliquiae, -ārum (pl.)","headword":"reliquiae","letter":"r","pos":"","posGroup":"other","english":"remnants, remains","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reliquum","latin":"reliquum, reliqui","headword":"reliquum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"that left after subtraction/elimination, remainder, residue, rest; balance owed","forms":["reliquum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Itaque interfectis Novioduni custodibus quique eo negotiandi causa convenerant, pecuniam atque equos inter se partiti sunt; obsides civitatum Bibracte ad magistratum deducendos curaverunt; oppidum, quod a se teneri non posse iudicabant, ne cui esset usui Romanis, incenderunt; frumenti quod subito potuerunt navibus avexerunt, {{reliquum}} flumine atque incendio corruperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reliquus","latin":"reliquus, -a, -um","headword":"reliquus","letter":"r","pos":"adjective","posGroup":"adjective","english":"remaining, left","forms":["reliqua","reliquae","reliquam","reliquarum","reliquas","reliquis","reliquō","reliquorum","reliquos","reliquus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab {{reliquis}} deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reluctor","latin":"reluctor, reluctari, reluctatus sum","headword":"reluctor","letter":"r","pos":"verb","posGroup":"verb","english":"resist, struggle against, make opposition","forms":["reluctantēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ārās falsīs dīīs per ūniversam IŪdaeam exstrūxit; omnia templī Hierosolymitanī omāmenta dētrāxit; librōs sacrōs iussit comburī; {{reluctantēs}} inaudītīs suppliciīs afrecit; urbem innumerā caede vastāvit: ac nē Iudaeī tot malīs oppressī rebellārent, praesidium in arce collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"remandare","latin":"(remandō) remandāre","headword":"remandāre","letter":"r","pos":"","posGroup":"other","english":"send back word","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"remaneo","latin":"remaneo, remanere, remansi, remansus","headword":"remaneo","letter":"r","pos":"verb","posGroup":"verb","english":"stay behind; continue, remain","forms":["Remanē","remaneat","remanebat","remanēbunt","remanent","remanēre","remanēret","remanet","remānserat","remānsisse","remānsissēmus","remānsisset","remānsit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His quam longissime possent egredi iussis, cum iam ex diei tempore coniecturam ceperat in castra perventum,: isdem sublicis, quarum pars inferior integra {{remanebat}}, pontem reficere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"remanere","latin":"(remaneō) remanēre, remānsisse, remānsum","headword":"remanēre","letter":"r","pos":"","posGroup":"other","english":"remain","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"remedium","latin":"remedium, remedi(i)","headword":"remedium","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"remedy, cure; medicine","forms":["remediōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sicyōnem inde et Argōs, nōbilēs urbēs, adit, inde haud parem opibus Epidaurum, sed inclūtam Aesculāpiī nōbilī templō, quod, quīnque mīlibus passuum ab urbe distāns, tum dōnīs dīves erat quae {{remediōrum}} salūtārium aegrī mercēdem sacrāverant deō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"remex","latin":"rēmex, -igis (m.)","headword":"rēmex","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"oarsman, rower","forms":["rēmige","rēmigis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"incitet et vēlō {{rēmigis}} addat opem,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"remigare","latin":"(rēmigō) rēmigāre, rēmigāvisse, rēmigātum","headword":"rēmigāre","letter":"r","pos":"verb","posGroup":"verb","english":"row back; to row","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"remigium","latin":"remigium, remigi(i)","headword":"remigium","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"rowing, oarage","forms":["Rēmigium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"45 {{Rēmigium}} volucrum, dispōnit in ōrdine pinnās,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"remigo","latin":"remigo, remigare, remigavi, remigatus","headword":"remigo","letter":"r","pos":"verb","posGroup":"verb","english":"row, use oars","forms":["rēmigant","rēmigāre"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Etsī nautae omnibus vīribus {{rēmigant}}, tamen illa nāvis, ventō secundō adiuvante, magis magisque appropinquat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"remigro","latin":"remigro, remigrare, remigravi, remigratus","headword":"remigro","letter":"r","pos":"verb","posGroup":"verb","english":"move back; return","forms":["remigrandī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Postquam illud tempus efflūxit, Cȳrus, Persārum rēx, dēvictō B abylōniorum rege, IŪdaeīs:fēcit potestātem in patriam remigrandī, templumque restituendī: sacra etiam vāsa, quae N abuchodonosor abstulerat, reddī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reminisci","latin":"(reminīscor) reminīscī (+ {i}gen{/i}. or {i}acc{/i}.)","headword":"reminīscī","letter":"r","pos":"verb","posGroup":"verb","english":"call to mind, recollect; to remember","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"reminiscor","latin":"reminiscor, reminisci, -","headword":"reminiscor","letter":"r","pos":"verb","posGroup":"verb","english":"call to mind, recollect","forms":["reminīscēbātur","reminīscēns","reminīscī","reminīscor"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Nōlīte eōrum reminīscī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"remissio","latin":"remissiō, -ōnis ( f.)","headword":"remissiō","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"relaxation; relaxation, easing","forms":["remissiōne","remissiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic est enim sanguis meus novī testamentī, quī prō mulfīs effundētur in {{remissiōnem}} peccātōrum.\"Et hymnō dictō, exiērunt in montem Olivefī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"remissus","latin":"remissus, remissa -um, remissior -or -us, remississimus -a -um","headword":"remissus","letter":"r","pos":"adjective","posGroup":"adjective","english":"relaxed/slack/sagging; loosely spaced; remiss; mild/gentle/free-and-easy/casual","forms":["remissus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duo tum excellebant ōrātōrēs, quī mē imitandī cupiditāte incitārent, Cotta et Hortēnsius, quōrum alter {{remissus}} et lēnis, alter ōrnātus, ācer et verbōrum et actiōnis genere commōtior.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"remittere","latin":"remittere","headword":"remittere","letter":"r","pos":"verb","posGroup":"verb","english":"to send back; to send back, let go back, drive away","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"remittit","latin":"remittit","headword":"remittit","letter":"r","pos":"verb","posGroup":"verb","english":"sends back","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"remitto","latin":"remittō, remittere","headword":"remittō","letter":"r","pos":"verb","posGroup":"verb","english":"send again, send back","forms":["remīsit","remissā","remissum","remissūrōs","remittam","remitte","remittēbantur","remittēbās","remittēbat","remittendōs","remittere","remitteret","remittet","remittit","remittō","remittunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut singulis effossis oculis domum {{remittit}}, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"remorari","latin":"(remoror) remorārī","headword":"remorārī","letter":"r","pos":"","posGroup":"other","english":"delay, linger","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"remoratus","latin":"remorātus, -a, -um","headword":"remorātus","letter":"r","pos":"adjective","posGroup":"adjective","english":"delayed again, hindered","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"remoror","latin":"remoror, remorari, remoratus sum","headword":"remoror","letter":"r","pos":"verb","posGroup":"verb","english":"delay","forms":["remorāta","remorātam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Iterum Hippomenēs virginem secundō pōmō {{remorātam}} superat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"remotus","latin":"remōtus, -a, -um","headword":"remōtus","letter":"r","pos":"adjective","posGroup":"adjective","english":"remote, distant","forms":["remōtā","remōtae","remotis","remoto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac {{remotis}} locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"removeo","latin":"removeō, -ēre, remōvī, remōtum","headword":"removeō","letter":"r","pos":"verb","posGroup":"verb","english":"remove, take away","forms":["Removē","removēbitur","removēre","removet","remōvisset","remōvistis","remōvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dum tālia dīcit, dea subitō ānus fōrmam ā sē {{remōvit}}, et sē clāram et armīs lūcentem ostendit: nymphae, quae ibi aderant, perterritae fūgērunt timentēs nē ipsae ā deā īrāta poenā afficerentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"removere","latin":"(removeō) removēre, remōvisse, remōtum","headword":"removēre","letter":"r","pos":"verb","posGroup":"verb","english":"remove; to remove, take away, put off","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"remunero","latin":"remunero, remunerare, remuneravi, remuneratus","headword":"remunero","letter":"r","pos":"verb","posGroup":"verb","english":"reward; repay, recompense, remunerate; requite; pay back, retaliate","forms":["remūnerābō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Iam fidēs tua mihi perspecta est, cum nōn pepercerīs fīliō tuō ūnicō; et ego favēbō tibi; remūnerābō splendidē fidem tuam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"remus","latin":"rēmus, -ī","headword":"rēmus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"oar","forms":["rēmī","rēmis","Remō","remorum","rēmōs","Remum","Remus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Conquirit etiam lintres; has magno sonitu {{remorum}} incitatas in eandem partem mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ren","latin":"ren, renis","headword":"ren","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"kidney(s) (usu. pl.); name of precious stone; (sg. ren not used L+S)","forms":["ren"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"domāre -uisse -itum — mītem/pà{{ren}}-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"renarro","latin":"renarro, renarrare, renarravi, renarratus","headword":"renarro","letter":"r","pos":"verb","posGroup":"verb","english":"tell over again","forms":["renārrābat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fāta {{renārrābat}} dīvum cursusque docēbat.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"renasci","latin":"(renāscor) renāscī, -ātum","headword":"renāscī","letter":"r","pos":"","posGroup":"other","english":"be reborn, be recreated","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"renascor","latin":"renascor, renasci, renatus sum","headword":"renascor","letter":"r","pos":"verb","posGroup":"verb","english":"be born again, be renewed, be revived","forms":["renāscētur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam prīncipium exstīnctum nec ipsum ab aliō {{renāscētur}} nec ex sē aliud creābit, sīquidem necesse est ā prīncipiō orīrī omnia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"renovare","latin":"(renovō) renovāre","headword":"renovāre","letter":"r","pos":"","posGroup":"other","english":"renew, resume","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"renovo","latin":"renovo, renovare, renovavi, renovatus","headword":"renovo","letter":"r","pos":"verb","posGroup":"verb","english":"renew, restore; revive","forms":["renovābat","renovandō","renovant","Renovantur","renovāre","renovat","renovātō","renovātum","renovāverat","renovāvī","renovāvit","renovent"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Renovantur}} cūrae rursusque surgit amor et īra: 'Ēn, quid agam?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"renuntiare","latin":"(renūntiō) renūntiāre","headword":"renūntiāre","letter":"r","pos":"","posGroup":"other","english":"report, renounce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"renuntio","latin":"renuntio, renuntiare, renuntiavi, renuntiatus","headword":"renuntio","letter":"r","pos":"verb","posGroup":"verb","english":"report, announce; reject","forms":["renuntiant","renūntiārent","renuntiatum","renūntiāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris {{renuntiant}} se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"renuo","latin":"renuo, renuere, renui, renutus","headword":"renuo","letter":"r","pos":"verb","posGroup":"verb","english":"refuse; disapprove; decline; give a refusal; throw back head/eye/brows as sign","forms":["renuēns","renuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Rēx impius {{renuit}} pārēre mandātīs Deī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reor","latin":"reor, reri, ratus sum","headword":"reor","letter":"r","pos":"verb","posGroup":"verb","english":"think, regard; deem; suppose, believe, reckon","forms":["ratū","rēbāmur","rēbantur","rēbātur","renda","rentur","reor","rēre","rēris","rētur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{renda}} (: patienda) prō-pōnant (ex-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"reparare","latin":"(reparō) reparāre","headword":"reparāre","letter":"r","pos":"","posGroup":"other","english":"repair, restore, renew","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reparo","latin":"reparo, reparare, reparavi, reparatus","headword":"reparo","letter":"r","pos":"verb","posGroup":"verb","english":"prepare again; renew, revive","forms":["reparāre","reparātō","reparāvērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sequentī annō Volscī contrā Rōmānōs bellum {{reparāvērunt}}, et victī aciē etiam Coriolōs, cīvitātem quam habēbant optimam, perdidērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"repecto","latin":"repecto, repectere, repexi, repexus","headword":"repecto","letter":"r","pos":"verb","posGroup":"verb","english":"comb back","forms":["repexa"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"hesternam crēdās — illa {{repexa}} modo est.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"repello","latin":"repellō, -ere, reppulī, repulsum","headword":"repellō","letter":"r","pos":"verb","posGroup":"verb","english":"drive back, drive away, spurn","forms":["repellere","reppulī","reppulisse","reppulit","repulsi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Bis magno cum detrimento {{repulsi}} Galli quid agant consulunt; locorum peritos adhibent; ex his superiorum castrorum situs munitionesque cognoscunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rependo","latin":"rependo, rependere, rependi, repensus","headword":"rependo","letter":"r","pos":"verb","posGroup":"verb","english":"weigh/balance (against); weigh out/pat in return; purchase, compensate","forms":["rependistis","rependite"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc Iōsēphus vocāvit dispēnsātōrem domūs suae, eīque dīxit: persequere virōs, et cum eōs assecūtus fuerīs, illīs dīcitō: quārē iniūriam prō beneficiō {{rependistis}}?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"repens","latin":"repēns (gen. repentis)","headword":"repēns","letter":"r","pos":"adjective","posGroup":"adjective","english":"sudden, unexpected","forms":["repēns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mātrōnae vagae per viās 'quae {{repēns}} clādēs allāta, quaeve fortūna exercitūs esset?' obviōs percontantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"repente","latin":"repente","headword":"repente","letter":"r","pos":"adverb","posGroup":"adverb","english":"suddenly","forms":["repente"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iamque hoc facere noctu apparabant cum matres familiae {{repente}} in publicum procurrerunt flentesque proiectae ad pedes suorum omnibus precibus petierunt ne se et communes liberos hostibus ad supplicium dederent quos ad capiendam fugam naturae et virium infirmitas impediret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"repentinus","latin":"repentīnus, -a, -um","headword":"repentīnus","letter":"r","pos":"adjective","posGroup":"adjective","english":"sudden","forms":["repentīna","repentīnae","repentino","repentinos","repentīnum","repentīnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interea aequum esse ab eis communis salutis causa impetrari ut castra munire instituerent, quo facilius {{repentinos}} hostium impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"repercussus","latin":"repercussus, repercussus","headword":"repercussus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"reverberation; reflection; echo","forms":["repercussum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Axis erat aureus, aureus erat tēmō, aureae rotae, at argenteī radiī: quae metalla ūna cum gemmīs, quibus tōtus currus ōrnābātur, Sōlis lūmen {{repercussum}} in omnēs caelī partēs spargēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"repercutio","latin":"repercutio, repercutere, repercussi, repercussus","headword":"repercutio","letter":"r","pos":"verb","posGroup":"verb","english":"cause to rebound, reflect, strike against","forms":["repercussae"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Ista {{repercussae}}, quam cernis, imāginis umbra est:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"repere","latin":"(rēpō) rēpere, rēpsisse, rēptum","headword":"rēpere","letter":"r","pos":"","posGroup":"other","english":"crawl","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reperio","latin":"reperio, reperire, repperi, repertus","headword":"reperio","letter":"r","pos":"verb","posGroup":"verb","english":"discover, learn; light on; find/obtain/get; find out/to be, get to know; invent","forms":["reperi","reperiās","reperiēbant","reperienda","reperiēs","reperiētur","reperire","reperīrī","reperit","reperītur","reperiunt","reperiuntur","repertam","repertus","repperī","repperit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris {{reperire}} possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reperire","latin":"reperīre","headword":"reperīre","letter":"r","pos":"verb","posGroup":"verb","english":"to find, discover","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reperit","latin":"reperit, -iunt","headword":"reperit","letter":"r","pos":"verb","posGroup":"verb","english":"find; finds","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"repertum","latin":"repertum, reperti","headword":"repertum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"discovery; invention; finding again (L+S)","forms":["reperta","repertī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"magnaque Thrēiciā sacra {{reperta}} Samō?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"repetere","latin":"(repetō) repetere (< petere)","headword":"repetere","letter":"r","pos":"","posGroup":"other","english":"return to, repeat, claim back, recall","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"repetitus","latin":"repetitus, repetita, repetitum","headword":"repetitus","letter":"r","pos":"adjective","posGroup":"adjective","english":"repeated","forms":["repetītae","repetītus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi orsus Albānus: \"Iniūriae et rēs nōn redditae, quae ex foedere {{repetītae}} sunt, causa huius bellī esse dīcuntur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"repeto","latin":"repeto, repetere, repetivi, repetitus","headword":"repeto","letter":"r","pos":"verb","posGroup":"verb","english":"return to; get back; demand back/again; repeat; recall; claim","forms":["repetam","repetāmus","repetēbant","repetēbantur","repetēbat","repetendās","repetēns","repetentēs","repetentibus","repetere","repetet","repetī","repetit","repetītīs","repetītum","repetīverant","repetīvit","repetuntur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum Absalōn adhūc palpitāret haerēns in quercū, armigerī Iōābī {{repetītīs}} ictibus cōnfossum interimērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"repetunda","latin":"repetunda, repetundae","headword":"repetunda","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"recovery (pl.) of extorted money","forms":["repetundārum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Post paulō Catilīna, pecūniārum {{repetundārum}} reus, prohibitus erat cōnsulātum petere, quod intrā lēgitimōs diēs profitērī nequīverat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"repleo","latin":"repleō, -ēre, -plēvī, -plētum","headword":"repleō","letter":"r","pos":"verb","posGroup":"verb","english":"fill up again, refill","forms":["repleam","repleat","replēbat","replēbātur","replētis","replēvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quīdam eōrum, nōmine Eurytus, quī māmaximē ēbrius erat, Hippodamen rapuit; aliī ra puērunt quās poterant; puellārum mātrōnārumque clamōribus tōta domus {{replēbātur}}: “Heus, tū, mōnstrum!” clāmābant, “Abstinē maniīs ā mē!” “Ō virī, auxilium ferte!” Omnēs igitur vīn, cum haec indigna scelera fierī vidērent, statim ē lectīs surrēxērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"repo","latin":"repo, repere, repsi, reptus","headword":"repo","letter":"r","pos":"verb","posGroup":"verb","english":"creep, crawl","forms":["rēpere","rēpor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Admissus ergô ad Caesarem est cum suô mūnere. (Phialam porrēxit) Caesarî, deinde tēcit {{rēpor}}- valdius quam expāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"reponere","latin":"repōnere","headword":"repōnere","letter":"r","pos":"verb","posGroup":"verb","english":"to put back, replace","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"repono","latin":"repōnō, repōnere","headword":"repōnō","letter":"r","pos":"verb","posGroup":"verb","english":"put back","forms":["repōnam","repōnat","repōne","repōnerētur","repōnī","repōnit","repōnō","repōnunt","reposītā","repositō","reposuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iōsēphus iussit frātrum saccōs implērī trīticō, et pecūniam quam attulerant repōnī in ōre saccōrum; addidit īnsuper cibāria in viam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reportare","latin":"(reportō) reportāre","headword":"reportāre","letter":"r","pos":"verb","posGroup":"verb","english":"carry back, bring home; to carry back, win","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"reporto","latin":"reportō (1)","headword":"reportō","letter":"r","pos":"verb","posGroup":"verb","english":"carry back, repeat, report","forms":["reportāre","reportārent","reportāret","reportat","reportāverat","reportāvimus","reportāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nescīmus quōnam cāsū id factum fuerit; sed eamdem pecūniam {{reportāvimus}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"reposco","latin":"reposcō, -ere, repoposcī","headword":"reposcō","letter":"r","pos":"verb","posGroup":"verb","english":"demand back, claim","forms":["reposcō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mittor et Īliacās audāx ōrātor ad arcēs vīsaque et intrāta est altae mihi cūria Trōiae plēnaque adhūc erat illa virīs; interritus ēgī, quam mihi mandārat commūnis Graecia, causam accūsōque Parin praedamque Helenamque reposcō et moveō Prīamum Prīamōque Antēnora iūnctum; at Paris et frātrēs et quī rapuēre sub illō vix tenuēre manūs (scīs hoc, Menelāe) nefandās, prīmaque lūx nostrī tēcum fuit illa perīclī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"repostus","latin":"repostus, reposta, repostum","headword":"repostus","letter":"r","pos":"adjective","posGroup":"adjective","english":"remote, out of the way","forms":["repostum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"exciderant animō: manet altā mente {{repostum}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"reprehendere","latin":"reprehendere","headword":"reprehendere","letter":"r","pos":"verb","posGroup":"verb","english":"to blame, rebuke","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"reprehendit","latin":"reprehendit","headword":"reprehendit","letter":"r","pos":"verb","posGroup":"verb","english":"rebukes, scolds","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reprehendo","latin":"reprehendō, reprehendere","headword":"reprehendō","letter":"r","pos":"verb","posGroup":"verb","english":"blame, censure; blame, rebuke","forms":["reprehendēbat","reprehendendus","reprehendere","reprehenderet","reprehenderis","reprehendet","reprehendiminī","reprehendimur","reprehendit","reprehenditur","reprehendō","reprehendor","reprehenduntur","reprehēnsa","reprehēnsōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Postero die Caesar contione advocata temeritatem cupiditatemque militum {{reprehendit}}, quod sibi ipsi iudicavissent quo procedendum aut quid agendum videretur neque signo recipiendi dato constitissent neque ab tribunis militum legatisque retineri potuissent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reprimere","latin":"(reprimō) reprimere, repressisse, -essum","headword":"reprimere","letter":"r","pos":"","posGroup":"other","english":"check, repress, restrain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reprimo","latin":"reprimo, reprimere, repressi, repressus","headword":"reprimo","letter":"r","pos":"verb","posGroup":"verb","english":"press back, repress; check, prevent, restrain","forms":["represso","reprimendōrum","reprimeret","reprimī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"His rebus comparatis, {{represso}} iam Lucterio et remoto, quod intrare intra praesidia periculosum putabat, in Helvios proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"repto","latin":"repto, reptare, reptavi, reptatus","headword":"repto","letter":"r","pos":"verb","posGroup":"verb","english":"crawl/creep (over); move slowly/lazily/furtively, stroll/saunter, slink, grope","forms":["rēptābis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dominus dīxit serpentī: quia dēcēpistī mulierem, eris odiōsus et exsecrātus inter omnia animantia; {{rēptābis}} super pectus, et comedēs terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"repudiare","latin":"(repudiō) repudiāre","headword":"repudiāre","letter":"r","pos":"","posGroup":"other","english":"reject, refuse to accept","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"repudio","latin":"repudio, repudiare, repudiavi, repudiatus","headword":"repudio","letter":"r","pos":"verb","posGroup":"verb","english":"reject; repudiate; scorn","forms":["repudiābat","repudiātīs","repudiātus","repudiet"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Rōmānōs saepe vīcit, usque ad quīntum mīliārium urbis accessit, oppugnātūrus etiam patriam suam (lēgātīs quī pācem petēbant {{repudiātīs}}), nisi ad eum māter Veturia et uxor Volumnia ex urbe vēnissent, quārum flētū et dēprecātiōne superātus remōvit exercitum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"repugnare","latin":"(repugnō) repugnāre, repugnāvisse","headword":"repugnāre","letter":"r","pos":"","posGroup":"other","english":"fight back (mostly intr.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"repugno","latin":"repugno, repugnare, repugnavi, repugnatus","headword":"repugno","letter":"r","pos":"verb","posGroup":"verb","english":"fight back, oppose; be incompatible with; disagree with","forms":["repugnābat","repugnābis","repugnābō","repugnantes","repugnantī","repugnantibus","repugnāre","repugnās","repugnet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hos continuo in itinere adorti omnibus impedimentis exuunt; {{repugnantes}} diem noctemque obsident; multis utrimque interfectis maiorem multitudinem ad arma concitant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"repulsa","latin":"repulsa, -ae","headword":"repulsa","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"defeat (in an election)","forms":["repulsa","repulsae","repulsam","repulsās","repulsis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Restituto proelio ac {{repulsis}} hostibus eo quo Labienum miserat contendit; cohortes IIII ex proximo castello deducit, equitum partem se sequi, partem circumire exteriores munitiones et ab tergo hostes adoriri iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"repulsus","latin":"repulsus, repulsus","headword":"repulsus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"reverberation; reflection; echo","forms":["repulsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praetereā, sī quid mēque vōbīsque dīgnum petīveris, haud {{repulsus}} abībis.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"repurgo","latin":"repurgō (1)","headword":"repurgō","letter":"r","pos":"verb","posGroup":"verb","english":"to cleanse away, purge","forms":["repurgat"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quicquid in Aenēā fuerat mortāle, {{repurgat}}\net respersit aquīs; pars optima restitit illī,\nlūstrātum genetrīx dīvīnō corpus odōre\nunxit et ambrosiā cum dulcī nectare mixtā\ncontigit ōs fēcitque deum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"reputare","latin":"(reputō) reputāre","headword":"reputāre","letter":"r","pos":"","posGroup":"other","english":"think over, reflect on","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reputo","latin":"reputo, reputare, reputavi, reputatus","headword":"reputo","letter":"r","pos":"verb","posGroup":"verb","english":"think over, reflect","forms":["reputā","reputāns","reputārent","reputāte","reputō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quī sīs, nōn unde nātus sīs, reputā!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"requies","latin":"requiēs, requiētis","headword":"requiēs","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rest","forms":["requiem","requiēte"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Requiem}} in mīlle casīs rogābant, sed mīlle casae erant clausae.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"requiescere","latin":"(requiēscō) requiēscere","headword":"requiēscere","letter":"r","pos":"verb","posGroup":"verb","english":"rest; to rest","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"requiesco","latin":"requiesco, requiescere, requievi, requietus","headword":"requiesco","letter":"r","pos":"verb","posGroup":"verb","english":"quiet down; rest; end","forms":["requiēscam","requiēscere","requiēscit","requiēvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn ante {{requiēscam}} quam mea uxor fuerīs, Galatēa.” Hīs verbīs Galatēae persuadēre cōnābātur nē sē timēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"requirere","latin":"(requīrō) requīrere, requīsīvisse, requīsitum","headword":"requīrere","letter":"r","pos":"","posGroup":"other","english":"seek, ask","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"requiro","latin":"requiro, requirere, requisivi, requisitus","headword":"requiro","letter":"r","pos":"verb","posGroup":"verb","english":"require, seek, ask for; need; miss, pine for","forms":["requīrat","requīrendī","requīrentēs","requīrere","Requīrētur","requīrī","requiris","requirunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Magno dolore Aedui ferunt se deiectos principatu, queruntur fortunae commutationem et Caesaris indulgentiam in se {{requirunt}}; neque tamen suscepto bello suum consilium ab reliquis separare audent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"reri","latin":"(reor) rērī, ratum","headword":"rērī","letter":"r","pos":"","posGroup":"other","english":"reckon, think, believe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"res","latin":"rēs, reī","headword":"rēs","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"(f.) thing, matter, affair; thing, matter; thing, object; (pl.) situation","forms":["re","rebus","rei","rem","rerum","res","ri"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eae {{res}} in Galliam Transalpinam celeriter perferuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resaluto","latin":"resaluto, resalutare, resalutavi, resalutatus","headword":"resaluto","letter":"r","pos":"verb","posGroup":"verb","english":"greet back; greet in return","forms":["resalūtāre","resalūtāvit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et quam benignus {{resalūtāre}}, nômina omnium reddere, tam- quam ūnus dē nôbîs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"rescindere","latin":"(rescindō) rescindere (< scindere)","headword":"rescindere","letter":"r","pos":"","posGroup":"other","english":"demolish, cancel, annul","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"rescindo","latin":"rescindo, rescindere, rescidi, rescissus","headword":"rescindo","letter":"r","pos":"verb","posGroup":"verb","english":"cut out; cut down, destroy; annul; rescind","forms":["resciderant","rescindendos","rescinderent","rescindi","rescindunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Itaque, ne id accideret, silvestri loco castris positis e regione unius eorum pontium quos Vercingetorix {{rescindendos}} curaverat, postero die cum duabus legionibus in occulto restitit; reliquas copias cum omnibus impedimentis, ut consueverat, misit, apertis quibusdam cohortibus, uti numerus legionum constare videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rescisco","latin":"rescisco, resciscere, rescivi, rescitus","headword":"rescisco","letter":"r","pos":"verb","posGroup":"verb","english":"learn, find out, ascertain; bring to light","forms":["rescīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Mulier virō persuāsit, ut sibi indicāret causam tantae virtūtis; et ubi {{rescīvit}} vīrēs eius in capillīs sitās esse, caput dormientīs tōtondit, atque ita Philistaeīs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rescribo","latin":"rescribo, rescribere, rescripsi, rescriptus","headword":"rescribo","letter":"r","pos":"verb","posGroup":"verb","english":"write back in reply","forms":["rescrībe","rescrībere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Lēgerit et nōlit {{rescrībere}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"resecare","latin":"resecāre","headword":"resecāre","letter":"r","pos":"verb","posGroup":"verb","english":"to cut off","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"reseco","latin":"reseco, resecare, resecui, resectus","headword":"reseco","letter":"r","pos":"verb","posGroup":"verb","english":"cut back, trim; reap, cut short","forms":["resecābat","resectā"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Posteā Mīdās aurēs purpureīs tiārīs pudōre celāre cōnābātur, sed servus, quī capillōs longōs {{resecābat}}, aurēs vīderat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"reservo","latin":"reservo, reservare, reservavi, reservatus","headword":"reservo","letter":"r","pos":"verb","posGroup":"verb","english":"reserve; spare; hold on to","forms":["reservārētur","Reservatis","reservō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Reservatis}} Aeduis atque Arvernis, si per eos civitates reciperare posset, ex reliquis captivis toto exercitui capita singula praedae nomine distribuit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resideo","latin":"resideo, residere, resedi, resessus","headword":"resideo","letter":"r","pos":"verb","posGroup":"verb","english":"sit down/on/in; settle; be perched; remain seated/idle/fixed/in place; squat","forms":["resēderat","resedisse","resēdit","residēbit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nihilo minus clandestinis nuntiis legationibusque Allobrogas sollicitat, quorum mentes nondum ab superiore bello {{resedisse}} sperabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"residere","latin":"(resīdō) resīdere, -sēdisse","headword":"resīdere","letter":"r","pos":"","posGroup":"other","english":"sink back, subside","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"resido","latin":"resido, residere, residi, -","headword":"resido","letter":"r","pos":"verb","posGroup":"verb","english":"sit down; settle; abate; subside, quieten down","forms":["resīdant","residēns","residere","residēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum his mihi res sit qui eruptionem probant; quorum in consilio omnium vestrum consensu pristinae {{residere}} virtutis memoria videtur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resigno","latin":"resigno, resignare, resignavi, resignatus","headword":"resigno","letter":"r","pos":"verb","posGroup":"verb","english":"unseal; open; resign","forms":["resignat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"dat somnōs adimitque, et lūmina morte {{resignat}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"resistere","latin":"(resistō) resistere, restitisse ({i}intr. + dat.{/i})","headword":"resistere","letter":"r","pos":"verb","posGroup":"verb","english":"resist; to resist (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"resisto","latin":"resisto, resistere, restiti, -","headword":"resisto","letter":"r","pos":"verb","posGroup":"verb","english":"pause; continue; resist, oppose; reply; withstand, stand (DAT); make a stand","forms":["resistat","resistebant","resistēns","resistente","resistentēs","resistere","resisterent","resistī","resistit","resistunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tamen, quod instituto Caesaris semper duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus {{resisterent}}, alii turres reducerent aggeremque interscinderent, omnis vero ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resolvo","latin":"resolvo, resolvere, resolvi, resolutus","headword":"resolvo","letter":"r","pos":"verb","posGroup":"verb","english":"loosen, release, disperse, melt; relax; pay; enervate, pay back; break up","forms":["resolve","resolvit","resolvō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tempore nec nexās saepe {{resolve}} comās!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"resonare","latin":"(resonō) resonāre","headword":"resonāre","letter":"r","pos":"","posGroup":"other","english":"resound","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"resono","latin":"resono, resonare, resonavi, resonatus","headword":"resono","letter":"r","pos":"verb","posGroup":"verb","english":"resound","forms":["resonābit","resonant","resonantia","resonat","resonāvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Clāmāre libēbat: “Actaeōn ego sum: dominum cognōscite vestrum!” Verba animō dēsunt; {{resonat}} lātrātibus aether.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"respecto","latin":"respecto, respectare, respectavi, respectatus","headword":"respecto","letter":"r","pos":"verb","posGroup":"verb","english":"keep on looking round or back; await; have regard for","forms":["respectant"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dī tibi, sī qua piōs {{respectant}} nūmina, sī quid","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"respergere","latin":"(respergō) respergere,","headword":"respergere","letter":"r","pos":"","posGroup":"other","english":"sprinkle, splatter respersisse, respersum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"respergo","latin":"respergō, -ere, -sī, -sum","headword":"respergō","letter":"r","pos":"verb","posGroup":"verb","english":"to sprinkle, wash over","forms":["respergerent","respersit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quicquid in Aenēā fuerat mortāle, repurgat\net {{respersit}} aquīs; pars optima restitit illī,\nlūstrātum genetrīx dīvīnō corpus odōre\nunxit et ambrosiā cum dulcī nectare mixtā\ncontigit ōs fēcitque deum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"respicere","latin":"(respiciō) respicere, -exisse,","headword":"respicere","letter":"r","pos":"","posGroup":"other","english":"look back (at), heed, regard, have","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"respicio","latin":"respicīō, -ere, respexī, respectum","headword":"respicīō","letter":"r","pos":"verb","posGroup":"verb","english":"look back, look behind","forms":["respexit","respice","respicere","respiciamus","respiciās","respiciēns","respiciet","respiciō","respicit","respicite","respiciunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Atque ego hanc sententiam probarem (tantum apud me dignitas potest), si nullam praeterquam vitae nostrae iacturam fieri viderem; sed in consilio capiendo omnem Galliam {{respiciamus}}, quam ad nostrum auxilium concitavimus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"respondeo","latin":"respondeō","headword":"respondeō","letter":"r","pos":"verb","posGroup":"verb","english":"answer, reply; reply, respond, answer","forms":["respondē","Respondeam","respondeat","respondēbam","respondēbat","respondēbis","respondēbitis","respondēbō","respondēmus","respondēns","respondent","respondentem","Respondentēs","respondeō","respondēre","respondēret","respondērunt","respondēs","respondet","respondētis","respondētur","respondī","Respondimus","respondissent","respondisset","respondistī","respondit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aemilia {{respondet}}: “Tē.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"respondet","latin":"respondet","headword":"respondet","letter":"r","pos":"verb","posGroup":"verb","english":"answer; answers, replies","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"responso","latin":"responso, responsare, responsavi, responsatus","headword":"responso","letter":"r","pos":"verb","posGroup":"verb","english":"answer, reply (to); reecho","forms":["respōnsō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"“Epistulam” inquit “dominō trādidī; ille mē dīmīsit sine respōnsō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"responsum","latin":"respōnsum, -ī","headword":"respōnsum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"answer","forms":["respōnsa","respōnsum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus: “Alterum {{respōnsum}} est rēctum — alterum nōn rēctum!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"respuo","latin":"respuo, respuere, respui, -","headword":"respuo","letter":"r","pos":"verb","posGroup":"verb","english":"reject, spit, spew out; turn away, repel; reject, destain, spurn, refuse","forms":["respuātur","respuēbat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"At vir fortissimus cibum vetitum {{respuēbat}} indignāns; quam ob rem cum ad supplicium dūcerētur, suī eum amicī hortābantur, ut aliam camem, quam attulerant, comedendō, simulāret sē regī pāruisse, sīcque mortem vltāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"restare","latin":"(restō) restāre","headword":"restāre","letter":"r","pos":"","posGroup":"other","english":"remain, be left","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"restat","latin":"restat, restare, -, restatus est","headword":"restat","letter":"r","pos":"verb","posGroup":"verb","english":"it remains to; it remains standing","forms":["restat"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nunc genus mortāle in nōbīs duōbus solīs {{restat}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"restinguere","latin":"(restinguō) restinguere, -xisse, put -ctum","headword":"restinguere","letter":"r","pos":"verb","posGroup":"verb","english":"out, extinguish; to extinguish, quench","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"restinguo","latin":"restinguo, restinguere, restinxi, restinctus","headword":"restinguo","letter":"r","pos":"verb","posGroup":"verb","english":"extinguish, quench, put out; exterminate, destroy; assuage, allay, mitigate","forms":["restincto","restīnctus","restinguendum","restinguere","restīnximus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tamen, quod instituto Caesaris semper duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque interscinderent, omnis vero ex castris multitudo ad {{restinguendum}} concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"restis","latin":"restis, -is ( f.)","headword":"restis","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rope; rope, cord","forms":["reste"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Īnfēlīcī arborī {{reste}} suspenditō!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"restituere","latin":"(restituō) restituere, -tuisse, -tutum","headword":"restituere","letter":"r","pos":"","posGroup":"other","english":"rebuild, restore, reinstate; restore, rebuild, reinstate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"restituo","latin":"restituo, restituere, restitui, restitutus","headword":"restituo","letter":"r","pos":"verb","posGroup":"verb","english":"restore; revive; bring back; make good","forms":["restituendae","restituendam","restituendī","restituendō","restituendus","restituere","restituērunt","restituet","restituī","restituit","restitūtam","Restituto","RESTITVIT"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Restituto}} proelio ac repulsis hostibus eo quo Labienum miserat contendit; cohortes IIII ex proximo castello deducit, equitum partem se sequi, partem circumire exteriores munitiones et ab tergo hostes adoriri iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resto","latin":"restō, -āre, -stitī","headword":"restō","letter":"r","pos":"verb","posGroup":"verb","english":"to remain, survive","forms":["restābant","restābat","restant","restantia","restet","Restitēre","restitērunt","restitissent","restitit","restō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Itaque, ne id accideret, silvestri loco castris positis e regione unius eorum pontium quos Vercingetorix rescindendos curaverat, postero die cum duabus legionibus in occulto {{restitit}}; reliquas copias cum omnibus impedimentis, ut consueverat, misit, apertis quibusdam cohortibus, uti numerus legionum constare videretur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"resumo","latin":"resumo, resumere, resumpsi, resumptus","headword":"resumo","letter":"r","pos":"verb","posGroup":"verb","english":"pick up again; resume; recover","forms":["Resūmpsī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Resūmpsī.” [Iūlius, ad servum:] “Porrige strigilem!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"resupinus","latin":"resupinus, resupina, resupinum","headword":"resupinus","letter":"r","pos":"adjective","posGroup":"adjective","english":"lying on one's back","forms":["resupīnō","resupīnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cupit ipse tenērī: nam quotiēs liquidīs porrēximus ōscula lymphīs, hīc totiēs ad mē resupīnō nītitur ōre.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"resurgere","latin":"(resurgō) resurgere (< surgere)","headword":"resurgere","letter":"r","pos":"","posGroup":"other","english":"rise again, be restored","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"resurgo","latin":"resurgo, resurgere, resurrexi, resurrectus","headword":"resurgo","letter":"r","pos":"verb","posGroup":"verb","english":"rise/appear again; rare up again, lift oneself, be restored/rebuilt, revive","forms":["resurgēns","resurgere","resurget"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Et postquam flagellāverint eum, occīdent eum; at tertī ā diē {{resurget}}.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"retardare","latin":"(retardō) retardāre","headword":"retardāre","letter":"r","pos":"","posGroup":"other","english":"delay, hold up","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"retardo","latin":"retardo, retardare, retardavi, retardatus","headword":"retardo","letter":"r","pos":"verb","posGroup":"verb","english":"delay, hold up","forms":["retardāret","retardāvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Prīmum ex suō rēgnō sīc Mithridātēs profūgit ex eōdem Pontō, quō Medēa illa quondam profūgisse dīcitur, quam praedicant in fugā frātris suī membra in iīs locīs quā sē parēns persequerētur dissipāvisse, ut eōrum collēctiō dispersa maerorque paternus celeritātem persequendī {{retardāret}}!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rete","latin":"rēte, rētis","headword":"rēte","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"(n.) net","forms":["rēte","rētī","rētia","retibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ut cessāvit loquī, dīxit Simonī:\"Due in altum, et laxātē {{rētia}}.\"Respondit Simōn:\"Praeceptor, tōtam noctem labōrāvimus, sed nihil cēpimus; tamen, sīcut dixisfī, laxābō rēte.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"retego","latin":"retēgō, -ere, retēxī, retēctum","headword":"retēgō","letter":"r","pos":"verb","posGroup":"verb","english":"uncover, lay bare","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"retexo","latin":"retexō, -ere, -textum","headword":"retexō","letter":"r","pos":"verb","posGroup":"verb","english":"reweave, unravel","forms":["retēxī","retēxit","retexite"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōrō, {{retexite}} fāta Eurydicēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"reticeo","latin":"reticeo, reticere, reticui, -","headword":"reticeo","letter":"r","pos":"verb","posGroup":"verb","english":"keep silent; give no reply; refrain from speaking/mentioning; leave unsaid","forms":["reticēbō","reticēre","reticet"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Vērum, utut es factūrus, hoc quidem hercle haud reticēbō tamen,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"reticere","latin":"(reticeō) reticēre, -uisse","headword":"reticēre","letter":"r","pos":"","posGroup":"other","english":"keep silent","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reticulum","latin":"reticulum, reticuli","headword":"reticulum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"small (fish) net; small mesh bag; hair net; type of undergarment; network","forms":["rēticulum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ultimô etiam periscelidês resolvit et {{rēticulum}} aureum quem ‘ex obrussā’ esse dîcëbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"retinaculum","latin":"retinaculum, retinaculi","headword":"retinaculum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"rope; hawser; rein; towing-rope","forms":["retinācula"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fulmineum strictōque ferit {{retinācula}} ferrō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"retinens","latin":"retinens, retinentis (gen.), retinentior -or -us, retinentissimus -a -um","headword":"retinens","letter":"r","pos":"adjective","posGroup":"adjective","english":"tenacious; observant","forms":["retinēns"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Catilīna vērō longē ā suīs inter hostium cadāvera repertus est, paululum etiam spīrāns ferōciamque animī quam habuerat vīvus in vultū {{retinēns}}.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"retineo","latin":"retineō, -ēre, -uī, -tentum","headword":"retineō","letter":"r","pos":"verb","posGroup":"verb","english":"keep, hold back, restrain","forms":["retentās","retentis","retentus","retinē","retinēbant","retinebantur","retinēbat","retinēmus","retinendae","retinendos","retinendum","retinendus","retinent","retinēre","retinerent","retinēret","retineri","retinet","retinētur","retīnuerat","retinuērunt","retinuissent","retinuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, {{retineri}} urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"retinere","latin":"(retineō) retinēre, retinuisse, retentum","headword":"retinēre","letter":"r","pos":"","posGroup":"other","english":"hold on to","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"retractus","latin":"retractus, retracta, retractum","headword":"retractus","letter":"r","pos":"adjective","posGroup":"adjective","english":"remote","forms":["retractus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Crassō, Caepārius — nam is paulō ante ex fugā {{retractus}} erat — Cn.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"retrahere","latin":"(retrahō) retrahere, retrāxisse, retractum","headword":"retrahere","letter":"r","pos":"verb","posGroup":"verb","english":"draw back, withdraw; to drag back","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"retraho","latin":"retraho, retrahere, retraxi, retractus","headword":"retraho","letter":"r","pos":"verb","posGroup":"verb","english":"draw back, withdraw; make known again, divert; bring back","forms":["retractum","retrahēbat","retraheret","retrahit","retrāxerīs","retrāxerit","retrāxī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"“Heu, quid faciam?” sē ipsa interrogābat, “parēamne Iovī an vās aperiam?” Fēmina, quae animō valdē perturbāta erat, nesciēbat quid faceret: saepe tam cupida erat īnspiciendī quid in illō vāse inesset, ut manum extenderet ad aperiendum; sed continuō manum {{retrahēbat}}, ut īram Iovis vītāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"retro","latin":"retrō","headword":"retrō","letter":"r","pos":"adverb","posGroup":"adverb","english":"back","forms":["retrō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ecce: crūdēlis fortūna mē iterum retrō vocat; mortis somnus oculōs rūrsus operit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"retundo","latin":"retundo, retundere, rettudi, retunsus","headword":"retundo","letter":"r","pos":"verb","posGroup":"verb","english":"blunt; weaken; repress, quell","forms":["rettudimus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam tōtī urbī, templīs, dēlūbrīs, tēctīs ac moenibus subiectōs prope iam ignēs circumdatōsque restīnximus, iīdemque gladiōs in rem pūblicam dēstrictōs {{rettudimus}} mucrōnēsque eōrum ā iugulīs vestrīs dēiēcimus!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"reus","latin":"reus, -ī","headword":"reus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"defendant, accused; accused man, defendant","forms":["Reae","reīs","reōs","reum","reus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"460 nōn tantum trepidōs ut tueàre {{reōs}};","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"revehere","latin":"(revehō) revehere (< vehere)","headword":"revehere","letter":"r","pos":"","posGroup":"other","english":"bring back","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reveho","latin":"reveho, revehere, revexi, revectus","headword":"reveho","letter":"r","pos":"verb","posGroup":"verb","english":"carry/bring back; ride/sail back (PASS)","forms":["revecta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Bellum prīmum cum Latīnīs gessit et oppidum ibi Apiolās vī cēpit; praedaque inde maiōre quam spērāverat {{revecta}}, lūdōs opulentius quam priōrēs rēgēs fēcit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"revello","latin":"revello, revellere, revelli, revulsus","headword":"revello","letter":"r","pos":"verb","posGroup":"verb","english":"tear/pull away/loose/out/from/down/up; wrench off; remove (person)","forms":["revelli","revulsum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Huc illi stipites demissi et ab infimo revincti, ne {{revelli}} possent, ab ramis eminebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"revenio","latin":"reveniō, -īre, -vēnī, -ventum","headword":"reveniō","letter":"r","pos":"verb","posGroup":"verb","english":"come back, return","forms":["revēnerat","revēnērunt","reveniat","revenīre","revenīs","revenit","revēniunt","reventum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum {{revenit}} ex oppidō, līberīs suīs multa dōna dat.” dōnum -ī","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"revenit","latin":"revenit, revenīre","headword":"revenit","letter":"r","pos":"verb","posGroup":"verb","english":"come back; comes back, returns","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"reverti","latin":"revertī","headword":"revertī","letter":"r","pos":"verb","posGroup":"verb","english":"return; to return","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"revertitur","latin":"revertitur","headword":"revertitur","letter":"r","pos":"verb","posGroup":"verb","english":"returns, comes back; returns, turns back","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"reverto","latin":"reverto, revertere, reverti, -","headword":"reverto","letter":"r","pos":"verb","posGroup":"verb","english":"turn back, go back, return; recur (usually DEP)","forms":["reverterunt","revertisse","revertit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos {{revertisse}}, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"revertor","latin":"revertor, revertī","headword":"revertor","letter":"r","pos":"verb","posGroup":"verb","english":"turn back","forms":["reversā","reversae","reversī","reversūrum","reversus","revertantur","revertar","revertendī","Revertēns","revertentur","revertere","reverterentur","reverterētur","reverterīs","reverti","revertiminī","revertitur","revertor","revertuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum {{revertuntur}} legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"revincere","latin":"(revincō) revincere (< vincere)","headword":"revincere","letter":"r","pos":"","posGroup":"other","english":"conquer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"revincio","latin":"revincio, revincire, revinxi, revinctus","headword":"revincio","letter":"r","pos":"verb","posGroup":"verb","english":"bind fast, fasten","forms":["revinciuntur","revincta","revincti","revīnctum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hae {{revinciuntur}} introrsus et multo aggere vestiuntur; ea autem quae diximus intervalla grandibus in fronte saxis effarciuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"revinco","latin":"revinco, revincere, revici, revictus","headword":"revinco","letter":"r","pos":"verb","posGroup":"verb","english":"conquer, crush, disprove","forms":["revicta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caeciliō victus captusque est, et {{revicta}} Macedonia.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"reviresco","latin":"reviresco, revirescere, revirui, -","headword":"reviresco","letter":"r","pos":"verb","posGroup":"verb","english":"grow green again; grow strong or young again","forms":["revirēscere"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Parvō tempore Medea amīcitiā falsā fīliās cēpit, dumque fābulam dē iuventūte Aesōnis receptā nārrat, eīs spem dat parentem suum arte magicā {{revirēscere}} posse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"revisere","latin":"(revīsō) revīsere (< vīsere)","headword":"revīsere","letter":"r","pos":"","posGroup":"other","english":"revisit, visit","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"reviso","latin":"reviso, revisere, -, -","headword":"reviso","letter":"r","pos":"verb","posGroup":"verb","english":"revisit, go back and see","forms":["revīsam","revīsit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sinite instaurāta {{revīsam}} proelia!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"revivo","latin":"revivo, revivere, revixi, revictus","headword":"revivo","letter":"r","pos":"verb","posGroup":"verb","english":"live again","forms":["revīxit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quia hic fīlius meus mortuus erat, et {{revīxit}}, perierat, et inventus est.” Et coepērunt epulārī.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"revocare","latin":"(revocō) revocāre, revocāvisse, revocātum","headword":"revocāre","letter":"r","pos":"","posGroup":"other","english":"call back","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"revoco","latin":"revoco, revocare, revocavi, revocatus","headword":"revoco","letter":"r","pos":"verb","posGroup":"verb","english":"call back, recall; revive; regain","forms":["revocā","revocandōs","revocant","revocantēs","revocāre","revocārent","revocāret","revocārī","revocat","revocātē","revocātīs","revocatur","revocātus","revocāvērunt","revocavit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter effecto opere legionibusque traductis et loco castris idoneo delecto, reliquas copias {{revocavit}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"revolvo","latin":"revolvo, revolvere, revolvi, revolutus","headword":"revolvo","letter":"r","pos":"verb","posGroup":"verb","english":"throw back, roll back","forms":["revolūtum","revolvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Et invēnērunt lapidem {{revolūtum}} ā monumentō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rex","latin":"rēx, rēgis","headword":"rēx","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"(m.) king","forms":["rēge","rēgem","rēgēs","rēgī","rēgibus","rēgis","rēgum","rex"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Rex}} ab. suis appellatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rhenus","latin":"Rhenus, Rheni","headword":"Rhenus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Rhine; (river dividing Gaul and Germany - in Caesar's Gallic War)","forms":["Rhenum","Rhēnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caesar, quod hostes equitatu superiores esse intellegebat et interclusis omnibus itineribus nulla re ex provincia atque Italia sublevari poterat, trans {{Rhenum}} in Germaniam mittit ad eas civitates quas superioribus annis pacaverat equitesque ab his arcessit et levis armaturae pedites, qui inter eos proeliari consuerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rhetor","latin":"rhētor, -oris (m.)","headword":"rhētor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"teacher of rhetoric","forms":["rhētorem","rhētoribus","rhētorum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"[EX PETRŌNIĪ SĀ TYRICON LIBRŌ XV] [In parte librîpraecêdentî, quae periit, haecferë nārrāta Encolgius et Asczltos, amïcî adulêscentulî, quî ūnä cum ī puerô iter in Italiäfaciêbant, in quādam cō- lôniä Campāniae {{rhētorem}} Agamemnonem convênerant, quôcum ad ‘lîberam cēnam’ vocätî erant apud T rimal- chiônem lîbertînum dîvitissimum atque lautissimum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"rhetoricus","latin":"rhetoricus, rhetorica, rhetoricum","headword":"rhetoricus","letter":"r","pos":"adjective","posGroup":"adjective","english":"of rhetoric, rhetorical","forms":["rhētorica"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praeter ōrātiōnēs multās et epistulās ad familiārēs suōs ēdidit opera {{rhētorica}}, ut trēs librōs ‘Dē ōrātōre’, et philosophica, ut ‘Tūsculānās disputātiōnēs’, quae annō XLV a.C. cōnscrīptae sunt.]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"rhodanus","latin":"Rhodanus, Rhodani","headword":"Rhodanus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Rhone; (river in SW Gaul - in Caesar's Gallic War)","forms":["Rhodanum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Allobroges crebris ad {{Rhodanum}} dispositis praesidiis magna cum cura et diligentia suos fines tuentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rictus","latin":"rīctus, -ūs","headword":"rīctus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"jaw, open mouth","forms":["rīctūs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Dīxit Achaemenidēs: \"iterum Polyphēmon et illōs\nadspiciam fluidōs hūmānō sanguine {{rīctūs}},\nhāc mihi sī cārior domus est Īthacāque carīna,\nsī minus Aenēān veneror genitōre, nec umquam\nesse satis poterō, nōn sī dederō omnia, grātus.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"rideo","latin":"rideo, ridere, risi, risus","headword":"rideo","letter":"r","pos":"verb","posGroup":"verb","english":"laugh at (with dat.), laugh; ridicule","forms":["rīdē","Rīdēbis","rīdēmus","rīdendō","rīdēns","rīdent","rīdentem","rīdentēs","rīdentī","ridentibus","Rīdeō","rīdēre","rīdēs","rīdet","rīdētis","rīserit","rīsī","rīsisse","rīsit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Lalla, lalla, lalla!” Dēlia {{rīdet}} et cantat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ridet","latin":"rīdet","headword":"rīdet","letter":"r","pos":"verb","posGroup":"verb","english":"laugh, make fun of; laughs, smiles","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"ridiculum","latin":"ridiculum, ridiculi","headword":"ridiculum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"joke, piece of humor; [per ridiculum => jockingly, for fun]","forms":["rīdiculum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Rīdēbis certē, mea soror, nec sine causā, nam {{rīdiculum}} est tālēs rēs optāre, nec lacrimās effundere mīlitem cuius officium est sanguinem effundere prō patriā.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ridiculus","latin":"rīdiculus, -a, -um","headword":"rīdiculus","letter":"r","pos":"adjective","posGroup":"adjective","english":"laughable, funny; ridiculous","forms":["rīdiculī","rīdiculus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Rīdiculī mihi puerō vidēbantur iī versūs, cum nōndum caedem vīdissem.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rigare","latin":"(rigō) rigāre, rigāvisse, rigātum","headword":"rigāre","letter":"r","pos":"","posGroup":"other","english":"water","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"rigat","latin":"rigat","headword":"rigat","letter":"r","pos":"verb","posGroup":"verb","english":"waters, irrigates","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"rigens","latin":"rigens, (gen.), rigentis","headword":"rigens","letter":"r","pos":"adjective","posGroup":"adjective","english":"stiff; rigid; frozen","forms":["rigentem","rigentēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Statim Aenēās manūs frīgore {{rigentēs}} ad caelum tendēns exclāmat: 'Ō virī beātī, quibus in patriā sub altīs Trōiae moenibus licuit occidere!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rigere","latin":"(rigeō) rigēre","headword":"rigēre","letter":"r","pos":"","posGroup":"other","english":"be stiff","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"rigidus","latin":"rigidus, rigida, rigidum","headword":"rigidus","letter":"r","pos":"adjective","posGroup":"adjective","english":"stiff, hard; stern; rough","forms":["rigida","rigidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et iam membra in viridem colōrem vertī atque capillī, quibus candida frōns operiēbātur, horrēre coepērunt: Cyparissus tunc arbor factus est alta et {{rigida}}, cuius pars summa caelum stēllīs ōrnātum spectāre vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rigo","latin":"rigo, rigare, rigavi, rigatus","headword":"rigo","letter":"r","pos":"verb","posGroup":"verb","english":"moisten, wet, water, irrigate","forms":["rigābat","rigante","rigāre","rigārī","rigat","rigātur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nec umquam arborēs sitim patī sinēbat, sed saepe terram aquā flūminum {{rigābat}}, nē sicca fieret: hic amor, hoc studium, Veneris quoque nūlla cupīdō est;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rima","latin":"rima, rimae","headword":"rima","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"crack, narrow cleft; (sometimes rude); chink, fissure; [ignea ~ => lightening]","forms":["rīma","rīmam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mūsae ex altō Olympō eum ōrantem audīvērunt, et apēs ad arcam mīsērunt, quae, in cubiculum per parvam {{rīmam}} ingressae, in arcam intrāvērunt et Comātam meile aluērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ringor","latin":"ringor, ringi, -","headword":"ringor","letter":"r","pos":"verb","posGroup":"verb","english":"snarl, show the teeth; be angry","forms":["ringentem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Suädeô bonum tuum cōn- coquās, milva, et mē nôn faciās {{ringentem}}, amasiuncula!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ripa","latin":"rīpa, -ae","headword":"rīpa","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"riverbank; bank; bank of a river; bank, shore","forms":["rīpā","rīpae","rīpam","ripas","rīpīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Noviodunum erat oppidum Aeduorum ad {{ripas}} Ligeris opportuno loco positum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"risus","latin":"rīsus, -ūs","headword":"rīsus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"(m.) laughter, laugh; laughter","forms":["rīsū","risum","rīsūs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ego ridere malo, neque iste poeta {{risum}} excitat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rite","latin":"rite","headword":"rite","letter":"r","pos":"adverb","posGroup":"adverb","english":"duly, according to religious usage, with due observance; solemnly; well","forms":["rīte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Rēbus dīvīnīs {{rīte}} factīs vocātāque ad concilium multitūdine, quae coalēscere in ūnum populum nōn poterat nisi lēgibus, Rōmulus iūra dedit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ritus","latin":"rītus, -ūs","headword":"rītus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"rite, ceremony; rite, religious custom","forms":["rītū","rītūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mulierēs exterae, quās adamāvit, eum iam senem ad {{rītūs}} gentīlēs pertraxērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rivalis","latin":"rivalis, rivalis","headword":"rivalis","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"rival; (esp. in love); one who shares use of a stream/mistress; neighbor (L+S)","forms":["rīvālem","rīvālī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Rīvālem}} patienter habē:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rivus","latin":"rīvus, -ī","headword":"rīvus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"brook; stream, brook","forms":["rīvīs","rīvō","rīvum","rīvus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mēdus, quī mīlitem vīvere gaudet, ex parvō rīvō aquam arcessit et mīlitī dat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"rixa","latin":"rīxa, -ae","headword":"rīxa","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"quarrel, brawl","forms":["rixa","rixae","rixam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{rixa}} -ae f — iūrgium violentum,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rixor","latin":"rixor, rixari, rixatus sum","headword":"rixor","letter":"r","pos":"verb","posGroup":"verb","english":"quarrel violently, brawl, dispute","forms":["rixantēs"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Trēs interim iâtraliptae in cônspectü eius Falemum pôtäbant, et cum plūrimum {{rixantēs}} effunderent, Trimal- chiô ‘hoc suum propîn esse’ dīcēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"robur","latin":"rōbur, -oris (n.)","headword":"rōbur","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"oak, strength, force; strength, oak; hard wood, oak","forms":["rōbora","rōbore","rōboris","rōbur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit comam, nec vīnum, nec sīcēram bibit; incrēdibilī fuit corporis {{rōbore}}: obvium leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"robustus","latin":"rōbustus, -a, -um","headword":"rōbustus","letter":"r","pos":"adjective","posGroup":"adjective","english":"strong, robust; strong, sturdy","forms":["rōbustam","rōbustiōribus","rōbustissimō","rōbustum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Nōn poteris” inquit “adulēscentulus cum virō rōbustissimō pugnāre.” Respondit Dāvīd: “Nē timeās, ō rēx: cum pāscerem ovēs patris meī, leō invāsit gregem, ovemque corripuit: ego illum persecūtus occīdī, et ovem ē faucibus illīus ēripuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rogare","latin":"(rogō) rogāre, rogāvisse, rogātum","headword":"rogāre","letter":"r","pos":"","posGroup":"other","english":"ask","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"rogatio","latin":"rogātiō, -ōnis ( f.)","headword":"rogātiō","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"proposed law, bill; bill, proposed law","forms":["rogātiōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Carbō tribūnus plēbis {{rogātiōnem}} tulisset 'ut eundem tribūnum plēbis quotiēns vellet creāre licēret', rogātiōnem eius P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rogitare","latin":"(rogitō) rogitāre, rogitāvisse, rogitātum","headword":"rogitāre","letter":"r","pos":"","posGroup":"other","english":"keep asking","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"rogito","latin":"rogito, rogitare, rogitavi, rogitatus","headword":"rogito","letter":"r","pos":"verb","posGroup":"verb","english":"ask, inquire","forms":["rogitāns","rogitantibus","rogitāre","rogitās","rogitat"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tabellārius: \"Multa simul {{rogitās}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rogo","latin":"rogō, -āre, -āvī, -ātum","headword":"rogō","letter":"r","pos":"verb","posGroup":"verb","english":"ask; ask, beg for","forms":["rogā","rogābant","rogābat","rogābit","rogābō","rogāmus","roganda","rogant","rogante","rogantēs","rogantī","rogantis","rogāre","rogārent","rogārēs","rogāret","rogās","rogat","rogāta","rogātae","Rogāte","rogati","rogātō","rogatum","rogātus","rogāverīs","rogāverō","rogāvērunt","rogāvī","rogāvit","rogem","rogēmus","roger","rogēs","roget","rogētur","rogō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, legatos mittunt subsidium {{rogatum}}, quo facilius hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rogus","latin":"rogus, -ī","headword":"rogus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"funeral pyre","forms":["rogōs","rogum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Lūxērunt omnēs nymphae; lūgentibus adsonuit Ēchō; sed cum iam {{rogum}} parāvissent, in quō corpus pōnerent,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"roma","latin":"Rōma, -ae","headword":"Rōma","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"Rome","forms":["Rōmā","Romae","Rōmam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His litteris cognitis {{Romae}} dierum viginti supplicatio redditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"romanus","latin":"Rōmānus, -a, -um","headword":"Rōmānus","letter":"r","pos":"adjective","posGroup":"adjective","english":"Roman, of Rome; Roman","forms":["Rōmāna","Rōmānae","Rōmānam","Rōmānārum","Rōmānās","Rōmāne","Romani","Romanis","Rōmānō","Romanorum","Romanos","Romanum","Rōmānus","ROMANVM","RŌMĀNVS"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi {{Romani}} imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"romulus","latin":"Romulus, Romuli","headword":"Romulus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Romulus (legendary founder of Rome)","forms":["Rōmule","Rōmulī","Rōmulō","Rōmulum","Rōmulus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"An tabulam dē Rōmulō, quī prīma moenia Rōmāna aedificāvit...?'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ros","latin":"ros, roris","headword":"ros","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"dew; light rain; spray/splash water; [ros marinus/maris => rosemary]","forms":["rōris","ros"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"NŌs etiam vé{{ros}} parcē profitēmur amōrēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rosa","latin":"rosa, -ae","headword":"rosa","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rose","forms":["rosa","rosae","rosam","rosārum","rosās","rosīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Forum plēnum est virōrum et fēminārum quī emunt aut vēndunt, in hīs Flōra, puella fōrmōsa, quae {{rosās}} vēndit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"roscidus","latin":"roscidus, roscida, roscidum","headword":"roscidus","letter":"r","pos":"adjective","posGroup":"adjective","english":"dewy, wet w/dew; consisting of dew; wet, dripping w/moisture; resembling dew","forms":["rōscidā","rōscidus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{rōscidus}} -ā -um « rós rōris m.— aqua","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"roseus","latin":"roseus, rosea, roseum","headword":"roseus","letter":"r","pos":"adjective","posGroup":"adjective","english":"rose-colored, red; (of sky/sun); made of roses","forms":["roseā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dīxit, et āvertēns roseā cervīce refulsit,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"rostratus","latin":"rōstrātus, -a, -um","headword":"rōstrātus","letter":"r","pos":"adjective","posGroup":"adjective","english":"having a beaked prow","forms":["rōstrātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cornēliō Asinā cōnsulibus, in marī dīmicāvērunt parātīs nāvibus {{rōstrātīs}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rostrum","latin":"rōstrum, -ī","headword":"rōstrum","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"beak, beaked prow; beak (of a ship); Rōstra, speaker's platform","forms":["Rōstra","rōstrīs","rōstrō","rŌstrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae simul ārentī sitientēs hausimus ōre,\net tetigit summōs virgā dea dīra capillōs,\n(et pudet et referam) saetīs horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\nmurmur et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla tumēre torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"rota","latin":"rota, -ae","headword":"rota","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"wheel","forms":["rotā","rotae","rotās","rotīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Axis erat aureus, aureus erat tēmō, aureae {{rotae}}, at argenteī radiī: quae metalla ūna cum gemmīs, quibus tōtus currus ōrnābātur, Sōlis lūmen repercussum in omnēs caelī partēs spargēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"roto","latin":"roto, rotare, rotavi, rotatus","headword":"roto","letter":"r","pos":"verb","posGroup":"verb","english":"whirl round; revolve, rotate","forms":["rotat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"fulmineō rabidōs cum {{rotat}} ōre canēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rotundus","latin":"rotundus, -a, -um","headword":"rotundus","letter":"r","pos":"adjective","posGroup":"adjective","english":"round","forms":["rotunda","rotundae","rotundam","rotundum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ōra {{rotunda}} ī51 summà fronte nōdum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rubens","latin":"rubens, (gen.), rubentis","headword":"rubens","letter":"r","pos":"adjective","posGroup":"adjective","english":"colored or tinged with red","forms":["rubēns","rubentes"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Mēdus {{rubēns}} nescit quid respondeat et velut homō surdus mūtusque ante eōs stat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rubeo","latin":"rubeo, rubere, -, -","headword":"rubeo","letter":"r","pos":"verb","posGroup":"verb","english":"be red, become red","forms":["rubēbant","rubēbat","rubent","rubēre","rubet"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus, quī paulō ante ob timōrem pallēbat, iam {{rubet}} propter pudōrem.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ruber","latin":"ruber, rubra, rubrum","headword":"ruber","letter":"r","pos":"adjective","posGroup":"adjective","english":"red","forms":["ruber","rubra","rubram","Rubrī","Rubrō","rubrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Medicus: “Sed faciēs eius nimis {{rubra}} erat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"rubere","latin":"(rubeō) rubēre","headword":"rubēre","letter":"r","pos":"verb","posGroup":"verb","english":"be red; to blush, be red","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"rubesco","latin":"rubesco, rubescere, rubui, -","headword":"rubesco","letter":"r","pos":"verb","posGroup":"verb","english":"turn red, redden, become red","forms":["rubēscere","rubuērunt"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"quās cum nōn iam appārēre, atque mundum {{rubēscere}} vīdissent, properāvērunt Horae equōs addūcere, quōs continuō curruī iūnxērunt; tum pater, animō turbātō, fīlium suum salūtāns dīxit:","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rubet","latin":"rubet","headword":"rubet","letter":"r","pos":"verb","posGroup":"verb","english":"blushes, is red","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"rubor","latin":"rubor, ruboris","headword":"rubor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"redness, blush; modesty, capacity to blush; shame, disgrace, what causes blush","forms":["rubor","rubōrem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ōrīs et in niveō mixtum candōre {{rubōrem}},","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rubricatus","latin":"rubricatus, rubricata, rubricatum","headword":"rubricatus","letter":"r","pos":"adjective","posGroup":"adjective","english":"red, painted red with ocher; (books) with chapter headings on red (i.e., legal)","forms":["rubrīcāta"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego et dîxî quia müstella comēdit! iam Graeculîs calcem impingit, et Latīnās coepit nôn male appetere. ��; Ëmî ergô nunc c ‘x “f: Pedīs puerô aliquot lībra {{rubrīcāta}}, quia volô illum pars posterior ad domüsiônem aliquid dē iūre gustāre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"rudens","latin":"rudens, rudentis","headword":"rudens","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"rope","forms":["rudentum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Īnsequitur clāmorque virum strīdorque {{rudentum}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"rudis","latin":"rudis, -e","headword":"rudis","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"rough","forms":["rude","rudem","rudēs","rudī","rudibus","rudis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Deus agricolārum est Sāturnus, quī ōlim rēx caelī, sed ā fīliō suō Iove ē caelō pulsus, in Italiam venit, eamque regiōnem quae Latium appellātur optimē rēxit hominēsque, ut tunc erant {{rudēs}} ac barbarōs, colere docuit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"ruere","latin":"(ruō) ruere, -isse, -tum","headword":"ruere","letter":"r","pos":"","posGroup":"other","english":"rush, tumble down","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"rufinus","latin":"Rufinus, Rufini","headword":"Rufinus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Rufinus; (St./Bishop of Assisi)","forms":["Rūfīnum","Rūfīnus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēlius {{Rūfīnus}} et M'.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rufus","latin":"rufus, rufa -um, rufior -or -us, rufissimus -a -um","headword":"rufus","letter":"r","pos":"adjective","posGroup":"adjective","english":"red (of various shades); (esp. hair); red-haired; tawny; ruddy","forms":["Rūfō","Rūfum","Rūfus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Est {{Rūfus}}, quī parvam vīllam cum hortō prope silvam habet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"ruga","latin":"ruga, rugae","headword":"ruga","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"wrinkle; crease, small fold","forms":["Rūga","rūgae","rūgās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"iam venient {{rūgae}}, quae tibi corpus ārent.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rugosus","latin":"rugosus, rugosa, rugosum","headword":"rugosus","letter":"r","pos":"adjective","posGroup":"adjective","english":"full of wrinkles, folds or creases","forms":["rūgōsam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In prātō quondam rāna cōnspexit bovem, et tācta invidiā tantae magnitūdinis {{rūgōsam}} inflāvit pellem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"ruina","latin":"ruīna, -ae","headword":"ruīna","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"collapse, ruin; ruin, disaster; ruin, fall","forms":["ruīnā","ruīnae","ruīnam","ruīnās","ruīnīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās concussit, et turba omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn inultus occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rumor","latin":"rūmor, rūmōris","headword":"rūmor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"(m.) rumor; rumour; rumour, report; rumour, hearsay","forms":["rūmor","rūmōre","rumores","rūmōrī","rumoribus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi et adfingunt {{rumoribus}} Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rumpere","latin":"(rumpō) rumpere, rūpisse, ruptum","headword":"rumpere","letter":"r","pos":"verb","posGroup":"verb","english":"break; to break, burst","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"rumpit","latin":"rumpit","headword":"rumpit","letter":"r","pos":"verb","posGroup":"verb","english":"breaks open, bursts","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"rumpo","latin":"rumpo, rumpere, rupi, ruptus","headword":"rumpo","letter":"r","pos":"verb","posGroup":"verb","english":"break; destroy","forms":["rumpam","rumpe","rumpēns","rumpere","rumperētur","rumpī","rumpit","rumpitur","rūpit","rupta","ruptō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Trāditus Philistaeīs {{rūpit}} vincula, quibus constrīctus erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ruo","latin":"ruo, ruere, rui, rutus","headword":"ruo","letter":"r","pos":"verb","posGroup":"verb","english":"destroy, ruin, overthrow; rush on, run; fall; charge (in + ACC); be ruined","forms":["ruat","ruēbant","ruente","ruentēs","ruere","ruisse","ruit","ruunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ut vīdit Iōsēphus exstīnctum patrem, {{ruit}} super eum flēns, et ōsculātus est eum, lūxitque illum diū.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rupes","latin":"rūpēs, -is ( f.)","headword":"rūpēs","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"crag, rock; rock, cliff","forms":["rūpe","rūpem","rūpēs","rūpibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interdum etiam dēfuit aquā: at, iubente Deō, Moysēs percutiēbat {{rūpem}} virgā, et continuō ērumpēbant fontēs aquae dulcis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ruptor","latin":"ruptor, -ōris (m.)","headword":"ruptor","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"one who breaks; breaker (of a treaty)","forms":["ruptor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mettius ille est ductor itineris huius, Mettius īdem huius auctor bellī, Mettius foederis Rōmānī Albānīque {{ruptor}}!\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ruri","latin":"rūrī","headword":"rūrī","letter":"r","pos":"adverb","posGroup":"adverb","english":"in the country","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"rursum","latin":"rursum","headword":"rursum","letter":"r","pos":"adverb","posGroup":"adverb","english":"turned back, backward; on the contrary/other hand, in return, in turn, again","forms":["rūrsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Columba {{rūrsum}} ēmissa attulit in ōre suō rāmum olīvae virentis, quō fīnis dīluviī significābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rursus","latin":"rūrsus","headword":"rūrsus","letter":"r","pos":"adverb","posGroup":"adverb","english":"again, back; back again","forms":["rursus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac re cognita, Vercingetorix {{rursus}} in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio victos Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rus","latin":"rūs, rūris","headword":"rūs","letter":"r","pos":"noun (n.)","posGroup":"noun","english":"(n.) countryside; rūrī = in the country; the country","forms":["rūra","rūre","rūrī","rūris","rūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Isaacus forte tunc dēambulābat {{rūre}}; vīdit camēlōs venientēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"rustica","latin":"rustica, rusticae","headword":"rustica","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"countrywoman, bumpkin","forms":["rūstica"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Polyphēmus fuit Cyclōps quī ōlim in īnsulā Sicilia habitābat ibique vīta {{rūstica}} fruēbātur (Cyclōps est mōnstrum homine altius atque fortius, quod vērō ūnum oculum in mediā fronte habet).","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"rustice","latin":"rustice, rusticius, rusticissime","headword":"rustice","letter":"r","pos":"adverb","posGroup":"adverb","english":"in the manner of a rustic/countrified style; clumsily, uncouthly, boorishly","forms":["rūstice"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Numquam mōrēs urbānōs discēs, {{rūstice}}!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rusticitas","latin":"rusticitas, rusticitatis","headword":"rusticitas","letter":"r","pos":"noun (f.)","posGroup":"noun","english":"lack of sophistication","forms":["rūsticitās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cultūs (urbànus) €» {{rūsticitās}}-àtis f sed quia cultus adest nec","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"rusticus","latin":"rūsticus, -a, -um","headword":"rūsticus","letter":"r","pos":"adjective","posGroup":"adjective","english":"of the country, rustic; rustic, boorish","forms":["rūsticae","rūsticam","rūsticīs","rūsticō","rūsticum","rūsticus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cūrā īnfantium multum temporis magnamque patientiam postulat, itaque parum temporis habeō ad opus {{rūsticum}}.”","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"rutilius","latin":"Rutilius, Rutili","headword":"Rutilius","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Rutilius; (Roman gens name)","forms":["Rūtiliō","Rūtilius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rūtiliō lēgātō; nam Metellus cōnspectum Mariī fūgerat, nē vidēret ea quae audīta animus tolerāre nequīverat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"rutilus","latin":"rutilus, -a, -um","headword":"rutilus","letter":"r","pos":"adjective","posGroup":"adjective","english":"red; reddish, glowing","forms":["Rutilum","rutilus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sempronium {{Rutilum}} attribuit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"rutuli","latin":"Rutulī, -ōrum","headword":"Rutulī","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"the Rutulians, the people of Turnus","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"rutulus","latin":"Rutulus, Rutuli","headword":"Rutulus","letter":"r","pos":"noun (m.)","posGroup":"noun","english":"Rutulian; (member of the Rutuli, Italic people led by Turnus)","forms":["Rutulī","Rutulīs","Rutulōrum","Rutulōs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Auget uterque suās externō rōbore vīrēs,\net multī {{Rutulōs}}, multī Trōiāna tuentur\ncastra, neque Aenēās Evandrī ad moenia frūstrā\n[īvit; nam Pallas, fīlius Evandrī, ad bellum pugnandum missus est.]\n[Bellum] perstat, habetque deōs pars utraque, quodque\ndeōrum est īnstar, habent animōs. . . .","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sabbatum","latin":"sabbatum, sabbati","headword":"sabbatum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"Sabbath (usu. pl.); Saturday (Jewish); Sunday (Christian); festival/feast day","forms":["sabbata","Sabbatō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sabbatō nūllum opus faciētis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sabinus","latin":"Sabinus, Sabini","headword":"Sabinus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sabines (pl.), people living NE of Rome; their territory; an estate there","forms":["Sabīna","Sabīnae","Sabīnās","Sabīnī","Sabīnīs","Sabīnō","Sabīnōrum","Sabīnōs","Sabīnum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ōlim Sabīnī, quī in Latiō habitābant, magnō exercitū Rōmānōs, hostēs suōs, oppugnāvērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sacco","latin":"sacco, saccare, saccavi, saccatus","headword":"sacco","letter":"s","pos":"verb","posGroup":"verb","english":"filter; strain","forms":["saccō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Perāctō convīviō, Iōsēphus dat negōtium dispēnsātōrī ut {{saccō}}s eōrum impleat frūmentō, pecūniam simul repōnat, et īnsuper scyphum suum argenteum in saccō Beniamīnī recondat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sacculus","latin":"sacculus, -ī","headword":"sacculus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"purse; little bag, purse","forms":["sacculō","sacculum","sacculus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dāvus, servus Iūliī, laetus est, quia nummum habet in sacculō suō.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"saccus","latin":"saccus, -ī","headword":"saccus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sack; sack, bag","forms":["saccī","saccīs","saccōrum","saccōs","saccum","saccus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Via quae est inter Tūsculum et vīllam Iūliī nōn tam longa est quam via Latīna, sed servī quattuor quī Tūsculō ad vīllam ambulant fessī sunt, quia lectīcam et {{saccōs}} portant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sacer","latin":"sacer, -cra, -crum","headword":"sacer","letter":"s","pos":"adjective","posGroup":"adjective","english":"holy, sacred","forms":["sacer","sacra","sacrae","sacram","sacrās","sacrī","sacrīs","sacrōrum","sacrōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam illud tempus efflūxit, Cȳrus, Persārum rēx, dēvictō B abylōniorum rege, IŪdaeīs:fēcit potestātem in patriam remigrandī, templumque restituendī: {{sacra}} etiam vāsa, quae N abuchodonosor abstulerat, reddī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sacerdos","latin":"sacerdōs, sacerdōtis","headword":"sacerdōs","letter":"s","pos":"noun (m.); noun","posGroup":"noun","english":"(m./f.) priest, priestess","forms":["sacerdōs","sacerdōte","sacerdōtem","sacerdotes","sacerdōtī","sacerdōtibus","sacerdōtis","sacerdōtum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per {{sacerdotes}} more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sacerdotium","latin":"sacerdotium, sacerdoti(i)","headword":"sacerdotium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"priesthood; benefice/living (Erasmus)","forms":["sacerdōtia"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tum Catilīna pollicērī tabulās novās, prōscrīptiōnem locuplētium, magistrātūs, {{sacerdōtia}}, rapīnās, alia omnia quae bellum atque libīdō victōrum fert. ‘Praetereā esse in Hispāniā citeriōre Pīsōnem, in Maurētāniā cum exercitū P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"sacra","latin":"sacra, -ōrum","headword":"sacra","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sacred things, rites","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"sacramentum","latin":"sacramentum, sacramenti","headword":"sacramentum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sum deposited in a civil process, guaranty; oath of allegiance; sacrament","forms":["sacrāmentō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Affirmābant autem ‘hanc fuisse summam vel culpae suae vel errōris, quod essent solitī statō diē ante lūcem convenīre, carmenque Christō quasi deō dīcere sēcum invicem sēque sacrāmentō nōn in scelus aliquod obstringere, sed nē fūrta, nē latrōcinia, nē adulteria committerent, nē fidem fallerent, nē dēpositum appellātī abnegārent’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sacrare","latin":"(sacrō) sacrāre","headword":"sacrāre","letter":"s","pos":"","posGroup":"other","english":"consecrate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sacrarium","latin":"sacrārium, -ī","headword":"sacrārium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sanctuary; shrine, sanctuary","forms":["sacrārium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Librī trēs, in {{sacrārium}} conditī, 'Sibyllīnī' appellātī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sacratus","latin":"sacratus, sacrata, sacratum","headword":"sacratus","letter":"s","pos":"adjective","posGroup":"adjective","english":"hallowed, holy, sacred","forms":["sacrātā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aut super Īdalium sacrātā sēde recondam,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sacrificare","latin":"(sacrificō) sacrificāre","headword":"sacrificāre","letter":"s","pos":"","posGroup":"other","english":"make a sacrifice","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sacrificium","latin":"sacrificium, -ī","headword":"sacrificium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sacrifice","forms":["sacrificia","sacrificiīs","sacrificiō","sacrificium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tum ērēxit altāre, et obtulit {{sacrificium}} Dominō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sacrifico","latin":"sacrificō (1)","headword":"sacrificō","letter":"s","pos":"verb","posGroup":"verb","english":"sacrifice","forms":["sacrificābat","sacrificābō","sacrificandum","sacrificante","sacrificāre","sacrificārentur","sacrificāret","sacrificārētur","sacrificārī","sacrificat","sacrificātō","sacrificāverint","sacrificāvērunt","sacrificāvī","sacrificāvit","sacrificem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cotīdiē itaque Pygmaliōn, quī cupidus erat eam puellam vīvam aspiciendī, deōrum templa adīre solēbat ad {{sacrificandum}} et deōs deāsque ōrābat: spērābat enim flendō sē deōrum animōs mollīre posse; neque enim quisquam, nisi deus, illī signō vītam dare poterat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sacrilegus","latin":"sacrilegus, sacrilega, sacrilegum","headword":"sacrilegus","letter":"s","pos":"adjective","posGroup":"adjective","english":"sacrilegious, impious","forms":["sacrilegās"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"435 Nōn mihi, {{sacrilegās}} meretrīcum ut persequar artēs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sacro","latin":"sacro, sacrare, sacravi, sacratus","headword":"sacro","letter":"s","pos":"verb","posGroup":"verb","english":"consecrate, make sacred, dedicate","forms":["sacrātum","sacrāverant","sacrāverat","sacrāvisset","sacrō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sīc coeunt sacrō. nūpta deusque torō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sacrum","latin":"sacrum, sacri","headword":"sacrum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sacrifice; sacred vessel; religious rites (pl.)","forms":["sacrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quō sacrificātō, Mīnōs servōs iussit {{sacrum}} taurum, quem Neptūnus mīserat, ad stabulum agere atque iānuās claudere: “Nunc magnā cūrā facite, ut nēmō hunc taurum videat: imperō vōbīs ut eum bene in stabulō occultētis.” Deinde rēx, laetus quod tam pulchrum taurum sibi parāvit, ad rēgiam suam rediit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"saeculum","latin":"saeculum, -ī","headword":"saeculum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"century; century, age","forms":["saecula","saeculī","saeculīs","saeculum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ad dextram et ad sinistram Sōlis aderant Diēs et Mēnsēs et Annī et {{Saecula}} et Horae;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"saepe","latin":"saepe","headword":"saepe","letter":"s","pos":"adverb","posGroup":"adverb","english":"often","forms":["saepe","saepissimē","saepius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Labienus milites cohortatus ut suae pristinae virtutis et secundissimorum proeliorum retinerent memoriam atque ipsum Caesarem, cuius ductu {{saepe}} numero hostes superassent, praesentem adesse existimarent, dat signum proeli.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"saepes","latin":"saepes, saepis","headword":"saepes","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"hedge; fence; anything planted/erected to form surrounding barrier","forms":["saepēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc īrātus pater familiās dīxit servō suō: “Exī citō in plateās et vīcōs cīvitātis, et pauperēs ac dēbilēs et caecōs et claudōs intrōdūc hūc!” 22 Et ait servus: “Domine, factum est ut imperāstī, et adhūc locus est.” 23 Et ait dominus servō: “Exī in viās et {{saepēs}}, et compelle intrāre, ut impleātur domus mea. 24 Dīcō autem vōbīs: quod nēmō virōrum illōrum quī vocātī sunt gustābit cēnam meam!”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"saepio","latin":"saepio, saepire, saepsi, saeptus","headword":"saepio","letter":"s","pos":"verb","posGroup":"verb","english":"surround/envelop/enfold/encircle; clothe/cover/protect; close/seal off; shut in","forms":["saepsissent","saepsit","saeptus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Custōdibus armātīs corpus {{saepsit}}; neque enim ad iūs regnī quicquam praeter vim habēbat, ut quī neque populī iussū neque auctōribus patribus regnāret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"saepire","latin":"(saepiō) saepīre, -sisse, -tum","headword":"saepīre","letter":"s","pos":"","posGroup":"other","english":"surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"saeptum","latin":"saeptum, saepti","headword":"saeptum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"fold, paddock; enclosure; voting enclosure in the Campus Martius","forms":["saepta"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ad haec Albāna iuventūs, inermīs ab armātīs {{saepta}}, silentium tenet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"saeta","latin":"saeta, -ae","headword":"saeta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"bristle, stiff hair","forms":["saetīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Quae simul ārentī sitientēs hausimus ōre,\net tetigit summōs virgā dea dīra capillōs,\n(et pudet et referam) {{saetīs}} horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\nmurmur et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla tumēre torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"saetiger","latin":"saetiger, saetigera, saetigerum","headword":"saetiger","letter":"s","pos":"adjective","posGroup":"adjective","english":"bristly","forms":["saetigerī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"cumque eadem passīs (tantum medicāmina possunt!)\nclaudor hara, sōlumque suīs caruisse figūrā\nvīdimus Eurylochum: sōlus data pōcula fūgit;\nquae nisi vītāsset, pecoris pars ūna manērem\nnunc quoque saetigerī, nec tantae clādis ab illō\ncertior ad Circēn ultor vēnisset Ulixēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"saevio","latin":"saeviō, -īre, -iī, -ītum","headword":"saeviō","letter":"s","pos":"verb","posGroup":"verb","english":"to rage, be violent; to rage, be fierce","forms":["saeviat","saevit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"... cecidistī et fēmina ferrō, totque tuōs idem frātrēs, tē perdidit īdem, exitium Trōiae nostrīque orbātor, Achillēs; at postquam cecidit Paridis Phoebīque sagittīs, ‘nunc certē’ dīxī ‘nōn est metuendus Achillēs’: nunc quoque mī metuendus erat; cinis ipse sepultī in genus hoc {{saevit}}, tumulō quoque sēnsimus hostem, Aeacidae fēcunda fuī!","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"saevitia","latin":"saevitia, -ae","headword":"saevitia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"savageness, cruelty; cruelty, savagery","forms":["saevitiā","saevitiam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam cum aliīs urbānīs operibus intentum sē esse simulāret, Sextus, fīlius eius quī minimus ex tribus erat, trānsfūgit ex compositō Gabiōs patris in sē {{saevitiam}} nōn tolerandam querēns: 'rēgem iam ab aliēnīs in suōs vertisse superbiam et līberīs quoque īnsidiās parāre, nē quem hērēdem regnī relinquat; sē quidem inter tēla et gladiōs patris ēlāpsum nihil usquam sibi tūtum nisi apud hostēs L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"saevus","latin":"saevus, -a, -um","headword":"saevus","letter":"s","pos":"adjective","posGroup":"adjective","english":"savage; savage, fierce; cruel, savage","forms":["saeva","saevae","saevam","saevē","saevī","saevīs","saevissima","saevissimam","saevissimō","saevissimum","saevius","saevō","saevum","saevus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quamquam multī in viā ambulābant, nēmō ad iuvandum cucurrit: nam omnēs Claudium timēbant, cuius {{saevissimum}} servum bene nōverant: neque quisquam parātus erat ad moriendum prō Virginīā.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sagax","latin":"sagāx, -ācis","headword":"sagāx","letter":"s","pos":"adjective","posGroup":"adjective","english":"wily, shrewd","forms":["sagāx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sed {{sagāx}} Ulixēs ūnum oculum tēlō acūtō trāns fodit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sagino","latin":"sagino, saginare, saginavi, saginatus","headword":"sagino","letter":"s","pos":"verb","posGroup":"verb","english":"fatten (animals) for eating; feed lavishly, stuff","forms":["sagīnātum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et addūcite vitulum {{sagīnātum}} et occīdite, et mandūcēmus et epulēmur!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sagitta","latin":"sagitta, -ae","headword":"sagitta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"arrow","forms":["sagitta","sagittae","sagittam","sagittarum","sagittās","sagittis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Multitudine {{sagittarum}} atque omnis generis telorum multos vulneratos; ad haec sustinenda magno usui fuisse tormenta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sagittarius","latin":"sagittārius, -ī (m.)","headword":"sagittārius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"archer, bowman","forms":["sagittarii","sagittarios","Sagittārium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Galli inter equites raros {{sagittarios}} expeditosque levis armaturae interiecerant, qui suis cedentibus auxilio succurrerent et nostrorum equitum impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sal","latin":"sāl, salis","headword":"sāl","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(n.) salt","forms":["sal","sale","salem","Salī","salis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"\"Salī modo!\" inquit gubernātor.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"salax","latin":"salax, (gen.), salacis","headword":"salax","letter":"s","pos":"adjective","posGroup":"adjective","english":"lecherous/lustful; highly sexed, eager for sex, lascivious; aphrodisiac; hot","forms":["salāx"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôveram hominem ôlim ôliôrum, et adhūc {{salāx}} erat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"saliens","latin":"saliens, salientis","headword":"saliens","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"fountain, jet d'eau; outflow (of water); flow in water-clock; gushing/spouting","forms":["saliēns"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Famē coācta vulpēs altā in vīneā ūvam appetēbat summīs {{saliēns}} vīribus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"salina","latin":"salina, salinae","headword":"salina","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"salt-pans (pl.)","forms":["salīnae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Usque ad mare imperium prōlātum est et in ōre Tiberis Ōstia urbs condita, {{salīnae}} circā factae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"salinae","latin":"salīnae, -ārum (pl.)","headword":"salīnae","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"salt pans, salt works; salt-pans","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"salio","latin":"salio, salire, salivi, saltus","headword":"salio","letter":"s","pos":"verb","posGroup":"verb","english":"leap, jump; move suddenly/spasmodically (part of body under stress), twitch","forms":["saliam","saliat","salīre","salit","salītur"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Iam tē monuī!\" Tabellārius vērō, quamquam sīc ā iānitōre monitus est, alterum gradum ad canem versus facit — sed ecce canis in eum {{salit}} catēnam rumpēns!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"salire","latin":"(saliō) salīre, saluisse","headword":"salīre","letter":"s","pos":"","posGroup":"other","english":"leap","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"salo","latin":"salo, salere, -, salsus","headword":"salo","letter":"s","pos":"verb","posGroup":"verb","english":"salt, salt down, preserve with salt; sprinkle before sacrifice","forms":["salō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"perque undās, superante salō, perque invia saxa","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"salomon","latin":"Salomon, Salomonis","headword":"Salomon","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"David","forms":["Salomōn","Salomōne","Salomōnem","Salomōnī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum esset extrēmā senectūte et īnfirmā valētūdine, {{Salomōnem}} hērēdem rēgnī cōnstituit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"salsus","latin":"salsus, salsa -um, salsior -or -us, salsissimus -a -um","headword":"salsus","letter":"s","pos":"adjective","posGroup":"adjective","english":"salted, salty, preserved in salt; briny; witty, funny, salted wit humor","forms":["salsus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Male {{salsus}} rīdēns dissimulāre!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"saltare","latin":"(saltō) saltāre","headword":"saltāre","letter":"s","pos":"","posGroup":"other","english":"dance","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"saltatio","latin":"saltatio, saltationis","headword":"saltatio","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"dancing; dance (Collins)","forms":["Saltātiō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"saltàtio -ōnis f « saltāre [Saltātiō, lūsus, locā vīsenda]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"saltem","latin":"saltem","headword":"saltem","letter":"s","pos":"adverb","posGroup":"adverb","english":"at least, anyhow","forms":["saltem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Sī potes hīs {{saltem}} monitīs pārēre parentīs, parce, puer, stimulīs et fortius ūtere lōrīs!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"salto","latin":"salto, saltare, saltavi, saltatus","headword":"salto","letter":"s","pos":"verb","posGroup":"verb","english":"dance, jump; portray or represent in a dance","forms":["saltābant","saltandī","saltāns","saltant","saltantīs","saltāre","saltat","saltet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Subitō autem novem pulcherrimās puellās vīdit, quās statim intellēxit novem Mūsās esse, deās artium canendī, scrībendī, saltandī.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"saltus","latin":"saltus, -ūs","headword":"saltus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"wooded hills; narrow pass","forms":["saltibus","saltū","saltum","saltūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ita genitī itaque ēducātī Rōmulus et Remus — ea frātribus geminīs nōmina fuērunt — cum prīmum adolēvērunt, nōn in stabulīs apud pecus sēgnēs manēbant, sed per {{saltūs}} vēnābantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"saluber","latin":"salūber, -bris, -bre","headword":"salūber","letter":"s","pos":"adjective","posGroup":"adjective","english":"healthy, salutary","forms":["salūberrimī","salūbris"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{salūbris}} -ē 7 quī salūtem affert, quī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"salus","latin":"salūs, salūtis","headword":"salūs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) safety; safety, deliverance; safety, welfare; greeting","forms":["salūs","salute","salutem","saluti","salutis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis {{salutis}} causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"salutare","latin":"salutare, salutaris","headword":"salutare","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"salvation","forms":["salūtāre","salūtāribus","salūtārium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum in captīvitātem abductus esset, eandem in Deum pietātem semper retinuit: omnia bona, quae habēre poterat, cotīdiē exsiliī suī comitibus impertiēbat, eōsque monitīs {{salūtāribus}} ad colendum Deum hortābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"salutaris","latin":"salutaris, salutaris, salutare","headword":"salutaris","letter":"s","pos":"adjective","posGroup":"adjective","english":"healthful; useful; helpful; advantageous","forms":["salūtāris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deinde est hominum generī prosperus et {{salūtāris}} ille fulgor quī dīcitur \"Iovis\"; tum rutilus horribilisque terrīs quem \"Martium\" dīcitis.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"salutat","latin":"salūtat","headword":"salūtat","letter":"s","pos":"verb","posGroup":"verb","english":"greet; greets; greets, hails","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"salutem dicere","latin":"salūtem dīcere","headword":"salūtem dīcere","letter":"s","pos":"","posGroup":"other","english":"say hi","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"saluto","latin":"saluto, salutare, salutavi, salutatus","headword":"saluto","letter":"s","pos":"verb","posGroup":"verb","english":"greet; wish well; visit; hail, salute","forms":["Salūtā","salūtābam","salūtābās","salūtābat","salūtābātur","salūtābō","salūtāmus","salūtandum","salūtāns","salūtant","salūtantur","salūtās","salūtat","salūtātī","salūtātis","salūtātum","salūtātur","salūtātus","salūtāvī","salūtāvissent","salūtāvisset","salūtāvistī","salūtāvit","salūtō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mēdus sē vertit ad Dōrippam eamque {{salūtat}}: “Salvē, Dōrippa!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"salvare","latin":"(salvō) salvāre, salvāvisse, salvātum","headword":"salvāre","letter":"s","pos":"verb","posGroup":"verb","english":"make safe; to save","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"salvator","latin":"salvator, salvatoris","headword":"salvator","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"savior","forms":["Salvātor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At angelus dīxit illīs:\"Nōlīte timēre: nātus est hodiē {{Salvātor}} in cīvitāte","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"salve","latin":"salvē","headword":"salvē","letter":"s","pos":"interjection; verb","posGroup":"interjection","english":"hello, good morning (sing.); hello! greetings!; greetings, hello, hail","forms":["salvē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mēdus: “Salvē, mea Lȳdia!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"salveo","latin":"salveo, salvere, -, -","headword":"salveo","letter":"s","pos":"verb","posGroup":"verb","english":"be well/in good health; [salve => hello/hail/greetings; farewell/goodbye]","forms":["Salvēte"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aemilia cum Iūliō adit ad Flōram, quae eōs salūtat: “{{Salvēte}}, domine et domina!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"salvo","latin":"salvo, salvare, salvavi, salvatus","headword":"salvo","letter":"s","pos":"verb","posGroup":"verb","english":"save","forms":["salvēre","salvō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quem, cum prīmum vīdit, hīs verbīs {{salvēre}} iussit: “Salve” inquit, “pulcherrimē puer.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"salvus","latin":"salvus, -a, -um","headword":"salvus","letter":"s","pos":"adjective","posGroup":"adjective","english":"safe; safe, saved; safe, unharmed","forms":["salvā","salvae","salvam","salvī","salvōs","salvum","salvus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quī respondērunt: {{salvus}} est pater noster; adhūc vīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"samaritanus","latin":"Samaritanus, Samaritana, Samaritanum","headword":"Samaritanus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Samaritan, of/pertaining to Samaria; (middle district of Palestine)","forms":["Samarītānus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Samarītānus}} autem, iter faciēns, venit secus eum: et vidēns eum, misericordiā mōtus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"samius","latin":"Samius, Samia, Samium","headword":"Samius","letter":"s","pos":"adjective","posGroup":"adjective","english":"of/belonging to Samos; (cheap/brittle pottery); [testa ~ => shard for cutting]","forms":["Samiīs","Samius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"\"Nēmō tibi ānulum ita abiectum reddet — nisi forte tam fēlīx eris quam Polycratēs tyrannus {{Samius}}, cuius ānulus, quem ipse in mare abiēcerat, mīrum in modum inventus est nōn in fundō maris, sed in ventre piscis!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sanat","latin":"sānat, sānāre","headword":"sānat","letter":"s","pos":"verb","posGroup":"verb","english":"heal, cure; heals, cures","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"sancio","latin":"sancio, sancire, sanxi, sanctus","headword":"sancio","letter":"s","pos":"verb","posGroup":"verb","english":"confirm, ratify; sanction; fulfill (prophesy); enact (law); ordain; dedicate","forms":["sanciatur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide {{sanciatur}} petunt, collatis militaribus signis, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sanctus","latin":"sānctus, -a, -um","headword":"sānctus","letter":"s","pos":"adjective","posGroup":"adjective","english":"holy; sacred","forms":["sāncta","sānctās","sāncte","sānctī","sanctīs","sānctissimam","sānctissimē","sānctissimīs","sanctissimo","sānctum","sānctus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Conclamant equites, {{sanctissimo}} iure iurando confirmari oportere, ne tecto recipiatur, ne ad liberos, ne ad parentes, ne ad uxorem aditum habeat qui non bis per agmen hostium perequitasset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sane","latin":"sānē","headword":"sānē","letter":"s","pos":"adverb","posGroup":"adverb","english":"certainly, truly","forms":["sānē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Admīrandum sānē vērī ac sincērī ergā inimīcum amōris exemplum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sanguineus","latin":"sanguineus, -a, -um","headword":"sanguineus","letter":"s","pos":"adjective","posGroup":"adjective","english":"bloodstained, bloodshot","forms":["sanguineam","sanguineōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sīc ait, et oculōs {{sanguineōs}} volvēns, pallida morte futūrā, altum rogum cōnscendit ēnsemque Aenēae ēdūxit — mūnus nōn in hunc ūsum datum! 'Accipite hanc animam mēque hīs exsolvite cūrīs!' Dixit, et ōs impressa torō 'Moriēmur inultae, sed moriāmur!' ait. 'Sīc, sīc iuvat īre sub umbrās!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sanguinolentus","latin":"sanguinolentus, sanguinolenta, sanguinolentum","headword":"sanguinolentus","letter":"s","pos":"adjective","posGroup":"adjective","english":"bloody; blood-red; blood-stained","forms":["sanguinolenta","sanguinolentus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"vulneribus nostrīs {{sanguinolenta}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sanguinulentus","latin":"sanguinulentus, -a, -um","headword":"sanguinulentus","letter":"s","pos":"adjective","posGroup":"adjective","english":"bloodstained; bloody","forms":["sanguinulenta","sanguinulentus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipse sub Ēsquiliīs, ubi erat sua rēgia, caesus concīdit in dūrā {{sanguinulentus}} humō.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sanguis","latin":"sanguis, sanguinis","headword":"sanguis","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) blood","forms":["sanguine","sanguinem","sanguinis","sanguis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine vestro {{sanguine}} tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sanitas","latin":"sānitās, -tātis","headword":"sānitās","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sanity, health","forms":["sanitatem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Adiuvat rem proclinatam Convictolitavis plebemque ad furorem impellit, ut facinore admisso ad {{sanitatem}} reverti pudeat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sannio","latin":"sannio, sannionis","headword":"sannio","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"buffoon","forms":["Sanniō","Sanniōnī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iānitor, cui nōmen est Sanniō, Dōrippam ēgredientem Sanniō -ōnis interrogat: “Quō īs, Dōrippa?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sano","latin":"sano, sanare, sanavi, sanatus","headword":"sano","letter":"s","pos":"verb","posGroup":"verb","english":"cure, heal; correct; quiet","forms":["sānābat","sanabitur","sānābuntur","sānāre","sānārem","sānāret","sānārī","sānat","sānātur","sanaturum","sānātus","sānō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Id tamen se celeriter maioribus commodis {{sanaturum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sanus","latin":"sānus, -a, -um","headword":"sānus","letter":"s","pos":"adjective","posGroup":"adjective","english":"healthy, well","forms":["sāna","sānae","sānam","sānī","sānum","sānus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sānā tē ipsum, medice!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sapere","latin":"(sapiō) sapere, sapīvisse","headword":"sapere","letter":"s","pos":"verb","posGroup":"verb","english":"be wise, have sense; to be wise","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"sapiens","latin":"sapiēns","headword":"sapiēns","letter":"s","pos":"adjective","posGroup":"adjective","english":"(gen.sapientis) wise","forms":["sapiēns","sapiente","sapientem","sapientior","sapientiōrem","sapientiōris","sapientissimus","sapientium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Itaque, Rēx, praefice tōtī Aegyptō virum {{sapientem}} et industrium, quī partem frūgum recondat in horreīs pūblicīs, servetque dīligenter in subsidium famis secūtūrae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sapienter","latin":"sapienter","headword":"sapienter","letter":"s","pos":"adverb","posGroup":"adverb","english":"wisely, sensibly","forms":["sapienter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Erat ibi puer hebraeus, quī nōbīs {{sapienter}} interpretātus est somnia; rēs enim interpretātiōnem comprobāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sapientia","latin":"sapientia, -ae","headword":"sapientia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"wisdom","forms":["sapientiā","sapientiae","sapientiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum iam in cōnspectū habēret terram ā Deō prōmissam, mortuus est vir sapientiā et cēterīs virtūtibus plānē admīrābilīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sapio","latin":"sapio, sapere, sapivi, -","headword":"sapio","letter":"s","pos":"verb","posGroup":"verb","english":"taste of; understand; have sense","forms":["sapere","sapi","sapiat","sapiēbat","sapiēs","sapiō","sapit","sapitis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"sed tū sī {{sapiēs}}, sī tē bene iungere anumque hanc audīre volēs (quae tē plūs omnibus illīs, plūs, quam crēdis, amō): vulgārēs reice taedās","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sarcina","latin":"sarcina, -ae","headword":"sarcina","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"pack, kit","forms":["sarcinas"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qua re nuntiata Caesar celeriter {{sarcinas}} conferri, arma expediri iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sarcio","latin":"sarcio, sarcire, sarsi, sartus","headword":"sarcio","letter":"s","pos":"verb","posGroup":"verb","english":"make good; redeem; restore","forms":["sarcīrī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum tempestātēs pluviae fuerint, ‘quae opera per imbrem fierī potuerint: dōlia lavārī, vīllam pūrgārī, frūmentum trānsferrī, stercus forās efferrī, sterculīnum fierī, sēmen pūrgārī, tīmēs sarcīrī, novōs fierī’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sardina","latin":"sardina, sardinae","headword":"sardina","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sardine; pilchard; small fish","forms":["sardīnās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dā {{sardīnās}}, siliquās et oleum Hispānum!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sardinia","latin":"Sardinia, Sardiniae","headword":"Sardinia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Sardinia; (large island west of Italy)","forms":["Sardinia","Sardiniam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Corsica et {{Sardinia}} et Sicilia īnsulae sunt.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sardus","latin":"Sardus, Sardi","headword":"Sardus","letter":"s","pos":"noun","posGroup":"noun","english":"Sardinian (person)","forms":["Sardīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Atīliō Bulbō cōnsulibus dē {{Sardīs}} triumphātum est, et pāce omnibus locīs factā Rōmānī nūllum bellum habuērunt, quod iīs post Rōmam conditam semel tantum, Numā Pompīliō regnante, contigerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sarmentum","latin":"sarmentum, -ī","headword":"sarmentum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"brushwood, branch","forms":["sarmenta","sarmentīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hannibal, vāstātā Campāniā, inter Casīlīnum oppidum et Calliculam montem ā Fabiō clausus, {{sarmentīs}} ad cornua boum alligātīs et incēnsīs, praesidium Rōmānōrum, quod Calliculam īnsidēbat, fugāvit, et sīc trānsgressus est saltum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"satanas","latin":"Satanas, Satanae","headword":"Satanas","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Satan, the Devil; adversary (Def)","forms":["Satanās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Intrāvit autem {{Satanās}} in IŪdam, quī cognōminābātur Iscariōtēs, ūnum dē duodecim.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"satelles","latin":"satelles, -itis (m.)","headword":"satelles","letter":"s","pos":"noun","posGroup":"noun","english":"attendant, henchman","forms":["satellitem","satellitēs","satellitibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnique Saūl mīsit {{satellitēs}}, quī Davidem domī in oculīs uxōris trucīdārent; haec vērō marītum dēmīsit per fenestram, atque ita ēripuit perīculō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"satio","latin":"satio, satiare, satiavi, satiatus","headword":"satio","letter":"s","pos":"verb","posGroup":"verb","english":"satisfy, sate; nourish","forms":["satiārī"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quantō est facilius mihi sub tēctō vīvere et ōtiōsum largō satiārī cibō!” [Canis:] “Venī ergō mēcum!” Dum prōcēdunt, lupus ā catēnā collum dētrītum canī aspicit. [Lupus:] “Unde hoc, amīce?” [Canis:] “Nīl est.” [Lupus:] “Dīc, sōdēs, tamen!” [Canis:] “Quia videor ācer, alligant mē interdiū, lūce ut quiēscam, ut vigilem nox cum vēnerit: crepusculō solūtus quā vīsum est vāgor.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"satis","latin":"satis","headword":"satis","letter":"s","pos":"adverb","posGroup":"adverb","english":"enough","forms":["satis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono tubae, quod {{satis}} magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"satisfacio","latin":"satisfacio, satisfacere, satisfeci, satisfactus","headword":"satisfacio","letter":"s","pos":"verb","posGroup":"verb","english":"satisfy; make amends; apologize, excuse; satisfy a claim; compensate; suffice","forms":["satisfacere","satisfaceret","satisfaciēbam","satisfaciendum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Postero die Vercingetorix concilio convocato id bellum se suscepisse non suarum necessitatum sed communis libertatis causa demonstrat et, quoniam sit fortunae cedendum, ad utramque rem se illis offere, seu morte sua Romanis {{satisfacere}} seu vivum tradere velint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"satius","latin":"satius","headword":"satius","letter":"s","pos":"adverb","posGroup":"adverb","english":"better, preferable","forms":["satius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eleazarus rem prāvam suādentibus nōluit assenfirī:\"Aetafī nostrae\"inquit,\"nōn convenit ista simulātiō: nōn committam ut perīculōsum exemplum adulēscentibus relinquam: multō {{satius}} est perīre, quam propter brevem vītae ūsūram turpirūdinis nōtam meō nominī inūrere.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"satur","latin":"satur, satura, saturum","headword":"satur","letter":"s","pos":"adjective","posGroup":"adjective","english":"well-fed, replete; rich; saturated","forms":["satur"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sequimur nôs, admirätiône iam {{satur}}î, et cum Agā- memnone ad iānuam pervenîmus, in cuius poste libellus erat cum hāc înscrîptiône ﬁxus: Quisquis servus sine dō- minicô iussüfōrās exierit accipietplägās centum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"saturnalium","latin":"Saturnalium, Saturnalii","headword":"Saturnalium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"Saturnalia; festival of Saturnalia (December)","forms":["Sāturnālia"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sīve {{Sāturnālia}}, cum Circus nōn","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"saturninus","latin":"Saturninus, Saturnini","headword":"Saturninus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Saturninus; (revolutionary tribune)","forms":["Sāturnīnī","Saturnīnō","Sāturnīnum","Saturnīnus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Sāturnīnum}} tribūnum plēbis et C.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"saturnius","latin":"Saturnius, Saturnia, Saturnium","headword":"Saturnius","letter":"s","pos":"adjective","posGroup":"adjective","english":"Saturnian; of Saturn; (epithet of Juno/Jupiter as children of Saturn)","forms":["Sāturnia","Sāturniam","Sāturnius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ex quibus ūnum globum possidet illa quam in terrīs \"{{Sāturniam}}\" nōminant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"saturnus","latin":"Saturnus, Saturni","headword":"Saturnus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Saturn; (Roman god of agriculture, father of Jupiter/Juno/Pluto)","forms":["Sāturnī","Sāturnus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Deus agricolārum est {{Sāturnus}}, quī ōlim rēx caelī, sed ā fīliō suō Iove ē caelō pulsus, in Italiam venit, eamque regiōnem quae Latium appellātur optimē rēxit hominēsque, ut tunc erant rudēs ac barbarōs, colere docuit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"satus","latin":"satus, sata, satum","headword":"satus","letter":"s","pos":"adjective","posGroup":"adjective","english":"sprung (from); native","forms":["satus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hīc Hammōne {{satus}} raptā Garamantide nymphā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"satyrus","latin":"satyrus, -ī","headword":"satyrus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"satyr","forms":["satyrī","Satyrīs","Satyrō","Satyrus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Neque igitur Satyrī, neque Pan et Silvānus, silvārum dī, ad eam accēdere potuerant, etsī nōn parvō amōre accēnsī erant; sed","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"saucio","latin":"saucio, sauciare, sauciavi, sauciatus","headword":"saucio","letter":"s","pos":"verb","posGroup":"verb","english":"wound, hurt; gash, stab","forms":["sauciat","sauciātum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tūta sit ornátrix: ōdī quae {{sauciat}} ōra","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"saucius","latin":"saucius, -a, -um","headword":"saucius","letter":"s","pos":"adjective","posGroup":"adjective","english":"wounded","forms":["saucia","sauciīs","saucius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{saucius}} ingemuit tēlumque volātile sēnsit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"saul","latin":"Saul, Saulis","headword":"Saul","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Saul; King of Israel); (original name of St Paul)","forms":["Saūl","Saūlem","Saūlis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quārē admonitus ā Deō Samūēl annuit eōrum postulātiōnī, et {{Saūlem}} rēgem cōnsecrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"saulus","latin":"Saulus, Sauli","headword":"Saulus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Saul; King of Israel); (original name of St Paul)","forms":["Saūlī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Erat Saūlī ingēns statūra et fōrma excellēns, adeō ut dignitās corporis dignitātī rēgiae pulchrē convenīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"saxum","latin":"saxum, -ī","headword":"saxum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"rock; rock, stone","forms":["saxa","saxī","saxis","saxō","saxum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum crebris diurnis nocturnisque eruptionibus aut aggeri ignem inferebant aut milites occupatos in opere adoriebantur et nostrarum turrium altitudinem, quantum has cotidianus agger expresserat, commissis suarum turrium malis adaequabant et apertos cuniculos praeusta et praeacuta materia et pice fervefacta et maximi ponderis {{saxis}} morabantur moenibusque appropinquare prohibebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scaber","latin":"scaber, scabra -um, scabrior -or -us, scaberrimus -a -um","headword":"scaber","letter":"s","pos":"adjective","posGroup":"adjective","english":"rough/scabrous from disease, scabby (esp. sheep); rough/corroded (surface)","forms":["scaber"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cui digitī pingués et {{scaber}} unguis erit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"scaena","latin":"scaena, -ae","headword":"scaena","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"scene, stage","forms":["scaena","scaenae","scaenam","scaenīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Hae {{scaenae}} moventēs factae sunt ā discipulīs dē Collegio Highland Park; magistra eōrum, Cyril Miles et coniūnx Arnold, pictūram moventem fēcērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"scaenicus","latin":"scaenicus, -a, -um","headword":"scaenicus","letter":"s","pos":"adjective","posGroup":"adjective","english":"theatrical; of the stage","forms":["scaenicīs","scaenicos"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: \"Ego ludos {{scaenicos}} praefero: malo fabulas spectare in theatro.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"scala","latin":"scala, scalae","headword":"scala","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"ladder (pl.)","forms":["scālam","scalarum","scālās","scālīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Uno die intermisso Galli atque hoc spatio magno cratium, {{scalarum}}, harpagonum numero effecto, media nocte silentio ex castris egressi ad campestres munitiones accedunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scalae","latin":"scālae, -ārum (pl.)","headword":"scālae","letter":"s","pos":"","posGroup":"other","english":"ladder","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"scalpellum","latin":"scalpellum, -ī","headword":"scalpellum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"scalpel, surgical knife; small knife, scalpel","forms":["scalpello"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: \"Quisnam vulneravit filium tuum?\" Aemilia: \"Medicus bracchium eius {{scalpello}} suo acuto secuit!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"scamnum","latin":"scamnum, -ī","headword":"scamnum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"stool","forms":["scamna","scamnum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Genera nōminum quot sunt?' Discipulus: 'Quattuor.' Magister: 'Quae?' Discipulus: 'Masculīnum, ut hic magister; fēminīnum, ut haec fēmina; neutrum, ut hoc {{scamnum}}; commūne, ut hic et haec sacerdōs.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"scandalizo","latin":"scandalizo, scandalizare, scandalizavi, scandalizatus","headword":"scandalizo","letter":"s","pos":"verb","posGroup":"verb","english":"tempt to evil; cause to stumble; offend, scandalize (Bee)","forms":["scandalizāverit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sī quis autem {{scandalizāverit}} ūnum dē parvulīs isfīs, expedit eī ut suspendiitur mola collō eius et dēmergātur in profundum mare.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scandalum","latin":"scandalum, scandali","headword":"scandalum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"temptation/inducement to sin; cause of offense; stumbling block; scandal (Bee)","forms":["scandalum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Vae hominī illī, per quem {{scandalum}} venit ī\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scandere","latin":"(scandō) scandere, scandisse,","headword":"scandere","letter":"s","pos":"","posGroup":"other","english":"climb, mount scansum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"scando","latin":"scando, scandere, scandi, scansus","headword":"scando","letter":"s","pos":"verb","posGroup":"verb","english":"climb; mount, ascend, get up, clamber","forms":["scandunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Intereā Aenēās et Achātēs celeriter prōgressī quō via dūcit iam magnum collem {{scandunt}} quī urbī Karthāginī imminet.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"scapula","latin":"scapula, scapulae","headword":"scapula","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"shoulder-blades (pl.); shoulder, back; wings (Ecc)","forms":["scapulīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Conveniunt tenuēs {{scapulīs}} analectridēs altīs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"scateo","latin":"scateo, scatere, -, -","headword":"scateo","letter":"s","pos":"verb","posGroup":"verb","english":"gush out, bubble, spring forth; swarm (with), be alive (with)","forms":["scatērent"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At illum subitus vīscerum dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta {{scatērent}} vermibus, et foetōrem lātē ēmitterent, exercituī et aegrō ipsī intolerābilem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scaurus","latin":"scaurus, scaura, scaurum","headword":"scaurus","letter":"s","pos":"adjective","posGroup":"adjective","english":"with swollen ankles","forms":["Scaurus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad summam: {{Scaurus}} mare patēmum hospitium.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sceleratus","latin":"scelerātus, -a, -um","headword":"scelerātus","letter":"s","pos":"adjective","posGroup":"adjective","english":"accursed, criminal; wicked, criminal","forms":["scelerāta","scelerātē","scelerātīs","scelerātissimus","scelerātōrum","scelerātum","scelerātus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Sīc pater ille {{scelerātus}}, dēbilis et invalidus, sine cibō et sine pōtiōne semper manet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"scelestus","latin":"scelestus, -a, -um","headword":"scelestus","letter":"s","pos":"adjective","posGroup":"adjective","english":"wicked","forms":["scelesta","sceleste","scelestī","scelestīs","scelestō","scelestōs","scelestum","scelestus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Deum ūnum timē, Deum intuēre, ā quō mercēdem recipiēs.\"Hīs verbīs cōnfirmātus, adulēscēns exclāmāvit:\"Nōn regī obsequor, sed legī.\"Tūne conversus ad Antiochum:\"Tū quid em, ō {{sceleste}}, Deī omnipotentis Īram nōn effugiēs: erit tempus cum, ab eō percussus et dolōre victus, tē hominem esse cōnfitēberis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scelus","latin":"scelus, sceleris","headword":"scelus","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"(n.) crime, wickedness; crime","forms":["scelera","scelere","scelerī","sceleris","scelerum","scelus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ruben, quī erat nātū maximus, dēterrēbat frātrēs ā tantō {{scelere}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scena","latin":"scena, scenae","headword":"scena","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"theater stage, \"boards\"; scene; a theater; public stage/view, publicity","forms":["scēnīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{scēnīs}} op-pōnere manūs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sceptrum","latin":"scēptrum, -ī","headword":"scēptrum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"scepter; sceptre","forms":["scēptra","sceptrī","scēptrō","sceptrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nōn sōlum nūllum ā mē maleficium patiēris, sed etiam rēgnābis mēcum apud Īnferōs, neque misera erit vīta tua: ego enim tē tam multum amō, ut tantum laetitia animum tuum afficere cupiam.” Hīs verbīs Plūtō perterritam virginem cōnsōlātus est; agēns deinde currum, equīs celeriter currentibus, ad locum pervēnit, ubi terrā, scēptrō percussa, sē aperuit ut iīs viam ad Īnferōs faceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"schema","latin":"schema, schemae","headword":"schema","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"shape, figure, form","forms":["schēmā","schēmās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nec {{schēmās}} loquēbātur, sed dîrëc- tum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"schola","latin":"schola, -ae","headword":"schola","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"school, class","forms":["scholam","scholās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Vādō in {{scholam}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sciens","latin":"sciēns (gen. scientis)","headword":"sciēns","letter":"s","pos":"adjective","posGroup":"adjective","english":"having knowledge of (+ gen.)","forms":["sciēns","scientēs","scientior","scientius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo {{scientius}} quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scientia","latin":"scientia, -ae","headword":"scientia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"knowledge; knowledge, skill","forms":["scientia","scientiae","scientiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Non virtute neque in acie vicisse Romanos, sed artificio quodam et {{scientia}} oppugnationis, cuius rei fuerint ipsi imperiti.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scilicet","latin":"scīlicet","headword":"scīlicet","letter":"s","pos":"adverb","posGroup":"adverb","english":"naturally, of course; obviously, of course","forms":["scīlicet"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dōrippa: “Nōn Lepidum {{scīlicet}}, sed ānulum eius iaciam in Tiberim!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"scindere","latin":"(scindō) scindere, scidisse, scissum","headword":"scindere","letter":"s","pos":"verb","posGroup":"verb","english":"rip, tear; to tear, split","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"scindit","latin":"scindit","headword":"scindit","letter":"s","pos":"verb","posGroup":"verb","english":"tears, rips","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"scindo","latin":"scindo, scindere, scidi, scissus","headword":"scindo","letter":"s","pos":"verb","posGroup":"verb","english":"tear, split, divide; rend, cut to pieces; tear in rage/grief/despair","forms":["scidisset","scidit","scindēbant","scindēbat","scindendum","scindēns","scindere","scindit","scinditur","scissa","scissīs","scissum","scissus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde {{scidit}} vestem, et induit cilicium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scintilla","latin":"scintilla, scintillae","headword":"scintilla","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"spark","forms":["scintilla","Scintillae","scintillam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum Promētheus, postquam cautē circum sē aspexit num quis venīret, curruī appropinquāvit, ut inde ignis {{scintillam}} sūmeret, quam hominibus dōnāret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"scio","latin":"sciō, scīre","headword":"sciō","letter":"s","pos":"verb","posGroup":"verb","english":"know","forms":["sci","sciam","sciamus","sciant","sciās","sciat","Scībam","sciēbam","sciēbāmus","sciēbant","sciēbat","sciēmus","scieris","sciēs","sciet","scīmus","sciō","scīre","scīrent","scīret","scīrī","scīs","scit","scītis","scītō","Scītōte","scītū","scītūr","sciunt","scivērunt","scīvit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ego nōn parvōs tantum numerōs sciō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"scipio","latin":"Scipio, Scipionis","headword":"Scipio","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Scipio; (P. Cornelia ~ beat Hannibal, his grandson destroyed Carthage)","forms":["Scīpiō","scīpiōne","Scīpiōnem","Scīpiōnī","Scīpiōnibus","Scīpiōnis","Scīpiōnum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"tibi, magne Scīpiō, pōnī (statua Ēn-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"scipus","latin":"scipus, scipi","headword":"scipus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"bowl, goblet, cup; communion cup","forms":["Scīpi"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"contiguus pōnī, {{Scīpi}}ó","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"scire","latin":"scīre","headword":"scīre","letter":"s","pos":"verb","posGroup":"verb","english":"to know","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"sciscitari","latin":"(scīscitōr) scīscitārī","headword":"scīscitārī","letter":"s","pos":"verb","posGroup":"verb","english":"inquire, ask; to ask, inquire","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"sciscitor","latin":"sciscitor, sciscitari, sciscitatus sum","headword":"sciscitor","letter":"s","pos":"verb","posGroup":"verb","english":"ask; question; consult","forms":["scīscitābātur","scīscitantēs","sciscitātī","scīscitātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum Rebecca vēnisset, sciscitātī sunt an vellet discēdere cum homine.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scisco","latin":"scisco, sciscere, scivi, scitus","headword":"scisco","letter":"s","pos":"verb","posGroup":"verb","english":"investigate, inquire; (political) vote; ordain","forms":["scīscam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Erīlis praevertit metus: accurrō ut {{scīscam}} quid velit,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"scissor","latin":"scissor, scissoris","headword":"scissor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"carver","forms":["scissor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn minus et Trimalchiô eiusmodî methodiô laetus “Carpe!” inquit. essedärius Prôcessit statim {{scissor}}, et ad _, cerâvit obsônium, ut putārēs Ā’ ' essedärium hydraulē cantante Ingerēbat nihilô minus Trimal- chiô lentissimä vôce: “Carpe!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"scius","latin":"scius, scia, scium","headword":"scius","letter":"s","pos":"adjective","posGroup":"adjective","english":"cognizant, possessing knowledge; skilled/expert (in w/ABL)","forms":["scius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nē-{{scius}} -ā -um ^ ger — nē-sciēns;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"scomber","latin":"scomber, scombri","headword":"scomber","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"mackerel","forms":["scombrīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quod sī nōn {{scombrīs}} scelerāta poēmata dōnās, cēnābis sōlus iam, Ligurīne, domī!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"scopulus","latin":"scopulus, -ī","headword":"scopulus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"rock; rock, cliff; rock, crag","forms":["scopulī","scopulīs","scopulō","scopulōs","scopulum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Voluī inclāmāre, sed hostī\nprōdere mē timuī; vīdī, cum monte revulsum\nimmāne {{scopulum}} mediās permīsit in undās;\nvīdī iterum velutī tormentī vīribus ācta\nvāsta Gigantēō iaculantem saxa lacertō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"scorpio","latin":"scorpio, scorpionis","headword":"scorpio","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"scorpion; (animal/constellation/zodiacal sign); small catapult; plant","forms":["Scorpiō","scorpione","scorpionis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas glaebas in ignem e regione turris proiciebat; {{scorpione}} ab latere dextro traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scorpios","latin":"scorpios, scorpii","headword":"scorpios","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"scorpion; (animal/constellation/zodiacal sign); small catapult; plant","forms":["scorpiōs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nōn tigrīs catulīs citāta raptīs, nec sīc {{scorpiōs}} improbus timētur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"scortum","latin":"scortum, -ī","headword":"scortum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"prostitute, harlot; prostitute","forms":["scorta","scortōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Scīpiō Āfricānus Numantiam obsēdit, et corruptum licentiā luxuriāque exercitum ad sevērissimam mīlitiae disciplīnam revocāvit: omnia dēliciārum īnstrūmenta recīdit, duo mīlia {{scortōrum}} ē castrīs ēiēcit, mīlitem cotīdiē in opere habuit et trīgintā diērum frūmentum ac septēnōs vallōs ferre cōgēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"scriba","latin":"scriba, scribae","headword":"scriba","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"scribe, clerk","forms":["scrībae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quaerēbant prīncipēs sacerdōtum et {{scrībae}} quōmodo Iēsum interficerent, timēbant vērō plēbem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"scribere","latin":"scrībere","headword":"scrībere","letter":"s","pos":"verb","posGroup":"verb","english":"to write; write","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"scribit","latin":"scrībit","headword":"scrībit","letter":"s","pos":"verb","posGroup":"verb","english":"writes","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"scribite","latin":"scrībite","headword":"scrībite","letter":"s","pos":"verb","posGroup":"verb","english":"write (plural command)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"scribo","latin":"scrībō, scrībere","headword":"scrībō","letter":"s","pos":"verb","posGroup":"verb","english":"write","forms":["scrībam","scribas","scrībe","scrībēbam","scrībēbant","scrībēbantur","scrībēbās","scrībēbat","scrībendam","scrībendī","scrībendīs","scrībendō","scrībente","scrībentem","scrībentī","scrībere","scrīberentur","scrībēs","scrībet","scrībimus","scrībis","scrībit","scrībite","scrībitis","scrībitō","scrībitur","scrībō","scrībundīs","scrībunt","scrīpseram","scrīpserāmus","scrīpserās","scrīpserat","scrīpserātis","scrīpsēre","scrīpserim","scrīpserīs","scrīpserit","scrīpsērunt","scrīpsī","scrīpsimus","scrīpsisse","scrīpsistī","scrīpsistis","scrīpsit","scrīptae","scrīptam","scrīptās","scrīptūrum","scrīptūrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nōnne fīlium nostrum bene legere, {{scrībere}}, computāre docet?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"scrinium","latin":"scrinium, scrini(i)","headword":"scrinium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"box, case","forms":["scrīnium"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eō senātum advocat, magnāque frequentiā eius ōrdinis Volturcium cum lēgātīs intrōdūcit; Flaccum praetōrem {{scrīnium}} cum litterīs, quās ā lēgātīs accēperat, eōdem adferre iubet.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"scripto","latin":"scripto, scriptare, scriptavi, scriptatus","headword":"scripto","letter":"s","pos":"verb","posGroup":"verb","english":"write; compose","forms":["scrīptō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tē lyrā pulsā manū, tē carmina nostra sonābunt, flōsque novus scrīptō gemitus imitābere nostrōs.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"scriptor","latin":"scrīptor, -ōris (m.)","headword":"scrīptor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"writer","forms":["scrīptōrem","scriptōrēs","scrīptōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eō lūstrō mīlia octōgintā cīvium cēnsa dīcuntur (adicit {{scrīptōrum}} antīquissimus Fabius Pictor \"eōrum quī arma ferre possent eum numerum fuisse\").","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"scriptum","latin":"scrīptum, -ī","headword":"scrīptum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"writing, book","forms":["scrīpta","scrīptīs","scrīptum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Statim in iīs ‘AI’ litterae ad Apollinis clāmōrem commemorandum appāruērunt, quae adhūc in illīus flōris foliīs {{scrīpta}} cernuntur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"scriptura","latin":"scrīptūra, -ae","headword":"scrīptūra","letter":"s","pos":"","posGroup":"other","english":"tax on grazing rights","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"scriptus","latin":"scriptus, scriptus","headword":"scriptus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"scribe's office; being a clerk","forms":["Scrīptus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Lȳdia: \"{{Scrīptus}} est ā quōdam Iudaeō nōmine Matthaeō, quī simul cum Chrīstō vīxit et discipulus eius fuit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"scrobis","latin":"scrobis, scrobis","headword":"scrobis","letter":"s","pos":"noun","posGroup":"noun","english":"ditch, trench; dike","forms":["scrobes","scrobis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ante hos obliquis ordinibus in quincuncem dispositis {{scrobes}} tres in altitudinem pedes fodiebantur paulatim angustiore ad infimum fastigio.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"scruta","latin":"scruta, scrutae","headword":"scruta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"pot","forms":["scrūta"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque per scūtum per ocream ëgî aginävî quemadmodum “Forte dominus Capuae exierat ad {{scrūta}} scîta expedī- endā.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"scrutari","latin":"(scrūtor) scrūtārī","headword":"scrūtārī","letter":"s","pos":"","posGroup":"other","english":"examine, search","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"scrutor","latin":"scrutor, scrutari, scrutatus sum","headword":"scrutor","letter":"s","pos":"verb","posGroup":"verb","english":"search/probe/examine carefully/thoroughly; explore/scan/scrutinize/investigate","forms":["scrūtārī","scrūtātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Continuō dēpōnunt saccōs et aperiunt; quōs ille {{scrūtātus}} invenit scyphum in saccō Beniamīnī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sculpo","latin":"sculpo, sculpere, sculpsi, sculptus","headword":"sculpo","letter":"s","pos":"verb","posGroup":"verb","english":"carve, engrave (inscription/face); fashion/work into form by carving/engraving","forms":["sculpere"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"monumentîs înscrîbitur né tribūnal: cum sēde magisträ- tūs (praetôris, aedîlis, cét.) cicarô : servulus dîlêctus licet {{sculpere}} (: volô té s.) quod sibi assûmpsit Trimal- cum posset : etsî poterat decuriîs: magistrâtuum mī- nistrî lïbertînî in decuriās ex parvô : ex parvīs rébus sēstertium Irecentiês centêna et tū (quī haec Iegis) valē’!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"scutum","latin":"scūtum, -ī","headword":"scūtum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"shield","forms":["scūta","scūtī","scūtīs","scūtō","scūtum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In bracchiō sinistrō vērō, quō {{scūta}} tenēbant, armillās aureās gerere solēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"scylla","latin":"Scylla, -ae","headword":"Scylla","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Scylla (a monster, a rock); Scylla, a monster with six dog heads","forms":["Scyllā","Scyllam"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Brevī nāvigābimus per fretum Siculum, ubi ab utrāque parte magnum perīculum impendet nautīs: ab ōrā Italiae saxa perīculōsa, quibus Scyllā nōmen est, ab ōrā Siciliae vorāgō terribilis quae Charybdis vocātur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"scyphus","latin":"scyphus, scyphi","headword":"scyphus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"bowl, goblet, cup; communion cup; two-handled drinking vessel","forms":["scyphum","scyphus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego exprimēbam ūvās in {{scyphum}} Pharaōnis, eīque porrigēbam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"se","latin":"sē, sibi","headword":"sē","letter":"s","pos":"pronoun","posGroup":"pronoun","english":"himself, herself; himself, herself, itself, themselves","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"se conferre","latin":"sē cōnferre","headword":"sē cōnferre","letter":"s","pos":"","posGroup":"other","english":"go, betake oneself","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sebum","latin":"sebum, sebi","headword":"sebum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"suet, tallow, hard animal fat","forms":["sebi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus {{sebi}} ac picis traditas glaebas in ignem e regione turris proiciebat; scorpione ab latere dextro traiectus exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"secare","latin":"(secō) secāre, secuisse, sectum","headword":"secāre","letter":"s","pos":"verb","posGroup":"verb","english":"cut; to cut","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"secedere","latin":"(sēcēdō) sēcēdere (< cēdere)","headword":"sēcēdere","letter":"s","pos":"","posGroup":"other","english":"withdraw, rebel","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"secedo","latin":"secedo, secedere, secessi, secessus","headword":"secedo","letter":"s","pos":"verb","posGroup":"verb","english":"withdraw; rebel; secede","forms":["sēcēdant","Sēcēde","sēcēdere","sēcēdit","sēcessērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hī, relicta urbe, nē vidērent mala, quibus ea cōnflīctābātur, {{sēcessērunt}} in solitiīdinem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"secernere","latin":"(sēcernō) sēcernere (< cernere)","headword":"sēcernere","letter":"s","pos":"verb","posGroup":"verb","english":"separate, detach; to separate, set apart","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"secerno","latin":"secerno, secernere, secrevi, secretus","headword":"secerno","letter":"s","pos":"verb","posGroup":"verb","english":"separate","forms":["sēcernant","sēcernantur","sēcerne","sēcernerent","sēcernunt"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nērēides nymphaeque simul, quae vellera mōtīs\nnūlla trahunt digitīs nec fīla sequentia dūcunt,\nherbās dispōnunt sparsōsque sine ōrdine flōrēs\n{{sēcernunt}} calathīs variāsque colōribus herbās;\nipsa, quod hae faciunt, opus exigit, ipsa, quis ūsus\nquōve sit in foliō, quae sit concordia mixtīs,\nnōvit et advertēns pensās examinat herbās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"secessus","latin":"secessus, secessus","headword":"secessus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"withdrawal; secluded place","forms":["sēcessū","sēcessum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hinc vīs per porticum propter lūmen? [Gāius silet.] Numquid vīs venīre ad {{sēcessum}}?” [Gāius:] “Bene mē admonuistī: venter mē cōgit!” [Gāius discēdit ad sēcessum et mox redit.] [Iūlius:] “Eāmus iam!” [Amīcī per porticum ad thermās eunt.] [Iūlius, in thermīs, ad servum:] “Exue mē!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"secius","latin":"secius","headword":"secius","letter":"s","pos":"adverb","posGroup":"adverb","english":"otherwise, none the less","forms":["sēcius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Posteā tamen etiam ut {{sēcius}} eōs Camillus ita cecīdit, ut et aurum quod iīs datum fuerat et omnia quae cēperant mīlitāria signa revocāret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"secludo","latin":"secludo, secludere, seclusi, seclusus","headword":"secludo","letter":"s","pos":"verb","posGroup":"verb","english":"shut off","forms":["sēclūdite"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"'Solvite corde metum, Teucrī, {{sēclūdite}} cūrās.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"seco","latin":"secō, -āre, -uī, sectum","headword":"secō","letter":"s","pos":"verb","posGroup":"verb","english":"cut","forms":["secābat","secant","secāre","secari","secat","secta","sectum","secuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pabulum {{secari}} non posse; necessario dispersos hostes ex aedificiis petere; hos omnes cotidie ab equitibus deligi posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"secor","latin":"secor, seci, secutus sum","headword":"secor","letter":"s","pos":"verb","posGroup":"verb","english":"follow; escort/attend/accompany; aim at/reach after/strive for/make for/seek","forms":["secuntur"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Cônstemätî nôs însolentiä ëbriôrum intentāvī- que ē gastñs lābentia, quae collēcta puer lance circum- Hās lautitiās aequāvit ingeniôsus cocus: in crätîculä enim argenteā cochleâs attulit et tremulā taeterrimāque Pudet referre quae {{secuntur}}: inaudîtô enim môre puerî capillätî attulērunt unguentum in argenteā pēlve pedësque recumbentium ūnxērunt, cum ante crūra tälôsque corônîs vînxissent.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"secretarium","latin":"secretarium, secretarii","headword":"secretarium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"|council chamber; conclave, consistory; private chapel; retirement place","forms":["sēcrētāriō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Praesente bis et Claudiānō cōnsulibus, sextō decimō kalendās Augustās, Carthāgine in sēcrētāriō impositīs Spērātō, Nartzālō et Cittīnō, Dōnātā, Secundā, Vestiā, Saturnīnus prōcōnsul dīxit: “Potestis indulgentiam dominī nostrī Imperātōris prōmerērī, sī ad bonam mentem redeātis.”","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"secreto","latin":"sēcrētō","headword":"sēcrētō","letter":"s","pos":"adverb","posGroup":"adverb","english":"in private; secretly","forms":["sēcrētō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Certē Iūnō mē hīc nōn vidēbit,” dīxit, “aut sī videt, sunt dēlectāmenta pretiōsa sed dīgna pretiī.” Statim Iuppiter fōrmam Diānae simulāvit et ita ad nympham sēcrētō appropinquāvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"secretum","latin":"sēcrētum, -ī","headword":"sēcrētum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"solitude, secrecy, seclusion, privacy","forms":["sēcrēta","sēcrētum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Medea nunc ad ārās antīquās Hecatēs īvit ut in silvā carmina {{sēcrēta}} et artēs magicās disceret.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sector","latin":"sector, sectari, sectatus sum","headword":"sector","letter":"s","pos":"verb","posGroup":"verb","english":"follow continually; pursue; pursue with punishment; hunt out; run after","forms":["sectāre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"mé pinnīs {{sectāre}} datīs, ego praevius ībō:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"secum","latin":"sēcum","headword":"sēcum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"with himself/herself","forms":["secum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Caesar ex castris equitatum educi iubet, proelium equestre committit; laborantibus iam suis Germanos equites circiter CCCC summittit, quos ab initio habere {{secum}} instituerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"secunda","latin":"secunda, secundae","headword":"secunda","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"after-birth (pl.); second/inferior parts","forms":["secunda"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His datis mandatis, qua nostrum opus erat intermissum, {{secunda}} vigilia silentio equitatum dimittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"secundo","latin":"secundō","headword":"secundō","letter":"s","pos":"verb","posGroup":"verb","english":"for the second time","forms":["secundo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Vercingetorix nihilo minus in aequum locum descenderet, levi facto equestri proelio atque {{secundo}} in castra exercitum reduxit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"secundum","latin":"secundum","headword":"secundum","letter":"s","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) along; along, after, according to; after; by, along","forms":["secundum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum dētrāxit ē manū suā annulum, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō torquem aureum circumdedit, eumque in currū suō {{secundum}} collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"secundus","latin":"secundus, -a, -um","headword":"secundus","letter":"s","pos":"adjective","posGroup":"adjective","english":"second, favorable; second; favourable; following, favourable, second","forms":["secundae","secundam","secundārum","secundās","Secunde","secundī","secundis","secundissimorum","secundos","secundus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Errare, si qui in bello omnes {{secundos}} rerum proventus exspectent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"securis","latin":"secūris, -is ( f.) (acc. -im; abl. -ī)","headword":"secūris","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"axe","forms":["secūrēs","securibus","secūrim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quod si ea quae in longinquis nationibus geruntur ignoratis, respicite finitimam Galliam, quae in provinciam redacta, iure et legibus commutatis, {{securibus}} subiecta perpetua premitur servitute.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"securus","latin":"sēcūrus, -a, -um","headword":"sēcūrus","letter":"s","pos":"adjective","posGroup":"adjective","english":"secure, free from care","forms":["sēcūrā","secūrī","sēcūrus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cui Iōsēphus: haec est interpretātiō istīus somniī: tria canistra sunt trēs diēs, quibus ēlāpsīs, Pharaō tē feriet secūrī, et affīget ad pālum, ubi avēs pāscentur carne tuā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"secus","latin":"secus","headword":"secus","letter":"s","pos":"adverb","posGroup":"adverb","english":"otherwise","forms":["secus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum turbae irruerent in Iēsum ut audīrent verbum Deī, ipse ascendit in nāvem quae erat {{secus}} stāgnum, et sedēns docēbat dē nāviculā turbās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sed","latin":"sed","headword":"sed","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"but","forms":["sed"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His collocatis et coagmentatis alius insuper ordo additur, ut idem illud intervallum servetur neque inter se contingant trabes, {{sed}} paribus intermissae spatiis singulae singulis saxis interiectis arte contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sedare","latin":"(sēdō) sēdāre","headword":"sēdāre","letter":"s","pos":"","posGroup":"other","english":"allay, appease, calm","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sedatus","latin":"sedatus, sedata, sedatum","headword":"sedatus","letter":"s","pos":"adjective","posGroup":"adjective","english":"calm, untroubled; quiet","forms":["sēdāta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Melius fuisset carēre istā pecūniā, ad quam recipiendam fīlius missus est: satis erat nōbīs, quod fīliī cōnspectū fruī licēret.” Cui marītus: “Nōlī flēre” inquit “incolumis fīlius perveniet in Mēdiam; incolumīs ad nōs redībit: Deus mittet angelum, quī eī prōsperum iter praestet.” Quibus verbīs {{sēdāta}}, mulier tacuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sedecim","latin":"sēdecim","headword":"sēdecim","letter":"s","pos":"numeral","posGroup":"numeral","english":"sixteen","forms":["sēdecim"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus: “... quīndecim, {{sēdecim}}, septendecim, duodēvīgintī, ūndēvīgintī, vīgintī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sedeo","latin":"sedeō, -ēre, sēdī, sessum","headword":"sedeō","letter":"s","pos":"verb","posGroup":"verb","english":"sit, remain, stay","forms":["sedeās","sedeat","sedēbat","sedēbit","sedēns","sedent","sedente","sedentem","sedentēs","sedentī","sedentis","sedeo","sēderat","sedēre","sederem","sedēret","sedet","Sedēte","sēdimus","sēdisse","sedit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iam duo hominēs ūnō equō vehuntur: mīles {{sedet}} post Cornēlium, Cornēlius ante mīlitem sedet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sedes","latin":"sēdēs, -is ( f.)","headword":"sēdēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"seat, abode, dwelling; seat, dwelling","forms":["sedē","sēdem","sēdēs","sēdibus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hīc post mē sedē!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sedet","latin":"sedet, sedēre","headword":"sedet","letter":"s","pos":"","posGroup":"other","english":"sit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sedile","latin":"sedile, sedilis","headword":"sedile","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"seat, chair, bench, stool; that which may be sat on; armchair","forms":["sedīle","sedīlia"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quōs hominēs ut vīdit ūnus ex multitūdine simiōrum, quī sē aliīs priōrem cōnstituerat, iussit eōs tenērī et interrogārī ‘quid illī hominēs dē eō dīcerent?’ iussitque omnēs simiōs sibi similēs adstāre ante sē ōrdine longō, dextrā laevāque, et {{sedīle}} sibi parārī in mediō, sīcut vīderat Imperātōrem aliquandō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"seditio","latin":"sēditiō, -ōnis ( f.)","headword":"sēditiō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"discord, insurrection; sedition, civil strife","forms":["seditio","sēditiōne","sēditiōnem","sēditiōnēs","sēditiōnibus","sēditiōnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quos ille multa iam nocte silentio ex fuga excepit veritus ne qua in castris ex eorum concursu et misericordia vulgi {{seditio}} oreretur, ut procul in via dispositis familiaribus suis principibusque civitatum disparandos deducendosque ad suos curaret, quae cuique civitati pars castrorum ab initio obvenerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"seditiosus","latin":"sēditiōsus, -a, -um","headword":"sēditiōsus","letter":"s","pos":"adjective","posGroup":"adjective","english":"seditious","forms":["sēditiōsō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Gracchus, sēditiōsō tribūnātū āctō, cum Aventīnum quoque armātā multitūdine occupāsset, ā Opīmiō cōnsule — ex senātūs cōnsultō vocātō ad arma populō — pulsus et occīsus est et cum eō Fulvius Flaccus cōnsulāris, socius eiusdem furōris.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sedo","latin":"sedo, sedare, sedavi, sedatus","headword":"sedo","letter":"s","pos":"verb","posGroup":"verb","english":"settle, allay; restrain; calm down","forms":["sēdāre","sēdārī","sēdātō","sēdātur","sēdāvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ōlim, multīs hominibus spectantibus, ambulātum exiit et ōram maris petīvit; ibi vērō Neptūnum tālibus verbīs ōrāvit: “Ō Neptūne” inquit, “ōrō tē ut pulchrum taurum ad meam īnsulam mittās, quem tibi, marium omnium deō quī magnōs flūctūs excitās tempestātēsque {{sēdāre}} solēs, sacrificābō!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"seduco","latin":"seduco, seducere, seduxi, seductus","headword":"seduco","letter":"s","pos":"verb","posGroup":"verb","english":"lead away, lead apart; lead astray, seduce","forms":["sēdūxerit","sēdūxit"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Scîs tñ mē nôn mentîrî: Agathô unguentārius proximē {{sēdūxit}} mē et “Suädeô” inquit “nôn patiāris genus tuum interîre.” At ego, dum bōnātus agô et nôlô vidërî levis, ipse mihi asciam in crūs “Rēctē!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sedulo","latin":"sedulo","headword":"sedulo","letter":"s","pos":"adverb","posGroup":"adverb","english":"carefully","forms":["sēdulō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Is ab ineunte aetāte lēgem dīvīnam sēdulō observābat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sedulus","latin":"sedulus, sedula, sedulum","headword":"sedulus","letter":"s","pos":"adjective","posGroup":"adjective","english":"attentive, painstaking, sedulous","forms":["sēdulus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"collige et immundà {{sēdulus}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"seges","latin":"seges, segetis","headword":"seges","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"grain field; crop","forms":["seges","sēgetēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Omnēs {{sēgetēs}}, vīneae et oleae exustae sunt; nec inimīcam gentem variīs incommodīs vexāre dēstitit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"segmentum","latin":"segmentum, segmenti","headword":"segmentum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"cutting, shred; borders/patches (pl.) of purple or gold","forms":["segmenta","segmentum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{segmentum}} -ī 7 7 pars vestis sectum Quid dē veste loquar?","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"segnis","latin":"sēgnis, -e","headword":"sēgnis","letter":"s","pos":"adjective","posGroup":"adjective","english":"slothful, inactive","forms":["sēgnem","sēgnēs","sēgnior","sēgnis","sēgnius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{sēgnis}} -ē — piger, iners","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"segniter","latin":"segniter, segnitius, segnitissime","headword":"segniter","letter":"s","pos":"adverb","posGroup":"adverb","english":"half-heartedly; without spirit/energy, feebly; [nihlo ~ius => no less actively]","forms":["sēgniter"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Omnia suīs locīs repōne!” [Iūlius, cum servō cubiculum ingressus:] “Dīligenter sterne lectum!” [Servus:] “Strāvimus.” [Iūlius:] “Et ideō dūrum est?” [Servus:] “Excussimus et pulvīnum mollīvimus.” [Iūlius:] “Quoniam autem {{sēgniter}} fēcistis quae necessāria sunt, nēmō forīs pernoctet aut exeat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"seiungere","latin":"(sēiungō) sēiungere (< iungere)","headword":"sēiungere","letter":"s","pos":"","posGroup":"other","english":"separate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"seiungo","latin":"sejungo, sejungere, sejunxi, sejunctus","headword":"sejungo","letter":"s","pos":"verb","posGroup":"verb","english":"separate; exclude","forms":["sēiungātur","sēiungunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad Alpēs posteāquam vēnit, quae Ītaliam ā Galliā {{sēiungunt}}, quās nēmō umquam cum exercitū ante eum — praeter Herculem Graium — trānsierat (quō factō is hodiē saltus 'Graius' appellātur), Alpicōs cōnantēs prohibēre trānsitū concīdit, loca patefēcit, itinera mūnīvit, effēcit ut ea elephantus ōrnātus īre posset quā anteā ūnus homō inermis vix poterat rēpere.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"seligo","latin":"seligo, seligere, selegi, selectus","headword":"seligo","letter":"s","pos":"verb","posGroup":"verb","english":"select, choose, pick out; weed out","forms":["sēlige","sēligī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vertumnumque torī socium tibi {{sēlige}}!...","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sella","latin":"sella, -ae","headword":"sella","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stool, chair; chair, seat","forms":["sellā","sellam","sellās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hēlī, audītō tantae clādis nūntiō, ē sellā dēcidit, et frāctā cervīce mortuus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"semel","latin":"semel","headword":"semel","letter":"s","pos":"adverb","posGroup":"adverb","english":"once","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"semele","latin":"Semele, Semeles","headword":"Semele","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Semele; (mother of Bacchus, destroyed by Jupiter thunderbolt)","forms":["Semele"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Semele}}, Lēde/Léda, Eurōpa, fēminae","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"semen","latin":"sēmen, sēminis","headword":"sēmen","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"(n.) seed","forms":["sēmen","sēmina","sēmine","sēminibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ipsa hominibus {{sēmina}} largīta est atque mōnstrāvit quōmodo in agrōs spargerent ac sererent, ut terra magnam frūmentī cōpiam ferret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"semet","latin":"sēmet","headword":"sēmet","letter":"s","pos":"","posGroup":"other","english":"intensive of sē","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"semianimis","latin":"sēmianimis, -e","headword":"sēmianimis","letter":"s","pos":"","posGroup":"other","english":"half alive","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"semiermis","latin":"sēmiermis, -e (< arma)","headword":"sēmiermis","letter":"s","pos":"adjective","posGroup":"adjective","english":"half-armed","forms":["sēmiermium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx cum perexiguā manū {{sēmiermium}} mīlitum Chalcidem sē recēpit; sub adventum cōnsulis ā Chalcide profectus Ephesum trānsmīsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"semino","latin":"semino, seminare, seminavi, seminatus","headword":"semino","letter":"s","pos":"verb","posGroup":"verb","english":"plant, sow","forms":["sēminātū"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"quam sēminātū'st, alter mēnse septumō;","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"semireductus","latin":"semireductus, semireducta, semireductum","headword":"semireductus","letter":"s","pos":"adjective","posGroup":"adjective","english":"half bent back","forms":["sēmireducta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"prōtegitur laevā {{sēmireducta}} manū.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"semisomnus","latin":"sēmisomnus, -a, -um","headword":"sēmisomnus","letter":"s","pos":"adjective","posGroup":"adjective","english":"half-asleep","forms":["semisomnōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed ubi plērumque noctis prōcessit, obscūrō etiam tum lūmine, mīlitēs Iugurthīnī signō datō castra hostium invādunt; {{semisomnōs}} partim, aliōs arma sūmentēs fugant funduntque.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"semita","latin":"semita, semitae","headword":"semita","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"path","forms":["sēmita","semitae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni {{semitae}} patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"semivir","latin":"semivir, semiviri","headword":"semivir","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"half man","forms":["sēmivirō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et nunc ille Paris cum sēmivirō comitātū,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"semper","latin":"semper","headword":"semper","letter":"s","pos":"adverb","posGroup":"adverb","english":"always","forms":["semper"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tamen, quod instituto Caesaris {{semper}} duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque interscinderent, omnis vero ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sempiterno","latin":"sempiterno","headword":"sempiterno","letter":"s","pos":"adverb","posGroup":"adverb","english":"eternally, perpetually, everlastingly, permanently","forms":["sempiternō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Sed quō sīs, Āfricāne, alacrior ad tuendam rem pūblicam, sīc habētō: omnibus quī patriam cōnservāverint, adiūverint, auxerint, certum esse in caelō dēfīnītum locum, ubi beātī aevō sempiternō fruantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sempiternus","latin":"sempiternus, -a, -um","headword":"sempiternus","letter":"s","pos":"adjective","posGroup":"adjective","english":"everlasting, eternal","forms":["sempiternam","sempiternī","sempiternīs","sempiternum","sempiternus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dīxit Hebraeīs: “Sī quandō vōs interrogāverint fīliī vestrī, quōrsum spectet ista lapidum congeriēs, respondēbitis: ‘Siccō pede trāiēcimus Iordānem istum: idcircō positī sunt lapidēs ad {{sempiternam}} factī memoriam, ut discant quanta sit Deī potentia.’”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sempronius","latin":"Sempronius, Sempronia, Sempronium","headword":"Sempronius","letter":"s","pos":"adjective","posGroup":"adjective","english":"Sempronian; of gens Sempronia; (in title of laws by Ti./C. Gracchus)","forms":["Semprōniā","Semprōniam","Semprōniō","Sempronium","Semprōnius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Sempronium}} Rutilum attribuit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"senarius","latin":"senarius, senaria, senarium","headword":"senarius","letter":"s","pos":"adjective","posGroup":"adjective","english":"composed of six in a group","forms":["Sēnāriī","sēnāriīs","sēnārius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sēnāriī sunt versūs quī in sēnōs pedēs dīviduntur, septēnāriī quī septēnōs pedēs continent.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"senator","latin":"senātor, -ōris (m.)","headword":"senātor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"senator","forms":["senātor","senātōrem","senātōrēs","senātōrī","senātōribus","senātōris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam vēro Coriolānī verba audivērunt, mīrābantur {{senātōrēs}}, et perterritī ac valdē turbātī erant cīvēs, perīculum sibi impendēns timentēs.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"senatorius","latin":"senatorius, senatoria, senatorium","headword":"senatorius","letter":"s","pos":"adjective","posGroup":"adjective","english":"of a senator,senatorial","forms":["senātōriī"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eō convēnēre senātōriī ōrdinis P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"senatus","latin":"senātus, -ūs","headword":"senātus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"senate, assembly, sitting; senate","forms":["senāti","senatu","senātuī","senatum","senatus","SENĀTVS"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Interim Teutomatus, Olloviconis filius, rex Nitiobrigum, cuius pater ab {{senatu}} nostro amicus erat appellatus, cum magno equitum suorum numero et quos ex Aquitania conduxerat ad eum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"senecta","latin":"senecta, -ae","headword":"senecta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"old age","forms":["senectā","senectae"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tempus erit, cum dē tantō mē corpore parvam\nlonga diēs faciet, cōnsūmptaque membra senectā\nad minimum redigentur onus: nec amāta vidēbor\nnec plācuisse deō, Phoebus quoque forsitan ipse\nvel nōn cognōscet, vel dīlēxisse negābit:\nūsque adeō mūtāta ferar nūllīque videnda,\nvōce tamen nōscar; vōcem mihi fāta relinquent.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"senectus","latin":"senectūs, -ūtis ( f.)","headword":"senectūs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"old age","forms":["senectūs","senectūte","senectūtem","senectūtis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iacobus respondit rēgī: vīxī centum et trīgintā annōs, nec adeptus sum {{senectūtem}} beātam avōrum meōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"senescere","latin":"(senēscō) senēscere, -uisse, -itum","headword":"senēscere","letter":"s","pos":"","posGroup":"other","english":"grow old, weaken","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"senesco","latin":"senesco, senescere, senui, -","headword":"senesco","letter":"s","pos":"verb","posGroup":"verb","english":"grow old; grow weak, be in a decline; become exhausted","forms":["senēscere","senuerat","senuisse","senuisset"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Abrahamus iam {{senuerat}}, et Sarā eius uxor erat sterilis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"senex","latin":"senex, senis","headword":"senex","letter":"s","pos":"noun (m.); noun","posGroup":"noun","english":"(m.) old man (not an i-stem); old man, old woman","forms":["sene","senem","senēs","senex","senī","senibus","Seniōrēs","seniōribus","senis","senum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Illa parāvit senī cibum quem nōverat suāvem esse palātō eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"seni","latin":"sēnī, -ae, -a","headword":"sēnī","letter":"s","pos":"adjective","posGroup":"adjective","english":"six at a time; six each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"senilis","latin":"senīlis, -e","headword":"senīlis","letter":"s","pos":"adjective","posGroup":"adjective","english":"of old age, aged","forms":["senīlem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pāruit Aenēās et formīdābilis Orcī\nvīdit opēs ātavōsque suōs umbramque {{senīlem}}\nmagnanimī Anchīsae; didicit quoque iūra locōrum,\nquaeque novīs essent adeunda perīcula bellīs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"senior","latin":"senior (gen. seniōris)","headword":"senior","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"older","forms":["senior"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Erat autem fīlius eius {{senior}} in agrō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"senones","latin":"Senones, Senonis","headword":"Senones","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Senones; tribe of central Gaul (Seine valley)","forms":["Senones","Senonum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Celeriter sibi {{Senones}}, Parisios, Pictones, Cadurcos, Turonos, Aulercos, Lemovices, Andos reliquosque omnes qui Oceanum attingunt adiungit; omnium consensu ad: eum defertur imperium.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sensa","latin":"sēnsa, -ōrum","headword":"sēnsa","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sense, feeling","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"sensim","latin":"sēnsim","headword":"sēnsim","letter":"s","pos":"adverb","posGroup":"adverb","english":"gradually, little by little","forms":["sēnsim"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deus immīsit ventum vehementem, et {{sēnsim}} aquae imminūtae sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sensum","latin":"sensum, sensi","headword":"sensum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"thought","forms":["sēnsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tūne aperuit illīs {{sēnsum}} ut intellegerent Scrlptlirās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sensus","latin":"sēnsus, -ūs","headword":"sēnsus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"power of perception, sensation","forms":["sēnsū","sēnsus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nec est ūllus hebetior {{sēnsus}} in vōbīs; sīcut, ubi Nīlus ad illa quae Catadūpa nōminantur praecipitat ex altissimīs montibus, ea gēns quae illum locum accolīt propter magnitūdinem sonitūs sēnsū audiendī caret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sententia","latin":"sententia, -ae","headword":"sententia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"opinion, sentence; sentence, thought; opinion","forms":["sententia","sententiae","sententiam","sententiārum","sententiās","sententiis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hac coacta manu, quoscumque adit ex civitate ad suam {{sententiam}} perducit; hortatur ut communis libertatis causa arma capiant, magnisque coactis copiis adversarios suos a quibus paulo ante erat eiectus expellit ex civitate.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sentina","latin":"sentina, sentinae","headword":"sentina","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"bilgewater; scum or dregs of society","forms":["sentīna"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam sī tē interficī iusserō, residēbit in rē pūblicā reliqua coniūrātōrum manūs; sīn tū — quod tē iam dūdum hortor — exieris, exhauriētur ex urbe tuōrum comitum magna et perniciōsa {{sentīna}} reī pūblicae.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"sentio","latin":"sentiō, -īre, sēnsī, -sum","headword":"sentiō","letter":"s","pos":"verb","posGroup":"verb","english":"feel, know, sense","forms":["sēnsa","senserat","sēnseris","sēnserit","sēnsērunt","sēnsi","sēnsimus","sēnsisse","sēnsissent","sēnsisset","sēnsit","sēnsūrus","senti","sentiam","sentiant","sentiās","sentiat","sentiēbat","sentientem","sentiēs","sentiō","sentīrem","sentīrent","sentīret","sentit","sentiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac habita contione et ad extremam orationem confirmatis militibus, ne ob hanc causam animo permoverentur neu quod iniquitas loci attulisset id virtuti hostium tribuerent, eadem de profectione cogitans quae ante {{senserat}} legiones ex castris eduxit aciemque idoneo loco constituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sentis","latin":"sentis, sentis","headword":"sentis","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"thorn, briar","forms":["sentīs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed quidnam tū {{sentīs}}, Orontēs?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sentit","latin":"sentit, sentīre","headword":"sentit","letter":"s","pos":"","posGroup":"other","english":"feel, sense, think","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"separatim","latin":"separatim","headword":"separatim","letter":"s","pos":"adverb","posGroup":"adverb","english":"apart, separately","forms":["sēparātim"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Neque mīrum: ubi vōs {{sēparātim}} sibi quisque cōnsilium capitis, ubi domī voluptātibus, hīc pecūniae aut grātiae servītis, eō fit ut impetus fīat in vacuam rem pūblicam.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"separo","latin":"separo, separare, separavi, separatus","headword":"separo","letter":"s","pos":"verb","posGroup":"verb","english":"divide, distinguish; separate","forms":["separare","sēparat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Magno dolore Aedui ferunt se deiectos principatu, queruntur fortunae commutationem et Caesaris indulgentiam in se requirunt; neque tamen suscepto bello suum consilium ab reliquis {{separare}} audent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sepelio","latin":"sepelio, sepelire, sepelivi, sepultus","headword":"sepelio","letter":"s","pos":"verb","posGroup":"verb","english":"bury/inter; (Romans cremate + inter ashes); submerge, overcome; suppress; ruin","forms":["sepelī","sepeliās","sepeliēns","sepelīret","sepelīrī","sepeliunt","sepelīvissent","sepelīvit","sepultū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ubi sēnsit mortem sibi imminēre, arcessītō Iōsēphō dīxit: sī mē amās, iūra tē id factūrum esse quod ā tē petam, scīlicet ut nē mē {{sepeliās}} in Aegyptō, sed corpus meum trānsferās ex hāc regiōne, et condās in sepulcrō maiōrum meōrum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sepelire","latin":"sepelīre","headword":"sepelīre","letter":"s","pos":"verb","posGroup":"verb","english":"to bury","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"seplasium","latin":"seplasium, seplasi(i)","headword":"seplasium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"perfume; Seplasian unguent","forms":["sēplasium"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Onerävî rūrsus vînum, lārdum, fabam, {{sēplasium}}, mān- “Hôc locô Fortūnāta rem piam fécit: omne enim aurum suum, omnia vestîmenta vēndidit, et mî centum aureôs in manū posuit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sepono","latin":"sepono, seponere, seposui, sepositus","headword":"sepono","letter":"s","pos":"verb","posGroup":"verb","english":"put away from one; disregard; isolate; reserve","forms":["sēpōnī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tunc iussit angelus fel piscis sēpōnī, utpote medicāmentum salūtāre; deinde partem carnis coxērunt comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"septem","latin":"septem","headword":"septem","letter":"s","pos":"numeral","posGroup":"numeral","english":"seven","forms":["septem","septēnōs","septima","Septimae","septimam","septimō","septimum","septimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi {{septima}} legio constiterat, hostes pelluntur atque in fugam coiciuntur; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"september","latin":"September, Septembris","headword":"September","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"September; (7th month before Caesar, 9th after); abb. Sept.","forms":["September","Septembrī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Annus in duodecim mēnsēs dīviditur, quibus haec sunt nōmina: Iānuārius, mēnsis prīmus; Februārius, secundus; Mārtius, tertius; Aprīlis, quārtus; Maius, quīntus; Iūnius, sextus; Iūlius, septimus; Augustus, octāvus; {{September}}, nōnus; Octōber, decimus; November, ūndecimus; December, mēnsis duodecimus ac postrēmus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"septenarius","latin":"septenarius, septenaria, septenarium","headword":"septenarius","letter":"s","pos":"adjective","posGroup":"adjective","english":"containing seven","forms":["septēnāriī","septēnārius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sēnāriī sunt versūs quī in sēnōs pedēs dīviduntur, septēnāriī quī septēnōs pedēs continent.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"septendecim","latin":"septendecim","headword":"septendecim","letter":"s","pos":"numeral","posGroup":"numeral","english":"seventeen","forms":["septendecim"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus: “... quīndecim, sēdecim, {{septendecim}}, duodēvīgintī, ūndēvīgintī, vīgintī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"septeni","latin":"septēnī, -ae, -a","headword":"septēnī","letter":"s","pos":"","posGroup":"other","english":"seven (each)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"septentrio","latin":"septentrio, septentrionis","headword":"septentrio","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Big/Little Dipper (s./pl.); north, north regions/wind; brooch w/7 stones","forms":["septentriōnem","septentriōnēs","septentrionibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Erat a {{septentrionibus}} collis, quem propter magnitudinem circuitus opere circumplecti non potuerant nostri; necessario paene iniquo loco et leniter declivi castra fecerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"septentrionalis","latin":"septentrionālis, -e (< septentriōnēs, ll.16, 50)","headword":"septentrionālis","letter":"s","pos":"","posGroup":"other","english":"northern","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"septentriones","latin":"septentriōnēs, septentriōnum","headword":"septentriōnēs","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m. pl.) north","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"septies","latin":"septies","headword":"septies","letter":"s","pos":"adverb","posGroup":"adverb","english":"seven times","forms":["septiēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum arca {{septiēs}} circumlāta esset, mūrī et turrēs īlicō corruērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"septimus","latin":"septimus, -a, -um","headword":"septimus","letter":"s","pos":"","posGroup":"other","english":"seventh","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"septingent","latin":"septingent","headword":"septingent","letter":"s","pos":"numeral","posGroup":"numeral","english":"seven hundred","forms":["septingenta","septingentēsimō","septingenti","septingentōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Eo die milites sunt paulo minus {{septingenti}} desiderati.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"septingenti","latin":"septingentī, -ae, -a","headword":"septingentī","letter":"s","pos":"","posGroup":"other","english":"seven hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"septuagesimus","latin":"septuāgēsimus, -a, -um","headword":"septuāgēsimus","letter":"s","pos":"","posGroup":"other","english":"seventieth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"septuaginta","latin":"septuāgintā","headword":"septuāgintā","letter":"s","pos":"numeral","posGroup":"numeral","english":"seventy","forms":["septuāgēsimō","septuāgēsimum","septuāgintā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Captīvitās Babylōnica per septuāgintā annōs dūrāvit, idque praedīxerat Deus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"septuennis","latin":"septuennis, septuennis, septuenne","headword":"septuennis","letter":"s","pos":"adjective","posGroup":"adjective","english":"of seven years","forms":["septuennēs","Septuennis"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam iam puerī {{septuennēs}} sunt, pater onerāvit nāvem magnam multīs mercibus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sepulcrum","latin":"sepulcrum, -ī","headword":"sepulcrum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"tomb, grave; grave, tomb","forms":["sepulcra","sepulcrī","sepulcrīs","sepulcrō","sepulcrum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed Iacobus nōluit accipere cōnsōlātiōnem, dīxitque: ego dēscendam moerēns cum fīliō meō in {{sepulcrum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sepultus","latin":"sepultus, -a, -um","headword":"sepultus","letter":"s","pos":"adjective","posGroup":"adjective","english":"buried","forms":["sepultae","sepultī","sepultīs","sepultōs","sepultus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nōn sōlum ille opem fert, sed etiam sapiēns vetuit mīlitēs suōs urbem captam vāstāre; mortuīs {{sepultīs}} pācem in terrā tōtā fēcit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sequana","latin":"Sequana, Sequanae","headword":"Sequana","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Seine, river in N Cen. Gaul - in Caesar's \"Gallic War\"","forms":["Sequanae","Sequanam","Sequanis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Id est oppidum Parisiorum, quod positum est in insula fluminis {{Sequanae}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sequanus","latin":"Sequanus, Sequani","headword":"Sequanus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sequani, tribe in E. Gaul - in Caesar's \"Gallic War\"","forms":["Sequanos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Labienum duabus cum legionibus et equitatu in {{Sequanos}} proficisci iubet; huic M.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sequens","latin":"sequens, (gen.), sequentis","headword":"sequens","letter":"s","pos":"adjective","posGroup":"adjective","english":"following; next","forms":["sequēns"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Sequēns}} viam secundum ōram, Thēseus vēnit ad montēs altōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sequentia","latin":"sequentia, sequentiae","headword":"sequentia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sequence","forms":["sequentia"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nērēides nymphaeque simul, quae vellera mōtīs\nnūlla trahunt digitīs nec fīla {{sequentia}} dūcunt,\nherbās dispōnunt sparsōsque sine ōrdine flōrēs\nsēcernunt calathīs variāsque colōribus herbās;\nipsa, quod hae faciunt, opus exigit, ipsa, quis ūsus\nquōve sit in foliō, quae sit concordia mixtīs,\nnōvit et advertēns pensās examinat herbās.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sequi","latin":"sequī","headword":"sequī","letter":"s","pos":"verb","posGroup":"verb","english":"to follow","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"sequitur","latin":"sequitur, sequī","headword":"sequitur","letter":"s","pos":"verb","posGroup":"verb","english":"follow; follows","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"sequor","latin":"sequor, sequī, secūtus sum","headword":"sequor","letter":"s","pos":"verb","posGroup":"verb","english":"follow","forms":["secūta","secūtae","secuti","secūtum","secūtūra","secūtūrae","secutus","sequāmur","sequar","sequāre","sequāris","sequātur","sequebantur","sequēbātur","sequēminī","sequēmur","sequendi","sequente","sequentem","sequentēs","Sequentī","sequentibus","sequentis","sequentium","sequentur","sequere","sequerentur","sequerētur","sequētur","sequi","Sequiminī","sequimur","sequitur","sequor","sequuntur","SEQVATVR"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed elati spe celeris victoriae et hostium fuga et superiorum temporum secundis proeliis, nihil adeo arduum sibi esse existimaverunt quod non virtute consequi possent, neque finem prius {{sequendi}} fecerunt quam muro oppido portisque appropinquarunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ser","latin":"Ser., abb.","headword":"Ser","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Servius (Roman praenomen); (abb. Ser.)","forms":["ser"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"et centum dūrīs postibus obde {{ser}}ás!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sera","latin":"sera, serae","headword":"sera","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"bar (for fastening doors); rail of post and rail fence; lock (Cal)","forms":["sērā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Seu té forte iuvat sērā et","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sereno","latin":"sereno, serenare, serenavi, serenatus","headword":"sereno","letter":"s","pos":"verb","posGroup":"verb","english":"clear up, brighten; lighten","forms":["serēnat","serēnō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nocte silentī lūna et plūrimae stēllae in caelō serēnō lūcēbant; ovēs dormiēbant; Comātās vērō nōn dormiēbat, sed in altō saxō sedēns, dum ovēs cūstōdit, lūnam et stēllās in caelō sine nūbibus lūcentēs spectābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"serenum","latin":"serenum, sereni","headword":"serenum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"fair weather","forms":["serēnum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hodiē caelum {{serēnum}} et ventus secundus est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"serenus","latin":"serēnus, -a, -um","headword":"serēnus","letter":"s","pos":"adjective","posGroup":"adjective","english":"clear, cloudless; clear, calm","forms":["serēna"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Rōmānī iuvenēs, postquam ex tam turbidō diē {{serēna}} et tranquilla lūx rediit, ubi vacuam sēdem rēgiam vīdērunt, velut sī orbī factī essent, maestī aliquamdiū siluērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"serere","latin":"(serō) serere, sēvisse, satum","headword":"serere","letter":"s","pos":"verb","posGroup":"verb","english":"sow; to sow","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"seria","latin":"seria, seriae","headword":"seria","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"large earthenware jar","forms":["seria"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Quin versus iocosos recitas nobis?\" Cui Iulius \"At Catullus\" inquit \"non tantum carmina {{seria}}, sed etiam iocosa scripsit.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"series","latin":"series, seriei","headword":"series","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"row, series, secession, chain, train, sequence, order (gen lacking, no pl.)","forms":["seriēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fortia facta patrum, {{seriēs}} longissima rērum","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"serio","latin":"serio","headword":"serio","letter":"s","pos":"adverb","posGroup":"adverb","english":"seriously, in earnest","forms":["sēriō"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"SOSIA: [ad Alcumēnam] Nunc quidem praeter nōs nēmō est—dīc mihi vērum sēriō:","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"serit","latin":"serit","headword":"serit","letter":"s","pos":"verb","posGroup":"verb","english":"sows","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"serius","latin":"sērius, -a, -um","headword":"sērius","letter":"s","pos":"adjective","posGroup":"adjective","english":"serious; rather late, too late","forms":["sēriae","sēriīs","sērius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"adv sērō, comp {{sērius}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sermo","latin":"sermō, sermōnis","headword":"sermō","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) conversation; conversation, talk; talk, conversation","forms":["sermō","sermōne","sermōnem","sermōnēs","sermōnī","sermōnibus","sermōnis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Semper dēlector cum legō {{sermōnēs}} illōs clārissimōs, quamquam multa sunt in iīs quae ego nōn bene intellegō; neque Aristotelēs, discipulus Platōnis doctissimus, facilior Aristotelēs -is esse mihi vidētur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sero","latin":"sērō","headword":"sērō","letter":"s","pos":"verb","posGroup":"verb","english":"late, too late","forms":["sata","satum","saturās","serat","serendum","serendus","serere","sererent","serit","seritur","sērō","sertīs","serunt","sēvisse"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipsa hominibus sēmina largīta est atque mōnstrāvit quōmodo in agrōs spargerent ac {{sererent}}, ut terra magnam frūmentī cōpiam ferret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"serpens","latin":"serpēns, -entis (m.)","headword":"serpēns","letter":"s","pos":"noun; noun (f.)","posGroup":"noun","english":"snake, serpent; snake","forms":["serpēns","serpente","serpentem","serpentēs","serpentī","serpentibus","serpentis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Serpēns}}, quī erat callidissimum omnium animantium, dīxit mulierī: cūr nōn comedis frūctum istīus arboris?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"serra","latin":"serra, serrae","headword":"serra","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"saw","forms":["serrā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ad impietātem accessit crūdēlitās: cum enim Isaliī s prophēta Īram dīvīnam illī dēnūntiāsset, rēx furōre percitus prophētam serrā ligneā secarī iussit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"serta","latin":"serta, sertae","headword":"serta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"garland, wreath, festoon","forms":["serta"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Eōrum inter rāmōs etiamnunc incolae illīus locī flōrum {{serta}} pōnere solent.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"serus","latin":"sērus, -a, -um","headword":"sērus","letter":"s","pos":"adjective","posGroup":"adjective","english":"late","forms":["sērae","sērē","sērior","serīs","sērus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Samsōn mediā nocte surrēxit, vēnitque ad portam urbis, quam cum invēnisset clausam, umerīs sustulit cum postibus et {{serīs}}, atque in verticem montis vicīnī supportāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"serva","latin":"serva, -ae","headword":"serva","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"female slave","forms":["servā"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"“Intrā līmen iacet” respondet aliquis, “Tū servā dominum tuum!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"servans","latin":"servans, servantis (gen.), servantior -or -us, servantissimus -a -um","headword":"servans","letter":"s","pos":"adjective","posGroup":"adjective","english":"ready to maintain (law/principle)","forms":["servāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vix ē cōnspectū Siciliae in altum vēla dabant laetī, cum Iūnō, aeternum vulnus sub pectore {{servāns}}, haec sēcum cōgitāvit: 'Mēne rēgem Teucrōrum ab Italiā āvertere nōn posse?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"servare","latin":"servāre","headword":"servāre","letter":"s","pos":"verb","posGroup":"verb","english":"to save, keep; to save, preserve","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"servat","latin":"servat","headword":"servat","letter":"s","pos":"verb","posGroup":"verb","english":"saves, preserves","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"servator","latin":"servātor, -ōris (m.)","headword":"servātor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"savior; saviour","forms":["servātōrem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōrum agmen imperātor secūtus — prōsequentibus cūnctīs '{{servātōrem}}' 'līberātōrem'que acclāmantibus — eādem quā vēnerat viā Elatēam rediit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"servatrix","latin":"servatrix, servatricis","headword":"servatrix","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"female preserver, protecotress","forms":["servātrīx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tum apud Graecōs perque urbēs eōrum honōrābor {{servātrīx}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"servilis","latin":"servīlis, -e","headword":"servīlis","letter":"s","pos":"adjective","posGroup":"adjective","english":"of a slave, servile","forms":["servīle","servīlem","servīlī","Servīlia","Servīlium"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vestītum {{servīlem}} gerēns atque in fōrmam Sōsiae servī commūtātus nūllō modō deī similis est—nisi quod pinnulae, quās in petasō gerit, significant eum esse Mercurium.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"servio","latin":"serviō, -īre, servīvī","headword":"serviō","letter":"s","pos":"verb","posGroup":"verb","english":"be a slave to (+ dat.)","forms":["serviēbam","serviēbās","servientibus","serviō","servīre","servīret","servit","servītis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mēdus: \"Num Rōmae māvīs {{servīre}} quam liber esse in Graeciā?\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"servire","latin":"(serviō) servīre, -īvisse/iisse,  -ītum  ({i}+ dat.{/i})","headword":"servīre","letter":"s","pos":"verb","posGroup":"verb","english":"be a slave to, serve; to serve (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"servitium","latin":"servitium, -ī","headword":"servitium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"slavery; slavery, subjection","forms":["servitia","servitiī","servitiō","Servitium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[{{Servitium}} et mīlitia amōris] umbráculum","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"servitus","latin":"servitūs, servitūtis","headword":"servitūs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) slavery","forms":["servitute","servitutem","servituti","servitūtis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Haec si gravia aut acerba videantur, multo illa gravius aestimare, liberos, coniuges in {{servitutem}} abstrahi, ipsos interfici; quae sit necesse accidere victis.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"servius","latin":"Servius, Servi","headword":"Servius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Servius (Roman praenomen); (abb. Ser.)","forms":["Serviī","Servium","Servius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Duodēquadrāgēsimō fermē annō ex quō rēgnāre coeperat Tarquinius, nōn apud rēgem modō, sed apud patrēs plēbemque in maximō honōre {{Servius}} Tullius erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"servo","latin":"servō, servāre","headword":"servō","letter":"s","pos":"verb","posGroup":"verb","english":"preserve, save; save, protect; to save, keep, preserve","forms":["servābant","servābat","servābātur","servābit","servābitur","servābō","servanda","servandam","servandī","servandōs","servant","servantī","servantur","servare","servārēmur","servārent","servāret","servārētur","servārī","servat","servāta","servātam","servātās","servāte","servātī","servātīs","servātōs","servātum","servātur","servātūram","servātūrōs","servātus","servāveram","servāverant","servāverat","servāvēre","servāverīs","servāverit","servāvērunt","servāvī","servāvissent","servāvistī","servāvit","servēs","servet","servētis","servetur","servō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"His collocatis et coagmentatis alius insuper ordo additur, ut idem illud intervallum {{servetur}} neque inter se contingant trabes, sed paribus intermissae spatiis singulae singulis saxis interiectis arte contineantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"servulus","latin":"servulus, servuli","headword":"servulus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"young slave","forms":["servulum","servulus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sī vîxerit, habēbis ad latus {{servulum}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"servus","latin":"servus, -ī","headword":"servus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"slave, servant; slave; servant, slave","forms":["serve","servī","servīs","servōrum","servōs","servum","servus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Libanus est {{servus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sescent","latin":"sescent","headword":"sescent","letter":"s","pos":"numeral","posGroup":"numeral","english":"six hundred","forms":["sēscenta","sescentēsimō","sēscentī","sescentīs","sescentos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta produci, {{sescentos}} obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sescentesimus","latin":"sescentēsimus, -a, -um","headword":"sescentēsimus","letter":"s","pos":"","posGroup":"other","english":"six hundreth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sescenti","latin":"sescentī, -ae, -a","headword":"sescentī","letter":"s","pos":"","posGroup":"other","english":"six hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sese","latin":"sēsē","headword":"sēsē","letter":"s","pos":"","posGroup":"other","english":"intensive form of sē","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sestertium","latin":"sestertium, sestertii","headword":"sestertium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"1000 sestertii; two and a half feet; (measure of depth/width)","forms":["sēstertia","sēstertium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mēdus: \"Certē praedōnēs pecūniam tibi ēripient, sed fēlīx eris sī pecūniae grātia vītae tuae parcent.\" Gubernātor: \"Sī necesse erit, decem mīlia {{sēstertium}} praedōnibus offerre possum.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sestertius","latin":"sēstertius, -ī","headword":"sēstertius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sesterce (coin)","forms":["sēstertiī","sēstertiīs","sēstertiō","sēstertiōs","sēstertius","SESTERTIVM"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Pretium hārum rosārum est duo sēstertiī tantum.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"setius","latin":"setīus","headword":"setīus","letter":"s","pos":"adverb","posGroup":"adverb","english":"nonetheless","forms":["sētius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ille nihilō {{sētius}} exercituī posteā praefuit rēsque in Āfricā gessit ūsque ad P.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"seu","latin":"seu","headword":"seu","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"or if, or (sive…sive)","forms":["seu","sēv"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Postero die Vercingetorix concilio convocato id bellum se suscepisse non suarum necessitatum sed communis libertatis causa demonstrat et, quoniam sit fortunae cedendum, ad utramque rem se illis offere, {{seu}} morte sua Romanis satisfacere seu vivum tradere velint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"severitas","latin":"severitas, severitatis","headword":"severitas","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"strictness, severity","forms":["sevēritās","severitatem","sevēritātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Summae diligentiae summam imperi {{severitatem}} addit; magnitudine supplici dubitantes cogit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"severus","latin":"sevērus, -a, -um","headword":"sevērus","letter":"s","pos":"adjective","posGroup":"adjective","english":"stern, severe; strict, severe","forms":["sevēra","sevēram","sevērē","sevērī","sevērior","severiorum","sevērissimam","sevērissimē","sevērissimī","sevērissimus","sevērius","sevērō","sevērōs","sevērum","sevērus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Servī autem quiētī nōn sunt, sed canunt et rīdent, quia dominum nōn vident; servī enim dominum {{sevērum}} ā vīllā abesse putant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"seviratus","latin":"seviratus, seviratus","headword":"seviratus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sexvirate; the position of a sevir; a member of a board of six men","forms":["SEVIRATVS"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Înscrîptiô quoque vidē dîligenter sī haec satis idônea HVIC {{SEVIRATVS}} ABSEN'Ī'Ī DECRETVS EST CVM POSSET IN OMNIBVS DECVRĪĪS RŌMAE ESSE PIVS FORTIS FIDĒLIS EX PARVŌ CRĒVIT SESTERTIVM RELIQVIT TRECENTIĒS NEC VMQVAM PHILOSOPHVM AVDĪVIT Haec ut dîxit Trimalchiô, ﬂëre coepit ūbertim.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sevoco","latin":"sevoco, sevocare, sevocavi, sevocatus","headword":"sevoco","letter":"s","pos":"verb","posGroup":"verb","english":"call aside; remove; separate","forms":["Sēvocābō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sēvocābō erum. [Clārā vōce] Menaechme!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sex","latin":"sex","headword":"sex","letter":"s","pos":"numeral","posGroup":"numeral","english":"six","forms":["sēna","sēnōs","sex","sexiēs","sextā","Sexte","Sextī","sextō","sextum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive {{sex}} in altitudinem pedum atque ita viis patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sexagesimus","latin":"sexāgēsimus, -a, -um","headword":"sexāgēsimus","letter":"s","pos":"","posGroup":"other","english":"sixtieth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sexaginta","latin":"sexāgintā","headword":"sexāgintā","letter":"s","pos":"numeral","posGroup":"numeral","english":"sixty","forms":["sexāgēsimō","sexāgēsimum","sexāgintā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Venit igitur in IŪdaeam cum sexāgintā quīnque hominum mīlibus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sexennis","latin":"sexennis, sexennis, sexenne","headword":"sexennis","letter":"s","pos":"adjective","posGroup":"adjective","english":"six years old","forms":["sexennem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nam, commundätîs ad symphôniam mënsîs, très albī suēs in triclînium adductî sunt, capistrîs et tintin- näbulîs cultî, quôrum ūnum ‘bîmum’ nômenclätor esse dîcëbat, alterum ‘trîmum’, tertium vërô iam ‘{{sexennem}}’.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sexies","latin":"sexiēs","headword":"sexiēs","letter":"s","pos":"","posGroup":"other","english":"six times","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sextilis","latin":"Sextilis, Sextilis, Sextile","headword":"Sextilis","letter":"s","pos":"adjective","posGroup":"adjective","english":"August (month/mensis understood); abb. Sext.??; renamed to Julius in 44 BC","forms":["Sextīlis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Item mēnsī Augustō nōmen erat \"{{Sextīlis}}\", quia sextus erat; nunc Augustus nōminātur ā Caesare.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sextius","latin":"Sextius, Sexti","headword":"Sextius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sextius; (Roman gens name); [Quintus ~ => Augustian philosopher]","forms":["Sextio","Sextium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"{{Sextium}} legatum, quem minoribus castris praesidio reliquerat, misit, ut cohortes ex castris celeriter educeret et sub infimo colle ab dextro latere hostium constitueret, ut, si nostros loco depulsos vidisset, quo minus libere hostes insequerentur terreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sextus","latin":"sextus, -a, -um","headword":"sextus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sixth","forms":["Sext","sextus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Libanus: “In familiā Cornēliī nōn trēs, sed duo līberī sunt: ūna fīlia, Cornēlia, et ūnus fīlius, {{Sextus}}.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sexus","latin":"sexus, sexus","headword":"sexus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sex; (male or female); sexual organs","forms":["sexus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ita fit ut Rōmānī, cum iūrant, alium deum virī, alium mulierēs appellent, Pollūcem vērō uterque {{sexus}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"si","latin":"sī","headword":"sī","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"if","forms":["si"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, {{si}} flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sibylla","latin":"Sibylla, -ae","headword":"Sibylla","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"the Sibyl, a prophetess","forms":["Sibyllae","Sibyllam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"[Aenēās] . . . loca fēta palustribus undīs,\nlītora Cūmārum vīvācisque antrā {{Sibyllae}}\nintrat, et [ut] ad mānēs veniat per Averna paternōs\nōrat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sibyllinus","latin":"Sibyllinus, Sibyllina, Sibyllinum","headword":"Sibyllinus","letter":"s","pos":"adjective","posGroup":"adjective","english":"of or connected with a sibyl, sibylline","forms":["Sibyllīnī","Sibyllīnīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"In antīquīs annalibus memoria super librīs {{Sibyllīnīs}} haec prōdita est: anus hospita atque incōgnita ad Tarquinium Superbum rēgem adiit novem librōs ferēns quōs esse dīcēbat dīvīna ōrācula: 'eōs velle vēnumdarī'.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sic","latin":"sīc","headword":"sīc","letter":"s","pos":"adverb","posGroup":"adverb","english":"so, thus; thus, so; thus","forms":["sic"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum {{sic}} animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sica","latin":"sica, sicae","headword":"sica","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"dagger","forms":["sīca","sīcārum","sīcīs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quotiēns iam tibi extorta est ista {{sīca}} dē manibus, quotiēns excidit cāsū aliquō et ēlāpsa est!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"siccare","latin":"(siccō) siccāre","headword":"siccāre","letter":"s","pos":"","posGroup":"other","english":"dry, drain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"siccitas","latin":"siccitas, siccitatis","headword":"siccitas","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"dryness; drought; dried up condition","forms":["siccitās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et quômodo {{siccitās}} persevērat!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sicco","latin":"sicco, siccare, siccavi, siccatus","headword":"sicco","letter":"s","pos":"verb","posGroup":"verb","english":"dry, drain; exhaust","forms":["siccābantur","siccāre","siccāret","siccat","siccāta","siccātus","siccō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Dīxit Hebraeīs: “Sī quandō vōs interrogāverint fīliī vestrī, quōrsum spectet ista lapidum congeriēs, respondēbitis: ‘Siccō pede trāiēcimus Iordānem istum: idcircō positī sunt lapidēs ad sempiternam factī memoriam, ut discant quanta sit Deī potentia.’”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"siccum","latin":"siccum, sicci","headword":"siccum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"dry land","forms":["siccum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Tunc Deus Moȳsī: “Prōtende” inquit “dextram tuam in mare, et dīvidē aquās, ut illae Hebraeīs gradientibus iter {{siccum}} praebeant.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"siccus","latin":"siccus, -a, -um","headword":"siccus","letter":"s","pos":"adjective","posGroup":"adjective","english":"dry","forms":["sicca","siccī","siccōs","siccus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nec umquam arborēs sitim patī sinēbat, sed saepe terram aquā flūminum rigābat, nē {{sicca}} fieret: hic amor, hoc studium, Veneris quoque nūlla cupīdō est;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sicera","latin":"sicera, sicerae","headword":"sicera","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"cider; kind of spirituous intoxicating drink; fermented liquor, strong drink","forms":["sīcēram"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Puer crēvit: intōnsam habuit comam, nec vīnum, nec {{sīcēram}} bibit; incrēdibilī fuit corporis rōbore: obvium leōnem manū interfēcit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sicilia","latin":"Sicilia, Siciliae","headword":"Sicilia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Sicily; (large island southwest of Italy)","forms":["Sicilia","Siciliae","Siciliam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ōlim Proserpina, Cereris fīliā virgō, cum aliīs puellīs in campīs {{Siciliae}} laeta errābat lūdēns et aut violās aut candida līlia carpēns, calathōs ac sinum eō cōnsiliō implēbat, ut cēterās amīcās flōrēs colligendō vinceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"siculus","latin":"Siculus, Sicula, Siculum","headword":"Siculus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Sicilian, of/pertaining to Sicily (island southwest of Italy); cruel; luxurious","forms":["Siculae","Siculam","Siculīs","Siculōrum","Siculum","Sīculus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mēdus et Lȳdia ventō secundō per mare Īnferum nāvigāre pergunt ad fretum {{Siculum}} (id est fretum quō Sicilia ab Italiā disiungitur).","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sicut","latin":"sīcut","headword":"sīcut","letter":"s","pos":"adverb","posGroup":"adverb","english":"just as","forms":["sicut"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Matres familiae de muro vestem argentumque iactabant, et pectore nudo prominentes passis manibus obtestabantur Romanos ut sibi parcerent neu, {{sicut}} Avarici fecissent, ne a mulieribus quidem atque infantibus abstinerent; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sicuti","latin":"sicuti","headword":"sicuti","letter":"s","pos":"adverb","posGroup":"adverb","english":"as, just as; like; in same way; as if; as it certainly is; as it were","forms":["sīcutī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quod ut illī proprium ac perpetuum sit, Quirītēs, cum commūnis salūtis atque imperiī, tum ipsīus hominis causā — sīcutī facitis — velle et optāre debētis.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sidere","latin":"(sīdō) sīdere, sēdisse, sessum","headword":"sīdere","letter":"s","pos":"","posGroup":"other","english":"sit down, settle","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sidereus","latin":"sidereus, siderea, sidereum","headword":"sidereus","letter":"s","pos":"adjective","posGroup":"adjective","english":"starry; relating to stars; heavenly; star-like","forms":["sīdereās","sīdereus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{sīdereus}} -ā -um (« sīdus) : caelestis Nōn ego sīdereās affectō","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sidonius","latin":"Sidonius, Sidonia, Sidonium","headword":"Sidonius","letter":"s","pos":"adjective","posGroup":"adjective","english":"Sidonian; of/from Sidon; Phoenician; Carthaginian","forms":["Sīdōnia","Sīdoniam"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hic templum Iūnōnī ingēns {{Sīdōnia}} Dīdō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sidus","latin":"sīdus, -eris (n.)","headword":"sīdus","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"star, heavenly body","forms":["sīdera","sīdere","sīderis","sīdus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō splendōre coruscē, ō Hyacinthe cui radiant ut {{sīdera}} ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sigillum","latin":"sigillum, sigilli","headword":"sigillum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"seal; statuette; embossed figure, relief; figure in tapestry/from signet ring","forms":["sigillīs","sigillum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{sigillum}} -ī ^ parvum signum vīle","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"signatus","latin":"signātus, -a, -um","headword":"signātus","letter":"s","pos":"","posGroup":"other","english":"marked, sealed","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"significans","latin":"significans, significantis (gen.), significantior -or -us, significantissimus -a -um","headword":"significans","letter":"s","pos":"adjective","posGroup":"adjective","english":"significant, meaningful; conveying meaning; expressive","forms":["significāns"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Nōmen quid est?' Discipulus: 'Pars ōrātiōnis cum cāsū, corpus aut rem propriē {{significāns}}; aut enim ūnīus nōmen est et proprium dīcitur, aut multōrum et appellātīvum.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"significantia","latin":"significantia, significantiae","headword":"significantia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"significance; indication; the act of conveying meaning/information","forms":["significantiā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Magister: 'Comparātiōnis gradūs quot sunt?' Discipulus: 'Trēs.' Magister: 'Quī?' Discipulus: 'Positīvus, ut doctus; comparātīvus, ut doctior; superlātīvus, ut doctissimus.' Magister: 'Quae nōmina comparantur?' Discipulus: 'Appellātīva dumtaxat quālitātem aut quantitātem significantiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"significat","latin":"significat","headword":"significat","letter":"s","pos":"verb","posGroup":"verb","english":"means, signifies","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"significatio","latin":"significātiō, significātiōnis","headword":"significātiō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) meaning, sense; meaning","forms":["Significātiō","significatione","significātiōnem","significātiōnēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Centuriones in oppido, cum ex {{significatione}} Gallorum novi aliquid ab eis iniri consili intellexissent, gladiis destrictis portas occupaverunt suosque omnes incolumes receperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"significo","latin":"significō, significāre","headword":"significō","letter":"s","pos":"verb","posGroup":"verb","english":"indicate, show, mean","forms":["significābātur","significāmus","significant","significare","significārī","significat","significātur","significāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque {{significant}}; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"signo","latin":"signō, signāre","headword":"signō","letter":"s","pos":"verb","posGroup":"verb","english":"mark, inscribe, indicate, notice, seal","forms":["signāre","signat","signātam","signātum","signātus","signāverat","signet","signo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ubi ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum {{signo}} dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"signum","latin":"signum, -ī","headword":"signum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"statue, sign; sign, statue; seal, sign; standard, sign; signal, sign; sign; statue, image","forms":["signa","signī","signis","signōrum","signum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus agitatis, profitentur Carnutes se nullum periculum communis salutis causa recusare, principesque ex omnibus bellum facturos pollicentur; et, quoniam in praesentia obsidibus cavere inter se non possint ne res efferatur, ut iure iurando ac fide sanciatur petunt, collatis militaribus {{signis}}, quo more eorum gravissima caerimonia continetur, ne facto initio belli ab reliquis deserantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"silanus","latin":"silanus, silani","headword":"silanus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"fountain","forms":["Sīlāne","Sīlānum","Sīlānus"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Sīlānus}}, prīmus sententiam rogātus, quod eō tempore cōnsul dēsignātus erat, dē eīs quī in cūstōdiīs tenēbantur et praetereā dē L.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"silentium","latin":"silentium, -ī","headword":"silentium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"silence","forms":["silentia","silentio","silentium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cenabenses paulo ante mediam noctem {{silentio}} ex oppido egressi flumen transire coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sileo","latin":"sileō, silēre","headword":"sileō","letter":"s","pos":"verb","posGroup":"verb","english":"be silent","forms":["silent","silentē","silentēs","silentī","silērī","silet","silētis","silētur","siluērunt","siluit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Per tōtam noctem exspectābant {{silentēs}}, ut Samsōnem māne exeuntem interficerent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"silere","latin":"silēre","headword":"silēre","letter":"s","pos":"verb","posGroup":"verb","english":"be silent","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"silex","latin":"silex, silicis","headword":"silex","letter":"s","pos":"noun","posGroup":"noun","english":"pebble/stone, flint; boulder, stone","forms":["silicī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ac prīmum silicī scintillam excūdit Achātēs,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"siliqua","latin":"siliqua, siliquae","headword":"siliqua","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"pod","forms":["siliquās","siliquīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"\"Et cupiēbat implēre ventrem {{siliquīs}} quās porcī mandūcābant: et nēmō illī dabat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"silus","latin":"silus, sila, silum","headword":"silus","letter":"s","pos":"adjective","posGroup":"adjective","english":"snub-nosed, pug-nosed","forms":["Sīlō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et dīxit eī:\"Vāde, lavā in natātōriā Sīlō ē.\"Abiit ille, et lāvit et vēnit vidēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"silva","latin":"silva, -ae","headword":"silva","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"wood, forest; forest, wood","forms":["silvā","silvae","silvam","silvārum","silvas","silvīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Illi celeriter per exploratores adventu Caesaris cognito carros impedimentaque sua in artiores {{silvas}} abdiderunt, copias omnes in loco edito atque aperto instruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"silvanus","latin":"silvanus, silvani","headword":"silvanus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"gods (pl.)associated with forest and uncultivated land","forms":["Silvānus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Neque igitur Satyrī, neque Pan et {{Silvānus}}, silvārum dī, ad eam accēdere potuerant, etsī nōn parvō amōre accēnsī erant; sed","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"silvestris","latin":"silvestris, -e","headword":"silvestris","letter":"s","pos":"adjective","posGroup":"adjective","english":"of the woods, wild","forms":["silvestri","silvestribus","silvestris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis {{silvestribus}} ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sima","latin":"sima, simae","headword":"sima","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"top molding of a pediment placed above its cornice; ogee (L+S)","forms":["sīma"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{sīma}} — menteés aperit, deō (Bacchō)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"simia","latin":"simia, simiae","headword":"simia","letter":"s","pos":"noun","posGroup":"noun","english":"monkey; ape; (applied to men as term of abuse)","forms":["Sīmia"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Sīmia}} quam similis, turpissima bēstia, nōbīs! [Ennius: Satirae, 69]","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"simile","latin":"simile, similis","headword":"simile","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"comparison; parallel","forms":["simile"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nam quid illi {{simile}} bello fuit?","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"similis","latin":"similis, -e","headword":"similis","letter":"s","pos":"adjective","posGroup":"adjective","english":"similar; like, similar (+ gen. or dat.)","forms":["similem","similēs","simili","similia","similior","similiōrem","similis","similius","simillima","simillimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Simili}} ratione ibi Vercingetorix, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"similiter","latin":"similiter","headword":"similiter","letter":"s","pos":"adverb","posGroup":"adverb","english":"similarly","forms":["similiter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Respondit Andreās, linus ex discipulīs:\"Est puer hic, quī habet quīnque pānēs et duōs piscēs, sed quid sunt inter tot hominēs?\"Accēpit ergō Iēsus pānēs et, cum grātiās ēgisset, distribuit: {{similiter}} et ex piscibus quantum volēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"similitudo","latin":"similitudo, similitudinis","headword":"similitudo","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"likeness, imitation; similarity, resemblance; by-word (Plater); parable","forms":["similitudine","similitūdinem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi {{similitudine}} armorum vehementer nostros perterruerunt, ac, tametsi dextris umeris exsertis animadvertebantur, quod insigne pactum esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"simius","latin":"simius, simii","headword":"simius","letter":"s","pos":"noun","posGroup":"noun","english":"ape","forms":["SIMIO","simiōrum","simiōs","sīmius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"DE {{SIMIO}} IMPERATORE","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"simplex","latin":"simplex, (gen.), simplicis","headword":"simplex","letter":"s","pos":"adjective","posGroup":"adjective","english":"single; simple, unaffected; plain","forms":["simplex"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ille fuit vēnātor strēnuus, hic autem placidus et {{simplex}} mōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"simplicitas","latin":"simplicitas, simplicitatis","headword":"simplicitas","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"simplicity, candor","forms":["simplicitās","simplicitātis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tanta {{simplicitās}} eī adfuit, haec iactūra virginēum dolōrem mōvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"simpliciter","latin":"simpliciter, simplicius, simplicissime","headword":"simpliciter","letter":"s","pos":"adverb","posGroup":"adverb","english":"simply/just; w/out complexity; candidly/openly/frankly; innocently; as one item","forms":["simpliciter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{simpliciter}} positae, scaena sine arte fuit;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"simul","latin":"simul","headword":"simul","letter":"s","pos":"adverb","posGroup":"adverb","english":"at the same time","forms":["simul"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quem {{simul}} atque oppidani conspexerunt atque in spem auxili venerunt, clamore sublato arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"simul atque","latin":"simul atque","headword":"simul atque","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"as soon as","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"simula","latin":"simula, simulae","headword":"simula","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"normal flour produced from triticum; finest wheat flour (L+S)","forms":["simulā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"excute nūllum pulverem! : simulā tē","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"simulac","latin":"simulac","headword":"simulac","letter":"s","pos":"adverb","posGroup":"adverb","english":"as soon as, the moment that","forms":["simulac"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"simul ut 7 {{simulac}} | sibi dīxit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"simulacrum","latin":"simulācrum, -ī","headword":"simulācrum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"image, statue","forms":["simulācra","simulācrīs","simulācrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postrēmō Domitiānus templum Iovis Capitōlīnī incendīō cōnsūmptum refēcit atque tantīs dīvitiīs exōrnāvit ut nihil magnificentius fierī posset: aurō et gemmīs splendet tēctum, quod plūrimīs columnīs ē marmore pulcherrimō factīs sustinētur; intus in cellā, templō clausus post forēs aurō opertās, ingēns {{simulācrum}} Iovis in altā sēde sedentis positum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"simulans","latin":"simulans, (gen.), simulantis","headword":"simulans","letter":"s","pos":"adjective","posGroup":"adjective","english":"imitating","forms":["simulāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille aurī cupidus Sychaeum ante āram clam necāvit factumque diū cēlāvit et multa {{simulāns}} viduam maestam falsā spē ēlūsit.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"simulare","latin":"(simulō) simulāre","headword":"simulāre","letter":"s","pos":"","posGroup":"other","english":"imitate, copy, pretend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"simulatio","latin":"simulatio, simulationis","headword":"simulatio","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"pretense, deceit","forms":["simulātiō","simulatione"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci deque his stramenta detrahi mulionesque cum cassidibus equitum specie ac {{simulatione}} collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"simulator","latin":"simulator, simulatoris","headword":"simulator","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"one who copies or imitates; feigner","forms":["simulātor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"615 Saepe tamen vérée coepit {{simulātor}} amáre;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"simulatque","latin":"simulatque","headword":"simulatque","letter":"s","pos":"adverb","posGroup":"adverb","english":"as soon as, the moment that","forms":["Simulatque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Simulatque}} enim sē īnflexit hic rēx in dominātum iniūstiōrem, fit continuō tyrannus, quō neque taetrius neque foedius nec dīs hominibusque invīsius animāl ūllum cōgitārī potest — quī, quamquam figūra est hominis, mōrum tamen immānitāte vāstissimās vincit bēluās!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"simulo","latin":"simulō, -āre","headword":"simulō","letter":"s","pos":"verb","posGroup":"verb","english":"imitate, copy, pretend, take the form of","forms":["simulābat","simulābō","simulanda","simulandam","simulant","simulantēs","simulāret","simulat","simulātum","simulātus","simulāverant","simulāvit","simulent","simulet"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At vir fortissimus cibum vetitum respuēbat indignāns; quam ob rem cum ad supplicium dūcerētur, suī eum amicī hortābantur, ut aliam camem, quam attulerant, comedendō, {{simulāret}} sē regī pāruisse, sīcque mortem vltāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"simultas","latin":"simultās, -ātis ( f.)","headword":"simultās","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"enmity, quarrel; enmity, feud","forms":["simultās","simultātium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tarquinius Gabiōs tamquam in suum regnum profectus ab ultōribus veterum {{simultātium}}, quās sibi ipse caedibus rapīnīsque concīverat, est interfectus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"simus","latin":"simus, sima, simum","headword":"simus","letter":"s","pos":"adjective","posGroup":"adjective","english":"flatnosed, snub-nosed; having flattened nose; flatten/splayed (nose/other)","forms":["sīmus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Frātrēs Iōsēphī respondērunt dispēnsātōrī: istud sceleris longē ā nōbīs aliēnum est; nōs, ut tūtē scīs, retulimus bonā fide pecūniam repertam in saccīs; tantum abest ut fūrātī {{sīmus}} scyphum dominī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sin","latin":"sīn","headword":"sīn","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"but if","forms":["sīn"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Sī rēctē faciēs, recipiēs mercēdem; {{sīn}} autem male, luēs poenam peccātī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sincerus","latin":"sincerus, sincera -um, sincerior -or -us, sincerissimus -a -um","headword":"sincerus","letter":"s","pos":"adjective","posGroup":"adjective","english":"clean, pure, uninjured, whole; sound, genuine, truthful, candid, sincere","forms":["sincērī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Admīrandum sānē vērī ac sincērī ergā inimīcum amōris exemplum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sindon","latin":"sindon, sindonis","headword":"sindon","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"muslin; woven material of fine texture; fine linen (Vulgate)","forms":["sindone","sindonem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quī mercātus est {{sindonem}}, et dēpōnēns eum ē cruce, involvit sindone et posuit in monumentō, et advolvit lapidem ad ōstium monumenfī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sine","latin":"sine","headword":"sine","letter":"s","pos":"preposition","posGroup":"preposition","english":"(prp. + abl.) without","forms":["sine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Id esse facile, quod neque legiones audeant absente imperatore ex hibernis egredi neque imperator {{sine}} praesidio ad legiones pervenire possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sinere","latin":"(sinō) sinere, sīvisse, situm","headword":"sinere","letter":"s","pos":"","posGroup":"other","english":"allow","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"singularis","latin":"singulāris (numerus)","headword":"singulāris","letter":"s","pos":"adjective","posGroup":"adjective","english":"singular; single, singular, unique","forms":["singulāre","singularem","singulari","singulāris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne {{singulari}} quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"singuli","latin":"singulī, -ae, -a","headword":"singulī","letter":"s","pos":"adjective","posGroup":"adjective","english":"one at a time; one each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"singulus","latin":"singulus, singula, singulum","headword":"singulus","letter":"s","pos":"adjective","posGroup":"adjective","english":"apiece (pl.); every; one each/at a time; individual/separate/single; several","forms":["singula","singulae","singulas","singuli","singulis","singulos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus tormentis necat, leviore de causa auribus desectis aut {{singulis}} effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sinister","latin":"sinister, -tra, -trum","headword":"sinister","letter":"s","pos":"adjective","posGroup":"adjective","english":"left, f. the left (hand); left (hand); left, adverse","forms":["sinistrae","sinistram","sinistrīs","sinistro","sinistrōs","sinistrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi septima legio constiterat, hostes pelluntur atque in fugam coiciuntur; ab {{sinistro}}, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sinistra","latin":"sinistra, sinistrae","headword":"sinistra","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"left hand","forms":["sinistrā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Manū dextrā gladium gerit, scūtum gerit manū sinistrā.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"sino","latin":"sino, sinere, sivi, situs","headword":"sino","letter":"s","pos":"verb","posGroup":"verb","english":"allow, permit","forms":["sinam","sinant","sinās","sinat","sinātis","sinēbat","sinere","sinerent","sineret","sinet","sinit","Sinite","sinitur","sinō","sinunt","sīverīs","sīvī","sīvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tē ōrō atque obsecrō ut {{sinās}} puerum abīre, mēque prō eō addīcās in servitūtem; ego poenam, quā dignus est, mihi sūmō et exsolvam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sinum","latin":"sinum, sini","headword":"sinum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"bowl for serving wine, etc","forms":["sinum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ōlim Proserpina, Cereris fīliā virgō, cum aliīs puellīs in campīs Siciliae laeta errābat lūdēns et aut violās aut candida līlia carpēns, calathōs ac {{sinum}} eō cōnsiliō implēbat, ut cēterās amīcās flōrēs colligendō vinceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sinus","latin":"sinus","headword":"sinus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"fold, bosom; fold, bosom, breast","forms":["sinis","sinū","sinus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Duōs igitur īnfantēs, quī nōndum ambulāre poterant, in sinū suō portāns per variās terrās errābat et valdē fessa erat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sinus -us","latin":"sinus -ūs","headword":"sinus -ūs","letter":"s","pos":"","posGroup":"other","english":"(m.) fold (of toga)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"siquidem","latin":"sīquidem","headword":"sīquidem","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"seeing that, since","forms":["siquidem"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Magister: 'Dā causālēs!' Discipulus: 'Sī, etsī, {{siquidem}}, quandō, nam, namque, etenim, quamobrem.' Magister: 'Dā ratiōnālēs!' Discipulus: 'Itaque, enim, quia, quāpropter, quoniam, ergō, ideō, igitur, scīlicet, proptereā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"siren","latin":"Siren, Sirenos/is","headword":"Siren","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Siren; (lured sailors with song); type of drone/solitary bee/wasp)","forms":["Sīren"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Sīren}} -enis f, pl Gr -ēnēs: IĪ virginēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sirenes","latin":"Sīrēnēs, -um","headword":"Sīrēnēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"the Sirens, whose song lures sailors","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"sirius","latin":"Sirius, Siria, Sirium","headword":"Sirius","letter":"s","pos":"adjective","posGroup":"adjective","english":"of the dog-star/Sirius","forms":["Siria"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Iūlia: “{{Siria}}...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sistere","latin":"(sistō) sistere, stetisse, statum","headword":"sistere","letter":"s","pos":"","posGroup":"other","english":"halt, stop","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sisto","latin":"sisto, sistere, stiti, status","headword":"sisto","letter":"s","pos":"verb","posGroup":"verb","english":"stop, check; cause to stand; set up","forms":["siste","sistere","sisterent","sistī","stitisse"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum nympha Arethūsa caput ex undīs tulit et comās ā fronte ad aurēs remōvit atque ait: \"Ō māter fīliae raptae et frūgum, {{siste}} immēnsōs labōrēs tuōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sitiens","latin":"sitiens, (gen.), sitientis","headword":"sitiens","letter":"s","pos":"adjective","posGroup":"adjective","english":"thirsting, producing thirst, arid, dry, parched, thirsty (for)","forms":["sitiēns","sitientēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quae simul ārentī {{sitientēs}} hausimus ōre,\net tetigit summōs virgā dea dīra capillōs,\n(et pudet et referam) saetīs horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\nmurmur et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla tumēre torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sitio","latin":"sitio, sitire, sitivi, -","headword":"sitio","letter":"s","pos":"verb","posGroup":"verb","english":"be thirsty","forms":["sitiēbat","sitiō","sitīre"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quamquam vērō {{sitiēbat}} et ēsuriēbat, neque aquam invenīre poterat, neque quisquam cibum eī largīrī volēbat: omnēs enim Iūnōnem īrātam metuēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sitire","latin":"(sitiō) sitīre, -īvisse, -ītum","headword":"sitīre","letter":"s","pos":"","posGroup":"other","english":"be thirsty","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sitis","latin":"sitis, sitis","headword":"sitis","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.; acc. sitim) thirst; thirst","forms":["sitī","sitim","sitis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Propter amōrem, quem in animō sentiō, iam multī diēs sunt, cum cibum nōn sūmpsī; at equidem cibō et aquā carēre, famem et {{sitim}} perferre facilius possum quam paulisper sine tē vīvere.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"situs","latin":"situs, -a, -um","headword":"situs","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"situated; position, situation","forms":["sita","sitae","sitam","sitās","situ","situm","situs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Caesar ex eo loco quintis castris Gergoviam pervenit equestrique eo die proelio levi facto, perspecto urbis {{situ}}, quae posita in altissimo monte omnes aditus difficiles habebat, de expugnatione desperavit; de obsessione non prius agendum constituit quam rem frumentariam expedisset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sive","latin":"sīve","headword":"sīve","letter":"s","pos":"conjunction","posGroup":"conjunction","english":"or, or if","forms":["sīve"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mercurius vērō continuō, sine morā, patris imperiō pāruit: induit calceōs suōs aureōs et ālis ornatōs, quibus ventō celerius volāre potest {{sīve}} super mare sīve super terram, et, virgam manū gerēns, ad campōs, in quibus ignēs ab hominibus accēnsōs vīderat, volandō pervēnit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sive...sive","latin":"sīve...sīve","headword":"sīve...sīve","letter":"s","pos":"","posGroup":"other","english":"whether…or","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sobrius","latin":"sobrius, sobria, sobrium","headword":"sobrius","letter":"s","pos":"adjective","posGroup":"adjective","english":"sober","forms":["sōbrius"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"dē superō, cum hūc accesserit; faciam ut sit madidus {{sōbrius}}!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"socer","latin":"socer, -erī (m.)","headword":"socer","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"father-in-law","forms":["socerī","socerō","socerum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cōnsūmptīs quīndecim diēbus, Rāgūēl voluit Tobiam retinēre, sed Tobiās: “Ōrō tē” ait “dīmitte mē quam prīmum: scīs enim parentēs meōs nunc animō angī meā causā.” Tandem, ā socerō dīmissus, cum uxōre ad patrem redībat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"socialis","latin":"sociālis, -e","headword":"sociālis","letter":"s","pos":"adjective","posGroup":"adjective","english":"of allies, social","forms":["sociāle","sociālis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam cum Sulla cōnsul contrā Mithridāten gestūrus bellum, quī Asiam et Achāiam occupāverat, mitterētur, isque exercitum in Campaniā paulisper tenēret, ut bellī {{sociālis}} — dē quō dīximus — quod intrā Ītaliam gestum fuerat, reliquiae tollerentur, Marius affectāvit ut ipse ad bellum Mithridāticum mitterētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sociare","latin":"(sociō) sociāre","headword":"sociāre","letter":"s","pos":"verb","posGroup":"verb","english":"join, unite; to unite, associate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"societas","latin":"societās, -ātis ( f.)","headword":"societās","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"partnership, alliance; alliance, partnership","forms":["societās","societāte","societātem","societātēs","societātī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēnique cum īrent omnēs ad vitulōs aureōs, quōs Ieroboāmus rēx Isrāēlis fēcerat, et populō adōrandōs prōposuerat, hīc sōlus fugiēbat {{societātem}} omnium; pergēbat autem ad templum Dominī, et ibi adōrābat Dominum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"socio","latin":"socio, sociare, sociavi, sociatus","headword":"socio","letter":"s","pos":"verb","posGroup":"verb","english":"unite, join, ally; share in","forms":["sociāre","sociātī","sociātus","sociāvit","sociō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Placuit tamen, 'quod contrā foedus nāvēs habērent, quod exercitum extrā fīnēs dūxissent, quod sociō populī Rōmānī et amīcō Masinissae arma intulissent, quod fīlium eius Gulussam — quī cum lēgātīs Rōmānīs erat — in oppidum nōn recēpissent', bellum hīs indīcī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"socius","latin":"socius, -ī","headword":"socius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"companion, partner, ally; companion, ally; ally, companion, comrade; ally, comrade","forms":["soci","sociam","sociās","sociī","sociīs","sociōrum","sociōs","socium","socius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ex ea fōrmāvit mulierem, quam dedit {{sociam}} Adamō, sīcque īnstituit mātrimōnium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"socordia","latin":"socordia, -ae","headword":"socordia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sluggishness, indolence","forms":["socordia","socordiae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi {{socordiae}} tē atque ignāviae trādiderīs, nēquīquam deōs implōrēs: īrātī īnfēstīque sunt.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"socrates","latin":"Socrates, Socratis","headword":"Socrates","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Socrates (Athenian philosopher 469-399 B.C.)","forms":["Sōcratem","Sōcratēs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diodōrus: “Multōs ‘bonōs librōs’ dīcere possum, sed in prīmīs librōs Platōnis, in quibus {{Sōcratem}} cum amīcīs colloquentem Platō -ōnis Sōcratēs -is facit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"socraticus","latin":"Socraticus, Socratica, Socraticum","headword":"Socraticus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Socratic; of Socrates","forms":["Sōcratica"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec est enim, ut scīs, vetus et {{Sōcratica}} ratiō contrā alterīus opīniōnem disserendī; nam ita facillimē quid vērī simillimum esset invenīrī posse Sōcratēs arbitrābātur.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sodalicium","latin":"sodalicium, sodalici(i)","headword":"sodalicium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"close association/partnership; club/society (religious/social/political)","forms":["sodālicium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dum haec loquitur, venit in aedēs quāsdam in quibus {{sodālicium}} erat eōdem diē futūrum; quō iste — prō nōtitiā dominī aedium — ingreditur cum hospitibus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sodalis","latin":"sodalis, sodalis","headword":"sodalis","letter":"s","pos":"noun","posGroup":"noun","english":"companion, associate, mate, intimate, comrade, crony; accomplice, conspirator","forms":["sodālem","sodālī","sodālis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ei mihi! nōn tūtum est quod ames laudāre sodālī:","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sodes","latin":"sodes","headword":"sodes","letter":"s","pos":"adverb","posGroup":"adverb","english":"if you do not mind, please; (si audes)","forms":["sōdēs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quantō est facilius mihi sub tēctō vīvere et ōtiōsum largō satiārī cibō!” [Canis:] “Venī ergō mēcum!” Dum prōcēdunt, lupus ā catēnā collum dētrītum canī aspicit. [Lupus:] “Unde hoc, amīce?” [Canis:] “Nīl est.” [Lupus:] “Dīc, {{sōdēs}}, tamen!” [Canis:] “Quia videor ācer, alligant mē interdiū, lūce ut quiēscam, ut vigilem nox cum vēnerit: crepusculō solūtus quā vīsum est vāgor.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sol","latin":"sōl, sōlis","headword":"sōl","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) sun","forms":["sōl","sole","solem","solēs","sōlī","sōlibus","solis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae Cenabi oriente {{sole}} gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"solacium","latin":"solacium, solaci(i)","headword":"solacium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"comfort, solace; relief in sorrow/misfortune; source of comfort/consolation","forms":["solaci","sōlāciō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi {{solaci}} proponebant, quod se prope explorata victoria celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"solamen","latin":"sōlāmen, -inis","headword":"sōlāmen","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"comfort, consolation","forms":["sōlāmen"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iam curru īnstābat Achillēs āgmina perque aciēs aut Cygnum aut Hectora quaerēns; occurrit Cygnō (decimum dīlāta in annum mors Hectoris erat): tum ... exhortātus equōs currum dīrēxit in hostem concutiensque suīs vibrantia tēla lacertīs “Quisquis es, ō iuvenis” dīxit “{{sōlāmen}} habētō mortis, ab Aeacidē quod sīs iugulātus Achille!”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"solari","latin":"(sōlor) sōlārī, sōlātum","headword":"sōlārī","letter":"s","pos":"","posGroup":"other","english":"comfort","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"solea","latin":"solea, -ae","headword":"solea","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"shoe, sandal","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"soleo","latin":"soleō, -ēre, solitus sum","headword":"soleō","letter":"s","pos":"verb","posGroup":"verb","english":"be accustomed","forms":["soleam","soleās","soleat","solēbam","solēbant","solēbās","solēbat","solent","soleō","solēre","solērent","solēret","solet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Erat in magnis Caesari difficultatibus res, ne maiorem aestatis partem flumine impediretur, quod non fere ante autumnum Elaver vado transiri {{solet}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"solet","latin":"solet, solēre","headword":"solet","letter":"s","pos":"verb","posGroup":"verb","english":"be accustomed; is accustomed to; is accustomed to, usually does","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"solidus","latin":"solidus, solida -um, solidior -or -us, solidissimus -a -um","headword":"solidus","letter":"s","pos":"adjective","posGroup":"adjective","english":"solid; same material throughout, unalloyed; not hollow; dense; unbroken/whole","forms":["solida","solidē","solidus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Putô meherculēs illum relîquisse {{solida}} centum, et omnia in nummîs habuit. `�� Plānē Fortūnae ﬁlius: in manū illîus plumbum aurum ﬁëbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"solito","latin":"solito, solitare, solitavi, solitatus","headword":"solito","letter":"s","pos":"verb","posGroup":"verb","english":"to make it one's constant habit to (w/INF); make a practice of; be accustomed","forms":["solitō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ad quōs cum vēnisset Iōsēphus māne, et animadvertisset eōs trīstiōrēs solitō, interrogāvit quaenam esset moestitiae causa.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"solitudo","latin":"sōlitūdō, -inis ( f.)","headword":"sōlitūdō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"loneliness, lonely place; solitude, deserted place","forms":["sōlitūdinem","sōlitūdinēs","sōlitūdō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hebraeī, trāiectō marī Rubrō, diū peragrārunt vastam {{sōlitūdinem}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"solitum","latin":"solitum, soliti","headword":"solitum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"custom; habit","forms":["solitum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"grāniferō {{solitum}} cum vehit óre cibum,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"solitus","latin":"solitus, -a, -um","headword":"solitus","letter":"s","pos":"adjective","posGroup":"adjective","english":"ususal","forms":["solita","solitī","solitīs","solitōs","solitus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"in-adsuētus -ā -um («» {{solitus}}) 7 quī fertur inadsuēta subsecuisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"solium","latin":"solium, -ī","headword":"solium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"throne; throne, seat of state","forms":["soliō","solium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Rēx novus soliō potītus est, quī Iōsēphum nōn vīderat, nec merita eius recordābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sollemne","latin":"sollemne, sollemnis","headword":"sollemne","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"solemn observance, religious ceremony; customary practice/usage","forms":["sollemne"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"pompa -ae f - agmen {{sollemne}} cīvī-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sollemnis","latin":"sollemnis, sollemne, sollemnior -or -us, sollemnissimus -a -um","headword":"sollemnis","letter":"s","pos":"adjective","posGroup":"adjective","english":"solemn, ceremonial, sacred, in accordance w/religion/law; traditional/customary","forms":["sollemnem","sollemnī","sollemnia","sollemnibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Iildās omnia pūrgāvit, portās refēcit, novum altāre ērēxit, cuius dēdicātiō magna tofius populī frequentiā, clangentibus tubīs, facta est; dēcrētumque, ad memoriam reī sempitēmam, quotannīs diem {{sollemnem}} celebrātum In.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sollertia","latin":"sollertia, sollertiae","headword":"sollertia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"skill, cleverness; resourcefulness","forms":["sollertiae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Singulari militum nostrorum virtuti consilia cuiusque modi Gallorum occurrebant, ut est summae genus {{sollertiae}} atque ad omnia imitanda et efficienda quae ab quoque traduntur aptissimum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sollicitare","latin":"(sollicitō) sollicitāre","headword":"sollicitāre","letter":"s","pos":"","posGroup":"other","english":"solicit, incite","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sollicitatio","latin":"sollicitatio, sollicitationis","headword":"sollicitatio","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"incitement to disloyalty or crime","forms":["sollicitātiōne"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Annium Chīlōnem, quī ūna cum hōc Fūriō semper erat in hāc Allobrogum {{sollicitātiōne}} versātus, in P.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"sollicite","latin":"sollicite, sollicitius, sollicitissime","headword":"sollicite","letter":"s","pos":"adverb","posGroup":"adverb","english":"anxiously; with a troubled mind; with anxious care","forms":["Sollicitē"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sollicitē exspectās dum té in convīvia dūcam","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sollicito","latin":"sollicito, sollicitare, sollicitavi, sollicitatus","headword":"sollicito","letter":"s","pos":"verb","posGroup":"verb","english":"disturb, worry; stir up, arouse, agitate, incite","forms":["sollicitābant","sollicitābat","sollicitandas","sollicitandōs","sollicitant","sollicitāre","sollicitārī","sollicitat","sollicitātam","sollicitātōs","sollicitatus","sollicitō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum haec ad Gergoviam geruntur, Convictolitavis Aeduus, cui magistratum adiudicatum a Caesare demonstravimus, {{sollicitatus}} ab Arvernis pecunia cum quibusdam adulescentibus colloquitur; quorum erat princeps Litaviccus atque eius fratres amplissima familia nati adulescentes.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sollicitudo","latin":"sollicitudo, sollicitudinis","headword":"sollicitudo","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"anxiety, concern, solicitude","forms":["sollicitudine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Magna adfectus {{sollicitudine}} hoc nuntio Caesar, quod semper Aeduorum civitati praecipue indulserat, nulla interposita dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium tali tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sollicitus","latin":"sollicitus, -a, -um","headword":"sollicitus","letter":"s","pos":"adjective","posGroup":"adjective","english":"anxious, troubled","forms":["sollicitīs","sollicitōs","sollicitum","sollicitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Stābat intereā Dāvīd ad portam urbis, exspectāns ēventum pugnae, et maximē dē fīliī salūte {{sollicitus}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"solor","latin":"solor, solari, solatus sum","headword":"solor","letter":"s","pos":"verb","posGroup":"verb","english":"solace, console, comfort; soothe, ease, lighten, relieve, assuage, mitigate","forms":["sōlandō","sōlantur","sōlārī","sōlor"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quanta erit potentia Poenōrum, quanta glōria tua, {{sōlor}}, sī cum duce Trōiānōrum tē coniūnxeris!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"solum","latin":"solum, -ī","headword":"solum","letter":"s","pos":"adverb","posGroup":"adverb","english":"soil, ground, floor; only","forms":["solum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non {{solum}} magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"solus","latin":"sōlus, -a, -um","headword":"sōlus","letter":"s","pos":"adjective","posGroup":"adjective","english":"alone, lonely; alone, only; alone, lone, only","forms":["sōla","sōlae","sōlam","sōlīus","solo","sōlōs","sōlus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Trabes directae perpetuae in longitudinem paribus intervallis distantes inter se binos pedes in {{solo}} collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"solutus","latin":"solutus, soluta -um, solutior -or -us, solutissimus -a -um","headword":"solutus","letter":"s","pos":"adjective","posGroup":"adjective","english":"unbound, released; free, at large; unrestrained, profligate; lax, careless","forms":["solūta","solūtīs","solūtōrum","solūtus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"\"Pecūnia {{solūta}}, amīcus meus ā pīrātīs līberātus grātiās ēgit prō beneficiō, ac simul mihi prōmīsit sē intrā paucōs diēs omnem pecūniam redditūrum esse — sed nē posteā quidem assem ab eō accēpī!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"solvere","latin":"(solvō) solvere, solvisse, solūtum","headword":"solvere","letter":"s","pos":"verb","posGroup":"verb","english":"loose (also pay); loose, pay; to untie, loosen; to pay; untie; to loosen","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"solvit","latin":"solvit","headword":"solvit","letter":"s","pos":"verb","posGroup":"verb","english":"pays","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"solvo","latin":"solvo, solvere, solvi, solutus","headword":"solvo","letter":"s","pos":"verb","posGroup":"verb","english":"loosen, release, unbind, untie, free; open; set sail; scatter; pay off/back","forms":["solūtum","solūtūrum","solvam","solvās","solvat","solvātur","Solve","solvendō","solvendum","solvent","solverat","solvere","solverētur","solvērunt","solvī","solvimur","solvis","solvisse","solvistī","solvit","solvite","solvitur","solvō","solvunt","solvuntur"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Solve}} canem tuum!” clāmat aliquis, dum aliī magnō cum strepitū forēs frangere cōnantur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"somniculose","latin":"somniculose","headword":"somniculose","letter":"s","pos":"adverb","posGroup":"adverb","english":"sleepily, drowsily","forms":["somnīculōsē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"SOSIA: Ego nōn soleō somnīculōsē meī erī imperia persequī.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"somnio","latin":"somnio, somniare, somniavi, somniatus","headword":"somnio","letter":"s","pos":"verb","posGroup":"verb","english":"dream; dream of or see in a dream","forms":["somniat","somniātor","somniāvimus","somniō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ecce, inquiēbant, {{somniātor}} venit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"somnium","latin":"somnium, -ī","headword":"somnium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"dream","forms":["somnia","somniī","somniīs","somnium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob causam Iōsēphus erat invīsus suīs frātribus, praesertim postquam nārrāvisset eīs duplex {{somnium}}, quō futūra eius magnitūdō portendēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"somnus","latin":"somnus, -ī","headword":"somnus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sleep; in somnō — asleep","forms":["Somne","somnī","somnīs","somnō","somnōs","somnum","somnus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iacobus vīdit in {{somnīs}} scālam, quae innīxa terrae pertinēbat ad caelum, atque Angelōs Deī adscendentēs et dēscendentēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sonare","latin":"(sonō) sonāre, -uisse, -itum","headword":"sonāre","letter":"s","pos":"verb","posGroup":"verb","english":"sound; to sound","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"sonipes","latin":"sonipes, sonipedis","headword":"sonipes","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"horse, steed","forms":["sonipēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"stat {{sonipēs}} ac frēna ferōx spūmantia mandit.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sonitus","latin":"sonitus, -ūs","headword":"sonitus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"noise, sound","forms":["sonitu","sonitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Conquirit etiam lintres; has magno {{sonitu}} remorum incitatas in eandem partem mittit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sono","latin":"sono, sonare, sonavi, sonatus","headword":"sono","letter":"s","pos":"verb","posGroup":"verb","english":"make a noise/sound; speak/utter, emit sound; be spoken of (as); express/denote","forms":["sonābat","sonābunt","sonāns","sonant","sonantēs","sonantīs","sonāre","sonās","sonat","sonātur","sonent","sonet","sono"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito {{sono}} tubae, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sonorus","latin":"sonorus, sonora, sonorum","headword":"sonorus","letter":"s","pos":"adjective","posGroup":"adjective","english":"noisy, loud, resounding, sonorous","forms":["sonōrās"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"luctantēs ventōs tempestātēsque {{sonōrās}}","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sons","latin":"sons, sontis","headword":"sons","letter":"s","pos":"noun","posGroup":"noun","english":"criminal","forms":["sontēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī causa peccandī in praesēns minus suppetēbat, nihilō minus īnsontēs sīcuti {{sontēs}} circumvenīre, iugulāre; scīlicet nē per ōtium torpēscerent manūs aut animus, grātuītō potius malus atque crūdēlis erat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"sonus","latin":"sonus, ī","headword":"sonus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) sound","forms":["sonōs","sonum","sonus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum vērō iam procul sōlis lūcem aspiceret, neque ūllum {{sonum}} post sē audīret, dubitāns an Eurydicē sē sequerētur, tantō metū captus est, ut iam dēsīderium uxōris rūrsus videndī, quō ārdēbat, retinēre nōn posset: cōnstitit igitur nōn iam patiēns morae, et ferē sub ipsā lūce, amōre victus, rēs pexit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sophocles","latin":"Sophocles, Sophoclis","headword":"Sophocles","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sophocles (Greek poet)","forms":["Sophoclēs","Sophoclis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inter haec tempora nōbilēs celebrēsque erant {{Sophoclēs}} ac deinde Eurīpidēs, tragicī poētae, et Hippocratēs medicus, et philosophus Dēmocritus, quibus Sōcratēs Athēniēnsis nātū quidem posterior fuit, sed quibusdam temporibus iīsdem vīxērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sopio","latin":"sopio, sopire, sopivi, sopitus","headword":"sopio","letter":"s","pos":"verb","posGroup":"verb","english":"cause to sleep, render insensible by a blow or sudden shock","forms":["sopītōs","sōpītum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iubet bonō animō esse: {{sōpītum}} esse rēgem subitō ictū; ferrum haud altē in corpus dēscendisse; iam ad sē redīisse; brevī ipsum eōs vīsūrōs esse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sopire","latin":"(sōpiō) sōpīre, -īvisse, -ītum","headword":"sōpīre","letter":"s","pos":"","posGroup":"other","english":"put to sleep, stun","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sopor","latin":"sopor, soporis","headword":"sopor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"deep sleep","forms":["sopor","sopōrem","sopōrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Deinde immīsit {{sopōrem}} in Adamum et dētrāxit ūnam ē costīs eius dormientīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sorbeo","latin":"sorbeo, sorbere, sorbui, sorbitus","headword":"sorbeo","letter":"s","pos":"verb","posGroup":"verb","english":"drink, absorb","forms":["sorbēre","sorbet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"caelestēs aquās (: imbrēs) {{sorbet}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sordes","latin":"sordēs, sordis {i}often pl. {/i} sordēs, -ium","headword":"sordēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) dirt; dirt, filth","forms":["sordēs","sordī","sordibus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōlī per imbrem frīgidum ambulāre!” sōlum ūmida, sed etiam sordida sunt vestīmenta eius, atque faciēs cruōre et {{sordibus}} operītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sordidus","latin":"sordidus, -a, -um","headword":"sordidus","letter":"s","pos":"adjective","posGroup":"adjective","english":"dirty, mean, base; dirty; dirty, filthy","forms":["sordida","sordidae","sordidam","sordidīs","sordidissimō","sordidō","sordidum","sordidus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Corpora eōrum nūda sunt atque foeda et {{sordida}}, colla longa et nūda...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"soror","latin":"soror, sorōris","headword":"soror","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) sister","forms":["soror","sorōre","sorōrem","sorōrēs","sorōrī","sorōribus","sorōris","sorōrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Frāter apud {{sorōrem}} cōnsīdit eamque interrogat: “Cūr tam quiēta es, Iūlia, neque canis?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sors","latin":"sors, -rtis ( f.)","headword":"sors","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"lot, drawing lots, fortune; lot, chance, lottery; lot, prophecy, fate; lot, fate; oracle","forms":["sors","sorte","sortem","sortēs","sortī","sortium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{sors}} tua mortālīs; nōn est mortāle, quod optās!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sortior","latin":"sortior, sortiri, sortitus sum","headword":"sortior","letter":"s","pos":"verb","posGroup":"verb","english":"cast or draw lots; obtain by lot; appoint by lot; choose","forms":["sortīrī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōminātae iam anteā cōnsulibus prōvinciae erant; tum sortīrī iussī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sortiri","latin":"(sortior) sortīrī","headword":"sortīrī","letter":"s","pos":"","posGroup":"other","english":"draw lots","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sospes","latin":"sōspes (gen. sōspitis)","headword":"sōspes","letter":"s","pos":"adjective","posGroup":"adjective","english":"safe and sound","forms":["sospitī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ūnam in ipsā portā sospitī fīliō repentē oblātam in complexū eius exspīrāsse ferunt; alteram, cui mors fīliī falsō nūntiāta erat, maestam sedentem domī, ad prīmum cōnspectum redeuntis fīliī gaudiō nimiō exanimātam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sp","latin":"Sp., abb.","headword":"Sp","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Spurius (Roman praenomen); (abb. Sp.)","forms":["sp"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Sp}}és tenet in tempus, semel","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"spargere","latin":"(spargō) spargere, sparsisse, sparsum","headword":"spargere","letter":"s","pos":"verb","posGroup":"verb","english":"sprinkle; to scatter, sprinkle","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"spargit","latin":"spargit","headword":"spargit","letter":"s","pos":"verb","posGroup":"verb","english":"scatters, sprinkles","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"spargo","latin":"spargo, spargere, sparsi, sparsus","headword":"spargo","letter":"s","pos":"verb","posGroup":"verb","english":"scatter, strew, sprinkle; spot","forms":["spargēbant","spargēbat","spargēns","spargere","spargerent","spargeret","Spargimur","spargit","spargitur","sparguntur","sparsa","sparsās","sparserit","sparsī","sparsimus","sparsīs","sparsit","sparsōs","sparsum","sparsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ipsa hominibus sēmina largīta est atque mōnstrāvit quōmodo in agrōs {{spargerent}} ac sererent, ut terra magnam frūmentī cōpiam ferret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sparta","latin":"Sparta, Spartae","headword":"Sparta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Sparta (Greek city)","forms":["Sparta","Spartae"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus: “Quid est {{Sparta}}?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"sparus","latin":"sparus, spari","headword":"sparus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"hunting-spear, javelin; a small kind of sea bream","forms":["sparōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed ex omnī cōpiā circiter pars quārta erat mīlitāribus armīs īnstrūcta; cēterī, ut quemque cāsus armāverat, {{sparōs}} aut lanceās, praeacūtās sudēs portābant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"spatior","latin":"spatior, spatiari, spatiatus sum","headword":"spatior","letter":"s","pos":"verb","posGroup":"verb","english":"walk; take a walk, promenade; spread","forms":["spatiātur"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aut ante ōra deum pinguīs {{spatiātur}} ad ārās,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"spatiosus","latin":"spatiosus, spatiosa, spatiosum","headword":"spatiosus","letter":"s","pos":"adjective","posGroup":"adjective","english":"spacious, wide, long","forms":["spatiōsī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Longa referre mora est, quae cōnsiliōque manūque ūtiliter fēcī spatiōsī tempore bellī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"spatium","latin":"spatium, -ī","headword":"spatium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"space, distance, interval, walk, time, period; space, distance","forms":["spati","spatiī","spatiis","spatio","spatium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam vigiliam in finibus Arvernorum audita sunt, quod {{spatium}} est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"species","latin":"speciēs, -ēī","headword":"speciēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"appearance, aspect, sort; sight, appearance, shape, semblance, sort; sight, appearance","forms":["specie","speciem","speciēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc cum in {{speciem}} varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"speciosus","latin":"speciosus, speciosa -um, speciosior -or -us, speciosissimus -a -um","headword":"speciosus","letter":"s","pos":"adjective","posGroup":"adjective","english":"beautiful/handsome/good-looking; attractive/appealing; presentable/respectable","forms":["speciōsā","speciōsus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{speciōsus}} -ā -um — speciē fōrmōsus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"spectaculum","latin":"spectāculum, -ī","headword":"spectāculum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sight, spectacle; show, spectacle","forms":["spectācula","spectāculī","spectāculīs","spectaculō","spectāculum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aderant trisfī spectaculō ceterī frātrēs cum mātre, sēque invicem hortābantur ad mortem fortiter tolerandam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spectat","latin":"spectat, spectāre","headword":"spectat","letter":"s","pos":"verb","posGroup":"verb","english":"watch, look at; watches, looks at","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"spectate","latin":"spectāte","headword":"spectāte","letter":"s","pos":"verb","posGroup":"verb","english":"look at (plural command)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"spectator","latin":"spectātor, spectātōris","headword":"spectātor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) spectator; spectator, onlooker","forms":["spectātor","spectatores","spectātōrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cornelius: \"Alter alterum in rete implicare conatur, nam qui reti implicitus est non potest se defendere et sine mora interficitur, nisi tam fortiter pugnavit ut {{spectatores}} eum vivere velint.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"specto","latin":"specto, spectare, spectavi, spectatus","headword":"specto","letter":"s","pos":"verb","posGroup":"verb","english":"observe, watch, look at, see; test; consider","forms":["spectā","spectābam","spectābant","spectabat","spectābimus","spectanda","spectandam","spectandī","spectandō","spectandōs","spectandum","spectāns","spectant","spectante","spectantem","spectantēs","spectantibus","spectāre","spectārent","spectāret","spectas","spectat","spectāta","spectāte","spectātī","spectātō","spectātum","spectātur","spectāverat","spectāvērunt","spectavi","spectāvisset","spectāvit","spectem","spectemus","spectent","spectentur","spectet","spectētur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sub muro, quae pars collis ad orientem solem {{spectabat}}, hunc omnem locum copiae Gallorum compleverant fossamque et maceriam sex in altitudinem pedum praeduxerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"speculari","latin":"(speculor) speculārī","headword":"speculārī","letter":"s","pos":"","posGroup":"other","english":"spy, reconnoiter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"speculator","latin":"speculātor, -ōris (m.)","headword":"speculātor","letter":"s","pos":"","posGroup":"other","english":"scout, spy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"speculor","latin":"speculor, speculari, speculatus sum","headword":"speculor","letter":"s","pos":"verb","posGroup":"verb","english":"watch, observe; spy out; examine, explore","forms":["speculābuntur","speculantur"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quam diū quisquam erit quī tē dēfendere audeat, vīvēs — et vīvēs ita ut vīvis: multīs meīs et firmīs praesidiīs oppressus, nē commovēre tē contrā rem pūblicam possīs; multōrum tē etiam oculī et aurēs nōn sentientem, sīcut adhūc fēcērunt, {{speculābuntur}} atque cūstōdient.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"speculum","latin":"speculum, -ī","headword":"speculum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"mirror","forms":["speculīs","speculō","speculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In speculō aquae videt imāginem suam.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"spelunca","latin":"spēlunca, -ae","headword":"spēlunca","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"cave, grotto; cave","forms":["spēluncā","spēluncam","spēluncīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi fūnus fēcērunt cum magnō plānctū, et sepeliērunt corpus in spēluncā ubi iacēbant Abrahāmus et Isaacus; reversīque sunt in Aegyptum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sperare","latin":"(spērō) spērāre, spērāvisse, spērātum","headword":"spērāre","letter":"s","pos":"verb","posGroup":"verb","english":"hope for; to hope","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"spernere","latin":"(spernō) spernere, sprēvisse,","headword":"spernere","letter":"s","pos":"verb","posGroup":"verb","english":"disdain, scorn sprētum; to despise, reject","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"sperno","latin":"sperno, spernere, sprevi, spretus","headword":"sperno","letter":"s","pos":"verb","posGroup":"verb","english":"scorn, despise, spurn","forms":["spernēbant","spernēbat","spernendō","Spernentibus","spernere","spernis","spernit","sprēverat","sprēverīs","sprēvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Saūlem, postquam Deī mandāta {{sprēverat}}, invāsit spīritus malus, ita ut ille in furōrem saepe incīderet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spero","latin":"spero, sperare, speravi, speratus","headword":"spero","letter":"s","pos":"verb","posGroup":"verb","english":"hope for; trust; look forward to; hope","forms":["sperabant","sperabat","spērāmus","spērandī","spērāns","spērantēs","spērantī","spērāre","spērārent","spērāret","spērat","spērātā","spērātam","spērāte","spērātō","Spērātum","Spērātus","spērāverat","spērāvī","spērāvit","spērem","spēret","spērō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id silentio noctis conati non magna iactura suorum sese effecturos {{sperabant}}, propterea quod neque longe ab oppido castra Vercingetorigis aberant et palus, quae perpetua intercedebat, Romanos ad insequendum tardabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"spes","latin":"spēs, -eī","headword":"spēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"(f.) hope","forms":["spe","spei","spem","spes","spī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quem simul atque oppidani conspexerunt atque in {{spem}} auxili venerunt, clamore sublato arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sphaera","latin":"sphaera, -ae","headword":"sphaera","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"globe, sphere; sphere, globe","forms":["sphaerā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum deinde Philus et Scīpiō et Tubērō parumper dē rēbus caelestibus disputāvissent — velut dē certīs et ratīs astrōrum mōtibus, quōs Archimēdēs Syrācūsiānus in globō sīve sphaerā aēneā arte mīrābilī effectā dēclārāvisse dīcitur — Laelius, quī eius modī disputātiōnēs tamquam inūtilēs contemnēbat, 'alia quaedam maiōra quaerenda esse' dīxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sphaeristerium","latin":"sphaeristerium, sphaeristerii","headword":"sphaeristerium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"place for playing ball","forms":["sphaeristēriō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rape nōbīs pilam! [Ad Gāium:] Lūdāmus in sphaeristēriō!” [Amīcī in sphaeristēriō pilā lūdunt.] [Iūlius:] “Exercērī volō in cērōmate.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"spica","latin":"spica, spicae","headword":"spica","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"head/ear of grain/cereal","forms":["spīcae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Septem {{spīcae}} plēnae ēnāscēbantur in ūnō culmō, aliaeque totidem exīlēs succrēscēbant, ēspīcās plēnās cōnsūmēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spiceus","latin":"spiceus, spicea, spiceum","headword":"spiceus","letter":"s","pos":"adjective","posGroup":"adjective","english":"consisting of heads/ears of grain/cereal","forms":["spīcea"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"'Er y Vērque novum stābat cīnctum flōrente corōnā, stābat nūda Aestās et {{spīcea}} serta gerēbat, stābat et Autumnus calcātīs sordidus ūvīs et glaciālis Hiems cānōs hirsūta capillōs","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"spicio","latin":"spicio, spicere, spixi, -","headword":"spicio","letter":"s","pos":"verb","posGroup":"verb","english":"look at, see","forms":["spīcēre","spiciēns","spīcīt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"álàs nàtī rē-{{spīcīt}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"spiculum","latin":"spiculum, spiculi","headword":"spiculum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sting; javelin; arrow; sharp point of a weapon","forms":["spīcula"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"520 quae patimur multō {{spīcula}} felle madent.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"spina","latin":"spina, spinae","headword":"spina","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"thorn/spine/prickle (plant/animal); spike (asparagus); thorn-bush; blackthorn","forms":["spīna","spīnās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Deinde Deus dīxit Adamō: quia gessistī mōrem uxōrī tuae, habēbis terram īnfēstam; ea fundet tibi {{spīnās}} et carduōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spirat","latin":"spīrat, spīrāre","headword":"spīrat","letter":"s","pos":"verb","posGroup":"verb","english":"breathe; breathes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"spiritus","latin":"spiritus, spiritus","headword":"spiritus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"breath, breathing, air, soul, life","forms":["spīritum","spīritus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Saūlem, postquam Deī mandāta sprēverat, invāsit {{spīritus}} malus, ita ut ille in furōrem saepe incīderet.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spiro","latin":"spīrō (1)","headword":"spīrō","letter":"s","pos":"verb","posGroup":"verb","english":"to breathe, live","forms":["spīrābant","spīrābunt","spīrāns","spīrāre","spīrat","spīrāte","spīrāvēre","spīrāvit","spīrō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Syra canem crassam in herbā iacēre videt eamque {{spīrāre}} audit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"spisso","latin":"spisso, spissare, spissavi, spissatus","headword":"spisso","letter":"s","pos":"verb","posGroup":"verb","english":"thicken, condense","forms":["spissō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"quod rogat in spissō lītore pingit opus.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"splendeo","latin":"splendeo, splendere, splendui, -","headword":"splendeo","letter":"s","pos":"verb","posGroup":"verb","english":"shine/gleam/glitter, be bright/radiant/resplendent (white/color)/distinguished","forms":["splendēbant","splendēbat","splendent","splendēre","splendet"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Rēgia Phoebī, Sōlis deī, cuius tēctum eburneum altissimīs ā columnīs sustinēbātur, lūcēbat tōta, cum ex pūrissimō aurō aliīsque metallīs ignem imitantibus facta esset; forēs atque fenestrae argenteae clārissimē {{splendēbant}}; at opus, quod Vulcānus arte suā in iānuīs cōnfēcerat, māteriam pretiōsam superābat: nam illīc caelāverat maria, quae cingunt terrās,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"splendere","latin":"(splendeō) splendēre","headword":"splendēre","letter":"s","pos":"","posGroup":"other","english":"shine","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"splendidus","latin":"splendidus, -a, -um","headword":"splendidus","letter":"s","pos":"adjective","posGroup":"adjective","english":"shining, splendid","forms":["splendida","splendidam","splendidē","splendidum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam fidēs tua mihi perspecta est, cum nōn pepercerīs fīliō tuō ūnicō; et ego favēbō tibi; remūnerābō splendidē fidem tuam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"splendor","latin":"splendor, -ōris (m.)","headword":"splendor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"brightness, splendor; brightness, splendour","forms":["splendōre","splendōrem"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Āmēns ōdit amatque ruitque solō impete caecō sēcumque ipse igitur tanta impia dicta revolvit: “Sī mē fastīdīs refugisque fronte superbā ō fōrmōse puer, nimiō {{splendōre}} coruscē, ō Hyacinthe cui radiant ut sīdera ocellī","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"spolia","latin":"spolia, -orum (n. pl.)","headword":"spolia","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"spoils, booty; spoils, armour stripped from a foe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"spoliare","latin":"(spoliō) spoliāre","headword":"spoliāre","letter":"s","pos":"verb","posGroup":"verb","english":"strip (of arms), rob; to strip, despoil","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"spolio","latin":"spoliō, -āre, spoliāvī","headword":"spoliō","letter":"s","pos":"verb","posGroup":"verb","english":"strip, despoil","forms":["spolia","spoliandī","spoliāre","spoliārī","spoliat","spoliatum","spoliātus","spoliō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Proinde agmine impeditos adoriantur; si pedites suis auxilium ferant atque in eo morentur, iter facere non posse; si, id quod magis futurum confidat, relictis impedimentis suae saluti consulant, et usu rerum necessariarum et dignitate {{spoliatum}} iri.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"spolium","latin":"spolium, spoli(i)","headword":"spolium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"spoils, booty; skin, hide","forms":["spoli","spoliī","spoliīs","Spoliōrum","spolium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed deinde Saūl Deum graviter offendit: vetuerat Deus nē quid ex {{spoliīs}} hostium reservārētur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sponda","latin":"sponda, spondae","headword":"sponda","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"bedstead; frame of bed/couch; bed/couch/sofa","forms":["spondā"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aurea composuit spondā mediamque locāvit.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"spondeo","latin":"spondeo, spondere, spopondi, sponsus","headword":"spondeo","letter":"s","pos":"verb","posGroup":"verb","english":"promise, give pledge/undertaking/surety; contract to give/take in marriage","forms":["spoponderat","spopondī","spopondit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Pater ūnicē dīligit puerum; nōlēbat prīmō eum dīmittere; nōn potuī id ab eō impetrāre, nisi postquam spopondī eum tūtum ab omnī perīculō fore.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"spondere","latin":"(spondeō) spondēre, spondisse,","headword":"spondēre","letter":"s","pos":"","posGroup":"other","english":"pledge, promise, betroth spōnsum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"spondeus","latin":"spondēus, -ī","headword":"spondēus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"spondee","forms":["spondēus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: iambus u —, trochaeus — u, anapaestus u u —, dactylus — u u, {{spondēus}} — —, tribrachys u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sponsa","latin":"sponsa, sponsae","headword":"sponsa","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"bride; betrothed woman","forms":["sponsa"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Turnus, rēx Rutulōrum, cui Lāvīnia ante adventum Aenēae {{sponsa}} fuerat, moleste patiēns advenam sibi praelātum esse, simul Aenēae Latīnōque bellum intulerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sponsum","latin":"sponsum, sponsi","headword":"sponsum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"agreement; consent","forms":["spōnsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cui soror virgō, quae dēspōnsa ūnī ex Curiātiīs fuerat, obvia ante portam Capēnam fuit, cognitōque super umerōs frātris palūdāmentō spōnsī, quod ipsa cōnfēcerat, solvit crīnēs et flēbiliter nōmine {{spōnsum}} mortuum appellat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sponsus","latin":"spōnsus, -ī","headword":"spōnsus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"fiancé; betrothed man, fiancé","forms":["spōnsī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cui soror virgō, quae dēspōnsa ūnī ex Curiātiīs fuerat, obvia ante portam Capēnam fuit, cognitōque super umerōs frātris palūdāmentō spōnsī, quod ipsa cōnfēcerat, solvit crīnēs et flēbiliter nōmine spōnsum mortuum appellat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sponte","latin":"sponte","headword":"sponte","letter":"s","pos":"adverb","posGroup":"adverb","english":"of my/his own accord","forms":["sponte"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Helvii sua {{sponte}} cum finitimis proelio congressi pelluntur et C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sportella","latin":"sportella, sportellae","headword":"sportella","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"little basket","forms":["sportellae","sportellās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Secūtum est hôs repositôrium in quô positus erat prīmae magnitūdinis aper ..., ē cuius dentibus {{sportellae}} dēpendēbant duae palmulîs textae, alterā caryôtîs alterā thëbaicîs rē- plēta.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"spuma","latin":"spūma, -ae","headword":"spūma","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"foam, froth","forms":["spūmās","spūmīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Intereā aēnō in igne positō medicāmen validum fervet et albet {{spūmīs}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"spumo","latin":"spumo, spumare, spumavi, spumatus","headword":"spumo","letter":"s","pos":"verb","posGroup":"verb","english":"foam, froth; be covered in foam; cover with foam","forms":["spūmantem","spūmantia","spūmantis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aut {{spūmantis}} aprī cursum clāmōre prementem.'","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"spuo","latin":"spuo, spuere, spui, sputus","headword":"spuo","letter":"s","pos":"verb","posGroup":"verb","english":"spit, spit out","forms":["spue"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hominēs sumus, nôn deî.” Idem et Scintilla ﬂëns dîxit, ac per genium eius ‘Gāium’ appellandô rogāre coepit ‘ut Nôn tenuit ultrā lacrimās Trimalchiô, et “Rogô” inquit, “Habinnä, @`� sî quid perperam tëcî, in faciem meam in- {{spue}}!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"spurium","latin":"spurium, spurii","headword":"spurium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"female external genitalia; marine animal of similar shape","forms":["Spūrium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum Scīpiō, calceīs et vestīmentīs sūmptīs, ē cubiculō est ēgressus et, cum paululum inambulāvisset in porticū, Laelium advenientem salūtāvit et eōs quī ūnā vēnerant, {{Spūrium}} Mummium, quem in prīmīs dīlīgēbat, et C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sputo","latin":"sputo, sputare, sputavi, sputatus","headword":"sputo","letter":"s","pos":"verb","posGroup":"verb","english":"spit out","forms":["spūtō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Exspuit ergō Iēsus in terram, et recit lutum ex spūtō et līnīvit oculōs eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sputum","latin":"sputum, sputi","headword":"sputum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"spittle","forms":["spūtum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô etiam pullārius erat - omnīs mortuum plangere/plôräre : plangere/plôräre dē mortuô (servum) macū (: ê potestāte minimus, quārta pars assis solidus -ā -um 4-) liquidus; sēcum in sepulcrum tulisse que pretiurrx; quid ā. mordeat Sâturnälia agere : in luxū leô : vir fortis ac ferôx rēctus, certus: probus, ﬁdusﬁdt micāre: lūdere digitîs extentîs {{spūtum}} (-î n) ex ôre êmittere pānem quem asse ëmissês...","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ss","latin":"SS., abb.","headword":"SS","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sacred scripture (early Church writings except Bible), Sacrae Scripturae (pl.)","forms":["ss"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Putâ{{ss}}ës eum semper mēcum habitāsse. tuam dê rêbus illîs fëcistî.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"st","latin":"st","headword":"st","letter":"s","pos":"interjection","posGroup":"interjection","english":"hush! hist!","forms":["st"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Syra: “{{St}}, Dēlia!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"stabilio","latin":"stabilio, stabilire, stabilivi, stabilitus","headword":"stabilio","letter":"s","pos":"verb","posGroup":"verb","english":"make firm, establish","forms":["stabiliendi","stabilīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Huc teretes stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et {{stabiliendi}} causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stabilis","latin":"stabilis, -e","headword":"stabilis","letter":"s","pos":"adjective","posGroup":"adjective","english":"firm, stable","forms":["stabilī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"cōnūbiō iungam stabilī propriamque dicābō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"stabulo","latin":"stabulo, stabulare, stabulavi, stabulatus","headword":"stabulo","letter":"s","pos":"verb","posGroup":"verb","english":"stable/house (domestic animals, poultry, etc); be housed, have stall/lair/den","forms":["stabulō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Mīnōs, ad taurum accēdēns, eum magna cum cūrā spectāvit: postquam vērō vīdit taurum pulcherrimum esse, nōluit tam fōrmōsam bēstiam Neptūnō sacrificāre; servōs igitur suōs id facere prohibuit, eōsque iussit alterum taurum ex stabulō suō ad maris ōram addūcere: “Ō servī” inquit, “vōbīs imperō ut taurum minus pulchrum ex stabulō meō sūmātis: cūrātē tamen ut colōre sit similis huic, quem Neptūnus mīsit.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"stabulum","latin":"stabulum, -ī","headword":"stabulum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"stable","forms":["stabulīs","stabulum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et appropinquāns alligāvit vulnera eius Īnfundēns oleum et vīnum; et impōnēns illum iūmentō suō, dūxit in {{stabulum}}, et cūram eius ēgit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"stadium","latin":"stadium, -ī","headword":"stadium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"running track","forms":["stadium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inter cētera Domitiānī opera memorandum est {{stadium}} in campō Mārtiō factum, ubi iuvenēs Rōmānī cursū sē exercent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stagno","latin":"stagno, stagnare, stagnavi, stagnatus","headword":"stagno","letter":"s","pos":"verb","posGroup":"verb","english":"form/lie in pools; be under water","forms":["stāgnō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In mediō stāgnō nympha Cyānē, ā cuius nōmine stāgnum dictum est, celeberrima inter nymphās Siciliānās exstitit recōgnōvitque deam.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"stagnum","latin":"stāgnum, ī","headword":"stāgnum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"pool, pond; pool, lake","forms":["stāgna","stagnī","stāgnum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum turbae irruerent in Iēsum ut audīrent verbum Deī, ipse ascendit in nāvem quae erat secus {{stāgnum}}, et sedēns docēbat dē nāviculā turbās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"stamen","latin":"stamen, staminis","headword":"stamen","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"warp (in the loom); thread (on distaff); thread of life spun by the Fates","forms":["stāmen"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"At Minerva eam inventam et in vītam reductam herbae cuiusdam sūcō aspersit; quō factum est ut tōtum eius corpus parvum fieret; in utrōque latere octo gracilia crūra appāruerunt; ex ventre verō iam ab illō tempore {{stāmen}} ēmittit: arānea enim facta, ut anteā, etiam nunc tēlās tēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"stat","latin":"stat, stāre","headword":"stat","letter":"s","pos":"","posGroup":"other","english":"stand","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"statera","latin":"statera, staterae","headword":"statera","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"scales, balance; grade, standard of quality; chariot pole","forms":["statēram"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"[Ferculum prîmum: duodecim signa caelestial] Laudätiônem ferculum est însecütum, plānē nôn prô oculôs: rotundum enim repositôrium duodecim habēbat signa in orbe disposita, super quae proprium conveniēn- temque māteriae strūctor imposuerat cibum: {{statēram}} in cuius alterâ parte scriblîta erat, in alterā placentā; In mediô autem caespes cum herbîs excîsus favum sustinēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"statim","latin":"statim","headword":"statim","letter":"s","pos":"adverb","posGroup":"adverb","english":"at once; immediately, at once; immediately","forms":["statim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Bituriges eorum discessu {{statim}} cum Arvernis iunguntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"statio","latin":"statiō, -tiōnis ( f.)","headword":"statiō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"station, post","forms":["statiōne","statiōnem","stationes","statiōnibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castra opportunis locis erant posita, ibique castella XXIII facta, quibus in castellis interdiu {{stationes}} ponebantur, ne qua subito: eruptio fieret; haec eadem noctu excubitoribus ac firmis praesidiis tenebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stativa","latin":"statīva, -ōrum (pl.)","headword":"statīva","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stationary camp (sc. castra)","forms":["statīva","statīvīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ea rēs ab {{statīvīs}} excīvit Mettium.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stator","latin":"stator, statoris","headword":"stator","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"one who establishes or upholds (cult-title of Jupiter)","forms":["Statōrem","Statōrī","Stātōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Multae viae ex omnibus urbis partibus in forum ferunt, ut Argīlētum, Sacra via, Nova via, vīcus Tuscus, vīcus Iūgārius, atque clīvus Capitōlīnus, quō imperātōrēs triumphantes in Capitōlium ascendunt. (\"Clīvus\" dīcitur via quae in clīvō montis facta est.) In summā Sacrā viā īnfrā clīvum Palātīnum est arcus Titī, dē quō mox dīcendum erit, et templum Iovis {{Stātōris}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"statua","latin":"statua, -ae","headword":"statua","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"statue","forms":["statuā","statuae","statuam","statuās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nabuehodonosor sibi pō suit {{statuam}} auream, quam ab omnibus iussit adorarī, prōposita mortis poenā iīs, quī pārēre nōllent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"statuere","latin":"(statuō) statuere, statuisse, statūtum","headword":"statuere","letter":"s","pos":"verb","posGroup":"verb","english":"fix, determine; to set up, decide","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"statuo","latin":"statuo, statuere, statui, statutus","headword":"statuo","letter":"s","pos":"verb","posGroup":"verb","english":"set up, establish, set, place, build; decide, think","forms":["statuāmus","statuātis","statuendam","statuendum","statuere","statueret","statuerit","statuērunt","statuet","statuētis","statuisse","statuistī","statuit","statuitur","statuō","statūtum","statūtus","statuunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires sufficere cuiusquam nec ferre operis laborem posse; itaque {{statuisse}} imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"statura","latin":"statura, staturae","headword":"statura","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"height, stature","forms":["statūra"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Erat Saūlī ingēns {{statūra}} et fōrma excellēns, adeō ut dignitās corporis dignitātī rēgiae pulchrē convenīret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"status","latin":"status, -ūs","headword":"status","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"state, condition, order","forms":["statuī","status"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"mēnsūrā cubantis fierī : statuī quanta hīc quoque, né possit fierī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"stela","latin":"stela, stelae","headword":"stela","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"pillar; column","forms":["stēlās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Homô meus coepit ad {{stēlās}} facere.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"stella","latin":"stēlla, -ae","headword":"stēlla","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"star","forms":["stēlla","stēllae","stēllam","stellārum","stēllās","stēllīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aemilia: “Hāc nocte hortus obscūrus nōn est, nam lūna et {{stēllae}} lūcent.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"stellatus","latin":"stellatus, stellata, stellatum","headword":"stellatus","letter":"s","pos":"adjective","posGroup":"adjective","english":"starry; set with stars; sparkling, glittering; shaped like a star or \"X\"","forms":["stēllātus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cōnspicit. atque illī {{stēllātus}} iaspide fulvā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"stellifer","latin":"stēllifer, -era, -erum","headword":"stēllifer","letter":"s","pos":"adjective","posGroup":"adjective","english":"star-bearing","forms":["stellifer"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quam ob causam summus ille caelī {{stellifer}} cursus, cuius conversiō est concitātior, acūtō et excitātō movētur sonō, gravissimō autem hic lūnāris atque īnfimus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stercoro","latin":"stercoro, stercorare, stercoravi, stercoratus","headword":"stercoro","letter":"s","pos":"verb","posGroup":"verb","english":"void excrement, defecate","forms":["stercora"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Forte ex nīdō hirundinum {{stercora}} calida incidērunt in oculōs dormientīs, unde caecus factus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sterculinum","latin":"sterculinum, sterculini","headword":"sterculinum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"dung heap/hill/pit, manure pile; midden","forms":["sterculīnō","sterculīnum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum tempestātēs pluviae fuerint, ‘quae opera per imbrem fierī potuerint: dōlia lavārī, vīllam pūrgārī, frūmentum trānsferrī, stercus forās efferrī, {{sterculīnum}} fierī, sēmen pūrgārī, tīmēs sarcīrī, novōs fierī’.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"stercus","latin":"stercus, stercoris","headword":"stercus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"filth, manure","forms":["stercore","stercus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ab asse crēvit, et parātus fuit quadrantem dē {{stercore}} mordlcus @ tollere!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sterilis","latin":"sterilis, -e","headword":"sterilis","letter":"s","pos":"adjective","posGroup":"adjective","english":"barren, sterile; barren, unable to bear children","forms":["sterilēs","sterilis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Abrahamus iam senuerat, et Sarā eius uxor erat {{sterilis}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sternere","latin":"(sternō) sternere, strāvisse, strātum","headword":"sternere","letter":"s","pos":"verb","posGroup":"verb","english":"spread, strew; to spread, lay out","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"sterno","latin":"sternō, -ere, strāvī, strātum","headword":"sternō","letter":"s","pos":"verb","posGroup":"verb","english":"to lay low, overthrow","forms":["sternantur","sterne","sternit","sternitur","sternunt","sternuntur","strāta","strātīs","strātōs","strāverant","Strāvimus","strāvit"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Servī domum tōtam multīs pulchrīsque flōribus exōrnāverant, vestibus pretiōsīs omnēs lectōs {{strāverant}}, in mēnsās vāsa argentea, in quibus cibōs optimōs appōnēbant, et pōcula aurea, in quae fundēbant dulcissimum vīnum, imposuerant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sterto","latin":"sterto, stertere, stertui, -","headword":"sterto","letter":"s","pos":"verb","posGroup":"verb","english":"snore","forms":["sterti","stertit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Iūlius {{stertit}}: “Ssst-rrrch, ssst-rrrch...!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"stichus","latin":"Stichus, Stichi","headword":"Stichus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"common slave name; representative name in legal forms, Anyslave","forms":["Stiche","Stichus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sîc amîcus vester, quī fuit rāna, “Interim, {{Stiche}}, prôfer vîtälia in quibus volô mē ef- ferrî!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"stillare","latin":"(stīllō) stīllāre","headword":"stīllāre","letter":"s","pos":"","posGroup":"other","english":"drip","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"stilus","latin":"stilus, -ī","headword":"stilus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"stylus; stylus, pen; pen, stylus","forms":["stilī","stilō","stilum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dāvus Mārcō librum et tabulam et {{stilum}} et rēgulam affert.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"stimulare","latin":"(stimulō) stimulāre","headword":"stimulāre","letter":"s","pos":"","posGroup":"other","english":"spur on, stimulate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"stimulo","latin":"stimulo, stimulare, stimulavi, stimulatus","headword":"stimulo","letter":"s","pos":"verb","posGroup":"verb","english":"urge forward with a goad, torment,\"sting\"; incite, rouse to frenzy","forms":["stimulābant","stimulābat","stimulant","stimulante","stimulat"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Crēscēbat in diēs Saūlis odium, {{stimulante}} invidiā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"stimulus","latin":"stimulus, stimuli","headword":"stimulus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"spur/goad; trap/spike in earth; prick/sting/cause of torment/torture instrument","forms":["stimulī","stimulis","stimulos"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ante haec taleae pedem longae ferreis hamis infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos {{stimulos}} nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stipator","latin":"stipator, stipatoris","headword":"stipator","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"one of train surrounding a king; bodyguard, close attendant","forms":["stīpātōribus","stīpātōrum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In tantā tamque corruptā cīvitāte Catilīna — id quod factū facillimum erat — omnium flāgitiōrum atque facinorum circum sē tamquam {{stīpātōrum}} catervās habēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"stipendiarius","latin":"stipendiarius, stipendiaria, stipendiarium","headword":"stipendiarius","letter":"s","pos":"adjective","posGroup":"adjective","english":"mercenary; paying tribute in the form of cash","forms":["stīpendiāriam","stipendiariis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne {{stipendiariis}} Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris subvectionibus laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stipendium","latin":"stipendium, -ī","headword":"stipendium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"salary; pay, service","forms":["stīpendia","stīpendiī","stīpendiīs","stipendio","stīpendium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Discedentibus his breviter sua in Aeduos merita exposuit: quos et quam humiles accepisset, compulsos in oppida, multatos agris, omnibus ereptis copiis, imposito {{stipendio}}, obsidibus summa cum contumelia extortis, et quam in fortunam quamque in amplitudinem deduxisset, ut non solum in pristinum statum redissent sed omnium temporum dignitatem et gratiam antecessisse viderentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stipes","latin":"stīpes, -itis (m.)","headword":"stīpes","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"stake, stick; stake, rough trunk","forms":["stipites","stīpitī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huc illi {{stipites}} demissi et ab infimo revincti, ne revelli possent, ab ramis eminebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stipo","latin":"stipo, stipare, stipavi, stipatus","headword":"stipo","letter":"s","pos":"verb","posGroup":"verb","english":"crowd, press together, compress, surround closely","forms":["stīpante","stīpāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"incessit magnā iuvenum {{stīpante}} catervā.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"stipula","latin":"stipula, stipulae","headword":"stipula","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stalk; stubble; straw; reed played on as a pipe","forms":["stipulā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"dē stipulā Tatiō rēgna tenente fuit.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"stirps","latin":"stirps, -pis ( f.)","headword":"stirps","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"origin, stock, offspring; stock, lineage","forms":["stirpe","stirpem","stirpēs","stirps"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mortuō Ochosia, māter eius {{stirpem}} rēgiam interēmit, et rēgnum occupāvit. -Onus tantum Ochosfae fīlius, nōmine IOās, prōmiscuae caedī ēreptus est, in templŌ cum nūtrīce occultātus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sto","latin":"stō, -āre, stetī, statum","headword":"stō","letter":"s","pos":"verb","posGroup":"verb","english":"stand","forms":["stā","stābam","stābant","stābat","stābis","stāns","stant","stantem","stantēs","stantī","Stantibus","stāre","stārent","stāret","stās","stat","stāte","stātis","statō","statu","statum","stent","stēs","stet","steterant","steterat","stetēre","stetērunt","stetit","stō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Pompei commodiorem in {{statum}} pervenisse intellegeret, in Transalpinam Galliam profectus est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stoicus","latin":"Stoicus, Stoica, Stoicum","headword":"Stoicus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Stoic","forms":["Stoicō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eram cum Stoicō Diodōtō, quī cum habitāvisset apud mē mēcumque vīxisset, nūper est domī meae mortuus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stola","latin":"stola, stolae","headword":"stola","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stola, Roman matron's outer garment; dress; clothing","forms":["stolam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dīxit autem pater ad servōs suōs: “Citō prōferte {{stolam}} prīmam et induite illum, et date ānulum in manum eius et calceāmenta in pedēs eius.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"stolatus","latin":"stolatus, stolata, stolatum","headword":"stolatus","letter":"s","pos":"adjective","posGroup":"adjective","english":"stola-wearing; befitting a matron","forms":["stolātae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Anteā {{stolātae}} luī/ū ��� �ӓ îbant nüdîs pedibus in clîvum, passîs ca- pill.îs, mentibus pürîs, et Iovem aquam exôräbant.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"stolide","latin":"stolide","headword":"stolide","letter":"s","pos":"adverb","posGroup":"adverb","english":"stupidly, obtusely; brutishly; solidly (physical growth), thickly","forms":["stolidē"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Quid mē aspectās, stolidē?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"strages","latin":"strāgēs, -is ( f.)","headword":"strāgēs","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"slaughter; slaughter, heap of slain","forms":["strāge"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Alterum intāctum ferrō corpus et gemināta victōria ferōcem in certāmen tertium dabat; alter, fessum vulnere fessum cursū corpus trahēns vīctusque frātrum ante sē {{strāge}}, victōrī obicitur hostī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stragulus","latin":"stragulus, stragula, stragulum","headword":"stragulus","letter":"s","pos":"adjective","posGroup":"adjective","english":"covering","forms":["strāgulam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nôn est mōrātus Stichus, sed et {{strāgulam}} albam et praetextam in triclînium attulit. (Quās Trimalchiô mîrätus est) iussitque nôs temptāre an bonīs länîs essent côn- fecta.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"stramentum","latin":"strāmentum, ī","headword":"strāmentum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"straw; straw, thatch","forms":["stramenta","strāmentō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Prima luce magnum numerum impedimentorum ex castris mulorumque produci deque his {{stramenta}} detrahi mulionesque cum cassidibus equitum specie ac simulatione collibus circumvehi iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stratum","latin":"stratum, strati","headword":"stratum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"coverlet; bed, couch; horse-blanket","forms":["strātum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tandem puer 'cēnam parātam esse' nūntiat. 'Trīclīnium intrēmus!' inquit Iūlius, atque convīvae laetī trīclīnium flōribus exōrnātum et veste pulcherrimā {{strātum}} intrant.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"strenuous","latin":"strenuous, -a, -um","headword":"strenuous","letter":"s","pos":"","posGroup":"other","english":"active, vigorous","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"strenuus","latin":"strenuus, strenua, strenuum","headword":"strenuus","letter":"s","pos":"adjective","posGroup":"adjective","english":"active, vigorous, strenuous","forms":["strēnuē","strēnuī","strēnuīs","strēnuō","strēnuum","strēnuus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ille fuit vēnātor {{strēnuus}}, hic autem placidus et simplex mōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"strepere","latin":"(strepō) strepere, -uisse","headword":"strepere","letter":"s","pos":"","posGroup":"other","english":"make a noise","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"strepitus","latin":"strepitus, -ūs","headword":"strepitus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"(m.) noise, din; noise, racket; noise, racket, uproar","forms":["strepitū","strepitum","strepitus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Solve canem tuum!” clāmat aliquis, dum aliī magnō cum strepitū forēs frangere cōnantur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"strepo","latin":"strepo, strepere, strepui, strepitus","headword":"strepo","letter":"s","pos":"verb","posGroup":"verb","english":"make a loud noise; shout confusedly; resound","forms":["strepente","strepere"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Accessēre continuô duo gäïÿla servī, et symphôniä {{strepente}} scrütärî paleam coepērunt, ërutāque subinde pävônîna ôva dîvîsëre convîvîs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"strictus","latin":"strictus, stricta, strictum","headword":"strictus","letter":"s","pos":"adjective","posGroup":"adjective","english":"tight, close, strait, drawn together","forms":["strictīs","strictō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quae simul ac videt, strictō ēnse Medea guttur senis secat; Medea veterem sanguinem effundit ut sūcīs novīs eum repleat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"strideo","latin":"strideo, stridere, stridi, -","headword":"strideo","letter":"s","pos":"verb","posGroup":"verb","english":"creak, squeak, grate, shriek, whistle; (make shrill sound); hiss; gnash","forms":["strīdēbat","strīdēns"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tālia iactantī {{strīdēns}} Aquilōne procellā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"strigilis","latin":"strigilis, strigilis","headword":"strigilis","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"strigil, an instrument used to scrape the skin after the bath","forms":["strigilem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Iūlius, quī amīcōs invītāvit, ante cēnam cum Gāiō amīcō in balneum itūrus est, ut lavētur et exerceātur.] [Iūlius, ad servōs:] “Afferte sabana ad balneum, {{strigilem}}, ampullam!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"stringere","latin":"(stringō) stringere, -nxisse, -ctum","headword":"stringere","letter":"s","pos":"","posGroup":"other","english":"draw, unsheathe","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"stringo","latin":"stringo, stringere, strinxi, strictus","headword":"stringo","letter":"s","pos":"verb","posGroup":"verb","english":"draw tight; draw; graze; strip off","forms":["stringere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et silvīs aptāre trabēs et {{stringere}} rēmōs:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"stropha","latin":"stropha, strophae","headword":"stropha","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"trick, artifice","forms":["strophae","strophās"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Pessimē mihi erat nē hîs precibus per rîdiculum aliquid cata- {{strophae}} quaererētur; nec enirn adhūc exciderat cocus ille quî oblîtus fuerat porcum exinterāre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"structor","latin":"structor, structoris","headword":"structor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"builder, carver","forms":["strūctor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"[Ferculum prîmum: duodecim signa caelestial] Laudätiônem ferculum est însecütum, plānē nôn prô oculôs: rotundum enim repositôrium duodecim habēbat signa in orbe disposita, super quae proprium conveniēn- temque māteriae {{strūctor}} imposuerat cibum: statēram in cuius alterâ parte scriblîta erat, in alterā placentā; In mediô autem caespes cum herbîs excîsus favum sustinēbat.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"struere","latin":"(struō) struere, struxisse,","headword":"struere","letter":"s","pos":"","posGroup":"other","english":"arrange, contrive, devise structum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"strues","latin":"strues, struis","headword":"strues","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"heap, pile; row of sacrificial cakes","forms":["struem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ubī pervēnērunt ambō in locum dēsignātum, Abrahamus exstrūxit āram, disposuit ligna, alligāvit Isaacum super {{struem}} lignōrum, deinde arripuit gladium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"struo","latin":"struo, struere, struxi, structus","headword":"struo","letter":"s","pos":"verb","posGroup":"verb","english":"build, construct","forms":["struere","struī","struis","struit","strūxerat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"prae-{{strūxerat}} : omnia (ex)strūxerat","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"studeo","latin":"studeo, studere, studui, -","headword":"studeo","letter":"s","pos":"verb","posGroup":"verb","english":"desire, be eager for; busy oneself with; strive","forms":["studēbat","studendum","student","studentem","studeo","studere","studeret","studēs","studet","studuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Qua oblata potestate omnibus his civitatibus obsides imperat, certum numerum militum ad se celeriter adduci iubet, armorum quantum quaeque civitas domi quodque ante tempus efficiat constituit; in primis equitatui {{studet}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"studere","latin":"(studeō) studēre, studuisse","headword":"studēre","letter":"s","pos":"verb","posGroup":"verb","english":"(+ dat.) devote oneself to; to study, be devoted to (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"studiose","latin":"studiose, studiosius, studiosissime","headword":"studiose","letter":"s","pos":"adverb","posGroup":"adverb","english":"eagerly, zealously, studiously, ardently, earnestly, attentively, assiduously","forms":["studiōsē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fuit Ēchō iūcundissimā nymphā, quae tam pulchrā vōce canere fābulāsque tam bellē nārrāre solēbat, ut ipsa Iūnō, deōrum rēgīna, saepe ex altō Olympō dēscenderet, ut eam canentem loquentemve studiōsē audīret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"studiosus","latin":"studiōsus, -a, -um","headword":"studiōsus","letter":"s","pos":"adjective","posGroup":"adjective","english":"(+ gen.) interested in; eager, fond of","forms":["studiōsa","studiōsī","studiosior","studiōsissima","studiōsissimē","studiōsissimus","studiōsius","studiōsō","studiōsōs","studiōsum","studiōsus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Studiōsissima}} enim sum eās aspiciendī!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"studium","latin":"studium, -ī","headword":"studium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"interest, study; study, eagerness","forms":["studi","studia","studiīs","studio","studium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"De re frumentaria Boios atque Aeduos adhortari non destitit; quorum alteri, quod nullo {{studio}} agebant, non multum adiuvabant, alteri non magnis facultatibus, quod civitas erat exigua et infirma, celeriter quod habuerunt consumpserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stulte","latin":"stultē","headword":"stultē","letter":"s","pos":"adverb","posGroup":"adverb","english":"stupidly","forms":["stultē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nōn cōgitās antequam mihi respondēs, Iūlia; itaque prāvē ac stultē respondēs!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"stultitia","latin":"stultitia, -ae","headword":"stultitia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stupidity, folly","forms":["stultitia","stultitiam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nolite hos vestro auxilio exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec {{stultitia}} ac temeritate vestra aut animi imbecillitate omnem Galliam prosternere et perpetuae servituti subicere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"stultus","latin":"stultus, -a, -um","headword":"stultus","letter":"s","pos":"adjective","posGroup":"adjective","english":"stupid, foolish","forms":["stulta","stultae","stultō","stultum","stultus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Fabia Mārcum puerum {{stultum}} esse putat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"stupefacio","latin":"stupefacio, stupefacere, stupefeci, stupefactus","headword":"stupefacio","letter":"s","pos":"verb","posGroup":"verb","english":"strike dumb/stun with amazement, stupefy; strike senseless","forms":["stupefactus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hoc somniō et vōce dīvīnā {{stupefactus}} Aenēās ē lectō sē corripuit manūsque ad caelum tendēns deōs precātus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stupefactus","latin":"stupefactus, -a, -um","headword":"stupefactus","letter":"s","pos":"","posGroup":"other","english":"amazed, stupefied","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"stupeo","latin":"stupeō, -ēre, stupuī","headword":"stupeō","letter":"s","pos":"verb","posGroup":"verb","english":"be amazed, be shocked","forms":["stupenda","stupēns","stupentēs","stupentī","stupentibus","stupet","stupuērunt","stupuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Moysēs, ut pharaōnis pertināciam vinceret, multa et {{stupenda}} ēdidit prōdigia, quae vocantur ‘plāgae Aegyptī’.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"stupere","latin":"(stupeō) stupēre, stupuisse","headword":"stupēre","letter":"s","pos":"","posGroup":"other","english":"be aghast","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"stupidus","latin":"stupidus, stupida, stupidum","headword":"stupidus","letter":"s","pos":"adjective","posGroup":"adjective","english":"senseless, stunned; stupid, dull","forms":["STVPIDO"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"DE CORVO {{STVPIDO}}","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"stupor","latin":"stupor, stuporis","headword":"stupor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"numbness, torpor; stupefaction; stupidity","forms":["stupor"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{stupor}} -ōrīs 7! — factum stultum, Quī stupor hic, Menelāe,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"stuprare","latin":"(stuprō) stuprāre","headword":"stuprāre","letter":"s","pos":"","posGroup":"other","english":"violate, rape","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"stupro","latin":"stupro, stuprare, stupravi, stupratus","headword":"stupro","letter":"s","pos":"verb","posGroup":"verb","english":"have (illicit) sexual intercourse with","forms":["stuprandae","stuprō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Tarquinium mala libīdō Lūcrētiae per vim {{stuprandae}} capit; cum fōrmā tum spectāta castitās incitat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"stuprum","latin":"stuprum, -ī","headword":"stuprum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"rape, defilement; shameful violation","forms":["stupra","stuprī","stuprum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"stuprī, dēdecoris ā virō argūtam meō!—","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"stygius","latin":"Stygius, Stygia, Stygium","headword":"Stygius","letter":"s","pos":"adjective","posGroup":"adjective","english":"Stygian; of the Styx (river of the underworld); infernal","forms":["Stygiā","Stygiās","Stygiō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"lūmina mors clausit dominī mīrantia fōrmam: tum quoque sē, postquam est mfemā sēde receptus, in Stygiā spectābat aquā.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"styx","latin":"Styx, Stygis","headword":"Styx","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"the river Styx (in the underworld)","forms":["Stygā","Stygem","Styx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Orpheus, postquam ad superās aurās mortem Eurydicēs satis plōrāvit, ausus est ad {{Stygem}} dēscendere et eam inter umbrās invenīre.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"suadeo","latin":"suadeo, suadere, suasi, suasus","headword":"suadeo","letter":"s","pos":"verb","posGroup":"verb","english":"urge, recommend; suggest; induce; propose, persuade, advise","forms":["suādēbit","suādent","suādente","suādentibus","suādeō","suādēre","suādēret","suādēs","suādet","suāserit","suāsērunt","suāsit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tunc aulicī eī {{suāsērunt}} ut aliquem arcesseret, quī citharam scīret pulsāre, ad dēlīniendum aegrum eius animum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suadere","latin":"(suādeō) suādēre, suāsisse  ({i}intr. + dat.{/i})","headword":"suādēre","letter":"s","pos":"verb","posGroup":"verb","english":"advise; to urge, persuade (+ dat.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"suavis","latin":"suavis, suave, suavior -or -us, suavissimus -a -um","headword":"suavis","letter":"s","pos":"adjective","posGroup":"adjective","english":"agreeable, pleasant, gratifying, sweet; charming, attractive","forms":["suāve","suāvem","suāvēs","suāvī","suāvior","suāvius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ingēns fluvius irrigābat hortum: erant ibi omnēs arborēs iūcundae aspectū, et frūctūs gustū {{suāvēs}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suaviter","latin":"suaviter","headword":"suaviter","letter":"s","pos":"adverb","posGroup":"adverb","english":"pleasantly, sweetly","forms":["suāviter"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Suāviter}} sit potins, et tū, Hermerôs, parce adulëscentulô!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sub","latin":"sub","headword":"sub","letter":"s","pos":"preposition","posGroup":"preposition","english":"(prp. + abl./acc.) under, at the foot of, near; under, beneath","forms":["sub"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Erat e regione oppidi collis {{sub}} ipsis radicibus montis egregie munitus atque ex omni parte circumcisus; quem si tenerent nostri, et aquae magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subagrestis","latin":"subagrestis, -e","headword":"subagrestis","letter":"s","pos":"","posGroup":"other","english":"somewhat rustic","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subarmalis","latin":"subarmalis, subarmalis, subarmale","headword":"subarmalis","letter":"s","pos":"adjective","posGroup":"adjective","english":"passing underarm","forms":["subarmāle"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dā {{subarmāle}}, cinge mē!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"subdere","latin":"(subdō) subdere (< dare)","headword":"subdere","letter":"s","pos":"","posGroup":"other","english":"lay under, subdue, substitue","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subditivus","latin":"subditivus, subditiva, subditivum","headword":"subditivus","letter":"s","pos":"adjective","posGroup":"adjective","english":"substituted, counterfeit; spurious","forms":["subditīvus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Amphitryō {{subditīvus}} eccum exit forās","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"subdo","latin":"subdo, subdere, subdidi, subditus","headword":"subdo","letter":"s","pos":"verb","posGroup":"verb","english":"place under, apply; supply","forms":["subdidit"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ergō abolendō rūmōrī Nerō {{subdidit}} reōs et quaesītissimīs poenīs affēcit quōs — per flāgitia invīsōs — vulgus ‘Christiānōs’ appellābat.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"subdolus","latin":"subdolus, subdola, subdolum","headword":"subdolus","letter":"s","pos":"adjective","posGroup":"adjective","english":"sly, deceitful, treacherous","forms":["subdola","subdolus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Huic rei idoneos homines deligebat quorum quisque aut oratione {{subdola}} aut amicitia facillime capere posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subducere","latin":"(subdūcō) subdūcere (< dūcere)","headword":"subdūcere","letter":"s","pos":"verb","posGroup":"verb","english":"draw up, beach, lead off; to beach, draw up (ships)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"subduco","latin":"subduco, subducere, subduxi, subductus","headword":"subduco","letter":"s","pos":"verb","posGroup":"verb","english":"lead up, carry off; transfer; haul","forms":["subdūcere","subdūcit","subdūcite","subductīs","subdūxit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Urbem quam statuō, vestra est; {{subdūcite}} nāvīs;\nTrōs Tyriusque mihī nūllō discrīmine agētur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"subeo","latin":"subeō, -īre, -iī, -itum","headword":"subeō","letter":"s","pos":"verb","posGroup":"verb","english":"to go under, enter","forms":["subeundam","subeunt","subeuntēs","subi","subiēre","subīre","subit","subitīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sententiis dictis constituunt, ut ei qui valetudine aut aetate inutiles sunt bello oppido excedant atque omnia prius experiantur quam ad Critognati sententiam descendant; illo tamen tempore potius utendum consilio, si res cogat atque auxilia morentur, quam aut deditionis aut pacis {{subeundam}} condicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subicere","latin":"(subiciō) subicere, -iēcisse, -iectum","headword":"subicere","letter":"s","pos":"","posGroup":"other","english":"put under, subject, add","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subicio","latin":"subicio, subicere, subjeci, subjectus","headword":"subicio","letter":"s","pos":"verb","posGroup":"verb","english":"throw under, place under; make subject; expose","forms":["subicere","subicerent","subiēcit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nolite hos vestro auxilio exspoliare, qui vestrae salutis causa suum periculum neglexerunt, nec stultitia ac temeritate vestra aut animi imbecillitate omnem Galliam prosternere et perpetuae servituti {{subicere}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subiectus","latin":"subiectus, -a, -um (+ dat.)","headword":"subiectus","letter":"s","pos":"adjective","posGroup":"adjective","english":"situated under","forms":["subiecta","subiectī","subiectīs","subiectos","subiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante se populi Romani imperio {{subiectos}} dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subigere","latin":"(subigō) subigere (< agere)","headword":"subigere","letter":"s","pos":"","posGroup":"other","english":"subdue, drive, force","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subigo","latin":"subigo, subigere, subegi, subactus","headword":"subigo","letter":"s","pos":"verb","posGroup":"verb","english":"conquer, subjugate; compel","forms":["subāctā","subacti","subāctūrae","subāctus","subēgit","subigendōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Facere, quod nostri maiores nequaquam pari bello Cimbrorum Teutonumque fecerunt; qui in oppida compulsi ac simili inopia {{subacti}} eorum corporibus qui aetate ad bellum inutiles videbantur vitam toleraverunt neque se hostibus tradiderunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subiicio","latin":"subjicio, subjicere, subjeci, subjectus","headword":"subjicio","letter":"s","pos":"verb","posGroup":"verb","english":"throw under, place under; make subject; expose","forms":["subiiciēmur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Num {{subiiciēmur}} ditiōnī tuae?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"subinde","latin":"subinde","headword":"subinde","letter":"s","pos":"adverb","posGroup":"adverb","english":"immediately afterward; soon after, repeatedly","forms":["subinde"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Accessēre continuô duo gäïÿla servī, et symphôniä strepente scrütärî paleam coepērunt, ërutāque {{subinde}} pävônîna ôva dîvîsëre convîvîs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"subire","latin":"(subeō) subīre, subiisse","headword":"subīre","letter":"s","pos":"","posGroup":"other","english":"undergo","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"subito","latin":"subitō","headword":"subitō","letter":"s","pos":"adverb","posGroup":"adverb","english":"suddenly","forms":["subito"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Illi {{subito}} ex omnibus partibus evolaverunt murumque celeriter compleverunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subitus","latin":"subitus, -a, -um","headword":"subitus","letter":"s","pos":"adjective","posGroup":"adjective","english":"sudden","forms":["subitā","subitus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"At Deus dīxit Iosue: “Nē timeās eōs: tua erit victōria.” Iosue igitur magnō impetū illōs adortus est, quī, subitā formīdine correptī, fūgērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sublatus","latin":"sublatus, sublata, sublatum","headword":"sublatus","letter":"s","pos":"adjective","posGroup":"adjective","english":"elated","forms":["sublātus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Necdum sciëbä- mūs quô mitterēmus suspiciônës nostrās, cum extrā triclî- nium clāmor {{sublātus}} est ingēns, et ecce canēs Lacônicî etiam circā mēnsam discurrere coepērunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"sublegere","latin":"(sublegō) sublegere (< legere)","headword":"sublegere","letter":"s","pos":"","posGroup":"other","english":"gather","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sublevo","latin":"sublevo, sublevare, sublevavi, sublevatus","headword":"sublevo","letter":"s","pos":"verb","posGroup":"verb","english":"lift up, raise; support; assist; lighten","forms":["sublevandō","sublevari","sublevat","sublevātā","sublevatus","subleventur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Id esse facile, quod equitatu ipsi abundent et quod anni tempore {{subleventur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sublicis","latin":"sublicis, sublicis","headword":"sublicis","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"wooden stake or pile; (normally used as support for bridge/heavy structure)","forms":["sublicis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"His quam longissime possent egredi iussis, cum iam ex diei tempore coniecturam ceperat in castra perventum,: isdem {{sublicis}}, quarum pars inferior integra remanebat, pontem reficere coepit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sublicius","latin":"sublicius, sublicia, sublicium","headword":"sublicius","letter":"s","pos":"adjective","posGroup":"adjective","english":"resting on/supported by piles; (Pons Sublicius/Pile Bridge, across the Tiber)","forms":["Subliciō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Id ponte Subliciō, tum prīmum in Tiberī factō, urbī coniūnctum est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sublimis","latin":"sublīmis, -e","headword":"sublīmis","letter":"s","pos":"adjective","posGroup":"adjective","english":"high (up), aloft","forms":["sublīmem","sublīmis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum perfūsus horrōre cōnstitissem, \"Abī, nūntiā\" inquit \"Rōmānīs, caelestēs ita velle ut mea Rōma caput orbis terrārum sit; proinde rem mīlitārem cōlant sciantque — et ita posterīs trādant — nūllās opēs hūmānās armīs Rōmānīs resistere posse.\" Haec\" inquit \"locūtus {{sublīmis}} abiit.\" Illī virō nūntiantī haec plēbs crēdidit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"subluo","latin":"subluo, subluere, sublui, sublutus","headword":"subluo","letter":"s","pos":"verb","posGroup":"verb","english":"wash, flow at the base of","forms":["subluebant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ipsum erat oppidum Alesia in colle summo, admodum edito loco, ut nisi obsidione expugnari non posse videretur; cuius collis radices duo duabus ex partibus flumina {{subluebant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"submergere","latin":"(submergō) submergere, -mersisse,  -mersum","headword":"submergere","letter":"s","pos":"","posGroup":"other","english":"sink, submerge","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"submergo","latin":"submergo, submergere, submersi, submersus","headword":"submergo","letter":"s","pos":"verb","posGroup":"verb","english":"plunge under, submerge","forms":["submergere","submergeret","submergit","submersa","submersae","submersīs","submersum","submersus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At illīc senēs nūllās aliās domōs praeter suam casam vīdērunt quae sola in latere collis stābat; nam omnia cētera palūde erant {{submersa}}.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"submittere","latin":"(submittō) submittere (< mittere)","headword":"submittere","letter":"s","pos":"verb","posGroup":"verb","english":"lower; to put down, lower, humble, yield","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"submitto","latin":"submitto, submittere, submisi, submissus","headword":"submitto","letter":"s","pos":"verb","posGroup":"verb","english":"allow to grow long; emit, put forth, raise; lower, moderate, relieve; submit","forms":["submīsit","submittere"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"ille caput viridī fessum {{submīsit}} in herbā,","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"submoveo","latin":"submoveo, submovere, submovi, submotus","headword":"submoveo","letter":"s","pos":"verb","posGroup":"verb","english":"remove; drive off, dislodge; expel; ward off; keep at a distance; bar/debar","forms":["submōtā","submōtō","submovēre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ac prīmō missilibus {{submovēre}} hostem, deinde ad ērumpendum etiam animus erat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"submovere","latin":"(submoveō) submovēre (< movēre)","headword":"submovēre","letter":"s","pos":"","posGroup":"other","english":"remove, drive off","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subnecto","latin":"subnecto, subnectere, subnexui, subnexus","headword":"subnecto","letter":"s","pos":"verb","posGroup":"verb","english":"bind under, add, subjoin, fasten up","forms":["subnectēns","subnectit","subnexus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"aurea {{subnectēns}} exsertae cingula mammae,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"subnixus","latin":"subnīxus, -a, -um","headword":"subnīxus","letter":"s","pos":"adjective","posGroup":"adjective","english":"resting on, relying on","forms":["subnīxa","subnīxōs","subnīxus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Domus, in quā omnis populus et prīncipēs Philistaeōrum epulābantur, {{subnīxa}} erat duābus columnīs mīrae magnitūdinis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suboles","latin":"suboles, subolis","headword":"suboles","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"shoot, sucker; race; offspring; progeny","forms":["subolēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ante fugam {{subolēs}}, sī quis mihi parvulus aulā","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"subrigo","latin":"subrigo, subrigere, subrexi, subrectus","headword":"subrigo","letter":"s","pos":"verb","posGroup":"verb","english":"rise, lift (Collins)","forms":["subrigit"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tot linguae, totidem ōra sonant, tot {{subrigit}} aurīs.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"subripio","latin":"subripio, subripere, subripui, subreptus","headword":"subripio","letter":"s","pos":"verb","posGroup":"verb","english":"snatch away, steal","forms":["Subripuistis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"{{Subripuistis}} scyphum argenteum quō dominus meus ūtitur; improbē fēcistis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"subrubeo","latin":"subrubeo, subrubere, -, -","headword":"subrubeo","letter":"s","pos":"verb","posGroup":"verb","english":"be tinged with red or purple","forms":["subrubet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"plénaque purpureó {{subrubet}} ūva merō,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"subscribere","latin":"(subscrībō) subscrībere (< scrībere)","headword":"subscrībere","letter":"s","pos":"","posGroup":"other","english":"write underneath","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subscribo","latin":"subscribo, subscribere, subscripsi, subscriptus","headword":"subscribo","letter":"s","pos":"verb","posGroup":"verb","english":"write below, subscribe","forms":["subscrīpsērunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cornēlium Rūfīnum, quī bis cōnsul et dictātor fuerat, senātū mōvērunt: causamque istī notae {{subscrīpsērunt}} 'quod eum comperissent argentī factī cēnae grātiā decem pondō lībrās habēre.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"subseco","latin":"subseco, subsecare, subsecui, subsectus","headword":"subseco","letter":"s","pos":"verb","posGroup":"verb","english":"cut away below; pare (the nails)","forms":["subsecuisse"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"in-adsuētus -ā -um («» solitus) 7 quī fertur inadsuēta {{subsecuisse}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"subsellium","latin":"subsellium, -ī","headword":"subsellium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"bench","forms":["subsellia","subselliī","subselliōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cornēliō Nāsīcā in Capitōliō ab optimātibus occīsus est, ictus prīmum fragmentīs subselliī, et inter aliōs quī in eādem sēditiōne occīsī erant īnsepultus in flūmen prōiectus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"subsequor","latin":"subsequor, subsequi, subsecutus sum","headword":"subsequor","letter":"s","pos":"verb","posGroup":"verb","english":"follow close after; pursue; support","forms":["subsequar","subsequi","subsequitur","subsequor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Vercingetorix minoribus Caesarem itineribus {{subsequitur}} et locum castris deligit paludibus silvisque munitum ab Avarico longe milia passuum XVI.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subsidium","latin":"subsidium, -ī","headword":"subsidium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"support, help, resource; help, relief","forms":["subsidia","subsidiis","subsidio","subsidium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, legatos mittunt {{subsidium}} rogatum, quo facilius hostium copias sustinere possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"substantia","latin":"substantia, substantiae","headword":"substantia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"nature; substance, resources, wealth; [omnem ~ => every living thing (Plater)]","forms":["substantiae","substantiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et dīxit adolēscentior patrī: ' P āter, dā mihi portiōnem {{substantiae}} quae mē contingit. ' Et pater dīvīsit illī substantiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"subsum","latin":"subsum, subesse, subfui, subfuturus","headword":"subsum","letter":"s","pos":"verb","posGroup":"verb","english":"be underneath/a basis for discussion/close at hand as a reserve, be near","forms":["suberit","subest"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sīve diēs {{suberit}} nātālis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"subter","latin":"subter","headword":"subter","letter":"s","pos":"adverb","posGroup":"adverb","english":"below, underneath","forms":["subter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur {{subter}} dēnsam quercum, coma eius implicitā est rāmīs, et ipse suspēnsus adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"subterraneus","latin":"subterrāneus, -a, -um","headword":"subterrāneus","letter":"s","pos":"adjective","posGroup":"adjective","english":"underground","forms":["subterrānea","subterrāneam","subterrāneus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In eā valle ōlim magna palūs erat, quae tum dēmum siccāta est cum aqua palūdis in flūmen dēdūcerētur per cloācam {{subterrāneam}}, quae appellātur \"cloāca Maxima\".","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"subtraho","latin":"subtraho, subtrahere, subtraxi, subtractus","headword":"subtraho","letter":"s","pos":"verb","posGroup":"verb","english":"carry off; take away; subtract","forms":["subtrahebant"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis {{subtrahebant}}, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque usitatum est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suburbanus","latin":"suburbānus, -a, -um","headword":"suburbānus","letter":"s","pos":"adjective","posGroup":"adjective","english":"near the city; near the city, suburban","forms":["suburbānīs","suburbānum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nē in Campāniā quidem plūrēs vīllae sunt, quamquam multī Rōmānī in ōra maritima eius regiōnis vīllās possident; nam plūrimī Rōmānī sub urbe Rōmā habitāre volunt in villīs {{suburbānīs}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"subvectio","latin":"subvectio, subvectionis","headword":"subvectio","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"transporting (of supplies) to a center","forms":["subvectionibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Magnam haec res Caesari difficultatem ad consilium capiendum adferebat: si reliquam partem hiemis uno loco legiones contineret, ne stipendiariis Aeduorum expugnatis cuncta Gallia deficeret, quod nullum amicis in eo praesidium videret positum esse; si maturius ex hibernis educeret, ne ab re frumentaria duris {{subvectionibus}} laboraret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subvenio","latin":"subveniō, -īre, -vēnī, -ventum","headword":"subveniō","letter":"s","pos":"verb","posGroup":"verb","english":"come to the aid of, help (+ dat.)","forms":["subveniendum","subvenire","subvenīret","Subvenīte","subveniundum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Conantibus auxiliari suis, 'Frustra', inquit, 'meae vitae {{subvenire}} conamini, quem iam sanguis viresque deficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"subvenire","latin":"(subveniō) subvenīre (< venīre)","headword":"subvenīre","letter":"s","pos":"","posGroup":"other","english":"come to help (+ dat.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"subverto","latin":"subverto, subvertere, subverti, subversus","headword":"subverto","letter":"s","pos":"verb","posGroup":"verb","english":"overturn, cause to topple; overthrow, destroy, subvert","forms":["subvertentem","subvertit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum Aegyptiī prōgrederentur in mediō marī, Dominus {{subvertit}} eōrum currūs et dēiēcit equitēs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"subvolvo","latin":"subvolvo, subvolvere, -, -","headword":"subvolvo","letter":"s","pos":"verb","posGroup":"verb","english":"roll uphill","forms":["subvolvere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"mōlīrīque arcem et manibus {{subvolvere}} saxa,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"succedere","latin":"(succēdō) succēdere (< cēdere)","headword":"succēdere","letter":"s","pos":"","posGroup":"other","english":"enter, succeed, follow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"succedo","latin":"succedo, succedere, successi, successus","headword":"succedo","letter":"s","pos":"verb","posGroup":"verb","english":"climb; advance; follow; succeed in","forms":["succēdēbant","succederent","succēdite","succedunt","successerat","successerit","successerunt","successit","successūrus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri {{successit}} tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"succendo","latin":"succendo, succendere, succendi, succensus","headword":"succendo","letter":"s","pos":"verb","posGroup":"verb","english":"set on fire","forms":["succenderant","succendere","succendī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Procumbunt omnibus Gallis ad pedes Bituriges, ne pulcherrimam prope totius Galliae urbem, quae praesidio et ornamento sit civitati, suis manibus {{succendere}} cogerentur; facile se loci natura defensuros dicunt, quod prope ex omnibus partibus flumine et palude circumdata unum habeat et perangustum aditum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"succensus","latin":"succēnsus, -a, -um","headword":"succēnsus","letter":"s","pos":"adjective","posGroup":"adjective","english":"set on fire, burning","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"successor","latin":"successor, -ōris (m.)","headword":"successor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"successor","forms":["successor","successōrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Osfās Amasīae fīlius et {{successor}} fuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"successus","latin":"successus, -ūs","headword":"successus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"success; outcome, success","forms":["successū"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Metellus variō successū contrā Sertōrium dīmicāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"succingere","latin":"(succingō) succingere (< cingere)","headword":"succingere","letter":"s","pos":"","posGroup":"other","english":"surround","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"succingo","latin":"succingo, succingere, succinxi, succinctus","headword":"succingo","letter":"s","pos":"verb","posGroup":"verb","english":"gather up with a belt or girdle; prepare for action; surround","forms":["succīnctae","succīnctam","succingitur"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Scylla latus dextrum, laevum inrequiēta Charybdis\nīnfestat; vorat haec raptās revomitque carīnās;\nilla ferīs canibus {{succingitur}}, illa etiam nunc\nvirginis ōra gerēns, et, sī nōn omnia vātēs\nficta relīquērunt, aliquō quoque tempore virgō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"succlamare","latin":"(succlāmō) succlāmāre","headword":"succlāmāre","letter":"s","pos":"","posGroup":"other","english":"shout in response","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"succlamo","latin":"succlamo, succlamare, succlamavi, succlamatus","headword":"succlamo","letter":"s","pos":"verb","posGroup":"verb","english":"shout in response (to)","forms":["succlāmātum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum Rōmānus, sinū ex togā factō, 'Hīc' inquit 'vōbīs bellum et pācem portō: utrum placet, sūmite!' Sub hanc vōcem haud minus ferōciter 'daret utrum vellet!' {{succlāmātum}} est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"succresco","latin":"succresco, succrescere, succrevi, -","headword":"succresco","letter":"s","pos":"verb","posGroup":"verb","english":"come up; grow up; overflow","forms":["succrēscēbant"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Septem spīcae plēnae ēnāscēbantur in ūnō culmō, aliaeque totidem exīlēs {{succrēscēbant}}, ēspīcās plēnās cōnsūmēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"succumbere","latin":"(succumbō) succumbere, -uisse, -itum","headword":"succumbere","letter":"s","pos":"verb","posGroup":"verb","english":"yield, submit; to yield, sink under","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"succumbo","latin":"succumbo, succumbere, succubui, succubitus","headword":"succumbo","letter":"s","pos":"verb","posGroup":"verb","english":"sink/fall/lie/break down; succumb/collapse (w/weight); suffer/concede defeat","forms":["Succubuit","succumbant","succumbere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ipse adit reliquos, cohortatur ne labori {{succumbant}}; omnium superiorum dimicationum fructum in eo die atque hora docet consistere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"succurrere","latin":"(succurō) succurrere (< currere)","headword":"succurrere","letter":"s","pos":"","posGroup":"other","english":"(run to) help","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"succurro","latin":"succurro, succurrere, succucurri, succursus","headword":"succurro","letter":"s","pos":"verb","posGroup":"verb","english":"run to the aid of, help","forms":["succurrere","succurrerent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Galli inter equites raros sagittarios expeditosque levis armaturae interiecerant, qui suis cedentibus auxilio {{succurrerent}} et nostrorum equitum impetus sustinerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sucus","latin":"sūcus, -ī","headword":"sūcus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"juice, sap; magic potion","forms":["sūcīs","sūcō","sūcōs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"At Minerva eam inventam et in vītam reductam herbae cuiusdam sūcō aspersit; quō factum est ut tōtum eius corpus parvum fieret; in utrōque latere octo gracilia crūra appāruerunt; ex ventre verō iam ab illō tempore stāmen ēmittit: arānea enim facta, ut anteā, etiam nunc tēlās tēxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"sudatorium","latin":"sudatorium, sudatorii","headword":"sudatorium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"sweating-room","forms":["sūdātōrium"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fricā mē! [Ad Gāium:] Venī ad {{sūdātōrium}}!” [In sūdātōrium introeunt.] [Iūlius:] “Sūdās?” [Gāius, sūdōrem dētergēns:] “Sūdō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sudis","latin":"sudis, sudis","headword":"sudis","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"stake, log","forms":["sudēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed ex omnī cōpiā circiter pars quārta erat mīlitāribus armīs īnstrūcta; cēterī, ut quemque cāsus armāverat, sparōs aut lanceās, praeacūtās {{sudēs}} portābant.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"sudo","latin":"sudo, sudare, sudavi, sudatus","headword":"sudo","letter":"s","pos":"verb","posGroup":"verb","english":"sweat, perspire","forms":["sūdāns","Sūdās","Sūdō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fricā mē! [Ad Gāium:] Venī ad sūdātōrium!” [In sūdātōrium introeunt.] [Iūlius:] “{{Sūdās}}?” [Gāius, sūdōrem dētergēns:] “Sūdō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"sudor","latin":"sūdor, -ōris (m.)","headword":"sūdor","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"sweat","forms":["sūdor","sudore","sūdōrem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis summo militum {{sudore}} ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suesco","latin":"suesco, suescere, suevi, suetus","headword":"suesco","letter":"s","pos":"verb","posGroup":"verb","english":"become accustomed (to)","forms":["suēscere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cón-/ad-suétüdo -īnīs f (« -{{suēscere}})","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sufficere","latin":"(sufficiō) sufficere (< facere)","headword":"sufficere","letter":"s","pos":"","posGroup":"other","english":"appoint, substitute","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sufficio","latin":"sufficio, sufficere, suffeci, suffectus","headword":"sufficio","letter":"s","pos":"verb","posGroup":"verb","english":"be sufficient, suffice; stand up to; be capable/qualified; provide, appoint","forms":["suffectō","suffectus","sufficere","sufficit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam vires {{sufficere}} cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suffixum","latin":"suffīxum, -ī","headword":"suffīxum","letter":"s","pos":"","posGroup":"other","english":"suffix","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"suffragari","latin":"(suffrāgor) suffrāgārī","headword":"suffrāgārī","letter":"s","pos":"","posGroup":"other","english":"vote for, support","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"suffragium","latin":"suffrāgium, -ī","headword":"suffrāgium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"vote","forms":["suffragiis","suffrāgium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multitudinis {{suffragiis}} res permittitur; ad unum omnes Vercingetorigem probant imperatorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suffrago","latin":"suffrago, suffragare, suffragavi, suffragatus","headword":"suffrago","letter":"s","pos":"verb","posGroup":"verb","english":"express public support (for), canvass/vote for; lend support (to), favor","forms":["suffrāgantis"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quoniam per annōs cōnsulī fierī nōn licēbat, cum magnō certāmine {{suffrāgantis}} plēbis et repugnantibus eī aliquamdiū patribus, lēgibus solūtus et cōnsul creātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"suffundo","latin":"suffundo, suffundere, suffudi, suffusus","headword":"suffundo","letter":"s","pos":"verb","posGroup":"verb","english":"pour in/on; cause to well up to surface; cover/fill with liquid that wells up","forms":["suffūsum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Empedoclēs animum esse cēnset cordī {{suffūsum}} sanguinem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"suillus","latin":"suillus, suilla, suillum","headword":"suillus","letter":"s","pos":"adjective","posGroup":"adjective","english":"of pigs/swine","forms":["suillam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Īnsignis fuit Eleazarī senis cōnstantia: is apertō ōre compellēbātur camem {{suillam}} comedere, quā Hidaeis lēx interdīcēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sulco","latin":"sulco, sulcare, sulcavi, sulcatus","headword":"sulco","letter":"s","pos":"verb","posGroup":"verb","english":"furrow, plow; cleave","forms":["sulcō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"pars optāre locum tēctō et conclūdere sulcō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sulcus","latin":"sulcus, sulci","headword":"sulcus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"furrow; rut; trail of a meteor, track, wake; female external genitalia (rude)","forms":["sulcī","sulcus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{sulcus}} -ī m — līneā per agrum araàta","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"sulla","latin":"Sulla, Sullae","headword":"Sulla","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sulla (Roman cognomen); [L. Cornelius ~ Felix => Roman dictator 138-78 BC]","forms":["Sulla","Sullae","Sullam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cēterum dum ea rēs geritur, {{Sulla}} quaestor cum magnō exercitū in castra vēnit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sulphur","latin":"sulphur, sulphuris","headword":"sulphur","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"brimstone, sulfur; lightning/thunder (associated with brimstone)","forms":["sulphur","sulphure"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hinc procul Aesōnidem et hinc procul sacerdōtēs īre iussit et oculōs profānōs removēre; Medea tum capillīs fluentibus in modum bacchantum ārās geminās circumit terque senem flammā, ter aquā, ter {{sulphure}} spargit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sulpicius","latin":"Sulpicius, Sulpicii","headword":"Sulpicius","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sulpicius","forms":["Sulpiciō","Sulpicium","Sulpicius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Sulpicium}} Cabilloni et Matiscone in Aeduis ad Ararim rei frumentariae causa collocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sum","latin":"sum, esse","headword":"sum","letter":"s","pos":"verb","posGroup":"verb","english":"be; I am","forms":["entis","eram","erāmus","erant","erās","erat","erātis","erimus","erit","eritis","erunt","es","esse","essem","essēmus","essent","essēs","esset","essētis","est","este","estis","Ēsto","ēstote","fore","forem","forent","forēs","foret","fuerant","fuerat","fuēre","fuerim","fuerint","fuerīs","fuerit","fuerō","fuērunt","fuī","fuimus","fuisse","fuissem","fuissent","fuisset","fuistī","fuistis","fuit","sim","sint","sīs","sit","sum","sumus","sunt","suntō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"In primis rationem {{esse}} habendam dicunt, prius quam eorum clandestina consilia efferantur, ut Caesar ab exercitu intercludatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sumit","latin":"sūmit","headword":"sūmit","letter":"s","pos":"verb","posGroup":"verb","english":"take; takes (up); takes, picks up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"summa","latin":"summa, -ae","headword":"summa","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"total, sum, main part","forms":["summa","summae","summam","summis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Simili ratione ibi Vercingetorix, Celtilli filius, Arvernus, {{summae}} potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"summas","latin":"summas, (gen.), summatis","headword":"summas","letter":"s","pos":"adjective","posGroup":"adjective","english":"high-born; eminent (Collins)","forms":["summās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, linguam amputarī, cutem capitis detrahī, {{summās}} mantīs ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"summe","latin":"summe","headword":"summe","letter":"s","pos":"adverb","posGroup":"adverb","english":"in the highest degree; intensely; superlatively well, consummately","forms":["summē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Gaudēbō, sī mēcum venīre voluerīs.” Cui Ganymēdēs “Eāmus,” respondit, “sī hoc tibi, summē Iuppiter, placet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"summitto","latin":"summitto, summittere, summisi, summissus","headword":"summitto","letter":"s","pos":"verb","posGroup":"verb","english":"allow to grow long; emit, put forth, raise; lower, moderate, relieve; submit","forms":["summittebant","summittere","summittit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Caesar ex castris equitatum educi iubet, proelium equestre committit; laborantibus iam suis Germanos equites circiter CCCC {{summittit}}, quos ab initio habere secum instituerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"summoveo","latin":"summoveo, summovere, summovi, summotus","headword":"summoveo","letter":"s","pos":"verb","posGroup":"verb","english":"remove; drive off, dislodge; expel; ward off; keep at a distance; bar/debar","forms":["summotis","summovit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte {{summotis}} hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"summum","latin":"summum, summi","headword":"summum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"top; summit, end, last; highest place; top surface; (voice) highest, loudest","forms":["summum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Conclamat omnis multitudo et suo more armis concrepat, quod facere in eo consuerunt cuius orationem approbant: {{summum}} esse Vercingetorigem ducem, nec de eius fide dubitandum, nec maiore ratione bellum administrari posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"summus","latin":"summus, -a, -um","headword":"summus","letter":"s","pos":"adjective","posGroup":"adjective","english":"highest; highest, topmost; top of, highest","forms":["summī","summo","summōs","summus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita viis patefactis {{summo}} militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sumo","latin":"sūmō, -ere, sūmpsī, sūmptum","headword":"sūmō","letter":"s","pos":"verb","posGroup":"verb","english":"to take, take up","forms":["sūmantur","sūmat","sūmātis","sūme","sūmēbant","sūmēbat","sūmendae","sūmendī","sūmendum","sūmēns","sūmentēs","sūmere","sūmerent","sūmeret","sūmis","sumit","sūmite","sūmitō","sūmō","sūmpserat","sūmpserīs","sūmpserō","sūmpsērunt","sūmpsī","sūmpsisse","sūmpsit","sūmpta","sūmptam","sūmptīs","sūmptō","sūmptū","sūmptum","sūmundum","sūmunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eorum adventu, quod minus idoneis equis utebantur, a tribunis militum reliquisque equitibus Romanis atque evocatis equos {{sumit}} Germanisque distribuit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sumptus","latin":"sūmptus, -ūs","headword":"sūmptus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"expenditure, expense Heteroclitic","forms":["sūmptibus","sūmptuī","sūmptūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"IOās, quamdiū cōnsiliīs Ioiadae ūsus est, observantissimus fuit divinī culfils: magnīs {{sūmptibus}} templum exomāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"sunt","latin":"sunt","headword":"sunt","letter":"s","pos":"verb","posGroup":"verb","english":"they are; are","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"suo","latin":"suo, suere, sui, sutus","headword":"suo","letter":"s","pos":"verb","posGroup":"verb","english":"sew together/up, stitch","forms":["suēre","suisse","suit","suo","sūtum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo {{suo}}, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suovetaurile","latin":"suovetaurile, suovetaurilis","headword":"suovetaurile","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"purificatory sacrifice (pl.) consisting of a boar, a ram, and a bull","forms":["suovetaurīlibus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ibi īnstrūctum exercitum omnem {{suovetaurīlibus}} lūstrāvit; ita cēnsuī fīnis factus est idque \"lustrum condere\" appellātum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"suovetaurilia","latin":"suovetaurīlia, -ium (n. pl.)","headword":"suovetaurīlia","letter":"s","pos":"","posGroup":"other","english":"a sacrifice consisting of a swine, a sheep, and a bull","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"supellex","latin":"supellex, supellectilis","headword":"supellex","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"furniture, house furnishings; paraphernalia, articles necessary for business","forms":["supellectilem","supellex"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Fāma dē adventū frātrum Iōsēphī ad aurēs rēgis pervēnit; quī dēdit eīs mūnera perferenda ad patrem cum hīs mandātīs: addūcite hūc patrem vestrum et omnem eius familiam, nec multum cūrātē {{supellectilem}} vestram, quia omnia quae opus erunt vōbīs praebitūrus sum, et omnēs opēs Aegyptī vestrae erunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"super","latin":"super","headword":"super","letter":"s","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) on (top of), above; (prp. + abl.)over (also adv.); over, about (+ acc./abl.)","forms":["super"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Antequam Mārcus rūrsus surgere potest, Sextus, quī puer gravior est, {{super}} pectus eius cōnsīdit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"super-eminere","latin":"(superēmineō) super-ēminēre","headword":"super-ēminēre","letter":"s","pos":"","posGroup":"other","english":"stand out above","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"superare","latin":"(superō) superāre","headword":"superāre","letter":"s","pos":"verb","posGroup":"verb","english":"cross, surpass, overcome, defeat, remain; to surpass, rise above, conquer","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"superbe","latin":"superbe, superbius, superbissime","headword":"superbe","letter":"s","pos":"adverb","posGroup":"adverb","english":"arrogantly, proudly, haughtily; superciliously","forms":["superbē","superbius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ōlim fēmina Rōmāna, nōmine Tullia, Cornēliam vīsit, cupida ōrnāmenta sua ostendendī; quae, superbē mōnstrāns gemmās, quās in digitīs et in collō gerēbat, “Multās” inquit “novās et pulchrās gemmās habeō, quae mē valdē dēlectant: spectā!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"superbia","latin":"superbia, -ae","headword":"superbia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"arrogance, pride; pride, arrogance; pride","forms":["superbia","superbiae","superbiam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Superbiam}} fuge, neque eam in animum aut in sermōnem sinās obrēpere.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"superbio","latin":"superbio, superbire, superbivi, superbitus","headword":"superbio","letter":"s","pos":"verb","posGroup":"verb","english":"show/have (too much) pride/disdain (to); be proud/gorgeous/superb/magnificent","forms":["superbiēns","superbit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Erat tūne aulicus quīdam apud rēgem grātiōsus, nōmine Amān, quī, favōre rēgiō {{superbiēns}}, adorarī sē volēbat, quod facere renuēns Mardochaeus, grave in sē odium Amānīs accenderat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"superbus","latin":"superbus, -a, -um","headword":"superbus","letter":"s","pos":"adjective","posGroup":"adjective","english":"lofty, arrogant; proud, arrogant; proud, haughty","forms":["superba","superbae","superbam","superbās","superbī","superbīs","superbō","superbōs","superbum","superbus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fēminās vērō, quās {{superbās}} esse putābat, nūllās amābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"supercilium","latin":"supercilium, supercili(i)","headword":"supercilium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"eyebrow; frown; arrogance","forms":["superciliī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Arte superciliī cōnfīnia nūda replētis","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"superemineo","latin":"superemineo, supereminere, -, -","headword":"superemineo","letter":"s","pos":"verb","posGroup":"verb","english":"overtop, stand out above the level of","forms":["superēminet"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Anchīsēs apud īnferōs: 'Aspice ut insignis spoliīs Marcellus opimīs ingreditur victorque virōs {{superēminet}} omnēs!' — Vergilius, Aenēis VI.855–856.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"superfluo","latin":"superfluo, superfluere, superfluxi, superfluxus","headword":"superfluo","letter":"s","pos":"verb","posGroup":"verb","english":"overflow, flow over brim/sides/surface; be superfluous/superabundant/surplus","forms":["superfluentēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Is dedit operam — sī modo id cōnsequī potuit — ut nimis redundantēs nōs et {{superfluentēs}} iuvenīlī quādam dīcendī impūnitāte et licentiā reprimeret et quasi extrā rīpās diffluentēs coercēret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"superfundere","latin":"(superfundō) superfundere (< fundere)","headword":"superfundere","letter":"s","pos":"","posGroup":"other","english":"pour over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"superfundo","latin":"superfundo, superfundere, superfudi, superfusus","headword":"superfundo","letter":"s","pos":"verb","posGroup":"verb","english":"pour over, cover (surface); spill over, pour over brim; pour in (invaders)","forms":["Superfūdit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Superfūdit}} deinde sē in Asiam et tredecim annīs quibus Alexander rēgnāvit prīmum omnia qua Persārum prope immēnsō spatiō imperium fuerat suae diciōnis fēcit; Arabās hinc Indiamque, quā terrārum ultimōs fīnēs Rubrum mare amplectitur, peragrāvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"superior","latin":"superior, superius","headword":"superior","letter":"s","pos":"","posGroup":"other","english":"higher","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"superlativus","latin":"superlātīvus, -ī (gradus)","headword":"superlātīvus","letter":"s","pos":"adjective","posGroup":"adjective","english":"superlative","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"superne","latin":"superne","headword":"superne","letter":"s","pos":"adverb","posGroup":"adverb","english":"at or to a higher level, above; in the upper part; on top","forms":["superne"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Appropinquante arca, aquae, quae {{superne}} dēfluēbant, stetērunt īnstar mūrī; quae autem īnfrā, dēscendērunt, et alveum siccum relīquērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"supero","latin":"superō (1)","headword":"superō","letter":"s","pos":"verb","posGroup":"verb","english":"overcome, conquer","forms":["supera","superābantur","superābat","Superābātur","superant","superante","superāre","superārentur","superāret","superāri","superārīs","superās","superat","superātī","superātīs","superātō","superātur","superātus","superāverit","superaverunt","superāvistī","superāvit","superes","superō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis imbribus tardarentur, tamen continenti labore omnia haec {{superaverunt}} et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"superstes","latin":"superstes, (gen.), superstitis","headword":"superstes","letter":"s","pos":"adjective","posGroup":"adjective","english":"outliving, surviving; standing over/near; present, witnessing","forms":["superstes","superstitem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Haec omnia mala in mē recīdunt; nōn dīmittam Beniamīnum; nam sī quid eī adversī acciderit in viā, nōn poterō eī {{superstes}} vīvere; sed dolōre oppressūs moriar.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"superstitio","latin":"superstitio, superstitionis","headword":"superstitio","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"superstition; irrational religious awe","forms":["superstitiō","superstitiōnem","superstitiōnibus","superstitiōnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Statim ut rēgnō pofitus est, populum et sacerdōtēs cohortātus, urbem ā p atēmīs {{superstitiōnibus}} expiāvit, templum omāvit, caerimōniās, quae iam prldem omissae erant, restituit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"supersum","latin":"supersum, superesse","headword":"supersum","letter":"s","pos":"verb","posGroup":"verb","english":"be over and above, remain, survive; be left, remain","forms":["supererant","supererat","superesse","superessent","superesset","superest","superfuerant","superfuērunt","superfuimus","superfuit","supersunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Duodecim frātrēs sumus; minimus retentus est domī ā patre; alius vērō nōn {{superest}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"superum","latin":"superum, superi","headword":"superum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"heaven (pl.); heavenly bodies; heavenly things; higher places","forms":["superum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Italia inter duo maria interest, quōrum alterum, quod suprā Italiam situm est, 'mare {{Superum}}' sīve 'Hadriaticum' appellātur, alterum, īnfrā Italiam situm, 'mare Īnferum' sīve 'Tuscum'.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"superus","latin":"superus, -a, -um","headword":"superus","letter":"s","pos":"adjective","posGroup":"adjective","english":"upper; highest, upper","forms":["superī","superior","superiōra","superiore","superiorem","superiores","superioribus","superiōris","superiorum","superīs","superōs","suprēma","suprēme","suprēmī","suprēmus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et {{superioribus}} victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supervacaneus","latin":"supervacaneus, supervacanea, supervacaneum","headword":"supervacaneus","letter":"s","pos":"adjective","posGroup":"adjective","english":"redundant; unnecessary","forms":["supervacāneum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dē timōre {{supervacāneum}} est disserere, cum praesertim dīligentiā clārissimī virī cōnsulis tanta praesidia sint in armīs.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"supervacuus","latin":"supervacuus, supervacua, supervacuum","headword":"supervacuus","letter":"s","pos":"adjective","posGroup":"adjective","english":"superfluous, redundant, more than needed; unnecessary, pointless, purposeless","forms":["supervacuārum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Iūlius Proculus auc- tiônemfaciet rêrum {{supervacuārum}}.” [T rimalchiô astrologus dē\" duodecim signīs] Interpellāvit tam dulcēs fābulās Trimalchiô; nam iam sublātum erat ferculum, hilarësque convîvae vînô ser- mônibusque püblicätîs operam coeperant dare.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"supervenio","latin":"supervenio, supervenire, superveni, superventus","headword":"supervenio","letter":"s","pos":"verb","posGroup":"verb","english":"come up, arrive","forms":["superveniente","supervēntum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed ā Camillō, quī in vīcīnā cīvitāte exsulābat, Gallīs {{supervēntum}} est gravissimēque victī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"supervenire","latin":"(supervenio) supervenīre (< venīre)","headword":"supervenīre","letter":"s","pos":"","posGroup":"other","english":"appear, surpass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"supinum","latin":"supīnum, -ī","headword":"supīnum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"supine (grammar)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"supinus","latin":"supinus, supina, supinum","headword":"supinus","letter":"s","pos":"adjective","posGroup":"adjective","english":"lying face upwards, flat on one's back; turned palm upwards; flat; passive","forms":["supīnīs","supīnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille, sanguinem cum vīnō mixtum ex ōre effiindēns, cecidit {{supīnus}} in terram neque iam movērl potuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"suppeditare","latin":"(suppeditō) suppeditāre","headword":"suppeditāre","letter":"s","pos":"verb","posGroup":"verb","english":"supply; to supply, furnish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"suppedito","latin":"suppedito, suppeditare, suppeditavi, suppeditatus","headword":"suppedito","letter":"s","pos":"verb","posGroup":"verb","english":"be/make available when/as required, supply with/needs (of)","forms":["suppeditāns","suppeditāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iōsēphus autem patrem et frātrēs suōs collocāvit in optimā parte Aegyptī, eīsque omnium rērum abundantiam {{suppeditāvit}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suppetia","latin":"suppetia, suppetiae","headword":"suppetia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"help (pl.), aid","forms":["suppetiae"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"nōn metuō quīn meae uxōrī lātae {{suppetiae}} sient.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"suppeto","latin":"suppeto, suppetere, suppetivi, suppetitus","headword":"suppeto","letter":"s","pos":"verb","posGroup":"verb","english":"be at hand; be equal to; be sufficient for","forms":["suppetant","suppetēbat","suppetere","suppeterent","suppetunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Harum ipsis rerum copiam {{suppetere}}, quod quorum in finibus bellum geratur, eorum opibus subleventur; Romanos aut inopiam non laturos aut magno periculo longius ab castris processuros; neque interesse ipsosne interficiant impedimentisne exuant, quibus amissis bellum geri non possit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supplementum","latin":"supplēmentum, -ī","headword":"supplēmentum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"reinforcement, supplement","forms":["supplementi","supplemento","supplementum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam {{supplementi}} equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suppleo","latin":"suppleo, supplere, supplevi, suppletus","headword":"suppleo","letter":"s","pos":"verb","posGroup":"verb","english":"supply","forms":["supplēvit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Equitum decem turmās ex Albānīs lēgit, et legiōnēs veterēs {{supplēvit}} et novās cōnscrīpsit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"supplere","latin":"(suppleō) supplēre, -ēvisse, -ētum","headword":"supplēre","letter":"s","pos":"","posGroup":"other","english":"fill up, reinforce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"supplex","latin":"supplex (gen. supplicis)","headword":"supplex","letter":"s","pos":"adjective; noun (m.)","posGroup":"adjective","english":"suppliant; suppliant, pleading","forms":["supplex","supplicem","supplicēs","supplici","supplicibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Summae diligentiae summam imperi severitatem addit; magnitudine {{supplici}} dubitantes cogit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supplicatio","latin":"supplicātiō, -ōnis ( f.)","headword":"supplicātiō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"thanksgiving; public thanksgiving","forms":["supplicatio","supplicātiōnēs","supplicātiōnibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"His litteris cognitis Romae dierum viginti {{supplicatio}} redditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suppliciter","latin":"suppliciter","headword":"suppliciter","letter":"s","pos":"adverb","posGroup":"adverb","english":"suppliantly, in an attitude of humble entreaty","forms":["suppliciter"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi calamitāte ēdoctus scelerum veniam {{suppliciter}} ā Deō pefīvit et impetrāvit: in rēgnum restirūtus, Deum piē coluit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"supplicium","latin":"supplicium, -ī","headword":"supplicium","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"punishment; punishment, execution","forms":["supplicia","suppliciī","suppliciis","supplicio","supplicium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His {{suppliciis}} celeriter coacto exercitu, Lucterium Cadurcum, summae hominem audaciae, cum parte copiarum in Rutenos mittit; ipse in Bituriges proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supplico","latin":"supplico, supplicare, supplicavi, supplicatus","headword":"supplico","letter":"s","pos":"verb","posGroup":"verb","english":"pray, supplicate; humbly beseech","forms":["supplicāmus","supplicandō","supplicārent","supplicet"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Kalendīs, īdibus, nōnīs, fēstus diēs cum erit, corōnam in focum indat, per eōsdemque diēs Larī familiārī prō cōpiā {{supplicet}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"suppono","latin":"suppono, supponere, supposui, suppositus","headword":"suppono","letter":"s","pos":"verb","posGroup":"verb","english":"place under; substitute; suppose","forms":["suppositā","supposuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Iter faciēns pervenit ad quemdam locum, ubi fessus dē viā pernoctāvit; {{supposuit}} lapidem capitī suō et obdormīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"supporto","latin":"supporto, supportare, supportavi, -","headword":"supporto","letter":"s","pos":"verb","posGroup":"verb","english":"carry up, transport","forms":["supportando","supportāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque cohortatus Aeduos de {{supportando}} commeatu, praemittit ad Boios qui de suo adventu doceant hortenturque ut in fide maneant atque hostium impetum magno animo sustineant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supra","latin":"suprā","headword":"suprā","letter":"s","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) above; above, over","forms":["supra"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut {{supra}} diximus, angustum habebat, aggerem apparare, vineas agere, turres duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"supremum","latin":"supremum, supremi","headword":"supremum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"funeral rites (pl.) or offerings","forms":["suprēmum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dāvīd, cum fīliō dedisset praecepta rēgnō administrandō ūtilissima, diem {{suprēmum}} obiit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"supremus","latin":"suprēmus, -a, -um","headword":"suprēmus","letter":"s","pos":"","posGroup":"other","english":"highest, sovereign","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sura","latin":"sura, surae","headword":"sura","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"calf of the leg","forms":["sūra"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{sūra}} -ae f — pars crūris posterior","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"surdus","latin":"surdus, -a, -um","headword":"surdus","letter":"s","pos":"adjective","posGroup":"adjective","english":"deaf","forms":["surdās","surdī","surdus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Lȳdia: \"Quī medicus verbīs sōlīs potest facere ut hominēs caecī videant, surdī audiant, mūtī loquantur, claudī ambulent?\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"surena","latin":"surena, surenae","headword":"surena","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"grand vizier/chief minister (of Parthians); kind of fish","forms":["Surēnā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Pompēī Magnī in cōnsulātū secundō, contrā Parthōs missus est, et cum circā Carrhās contrā ōmen et auspicia dīmicāsset, ā Surēnā, Orōdis rēgis duce, victus ad postrēmum interfectus est cum fīliō, clārissimō et praestantissimō iuvene.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"surgere","latin":"surgere, -ō, surrēxī, surrēctum","headword":"surgere","letter":"s","pos":"verb","posGroup":"verb","english":"to get up, rise; to rise, get up","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"surgit","latin":"surgit, surgere","headword":"surgit","letter":"s","pos":"verb","posGroup":"verb","english":"rise, get up; rises, gets up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"surgo","latin":"surgō, -ere, surrexī, surrēctum","headword":"surgō","letter":"s","pos":"verb","posGroup":"verb","english":"to rise, get up","forms":["Surgam","surgat","surge","surgēbant","surgēbat","surgendum","surgēns","surgent","surgentem","surgentī","surgentia","surgere","surgerent","surgeret","surgit","surgō","surgunt","surrēxerat","surrēxērunt","surrēxī","surrēxisse","surrēxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aemilia “{{Surge}}, Iūlī!” inquit, “Neque enim necesse est margarītās in hortō quaerere: in cubiculō nostrō sunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"suria","latin":"Suria, Suriae","headword":"Suria","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Syria; (area between Asia Minor and Egypt including Phoenicia and Palestine)","forms":["Suria"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}],"examples":[{"latin":"Iūlia: “{{Suria}} est in Asiā.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"surrepo","latin":"surrepo, surrepere, surrepsi, surreptus","headword":"surrepo","letter":"s","pos":"verb","posGroup":"verb","english":"creep (under/up to); move stealthily; ooze/seep (liquid); insinuate self","forms":["surreptus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Syrācūsās dē sē rē rediit nūntius ad avum puerōrum ‘puerum surrēptum alterum patremque puerī esse Tarentī ēmortuum’, immūtat nōmen avus huic geminō alterī — ita eum dīlēxit quī {{surreptus}} est alterum — illīus nōmen indit illī quī domī est ‘Menaechmō’, idem quod alterī nōmen fuit (et ipse eōdem avus est vocātus nōmine).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"surrepticius","latin":"surrepticius, surrepticia, surrepticium","headword":"surrepticius","letter":"s","pos":"adjective","posGroup":"adjective","english":"surreptitious","forms":["surreptīcium","surreptīcius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Adoptat illum puerum {{surreptīcium}} sibi fīlium, eīque uxōrem dōtātam dedit, eumque hērēdem fēcit cum ipse obiit diem.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"surreptum","latin":"surreptum","headword":"surreptum","letter":"s","pos":"adverb","posGroup":"adverb","english":"stealthily","forms":["surrēptum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Postquam Syrācūsās dē sē rē rediit nūntius ad avum puerōrum ‘puerum {{surrēptum}} alterum patremque puerī esse Tarentī ēmortuum’, immūtat nōmen avus huic geminō alterī — ita eum dīlēxit quī surreptus est alterum — illīus nōmen indit illī quī domī est ‘Menaechmō’, idem quod alterī nōmen fuit (et ipse eōdem avus est vocātus nōmine).","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"surripere","latin":"(surripiō) surripere, surripuisse, surreptum","headword":"surripere","letter":"s","pos":"verb","posGroup":"verb","english":"steal; to steal, snatch; to steal","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"surripio","latin":"surripio, surripere, surripui, surreptus","headword":"surripio","letter":"s","pos":"verb","posGroup":"verb","english":"take away secretly; steal, filch","forms":["surriperet","surriperētur","surripuī","surripuisse","surripuit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ūnus ex hīs puerulīs post diem tertium nocte mortuus est: māter {{surripuit}} puerum alterīus mulieris dormientis, et huius locō fīlium suum mortuum supposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"surripit","latin":"surripit","headword":"surripit","letter":"s","pos":"verb","posGroup":"verb","english":"steals","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"sursum","latin":"sūrsum","headword":"sūrsum","letter":"s","pos":"adverb","posGroup":"adverb","english":"up; upwards","forms":["sūrsum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ariēs vērō aureus {{sūrsum}} suprā humum sē levāvit et ex eō locō, ubi sita erat puerōrum casa, ēvolāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"surus","latin":"Surus, Sura, Surum","headword":"Surus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Syrian, of Syria","forms":["sūrās"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"purpureōque altē {{sūrās}} vincīre cothurnō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"sus","latin":"sūs, -suis (m./f.)","headword":"sūs","letter":"s","pos":"noun","posGroup":"noun","english":"pig; pig, sow, boar","forms":["suem","suēs","sūs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iildās cum octingenfīs tantum hominibus impetum hostium sustinuit, immō oppositam sibi acieī partem fildit, sed multitūdine hostium circumventus illōrum tells confōs {{sūs}} est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suscipere","latin":"(suscipiō) suscipere (< capere)","headword":"suscipere","letter":"s","pos":"","posGroup":"other","english":"take up, receive, adopt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"suscipio","latin":"suscipiō, -ere, -cēpī, -ceptum","headword":"suscipiō","letter":"s","pos":"verb","posGroup":"verb","english":"undertake, take up, offer","forms":["suscēperant","suscēpērunt","suscēpimus","suscepisse","suscēpisset","suscēpit","suscepta","susceptī","suscepto","susceptum","susceptus","suscipere","suscipī","suscipiant","suscipiendō","suscipiendum","suscipitur","suscipiunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio deductis, cum se vel principes eius consili fore profiterentur, ratio perficiendi quaerebatur, quod civitatem temere ad {{suscipiendum}} bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suscitare","latin":"(suscitō) suscitāre, suscitāvisse, suscitātum","headword":"suscitāre","letter":"s","pos":"verb","posGroup":"verb","english":"wake up, rouse; to raise, wake","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"suscito","latin":"suscito, suscitare, suscitavi, suscitatus","headword":"suscito","letter":"s","pos":"verb","posGroup":"verb","english":"encourage, stir up; awaken, rouse, kindle","forms":["suscitāre","suscitāret","suscitās","suscitāvērunt","suscitāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et accessērunt ad eum discipulī eius, et {{suscitāvērunt}} eum dīcentēs:\"Domine, salviī nōs: perīmus ī\"Et dīcit eīs Jēsus:\"Quid timidī estis?\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suspecto","latin":"suspecto, suspectare, suspectavi, suspectatus","headword":"suspecto","letter":"s","pos":"verb","posGroup":"verb","english":"suspect; mistrust, be suspicious of; suspect the presence of evil; gaze up at","forms":["suspectō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed et turris ingēns imminebat, et mūrus, ut in suspectō locō, ēmūnītus erat, et iuventūs dēlēcta ubi plūrimum perīculī ac timōris ostendēbātur ibi vī maiōre obsistēbat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"suspectus","latin":"suspectus, -a, -um","headword":"suspectus","letter":"s","pos":"adjective","posGroup":"adjective","english":"suspected, suspect","forms":["suspecta","suspectōs","suspectus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ut plūribus metum iniceret, iūdicia per sē sōlus exercēbat, perque eam causam occīdere aut exsiliō agere poterat nōn {{suspectōs}} modo aut invīsōs, sed etiam eōs unde nihil aliud quam praedam spērāre posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"suspendere","latin":"(suspendō) suspendere, -disse, -sum","headword":"suspendere","letter":"s","pos":"","posGroup":"other","english":"hang, suspend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"suspendo","latin":"suspendo, suspendere, suspendi, suspensus","headword":"suspendo","letter":"s","pos":"verb","posGroup":"verb","english":"hang up, suspend","forms":["suspende","suspenderat","suspendī","suspendit","suspenditō","suspēnsum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Restituit praefectō pincernārum mūnus suum; alterum vērō sēcūrī percussum {{suspendit}} ad pālum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suspensus","latin":"suspensus, suspensa, suspensum","headword":"suspensus","letter":"s","pos":"adjective","posGroup":"adjective","english":"in a state of anxious uncertainty or suspense, light","forms":["suspēnsam","suspēnsus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Absalōn fugiēns mūlō īnsidēbat; erat autem prōmissō et dēnsō capillō: dum praecipitī cursū fertur subter dēnsam quercum, coma eius implicitā est rāmīs, et ipse {{suspēnsus}} adhaesit, mūlō interim praetereunte et cursum pergente.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"suspicari","latin":"(suspicor) suspicārī","headword":"suspicārī","letter":"s","pos":"","posGroup":"other","english":"guess, suspect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"suspicere","latin":"(suspiciō) suspicere, suspexisse, suspectum","headword":"suspicere","letter":"s","pos":"","posGroup":"other","english":"look up (at)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"suspicio","latin":"suspīciō, -ōnis ( f.)","headword":"suspīciō","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"suspicion","forms":["suspectum","suspexit","suspici","suspiciēns","suspicio","suspīciōne","suspicionem","suspīciōnēs","suspīciōnis","suspicit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Augetur Gallis {{suspicio}} atque omnes illo ad munitionem copiae traducuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suspicor","latin":"suspicor, suspicari, suspicatus sum","headword":"suspicor","letter":"s","pos":"verb","posGroup":"verb","english":"mistrust, suspect; suppose","forms":["suspicābātur","suspicandum","suspicantem","suspicantēs","suspicātī","suspicātus","suspicor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ego, {{suspicātus}} ad aliquam ur- bānitātem totiēns iterâtam vôcem pertinēre, nôn ërubuî eum quî suprā mē accumbēbat hoc ipsum interrogāre.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"suspiro","latin":"suspīrō, -āre, -āvī, -ātum","headword":"suspīrō","letter":"s","pos":"verb","posGroup":"verb","english":"breathe","forms":["suspīrāns","suspīrat","suspīret"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dum miser Pān {{suspīrat}} trāns papyrōs, papyrī sonum querellae dant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"sustentare","latin":"(sustentō) sustentāre","headword":"sustentāre","letter":"s","pos":"","posGroup":"other","english":"sustain, maintain, endure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"sustentatus","latin":"sustentatus, sustentatus","headword":"sustentatus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"support, sustaining, bearing/carrying; keeping erect/upright; hangings/drapes","forms":["sustentātus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quō in locō cum esset silvestris bēluae {{sustentātus}} ūberibus pastōrēsque eum sustulissent et in agrēstī cultū labōreque aluissent, perhibētur, ut adolēverit, et corporis vīribus et animī ferōcitāte tantum cēterīs praestitisse ut omnēs quī tum eōs agrōs ubi hodiē est haec urbs incolēbant aequō animō illī libenterque pārērent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sustento","latin":"sustento, sustentare, sustentavi, sustentatus","headword":"sustento","letter":"s","pos":"verb","posGroup":"verb","english":"endure, hold out","forms":["sustentābat","sustentarent"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem {{sustentarent}}, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sustineo","latin":"sustineō","headword":"sustineō","letter":"s","pos":"verb","posGroup":"verb","english":"to withstand, hold out","forms":["sustine","sustineāmus","sustineant","sustinebant","sustinēbat","sustinēbātur","sustinēbit","sustinēbitur","sustinēbō","sustinenda","sustinēns","sustinentī","sustinere","sustinerent","sustinēret","sustineri","sustinet","sustinētur","sustinuērunt","sustinuisse","sustinuisset","sustinuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Eius adventu Bituriges ad Aeduos, quorum erant in fide, legatos mittunt subsidium rogatum, quo facilius hostium copias {{sustinere}} possint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sustinet","latin":"sustinet, sustinēre","headword":"sustinet","letter":"s","pos":"","posGroup":"other","english":"support, sustain, endure","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"sutrinus","latin":"sutrinus, sutrina, sutrinum","headword":"sutrinus","letter":"s","pos":"adjective","posGroup":"adjective","english":"of a shoemaker","forms":["Sutrīnōrum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam Camillus eō annō Volscōrum cīvitātem, quae per septuāgintā annōs bellum gesserat, vīcit, et Aequōrum urbem et {{Sutrīnōrum}}, atque omnēs — dēlētīs eārundem exercitibus — occupāvit, et trēs simul triumphōs ēgit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"suum","latin":"suum, sui","headword":"suum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"his property (pl.); [se suaque => themselves and their possessions]","forms":["suum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum {{suum}} hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"suus","latin":"suus, -a, -um","headword":"suus","letter":"s","pos":"adjective","posGroup":"adjective","english":"his, her, their (own); his, her, its (own); his own, her own, its own, their own; its own, his own, her own","forms":["sua","suae","suam","suarum","suas","sūe","sui","suis","suorum","suos","suus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et {{sui}} capitis periculo Galliam in libertatem vindicent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"sychaeus","latin":"Sychaeus, Sychaei","headword":"Sychaeus","letter":"s","pos":"noun (m.)","posGroup":"noun","english":"Sychaeus; (first husband of Dido, murdered by Pygmalion)","forms":["Sychaeī","Sychaeum","Sychaeus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Huic coniūnx erat {{Sychaeus}}, dīvitissimus Phoenīcum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"sycophanta","latin":"sycophanta, sycophantae","headword":"sycophanta","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"informer, trickster","forms":["sȳcophanta"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Illīc homō aut {{sȳcophanta}} aut geminus est frāter tuus.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"syllaba","latin":"syllaba, -ae","headword":"syllaba","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"syllable","forms":["syllaba","syllabae","syllabam","syllabārum","syllabās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nēmō mē legere docuit; sed saepe Diodōrum puerōs docentem audiō, ita litterās et {{syllabās}} discō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"symphonia","latin":"symphonia, symphoniae","headword":"symphonia","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"harmony of sounds; singers/musicians; symphony (L+S); instrument; war signal","forms":["symphōniam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et cum venīret et appropinquāret domuī, audīvit {{symphōniam}} et chorum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"synonymum","latin":"synōnymum, -ī","headword":"synōnymum","letter":"s","pos":"noun (n.)","posGroup":"noun","english":"synonym","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"syracuses","latin":"Syracuses, Syracusae","headword":"Syracuses","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Syracuse (pl.); (chief city of Sicily)","forms":["Syrācūsās","Syrācūsīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Diāna igitur terram aperuit; Arethūsae aquae, mersae in humum apertam, sub terrā Ortygiam, ad Īnsulam prope {{Syrācūsās}} sitam, vectae sunt, ubi dea ad lūcem et sōlem eās iterum ēdūxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"syria","latin":"Syria, Syriae","headword":"Syria","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Syria; (area between Asia Minor and Egypt including Phoenicia and Palestine)","forms":["Syria","Syriae","Syriam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Mārcus: “Ubi est {{Syria}}, Iūlia?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"syriacus","latin":"Syriacus, Syriaca, Syriacum","headword":"Syriacus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Syrian, of/connected with Syria, produced/found in Syria","forms":["Syriaca"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Fuērunt et tō- mäculā ferventia suprā crätîculam argenteam posita, et înfrä crätîcu- lam {{Syriaca}} prūna cum gränîs [Trimalchiô accumbit mīrābiliter exôrnätus] 32 In hîs erāmus lautitiîs, cum ipse Trimalchiô ad sym- phôniam allātus est, positus- que inter cervîcälia minūtīs- sīma expressit imprūdentibus rîsum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"syringa","latin":"Syringa, -ae","headword":"Syringa","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"Syrinx (a nymph)","forms":["Syringa","Syringam"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nōmen nymphae erat {{Syringa}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"syrtis","latin":"syrtis, syrtis","headword":"syrtis","letter":"s","pos":"noun (f.)","posGroup":"noun","english":"sandbank, quicksand; (esp. one on the coast of North Africa)","forms":["Syrtēs","syrtīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sīve per {{Syrtēs}} iter aestuōsās / sīve factūrus per inhospitālem / Caucasum vel quae loca fābulōsus / lambit Hydaspēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"syrus","latin":"Syrus, Syra, Syrum","headword":"Syrus","letter":"s","pos":"adjective","posGroup":"adjective","english":"Syrian, of Syria","forms":["Syra","Syrae","Syram","Syre","Syrī","Syrō","Syrum","Syrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Syra}} Dēliam audit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tabella","latin":"tabella, -ae","headword":"tabella","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"writing tablet; writing-tablet","forms":["tabella","tabellae","tabellam","tabellās","tabellīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eum putō meam {{tabellam}} sūmpsisse.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tabellarius","latin":"tabellārius, -ī","headword":"tabellārius","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"letter carrier; postman, letter-carrier; letter-carrier, courier; courier, letter-carrier","forms":["tabellāriī","tabellāriō","tabellāriōs","tabellārium","tabellārius"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Tabellārius}} vērō canem vīnctum nōn timet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tabeo","latin":"tabeo, tabere, -, -","headword":"tabeo","letter":"t","pos":"verb","posGroup":"verb","english":"rot away, decay; waste away","forms":["tābentīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"et sale {{tābentīs}} artūs in lītore pōnunt.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"taberna","latin":"taberna, -ae","headword":"taberna","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"shop, stall; shop, tavern","forms":["tabernā","tabernae","tabernam","tabernās","tabernīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ipse ad {{tabernam}} ībō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tabernaculum","latin":"tabernāculum, -ī","headword":"tabernāculum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"tent","forms":["tabernāculī","tabernaculo","tabernāculum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in {{tabernaculo}} oppressus, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tabernarius","latin":"tabernārius, -ī","headword":"tabernārius","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"shopkeeper","forms":["tabernāriī","tabernāriō","tabernārius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quī tabernam habet {{tabernārius}} est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"tabes","latin":"tabes, tabis","headword":"tabes","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"wasting away; decay; putrefaction; fluid resulting from corruption or decay","forms":["tābēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Namque, duōbus senāti dēcrētīs, ex tantā multitūdine neque praemiō inductus coniūrātiōnem patefēcerat neque ex castrīs Catilīnae quisquam omnium discesserat: tanta vīs morbī ac velutī {{tābēs}} plērōsque cīvium animōs invāserat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"tabescere","latin":"(tābēscō) tābēscere, -uisse","headword":"tābēscere","letter":"t","pos":"","posGroup":"other","english":"waste away, decay","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tabesco","latin":"tabesco, tabescere, tabui, -","headword":"tabesco","letter":"t","pos":"verb","posGroup":"verb","english":"melt, dissolve; dry up, evaporate; waste away, dwindle away; (mental aspect)","forms":["tabēscere"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Subvenīte mihi miserō, īte obviam iniūriae, nōlīte patī rēgnum Numidiae, quod vestrum est, per scelus et sanguinem familiae nostrae {{tabēscere}}!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tabula","latin":"tabula, -ae","headword":"tabula","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"writing tablet; writing-tablet; story, tale; picture; picture, painted panel; board, plank, table","forms":["tabulā","tabulae","tabulam","tabulārum","tabulās","tabulīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Mārcus: “At ego gaudeō quod mihi necesse nōn est {{tabulam}} et librōs portāre.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tabularium","latin":"tabularium, tabulari(i)","headword":"tabularium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"collection of (inscribed) tablets; record-office, registry","forms":["Tabulārium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In īnfimō Capitōliō est {{Tabulārium}}, id est amplum aedificium in quō tabulae et litterae pūblicae servantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tabum","latin":"tabum, tabi","headword":"tabum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"viscous fluid consisting of putrid matter","forms":["tābō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ille quidem tōtam gemebundus obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī trepident sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"taceo","latin":"taceo, tacere, tacui, tacitus","headword":"taceo","letter":"t","pos":"verb","posGroup":"verb","english":"be silent; pass over in silence; leave unmentioned, be silent about something","forms":["tacē","taceant","taceās","taceat","tacēbō","tacenda","tacendī","tacendum","tacēns","tacent","tacente","taceō","tacēre","tacērent","tacēret","tacērī","tacēs","tacet","Tacēte","tacuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Dāvus, quī probus est servus, {{tacet}} neque Mēdum accūsat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tacere","latin":"tacēre","headword":"tacēre","letter":"t","pos":"verb","posGroup":"verb","english":"to be silent","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"tacet","latin":"tacet","headword":"tacet","letter":"t","pos":"verb","posGroup":"verb","english":"be silent; is silent, is quiet; is silent","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"taciturnitas","latin":"taciturnitas, taciturnitatis","headword":"taciturnitas","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"maintaining silence","forms":["taciturnitās","taciturnitātis"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī hoc post hominum memoriam contigit nēminī, vōcis exspectās contumēliam, cum sīs gravissimō iūdiciō {{taciturnitātis}} oppressus?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"taciturnus","latin":"taciturnus, taciturna, taciturnum","headword":"taciturnus","letter":"t","pos":"adjective","posGroup":"adjective","english":"silent, quiet","forms":["taciturna","taciturnus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"is qul sermōne placet quī sermōne placet, {{taciturna}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tacitus","latin":"tacitus, -a, -um","headword":"tacitus","letter":"t","pos":"adjective","posGroup":"adjective","english":"silent; silent, quiet","forms":["tacita","tacitē","tacitī","tacitīs","tacitō","tacitōrum","tacitōs","tacitum","tacitus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus {{tacitus}} pullōs aspicit, tum rīdēre incipit: “Hahaha!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tactum","latin":"-tactum","headword":"tactum","letter":"t","pos":"","posGroup":"other","english":"to, happen","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"taeda","latin":"taeda, taedae","headword":"taeda","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"pine torch","forms":["taeda","taedās","taedīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"sed tū sī sapiēs, sī tē bene iungere anumque hanc audīre volēs (quae tē plūs omnibus illīs, plūs, quam crēdis, amō): vulgārēs reice {{taedās}}","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"taedeo","latin":"taedeo, taedere, taedui, taesus","headword":"taedeo","letter":"t","pos":"verb","posGroup":"verb","english":"be tired/weary/sick (of) (w/GEN or INF+ACC of person); be disgusted/offended","forms":["taedeat","taedēre","taedēret"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"taedium -ī7 « {{taedēre}}; tolle taedium","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"taedere","latin":"(taedet) taedēre, -duisse, -sum","headword":"taedēre","letter":"t","pos":"","posGroup":"other","english":"be tired/sick of","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"taedet","latin":"taedet, taedere, taeduit, taesus est","headword":"taedet","letter":"t","pos":"verb","posGroup":"verb","english":"be tired/weary/sick (of) (w/GEN or INF+ACC of person); be disgusted/offended","forms":["taedet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{taedet}}; taedium nūllum fuge (: vīta)!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"taedium","latin":"taedium, -ī","headword":"taedium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"weariness, tedium","forms":["taedia","taedium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nōn tulit, impatiēns longī tormenta dolōris, Īphis et ante forēs haec verba novissima dīxit: “Vincis, Anaxaretē, neque erunt tibi {{taedia}} tandem ūlla ferenda meī...","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"taeter","latin":"taeter, -tra, -trum","headword":"taeter","letter":"t","pos":"adjective","posGroup":"adjective","english":"foul, horrible","forms":["taetra","taetram"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Magna dīs immortālibus habenda est atque huic ipsī Iovī Statōrī, antīquissimō cūstōdī huius urbis, grātia, quod hanc tam {{taetram}}, tam horribilem tamque īnfēstam reī pūblicae pestem totiēns iam effūgimus.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"talare","latin":"talare, talaris","headword":"talare","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"winged sandals (pl.) of Mercury; skirts/robes reaching to ankles","forms":["tālāria"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"imperiō; et prīmum pedibus {{tālāria}} nectit","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"talea","latin":"talea, taleae","headword":"talea","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"block; bar","forms":["taleae"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ante haec {{taleae}} pedem longae ferreis hamis infixis totae in terram infodiebantur mediocribusque intermissis spatiis omnibus locis disserebantur; quos stimulos nominabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"talentum","latin":"talentum, -ī","headword":"talentum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"a talent (sum of money); talent (a sum of money)","forms":["talenta"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Gābelō cuidam egentī decem {{talenta}}, quibus ā rēge dōnātus erat, perhūmāniter commodāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"talis","latin":"tālis, tāle","headword":"tālis","letter":"t","pos":"adjective","posGroup":"adjective","english":"of such a sort; of such a kind; such (a)","forms":["tāle","tālem","tālēs","tali","tālia","tālibus","tālis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magna adfectus sollicitudine hoc nuntio Caesar, quod semper Aeduorum civitati praecipue indulserat, nulla interposita dubitatione legiones expeditas quattuor equitatumque omnem ex castris educit; nec fuit spatium {{tali}} tempore ad contrahenda castra, quod res posita in celeritate videbatur; C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"talus","latin":"talus, tali","headword":"talus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"ankle; ankle/pastern bone; sheep knucklebone (marked for dice); dice game (pl.)","forms":["tālōrum","tālōs","tālus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{tālus}} -17 — tessera ex osse ovis facta","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tam","latin":"tam","headword":"tam","letter":"t","pos":"adverb","posGroup":"adverb","english":"so, as; so","forms":["tam"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Via quae est inter Tūsculum et vīllam Iūliī nōn {{tam}} longa est quam via Latīna, sed servī quattuor quī Tūsculō ad vīllam ambulant fessī sunt, quia lectīcam et saccōs portant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tamdiu","latin":"tamdiū","headword":"tamdiū","letter":"t","pos":"adverb","posGroup":"adverb","english":"so long, as long; so long","forms":["tamdiū"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"“Quārē tamdiū morātur fīlius?” inquiēbat maerēns “forsitan Gābelus mortuus est, et nēmō est quī illī reddat istam pecūniam: illum abesse ā nōbīs vehementer doleō.” Coepēruntque ipse et uxor eius flēre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tamen","latin":"tamen","headword":"tamen","letter":"t","pos":"adverb","posGroup":"adverb","english":"(adv. + conj.) nevertheless","forms":["tamen"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc temptandam fortunam non existimabant; expellitur ex oppido Gergovia; non destitit {{tamen}}, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tametsi","latin":"tametsī","headword":"tametsī","letter":"t","pos":"conjunction","posGroup":"conjunction","english":"although, notwithstanding","forms":["tametsi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quae {{tametsi}} Caesar intellegebat, tamen quam mitissime potest legatos appellat: nihil se propter inscientiam levitatemque vulgi gravius de civitate iudicare neque de sua in Aeduos benevolentia deminuere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tamquam","latin":"tamquam","headword":"tamquam","letter":"t","pos":"conjunction","posGroup":"conjunction","english":"as, like, as though; as, just like","forms":["tamquam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cui Isaacus mīrāns dīxit: quis est ergō ille quī modo attulit mihi cibum, et cui apprecātus sum omnia fausta, {{tamquam}} prīmōgenitō?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tandem","latin":"tandem","headword":"tandem","letter":"t","pos":"adverb","posGroup":"adverb","english":"finally; at last, finally","forms":["tandem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Tandem}} Germani ab dextro latere summum iugum nacti hostes loco depellunt; fugientes usque ad flumen, ubi Vercingetorix cum pedestribus copiis consederat, persequuntur compluresque interficiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tangere","latin":"tangere","headword":"tangere","letter":"t","pos":"verb","posGroup":"verb","english":"to touch","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tangit","latin":"tangit, tangere","headword":"tangit","letter":"t","pos":"verb","posGroup":"verb","english":"touch; touches","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tango","latin":"tangō, -ere, tetigī, tactum","headword":"tangō","letter":"t","pos":"verb","posGroup":"verb","english":"touch","forms":["tācta","tāctae","tāctī","tāctō","tāctum","tangam","tangās","tangat","tange","tangēbam","tangēbant","tangēbat","tangenda","tangendō","tangere","tangeris","tangī","tangit","tangunt","tetigerat","tetigēre","tetigerīmus","tetigerit","tetigerō","tetigērunt","tetigimus","tetigisse","tetigissent","tetigit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlius id quod in herbā iacet manū {{tangit}} atque “Fui!” inquit horrēns, “Est parva bēstia nūda.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tantopere","latin":"tantopere","headword":"tantopere","letter":"t","pos":"adverb","posGroup":"adverb","english":"so much, so hard","forms":["tantopere"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ōderant illum {{tantopere}}, ut nōn possent cum eō amīcē loquī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tantulus","latin":"tantulus, tantula, tantulum","headword":"tantulus","letter":"t","pos":"adjective","posGroup":"adjective","english":"so very small, so trifling","forms":["tantulo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent {{tantulo}} spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot virorum fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tantum","latin":"tantum","headword":"tantum","letter":"t","pos":"adverb","posGroup":"adverb","english":"so much, only; only, so much, also indecl. noun; only","forms":["tantum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine vestro sanguine {{tantum}} exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tantummodo","latin":"tantummodo","headword":"tantummodo","letter":"t","pos":"adverb","posGroup":"adverb","english":"only, merely","forms":["tantummodo"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Īrātus rēx eōs vesfītōs et catēnīs vīnctōs coniēcit in fomaeem ārdentem, sed flamma nihil illīs nocuit: nec corpus adussit ignis, nec vestēs quidem mūtāvit, at solvit {{tantummodo}} vincula, quibus eonstringēbantur, ita ut illaesī in mediā fomace ambulārent.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tantundem","latin":"tantundem","headword":"tantundem","letter":"t","pos":"adverb","posGroup":"adverb","english":"just as much","forms":["tantundem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Fossam pedum XX derectis lateribus duxit, ut eius fossae solum {{tantundem}} pateret quantum summae fossae labra distarent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tantus","latin":"tantus, -a, -um","headword":"tantus","letter":"t","pos":"adjective","posGroup":"adjective","english":"so big, so great; so great, so big; such a great, so great","forms":["tanta","tantae","tantam","tantārum","tantas","tantī","tantis","tanto","tantōs","tantus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in {{tantis}} dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tapes","latin":"tapes, tapetis","headword":"tapes","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"woolen cloth or rug used as a covering, hanging, carpet, tapestry","forms":["tapētibus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Tūre datō flammīs vīnōque in tūra profūsō,\n. . . rēgia tēcta petunt, positīsque {{tapētibus}} altīs\nmūnera cum liquidō capiunt Cereālia Bacchō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tardare","latin":"(tardō) tardāre","headword":"tardāre","letter":"t","pos":"","posGroup":"other","english":"make slow, delay","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tardo","latin":"tardo, tardare, tardavi, tardatus","headword":"tardo","letter":"t","pos":"verb","posGroup":"verb","english":"check, retard; hinder","forms":["tardabat","tardarent","tardarentur","tardaret","tardavit","tardō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"His tot rebus impedita oppugnatione milites, cum toto tempore frigore et assiduis imbribus {{tardarentur}}, tamen continenti labore omnia haec superaverunt et diebus XXV aggerem latum pedes CCCXXX, altum pedes LXXX exstruxerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tardus","latin":"tardus, -a, -um","headword":"tardus","letter":"t","pos":"adjective","posGroup":"adjective","english":"late, tardy; slow, late; late, slow","forms":["tarda","tardē","tardior","tardīs","tardissimē","tardius","tardum","tardus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Intereā Tobiās pater erat animō anxiō et sollicitō, quod suus fīlius in redeundō {{tardior}} esset.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tarquinius","latin":"Tarquinius, Tarquini","headword":"Tarquinius","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Etruscan name; (T~ Priscus, 5th Roman king; T~ Superbus, last king 534-510 BC)","forms":["Tarquinī","Tarquiniī","Tarquiniō","Tarquinium","Tarquinius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ultimus autem rēx, nōmine {{Tarquinius}}, quī nōn Rōmānus sed Tuscus erat, glōriōsus, sevērissimus et tam nēquam fuit ut ‘Superbus’ appellārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tartarum","latin":"Tartarum, Tartari","headword":"Tartarum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"infernal regions (pl.), the underworld","forms":["Tartara","Tartarum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Proserpinam et Plūtōnem tenentem rēgnum umbrārum adiit et sīc ait: \"Ō dī positī sub terrā, nōn hūc dēscendī quod {{Tartarum}} vidēre dēsīderābam nec canem Cerberum, mōnstrum ingēns, vincere.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"taurinus","latin":"taurinus, taurina, taurinum","headword":"taurinus","letter":"t","pos":"adjective","posGroup":"adjective","english":"of or derived from a bull; made of ox-hide","forms":["taurīnō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"taurīnō quantum possent circumdare tergō.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"taurus","latin":"taurus, -ī","headword":"taurus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"bull","forms":["taurī","taurīs","taurō","taurōrum","taurōs","taurum","taurus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quae, dum cum aliīs puellīs in campō lūdit, currit, pilam iacit flōrēsque carpendō dēlectātur, subitō magnum et album {{taurum}} vīdit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"te","latin":"tē","headword":"tē","letter":"t","pos":"pronoun","posGroup":"pronoun","english":"you","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"tectum","latin":"tēctum, -ī","headword":"tēctum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"roof","forms":["tēcta","tēctī","tēctīs","tecto","tēctōrum","tēctum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Conclamant equites, sanctissimo iure iurando confirmari oportere, ne {{tecto}} recipiatur, ne ad liberos, ne ad parentes, ne ad uxorem aditum habeat qui non bis per agmen hostium perequitasset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tectus","latin":"tectus, tecta -um, tectior -or -us, tectissimus -a -um","headword":"tectus","letter":"t","pos":"adjective","posGroup":"adjective","english":"covered, roofed; hidden, secret; concealed/disguised; guarded/secretive","forms":["tēctus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Proserpina, quae maesta Plūtōnī vidēbātur, nunc laeta est, ut sōl quī nūbibus obscūrīs ante {{tēctus}} fuit, nunc ē nūbibus exit et terrae lūcem dat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tecum","latin":"tēcum","headword":"tēcum","letter":"t","pos":"","posGroup":"other","english":"with you","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"tegere","latin":"(tegō) tegere, tetigisse, tactum","headword":"tegere","letter":"t","pos":"","posGroup":"other","english":"cover, conceal","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tegimen","latin":"tegimen, tegiminis","headword":"tegimen","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"covering/cover/protection; clothing; body armor; skin/shell/husk (animal/fruit)","forms":["tegimen"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"cui {{tegimen}} septem terga fuēre boum!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tegmen","latin":"tegmen, tegminis","headword":"tegmen","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"covering/cover/protection; clothing; body armor; skin/shell/husk (animal/fruit)","forms":["tegmine","tegminis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"(Mīrābātur Achillēs enim.) “Nec haec cassis quam vidēs neque scūtum, onus sinistrae, auxiliō mihi sunt; decor est quaesītus ab istīs; Mars quoque ob hoc capere arma solet! [Sī] removēbitur huius {{tegminis}} officium, tamen indestrictus abībō; est aliquid nōn esse nātum Nērēide, sed quī Nēreaque et nātās et tōtum temperat aequor.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tego","latin":"tegō, -ere, tēxī, tēctum","headword":"tegō","letter":"t","pos":"verb","posGroup":"verb","english":"cover, conceal, hide; cover, hide","forms":["tēctam","tegant","tegantur","tegat","tegēbant","tegēbat","tegendum","tegente","tegentī","tegentibus","tegere","tegerent","tegeret","teget","tegimur","tegis","tegit","tegitur","teguntur","tēxerint","texerunt","tēxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sic cum suis fugientibus permixti, quos non silvae montesque {{texerunt}}, ab equitatu sunt interfecti.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tela","latin":"tēla, -ae","headword":"tēla","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"loom","forms":["tela","tēlās"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Reliquas omnes munitiones ab ea fossa passus quadringentos reduxit, id hoc consilio, quoniam tantum esset necessario spatium complexus nec facile totum opus corona militum cingeretur, ne de improviso aut noctu ad munitiones hostium multitudo advolaret aut interdiu {{tela}} in nostros operi destinatos coicere possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"telis","latin":"telis, telis","headword":"telis","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"fenugreek (herb)","forms":["telis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi septima legio constiterat, hostes pelluntur atque in fugam coiciuntur; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium transfixi {{telis}} concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tellus","latin":"tellūs, -ūris ( f.)","headword":"tellūs","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"earth; earth, land; land, earth","forms":["tellūre","tellūris","tellūs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"At nisi opem tulero, taurī ignem ex ōre spīrābunt in eum, aut concurrēt hostibus armātīs {{tellūre}} creātīs, aut avidō dracōnī dabitur.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"telo","latin":"telo, telonis","headword":"telo","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"customs officer; (Erasmus)","forms":["tēlō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Trāditus Philistaeīs rūpit vincula, quibus constrīctus erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"telum","latin":"tēlum, -ī","headword":"tēlum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"spear, weapon; weapon, dart, missile; weapon, spear","forms":["telorum","tēlum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multitudine sagittarum atque omnis generis {{telorum}} multos vulneratos; ad haec sustinenda magno usui fuisse tormenta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"temerarius","latin":"temerārius, -a, -um","headword":"temerārius","letter":"t","pos":"adjective","posGroup":"adjective","english":"reckless; reckless, rash; rash, reckless","forms":["temerāria","temerāriam","Temerāriī","temerāriō","temerāriōs","temerārius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Temerāriī mihi hī omnēs iuvenēs videntur esse, sī vēra sunt, quae dē Atalantae celeritāte nārrantur!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"temere","latin":"temere","headword":"temere","letter":"t","pos":"adverb","posGroup":"adverb","english":"heedlessly; rashly, at random","forms":["temere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio deductis, cum se vel principes eius consili fore profiterentur, ratio perficiendi quaerebatur, quod civitatem {{temere}} ad suscipiendum bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"temeritas","latin":"temeritās, -ātis ( f.)","headword":"temeritās","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"recklessness; rashness","forms":["temeritas","temeritate","temeritatem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Impellit alios avaritia, alios iracundia et {{temeritas}} quae maxime illi hominum generi est innata, ut levem auditionem habeant pro re comperta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"temno","latin":"temno, temnere, -, -","headword":"temno","letter":"t","pos":"verb","posGroup":"verb","english":"scorn, despise","forms":["temnis","temnitis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sī genus hūmānum et mortālia {{temnitis}} arma","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"temo","latin":"temo, temonis","headword":"temo","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"pole, beam; tongue of a wagon or chariot","forms":["tēmō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Axis erat aureus, aureus erat tēmō, aureae rotae, at argenteī radiī: quae metalla ūna cum gemmīs, quibus tōtus currus ōrnābātur, Sōlis lūmen repercussum in omnēs caelī partēs spargēbant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"temperans","latin":"temperans, (gen.), temperantis","headword":"temperans","letter":"t","pos":"adjective","posGroup":"adjective","english":"restrained, self-controlled","forms":["temperāns"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Frendēns gemēnsque ac vix lacrimīs {{temperāns}} dīcitur lēgātōrum verba audīsse.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"temperantia","latin":"temperantia, -ae","headword":"temperantia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"self-control, moderation","forms":["temperantia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ac prīmum quanta innocentia dēbent esse imperātōrēs! quanta deinde in omnibus rēbus {{temperantia}}! quanta fide, quanta facilitāte, quanto ingeniō, quanta hūmānitāte!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"temperare","latin":"(temperō) temperāre","headword":"temperāre","letter":"t","pos":"","posGroup":"other","english":"moderate, temper, refrain","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"temperatio","latin":"temperātiō, -ōnis ( f.)","headword":"temperātiō","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"fit proportion, organizing principle; blending, moderation","forms":["temperātiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Deinde subter mediam ferē regiōnem Sōl obtinet, dux et prīnceps et moderātor lūminum reliquōrum, mēns mundī et temperātiō, tantā magnitūdine ut cūncta suā lūce lūstret et compleat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"temperatus","latin":"temperatus, temperata -um, temperatior -or -us, temperatissimus -a -um","headword":"temperatus","letter":"t","pos":"adjective","posGroup":"adjective","english":"temperate, mild","forms":["temperātius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sed cum cēnserem remissiōne et moderātiōne vōcis et commūtātō genere dīcendī mē et perīculum vītāre posse et {{temperātius}} dīcere, ut cōnsuētūdinem dīcendī mūtārem, ea causa mihi in Asiam proficīscendī fuit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"temperi","latin":"temperi, temperius, temperissime","headword":"temperi","letter":"t","pos":"adverb","posGroup":"adverb","english":"at right/better/best time, seasonably","forms":["temperī","Temperius"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Vīnō bonō domesticō ūtimur.” [Gāius:] “Sīc fīat.” [Iūlius:] “{{Temperius}} ergō venī ad nōs.” [Gāius:] “Quandō vīs, mitte ad nōs.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"tempero","latin":"temperō, -āre, temperāvī","headword":"temperō","letter":"t","pos":"verb","posGroup":"verb","english":"rule, control; temper","forms":["Temperā","temperat","temperāta","temperātum","temperet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"(Mīrābātur Achillēs enim.) “Nec haec cassis quam vidēs neque scūtum, onus sinistrae, auxiliō mihi sunt; decor est quaesītus ab istīs; Mars quoque ob hoc capere arma solet! [Sī] removēbitur huius tegminis officium, tamen indestrictus abībō; est aliquid nōn esse nātum Nērēide, sed quī Nēreaque et nātās et tōtum {{temperat}} aequor.”","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tempestas","latin":"tempestās, tempestātis","headword":"tempestās","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"(f.) storm; storm, tempest","forms":["tempestas","tempestāte","tempestātem","tempestātēs","tempestātibus","tempestātum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eo cum esset ventum, exploratores hostium, ut omni fluminis parte erant dispositi, inopinantes, quod magna subito erat coorta {{tempestas}}, ab nostris opprimuntur; exercitus equitatusque equitibus Romanis administrantibus quos ei negotio praefecerat celeriter transmittitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tempestivus","latin":"tempestīvus, -a, -um","headword":"tempestīvus","letter":"t","pos":"adjective","posGroup":"adjective","english":"timely, suitable; timely, ripe, mature","forms":["tempestīvō","tempestīvus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iamque deōs omnēs ipsamque Aenēia virtūs\nIūnōnem veterēs fīnīre coēgerat īrās,\ncum, bene fundātīs opibus crēscentis Iūlī,\n{{tempestīvus}} erat caelō Cythēreius hērōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"templum","latin":"templum, -ī","headword":"templum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"temple","forms":["templa","templī","templīs","templō","templum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In forō est {{templum}} antīquum.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"temptare","latin":"(temptō) temptāre","headword":"temptāre","letter":"t","pos":"","posGroup":"other","english":"try (to influence), attack","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"temptatio","latin":"temptatio, temptationis","headword":"temptatio","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"trial, temptation","forms":["temptātiōnem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et cum pervēnisset eō, dīxit illīs:\"Ōrātē nē intrētis in {{temptātiōnem}}.\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tempto","latin":"temptō, -āre","headword":"temptō","letter":"t","pos":"verb","posGroup":"verb","english":"try, attempt","forms":["temptābant","temptābimus","temptābunt","temptanda","temptandam","temptandās","temptant","temptantēs","temptantur","temptare","Temptās","temptat","temptāta","temptātis","temptātur","temptātūrum","temptāverat","temptāvērunt","temptāvī","temptāvit","Temptēmus","temptent","temptēs","temptet","temptō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prohibetur ab Gobannitione, patruo suo, reliquisque principibus, qui hanc {{temptandam}} fortunam non existimabant; expellitur ex oppido Gergovia; non destitit tamen, atque in agris habet dilectum egentium ac perditorum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tempus","latin":"tempus, temporis","headword":"tempus","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"(n.) time; time, tense; time, times","forms":["tempora","tempore","temporibus","temporis","temporum","tempus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum, collaudatis Carnutibus, dato iure iurando ab omnibus qui aderant, {{tempore}} eius rei constituto ab concilio disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tenax","latin":"tenax, tenacis (gen.), tenacior -or -us, tenacissimus -a -um","headword":"tenax","letter":"t","pos":"adjective","posGroup":"adjective","english":"holding fast, clinging; tenacious; retentive; close-fisted/tight/niggardly","forms":["tenāx"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"tam fictī prāvīque {{tenāx}} quam nūntia vērī.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"tendere","latin":"(tendō) tendere, tetendisse,","headword":"tendere","letter":"t","pos":"verb","posGroup":"verb","english":"stretch, spread, lay, make one’s; to stretch out, extend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"tendo","latin":"tendō, -ere, tetendī, tentum","headword":"tendō","letter":"t","pos":"verb","posGroup":"verb","english":"stretch out, extend","forms":["tendat","tende","tendebant","tendēbat","tendēns","tendente","tendentem","tendere","tenderent","tenderet","tendimus","tendis","tendit","tendunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"His cognitis et Litavicci fraude perspecta Aedui manus {{tendere}} et deditionem significare et proiectis armis mortem deprecari incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tenebra","latin":"tenebra, tenebrae","headword":"tenebra","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"darkness (pl.), obscurity; night; dark corner; ignorance; concealment; gloom","forms":["tenebrae","tenebrās","tenebris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Prospectu {{tenebris}} adempto multa utrimque vulnera accipiuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tenebrae","latin":"tenebrae, -ārum","headword":"tenebrae","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"(f.pl.) darkness; darkness, shadows","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"tenebricosus","latin":"tenebricōsus, -a, -um","headword":"tenebricōsus","letter":"t","pos":"adjective","posGroup":"adjective","english":"dark","forms":["tenebricosum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Qui nunc it per iter {{tenebricosum}}","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"tenebrosus","latin":"tenebrosus, tenebrosa, tenebrosum","headword":"tenebrosus","letter":"t","pos":"adjective","posGroup":"adjective","english":"dark, gloomy","forms":["tenebrōsō","tenebrōsum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Deinde tellūs tremit et ipse rēx, Plūtō, terret nē, terrā fissā, lūx in rēgnum {{tenebrōsum}} perveniat et trepidantēs umbrās terreat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"teneo","latin":"teneō, -ēre, -uī, tentum","headword":"teneō","letter":"t","pos":"verb","posGroup":"verb","english":"hold, keep, possess, have","forms":["tenē","teneam","teneant","teneantur","teneās","teneat","teneātis","teneātur","tenebant","tenebantur","tenebat","tenebatur","tenēbō","tenenda","tenēns","tenent","tenente","tenentem","tenentīs","tenentur","teneō","tenēre","tenerent","tenērentur","tenērer","tenēret","tenērētur","teneri","tenēris","tenēs","tenet","tenēte","tenētis","tenētur","tentīs","tentum","tenuēre","tenuerit","tenuērunt","tenuī","tenuimus","tenuisse","tenuisset","tenuistis","tenuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Erat e regione oppidi collis sub ipsis radicibus montis egregie munitus atque ex omni parte circumcisus; quem si {{tenerent}} nostri, et aquae magna parte et pabulatione libera prohibituri hostes videbantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tener","latin":"tener, -era, -erum","headword":"tener","letter":"t","pos":"adjective","posGroup":"adjective","english":"tender, delicate","forms":["tener","tenerā","tenerae","tenerās","tenerō","tenerōs","tenerum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"multī illum iuvenēs, multae cupiēre puellae; sed fuit in tenerā tam dūra superbiā fōrma, nūllī illum iuvenēs, nūllae tetigēre puellae.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tenet","latin":"tenet, tenent","headword":"tenet","letter":"t","pos":"verb","posGroup":"verb","english":"hold, keep (back); holds; holds, keeps","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tento","latin":"tento, tentare, tentavi, tentatus","headword":"tento","letter":"t","pos":"verb","posGroup":"verb","english":"handle, feel; attempt, try; prove; test; attack; brave; make an attempt","forms":["tentāns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Postquam Isaacus adolēvit, deus {{tentāns}} fidem Abrahamī, dīxit illī: Abrahame, tolle fīlium tuum ūnicum quem amās, et immolā eum mihi in monte quem ostendam tibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tentorium","latin":"tentorium, tentori(i)","headword":"tentorium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"tent","forms":["tentōria","tentōriō","tentōrium"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"rum explōrātum ībat noctū (vigil) {{tentōrium}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tentum/tensum","latin":"tentum/tēnsum","headword":"tentum/tēnsum","letter":"t","pos":"","posGroup":"other","english":"way, insist","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tenuis","latin":"tenuis, -e","headword":"tenuis","letter":"t","pos":"adjective","posGroup":"adjective","english":"thin; thin, slender","forms":["tenue","tenuem","tenuēs","tenuia","tenuis","tenuissimā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tremēbat iam tōtō corpore, pallēbat vultūs, odiō erat affectum miserum cor, neque iam {{tenuis}} spēs animum tenēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tenuitas","latin":"tenuitas, tenuitatis","headword":"tenuitas","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"thinness/fineness/leanness; poverty; frugality; simpleness (style); subtlety","forms":["tenuitate","tenuitātem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu {{tenuitate}} Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tenuo","latin":"tenuo, tenuare, tenuavi, tenuatus","headword":"tenuo","letter":"t","pos":"verb","posGroup":"verb","english":"make thin; reduce, lessen; wear down","forms":["tenuābit","tenuāre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"tēnūàrē — at-{{tenuāre}}, levem facere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tenus","latin":"tenus","headword":"tenus","letter":"t","pos":"preposition","posGroup":"preposition","english":"as far as, to the extent of, up to, down to","forms":["tenus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"hāc-{{tenus}} adv — adhūc Hāctenus, unde lēgās quod","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tepeo","latin":"tepeo, tepere, tepui, -","headword":"tepeo","letter":"t","pos":"verb","posGroup":"verb","english":"be warm/tepid/lukewarm; have body warmth; feel love warmth/glow; fall flat","forms":["tepentī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"185 Quot nova terra parit flōrēs, cum vēre tepentī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tepidus","latin":"tepidus, tepida, tepidum","headword":"tepidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"warm, tepid","forms":["tepidō","tepidum","tepidus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{tepidus}} -ā -um — placidē calidus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ter","latin":"ter","headword":"ter","letter":"t","pos":"adverb","posGroup":"adverb","english":"three times; three times, thrice; thrice, three times","forms":["ter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Alcyonē autem, cum prīmum hoc nōvit, acerbō dolōre affectā, lacrimās per genās effūdit tōtōque vultū palluit et, postquam {{ter}} frūstrā prae tristitiāā cōnāta est loquī, tum dēmum “Heu, mē miseram!” inquit, “Nōn iam mē amās, ō Cēyx?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ter quinque","latin":"ter quīnque","headword":"ter quīnque","letter":"t","pos":"phrase","posGroup":"other","english":"fifteen (3 x 5)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"terebinthina","latin":"terebinthina, terebinthinae","headword":"terebinthina","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"turpentine","forms":["terebinthinā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Permittitis tamen ﬁnîrî lūsum?” Sequēbātur puer cum tabulā terebinthinā et crystallinîs tesserîs, notävîque rem om- nium dēlicātissimam: prô calculîs enim albîs ac nigrîs aureôs argenteôsque habēbat tesserae Interim, �Ē$ gustantibus adhūc nôbîs, repositôrium al- lātum est cum corbe in quô gallîna erat lignea patentibus in orbem älîs, quālēs esse solent quae _ incubant ôva.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"terere","latin":"(terō) terere, trīvisse, trītum","headword":"terere","letter":"t","pos":"","posGroup":"other","english":"wear out, use up, spend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"teres","latin":"teres, (gen.), teretis","headword":"teres","letter":"t","pos":"adjective","posGroup":"adjective","english":"smooth; tapering","forms":["teres","teretes","teretī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Huc {{teretes}} stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"terg","latin":"terg, tergoris","headword":"terg","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"back (animal, meat); ridge, raised surface; far side; covering (animal/organ)","forms":["terg","tergora"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quae nisi fēcissem, frūstrā Tēlamone creātus gestāsset laevā taurōrum {{tergora}} septem.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tergeo","latin":"tergeo, tergere, tersi, tersus","headword":"tergeo","letter":"t","pos":"verb","posGroup":"verb","english":"rub, wipe; wipe off, wipe dry; clean, cleanse","forms":["Tergē","tergendō","tergēns","tergere","terget","tersī","tersit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Tergē oculōs, Iūlia!","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"terget","latin":"terget, tergent","headword":"terget","letter":"t","pos":"verb","posGroup":"verb","english":"wipe; wipes, dries","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tergo","latin":"tergo, tergere, tersi, tersus","headword":"tergo","letter":"t","pos":"verb","posGroup":"verb","english":"rub, wipe; wipe off, wipe dry; clean, cleanse (sometimes tergeo)","forms":["tergo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Restituto proelio ac repulsis hostibus eo quo Labienum miserat contendit; cohortes IIII ex proximo castello deducit, equitum partem se sequi, partem circumire exteriores munitiones et ab {{tergo}} hostes adoriri iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tergum","latin":"tergum, -ī","headword":"tergum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"back; terga dare — to flee; back, hide","forms":["terga","tergī","tergum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"At incerto etiam nunc exitu victoriae, cum Septimae legionis tribunis esset nuntiatum quae in sinistro cornu gererentur, post {{tergum}} hostium legionem ostenderunt signaque intulerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"terminare","latin":"termināre","headword":"termināre","letter":"t","pos":"verb","posGroup":"verb","english":"to end, finish","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"termino","latin":"termino, terminare, terminavi, terminatus","headword":"termino","letter":"t","pos":"verb","posGroup":"verb","english":"mark the boundaries of, form the boundaries of; restrict; conclude","forms":["terminātum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ubi carmen Pānis {{terminātum}} est, sacer Tmōlus ōs vertit ad ōs Phoebī, quī gerēbat laurum in capite vestīmentumque longum tīnctum Tyriō murice.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"terminus","latin":"terminus, -ī","headword":"terminus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"boundary(-stone)","forms":["terminōs","terminum","terminus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Collātīnīs hīs verbīs dēditī sunt, eaque dēditiōnis fōrmula est: Rēx interrogāvit: \"Estisne vōs lēgātī ōrātōrēsque ut missī ā populō Collātīnō, vōs populumque Collātīnum dēderētis?\" \"Sumus.\" \"Estne populus Collātīnus in suā potestāte?\" \"Est.\" \"Dēditisne vōs populumque Collātīnum, urbem, agrōs, aquam, {{terminōs}}, dēlūbra, dīvīna hūmānaque omnia in meam populumque Rōmānum diciōnem?\" \"Dedimus.\" \"At ego recipiō.\"","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"terni","latin":"ternī, -ae, -a","headword":"ternī","letter":"t","pos":"adjective","posGroup":"adjective","english":"three at a time; three each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"tero","latin":"tero, terere, trivi, tritus","headword":"tero","letter":"t","pos":"verb","posGroup":"verb","english":"rub, wear away, wear out; tread","forms":["terēbant","terenda","terentēs","terere","terī","teris","teruntur"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"fréna {{teruntur}} dente equī magnanimī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"terra","latin":"terra, -ae","headword":"terra","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"earth, ground, country; earth, land; land, country, earth","forms":["terra","terrae","terram","terrarum","terras","terrīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae ab reliquis Gallis civitates dissentirent, has sua diligentia adiuncturum atque unum consilium totius Galliae effecturum, cuius consensui ne orbis quidem {{terrarum}} possit obsistere; idque se prope iam effectum habere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"terreo","latin":"terreō, -ēre, -uī, -itum","headword":"terreō","letter":"t","pos":"verb","posGroup":"verb","english":"terrify, frighten","forms":["terreat","terrēbant","terrēbantur","terrēbat","terrēbātur","terrēbit","terrendos","terrent","terrēre","terrērent","terreret","terrērī","terret","terrētur","territā","territae","territum","territus","terruērunt","terruit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sextium legatum, quem minoribus castris praesidio reliquerat, misit, ut cohortes ex castris celeriter educeret et sub infimo colle ab dextro latere hostium constitueret, ut, si nostros loco depulsos vidisset, quo minus libere hostes insequerentur {{terreret}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"terrere","latin":"(terreō) terrēre, terruisse, territum","headword":"terrēre","letter":"t","pos":"verb","posGroup":"verb","english":"frighten; to frighten","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"terrestris","latin":"terrestris, -e","headword":"terrestris","letter":"t","pos":"adjective","posGroup":"adjective","english":"earthly, terrestrial","forms":["terrestrēs","terrēstribus","terrestris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deus posuit Adamum et Ēvam in hortō amoenissimō, quī solet appellārī Paradīsus {{terrestris}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"terribilis","latin":"terribilis, -e","headword":"terribilis","letter":"t","pos":"adjective","posGroup":"adjective","english":"terrible","forms":["terribile","terribilem","terribilēs","terribilī","terribilis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Perrēxit autem īre, velut leō quī dēscendit dē montibus; nūdus et sordidus tamque {{terribilis}} vīsū erat, ut puellae omnēs, cum prīmum eum cōnspexērunt, hūc et illūc fugerent animō turbātae.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"terrifico","latin":"terrifico, terrificare, terrificavi, terrificatus","headword":"terrifico","letter":"t","pos":"verb","posGroup":"verb","english":"terrify","forms":["terrificant","terrificō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ibi Deus dēdit iīs lēgem cum apparātū terrificō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"territo","latin":"territo, territare, territavi, territatus","headword":"territo","letter":"t","pos":"verb","posGroup":"verb","english":"intimidate; keep on frightening","forms":["territant","territat"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Legationes in omnes partes circummittuntur; quantum gratia, auctoritate, pecunia valent ad sollicitandas civitates nituntur; nacti obsides quos Caesar apud eos deposuerat, horum supplicio dubitantes {{territant}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"territus","latin":"territus, -a, -um","headword":"territus","letter":"t","pos":"adjective","posGroup":"adjective","english":"terrified","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"terror","latin":"terror, -ōris (m.)","headword":"terror","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"fright, terror; fear, terror; terror, fright","forms":["Terror","terrōre","terrorem","terrori","terrōris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus {{terrorem}} inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tertio","latin":"tertiō","headword":"tertiō","letter":"t","pos":"adverb","posGroup":"adverb","english":"for the third time","forms":["tertia","tertio"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria uteretur, oppugnare instituit idque biduo circumvallavit; {{tertio}} die missis ex oppido legatis de deditione, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tertium","latin":"tertium","headword":"tertium","letter":"t","pos":"adverb","posGroup":"adverb","english":"for the third time","forms":["tertium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ūnus ex hīs puerulīs post diem {{tertium}} nocte mortuus est: māter surripuit puerum alterīus mulieris dormientis, et huius locō fīlium suum mortuum supposuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tertius","latin":"tertius, -a, -um","headword":"tertius","letter":"t","pos":"adjective","posGroup":"adjective","english":"third","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"tessera","latin":"tessera, tesserae","headword":"tessera","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"die; square tablet marked with watchword, countersign; token, ticket","forms":["tessera","tesserae","tesserās","tesserīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"ālea -ae f — lūdus quō {{tesserīs}} iacī-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"testa","latin":"testa, testae","headword":"testa","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"object made from burnt clay; earthenware jar; fragment of earthenware, shard","forms":["Testā"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Testā autem mēnsa plāna facta est.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"testamentum","latin":"testāmentum, -ī","headword":"testāmentum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"will, testament","forms":["testamentī","testāmentō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hic est enim sanguis meus novī testamentī, quī prō mulfīs effundētur in remissiōnem peccātōrum.\"Et hymnō dictō, exiērunt in montem Olivefī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"testari","latin":"(testor) testārī","headword":"testārī","letter":"t","pos":"","posGroup":"other","english":"call to witness","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"testatus","latin":"testatus, testata, testatum","headword":"testatus","letter":"t","pos":"adjective","posGroup":"adjective","english":"known on good evidence","forms":["Testātus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hīc habēmus īnstrūmenta.” [Lūcius Gāium sēcum dūcit ad iūdicēs.] [Iūdex:] “Dēnūntiāstī illī?” [Lūcius:] “Dēnūntiāvī.” [Iūdex:] “{{Testātus}} es?” [Lūcius:] “Testātus sum.” [Iūdex:] “Parātus estō!” [Lūcius:] “Parātus sum.” [Iūdex:] “Et adversārius interpellāre vult.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"testificor","latin":"testificor, testificari, testificatus sum","headword":"testificor","letter":"t","pos":"verb","posGroup":"verb","english":"assert solemnly, testify (to a fact); demonstrate; invoke as a witness","forms":["testificēre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"270 té memorem dominae {{testificēre}} tuae.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"testimonium","latin":"testimonium, testimoni(i)","headword":"testimonium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"testimony; deposition; evidence; witness; (used of ark and tabernacle) (Plater)","forms":["testimōnium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nōn occīdētis, nōn adulterābitis, nōn faciētis fūrtum; nōn dīcētis falsum {{testimōnium}} adversus proximum vestrum; nōn concupīscētis rem alterīus.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"testis","latin":"testis, -is","headword":"testis","letter":"t","pos":"noun (m.); noun","posGroup":"noun","english":"(m.) witness","forms":["teste","testem","testes","testibus","testis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sibi numquam placuisse Avaricum defendi, cuius rei {{testes}} ipsos haberet; sed factum imprudentia Biturigum et nimia obsequentia reliquorum uti hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"testor","latin":"testor, -ārī, -ātus sum","headword":"testor","letter":"t","pos":"verb","posGroup":"verb","english":"to bear witness, declare","forms":["testantia","testātur","testor"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quō magis illa canit, magis hōc tellūre levātī\nērigimur, saetaeque cadunt, bifidōsque relinquit\nrīma pedēs, redeunt umerī et subiecta lacertīs\nbracchia sunt; flentem flentēs amplectimur ipsī\nhaerēmusque ducis collō, nec verba locūtī\nūlla priōra sumus quam nōs {{testantia}} grātōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"testudo","latin":"testudo, testudinis","headword":"testudo","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tortoise; testudo; armored movable shed; troops locking shields overhead","forms":["testudine"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alii tela coiciunt, alii {{testudine}} facta subeunt; defatigatis in vicem integri succedunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tetrarches","latin":"tetrarches, tetrarchae","headword":"tetrarches","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tetrarch (minor king under Roman protection)","forms":["tetrarchae"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nam postquam rēs pūblica in paucōrum potentium iūs atque diciōnem concessit, semper illīs rēgēs, {{tetrarchae}} vectīgālēs esse, populī, nātiōnēs stīpendia pendēre — cēterī omnēs, strēnuī, bonī, nōbilēs atque ignōbilēs, vulgus fuimus sine grātiā, sine auctōritāte, eīs obnoxiī quibus, sī rēs pūblica valēret, formīdinī essēmus.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"tetricus","latin":"tetricus, tetrica, tetricum","headword":"tetricus","letter":"t","pos":"adjective","posGroup":"adjective","english":"harsh, gloomy, severe","forms":["tetricae","tetricam","tetricus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{tetricus}} -ā -um — sēvérūs, inimīcus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"teucer","latin":"Teucer, Teucri","headword":"Teucer","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Teucer; (ancestor of the Trojans; Greek archer, son of Telamon)","forms":["Teucrī","Teucrōrum","Teucrōs","Teucrum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Aut hōc inclūsī lignō occultantur Achīvī,\naut haec in nostrōs fābricāta est māchina mūrōs\nīnspectūra domōs ventūraque dēsuper urbī,\naut aliquis latet error: equō nē crēdite, Teucrī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"texo","latin":"texo, texere, texui, textus","headword":"texo","letter":"t","pos":"verb","posGroup":"verb","english":"weave; plait (together); construct with elaborate care","forms":["texendā","textae","textam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Dederat illī togam {{textam}} ē fīlīs variī colōris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"textile","latin":"textile, -is","headword":"textile","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"weaving, woven cloth","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"textilis","latin":"textilis, textilis, textile","headword":"textilis","letter":"t","pos":"adjective","posGroup":"adjective","english":"woven","forms":["textilī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pictūrās pulchrās in textilī format.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"thalamus","latin":"thalamus, -ī","headword":"thalamus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"inner room, bedroom, marriage bed; marriage couch, marriage, bedroom; marriage couch, chamber; bedchamber","forms":["thalamī","thalamō","thalamōs","thalamum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aegeus hanc accipit, neque satis hospitium est, sed sē Medeae foedere thalamī quoque iungit, nam spērābat sē arte Medeae fīlium prōcreātūrum esse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"theatrum","latin":"theātrum, -ī","headword":"theātrum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"theatre","forms":["theātra","theātrīs","theatro","theatrum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: \"Ego ludos scaenicos praefero: malo fabulas spectare in {{theatro}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"theba","latin":"Theba, Thebae","headword":"Theba","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thebes; (Greek city; Egyptian city)","forms":["Thēbae","Thēbārum","Thēbās","Thēbīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum iīs igitur iuvenis moenia urbis aedificāvit, quam ‘Cadmēiam’ ā nōmine suō vocāvit; incolae autem, post Cadmī mortem, eam ‘{{Thēbās}}’ appellāvērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"thebae","latin":"Thēbae, -ārum","headword":"Thēbae","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thebes (the city)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"thebanus","latin":"Thēbānus, -a, -um","headword":"Thēbānus","letter":"t","pos":"adjective","posGroup":"adjective","english":"Theban","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"theca","latin":"theca, thecae","headword":"theca","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"case, box; that which encloses, envelope/cover/hull/sheath (L+S); vagina","forms":["thēcā","thēcam"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rogô, mē putātis illā cēnā esse contentum quam in thēcā repositôriî vîderâtis? cēnandum philologiam nôsse.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"therma","latin":"therma, thermae","headword":"therma","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"warm/hot baths (pl.); baths","forms":["thermae","thermās","thermīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Agrippā, duce illūstrī quī classī Augustī praefectus erat, itemque magnae balneae quae ab eōdem {{thermae}} Agrippae vocantur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"thermae","latin":"thermae, -ārum (pl.)","headword":"thermae","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"public baths","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"thesaurus","latin":"thēsaurus, -ī","headword":"thēsaurus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"treasure, treasury; treasure","forms":["thēsaurīs","thēsaurōs","thēsaurum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sed quômodo dîcunt rapuisset, {{thēsaurum}} invēnit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"theseus","latin":"Thēseus, -eī","headword":"Thēseus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Theseus, son of Aegeus","forms":["Thēsēa","Thēseī","Thēseō","Theseu","Thēseum","Thēseus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Thēseus}}, fortissimus iuvenis, ad Eurytus conversus: “Quae stultitia tē,” inquit, “scelestē, capit, quī Pīrithoō ita nocēre cōnāris?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"thessalonica","latin":"Thessalonica, Thessalonicae","headword":"Thessalonica","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thessalonica (Macedonian city); (now Saloniki)","forms":["Thessalonīca"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Beroea prīmum, deinde {{Thessalonīca}} et Pella et deinceps omnis fermē Macedonia intrā bīduum dēdita.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"thetis","latin":"Thetis, Thetidis","headword":"Thetis","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thetis; (sea goddess, mother of Achilles)","forms":["Thetidis","Thetis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{Thetidis}}, deae maris (Thetis -īdīs /)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"thisbe","latin":"Thisbē, -ēs","headword":"Thisbē","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thisbe (a maiden)","forms":["Thisbē","Thisbēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pyramus iuvenis pulcherrimus et Thisbē virgō fōrmōsissima domōs vīcīnās tenuērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"thracia","latin":"Thracia, Thraciae","headword":"Thracia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Thrace; (vaguely defined country east of Macedon/north-east of Greece)","forms":["Thrāciā","Thrāciae","Thrāciam"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Thràce -es f (acc Gr -ēn) — Thrāciā","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"thyia","latin":"thyia, thyiae","headword":"thyia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"citrus tree (Greek name for)","forms":["Thȳias"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Thȳias}}, ubi audītō stimulant trietērica Bacchō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"thymum","latin":"thymum, thymi","headword":"thymum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"thyme","forms":["thyma"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"pāscuā per flōrēs et {{thyma}} summa volant,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ti","latin":"Ti., abb.","headword":"Ti","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tiberius, Roman praenomen; (abb. Ti./Tib.)","forms":["tī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Üsus opus movet hoc: vàtī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tiara","latin":"tiara, tiarae","headword":"tiara","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"ornamented conical felt Asian head-dress; Phrygian bonnet w/cheek lappets","forms":["tiārīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Posteā Mīdās aurēs purpureīs {{tiārīs}} pudōre celāre cōnābātur, sed servus, quī capillōs longōs resecābat, aurēs vīderat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tiberinus","latin":"Tiberinus, Tiberini","headword":"Tiberinus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tiber (river); (Collins)","forms":["Tiberīnī","Tiberīnum","Tiberīnus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hae tibi erunt artēs: pācīque impōnere mōrem, parcere subiectīs et dēbellāre superbōs.' Cumīs profectus Aenēās prīmum portum Caiētae petīvit, deinde ventīs secundīs ad ōstium {{Tiberīnum}} advectus est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tiberis","latin":"Tiberis, Tiberis","headword":"Tiberis","letter":"t","pos":"noun","posGroup":"noun","english":"Tiber; (the river at Rome)","forms":["Tiberim","Tiberis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sōla in cubiculō suō Dōrippa forem clausam aspicit, tum ad fenestram apertam accēdit, unde {{Tiberim}} flūmen spectat et pontem Fabricium, quī dūcit ad parvam īnsulam in mediō pōns pontis flūmine sitam.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tiberius","latin":"Tiberius, Tiberi","headword":"Tiberius","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tiberius (praenomen); abb. Ti./Tib.; (Tiberius Julius Caesar Emperor, 14-37 AD)","forms":["Tiberī","Tiberiī","Tiberiō","Tiberium","Tiberius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cornēlia bona et proba fēmina Rōmāna fuit, quae duōs habuit fīliōs, quōrum alterī {{Tiberius}}, alterī Gāius nōmina erant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tibi","latin":"tibi","headword":"tibi","letter":"t","pos":"pronoun","posGroup":"pronoun","english":"you, yourself (dat.); to you, for you (dative)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"tibia","latin":"tībia, -ae","headword":"tībia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"shin bone, pipe, flute","forms":["tībiae","tībiam","tībiīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ut vērō amōris dolōrem, quō animus eius afficiēbātur, levāret, nōnnumquam in celsum saxum ascendēbat, unde, mare prōspiciēns, {{tībiīs}} ūsus hōc modō canēbat: “Ō fōrmōsa Galatēa, cāseō candidior, agnō suāvior, ūva mātūra dulcior, cūr mē amantem contemnis, sī dīligenter tē cūrō?","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tibicen","latin":"tībīcen, tībicinis","headword":"tībīcen","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"(m.) flute player","forms":["tībīcen","tībīcine","tībīcinēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Et cum vēnisset domum prīncipis, et vīdisset {{tībīcinēs}} et turbam tumultuantem, dīcēbat:\"Recēdite: nōn est enim mortua puella, sed dormit.\"Et cum ēiecta esset turba, intrāvit, et tenuit manum eius.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tigris","latin":"tigris, -is (m./f.)","headword":"tigris","letter":"t","pos":"noun; noun (f.)","posGroup":"noun","english":"tiger; a tiger","forms":["tigrēs","tigribus","tigride","Tigrim","tigrīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Intereā Tobiās et angelus pervēnēre ad flūmen {{Tigrim}}, et cum adulēscēns accessisset ad abluendōs pedēs, ecce piscis ingēns exsiluit, quasi illum dēvorātūrus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tigurinus","latin":"Tigurinus, Tigurini","headword":"Tigurinus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tiguri, one of the four divisions of the Helvetii - in Caesar's \"Gallic War\"","forms":["Tīgurīnīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caepiō ā Cimbrīs et Teutonibus et {{Tīgurīnīs}} et Ambrōnibus, quae erant Germānōrum et Gallōrum gentēs, victī sunt iuxtā flūmen Rhodanum ingentī interniciōne; etiam castra sua et magnam partem exercitūs perdidērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tilia","latin":"tilia, tiliae","headword":"tilia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"lime-tree","forms":["tiliā"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nārrābō dē duābus arboribus, dē tiliā et quercū in Phrygiā.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tim","latin":"Tim., abb.","headword":"Tim","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Timothy (abb.); (Book of the Bible)","forms":["tim"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"rūstica pāūlà{{tim}} taurus","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"timeo","latin":"timeō, -ēre, -uī","headword":"timeō","letter":"t","pos":"verb","posGroup":"verb","english":"fear, be afraid of","forms":["timē","timeam","timeās","timeat","timeātis","timēbant","timēbās","timebat","timenda","timendum","timēns","timent","timentes","timeō","timēre","timērent","timēret","timērī","timēris","timēs","timet","timēte","timētis","timētur","timuēre","timuerint","timuerīs","timuerītis","timuērunt","timuī","timuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eo cum venisset, {{timentes}} confirmat, praesidia in Rutenis provincialibus, Volcis Arecomicis, Tolosatibus circumque Narbonem, quae loca hostibus erant finitima, constituit; partem copiarum ex provincia supplementumque quod ex Italia adduxerat in Helvios, qui fines Arvernorum contingunt, convenire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"timet","latin":"timet, timent","headword":"timet","letter":"t","pos":"verb","posGroup":"verb","english":"fear, be afraid (of); fears, is afraid of","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"timide","latin":"timide, timidius, timidissime","headword":"timide","letter":"t","pos":"adverb","posGroup":"adverb","english":"timidly, fearfully, apprehensively, nervously; cautiously, with hesitation","forms":["timidē"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Baucis et Philēmōn, quōrum casa in templum est mūtāta, lavis sacerdōtēs fīunt Dīcite igitur, sī quid habēre vēlitis, et ego vōbīs libenter dabō.” At illī timidē “Sacerdōtēs” respondērunt “tuī templī esse velimus, dum vīvēmus, tum etiam eōdem diē morī, quoniam neuter nostrum sōlus vīvere potest.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"timidus","latin":"timidus, -a, -um","headword":"timidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"timid; timid, fearful; shy, timid","forms":["timida","timidae","timidās","timidī","timidīs","timidissima","timidō","timidōs","timidum","timidus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Et accessērunt ad eum discipulī eius, et suscitāvērunt eum dīcentēs:\"Domine, salviī nōs: perīmus ī\"Et dīcit eīs Jēsus:\"Quid timidī estis?\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"timor","latin":"timor, timōris","headword":"timor","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"(m.) fear","forms":["timor","timore","timōrem","timoris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ubi eos in sententia perstare viderunt, quod plerumque in summo periculo {{timor}} misericordiam non recipit, conclamare et significare de fuga Romanis coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tina","latin":"tina, tinae","headword":"tina","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"cask; tub","forms":["tīna"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Cum haec dīcerent, Hippodame, pulcherrima virgō, {{tīna}} cum aliīs fēminīs et mātrōnīs trīclīnium intrāvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tingere","latin":"(tingō) tingere, -xisse, -ctum","headword":"tingere","letter":"t","pos":"","posGroup":"other","english":"wet, soak","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tingo","latin":"tingo, tingere, tinxi, tinctus","headword":"tingo","letter":"t","pos":"verb","posGroup":"verb","english":"wet/moisten/dip/soak; color/dye/tinge/tint, stain (w/blood); imbue; impregnate","forms":["tīnctum","tinge","tingere","tingunt","tīnxērunt","tīnxisse","tīnxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tunc frātrēs Iōsēphī {{tīnxērunt}} togam eius in sanguine haedī quem occīderant, et mīsērunt eam ad patrem cum hīs verbīs: invenīmus hanc togam; vidē an toga fīliī tuī sit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tinguo","latin":"tinguo, tinguere, tinxi, tinctus","headword":"tinguo","letter":"t","pos":"verb","posGroup":"verb","english":"wet/moisten/dip/soak; color/dye/tinge/tint, stain (w/blood); imbue; impregnate","forms":["tinguere"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quid tantum Ōceanō properent sē {{tinguere}} sōlēs","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"tinnio","latin":"tinnio, tinnire, tinnivi, tinnitus","headword":"tinnio","letter":"t","pos":"verb","posGroup":"verb","english":"ring/clang/jangle (metal); ring (ears); utter a shrill/metallic sound","forms":["tinniant","tinnīre","tinnit","tinniunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Ānulus {{tinnit}}: “Tintintin...”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tinus","latin":"tinus, tini","headword":"tinus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"laurustinus; (bay/laurel); evergreen winter-flowering shrub (Viburnum ~ OED)","forms":["tīne"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Apollō igitur, trīstis ad arborem accēdēns, “Ego” inquit, “semper tē flēbō, amīce; tū vērō aliōs flēbis et dolentibus hominibus omnī tempore aderis!” Hoc est cūr arborem, quae ex illō puerō Graecē ‘cyparissī’, La {{tīne}} vērō ‘cupressī’ nōmen habet, prope amīcōrum nostrōrum sepulcra pōnāmus.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tiro","latin":"tīrō, -ōnis (m.)","headword":"tīrō","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"recruit; new recruit, novice soldier","forms":["tīrōnēs","tīrōnum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et cum Latīnī, quī ā Rōmānīs subāctī erant, mīlitēs praestāre nōllent, ex Rōmānīs tantum {{tīrōnēs}} lēctī sunt, factaeque legiōnēs decem; quī modus sexāgintā vel amplius armātōrum mīlia efficiēbat. (Parvīs adhūc Rōmānīs rēbus tanta tamen in rē mīlitārī virtūs erat.)","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"titan","latin":"Titan, Titanos/is","headword":"Titan","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Titan; (one of race of gods/giants preceding Olympians)","forms":["Tītānī","Tītānis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Promētheus fuit fīlius Tītānī, nōmine Īapetī, et Nymphae, quae Clymenē appellābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tithonus","latin":"Tithonus, Tithoni","headword":"Tithonus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tithonus; (mortal lover of Aurora/Eos, granted immortality but not youth)","forms":["Tīthōnī"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tīthōnī croceum linquēns Aurōra cubīle.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"titubo","latin":"titubo, titubare, titubavi, titubatus","headword":"titubo","letter":"t","pos":"verb","posGroup":"verb","english":"stagger, totter; falter","forms":["titubāre","titubet"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{titubāre}} — paene cadere/lābī, turbàrī","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"titulus","latin":"titulus, -ī","headword":"titulus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"title","forms":["titulō","titulōs","titulum","titulus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sex librōs eius possideō quibus {{titulus}} est {i}Dē rērum nātūrā.”{/i}","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"titus","latin":"Titus, Titi","headword":"Titus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Titus; Roman praenomen, abb. T.; (~ Flavius Vespasianus, Emperor, 79-81 AD)","forms":["Tite","Titī","Titō","Titum","Titus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Titus}}: “Ergō necesse est tē ipsum rēs tuās portāre, ut ego et Sextus rēs nostrās ipsī portāmus.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"toga","latin":"toga, -ae","headword":"toga","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"toga","forms":["toga","togam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dederat illī {{togam}} textam ē fīlīs variī colōris.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"toga virilis","latin":"toga virīlis","headword":"toga virīlis","letter":"t","pos":"phrase","posGroup":"other","english":"the toga of manhood","forms":[],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"togatus","latin":"togātus, -a, -um","headword":"togātus","letter":"t","pos":"adjective","posGroup":"adjective","english":"wearing the toga","forms":["togātō","togātōrum","togātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Virō togātō nūlla pars corporis est nūda praeter bracchium alterum.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"tolerabilis","latin":"tolerābilis, -e","headword":"tolerābilis","letter":"t","pos":"adjective","posGroup":"adjective","english":"tolerable","forms":["tolerābile","tolerābilī","tolerābilia"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"P$Ā Nec ūllus tot malôrum ﬁnīs fuisset nisi epidîpnīs esset allāta: turdî silîgineî üvîs passîs ñucibusque farsî. În- secūta sunt Cydônia etiam mäla spînîs cônﬁxa, ut echînôs Et haec quidem {{tolerābilia}} erant, sī nôn ferculum longē mônstrôsius effēcisset ut vel famē perîre mällêmus!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"tolerare","latin":"(tolerō) tolerāre","headword":"tolerāre","letter":"t","pos":"","posGroup":"other","english":"bear, endure","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tolero","latin":"tolero, tolerare, toleravi, toleratus","headword":"tolero","letter":"t","pos":"verb","posGroup":"verb","english":"bear, endure, tolerate","forms":["tolerābat","toleranda","tolerandam","tolerare","tolerāret","tolerātam","tolerāverant","toleraverunt","tolerāvisse"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ratione inita exigue dierum se habere XXX frumentum, sed paulo etiam longius {{tolerare}} posse parcendo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tollere","latin":"tollere","headword":"tollere","letter":"t","pos":"verb","posGroup":"verb","english":"to raise, lift","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"tollo","latin":"tollō, tollere","headword":"tollō","letter":"t","pos":"verb","posGroup":"verb","english":"raise, lift, pick up, remove, take away; raise, lift; raise, lift up","forms":["sublāta","sublātam","sublātīs","sublato","sublātōs","sublātum","sustulerant","sustulērunt","sustulissent","sustulisset","sustulit","tollās","tollat","tolle","tollēbantur","tollēmus","tollendam","tollēns","tollere","tollerem","tollerentur","tolleret","tolleretur","tollētur","tollī","tollit","tollite","tollitō","tollō","tollunt","tolluntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quem simul atque oppidani conspexerunt atque in spem auxili venerunt, clamore {{sublato}} arma capere, portas claudere, murum complere coeperunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tomaculum","latin":"tomaculum, tomaculi","headword":"tomaculum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"kind of sausage","forms":["tomācula"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec mora: ex plägîs ponderis inclînätiône crēscentibus {{tomācula}} cum rogāmus ut eum mittās (z im- sî piscem exinterāre praeter- ponderis ī.ē : quia pondus fēcit rē-porrigere : rogāvit ut [T rimalchiô dē\" āere Corinthiā‘, dē‘ vitrô, dê argentô] Plausum post hōc automātum familia dedit et “Gäiô féliciter!” conclāmāvit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"tonare","latin":"(tonō) tonāre, -uisse","headword":"tonāre","letter":"t","pos":"verb","posGroup":"verb","english":"thunder; to thunder","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"tonat","latin":"tonat, tonare, -, tonatus est","headword":"tonat","letter":"t","pos":"verb","posGroup":"verb","english":"it thunders","forms":["tonat"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"[Amphitryō ad ōstium versus properat, cum subitō ita clārē fulget ac tam validē {{tonat}} ut ille quasi mortuus ante forēs concīdat.]","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"tondeo","latin":"tondeo, tondere, totondi, tonsus","headword":"tondeo","letter":"t","pos":"verb","posGroup":"verb","english":"cut, shear, clip","forms":["tondēre","tōnsum","totondisse","tōtondit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Mulier virō persuāsit, ut sibi indicāret causam tantae virtūtis; et ubi rescīvit vīrēs eius in capillīs sitās esse, caput dormientīs {{tōtondit}}, atque ita Philistaeīs trādidit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tonitrus","latin":"tonitrus, -ūs","headword":"tonitrus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"(m.) thunder","forms":["tonitrū","tonitrum","tonitrus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Titus et Mārcus, quī fulgura ac {{tonitrum}} verentur, statim surgunt et Sextum in viā iacentem relinquunt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tonitruum","latin":"tonitruum, tonitrui","headword":"tonitruum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"thunder","forms":["tonitrua"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Coepērunt exaudīrī {{tonitrua}}, micāre fulgura: nūbēs dēnsa operiēbat montem, et clangor buccinae vehementius perstrepēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tono","latin":"tono, tonare, tonui, tonitus","headword":"tono","letter":"t","pos":"verb","posGroup":"verb","english":"thunder; speak thunderous tones/thunderously; make/resound like thunder","forms":["tonitus","tonuit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"at-{{tonitus}} -ā -um (ad-) 7 (tonitrū)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tonsura","latin":"tonsura, tonsurae","headword":"tonsura","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"clipping, shearing; pruning; tonsure; haircut","forms":["tōnsūra"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{tōnsūra}} -ae f'« tondēre totondisse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tonsus","latin":"tonsus, tonsa, tonsum","headword":"tonsus","letter":"t","pos":"adjective","posGroup":"adjective","english":"shorn, clipped, cut, lopped","forms":["tōnsus"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"sūra, pēs, statūra, {{tōnsus}}, oculī, nāsus, vel labra,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"tonus","latin":"tonus, toni","headword":"tonus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tone, pitch (sound), note; interval; musical scale; astronomical measure","forms":["tone"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ego respiciēns ad Ascyltōn “Quid côgitäs?” inquam, “Ego enim, sî vîderô balneum, statim expîräbô!” “Assentēmur” ait ille, “et dum illî balneum petunt, nôs Cum haec placuissent, dücentē per porticum Gî{{tone}} ad excēpit ut Ascyltos etiam in piscînam cecīderit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"toreuma","latin":"toreuma, toreumatis","headword":"toreuma","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"carved or embossed work","forms":["toreumata"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum tabulās, signa, {{toreumata}} emunt, nova dīruunt, alia aedificant, postrēmō omnibus modīs pecūniam trahunt, vexant, tamen summā libīdine dīvitiās suās vincere nequeunt!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"tormentum","latin":"tormentum, tormenti","headword":"tormentum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"windlass; instrument for twisting/winding; engine for hurling stones; missile","forms":["tormenta","tormentī","tormentis","tormentum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nam maiore commisso delicto igne atque omnibus {{tormentis}} necat, leviore de causa auribus desectis aut singulis effossis oculis domum remittit, ut sint reliquis documento et magnitudine poenae perterreant alios.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"torpeo","latin":"torpeo, torpere, -, -","headword":"torpeo","letter":"t","pos":"verb","posGroup":"verb","english":"be numb or lethargic; be struck motionless from fear","forms":["torpent","torpentī","torpeō","torpēre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{torpēre}} — languére, iners esse, fātī- [Dē amōre torpentī excitandō]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"torpesco","latin":"torpesco, torpescere, torpui, -","headword":"torpesco","letter":"t","pos":"verb","posGroup":"verb","english":"grow numb, become slothful","forms":["torpēscerent"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī causa peccandī in praesēns minus suppetēbat, nihilō minus īnsontēs sīcuti sontēs circumvenīre, iugulāre; scīlicet nē per ōtium {{torpēscerent}} manūs aut animus, grātuītō potius malus atque crūdēlis erat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"torquatus","latin":"torquātus, -a, -um","headword":"torquātus","letter":"t","pos":"adjective","posGroup":"adjective","english":"wearing a collar, necklace","forms":["Torquātī","Torquātō","Torquātum","Torquātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eius reī exemplum memorātur Titus Mānlius {{Torquātus}}, quī fīlium suum cōram exercitū necārī iussit quia contrā imperium patris cum hoste pugnāverat.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"torqueo","latin":"torqueo, torquere, torsi, tortus","headword":"torqueo","letter":"t","pos":"verb","posGroup":"verb","english":"turn, twist; hurl; torture; torment; bend, distort; spin, whirl; wind (round)","forms":["torque","torquent","torquentēs","torquēre","torquet","torserit","torsit","tortus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ēheu, quam multós advena {{torsit}} amor!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"torques","latin":"torques, torquis","headword":"torques","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"collar/necklace of twisted metal (often military); wreath (L+S); ring; chaplet","forms":["torquem","torquēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum dētrāxit ē manū suā annulum, et Iōsēphī digitō īnseruit; induit illum veste byssinā, collō {{torquem}} aureum circumdedit, eumque in currū suō secundum collocāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"torreo","latin":"torreo, torrere, torrui, tostus","headword":"torreo","letter":"t","pos":"verb","posGroup":"verb","english":"parch, roast, scorch, bake, burn; dry up; begin to burn; harden by charring","forms":["torrēbat","torrent","torrēre","torrerī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Īrātus rēx ōllās aereās succendī iussit, tum eī, quī locūtus erat, linguam amputarī, cutem capitis detrahī, summās mantīs ac pedēs praecidī, et truncum corpus in ōllā torrerī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"torrere","latin":"(torreō) torrēre, -uisse, -tōstum","headword":"torrēre","letter":"t","pos":"verb","posGroup":"verb","english":"scorch, parch; to scorch, burn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"torridus","latin":"torridus, -a, -um","headword":"torridus","letter":"t","pos":"","posGroup":"other","english":"scorched, parched","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"torta","latin":"torta, tortae","headword":"torta","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"pie","forms":["tortae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Vënit ergô, galbinô succîncta cingillô, periscelis _ ita ut înfrä cerasina appārēret tunica et periscelidēs {{tortae}} phaecasiaeque inaurā- tae.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"tortuosus","latin":"tortuosus, tortuosa, tortuosum","headword":"tortuosus","letter":"t","pos":"adjective","posGroup":"adjective","english":"twisting, tortuous","forms":["tortuōsīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Nec loquācēs autem” inquit “convīvās nec mūtōs legere oportet, quia ēloquentia in forō et apud subsellia, silentium vērō nōn in convīviō, sed in cubiculō esse dēbet.” Sermōnēs igitur id temporis habendōs cēnset ‘nōn super rēbus anxiīs aut {{tortuōsīs}}, sed iūcundōs atque invītābilēs et cum quādam illecebrā et voluptāte ūtilēs, ex quibus ingenium nostrum venustius fīat et amoenius.’","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"torus","latin":"torus, -ī","headword":"torus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"bed, couch; couch","forms":["torī","torīs","torō","torōs","torum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vertumnumque torī socium tibi sēlige!...","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"torvus","latin":"torvus, torva, torvum","headword":"torvus","letter":"t","pos":"adjective","posGroup":"adjective","english":"pitiless/grim; fierce/stern/harsh/savage/dreadful; staring/piercing/wild (eye)","forms":["torvīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"quem videat lacrimàns, quem {{torvīs}} spectet ocellīs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tot","latin":"tot","headword":"tot","letter":"t","pos":"adjective","posGroup":"adjective","english":"so many","forms":["tot"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vercingetorix, {{tot}} continuis incommodis Vellaunoduni, Cenabi, Novioduni acceptis, suos ad concilium convocat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"totidem","latin":"totidem","headword":"totidem","letter":"t","pos":"","posGroup":"other","english":"as many","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"totidemus","latin":"totidemus, totidema, totidemum","headword":"totidemus","letter":"t","pos":"adjective","posGroup":"adjective","english":"as many; just so/as many; the equivalent number of, same (as specified before)","forms":["totidem"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam Noëmus ipse ingressus est in arcam cum coniuge, tribus fīliīs et {{totidem}} nuribus, aquā maris et omnium fontium ērūpērunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"toties","latin":"totiēs","headword":"totiēs","letter":"t","pos":"adverb","posGroup":"adverb","english":"so many times","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"totus","latin":"tōtus, -a, -um","headword":"tōtus","letter":"t","pos":"adjective","posGroup":"adjective","english":"the whole of, all","forms":["tota","totae","tōtam","tōtās","toti","tōtīs","totius","toto","tōtōs","totum","tōtus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ibi cognoscit de Clodi caede, de senatusque consulto certior factus, ut omnes iuniores Italiae coniurarent, dilectum {{tota}} provincia habere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tr","latin":"tr","headword":"tr","letter":"t","pos":"numeral","posGroup":"numeral","english":"three","forms":["terna","ternī","ternos","Tertiae","tertiam","tertius","tr","tres","tria","tris","trium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante {{tertiam}} vigiliam est animadversum fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab utroque latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"trabes","latin":"trabes, trabis","headword":"trabes","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tree-trunk, beam, timber; ship","forms":["trabes"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Trabes}} directae perpetuae in longitudinem paribus intervallis distantes inter se binos pedes in solo collocantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"trabs","latin":"trabs, -bis ( f.)","headword":"trabs","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"beam, ship; beam, timber","forms":["trabem","trabī","trabibus","trabs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis {{trabibus}} ac saxis quae rectis lineis suos ordines servant, tum ad utilitatem et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tractabilis","latin":"tractabilis, tractabilis, tractabile","headword":"tractabilis","letter":"t","pos":"adjective","posGroup":"adjective","english":"manageable; tractable; easy to deal with","forms":["tractābile","tractābilis"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"quassātaeque ratēs, dum nōn {{tractābile}} caelum.'","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"tractare","latin":"(tractō) tractāre","headword":"tractāre","letter":"t","pos":"","posGroup":"other","english":"handle, treat, manage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tractatus","latin":"tractatus, tractatus","headword":"tractatus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"dealing w/problem/subject/treatment; treatment method; handling/management","forms":["tractātū"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mox — ipsō tractātū, ut fierī solet, diffundente sē crīmine — plūrēs speciēs incidērunt.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"tracto","latin":"tracto, tractare, tractavi, tractatus","headword":"tracto","letter":"t","pos":"verb","posGroup":"verb","english":"draw, haul, pull, drag about; handle, manage, treat, discuss","forms":["tractābant","tractābat","tractāre","tractārent","tractātīs","tractāvissent","tractāvit","tractō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Post novem diēs et novem noctēs, herbīs collēctīs, Medea curru dracōnibus pennātīs tractō rediit; dracōnēs sōlum odōre herbārum tāctī pellēs senectūtis dēposuērunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tractus","latin":"tractus, tractus","headword":"tractus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"dragging or pulling along; drawing out; extent; tract, region; lengthening","forms":["tractus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī quidem, cum ad rēgem {{tractus}} esset “Rōmānus sum” inquit “cīvīs; Gāium Mūcium mē vocant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tradere","latin":"(trādō) trādere, trādidisse, trāditum","headword":"trādere","letter":"t","pos":"verb","posGroup":"verb","english":"hand over or down; to hand over, deliver","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"tradit","latin":"trādit","headword":"trādit","letter":"t","pos":"verb","posGroup":"verb","english":"hands over, delivers","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"trado","latin":"trādō, -ere, trādidī, trāditum","headword":"trādō","letter":"t","pos":"verb","posGroup":"verb","english":"hand over, betray, surrender","forms":["trādant","trādat","tradatur","trāde","tradebant","trādendum","trādentibus","tradere","trāderent","trāderentur","trāderet","trāderētur","trādet","trādētur","tradi","trādiderīs","trādiderit","tradiderunt","trādidī","tradidisse","trādidisset","trādidit","trādis","trādit","tradita","trāditae","traditas","trāditī","Trāditō","traditum","traditur","trāditūrum","Trāditus","trādō","tradunt","traduntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam, ubique maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis {{tradunt}}, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"traducere","latin":"(trādūcō) trādūcere (< dūcere)","headword":"trādūcere","letter":"t","pos":"","posGroup":"other","english":"move (across), pass","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"traduco","latin":"traduco, traducere, traduxi, traductus","headword":"traduco","letter":"t","pos":"verb","posGroup":"verb","english":"bring across/over, move/transfer; convert; cause to cross/to extend across area","forms":["traducēbātur","trādūcere","traducerent","trādūcī","traducit","traducta","traductis","traducuntur","trādūxerat","trādūxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Oppidum diripit atque incendit, praedam militibus donat, exercitum Ligerim {{traducit}} atque in Biturigum fines pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tragicus","latin":"tragicus, -a, -um","headword":"tragicus","letter":"t","pos":"adjective","posGroup":"adjective","english":"tragic; of tragedy","forms":["tragicam","tragicī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Inter haec tempora nōbilēs celebrēsque erant Sophoclēs ac deinde Eurīpidēs, tragicī poētae, et Hippocratēs medicus, et philosophus Dēmocritus, quibus Sōcratēs Athēniēnsis nātū quidem posterior fuit, sed quibusdam temporibus iīsdem vīxērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tragoedia","latin":"tragoedia, -ae","headword":"tragoedia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tragedy","forms":["tragoediā","tragoediae","tragoediam","tragoediārum","tragoediās"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nunc argūmentum huius ēloquar {{tragoediae}}.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"tragoedus","latin":"tragoedus, tragoedi","headword":"tragoedus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tragic actor","forms":["tragoedum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Nec contentus fuit recumbere, sed continuô Ephesum {{tragoedum}} coepit imitärî et subinde dominum suum spônsiône prôvocäre: ‘sī prasinus proxī- mîs circēnsibus prîmam palmam?’ [T rimalchiô dê testämentô et monumentô suô] Diﬂîlsus hāc contentiône Trimalchiô “Amîci!” inquit, “Et servī hominēs sunt et aequē ūnum lactem bibērunt, etiam sî illôs mālus tātus oppresserit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"tragula","latin":"trāgula, -ae","headword":"trāgula","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"spear, javelin","forms":["trāgulā"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ut vērō Hannibal ipse, dum mūrum incautius subit, trāgulā graviter ictus cecidit, tanta circā fuga ac trepidātiō fuit ut nōn multum abesset quīn opera ac vīneae dēsererentur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"trahere","latin":"(trahō) trahere, trāxisse, tractum","headword":"trahere","letter":"t","pos":"","posGroup":"other","english":"drag","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"traho","latin":"trahō, -ere, trāxī, -ctum","headword":"trahō","letter":"t","pos":"verb","posGroup":"verb","english":"draw, draw out, drag","forms":["tracta","trāctum","trahat","trahe","trahēbant","trahēbantur","trahēbat","trahēbātur","trahendō","trahēns","trahere","traherent","trahī","trahit","trahitur","trahō","trahor","trahunt","trahuntur","trāxēre","trāxērunt","trāxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Id ubi rēx cognōvit, fīlium morte plectī voluit; sed recēns meritum perīculō iuvenem exēmit, nec populus tulit īnsontem ad supplicium trahī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"traianus","latin":"Trajanus, Trajani","headword":"Trajanus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Trajan; (Roman cognomen); [M. Ulpius Traianus => Emperor, 98-117 AD]","forms":["Trāiānī","Trāiānō","Trāiānus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hae prīmae thermae Rōmae fuērunt, sed posteā aliae thermae etiam magnificentiorēs aedificātae sunt ab imperātōre Nerōne in campō Mārtiō, ā Titō et Trāiānō in Esquiliīs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"traicere","latin":"(trāicio) trāicere (< icere)","headword":"trāicere","letter":"t","pos":"verb","posGroup":"verb","english":"take across, cross, pierce; to cross, transport across; to cross over, transport","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"traicio","latin":"traicio, traicere, trajeci, trajectus","headword":"traicio","letter":"t","pos":"verb","posGroup":"verb","english":"transfer; transport; pierce, transfix","forms":["trāiceret","trāiciendā","trāiciendus","trāicientēs","trāicit","trāiēcimus","trāiēcisse","trāiēcisset","trāiēcit","trāiectūrus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut Hebraeī in terram prōmissam intrōdūcerentur, Iordānis erat {{trāiciendus}}, nec erat iīs nāvium cōpiā, nec vadum praebēbat amnis tunc plēnō alveō fluēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"traiectus","latin":"trajectus, trajecta, trajectum","headword":"trajectus","letter":"t","pos":"adjective","posGroup":"adjective","english":"crossing, passage","forms":["traiecti","trāiectō","traiectus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quidam ante portam oppidi Gallus per manus sebi ac picis traditas glaebas in ignem e regione turris proiciebat; scorpione ab latere dextro {{traiectus}} exanimatusque concidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"trames","latin":"trames, tramitis","headword":"trames","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"footpath, track; (stream) bed; course; (family) branch; narrow strip (land)","forms":["trāmitēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sed postquam in castra nūntius pervēnit Rōmae coniūrātiōnem patefactam, dē Lentulō et Cethēgō cēterīsque (quōs suprā memorāvī) supplicium sūmptum, plērīque, quōs ad bellum spēs rapīnārum aut novārum rērum studium illexerat, dīlābuntur; reliquōs Catilīna per montēs asperōs magnīs itineribus in agrum Pistōriēnsem abdūcit eō cōnsiliō utī per {{trāmitēs}} occultē perfugeret in Galliam Trānsalpīnam.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"tranatare","latin":"(trānatō) trānatāre","headword":"trānatāre","letter":"t","pos":"","posGroup":"other","english":"swim across","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"trano","latin":"trano, tranare, tranavi, tranatus","headword":"trano","letter":"t","pos":"verb","posGroup":"verb","english":"swim across","forms":["trānantur","trānat"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Obsequiō {{trānantur}} aquae,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tranquillitas","latin":"tranquillitās, tranquillitātis","headword":"tranquillitās","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"(f.) tranquility; calmness, calm","forms":["tranquillitās","tranquillitāte"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Samūēl fuit postrēmus Hebraeōrum iūdex, eōrumque rēs in summā pāce et perpetuā {{tranquillitāte}} administrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tranquillo","latin":"tranquillo, tranquillare, tranquillavi, tranquillatus","headword":"tranquillo","letter":"t","pos":"verb","posGroup":"verb","english":"calm, quiet","forms":["tranquillō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Tum, cum omnēs gaudērent quod marī tranquillō fruēbantur, ventus inexspectātus flāre coepit brevīque caelum nūbibus ātrīs opertum est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tranquillum","latin":"tranquillum, tranquilli","headword":"tranquillum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"calm weather; calm state of affairs","forms":["tranquillum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ut tempestātēs mare {{tranquillum}} turbāre solent, ita verba Apollinis animum Admētī turbāvērunt.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tranquillus","latin":"tranquillus, -a, -um","headword":"tranquillus","letter":"t","pos":"adjective","posGroup":"adjective","english":"calm, still","forms":["tranquilla","tranquillae","tranquillās","tranquillōs","tranquillus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ita quamdiū Alexander rēgnō pofitus est, rēs Iildaēōrum {{tranquillae}} fuērunt; sed paulō post 1ōnathas ā Triphōne quōdam per Īnsidiās necātus est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"trans","latin":"trāns","headword":"trāns","letter":"t","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) across","forms":["trans"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Caesar, quod hostes equitatu superiores esse intellegebat et interclusis omnibus itineribus nulla re ex provincia atque Italia sublevari poterat, {{trans}} Rhenum in Germaniam mittit ad eas civitates quas superioribus annis pacaverat equitesque ab his arcessit et levis armaturae pedites, qui inter eos proeliari consuerant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transalpinus","latin":"Transalpinus, Transalpina, Transalpinum","headword":"Transalpinus","letter":"t","pos":"adjective","posGroup":"adjective","english":"of/belonging to/situated in the region beyond the Alps (from Rome)","forms":["Transalpinam","Trānsalpīnī","Trānsalpīnum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Eae res in Galliam {{Transalpinam}} celeriter perferuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transcendere","latin":"(trānscendō) trānscendere (< scendere)","headword":"trānscendere","letter":"t","pos":"","posGroup":"other","english":"climb across, cross","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transcendo","latin":"transcendo, transcendere, transcendi, transcensus","headword":"transcendo","letter":"t","pos":"verb","posGroup":"verb","english":"climb/step/go across/over; board; transgress; exceed; pass on, make transition","forms":["transcendere"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Fit magna caedes; non nulli relictis equis fossam transire et maceriam {{transcendere}} conantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transeo","latin":"transeo, transire, transivi(ii), transitus","headword":"transeo","letter":"t","pos":"verb","posGroup":"verb","english":"go over, cross","forms":["trānseant","trānsiēre","transire","trānsīrent","trānsīret","transiri","trānsit","trānsītur","trānsitūrum","trānsīvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen {{transire}} ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transfero","latin":"trānsferō, -ferre, trānstulī, trānslātum","headword":"trānsferō","letter":"t","pos":"verb","posGroup":"verb","english":"carry across; transfer","forms":["trānsfer","trānsferās","trānsferātur","transferre","trānsferrī","trānsfert","trānsfertur","trānslātae","translatum","trānstulerant","trānstulistī","trānstulit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Celeriter haec fama ac nuntii ad Vercingetorigem perferuntur; quem perterriti omnes Arverni circumsistunt atque obsecrant ut suis fortunis consulat neve ab hostibus diripiantur, praesertim cum videat omne ad se bellum {{translatum}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transferre","latin":"(trānsferō) trānsferre, trānstulisse, trānslātum","headword":"trānsferre","letter":"t","pos":"verb","posGroup":"verb","english":"transfer, transport; to carry across","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"transfigere","latin":"(trānsfīgō) trānsfīgere (< figere)","headword":"trānsfīgere","letter":"t","pos":"","posGroup":"other","english":"pierce","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transfigo","latin":"transfigo, transfigere, transfixi, transfixus","headword":"transfigo","letter":"t","pos":"verb","posGroup":"verb","english":"transfix, pierce through","forms":["trānsfīgendum","trānsfīgere","trānsfīgit","transfixi","trānsfīxit","trānsfīxō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Primo concursu ab dextro cornu, ubi septima legio constiterat, hostes pelluntur atque in fugam coiciuntur; ab sinistro, quem locum duodecima legio tenebat, cum primi ordines hostium {{transfixi}} telis concidissent, tamen acerrime reliqui resistebant nec dabat suspicionem fugae quisquam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transfodio","latin":"transfodio, transfodere, transfodi, transfossus","headword":"transfodio","letter":"t","pos":"verb","posGroup":"verb","english":"transfix, pierce, impale","forms":["transfodiebantur","trānsfodiendum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Dum longius ab munitione aberant Galli, plus multitudine telorum proficiebant; postea quam propius successerunt, aut se stimulis inopinantes induebant aut in scrobes delati {{transfodiebantur}} aut ex vallo ac turribus traiecti pilis muralibus interibant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transformat","latin":"trānsformat","headword":"trānsformat","letter":"t","pos":"verb","posGroup":"verb","english":"transforms, changes","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"transformo","latin":"transformo, transformare, transformavi, transformatus","headword":"transformo","letter":"t","pos":"verb","posGroup":"verb","english":"change in shape, transform","forms":["trānsfōrmantur","trānsformat","trānsformāverat","trānsfōrmāvit","trānsformet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Ita Iuppiter sē in taurum pulchrum {{trānsformat}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"transfuga","latin":"trānsfuga, -ae (m.)","headword":"trānsfuga","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"deserter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"transfugere","latin":"(trānsfugiō) trānsfugere (< fugere)","headword":"trānsfugere","letter":"t","pos":"verb","posGroup":"verb","english":"go over, desert; to desert, go over to the enemy","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"transfugio","latin":"transfugio, transfugere, transfugi, -","headword":"transfugio","letter":"t","pos":"verb","posGroup":"verb","english":"go over to the enemy, desert","forms":["transfugerent","trānsfūgerit","trānsfūgit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam cum aliīs urbānīs operibus intentum sē esse simulāret, Sextus, fīlius eius quī minimus ex tribus erat, {{trānsfūgit}} ex compositō Gabiōs patris in sē saevitiam nōn tolerandam querēns: 'rēgem iam ab aliēnīs in suōs vertisse superbiam et līberīs quoque īnsidiās parāre, nē quem hērēdem regnī relinquat; sē quidem inter tēla et gladiōs patris ēlāpsum nihil usquam sibi tūtum nisi apud hostēs L.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transgredi","latin":"(trānsgrediōr) trānsgredī, -gressum","headword":"trānsgredī","letter":"t","pos":"verb","posGroup":"verb","english":"cross; to cross over, pass over; to cross over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"transgredior","latin":"transgredior, transgredi, transgressus sum","headword":"transgredior","letter":"t","pos":"verb","posGroup":"verb","english":"cross, go/move/travel over/across; go to other side; change allegiance/policy","forms":["trānsgreditur","transgressi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque {{transgressi}} trinis castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transgressus","latin":"transgressus, transgressus","headword":"transgressus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"crossing to the other side","forms":["transgressus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Hunc ex proximis unus iacentem {{transgressus}} eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus vacuus relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transigere","latin":"(trānsigō) trānsigere (< agere)","headword":"trānsigere","letter":"t","pos":"","posGroup":"other","english":"carry through, finish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transigo","latin":"transigo, transigere, transegi, transactus","headword":"transigo","letter":"t","pos":"verb","posGroup":"verb","english":"stab, pierce; finish, settle, complete, accomplish; perform; bargain, transact","forms":["trānsācta","trānsāctum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ille grātiās Rōmānīs ēgit, auxilia nōn accēpit; iam enim fuerat pugna {{trānsācta}}.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transilio","latin":"transilio, transilire, transilui, -","headword":"transilio","letter":"t","pos":"verb","posGroup":"verb","english":"jump across, leap over","forms":["transiliet","transiluit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Remus vērō, cum hoc moleste ferret, opus frātris dērīdēns novōs {{transiluit}} mūrōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transilire","latin":"(trānsiliō) trānsilīre, -iluisse, -ītum","headword":"trānsilīre","letter":"t","pos":"","posGroup":"other","english":"jump over","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transire","latin":"(trānseō) trānsīre, trānsīvisse","headword":"trānsīre","letter":"t","pos":"verb","posGroup":"verb","english":"cross, pass; to cross; to go across, pass over, cross","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"transitio","latin":"trānsitiō, -ōnis ( f.) (< trānsīre)","headword":"trānsitiō","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"crossing over, defection; going over, desertion","forms":["trānsitiō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Octāviī prōnūntiātum est per praecōnem 'rēgiōs puerōs Macedonāsque aliōs quī Samothrācae essent, sī transīrent ad Rōmānōs, incolumitātem lībertātemque et sua omnia servātūrōs quae aut sēcum habērent aut in Macedoniā relīquissent.' Ad hanc vōcem trānsitiō omnium facta est, nōminaque dabant ad C.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transitus","latin":"trānsitus, -ūs","headword":"trānsitus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"crossing, passage","forms":["transitu","trānsitum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is cum animadvertisset perpetuam esse paludem quae influeret in Sequanam atque illum omnem locum magnopere impediret, hic consedit nostrosque {{transitu}} prohibere instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"translato","latin":"translato, translatare, translatavi, translatatus","headword":"translato","letter":"t","pos":"verb","posGroup":"verb","english":"offer; transfer","forms":["trānslātō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tum lituō in laevam manum trānslātō, dextrā in caput Numae impositā, ita precātus est: \"Iuppiter pater, sī est fās hunc Numam Pompilium, cuius ego caput teneō, rēgem Rōmae esse, utī tū signa nōbīs certa dēclārēs inter eōs fīnēs quōs fēcī!\" Tum auspiciīs missīs dēclārātus rēx Numa dē templō dēscendit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transmarinus","latin":"trānsmarīnus, -a, -um","headword":"trānsmarīnus","letter":"t","pos":"adjective","posGroup":"adjective","english":"from beyond the seas; from across the sea, overseas","forms":["trānsmarīnō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is mox ad Italiam vēnit, tumque prīmum Rōmānī cum trānsmarīnō hoste dīmicāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transmittere","latin":"(trānsmittō) trānsmittere (< mittere)","headword":"trānsmittere","letter":"t","pos":"","posGroup":"other","english":"send over, cross","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transmitto","latin":"transmitto, transmittere, transmisi, transmissus","headword":"transmitto","letter":"t","pos":"verb","posGroup":"verb","english":"send across; go across; transmit","forms":["trānsmīsit","trānsmittere","transmittitur","trānsmittunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eo cum esset ventum, exploratores hostium, ut omni fluminis parte erant dispositi, inopinantes, quod magna subito erat coorta tempestas, ab nostris opprimuntur; exercitus equitatusque equitibus Romanis administrantibus quos ei negotio praefecerat celeriter {{transmittitur}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transno","latin":"transno, transnare, transnavi, transnatus","headword":"transno","letter":"t","pos":"verb","posGroup":"verb","english":"swim across, sail across; swim to the other side","forms":["trānsnābimus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Per Stygā détur iter, Stygiās {{trānsnābimus}} undās!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"transportare","latin":"(trānsportō) trānsportāre","headword":"trānsportāre","letter":"t","pos":"","posGroup":"other","english":"carry across, transport","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transporto","latin":"trānsportō, -āre, -āvī, -ātum","headword":"trānsportō","letter":"t","pos":"verb","posGroup":"verb","english":"transport, carry","forms":["trānsportandō","transportantur","transportārētur","transportari","trānsportātae","transportati","trānsportāverat","trānsportāvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Uno fere tempore sub lucem hostibus nuntiatur in castris Romanorum praeter consuetudinem tumultuari et magnum ire agmen adverso flumine sonitumque remorum in eadem parte exaudiri et paulo infra milites navibus {{transportari}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"transtrum","latin":"transtrum, transtri","headword":"transtrum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"crossbeam; rower's seat","forms":["trānstrīs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"praecipitīs: 'vigilāte, virī, et cōnsīdite {{trānstrīs}};","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"transvehere","latin":"(trānsvehō) trānsvehere (< vehere)","headword":"trānsvehere","letter":"t","pos":"","posGroup":"other","english":"carry (pass. sail) across","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"transveho","latin":"transveho, transvehere, transvexi, transvectus","headword":"transveho","letter":"t","pos":"verb","posGroup":"verb","english":"transport, lead across; elapse; carry","forms":["trānsvectus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō in Hispāniā cum Poenīs dēbellāvit quārtō decimō annō eius bellī; et ā Tarracōne in Āfricam ad Syphācem, rēgem Massȳlōrum, {{trānsvectus}}, foedus cum eō iūnxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"transversus","latin":"trānsversus, -a, -um","headword":"trānsversus","letter":"t","pos":"adjective","posGroup":"adjective","english":"placed crosswise","forms":["trānsversōs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vidēs habitārī in terrā rārīs et angustīs in locīs et in ipsīs quasi maculīs ubi habitātur vāstās sōlitūdinēs interiectās, eōsque quī incolunt terram nōn modo interruptōs ita esse ut nihil inter ipsōs ab aliīs ad aliōs mānāre possit, sed partim oblīquōs, partim {{trānsversōs}}, partim etiam adversōs stāre vōbīs — ā quibus exspectāre glōriam certē nūllam potestis!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"travectio","latin":"travectio, travectionis","headword":"travectio","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"crossing","forms":["trāvectiō"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dīc, quaesō: num tē illa terrent: triceps apud īnferōs Cerberus, Cocytī fremitus, trāvectiō Acherontis, ...","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"trecent","latin":"trecent","headword":"trecent","letter":"t","pos":"numeral","posGroup":"numeral","english":"three hundred; (used to denote a large number)","forms":["trecenta","trecentārum","trecentās","trecentēsimō","trecentēsimum","trecentī","trecentiēs","trecentīs","trecentōs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Tamen Deus dīxit Gedeōnī: “Nōn opus est tibi tot mīlibus hominum: dīmissīs cēterīs, retinē tantum {{trecentōs}} virōs, nē victōriam suae virtūtī tribuant, sed potentiae dīvīnae.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"trecentesimus","latin":"trecentēsimus, -a, -um","headword":"trecentēsimus","letter":"t","pos":"","posGroup":"other","english":"three hundredth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"trecenti","latin":"trecentī, -ae, -a","headword":"trecentī","letter":"t","pos":"","posGroup":"other","english":"three hundred","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"tredecim","latin":"trēdecim","headword":"trēdecim","letter":"t","pos":"numeral","posGroup":"numeral","english":"thirteen","forms":["trēdecim"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Iūlia lacrimam dētergēns ab ūndecim numerāre incipit: “Ūndecim, duodecim, {{trēdecim}}, quattuordecim...” Hīc puella numerāre dēsinit atque “Cēterōs” inquit “numerōs nesciō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tremere","latin":"(tremō) tremere, tremuisse","headword":"tremere","letter":"t","pos":"verb","posGroup":"verb","english":"tremble; to tremble","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tremesco","latin":"tremesco, tremescere, -, -","headword":"tremesco","letter":"t","pos":"verb","posGroup":"verb","english":"tremble, quiver, vibrate; tremble at","forms":["tremēscere"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"\"Nox,\" ait, \"fīdissima, et stellae aureae et lūna et tū, Hecatē triformis, quae meās artēs magicās carminibus tuīs iuvās, auxiliō vestrō ventōs vocō et nūbēs moveō; serpentēs superō et saxa silvāsque moveō; montēs {{tremēscere}} et mānēs ex sepulcrīs exīre iubeō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tremis","latin":"tremis, tremissis","headword":"tremis","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"coin; third part of gold aureus","forms":["tremis"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Iānitor eum tremere animadvertit iterumque dērīdet: \"Quid {{tremis}}?","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"tremisco","latin":"tremisco, tremiscere, -, -","headword":"tremisco","letter":"t","pos":"verb","posGroup":"verb","english":"tremble, quiver, vibrate; tremble at; (tremescere)","forms":["tremīscēns"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Perque diēs multōs latitāns omnemque {{tremīscēns}}\nad strepitum mortemque timēns cupidusque morīrī,\nglande famem pellēns et mixtā frondibus herbā\nhanc procul adspexī longō post tempore nāvem\nōrāvīque fugam gestū ad lītusque cucurrī,\net mōvī: Graiumque ratis Trōiāna recēpit.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tremo","latin":"tremo, tremere, tremui, -","headword":"tremo","letter":"t","pos":"verb","posGroup":"verb","english":"tremble, shake, shudder at","forms":["Tremēbat","tremēns","trementem","trementēs","trementia","trementīs","tremere","tremeret","tremit","tremō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Puella {{tremēns}} atque horrēns oculōs claudit, deinde sē vertit ac pontem relinquit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tremulus","latin":"tremulus, -a, -um","headword":"tremulus","letter":"t","pos":"adjective","posGroup":"adjective","english":"trembling, shaking","forms":["tremulā","tremulae","tremulus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sed harundinēs {{tremulae}}, quae ex terrā crēscunt, verba humāta remittunt, quia ventō mōtae fābulam dē auribus asellī murmurant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"trepidans","latin":"trepidans, trepidantis (gen.), trepidantior -or -us, trepidantissimus -a -um","headword":"trepidans","letter":"t","pos":"adjective","posGroup":"adjective","english":"trembling, anxious; panicking","forms":["trepidāns","trepidante","trepidantēs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Deinde tellūs tremit et ipse rēx, Plūtō, terret nē, terrā fissā, lūx in rēgnum tenebrōsum perveniat et {{trepidantēs}} umbrās terreat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"trepidare","latin":"(trepidō) trepidāre","headword":"trepidāre","letter":"t","pos":"","posGroup":"other","english":"be in panic, tremble","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"trepidatio","latin":"trepidātiō, -ōnis ( f.)","headword":"trepidātiō","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"alarm, panic; panic, alarm","forms":["trepidātiō","trepidātiōne"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tullus equitem clārā increpāns vōce, ut hostēs exaudīrent, redīre in proelium iubet: nihil {{trepidātiōne}} opus esse; ut suō iussū circumdūcī Albānum exercitum, ut Fīdēnātium nūda terga invādat!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"trepido","latin":"trepido, trepidare, trepidavi, trepidatus","headword":"trepido","letter":"t","pos":"verb","posGroup":"verb","english":"tremble, be afraid, waver","forms":["trepidāre","trepidārent","trepident","trepidō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ille quidem tōtam gemebundus obambulat Aetnam\npraetemptatque manū silvās et lūminis orbus\nrūpibus incursat foedātaque bracchia tābō\nin mare prōtendēns gentem exsecrātur Achīvam\natque ait: \"Ō sī quis referat mihi cāsus Ulixēn,\naut aliquem ē sociīs, in quem mea saeviat īra,\nvīscera cuius edam, cuius vīventia dextrā\nmembra meā laniem, cuius mihi sanguis inundet\nguttur, et ēlīsī {{trepident}} sub dentibus artūs.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"trepidus","latin":"trepidus, -a, -um","headword":"trepidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"alarmed, in panic; alarmed, trembling","forms":["trepida","trepidae","trepidī","trepidōs","trepidus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Stābat populus prae metū {{trepidus}} ad rādīcēs montis fūmantis.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tres","latin":"trēs","headword":"trēs","letter":"t","pos":"numeral","posGroup":"numeral","english":"three","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tresvir","latin":"tresvir, tresviri","headword":"tresvir","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"board of three (pl.)","forms":["trēsvirōs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Postquam, ut dīxī, senātus in Catōnis sententiam discessit, cōnsul optimum factū ratus noctem quae īnstābat antecapere, nē quid eō spatiō novārētur, {{trēsvirōs}} quae ad supplicium postulābantur parāre iubet; ipse, praesidiīs dispositīs, Lentulum in Carcerem dēdūcit; īdem fit cēterīs per praetōrēs.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"treverus","latin":"Treverus, Treveri","headword":"Treverus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Treveri, German tribe around Trier (Treves)","forms":["Treveri"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Ab hoc concilio Remi, Lingones, {{Treveri}} afuerunt; illi, quod amicitiam Romanorum sequebantur; Treveri, quod aberant longius et ab Germanis premebantur, quae fuit causa quare toto abessent bello et neutris auxilia mitterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tria","latin":"tria","headword":"tria","letter":"t","pos":"numeral","posGroup":"numeral","english":"three (neut.)","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tribrachysos","latin":"tribrachysos, tribrachyei","headword":"tribrachysos","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tribrach; metric foot of three short syllables (UUU)","forms":["tribrachys"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: iambus u —, trochaeus — u, anapaestus u u —, dactylus — u u, spondēus — —, {{tribrachys}} u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"tribuere","latin":"(tribuō) tribuere, -uisse, -ūtum","headword":"tribuere","letter":"t","pos":"","posGroup":"other","english":"grant, attribute","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tribunal","latin":"tribūnal, -ālis (n.)","headword":"tribūnal","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"dais, platform; raised platform, tribunal","forms":["tribūnal","tribūnālī"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In dē- mentô levātum in {{tribūnal}} excelsum Mercurius rapiēbat. cornū abundantī et très Parcae aurea pēnsa torquentēs.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"tribunatus","latin":"tribūnātus, -ūs","headword":"tribūnātus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"office of tribune","forms":["tribūnātū","tribūnātūs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Et continuātō in alterum annum tribūnātū, lēgibus agrāriīs lātīs effēcit ut complūrēs colōniae in Italiā dēdūcerentur et ūna in solō dīrutae Carthāginis, quō ipse triumvir creātus colōniam dēdūxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tribunus","latin":"tribūnus, -ī","headword":"tribūnus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tribune","forms":["tribūnī","tribunis","tribūnō","tribūnōrum","tribūnōs","tribunum","tribūnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Aristium, {{tribunum}} militum, iter ad legionem facientem fide data ex oppido Cabillono educunt; idem facere cogunt eos qui negotiandi causa ibi constiterant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tribunus militum","latin":"tribūnus mīlitum","headword":"tribūnus mīlitum","letter":"t","pos":"","posGroup":"other","english":"tribune of the military","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tribunus plebis","latin":"tribūnus plēbis","headword":"tribūnus plēbis","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tribune of the people; tribune of the plebs","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"tribuo","latin":"tribuo, tribuere, tribui, tributus","headword":"tribuo","letter":"t","pos":"verb","posGroup":"verb","english":"divide, assign; present; grant, allot, bestow, attribute","forms":["tribuant","tribue","tribuenda","tribuendum","tribuere","tribuerent","tribuerit","tribuētis","tribuisset","tribuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Esse non nullo se Caesaris beneficio adfectum, sic tamen ut iustissimam apud eum causam obtinuerit; sed plus communi libertati {{tribuere}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tribus","latin":"tribus, -ūs ( f.)","headword":"tribus","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tribe (division of citizens); tribe, territorial division","forms":["tribū","tribubus","tribus","tribuum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ipse post paulo silentio egressus cum {{tribus}} legionibus eum locum petit quo naves appelli iusserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tributum","latin":"tribūtum, -ī","headword":"tribūtum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"tax; tribute, tax","forms":["tribūta","tribūtum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Deversī in patriam IUdaeī, compositō urbis stātiī, nōn iam egēs habuēre, sed imperium penes pontificēs fuit: {{tribūta}} tamen pēnsitārunt prīmum Persīs, deinde Graecīs, post dēvictum ab Alexandra Darīum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tributus","latin":"tributus, tributa, tributum","headword":"tributus","letter":"t","pos":"adjective","posGroup":"adjective","english":"organized by tribes","forms":["tribūtam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"'Cum pateat igitur aeternum id esse quod ā sē ipsō moveātur, quis est quī hanc nātūram animīs esse {{tribūtam}} neget?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tricesimus","latin":"trīcēsimus, -a, -um","headword":"trīcēsimus","letter":"t","pos":"","posGroup":"other","english":"30th","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"triclinium","latin":"triclīnium, -ī","headword":"triclīnium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"dining room","forms":["trīclīniō","trīclīnium"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum dēmum Iuppiter domum cum puerō reversus est, eī ministrī opus dēdit, ut semper in trīclīniō, inter deōrum convīvia, vīnum aquae mixtum sibi hospitibusque suīs in pōcula funderet.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"tridens","latin":"tridēns, -entis (m.)","headword":"tridēns","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"trident","forms":["tridente","tridentem","tridentī"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Sine morā inter sē certāre coepērunt: Minerva deōrum rēs gestās acū pīnxit: praeter cēterās ante oculōs appārēbat Iovis rēgis imāgō, apud quem Minerva Neptūnum stantem fēcit, quī {{tridentem}} manū gerēbat; deinde sē ipsam, indūtam clipeō et acūtam hastam gestantem, multōsque aliōs deōs pmxit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"triduum","latin":"trīduum, -ī","headword":"trīduum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"three days","forms":["triduo","trīduum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige usu ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius {{triduo}} ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"triennium","latin":"triennium, -ī","headword":"triennium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"three years; period of three years","forms":["trienniō","triennium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praesūmpsērunt tamen tribūnī mīlitēs cōnsulārī potestāte iterum dignitātem, et {{triennium}} perseverāvērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"triens","latin":"triēns, -entis (m.)","headword":"triēns","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"third of an as; a third (of an as)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"trietericum","latin":"trietericum, trieterici","headword":"trietericum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"triennial (alternate year) rites (pl.) of Bacchus held at Thebes","forms":["trietērica"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Thȳias, ubi audītō stimulant {{trietērica}} Bacchō","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"triformis","latin":"triformis, triformis, triforme","headword":"triformis","letter":"t","pos":"adjective","posGroup":"adjective","english":"of three forms, triple, threefold","forms":["trīfōrmis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Servātus, prōmissa det et servet!\" Hic per sacra Hecatēs {{trīfōrmis}} deae iūrāvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"trigeminus","latin":"trigeminus, -a, -um","headword":"trigeminus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"triplet","forms":["trigemina","trigeminī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Forte in duōbus tum exercitibus erant trigeminī frātrēs, Horātiī Curiātīque, nec aetāte nec vīribus disparēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"triginta","latin":"trīgintā","headword":"trīgintā","letter":"t","pos":"numeral","posGroup":"numeral","english":"thirty","forms":["trīcēsima","trīcēsimō","trīcēsimum","trīgintā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iōsēphus erat trīgintā annōs nātū, cum summam potestātem ā rēge accēpit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"trigon","latin":"trigon, trigonis","headword":"trigon","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"ball game with three players in triangle (in baths); ball for playing trigon","forms":["trigōnem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ast ubi mē fessum sōl ācrior īre lavātum admonuit, fugiō Campum lūsumque {{trigōnem}}.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"trimus","latin":"trimus, trima, trimum","headword":"trimus","letter":"t","pos":"adjective","posGroup":"adjective","english":"three, three years old","forms":["Trīma"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Itaque quotiēnscumque dîcit “Carpe!” eôdem verbô et [Dê Fortûnätä, dê dîvitiîs T rimalchiônis, dē collîbertîs] Nôn potuî amplius quicquam gustāre, sed conversus ad eum, ut quam plūrima exciperem, longē accersere täbulās coepî scîscitäxîque ‘quae esset mulier illa quae hūc atque “Uxor” inquit “Trīma1chiônis, ‘Fortūnāta’ appellättlr; quae nummôs modiô mëtîtur.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"trini","latin":"trīnī, -ae, -a","headword":"trīnī","letter":"t","pos":"adjective","posGroup":"adjective","english":"three at a time; three each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"trinus","latin":"trinus, trina, trinum","headword":"trinus","letter":"t","pos":"adjective","posGroup":"adjective","english":"triple","forms":["trīnās","trinis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Milites dato signo celeriter ad munitionem perveniunt eamque transgressi {{trinis}} castris potiuntur; ac tanta fuit in castris capiendis celeritas ut Teutomatus, rex Nitiobrigum, subito in tabernaculo oppressus, ut meridie conquieverat, superiore corporis parte nudata, vulnerato equo vix se ex manibus praedantium militum eriperet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"trio","latin":"Trio, Trionis","headword":"Trio","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"oxen (pl.) used for plowing; constellations Great/Little Bear (7 stars/oxen)","forms":["Triōnēs"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Arctūrum pluviāsque Hyadas geminōsque {{Triōnēs}};","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"tripertito","latin":"tripertito","headword":"tripertito","letter":"t","pos":"adverb","posGroup":"adverb","english":"in three parts","forms":["tripertito"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Qua re nuntiata Caesar suum quoque equitatum {{tripertito}} divisum contra hostem ire iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"triplex","latin":"triplex, (gen.), triplicis","headword":"triplex","letter":"t","pos":"adjective","posGroup":"adjective","english":"threefold, triple; three","forms":["triplicem"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Platō {{triplicem}} fīnxit animum, cuius principātum, id est ratiōnem, in capite sīcut in arce posuit, et duās partēs eī pārēre voluit, īram et cupiditātem, quās suīs locīs, īram in pectore, cupiditātem subter praecordia locāvit.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"triremis","latin":"trirēmis, -e","headword":"trirēmis","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"having three banks of oars; ( f.) ship with three banks of oars","forms":["trirēmis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ecce classis Graecōrum, birēmis, {{trirēmis}}; servī remōs dūcentēs; ducēs ventum secundum spērantēs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"triste","latin":"triste","headword":"triste","letter":"t","pos":"adverb","posGroup":"adverb","english":"sadly, sorrowfully; harshly, severely","forms":["triste"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"At sī quōs tamen ultima nostrī verba movent ōris (Prīamī vōs fīlia rēgis, nōn captīva rogat), genetricī corpus inemptum reddite, nēve aurō redimat iūs {{triste}} sepulcrī, sed lacrimīs! tunc, cum poterat, redimēbat et aurō.” Dīxerat, at populus lacrimās, quās illa tenēbat, nōn tenet; ipse etiam flēns invītusque sacerdōs virginis ferrum in pectore condit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tristis","latin":"trīstis, -e","headword":"trīstis","letter":"t","pos":"adjective","posGroup":"adjective","english":"sad; sad, gloomy","forms":["trīstem","trīstēs","trīstī","trīstia","trīstis"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlia: “Nōn canō, quia {{trīstis}} sum.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tristitia","latin":"trīstitia, -ae","headword":"trīstitia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"sadness","forms":["trīstitia"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tanta tamen erat eōrum laetitia, tam grātae omnibus illae nūptiae, tam multae omnium laudēs, ut Aristaeus, pāstor quī iam anteā Eurydicēn amāverat, nōn sōlum {{trīstitia}}, vērum etiam magna invidia afficerētur, cum sē nihil iam ex virgine spērāre posse vidēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"triticum","latin":"trīticum, -ī","headword":"trīticum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"wheat","forms":["trīticī","trīticō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iōsēphus iussit frātrum saccōs implērī trīticō, et pecūniam quam attulerant repōnī in ōre saccōrum; addidit īnsuper cibāria in viam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"triumphalis","latin":"triumphālis, -e","headword":"triumphālis","letter":"t","pos":"adjective","posGroup":"adjective","english":"triumphal","forms":["triumphālī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In parte interiōre triumphus Titī dē Iūdaeīs imāginibus illūstrātur: ab alterā parte imperātor laurō ōrnātus curru triumphālī vectus vidētur, ab alterā mīlitēs candēlābrum et tubās Iūdaeōrum ferentēs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"triumphare","latin":"(triumphō) triumphāre","headword":"triumphāre","letter":"t","pos":"","posGroup":"other","english":"celebrate a triumph","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"triumpho","latin":"triumpho, triumphare, triumphavi, triumphatus","headword":"triumpho","letter":"t","pos":"verb","posGroup":"verb","english":"triumph over; celebrate a triumph; conquer completely, triumph","forms":["triumphāns","triumphantes","triumphārent","triumphātum","triumphāvī","triumphāvit","triumphō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ad hoc templum imperātor victor post triumphum ascendit, ut Iovī Optimō Maximō sacrificium faciat, dum ducēs hostium, quī in triumphō ante currum imperātōris ductī sunt, ad supplicium trāduntur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"triumphus","latin":"triumphus, ī","headword":"triumphus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"triumph; triumph, triumphal procession","forms":["triumphī","triumphīs","triumphōs","triumphum","triumphus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"ē Ē [{{Triumphus}}]","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"triumvir","latin":"triumvir, -ī","headword":"triumvir","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"one of three commissioners","forms":["triumvir","triumvirī","triumvirīs","triumvirōs","triumvirum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Gracchum frātrem et Appium Claudium socerum {{triumvirōs}} ad dīvidendum agrum creāret.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"triumviralis","latin":"triumvirālis, -e","headword":"triumvirālis","letter":"t","pos":"adjective","posGroup":"adjective","english":"of the triumvirs","forms":["triumvirālēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dēfūnctō eō, ācrius sēditiōnēs {{triumvirālēs}} exārsērunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"trivium","latin":"trivium, trivi(i)","headword":"trivium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"place where three roads meet; \"the gutter\", breeding place of course manners","forms":["triviīs"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tempora quaeram, occurram in {{triviīs}}, dēdūcam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"trochaeus","latin":"trochaeus, -ī","headword":"trochaeus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"trochee","forms":["trochaeōs","trochaeus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Versūs in pedēs dīviduntur, quibus nōmina sunt: iambus u —, {{trochaeus}} — u, anapaestus u u —, dactylus — u u, spondēus — —, tribrachys u u u.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"troezen","latin":"Troezēn, -ēnis","headword":"Troezēn","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Troezen, a city in Argolis","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"troia","latin":"Troia, Troiae","headword":"Troia","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Troy; (ancient city in Asia Minor, homeland of Aeneas)","forms":["Trōiā","Troiae","Trōiam"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fuit ōlim in urbe Trōiā puer pulcherrimus, nōmine Ganymēdēs, nōbilissimīs parentibus nātus, quī tamen pāstōris opus facere solēbat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"troianus","latin":"Troianus, Troiana, Troianum","headword":"Troianus","letter":"t","pos":"adjective","posGroup":"adjective","english":"Trojan; of/from Troy","forms":["Trōiāna","Trōiānae","Troiānam","Trōiānās","Trōiāne","Troiānī","Trōiānīs","Troiānō","Troiānōrum","Trōiānōs","Troiānum","Troiānus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cotīdiē igitur sub urbe in campīs et in silvīs, quamquam fīlius {{Troiānōrum}} rēgis erat, cum ovibus errābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"trucidare","latin":"(trucīdō) trucīdāre","headword":"trucīdāre","letter":"t","pos":"","posGroup":"other","english":"slaughter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"trucido","latin":"trucido, trucidare, trucidavi, trucidatus","headword":"trucido","letter":"t","pos":"verb","posGroup":"verb","english":"slaughter, butcher, massacre","forms":["trucīdābantur","trucīdant","trucīdārent","trucīdārī","trucīdātōs","trucīdātum","trucīdāvērunt","trucīdāvistī","trucīdēminī","trucīdentur"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Dēnique Saūl mīsit satellitēs, quī Davidem domī in oculīs uxōris {{trucīdārent}}; haec vērō marītum dēmīsit per fenestram, atque ita ēripuit perīculō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"trunco","latin":"trunco, truncare, truncavi, truncatus","headword":"trunco","letter":"t","pos":"verb","posGroup":"verb","english":"maim, mutilate; strip of branches, foliage; cut off","forms":["truncō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Dīxit et aurō\nfulgentem rāmum silvā Iūnōnis Avernae\nmōnstrāvit iussitque suō dīvellere truncō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"truncus","latin":"truncus, -ī","headword":"truncus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"trunk, stem","forms":["truncis","truncum","truncus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Itaque {{truncis}} arborum aut admodum firmis ramis abscisis atque horum delibratis ac praeacutis cacuminibus perpetuae fossae quinos pedes altae ducebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"trux","latin":"trux (gen. trucis)","headword":"trux","letter":"t","pos":"adjective","posGroup":"adjective","english":"savage, grim; savage, grim, fierce","forms":["trucēs","trucī","trucis","trux"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"- {{trux}} trucis adī — ferōx, saevus Blandā truc&s animōs fertur","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tu","latin":"tū","headword":"tū","letter":"t","pos":"pronoun","posGroup":"pronoun","english":"you, yourself; you (sing.)","forms":["tē","tēd","tibi","tis","tū","tuī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Num cēterī servī Cornēliī tuī servī sunt?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tuba","latin":"tuba, -ae","headword":"tuba","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"trumpet","forms":["tuba","tubae","tubārum","tubās","tubīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono {{tubae}}, quod satis magna valles intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tubero","latin":"Tubero, Tuberonis","headword":"Tubero","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Tuber (surname of gens Aelia)","forms":["Tubērō","Tubērōnem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aelium {{Tubērōnem}} obviam rēgī mīsit, cēterōs manēre in praetōriō frequentēs iussit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tubicen","latin":"tubicen, -inis (m.)","headword":"tubicen","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"trumpeter","forms":["tubicen","tubicine","tubicinēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam stābant aciēs ferrō mortīque parātae, iam lituō {{tubicen}} signa datūrus erat, cum raptae veniunt inter patrēsque virōsque, inque sinū nātōs, pignora cāra, ferunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tueor","latin":"tueor, tuērī, tūtus sum","headword":"tueor","letter":"t","pos":"verb","posGroup":"verb","english":"protect, guard; to protect, defend","forms":["tueantur","tueāris","tueātur","tuēbantur","tūēbitur","tuendā","tuendam","tuendi","tuendō","tuentem","tuentur","tuērentur","tuērētur","tuerī","tuētur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui tum primum allato nuntio de oppugnatione Vellaunoduni, cum longius eam rem ductum iri existimarent, praesidium Cenabi {{tuendi}} causa quod eo mitterent comparabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tueri","latin":"(tueor) tuērī, tuitum","headword":"tuērī","letter":"t","pos":"verb","posGroup":"verb","english":"and tūtumsee, watch, protect; to protect, guard","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"tugurium","latin":"tugurium, -ī","headword":"tugurium","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"hut, cottage","forms":["tuguriō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quī postquam in aedēs irrūpēre, dīversī rēgem quaerere, dormientēs aliōs, aliōs occurrentēs interficere, scrūtārī loca abdita, clausa effringere, strepitū et tumultū omnia miscēre — cum interim Hiempsal reperītur occultāns sē tuguriō mulieris ancillae, quō initiō pavidus et ignārus locī perfūgerat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tullianum","latin":"tullianum, tulliani","headword":"tullianum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"underground execution chamber in prison of Rome; (built by Servus Tullius?)","forms":["Tulliānō","Tulliānum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Prope aedem Concordiae est Carcer, cuius pars subterrānea, tenebrīs et odōre foeda atque terribilis, {{Tulliānum}} appellātur; multī hostēs Rōmānōrum in Tulliānō suppliciō affectī sunt.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tullius","latin":"Tullius, Tulli","headword":"Tullius","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Tullius; (Roman gens name); M. Tullius Cicero, orator","forms":["Tullī","Tullia","Tulliae","Tulliī","Tulliō","Tullium","Tullius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Tullium}} Ciceronem et P.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tum","latin":"tum","headword":"tum","letter":"t","pos":"adverb","posGroup":"adverb","english":"then; then, at that time","forms":["tum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Tum}}, collaudatis Carnutibus, dato iure iurando ab omnibus qui aderant, tempore eius rei constituto ab concilio disceditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tumeo","latin":"tumeo, tumere, -, -","headword":"tumeo","letter":"t","pos":"verb","posGroup":"verb","english":"swell, become inflated; be puffed up; be bombastic; be swollen with conceit","forms":["tumēbat","tument","tumēre","tumet"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quae simul ārentī sitientēs hausimus ōre,\net tetigit summōs virgā dea dīra capillōs,\n(et pudet et referam) saetīs horrēscere coepī\nnec iam posse loquī, prō verbīs ēdere raucum\nmurmur et in terram tōtō prōcumbere vultū,\nōsque meum sēnsī tum magnō crēscere rōstrō,\ncolla {{tumēre}} torīs, et quā modo pōcula parte\nsumpta mihi fuerant, illā vestīgia fēcī;","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tumere","latin":"(tumeō) tumēre, -uisse, -itum","headword":"tumēre","letter":"t","pos":"","posGroup":"other","english":"swell","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tumidus","latin":"tumidus, -a, -um","headword":"tumidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"swollen; swollen, surging","forms":["tumida","tumidam","tumidum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"bam (superbia {{tumidam}}) facere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tumulo","latin":"tumulo, tumulare, tumulavi, tumulatus","headword":"tumulo","letter":"t","pos":"verb","posGroup":"verb","english":"cover with a burial mound","forms":["tumulō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Pōnite in hōc tumulō ūnō nōs, quōs amor coniūnxit, quōs ūna hōra coniūnxit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tumulosus","latin":"tumulōsus, -a, -um","headword":"tumulōsus","letter":"t","pos":"adjective","posGroup":"adjective","english":"hilly","forms":["tumulōsum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dein tertiā, multō ante lūcis adventum, pervenit in locum {{tumulōsum}} ab Capsā nōn amplius duum mīlium intervāllō, ibique quam occultissimē potest cum omnibus cōpiīs opperītur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tumultuari","latin":"(tumultuor) tumultuārī, tumultuātum","headword":"tumultuārī","letter":"t","pos":"","posGroup":"other","english":"make an uproar","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"tumultuarius","latin":"tumultuārius, -a, -um","headword":"tumultuārius","letter":"t","pos":"adjective","posGroup":"adjective","english":"hurried, disorderly","forms":["tumultuāriīs","tumultuāriō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quibus {{tumultuāriīs}} certāminibus haud fermē plūrēs Saguntīnī cadēbant quam Poenī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tumultuo","latin":"tumultuo, tumultuare, tumultuavi, tumultuatus","headword":"tumultuo","letter":"t","pos":"verb","posGroup":"verb","english":"make commotion/disturbance/uproar/armed rising; scrap/scrimmage; be confused","forms":["tumultuantem","tumultuari"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Uno fere tempore sub lucem hostibus nuntiatur in castris Romanorum praeter consuetudinem {{tumultuari}} et magnum ire agmen adverso flumine sonitumque remorum in eadem parte exaudiri et paulo infra milites navibus transportari.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tumultuosus","latin":"tumultuosus, tumultuosa -um, tumultuosior -or -us, tumultuosissimus -a -um","headword":"tumultuosus","letter":"t","pos":"adjective","posGroup":"adjective","english":"turbulent, full of commotion or uproar","forms":["tumultuosius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Imperat his ut paulo {{tumultuosius}} omnibus locis pervagentur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tumultus","latin":"tumultus, -ūs","headword":"tumultus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"(m.) uproar","forms":["tumultu","tumultum","tumultus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum vero ex omnibus urbis partibus orto clamore, qui longius aberant repentino {{tumultu}} perterriti, cum hostem intra portas esse existimarent, sese ex oppido eiecerunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tumulus","latin":"tumulus, -ī","headword":"tumulus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"grave, mound; mound, grave","forms":["tumulīs","tumulōs","tumulum","tumulus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum relīquerint domōs et oppidum, ad {{tumulum}} Nīnī sub arborem convenient.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tunc","latin":"tunc","headword":"tunc","letter":"t","pos":"adverb","posGroup":"adverb","english":"then","forms":["tunc"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Tunc}} Eliezer prōgressus obviam puellae: dā, inquit, pōtum mihi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tundo","latin":"tundo, tundere, tutudi, tunsus","headword":"tundo","letter":"t","pos":"verb","posGroup":"verb","english":"beat; bruise, pulp, crush","forms":["tundēns","tundere","tūnsae","tūnsum","tūsum","tutudisse"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iamque iterum {{tundēns}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tunica","latin":"tunica, -ae","headword":"tunica","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tunic","forms":["tunicā","tunicam","tunicārum","tunicās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cui māter suā certīs temporibus afferēbat parvam {{tunicam}}, quam ipsa cōnfēcerat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tunicatus","latin":"tunicatus, tunicata, tunicatum","headword":"tunicatus","letter":"t","pos":"adjective","posGroup":"adjective","english":"clothed in a tunic","forms":["tunicāta","tunicātus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ad-stāre -stitisse; s; adstiterit Adstiterit {{tunicāta}}: \"Movēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tuor","latin":"tuor, tuari, -","headword":"tuor","letter":"t","pos":"verb","posGroup":"verb","english":"see, look at; protect, watch; uphold; (form of tueor)","forms":["tuor"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Iam quat- {{tuor}} partēs dîcit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"turba","latin":"turba, -ae","headword":"turba","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"crowd","forms":["turba","turbae","turbam","turbās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās concussit, et {{turba}} omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn inultus occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"turbido","latin":"turbido, turbidare, turbidavi, turbidatus","headword":"turbido","letter":"t","pos":"verb","posGroup":"verb","english":"disturb/trouble/agitate; make turbulent/turbid; obscure, make turmoil/confusion","forms":["turbidō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nautae nec marī turbidō nec marī tranquillō nāvigāre possunt; itaque in portū ventum secundum opperiuntur. (Ventus secundus est ventus quī ā tergō flat.) Ventō secundō nāvēs ē portū ēgrediuntur: vēla ventō implentur ac nāvēs plēnīs vēlīs per mare vehuntur.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"turbidus","latin":"turbidus, -a, -um","headword":"turbidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"agitated, stormy; rough, disturbed","forms":["turbida","turbidae","turbidum","turbidus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Cum vēro ōlim Arethūsa, postquam diū per silvāsas cucurrerat, domum sōia redīret, ad rapidum fluvium pervēnit, cuius frīgidae aquae, nūllō modō {{turbidae}} ac percussae radiīs sōlis, quī in mediō caelō sine nūbibus fulgēbat, ita illūstrābantur ut nympha ipsōs calculōs in īmō flūmine iacentēs cemere posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"turbo","latin":"turbō, turbāre","headword":"turbō","letter":"t","pos":"verb","posGroup":"verb","english":"stir up, agitate","forms":["turbandam","turbant","turbāre","turbārent","turbāret","turbārī","turbat","turbāta","turbātae","turbātās","turbātī","turbātō","turbātōs","turbātum","turbātur","turbātus","turbāvēre","turbāvērunt","turbāvī","turbāvistī","turbāvit","turbent","turbet","turbine","turbō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Madianītae, audītō tubārum sonitū et vīsīs lampadibus, turbātī sunt, et turpī fugā, quō quisque potuit, dīlāpsī sunt.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"turbulentus","latin":"turbulentus, turbulenta -um, turbulentior -or -us, turbulentissimus -a -um","headword":"turbulentus","letter":"t","pos":"adjective","posGroup":"adjective","english":"violently disturbed, stormy, turbulent; unruly, riotous; w/violent unrest","forms":["turbulenta","turbulentam"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Tunc fauce improbā latrō incitātus iūrgiī causam intulit: “Cūr” inquit “{{turbulentam}} fēcistī mihi aquam bibentī?” Lāniger contrā timēns: “Quī possum, quaesō, facere quod quereris, lupe?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"turgidulus","latin":"turgidulus, turgidula, turgidulum","headword":"turgidulus","letter":"t","pos":"adjective","posGroup":"adjective","english":"(poor little) swollen/inflated/inflamed/grandiose","forms":["turgiduli"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"flendo {{turgiduli}} rubent ocelli!\"","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"turgidus","latin":"turgid(ul)us, -a, -um","headword":"turgidus","letter":"t","pos":"adjective","posGroup":"adjective","english":"swollen; swollen, turgid","forms":["turgida","turgidi","turgido","turgidum"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qui, cum Quintus heri de alta arbore cecidisset, pedem eius {{turgidum}} vix tetigit, sed misello puero sanguinem misit!","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"turicremus","latin":"turicremus, turicrema, turicremum","headword":"turicremus","letter":"t","pos":"adjective","posGroup":"adjective","english":"burning incense","forms":["tūricremās","tūricremīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vīsite {{tūricremās}} vaccae Memphītīdōs àràs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"turma","latin":"turma, -ae","headword":"turma","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"squadron","forms":["turma","turmae","turmas","turmis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hac re cognita, Caesar mittit complures equitum {{turmas}} eo de media nocte.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"turmatim","latin":"turmatim","headword":"turmatim","letter":"t","pos":"adverb","posGroup":"adverb","english":"by squadrons, by troops; by turma (squadron of 30 horsemen)","forms":["turmātim"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō; deinde equitēs {{turmātim}} et cohortēs peditum.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"turnus","latin":"Turnus, Turni","headword":"Turnus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"Turnus; (king of the Rutulians, rival of Aeneas for Lavinia)","forms":["Turnī","Turnō","Turnum","Turnus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Bellum cum gente ferōcī\nsuscipitur, pactāque furit prō coniuge {{Turnus}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"turpe","latin":"turpe, turpius, turpissime","headword":"turpe","letter":"t","pos":"adverb","posGroup":"adverb","english":"repulsively, disgracefully, shamelessly; in an ugly/unsightly manner","forms":["turpe"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quis umquam tam {{turpe}} et inhūmānum scelus fēcit?” Cēterīs deīs sevērissimam poenam invocantibus, “Profectō maximō suppliciō afficiēris;” inquit deōrum pater, “ō Tantale, quod nisi factum erit, etiam hominēs nēquam, tē imitātī, tālia scelera committent; nec enim quidquam, nisi poena sevēra, huius generis hominēs ab iniūriīs et maleficiīs dēterrēre potest.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"turpis","latin":"turpis, turpe","headword":"turpis","letter":"t","pos":"adjective","posGroup":"adjective","english":"ugly, foul; ugly, shameful","forms":["turpem","turpēs","turpī","turpia","turpiōribus","turpis","turpissima","turpissimam","turpissimum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hic, summo in Arvernis ortus loco et magnae habitus auctoritatis, 'nihil', inquit, 'de eorum sententia dicturus sum, qui {{turpissimam}} servitutem deditionis nomine appellant, neque hos habendos civium loco neque ad concilium adhibendos censeo.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"turpissime","latin":"turpissime","headword":"turpissime","letter":"t","pos":"adverb","posGroup":"adverb","english":"basely; shamefully; uglily; (found in Patrologiae Graecae, 19th Cent)","forms":["turpissimē"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cāsū venit obvius illī adversārius, et “Quō tū, turpissimē?” magnā inclāmat vōce, et “Licet antestārī?” Ego vērō oppōnō auriculam.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"turpiter","latin":"turpiter","headword":"turpiter","letter":"t","pos":"adverb","posGroup":"adverb","english":"foully, shamefully","forms":["turpiter"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius indicio vocati, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi {{turpiter}} se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"turpitudo","latin":"turpitudo, turpitudinis","headword":"turpitudo","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"ugliness/deformity; shame/indecency; nakedness/genitals; disgrace; turpitude","forms":["turpitūdine","turpitūdinis"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae nota domesticae {{turpitūdinis}} nōn inusta vītae tuae est?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"turris","latin":"turris, -is ( f.) (acc. -im; abl. -ī)","headword":"turris","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"tower","forms":["turres","turrī","turribus","turrim","turris","turrium"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut supra diximus, angustum habebat, aggerem apparare, vineas agere, {{turres}} duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"turtur","latin":"turtur, turturis","headword":"turtur","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"turtle-dove","forms":["turtur","turturem"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"In marī ingēns {{turtur}} illōs dēvorābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tus","latin":"tus, turis","headword":"tus","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"frankincense","forms":["tūra","tūre","tūris","tūrum","tūs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Lātōna est dea fēminārum.” Itaque fēminae Thēbārum āram deae in templō ōrnant; ibi dōna deīs deābusque dant et {{tūra}} sanctīs flammīs dant.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tusculum","latin":"Tusculum, Tusculi","headword":"Tusculum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"Tusculum; town in Latium/Italy","forms":["Tūsculī","Tūsculō","Tūsculum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In oppidō Tūsculō magnum forum est.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tussis","latin":"tussis, tussis","headword":"tussis","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"cough","forms":["tussis"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Namque īnstat fātum mihi trīste, Sabellā quod puerō cecinit dīvīnā mōta anus urnā: Hunc neque dīra venēna nec hosticus auferet ēnsis, nec laterum dolor, aut {{tussis}}, nec tarda podagra.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"tutari","latin":"(tūtor) tūtārī","headword":"tūtārī","letter":"t","pos":"","posGroup":"other","english":"protect","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tute","latin":"tute","headword":"tute","letter":"t","pos":"adverb","posGroup":"adverb","english":"without risk/danger, safely, securely","forms":["tūtē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Frātrēs Iōsēphī respondērunt dispēnsātōrī: istud sceleris longē ā nōbīs aliēnum est; nōs, ut tūtē scīs, retulimus bonā fide pecūniam repertam in saccīs; tantum abest ut fūrātī sīmus scyphum dominī tuī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tuto","latin":"tūtō","headword":"tūtō","letter":"t","pos":"adverb","posGroup":"adverb","english":"safely","forms":["tūtantur","tūtārī","tūtāta","tūtātus","tuto"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Silentio noctis Caesar ex castris egressus, prius quam subsidio ex oppido veniri posset, deiecto praesidio, potitus loco duas ibi legiones collocavit fossamque duplicem duodenum pedum a maioribus castris ad minora perduxit, ut {{tuto}} ab repentino hostium incursu etiam singuli commeare possent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tutor","latin":"tūtor, -ōris (m.)","headword":"tūtor","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"guardian","forms":["tūtor","tūtōris"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Brevī Tarquinius cum Ancō rēge tam firmam amīcitiam iūnxit ut pūblicīs pariter ac prīvātīs cōnsiliīs bellō domīque interesset, et postrēmō {{tūtor}} etiam līberīs rēgis testāmentō īnstituerētur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tutum","latin":"-tūtum","headword":"tūtum","letter":"t","pos":"","posGroup":"other","english":"train, instruct","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"tutus","latin":"tūtus, -a, -um","headword":"tūtus","letter":"t","pos":"adjective","posGroup":"adjective","english":"safe","forms":["tuta","tūtae","tūtam","tūtī","tūtior","tūtissima","tūtissimus","tūtōs","tūtum","tūtus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praeterea oppida incendi oportere, quae non munitione et loci natura ab omni sint periculo {{tuta}}, neu suis sint ad detrectandam militiam receptacula neu Romanis proposita ad copiam commeatus praedamque tollendam.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"tuus","latin":"tuus, -a, -um","headword":"tuus","letter":"t","pos":"adjective","posGroup":"adjective","english":"your, yours; your (of one person)","forms":["tua","tuae","tuam","tuārum","tuās","tue","tuīs","tuō","tuōrum","tuōs","tuum","tuus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Libanus: “Quae est domina {{tua}}, Dēlia?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"tympanum","latin":"tympanum, -ī","headword":"tympanum","letter":"t","pos":"noun (n.)","posGroup":"noun","english":"tambourine, drum","forms":["tympana","tympanīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Hebraeī, grātulantēs, victōrem dēdūcunt ad urbem: ipsae mulierēs, domibus ēgressae, cum {{tympanīs}} laudēs eius canēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tyrannis","latin":"tyrannis, -idis","headword":"tyrannis","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"rule of a tyrant, tyranny","forms":["tyrannidem"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Iam deinde, tribūnīs mīlitum cōnsulārī imperiō rem pūblicam Rōmae regentibus, ad annum ferē conditae urbis trecentēsimum quadrāgēsimum septimum, trīgintā illī tyrannī praepositī sunt ā Lacedaemoniīs Athēniēnsibus, et in Siciliā Dionȳsius superior {{tyrannidem}} tenuit; paucīsque annīs post Sōcratēs Athēnīs capitis damnātus est et in carcere venēnō necātus.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"tyrannus","latin":"tyrannus, -ī","headword":"tyrannus","letter":"t","pos":"noun (m.)","posGroup":"noun","english":"tyrant","forms":["tyrannī","tyrannō","tyrannum","tyrannus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Illa irrīdēns crūdēlem {{tyrannum}}, sīc fīlium allocūta est:\"Miserēre, filī mī, miserēre mātris tuae, quae tē uterō gestavī, quae tē nātum lacte aluī: nolī ā fratēmā virtūte dēgenerāre; nōn timēre camificem istum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"tyrius","latin":"Tyrius, -a, -um","headword":"Tyrius","letter":"t","pos":"adjective","posGroup":"adjective","english":"Tyrian, of Tyre","forms":["Tyriā","Tyriam","Tyriās","Tyrīī","Tyriīs","Tyriō","Tyriōs","Tyrius"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eurōpa cum amīcīs {{Tyriīs}} lūdit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"tyros","latin":"Tyros, Tyri","headword":"Tyros","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Tyre; (city on the Phoenician coast)","forms":["Tyrōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tyrius -ā -um («€ {{Tyrōs}} -ī f, urbs Sy-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"tyrus","latin":"Tyrus, -ī","headword":"Tyrus","letter":"t","pos":"noun (f.)","posGroup":"noun","english":"Tyre","forms":["Tyrī","Tyrō","Tyrus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Est īnsula pulchra—{{Tyrus}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"uber","latin":"ūber, -eris","headword":"ūber","letter":"u","pos":"adjective","posGroup":"adjective","english":"fertile","forms":["ūbera","ūbere","ūberī","ūberibus","ūberiōre","ūberrima"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Arbor est mōrus, ūberrima pōmīs albīs, vīcīna fontī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"ubertas","latin":"ūbertās, -ātis ( f.)","headword":"ūbertās","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"fruitfulness","forms":["ūbertāte","ūbertātem","ūbertātis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Septem vaccae pinguēs et septem spīcae plēnae sunt septem annī ūbertātis mox ventūrae; septem vērō vaccae macilentae et septem spīcae exīlēs sunt totidem annī famis, quae ūbertātem secūtūra est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ubertim","latin":"ubertim","headword":"ubertim","letter":"u","pos":"adverb","posGroup":"adverb","english":"abundantly; copiously (weeping)","forms":["ūbertim"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"“Înscrîptiô quoque vidē dîligenter sī haec satis idônea HVIC SEVIRATVS ABSEN'Ī'Ī DECRETVS EST CVM POSSET IN OMNIBVS DECVRĪĪS RŌMAE ESSE PIVS FORTIS FIDĒLIS EX PARVŌ CRĒVIT SESTERTIVM RELIQVIT TRECENTIĒS NEC VMQVAM PHILOSOPHVM AVDĪVIT Haec ut dîxit Trimalchiô, ﬂëre coepit ūbertim.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"ubi","latin":"ubi?","headword":"ubi","letter":"u","pos":"adverb; conjunction","posGroup":"adverb","english":"interrog. adv. where; where?; where; when, while, where; where, when","forms":["ubi"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Ubi}} ea dies venit, Carnutes, Cotuato et Conconnetodumno ducibus, desperatis hominibus, Cenabum signo dato concurrunt civesque Romanos qui negotiandi causa ibi constiterant, in his C.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ubicumque","latin":"ubicumque","headword":"ubicumque","letter":"u","pos":"adverb","posGroup":"adverb","english":"wherever","forms":["ubicumque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is Ascanius — {{ubicumque}} et quācumque mātre nātus — Lāvīnium, opulentam iam (ut tum rēs erant) urbem, Lāvīniae relīquit, ipse novam urbem sub Albānō monte condidit, quae ab sitū urbis in dorsō montis 'Alba Longa' appellāta est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ubinam","latin":"ubinam","headword":"ubinam","letter":"u","pos":"adverb","posGroup":"adverb","english":"where in the world?","forms":["ubinam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cum iter facerent simul, Isaacus dīxit patrī: mī pater, ecce ligna; sed {{ubinam}} est hostia immolanda?","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ubique","latin":"ubīque","headword":"ubīque","letter":"u","pos":"adverb","posGroup":"adverb","english":"anywhere, everywhere; everywhere","forms":["ubique"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam, {{ubique}} maior atque inlustrior incidit res, clamore per agros regionesque significant; hunc alii deinceps excipiunt et proximis tradunt, ut tum accidit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"udus","latin":"ūdus, -a, -um","headword":"ūdus","letter":"u","pos":"adjective","posGroup":"adjective","english":"wet","forms":["ūdā","ūdīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"dēficient, ūdā lūmina tange manū!","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"ulcisci","latin":"(ulcīscor) ulcīscī, -ultum","headword":"ulcīscī","letter":"u","pos":"verb","posGroup":"verb","english":"revenge, avenge; to avenge, punish","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"ulciscor","latin":"ulciscor, ulcisci, ultus sum","headword":"ulciscor","letter":"u","pos":"verb","posGroup":"verb","english":"avenge; punish","forms":["ulcīscar","ulcīscātur","ulciscendī","ulcīscerētur","ulcīscī","ulta","ultī","ultum","ultus","vlta","vltam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Post mortem patris, timēbant frātrēs Iōsēphī nē {{ulcīscerētur}} iniūriam quam accēperat; mīsērunt igitur ad illum rogantēs nōmine patris ut eam oblīvīscerētur, sibique condōnāret.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ulixes","latin":"Ulixēs, -is","headword":"Ulixēs","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"Ulysses (Greek Odysseus)","forms":["Ulixe","Ulixem","Ulixēs","Ulixī","Ulixis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam vērō diū hoc modo inter sē magnō cum gaudiō lūsērunt, rēgis fīlia pilam ad ancillam tam altē iēcit, ut illa capere nōn posset; cecidit autem in mare flūctūsque eam ita sēcum trāxērunt, ut mergerētur: itaque puellae simul omnēs tam magnā vōce clāmāvērunt, ut {{Ulixēs}}, nōtissimus ille Graecōrum dux, quī in silvā prope lītus dormiēbat, subitō excitārētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ullus","latin":"ūllus, -a, -um","headword":"ūllus","letter":"u","pos":"adjective","posGroup":"adjective","english":"any (usually only with negation)","forms":["ulla","ūllae","ūllam","ūllās","ūllī","ūllīs","ūllīus","ūllō","ūllōs","ūllum","ūllus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Neque enim {{ulla}} alia condicione bella gesserunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ulmus","latin":"ulmus, ulmi","headword":"ulmus","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"elm tree","forms":["ulmō","ulmum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Habēbat ante oculōs {{ulmum}} pulcherrimam, ex quā pendēbant mīrābilēs ūvae; quās cum multīs verbīs laudāvisset, “At sī arbor” inquit “stāret sine vīte, nūllā esset causā cūr hominēs eam peterent, praeter umbram, quam facit; haec quoque vītis, quae cum ulmō iūncta est, in arbore quiēscit; sī enim nōn nūpta esset, humī iacēret;","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ulterior","latin":"ulterior, ulterius","headword":"ulterior","letter":"u","pos":"adjective","posGroup":"adjective","english":"farther, more distant; farther","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"ultimum","latin":"ultimum","headword":"ultimum","letter":"u","pos":"adverb","posGroup":"adverb","english":"extremely, to the last degree, utterly; finally, at last","forms":["ultimum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quibus superbissimīs verbīs audītīs, Virginius, gladiō sub palliō occultātō, ad fīliam suam accessit, dīcēns Claudiō sē {{ultimum}} eam complectī velle: gladium vērō in corpus eius mersit atque interfēcit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ultimus","latin":"ultimus, -a, -um","headword":"ultimus","letter":"u","pos":"adjective","posGroup":"adjective","english":"most distant, last; last, final; last","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"ultio","latin":"ultio, ultionis","headword":"ultio","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"revenge, vengeance, retribution","forms":["ultiōnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Sed spatiō temporis crīnis accīsus crēscere et cum crīne virtūs redīre coepit: iamque Samsōn, cōnscius receptī rōboris, iūstae {{ultiōnis}} tempus opperiēbātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ultor","latin":"ultor, -ōris (m.)","headword":"ultor","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"avenger","forms":["ultor","ultōribus","Ultōris"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum Hebraeī in potestāte essent Philistaeōrum, et ab illīs afflīgerentur, nātus est Samsōn, futūrus {{ultor}} hostium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ultra","latin":"ultrā","headword":"ultrā","letter":"u","pos":"preposition","posGroup":"preposition","english":"(prp. + acc.) on that (the far) side; beyond (+ acc.)","forms":["ultrā"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Vōs autem dēbitās Deō grātēs rependite.” Haec locūtus, ab illōrum cōnspectū ablātus est, nec ultrā compāruit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ultrix","latin":"ultrīx, -īcis ( f.)","headword":"ultrīx","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"avenging","forms":["ultrīcēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ō Sōl, quī omnia terrārum opera flammīs tuīs illūstrās, tūque Iūnō, testis hārum cūrārum, et Furiae {{ultrīcēs}}, audīte precēs nostrās: Sī necesse est virum impium terram Italiae attingere et sīc fāta poscunt — at bellō et hostium armīs ex fīnibus suīs pulsus auxilium implōret videatque indigna suōrum fūnera!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ultro","latin":"ultrō","headword":"ultrō","letter":"u","pos":"adverb","posGroup":"adverb","english":"spontaneously","forms":["ultro"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Qui se {{ultro}} morti offerant facilius reperiuntur quam qui dolorem patienter ferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ululat","latin":"ululat, -ant","headword":"ululat","letter":"u","pos":"verb","posGroup":"verb","english":"howl; howls","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"ululatus","latin":"ululātus, -ūs","headword":"ululātus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"howling; wailing, shriek","forms":["ululāta","ululātibus","ululatu"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum suos pugna superiores esse Galli confiderent et nostros multitudine premi viderent, ex omnibus partibus et ei qui munitionibus continebantur et hi qui ad auxilium convenerant clamore et {{ululatu}} suorum animos confirmabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ululo","latin":"ululo, ululare, ululavi, ululatus","headword":"ululo","letter":"u","pos":"verb","posGroup":"verb","english":"howl, yell, shriek; celebrate or proclaim with howling","forms":["ululantem","ululāre","ululat"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Parvus canis, quī magnum canem timet, nōn lātrat, sed {{ululat}}: “Uhuhū!” et ad dominum suum currit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"umbra","latin":"umbra, -ae","headword":"umbra","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"shade, shadow; shade, spirit, shadow","forms":["umbrā","umbrae","umbram","umbrārum","umbrās","umbrīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce puerī quī nīdōs quaerunt in arboribus.” Iūlia Mārcum et Quīntum in umbrā inter arborēs errāre et nīdōs quaerere videt.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"umbraculum","latin":"umbraculum, umbraculi","headword":"umbraculum","letter":"u","pos":"noun (n.)","posGroup":"noun","english":"shelter/shade; protection from sun; parasol/umbrella; shady retreat/bower/arbor","forms":["umbrācula"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"209 Ipse tenē distenta suīs {{umbrācula}} virgīs,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"umbrosus","latin":"umbrōsus, -a, -um","headword":"umbrōsus","letter":"u","pos":"adjective","posGroup":"adjective","english":"shady","forms":["umbrōsā","umbrōsīs","umbrōsus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Sē in silvā umbrōsā et dēnsā celābat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"umecto","latin":"umecto, umectare, umectavi, umectatus","headword":"umecto","letter":"u","pos":"verb","posGroup":"verb","english":"moisten, make wet","forms":["ūmectat"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"multa gemēns, largōque ūmectat flūmine voltum.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"umens","latin":"umens, (gen.), umentis","headword":"umens","letter":"u","pos":"adjective","posGroup":"adjective","english":"moist, wet","forms":["ūmentibus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Alcyonē tamen nōn surrēxit, sed oculīs ūmentibus marītum quaerēbat, quī in celsā puppī stāns manum agitābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"umerus","latin":"umerus, -ī","headword":"umerus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"shoulder","forms":["umerī","umeris","umerō","umerōs","umerum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hi similitudine armorum vehementer nostros perterruerunt, ac, tametsi dextris {{umeris}} exsertis animadvertebantur, quod insigne pactum esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"umidum","latin":"umidum, umidi","headword":"umidum","letter":"u","pos":"noun (n.)","posGroup":"noun","english":"swamp","forms":["ūmidum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Ac prīmum Achātēs ignem facit et sociī cibō egentēs frūmentum ūmidum flammīs torrent.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"umidus","latin":"ūmidus, -a, -um","headword":"ūmidus","letter":"u","pos":"adjective","posGroup":"adjective","english":"humid, wet; wet, damp","forms":["ūmida","ūmidae","ūmidās","ūmidī","ūmidīs","ūmidus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōlī per imbrem frīgidum ambulāre!” sōlum ūmida, sed etiam sordida sunt vestīmenta eius, atque faciēs cruōre et sordibus operītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"umquam","latin":"umquam","headword":"umquam","letter":"u","pos":"adverb","posGroup":"adverb","english":"ever (always in neg. context)","forms":["umquam","VMQVAM"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem {{umquam}} homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint vagentur et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"un","latin":"un","headword":"un","letter":"u","pos":"numeral","posGroup":"numeral","english":"one","forms":["semel"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Sextus, quamquam puer fortis est, simul contrā duōs puerōs pugnāre nōn potest: iam is in viā dūrā iacet sub Titō et Mārcō, quī eum {{semel}} atque iterum pugnīs pulsant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"una","latin":"ūnā","headword":"ūnā","letter":"u","pos":"adverb","posGroup":"adverb","english":"together","forms":["una"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam veritos revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, {{una}} ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"una cum","latin":"ūnā cum","headword":"ūnā cum","letter":"u","pos":"","posGroup":"other","english":"(prp. + acc.) together with","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"unanimus","latin":"unanimus, unanima, unanimum","headword":"unanimus","letter":"u","pos":"adjective","posGroup":"adjective","english":"acting in accord; sharing a single purpose; harmonious (L+S); unanimous","forms":["ūnanimam"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cum sīc ūnanimam adloquitur male sāna sorōrem:","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"unctus","latin":"unctus, uncta, unctum","headword":"unctus","letter":"u","pos":"adjective","posGroup":"adjective","english":"oily, greasy; anointed, oiled","forms":["ūnctus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Quam ob causam reiectus est ā Deō, et in eius locum Dāvīd, adhūc iuvenis, ē tribū Iūdae ēlēctus est, et ā Samūēle ūnctus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"uncus","latin":"uncus, unci","headword":"uncus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"hook, barb, clamp; hook in neck used to drag condemned/executed criminals","forms":["uncō"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"ūlla tenent, uncō nōn alligat ancora morsū.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"unda","latin":"unda, -ae","headword":"unda","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"wave; wave, water, stream; wave, water, sea","forms":["undā","undae","undam","undārum","undās","undīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ibi Galatēa, nymphārum omnium pulcherrima, quae ūna cum sorōribus Siciliae {{undās}} incolēbat, ab Ācide pāstōre amābātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"unde","latin":"unde?","headword":"unde","letter":"u","pos":"adverb","posGroup":"adverb","english":"from where? whence?; from where?","forms":["unde"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Unde}} sunt illae rosae?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"undecentum","latin":"ūndēcentum","headword":"ūndēcentum","letter":"u","pos":"","posGroup":"other","english":"ninety-nine","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"undecim","latin":"ūndecim","headword":"ūndecim","letter":"u","pos":"numeral","posGroup":"numeral","english":"eleven","forms":["ūndecim","ūndecimō","ūndecimus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Difficile nōn est ab ūndecim!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"undecimus","latin":"ūndecimus, -a, -um","headword":"ūndecimus","letter":"u","pos":"","posGroup":"other","english":"eleventh","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"undecumque","latin":"undecumque","headword":"undecumque","letter":"u","pos":"adverb","posGroup":"adverb","english":"from/in whatever/every direction; from any point/source/side; in every respect","forms":["undecumque"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Iūlius ante nummulāriī mēnsam adsistit.] [Nummulārius:] “Domine, quid imperās?” [Iūlius:] “Numquid habēs pecūniam vacuam?” [Nummulārius:] “Quid opus habēs mūtuārī?” [Iūlius:] “Sī habēs, commodā mihi quīnque sēstertia.” [Nummulārius:] “Et sī nōn habērem, {{undecumque}} explicārem.” [Iūlius:] “Pignus vīs?” [Nummulārius:] “Absit, nōn opus habeō.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"undequadraginta","latin":"ūndēquadrāgintā","headword":"ūndēquadrāgintā","letter":"u","pos":"numeral","posGroup":"numeral","english":"thirty-nine","forms":["ūndēquadrāgintā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Trīgintā et novem sunt ūndēquadrāgintā.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"undequinquagesimus","latin":"ūndēquīnquāgēsimus, -a, -um","headword":"ūndēquīnquāgēsimus","letter":"u","pos":"","posGroup":"other","english":"forty-ninth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"undetriginta","latin":"ūndētrīgintā","headword":"ūndētrīgintā","letter":"u","pos":"numeral","posGroup":"numeral","english":"thirty-nine","forms":["ūndētrīgintā"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iānuārius tam longus est quam December, sed Februārius brevior est: duodētrīgintā aut ūndētrīgintā diēs tantum habet.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"undevicesimus","latin":"ūndēvīcēsimus, -a, -um","headword":"ūndēvīcēsimus","letter":"u","pos":"","posGroup":"other","english":"nineteenth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"undeviginti","latin":"ūndēvīgintī","headword":"ūndēvīgintī","letter":"u","pos":"numeral","posGroup":"numeral","english":"nineteen","forms":["ūndevīcēsimō","ūndēvīgintī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Mārcus: “... quīndecim, sēdecim, septendecim, duodēvīgintī, ūndēvīgintī, vīgintī.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"undique","latin":"undique","headword":"undique","letter":"u","pos":"adverb","posGroup":"adverb","english":"from all sides","forms":["undique"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ubi neminem in aequum locum sese demittere sed toto {{undique}} muro circumfundi viderunt, veriti ne omnino spes fugae tolleretur, abiectis armis ultimas oppidi partes continenti impetu petiverunt, parsque ibi, cum angusto exitu portarum se ipsi premerent, a militibus, pars iam egressa portis ab equitibus est interfecta; nec fuit quisquam qui praedae studeret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"undo","latin":"undo, undare, undavi, undatus","headword":"undo","letter":"u","pos":"verb","posGroup":"verb","english":"surge/flood/rise in waves; gush/well up; run, stream; billow; undulate; waver","forms":["undāre"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"ab-{{undāre}} * ab 7 nimis plénus esse","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"undosus","latin":"undosus, undosa, undosum","headword":"undosus","letter":"u","pos":"adjective","posGroup":"adjective","english":"abounding in waves, flowing water, etc","forms":["undōsum"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Troia per {{undōsum}} peterētur classibus aequor?","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"ungo","latin":"ungo, ungere, unxi, unctus","headword":"ungo","letter":"u","pos":"verb","posGroup":"verb","english":"anoint/rub (w/oil/unguent); smear with oil/grease; dress (food w/oil); add oil","forms":["ungēbam","ungerent","ungor"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et veniēbant valdē dīlūculō mulierēs portantēs, quae parāverant, arōmata, ut {{ungerent}} corpus Iēsu.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"unguentarius","latin":"unguentarius, unguentari(i)","headword":"unguentarius","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"dealer in ointments, maker of ointments","forms":["unguentārium","unguentārius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aenêīs 11.44 praxis -is f (acc -im): habêre citrat (: pedibus pulsat) mäteriâ mollî (ut cērä, gyp- pedês (vincula pedum) gerit {{unguentārius}} unguentum, ve- mola -ae f: înstrümentum rō- vertitur; ita sēmen mōlītur comparāre + dat: illî : cum “In Geminîs autem nāscuntur bîgae et bovēs et coleî et quî utrôsque parietēs linunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"unguentum","latin":"unguentum, unguenti","headword":"unguentum","letter":"u","pos":"noun (n.)","posGroup":"noun","english":"oil, ointment","forms":["unguenta","unguentum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Aenêīs 11.44 praxis -is f (acc -im): habêre citrat (: pedibus pulsat) mäteriâ mollî (ut cērä, gyp- pedês (vincula pedum) gerit unguentārius {{unguentum}}, ve- mola -ae f: înstrümentum rō- vertitur; ita sēmen mōlītur comparāre + dat: illî : cum “In Geminîs autem nāscuntur bîgae et bovēs et coleî et quî utrôsque parietēs linunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"unguis","latin":"unguis, -is (m.)","headword":"unguis","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"nail, claw; claw, nail","forms":["ungue","unguēs","unguibus","unguis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum prīmum hoc audīvit, Iuppiter “Ergō,” inquit, “quoniam tam cupidus es mēcum veniendī, Olympum petāmus: tē statim illūc veham.” et puerum apprehēnsum portāvit, cavēns tamen nē candidīs Ganymēdīs membrīs {{unguibus}} nocēret; neque diū, quamquam iter satis longum erat, Iuppiter domō āfuit, sed celerrimē, ut Trōiam pervēnerat, ita inde, ab īmīs ad summā ascendēns, rūrsus ēvolāvit, domumque rēcta via iterum petīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"unguo","latin":"unguō, -ere, ūnxī, ūnctum","headword":"unguō","letter":"u","pos":"verb","posGroup":"verb","english":"to anoint, smear","forms":["ūncta","ūnctum","unguent","unguēre","unguimur","ūnxērunt","ūnxisse","unxit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quicquid in Aenēā fuerat mortāle, repurgat\net respersit aquīs; pars optima restitit illī,\nlūstrātum genetrīx dīvīnō corpus odōre\n{{unxit}} et ambrosiā cum dulcī nectare mixtā\ncontigit ōs fēcitque deum.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"uni","latin":"ūnī, -ae, -a","headword":"ūnī","letter":"u","pos":"adjective","posGroup":"adjective","english":"one at a time; one each","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"unice","latin":"unice","headword":"unice","letter":"u","pos":"adverb","posGroup":"adverb","english":"to a singular degree; especially","forms":["ūnicē"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Pater ūnicē dīligit puerum; nōlēbat prīmō eum dīmittere; nōn potuī id ab eō impetrāre, nisi postquam spopondī eum tūtum ab omnī perīculō fore.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"unicus","latin":"ūnicus, -a, -um","headword":"ūnicus","letter":"u","pos":"adjective","posGroup":"adjective","english":"one and only, sole","forms":["ūnicam","ūnicō","ūnicum","ūnicus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam Isaacus adolēvit, deus tentāns fidem Abrahamī, dīxit illī: Abrahame, tolle fīlium tuum ūnicum quem amās, et immolā eum mihi in monte quem ostendam tibi.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"universus","latin":"ūniversus, -a, -um","headword":"ūniversus","letter":"u","pos":"adjective","posGroup":"adjective","english":"the whole of, entire; whole, entire","forms":["ūniversa","universae","ūniversam","ūniversī","universis","ūniversō","ūniversōs","ūniversum","ūniversus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tamen tanta {{universae}} Galliae consensio fuit libertatis vindicandae et pristinae belli laudis reciperandae, ut neque beneficis neque amicitiae memoria moverentur, omnesque et animo et opibus in id bellum incumberent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"unquam","latin":"unquam","headword":"unquam","letter":"u","pos":"adverb","posGroup":"adverb","english":"at any time, ever; at some time","forms":["unquam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum obdūxerō nūbēs caelō, arcus meus appārēbit, et recordābor foederis meī, nec {{unquam}} dīluvium erit ad perdendum orbem terrārum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"unus","latin":"ūnus","headword":"ūnus","letter":"u","pos":"numeral; adjective","posGroup":"numeral","english":"one, only; one","forms":["unam","ūnī","unius","uno","unum","unus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eo cum pervenisset, ad reliquas legiones mittit priusque omnes in {{unum}} locum cogit quam de eius adventu Arvernis nuntiari posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"urbanitas","latin":"urbanitas, urbanitatis","headword":"urbanitas","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"city living, city life/manners, life in Rome; sophistication, polish, wit","forms":["urbānitātem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Plürimî hôc signô scholasticî nāscuntur et Laudâmus {{urbānitātem}} mathëmaticî; itaque adiēcit: “Deinde tôtus caelus Taurulus ﬁt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"urbanus","latin":"urbānus, -a, -um","headword":"urbānus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"of the city, sophisticated","forms":["urbāna","urbanas","urbānī","urbānīs","urbano","urbānōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri {{urbano}} motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"urbs","latin":"urbs, urbis","headword":"urbs","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"(f.) city","forms":["urbe","urbem","urbes","urbī","urbibus","urbis","urbium","urbs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Omnium consensu hac sententia probata, uno die amplius XX {{urbes}} Biturigum incenduntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"urceolus","latin":"urceolus, urceoli","headword":"urceolus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"small jug or pitcher","forms":["urceolum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Immô puer quoque ofﬁciôsus {{urceolum}} ﬁîgidum ad mālam eius admôvit, super quem incumbēns Fortūnāta Contrā Trimalchiô “Quid enim?” inquit, “Ambūbāiam nôn meminit sē?","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"urere","latin":"(ūrō) ūrere, ussisse, ustum","headword":"ūrere","letter":"u","pos":"verb","posGroup":"verb","english":"burn; to burn, scorch","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"urgeo","latin":"urgeo, urgere, ursi, -","headword":"urgeo","letter":"u","pos":"verb","posGroup":"verb","english":"press/squeeze/bear hard/down; tread/traverse continually; push/shove/thrust","forms":["urgēbātur","urgent","urgente","urgentur","urgērī","urget"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Positīs {{urgentur}} pectora palmīs, tunc prīmum externā pectora tācta manū.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"urgere","latin":"(urgeō) urgēre, ursisse","headword":"urgēre","letter":"u","pos":"","posGroup":"other","english":"press, oppress","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"urit","latin":"ūrit","headword":"ūrit","letter":"u","pos":"verb","posGroup":"verb","english":"burns, scorches","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"urna","latin":"ūrna, -ae","headword":"ūrna","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"urn, vessel of baked clay","forms":["ūrnā","urnae","urnam","urnās","urnīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ecce statim Rebecca, virgō eximia pulchritūdine, prōdiit, gerēns {{urnam}} hūmēris; quae dēscendit ad puteum, et implēvit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"uro","latin":"uro, urere, ussi, ustus","headword":"uro","letter":"u","pos":"verb","posGroup":"verb","english":"burn","forms":["ūrātur","ūrendum","ūrere","ūret","ūris","ūrit","ūritur","ūror","ūruntur","ussit","ustī","ustīs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum sibi deōs verendōs esse negārent eōsque contemnerent, manūs nōn abstinēbant ab aurō quod in templīs servābātur, et tam nēquam atque inī ustī erant ut aliī crūdēlissimī ergā līberōs essent, aliī patrēs suōs ipsī necārent; nam neque patrēs amābant līberōs, neque līberī patrēs: aliī aliōs ōderant.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"ursa","latin":"ursa, -ae","headword":"ursa","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"bear; Ursa Māior — Greater Bear; Ursa Minor — Smaller Bear","forms":["ursa","ursae","ursam","ursum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"{{Ursum}} pariter interfēcī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ursus","latin":"ursus, ursi","headword":"ursus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"bear","forms":["Urse","ursō","ursōs","ursus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Duo servī, Dāvus et {{Ursus}}, lectīcam cum dominō portant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"usitatus","latin":"usitatus, usitata -um, usitatior -or -us, usitatissimus -a -um","headword":"usitatus","letter":"u","pos":"adjective","posGroup":"adjective","english":"usual, customary, ordinary, common, familiar, everyday; commonly used/practiced","forms":["usitatum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Nam et laqueis falces avertebant, quas cum destinaverant tormentis introrsus reducebant, et aggerem cuniculis subtrahebant, eo scientius quod apud eos magnae sunt ferrariae atque omne genus cuniculorum notum atque {{usitatum}} est.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"usquam","latin":"usquam","headword":"usquam","letter":"u","pos":"adverb","posGroup":"adverb","english":"anywhere","forms":["usquam"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Neque ego umquam {{usquam}} tanta mīra mē vīdisse cēnseō.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"usque","latin":"ūsque","headword":"ūsque","letter":"u","pos":"adverb","posGroup":"adverb","english":"up (to), all the time; all the way, even","forms":["usque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, {{usque}} eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"usurarius","latin":"usurarius, usuraria, usurarium","headword":"usurarius","letter":"u","pos":"adjective","posGroup":"adjective","english":"of interest/usury; interest-derived; subject to interest; provided on loan","forms":["ūsūrāriā"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"cum Alcumēnā—uxōre ūsūrāriā.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"usurpo","latin":"usurpo, usurpare, usurpavi, usurpatus","headword":"usurpo","letter":"u","pos":"verb","posGroup":"verb","english":"seize upon, usurp; use","forms":["ūsūrpābitis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Nōn ūsūrpābitis nōmen Deī vestrī temere et sine causā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"usus","latin":"ūsus, -ūs","headword":"ūsus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"use, practice, usage; use, practice; use, service, advantage","forms":["usu","usui","ūsum","usus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Caesar biduum in his locis moratus, quod haec de Vercingetorige {{usu}} ventura opinione praeceperat, per causam supplementi equitatusque cogendi ab exercitu discedit; Brutum adulescentem his copiis praeficit; hunc monet ut in omnes partes equites quam latissime pervagentur; daturum se operam ne longius triduo ab castris absit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"ut","latin":"ut","headword":"ut","letter":"u","pos":"conjunction","posGroup":"conjunction","english":"like, as; that, in order that; as, like; that","forms":["ut","Vt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Quieta Gallia, Caesar, {{ut}} constituerat, in Italiam ad conventus agendos proficiscitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utcumque","latin":"utcumque","headword":"utcumque","letter":"u","pos":"adverb","posGroup":"adverb","english":"no matter how, however","forms":["Utcumque"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"SOSIA: {{Utcumque}} animō collibitum est meō!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"utens","latin":"utens, utentis (gen.), utentior -or -us, utentissimus -a -um","headword":"utens","letter":"u","pos":"adjective","posGroup":"adjective","english":"having money to spend","forms":["ūtēns"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Tum ille, occāsiōne ūtēns, columnās concussit, et turba omnis obruta est ruīnā domūs, simulque Samsōn ipse cum hostibus nōn inultus occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"uter","latin":"uter, -tra, -trum?","headword":"uter","letter":"u","pos":"pronoun","posGroup":"pronoun","english":"which (of the two)?; which of the two?","forms":["uter","utra","utram","Utrēs","utrī","utris"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Aqua flūminis tam lentē currēbat, ut in {{utram}} partem flueret oculīs cernī nōn posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"uterque","latin":"uterque, utraque, utrumque","headword":"uterque","letter":"u","pos":"pronoun","posGroup":"pronoun","english":"each of the two; each of the two, both; each (of the two); each (of two), both","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"uterus","latin":"uterus, uteri","headword":"uterus","letter":"u","pos":"noun (m.)","posGroup":"noun","english":"womb; belly, abdomen","forms":["uterō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Cum ex hāc vītā dēcesserō, sepelī corpus meum; mātrem tuam colitō, memor malōrum quae passa est, cum tē in uterō gestāret, et cum ipsā suprēmum diem obierit, eam pōnitō mēcum in eōdem sepulcrō.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"uti","latin":"(ūtor) ūtī, ūsum","headword":"ūtī","letter":"u","pos":"verb","posGroup":"verb","english":"(+abl.) use; like, as, how; to use","forms":["uti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sibi numquam placuisse Avaricum defendi, cuius rei testes ipsos haberet; sed factum imprudentia Biturigum et nimia obsequentia reliquorum {{uti}} hoc incommodum acciperetur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utica","latin":"Utica, Uticae","headword":"Utica","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"Utica; (town in Africa west of Carthage)","forms":["Ūticae","Uticam"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Scīpiō adventū Hasdrubalis et Syphācis, quī prope cum centum mīlibus armātōrum vēnerant, ab obsidiōne Ūticae dēpulsus hīberna commūnīvit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"utilis","latin":"ūtilis, -e","headword":"ūtilis","letter":"u","pos":"adjective","posGroup":"adjective","english":"useful","forms":["ūtile","ūtilem","ūtilēs","utili","ūtilia","ūtilibus","ūtilis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Huius opera Commi, ut antea demonstravimus, fideli atque {{utili}} superioribus annis erat usus in Britannia Caesar; quibus ille pro meritis civitatem eius immunem esse iusserat, iura legesque reddiderat atque ipsi Morinos attribuerat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utilitas","latin":"ūtilitās, -ātis ( f.)","headword":"ūtilitās","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"interest, advantage; usefulness, advantage","forms":["ūtilitās","utilitatem","ūtilitātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hoc cum in speciem varietatemque opus deforme non est, alternis trabibus ac saxis quae rectis lineis suos ordines servant, tum ad {{utilitatem}} et defensionem urbium summam habet opportunitatem, quod et ab incendio lapis et ab ariete materia defendit, quae perpetuis trabibus pedes quadragenos plerumque introrsus revincta neque perrumpi neque distrahi potest.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utiliter","latin":"utiliter, utilius, utilissime","headword":"utiliter","letter":"u","pos":"adverb","posGroup":"adverb","english":"usefully/profitably/to advantage; interestedly; validly/effectively/practically","forms":["ūtiliter","ūtilius"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Longa referre mora est, quae cōnsiliōque manūque ūtiliter fēcī spatiōsī tempore bellī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"utinam","latin":"utinam","headword":"utinam","letter":"u","pos":"adverb","posGroup":"adverb","english":"if that, only that, would that; if only","forms":["utinam"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Inambulābat in cēnāculō maerēns, et in hās vōcēs identidem ērumpēns: “Fīlī mī Absalōn, Absalōn fīlī mī: {{utinam}} prō tē moriar, Absalōn fīlī mī, fīlī mī Absalōn.”","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"utique","latin":"utique","headword":"utique","letter":"u","pos":"adverb","posGroup":"adverb","english":"certainly, by all means; at any rate","forms":["utique"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Et Titus noster magnum animum habet et est caldicerebrius: aut hoc aut illud, erit quid {{utique}}.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"utor","latin":"ūtor, ūtī, ūsus sum","headword":"ūtor","letter":"u","pos":"verb","posGroup":"verb","english":"use, make use of (+ abl.); to use, employ (+ abl.)","forms":["ūsa","ūsī","ūsūram","ūsūrum","Ūtāmur","ūtar","ūtātur","utebantur","ūtēbātur","ūtenda","utendum","ūtentēs","ūtere","ūterentur","uteretur","utimini","ūtimur","ūtitur","ūtor","ūtuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Altero die cum ad oppidum Senonum Vellaunodunum venisset, ne quem post se hostem relinqueret, quo expeditiore re frumentaria {{uteretur}}, oppugnare instituit idque biduo circumvallavit; tertio die missis ex oppido legatis de deditione, arma conferri, iumenta produci, sescentos obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utpote","latin":"utpote","headword":"utpote","letter":"u","pos":"adverb","posGroup":"adverb","english":"namely","forms":["utpote"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Tunc iussit angelus fel piscis sēpōnī, {{utpote}} medicāmentum salūtāre; deinde partem carnis coxērunt comedendam in viā.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"utrimque","latin":"utrimque","headword":"utrimque","letter":"u","pos":"adverb","posGroup":"adverb","english":"on/from both sides; on each side, on both sides","forms":["utrimque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum uterque {{utrimque}} exisset exercitus, in conspectu fereque e regione castris castra ponebant, dispositis exploratoribus necubi effecto ponte Romani copias traducerent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utrobique","latin":"ūtrobīque","headword":"ūtrobīque","letter":"u","pos":"adverb","posGroup":"adverb","english":"in both places","forms":["utrobīque"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Dissidēbat ab eō Pergamēnus rēx Eumenēs, Rōmānīs amīcissimus, bellumque inter eōs gerēbātur et marī et terrā; sed {{utrobīque}} Eumenēs plūs valēbat propter Rōmānōrum societātem.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"utroque","latin":"utroque","headword":"utroque","letter":"u","pos":"adverb","posGroup":"adverb","english":"to both places; in both directions; to both sides (in conflict)","forms":["utroque"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Cum is murum hostium paene contingeret et Caesar ad opus consuetudine excubaret militesque hortaretur ne quod omnino tempus ab opere intermitteretur, paulo ante tertiam vigiliam est animadversum fumare aggerem, quem cuniculo hostes succenderant; eodemque tempore toto muro clamore sublato, duabus portis ab {{utroque}} latere turrium eruptio fiebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"utrum","latin":"utrum","headword":"utrum","letter":"u","pos":"conjunction","posGroup":"conjunction","english":"whether","forms":["utrum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Fabia: “{{Utrum}} fīlium dīcis, māiōremne an minōrem?”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"utut","latin":"utut","headword":"utut","letter":"u","pos":"conjunction","posGroup":"conjunction","english":"however; in whatever way","forms":["utut"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Vērum, {{utut}} es factūrus, hoc quidem hercle haud reticēbō tamen,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"uva","latin":"ūva, -ae","headword":"ūva","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"grape","forms":["ūva","ūvae","ūvam","ūvās","ūvīs","VVA"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum prior sīc exposuit Iōsēphō somnium suum: vīdī in quiēte vītem in quā erant trēs palmitēs; ea paulātim prōtulit gemmās; deinde flōrēs ērūpērunt, ac dēnique ūvae mātūrēscēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"uxor","latin":"uxor, uxōris","headword":"uxor","letter":"u","pos":"noun (f.)","posGroup":"noun","english":"(f.) wife","forms":["uxor","uxōre","uxorem","uxōrēs","uxōrī","uxoribus","uxōris"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Conclamant equites, sanctissimo iure iurando confirmari oportere, ne tecto recipiatur, ne ad liberos, ne ad parentes, ne ad {{uxorem}} aditum habeat qui non bis per agmen hostium perequitasset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"uxorem ducere","latin":"uxōrem dūcere","headword":"uxōrem dūcere","letter":"u","pos":"phrase","posGroup":"other","english":"to marry (a woman)","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"uxorius","latin":"uxōrius, -a, -um","headword":"uxōrius","letter":"u","pos":"adjective","posGroup":"adjective","english":"attached to one’s wife","forms":["uxōria","uxōrius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"155 hoc decet uxōrēs, dōs est {{uxōria}} lītēs","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"v","latin":"v","headword":"v","letter":"v","pos":"pronoun","posGroup":"pronoun","english":"you (pl.), ye","forms":["vobis","vōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Vos}} data facultate vobis consulite.' Simul in medios hostes irrupit duobusque interfectis reliquos a porta paulum summovit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"va","latin":"va","headword":"va","letter":"v","pos":"interjection","posGroup":"interjection","english":"Ha!/oh!/ah!; (exclamation of pain/dismay, of contempt/anger, of surprise/joy)","forms":["vā"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Proteus -ī 7, deus maris, quī in vā-","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vacca","latin":"vacca, vaccae","headword":"vacca","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"cow","forms":["vacca","vaccae","vaccam","vaccās"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vidēbātur sibi adstāre Nīlō flūminī; et ecce ēmergēbant dē flūmine septem {{vaccae}} pinguēs, quae pāscēbantur in palūde.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vaco","latin":"vaco, vacare, vacavi, vacatus","headword":"vaco","letter":"v","pos":"verb","posGroup":"verb","english":"be empty; be vacant; be idle; be free from, be unoccupied","forms":["vacat","vacet"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Nam quicquid illī {{vacat}}, caput dē tabulā nôn tollit.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vacuefacio","latin":"vacuefacio, vacuefacere, vacuefeci, vacuefactus","headword":"vacuefacio","letter":"v","pos":"verb","posGroup":"verb","english":"empty/free/clear place); make room; make vacant; disencumber; abolish (L+S)","forms":["vacuēfacta","vacuēfēcissēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nūper, cum morte superiōris uxōris novīs nūptiīs domum {{vacuēfēcissēs}}, nōnne etiam aliō incrēdibilī scelere hoc scelus cumulāvistī?","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vacuo","latin":"vacuo, vacuare, vacuavi, vacuatus","headword":"vacuo","letter":"v","pos":"verb","posGroup":"verb","english":"empty","forms":["vacuo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"A medio fere colle in longitudinem, ut natura montis ferebat, ex grandibus saxis sex pedum murum, qui nostrum impetum tardaret praeduxerant Galli atque inferiore omni spatio {{vacuo}} relicto superiorem partem collis usque ad murum oppidi densissimis castris compleverant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vacuus","latin":"vacuus, -a, -um","headword":"vacuus","letter":"v","pos":"adjective","posGroup":"adjective","english":"empty","forms":["vacuā","vacuae","vacuam","vacuās","vacuī","vacuōs","vacuum","vacuus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hunc ex proximis unus iacentem transgressus eodem illo munere fungebatur; eadem ratione ictu scorpionis exanimato alteri successit tertius et tertio quartus; nec prius ille est a propugnatoribus {{vacuus}} relictus locus quam restincto aggere atque omni ex parte summotis hostibus finis est pugandi factus.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vadere","latin":"(vādō) vādere","headword":"vādere","letter":"v","pos":"","posGroup":"other","english":"advance, go","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vado","latin":"vado, vadere, vasi, -","headword":"vado","letter":"v","pos":"verb","posGroup":"verb","english":"go, advance, rush, hurry; walk","forms":["vadātō","vādentem","vado","vādunt"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Erat in magnis Caesari difficultatibus res, ne maiorem aestatis partem flumine impediretur, quod non fere ante autumnum Elaver {{vado}} transiri solet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vadum","latin":"vadum, -ī","headword":"vadum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"ford, shallows; shallows, bottom of the sea; shallow water, shoal","forms":["vada","vādis","vadum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ut Hebraeī in terram prōmissam intrōdūcerentur, Iordānis erat trāiciendus, nec erat iīs nāvium cōpiā, nec {{vadum}} praebēbat amnis tunc plēnō alveō fluēns.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vae","latin":"vae","headword":"vae","letter":"v","pos":"interjection","posGroup":"interjection","english":"alas, woe, ah; oh dear; (Vae, puto deus fio. - Vespasian); Bah!, Curses!","forms":["uae","vae"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"{{Vae}} hominī illī, per quem scandalum venit ī\"","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vafer","latin":"vafer, vafra, vafrum","headword":"vafer","letter":"v","pos":"adjective","posGroup":"adjective","english":"sly, cunning, crafty","forms":["vafer","vafrī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"cuive pater vafrī lūditur arte Getae.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vagari","latin":"(vagor) vagārī","headword":"vagārī","letter":"v","pos":"","posGroup":"other","english":"wander, roam","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vagina","latin":"vāgīna, -ae","headword":"vāgīna","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"sheath; scabbard, sheath","forms":["vāgīnā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Mūcius ergō, gladiō ē vāgīnā ēductō, in tabernāculum ingressus, in virum scrībentem impetum fēcit, quī, cum purpureīs vestīmentīs esset indūtus, rēx eī esse vidēbātur, et clāmāns “Ita tē, Porsenna, occīdō!”, eum gladiō percussit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vagio","latin":"vāgiō, vāgīre","headword":"vāgiō","letter":"v","pos":"verb","posGroup":"verb","english":"wail (of babies)","forms":["vāgiente","vāgientem","vāgiet","vāgit","Vāgīvērunt"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Aperta fiscella, cernēns parvulum {{vāgientem}}, miserita est illīus: “Iste est” inquit “ūnus ex īnfantibus Hebraeōrum.” Tunc soror puerī accēdēns: “Vīsne” ait “ut arcessam mulierem Hebraeam, quae nūtriat parvulum?” et tunc vocāvit mātrem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vagire","latin":"vāgīre","headword":"vāgīre","letter":"v","pos":"verb","posGroup":"verb","english":"cry, wail","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vagitus","latin":"vāgītus, -ūs","headword":"vāgītus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"wail, squall; wail, infant cry","forms":["vāgītum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum aqua recēdēns alveum, in quō expositī erant puerī, in siccō relīquisset, lupa sitiēns ex montibus ad puerīlem {{vāgītum}} cursum flēxit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vagor","latin":"vagor, vagari, vagatus sum","headword":"vagor","letter":"v","pos":"verb","posGroup":"verb","english":"wander, roam","forms":["vagantem","vagantur","vagarentur","vagātur","vagātus","vagentur","vagor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quibus oppressis inopinantibus, quod se Cevenna ut muro munitos existimabant, ac ne singulari quidem umquam homini eo tempore anni semitae patuerant, equitibus imperat ut quam latissime possint {{vagentur}} et quam maximum hostibus terrorem inferant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vagus","latin":"vagus, -a, -um","headword":"vagus","letter":"v","pos":"adjective","posGroup":"adjective","english":"wandering","forms":["vagae","vagōs","vagus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eris {{vagus}} in orbe terrārum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"valde","latin":"valdē","headword":"valdē","letter":"v","pos":"adverb","posGroup":"adverb","english":"strongly, very (much)","forms":["valdē","valdius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Rebecca audierat Isaacum loquentem; vocāvit Iacobum, et: affertō, inquit, mihi duōs haedōs opīmōs; cōnficiam pulmentum, quō pater tuus valdē dēlectātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vale","latin":"valē, valēte","headword":"valē","letter":"v","pos":"verb","posGroup":"verb","english":"farewell, goodbye","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"valedico","latin":"valedico, valedicere, valedixi, valedictus","headword":"valedico","letter":"v","pos":"verb","posGroup":"verb","english":"say goodbye","forms":["valedīxit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Itaque Tobiās {{valedīxit}} parentibus, simulque ambō dedērunt sē in viam, et canis secūtus est eōs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"valens","latin":"valens, valentis (gen.), valentior -or -us, valentissimus -a -um","headword":"valens","letter":"v","pos":"adjective","posGroup":"adjective","english":"strong; vigorous/healthy/robust; powerful/potent/effective; severe; influential","forms":["valēns","valentior"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Caput {{valēns}} nōn dolet nec membra valentiā.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"valeo","latin":"valeo, valere, valui, valitus","headword":"valeo","letter":"v","pos":"verb","posGroup":"verb","english":"be strong/powerful/influential/healthy; prevail; [vale => goodbye/farewell]","forms":["valē","valeās","valeō","valēs","valēte","valētis","valuēre","valuisse","valuisset","valuistī","valuit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ergō valē, bone serve, ac bene ambulā!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"valerius","latin":"Valerius, Valeri","headword":"Valerius","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Valerius; (Roman gens name); P. Valerius Publicola, very early consul (509 BC)","forms":["Valerio","Valerium","Valerius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"{{Valerio}} Donnotauro, Caburi filio, principe civitatis compluribusque aliis interfectis intra oppida ac muros compelluntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"valet","latin":"valet, valēre","headword":"valet","letter":"v","pos":"verb","posGroup":"verb","english":"be strong, be well; is well, is strong","forms":["valeant","valeat","valēbat","valent","valentem","valentēs","valentiā","valēre","valēret","valet"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Legationes in omnes partes circummittuntur; quantum gratia, auctoritate, pecunia {{valent}} ad sollicitandas civitates nituntur; nacti obsides quos Caesar apud eos deposuerat, horum supplicio dubitantes territant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"valetudo","latin":"valētūdō, valētūdinis","headword":"valētūdō","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) health","forms":["valetudine","valētūdinem"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sententiis dictis constituunt, ut ei qui {{valetudine}} aut aetate inutiles sunt bello oppido excedant atque omnia prius experiantur quam ad Critognati sententiam descendant; illo tamen tempore potius utendum consilio, si res cogat atque auxilia morentur, quam aut deditionis aut pacis subeundam condicionem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"validus","latin":"validus, -a, -um","headword":"validus","letter":"v","pos":"adjective","posGroup":"adjective","english":"strong; strong, powerful; strong, vigorous","forms":["valida","validae","validam","validē","validī","validō","validōs","validum","validus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nōn putō Mārcum tam {{validum}} esse quam tē.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vallare","latin":"(vāllō) vāllāre","headword":"vāllāre","letter":"v","pos":"","posGroup":"other","english":"fortify, defend","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vallaris","latin":"vallaris, vallaris","headword":"vallaris","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"crown/garland awarded to first soldier to scale an enemy rampart (vallum)","forms":["vallāre"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Aegrē propter onus incēdentī dīcēbat: 'Cum gladiō tē {{vallāre}} scieris, vallum ferre dēsinitō!' Quem mīlitem extrā ōrdinem dēprehendit, sī Rōmānus esset, vītibus, sī extrāneus, virgīs cecīdit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"valles","latin":"valles, vallis","headword":"valles","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"valley, vale, hollow","forms":["valles"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Consecutus id quod animo proposuerat Caesar receptui cani iussit legionisque decimae, quacum erat, continuo signa constituit; ac reliquarum legionum milites, non exaudito sono tubae, quod satis magna {{valles}} intercedebat, tamen ab tribunis militum legatisque, ut erat a Caesare praeceptum, retinebantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vallis","latin":"vallis, vallis","headword":"vallis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) valley","forms":["vallem","vallibus","vallis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Quini erant ordines coniuncti inter se atque implicati; quo qui intraverant, se ipsi acutissimis {{vallis}} induebant; hos cippos appellabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vallo","latin":"vallo, vallare, vallavi, vallatus","headword":"vallo","letter":"v","pos":"verb","posGroup":"verb","english":"surround/fortify/furnish (camp, etc) with a palisaded rampart","forms":["vallo"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Summis copiis castra oppugnata demonstrant, cum crebro integri defessis succederent nostrosque assiduo labore defatigarent, quibus propter magnitudinem castrorum perpetuo esset isdem in {{vallo}} permanendum.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vallum","latin":"vāllum, -ī","headword":"vāllum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"rampart; rampart, wall","forms":["vallum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Post eas aggerem ac {{vallum}} XII pedum exstruxit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vallus","latin":"vāllus, -ī","headword":"vāllus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"stake (for a palisade)","forms":["valle","vallōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"diret) in {{valle}} ad Ascram oppidum\"","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"valva","latin":"valva, valvae","headword":"valva","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"double or folding door (usu. pl.), one leaf of the doors","forms":["valvās","valvīs"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Prō {{valvīs}} rēgiae duās ārās aedificāvit, ūnam dextrā parte Hecatae et alteram sinistrā parte Iuventūtī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"valvae","latin":"valvae, -ārum","headword":"valvae","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"folding doors","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vanesco","latin":"vanesco, vanescere, -, -","headword":"vanesco","letter":"v","pos":"verb","posGroup":"verb","english":"vanish, fade, disappear","forms":["vānēscit"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"amor absēns (: absentis) {{vānēscit}} et","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vanitas","latin":"vanitas, vanitatis","headword":"vanitas","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"emptiness, untruthfulness; futility, foolishness, empty pride","forms":["vānitās"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Huic hominī nōn minor {{vānitās}} inerat quam audācia: neque reticēre quae audierat, neque suāmet ipse scelera occultāre; prōrsus neque dīcere neque facere quicquam pēnsī habēbat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vanus","latin":"vānus, -a, -um","headword":"vānus","letter":"v","pos":"adjective","posGroup":"adjective","english":"empty, useless, vain; void, meaningless, vain","forms":["vāna","vānam","vānīs","vānum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Orpheus gaudēns eam accipit sed cum hāc lēge Plūtōnis: nōn debet respicere Eurydicēn dōnec ingentem spēluncam Avernum exierit; aut dōnum erit {{vānum}}.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vapor","latin":"vapor, vaporis","headword":"vapor","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"steam/vapor; exhalation; heat/warmth (of sun); fever, body heat; excited state","forms":["vapōrēs"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Postquam verba Iūnōnis nūntiāvit, Īris prōtinus abiit, nam diūtius {{vapōrēs}}, quibus tōta spēlunca complēbātur, perferre nōn potuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vapulo","latin":"vapulo, vapulare, vapulavi, vapulatus","headword":"vapulo","letter":"v","pos":"verb","posGroup":"verb","english":"be beaten","forms":["vāpulā","vāpulābis","vāpulem"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: [Sōsiam pulsat] Nunc profectō vāpulā ob mendācium!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"varietas","latin":"varietās, -ātis ( f.)","headword":"varietās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"variety, diversity","forms":["varietāte"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eōque magis hoc eōs quibus eram cārus commovēbat, quod omnia sine remissiōne, sine {{varietāte}}, vī summā vōcis et tōtīus corporis contentiōne dīcēbam.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vario","latin":"vario, variare, variavi, variatus","headword":"vario","letter":"v","pos":"verb","posGroup":"verb","english":"mark with contrasting colors, variegate; vary, waver; fluctuate, change","forms":["variō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Sed īnfēlīx Dīdō noctem variō sermōne trahēbat, multa super Priamō rogitāns, super Hectore multa: 'Immo, age, et ā prīmā dīc, hospes, orīgine nōbīs īnsidiās' inquit 'Danaum cāsūsque tuōrum errōrēsque tuōs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"varius","latin":"varius, -a, -um","headword":"varius","letter":"v","pos":"adjective","posGroup":"adjective","english":"manifold, various; various, different","forms":["varia","variārum","variās","variē","variī","variis","variōrum","variōs","varium","varius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ac {{variis}} dictis sententiis, quarum pars deditionem, pars, dum vires suppeterent, eruptionem censebat, non praetereunda oratio Critognati videtur propter eius singularem et nefariam crudelitatem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"varus","latin":"varus, vara, varum","headword":"varus","letter":"v","pos":"adjective","posGroup":"adjective","english":"bent-outwards; bandy; bow-legged; contrasting","forms":["vari","Vārō"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Nec longē aberrāvit suspîciô mea: in vicem enim poenae vënit dēcrētum Trimalchiônis quô puerum iussit lîberum esse, ‘né quis posset dîcere tantum virum esse ā servô vulnerātum! ’ Comprobāmus nôs factum, et ‘quam in praecipitî rēs 55 hūmānae essent’ {{vari}}ô sermône gan-îmus.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vas","latin":"vās, vāsis","headword":"vās","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"(n.) (pl. vāsa, -ōrum) container","forms":["vāde","vās","vāsa","vāse","vāsī","vāsīs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tum Eliezer dēprōmpsit {{vās}} aurea et argentea, vestēsque pretiōsās, quās dēdit Rebeccae; obtulit etiam mūnera mātrī eius et frātrī, et iniērunt convīvium.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vastare","latin":"(vāstō) vāstāre","headword":"vāstāre","letter":"v","pos":"","posGroup":"other","english":"lay waste, ravage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vastitas","latin":"vastitas, vastitatis","headword":"vastitas","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"desolation; devastation","forms":["vastitātem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Nunc iam apertē rem pūblicam ūniversam petis, templa deōrum immortālium, tēcta urbis, vītam omnium cīvium, Ītaliam tōtam ad exitium et {{vastitātem}} vocās!","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vasto","latin":"vāstō (1)","headword":"vāstō","letter":"v","pos":"verb","posGroup":"verb","english":"destroy, lay waste","forms":["vastābat","vastābitur","vastandōs","vastantēs","vāstāre","vastāret","vāstātā","vāstātīs","vastātur","vāstāverat","vastāvisset","vastāvit","vastō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Erat in dēsertō spēluncā vastō recessū patēns: ibi Dāvīd cum suīs comitibus in interiōre parte latēbat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vastus","latin":"vāstus, -a, -um","headword":"vāstus","letter":"v","pos":"adjective","posGroup":"adjective","english":"desolate, vast, huge","forms":["vāsta","vastae","vastam","vāstās","vāstī","vastīs","vāstissimās","vastōs","vastum","Vastus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hebraeī, trāiectō marī Rubrō, diū peragrārunt {{vastam}} sōlitūdinem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vasum","latin":"vasum, vasi","headword":"vasum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"vessel/dish; vase; pack/kit; utensil/instrument/tool; equipment/apparatus (pl.)","forms":["vāsum"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"At ille sustulit phialam dē terrā: collîsa erat tamquam {{vāsum}} aēneum.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vates","latin":"vātēs, -is (m./f.)","headword":"vātēs","letter":"v","pos":"noun; noun (m.)","posGroup":"noun","english":"prophet(ess), seer; bard, poet, seer, singer; seer, prophet; prophet, poet","forms":["vāte","vātem","vātēs","vātī","vātum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"{{Vātēs}}, ā rēge interrogātus quid facere posset, ut civēs suōs tantīs malīs līberāret, eum hortātus est ut mōnstrō illī saevissimō Hēsionam fīliam offerret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vatis","latin":"vatis, vatis","headword":"vatis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"prophetess/ mouthpiece of deity; oracle/soothsayer; poetess (divinely inspired)","forms":["vātis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Necem {{vātis}} suī brevī ultus est Deus: Mānāssēs enim ab Assyriīs victus captusque est, et in vincula coniectūs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ve","latin":"-ve","headword":"ve","letter":"v","pos":"","posGroup":"other","english":"or (=vel)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"vecordia","latin":"vecordia, vecordiae","headword":"vecordia","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"frenzy","forms":["vēcordia"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Igitur color eī exsanguis, foedī oculī, citus modō, modo tardus incessus: prōrsus in faciē vultūque {{vēcordia}} inerat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vectigal","latin":"vectīgal, -ālis (n.)","headword":"vectīgal","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"tax; tax, revenue","forms":["vectīgal","vectīgālia","vectīgālibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Salomōn populō {{vectīgal}} gravissimum imposuerat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vectigalis","latin":"vectīgālis, -e","headword":"vectīgālis","letter":"v","pos":"adjective","posGroup":"adjective","english":"tax-paying, tributary","forms":["vectīgālēs"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Nam postquam rēs pūblica in paucōrum potentium iūs atque diciōnem concessit, semper illīs rēgēs, tetrarchae {{vectīgālēs}} esse, populī, nātiōnēs stīpendia pendēre — cēterī omnēs, strēnuī, bonī, nōbilēs atque ignōbilēs, vulgus fuimus sine grātiā, sine auctōritāte, eīs obnoxiī quibus, sī rēs pūblica valēret, formīdinī essēmus.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vectis","latin":"vectis, vectis","headword":"vectis","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"crowbar, lever","forms":["vectī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Prīmum in Thrāciam vectī sunt ibīque in lītore curvō novam urbem condere volēbant.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vecto","latin":"vecto, vectare, vectavi, vectatus","headword":"vecto","letter":"v","pos":"verb","posGroup":"verb","english":"transport, carry; (of habitual agent/means); (PASS) ride, be conveyed, travel","forms":["vectā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Flante validissimō ventō in altum montem est vectā; ibi etiam nunc saxum, in quod mūtāta est, lacrimāre nōn dēsinit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vehemens","latin":"vehemēns (gen. vehementis)","headword":"vehemēns","letter":"v","pos":"adjective","posGroup":"adjective","english":"violent, vigorous; violent, forceful","forms":["vehemēns","vehementem","vehementī","vehementissimē","vehementius"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Multum ad terrendos nostros valet clamor, qui post tergum pugnantibus exstitit, quod suum periculum in aliena vident salute constare; omnia enim plerumque quae absunt {{vehementius}} hominum mentes perturbant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vehementer","latin":"vehementer, vehementius, vehementissime","headword":"vehementer","letter":"v","pos":"adverb","posGroup":"adverb","english":"vehemently, vigorously; exceedingly, very much","forms":["vehementer"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Hi similitudine armorum {{vehementer}} nostros perterruerunt, ac, tametsi dextris umeris exsertis animadvertebantur, quod insigne pactum esse consuerat, tamen id ipsum sui fallendi causa milites ab hostibus factum existimabant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vehiculum","latin":"vehiculum, -ī","headword":"vehiculum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"wagon, vehicle; vehicle, carriage","forms":["vehiculō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Foedum inhūmānumque inde trāditur scelus: Tullia per patris corpus carpentum ēgisse fertur, partemque sanguinis ac caedis paternae cruentō vehiculō tulisse ad Penātēs suōs virīque suī!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vehit","latin":"vehit, vehunt","headword":"vehit","letter":"v","pos":"verb","posGroup":"verb","english":"carry, convey, ride, sail, travel; carries, conveys","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vehitur","latin":"vehitur","headword":"vehitur","letter":"v","pos":"verb","posGroup":"verb","english":"is carried, travels","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"veho","latin":"veho, vehere, vexi, vectus","headword":"veho","letter":"v","pos":"verb","posGroup":"verb","english":"bear, carry, convey; pass, ride, sail","forms":["vectae","vectōs","vectū","vectus","veham","vehat","vehēbantur","vehēbat","vehēbātur","vehendum","vehere","vehī","vehit","vehite","vehitur","vehō","vehunt","vehuntur","vēxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Iūlius, quī lectīcā {{vehitur}}, servōs videt fessōs et imperat: “Pōnite lectīcam in viā, servī!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vel","latin":"vel","headword":"vel","letter":"v","pos":"conjunction","posGroup":"conjunction","english":"or","forms":["vel"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Celeriter adulescentibus et oratione magistratus et praemio deductis, cum se {{vel}} principes eius consili fore profiterentur, ratio perficiendi quaerebatur, quod civitatem temere ad suscipiendum bellum adduci posse non confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"velamen","latin":"vēlāmen, -inis","headword":"vēlāmen","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"garment, covering, veil","forms":["vēlāmen","vēlāmina"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ubi fugit, {{vēlāmina}} relinquit quae leō ōre cruentō laniat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"velare","latin":"(vēlō) vēlāre","headword":"vēlāre","letter":"v","pos":"","posGroup":"other","english":"cover","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"velle","latin":"velle","headword":"velle","letter":"v","pos":"verb","posGroup":"verb","english":"to want","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vello","latin":"vello, vellere, velli, vulsus","headword":"vello","letter":"v","pos":"verb","posGroup":"verb","english":"pluck/pull/tear out; extract; pull hair/plants; uproot; depilate; demolish","forms":["vulsī","vulsum"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"rē-vellere -lisse -{{vulsum}} - abripere","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vellus","latin":"vellus, -eris","headword":"vellus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"fleece, wool; fleece","forms":["vellera","vellere","velleribus","velleris","vellus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum aureum eius {{vellus}} ad Colchidis rēgem portāvit, quī: “Cūrābō” inquit, “ut hoc vellus aureum in rāmō altissimae quercus pōnātur, quae in silvā prope rēgiam est.” Dracō vērō saevus, quī in silvā vīvēbat, circum arboris truncum sē volvēns vellus per multōs annōs cūstōdīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"velo","latin":"velo, velare, velavi, velatus","headword":"velo","letter":"v","pos":"verb","posGroup":"verb","english":"veil, cover, cover up; enfold, wrap, envelop; hide, conceal; clothe in","forms":["vēlāre","vēlat","vēlātīs","vēlātō","vēlō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sī nāvis, Minotaurō necātō, reveniat, vēlō albō nāviget; iuvenibus necātīs, vēlō ātrō.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"velociter","latin":"velociter, velocius, velocissime","headword":"velociter","letter":"v","pos":"adverb","posGroup":"adverb","english":"swiftly/rapidly, with speed of movement; quickly, in a short time","forms":["vēlōciter"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Tubae signum dedērunt: Atalanta et Hippomenēs tam {{vēlōciter}} currere coepērunt, ut eōrum pedēs vix terram tangere vidērentur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"velox","latin":"vēlōx","headword":"vēlōx","letter":"v","pos":"adjective","posGroup":"adjective","english":"(gen.vēlōcis) swift; swift, fast","forms":["vēlōcem","vēlōcēs","vēlōcior","vēlōcissima","vēlōcissimē","vēlōcissimōs","velōcius","vēlōx"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nec {{vēlōcior}} erat Alphēus: sed tandem Arethūsa tam fessa fuit, ut iam currere nōn posset.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"velum","latin":"vēlum, -ī","headword":"vēlum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"sail; cloth","forms":["vēla","vēlum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dnus autem d ē hīs latrōnibus, quī pendēbant, blasphēmābat eum, dīcēns:\"Sī tū es Chrīstus, salvā tē ipsum et nōs.\"Et alter ihcrepābat eum dīcēns:\"Neque tū timēs Deum?\"Et dīxit illī Jēsus:\"Hodiē mēcum eris in paradīsō.\"Et obscūrātus est sōl, et {{vēlum}} temp lī scissum est.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"velut","latin":"velut","headword":"velut","letter":"v","pos":"adverb","posGroup":"adverb","english":"as, as if","forms":["velut"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Perrēxit autem īre, {{velut}} leō quī dēscendit dē montibus; nūdus et sordidus tamque terribilis vīsū erat, ut puellae omnēs, cum prīmum eum cōnspexērunt, hūc et illūc fugerent animō turbātae.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"veluti","latin":"veluti","headword":"veluti","letter":"v","pos":"adverb","posGroup":"adverb","english":"just as, as if","forms":["velutī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Altera saxum iēcit, quod in aurā missum ipsā vōce et lyrā victum est et velutī supplex ante pedēs Orpheī iacuit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vena","latin":"vēna, -ae","headword":"vēna","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"vein","forms":["vēnae","vēnam","vēnās"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Iūlius: “Cum pēs aegrōtat, necesse nōn est {{vēnam}} bracchiī aperīre.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"venabulum","latin":"venabulum, venabuli","headword":"venabulum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"hunting-spear","forms":["vēnābula"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"rētia rāra, plagae, lātō {{vēnābula}} ferrō,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"venalis","latin":"vēnālis, -e","headword":"vēnālis","letter":"v","pos":"adjective","posGroup":"adjective","english":"for sale; for sale, venal","forms":["vēnālem","vēnālia"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Eā tempestāte exercitū nostrō fuēre complūrēs novī atque nōbilēs, quibus dīvitiae bonō honestōque potiōrēs erant, factiōsī domī, potentēs apud sociōs, clārī magis quam honestī; quī Iugurthae nōn mediocrem animum pollicitandō accendēbant, 'sī Micipsa rēx occidisset, fore utī sōlus imperiī Numidiae potīrētur: in ipsō maximam virtūtem, Rōmae omnia {{vēnālia}} esse!'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"venari","latin":"(vēnor) vēnārī","headword":"vēnārī","letter":"v","pos":"","posGroup":"other","english":"go hunting, hunt","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"venatio","latin":"venatio, venationis","headword":"venatio","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"hunting; the chase","forms":["vēnātiōne"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Isaacus, quī dēlectābātur {{vēnātiōne}}, amābat Esāüm; Iacobus vērō erat cārior Rebeccae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"venator","latin":"vēnātor, -ōris (m.)","headword":"vēnātor","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"hunter","forms":["vēnātor","vēnātōre","vēnātōrēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Ille fuit {{vēnātor}} strēnuus, hic autem placidus et simplex mōribus.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"venatrix","latin":"venatrix, venatricis","headword":"venatrix","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"huntress","forms":["vēnātrīx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Vīcit hērōs suem multīs cum comitibus, inter quōs erant Iāsōn et Pīrithous et virgō {{vēnātrīx}} Atalanta et hērōs Calydōnius, Meleager ipse.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vendere","latin":"vēndere","headword":"vēndere","letter":"v","pos":"verb","posGroup":"verb","english":"to sell","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vendit","latin":"vēndit, vēndunt","headword":"vēndit","letter":"v","pos":"verb","posGroup":"verb","english":"sell; sells","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vendo","latin":"vendo, vendere, vendidi, venditus","headword":"vendo","letter":"v","pos":"verb","posGroup":"verb","english":"sell","forms":["vēndam","vēndēbant","vendēbat","vendenda","vēndentēs","vēndere","vēnderent","vēnderet","vēndidistī","vēndidistis","vēndidit","vēndis","vēndit","vēndō","vēndunt"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Forum plēnum est virōrum et fēminārum quī emunt aut {{vēndunt}}, in hīs Flōra, puella fōrmōsa, quae rosās vēndit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"venenatus","latin":"venēnātus, -a, -um","headword":"venēnātus","letter":"v","pos":"adjective","posGroup":"adjective","english":"poisoned, poisonous; venomous, poisonous","forms":["venēnātās","venēnātīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Imperāvit quam plūrimās {{venēnātās}} serpentēs vīvās colligī eāsque in vāsa fictilia conicī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"veneno","latin":"veneno, venenare, venenavi, venenatus","headword":"veneno","letter":"v","pos":"verb","posGroup":"verb","english":"imbue or infect with poison; injure by slander","forms":["venēnō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Medea hanc iniūriam sine īrā nōn fert et fīliae rēgis vestīmenta magica et corōnam cum venēnō mīsit, quae ignāra fīlia induit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"venenum","latin":"venēnum, -ī","headword":"venēnum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"poison","forms":["venēna","venēnī","venēnum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Cum vērō dea haec vidēret: “Cave” inquit “hanc bēstiam Īnfīdam: nōn enim eam occīdēs, sī modo caput hastā petīverīs: in ventrem faciendus est tibi impetus!” Cadmus igitur magnam hastam in Īmum dracōnis ventrem tantā vī tantōque impetū mersit, ut bēstiam arborī fīgeret; quae, postquam multum venēnī per os effūdit, inter magnōs dolōrēs mortua est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"veneo","latin":"veneo, venire, venivi(ii), venitus","headword":"veneo","letter":"v","pos":"verb","posGroup":"verb","english":"go for sale, be sold (as slave), be disposed of for (dishonorable/venal) gain","forms":["vēneant","vēneunt"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"gum\") in Circō Màximo {{vēneunt}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"venerabilis","latin":"venerābilis, -e","headword":"venerābilis","letter":"v","pos":"adjective","posGroup":"adjective","english":"venerable, worthy of reverence","forms":["venerābile"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Nōn tamen ēversam Trōiae cum moenibus esse\nspem quoque fāta sinunt: sacra et, sacra altera, patrem\nfert umerīs, {{venerābile}} onus, Cythēreius hērōs.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"veneri","latin":"Veneri, (gen.), Veneriis","headword":"Veneri","letter":"v","pos":"adjective","posGroup":"adjective","english":"of/sacred to/devoted to Venus, Roman goddess of love; of sexual love; erotic","forms":["Venerī"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Est ager in parte optimā īnsulae Cyprī, quae est sacra deae Venerī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"venero","latin":"venero, venerare, veneravi, veneratus","headword":"venero","letter":"v","pos":"verb","posGroup":"verb","english":"adore, revere, do homage to, honor, venerate; worship; beg, pray, entreat","forms":["Veneres","vēnerō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Gaudēbō ego quoque et iūcundam vītam agam inter deōs, sī tēcum vēnerō.”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"veneror","latin":"veneror, -ārī, -ātus sum","headword":"veneror","letter":"v","pos":"verb","posGroup":"verb","english":"to revere, worship","forms":["venerābantur","venerārī","venerātī","veneror"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ecce manipulus meus surgēbat et stābat rēctus; vestrī autem manipulī circumstantēs {{venerābantur}} meum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"venia","latin":"venia, -ae","headword":"venia","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"favor, leave, pardon; pardon, favour","forms":["venia"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Datur petentibus {{venia}}, dissuadente primo Vercingetorige, post concedente et precibus ipsorum et misericordia vulgi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"venio","latin":"veniō, -īre, vēnī, ventum","headword":"veniō","letter":"v","pos":"verb","posGroup":"verb","english":"come","forms":["vēnerant","venerat","vēnerim","vēnerint","vēnerit","venerunt","venī","veniam","veniāmus","veniant","veniās","veniat","veniebant","veniēbat","veniendī","veniēns","venient","veniente","venientem","venientēs","venientī","venientium","veniēs","veniet","vēnimus","veniō","venire","venīrem","venīrēmus","venīrent","venīrēs","venīret","veniretur","veniri","venīs","vēnisse","vēnissem","venissent","vēnissēs","venisset","vēnistī","vēnistis","venit","venīte","venītis","venītōte","veniunt","ventura","ventūrae","ventūram","venturos","ventūrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere videbatur, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum {{venire}} posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"venire","latin":"(vēneō) vēnīre","headword":"vēnīre","letter":"v","pos":"","posGroup":"other","english":"be sold","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"venit","latin":"venit","headword":"venit","letter":"v","pos":"verb","posGroup":"verb","english":"come; comes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"venor","latin":"venor, venari, venatus sum","headword":"venor","letter":"v","pos":"verb","posGroup":"verb","english":"hunt","forms":["vēnābantur","vēnābātur","vēnandō","vēnandum","vēnantis","vēnāntum","vēnāre","vēnārī","vēnātō","vēnātum","vēnātur","vēnēr"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Esāüs itaque profectus est {{vēnātum}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"venter","latin":"venter, ventris","headword":"venter","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"(m.) stomach; belly, stomach","forms":["venter","ventre","ventrem","ventrī"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Is vīderat bēluam ūnam cēterīs maiōrem, ac phalerīs rēgis circumtēctam; exīstimāns illa rēgem vehī, sē prō communī saliite dēvōvit: per mediōs hostēs ad bēluam properāvit, sub illīus {{ventrem}} subiit, repefifīs ictibus cōnfossam occīdit, et bēluae lābentis pondere oppressus ipse occubuit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ventitare","latin":"(ventitō) ventitāre","headword":"ventitāre","letter":"v","pos":"verb","posGroup":"verb","english":"come frequently; to come often","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"ventito","latin":"ventito, ventitare, ventitavi, ventitatus","headword":"ventito","letter":"v","pos":"verb","posGroup":"verb","english":"keep coming; come regularly, come often; resort (to)","forms":["ventitātūrī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Āfricānus, hic Paulī fīlius, fēriīs Latīnīs Tūditānō cōnsule et Aquīliō, cōnstituisset in hortīs esse familiārissimīque eius ad eum frequenter per eōs diēs ventitātūrī sē esse dīxissent, Latīnīs ipsīs māne ad eum prīmus sorōris fīlius vēnit Q.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"ventus","latin":"ventus, -ī","headword":"ventus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"wind","forms":["uente","ventī","ventīs","ventō","ventōrum","ventōs","ventum","ventus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Eo cum esset {{ventum}}, exploratores hostium, ut omni fluminis parte erant dispositi, inopinantes, quod magna subito erat coorta tempestas, ab nostris opprimuntur; exercitus equitatusque equitibus Romanis administrantibus quos ei negotio praefecerat celeriter transmittitur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"venumdare","latin":"(vēnumdō) vēnumdare (< dare)","headword":"vēnumdare","letter":"v","pos":"verb","posGroup":"verb","english":"put up for sale; to sell","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"venumdo","latin":"venumdo, venumdare, venumdedi, venumdatus","headword":"venumdo","letter":"v","pos":"verb","posGroup":"verb","english":"sell; offer for sale","forms":["vēnumdarī","vēnumdatī"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"In antīquīs annalibus memoria super librīs Sibyllīnīs haec prōdita est: anus hospita atque incōgnita ad Tarquinium Superbum rēgem adiit novem librōs ferēns quōs esse dīcēbat dīvīna ōrācula: 'eōs velle vēnumdarī'.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"venus","latin":"Venus, Veneris","headword":"Venus","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"Venus (goddess of love)","forms":["vēnēre","venerem","vēnerīs","vēnus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hippomenēs igitur {{Venerem}}, amōris deam, invocāvit: “Ō Venus, adiuvā mē, et amōrem, quem tū dedistī, dēfende!” Audīvit Venus haec verba, quae ventus usque ad eius aurēs tulit; sine morā igitur ad auxilium ferendum dēscendit ex Olympō et ad Hippomenēm accessit; neque tamen quisquam alius eam vidēre poterat nisi Hippomenēs ipse.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"venuste","latin":"venuste, venustius, venustissime","headword":"venuste","letter":"v","pos":"adverb","posGroup":"adverb","english":"charmingly, attractively, gracefully; in a charming/attractive manner","forms":["venuste","venustius"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Haec si, inquam, attuleris, {{venuste}} noster,","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"venustus","latin":"venustus, -a, -um","headword":"venustus","letter":"v","pos":"adjective","posGroup":"adjective","english":"charming; charming, graceful","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vepris","latin":"vepris, vepris","headword":"vepris","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"thorn-bush","forms":["veprēs"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Abrahamus respexit, et vīdit arietem haerentem cornibus inter {{veprēs}}, quem immolāvit locō fīliī.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"ver","latin":"vēr, vēris","headword":"vēr","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"(n.) spring","forms":["vēr"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Apud lacum currēbat amoenum, quem pulcherrima silva cingēbat novīs foliīs modo vestīta; avēs canentēs {{vēr}} nūntiābant, et sōl clāra suā lūce omnia ita illūstrābat, ut nūllum perīculum puellīs lūdentibus impendēre vidērētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"verax","latin":"verax, veracis (gen.), veracior -or -us, veracissimus -a -um","headword":"verax","letter":"v","pos":"adjective","posGroup":"adjective","english":"speaking the truth, truthful (people); conveying the truth (things)","forms":["vērāx"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"[Aesōpus Latīnus, 78] Duo hominēs, ūnus fallāx, alter {{vērāx}}, simul iter agēbant, et vēnērunt in prōvinciam simiōrum.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"verba dare","latin":"(verba dō) verba dare","headword":"verba dare","letter":"v","pos":"","posGroup":"other","english":"deceive, cheat","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"verber","latin":"verber, verberis","headword":"verber","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"lash, whip; blows (pl.), a beating, flogging","forms":["verber","verbere","verberibus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Neque laudibus neque {{verberibus}} melior fierī potest.'","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"verbera","latin":"verbera, um","headword":"verbera","letter":"v","pos":"","posGroup":"other","english":"(n. pl.) a lashing","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"verberare","latin":"verberāre, -ō, -āvī, -ātum","headword":"verberāre","letter":"v","pos":"verb","posGroup":"verb","english":"to beat, whip","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"verberat","latin":"verberat","headword":"verberat","letter":"v","pos":"verb","posGroup":"verb","english":"beat, flog; beats, whips","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"verberatus","latin":"verberatus, verberatus","headword":"verberatus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"beating; chastisement (Vulgate)","forms":["verberātus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Mārcus dīcit sē bonum puerum fuisse et laudātum esse, quamquam puer improbus fuit et ā magistrō {{verberātus}} est.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"verbero","latin":"verbero, verberare, verberavi, verberatus","headword":"verbero","letter":"v","pos":"verb","posGroup":"verb","english":"beat, strike, lash","forms":["verberā","verberābō","verberāminī","verberāmur","verberandō","verberāre","verberārer","verberārī","verberās","verberat","verberātī","Verberātō","verberātum","verberāverat","verberāvit","verberem","verberet","verberō"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Cornēlius equum suum amat neque eum {{verberat}}; itaque equus nōn currit, sed ambulat.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"verbum","latin":"verbum, -ī","headword":"verbum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"word, verb; verb, word; word","forms":["verba","verbī","verbīs","verbō","verbōrum","verbum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nūllus dominus {{verba}} eius audit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vercingetorix","latin":"Vercingetorix, Vercingetorigis","headword":"Vercingetorix","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Vercingetorix; a Gaul (Avernian). led revolt against Caesar in 52 BC","forms":["Vercingetorige","Vercingetorigem","Vercingetorigi","Vercingetorigis","Vercingetorix"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Simili ratione ibi {{Vercingetorix}}, Celtilli filius, Arvernus, summae potentiae adulescens, cuius pater principatum Galliae totius obtinuerat et ob eam causam, quod regnum appetebat, ab civitate erat interfectus, convocatis suis clientibus facile incendit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vere","latin":"vere, verius, verissime","headword":"vere","letter":"v","pos":"adverb","posGroup":"adverb","english":"really, truly, actually, indeed; rightly, correctly, exactly; truthfully","forms":["vērē"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Mārcus: “Saepe ita dīcit pater — et vērē dīcit.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"verendum","latin":"verendum, verendi","headword":"verendum","letter":"v","pos":"noun","posGroup":"noun","english":"external sexual organs, private parts (pl.); [partes ~ae => private parts]","forms":["verendum"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sī tē iam, Catilīna, comprehendī, sī interficī iusserō, crēdō, erit {{verendum}} mihi nē nōn potius hoc omnēs bonī ‘sērius’ ā mē quam quisquam ‘crūdēlius’ factum esse dīcat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vereor","latin":"vereor","headword":"vereor","letter":"v","pos":"verb","posGroup":"verb","english":"fear (deponent)","forms":["vereantur","verēbantur","verēbātur","verēbere","verēminī","verēmur","verendōs","verēns","verentur","vereor","verērentur","verērī","verēris","verētur","veriti","veritos","veritus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Qui cum ad flumen Ligerim venissent, quod Bituriges ab Aeduis dividit, paucos dies ibi morati neque flumen transire ausi domum revertuntur legatisque nostris renuntiant se Biturigum perfidiam {{veritos}} revertisse, quibus id consili fuisse cognoverint ut, si flumen transissent, una ex parte ipsi, altera Arverni se circumsisterent.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vereri","latin":"verērī","headword":"verērī","letter":"v","pos":"verb","posGroup":"verb","english":"to fear, respect; to fear, be afraid of; to fear, be afraid","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"veretur","latin":"verētur, verērī","headword":"verētur","letter":"v","pos":"","posGroup":"other","english":"fear","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"vergere","latin":"(vergō) vergere","headword":"vergere","letter":"v","pos":"","posGroup":"other","english":"slope, point, turn","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vergilius","latin":"Vergilius, Vergili","headword":"Vergilius","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Virgil; (Roman gens name); [P. Vergilius Maro => poet Virgil 70-19 BC]","forms":["Vergiliī","Vergiliō","Vergilius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Interim puer Alexandrînus, quī caldam ministrābat, lusciniās coepit imitärî, clāmante Trimalchiône subinde: Ecce alius lūdus: servus quī ad pedēs Habinnae sēdë- bat, iussus, crëdô, ā dominô suô, prôclämävit subitô Nūllus sonus umquam acidior percussit aurēs meâs, tunc prîmum mē etiam {{Vergilius}} offenderit!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vergo","latin":"vergo, vergere, -, -","headword":"vergo","letter":"v","pos":"verb","posGroup":"verb","english":"incline, lie, slope","forms":["vergēns","vergente","vergunt"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Angulus mūrī erat in plāniōrem patentiorēmque vallem {{vergēns}}; adversus eum vīneās agere īnstituit, per quās ariēs moenibus admovērī posset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"veritas","latin":"veritas, veritatis","headword":"veritas","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"truth, fact, accuracy; honesty, truthfulness, frankness; sincerity, uprightness","forms":["vēritātem","vēritātis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Rēx autem ut explōrāret latentem {{vēritātem}}: “Dīvidātur” inquit “puer dē quō contrōversia est, et pars ūna ūnī mulierī, altera alterī dētur.” Iūdiciō assēnsa est falsa māter; altera vērō exclāmāvit: “Nē, quaesō, nē occīdātur puer, ō rēx: mālō ista tōtum habeat.” Tunc rēx ait: “Rēs est manifēsta: haec vērē est māter puerī.” Et huic illum adiūdicāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"veritate","latin":"veritate","headword":"veritate","letter":"v","pos":"adverb","posGroup":"adverb","english":"in point of fact; actually","forms":["vēritāte"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Et interrogāvērunt eum dīcentēs: “Magister, scīmus quia rēctē dīcis et docēs, et nōn accipis persōnam, sed viam Deī in {{vēritāte}} docēs: licet nōbīs dare tribūtum Caesarī an nōn?” Cōnsīderāns autem dolum illōrum dīxit ad eōs: “Quid mē temptātis?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"vermis","latin":"vermis, vermis","headword":"vermis","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"worm, maggot","forms":["vermibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"At illum subitus vīscerum dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta scatērent {{vermibus}}, et foetōrem lātē ēmitterent, exercituī et aegrō ipsī intolerābilem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vernaculus","latin":"vernaculus, vernacula, vernaculum","headword":"vernaculus","letter":"v","pos":"adjective","posGroup":"adjective","english":"domestic, homegrown; indigenous, native; country; low-bred, proletarian","forms":["vernāculae"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"(dîvitiae) octingenta mîlia sēstertium Incubô -ônis m, deus cüstôs thêsauﬂ occultî, quī pilleô nôn male (: bene) sibi vult lîbertînî locus: medius in îmô sēstertium deciēs centêna capillôs lîberôs : quicquam ipsô melior z melior quam ille ad sé fēcērunt : suā tëcêrunt gôtium est ﬁmera apparāre .”‘“ {{vernāculae}} quae sunt meliusculae ā Graeculîs citās: nūlla nôn aut cōn- “Rē1iquôs autem collîbertôs eius cavē contemnās!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vero","latin":"vērō","headword":"vērō","letter":"v","pos":"adverb","posGroup":"adverb","english":"really, however, but","forms":["vero"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Tamen, quod instituto Caesaris semper duae legiones pro castris excubabant pluresque partitis temporibus erant in opere, celeriter factum est ut alii eruptionibus resisterent, alii turres reducerent aggeremque interscinderent, omnis {{vero}} ex castris multitudo ad restinguendum concurreret.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"verro","latin":"verro, verrere, verri, versus","headword":"verro","letter":"v","pos":"verb","posGroup":"verb","english":"sweep clean; sweep together; sweep (to the ground); skim, sweep; sweep along","forms":["verrunt"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"adnīxī torquent spūmās et caerula {{verrunt}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"versare","latin":"(versō) versāre","headword":"versāre","letter":"v","pos":"","posGroup":"other","english":"turn over, ponder","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"versari","latin":"(versor) versārī, versātum","headword":"versārī","letter":"v","pos":"","posGroup":"other","english":"move about, be present","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"versiculus","latin":"versiculus, -ī","headword":"versiculus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"a little line of verse (diminuitive of versus, -ūs); little verse","forms":["versiculōs"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"{{Versiculos}} in me narratur scribere Cinna.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"versipellis","latin":"versipellis, versipellis","headword":"versipellis","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"shape-changer, who can metamorphose to different shape; double-dealer (Vulgate)","forms":["versipellem"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"“Intellëxî illum {{versipellem}} esse, nec posteā cum illô pānem gustāre potuî, nôn sî mē occîdissës!","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"verso","latin":"verso, versare, versavi, versatus","headword":"verso","letter":"v","pos":"verb","posGroup":"verb","english":"keep turning/going round, spin, whirl; turn over and over; stir; maneuver","forms":["versābantur","versābar","versābat","versāmur","versantī","versantur","versāre","versārer","versārētur","versari","versārīs","versat","versātur","versātus","versēmur","verser"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Eporedorigem et Viridomarum, quos illi interfectos existimabant, inter equites {{versari}} suosque appellare iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"versum","latin":"versum","headword":"versum","letter":"v","pos":"adverb","posGroup":"adverb","english":"toward, in the direction of; in specified direction; towards quarter named","forms":["versum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ego cūnās recessim rūrsum {{versum}} trahere et dūcere,","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"versus","latin":"versus, versūs","headword":"versus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"line, verse","forms":["versibus","versus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Dimittit quoque {{versus}} legationes; obtestatur ut in fide maneant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vertere","latin":"vertere","headword":"vertere","letter":"v","pos":"verb","posGroup":"verb","english":"to turn","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vertex","latin":"vertex, -icis (m.)","headword":"vertex","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"whirlpool, peak, pole; whirlpool; summit; summit, peak","forms":["vertex","vertice","verticem","verticēs","verticibus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Samsōn mediā nocte surrēxit, vēnitque ad portam urbis, quam cum invēnisset clausam, umerīs sustulit cum postibus et serīs, atque in {{verticem}} montis vicīnī supportāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vertit","latin":"vertit, vertunt","headword":"vertit","letter":"v","pos":"verb","posGroup":"verb","english":"turn; turns","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"verto","latin":"vertō, -ere, vertī, versum","headword":"vertō","letter":"v","pos":"verb","posGroup":"verb","english":"turn, overturn","forms":["versa","versās","versī","versīs","versu","vertant","vertātur","Verte","vertēbantur","vertēns","Vertentibus","vertere","verterent","verterēs","verteret","verterunt","vertī","vertis","vertisse","vertit","vertitur","vertunt","vertuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hostes terga {{verterunt}}; fugientibus equites occurrunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"verum","latin":"vērum","headword":"vērum","letter":"v","pos":"conjunction","posGroup":"conjunction","english":"but; but, however","forms":["vērum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Dōrippa: “Id quod {{vērum}} est.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"verumtamen","latin":"verumtamen","headword":"verumtamen","letter":"v","pos":"conjunction","posGroup":"conjunction","english":"but yet, nevertheless, but even so, still (resuming after digression)","forms":["vērumtamen"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et ipse āvulsus ē s t ab iīs quantum ē s t ī āctus lapidī s: et posifīs genibus, ōrābat dīcēns:\"Pater, sī vīs, trānsfer calicem istum ā mē; {{vērumtamen}} nōn mea voluntās, sed tua fīat.\"Et ecce sūdor eius, sīcut guttae sanguinis, dēcurrit in terram.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"verus","latin":"vērus, -a, -um","headword":"vērus","letter":"v","pos":"adjective","posGroup":"adjective","english":"true, n. truth; true","forms":["uere","vēra","vērae","vēram","vērās","vērī","vērīs","vērissima","vērissimē","vērius","vērōs","vērus"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Aspice Mēdum: is est vir probus atque {{vērus}} amīcus, quī amīcam suam nōn relinquit.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vesanus","latin":"vesanus, vesana, vesanum","headword":"vesanus","letter":"v","pos":"adjective","posGroup":"adjective","english":"mad, frenzied; wild","forms":["vēsānīs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec cavā {{vēsānīs}} ictibus āera sonant,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vesci","latin":"(vescor) vescī","headword":"vescī","letter":"v","pos":"","posGroup":"other","english":"feed on, eat (+ abl.)","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vescor","latin":"vescor, vesci, -","headword":"vescor","letter":"v","pos":"verb","posGroup":"verb","english":"feed on, eat, enjoy (with ABL)","forms":["vēscitur"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Mōnstrum īnfandum est Cyclōps ille nōmine Polyphēmus, quī carne et sanguine hominum miserōrum {{vēscitur}}!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vespasianus","latin":"Vespasianus, Vespasiani","headword":"Vespasianus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Vespasian; (Tiberius Flavius Vespasianus, Emperor, 69-79 AD)","forms":["Vespasiānī","Vespasiānus"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Īnfrā Capitōlium iūxtā Tabulārium sunt aedēs Concordiae et Dīvī Vespasiānī.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vesper","latin":"vesper, vesperī","headword":"vesper","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"evening","forms":["vesper","Vespere","vesperō","vesperum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sub {{vesperum}} consilio convocato, cohortatus ut ea quae imperasset diligenter industrieque administrarent, naves quas Metiosedo deduxerat singulas equitibus Romanis attribuit et prima confecta vigilia IIII milia passuum secundo flumine silentio progredi ibique se exspectari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vesperi","latin":"vesperi","headword":"vesperi","letter":"v","pos":"adverb","posGroup":"adverb","english":"in the evening","forms":["vesperī"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[{"latin":"Merīdiē in sōle ambulāre mē nōn dēlectat, sed vesperī āēr nec nimis calidus nec nimis frīgidus est.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vesta","latin":"Vesta, Vestae","headword":"Vesta","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"Vesta; (goddess of flocks/herds and of hearth/household)","forms":["Vesta","Vestae"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In contrāriā forī parte est aedēs {{Vestae}} antīquissima, quae fōrmam habet rotundam, nōn quadrātam.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vestalis","latin":"Vestalis, Vestalis, Vestale","headword":"Vestalis","letter":"v","pos":"adjective","posGroup":"adjective","english":"Vestal, of Vesta; (festival 9 June)","forms":["Vestālem","Vestālēs","Vestālis","Vestālium"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Sex virginēs {{Vestālēs}} ex fīliābus Rōmānōrum illūstrium ēlēctae dīligenter cūrant nē ignis Vestae umquam exstinguātur, namque ignis ille semper ardēns Rōmam urbem aeternam esse significat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vester","latin":"vester, -tra, -trum","headword":"vester","letter":"v","pos":"adjective","posGroup":"adjective","english":"your, yours","forms":["vester","vestra","vestrae","vestram","vestrās","vestrī","vestrīs","vestro","vestrōrum","vestrōs","vestrum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine {{vestro}} sanguine tantum exercitum victorem fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vestiarius","latin":"vestiarius, vestiari(i)","headword":"vestiarius","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"clothes dealer","forms":["vestiārius"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tamen calda pôtiô {{vestiārius}} est.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vestibulum","latin":"vestibulum, ī","headword":"vestibulum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"forecourt","forms":["vestibulō"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"In vestibulō stābat ingēns statua tyrannī ex aere facta, quae Colossus appellābātur.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vestigium","latin":"vestīgium, -ī","headword":"vestīgium","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"footprint, trace; trace, footprint; track, footstep","forms":["vestīgia","vestīgiīs","vestīgiō","vestīgium"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Rūfus: “Sed {{vestīgia}} ovium tuārum in hortō meō sunt.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vestimentum","latin":"vestīmentum, -ī","headword":"vestīmentum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"garment, clothing; garment, clothes","forms":["vestīmenta","vestīmentīs","vestīmentō","vestīmentum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Itaque mātrī ōrnāmenta et {{vestīmenta}} pulchra largītur.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vestio","latin":"vestio, vestire, vestivi, vestitus","headword":"vestio","letter":"v","pos":"verb","posGroup":"verb","english":"clothe","forms":["Vestiam","vestīre","vestīrent","vestit","vestīta","vestītae","vestītam","vestītī","vestītum","vestiuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Hae revinciuntur introrsus et multo aggere {{vestiuntur}}; ea autem quae diximus intervalla grandibus in fronte saxis effarciuntur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vestis","latin":"vestis, vestis","headword":"vestis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) clothes, cloth; garment, clothes","forms":["veste","vestem","vestēs","Vestī","vestibus","vestis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Matres familiae de muro {{vestem}} argentumque iactabant, et pectore nudo prominentes passis manibus obtestabantur Romanos ut sibi parcerent neu, sicut Avarici fecissent, ne a mulieribus quidem atque infantibus abstinerent; non nullae de muro per manus demissae sese militibus tradebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vestit","latin":"vestit, vestīre","headword":"vestit","letter":"v","pos":"verb","posGroup":"verb","english":"dress; dresses (someone)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vestitus","latin":"vestitus, vestitus","headword":"vestitus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"clothing","forms":["vestitus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Eius adventu ex colore {{vestitus}} cognito, quo insigni in proeliis uti consuerat, turmisque equitum et cohortibus visis quas se sequi iusserat, ut de locis superioribus haec declivia et devexa cernebantur, hostes proelium committunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vetare","latin":"(vetō) vetāre, vetuisse, vetitum","headword":"vetāre","letter":"v","pos":"verb","posGroup":"verb","english":"forbid; to forbid","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"veter","latin":"veter, vetera, veterum","headword":"veter","letter":"v","pos":"adjective","posGroup":"adjective","english":"old; long established; veteran, bygone; chronic","forms":["veter"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{veter}}és litterās ē tabellā dēlēre céra tuae prīmum cōnscia","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"veteranus","latin":"veteranus, veterana, veteranum","headword":"veteranus","letter":"v","pos":"adjective","posGroup":"adjective","english":"old, veteran","forms":["veterānās","Veterānī"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Ille cohortēs {{veterānās}}, quās tumultus causā cōnscrīpserat, in fronte, post eās cēterum exercitum in subsidiīs locat.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"veto","latin":"vetō, -āre, vetuī, vetitum","headword":"vetō","letter":"v","pos":"verb","posGroup":"verb","english":"forbid, prohibit","forms":["Veta","vetābat","vetāmus","vetant","vetante","vetāre","vetarent","vetāret","vetat","vetere","veteris","vetitī","vetitō","vetitum","vetō","vetor","vetueram","vetuerat","vetuērunt","vetuit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia vivo utroque non solum magistratus creari {{vetarent}} sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vetulus","latin":"vetulus, vetula, vetulum","headword":"vetulus","letter":"v","pos":"adjective","posGroup":"adjective","english":"elderly, aging","forms":["vetulus"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Hinc, involūtus coccinā gausapā, lectīcae impositus est, praecēdentibus phalerātis cursôribus quattuor et chîra- maxiô in quô dēliciae eius vehēbantur, puer {{vetulus}}, lippus, dominô Trimalchī- ône dëfôrmior.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vetus","latin":"vetus","headword":"vetus","letter":"v","pos":"adjective","posGroup":"adjective","english":"(gen.veteris) old","forms":["vetera","veterem","veterēs","veteribus","veterrima","veterrimus","veterum","vetus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Postremo in acie praestare interfici quam non {{veterem}} belli gloriam libertatemque quam a maioribus acceperint reciperare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vetustas","latin":"vetustās, -ātis ( f.)","headword":"vetustās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"age, old age, long existence","forms":["vetustās","vetustāte"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"uitur {{vetustās}} (: redditur iuventūs)","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vetustus","latin":"vetustus, -a, -um","headword":"vetustus","letter":"v","pos":"adjective","posGroup":"adjective","english":"ancient, old","forms":["vetustum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Is Numitōrem atque Amūlium prōcreat; Numitōrī, quī fīlius māior erat, rēgnum {{vetustum}} Silviae gentis lēgat.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vexare","latin":"(vexō) vexāre","headword":"vexāre","letter":"v","pos":"","posGroup":"other","english":"harass, trouble, ravage","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vexatio","latin":"vexatio, vexationis","headword":"vexatio","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"shaking, jolting; shock; disturbance, upheaval","forms":["vexātiō"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Quae tēcum, Catilīna, sīc agit et quōdam modo tacita loquitur: ‘Nūllum iam aliquot annīs facinus exstitit nisi per tē, nūllum flāgitium sine tē; tibi ūnī multōrum cīvium necēs, tibi vexātiō dīreptiōque sociōrum impūnīta fuit ac lībera; tū nōn sōlum ad neglegendās lēgēs et quaestiōnēs, vērum etiam ad ēvertendās perfringendāsque valuistī.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vexillum","latin":"vexillum, -ī","headword":"vexillum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"standard, ensign","forms":["vexillum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"'Nōn possum fideī causā imāginēs neque triumphōs aut cōnsulātūs maiōrum meōrum ostentāre — at, sī rēs postulet, hastās, {{vexillum}}, phalerās, alia mīlitāria dōna, praetereā cicātrīcēs adversō corpore!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vexo","latin":"vexo, vexare, vexavi, vexatus","headword":"vexo","letter":"v","pos":"verb","posGroup":"verb","english":"shake, jolt, toss violently; annoy, trouble, harass, plague, disturb, vex","forms":["vexābant","vexābat","vexābuntur","vexant","vexāre","vexātī","vexātus","vexāvit"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hebraeī ā Madianitīs vexātī opem ā Deō petīvērunt: Deus illōrum precēs audīvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"via","latin":"via, -ae","headword":"via","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"road, way, street; road, way; road, street; street, road","forms":["via","viae","viam","viārum","viās","viis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Etsi mons Cevenna, qui Arvernos ab Helviis discludit, durissimo tempore anni, altissima nive iter impediebat, tamen discussa nive sex in altitudinem pedum atque ita {{viis}} patefactis summo militum sudore ad fines Arvernorum pervenit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"viaticum","latin":"viāticum, -ī","headword":"viāticum","letter":"v","pos":"","posGroup":"other","english":"provision for a journey","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vibro","latin":"vibro, vibrare, vibravi, vibratus","headword":"vibro","letter":"v","pos":"verb","posGroup":"verb","english":"brandish, wave, crimp, corrugate; rock; propel suddenly; flash; dart; glitter","forms":["vibrā","vibrāns","vibrantia"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Tūne ante aciem Ilidaēōrum vīsus est eques veste candidā, armīs aureīs indūtus, hastam {{vibrāns}}.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vicesimus","latin":"vīcēsimus, -a, -um","headword":"vīcēsimus","letter":"v","pos":"","posGroup":"other","english":"twentieth","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vicinitas","latin":"vīcīnitās, -ātis ( f.)","headword":"vīcīnitās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"neighborhood, vicinity","forms":["vīcīnitātem"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Flāminium in agrō Ārrētīnō, dum {{vīcīnitātem}} anteā sollicitātam armīs exōrnat, cum fascibus atque aliīs imperī īnsignibus in castra ad Mānlium contendit.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"vicinum","latin":"vicinum, vicini","headword":"vicinum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"neighborhood, neighboring place, vicinity (of )","forms":["vīcīnum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Manibus ad caelum tentīs, hōc modō ōrat: \"Dā veniam, pater benignē, peccāvimus, sed remitte damnōsum dōnum.\" Bacchus benignus inquit: \"Ī ad flūmen {{vīcīnum}} Sardibus et carpe viam in montēs Lydiae ūsque ad ortum flūminis.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vicinus","latin":"vīcīnus, -a, -um","headword":"vīcīnus","letter":"v","pos":"adjective","posGroup":"adjective","english":"neighboring; neighboring, near (to) (+ dat.)","forms":["vīcīna","vīcīnae","vīcīnam","vīcīnās","vicīnī","vīcīnō","vīcīnōs","vīcīnus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"At Samsōn mediā nocte surrēxit, vēnitque ad portam urbis, quam cum invēnisset clausam, umerīs sustulit cum postibus et serīs, atque in verticem montis vicīnī supportāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vicis","latin":"vicis, vicis","headword":"vicis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"turn, change, succession; exchange, interchange, repayment; plight, lot","forms":["vicem","vicibus","vicis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus {{vicis}} adacto extremam famem sustentarent, nulla tamen vox est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vicissim","latin":"vicissim","headword":"vicissim","letter":"v","pos":"adverb","posGroup":"adverb","english":"in turn","forms":["vicissim"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Quōs cum omnēs salūtāvisset, convertit sē in porticū et coniēcit in medium Laelium (fuit enim hoc in amīcitiā quasi quoddam iūs inter illōs, ut mīlitiae propter eximiam bellī glōriam Āfricānum ut deum coleret Laelius, domī {{vicissim}} Laelium, quod aetāte antecēdēbat, observāret in parentis locō Scīpiō).","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"victima","latin":"victima, -ae","headword":"victima","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"victim (sacrificial)","forms":["victimā","victimam","victimārum","victimās","victimīs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Iam egō hanc {{victimam}} Mānibus peremptōrum foedē cīvium dabō!' subditīsque calcāribus equō per cōnfertissimam hostium turbam impetum facit cōnsulemque lanceā trānsfīxit!","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"victor","latin":"victor, victōris","headword":"victor","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"(m.) victor","forms":["victor","victōre","victorem","victōrēs","victōrī","victōribus","VICTORIBVS","victōris","victorum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"'Haec,' inquit, 'a me,' Vercingetorix, 'beneficia habetis, quem proditionis insimulatis; cuius opera sine vestro sanguine tantum exercitum {{victorem}} fame consumptum videtis; quem turpiter se ex fuga recipientem ne qua civitas suis finibus recipiat a me provisum est.'","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"victoria","latin":"victōria, -ae","headword":"victōria","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"victory","forms":["victoria","victoriae","victoriam","victoriis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hoc idem fit in reliquis civitatibus; in omnibus partibus incendia conspiciuntur; quae etsi magno cum dolore omnes ferebant, tamen hoc sibi solaci proponebant, quod se prope explorata {{victoria}} celeriter amissa reciperaturos confidebant.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"victrix","latin":"victrīx, -īcis ( f.)","headword":"victrīx","letter":"v","pos":"adjective","posGroup":"adjective","english":"femal conqueror (she who is) victorious","forms":["victrīcī","victrīcia","victrīx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Bella gerunt,\ntandemque Venus {{victrīcia}} nātī\narma videt, Turnusque cadit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"victus","latin":"victus, victus","headword":"victus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"living, way of life; that which sustains life; nourishment; provisions; diet","forms":["victus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tandem {{victus}} pater annuit: quoniam necesse est, inquit, proficīscātur Beniamīnus vōbīscum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vicus","latin":"vīcus, ī","headword":"vīcus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"street, village","forms":["vicos","vīcum","vīcus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praeterea salutis causa rei familiaris commoda neglegenda: {{vicos}} atque aedificia incendi oportere hoc spatio ab via quoqueversus quo pabulandi causa adire posse videantur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"videlicet","latin":"vidēlicet","headword":"vidēlicet","letter":"v","pos":"adverb","posGroup":"adverb","english":"evidently, of course","forms":["vidēlicet"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"Hostium cēpī bīna castra — praedae {{vidēlicet}} plēna et commeātuum —: frūmentum et pecūniam date!\" Quid aliud, sī spoliātus, sī exūtus castrīs essēs, peterēs?","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"video","latin":"videō, -ēre, vīdī, vīsum","headword":"videō","letter":"v","pos":"verb","posGroup":"verb","english":"see","forms":["vidē","videam","videāminī","videāmur","videāmus","videant","videantur","videar","videāre","videāris","videās","videat","videātis","videatur","vidēbam","vidēbant","videbantur","vidēbās","videbat","vidēbātis","videbatur","vidēbimur","vidēbis","vidēbit","vidēbitis","vidēbitur","vidēbō","vidēbor","vidēbunt","vidēminī","vidēmur","vidēmus","videnda","videndae","videndam","videndī","videndum","videndus","vidēns","vident","videntēs","videntur","videō","videor","vīderam","vīderant","vīderat","vidēre","viderem","viderent","viderentur","vidērer","vidērēs","videret","vidērētis","videretur","vidērī","vīderint","vidēris","vīderit","vīderitis","vīderō","viderunt","vidēs","videt","vidēte","videtis","vidētō","videtur","vīdī","vīdimus","vīdisse","vīdissem","vīdissent","vīdissēs","vidisset","vīdistī","vīdistis","vīdit","vīsae","vīsōs","vīsū","vīsūrōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Addunt ipsi et adfingunt rumoribus Galli, quod res poscere {{videbatur}}, retineri urbano motu Caesarem neque in tantis dissensionibus ad exercitum venire posse.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"videri","latin":"(videor) vidērī, vīsum","headword":"vidērī","letter":"v","pos":"","posGroup":"other","english":"be seen, seem","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"videt","latin":"videt","headword":"videt","letter":"v","pos":"verb","posGroup":"verb","english":"see; sees","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"videtur","latin":"vidētur","headword":"vidētur","letter":"v","pos":"verb","posGroup":"verb","english":"he, she, it seems","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vidua","latin":"vidua, -ae","headword":"vidua","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"widow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[]},{"id":"viduo","latin":"viduo, viduare, viduavi, viduatus","headword":"viduo","letter":"v","pos":"verb","posGroup":"verb","english":"widow; bereave of a husband","forms":["vidua"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Cum autem appropinquāret portae cīvitātis ecce defiīnctus efferēbātur fīlius ūnicus mulieris quae {{vidua}} erat.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"viduus","latin":"viduus, vidua, viduum","headword":"viduus","letter":"v","pos":"adjective","posGroup":"adjective","english":"widowed, deprived of (with gen.); bereft; unmarried","forms":["viduae","viduam","viduōs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"cum iūvit {{viduōs}} rapta Sabīna virōs.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vigeo","latin":"vigeo, vigere, -, -","headword":"vigeo","letter":"v","pos":"verb","posGroup":"verb","english":"be strong/vigorous; thrive, flourish, bloom/blossom; be active, be effective","forms":["vigēbant","vigēre","viget"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quam virtūtem eius et Catō, vir prōmptioris ad vituperandum linguae, in senātū sīc prōsecūtus est ut dīceret 'reliquōs quī in Āfricā mīlitārent umbrās volitāre, Scīpiōnem {{vigēre}}.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vigere","latin":"(vigeō) vigēre, -uisse","headword":"vigēre","letter":"v","pos":"","posGroup":"other","english":"be vigorous","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vigesco","latin":"vigesco, vigescere, vigui, -","headword":"vigesco","letter":"v","pos":"verb","posGroup":"verb","english":"acquire strength","forms":["viguit"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Inter cētera iuvenālia opera quae ad ultimum ēdidit, adeō etiam nervīs in senectā {{viguit}} ut post sextum et octōgēsimum annum fīlium genuerit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vigil","latin":"vigil (gen. vigilis)","headword":"vigil","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"wakeful, watchful","forms":["vigil","vigilem","vigilēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"rum explōrātum ībat noctū ({{vigil}}) tentōrium","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vigilans","latin":"vigilans, vigilantis (gen.), vigilantior -or -us, vigilantissimus -a -um","headword":"vigilans","letter":"v","pos":"adjective","posGroup":"adjective","english":"watchful, vigilant, alert; wakeful, wide awake (of watchkeeper)","forms":["vigilāns","vigilantem","vigilantēs","vigilantiōrēs","vigilantius"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Pāstōrēs erant in regiōne eādem {{vigilantēs}} aut cūstōdientēs gregem suum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vigilare","latin":"vigilāre","headword":"vigilāre","letter":"v","pos":"verb","posGroup":"verb","english":"stay awake","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vigilat","latin":"vigilat, vigilāre","headword":"vigilat","letter":"v","pos":"verb","posGroup":"verb","english":"be awake; is awake, keeps watch; is awake, stays awake","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vigilia","latin":"vigilia, -ae","headword":"vigilia","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"night watch; watch (of the night)","forms":["vigilia","vigiliae","vigiliam","vigiliās","vigiliīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nam quae Cenabi oriente sole gesta essent ante primam confectam {{vigiliam}} in finibus Arvernorum audita sunt, quod spatium est milium passuum circiter centum LX.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vigilo","latin":"vigilo, vigilare, vigilavi, vigilatus","headword":"vigilo","letter":"v","pos":"verb","posGroup":"verb","english":"remain awake, be awake; watch; provide for, care for by watching, be vigilant","forms":["vigilābō","Vigilāmus","vigilandō","vigilāre","vigilat","vigilāta","vigilātae","vigilāte","vigilātum","vigilāvī","vigilō"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Bracchium quoque dolet Quīntō; itaque is nōn dormit, sed {{vigilat}}.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"viginti","latin":"vīgintī","headword":"vīgintī","letter":"v","pos":"numeral","posGroup":"numeral","english":"twenty","forms":["vīcēsimam","vīcēsimō","vīcēsimum","viginti"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His litteris cognitis Romae dierum {{viginti}} supplicatio redditur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vigor","latin":"vigor, -ōris (m.)","headword":"vigor","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"vigor; liveliness, force, vigor","forms":["vigor","vigōrem","vigōris"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Imāgō iterum fugitāvit; amor corpus iuvenis dēvorāvit; neque {{vigor}}, neque color, neque fōrma mānsit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vilica","latin":"vilica, vilicae","headword":"vilica","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"wife of a farm overseer","forms":["Vīlicae"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Vīlicae}} quae sunt officia, cūrātō faciat!","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"vilicus","latin":"vilicus, vilici","headword":"vilicus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"farm overseer (slave/free), estate manager; grade of imperial/public servant","forms":["vīlicī","vīlicum","vīlicus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Ubi cognōvit, quō modō fundus cultus siet operaque quae facta īnfectaque sient, postrīdiē eius diēī {{vīlicum}} vocet, roget ‘quid operis siet factum, quid restet? satisne temperī opera sient cōnfecta? possitne quae reliqua sient cōnficere? et quid factum vīnī, frūmentī?’ aliārumque rērum omnium.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"vilis","latin":"vīlis, -e","headword":"vīlis","letter":"v","pos":"adjective","posGroup":"adjective","english":"cheap","forms":["vīle","vilī","vīlia","vīlibus","vīlis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"In Iōachae locum suffectus est Ioakim, quō rēgnante, Nabuchodonosor, B abylōniōrum rēx, Hierosolymam expugnāvit, cīvēs B abylōnem trānstulit, relicta vilī plēbēculā, cui prae:Iēcit Sedeciam postrēmum rēgem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vilitas","latin":"vīlitās, -ātis ( f.)","headword":"vīlitās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"cheapness, low price; cheapness","forms":["vīlitās"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Pompēiō omnium rērum ēgregiārum exempla sūmantur: quō diē ā vōbīs maritimō bellō praepositus est imperātor, tanta repentē {{vīlitās}} ex summā inopiā et cāritāte reī frūmentāriae cōnsecūta est ūnīus hominis spē ac nōmine, quantam vix in summā ūbertāte agrōrum dīturna pāx efficere potuisset.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"villa","latin":"vīlla, -ae","headword":"vīlla","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"country house, villa; country house, estate","forms":["vīllā","vīllae","vīllam","vīllās","vīllīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Via quae est inter Tūsculum et {{vīllam}} Iūliī nōn tam longa est quam via Latīna, sed servī quattuor quī Tūsculō ad vīllam ambulant fessī sunt, quia lectīcam et saccōs portant.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"villosus","latin":"villōsus, -a, -um","headword":"villōsus","letter":"v","pos":"adjective","posGroup":"adjective","english":"shaggy, hairy","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"villus","latin":"villus, -ī","headword":"villus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"shaggy hair","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vimen","latin":"vimen, viminis","headword":"vimen","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"twig, shoot","forms":["viminibus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}],"examples":[{"latin":"Huc teretes stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias {{viminibus}} ac virgultis integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vincere","latin":"(vincō) vincere, vīcisse, victum","headword":"vincere","letter":"v","pos":"verb","posGroup":"verb","english":"defeat, overcome, win; to conquer, defeat; to conquer, defeat, vanquish","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vincio","latin":"vincio, vincire, vinxi, vinctus","headword":"vincio","letter":"v","pos":"verb","posGroup":"verb","english":"bind, fetter; restrain","forms":["vinciēbant","vincīre","vincīrētur","vincīrī","vīncta","vīnctam","vīnctō","vīnctōs","vīnctum","vīnctus","vīnxisset","vīnxit"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tabellārius vērō canem {{vīnctum}} nōn timet.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vincire","latin":"(vinciō) vincīre, vīnxisse, vīnctum","headword":"vincīre","letter":"v","pos":"verb","posGroup":"verb","english":"bind; to chain, tie up","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vincit","latin":"vincit","headword":"vincit","letter":"v","pos":"verb","posGroup":"verb","english":"conquers, defeats","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vinclum","latin":"vinclum, vincli","headword":"vinclum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"chain, bond, fetter; imprisonment (pl.)","forms":["vincla","vinclīs","vinclō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"{{Vincla}} trahit galeae; victum spoliāre parābat; arma relicta videt; corpus deus aequoris albam contulit in volucrem, cuius modo nōmen habēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vinco","latin":"vincō","headword":"vincō","letter":"v","pos":"verb","posGroup":"verb","english":"to conquer, defeat","forms":["vīcerat","vīcerit","vīcērunt","vīcī","vīcimus","vicisse","vīcissent","vīcissēs","vīcisset","vīcistī","vīcit","victa","victae","vīctam","vīctī","victis","victō","victos","vīctū","vīctum","victūrōs","vīctūrum","vincam","vincāmus","vincant","vincar","vincat","vincātis","vincātur","vincēbant","Vincēmus","vincendō","vincent","vincere","vinceret","vincēs","vincet","Vincētur","vincī","vincimus","vincis","vincit","vincite","vincitur","vincō","Vincor","vincunt","vincuntur"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac re cognita, Vercingetorix rursus in Bituriges exercitum reducit atque inde profectus Gorgobinam, Boiorum oppidum, quos ibi Helvetico proelio {{victos}} Caesar collocaverat Aeduisque attribuerat, oppugnare instituit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vinculum","latin":"vinculum, -ī","headword":"vinculum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"bond, chain; bond, strap, chain","forms":["vincula","vinculīs","vinculum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Trāditus Philistaeīs rūpit {{vincula}}, quibus constrīctus erat, et arrēptā maxillā asinī, hōc tēlō, quod cāsus dederat, mīlle hostium prōstrāvit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vindicare","latin":"(vindicō) vindicāre","headword":"vindicāre","letter":"v","pos":"","posGroup":"other","english":"claim, avenge","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vindico","latin":"vindico, vindicare, vindicavi, vindicatus","headword":"vindico","letter":"v","pos":"verb","posGroup":"verb","english":"claim, vindicate; punish, avenge","forms":["vindicāmus","vindicandae","vindicandam","vindicandum","vindicāre","vindicāret","vindicat","vindicāta","vindicātūrum","vindicent","vindicēs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Indictis inter se principes Galliae conciliis silvestribus ac remotis locis queruntur de Acconis morte; posse hunc casum ad ipsos recidere demonstrant; miserantur communem Galliae fortunam; omnibus pollicitationibus ac praemiis deposcunt qui belli initia faciant et sui capitis periculo Galliam in libertatem {{vindicent}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vindicta","latin":"vindicta, vindictae","headword":"vindicta","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"ceremonial act claiming as free one contending wrongly enslaved; vengeance","forms":["vindicta"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"615 Tē quoque servārī, modo quam {{vindicta}} redēmit,","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vinea","latin":"vīnea, -ae","headword":"vīnea","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"vineyard","forms":["vīneā","vīneae","vīneārum","vineas","vīneīs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Castris ad eam partem oppido positis Caesar, quae intermissa a flumine et a paludibus aditum, ut supra diximus, angustum habebat, aggerem apparare, {{vineas}} agere, turres duas constituere coepit; nam circumvallare loci natura prohibebat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vinosus","latin":"vinosus, vinosa, vinosum","headword":"vinosus","letter":"v","pos":"adjective","posGroup":"adjective","english":"drunk w/over fond of wine; tasting/smelling of wine; vinous; dreg-colored","forms":["vīnōsī"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"j30. sit quoque vīnōsī Téia Mūsa senis;","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vinum","latin":"vīnum, -ī","headword":"vīnum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"wine","forms":["vīna","vīnī","vīnīs","vīnō","vīnum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ego nōn aquam, sed {{vīnum}} bibere volō.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"viola","latin":"viola, violae","headword":"viola","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"violet; several spring flowers, pansy; violet color","forms":["violae","violās"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Ōlim Proserpina, Cereris fīliā virgō, cum aliīs puellīs in campīs Siciliae laeta errābat lūdēns et aut {{violās}} aut candida līlia carpēns, calathōs ac sinum eō cōnsiliō implēbat, ut cēterās amīcās flōrēs colligendō vinceret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"violare","latin":"(violō) violāre","headword":"violāre","letter":"v","pos":"","posGroup":"other","english":"violate","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"violenter","latin":"violenter","headword":"violenter","letter":"v","pos":"adverb","posGroup":"adverb","english":"violently, impetuously","forms":["violenter","violentius"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"lenter, comp {{violentius}}","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"violentia","latin":"violentia, violentiae","headword":"violentia","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"violence, aggressiveness","forms":["violentiam"],"sources":[{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Sciēbam saepe numerō parvā manū cum magnīs legiōnibus hostium contendisse, cognōveram parvīs cōpiīs bella gesta cum opulentīs rēgibus, ad hōc saepe fortūnae {{violentiam}} tolerāvisse, fācundiā Graecōs, glōria bellī Gallōs ante Rōmānōs fuisse.","book":"Catilina","bookSlug":"sallustius-cicero-catilina"}]},{"id":"violentus","latin":"violentus, -a, -um","headword":"violentus","letter":"v","pos":"adjective","posGroup":"adjective","english":"violent, impetuous; violent, fierce","forms":["violentās","violentum","violentus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Vīdit quīdam pendentem Absalōnem, nec ausus est illī manūs {{violentās}} īnferre, sed nūntiāvit Iōābō, quī eum increpāns: “Debuerās” inquit “iuvenem impium cōnfodere.” “Atquī” respondit ille “mē praesente, rēx praecēpit tibi, ut fīliō suō parcerēs.” “Ego vērō nōn parcam” ait Iōāb, et statim sūmpsit trēs lanceās, quās in pectus Absalōnis dēfīxit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"violo","latin":"violo, violare, violavi, violatus","headword":"violo","letter":"v","pos":"verb","posGroup":"verb","english":"violate, dishonor; outrage","forms":["violāre","violāta","violātae","violātī","violātum","violāvērunt","violō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Illum, quī ā sē Saūlem occīsum esse iactitābat, et rēgia īnsignia attulerat, perimī iussit, in poenam {{violātae}} māiestātis rēgiae.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vipera","latin":"vipera, viperae","headword":"vipera","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"viper, snake","forms":["vīpera"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"nec brevis ignārō {{vīpera}} laesa pede","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vir","latin":"vir, -ī","headword":"vir","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"man, husband; man","forms":["vir","virī","virīs","virō","virorum","virōs"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Indignantes milites Caesar, quod conspectum suum hostes perferre possent tantulo spatio interiecto, et signum proeli exposcentes edocet quanto detrimento et quot {{virorum}} fortium morte necesse sit constare victoriam; quos cum sic animo paratos videat ut nullum pro sua laude periculum recusent, summae se iniquitatis condemnari debere, nisi eorum vitam sua salute habeat cariorem.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"virens","latin":"virens, (gen.), virentis","headword":"virens","letter":"v","pos":"adjective","posGroup":"adjective","english":"green; (in reference to plants)","forms":["virentis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Columba rūrsum ēmissa attulit in ōre suō rāmum olīvae {{virentis}}, quō fīnis dīluviī significābātur.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vires","latin":"vīrēs, vīrium","headword":"vīrēs","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.pl.) strength; strength, forces","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"virga","latin":"virga, -ae","headword":"virga","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"rod; rod, cane","forms":["virgā","virgae","virgam","virgīs"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Nihil Ergō nōs bene dormīmus, nec rūrsus excitāmur antequam is recitāre dēsinit; tum clāmōre magistrī īrātī excitāmur, nec modo verbīs reprehendimur, sed etiam virgā verberāmur!”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"virgineus","latin":"virgineus, -a, -um","headword":"virgineus","letter":"v","pos":"adjective","posGroup":"adjective","english":"maidenly, of a virgin","forms":["virgineī","virgineō","virginēum","virgineus"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Tanta simplicitās eī adfuit, haec iactūra {{virginēum}} dolōrem mōvit.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"virginia","latin":"virginia, virginiae","headword":"virginia","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"husband of virgin bride; first husband of girl/virgin","forms":["Virginīā"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"Quamquam multī in viā ambulābant, nēmō ad iuvandum cucurrit: nam omnēs Claudium timēbant, cuius saevissimum servum bene nōverant: neque quisquam parātus erat ad moriendum prō Virginīā.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"virginitas","latin":"virginitās, -ātis ( f.)","headword":"virginitās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"virginity; virginity, maidenhood","forms":["virginitās","virginitāte"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"\"Nec dea sum,\" dīxit, \"nec sacrī tūris honōre\nhūmānum dignāre caput; neu nescius errēs,\nlūx aeterna mihi cārītūraque fīne dabātur,\nsī mea {{virginitās}} Phoebō patuisset amantī.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"virginius","latin":"virginius, virginia, virginium","headword":"virginius","letter":"v","pos":"adjective","posGroup":"adjective","english":"virgin; of/appropriate for/haunted by marriageable age girls; unworked (land)","forms":["Virginiam","Virginīō","Virgīnius"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}],"examples":[{"latin":"{{Virgīnius}} vir Rōmānus fuit, quī pulchram fīliam habēbat, nōmine Virginiam, quam valdē amābat.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"virgo","latin":"virgō, virginis","headword":"virgō","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) unmarried girl; maiden, virgin; maiden, young woman","forms":["virgine","virginem","virginēs","virginī","virginibus","virginis","virginum","virgō"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ecce statim Rebecca, virgō eximia pulchritūdine, prōdiit, gerēns urnam hūmēris; quae dēscendit ad puteum, et implēvit urnam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"virgultum","latin":"virgultum, virgulti","headword":"virgultum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"brushwood","forms":["virgulta","virgultis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Huc teretes stipites feminis crassitudine ab summo praeacuti et praeusti demittebantur ita ut non amplius digitis quattuor ex terra eminerent; simul confirmandi et stabiliendi causa singuli ab infimo solo pedes terra exculcabantur; reliqua pars scrobis ad occultandas insidias viminibus ac {{virgultis}} integebatur.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"viridis","latin":"viridis, -e","headword":"viridis","letter":"v","pos":"adjective","posGroup":"adjective","english":"green","forms":["viridem","viridēs","viridī","viridibus","viridis"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Et iam membra in {{viridem}} colōrem vertī atque capillī, quibus candida frōns operiēbātur, horrēre coepērunt: Cyparissus tunc arbor factus est alta et rigida, cuius pars summa caelum stēllīs ōrnātum spectāre vidēbātur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"virilis","latin":"virīlis, -e","headword":"virīlis","letter":"v","pos":"adjective","posGroup":"adjective","english":"male, manly","forms":["virīle","virīlem","virīlī","virīlis"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"lēgitimum fīnem flamma {{virīlis}} habet.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"viritim","latin":"virītim","headword":"virītim","letter":"v","pos":"adverb","posGroup":"adverb","english":"man by man","forms":["viritim"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Frumentum omne ad se referri iubet; capitis poenam eis qui non paruerint constituit; pecus, cuius magna erat copia ab Mandubiis compulsa, {{viritim}} distribuit; frumentum parce et paulatim metiri instituit; copias omnes quas pro oppido collocaverat in oppidum recipit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"virtus","latin":"virtūs, virtūtis","headword":"virtūs","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) virtue; courage, virtue; courage, manliness; courage, excellence","forms":["virtus","virtute","virtutem","virtūtēs","virtuti","virtūtibus","virtutis","virtūtum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"His rebus in Italiam Caesari nuntiatis, cum iam ille urbanas res {{virtute}} Cn.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"virum","latin":"virum, viri","headword":"virum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"virus","forms":["virum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Fabia {{virum}} suum exspectat.","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"virus","latin":"virus, viri","headword":"virus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"venom (sg.), poisonous secretion of snakes/creatures/plants; acrid element","forms":["vīrus"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"{{vīrus}} -ī7 (acc 7 nàm) - venénum ex","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vis","latin":"vīs","headword":"vīs","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) force, power; force, strength; touch","forms":["ui","uis","vē","vem","vēs","vi","vim","vires","vīribus","virium","vīs","vum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Hi iam ante edocti quae interrogati pronuntiarent, milites se esse legionarios dicunt; fame atque inopia adductos clam ex castris exisse, si quid frumenti aut pecoris in agris reperire possent; simili omnem exercitum inopia premi, nec iam {{vires}} sufficere cuiusquam nec ferre operis laborem posse; itaque statuisse imperatorem, si nihil in oppugnatione oppidi profecissent, triduo exercitum deducere.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"visa","latin":"visa, visae","headword":"visa","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"visa","forms":["visa"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Haec cogitanti accidere {{visa}} est facultas bene rei gerendae.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"viscera","latin":"viscera, viscerum","headword":"viscera","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"(n. pl.) internal organs; entrails, inner organs","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"viscum","latin":"viscum, visci","headword":"viscum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"mistletoe; bird-lime (made from mistletoe berries)","forms":["Viscum"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Incipit ille: “Sī bene mē nōvī, nōn {{Viscum}} plūris amīcum, nōn Varium faciēs: nam quis mē scrībere plūrēs aut citius possit versūs? quis membra movēre mollius?","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"viscus","latin":"viscus, visceris","headword":"viscus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"soft fleshy body parts (usu. pl.), internal organs; entrails, flesh; offspring","forms":["vīscera","vīsceribus","vīscerum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"At illum subitus {{vīscerum}} dolor corripuit ā Deō immissus; cumque nihilōminus cursum accelerāret, ē currlī graviter dēcidit, et cāsus gravis aegrum iam corpus valdē afflīxit: unde factum ē st, ut membra corrupta scatērent vermibus, et foetōrem lātē ēmitterent, exercituī et aegrō ipsī intolerābilem.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"visere","latin":"(vīsō) vīsere","headword":"vīsere","letter":"v","pos":"","posGroup":"other","english":"go to see, visit","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[]},{"id":"visitatio","latin":"visitatio, visitationis","headword":"visitatio","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"|visit/visitation; (to sick/prisoners); visit of inspection/supervision","forms":["vīsitātiōnis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}],"examples":[{"latin":"Et ad terram prostement tē et fīliōs tuōs, quī sunt in tē, et nōn relinquent in tē lapidem super lapidem: quia nōn cognovisfi tempus {{vīsitātiōnis}} dominī tuī.\"Ingressus cīvitātem docēbat in templō.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"visito","latin":"visito, visitare, visitavi, visitatus","headword":"visito","letter":"v","pos":"verb","posGroup":"verb","english":"visit, call upon; see frequently/habitually","forms":["vīsitāre","Vīsitēmus"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Vīsitēmus}} eum.” [Gāius:] “Quid enim habet?” [Iūlius:] “Aegrōtat.” [Gāius:] “Ā quandō?” [Iūlius:] “Intrā paucōs diēs incidit.” [Gāius:] “Ubi manet?” [Iūlius:] “Nōn longē.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"viso","latin":"vīsō, -ere, vīsī, vīsum","headword":"vīsō","letter":"v","pos":"verb","posGroup":"verb","english":"to visit, go to see","forms":["vīsam","vīsenda","vīsendī","vīsēns","vīsere","viseret","visi","visis","vīsit","vīsite","vīsō","vīsundī"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Cum acerrime comminus pugnaretur, hostes loco et numero, nostri virtute confiderent, subito sunt Aedui {{visi}} ab latere.nostris aperto, quos Caesar ab dextra parte alio ascensu manus distinendae causa miserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"visum","latin":"vīsum, -ī","headword":"vīsum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"sight","forms":["visum"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Praestare {{visum}} est tamen omnes difficultates perpeti quam tanta contumelia accepta omnium suorum voluntates alienare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"visus","latin":"vīsus, -ūs","headword":"vīsus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"sight, vision","forms":["visus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Parte iam obsidum tradita, cum reliqua administrarentur, centurionibus et paucis militibus intromissis qui arma iumentaque conquirerent, equitatus hostium procul {{visus}} est, qui agmen Vercingetorigis antecesserat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vita","latin":"vīta, -ae","headword":"vīta","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"life","forms":["vītā","vitae","vitam"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Ille oppidum Biturigum positum in via Noviodunum oppugnare instituerat. (Quo ex oppido cum legati ad eum venissent oratum ut sibi ignosceret suaeque {{vitae}} consuleret, ut celeritate reliquas res conficeret, qua pleraque erat consecutus, arma conferri, equos produci, obsides dari iubet.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vitalis","latin":"vitalis, vitalis, vitale","headword":"vitalis","letter":"v","pos":"adjective","posGroup":"adjective","english":"vital; of life (and death); living/alive, able to survive; lively; life-giving","forms":["vītāle","vītālis"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ille dedit, quod nōn animā haec Cyclōpis in ōra\nvēnit, et ut iam nunc lūmen {{vītāle}} relinquam,\naut tumulō aut certē nōn illā condar in alvō.\"","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vitare","latin":"(vītō) vītāre, vītāvisse, vītātum","headword":"vītāre","letter":"v","pos":"verb","posGroup":"verb","english":"avoid; to avoid","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vitio","latin":"vitio, vitiare, vitiavi, vitiatus","headword":"vitio","letter":"v","pos":"verb","posGroup":"verb","english":"make faulty, spoil, damage; vitiate","forms":["vitiō"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"In vitiō decor est: quaedam","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vitis","latin":"vītis, vītis","headword":"vītis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) vine","forms":["vīte","vītem","vītēs","viti","vītibus","vītis"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Tum prior sīc exposuit Iōsēphō somnium suum: vīdī in quiēte {{vītem}} in quā erant trēs palmitēs; ea paulātim prōtulit gemmās; deinde flōrēs ērūpērunt, ac dēnique ūvae mātūrēscēbant.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vitium","latin":"vitium, -ī","headword":"vitium","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"defect, fault, vice","forms":["vitia","vitiīs","vitiōrum","vitium"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Postquam numerus hominum crēvit, omnia {{vitia}} invaluēre.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vito","latin":"vītō (1)","headword":"vītō","letter":"v","pos":"verb","posGroup":"verb","english":"to avoid, shun","forms":["vītābat","vītābit","vītāmus","vītanda","vītandae","vītandī","vītāre","vītārem","vītārent","vītāret","vītārī","vītārīs","vītat","vītāte","vītātum","vītāverant","vītēmus","vītet","vītētur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"“Rōmā discessī” aiēbat Coriolānus, “ut certam mortem {{vītārem}}, ad quam mē cīvēs meī mittere volēbant; nunc ipse, vōbīs iuvantibus, plūrimōs cīvēs meōs ad Īnferōs mittam, ubi umbrae mortuōrum versārī dīcuntur!","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vitreus","latin":"vitreus, vitrea, vitreum","headword":"vitreus","letter":"v","pos":"adjective","posGroup":"adjective","english":"of glass; resembling glass in its color (greenish), translucency, or glitter","forms":["vitrea","vitream"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Sîc Corintheā nāta sunt, ex omnibus in ūnum, “Ignôscëtis mihi quod dîxerô: ego mälô mihi {{vitrea}}, certē nôn olunt.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"vitta","latin":"vitta, -ae","headword":"vitta","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"fillet, band","forms":["vitta","vittae","vittum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Fībula vestīmentum retinēbat et {{vitta}} neglēctōs capillōs retinēbat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vitulus","latin":"vitulus, vituli","headword":"vitulus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"calf","forms":["vitulōs","vitulum","vitulus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Dēnique cum īrent omnēs ad {{vitulōs}} aureōs, quōs Ieroboāmus rēx Isrāēlis fēcerat, et populō adōrandōs prōposuerat, hīc sōlus fugiēbat societātem omnium; pergēbat autem ad templum Dominī, et ibi adōrābat Dominum.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vituperare","latin":"(vituperō) vituperāre","headword":"vituperāre","letter":"v","pos":"","posGroup":"other","english":"criticize, blame","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vitupero","latin":"vitupero, vituperare, vituperavi, vituperatus","headword":"vitupero","letter":"v","pos":"verb","posGroup":"verb","english":"find fault with, blame, reproach, disparage, scold, censure","forms":["vituperandum","vituperāre","vituperat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Quam virtūtem eius et Catō, vir prōmptioris ad {{vituperandum}} linguae, in senātū sīc prōsecūtus est ut dīceret 'reliquōs quī in Āfricā mīlitārent umbrās volitāre, Scīpiōnem vigēre.'","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vivax","latin":"vīvāx, -ācis","headword":"vīvāx","letter":"v","pos":"adjective","posGroup":"adjective","english":"long-lived, lively","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vivere","latin":"vīvere","headword":"vīvere","letter":"v","pos":"verb","posGroup":"verb","english":"to live","forms":[],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vivit","latin":"vīvit, vīvere","headword":"vīvit","letter":"v","pos":"verb","posGroup":"verb","english":"live, be alive; lives; lives, is alive","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vivo","latin":"vīvō, -ere, vīxī, victum","headword":"vīvō","letter":"v","pos":"verb","posGroup":"verb","english":"live, be alive","forms":["vīvam","vīvāmus","Vīvant","vīvās","vīvat","vīve","vīvēbant","vīvēbat","vīvēmus","vīvendī","vīvendō","vīvendum","vīventem","vīventēs","vīventia","vīvere","vīverem","vīverent","vīverēs","vīveret","vīvēs","vīvet","vīvī","vīvimus","vīvis","vīvit","vivo","vīvunt","vīxērunt","vīxī","vīxisse","vīxisset","vīxistī","vīxit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Cum prope omnis civitas eo convenisset, docereturque paucis clam convocatis alio loco, alio tempore atque oportuerit fratrem a fratre renuntiatum, cum leges duo ex una familia {{vivo}} utroque non solum magistratus creari vetarent sed etiam in senatu esse prohiberent, Cotum imperium deponere coegit; Convictolitavem, qui per sacerdotes more civitatis intermissis magistratibus esset creatus, potestatem obtinere iussit.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vivus","latin":"vīvus, -a, -um","headword":"vīvus","letter":"v","pos":"adjective","posGroup":"adjective","english":"living, alive; alive","forms":["vīva","vīvōrum","vīvōs","vivum","vivus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Sedulius, dux et princeps Lemovicum, occiditur; Vercassivellaunus Arvernus {{vivus}} in fuga comprehenditur; signa militaria LXXIIII ad Caesarem referuntur; pauci ex tanto numero se incolumes in castra recipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vix","latin":"vix","headword":"vix","letter":"v","pos":"adverb","posGroup":"adverb","english":"hardly; scarcely","forms":["vix"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Alii faces atque aridam materiem de muro in aggerem eminus iaciebant, picem reliquasque res quibus ignis excitari potest fundebant, ut quo primum curreretur aut cui rei ferretur auxilium {{vix}} ratio iniri posset.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vixdum","latin":"vixdum","headword":"vixdum","letter":"v","pos":"adverb","posGroup":"adverb","english":"scarcely yet, only just","forms":["vixdum"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Flāminius, cum prīdiē sōlis occāsū ad lacum pervēnisset, inexplōrātō posterō diē, {{vixdum}} satis certā lūce angustiīs superātīs, postquam in patentiorēm campum pandī agmen coepit, id tantum hostium quod ex adversō erat cōnspexit: ā tergō ac super caput dēcēpēre īnsidiae.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"vobis","latin":"vōbīs","headword":"vōbīs","letter":"v","pos":"pronoun","posGroup":"pronoun","english":"to you, for you (plural)","forms":[],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[]},{"id":"vocabulum","latin":"vocābulum, -ī","headword":"vocābulum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"word","forms":["vocābula","vocābulī","vocābulīs","vocābulō","vocābulōrum","vocābulum"],"sources":[{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Mārcus: “{i}Y {/i} nōn est littera Latīna, sed littera Graeca. {i}Syria {/i} est {{vocābulum}} Graecum.”","book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"}]},{"id":"vocalis","latin":"vōcālis, vōcālis","headword":"vōcālis","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) vowel","forms":["vōcālem","vōcālēs","vōcālī","vōcālis","vōcālium"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Litterae sunt aut {{vōcālēs}} aut cōnsonantēs: vōcālēs sunt Ā, Ē, I, Ō, V, Y; cēterae sunt cōnsonantēs. (Etiam I et V cōnsonantēs sunt in vocābulīs IAM, VEL, vōs, QVAM, cet.)","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"vocare","latin":"vocāre","headword":"vocāre","letter":"v","pos":"verb","posGroup":"verb","english":"to call","forms":[],"sources":[{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vocat","latin":"vocat","headword":"vocat","letter":"v","pos":"verb","posGroup":"verb","english":"call, invite; calls","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vocativus","latin":"vocātīvus, -ī (cāsus)","headword":"vocātīvus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"vocative","forms":["vocātīvus"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Magister: 'Cāsus nōminum quot sunt?' Discipulus: 'Sex.' Magister: 'Quī?' Discipulus: 'Nōminātīvus, genetīvus, dativus, accūsātīvus, {{vocātīvus}}, ablātīvus.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"vocatus","latin":"vocatus, vocatus","headword":"vocatus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"peremptory or urgent call","forms":["vocātus"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"{{Vocātus}} est autem et Iēsus et discipulī eius ad nūptiās.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"voco","latin":"vocō, -āre","headword":"vocō","letter":"v","pos":"verb","posGroup":"verb","english":"call, summon","forms":["vocā","vocābant","vocābantur","vocābat","vocābātur","vocāberis","vocābiminī","vocābimur","vocābuntur","vocāmus","vocandī","vocandō","vocandus","vocāns","vocant","vocantem","vocantī","vocantis","vocantur","vocāre","vocāret","vocārētur","vocārī","vocās","vocat","vocātam","vocāte","vocati","vocātis","vocātō","vocātōs","vocātum","vocātur","vocātūrum","Vocāvērunt","vocāvī","vocāvit","vocēmus","vocet","vocō","vocor"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Romani si casu intervenerint, fortunae, si alicuius indicio {{vocati}}, huic habendam gratiam, quod et paucitatem eorum ex loco superiore cognoscere et virtutem despicere potuerint, qui dimicare non ausi turpiter se in castra receperint.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"volans","latin":"volans, volantis","headword":"volans","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"mercury (element); flying/soaring things, birds (pl.)","forms":["volāns"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Quae, cum graviter vulnerātam sē esse sēnsisset, prīmum sē in aquās mersit; deinde ex flūctibus surrēxit, horrenda vīsū; tum Persēum iterum iterumque mordēre cōnābātur, at ille, hūc illūc vēlōcissimē {{volāns}}, eius impetus facile vītābat; dēnique maxima cum vī saevam bēstiam etiam atque etiam in complūribus corporis partibus ēnse vulnerāvit, dōnec illa, multō sanguine effūsō, ex vulneribus mortua est.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"volat","latin":"volat, volāre","headword":"volat","letter":"v","pos":"verb","posGroup":"verb","english":"fly; flies","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"volatilis","latin":"volatilis, volatilis, volatile","headword":"volatilis","letter":"v","pos":"adjective","posGroup":"adjective","english":"equipped to fly, flying fleeing, fleeting transient","forms":["volātile"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"saucius ingemuit tēlumque {{volātile}} sēnsit","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"volcanus","latin":"Volcanus, Volcani","headword":"Volcanus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Vulcan, god of fire; fire","forms":["Volcānum"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"MERCVRIVS: [ad Sōsiam appropinquantem] Quō ambulās tū, quī {{Volcānum}} in cornū conclūsum geris?","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"volgo","latin":"volgo, volgare, volgavi, volgatus","headword":"volgo","letter":"v","pos":"verb","posGroup":"verb","english":"spread around/among the multitude; publish, divulge, circulate; prostitute","forms":["volgāta"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"bellaque iam fāmā tōtum {{volgāta}} per orbem,","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"volgus","latin":"volgus, volgi","headword":"volgus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"common people/general public/multitude/common herd/rabble/crowd/mob; flock","forms":["volgus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cornibus arboreīs, sternit, tum {{volgus}}, et omnem","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"volitare","latin":"(volitō) volitāre","headword":"volitāre","letter":"v","pos":"","posGroup":"other","english":"fly about, flutter","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"volito","latin":"volito, volitare, volitavi, volitatus","headword":"volito","letter":"v","pos":"verb","posGroup":"verb","english":"fly about, hover over","forms":["volitāns","volitant","volitantēs","volitāre"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Quīntō diē, avēs quae {{volitant}} in aere, et piscēs quī natant in aquīs.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"volnus","latin":"volnus, volneris","headword":"volnus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"wound; mental/emotional hurt; injury to one's interests; wound of love","forms":["volnus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"cum Iūnō, aeternum servāns sub pectore {{volnus}},","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"volo","latin":"volō, velle","headword":"volō","letter":"v","pos":"verb","posGroup":"verb","english":"wish, want; fly","forms":["velim","velimus","velint","velīs","velit","vēlitis","velle","vellem","vellent","vellēs","vellet","volā","volābat","volābimus","volābis","volandī","volandō","volandum","volant","volantem","volantēs","volantia","volāre","volārem","volāret","volās","volat","volāvērunt","volāvit","volēbam","volēbant","volēbat","volent","volentem","volentēs","volēs","volet","volō","voluerat","voluerīs","voluerit","voluērunt","voluī","voluimus","voluisse","voluissem","voluissent","voluissēs","voluisset","voluistī","voluit","volumus","volunt","volvere","volvī","volvit"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"Ibi per certos exploratores in singula diei tempora quae ad Avaricum agerentur cognoscebat et quid fieri {{vellet}} imperabat.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"voltus","latin":"voltus, voltus","headword":"voltus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"face, expression; looks","forms":["voltū","voltum","voltus"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"spem voltū simulat, premit altum corde dolōrem.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"volucris","latin":"volucris, -is ( f.)","headword":"volucris","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"bird","forms":["volucrem","volucrēs","volucris","volucrum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"fōns erat illīmīs, nitidīs argenteus undīs, quem neque pāstōrēs neque pastae monte capellae contigerant aliudve pecus, quem nūlla {{volucris}}","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"voluntarius","latin":"voluntārius, -a, -um","headword":"voluntārius","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"voluntary","forms":["voluntārium","voluntārius"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Movet cum patris maestitia, tum Brūtus castīgātor lacrimārum atque inertium querēlārum auctorque 'quod virōs, quod Rōmānōs deceret!' arma capiendī 'adversus hostīlia ausōs!' Ferōcissimus quisque iuvenum cum armīs {{voluntārius}} adest; sequitur et cētera iuventūs.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"voluntas","latin":"voluntās, voluntātis","headword":"voluntās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) will, desire, good will; will","forms":["voluntās","voluntāte","voluntatem","voluntates","voluntātī","voluntātibus","voluntātis"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praestare visum est tamen omnes difficultates perpeti quam tanta contumelia accepta omnium suorum {{voluntates}} alienare.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"volup","latin":"volup","headword":"volup","letter":"v","pos":"adverb","posGroup":"adverb","english":"with pleasure; pleasurably; [~ esse => be pleasurable/a source of pleasure]","forms":["volup"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}],"examples":[{"latin":"Nam quia vōs tranquillōs videō, gaudeō et {{volup}} est mihi.","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"voluptas","latin":"voluptās, -ātis ( f.)","headword":"voluptās","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"pleasure, delight; pleasure","forms":["voluptās","voluptāte","voluptātem","voluptātēs","voluptātī","voluptātibus","voluptātis","voluptātum"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Posteā Salomōn voluptātī sē dēdit: nihil porrō tam inimīcum est virīs quam voluptās: itaque āmīsit sapientiam.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"volutare","latin":"(volūtō) volūtāre","headword":"volūtāre","letter":"v","pos":"","posGroup":"other","english":"roll, pass, whirl","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"voluto","latin":"voluto, volutare, volutavi, volutatus","headword":"voluto","letter":"v","pos":"verb","posGroup":"verb","english":"roll, wallow, turn over in one's mind, think or talk over","forms":["volūtāns","volūtant","volūtantur","volūtat"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"'Namque eōrum animī quī sē corporis voluptātibus dēdiderunt eārumque sē quasi ministrōs praebuērunt impulsūque libīdinum voluptātibus oboedientium deōrum et hominum iūra violāvērunt, corporibus ēlāpsī circum terram ipsam {{volūtantur}} nec hunc in locum, nisi multīs exagitātī saeculīs, revertuntur.' Ille discessit.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"volvere","latin":"(volvō) volvere, voluisse,","headword":"volvere","letter":"v","pos":"","posGroup":"other","english":"roll, turn (over), ponder volutum","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"volvo","latin":"volvo, volvere, volvi, volutus","headword":"volvo","letter":"v","pos":"verb","posGroup":"verb","english":"roll, cause to roll; travel in circle/circuit; bring around/about; revolve","forms":["volvantur","volvēbat","volvēns","volventēs","volventibus","volverentur","volvitur","volvunt","volvuntur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Tum aureum eius vellus ad Colchidis rēgem portāvit, quī: “Cūrābō” inquit, “ut hoc vellus aureum in rāmō altissimae quercus pōnātur, quae in silvā prope rēgiam est.” Dracō vērō saevus, quī in silvā vīvēbat, circum arboris truncum sē {{volvēns}} vellus per multōs annōs cūstōdīvit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vomer","latin":"vomer, vomeris","headword":"vomer","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"plowshare; stylus (for writing with (L+S); (metaphor for penis)","forms":["vōmer","vomere"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"interit assiduā {{vōmer}} aduncus humō.","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vomo","latin":"vomo, vomere, vomui, vomitus","headword":"vomo","letter":"v","pos":"verb","posGroup":"verb","english":"be sick, vomit; discharge, spew out; belch out","forms":["vomit","Vomuit"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Ingēns Aetna pectora et caput premit; resupīnus flammās cinerēsque ex ōre {{vomit}}, dum aliī montēs aliās partēs corporis premunt.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"vorago","latin":"vorāgō, vorāginis","headword":"vorāgō","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) abyss, whirlpool; whirlpool","forms":["vorāgine","vorāginem","vorāginēs","vorāginī","vorāgō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Praetereā multa genera perīculōrum nāvigantibus impendent: sī nāvīs saxīs occurrerit, frangētur; sī vorāginī, mergētur; sī tempestās orta erit, magnī flūctūs nāvem aquā implēbunt...","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vorare","latin":"(vorō) vorāre, vorāvisse, vorātum","headword":"vorāre","letter":"v","pos":"verb","posGroup":"verb","english":"devour; to devour","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vorax","latin":"vorax, voracis","headword":"vorax","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"ravenous; insatiable; devouring","forms":["vorāx"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}],"examples":[{"latin":"Nunc Scylla, mōnstrum maris sex capitibus nautam carpit; ecce Charybdis — cūr tam {{vorāx}}? — nāvēs, undās, avēs, vada, mōnstra dēvorat revomitque.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"voro","latin":"voro, vorare, voravi, voratus","headword":"voro","letter":"v","pos":"verb","posGroup":"verb","english":"swallow, devour","forms":["vorābantur","vorābat","vorandōs","vorāret","vorārētur","vorat","vorētur"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Postquam vērō cōram deīs fuit, Iuppiter hanc sevērissimam gravissimamque poenam in eum statuit: ut in monte Caucasō catēnā ferreā vincīrētur; praetereā ut aquila cotīdiē eius iecur interdiū {{vorāret}}, quod nocte iterum nāscerētur, nē supplicium umquam fīnem habēret.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vortex","latin":"vortex, vorticis","headword":"vortex","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"whirlpool, eddy, vortex; crown of the head; peak, top, summit; the pole","forms":["vortex"],"sources":[{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"torquet agēns circum, et rapidus vorat aequore {{vortex}}.","book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}]},{"id":"vos","latin":"vōs","headword":"vōs","letter":"v","pos":"pronoun","posGroup":"pronoun","english":"you, yourselves; you (pl.)","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vosmet","latin":"vōsmet","headword":"vōsmet","letter":"v","pos":"","posGroup":"other","english":"you, yourselves","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"voto","latin":"voto, votare, votui, votitus","headword":"voto","letter":"v","pos":"verb","posGroup":"verb","english":"forbid, prohibit; reject, veto; be an obstacle to; prevent","forms":["vōtō"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}],"examples":[{"latin":"Templa flōribus corōnantur; populus Minervam cum Iove dīsque aliīs honorat, quōrum templa sanguine, vōtō, mūneribus datīs tūribusque decorat.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]},{"id":"votum","latin":"vōtum, -ī","headword":"vōtum","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"prayer, offering, vow","forms":["vōta","vōtī","vōtīs","vōtum"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Ō utinam ā nostrō sēcēdere corpore possem! {{vōtum}} in amante novum: vellem, quod amāmus, abesset!”","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"voveo","latin":"voveo, vovere, vovi, votus","headword":"voveo","letter":"v","pos":"verb","posGroup":"verb","english":"vow, dedicate, consecrate","forms":["voveō","vōverat","vōvī","vōvit"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"ut quae apud legiōnēs vōta vōvī 's domum","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"vovere","latin":"(voveō) vovēre, vōvisse, vōtum","headword":"vovēre","letter":"v","pos":"","posGroup":"other","english":"promise, vow","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vox","latin":"vōx, vōcis","headword":"vōx","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"(f.) voice","forms":["vōce","vōcem","vōcēs","vōcibus","vōcis","vox"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Summa difficultate rei frumentariae adfecto exercitu tenuitate Boiorum, indiligentia Aeduorum, incendiis aedificiorum, usque eo ut complures dies frumento milites caruerint et pecore ex longinquioribus vicis adacto extremam famem sustentarent, nulla tamen {{vox}} est ab eis audita populi Romani maiestate et superioribus victoriis indigna.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vulcanus","latin":"Vulcānus","headword":"Vulcānus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"Vulcan, god of smiths","forms":["Vulcāne","Vulcānī","Vulcānō","Vulcānum","Vulcānus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"{{Vulcānum}} igitur fīlium arcessīvit, eumque iussit mulierem ex aquā et terrā cōnficere, quae formā pulcherrima esse vidērētur.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vulgaris","latin":"vulgāris, -e","headword":"vulgāris","letter":"v","pos":"","posGroup":"other","english":"common, everyday","forms":[],"sources":[{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[]},{"id":"vulgo","latin":"vulgō","headword":"vulgō","letter":"v","pos":"verb","posGroup":"verb","english":"commonly","forms":["vulgāre","vulgārēs","vulgō"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"sed tū sī sapiēs, sī tē bene iungere anumque hanc audīre volēs (quae tē plūs omnibus illīs, plūs, quam crēdis, amō): {{vulgārēs}} reice taedās","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vulgus","latin":"vulgus, -ī","headword":"vulgus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"the (common) people; the crowd, common people","forms":["vulgi","vulgus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Datur petentibus venia, dissuadente primo Vercingetorige, post concedente et precibus ipsorum et misericordia {{vulgi}}.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vulnerare","latin":"(vulnerō) vulnerāre, -āvisse, -ātum","headword":"vulnerāre","letter":"v","pos":"verb","posGroup":"verb","english":"wound; to wound","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[]},{"id":"vulnero","latin":"vulnerō","headword":"vulnerō","letter":"v","pos":"verb","posGroup":"verb","english":"to wound","forms":["vulnerās","vulnerātam","vulnerati","vulnerātīs","vulnerato","vulneratos","vulneratum","vulnerātus","vulnerāvit","vulneret","vulnerō"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"Multitudine sagittarum atque omnis generis telorum multos {{vulneratos}}; ad haec sustinenda magno usui fuisse tormenta.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vulnus","latin":"vulnus, vulneris","headword":"vulnus","letter":"v","pos":"noun (n.)","posGroup":"noun","english":"(n.) wound","forms":["vulnera","vulnere","vulneribus","vulneris","vulnerum","vulnus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Petronius, eiusdem legionis centurio, cum portas excidere conatus esset, a multitudine oppressus ac sibi desperans, multis iam {{vulneribus}} acceptis, manipularibus suis, qui illum secuti erant, 'Quoniam, inquit, me una vobiscum servare non possum, vestrae quidem certe vitae prospiciam, quos cupiditate gloriae adductus in periculum deduxi.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"vulpes","latin":"vulpes, vulpis","headword":"vulpes","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"fox","forms":["vulpem","vulpēs","VVLPE","VVLPES"],"sources":[{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Samsōn adultus Philistaeōs multīs affēcit clādibus: cēpit trecentās {{vulpēs}}, quārum caudīs accēnsās lampadēs alligāvit, et in hostium agrōs immīsit.","book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"}]},{"id":"vult","latin":"vult, volunt","headword":"vult","letter":"v","pos":"verb","posGroup":"verb","english":"want, be willing; wants, wishes","forms":[],"sources":[{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}],"examples":[]},{"id":"vultur","latin":"vultur, -is (m.)","headword":"vultur","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"vulture","forms":["vultur","vulturēs"],"sources":[{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"que {{vultur}}: tuum exhibeat : et nocte","book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"}]},{"id":"vultus","latin":"vultus, vultūs","headword":"vultus","letter":"v","pos":"noun (m.)","posGroup":"noun","english":"(m.) face, facial expression; face, expression; expression of the face, countenance, face","forms":["vultibus","vultū","vultuī","vultum","vultus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"},{"book":"Lingua Latina: Exercitia Latina I","bookSlug":"exercitia-latina"}],"examples":[{"latin":"Neque tam foedus sum: nūper mē in aquā vīdī, et mihi {{vultus}} meus valdē placuit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"vulva","latin":"vulva, vulvae","headword":"vulva","letter":"v","pos":"noun (f.)","posGroup":"noun","english":"womb/uterus/matrix; (esp. sow's); female sexual organ; (seed) covering (L+S)","forms":["vulvā"],"sources":[{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}],"examples":[{"latin":"Voluerīs: dē vulvā faciet piscem, dē lärdô palumbum, dē pēmā turturem, dē côlëpiô gallînam.","book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"}]},{"id":"xerxes","latin":"Xerxes, Xerxis","headword":"Xerxes","letter":"x","pos":"noun (m.)","posGroup":"noun","english":"Xerxes; (son of Darius, King of Persia 485-465 BC)","forms":["Xerxēs"],"sources":[{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Post deinde paucīs annīs {{Xerxēs}} rēx ab Athēniēnsibus et plērāque Graeciā, Themistocle duce, nāvālī proeliō quod ad Salamīna factum est victus fugātusque est.","book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}]},{"id":"zeno","latin":"Zeno, Zenonis","headword":"Zeno","letter":"z","pos":"noun (m.)","posGroup":"noun","english":"Zeno (Greek philosopher); L:Zeno (Emperor 474-491)","forms":["Zēnō","Zēnōnī"],"sources":[{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Sermones Romani","bookSlug":"sermones-romani"}],"examples":[{"latin":"Mārcus: 'Ego ipse nōn scrībō, sed Zēnōnī dictō.","book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"}]},{"id":"zephyrus","latin":"zephȳrus, -ī","headword":"zephȳrus","letter":"z","pos":"noun (m.)","posGroup":"noun","english":"west wind","forms":["Zephyrī","Zephyrōs","zephyrus"],"sources":[{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"},{"book":"A Companion to Familia Romana","bookSlug":"companion"}],"examples":[{"latin":"{{Zephyrus}} enim, quī iam diū, occultātus inter nūbēs, eōs lūdentēs spectābat, cum ipse quoque puerī amōre accēnsus esset, et Apollinī hāc dē causā invidēret, īrātus in discum vehementī flātū spīrāvit; quod cum fēcisset, discus, dē suō cursū flectēns, Hyacinthī caput graviter percussit.","book":"Fabulae Syrae","bookSlug":"fabulae-syrae"}]},{"id":"zona","latin":"zōna, -ae","headword":"zōna","letter":"z","pos":"noun (f.)","posGroup":"noun","english":"belt, zone","forms":["zōnās"],"sources":[{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"A Companion to Roma Aeterna","bookSlug":"companion-roma-aeterna"}],"examples":[{"latin":"Hī {{zōnās}}, illī rēs pretiōsās colligunt subsidium vītae.","book":"Sermones Romani","bookSlug":"sermones-romani"}]},{"id":"zzz","latin":"zzz","headword":"zzz","letter":"z","pos":"pronoun","posGroup":"pronoun","english":"him/her/it/ones-self; him/her/it; them (selves) (pl.); each other, one another","forms":["se","sese","sibi","ulterior","ulteriōra","ulteriōre","ulteriōrem","ulterioribus","ultimā","ultimae","ultimam","ultimas","ultimis","Ultimō","ultimōs","ultimus"],"sources":[{"book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"},{"book":"Lingua Latina: Colloquia Personarum","bookSlug":"colloquia-personarum"},{"book":"Epitome Historiae Sacrae","bookSlug":"epitome-historiae-sacrae"},{"book":"Fabulae Syrae","bookSlug":"fabulae-syrae"},{"book":"Lingua Latina: Pars I — Familia Romana","bookSlug":"familia-romana"},{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Petronius: Cena Trimalchionis","bookSlug":"petronius-cena-trimalchionis"},{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"},{"book":"Sermones Romani","bookSlug":"sermones-romani"},{"book":"Vergil: Aeneis Libros I et IV","bookSlug":"vergil-aeneis-i-et-iv"}],"examples":[{"latin":"Hac impulsi occasione qui iam ante {{se}} populi Romani imperio subiectos dolerent liberius atque audacius de bello consilia inire incipiunt.","book":"Caesar: De Bello Gallico VII","bookSlug":"caesar-de-bello-gallico-vii"}]},{"id":"zzzet","latin":"zzzet, zzzere, collibuit, collibitus est","headword":"zzzet","letter":"z","pos":"verb","posGroup":"verb","english":"it pleases/is very agreeable; (IMPERS PERFDEF perfect form has present sense)","forms":["collibitum","collibuisset"],"sources":[{"book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"},{"book":"Catilina","bookSlug":"sallustius-cicero-catilina"}],"examples":[{"latin":"SOSIA: Utcumque animō {{collibitum}} est meō!","book":"Plautus: Amphitryo Comoedia","bookSlug":"plautus-amphitryo"}]},{"id":"zzzus","latin":"zzzus, zzza -um, deterior -or -us, deterrimus -a -um","headword":"zzzus","letter":"z","pos":"adjective","posGroup":"adjective","english":"low/bad/inferior; poor/mean; unfavorable; weak; degenerate/wicked","forms":["dēterior","dēteriōra","dēterrimum"],"sources":[{"book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"},{"book":"Ovidii Nasonis: Ars Amatoria","bookSlug":"ovidii-ars-amatoria"},{"book":"Lingua Latina: Pars II — Roma Aeterna","bookSlug":"roma-aeterna"}],"examples":[{"latin":"Nam mē gravat invītam nova vīs, aliudque cupīdō, mēns aliud suādet: videō meliōra probōque, {{dēteriōra}} sequor.","book":"Latin via Ovid: A First Course","bookSlug":"latin-via-ovid"}]}]

